		[GetQuestName(3686)] = { -- "Three Tender Souls"			-- Rosque
				["Talk to Dendras Indalor"] =
					{appendText=". Given the murder, Denras might be wandering the paths on the northern edge of town."},
				["Talk to Gethis Omobar"] =
					{appendText=". Vicecanon Hrondar in the Fighters Guild may know where to find them."},
				["Talk to Tiiril Alor"] =
					{appendText=". Vicecanon Hrondar in the Fighters Guild may know where to find them."},
				["Examine Arilen Maralvel"] =
					{appendText="."},
				["Examine Eroni Omobar"] =
					{appendText="."},
				["Examine Naldyn Indalor"] =
					{appendText="."},
				["Talk to Smith Halva"] =
					{appendText=" in the mortuary on the southern edge of town."},
				["Meet Gethis Omobar at His Home"] =
					{appendText="."},
				["Investigate Gethis Omobar's Home"] =
					{appendText=" on the east side of town."},
				["Talk to Vicecanon Hrondar"] =
					{appendText=" inside the Ayleid ruin housing the guilds."},
				["Talk to Vicecanon Heita-Meen"] =
					{appendText=" inside the Ayleid ruin housing the guilds."},
			},
		[GetQuestName(3687)] = { -- "Getting to the Truth"			-- Rosque
			["Talk to Listens-to-Water"] =
				{appendText=". Vicecanon Heita-Meen said to look for the mud huts, and not to address him by name in case he assumes a debt collector is after him."},
			["Find Listens-to-Water's Reports"] =
				{appendText=" inside the mud hut in western Stormhold."},
			["Enter Silyanorn Ruins"] =
				{appendText="."},
			["Investigate Silyanorn Ruins"] =
				{appendText=", the Ayleid ruins with an entrance on the western side of Stormhold."},
			["Rescue Vicecanon Hrondar"] =
				{appendText=" inside Silyanorn Ruins, the entrance to which lies on the western side of Stormhold."},
			["Free the Prisoners"] =
				{appendText=" inside Silyanorn Ruins, the entrance to which lies on the western side of Stormhold."},
			["Find Vicecanon Hrondar"] =
				{appendText=". He said he wanted to warn the other vicecanons, so he's likely to have gone back outside the ruins in Stormhold."},
			["Talk to Vicecanon Hrondar"] =
				{appendText=". He said he wanted to warn the other vicecanons, so he's likely to have gone back outside the ruins in Stormhold."},
		},
		[GetQuestName(3690)] = { -- "Scouring the Mire"				-- Rosque
			["Meet Vicecanon Hrondar in Ten-Maur-Wolk"] =
				{appendText=". To reach it, head to the Stormhold stables, and then follow the road south, keeping the big river always on the left."},
		},
		[GetQuestName(4587)] = { -- "Trail of the Skin-Stealer"		-- Rosque
			["Find Vicecanon Servyna and Vicecanon Heita-Meen"] =
				{appendText=". Vicecanon Hrondar, north of the ruin, may be able to suggest a location where the other vicecanons may have holed themselves up."},
			["Talk to Vicecanon Heita-Meen"] =
				{appendText=" in the cave near the center of Ten-Maur-Wolk."},
			["Find Vicecanon Hrondar's Regiment"] =
				{appendText=", or any traces of where they went, near the cave in the middle of the ruin."},
			["Examine the Soldier's Body"] =
				{appendText=" near the cave in the middle of the ruin."},
			["Find the Rest of the Regiment"] =
				{appendText=". If one of Vicecanon Hrondar's soldiers was inside the bounds of the ruin, there may be more."},
			["Talk to the Surviving Soldier"] =
				{appendText=" at the cages on the western edge of Ten-Maur-Wolk."},
			["Rescue Ukatsei from the Ritual"] =
				{appendText=" on the northern side of the ruin. Two ominous torches burn in view of the cages."},
			["Talk to Ukatsei 1"] =
				{appendText=" in the cave in the center of the ruin.", stepTextKey="I rescued Ukatsei from the fate that befell his companions. He fled for the cave containing the vicecanons.\n\nI should follow him and see if he knows of Vicecanon Hrondar's whereabouts."},
			["Follow the Trail with Ukatsei"] =
				{appendText=". He mentioned seeing the Vicecanon head off with his guard somewhere east of the ruin."},
			["Examine Vicecanon Hrondar's Body"] =
				{appendText=" in the daedric pavilion northeast of the center of Ten-Maur-Wolk."},
			["Talk to Ukatsei 2"] =
				{appendText=" in the daedric pavilion northeast of the center of Ten-Maur-Wolk.", stepTextKey="Ukatsei seems to be in shock upon seeing the body of his commander. I should speak with him about Vicecanon Hrondar's mysterious death."},
			["Talk to Ukatsei 3"] =
				{appendText=" in the daedric pavilion northeast of the center of Ten-Maur-Wolk.", stepTextKey="Ukatsei confirmed Vicecanon Hrondar died hours ago. That means a skin-stealer is leading the regiment!"},
		},
		[GetQuestName(4590)] = { -- "The Skin-Stealer's Lair"		-- Rosque
			["Find the Temple Complex Entrance"] =
				{appendText=". Ukatsei mentioned that Hrondar's imposter ordered his forces to stay away from the hill in Ten-Maur-Wolk; there may be something there worth investigating."},
			["Explore the Temple Complex"] =
				{appendText=" from the portal atop the large hill in Ten-Maur-Wolk."},
			["Talk to Lyranth 1"] =
				{appendText=" inside the portal atop the large hill in Ten-Maur-Wolk.", stepTextKey="I found a captive Dremora in the Dominion's underground lair. She wants me to speak with her. Perhaps she knows the skin-stealer's plans."},
			["Find the Inner Altar"] =
				{appendText=" inside the portal atop the large hill in Ten-Maur-Wolk."},
			["Disrupt Lyranth's Bindings"] =
				{appendText=" deeper in the complex from the portal atop the large hill in Ten-Maur-Wolk."},
			["Talk to Lyranth 2"] =
				{appendText=" deeper in the complex from the portal atop the large hill in Ten-Maur-Wolk.", stepTextKey="If I'm going to put an end to the skin-stealers' plans, I'll need to speak with Lyranth."},
			["Enter the Vault"] =
				{appendText=" deep in the complex from the portal atop the large hill in Ten-Maur-Wolk."},
			["Destroy the Hist Vats"] =
				{appendText=" in the Lair of the Skin Stealer, deep within the complex through the portal above Ten-Maur-Wolk."},
			["Kill Vicecanon Hrondar's Imposter"] =
				{appendText=" in the Lair of the Skin Stealer, deep within the complex through the portal above Ten-Maur-Wolk."},
			["Talk to Lyranth 3"] =
				{appendText=" in the Lair of the Skin Stealer, deep within the complex through the portal above Ten-Maur-Wolk.", stepTextKey="I defeated the skin-stealer responsible for Vicecanon Hrondar's death. I should speak to Lyranth before I leave."},
			["Talk to Vicecanon Servyna outside of Ten-Maur-Wolk"] =
				{appendText=". If the vicecanons escaped, they may have decided to regroup just south of the ruin's walls."},
			["Talk to Vicecanon Servyna"] =
				{appendText=". If the vicecanons escaped, they may have decided to regroup just south of the ruin's walls."},
			["Destroy the Animus Geodes Holding Bijot's Friends"] =
				{appendText="\nBijot said they were up on platforms inside the complex in the portal atop the large hill in Ten-Maur-Wolk."},
			["Talk to Bijot at the Inner Altar"] =
				{appendText=", deeper in the complex from the portal atop the large hill in Ten-Maur-Wolk."},
			["Talk to Bijot"] =
				{appendText=" in the Lair of the Skin Stealer, deep within the complex through the portal above Ten-Maur-Wolk."},
		},
		[GetQuestName(3815)] = { -- "Cracking the Egg"				-- Rosque
			["Meet Vicecanon Servyna in Hatching Pools"] =
				{appendText=", in the very center of Shadowfen. The dangerous swamps are famously difficult to navigate. The only way to reach Hatching Pools from the north is to go through an ogre-filled pass south of Mud Tree Village, or wind around the eastern roads of the entire region. The winding road south of the pools houses a small camp where argonian Keepers can welcome visitors."},
		},
		[GetQuestName(4606)] = { -- "Keepers of the Shell"			-- Rosque
			["Find Keeper Uxith-Ei"] =
				{appendText=" somewhere inside. Vicecanon Servyna said there was ceremonial garb in the chest in the camp just south of the main entrance that could offer a disguise, though she warned it wouldn't work on tigers."},
			["Light the Western Xanmeer"] =
				{appendText=" brazier, situated high on the west side of the pool's hist tree."},
			["Light the Eastern Xanmeer"] =
				{appendText=" brazier, situated high on the east side of the pool's hist tree."},
			["Find Assistant Telixith"] =
				{appendText=". Though the Hatching Pools are large, Dominion forces seem concentrated on the stone ruins, leaving the marsh in the center to the keepers."},
			["Talk to Keeper Uxith-Ei 1"] =
				{appendText=" on the stairs before the Hist inside the Hatching Pools.", stepTextKey="I lit the braziers and found Assistant Telixith. I should return to Keeper Uxith-Ei and share what I've learned of the Dominion's plans."},
			["Watch For Dominion Activity"] =
				{appendText=" on the stairs before the Hist inside the Hatching Pools."},
			["Talk to Keeper Uxith-Ei 2"] =
				{appendText=" on the stairs before the Hist inside the Hatching Pools.", stepTextKey="The hatching ritual went horribly wrong. Keeper Uxith-Ei's assistant Ahaht-Ei died during the ritual, and he looks to be in severe pain. I should find out what happened."},
			["Save the Eggs"] =
				{appendText=" surrounding the Hist inside the Hatching Pools."},
			["Talk to Assistant Telixith"] =
				{appendText=" on the stairs before the Hist inside the Hatching Pools."},
			["Escape the Hatching Pools"] =
				{appendText=". Assistant Telixith may wish to speak outside."},
			["Talk to Vicecanon Servyna"] =
				{appendText=" south of the Hatching Pools."},
		},
		[GetQuestName(4646)] = { -- "The Mnemic Egg"				-- Rosque
			["Travel to Loriasel"] =
				{appendText=". To reach it, head west from the Hatching Pools until the ancient Second Empire fortress of Arx Corinium. There, just south of it, is the ancient Ayleid ruin of Loriasel. Someone there may know where to find Heita-Meen, either on the northern approach, or the southern one, just above Xal Ithix."},
		},
		[GetQuestName(3909)] = { -- "The Dominion's Alchemist"		-- Rosque
			["Talk to Vicecanon Heita-Meen 1"] =
				{appendText=". The trail of corpses of both Dominion and lamias winding about the ruins should roughly mark her position.", stepTextKey="Vicecanon Heita-Meen's aide informed me she went ahead to scout the aftermath of a battle between Dominion soldiers and lamias. I should find her and tell her of Ruuvitar's plans for the Mnemic Egg."},
			["Search the Camp for Clues"] =
				{appendText=" around the northwestern edge of the ruins."},
			["Talk to Gerent Kepanuu"] =
				{appendText=" at the camp on the northwestern edge of the ruins."},
			["Enter the Ruins of Loriasel"] =
				{appendText="."},
			["Find Ruuvitar"] =
				{appendText=" inside the interior ruins of Loriasel, where the Dominion forces hid when routed by lamias."},
			["Talk to Kazdi"] =
				{appendText=" within the ruins of Loriasel."},
			["Find a Way into the Inner Bailey"] =
				{appendText=" within the ruins of Loriasel."},
			["Activate the Eastern Keystone"] =
				{appendText=" inside the ruins of Loriasel, through the legion of lamias."},
			["Activate the Western Keystone"] =
				{appendText=" inside the ruins of Loriasel, through the army of unquiet dead."},
			["Go to the Unsealed Door"] =
				{appendText=" within the ruins of Loriasel."},
			["Deal with Kazdi"] =
				{appendText=" within the ruins of Loriasel."},
			["Talk to Vicecanon Heita-Meen 2"] =
				{appendText=" within the ruins of Loriasel.", stepTextKey="I'm ready to proceed to the Inner Bailey and stop Ruuvitar. Before I go, Vicecanon Heita-Meen wishes to speak."},
		},
		[GetQuestName(3910)] = { -- "The Dream of the Hist"			-- Rosque
			["Kill Ruuvitar"] =
				{appendText=" inside Loriasel Inner Bailey, deep within the ruins of Loriasel."},
			["Find the Mnemic Egg"] =
				{appendText=" inside Loriasel Inner Bailey, deep within the ruins of Loriasel. If Ruuvitar was experimenting on it, it must be somewhere nearby."},
			["Help Vicecanon Heita-Meen Retrieve the Mnemic Egg"] =
				{appendText=" inside Loriasel Inner Bailey, deep within the ruins of Loriasel and high up on the Ayleid platform."},
			["Talk to Gerent Nuleem-Malem"] =
				{appendText=" inside Loriasel Inner Bailey, deep within the ruins of Loriasel and high up on the Ayleid platform."},
			["Investigate the Mnemic Egg"] =
				{appendText=" inside Loriasel Inner Bailey, deep within the ruins of Loriasel and high up on the Ayleid platform."},
			["Explore Deeper into the Dream"] =
				{appendText="."},
			["Talk to the Hist-Brothers"] =
				{appendText="."},
			["Return to Heita-Meen"] =
				{appendText="."},
			["Talk to the Voice of the Hist"] =
				{appendText=", somewhere within the dream. Given the Hist's alien nature,  it might not manifest in a recognizable form."},
			["Talk to Vicecanon Heita-Meen 1"] =
				{appendText=" inside The Ordinator's Revenge, the large seaworthy vessel in Alten Corimont.", stepTextKey="The Hist concentrated within the Mnemic Egg could not survive the tortures of Ruuvitar. The Egg is little more than a shell.\n\nI awoke in a strange room. I should ask Hist-Brother where we are."},
			["Talk to Vicecanon Heita-Meen 2"] =
				{appendText=" inside The Ordinator's Revenge, the large seaworthy vessel in Alten Corimont.", stepTextKey="The Hist concentrated within the Mnemic Egg survived the tortures of Ruuvitar. It suggested that in time it could be whole once more.\n\nI awoke in a strange room. I should ask Hist-Brother where we are."},
		},
		[GetQuestName(5013)] = { -- "Hushed Whispers"				-- Rosque
			["Talk to Vicecanon Hrondar"] =
				{appendText=". Given the moisture of Shadowfen, and that 'Hrondar' isn't traditionally an Argonian name, he may be preferring to coordinate his investigation from inside the dryness of one of the city's Ayleid ruins."},
		},
		[GetQuestName(5015)] = { -- "Eyes of the Enemy"				-- Rosque
			["Talk to an Official at Ten-Maur-Wolk"] =
				{appendText=". To reach it, head south out of the Hatching Pools, then follow the road east to the silhouette of an enormous grounded ship. From there, go north up the road towards Stormhold."},
		},
		[GetQuestName(5016)] = { -- "Children of the Hist"			-- Rosque
			["Talk to Keeper Uxith-Ei"] =
				{appendText=" in the Hatching Pools. To reach it, head east along the roads from Loriasel until reaching the largest landmass in Shadowfen. The pools are past a stone gate there, lying at the center of old argonian ruins that surround a Hist tree. There must be someone overseeing it."},
		},


