		[GetQuestName(3709)] = { -- "The Bargain's End"				-- ARKANOBOT 
			["Follow Shaman Chirah's Advice"] =
				{appendText=""},
			["Follow War Chief Helushk's Advice"] =
				{appendText="\n\nThe Shaman and the War Chief seem to be at odds regarding the whole ordeal. Perhaps it is time for you to take a stand. Meet them at the Chieftain’s hut in the center of the village and make your choice!"},
			["Enter the Odious Chapel"] =
				{appendText=" in the Western corner of the village."},
			["Enter the Vile Terminus"] =
				{appendText=" deep inside the Odious Chapel in the western corner of Village."},
			["Destroy the Soul Gem Array"] =
				{appendText=""},
			["Preserve the Soul Gem Array"] =
				{appendText="\n\nFate of the Kothringi of Stillrise Village must be decided deep inside the Daedric Chapel west of the Village."},
			["Return to Stillrise 1"] =
				{appendText=" Village.", stepTextKey="I destroyed the soul gem array, ending the villagers' bargain with Clavicus Vile. I should return to Stillrise Village and see what became of the villagers."},
			["Talk to Chieftain Suhlak"] =
				{appendText=" near the center of the village."},
			["Return to Stillrise 2"] =
				{appendText=" Village.", stepTextKey="I preserved the soul gem array, ending the villagers' bargain with Clavicus Vile. I should return to Stillrise Village and see what became of the villagers."},
		},
		[GetQuestName(3982)] = { -- "Bound to the Bog"				-- ARKANOBOT 
			["Talk to Gerent Saervild Steel-Wind at Bogmother"] =
				{appendText=" Crossroads,  northeast of Mud Tree Village."},
		},
		[GetQuestName(3712)] = { -- "Captive Souls"					-- ARKANOBOT 
			["Talk to Daeril"] =
				{appendText=". Sia said the necromancers took Daeril to the camp northeast of Stillrise Village."},
			["Destroy Nerys' Animus Geode"] =
				{appendText=""},
			["Destroy Liam's Animus Geode"] =
				{appendText=""},
			["Destroy Wilhem's Animus Geode"] =
				{appendText=""},
			["Destroy Gerren's Animus Geode"] =
				{appendText="\n\nAccording to Daeril, they appear to look like large Soul Gems."},
			["Find Daeril Near Stillrise Village"] =
				{appendText=""},
		},
		[GetQuestName(4259)] = { -- "Foreign Vintage"				-- ARKANOBOT 
			["Make the Aldmeri Spies Drink"] =
				{appendText="\n\nThey have infiltrated the celebration in Sanguin's Demesne."},
			["Talk to Seducer Trilvath"] =
				{appendText=" near the entrance inside Sanguine's Demesne."},
		},
		[GetQuestName(3824)] = { -- "A Last Reminder"				-- ARKANOBOT 
			["Take the Runestone to Eydvi Iron-Kettle in Mud Tree Village"] =
				{appendText=".\n\nThere are rumors of miners trapped in the Mud Tree Mines... Is she one of them? The mine foreman is bound to know more about their whereabouts."},
		},
		[GetQuestName(4237)] = { -- "Life of the Party"				-- ARKANOBOT 
			["Find a Barkeep for the Bar"] =
				{appendText=""},
			["Secure an Actor for the Stage"] =
				{appendText=""},
			["Get a Musician for the Ballroom"] =
				{appendText=""},
			["Get a Second Musician for the Ballroom"] =
				{appendText="\n\nSearch for the remains of the dead entertainers in Sanguine's Demesne."},
			["Talk to Sings-with-Drink"] =
				{appendText=" in Sanguine's Demesne."},
		},
		[GetQuestName(3840)] = { -- "Saving the Relics"				-- ARKANOBOT 
			["Talk to Gerent Saervild Steel-Wind"] =
				{appendText=" in his camp near the Crossroads to Bogmother, southeast of Stormhold."},
			["Collect Xaloc Relic"] =
				{appendText=""},
			["Collect Shol Relic"] =
				{appendText=""},
			["Collect Tsith Relic"] =
				{appendText=""},
			["Collect Umoj Relic"] =
				{appendText="\n\nSaervild claims the relics scattered around the ruins of Bogmother, extending to the northwestern borders of the daedric ruins of Ten-Maur-Wolk."},
			["Talk to Njorlund Steel-Wind 1"] =
				{appendText=" at Bogmother ruins.", stepTextKey="When I finished collecting the relics, Njorlund Steel-Wind showed up. I should tell him to return to the camp."},
			["Go to the Tree-Minders' Camp"] =
				{appendText=" by the Road, north of Bogmother ruins."},
			["Talk to Njorlund Steel-Wind 2"] =
				{appendText=" at the tree-minders camp by the road north of Bogmother ruins.", stepTextKey="The tree-minders aren't at their camp. I should tell Njorlund Steel-Wind about this."},
			["Find the Tree-Minders"] =
				{appendText=".\n\nNjorlund says that the Dreugh could have buried the tree-minders in the mud pile in the northern region of Bogmother towards the river and the eastern region of Bogmother."},
			["Return to Tree-Minder Raleetal's Camp"] =
				{appendText=""},
			["Talk to Tree-Minder Raleetal 1"] =
				{appendText="", stepTextKey="I got back to the camp too late and found Njorlund Steel-Wind was dead, and the relics taken. I should see if there is anything Tree-Minder Raleetal can do to help me return them."},
			["Collect the Dominion Troops' Scent"] =
				{appendText=" by collecting something from the Dominion camp, south of Bogmother ruins."},
			["Talk to Tree-Minder Raleetal 2"] =
				{appendText=" near the reliquary in the vicinity of the central Bogmother ruins.", stepTextKey="I found a Dominion bedroll, still smelling like its owner. Tree-Minder Raleetal needs this to start her ritual at the reliquary within the ruins beside her camp."},
			["Place the Dominion Bedroll in the Reliquary"] =
				{appendText=" near the central Bogmother ruins."},
			["Witness the Ritual"] =
				{appendText=" performed by the Tree-Minder Raleetal at the central Bogmother ruins."},
			["Talk to Tree-Minder Raleetal 3"] =
				{appendText=" at the central Bogmother ruins.", stepTextKey="The dreugh seemed enthralled by the scent of the Dominion troops. I should talk to Tree-Minder Raleetal before I go in search of Gerent Saervild Steel-Wind."},
			["Kill Saervild"] =
				{appendText=""},
			["Take the Relics"] =
				{appendText="\n\nSaervild should be somewhere in Mudshallow Cave south of Camp Silken Snare, south of Bogmother ruins."},
			["Talk to Tree-Minder Raleetal 4"] =
				{appendText=" outside the Mudshallow cave, south of Camp Silken Snare.", stepTextKey="The Dominion spy using Saervild's form is dead. Now that I've collected the relics, I should take them back to Tree-Minder Raleetal."},
		},
		[GetQuestName(3822)] = { -- "Schism"						-- ARKANOBOT 
			["Talk to Surii Dreth"] =
				{appendText=". She should be somewhere in Mud Tree Village."},
			["Enter the Mud Tree Mine"] =
				{appendText=" southwest of Mud Tree Village."},
			["Save Eydvi Iron-Kettle"] =
				{appendText=""},
			["Save Lenam Sero"] =
				{appendText=""},
			["Save Miharil"] =
				{appendText="\n\nThe Miners are trapped in the Mines of Mud Tree Village."},
			["Recover Goblin Totem from the Gnaw-Root War Chief"] =
				{appendText=" in the Goblin camp above the Mines of Mud Tree Village."},
			["Find the Source of a Cry for Help"] =
				{appendText=". A faint cry was heard from the cliffs north of the Goblin camp, located south of Mud Tree Village."},
			["Goblins Subdued"] =
				{appendText="\n\nThe Goblins in the Goblin Camp above the Mines of the Mud Tree Village need to be subdued."},
			["Take the Gnaw-Root Goblin Totem to Miharil's Hut Inside the Mine"] =
				{appendText=" near the Mud Tree Village"},
			["Give the Gnaw-Root Goblin Totem to Thragnar the Breaker"] =
				{appendText=""},
			["Give the Gnaw-Root Goblin Totem to Miharil"] =
				{appendText=""},
			["Talk to Miharil's brothers in Mud Tree Village"] =
				{appendText=""},
			["Talk to Surii Dreth in Mud Tree Village"] =
				{appendText=""},
		},
		[GetQuestName(4554)] = { -- "Shadowfen Smorgasbord"			-- ARKANOBOT 
			["Talk to Veenaza 1"] =
				{appendText=", Angwe says he's hunting game east, just outside the city limits of Stormhold.", stepTextKey="Angwe doesn't even know where to hunt alits, kagoutis, giant wasps or mudcrabs. She wants me to talk to the very person she made the bet with, Veenaza, and get him to tell me what I need to know. She's begged me not to tell him why."},
			["Collect Wasp Eggs"] =
				{appendText=" in the northern region of Shadowfen."},
			["Collect an Alit's Heart"] =
				{appendText=" from the Alit's roaming the southern region of Shadowfen."},
			["Collect Kagouti Ribs"] =
				{appendText=" in the northwestern region of Shadowfen."},
			["Collect Mudcrab Claw Meat"] =
				{appendText=" from the mudcrabs roaming the river banks in the northeastern region of Shadowfen."},
			["Talk to Angwe"] =
				{appendText=""},
			["Talk to Veenaza 2"] =
				{appendText="\n\nThey await you at Hissmir in the southwestern region of Shadowfen.", stepTextKey="I've collected all the cook's ingredients and I need to take them to Hissmir. But I also need to decide: Should I take them to her so she can win her bet, or should I give them to Veenaza and reveal his drunkard friend's plan to cheat him?"},
			["Give the meat to Angwe"] =
				{appendText=" at Hissmir"},
			["Give ingredients to Veenaza"] =
				{appendText=" at Hissmir"},
		},
		[GetQuestName(3685)] = { -- "The Thin Ones"					-- ARKANOBOT 
			["Talk to Chieftain Suhlak 1"] =
				{appendText="", stepTextKey="To find out why, I should speak to their leader, Chieftain Suhlak. Her hut is near the center of the village."},
			["Confront Gorag"] =
				{appendText=""},
			["Confront Felra"] =
				{appendText=""},
			["Confront Draguar"] =
				{appendText="\n\nSuhlak said that some of the huts have storage cellars."},
			["Talk to Chieftain Suhlak 2"] =
				{appendText=" in her hut in the center of the village.", stepTextKey="None of the Worm Cult lieutenants would surrender. I should inform Chieftain Suhlak."},
			["Talk to Chieftain Suhlak 3"] =
				{appendText=" in her hut in the center of the village.", stepTextKey="I learned a shocking secret. The people of Stillrise Village are living skeletons! Chieftain Suhlak asked me not to be alarmed. I should speak with her further."},
			["Talk to Shaman Chirah"] =
				{appendText=" in his hut near the center of the village."},
			["Talk to War Chief Helushk"] =
				{appendText=" near the entrance of the daedric temple near the western corner of the village."},
			["Enter the Odious Chapel"] =
				{appendText=" in the cave towards the western corner of the village."},
			["Offer the Vacant Daedric Soul Totem to Clavicus Vile"] =
				{appendText=" in the Chapel in the caves west of the village."},
			["Talk to Acolyte Morag in Stillrise Village"] =
				{appendText=". Morag should be near a hut in the northern corner of the village."},
			["Retrieve the Soul Gem Array"] =
				{appendText=" from the Worm Cult camp northeast of the village. Acolyte Morag said that she stuck one of her skeletal toes to the Soul Gem Array."},
			["Talk to Chieftain Suhlak 4"] =
				{appendText=" in her hut in the center of the village.", stepTextKey="I recovered the soul gem array. I should return it to Chieftain Suhlak."},
		},
		[GetQuestName(4390)] = { -- "Unbridled Wealth"				-- ARKANOBOT 
			["Search Guar Pack Animals for Teegya's Ruby"] =
				{appendText="\n\nThe Pack Guars should be in the nearby Swamps."},
			["Capture Wades-In-Muck"] =
				{appendText=" in the Swamps West of the Shadow Stone."},
			["Search Crocodile Bellies for Teegya's Ruby"] =
				{appendText=". Perhaps one of the crocodiles in the swamp near the Shadow stone has swallowed it?"},
			["Talk to Teegya"] =
				{appendText=" near the cross roads, southeast of the Shadow stone."},
		},
		[GetQuestName(3688)] = { -- "Unwelcome Guests"				-- ARKANOBOT 
			["Convince Mercenaries to Leave"] =
				{appendText=""},
			["Talk to Doubts-the-Moon"] =
				{appendText=" in his stall called 'Doubt Not These Prices' at Riverside Markets in Stormhold."},
			["Talk to Hjotild"] =
				{appendText=" near 'Doubt Not These Prices' stall at Riverside Markets in Stormhold."},
		},
		[GetQuestName(3731)] = { -- "Broken Apart"					-- ARKANOBOT 
			["Return to Valrendil's Camp"] =
				{appendText=" behind the xanmeer in the southern edge of Deep Graves."},
			["Convince Valrendil of the Wispmother's Treachery"] =
				{appendText=". He is tricked into protecting the wispmother and stands guard at the entrance of the cave next to his camp behind the southern xanmeer in Deep Graves."},
			["Seal the Wispmother's Remains in the Blessed Vessel 1"] =
				{appendText=". She hides in Valrendil's cave next to his camp behind the southern xanmeer in Deep Graves.", stepTextKey="I convinced Valrendil of the wispmother's illusions. Hopefully, he'll stay out of my way."},
			["Talk to Valrendil Outside the Cave"] =
				{appendText=" near his camp behind the southern xanmeer in Deep Graves."},
			["Talk to Valrendil"] =
				{appendText=""},
			["Seal the Wispmother's Remains in the Blessed Vessel 2"] =
				{appendText=". She hides in Valrendil's cave next to his camp behind the southern xanmeer in Deep Graves.", stepTextKey="Valrendil did not believe my argument against the wispmother, but I convinced him to let me into her lair. Now I must slay the wispmother and seal her remains."},
			["Talk to Xijai-Teel 1"] =
				{appendText=" at Valrendil's camp behind the southern xanmeer in Deep Graves.", stepTextKey="The wispmother has been sealed away, though Valrendil fell to her charms. I should speak to Xijai-Teel, so she'll know the wispmother is no longer plaguing the Deep Graves."},
			["Talk to Xijai-Teel 2"] =
				{appendText=" at Valrendil's camp behind the southern xanmeer in Deep Graves.", stepTextKey="The wispmother has been sealed away, though Valrendil fell to her charms. I should let Xijai-Teel know the wispmother is no longer plaguing Deep Graves."},
		},
		[GetQuestName(3905)] = { -- "Clarity"						-- ARKANOBOT 
			["Talk to Tree-Minder Fal-Xoc 1"] =
				{appendText=" at her hut in Precolating Mire.", stepTextKey="I should go speak to Tree-Minder Fal-Xoc about Ja-Reet's strange silence."},
			["Collect Lanceata Pholiota"] =
				{appendText=", a giant mushroom from the Mushroom Cave east of Precolating Mire."},
			["Talk to Tree-Minder Fal-Xoc 2"] =
				{appendText=" at her hut in Precolating Mire.", stepTextKey="I should return to Tree-Minder Fal-Xoc for the blessing that will enable me to locate Ja-Reet's spirit."},
			["Talk to Memory of Ja-Reet's Father"] =
				{appendText=""},
			["Talk to Memory of Overseer"] =
				{appendText=""},
			["Talk to Memory of Feyne Vildan"] =
				{appendText="\n\nThe memories are scattered around the Village."},
			["Talk to Spirit of the Hist 1"] =
				{appendText="", stepTextKey="I should go to the Hist tree at the center of the village to meet spirit of the Hist."},
			["Talk to Spirit of the Hist 2"] =
				{appendText=" near the Hist Tree at the Center of the Village.", stepTextKey="Spirit of the Hist can send me directly to Carethil, the Dominion soldier responsible for corrupting Ja-Reet's memories."},
			["Kill Carethil"] =
				{appendText=" deep within the Hist tree"},
			["Destroy Binding Crystals"] =
				{appendText=""},
			["Talk to Tree-Minder Fal-Xoc 3"] =
				{appendText=" at her hut in Precolating Mire.", stepTextKey="Tree-Minder Fal-Xoc kept watch over me while I searched for and freed Ja-Reet's spirit."},
			["Talk to Ja-Reet 1"] =
				{appendText="", stepTextKey="Ja-Reet can stay in Percolating Mire to train as a healer, but he's free to leave with Feyne Vildan. I should help him make a choice."},
			["Talk to Ja-Reet 2"] =
				{appendText=" at Precolating Mire.", stepTextKey="Ja-Reet decided to remain in Percolating Mire to train as a healer."},
			["Talk to Ja-Reet 3"] =
				{appendText=" at Precolating Mire.", stepTextKey="Ja-Reet decided to return to Narsis, Feyne's hometown."},
		},
		[GetQuestName(3828)] = { -- "Cold-Blooded Revenge"			-- Chaos
			["Kill Maldur"] =
				{appendText=" after burning his banner at the Dominion Camp west of Merciful Reduction, in front of the largest tent."},
			["Get Maldur's Heart"] =
				{appendText=""},
			["Talk to Prowls-in-Stealth at the Swamp's Edge"] =
				{appendText=" by the water, south of the Camp Merciful Reduction."},
			["Talk to Prowls-in-Stealth"] =
				{appendText=" by the water, south of the Camp Merciful Reduction."},
		}, 
		[GetQuestName(3888)] = { -- "Buried in the Past"			-- Chaos
			["Talk to Barvyn"] =
				{appendText=" near the log bridge, following the road to the east of Looks-Under-Rocks' camp and west of Sunscale Strand."},
			["Recover Green Puzzle Stone"] =
				{appendText=" by killing pirates around Sunscale Strand."},
			["Use the Green Puzzle Stone"] =
				{appendText=" near Sunscale Strand."},
			["Retrieve Blue Puzzle Stone"] =
				{appendText=" after following the Hist Guide near Sunscale Strand."},
			["Use the Blue Puzzle Stone"] =
				{appendText=" near Sunscale Strand."},
			["Find the Red Puzzle Stone"] =
				{appendText=" after following the Hist Guide around Sunscale Strand."},
			["Use the Red Puzzle Stone"] =
				{appendText=" near Sunscale Strand."},
			["Climb the Xanmeer"] =
				{appendText=" in Sunscale Strand."},
			["Talk to Looks-Under-Rocks 1"] =
				{appendText=" atop the tallest building in Sunscale Strand, west of the pirate boat.", stepTextKey="I need to see if the Argonian on top of the xanmeer knows about the puzzle stones and how they relate to the xanmeer."},
			["Talk to Looks-Under-Rocks 2"] =
				{appendText=" atop the tallest building in Sunscale Strand, west of the pirate boat.", stepTextKey="The puzzle stones are now something called a Hist key. Keys unlock things, but what lies behind the lock? I need to talk to Looks to find out more."},
		},
		[GetQuestName(3889)] = { -- "The Fangs of Sithis"			-- ARKANOBOT 
			["Talk to Barvyn"] =
				{appendText=" at the western spire of the Xanmeer in Sunscale Strand."},
			["Talk to Looks-Under-Rocks 1"] =
				{appendText=" at the western spire of the Xanmeer in Sunscale Strand.", stepTextKey="Barvyn didn't heed his partner's warning. He unsealed the xanmeer and went in. I hope Looks-Under-Rocks can tell me more about what's hidden in these ruins."},
			["Use Ancient Door to Enter Ruins"] =
				{appendText=" at the western spire of the Xanmeer in Sunscale Strand."},
			["Stop Barvyn"] =
				{appendText=" from claiming the 'Fangs of Sithis' from the ancient ruins inside the Xanmeer in Sunscale Strand."},
			["Exit Sunscale Ruins"] =
				{appendText=""},
			["Talk to Looks-Under-Rocks 2"] =
				{appendText=" at the entrance of the cave southeast of the Xanmeer in Sunscale Strand.", stepTextKey="Barvyn succumbed to the enchantment of the Fangs of Sithis, but he repented as he was dying. More importantly, I've recovered only one Fang. The other is gone. I must tell Looks-Under-Rocks."},
		},
		[GetQuestName(3900)] = { -- "Into the Mire"					-- Chaos
			["Rescue Residents"] =
				{appendText="\n\nSearch around Percolating Mire."},
			["Rescue Ja-Reet"] =
				{appendText=". Search for his hut to the north of Percolating Mire, around the main tree at the center of town."},
			["Talk to Feyne"] =
				{appendText=" at the eastern side of town, close to a wooden bridge around the central tree."},
		},
		[GetQuestName(3675)] = { -- "Last One Standing"				-- Mouch30
			["Question the Pirates on the Docks"] =
				{appendText="\nThese sneaky Khajiit will surely give up information after watching you murder the Dominion agents wandering about."},
			["Go to the Warehouse"] =
				{appendText=", a small, dank structure at the boat's stern."},
			["Kill Tsanji and Take the Dominion's Treasure"] =
				{appendText=". Lady, as she is known to her cohorts, waits in the abandoned mine just under your feet."},
			["Talk to S'jash 1"] =
				{appendText=", a young cat that follows your every move.", stepTextKey="In the underground hideout, a Khajiit approached me, right after killing his leader. I should speak to him and find out what he wants."},
			["Talk to S'jash Outside Tsanji's Hideout"] =
				{appendText=", tucked away in a cave on the eastern shore across from Alten Corimont."},
			["Talk to S'jash 2"] =
				{appendText=" outside Tsanji's hideout, tucked away in a cave on the eastern shore across from Alten Corimont.", stepTextKey="The treasure One-Eye expected to be in the Khajiit's hideout was not there. A pirate named S'jash said he and his gang would be willing to help me track it down, if I spared them. I should see what they have to offer me."},
		},
		[GetQuestName(4388)] = { -- "A Life of Privilege"			-- Mouch30
			["Find Suriel's Belongings"] =
				{appendText="\nFauna of all shapes and sizes have made the trees their home, leaving convenient hiding spots in the rotting trunks. The southeastern swamp is full of hollow trees."},
			["Talk to Suriel 1"] =
				{appendText=", who sprinted off to crouch in the muck of the pools east of the nearby Dominion camp.", stepTextKey="I've collected Suriel's things from the dubious hiding spots in the swamp. She ran off almost immediately. I should bring her the trinkets and see what's got her so excited."},
			["Follow Suriel"] =
				{appendText=" to the dinghy resting just below the northern shore, in the southeastern swamp."},
			["Decide Suriel's Fate"] =
				{appendText=". The two women are waiting by the rowboat moored in the southeastern swamp. The Dark Elf looks out of place in the muddy pools, decked in jewelry and satin."},
			["Talk to Aldyna 1"] =
				{appendText=" by the moored boat in the southeastern swamps.", stepTextKey="I think I've \"convinced\" Aldyna to forget about Suriel and leave with her stolen items."},
			["Talk to Suriel 2"] =
				{appendText=" by the moored boat in the southeastern swamps. It seems Dark Elf slavers only respond to threats.", stepTextKey="I think I've \"convinced\" Aldyna to forget about her former slave. I should speak with Suriel before she leaves."},
			["Talk to Suriel 3"] =
				{appendText=" by the moored boat in the southeastern swamps.", stepTextKey="I gave Suriel to buy her freedom without stealing from her now-former master. Aldyna probably won't be happy about this turn of events."},
			["Talk to Aldyna 2"] =
				{appendText=" by the moored boat in the southeastern swamps. The hefty price you paid was worth it to free the Breton.", stepTextKey="I bought Suriel's freedom. I should speak with Aldyna and make sure she doesn't plan to go back on the deal."},
			["Talk to Aldyna 3"] =
				{appendText=" by the moored boat in the southeastern swamps.", stepTextKey="I've agreed to return Aldyna's stolen goods to her - both the trinkets and her slave, Suriel."},
			["Talk to Aldyna 4"] =
				{appendText=" by the moored boat in the southeastern swamps. The squabbles between Dunmer and their property isn't important enough to matter to you.", stepTextKey="I've agreed to return Aldyna's stolen property to her. I should speak with her before she departs."},
		},
		[GetQuestName(3724)] = { -- "Lost to the Mire"				-- Mouch30
			["Find Luteema in the Percolating Mire"] =
				{appendText=". The village lies to the south of Alten Corimont, surrounded by the river on all sides. Luteema followed another to the Mire, leaving behind the one that loved him from the start."},
		},
		[GetQuestName(3914)] = { -- "Missing Son"					-- ARKANOBOT 
			["Find Wideem-Voh"] =
				{appendText=" in the Dominion camp north of Precolating Mire."},
			["Find Wideem-Voh's Necklace"] =
				{appendText=". Search the Camp Crystal Abattoir for the necklace."},
			["Talk to Tah-Tehat"] =
				{appendText=" at Precolating Mire."},
		},
		[GetQuestName(3676)] = { -- "A Pirate Parley"				-- Mouch30
			["Find the Dominion Treasure Ship"] =
				{appendText=", a gorgeous galleon docked on the river east of Alten Corimont."},
			["Find the Pirate Treasure on the Dominion Ship"] =
				{appendText=", which is rife with Dominion troops. The paychest should be safely stored to the back of the ship's hold."},
			["Talk to One-Eye 1"] =
				{appendText=", who patiently waits for her 'hard-earned' payment on the southern docks. S'jash mentioned a boat waiting for you on the shore near the old hideout.", stepTextKey="One-Eye is waiting for me to return to Alten Corimont. Supposedly, she has some important information I must hear. S'jash said she would be waiting on the docks."},
			["Kill Sirinaire"] =
				{appendText=", and take back Alten Corimont from the clutches of the Dominion."},
			["Talk to One-Eye 2"] =
				{appendText=" on her ship's main deck.", stepTextKey="Sirinaire is dead. With luck, this means the end of supply running through Alten Corimont. That deals a severe blow to the Dominion's designs in Shadowfen. I should let One-Eye know the Dominion won't bother her town any longer."},
			["Talk to Vicecanon Servyna"] =
				{appendText=" on the upper deck of the Blasted Breton."},
		},
		[GetQuestName(3890)] = { -- "Pull the Last Fang"			-- ARKANOBOT 
			["Board the Pirate Ship"] =
				{appendText=" at Sunscale Strand"},
			["Find the Key to the Hold"] =
				{appendText=". It should be somewhere in the top deck of the Pirate Ship at Sunscale Strand."},
			["Recover the Fang of Sithis"] =
				{appendText=" from the pirate captain below decks of the ship at Sunscale Strand"},
			["Find Looks-Under-Rocks"] =
				{appendText=" in Sunscale Strand."},
			["Talk to Sharava 1"] =
				{appendText=" at Looks-Under-Rocks' camp northeast of Sunscale Strand.", stepTextKey="These Shadowscales appeared out of nowhere. I should talk to their leader, Sharava and find out what they want."},
			["Give the Fangs to Sharava"] =
				{appendText=""},
			["Give the Fangs to Looks-Under-Rocks"] =
				{appendText="\n\nThey await your decision at Looks-Under-Rocks' camp northeast of Sunscale Strand."},
			["Talk to Sharava 2"] =
				{appendText=" at Looks-Under-Rocks' camp northeast of Sunscale Strand.", stepTextKey="I gave Sharava the Fangs of Sithis. I should talk to her again before she leaves."},
			["Talk to Aspect of Sithis"] =
				{appendText=" at Looks-Under-Rocks' camp northeast of Sunscale Strand."},
			["Talk to Looks-Under-Rocks"] =
				{appendText=" at his camp northeast of Sunscale Strand."},
		},
		[GetQuestName(3729)] = { -- "A Stranger Uninvited"			-- ARKANOBOT 
			["Find the High Elf's Camp"] =
				{appendText=" behind the xanmeer at Deep Graves."},
			["Search the Altmer's Camp"] =
				{appendText=" behind the xanmeer at Deep Graves."},
			["Talk to Valrendil"] =
				{appendText=" at his camp behind the xanmeer in Deep Graves."},
			["Talk to Valrendil's Wife"] =
				{appendText=" in the cave next to his camp behind the xanmeer in Deep Graves."},
			["Talk to Xijai-Teel atop the Xanmeer"] =
				{appendText=" in Deep Graves."},
			["Retrieve the Fragmented Urn"] =
				{appendText=" from the ruined xanmeer in the northeastern edge of Deep Graves."},
			["Retrieve the Fragmented Stopper"] =
				{appendText=" from the northwestern xanmeer in Deep Graves."},
			["Complete the Ritual with Xijai-Teel"] =
				{appendText=". She awaits your return with the artifacts near the road in the northern edge of Deep Graves."},
			["Talk to Xijai-Teel"] =
				{appendText=" near the cart filled with recent dead at the road on the northern edge of Deep Graves."},
		},
		[GetQuestName(4556)] = { -- "Strength of the Father"		-- Mouch30
			["Read Gordag's Journal"] =
				{appendText=" in the final chamber of the ruins."},
			["Create an Antidote"] =
				{appendText=" from the native plants around the ruins. A Seriweed Elixir will cure Mozgosh and ease her pain, but Gordag is against using such gentle methods. The Xthari Elixir, although poisonous, promises a grueling recovery to anyone who can muster through the burning sensations."},
			["Use Xthari Elixir on Mozgosh"] =
				{appendText=", who waits for the cure in the ruins of Hissmir, a xanmeer located above the southern river of Shadowfen."},
			["Switch to Seriweed Elixir"] =
				{appendText=" for a gentler, painless cure."},
			["Use Seriweed Elixir on Mozgosh"] =
				{appendText=", who waits for the cure in the ruins of Hissmir, a xanmeer located above the southern river of Shadowfen."},
			["Switch to Xthari Elixir"] =
				{appendText=" for a more intense, painful cure."},
			["Talk to Mozgosh 1"] =
				{appendText=" near her tent on the northeast platform of Hissmir. Her skin is pale and damp, but she's standing on her own feet.", stepTextKey="While the Xthari Elixir woke Mozgosh from her coma, she appears severely weakened. I should find out how she feels."},
			["Talk to Mozgosh 2"] =
				{appendText=" near her tent on the northeast platform of Hissmir. Her skin has gained a youthful glow, and she stands with renewed vigor.", stepTextKey="The Seriweed Elixir appears to have cured Mozgosh entirely. I should find out how she feels."},
		},
		[GetQuestName(4553)] = { -- "Threefold Folly"				-- ARKANOBOT 
			["Talk to Akishan"] =
				{appendText=" near the crossroads to the Hatching Pools, west of Alten Corimont."},
			["Solve Akishan's Riddles"] =
				{appendText=""},
			["Trick Akishan into Answering a Riddle"] =
				{appendText="\n\nAkishan waits for you to answer her riddles near the Crossroads, south of the Hatching Pools."},
			["Return Erranenen's Lute"] =
				{appendText=". He waits for you near the ruins at the western corner of Alten Corimont."},
			["Talk to Erranenen"] =
				{appendText=" near the ruins at the western corner of Alten Corimont."},
		},
		[GetQuestName(3827)] = { -- "The Tree-Minder's Fate"		-- ARKANOBOT 
			["Recover Broken Haft"] =
				{appendText=""},
			["Recover Ancient Book"] =
				{appendText=""},
			["Recover Lost Key"] =
				{appendText="\n\nSearch the Forsaken Hamlet for clues."},
			["Talk to Tree-Minder Deyapa 1"] =
				{appendText="'s ghost inside one of the huts in Forsaken Hamlet.", stepTextKey="The tree-minder's ghost appeared, hovering over the last object I recovered. I need to talk to this spirit."},
			["Talk to Tree-Minder Deyapa in Her Hut"] =
				{appendText=" in Forsaken Hamlet."},
			["Subdue Spirits"] =
				{appendText="\n\nThe mad Argonian spirits run rampant in the Forgotten Hamlet."},
			["Go to the Hist Tree"] =
				{appendText=" in the center of Forgotten Hamlet."},
			["Talk to Tree-Minder Deyapa at the Hist Tree"] =
				{appendText=" in the center of Forgotten Hamlet."},
			["Talk to Tree-Minder Deyapa 2"] =
				{appendText=" near the Hist tree in the center of the Forgotten Hamlet.", stepTextKey="Having returned the broken headpiece to the tree-minder, I need to wait and see if she is able to restore the Hist tree … or at least put her fellow spirits to rest. I'll talk to her when she's finished."},
			["Burn Hist Sap Containers"] =
				{appendText="\n\nThe tree-minder says that the Dominion has taken the Sap Containers to their camp north of the Forgotten Hamlet."},
			["Talk to Tree-Minder Deyapa 3"] =
				{appendText=" at Forgotten Hamlet.", stepTextKey="The Hist sap is free of the Dominion's refinement containers, so the Argonian spirits should be calm again, but the Dominion's soldiers know where I came from. I must return to the Hist tree and confer with Tree-Minder Deyapa."},
			["Tell Tree-Minder Deyapa to Begin the Ritual"] =
				{appendText=". She waits for you at Forsaken Hamlet."},
			["Defend the Spirits"] =
				{appendText=" performing the ritual at Forsaken Hamlet."},
			["Talk to Tree-Minder Deyapa 4"] =
				{appendText=" near the hist tree at the center of Forsaken Hamlet.", stepTextKey="The Dominion's forces have been routed. Tree-Minder Deyapa's ritual was a success. The Argonian spirits of the forsaken hamlet can now return to the restored Hist tree. They can be at peace."},
		},
		[GetQuestName(3674)] = { -- "Warm Welcome"					-- Mouch30
			["Talk to Senil Fenrila"] =
				{appendText=", imprisoned in the stocks located on the northern side of the docked ship. Stale alcohol and swamp water mingle together, producing a fetid stench that covers the town."},
			["Get an Audience with Alten Corimont's Leader"] =
				{appendText=". Strength recognizes strength among pirates, and there's no better way to earn respect than with a good ol' rumble."},
			["Talk to One-Eye 1"] =
				{appendText=", a grizzled Argonian captain. As her name suggests, one eye is a pale, milky white, blinded in a terrible scuffle.", stepTextKey="I won the right to speak to One-Eye, the leader of Alten Corimont. Her thugs said she would be in the captain's quarters of the beached ship, on the main deck."},
			["Get Information from One-Eye's Contact"] =
				{appendText=", a twitchy, speckled Argonian lurking near some supply crates."},
			["Eavesdrop on the Meeting in the Warehouse"] =
				{appendText=" to the south of the Blasted Breton."},
			["Talk to One-Eye 2"] =
				{appendText=", residing in her quarters on the ship's main deck.", stepTextKey="Tsanji has made a deal with the Thalmor, the military force of the Dominion in Shadowfen. One-Eye should hear about this immediately."},
			["Talk to One-Eye 3"] =
				{appendText=", residing in her quarters on the ship's main deck.", stepTextKey="It seems Tsanji made a deal with the Thalmor, the military force of the Dominion in Shadowfen. One-Eye should hear about this immediately."},
		},
		[GetQuestName(3730)] = { -- "Whispers of the Wisps"			-- ARKANOBOT 
			["Talk to Parash 1"] =
				{appendText=" at Deep Graves, in the swamps southwest of Alten Corimont", stepTextKey="I should seek out Parash and see what's going on."},
			["Rescue the Travelers"] =
				{appendText=""},
			["Talk to Parash 2"] =
				{appendText=" at Deep Graves.", stepTextKey="I should return to Parash and let him know the travelers should be safer now."},
			["Follow the Ghostly Figure"] =
				{appendText=" near Parash at Deep Graves."},
			["Talk to Xijai-Teel"] =
				{appendText=" at Deep Graves."},
		},
		[GetQuestName(4557)] = { -- "Will of the Broken"			-- Mouch30
			["Talk to the Dying Priest"] =
				{appendText=" sprawled on the platform, in the second chamber."},
			["Bring Daedric Urn to Vaudrie 1"] =
				{appendText=", a fellow priestess of Arkay, who is stationed in the eastern port city.", stepTextKey="Mallius Falto is at peace. The Blessing of Arkay will keep his spirit safe from Daedric corruption. He asked me to bring the urn to Vaudrie in Alten Corimont."},
			["Talk to Vaudrie"] =
				{appendText=", a fellow priestess of Arkay, stationed in the eastern port city."},
			["Bring Daedric Urn to Vaudrie 2"] =
				{appendText=", a fellow priestess of Arkay, stationed in the eastern port city.", stepTextKey="Mallius Falto blessed me before he died, to keep me safe from Daedra. He asked me to bring the urn to Vaudrie in Alten Corimont."},
		},
		[GetQuestName(3845)] = { -- "And Throw Away The Key"		-- ARKANOBOT 
			["Talk to a Guard"] =
				{appendText=" at White Rose Prison."},
			["Talk to General Raetus"] =
				{appendText=" at one of the broken buildings in the southern section of the White Rose Prison."},
			["Collect Medical Supplies"] =
				{appendText=""},
			["Take Medical Supplies to the Tower"] =
				{appendText=" near the overrun camp, northwest of White Rose Prison."},
		},
		[GetQuestName(3719)] = { -- "Captured Time"					-- ARKANOBOT 
			["Awaken Ayleid Pilasters"] =
				{appendText="\n\nSearch for the Ayleid Pilasters in the Temple of Sul, north of the village in Zuuk. According to the book, the Pilasters resemble a smaller variant of Welkynd Stones."},
			["Talk to Neeja-Meen"] =
				{appendText=" at Hissmir in the southwestern region of Shadowfen."},
		},
		[GetQuestName(4391)] = { -- "Catch the Lightning"			-- ARKANOBOT 
			["Talk to Drulis"] =
				{appendText=". According to Gathotar, Drulis should be along the riverbanks to the east of Chid-Moska Ruins and south of Hissmir. Gathotar says Drulis is not willing to partake in the experimentation of the amulet. Perhaps you will fare better at persuading him?"},
			["Collect Wamasu Lightning"] =
				{appendText="\n\nUse the amulet given by Gathotar on a Wamasu while it emits lightning. Wamasus are known to roam in the swamps near Venomous Fens Dolmen and Chid-Moska Ruins."},
			["Talk to Gathotar"] =
				{appendText=" about the results of the experimentation. He should be awaiting your return in an Argonian tower next to the vine bridge leading to Blackwood southeast of Chid-Moska Ruins."},
		},
		[GetQuestName(3795)] = { -- "Deep Disturbance"				-- ARKANOBOT 
			["Talk to Tree-Minder Nexith 1"] =
				{appendText=". He usually spends time communing with the Hist in his hut in the village of Xal Ithix.", stepTextKey="The hunter I met in Xal Ithix says if I want to know what's happening in the swamp, I need to talk to Tree-Minder Nexith in his hut."},
			["Place Ritual Potion at Northeast Stele"] =
				{appendText=""},
			["Place Ritual Potion at Southeast Stele"] =
				{appendText=""},
			["Place Ritual Potion at Southwest Stele"] =
				{appendText=""},
			["Place Ritual Potion at Northwest Stele"] =
				{appendText="\n\nThe Tree-Minder warns of daedric forces guarding the stele surrounding the ancient xanmeer south of Xal Ithix."},
			["Talk to Tree-Minder Nexith 2"] =
				{appendText=". He is preparing for the ritual of clear sight atop the xanmeer south of Xul Ithix.", stepTextKey="I should meet Tree-Minder Nexith atop its ancient stone temple. He should be able to begin his ritual now."},
			["Talk to Tree-Minder Nexith 3"] =
				{appendText=" atop the xanmeer south of Xal Ithix. His ritual did seem to go well almost up until the end. Perhaps the ancients revealed the real cause for the corruption in the bog?", stepTextKey="I should ask Tree-Minder Nexith whether his ritual revealed the source of Xal Ithix's problems."},
			["Go to Hist Tree"] =
				{appendText=""},
			["Unearth Daedric Relic at the Stele"] =
				{appendText=" by the waterfall, west of the Hist tree southwest of Xal Ithix."},
			["Talk to the Daedra"] =
				{appendText=" at the stele next to the waterfall west of the Hist tree southwest of Xal Ithix. The daedra does not seem to be pleased with what you have done..."},
			["Go to Ritual Site"] =
				{appendText=" by following the path through the caves near the stele by the waterfalls west of the hist tree in the southwestern region of Xal Ithix. Beware though! The aspect of the Daedric Prince Namira has threatened to overwhelm you by sending her minions if you attempt to foil her plans."},
			["Talk to Aspect of Namira at Ritual Site"] =
				{appendText=" west of Xal Ithix."},
			["Disrupt Ritual"] =
				{appendText=" at the ritual site atop the mountain southwest of Xal Ithix. According to the Tree-Minder, you can use the artifact you found at the stele to disrupt Namira's daedric minions"},
			["Talk to Tree-Minder Nexith 4"] =
				{appendText=" atop the mountain southwest of Xal Ithix.", stepTextKey="I stopped Namira's ritual of corruption. I can see Tree-Minder Nexith at the top of a nearby structure. I should go talk to him and see what's next for Xal Ithix."},
		},
		[GetQuestName(3679)] = { -- "Dreams From the Hist"			-- ARKANOBOT 
			["Drink Hist Sap"] =
				{appendText=" next to Bimee-Kas at the pit south of Hissmir."},
			["Witness the Lost Communion"] =
				{appendText=" by talking to the ancient Argonian spirit at the broken structure near the wooden bridge west from the pit south of Hissmir."},
			["Witness the Fruit and the Stone"] =
				{appendText=" by talking to the ancient Argonian spirit and then placing the amber in the zaht stone at the hist tree next to the road in the swamps southwest of Hissmir."},
			["Witness the True Balance"] =
				{appendText=" by activating the Zaht Stone at the road in the swamps southwest of Hissmir. Travel north by northeast by following the path from the location where you witnessed the Fruit and Stone, towards Hissmir to reach the location of the True Balance."},
			["Talk to Bimee-Kas"] =
				{appendText=" at the pit south of Hissmir."},
			["Talk to Kamax-Ei at the Xanmeer's Summit"] =
				{appendText=" in Hissmir"},
			["Confront Captain Henaamo"] =
				{appendText=""},
			["Collect Hist Amber"] =
				{appendText="\n\nFind Captain Henaamo and the Hist Amber inside the Ruined Xanmeer northwest of Hissmir."},
			["Activate the Northern Zaht Stone"] =
				{appendText=""},
			["Activate the Eastern Zaht Stone"] =
				{appendText=""},
			["Activate the Southern Zaht Stone"] =
				{appendText=""},
			["Activate the Western Zaht Stone"] =
				{appendText=""},
			["Talk to Kamax-Ei"] =
				{appendText=" at the Xanmeer's Summit in Hissmir."},
		},
		[GetQuestName(3849)] = { -- "A Final Release"				-- ARKANOBOT 
			["Find Najeepa's Remains"] =
				{appendText=". There have been rumors of sightings of an Argonian spirit on the road east of White Rose Prison. Perhaps you should start your search there."},
			["Find the Remains of Bezeer's Mother"] =
				{appendText=""},
			["Bring Najeepa's Remains to her Spirit"] =
				{appendText=" on the road east of White Rose Prison."},
		},
		[GetQuestName(3718)] = { -- "Into the Temple"				-- ARKANOBOT 
			["Break the Ward Blocking the Temple of Sul"] =
				{appendText=". The entrance is located in the Ayleid ruins north of the village in Zuuk."},
			["Enter the Temple of Sul"] =
				{appendText=". It is located in the Ayleid ruins north of the village in Zuuk."},
			["Search the Temple of Sul"] =
				{appendText=" at Zuuk.\n\nA ward of some kind blocks the keystone chamber. Perhaps the pillar marked with the image of Celestials could be the key to this ward?"},
			["Find the Keystone"] =
				{appendText=" in the final chamber of the Temple of Sul, north of the village in Zuuk."},
			["Talk to Morilye"] =
				{appendText=" in the final chamber of the Temple of Sul, north of the village in Zuuk."},
			["Return to Drillk"] =
				{appendText=" at the broken Ayleid tower, north of the village in Zuuk."},
			["Talk to Lodyna Arethi 1"] =
				{appendText=" behind a fallen tree log near the crossroads south of Zuuk.", stepTextKey="I couldn't let Drillk die on my behalf. The keystone will be safe within him. I should return to Lodyna Arethi and let her know about the keystone."},
			["Talk to Lodyna Arethi 2"] =
				{appendText=" behind a fallen tree log near the crossroads south of Zuuk", stepTextKey="Drillk is dead. He gave his life to pass the keystone to me. I should return to Lodyna Arethi and let her know about the keystone."},
		},
		[GetQuestName(3846)] = { -- "The Keystone"					-- ARKANOBOT 
			["Enter the Dungeon"] =
				{appendText=". The entrance to the dungeon lies in a cave near the swamps in the northwest section of the White Rose Prison below the southwestern tower."},
			["Find Sargon"] =
				{appendText=" in the dungeons near the northwest section of White Rose Prison."},
			["Find the Warden's Office"] =
				{appendText=" in the area above the cells inside the dungeon near the northwest section of White Rose Prison."},
			["Talk to Sargon"] =
				{appendText=" in the dungeons near the northwest section of White Rose Prison."},
			["Decide the Prisoners' Fate"] =
				{appendText=""},
			["Survive the Feral Onslaught"] =
				{appendText=" inside the dungeon."},
			["Talk to General Raetus"] =
				{appendText=" at one of the broken buildings in the southern section of the White Rose Prison."},
			["Talk to Gerent Hernik 1"] =
				{appendText=" on the road east, outside of White Rose Prison.", stepTextKey="I need to speak with Gerent Hernik and tell him about the Keystone."},
			["Escape White Rose Prison"] =
				{appendText=""},
			["Find Gerent Hernik"] =
				{appendText=""},
			["Meet Hernik Outside"] =
				{appendText=" near the southern exit of the White Rose Prison."},
			["Talk to Gerent Hernik 2"] =
				{appendText=" near the southern exit of the White Rose Prison.", stepTextKey="Gerent Hernik fled from the prison after I killed General Raetus. I should meet him outside the prison walls."},
		},
		[GetQuestName(3717)] = { -- "King of Dust"					-- ARKANOBOT 
			["Free the Kothringi in Zuuk"] =
				{appendText=". The Dominion has chained him in the center of the village in Zuuk."},
			["Talk to Drillk 1"] =
				{appendText="", stepTextKey="I need to speak to the Kothringi at his \"castle\" in Zuuk."},
			["Collect Metal Band"] =
				{appendText=""},
			["Collect Colored Glass"] =
				{appendText="\n\nSearch for the materials in and around the village in Zuuk."},
			["Forge the Crown"] =
				{appendText=" at the anvil near the center of the village in Zuuk."},
			["Bring the Crown to Drillk"] =
				{appendText=" at his hut in Zuuk."},
			["Steal a Scroll of Release"] =
				{appendText=" from the invader's camp west of Zuuk."},
			["Free Lleram"] =
				{appendText=""},
			["Free Dethrel"] =
				{appendText=""},
			["Free Sarase"] =
				{appendText="\n\nThe subjects of Zuuk are trapped in the lowlands in the western and northwestern region of Zuuk. Their screams can be heard echoing throughout the lowlands."},
			["Talk to Drillk 2"] =
				{appendText=" at his hut in Zuuk.", stepTextKey="I freed the subjects of Zuuk, though they weren't living, they were spirits. I should report this information to Drillk."},
			["Escort Drillk to the Tower"] =
				{appendText=" north of the village in Zuuk."},
			["Talk to Drillk 3"] =
				{appendText=" at the broken Ayleid tower north of the village in Zuuk.", stepTextKey="Drillk declared me the captain of his royal army. Now that he has addressed his \"subjects\" I should speak to Drillk about the keystone."},
		},
		[GetQuestName(3681)] = { -- "Lost Pilgrimage"				-- ARKANOBOT 
			["Search for Pilgrims"] =
				{appendText=" in the swamps north of Hissmir up to the road northeast of Hissmir. They may have lost their way and ended up in the treacherous marshes, where they are at risk of being killed by bandits or consumed by dangerous creatures lurking in the shadows."},
			["Search for Remaining Pilgrims"] =
				{appendText=" in the nearby swamps north of Hissmir. Perhaps someone survived to tell the tale and shed light on the recent deaths of their companions."},
			["Confront the Pilgrims' Murderers"] =
				{appendText=" on the Hill past the swamps north of Hissmir."},
			["Talk to Kiameed"] =
				{appendText=". He is waiting for your return with news of the pilgrims at the northern end of Hissmir."},
		},
		[GetQuestName(3804)] = { -- "Missing in the Mire"			-- Chaos
			["Rescue Scavengers from Stranglers"] =
				{appendText="\n\nSearch the area south of Xal Ithix."},
			["Talk to Sleeps-with-Open-Eyes"] =
				{appendText=" in front of the ruins south of Xal Ithix."},
			["Search the Trash Piles"] =
				{appendText=" south of Xal Ithix, in the vicinity the bog."},
			["Talk to Nimble-Knuckles"] =
				{appendText=". She is sitting around the ruins of Xal Ithix."},
		},
		[GetQuestName(3680)] = { -- "Of Dubious Value"				-- ARKANOBOT 
			["Interview Xula"] =
				{appendText=""},
			["Interview Tulut"] =
				{appendText=""},
			["Interview Kaloo"] =
				{appendText=""},
			["Search the Cart for Clues"] =
				{appendText="\n\nSearch the cart next to Wareem in Hissmir and ask around for any possible witnesses to the theft in the southwestern corner of Xanmeer in Hissmir."},
			["Search for the Culprit"] =
				{appendText=" or clues pointing towards the culprit on the eastern side of Hissmir."},
			["Search the Nearby Hut"] =
				{appendText=" in the eastern side of Hissmir."},
			["Talk to Wareem"] =
				{appendText=" at the southwestern corner of the Xanmeer in Hissmir. She should be waiting by her cart for news relating to the relics."},
		},
		[GetQuestName(3847)] = { -- "The Ones Left Behind"			-- ARKANOBOT 
			["Find Zarukhari's Remains"] =
				{appendText=""},
			["Find Nuzal's Remains"] =
				{appendText="\n\nSearch the prison dungeons for the ashes of Erranza's children. Perhaps the ashes are stored in an urn of some kind?"},
			["Collect Erranza's Remains"] =
				{appendText=" from White Rose Prison dungeon."},
			["Bury the Remains"] =
				{appendText=""},
			["Talk to Erranza"] =
				{appendText=" near the tree northwest of White Rose Prison."},
		},
		[GetQuestName(3732)] = { -- "Overrun"						-- ARKANOBOT
			["Talk to Silent-Moss at Murkwater"] =
				{appendText=". The Shadowscale Silent-Moss is observing the Dominion movements at Murkwater from the crossroads leading into Murkwater, just southeast of Hissmir."},
		},
		[GetQuestName(4551)] = { -- "A Poisoned Heart"				-- ARKANOBOT 
			["Collect a Wasp Husk"] =
				{appendText=" from the wasps south of the Hatching Pools.\n\nRhea could have some information that could help. Speak to her near the Hatching Pools Wayshrine."},
			["Bring the Husk to Rhea"] =
				{appendText=" at her Camp near the road beyond the swamps south of the Hatching Pools."},
			["Talk to Marius 1"] =
				{appendText=" at the Imperial Camp near the road beyond the swamps south of Hatching Pools.", stepTextKey="Rhea enchanted the wasp husk and instructed me to ask Marius about their plans."},
			["Use the Enchanted Container to Collect Poison Gas"] =
				{appendText="\n\nMarius has asked you to take care of the poison gas in the swamps southwest of the Hatching Pools near Gandranen Ruins and by the swamps further westward."},
			["Give Rhea the Poison"] =
				{appendText=""},
			["Give Marius the Poison"] =
				{appendText="\n\nThey await your return near a murky pond south of Zuuk, west of Gandranen Ruins."},
			["Talk to Rhea"] =
				{appendText=" at the poison dumping ditch, near the murky pool south of Zuuk, west of Gandranen Ruins."},
			["Talk to Marius 2"] =
				{appendText=" at the poison dumping ditch, near the murky pool south of Zuuk, west of Gandranen Ruins.", stepTextKey="I gave the enchanted container filled with poison to Marius, who was very grateful. I should speak to him about my reward."},
		},
		[GetQuestName(4560)] = { -- "Riches Beyond Measure"			-- ARKANOBOT 
			["Find the Crown of Ascension"] =
				{appendText=" deeper within Gandranen Ruins. According to what Zahra has heard, it is the crown of ancient Ayleid fenlords, and is made up of ice."},
			["Talk to Zahra"] =
				{appendText=" near the Crown of Ascension in Gandranen Ruins."},
		},
		[GetQuestName(3799)] = { -- "Scales of Retribution"			-- ARKANOBOT 
			["Rescue Batar-Meej"] =
				{appendText=". Silent-Moss said that Batar-Meej was captured and tied somewhere near the crescent pool in Murkwater."},
			["Rescue Nuwisha"] =
				{appendText=". Silent-Moss heard her cries coming from the caves in Murkwater."},
			["Rescue Radithax"] =
				{appendText=". Silent-Moss assumes he must be somewhere deeper in the Dominion Camp towards the western area of Murkwater southeast of Hissmir"},
			["Rendezvous with the Shadowscales"] =
				{appendText=""},
			["Signal Shadowscales to Save Townsfolk"] =
				{appendText="\n\nThe townsfolk of Murkwater are being coerced into excavating for an ancient relic in the Ayleid ruins on the southernmost edge of Murkwater. Search for the surviving townsfolk in the Ayleid ruins and signal the Shadowscales."},
			["Locate Haj-Tulm"] =
				{appendText=". She was last seen near the eastern section of the Ayleid ruins located at the southernmost edge of Murkwater."},
			["Find the Relleis Lor Keystone"] =
				{appendText=" in the Ayleid ruins located at the southernmost edge of Murkwater."},
			["Talk to Silent-Moss 1"] =
				{appendText=" at the eastern section of the Ayleid ruins located at the southernmost edge of Murkwater.", stepTextKey="Now that I've retrived the Relleis Lor keystone, I should find Silent-Moss.\n\nHe's waiting for me at an excavation site in Murkwater."},
			["Talk to Silent-Moss 2"] =
				{appendText=" at the eastern section of the Ayleid ruins located at the southernmost edge of Murkwater.", stepTextKey="Now that I've retrieved the Relleis Lor keystone, I should find Silent-Moss.\n\nHe's waiting for me at an excavation site in Murkwater."},--if zos fixes typo
			["Kill Khasar-dro and Velelya"] =
				{appendText=""},
			["Collect Fire Salts"] =
				{appendText=""},
			["Use Fire Salts Along the River"] =
				{appendText="\n\nThe Shadowscale Silent-Moss has asked you to use the Fire salts on the river near the Dominion Ship and in the surrounding water bodies to cut off their escape route."},
			["Talk to Silent-Moss 3"] =
				{appendText=" west of the Dominion Ship along the banks of the river in Murkwater.", stepTextKey="I've spread the fire salts all along the river. Now I need to meet with Silent-Moss east of the Dominion's ship."},
			["Light Fire Salts"] =
				{appendText=" on the broken branches set up by Silent-Moss near him on the river banks west of the Dominion Ship in Murkwater."},
			["Talk to Pale-Heart 1"] =
				{appendText=" at her camp on the hill near the southernmost edge of Murkwater.", stepTextKey="I've burnt the Dominion ships and retrieved the Relleis Lor keystone, I should return to Pale-Heart in Murkwater."},
			["Talk to Pale-Heart 2"] =
				{appendText=" at her camp on the hill near the southernmost edge of Murkwater.", stepTextKey="I've taken part in a ritual that bound the Rellis Lor Keystone to me. I should speak to Pale-Heart to see what's next."},
		},
		[GetQuestName(3911)] = { -- "The Swamp's Embrace"			-- ARKANOBOT 
			["Find the Prisoners' Bodies"] =
				{appendText="\n\nMaahi says that the bodies of other prisoners should be around the eastern halls and the caves adjacent to Loriasel's eastern halls. He has warned of the Lamias roaming the area due to the stench of the bodies."},
			["Talk to Maahi 1"] =
				{appendText=" in the cavern leading from caves adjacent to Loriasel's eastern halls. He has somehow managed to slip past the Lamias roaming the area.", stepTextKey="I found four of the missing prisoners. Akeenus said Maahi is waiting ahead, farther into the caves."},
			["Kill the Lamia Queen and Retrieve the Argonian Remains"] =
				{appendText="\n\nMaahi last saw the Lamia Queen in the Cavern leading from caves adjacent to Loriasel's eastern halls."},
			["Take the Remains to the Ruin's Antechamber"] =
				{appendText=""},
			["Reunite the Bodies"] =
				{appendText="\n\nThe bodies of the prisoners are kept near Maahi in the antechamber of Loriasel."},
			["Talk to Maahi 2"] =
				{appendText=" in the antechamber of Loriasel.", stepTextKey="I returned the flesh to the Argonian prisoners. I should speak to Maahi."},
			["Talk to Maahi 3"] =
				{appendText=" in the antechamber of Loriasel.", stepTextKey="I returned the flesh to the Argonian victims. I should speak to Maahi."},
		},
		[GetQuestName(3678)] = { -- "Trials of the Burnished Scales"-- ARKANOBOT 
			["Talk to Chimatei 1"] =
				{appendText=" at Hissmir", stepTextKey="I must speak with Chimatei to begin the first trial. She's on the northwest corner of the pyramid."},
			["Enter the Trial of the Mind"] =
				{appendText=". The entrance lies next to Chimatei, in the northwest corner of the pyramid in Hissmir."},
			["Complete the Trial of the Mind"] =
				{appendText=" at the northwest corner of the pyramid in Hissmir."},
			["Talk to Chimatei 2"] =
				{appendText=" at the northwest corner of the pyramid in Hissmir.", stepTextKey="I've completed the Trial of the Mind. I should speak with Chimatei about the next trial."},
			["Go to First Waypoint"] =
				{appendText=" at the tower connecting the pyramid in the western corner of the pyramid in Hissmir."},
			["Talk to Chimatei 3"] =
				{appendText=" at the northwest corner of the pyramid in Hissmir.", stepTextKey="I should speak with Chimatei to start the Trial of the Heart once more."},
			["Go to Second Waypoint"] =
				{appendText=" by following the path west from the tower. On your way towards the waypoint, there awaits someone who could use your help but will you?"},
			["Go to Third Waypoint"] =
				{appendText=" by following the same path back to Hissmir, to the stele towards the southwest corner of Hissmir. Once again, on your way towards the waypoint, You see the Argonian next to the stone brazier who could use your help, but will you?"},
			["Talk to Nazuux"] =
				{appendText=" next to the stele in the southwest corner of Hissmir."},
			["Talk to Bimee-Kas 1"] =
				{appendText=", south of Hissmir.", stepTextKey="I must talk to Bimee-Kas to begin the Trial of the Fang. I can find him in the pit south of the pyramid."},
			["Drink the Root Rot Poison"] =
				{appendText=" at the pit south of Hissmir."},
			["Complete the Trial of the Fang"] =
				{appendText=" at the pit south of Hissmir."},
			["Talk to Bimee-Kas 2"] =
				{appendText=" at the pit south of Hissmir.", stepTextKey="I defeated my opponent and completed the Trial of the Fang. I should speak to Bimee-Kas."},
			["Escort Leetu Back to Hissmir"] =
				{appendText=""},
		},
		[GetQuestName(3912)] = { -- "Vigil's End"					-- ARKANOBOT 
			["Recover the Sword Shards"] =
				{appendText=""},
			["Find the Knight's Shield"] =
				{appendText="\n\nSearch the western halls in Loriasel for the relics."},
			["Find the Ayleid Knight"] =
				{appendText=" in the western halls in Loriasel"},
			["Talk to the Ayleid Knight 1"] =
				{appendText=". His spirit awaits me in his tomb chamber with an Ayelid statue in the western halls of Loriasel.", stepTextKey="The spirit appeared before me at its tomb. I should find out why it has taken an interest in me."},
			["Find the Enchanter"] =
				{appendText=" in the western halls of Loriasel. Perhaps searching for the Tomb of the Liege Lord might give you more insights into finding the enchanter and putting the spirit of the Ayleid knight to rest."},
			["Investigate the Tomb"] =
				{appendText=" of the Liege Lord in the western halls of Loriasel."},
			["Talk to the Ayleid Knight 2"] =
				{appendText=" in the Tomb of the Liege Lord in the western halls of Loriasel.", stepTextKey="The spirit drive away the ghost of the Enchanter, who had murdered the spirit's liege lord. It asked me to destroy the Enchanter's phylactery. The spirit believes doing so will end the Enchanter's threat."},
			["Destroy the Phylactery"] =
			 {appendText=" in the Tomb of the Liege Lord in the western halls of Loriasel."},
		},
		[GetQuestName(3802)] = { -- "What Happened at Murkwater"	-- ARKANOBOT 
			["Talk to Azinar at Hissmir"] =
				{appendText=". He is listening to the complaints of agitated Argonians on the road northeast, just outside of Hissmir."},
		},
		[GetQuestName(3791)] = { -- "Outside Interference"			-- Rosque
			["Examine Extractor Instructions"] =
				{appendText="."},
			["Collect Giant Wasp Larvae"] =
				{appendText=""},
			["Collect Hist Sap"] =
				{appendText="."},
			["Test Poultice on a Jungle Plant"] =
				{appendText=". One of the tall, leafy green plants around the edges of the Hatching Pools should be suitable."},
			["Inform a Keeper of the Shell"] =
				{appendText=". Someone that tends to the Hist would be the most appropriate to warn about the dangers of the poultice."},
			["Talk to Keeper Keel-Lurash"] =
				{appendText=", near the southern stairs at the Hist of the Hatching Pools."},
		},


-- 		=========================================================================
--		  Eastmarch Main
-- 		=========================================================================
		[GetQuestName(4152)] = { -- "Swamp to Snow"					-- Rosque 
			["Talk to the Boatmaster"] =
				{appendText=" in Shadowfen. With the preparations to depart, they should be just beside the large seaworthy vessel in Alten Corimont, getting ready to cast off."},
			["Talk to Vicecanon Heita-Meen"] =
				{appendText=" at the northern docks of Windhelm."},
		},
		[GetQuestName(4058)] = { -- "Shadows Over Windhelm"			-- Mouch30
			["Talk to Thane Mera Stormcloak 1"] =
				{appendText=", who is stretched thin from all her duties. She waits for capable helpers at the front gates of the formidable manor, watching over the city from the north.", stepTextKey="Mera Stormcloak, thane of Windhelm and commander of the Windhelm Guard, wants to speak to me. I can find her in front of the Palace of Ysgramor."},
			["Enter the Cold Moon Inn"] =
				{appendText=", a quaint establishment that hosts many warriors, as long as they don't mind the smell of the stables right outside."},
			["Find Evidence"] =
				{appendText=" that might link the Stormfist clan to the injuries and deaths that have been occurring around the city."},
			["Find Hidden Caches"] =
				{appendText="\nAccording to the journal, the clues are as follow:\n\n'Between a moon that's cold and a wizard's hoard\nBehind a cracked henge stone, west and breezy\nAt the rear of Windhelm's only abstaining Nord\nWhere mount and mare rest calm and easy.\n\nThe clues seem to refer to specific buildings and locations in the city."},
			["Talk to Thane Mera Stormcloak 2"] =
				{appendText=", who waits for your return at the gate of the Palace of Ysgramor, in the northern district.", stepTextKey="I recovered a number of notes and weapons from caches hidden throughout Windhelm, as well as a journal that ties these things to the Stormfist clan. Thane Mera will want to see these."},
		},
		[GetQuestName(4059)] = { -- "The Konunleikar"				-- Mouch30
			["Talk to Lenning the Hawk 1"] =
				{appendText=". A crowd gathers near the standing stones to the west, cheering on the participants.", stepTextKey="The footrace starts along the western wall of Windhelm. I need to speak to Lenning the Hawk, the race organizer, to enter the event."},
			["Light the Starting Flare"] =
				{appendText=" at the base of the stairs of Windhelm's western wall."},
			["Reach the First Tower"] =
				{appendText=""},
			["Reach the Second Tower"] =
				{appendText=""},
			["Reach the Third Tower"] =
				{appendText=""},
			["Reach the Fourth Tower"] =
				{appendText=""},
			["Reach the Fifth Tower"] =
				{appendText=""},
			["Reach the Sixth Tower"] =
				{appendText=""},
			["Reach the Seventh Tower"] =
				{appendText=", and win the race for yourself!"},
			["Help Hadring the Swift"] =
				{appendText=", who fell on the bridge to the seventh tower. There might be foul play afoot."},
			["Reach the Eighth Tower"] =
				{appendText=""},
			["Reach the Ninth Tower"] =
				{appendText=""},
			["Reach the Finish Line"] =
				{appendText=""},
			["Talk to Lenning the Hawk 2"] =
				{appendText=", waiting for the competitors at the finish line, at the very northeastern point of Windhelm's surrounding wall.", stepTextKey="I won the race. I should speak with Lenning the Hawk."},
			["Talk to Thane Mera Stormcloak 1"] =
				{appendText=". She will be pleased to learn that her new champion has won the race.", stepTextKey="The race has ended and Thane Mera has asked to speak with me. I should meet her outside the palace."},
			["Talk to Lenning the Hawk 3"] =
				{appendText=", waiting for the competitors at the finish line, at the very northeastern point of Windhelm's surrounding wall.", stepTextKey="I abandoned the race to help Hadring. Unfortunately, he didn't make it. He provided me with useful information before he expired, though. I should speak with Lenning the Hawk."},
			["Talk to Thane Mera Stormcloak 2"] =
				{appendText=" back at the palace steps, in the city's northern district. You didn't win the race, but Hadring's final words might just save the day.", stepTextKey="Someone killed Hadring during the race. I should speak to Thane Mera and let her know what happened."},
		},
		[GetQuestName(4060)] = { -- "Windhelm's Champion"			-- Mouch30
			["Talk to Witnesses"] =
				{appendText=" who were standing by the sixth and seventh tower when the race was happening, which should be in the clearing next to the Cold Moon Inn and The Anvil and the Pauldron."},
			["Follow the Assassins"] =
				{appendText=" before they get too far. Following the southern road might lead you to their headquarters."},
			["Collect Evidence"] =
				{appendText=" from the Stormfist brutes around the camp. They might be carrying something incriminating."},
			["Retrieve Assassin's Orders"] =
				{appendText=" - there has to be some documentation to prove that these were indeed calculated crimes."},
			["Talk to Mera Stormcloak"] =
				{appendText=", standing in her familiar spot at the gate of the Palace of Ysgramor, in the northern district of the city."},
		},
		[GetQuestName(4061)] = { -- "One Victor, One King"			-- Mouch30
			["Enter the Hall of Trials"] =
				{appendText=", a large Nordic ruin turned arena. The hall can be found in the northeastern district, past the docks and is right next to the local carpenter."},
			["Enter the Arena"] =
				{appendText=", at the northeastern district of the city. The hall is lined with impressive Nordic statues, and the stench of mead and blood lingers in the air."},
			["Observe the Champion"] =
				{appendText=", at the northeastern district of the city."},
			["Defeat the Stormfist Clan"] =
				{appendText=", in the Hall of Trials in the northeastern district of the city. No Stormfist can be left alive."},
			["Talk to Jorunn the Skald-King"] =
				{appendText=", in the Hall of Trials at the northeast district of the city. He doesn't seem to be hurt - he's quite the warrior himself."},
			["Talk to Thane Mera Stormcloak"] =
				{appendText=". It's a miracle she doesn't catch a cold standing at the northern gates all day."},
		},
		[GetQuestName(4197)] = { -- "Sounds of Alarm"				-- Mouch30
			["Talk to Captain Hamar"] =
				{appendText=", the head of the Morvunskar division. The fort guards the northwest of Eastmarch, watching over the snowy hills and the branching rivers. Camps have been set up just past the leading bridge."},
		},
		[GetQuestName(4062)] = { -- "Blindsided"					-- Mouch30
			["Rescue Morvunskar Soldiers"] =
				{appendText="\n. These loyal warriors are being held captive in the fort's many buildings. Search the entire courtyard to rescue your fellow soldiers."},
			["Talk to Lieutenant Koruni 1"] =
				{appendText=", who should be able to give you your next order.", stepTextKey="I need to meet Lieutenant Koruni and the other soldiers at the barracks near the center of Fort Morvunskar."},
			["Enter the Barracks"] =
				{appendText=", the central building in the courtyard."},
			["Defeat Warlord Halskar"] =
				{appendText=", fighting your way through his savages in the barracks, at the center of the courtyard."},
			["Search the Strongbox"] =
				{appendText=" on Halskar's desk, on the second floor of the fort barracks."},
			["Talk to Queen Nurnhilde"] =
				{appendText=", a regal and handsome looking spirit. She has materialized on the second floor of the fort barracks, where you defeated Halskar."},
			["Talk to Lieutenant Koruni 2"] =
				{appendText=",  who awaits you on first floor of the fort barracks.", stepTextKey="I spoke to the spirit of Queen Nurnhilde. She asked me to return the relics to the tombs beneath the fort. Along with these relics, I recovered Halskar's orders. I should give the orders to Lieutenant Koruni before I go meet the ghost."},
		},
		[GetQuestName(4071)] = { -- "Sleep for the Dead"			-- Mouch30
			["Talk to Queen Nurnhilde 1"] =
				{appendText=", the late sister of King Jorunn and of their traitor brother Fildgor. She waits at the front doors of the crypt on the northern side of Fort Morvunskar's barracks.", stepTextKey="Queen Nurnhilde wanted me to meet her at the entrance to the crypt. It should be right behind the barracks."},
			["Enter the Royal Tombs"] =
				{appendText=", located in the crypt on the northern side of Fort Morvunskar's barracks."},
			["Find the First Burial Chamber"] =
				{appendText=" by exploring the ruins on the northern side of Fort Morvunskar's barracks."},
			["Return the Old Nord Cup"] =
				{appendText=". The cup itself is simple in design, with few ornamentation."},
			["Find the Second Burial Chamber"] =
				{appendText=" by using the wooden ramps to go further into the ruins on the northern side of Fort Morvunskar's barracks."},
			["Return the Nord Book"] =
				{appendText=" to its original glory by reading what remains and choosing the correct page. The book awaits for you in your pack, along with any pages you might collect in the chamber."},
			["Find the Final Burial Chamber"] =
				{appendText=" located in the deepest depths of the ruin on the northern side of Fort Morvunskar's barracks."},
			["Talk to Queen Nurnhilde 2"] =
				{appendText=" in the final burial chamber of the ruins on the northern side of Fort Morvunskar's barracks.", stepTextKey="I made my way to Queen Nurnhilde's burial chamber. I see her standing by her stone coffin and she seems upset. I should speak to her."},
			["Exit the Tomb Via the Tunnel"] =
				{appendText=" on the eastern wall of the final burial chamber on the northern side of Fort Morvunskar's barracks."},
			["Pursue Fildgor Orcthane"] =
				{appendText=", who rushed out of the tunnel and into the great beyond of Eastmarch."},
			["Defeat Shukul gro-Agluk"] =
				{appendText=" at the mouth of the tunnel exiting the Morvunskar ruins."},
			["Talk to Captain Hamar"] =
				{appendText=" in the fort's courtyards. The savages seem to have been driven out."},
			["Talk to Queen Nurnhilde 3"] =
				{appendText=", who has appeared just beyond the captain and his team, in the fort's courtyard. She glows a brighter blue against the white snow.", stepTextKey="After I learned of Fort Morvunskar's liberation, the spirit of Queen Nurnhilde appeared again. I should speak to her."},
		},
		[GetQuestName(4177)] = { -- "Victory at Morvunskar"			-- Mouch30
			["Talk to Thane Oda at Fort Amol"] =
				{appendText=", a stronghold overlooking the southwest region of Eastmarch. Oda and the other nobles strategize at the pavilions near the eastern bridge."},
		},
		[GetQuestName(4150)] = { -- "Sleeping on the Job"			-- Mouch30
			["Talk to Commander Yjarnn"] =
				{appendText=", accompanied by a Nord soldier, standing guard on a bridge in the middle of the town."},
			["Find Sentry Thod"] =
				{appendText=". All sorts of important figures gather around the tents on the eastern border - surely some of them must know where Thod could be."},
			["Find Commander Yjarnn"] =
				{appendText=" at his regular post in the middle of town. Thod's fellow guards will no doubt be relieved to know that he is safe."},
			["Look for Commander Yjarnn at the Guard House"] =
				{appendText=" on the west side of town."},
			["Talk to Lord Vurlop"] =
				{appendText=", a richly dressed Nord sulking on the steps of the barracks, on the west side of town."},
			["Follow Commander Yjarnn"] =
				{appendText=" through the fort grounds. Keep your distance, but don't lose him!"},
			["Search Marla's House"] =
				{appendText=", a decently sized cottage with an adjoining makeshift marketplace, just across from the barracks."},
			["Talk to Hloenor Chill-Owl"] =
				{appendText=" at her post on the bridge in the middle of town. With the alchemy report in hand and the commander dead, it'll be hard to trust anyone in Fort Amol."},
			["Talk to Guard Hloenor"] =
				{appendText=" at her post on the bridge in the middle of town. With the alchemy report in hand and the commander dead, it'll be hard to trust anyone in Fort Amol."},
		},
		[GetQuestName(4158)] = { -- "The Pride of a Prince"			-- Mouch30
			["Talk to Lord Vurlop"] =
				{appendText=". The inn, one of the largest buildings on site, stands near the western bridge. The stink of fish from the docks nearby does no harm to the appetites of the Nords."},
			["Talk to Thane Harvald 1"] =
				{appendText=" back at the tents to the east. Harvald and the other more reasonable Nords continue talking with the prince, leaving the revelry to the others.", stepTextKey="Lord Vurlop doesn't want word of this to reach Prince Irnskar. He's afraid that tempers will fly and cause a rift among the alliance. He suggested that I talk to Thane Harvald at the Nord camp and get his advice on this matter."},
			["Talk to the Pact Delegates"] =
				{appendText="\nGelds Indoril, the Dark Elf delegate, is as snobbish as they come. Perhaps someone at the camp is more suited to convince him?\nRuns-With-Quickness, the Argonian leader, is hurt by the prince's dismissal. Offering some sort of help might restore their faith in the Pact."},
			["Talk to Thane Harvald 2"] =
				{appendText=", waiting for you to return to the strategy table in the Nord camp.", stepTextKey="I convinced the Argonians and the Dark Elves to return to Prince Irnskar's meeting. I should inform Thane Harvald and see how he wants to proceed."},
		},
		[GetQuestName(4166)] = { -- "The War Council"				-- Mouch30
			["Accompany Lord Vurlop to the Keep"] =
				{appendText=". Massive stone walls surround the manor, taking up most of the southern grounds."},
			["Talk to Naryu 1"] =
				{appendText=" just off to the side from the keep gates, on the southern grounds of the fort.", stepTextKey="Lord Vurlop led me into a trap. Naryu Virian showed up just in time to help me. I should ask her what's going on."},
			["Find the Key to the Jarl's Manor"] =
				{appendText=", on the southern grounds of the fort. Dangerous Stormfist bandits mill about, waiting for their next orders."},
			["Enter the Jarl's Manor"] =
				{appendText=", on the southern grounds of the fort. You can only hope that the King is still alive."},
			["Talk to Naryu 2"] =
				{appendText=", waiting in the middle of the foyer of the manor, on the southern grounds of the fort.", stepTextKey="It looks like Naryu found her own way into the Jarl's manor. But I see only one guard. Where are the rest of King Jorunn's soldiers? I should talk to Naryu and see what she found out."},
			["Find a Way to Open the Locked Doors"] =
				{appendText=" - a safe room on the ground floor, and a vault on the upper level. Naryu suggested to search the upper floor for any clues."},
			["Enter the Safe Room and Talk to King Jorunn"] =
				{appendText=", on the ground floor of the Jarl's manor, on the southern grounds of the fort."},
			["Defeat Dhalen"] =
				{appendText=", lurking on the upper level of the Jarl's manor, in the southern grounds of the fort."},
			["Rescue the Pact Leaders"] =
				{appendText=". The vault doors, on the upper level of the Jarl's manor, appear to have been unlocked."},
			["Find Help for the King"] =
				{appendText=". Someone in Fort Amol might have the knowhow to cure the King."},
			["Talk to Naryu 3"] =
				{appendText=". She beckons you at the top of the staircase of the upper level of the Jarl's manor, on the southern grounds of the fort.", stepTextKey="I ran into Naryu when I emerged from the vault. I should speak to her."},
			["Talk to Prince Irnskar"] =
				{appendText=" on the lower level of the Jarl's manor, on the southern grounds of the fort. News of his father being poisoned has left him more agitated than usual."},
		},
		[GetQuestName(4203)] = { -- "Lifeline"						-- Mouch30
			["Get the Help of the Dreamwalker"] =
				{appendText=", an Argonian mystic who can traverse the realm of dreams. He must be in hiding, as his home of Darkwater Crossing is overrun by trolls."},
			["Get the Blood of the Vampire from Wittestadr"] =
				{appendText=". Rumor has it a den of vampires make their home near the hot springs. They won't give their blood willingly, but maybe a barter can take place."},
			["Meet Oda at the Ternion Cave"] =
				{appendText=". The cave is tucked in a rocky grove, directly northeast of the ancient dragon burial mound."},
		},
		[GetQuestName(4205)] = { -- "Our Poor Town"					-- Mouch30
			["Find Stormy-Eyes's Key"] =
				{appendText=". He stashed it in an urn moments before entering the cave - the vase must still be nearby. A group of rocks seems like the perfect hiding place."},
			["Enter Stormy-Eyes's House"] =
				{appendText=", the only intact building in the area."},
			["Confront the Stranger in the House"] =
				{appendText=". A disgruntled Redguard roots among Stormy's items, making quite a mess."},
			["Confront Asmalah"] =
				{appendText=" about his apparent grudge towards Stormy-Eyes. He might have gone to hurt the hiding Argonians in their cave, or may be lying in wait near the ruined building."},
			["Find Asmalah"] =
				{appendText=" before he gets too far. The portal he opened is still active on the rocky river bank to the southwest of the Argonians' cave."},
			["Search the Ruined House for the Reagents"] =
				{appendText=". Asmalah stashed them in a vase before waiting for your arrival."},
			["Return to Stormy-Eyes 1"] =
				{appendText=", who has been eagerly awaiting your return in the nearby den.", stepTextKey="I recovered the reagents and collected the torchbug wings needed for the healing ritual. I should return to the cave and turn them over to Stormy-Eyes."},
			["Watch the Ritual 1"] =
				{appendText=" occurring in the Argonians' cave. An azure miasma hangs over the sleeping Argonian, while Stormy-Eyes tends to her injuries.", stepTextKey="I gave Stormy-Eyes what he needed to perform the healing ritual. Now all I can do is watch and wait."},
			["Talk to Stormy-Eyes 1"] =
				{appendText=" in the Argonians' cave. He should be willing to help you now.", stepTextKey="The ritual seems to have worked. I should speak to Stormy-Eyes."},
			["Return to Stormy-Eyes 2"] =
				{appendText=", who has been eagerly awaiting your return in the nearby den.", stepTextKey="Asmalah is dead. I wasn't able to recover Stormy-Eyes's satchel. I should return to the cave and see how Stormy-Eyes wants to proceed."},
			["Watch the Ritual 2"] =
				{appendText=" occurring in the Argonians' cave. An azure miasma hangs over the sleeping Argonian, while Stormy-Eyes tends to her injuries.", stepTextKey="Stormy-Eyes has decided to go ahead with the healing ritual even though I wasn't able to gather everything he needed. I should wait and see what happens."},
			["Talk to Stormy-Eyes 2"] =
				{appendText=" in the Argonians' cave. Hopefully this failure doesn't stop Stormy-Eyes from helping you.", stepTextKey="The ritual failed. The poor Argonian woman is dead and Stormy-Eyes is wounded, but at least Asmalah paid for what he did. I should speak to Stormy-Eyes to find out what to do next."},
		},
		[GetQuestName(4075)] = { -- "A Right to Live"				-- Mouch30
			["Talk to Sena Aralor"] =
				{appendText=", a dazed and injured Dark Elf. She tries her best to stay by your side as you explore the dangerous region of Wittestadr."},
			["Find Imhey"] =
				{appendText=". The center of the springs is marked by a large, jutting rock overlooking the muddy pools of Wittestadr."},
			["Speak to the Stranger Confronting Imhey"] =
				{appendText=". The pale skinned soldier is clearly uncomfortable, but Imhey will not budge from underneath the outcrop in the center of the hot springs of Wittestadr."},
			["Collect Bloodfiend Dust"] =
				{appendText="\nBloodfiends are feral vampires that lust for nothing more than mortal blood. Hordes gather outside the buildings of Wittestadr, waiting for unsuspecting victims to walk by."},
			["Enter Valeric's Manor"] =
				{appendText=". It must be one of the only two buildings on the grounds of Wittestadr."},
			["Talk to Valeric 1"] =
				{appendText=". Rala mentioned that he would be upstairs in his manor on the grounds of Wittestadr.", stepTextKey="I'm inside Valeric's manor. I need to find Valeric and see how Imhey is doing."},
			["Talk to Valeric 2"] =
				{appendText=". Rala mentioned that he would be upstairs in his manor on the grounds of Wittestadr.", stepTextKey="I should speak to Valeric and discuss Imhey's situation."},
		},
		[GetQuestName(4106)] = { -- "The Better of Two Evils"		-- Mouch30
			["Talk to Jaruk"] =
				{appendText=", the Khajiit tending the bar on the lower level of Valeric's manor in Wittestadr."},
			["Find the Hunters' Camp"] =
				{appendText=", stationed in the southern region of Wittestadr. It would be wise to distract the hunters with combat before dousing them in this warm and pungent fluid."},
			["Talk to Majorn or Ignore Him and Find the Hunters"] =
				{appendText=", who have set up camp in the southern region of Wittestadr."},
			["Use the Rune to Capture a Bloodfiend"] =
				{appendText=". Standing near one of the feral beasts near the manors in Wittestadr should be enough for the rune to work."},
			["Kill the Hunters"] =
				{appendText="\nTheir camp can be found by following the southern dirt path to the lower region of Wittestadr."},
			["Talk to Majorn the Ancient 1"] =
				{appendText=" back at his manor in the northern region of Wittestadr.", stepTextKey="The hunters are dead. I should return to Majorn and tell him that I did what he requested."},
			["Kill Valeric"] =
				{appendText=". His reckless goal to rescue vampires from their natural state has caused too many deaths. It's time to end his foolish dream."},
			["Talk to Majorn the Ancient 2"] =
				{appendText=", back at his manor in Wittestadr. It was his wish for his son to die, but he might not be too happy with the conclusion.", stepTextKey="I destroyed Valeric, just as Majorn requested. I should return to Majorn and let him know what happened."},
			["Talk to Majorn the Ancient 3"] =
				{appendText=", back at his manor in Wittestadr.", stepTextKey="I should talk to Majorn and claim my reward."},
			["Splash the Weakened Hunters"] =
				{appendText="\nThe hunters have set up camp in the southern region of Wittestadr. It would be wise to distract them in combat before dousing them in this unpleasant fluid."},
			["Talk to Valeric 1"] =
				{appendText=" back at his manor in the northern region of Wittestadr. His plan worked perfectly, and the hunters are safe.", stepTextKey="The scent of the hunters has been masked. I should return to Valeric to let him know."},
			["Enter Majorn's Manor"] =
				{appendText=", the only other building in the northern region of Wittestadr."},
			["Confront Rala"] =
				{appendText=", at Majorn's manor in the northern region of Wittestadr."},
			["Stop Rala and Retrieve the Crypt Key"] =
				{appendText=". She fled to the upper level of Majorn's manor in the northern region of Wittestadr."},
			["Enter the Crypt 1"] =
				{appendText=" to get to the lower levels of Majorn's manor in the northern region of Wittestadr. The cellar door must be hidden in the house.", stepTextKey="I had to kill Rala. I found the key to the crypt on her body. Now I need to enter the crypt and confront Majorn."},
			["Kill Majorn the Ancient"] =
				{appendText=" and stop him from fulfilling his goals. He's hiding in the depths of his manor in the northern region of Wittestadr."},
			["Talk to Valeric 2"] =
				{appendText=", waiting for you to return to his manor in the northern region of Wittestadr. With his father out of the way, he can continue his plan to help lost vampires.", stepTextKey="I destroyed Majorn the Ancient. I should return to Valeric and let him know what happened."},
			["Talk to Valeric 3"] =
				{appendText=" at his manor in the northern region of Wittestadr.", stepTextKey="I should talk to Valeric and find out what he plans to do next."},
			["Enter the Crypt 2"] =
				{appendText=" to get to the lower levels of Majorn's manor in the northern region of Wittestadr. The cellar door must be hidden in the house.", stepTextKey="I managed to calm Rala and get the key to the crypt. Now I need to enter the crypt and confront Majorn."},
		},
		[GetQuestName(4115)] = { -- "Eternal Slumber"				-- Mouch30
			["Talk to Jadvar"] =
				{appendText=". The Ternion monks are using the cavern to the northeast of the ancient dragon burial mound as their home, where they will aid the Skald-King."},
			["Enter the Ritual Grounds"] =
				{appendText=" to gain acess to the rest of the Ternion monks' home. The portal waits on the stone altar, in the cave to the northeast of the ancient dragon burial mound."},
			["Talk to the High Priest"] =
				{appendText=", currently watching over the slumbering body of the Skald-King, underneath the stone arch in Mistwatch."},
			["Observe the Dreamwalker"] =
				{appendText=""},
			["Pray at the Totems"] =
				{appendText="\nThe Totem of the Fox represents the Chief of The Gods, Shor.\nThe Totem of the Bear symbolizes the strength of Tsun, the protector.\nThe Totem of the Wolf pays homage to Mara, the Divine Mother.\n\nHigh Priest Esling stands between the totems, on the stone altar in Mistwatch."},
			["Return to High Priest Esling"] =
				{appendText=" at the central altar of Mistwatch."},
			["Talk to High Priest Esling"] =
				{appendText=" at the central altar of Mistwatch."},
		},
		[GetQuestName(4123)] = { -- "Gods Save the King"			-- Mouch30
			["Pray to the Fox 1"] =
				{appendText=" and feel yourself move swiftly among your attackers.", stepTextKey="The first trial requires strength. I should pray to one of the three totems for guidance. Perhaps High Priest Esling can offer some advice before I choose."},
			["Pray to the Bear 1"] =
				{appendText=" and bolster your protection against foes.", stepTextKey="The first trial requires strength. I should pray to one of the three totems for guidance. Perhaps High Priest Esling can offer some advice before I choose."},
			["Pray to the Wolf 1"] =
				{appendText=" and gain insight on your enemy's weaknesses.", stepTextKey="The first trial requires strength. I should pray to one of the three totems for guidance. Perhaps High Priest Esling can offer some advice before I choose."},
			["Free Fractured Spirit of Jorunn 1"] =
				{appendText=". The first shard is hidden at the end of a Nordic tomb. Undead soldiers roam the halls, and the stench of decay hangs heavy in the air.", stepTextKey="It appears the King's spirit has been fractured, broken into three parts. I must run the gauntlet of Jorunn's nightmare and set his spirit shard free."},
			["Talk to High Priest Esling 1"] =
				{appendText=" at the central altar of Mistwatch.", stepTextKey="I set a shard of King Jorunn's fractured spirit free. I should leave this dark dream and talk to High Priest Esling."},
			["Pray to the Fox 2"] =
				{appendText=" and feel yourself move swiftly among your attackers.", stepTextKey="The second trial requires quickness. I should pray to one of the three totems for guidance. Perhaps High Priest Esling can offer some advice before I choose."},
			["Pray to the Bear 2"] =
				{appendText=" and bolster your protection against foes.", stepTextKey="The second trial requires quickness. I should pray to one of the three totems for guidance. Perhaps High Priest Esling can offer some advice before I choose."},
			["Pray to the Wolf 2"] =
				{appendText=" and gain insight on your enemy's weaknesses.", stepTextKey="The second trial requires quickness. I should pray to one of the three totems for guidance. Perhaps High Priest Esling can offer some advice before I choose."},
			["Talk to the Shade of Jorunn"] =
				{appendText=". His ghostly figure barely stands out against the frozen walls and chilly air.\n"},
			["Free Fractured Spirit of Jorunn 2"] =
				{appendText=". This shard is lost within the icy tunnel. Frozen icicles stick out from the walls, threatening a slow and frosty death.", stepTextKey="I need to stay close to the fires as I navigate this dream. Otherwise, the cold will sap my strength. I must run the gauntlet of Jorunn's nightmare and set the shard of his spirit free."},
			["Talk to High Priest Esling 2"] =
				{appendText=" at the central altar of Mistwatch.", stepTextKey="I set the second shard of King Jorunn's fractured spirit free. I should leave this dark dream and talk to High Priest Esling."},
			["Pray to the Fox 3"] =
				{appendText=" and feel yourself move swiftly among your attackers.", stepTextKey="The third trial requires perception and observation. I should pray to one of the totems for guidance, one last time. Perhaps High Priest Esling can offer some advice before I choose."},
			["Pray to the Bear 3"] =
				{appendText=" and bolster your protection against foes.", stepTextKey="The third trial requires perception and observation. I should pray to one of the totems for guidance, one last time. Perhaps High Priest Esling can offer some advice before I choose."},
			["Pray to the Wolf 3"] =
				{appendText=" and gain insight on your enemy's weaknesses.", stepTextKey="The third trial requires perception and observation. I should pray to one of the totems for guidance, one last time. Perhaps High Priest Esling can offer some advice before I choose."},
			["Talk to Stormy-Eyes"] =
				{appendText=", in the final dream realm. It's almost an exact replica of Mistwatch, save for the snowbanks."},
			["Free Fractured Spirit of Jorunn 3"] =
				{appendText=". The shard followed a pretty young woman up the stairs to the central altar of this frozen Mistwatch.", stepTextKey="The King's spirit has been fractured, and the final part remains a prisoner within his own dreams. I need to find it and set it free before it's too late."},
			["Talk to Jorunn the Skald-King 1"] =
				{appendText=" at the altar on the highest platform of Mistwatch. Two empty thrones stare back at the Skald-King.", stepTextKey="King Jorunn's fractured spirit has been freed and made whole again. I should speak to him before exiting his dream."},
			["Leave the Dream"] =
				{appendText=" through the portal near the altar on the highest platform of Mistwatch."},
			["Talk to Jorunn the Skald-King 2"] =
				{appendText=" at the stone altar in Mistwatch.", stepTextKey="King Jorunn is awake. I should speak to him."},
			["Talk to Jorunn the Skald-King 3"] =
				{appendText=" at the stone altar in Mistwatch.", stepTextKey="Jorunn the Skald-King is awake. I should speak to him."},
		},
		[GetQuestName(4169)] = { -- "Of Councils and Kings"			-- Mouch30
			["Go to Jorunn's Stand"] =
				{appendText=", a sprawling campsite near the eastern mountains, and check in with the guard at the front gate."},
		},
		[GetQuestName(4069)] = { -- "Making Amends"					-- Mouch30
			["Talk to Prince Irnskar 1"] =
				{appendText=". Hopefully his head has cleared and he's ready to fight for the Pact.", stepTextKey="Prince Irnskar wants to speak with me. I can find him on the battlements above the east gate."},
			["Talk to General Noramil or Eyes-of-Steel"] =
				{appendText=". The troop leaders are at their respective camps, near the rocky walls to the west."},
			["Talk to General Yeveth Noramil"] =
				{appendText=" at the Dunmer tents near the rocky walls to the west."},
			["Charge Viper's Strike"] =
				{appendText="\nBathe the dagger in the blood of slain Stormfists that hang out in the snowy hills to the east of Jorunn's Stand."},
			["Get Bitterblade's Head"] =
				{appendText=". The Stormfist leader is stationed at the top of the eastern path."},
			["Talk to Eyes-of-Steel"] =
				{appendText=", watching over the settlement from a grassy outcrop near the Argonians' camp."},
			["Return Viper's Strike to General Yeveth Noramil"] =
				{appendText=" at the Dunmer dining tent."},
			["Give Bitterblade's Head to Eyes-of-Steel"] =
				{appendText=" at her position overlooking the Argonian camp."},
			["Talk to Prince Irnskar 2"] =
				{appendText=" on the battlements above the east gate.", stepTextKey="I should report to Prince Irnskar and tell him what I did to improve relations with General Yeveth Noramil and Eyes-of-Steel."},
		},
		[GetQuestName(4078)] = { -- "A Council of Thanes"			-- Mouch30
			["Talk to Thane Harvald 1"] =
				{appendText=", stationed at the northernmost gate in Jorunn's Stand.", stepTextKey="Prince Irnskar suggested that I speak to Thane Harvald first."},
			["Talk to Thane Oda's Housecarl"] =
				{appendText=", who watches over the southern field of Jorunn's Stand from atop the battlement."},
			["Give Harvald's Dispatch to the Skald-King"] =
				{appendText=". He resides in a secluded pavilion at the end of the Dunmer camp, just west of the northern gate of Jorunn's Stand."},
			["Talk to Thane Harvald 2"] =
				{appendText=", waiting for your return at the northern gate of Jorunn's Stand.", stepTextKey="King Jorunn seemed tired, but he asked me to reassure Harvald and let the thane know that Jorunn's still running the kingdom."},
			["Find Oda Wolf-Sister"] =
				{appendText=". Her housecarl mentioned that she might be off to the east of Jorunn's Stand."},
			["Talk to Oda Wolf-Sister 1"] =
				{appendText=", standing underneath a grassy outcrop to the east of Jorunn's Stand.", stepTextKey="I didn't have to kill any wolves, so that should please Thane Oda. She has a strong attachment to the wolves. Now I should find her and speak to her about the war council."},
			["Talk to Oda Wolf-Sister 2"] =
				{appendText=", standing underneath a grassy outcrop to the east of Jorunn's Stand.", stepTextKey="I fought my way through the wolves to find Thane Oda. I should speak to her."},
			["Talk to Thane Jeggi"] =
				{appendText=". The mead-loving Nord would be hanging out near the inn, near the entrance of Jorunn's Stand."},
			["Collect Mead for Thane Jeggi"] =
				{appendText="\nBottles of this Nordic liquid gold can be found scattered near the tents of Jorunn's Stand. A crate was also gifted to the Dunmer - they might be willing to part with their supply."},
			["Deliver Mead to Thane Jeggi"] =
				{appendText=", the shirtless Nord at the inn near the entrance of Jorunn's Stand."},
			["Go to the War Council"] =
				{appendText=", gathering at the northern end of the Dunmer camp in Jorunn's Stand."},
			["Observe the War Council"] =
				{appendText=" at the northern end of the Dunmer camp in Jorunn's Stand."},
			["Talk to Jorunn the Skald-King 1"] =
				{appendText=". He's finally strong enough to be able to stand outside his tent at the northern end of the Dunmer camp in Jorunn's Stand.", stepTextKey="Now that the war council has concluded, the Skald-King wants to speak to me."},
			["Talk to Jorunn the Skald-King 2"] =
				{appendText=". He's finally strong enough to be able to stand outside his tent at the northern end of the Dunmer camp in Jorunn's Stand.", stepTextKey="Now that the war council has concluded, the Skald-King wants to speak to me."},
		},
		[GetQuestName(4087)] = { -- "Sneak Peak"					-- Mouch30
			["Talk to Scout Snowhunter"] =
				{appendText=", who guards the secret tunnel to Skuldafn. How he hasn't frozen solid waiting for you in these snowy hills is a mystery."},
		},
		[GetQuestName(4117)] = { -- "Songs of Sovngarde"			-- Mouch30
			["Enter Sovngarde"] =
				{appendText=". The portal awaits through the last door and up the final staircase."},
			["Defeat Fildgor Orcthane"] =
				{appendText=", looming over his sister's corpse in Sovngarde."},
			["Talk to Fildgor Orcthane"] =
				{appendText=", clutching his wounds by his sister's altar in Sovngarde."},
			["Talk to Nurnhilde 1"] =
				{appendText=". She stands above her own lifeless corpse, a look of contemplation on her face."},
			["Talk to Nurnhilde 2"] =
				{appendText=". She stands above her own lifeless corpse, a look of contemplation on her face."},
			["Return to Skuldafn's Peak"] =
				{appendText=". The freezing mists of Sovngarde tugs at your soul, but it is not your time yet. There is more work to be done."},
			["Talk to Jorunn the Skald-King"] =
				{appendText=", standing on the northernmost platform of Skuldafn."},
			["Witness the Great Moot"] =
				{appendText=" taking place on the northernmost platform of Skuldafn."},
			["Talk to Prince Irnskar 1"] =
				{appendText=" atop the eastern gate. He will be pleased to hear that the threat of Fildgor is over.", stepTextKey="The Ebonheart Pact is sealed. High-King Jorunn asked me to return to Jorunn's Stand and let Prince Irnskar know what happened here."},
			["Witness Fildgor's Execution"] =
				{appendText=" on the northernmost platform of Skuldafn. Jorunn must spill his brother's blood for the good of Skyrim."},
			["Talk to Prince Irnskar 2"] =
				{appendText=" atop the eastern gate. He will be pleased to hear that the threat of Fildgor is over.", stepTextKey="The Ebonheart Pact is sealed. High-King Jorunn asked me to return to Jorunn's Stand and let Prince Irnskar know what happened here."},
			["Talk to Prince Irnskar 3"] =
				{appendText=" atop the eastern gate. He will be pleased to hear that the threat of Fildgor is over."},
		},
		[GetQuestName(4116)] = { -- "Snow and Flame"				-- Mouch30
			["Enter the Hidden Tunnel"] =
				{appendText=" located in the snowy hills, just northeast of Jorunn's Stand."},
			["Navigate the Hidden Tunnel"] =
				{appendText=" to the northeast of Jorunn's Stand. Giant icicles hang over your head, and the faint stench of old burials linger in the air."},
			["Exit the Hidden Tunnel"] =
				{appendText=" to the northeast of Jorunn's Stand. A large, iron door greets you, intricately carved with a dragon's fearsome visage."},
			["Talk to Thane Mera Stormcloak"] =
				{appendText=" in the center of the shrine to get your next orders."},
			["Burn the Weapons Stockpile"] =
				{appendText=", a covered cart on a ledge overlooking the southwestern waterfall and lake."},
			["Burn the Food Stockpile"] =
				{appendText=", laden with sacks of grain and salted meat. This cart is stashed along the southern path of the ruin."},
			["Burn the Mead Stockpile"] =
				{appendText=", arguably the most important supply of all. The Stormfists keep the cart close to the east near the tombs."},
			["Light the Signal Fire"] =
				{appendText=" to the west of the Skuldafn tombs."},
			["Enter the Skuldafn Tombs"] =
				{appendText=". The assault must begin now!"},
			["Talk to Queen Nurnhilde"] =
				{appendText=", just inside the tombs. Her usual regality is tarnished by her wounded aura."},
		},


-- 		=========================================================================
--		  Eastmarch Side
-- 		=========================================================================
		[GetQuestName(4037)] = { -- "A Brother's Revenge"			-- Rosque
			["Defeat Kazok gro-Nogremor"] =
				{appendText=" behind the barn of Voljar Meadery."},
			["Talk to Yraldar by the Barn"] =
				{appendText=" at Voljar Meadery."},
			["Stick Kazok's Head on a Pike"] =
				{appendText=" in front of the gates of Voljar Meadery."},
			["Talk to Yraldar Snowpeak"] =
				{appendText=" in front of the gates of Voljar Meadery."},
		},
		[GetQuestName(4043)] = { -- "Collector of Pelts"			-- Chaos
			["Collect Wolf Pelts"] =
				{appendText=" around Lower Yorgrim. It is located north of Giant's Heart and east of Windhelm.\n\nThere are some giants lurking around the settlement. Be careful around them, for they might attack you."},
			["Talk to Hanmaer Furmender"] =
				{appendText=". She is staying at the fishing camp around Lower Yorgrim, southeast of Windhelm and directly north of Ragnthar. Lower Yorgrim is situated a little after the crossroad south of Windhelm, across the upper road to the east. Belofa Frostmoon is sitting in front of the fishing camp."},
		},
		[GetQuestName(4055)] = { -- "A Cure For Droi"				-- Chaos
			["Collect Kyne's Breath"] =
				{appendText=". The red flowers that grow around the great rune stones of Kynesgrove. There are usually two soldiers and a witch around those stones."},
			["Talk to Fresgil"] =
				{appendText=" in the keeper's house. It's the biggest building in the west side of town, close to a well."},
		},
		[GetQuestName(4583)] = { -- "Dear Cousins"					-- Chaos
			["Talk to Idirfa"] =
				{appendText="\n\nI should try looking for her around the merchant caravans at the northernmost part of town. I should also try looking near the river.\n\nThe diary does not mention anyone else, so she'll probably be alone."},
		},
		[GetQuestName(4056)] = { -- "For Kyne's Honor"				-- Chaos
			["Talk to Fresgil 1"] =
				{appendText=". She's behind the Abandoned House in Kynesgrove, beside a fallen tree, right in front of the loose window.\n\nIf I can't find her, I should try looking around the lake closest to Kynesgrove.", stepTextKey="I need to tell Fresgil and the remaining members of Captain Alhana's brigade what happened to their commander. I also need to tell them how the Keepers became Daedric witches."},
			["Kill Ormi"] =
				{appendText="\n\nThe shrine is east of Kynesgrove, right outside Icehammer's Vault, and it looks like a big brown circle on my map."},
			["Talk to Fresgil 2"] =
				{appendText="\n\nShe's at the Kynesgrove Wayshrine, north of Kynesgrove. I can get there by following the road back down to the town and going north, or by following the road straight south from Windhelm.", stepTextKey="I killed Ormi. Without her leadership, the rest of the corrupted Keepers will eventually slip away. I need to find Fresgil and tell her what happened."},
			["Find Sahun in Windhelm"] =
				{appendText=". Turn right after entering Windhelm and go up. Turn left at the stable."},
			["Confront Ormi at Kynesgrove"] =
				{appendText=". The shrine is east of Kynesgrove, right outside Icehammer's Vault, and it looks like a big brown circle on my map."},
			["Talk to Sahun"] =
				{appendText=" at the shrine, east of Kynesgrove, right outside Icehammer's Vault. It looks like a big brown circle on my map."},
			["Watch Sahun Pray"] =
				{appendText=""},
			["Talk to Keeper Ormi"] =
				{appendText=" at the shrine, east of Kynesgrove, right outside Icehammer's Vault. It looks like a big brown circle on my map."}, 
			["Talk to Captain Alhana 1"] =
				{appendText=" at the Keeper's House, straight down from the Kynesgrove wayshrine, northwest of the town's lake.\n\nThe house can easily be found on my map.", stepTextKey="Keeper Ormi has restored the soldiers. I should return to the Keeper's house and speak to Captain Alhana."},
			["Talk to Captain Alhana 2"] =
				{appendText="", stepTextKey="Keeper Ormi has restored the soldiers. I can find them in the Keeper's house."},
		},
		[GetQuestName(4034)] = { -- "A Friend in Mead"				-- Rosque
			["Talk to Haraldar 1"] =
				{appendText=".", stepTextKey="I should help restore Voljar's Meadery. Fens asked me to speak to his older brother, Haraldar. He's by the farmhouse."},
			["Enter the Meadery"] =
				{appendText="."},
			["Find Fragrant Herbs"] =
				{appendText=" inside Voljar Meadery."},
			["Find the Mead Recipe Book"] =
				{appendText=" inside Voljar Meadery."},
			["Retrieve Rare Spices from the Storeroom"] =
				{appendText=" inside Voljar Meadery. Given their rarity, they're likely in a small, decorated container."},
			["Talk to Haraldar 2"] =
				{appendText=" inside Voljar Meadery.", stepTextKey="The Snowpeak brothers now have access to the meadery. Once I turn over the recipe book and the ingredients, they should be able to start making mead again. I should talk to Haraldar and see what other help he needs."},
			["Talk to Roruld"] =
				{appendText=" inside Voljar Meadery."},
			["Collect Giant's Toe"] =
				{appendText=" by any means necessary."},
			["Give Giant's Toe to Roruld"] =
				{appendText=" inside Voljar Meadery."},
			["Collect Appleblossom Honey"] =
				{appendText="."},
			["Deliver Honey to Roruld Snowpeak"] =
				{appendText=" inside Voljar Meadery."},
			["Sample Roruld Snowpeak's Newest Mead"] =
				{appendText=" inside Voljar Meadery. He's set up a flagon next to the keg for tasting."},
			["Talk to Haraldar 3"] =
				{appendText=" inside Voljar Meadery.", stepTextKey="I woke up after sampling one of the new meads. Now that Voljar's Meadery is back in business, I hope Haraldar feels he honored his wife's memory. I should talk to him."},
		},
		[GetQuestName(4018)] = { -- "Giant Problems"				-- Chaos
			["Talk to Eiraki Frostwind 1"] =
				{appendText=" in Lower Yorgrim. The fishing camp is right in front of the river that surrounds Windhelm.", stepTextKey="I should find Eiraki Frostwind in the fishing camp east of the bridge to Windhelm and see what I can do to help the people of Lower Yorgrim."},
			["Talk to Skorvild Frostwind 1"] =
				{appendText=". His house neighboors the fishing camp, so I just need to turn right after exiting the camp.\n\nOn my map, his house is close to the main crossroad in the middle of town.", stepTextKey="Eiraki's borther Skorvild is gathering a force of warriors in a house north of the fishing camp. I should speak to him about how I can aid the village."},
			["Collect Supplies"] =
				{appendText="\n\nI should look for bags of Militia Supplies in the open around the northmost part of town."},
			["Rescue Villagers"] =
				{appendText="\n\nI should look in the three buildings at the northenmost part of town, and pay extra attention to any house with more than one floor."},
			["Talk to Skorvild"] =
				{appendText=". He's waiting for me in the Old Manor, right behind the fishing camp in front of the river that surrounds Windhelm where I first talked to Eiraki.\nOn my map, the Manor is the first building northeast of Ragnthar.\n"},
			["Talk to Eiraki"] =
				{appendText=" in Lower Yorgrim. The fishing camp is right in front of the river that surrounds Windhelm."},
			["Kill the Giant Leader"] =
				{appendText=" on the hill east of Lower Yorgrim.\n\n On my map, his camp is directly south of Giant's Heart."},
			["Wait for Skorvild"] =
				{appendText=" on the hill east of Lower Yorgrim, south of Giant's Heart."},
			["Talk to Skorvild Frostwind 2"] =
				{appendText=". He awaits you amidst three sizable boulders, right outside Lower Yorgrim. Direct your gaze south from Giant's Heart and to the east of the town, close to a charred hut or in the vicinity of a warehouse.", stepTextKey="Skorvild took some meat from the giant's leader and ran over to a stand of rocks. I should meet him there."},
			["Stop Skorvild"] =
				{appendText=".  Look for him in the first floor of the Old Manor, right behind the fishing camp in front of the river that surrounds Windhelm.\n\nOn my map, the Manor is the first building northeast of Ragnthar."},
			["Leave the Ritual Chamber"] =
				{appendText=""},
			["Talk to Eiraki Frostwind 2"] =
				{appendText=" in the Old Manor, right behind the fishing camp in front of the river that surrounds Windhelm.\n\nOn my map, the Manor is the first building northeast of Ragnthar.", stepTextKey="Eiraki Frostwind met me in the manor house. I should speak to her and tell her what happened."},
			["Burn the Giant Remains"] =
				{appendText=" on the campfire at the northmost part of town, near the houses where the villagers were."},
			["Talk to Eiraki Frostwind 3"] =
				{appendText=" in Lower Yorgrim. The fishing camp is right in front of the river that surrounds Windhelm.", stepTextKey="With the remains burned, the giants have calmed down. I should return to Eiraki at the fishing village and tell her what happened."},
		},
		[GetQuestName(4322)] = { -- "Lost Crown"					-- Chaos
			["Locate Lodorr's Tomb"] =
				{appendText=". The entrance is located on the upper floor of the main chamber, but it's only reachable from the south portion of the Hall of the Dead."},
			["Open Lodorr's Sarcophagus"] =
				{appendText=", reachable from the south portion of the Hall of the Dead."},
			["Kill Lodorr"] =
				{appendText=""},
			["Talk to Malana"] =
				{appendText=" near Loddor's tomb, at the upper floor of the main chamber."},
			["Defeat Ulfnir Ice-Blood and Search His Body for Lodorr's Crown"] =
				{appendText=" on the top level in the main chamber."},
			["Take Lodorr's Crown to Malana"] =
				{appendText=""},
			["Kill Malana"] =
				{appendText=" in the Ancient Tomb. The entrance is only accessible from the upper floor at the main chamber."},
			["Talk to Lodorr"] =
				{appendText=" in the Ancient Tomb. Access to the entrance is exclusively available from the top level of the primary room.."},
			["Recover Lodorr's Crown"] =
				{appendText=""},
		}, 
		[GetQuestName(4206)] = { -- "Nature's Accord"				-- Chaos
			["Find Imwyn's Sister"] =
				{appendText=". She's hiding near the Dragon Mound south of Windhelm, between the rock peaks close to a lonely tree."},
			["Find the Sigil of Nature's Accord"] =
				{appendText=" Near the main road west of Cragwallow and south of the lake of Kynesgrove. It's in a bag behind a pile of wood.\n\nThere is a forest spirit guiding you. If you see a bright sphere of blue light, try following it."},
			["Find Imwyn's Daughter in Windhelm"] =
				{appendText=" at the Cold-Moon Fine Steeds stable."},
			["Talk to Aerana"] =
				{appendText=" at the Cold-Moon Fine Steeds stable."},
		},
		[GetQuestName(4316)] = { -- "On a Dare"						-- Chaos
			["Find the Lost Celebrators"] =
				{appendText=" in the early parts of the catacombs, before the first half of the main chamber."},
			["Talk to Nivene Orthil"] =
				{appendText=""},
		},
		[GetQuestName(4149)] = { -- "Party Planning"				-- Rosque
			["Collect Pickled Fish from Lower Yorgrim"] =
				{appendText=". A fisherman on the docks would likely know more about the shipment's fate. Rigurt in Windhelm may be able to provide directions."},
			["Collect Mead from Voljar's Meadery"] =
				{appendText=". Someone inside the Voljar Farmhouse might know more about the shipment's fate. Rigurt in Windhelm may be able to provide directions."},
			["Recover Dunmer Cultural Garb"] =
				{appendText=", wherever it may be."},
			["Bring Party Items to Rigurt"] =
				{appendText=" near the gates of Windhelm."},
			["Meet Rigurt Near the Docks"] =
				{appendText=" of Windhelm."},
			["Greet the Pact Dignitaries"] =
				{appendText=" near the Docks of Windhelm."},
			["Talk to Rigurt"] =
				{appendText=" near the Docks of Windhelm."},
		},
		[GetQuestName(4030)] = { -- "Shrine of Corruption"			-- Chaos
			["Find the Missing Brigade"] =
				{appendText=""},
			["Talk to the Soldiers Through the Door"] =
				{appendText=". Look for the Keeper's Home at the western part of town, near a well."},
			["Prove You Are Not a Witch"] =
				{appendText=". Get three Amulets of Kyne from the enemy soldiers at Kynesgrove."},
			["Bring Amulets to the Safe House"] =
				{appendText=". It's the biggest building to the western part of town, near a well."},
			["Talk to the Soldiers in the House"] =
				{appendText=" in the building at the western part of town, in the proximity of a well."},
			["Search for Clues to the Keepers' Whereabouts"] =
				{appendText=".\n\nFind the key for the keeper's dresser on enemy soldiers in Kynesgrove. The dresser is in their home, at the western part of town, close to a well.\n\nThe Hymn to Kyne can be found on enemy soldiers in Kynesgrove.\n\nSearch the witch atop a rock, west of the town's lake."},
			["Talk to Captain Alhana 1"] =
				{appendText=" at the Keeper's Home at the western part of town, near a well.", stepTextKey="I gathered the clues to the Keepers' fate: a hymn book, a soldier's journal, and the strange ramblings of the witch Leifnar. I should return to Captain Alhana and tell her what I found."},
			["Enter the Locked House"] =
				{appendText=" at the eastern side of town. There is also a bag placed by the tree in front of the house that might be worth looking into."},
			["Search the House for Clues"] =
				{appendText=""},
			["Talk to Captain Alhana 2"] =
				{appendText="", stepTextKey="Alhana followed me into the house. I should let her know what I discovered."},
		},
		[GetQuestName(4138)] = { -- "Alchemical Analysis"			-- Tahir
			["Find the Alchemist Shop in Fort Amol"] =
				{appendText=". That is marked on my map."},
			["Ask Aleeto to Examine the Ore"] =
				{appendText=". I should tell her of it's qualities too - maybe she'll know what this metal is."},
			["Get the Varla Stone Tincture"] =
				{appendText=". It could be stored somewhere, maybe on a table or shelf."},
			["Give the Tincture to Aleeto"] =
				{appendText="."},
			["Find Ovuld's Study of Metallurgic Anomalies"] =
				{appendText=". On an island near the riverbank."},
			["Return Ovuld's Book to Aleeto"] =
				{appendText=", back at the Uncanny Alembic."},
			["Observe the Experiment"] =
				{appendText=". Aleeto seems like she knows what she's doing. One could suppose."},
			["Talk to Aleeto"] =
				{appendText=". To assess her current condition."},
		},
		[GetQuestName(4204)] = { -- "Bath Time"						-- Tahir
			["Find Grida Meadmoon"] =
				{appendText=", east of Fort Amol. I should stick to the road to see if I can find the town."},
			["Read Grida's Note"] =
				{appendText=" in Darkwater Crossing. It might have an explanation as to what happened here."},
			["Collect Mudcrab Claws"] =
				{appendText="\nI can find mudcrab claws by killing mudcrabs, usually found around moist regions of Tamriel. The river may be a good place to look."},
			["Collect Troll Fat"] =
				{appendText="\nI can find troll fat by killing trolls and collecting their fat. Trolls are quite large and common in Eastmarch, it's hard to miss them. They can't be too far."},
			["Collect Daril"] =
				{appendText=". The note might mention something about where to find this. The Argonian encampment must be well-hidden if it hasn't been thrashed by trolls yet, it can't be out in the open."},
			["Grind Ingredients at the Mill"] =
				{appendText=". It should be it should be close by to the wreckage of Darkwater, up on the hill."},
			["Talk to Dralof Waterwalker 1"] =
				{appendText=". He should be where I met him, south of the Ratmaster's Prowl.", stepTextKey="As I ground the bath salts ingredients, Grida appeared. She was some kind of undead creature. I wonder if the bath salts had anything to do with her condition? I should speak to Dralof about this."},
			["Talk to Dralof Waterwalker 2"] =
				{appendText=", south of the Ratmaster's Prowl.", stepTextKey="I decided to give Dralof the bath salts. He's a big Nord and he knows the risks."},
		   ["Talk to Frera Dagger-Lost"] =
				{appendText=", south of the Ratmaster's Prowl."},
		},
		[GetQuestName(4218)] = { -- "Best of the Best"				-- Tahir
			["Get the Hunting Bow"] =
				{appendText=". It should be close to the riverbed on a rock, near the north riverbank of Fort Amol."},
			["Talk to Steady-Hand 1"] =
				{appendText=". If I'm up for the challenge, then he will allow me to begin.", stepTextKey="I can talk to Steady-Hand to start the competition, or I can speak to Vurila for some advice before I begin."},
			["Talk to Vurila"] =
				{appendText=". Maybe she has some advice I could use for the competition."},
			["Talk to Steady-Hand 2"] =
				{appendText=" to begin the contest. He should be by the riverbank north of Fort Amol.", stepTextKey="Vurila gave me some fiery arrows. I should talk to Steady-Hand to start the contest."},
			["Use the Hunting Bow to Kill Rabbits"] =
				{appendText=". I can find them in the area just north of the river."},
			["Kill Golden Jack with the Hunting Bow"] =
				{appendText=". He's a slippery creature from what I've heard. I can find him north of the river as well."},
			["Talk to Steady-Hand 3"] =
				{appendText=" by the riverbank north of Fort Amol.", stepTextKey="I won the contest! I should talk to Steady-Hand to collect my reward."},
			["Talk to Steady-Hand 4"] =
				{appendText=" by the riverbank north of Fort Amol.", stepTextKey="Time ran out. Maybe if I speak to Steady-Hand I can try again."},
		},
		[GetQuestName(4118)] = { -- "Dark Deeds"					-- Tahir
			["Find Jakild"] =
				{appendText=" in her cabin north of the Bonestrewn Crest."},
			["Find Agnedir"] =
				{appendText=" in his cabin along the path east of the Bonestrewn Crest."},
			["Find Kerthor"] =
				{appendText=" in the cabin northwest of the Wittestadr wayshrine."},
			["Talk to Selgaard 1"] =
				{appendText=". I can find him outside of Kerthor's cabin, northwest of the Wittestadr wayshrine.", stepTextKey="I checked the houses along Bonestrewn Crest. I should tell Selgaard that only his wife, Jakild, survived the draugr assault."},
			["Find the Mysterious Travelers"] =
				{appendText=". I think I can find them within the Bonestrew Barrow crypts."},
			["Enter Bonestrewn Barrow"] =
				{appendText=""},
			["Find the Covenant Expedition"] =
				{appendText=". I should navigate the crypt and look for any traces they may have left behind."},
			["Read Henri's Journal"] =
				{appendText=", on the floor in the Bonestrewn Barrow. It lies among the bodies of fallen Covenant soldiers."},
			["Find the Covenant Camp"] =
				{appendText=" deeper into the barrow. They would need a large area to set up a camp..."},
			["Read Ophelia's Journal"] =
				{appendText=", on a table within the Covenant camp in the Bonestrewn Barrow."},
			["Defeat Ophelia Ceirans"] =
				{appendText=", in the Covenant camp located within the Bonestrewn Barrow. She appears to have been suddenly reanimated by a ritual."},
			["Use Ophelia's Key"] =
				{appendText=". I should venture deeper into the Bonestrewn Barrow to uncover what transpired here."},
			["Talk to Owen Pavelle"] =
				{appendText=". He's locked in a cage within the Bonestrewn Barrow."},
			["Throw the Switch"] =
				{appendText=". Owen said the left switch releases him, but he repeatedly warned me to not flip the right switch; it sounds like it does something grim."},
			["Enter the Final Chamber"] =
				{appendText=", deep in the Bonestrewn Barrow. I need to put an end to this necromancer's interference with the dead."},
			["Defeat Sir Valcent Tailies"] =
				{appendText=", located in the final chamber of the Bonestrewn Barrow."},
			["Leave Bonestrewn Barrow"] =
				{appendText=" via the west exit. I've put an end to the necromancer's ploys."},
			["Talk to Selgaard 2"] =
				{appendText=". He should be waiting for me north of the Bonestrewn Crest, inside Jakild's cabin.", stepTextKey="The exit out of Bonestrewn Barrow led me back to Bonestrewn Crest. I should find Selgaard and his wife at their cabin and tell them what happened."},
		},
		[GetQuestName(4141)] = { -- "Do Kill the Messenger"			-- Tahir
			["Intercept the Courier"] =
				{appendText=". I should be able to find him by the river surrounding Fort Amol.\n\nThe courier works for the Stormfists, he might have an escort. I should keep an eye out for any Stormfist soldiers."},
			["Talk to Tridi 1"] =
				{appendText=". She should be waiting for me by the Stormfist camp I attacked south of the Fort Amol wayshrine.", stepTextKey="I located the courier and intercepted the letter she carried. Tridi is nearby. I should give the letter to her."},
			["Talk to Tridi 2"] =
				{appendText=". She is expected to be waiting for me near the Stormfist camp I assaulted, located to the south of the Fort Amol wayshrine.", stepTextKey="Osanne's letter to Fildgor will be destroyed. Hopefully, the miners of Lost Knife Cave won't have any more trouble with Fildgor and the Stormfists."},
		},
		[GetQuestName(4126)] = { -- "Labor Dispute"					-- Tahir
			["Collect Stormfist Weapons"] =
				{appendText="\nIf I defeat Stormfist soldiers, I can take their weapons."},
			["Find Tridi"] =
				{appendText=". She must be somewhere in the mine."},
			["Find Nedrek"] =
				{appendText=". He too must be in the mine — maybe Eitaki knows where he is."},
			["Talk to Jomund"] =
				{appendText=". He should be close by to where I found Nedrek, further within the mine."},
		},
		[GetQuestName(4128)] = { -- "Mystery Metal"					-- Tahir
			["Find Ore Sample"] =
				{appendText=". It should be in the chamber deeper into the Lost Knife mine."},
			["Collect Research Notes"] =
				{appendText=". I should have a description of where it is in my journal."},
			["Talk to Jomund 1"] =
				{appendText=" I should leave the northwestern chamber through the south exit, He's waiting for you for me there", stepTextKey="I recovered the hidden research notes and retrieved the ore sample from Magister Osanne. I should find Jomund and let him know what happened."},
			["Gather More Ore Samples"] =
				{appendText="\nI should beware of any trolls ahead in the Lost Knife mine."},
			["Exit the Mine"] =
				{appendText=" and go to the camp at Lost Knife."},
			["Talk to Jomund 2"] =
				{appendText=". He should be near one of the lodges.\n", stepTextKey="The weapons I provided allowed the miners to drive off the Orcthane's troops. Lost Knife Cave Mine is once again free. I should talk to Jomund and hand over the ore samples."},
		},
		[GetQuestName(4584)] = { -- "Pilfered Urn"					-- Tahir
			["Talk to Agvar"] =
				{appendText=". I can find him by the northern tip of the Windhelm docks fishing by the river."},
		},
		[GetQuestName(4099)] = { -- "A Dying Wish"					-- Rosque
			["Find Lothgar's Sword"] =
				{appendText=" inside Cragwallow Cave, in a camp hidden from the view of a shaft of light by an underground tree."},
			["Find Lothgar's Shield"] =
				{appendText=" behind a closed gate in Cragwallow Cave."},
			["Bring Items to Lothgar"] =
				{appendText=", somewhere on the road between Cragwallow and Cragwallow Cave."},
			["Return to Lothgar"] =
				{appendText=", somewhere on the road between Cragwallow and Cragwallow Cave, watched over by a loving hound."},
		},
		[GetQuestName(4104)] = { -- "In Search of Kireth Vanos"		-- Rosque
			["Enter Mzulft"] =
				{appendText="."},
			["Find Kireth Vanos"] =
				{appendText=" inside Mzulft."},
			["Talk to Kireth Vanos"] =
				{appendText=" deep within the Mzulft ruins."},
		},
		[GetQuestName(4105)] = { -- "Kireth's Amazing Plan"			-- Rosque
			["Enter the Ice Tunnels"] =
				{appendText="."},
			["Help Kireth Find the Key"] =
				{appendText=" beneath the snow inside the Ice Tunnels, deep in the eastern end of Mzulft. She may have to do some searching, and will need protection while she does so."},
			["Go To the Vault"] =
				{appendText=". Kireth may know where it might be located."},
			["Read the Researcher's Journal"] =
				{appendText=" at the eastern edge of the Ice Tunnels in Mzulft."},
			["Find an Uncharged Dwemer Orb"] =
				{appendText=" at the eastern edge of the Ice Tunnels in Mzulft."},
			["Listen to Kireth and Raynor"] =
				{appendText=" at the eastern edge of the Ice Tunnels in Mzulft."},
			["Support Kireth"] =
				{appendText=" at the eastern edge of the Ice Tunnels in Mzulft. She wants a map to Dwemer ruins, so she and her brother can explore to their heart's content."},
			["Support Raynor"] =
				{appendText=" at the eastern edge of the Ice Tunnels in Mzulft. He wants ancient knowledge of Dwemer soul gems, so he and his sister will be taken seriously by academia."},
			["Talk to Kireth Vanos"] =
				{appendText=" at the eastern edge of the Ice Tunnels in Mzulft."},
			["Talk to Raynor Vanos"] =
				{appendText=" at the eastern edge of the Ice Tunnels in Mzulft."},
		},
		[GetQuestName(4588)] = { -- "Land Dispute"					-- Rosque
			["Investigate the Logging Cabin"] =
				{appendText=" on the west end of Thulvald's Logging Camp."},
			["Talk to Eginir"] =
				{appendText=" inside the logging cabin on the west end of Thulvald's Logging Camp."},
			["Investigate the Logging Chief's Lodge"] =
				{appendText=" at Thulvald's Logging Camp."},
			["Talk to Jafelma"] =
				{appendText=" at Thulvald's Logging Camp."},
			["Defeat the Spriggan Matron"] =
				{appendText=". Jafelma said that the spriggan matron was at the pool south of Thulvald's Logging Camp."},
			["Talk to Thulvald"] =
				{appendText=" near the Logging Camp Wayshrine."},
		},
		[GetQuestName(4096)] = { -- "Merriment and Mystery"			-- Rosque
			["Talk to Berj Stoneheart"] =
				{appendText=". Frirvid said that he was just up the road, in the middle of Cragwallow."},
			["Choose One of the Cooks"] =
				{appendText=", up near Cragwallow's Mead Hall."},
			["Lure a Goat to Heggvir"] =
				{appendText=". There should be some goats far up on the mountains, to the northeast of Cragwallow, that should suffice. They are known for their improbable climbing skills."},
			["Talk to Heggvir"] =
				{appendText=" in Cragwallow, near the Mead Hall."},
			["Find Ralduf at the Storehouse"] =
				{appendText="."},
			["Find the Wolf with the Key"] =
				{appendText=" north of Cragwallow. It is unfortunate for the wolves, but there is no way to pick the lock to the royal work crew's Storehouse."},
			["Get Mead for the Party"] =
				{appendText=" from the Storehouse."},
			["Deliver Mead to Berj"] =
				{appendText=" in the Mead Hall."},
			["Ask the Bard to Play"] =
				{appendText=". Berj said that he was upstairs in the Mead Hall."},
			["Listen to the Bard"] =
				{appendText=" upstairs in the Mead Hall."},
			["Talk to Arvild Gray-Sky 1"] =
				{appendText=" upstairs in the Mead Hall.", stepTextKey="I seem to have blacked out. I need to find out what happened."},
			["Talk to the Survivors"] =
				{appendText=" inside the Mead Hall."},
			["Talk to Arvild Gray-Sky 2"] =
				{appendText=" outside the Mead Hall in Cragwallow.", stepTextKey="No one seems to have a clear memory of what happened, but they all heard the bard playing before things got bad. The bard, however, is missing."},
			["Search Cragwallow for the Missing Bard"] =
				{appendText=". With Arvild Gray-Sky checking inner Cragwallow, it may be of benefit to search the outskirts."},
			["Talk to Vestrek Raven-Eye"] =
				{appendText=" east of Cragwallow."},
			["Enter the Cave"] =
				{appendText=" east of Cragwallow."},
			["Find Valding"] =
				{appendText=" inside Cragwallow Cave."},
			["Get the Key from the Riekling Chieftain"] =
				{appendText=" inside Cragwallow Cave."},
			["Decide Valding's Fate"] =
				{appendText=" inside Cragwallow Cave."},
			["Exit the Cave"] =
				{appendText="."},
			["Talk to Vestrek"] =
				{appendText=" outside Cragwallow Cave."},
			["Get Bear Steaks"] =
				{appendText=" from the large single spire behind Cragwallow's Storehouse."},
			["Talk to Kalogar"] =
				{appendText=" in Cragwallow, near the Mead Hall."},
			["Unlock the Cage"] =
				{appendText=" inside Cragwallow Cave."},
			["Lead Valding to the Exit"] =
				{appendText=" of Cragwallow Cave."},
			["Talk to Valding 1"] =
				{appendText=" outside Cragwallow Cave.", stepTextKey="I know Valding didn't intend for anyone to get hurt, but he has to take responsibility for what happened. I should talk to him to make sure he understands that."},
			["Talk to Valding 2"] =
				{appendText=" outside Cragwallow Cave.", stepTextKey="Valding the Bard turned out to be a common thief. But he promised to return to Cragwallow and explain what happened. The royal workers will decide his fate. At least the enchanted lute was destroyed."},
		},
		[GetQuestName(4585)] = { -- "Relative Matters"				-- Rosque
			["Talk to Hojard"] =
				{appendText=" by the eastern gate in Jorunn's Stand."},
		},
		[GetQuestName(4070)] = { -- "Security Details"				-- Rosque
			["Light the Torch"] =
				{appendText=" in the campfire near Ula-Reen at Jorunn's Stand."},
			["Light the South and East Gate Watchfires"] =
				{appendText="\nThe watchfires are located just past the gates, in the center of the surrounding wilderness, where they can foil the stealth of incoming troops. They appear as firewood piled on slabs of stone."},
			["Talk to Ula-Reen 1"] =
				{appendText=" in Jorunn's Stand.", stepTextKey="I should let Ula-Reen know that the watchfires are lit."},
			["Kill Spymaster Ramorgol and Recover Orders"] =
				{appendText=" in the wilderness southeast of Jorunn's Stand. The spymaster likely has his own small contingent of supplies there."},
			["Talk to Scout Speaks-with-Blades"] =
				{appendText=" in the wilderness southeast of Jorunn's Stand."},
			["Kill Shaman Moramat and Recover Orders"] =
				{appendText=", southeast of Jorunn's Stand. The shaman likely has her own small contingent of supplies there."},
			["Talk to Ula-Reen 2"] =
				{appendText=" in Jorunn's Stand.", stepTextKey="I eliminated the Orcthane's spymaster and shaman and retrieved their orders. I should report back to Captain Ula-Reen and let her know her security issues have been dealt with."},
		},
		[GetQuestName(4212)] = { -- "Torn Asunder"					-- Rosque
			["Find the First Daughter"] =
				{appendText=". Hadmal's torn journal page is lying at the gravestone on the hill south of the wayshrine of Jorunn's Stand."},
			["Find the Second Daughter"] =
				{appendText=". Hadmal's torn journal page is lying at the gravestone near the Hall of the Dead in Windhelm."},
			["Find the Third Daughter"] =
				{appendText=". Hadmal's torn journal page is lying on the rock behind the curved stone wall outside of Bonestrewn Crest."},
			["Bring the Skulls to Sonya Lastblood"] =
				{appendText=" at the grave on the hill south of Jorunn's Stand Wayshrine."},
			["Find Hadmal Lastblood"] =
				{appendText=". His letter is on the ground at the grave on the hill south of Jorunn's Stand Wayshrine."},
			["Stop Sonya's Ritual"] =
				{appendText=" at the ruins on the far southeastern edge of Eastmarch."},
			["Talk to Hadmal Lastblood"] =
				{appendText=" in Jorunn's Stand. He was last seen on the lower level, near the Argonian known for prolific soup cooking."},
			["Open Hadmal's Chest"] =
				{appendText=" on the lower level of Jorunn's Stand."},
		},
		[GetQuestName(4095)] = { -- "The Siege of Cradlecrush"		-- Rosque
			["Talk to the Giant"] =
				{appendText=" next to the natural wall at the camp near Cradlecrush Wayshrine."},
			["Get Inside the Fort"] =
				{appendText="."},
			["Free the Mammoths"] =
				{appendText=""},
			["Use the Gate Switches"] =
				{appendText=""},
			["Go to Cradlecrush Arena"] =
				{appendText=", the towering circular structure in the center of Cradlecrush."},
			["Talk to Aspera Giant-Friend 1"] =
				{appendText=" outside the arena in the middle of Cradlecrush.", stepTextKey="Somehow, Aspera reached the arena before I did. She wants to speak with me."},
			["Enter Cradlecrush Arena"] =
				{appendText=", the towering circular structure at the center of Cradlecrush sacred to Orcs that worship Malacath."},
			["Blow the Horn to Challenge Lob"] =
				{appendText=" inside Cradlecrush Arena at the center of Cradlecrush."},
			["Survive the Arena Challenge"] =
				{appendText=" inside Cradlecrush Arena."},
			["Exit Cradlecrush Arena"] =
				{appendText="."},
			["Talk to Aspera Giant-Friend 2"] =
				{appendText=" outside Cradlecrush Arena at the center of Cradlecrush.", stepTextKey="Aspera Giant-Friend is waiting for me outside the arena. I should talk to her."},
		},
		[GetQuestName(4086)] = { -- "Strange Allies"				-- Rosque
			["Use the Horn"] =
				{appendText=" at the cave east of the frozen Dwemer ruin of Frostvault."},
			["Collect Stormfist Scout Orders"] =
				{appendText="\nThe Stormfist scouts should be north of Cradlecrush, lying in wait atop the trees tall enough to look over the walls."},
			["Talk to Aspera Giant-Friend"] =
				{appendText=". The camp's diagonally-stacked logs burn in view of the Cradlecrush Wayshrine."},
		},


-- 		=========================================================================
--		  Rift Main
-- 		=========================================================================
		[GetQuestName(3919)] = { -- "Beneath the Stone"				-- Cyberjanet
			["Talk to Vigrod Wraithbane"] =
				{appendText="\nFallowstone Hall is to the north of the wayshrine of the same name, and Shor's Stone is to the east. Follow the main road until you find wooden gates and a barricade.\n\nYou see a well near some construction work as soon as you pass through, and the crafters Arela and Rami. Continue on past the house and inn, then look around for Vigrod Wraithbane behind the Guild Trader, among Pact Soldiers."},
			["Talk to Ree-Zish 1"] =
				{appendText=", standing near the well at the entrance to Shor's Stone. They seem to be supervising building work around the entrance to the mine.", stepTextKey="Companion leader Vigrod Wraithbane is offering aid to the Pact at Shor's Stone. He's asked me to work with the Argonian, Ree-Zish to break into the Shor's Stone mine."},
			["Destroy Corpses and Collect Magicka"] =
				{appendText="\nThe Boneshaper Clansmen use some kind of tethering ritual to imbue the corpses. They're easily spotted by the blue light formed in the process. Just kill the Clansmen to destroy the corpses and collect the magicka that Zee-Rish needs."},
			["Talk to Ree-Zish 2"] =
				{appendText=" who is waiting for you with her companions at the Shor's Stone mine entrance, near the well, opposite the crafters.", stepTextKey="I've collected the corrupted magicka into the Argonian talisman, as Ree-Zish requested. I need to get back to her."},
			["Imbue Effigies and Enter Mine"] =
				{appendText="\nThe effigies are on either side of the wooden archway at the entrance to Shor's Stone mine, near the well. Once imbued, the door to the mine should open easily.\n"},
			["Enter the Mine"] =
				{appendText=" through the door you created into Shor's Stone mine at the entrance to the township. There are complex wooden structures around it."},
			["Talk to Foreman Gandis"] =
				{appendText=" who is hiding in Shor's Stone mine. The mine's entrance is just near the well. Follow the path, you'll see Foreman Gandis easily where it splits."},
			["Find Foreman Gandis 1"] =
				{appendText=", crouching behind crates and beams where the path into the mine splits. \n\nThe mine entrance dominates Shor's Stone, easily visible from the well.", stepTextKey="I need to find Foreman Gandis. He may know what's going on down here."},
			["Find Foreman Gandis 2"] =
				{appendText="who is hiding inside the Shor's Stone mine, just where the path splits. The mine's entrance is near the well.", stepTextKey="I need to find Foreman Gandis. He may know what's going on down here."},
			["Find Foreman Gandis 3"] =
				{appendText=", hiding inside Shor's Stone mine, just where the path splits. The mine's entrance is near the well.", stepTextKey="I need to find Foreman Gandis. He may know what's going on down here."},
		},
		[GetQuestName(3920)] = { -- "Unearthed"						-- Cyberjanet
			["Find Foreman Gandis"] =
				{appendText=" inside Shor's Stone Mine. He is crouched in the shadows near some crates at the point where the path splits.\n\nThe mine entrance is near the well just past the barricades on the main road leading into Shor's Stone."},
			["Find Relics"] =
				{appendText="\nThey are deeper in the tunnels in Shor's Stone Mine.\n\nOne is in an iron box on a wooden platform in a tunnel off a large room with a horned totem at its entrance. Bear right to find the tunnel. If Gandis gave you a secret door key, it will open the mine entrance below the platform to get you back to the horned totem quickly.\n\nIf not, walk back to the horned totem at the entrance of the large room. Then pass between the two wooden structures. There is another tunnel just after them. Hug the left wall, pass what looks like a frozen door, and continue until you find another iron box next to a horned totem."},
			["Place Fireheart's Medallion"] =
				{appendText=" on the skeleton in a praying stance next to the Tomb of the Companions. The door is hidden by what looks like a frozen charm. You will have passed it when looking for the relic using the leftmost tunnel from the large room with the horned totem at the entrance."},
			["Place Darkhammer's Amulet"] =
				{appendText=" on the other skeleton in a praying stance at the door. You will have seen it when searching for the relics."},
			["Explore the Tomb"] =
				{appendText=" while the two ghosts keep guard at the door, in the leftmost tunnel where you used the relics. The door leads into another tunnel and then to the door of Sinmur's Tomb."},
			["Examine the Altar"] =
				{appendText=" in Sinmur's Tomb. It is after the tunnel leading from the door to the Companions tomb.\n\nUsing the relics on the skeletons at the door to the Tomb of the Companions released two ghosts, who now stand guard while you explore."},
			["Find Vigrod Outside the Mine"] =
				{appendText=". He is just near the well at the entrance."},
			["Warn Vigrod 1"] =
				{appendText=" waiting at the mine entrance near the well.", stepTextKey="I need to report in to Vigrod. He must be told about the Reachmen's dark ritual."},
			["Warn Vigrod 2"] =
				{appendText=", standing near the well near the entrance to the mine.", stepTextKey="I need to report in to Vigrod. He must be told about the Reachmen's dark ritual."},
		},
		[GetQuestName(3974)] = { -- "Storming the Hall"				-- Cyberjanet
			["Talk to Vigrod Wraithbane 1"] =
				{appendText=", waiting at the well near the Shor's Stone mine entrance.", stepTextKey="Vigrod heard that Fallowstone Hall has been overrun and he's asked for my help. I can follow him or meet him there."},
			["Follow Vigrod Wraithbane"] =
				{appendText=" as he runs along the main road, stopping occasionally for news from his informants."},
			["Talk to Vigrod Wraithbane 2"] =
				{appendText=" on the path leading from the Fallowstone Hall wayshrine up to the hall.", stepTextKey="I've made my way to Fallowstone Hall. I should report in to Vigrod Wraithbane."},
			["Rally Survivors"] =
				{appendText=".\n\nVigrod said the survivors retreated to the shrines. These are cobbled platforms with a symbolic stone arch featuring a carving of a door."},
			["Talk to Vigrod Wraithbane 3"] =
				{appendText=" waiting with the survivors at the lamppost outside the hall. It's a stone and wood building at the end of the path leading from the wayshrine.", stepTextKey="I rallied the survivors I found. I need to meet with Vigrod Wraithbane at the Hall."},
			["Talk to Sage Tirora"] =
				{appendText=" after using the ashes at the correct brazier. The braziers are on top of small stone pedestals near small arched stone crypts with wooden doors."},
			["Kill Chieftain Frostfang"] =
				{appendText=" in the basement of Fallowstone Hall. Use the trapdoor in the dining room to reach him. Follow Vigrod."},
			["Meet Vigrod Wraithbane at the Vault Entrance"] =
				{appendText=" in the basement of Fallowstone Hall. The trapdoor in the dining room took you down to where you killed Chieftain Frostfang, right in front of the door leading to the entrance to the vault."},
			["Talk to Vigrod Wraithbane 4"] =
				{appendText=" in the basement of Fallowstone Hall. You followed him through the trapdoor in the dining room, and killed Chieftain Frostfang in front of the door to the vault entrance.", stepTextKey="I should ask Vigrod Wraithbane what's next."},
			["Search the Hall of Heroes"] =
				{appendText=" in the basement of Fallowstone Hall. You found and killed Chieftain Frostfang when you followed Vigrod through the trapdoor. Now follow the corridor from the Vault Entrance to the Hall of Heroes."},
			["Talk to Vigrod Wraithbane 5"] =
				{appendText=", waiting outside Fallowstone Hall. The far exit from the Hall of Heroes leads outside.", stepTextKey="I need to let Vigrod Wraithbane know that the ancient axe Wuuthrad is missing."},
			["Talk to Vigrod Wraithbane 6"] =
				{appendText=" outside Fallowstone Hall.", stepTextKey="I need to tell Vigrod Wraithbane that Wuuthrad is missing."},
			["Talk to Vigrod Wraithbane 7"] =
				{appendText=" outside Fallowstone Hall.", stepTextKey="I need to tell Vigrod Wraithbane that Wuuthrad is missing."},
		},
		[GetQuestName(3977)] = { -- "To Vernim Woods"				-- Cyberjanet
			["Travel to Vernim Woods"] =
				{appendText=", west of Fallowstone Hall, just after the Northwind Mine wayshrine. Bermund awaits your arrival on the path."},
		},
		[GetQuestName(3928)] = { -- "Dangerous Union"				-- Cyberjanet
			["Talk to Dajaheel 1"] =
				{appendText=" in a tented area in Vernim Woods, just off the road, west of the Northwind Mine wayshrine.", stepTextKey="I've been asked to talk to Dajaheel at the Pact's forward encampment."},
			["Use Dagger on Dead Cultist"] =
				{appendText=". You'll have to kill one or two, and there are many just beyond the tented Pact camp just west of the Northwind Mine wayshrine."},
			["Talk to Belron"] =
				{appendText=" in the camp near the Northwind Mine wayshrine, near a tall rock."},
			["Place Beating Heart into Slain Cultist"] =
				{appendText=" member in the rocky enclosure next to Lieutenant Belron. The rocks protect this little ritual from the view of the soldiers in the tented camp just to the west of the Northwind Mine wayshrine."},
			["Interrogate Cultist"] =
				{appendText=", newly risen in the rocky enclosure next to Lieutenant Belron. The tented camp near the Northwind Mine wayshrine is just nearby."},
			["Talk to Dajaheel 2"] =
				{appendText=" in a tented area in the Vernim Woods camp near the Northwind Mine wayshrine.", stepTextKey="The Worm Cultists are transforming the Reachmen as a part of an agreement between Stral and the head of the Worm Cult. I must report back to Dajaheel at once."},
			["Use Globe on Cultist Then Kill Them"] =
				{appendText=". Follow the pathway and use the globe as soon as they attack you."},
			["Give Globe to Belron"] =
				{appendText=", waiting next to an obelisk in Vernim Woods by the Northwind Mine wayshrine."},
			["Talk to the Memory of Stral"] =
				{appendText=" conjured up next to Belron, near an obelisk in Vernim Woods by the Northwind Mine wayshrine."},
			["Talk to Dajaheel 3"] =
				{appendText=" under the tented awning in the Pact camp west of the Northwind Mine wayshrine. The rocky enclosure where you raised the cultist is close by, but it's unlikely they would have seen or heard anything.", stepTextKey="The Worm Cultists are transforming the Reachmen as a part of an agreement between Stral and the head of the Worm Cult. I must report back to Dajaheel at once."},
			["Talk to Dajaheel 4"] =
				{appendText=" under the tented awning in the Pact camp in Vernim Woods.", stepTextKey="The Worm Cultists are transforming the Reachmen as a part of an agreement between Stral and the head of the Worm Cult. I must report back to Dajaheel at once."},
		},
		[GetQuestName(3957)] = { -- "Gift of the Worm"				-- Cyberjanet
			["Talk to Belron 1"] =
				{appendText=" in the Worm Cult enclosure. The tented Pact camp, just west of the Northwind Mine wayshrine, overlooks it. Make your way onto lower ground and look around for a rope bridge.  Belron is just beyond it, hiding between some rocks and white-barked trees.", stepTextKey="Belron left camp, hoping to learn more about the rituals. I should seek him out in the field."},
			["Collect Calix Thorntongue's Heart"] =
				{appendText=". He is in the centre of a ritual site surrounded by candles in skulls, with distinctive glowing blue lights. It's just a few paces from the white-barked trees where Belron is hiding, near a rope bridge in the Worm Cult Enclosure overlooked by the Pact camp in Vernim Woods.\n"},
			["Talk to Belron 2"] =
				{appendText=". He's still hiding between the white-barked trees near a rope bridge in Vernim Woods. The Pact Camp overlooks the area.", stepTextKey="I collected the Graveborn's heart. I should speak to Belron."},
			["Get Odanach's Heart"] =
				{appendText=". The Worm Cult occupies a large square area in Vernim Woods, enclosed by a sandy pathway linked with rope bridges.  Follow the main path and look for the ritual areas with their distinctive blue lights."},
			["Get Kraig's Heart"] =
				{appendText=". Keep following the outer path that marks the Worm Cult territory and look for his ritual site with the distinctive blue lights across a rope bridge. The other sites off the path and under the trees have lesser cultists."},
			["Get Uracaile's Heart"] =
				{appendText=". Keep following the outer path past a wooden cage with prisoners. There is another bridge."},
			["Talk to Belron 3"] =
				{appendText=", who has returned to the tented camp the Pact is using near Northwind Mine. It overlooks the Worm Cult enclosure, so you can continue uphill on the path around it. Belron is in a tent.", stepTextKey="I've collected three more hearts from the Graveborn. I must return to Belron at the Pact camp."},
			["Talk to Belron 4"] =
				{appendText=" in his tent in the Pact camp near Northwind Mine wayshrine. The camp overlooks the Worm Cult enclosure, so you can continue uphill on the path around it.", stepTextKey="I've collected three more hearts from the Graveborn. I must return to Belron at the Pact camp."},
		},
		[GetQuestName(3968)] = { -- "Through the Shroud"			-- Cyberjanet
			["Drink Potion near Belron"] =
				{appendText=". It's in a gray jar in his tent in Vernim Woods. The camp is just off the main road leading west from Northpoint Mine wayshrine."},
			["Talk to Belron 1"] =
				{appendText=" in his tent in Vernim Woods. The camp is just off the main road leading west from Northpoint Mine wayshrine.", stepTextKey="I've drunk the potion. I should speak to Belron to learn what my next move should be."},
			["Destroy Totem"] =
				{appendText=" in the barrow in the centre of the Worm Club enclosure. It's not visible from the Pact Camp west of the Northwind Mine wayshrine. Make your way down some rocks, off the main path, and look for the glowing blue miasma above a round structure.\n\nStairs lead down to the totem, a withered idol with an animal skull head and twisted thorny log base."},
			["Talk to Belron 2"] =
				{appendText=" who has joined you in the barrow in the center of the Worm Cult encampment. The barrow is not visible from the tented Pact camp just west of the Northwind Mine wayshrine, so they must have followed you down.", stepTextKey="The idol has been destroyed, and the shroud is gone. Belron has arrived with backup. I should speak to him."},
			["Enter the Ruins"] =
				{appendText=" through the door in the huge barrow in the centre of the Worm Cult enclosure in Vernim Winds."},
			["Defeat the Graveborn"] =
				{appendText=" in the Vaults of Vernim, hidden in the barrow in the center of Vernim Woods."},
			["Kill Stral Blackthroat"] =
				{appendText="in the barrow in the center of Vernim Woods. A door leads from the main Vault to Stral's Ritual Site."},
			["Report in at the Pact Camp 1"] =
				{appendText=" just off the main road leading to Vernim Woods from the Northwind Mine wayshrine. Orla said she would meet you there and is standing under a canopy.", stepTextKey="Stral is dead. Unfortunately, he took Dajaheel and Belron with him. I should return to the encampment and regroup with whomever is left."},
			["Report in at the Pact Camp 2"] =
				{appendText=" west of the Northwind Mine wayshrine, where Orla is standing under a canopy.", stepTextKey="Stral is dead. Unfortunately, he took Dajaheel and Belron with him. I should return to the encampment and regroup with whomever is left."},
		},
		[GetQuestName(4225)] = { -- "To Nimalten"					-- Cyberjanet
			["Talk to a Guard in Nimalten"] =
				{appendText=", in the western part of The Rift. If you're new to the area, just follow the road west of Vernim Woods until you reach it. Cross a bridge over the river, then turn left. The guard is on duty at the entrance to the town, arms crossed."},
		},
		[GetQuestName(4153)] = { -- "Concealed Weapons"				-- Cyberjanet
			["Talk to Thane Fjora"] =
				{appendText=". Thane's Hall is at the top of the stairs in the center of town.\n\nThane Fjora is upstairs in the throne room, next to Aera Earthturner."},
			["Talk to Golun at the Guild Hall"] =
				{appendText=" in the center of town, just next to the Guild Trader. Both Fighters Guild and Mages Guild banners hang outside it. \n\nGolun is wearing brown and beige mage robes, and is consulting the bookshelves."},
			["Talk to Borodin at the Inn"] =
				{appendText=" in the center of town, just next to the stairs. Borodin is upstairs, away from the fire, talking to two people."},
			["Talk to Aera 1"] =
				{appendText=". Thane Fjora asked you to speak to Borodin at the Inn and Golun at the Mages Guild. Aera has followed you into the room. Speak to her before doing anything else!", stepTextKey="Sergeant Aera wants to know how the investigation is going. I should talk to her."},
			["Investigate Betar-Nes's House"] =
				{appendText=", behind the pub. Look for inconspicuous documents."},
			["Return to Thane's Hall"] =
				{appendText=" at the top of the stairs in the center of Nimalten."},
			["Talk to Aera 2"] =
				{appendText=" at the top of the stairs in the center of Nimalten.", stepTextKey="Golun has apparently been killed. I should speak to Aera outside the thane's hall to learn more."},
			["Investigate Golun's Murder"] =
				{appendText=". Thane's Hall is at the top of the stone stairs in the center of Nimalten. Its library is just behind the wooden stairs as you enter."},
			["Use Glowing Orb"] =
				{appendText=", which is not actually visible. Search for a prompt next to Golun's body in the library of Thane's Hall."},
			["Talk to Glowing Projection"] =
				{appendText=" in the library of Thane's Hall."},
			["Enter Secret Passage to the Crypt"] =
				{appendText=" in the library of Thane's Hall. Thane’s Hall is at the top of the stone stairs in the center of Nimalten. Is this crypt directly below it?"},
			["Listen to Borodin"] =
				{appendText=", who appeared as soon as you entered the crypt from the library fireplace in Thane's Hall."},
			["Kill Borodin"] =
				{appendText=", who appeared as soon as you used the crypt entrance in the library fireplace and teleported you away. You are still in the crypt below Thane's Hall in the center of Nimalten, and Borodin is not in the immediate area. You'll have to search deeper."},
			["Find Thane Fjora"] =
				{appendText=" upstairs in Thane's Hall, which overlooks the center of Nimalten.\n\nLook for doorways out of the crypt. One of them will lead you back into the library."},
			["Talk to the Thane"] =
				{appendText=" upstairs in Thane's Hall, which overlooks the center of Nimalten. She is injured, but alive."},
			["Exit Thane's Hall"] =
				{appendText=" and head for the stairs leading down to the town center. Aera can't be far."},
			["Talk to the Wounded Housecarl"] =
				{appendText=" standing on the path between Thane's Hall and the stairs leading to the town center. He's also been injured."},
			["Find Aera"] =
				{appendText=". The stone staircase has an exit towards the water. The wounded housecarl is on the stones.\n\nA large, round, grey stone set in rocks next to the water marks the likely entrance to the crypt."},
			["Talk to Aera Earth-Turner"] =
				{appendText=". After using the door hidden in the large, round stone next to the water, follow the wooden walkway in the barrow entrance and take the trapdoor soon after to find her."},
			["Arrest Aera Earth-Turner"] =
				{appendText=" and bring her to face justice."},
			["Exile Aera Earth-Turner"] =
				{appendText=" if you really believe her words. Let her run and hide forever."},
			["Kill Aera Earth-Turner 1"] =
				{appendText=" if you abhor her betrayal of the Pact.", stepTextKey="Aera was with the Worm Cult, but she's done serving them. She wants to flee.\n\nI can kill her, try to bring her back to face justice, or let her go."},
			["Kill Aera Earth-Turner 2"] =
				{appendText=". After fleeing into the crypt, she took a trapdoor into the barrow, where you found her. Now she has fled through another door.", stepTextKey="After being confronted with her crimes, Aera fled. She leaves me no choice. I cannot allow her to escape. I must go after her and kill her."},
			["Talk to Thane in Throne Room 1"] =
				{appendText=". Make your way back to the center of Nimalten, where you'll find Thane's Hall at the top of the stone staircase. The throne room is upstairs.\n\n", stepTextKey="Aera is dead. I should speak with the Thane in her throne room."},
			["Kill Worm Cultist and Leave the Crypt"] =
				{appendText=". A door leads into a room with another crypt exit, but a worm cult leader, Morgane, is lying in wait.\n\nAfter disposing of her, make your way back to the center of town and up the stairs to Thane's Hall."},
			["Talk to Thane in Throne Room 2"] =
				{appendText=" of Thane's Hall. Find your way back to the center of town and take the stairs.", stepTextKey="Aera has rejected all ties with the Worm Cult. I let her go into exile. To keep her safe, I must lie to Thane Fjora and say Aera is dead."},
			["Talk to Thane in Throne Room 3"] =
				{appendText=". Make your way back to the center of town and follow the stairs to get back to Thane's Hall.", stepTextKey="Aera is dead. I should speak with the thane in her throne room."},
		},
		[GetQuestName(4286)] = { -- "Pinepeak Caverns"				-- Cyberjanet
			["Talk to Researcher at Pinepeak Caverns"] =
				{appendText=". Your battle against the Reachmen and now the Worm Cult leads you ever westward through The Rift. After leaving Nimalten and crossing the bridge across the river, take the next two bridges nearby and enter Geirmund's Hall.\n\nThere's a big party here! Take the left fork in the road where the dancers show off their moves to a beating drum. Keep left until you see a makeshift stage, then bear right and cross the bridge. Geirmund's Hall wayshrine is just after that.\n\nContinue on the road between the barrow and the wayshrine, then cross another wooden bridge. Lots of water here! The researcher, an Argonian, is meandering on the riverside."},
		},
		[GetQuestName(3978)] = { -- "Tomb Beneath the Mountain"		-- Cyberjanet
			["Use Hakra Shard on Cultist Corpse"] =
				{appendText=" inside Pinepeak Cavern, directly across the river from Geirmund's Hall wayshrine. A wooden bridge links the two banks. Pass a small group including two Argonians. Three tents are pitched outside the boarded-off entrance.\n\nOnce through the door, there are Worm Cult corpses on the ground, between the fire traps. \n"},
			["Talk to Reanimated Corpse"] =
				{appendText=" inside Pinepeak Cavern, opposite the Geirmund's Hall wayshrine. Worm Cult bodies lie between the fire traps at the entrance."},
			["Destroy Urn of Kyne"] =
				{appendText=". Inside Pinepeak Cavern, take the path past the fire trap blocking a long corridor. Follow the path down into a large cavern, then check the exits for blue lights emanating from an urn."},
			["Destroy Urn of Stuhn"] =
				{appendText=". Continue down the corridor from where you found the Urn of Kyne until you see another blue light emanating from an urn."},
			["Destroy Urn of Shor"] =
				{appendText=". Retrace your steps to the large cavern you found after following the long corridor with the fire trap at the entrance to Pinepeak Cavern. \n\nWith the glowing blue arch in front of you, turn right and take the first exit. That tunnel leads to a door. Go through and follow the path until you see an urn with blue light emanating from it.\n"},
			["Defeat Hakra"] =
				{appendText=" in her tomb. Take the nearby exit with several fire traps in a row and follow the short path to the door of her tomb in Pinepeak Cavern. \n\nIf the cultists managed to overpower her while you were destroying the urns, they must have found a way through the door at the entrance to the cavern."},
			["Talk to Hakra Outside 1"] =
				{appendText=". Exit through the corridor, probably the one the Worm Cult used to gain entrance to her tomb so quickly. It's a shortcut back to the entrance and the door into The Rift. Her ghost is standing with the researchers.", stepTextKey="Hakra's spirit is no longer bound to her tomb or to the Worm Cult. She is free, after all these years. I must talk to her, outside the cavern."},
			["Talk to Hakra Outside 2"] =
				{appendText=". Her ghost is standing with the researchers not far from the wooden bridge linking the Cavern with the Geirmund's Hall area.", stepTextKey="Hakra's spirit is no longer bound to her tomb or to the Worm Cult. She is free, after all these years. I must talk to her, outside the cavern."},
		},
		[GetQuestName(3981)] = { -- "To Taarengrav"					-- Cyberjanet
			["Reach Taarengrav"] =
				{appendText=". From Pinepeak Cavern, cross the wooden bridge and take the road to the left, which passes below the Geirmund's Hall wayshrine. \n\nContinue on and cross a stone bridge. Pass some partygoers, then cross another stone bridge. Continue straight on until you see the Taarengrav wayshrine. \n\nTaarengrav is downhill from the wayshrine. Once again, you will see Pact tents. As you approach, a male Dunmer in blue and grey mage robes will run up to you asking for help. \n\nHowever, the Pact Military is dealing with the Worm Cult. They may have more information on Valdur."},
			["Talk to Narir 1"] =
				{appendText=", a male Nord crouching over an injured soldier next to a tent.", stepTextKey="Now that I've reached Taarengrav, I should speak to a local to find out what's going on."},
			["Talk to Narir 2"] =
				{appendText=", a male Nord crouching over an injured soldier next to a tent.", stepTextKey="Now that I've reached Taarengrav, I should speak to a local to find out what's going on."},
		},
		[GetQuestName(4185)] = { -- "To Honrich Tower"				-- Cyberjanet
			["Reach Honrich Tower"] =
				{appendText=". Now that you've travelled to the very west of The Rift, it's time to head back east to the center of The Rift, slightly south of the lakes. Follow the minor roads until you get to Ragged Hills wayshrine, there are no bridges to cross. Then follow the main road to Honrich Tower. Look for the Pact tents near the wayshrine."},
			["Talk to Jorunn the Skald-King 1"] =
				{appendText=" under an awning in the Pact encampment, between the two spirits of the companions you freed.", stepTextKey="Now that I've reached Honrich Tower I should speak to Jorunn the Skald-King."},
			["Talk to Jorunn the Skald-King 2"] =
				{appendText=" under an awning in the Pact encampment, between the two spirits of the companions you freed.", stepTextKey="Now that I've reached Honrich Tower I should speak to Jorunn the Skald-King."},
			["Talk to Jorunn the Skald-King 3"] =
				{appendText="under an awning in the Pact encampment, between the two spirits of the companions you freed.", stepTextKey="Now that I've reached Honrich Tower I should speak to Jorunn the Skald-King."},
		},
		[GetQuestName(4147)] = { -- "The Shackled Guardian"			-- Cyberjanet
			["Talk to Narir"] =
				{appendText=", a male Nord crouching over an injured soldier next to a tent in Taarengrav, downhill from the wayshrine of the same name.\n"},
			["Collect Lost Notes"] =
				{appendText="\nThe cultists have them. They're all around the Pact encampment at Taarengrav."},
			["Save Captive Delvers"] =
				{appendText="\nThe Worm cultists around the Taarengrav encampment have tethered many in ritual circles with tell-tale blue lights, but some are tied up."},
			["Find Kireth Vanos"] =
				{appendText=". Almost everyone you freed told you she's in a tent behind the dragon mound, the other name for the barrow at Taarengrav.\n"},
			["Investigate the Taarengrav Barrow"] =
				{appendText=". Go down the stairs leading into the barrow and look for a door. Remember, you were sent to Taarengrav to look for the spirit of Valdur."},
			["Find a Way to Go Deeper into the Barrow"] =
				{appendText=" at Taarengrav. Head past the spirit and follow the fire traps until you hear the spirit's voice or see him again. Enter the large cavern then find the door the spirit is showing you. Kireth's Dunmer assistant is alive and has something to tell you."},
			["Read Delver Notes"] =
				{appendText=" you recovered from the cultists around the Tarrengrav encampment. The last paragraph seems to be Kireth's transcription."},
			["Solve the Door Puzzle"] =
				{appendText=" in the Taarengrav barrow. It's at the end of a trail of fire traps. The spirit of Valdur guides you to a large cavern and then to the entrance of the puzzle room.\n\nKireth's notes are very poetic, and the symbols above the doors are not that clear. Still, it is possible to follow her directions if your eyes are sharp enough to decipher the symbols, and if you read her sentences in pairs."},
			["Stop the Ritual"] =
				{appendText=". You solved the door puzzle at the end of the trail of fire traps in the Taarengrav barrow. The Spirit of Valdur guided you to the puzzle room.\n\nNow it's up to you save the spirit in the barrow, tethered in the same way as the delvers above ground, in a circle with blue lights. You remember how you stopped the ritual before."},
			["Talk to Valdur 1"] =
				{appendText=". He went through the door by the brazier, and seems to have unlocked the door near the entrance to the barrow in doing so.\n\nHe will have more to say if you wait a moment longer.\n", stepTextKey="The spirit Valdur seems to be free. I should speak with him."},
			["Talk to Valdur 2"] =
				{appendText=". He went through the door by the brazier, and seems to have unlocked the door near the entrance to the barrow in doing so.\n\nHe will have more to say if you wait a moment longer.\n", stepTextKey="The spirit Valdur seems to be free. I should speak with him."},
		},
		[GetQuestName(4139)] = { -- "Shattered Hopes"				-- Cyberjanet
			[1] = 
				{appendStepText="", stepTextKey="The Pact's forces are spread thin. Jorunn has asked me to close the portals to Coldharbour and confront the Cult's leader, Thallik Wormfather. I should speak with the spirit of Valdur, one of Ysgramor's Companions."},
			["Talk to Valdur"] =
				{appendText="'s spirit, next to King Jorunn and the spirit of Hakra, under an awning in the tented Pact camp at Honrich Tower."},
			[2] = 
				{appendStepText="", stepTextKey="I got the impression I might be able to convince Valdur to provide me with additional aid if I can persuade him. Otherwise, I should leave the king's camp and look for the portals I need to close."},
			["Leave the Camp"] =
				{appendText=" and look for the wetland between the Honrich Tower wayshrine and the lake. Lake and land areas are interlaced."},
			[3] = 
				{appendStepText="", stepTextKey="I must seek out the four portals the Worm Cult has opened to Coldharbour. Closing the portals will stop the legions of Daedra coming through."},
			["Close the Portals to Coldharbour"] =
				{appendText="\n\nSearch the edges of the wetland between Honrich Tower wayshrine and the lake for broken towers. The blue-black portals are hidden inside them."},
			[4] = 
				{appendStepText="", stepTextKey="I closed the portals to Coldharbour and the spirit of Valdur appeared. He says they've found the cult's leader, Thallik Wormfather, and I should come to the central ruins."},
			["Confront Thallik Wormfather at the Central Ruins"] =
				{appendText=", a large ruin than the broken towers dotted around the edge of the wetland between the lake and Honrich Tower wayshrine."},
			[5] = 
				{appendStepText="", stepTextKey="Thallik Wormfather escaped through a portal to the cult's base at Arcwind Point. Valdur says Captain Hrosta has gone after him. I should go through the portal and try to catch up."},
			["Enter the Portal to Arcwind Point"] =
				{appendText=", a glowing portal in the central ruins in the wetland between Honrich Tower wayshrine and the lake."},
			[6] = 
				{appendStepText="Thalik Wormfather created a portal in the central ruin and escaped. Captain Hrosta and her soldiers followed. So should I.\n\n", stepTextKey="I've traveled through the portal to the Worm Cult's base at Arcwind Point. I should look for Captain Hrosta to find out where Thallik Wormfather went."},
			["Find Captain Hrosta"] =
				{appendText=" in this bleak, snowy landscape. Here, Dremora perform the rituals you have seen the Worm Cult emulating throughout the Rift.\n\nTake the stairs down. To the left you'll see stone arches. Follow those to find a barrow, and go down the stairs to find Captain Hrosta."},
			[7] = 
				{appendStepText="", stepTextKey="I found Captain Hrosta. I should speak to her to find out where Thallik Wormfather has gone."},
			["Talk to Captain Hrosta"] =
				{appendText=" in the barrow at Arcwind Point. She is alive. The bodies around her show her soldiers survived the journey through the portal from the wetlands near Honrich Tower wayshrine and the cold journey through the stone archways, but not the fight that ensued."},
			[8] = 
				{appendStepText="Thalik Wormfather created a portal in the central ruin at Honrich Tower, and escaped. Captain Hrosta and her soldiers followed through a trail of stone arches. But Wormfather escaped again, thanks to a human sacrifice.\n\n", stepTextKey="Thallik Wormfather has retreated into the lower ruins at Arcwind Point. To get past the wards to follow him, a life must be sacrificed. Captain Hrosta has volunteered, or I can perhaps trick a Reachman prisoner into doing so."},
			["Sacrifice Captain Hrosta 1"] =
				{appendText=". She's the only survivor of the bloody battle that took place here. That should ensure her a place in Sovngarde, does she really have to die now?", stepTextKey="Thallik Wormfather has retreated into the lower ruins at Arcwind Point. To get past the wards to follow him, a life must be sacrificed. Captain Hrosta has volunteered, or I can perhaps trick a Reachman prisoner into doing so."},
			["Trick a Reachman Prisoner"] =
				{appendText=". Captain Hrosta mentioned she saw one in a cage not far from the barrow here in Arcwind Point.\n\nIt's a bleak, snowy place that seems to be only accessible through portals. The one that brought you here was in the central ruins in the wetlands near Honrich Tower wayshrine."},
			[9] = 
				{appendStepText="Thalik Wormfather created a portal in the central ruin at Honrich Tower to reach Arcwind Point. Captain Hrosta and her soldiers followed through a trail of stone arches. But Wormfather used a human sacrifice to escape again.\n\n", stepTextKey="Someone must be sacrificed to open the door to follow Thallik Wormfather. Though Captain Hrosta offered to sacrifice herself, I've decided to trick a Reachman prisoner into killing himself. There's one in a cage up the mountain."},
			["Find a Reachman Prisoner"] =
				{appendText=". Leave the barrow and follow the uphill path away from the arch."},
			[10] = 
				{appendStepText="", stepTextKey="Someone must die to open the door to follow Thallik Wormfather. Captain Hrosta volunteered, and I agreed it was the only way."},
			["Ask Captain Hrosta To Open the Door"] =
				{appendText=". She will die doing so, after surviving everything else. She survived the icy trip from the portal opened in the central ruins of Honrich Tower. She was the only survivor of the bloody battle in the barrow at the end of the stone arches."},
			[11] = 
				{appendStepText="", stepTextKey="The sacrifice is made. I must wait until the circle's victim is devoured."},
			["Witness the Sacrifice"] =
				{appendText=" in the barrow at Arcwind Point, at the end of a line of ritual arches.\n\nThallik Wormfather used a sacrifice to enter the barrow, after escaping from Honrich Tower through a portal in the central ruin."},
			[12] = 
				{appendStepText="", stepTextKey="Thallik Wormfather has the legendary axe Wuuthrad in the lower ruins at Arcwind Point. I must find and kill him to retrieve Wuuthrad and end the Worm Cult threat."},
			["Find Thallik Wormfather"] =
				{appendText=" now that the sacrifice has opened the door in the barrow at the end of the stone arches.\n\nHe escaped the ruin in the wetland near Honrich Tower wayshrine by opening a portal that brought you here. "},
			[13] = 
				{appendStepText="", stepTextKey="Thallik Wormfather is performing some dark ritual with the legendary axe Wuuthrad in the lower ruins at Arcwind Point. I must kill him to retrieve Wuuthrad and end the Worm Cult threat."},
			["Kill Thallik Wormfather"] =
				{appendText=" in the barrow at the end of a line of stone arches in Arcwind Point.\n\nHe came here through a portal in the central ruin at Honrich Tower.  Now he hides deeper in the barrow, in Sinmur's Tomb."},
			[14] = 
				{appendStepText="", stepTextKey="I slew Thallik Wormfather, but Wuuthrad was shattered and it seems Thallik merged his spirit with the ghost giant Sinmur. I should speak to Hakra. She may know more about what just happened."},
			["Talk to Hakra"] =
				{appendText=", who has materialised in Sinmur's Tomb in the Arcwind Point barrow, at the end of a line of ritual stone arches.\n\nIt's in the far southwest of the Rift, but there are no wayshrines here. The only access is through portals like the one Thallik Wormfather created in the central ruin of Honrich Tower."},
			[15] = 
				{appendStepText="", stepTextKey="Thallik Wormfather is dead, but he merged his spirit with the ghost giant Sinmur and shattered the legendary axe Wuuthrad. All that remains is the axe's haft. I should collect the haft and take it back to Honrich Tower."},
			["Collect the Haft of Wuuthrad"] =
				{appendText=" from the ground in front of Valdur's spirit, which materialized in Sinmur's Tomb after you killed Thallik Wormfather.\n\nWormfather escaped you in the central ruin of the Honrich Tower wetland by creating a portal to this remote snowscape. A chain of stone arches led you to the barrow which holds Sinmur's Tomb, where he bonded with Sinmur in death."},
			[16] = 
				{appendStepText="", stepTextKey="Thallik Wormfather is dead, but he merged his spirit with the ghost giant Sinmur and shattered the legendary axe Wuuthrad. I should take Wuuthrad's haft through the portal back to Honrich Tower."},
			["Enter the Portal to Honrich Tower"] =
				{appendText=", a glowing portal like the one that brought you to Arcwind Point from the central ruin at Honrich Tower.  This remote snowscape has no wayshrines. Entering - and leaving - requires a portal."},
			[17] = 
				{appendStepText="", stepTextKey="Thallik Wormfather is dead, but he merged his spirit with the ghost giant Sinmur and shattered the legendary axe Wuuthrad. I should talk to Jorunn about what has transpired."},
			["Talk to Jorunn the Skald-King 1"] =
				{appendText=" in his tented camp near Honrich Tower wayshrine.", stepTextKey="Thallik Wormfather is dead, but he merged his spirit with the ghost giant Sinmur and shattered the legendary axe Wuuthrad. I should talk to Jorunn about what has transpired."},
			[18] = 
				{appendStepText="", stepTextKey="Valdur has offered to summon the spirit of one of the Five Hundred Companions to fight at my side. I only have to let him know which warrior I want."},
			["Choose Warrior"] =
				{appendText=", a brave swordswoman who fought in the great battle against the Elves in what became Eastmarch."},
			["Choose Firemage"] =
				{appendText=", who rained fire on the elves of Red Mountain."},
			["Choose Healer"] =
				{appendText=", who tended their dying companions in the battle against the Argonians in Black Marsh."},
			[19] = 
				{appendStepText="Pact soldiers followed Thallik Wormfather through a portal in the central ruin at Honrich Towers. But in a barrow at the end of a line of arches he escaped using a human sacrifice. \n\nNow we need a sacrifice too, to follow him.", stepTextKey="The Reachman prisoner does not suspect anything. I must lead him back to the ritual circle."},
			["Lead Reachman to Ritual Circle"] =
				{appendText=" in the barrow here in Arcwind Point. \n\nTo get back to the barrow from the cage, there is only one path, slightly downhill."},
			[20] = 
				{appendStepText="", stepTextKey="I led the Reachman prisoner to the ritual circle. I can trick him into touching the gem and killing himself or I can ask Captain Hrosta to sacrifice herself."},
			["Sacrifice Captain Hrosta 2"] =
				{appendText=".  She survived the journey through a portal from the central ruin in the wetland near Honrich Tower wayshrine. She survived the ensuing battle in this snowy wasteland after following Tharrik Wormfather through a trail of stone arches. Now, she will survive no more.", stepTextKey="I led the Reachman prisoner to the ritual circle. I can trick him into touching the gem and killing himself or I can ask Captain Hrosta to sacrifice herself."},
			["Sacrifice Reachman Prisoner"] =
				{appendText=", caged because he freed a child rather than sacrifice her to a Worm Cult ritual. She reminded him of his own daughter."},
			[21] = 
				{appendStepText="\n", stepTextKey="Thallik Wormfather is dead, but he merged his spirit with the ghost giant Sinmur and shattered the legendary axe Wuuthrad. I should talk to Jorunn about what has transpired."},
			["Talk to Jorunn the Skald-King 2"] =
				{appendText=" under an awning in his tented camp.", stepTextKey="Thallik Wormfather is dead, but he merged his spirit with the ghost giant Sinmur and shattered the legendary axe Wuuthrad. I should talk to Jorunn about what has transpired."},
			[22] = 
				{appendStepText="", stepTextKey="Thallik Wormfather is dead, but he merged his spirit with the ghost giant Sinmur and shattered the legendary axe Wuuthrad. I should talk to Jorunn about what has transpired."},
			["Talk to Jorunn the Skald-King 3"] =
				{appendText=" under an awning in his tented camp.", stepTextKey="Thallik Wormfather is dead, but he merged his spirit with the ghost giant Sinmur and shattered the legendary axe Wuuthrad. I should talk to Jorunn about what has transpired."},
		},
		[GetQuestName(4164)] = { -- "A Giant in Smokefrost Peaks"	-- Cyberjanet
			[1] = 
				{appendStepText="", stepTextKey="Jorunn the Skald-King has asked me to travel to Riften and speak with Captain Viveka."},
			["Talk to Captain Viveka"] =
				{appendText=" in Riften. The ghost giant Sinmur was headed in that direction. From the road near the Honrich Tower wayshrine, look for a large stone bridge. Cross that, then follow the road with the shoreline on your right for as long as you can. When the road runs out, continue following the shoreline until you see the Pact tents ahead of you, on the western outskirts of Riften. Captain Viveka is at her desk in a large, well-furnished tent."},
		},
		[GetQuestName(3927)] = { -- "In His Wake"					-- Cyberjanet
			["Rescue Citizens From Rubble"] =
				{appendText="\nThe giant Sinmur caused the north wall of Riften to collapse. Survivors could be struggling to escape from under piles of large stones, scattered between the canal and the broken wall."},
			["Put Out Fires"] =
				{appendText="\nThere is a bucket near the well outside the broken northern wall of Riften, and many fires around it."},
			["Burn Corpses"] =
				{appendText="\nThe dead are scattered openly outside the broken northern wall, too many to bury."},
			["Talk to Captain Viveka"] =
				{appendText=". She's standing on a wooden bench near the broken northern wall."},
		},
		[GetQuestName(4135)] = { -- "Pulled Under"					-- Cyberjanet
			[1] = 
				{appendStepText="", stepTextKey="Captain Viveka asked me to speak with Yiri Windtorn. Yiri claims something took her father."},
			["Enter Yiri's Home"] =
				{appendText=" in Riften. It's right next to the Riften Wayshrine, and bears the name Windtorn House."},
			[2] = 
				{appendStepText="", stepTextKey="When I entered Yiri's home, I found Bonohild Windtorn standing over a dead Worm Cultist! I must ask her what's going on."},
			["Talk to Bonohild Windtorn"] =
				{appendText=", upstairs in her Riften home next to the wayshrine. It's called Windtorn House, though it doesn't look windtorn or even damaged by Sinmur."},
			[3] = 
				{appendStepText="", stepTextKey="Why would the Worm Cult want to kill Yiri? I should investigate the cultist's body."},
			["Investigate Cultist Body"] =
				{appendText=" at Bonohild's feet. The worm cultist entered their home Windtorn House in Riften, next to the wayshrine, and tried to kill Yiri."},
			[4] = 
				{appendStepText="", stepTextKey="I found a scroll on the dead cultist. Reading it may reveal the Worm Cult's plans."},
			["Read Cultist Note Near Bonohild"] =
				{appendText=". It may offer a reason why the cultist entered their home, Windtorn House, in Riften and tried to kill Yiri."},
			[5] = 
				{appendStepText="", stepTextKey="The Worm Cult seeks a shard of Wuuthrad in Riften. Yiri must know something about their plans to retrieve it, but whatever she witnessed has rendered her unable to speak.\n\nI need to find a way to draw her out of her terrified state."},
			["Find Out What Happened to Yiri's Father"] =
				{appendText=" by talking to Bonohild. She just killed a Worm Cultist that attacked Yiri upstairs in her home, Windtorn House, next to the Riften Wayshrine.\n\nTraders have set up their tents around the well in the center of town."},
			[6] = 
				{appendStepText="", stepTextKey="The Worm Cult seeks a shard of Wuuthrad in Riften. Captain Viveka said to speak with her commanding officer once I learned what was going on. Perhaps he can help."},
			["Talk to Centurion Andrin 1"] =
				{appendText=" in the walled courtyard of the Fighter's Guild. From Yiri's home next to the wayshrine, travel past the Mages Guild and the Shadehome Inn to reach it. He stands alone, next to a lit sconce, within the entrance to the Fighter’s Guild.", stepTextKey="The Worm Cult seeks a shard of Wuuthrad in Riften. Captain Viveka said to speak with her commanding officer once I learned what was going on. Perhaps he can help."},
			[7] = 
				{appendStepText="", stepTextKey="Andrin, the commander of the Pact forces, has no soldiers to spare for an investigation. He seemed not to believe me. He said I was free to look into the matter if I wanted."},
			["Uncover the Worm Cult Plot"] =
				{appendText=". The homeless that Andrin mentioned mostly seek shelter behind the Shadehome Inn. \n\nThe stable is outside the Riften walls. Take the exit next to the Inn, turn left and look for a worker with a shovel.\n\nThe smithy is next to the waterside. Wasn't Yiri's father taken by zombies near water? \n\nThe docks are further on. Just follow the ramps until you see a glowing figure that disappears. A figure next to them is casting spells of some kind."},
			[8] = 
				{appendStepText="", stepTextKey="The Worm Cult already has the shard of Wuuthrad. When I approached, a Worm Cult necromancer mocked me, then ordered the leader of the local cult cell to eliminate me."},
			["Kill Anchorite Garmar"] =
				{appendText=" who is on the Riften docks platform, just next to a ritual circle in the water."},
			[9] = 
				{appendStepText="", stepTextKey="I've slain Anchorite Garmar, the apparent leader of a Worm Cult cell in Riften. However, another cultist escaped with a shard of Wuuthrad. Centurion Andrin will need to know of these events."},
			["Talk to Centurion Andrin 2"] =
				{appendText=" in the walled courtyard of the Fighters Guild, directly across the canal from the crafting hall.", stepTextKey="I've slain Anchorite Garmar, the apparent leader of a Worm Cult cell in Riften. However, another cultist escaped with a shard of Wuuthrad. Centurion Andrin will need to know of these events."},
			[10] = 
				{appendStepText="", stepTextKey="I've slain Anchorite Garmar, the apparent leader of a Worm Cult cell in Riften. However, another cultist escaped with a shard of Wuuthrad. Centurion Andrin will need to know of these events."},
			["Talk to Centurion Andrin 3"] =
				{appendText=" in the walled courtyard of the Fighters Guild, directly across the canal from the crafting hall.", stepTextKey="I've slain Anchorite Garmar, the apparent leader of a Worm Cult cell in Riften. However, another cultist escaped with a shard of Wuuthrad. Centurion Andrin will need to know of these events."},
			[11] = 
				{appendStepText="", stepTextKey="I've slain Anchorite Garmar, the apparent leader of a Worm Cult cell in Riften. However, another cultist escaped with a shard of Wuuthrad. Centurion Andrin will need to know of these events."},
			["Talk to Centurion Andrin 4"] =
				{appendText=" in the walled courtyard of the Fighters Guild, directly across the canal from the crafting hall.", stepTextKey="I've slain Anchorite Garmar, the apparent leader of a Worm Cult cell in Riften. However, another cultist escaped with a shard of Wuuthrad. Centurion Andrin will need to know of these events."},
		},
		[GetQuestName(4273)] = { -- "To the King"					-- Cyberjanet
			["Talk to Jorunn the Skald-King"] =
				{appendText=" once you have recovered some shards of Wuuthrad. To find them, walk or ride along the main road leading east from Riften.\n\nAs you travel along the road to meet the king, look for evidence of Worm Cult activity. The Worm Cult found one shard in Riften, there may be others along the way.\n\nA lone Nord cowering by an overturned wagon near Lost Prospect may have a Worm Cult story to tell.\n\nFort Fulhelm has been overwhelmed by undead, a sure sign of Worm Cult influence. Someone in the area must have information.\n\nAnd a dead elf in Worm Cult garb near Forelhost carries a note you should read. \n\nThe main road continues south to Trolhetta. The king is in the first tent past the wayshrine."},
		},
		[GetQuestName(4186)] = { -- "Securing the Pass"				-- Cyberjanet
			[1] = 
				{appendStepText="The Worm Cult has placed wards on doors to make them impassable. There must be orbs inside Trolhetta which control the wards.\n\n", stepTextKey="I need to enter Trolhetta and lower the Worm defenses."},
			["Enter Trolhetta"] =
				{appendText=". The entrance to the cave is at the far end of the Pact tented encampment near the wayshrine. A wooden gate seals the entrance."},
			[2] = 
				{appendStepText="", stepTextKey="I should choose a companion to help me fight through the Worm Cultists ahead.\n\nJorunn the Skald-King suggested I seek the council of Holgunn, Walks-in-Ash, and Valdam Andoren."},
			["Choose Warrior"] =
				{appendText=". Speak to Holgunn One-Eye, dressed in brown armor. He's with the small group around the cookfire between the tents."},
			["Choose Firemage"] =
				{appendText=". Speak to Walks-in-Ash, the Argonian next to the cooking fire between the tents."},
			["Choose Healer"] =
				{appendText=". Speak to Valdam Andoren, a robed Dunmer in the group by the cooking fire."},
			[3] = 
				{appendStepText="The Worm Cult has placed wards on doors to make them impassable. There must be orbs inside Trolhetta which control the wards.\n\n", stepTextKey="Now I need to enter Trolhetta."},
			["Enter Trolhetta Cave"] =
				{appendText=" with your chosen companion, using the wooden gate just beyond the Pact tents near the wayshrine.\n\nCheck your inventory. While you have their Amulet of the Pact, the companion will follow you. Should you lose them, use the Horn of the Pact to resummon them."},
			[4] = 
				{appendStepText="", stepTextKey="I must find and destroy the Reaper Orb that is sealing the gate ahead."},
			["Destroy the Reaper Orb"] =
				{appendText=" in the Trolhetta cave just beyond the Pact tents near the wayshrine. To reach the orb, you must travel through a long tunnel, keeping to the high ground, until you reach some stairs leading down. Follow them to a nearby wooden door. \n\nThe orb is through the door, in a glowing purple beam."},
			[5] = 
				{appendStepText="The Worm Cult barred access to Trolhetta Summit using orbs to ward doors. The first orb was in a room at the very end of the tunnel through the Trolhetta Cave.\n\n", stepTextKey="The Reaper Orb is destroyed, but the way is barred by the Necrosis Orb. I must destroy it to advance."},
			["Destroy the Necrosis Orb"] =
				{appendText=". Leave the room where you destroyed the Reaper Orb.  It's now possible to use the ornate wooden door just beyond a purple gem cluster in the ceiling. \n\nPact soldiers occupy the short tunnel beyond the door. Another ornate door at the end leads into a barrow in Trolhetta, surrounded by Worm Cultists performing rituals. \n\nYou have two choices here. You can stay on the lip of the barrow and head towards the giant mushrooms, then look for a hidden path uphill. At the top is an archway leading onto a stone platform with a dead giant on the ground. From there, you can see a warded metal door ahead.  As you approach, you'll find an identical unwarded door just to the right of it.\n\nOr you can take a path through the ritual circles, where you may be able to assist in a separate matter, if you wish. Go through a broken arch, follow the curve uphill and you will see two stone pillars holding up a large incomplete arch. Through there, you will find the two metal doors.\n\nTake the unwarded door into a room where an orb floats in a glowing purple beam."},
			[6] = 
				{appendStepText="I have cleared the path to Trolhetta Summit! The first ward fell when I destroyed an orb at the end of the Trolhetta tunnel, near the Pact tents at Trolhetta. From there, a door past a purple gem cluster led to a barrow, and an uphill path took me to the second warding orb.\n\n", stepTextKey="I should speak to Vigrod Wraithbane."},
			["Talk to Vigrod Wraithbane 1"] =
				{appendText=" now that the wards are down. He is at the Trolhetta Summit wayshrine, just beyond the door you unwarded.\n\n", stepTextKey="I should speak to Vigrod Wraithbane."},
			[7] = 
				{appendStepText="I have cleared the path to Trolhetta Summit! The first ward fell when I destroyed an orb at the end of the Trolhetta tunnel, near the Pact tents at Trolhetta. From there a door past a purple gem cluster led to a barrow, and an uphill path took me to the second warding orb.\n", stepTextKey="I should speak to Vigrod Wraithbane."},
		},
		[GetQuestName(4188)] = { -- "Stomping Sinmur"				-- Cyberjanet
			["Enter Trolhetta Summit"] =
				{appendText=" through the large metal door near the wayshrine."},
			["Talk to Jorunn the Skald-King 1"] =
				{appendText=", who is waiting on the low rocky overlook of Trolhetta Summit. ", stepTextKey="Now that I'm at Trolhetta Summit, I should talk to King Jorunn."},
			["Defeat the Worm Cultists"] =
				{appendText=" throughout the large open area of Trolhetta Summit.  Jorunn the Skald-King leads the way."},
			["Defeat Sinmur"] =
				{appendText=". His spirit looms large and golden under an arch up some stairs at the far end of the Trolhetta Summit battleground. \n"},
			["Listen to Ysgramor"] =
				{appendText=". Join the spirits of Ysgramor and the Companions under the Great Arch of the Trolhetta Summit battleground."},
			["Talk to Jorunn the Skald-King 2"] =
				{appendText=". He is under the Great Arch of the Trolhetta Summit, watching the spirits of the Companions melt away to Sovngard.", stepTextKey="Sinmur is dead. I need to talk to Jorunn the Skald-King."},
			["Exit Trolhetta"] =
				{appendText=". There is a large metal door on the west side of the plain, leading back to the Trolhetta Summit wayshrine."},
			["Talk to Vigrod Wraithbane"] =
				{appendText=", a Nord in metal armour near the Trolhetta Summit wayshrine."},
			["Talk to Jorunn the Skald-King 3"] =
				{appendText=", who has joined the group waiting at the Trolhetta Summit wayshrine.", stepTextKey="With Sinmur defeated, I should speak to Jorunn the Skald-King to make sure all is well."},
			["Talk to Jorunn the Skald-King 4"] =
				{appendText=", who has joined the group waiting at the Trolhetta Summit wayshrine.", stepTextKey="With Sinmur defeated, I should speak to Jorunn the Skald-King to make sure all is well."},
		},
		[GetQuestName(5034)] = { -- "A Grave Situation"				-- Cyberjanet
			[1] = 
				{appendStepText="", stepTextKey="Holgunn One-Eye asked that I seek out Narir in Taarengrav."},
			["Talk to Narir"] =
				{appendText=". It’s quite a walk to this outpost in the far west of the Rift. From the Honrich Tower wayshrine, pass the Pact soldiers near a wagon and make your way down to the road. Continue in that same westerly direction. You will pass Scout Fenrir. When you reach the fork in the road, bear left. The Ragged Hills wayshrine is just past a white tree broken almost in half.\n\nContinue westward, bearing left when given a choice. The cobbled road will become a dirt path. When you reach a wooden platform with crates, and a wagon, turn right. Continue on the dirt path. A tree with white bark and two trunks is just next to an icy atronach lair. A little further on, just past two large rocks, you will see enemy tents to the left. Follow the path uphill away from them to reach Taarengrav wayshrine just ahead. A mage in blue robes may try to intercept you on the way.\n\nThe Pact camp is downhill. There is a path leading to it, a little way back from the wayshrine, just past some large white-barked trees. Worm Cult tents are to the left and there are Pact tents to the right, so you may prefer to make your way from the wayshrine down over the rocks.\n\nNarir is a male Nord, crouched over a wounded soldier next to a tent."},
		},
		[GetQuestName(4184)] = { -- "To Pinepeak Caverns"			-- Cyberjanet
			["Reach Pinepeak Cavern"] =
				{appendText=". Valdur spoke to you in Taarengrav. Take the main road heading north from the wayshrine. After crossing one bridge, look for a second bridge to cross. That road will take you past Geirmund's Hall wayshrine, and then another wooden bridge will take you to your destination."},
			["Talk to Netapatuu"] =
				{appendText=", who is tending to a wounded Dunmer."},
		},
		[GetQuestName(5036)] = { -- "Honrich Tower"					-- Cyberjanet
			[1] = 
				{appendStepText="", stepTextKey="Netapatuu asked that I seek out Jorunn the Skald-King at Honrich Tower."},
			["Talk to Jorunn the Skald-King"] =
				{appendText=".\nMake your way to Taarengrav, where you freed the spirit of Valdur.\n\nFrom that wayshrine, travel east along the minor roads. Start by heading south on the dirt path past two large white-barked trees, then left at the first fork. You will pass an icy atronach lair. Keep your distance, stay on the dirt path, take the next right-hand fork, and you will reach a wooden platform stacked with crates. Continue east on the dirt path.\n\nAt the fork, the road becomes cobbled, but the two routes join up a little further on, just before the Ragged Hills wayshrine. Continue east along the main road until you see a large ruined tower to the left, and Scout Fenrir to the right.\n\nHonrich Tower wayshrine is just ahead, and the Pact tents are close by. The king is under an awning, between the ghosts of the two companions you freed."},
		},
		[GetQuestName(5104)] = { -- "The Shards of Wuuthrad"		-- Cyberjanet
			["Talk to Elfriede"] =
				{appendText=". Honrich is west of Riften, on the main road past the dolmen. Cross a bridge, with the lake on your right. Elfriede is in the tented encampment, close to a wagon near the wayshrine."},
		},
		[GetQuestName(5035)] = { -- "Calling Hakra"					-- Cyberjanet
			[1] = 
				{appendStepText="", stepTextKey="Holgunn One-Eye asked me to go to Pinepeak Cavern and make sure Lieutenant Slonn is alright."},
			["Talk to Lieutenant Slonn at Pinepeak Cavern"] =
				{appendText=". Pinepeak Cavern is some distance away, in the northwest of The Rift. Pack supplies for a long journey and possible adventures along the route!\n\nFrom the Honrich Tower wayshrine, pass the Pact soldiers near a wagon and make your way down to the road. Continue in that same westerly direction. You will pass Scout Fenrir. When you reach the fork in the road, bear left. The Ragged Hills wayshrine is just past a white tree broken almost in half.\n\nContinue westward, bearing left when given a choice. The cobbled road will become a dirt path. When you reach a wooden platform with crates and a wagon, turn right. Continue on the dirt path. A tree with white bark and two trunks is just next to an icy atronach lair.  A little further on, just past two large rocks, you will see enemy tents to the left. Follow the path away from them, uphill, to reach Taarengrav wayshrine just ahead. A mage in blue robes may try to intercept you on the way.\n\nThe dirt path veers north at Taarengrav and soon becomes cobbled. Continue onwards to a stone bridge, cross it and look for a second bridge to the left. After crossing that, you will see the Geirmund's Hall wayshrine on your right.  Continue on past that to a wooden bridge. Cross that bridge and Lieutenant Slonn is to your right, standing next to a white-barked tree near a small group."},
		},


