--		  Rift Side
-- 		=========================================================================
		[GetQuestName(4446)] = { -- "Aiding Sigunn"					-- ARKANOBOT
			["Find Salvageable Goods"] =
				{appendText=". Sigunn says the wagon was ambushed on the trail on the eastern side of Shor's Stone near the troll cave."},
			["Talk to Sigunn in Shor's Stone"] =
				{appendText=". He awaits your return with the news in the shelter near the Guild Traders."},
		},
		[GetQuestName(4176)] = { -- "Breaking the Coven"			-- ARKANOBOT
			["Get the Head of Dyta"] =
				{appendText=". She should be in the northern caves inside the Northwind Mine."},
			["Get the Head of Jadwiga"] =
				{appendText=". She should be in the southern caves inside the Northwind Mine."},
			["Place Hagraven Heads on Pikes"] =
				{appendText=" in the western caves inside Northwind Mine."},
			["Kill Matriarch Kasmira"] =
				{appendText=" in the eastern caves inside Northwind Mine."},
			["Talk to Tovisa"] =
				{appendText=" in the eastern caves inside Northwind Mine."},
			["Meet Tovisa Outside"] =
				{appendText=". There seems to be a barred door leading outside the cave in the eastern caves of Northwind Mine."},
			["Talk To Tovisa"] =
				{appendText=" outside the exit of the mine west of Northwind Mine."},
		},
		[GetQuestName(5005)] = { -- "Drink, Drink, and Be Merry"	-- ARKANOBOT
			["Talk to Darva"] =
				{appendText=". She is usually at the Alchemist Shop at Lakeside Experiments in Riften. But she also frequents the Fighters Guild in Riften."},
			["Talk to Innarrek 1"] =
				{appendText=" at the Fighters Guild in Riften.", stepTextKey="Darva mentioned that Riften's housecarl Innarrek wishes to speak with me after my drunken escapade."},
			["Talk to Innarrek 2"] =
				{appendText=" at the Fighters Guild in Riften.", stepTextKey="The alchemist Darva, who'd devised the wine the bandits stole, said Riften's housecarl Innarrek is interested in Fort Greenwall.  I should discuss what I found with him."},
		},
		[GetQuestName(3923)] = { -- "The Farmer's Champion"			-- NaeomiFriz 
			["Investigate Treva's Farm"] =
				{appendText=", to the southeast of Nimalten. Murmurs of survivors near the farm say to look near the stables."},
			["Find Gjakil"] =
				{appendText=", who might be near the ridge to the north that Irna mentioned."},
			["Find Fridda"] =
				{appendText=", Gjakil gave me some directions. I heard some clambering over some rocks."},
			["Find Gretsine"] =
				{appendText=". Fridda had seen her go inside a cave in the hills east of the farm."},
			["Talk to Centurion Gjakil 1"] =
				{appendText=", who is outside of a cave to the northeast of the farm.", stepTextKey="Gjakil, wounded but unbroken, stands outside the cave. Gretsine said he might know what to do about the impending giant attack. I should speak with him."},
			["Follow Centurion Gjakil"] =
				{appendText=" to Mammoth Ridge."},
			["Kill Chieftain Bomaz"] =
				{appendText=", the leader of the giant camp near Mammoth Ridge."},
			["Talk to Centurion Gjakil 2"] =
				{appendText=" outside of the giant's camp at Mammoth Ridge.", stepTextKey="I defeated the giant chieftain. I should speak with Centurion Gjakil"},
		},
		[GetQuestName(4306)] = { -- "Finding Winter's Hammer"		-- Westrany
			["Recover Winter's Hammer"] =
				{appendText=" from the bandits at Fort Greenwall, north of Riften.\n"},
			["Return Winter's Hammer to Sage Svari"] =
				{appendText=" at Fallowstone Hall, northwest of Shor's Stone."},
		},
		[GetQuestName(4448)] = { -- "Kalodar's Farewell"			-- Johnyfreeman
			["Search for Kalodar's Remains"] =
				{appendText=". The locals have seen him hunting bears and other animals in the region just north of Vermin Woods, it is reasonable to assume that there might be evidence of his presence nearby. The area to the west alongside the hills before the river still harbors a considerable number of bears. Thus, it would be a good location to begin the search."},
			["Take the Letter by Kalodar's Remains"] =
				{appendText=". An extinguished campfire and a broken crate with some bottles in the shadow of the hills, just northwest of Vermin Woods, north of the road, silently bear witness to Kalodar's final resting place."},
			["Deliver Kalodar's Letter to Helfhild"] =
				{appendText=" next to the road by a campfire, not too far from the north of Vermin Woods."},
		},
		[GetQuestName(3921)] = { -- "Move out Miners"				-- ARKANOBOT
			["Save Jaknir"] =
				{appendText="."},
			["Save Adana"] =
				{appendText="."},
			["Save Narir"] =
				{appendText="."},
			["Save Raena"] =
				{appendText=".\n\nSearch Shor's Stone Mine for the captured Miners."},
			["Talk to Foreman Gandis 1"] =
				{appendText=" near the first intersection inside Shor's Stone Mine.", stepTextKey="I've set free all the miners I could find. I should find Foreman Gandis and tell him the good news."},
			["Talk to Foreman Gandis 2"] =
				{appendText=" near the first intersection inside Shor's Stone Mine.", stepTextKey="I should find Foreman Gandis in Shor's Stone to let him know I saved as many miners as I could."},
		},
		[GetQuestName(3961)] = { -- "Raise the Colors"				-- NaeomiFriz 
			["Kill Kevinne Blightheart"] =
				{appendText=". She's at the bend in the path west of the Boulderfall Pass."},
			["Kill Lydi Snowpelt"] =
				{appendText=", her camp resides near the cages, as the path to the west wraps around itself."},
			["Kill Vivian Witchclaw"] =
				{appendText=", she's holed up southwest of the tower at the end of the path."},
			["Plant the Pact's Banner"] =
				{appendText=" at the small tower fort at the end of a path west of Boulderfall Pass."},
		},
		[GetQuestName(4307)] = { -- "Returning Winter's Bite"		-- Westrany
			["Recover Winter's Bite at Faldar's Tooth"] =
				{appendText=" on the peninsula northwest of Skald's Retreat.\n\nThe staff is being held by a bandit boss named Thorfa, outside the entrance of the delve.\n"},
			["Deliver Staff to Sage Svari"] =
				{appendText=" on the second floor of Fallowstone Hall."},
		},
		[GetQuestName(4171)] = { -- "The Rise of Sage Svari"		-- ARKANOBOT
			["Talk to Skald Svari"] =
				{appendText=" near a companion shrine in the burial grounds of Fallowstone Hall."},
			["Accompany Skald Svari to the Shrine of Yngol"] =
				{appendText=" in the northern section of the burial grounds of Fallowstone Hall."},
			["Pray with Skald Svari at the Shrine of Yngol"] =
				{appendText=". The Shrine adorns the northern mountainside in the burial grounds near Fallowstone Hall."},
			["Accompany Skald Svari to the Shrine of Ylgar"] =
				{appendText=" at the spire in the southern section of the burial grounds of Fallowstone Hall."},
			["Pray with Skald Svari at the Shrine of Ylgar"] =
				{appendText=". The Shrine adorns the spire in the southern section of the burial grounds near Fallowstone Hall."},
			["Accompany Skald Svari to the Shrine of Ysgramor"] =
				{appendText=" near the mountainside in the northwestern corner of the burial grounds of Fallowstone Hall."},
			["Pray with Skald Svari at the Shrine of Ysgramor"] =
				{appendText=". The Shrine adorns the mountainside in the northwestern section of the burial grounds near Fallowstone Hall."},
			["Meet Skald Svari at the Hall"] =
				{appendText=" near the entrance to Fallowstone Hall."},
			["Give Skald Svari the Prayer Beads"] =
				{appendText=" near the entrance to Fallowstone Hall."},
			["Watch Skald Svari Gain the Title of Sage"] =
				{appendText=" near the entrance to Fallowstone Hall."},
			["Talk to Sage Svari"] =
				{appendText=" near the entrance to Fallowstone Hall."},
		},
		[GetQuestName(4174)] = { -- "Scouting the Mine"				-- ARKANOBOT
			["Investigate Camp"] =
				{appendText="\n\nSearch the buildings, the carts and totem shrine around the Northwind Mine for valuable information related to Reachmen."},
			["Talk to Tovisa 1"] =
				{appendText=" at the prisoner camp next to Alona's Sanctum at Northwind Mine.", stepTextKey="I've discovered that the Reachmen here worship a coven of Hagravens. I should go tell Tovisa."},
			["Infiltrate Alona's Sanctum"] =
				{appendText=" at Northwind Mine."},
			["Get a Northwind Mine Key"] =
				{appendText=" from Alona's Sanctum at Northwind Mine."},
			["Talk to Tovisa 2"] =
				{appendText=" at the prisoner camp next to Alona's Sanctum at Northwind Mine.", stepTextKey="Now to check back with Tovisa and tell her I'm heading into the mine."},
			["Talk to Prisoner Gnarled-Root"] =
				{appendText=" at the prisoner camp next to Alona's Sanctum at Northwind Mine."},
			["Enter Mine"] =
				{appendText=". The entrance should be to the west of Northern Mine."},
			["Find Tovisa 1"] =
				{appendText=" inside the Northwind Mine.", stepTextKey="I have to find Tovisa and get her out of here."},
			["Find Tovisa 2"] =
				{appendText=" inside the Northwind Mine.", stepTextKey="I have to find Tovisa and get her out of here before something terrible happens!"},
		},
		[GetQuestName(3959)] = { -- "Smoke on the Horizon"			-- Westrany
			["Save Soldiers from the Reachmen"] =
				{appendText="\n\nHead out into the fields around Boulderfall Pass and help five Pact Soldiers fight against the Reachmen. \n"},
			["Talk to Captain Jardirr 1"] =
				{appendText=" in a small cave near the battlefield southwest of Boulderfall Pass.\n", stepTextKey="One of the pact soldiers told me that Captain Jardirr has holed up in a small cave near the battlefield. I should find her there and ensure she's safe."},
			["Find Signal Fire"] =
				{appendText=" Tower atop a hill west of Bouldfall Pass.\n"},
			["Light Signal Fire"] =
				{appendText=" outside a tower west of Bouldfall Pass.\n"},
			["Defend the Signal Fire"] =
				{appendText=" you just lit outside a tower west of Bouldfall Pass.\n"},
			["Talk to Captain Jardirr 2"] =
				{appendText=" back at Boulderfall Pass.", stepTextKey="The Rift knows of the danger posed by the Reachmen. I should report in to Captain Jardirr. She said she'd escort her men back to the tower."},
		},
		[GetQuestName(4133)] = { -- "Soul Harvest"					-- NaeomiFriz 
			["Release Souls from Geodes"] =
				{appendText=", strange bags with gems fitting their description have been seen along the path to the northwest of Treva's Farm and to the east of Nimalten."},
			["Free Treva"] =
				{appendText=", who's languished soul has been kept within a cave to the northwest of the farm."},
			["Talk to Treva"] =
				{appendText=", who's freed soul is in a cave northwest of the farm."},
		},
		[GetQuestName(4276)] = { -- "The Troubleshooter"			-- Westrany
			["Kill Linele Skullcarver"] =
				{appendText=" at her camp east of Shor's Stone.\n"},
			["Kill Lolann"] =
				{appendText=" at Linele Skullcarver's Camp, east of Shor's Stone.\n"},
			["Talk to Vaerarre"] =
				{appendText=" back at her camp in the center of Shor's Stone.\n"},
		},
		[GetQuestName(4447)] = { -- "Yngrel the Bloody"				-- Johnyfreeman
			["Kill Yngrel the Bloody"] =
				{appendText=". Medveig said that the bandit leader is somewhere in the hills. There is a mine on the northern edge of Rift, Northwind Mine. Just east of the mine passing a small bridge, there are multiple rocks that provide an ideal hiding spot for bandits to ambush unsuspecting travelers on the nearby roads."},
			["Return to Medveig"] =
				{appendText=". As the hills witnessed Yngred's demise, travelers passing through can now feel a glimmer of safety. Medveig will want to know the news, she is just southeast of Northwind Mines, close to the hunter's camp."},
		},
		[GetQuestName(5011)] = { -- "Beneath the Surface"			-- Johnyfreeman
			["Free Israk"] =
				{appendText=" from his cell, in a corridor in the west, inside Falda's Tooth."},
			["Free Nathon"] =
				{appendText=". The ancient corridors of Faldar's Tooth resound with the echoes of the hammers and chains. A voice can be heard pleading for help in the distance. Nathon must be nearby, in the cave section of the fort."},
			["Talk to Israk in Riften"] =
				{appendText=". After narrowly escaping the danger of the bandits, they are fishing at the docks near the Fighters Guild."},
		},
		[GetQuestName(4167)] = { -- "A Business Proposition"		-- Westrany -- Cyberjanet
			["Talk to Turil 1"] =
				{appendText=", having a meal at the Riverside Inn near the stone staircase in the center of town.", stepTextKey="I told Enthis that I'd retrieve his silk from Turil, his rival. I need to confront Turil, who is in the Riverside Inn in Nimalten."},
			["Find Silk"] =
				{appendText=" in the bandit camp near Grethel's Vigil, west of Nimalten. It's uphill of the wayshrine. The silk is in a bag up some stairs in a ruined tower."},
			["Return Silk to Enthis"] =
				{appendText=", sitting across from Turil at the Riverside Inn. He hired Chanda to attack Turil."},
			["Return Silk to Turil"] =
				{appendText=", sitting across the table from Enthis. He hired Chanda to attack Enthis."},
			["Throw Silk in the Fire"] =
				{appendText=". Enthis and Turil each hired Chanda to attack the other, no matter their reasons. Perhaps the bandit leader should have taken it all."},
			["Talk to Enthis 1"] =
				{appendText=", sitting across from Turil in the Riverside Inn. He hired Chandra to attack Turil.", stepTextKey="I've decided to give the silk to Enthis. I should give him the good news."},
			["Tell Enthis the Bad News"] =
				{appendText=". He's sitting across from Turil at the Riverside Inn."},
			["Tell Turil the Bad News"] =
				{appendText=". He's sitting across from Enthis at the Riverside Inn."},
			["Talk to Turil 2"] =
				{appendText=", having a meal at the Riverside Inn.", stepTextKey="I've destroyed the silk. I should inform Turil."},
			["Talk to Enthis 2"] =
				{appendText=", sitting across from Turil in the Riverside Inn.", stepTextKey="I've destroyed the silk. I should inform Enthis."},
			["Talk to Turil 3"] =
				{appendText=", having a meal at the Riverside Inn.", stepTextKey="I've decided to give the silk to Turil."},
			["Talk to Enthis 3"] =
				{appendText=", sitting across the table from Turil in the Riverside Inn.", stepTextKey="I've decided to give the silk to Enthis. I should give him the good news."},
		},
		[GetQuestName(4320)] = { -- "Fierce Beasts of Ivarstead"	-- NaeomiFriz 
			["Kill Lockjaw"] =
				{appendText=", the foul beast lives within a felled tree northeast of Shroud Hearth Barrow. Beware!"},
			["Talk to Nilwen 1"] =
				{appendText=", who resides in her shack tucked away in rocks east-southeast of Pinepeak Cavern.", stepTextKey="Hmm. Lockjaw wasn't as fierce as I'd been led to believe. I need to talk to Nilwen to clear this up."},
			["Find Greatclaw"] =
				{appendText=", the 'fearsome' beast is east of her shack and east of Pinepeak Cavern."},
			["Report Nilwen for Squatting 1"] =
				{appendText=", I heard that the constable enjoys a good mead every now and again.", stepTextKey="Nilwen asked me to kill a beast called Greatclaw. She claims it killed a man by dropping a tree on him.\n\nShould I look for Greatclaw or report Nilwen in Ivarstead for squatting?"},
			["Talk to Constable Gerrunn"] =
				{appendText=". He's in the Horker's Tusk inn, in Ivarstead proper."},
			["Talk to Nilwen 2"] =
				{appendText=", who resides in her shack tucked away in rocks east-southeast of Pinepeak Cavern.", stepTextKey="Once again, no great beast. Not sure what Nilwen's game is, but I'm going to find out."},
			["Kill Cracktooth"] =
				{appendText=", which should be northeast of the Ragged Hills Dolmen."},
			["Report Nilwen for Squatting 2"] =
				{appendText=", the constable might want to hear about this... He spends a lot of his time in the Inn.", stepTextKey="Nilwen insists Cracktooth, a \"fierce Goblin\" will kill her if I don't intervene.\n\nNot sure if I should seek out Cracktooth or report Nilwen in Ivarstead."},
			["Talk to Nilwen 3"] =
				{appendText=", she should still be squatting in 'her' shack east-southeast of Pinepeak Caverns.", stepTextKey="Cracktooth turned out to be a giant. I'm going to wring the truth out of Nilwen this time."},
			["Talk to Nilwen 4"] =
				{appendText=", she's out in a shack east-southeast of Pinepeak Caverns.", stepTextKey="Time to confront Nilwen and claim my reward, if there is one."},
		},
		[GetQuestName(4248)] = { -- "Geirmund's Guardian"			-- Johnyfreeman
			["Talk to Thane Vofknir 1"] =
				{appendText=". He is in front of the Feasting Hall, the big house in the middle of the island, and seems to be enjoying the festival.", stepTextKey="I should speak to the Thane at Geirmund's Hall."},
			["Complete the Trial of the Body"] =
				{appendText=". Daljari is standing by the roadside next to a backpack and a sleeping bag, near the cave west of the Feasting Hall."},
			["Complete the Trial of the Spirit"] =
				{appendText=". Widulf is in a white and orange tent not far southwest of the Feasting Hall, praying to Kyne."},
			["Complete the Trial of the Mind"] =
				{appendText=". Iroda, immersed in her reading, is in a red tent with the bookshelves, southwest of the Feasting Hall."},
			["Talk to Thane Vofknir 2"] =
				{appendText=", he is standing in front of the manor of Geirmund's Hall.", stepTextKey="I completed the three challenges. I should speak to the Thane."},
			["Follow Thane Vofknir"] =
				{appendText=" inside the Feasting Hall, the big house in Geirmund's Hall, he will be waiting in the balcony."},
			["Listen to the Thane's Speech"] =
				{appendText=" in the balcony of the Feasting Hall."},
			["Talk to Runehild"] =
				{appendText=" just outside the Feasting Hall. She appears visibly frightened and exhausted, something serious must have occurred."},
		},
		[GetQuestName(4249)] = { -- "Trial of the Body"				-- Johnyfreeman
			["Win Fights"] =
				{appendText=". Finding an opponent in Geirmund's Hall shouldn't be a challenge. There are several fighters eager to show their strength on the northwestern side of the island."},
			["Talk to Daljari 1"] =
				{appendText=" again, she is on the roadside west of the cave in the middle of Geirmund's Hall.", stepTextKey="I need to report back to Daljari, tell her how I did."},
			["Defeat a Champion"] =
				{appendText=". Alongside the other fighters, there are a few champions who have come to Gerimund's Hall to join the festival. Near the cave in the middle of the island are Maeri and Makoll. Near the river, admiring the landscape, is Olveidi. Votar is a short walk from the southwestern bridge and Gjoson is close to the northwestern bridge, writing."},
			["Talk to Daljari 2"] =
				{appendText=" again near the road to the west of the cavern in the middle of Geirmund's Hall.", stepTextKey="I've done it. I defeated the champion. I should speak to Daljari."},
		},
		[GetQuestName(4250)] = { -- "Trial of the Mind"				-- Johnyfreeman
			["Find Answer to the First Riddle"] =
				{appendText=". The answer lies somewhere around Geirmund's Hall.\n\nOn the other hand, Keema-Ta, an Argonian near the entrance of Iroda's tent, the red tent southwest of the Feasting Hall, appears to have something to share."},
			["Talk to Iroda 1"] =
				{appendText=" in her tent, the red tent southwest of the Feasting Hall in Geirmund's Hall.", stepTextKey="The answer to the first riddle is \"Mirror.\" I need to return to Iroda to give her my answer."},
			["Find Answer to the Second Riddle"] =
				{appendText=" somewhere around Geirmund's Hall.\n\nOnce again, the Argonian Keema-Ta claims that he knows the answer. He is still near Iroda's tent, the red tent with the bookshelves, southwest of the Feasting Hall."},
			["Talk to Iroda 2"] =
				{appendText=" in her tent, the red tent southwest of the Feasting Hall of Geirmund's Hall.", stepTextKey="The answer to the riddle is \"Water.\" I should head back to Iroda."},
			["Find the Answer to the Last Riddle"] =
				{appendText=", again around Gerimund's Hall.\n\nKeema-Ta can help with that, he remains near Iroda's tent."},
			["Talk to Iroda 3"] =
				{appendText=" again, she remains at her tent, the red one, southwest of the Feasting Hall in Geirmund's Hall.", stepTextKey="The answer to the third riddle is \"Map.\" I should return to Iroda to finish my Trial."},
		},
		[GetQuestName(4251)] = { -- "Trial of the Spirit"			-- Johnyfreeman
			["Drink Widulf's Mead Outside the Tent"] =
				{appendText=". Widulf tent is the only one with different colors from the other tents around Geirmund's Hall."},
			["Reach First Spirit Fire"] =
				{appendText=""},
			["Reach Next Spirit Fire"] =
				{appendText=""},
			["Reach Final Spirit Fire"] =
				{appendText=""},
			["Talk to Widulf"] =
				{appendText=". Having traversed the entire place running and swimming in pursuit of peculiar blue fires, it's time to return. Widulf is near the road just south of the wooden bridge located on the northern side of the Geirmund's Hall island."},
		},
		[GetQuestName(4253)] = { -- "Geirmund's Oath"				-- Johnyfreeman
			["Talk to Aelm"] =
				{appendText=" in the building west of the Feasting Hall. She is standing in the door with her arms crossed. The smell of alcohol from the place fills the air."},
			["Win Drinking Contest"] =
				{appendText=""},
			["Talk to Eirfa 1"] =
				{appendText=". She is on the side of the building west of the Feasting Hall.", stepTextKey="I've survived the drinking contest and should speak to Eirfa."},
			["Drink the Potent Brew"] =
				{appendText=" that is in a barrel near the stage not far from the building west of the Feasting Hall."},
			["Recite Geirmund's Oath"] =
				{appendText=" on the stage near the building west of the Feasting Hall."},
			["Talk to Eirfa 2"] =
				{appendText=". She is on the side of the building west of the Feasting Hall.", stepTextKey="I've done it. I should talk to Eirfa."},
		},
		[GetQuestName(4332)] = { -- "Prisoner Dilemma"				-- ARKANOBOT
			["Free the Loyal Prisoners"] =
				{appendText="\n\nLook for the Interrogation Transcripts and the Prisoners at the camp to the southeast"},
