		},
		[GetQuestName(974)]  = { -- "A Duke in Exile"				-- NaeomiFriz
			["Talk to Lieutenant Harim"] =
				{appendText=". The Lighthouse is overrun, I should check the swamp around it for the Lieutenant."},
			["Find Duke Sebastien"] =
				{appendText=" in the Aldcroft Lighthouse."},
			["Free Duke Sebastien by Destroying Crystals"] =
				{appendText=""},
			["Talk to Duke Sebastien 1"] =
				{appendText=" at the top of Aldcroft lighthouse.", stepTextKey="When I destroyed the crystals, the enchantment holding the Duke prisoner was broken. Now the Duke wants to speak with me."},
			["Free the Second Prisoner"] =
				{appendText=", I should check the houses near the Aldcroft Lighthouse."},
			["Talk to Duke Sebastien 2"] =
				{appendText=", he should be in his temporary command.", stepTextKey="At the Duke of Camlorn's request, I rescued a second prisoner from the Bloodthorn cult, Gloria Fausta. I should make sure that Duke Sebastien made it back to Aldcroft."},
		},
		[GetQuestName(3013)] = { -- "Wolves in the Fold"			-- NaeomiFriz
			["Reveal and Defeat Hidden Werewolves"] =
				{appendText="\nThe refugees are massed at the docks, I should look there."},
			["Talk to Duke Sebastien"] =
				{appendText=", he should be in his temporary command."},
		},
		[GetQuestName(3018)] = { -- "Lineage of Tooth and Claw"		-- NaeomiFriz
			["Talk to Sergeant Armoil Viranes"] =
				{appendText=". He is training his soldiers on the north side of Aldcroft."},
			["Capture a Werewolf"] =
				{appendText=" with Lexi. They've infested the swamp north of Aldcroft."},
			["Take the Werewolf to the Cave"] =
				{appendText="."},
			["Find Gloria Fausta in the Cave"] =
				{appendText=" northeast of the Aldcroft docks."},
			["Perform the Ritual with Gloria Fausta"] =
				{appendText=". She's in the cave northeast of the Aldcroft docks."},
			["Talk to Gloria Fausta 1"] =
				{appendText=" in the cave northeast of the Aldcroft docks.", stepTextKey="The ritual revealed Angof's role in Faolchu's return from the dead. I should talk to Gloria Fausta about what we've seen."},
			["Listen to Werewolf"] =
				{appendText=" in the cave northeast of the Aldcroft docks."},
			["Talk to Gloria Fausta 2"] =
				{appendText=" in the cave northeast of the Aldcroft docks.", stepTextKey="The werewolf said that when the Duke of Camlorn was captured, he was infected with lycanthropy. I should speak with Gloria about this revelation."},
			["Cure Duke Sebastien"] =
				{appendText=""},
			["Talk to Duke Sebastien 1"] =
				{appendText=", in his temporary command in Aldcroft.", stepTextKey="Gloria's blood cured the Duke. At least she didn't die in vain. Now that the Duke has recovered, I should speak with him."},
			["Talk to Duke Sebastien 2"] =
				{appendText=" in front of his residence.", stepTextKey="We can't let Gloria sacrifice herself to cure the Duke. I should return to Aldcroft and confront the Duke before he transforms into a werewolf."},
			["Talk to Gloria Fausta 3"] =
				{appendText=". she's on the streets of Aldcroft.", stepTextKey="I decided to spare the Duke. Gloria has taken him prisoner. I should speak with her about my decision."},
			["Talk to Gloria Fausta 4"] =
				{appendText=" outside the duke's residence in Aldcroft.", stepTextKey="The Duke of Camlorn is dead. He tranformed into a werewolf and left me no choice. I should speak with Gloria Fausta about the Duke's death."},
			["Talk to Gloria Fausta 5"] =
				{appendText=" outside the duke's residence in Aldcroft.", stepTextKey="The Duke of Camlorn is dead. He transformed into a werewolf and left me no choice. I should speak with Gloria Fausta about the Duke's death."},
			["Kill Duke Sebastien"] =
				{appendText=" inside his residence in Aldcroft."},
		},
		[GetQuestName(3184)] = { -- "The Glenumbra Moors"			-- NaeomiFriz
			["Go to Glenumbra Moors"] =
				{appendText=", they are to the northwest of Aldcroft."},
			["Talk to the Mages Guild at Glenumbra Moors"] =
				{appendText=" northwest of Aldcroft. One of their envoys is within the rough camp built near to their entrance."},
		},
		[GetQuestName(3027)] = { -- "Ripple Effect"					-- NaeomiFriz
			["Collect the Blades of the Alessian Generals"] =
				{appendText=". I see their ghosts mark where they had fallen along the path."},
			["Bring Blades to Sarvith Yunlin"] =
				{appendText=", they are the camp at the entrance of the moors."},
			["Talk to Sarvith Yunlin"] =
				{appendText=", they are the camp at the entrance of the moors."},
			["Talk to Grahla"] =
				{appendText=", they are the camp at the entrance of the moors."},
			["Examine the Time Ripples"] =
				{appendText=" in the Moor, I can scry through their purple glow by getting close."},
			["Find the Crypt"] =
				{appendText=", its old stone peaks through a sidepath of the moors."},
			["Talk to the Spirit of Alana"] =
				{appendText=" which remains in the dusty crypt off the side path in the moors."},
		},
		[GetQuestName(3047)] = { -- "A Step Back in Time"			-- NaeomiFriz
			["Put on the Direnni Armor"] =
				{appendText=". The crypt is off a side path in Glenumbra Moors."},
			["Talk to Alana Relin"] =
				{appendText=", she's at the bottom of the stairs of the crypt off the side path of Glenumbra Moors."},
			["Find Alessian Orders"] =
				{appendText=", in the camp on the path into Glenumbra Moors."},
			["Go to the Direnni Camp"] =
				{appendText=", at the start of the path going into Glenumbra Moors."},
			["Talk to Commander Parmion"] =
				{appendText=" at the start of the path going into Glenumbra moors"},
			["Talk to King Laloriaran Dynar"] =
				{appendText=", he is in the Direnni camp, his bodyguards flanking him at the start of the path leading into Glenumbra moors."},
			["Talk to Alana"] =
				{appendText=". She is in a tent at the Direnni camp at the start of the path leading into Glenumbra moors."},
			["Listen to Parmion's Speech"] =
				{appendText=". I see him at the fire in the Direnni camp, just at the start of the path leading futher into the Glenumbra Moors."},
			["Defeat the Alessian Shadow Scouts"] =
				{appendText=".\nI hear muffled voices just southeast of the gate marking the start of the Glenumbra Moors.\n\nI see a glow to the northwest of the gate, as well.\n\nAt the top of the hill which the crypt lies off the side path, I can see a figure."},
			["Find Faolchu's Lair"] =
				{appendText=", I heard the scout murmur as he died, about the lair's entrance being somewhere along the main path."},
		},
		[GetQuestName(3049)] = { -- "The Nameless Soldier"			-- NaeomiFriz
			["Rescue Alana"] =
				{appendText=", I should talk to Scout Hanil and have his soldiers fight Faolchu if I go this route. He and his soldiers are outside Faolchu's lair, just off a path in the main route through Glenumbra Moors."},
			["Kill Faolchu 1"] =
				{appendText=", I should tell Hanil if I intend to fight Faolchu myself.", stepTextKey="I need to decide my next course of action. Do I go after Faolchu or should I try to save Alana and leave Faolchu to the remaining soldiers?"},
			["Find Alana In the Enemy Camp"] =
				{appendText=", it's at the end of the path in Glenumbra Moors. I should find her in the tower."},
			["Use Fire to Defeat Faolchu"] =
				{appendText=". He's at the end of his lair, its entrance is off the path in Glenumbra Moors."},
			["Return to the Present 1"] =
				{appendText=". There is a portal that will end the spell in Faolchu's Lair, the entrance of which is off the main path in Glenumbra Moors.", stepTextKey="The fire worked and Faolchu has been slain. The spirit of the knight whose place I took appeared before me and told me to use the nearby portal to return to the present."},
			["Talk to the Mages Guild"] =
				{appendText=", their envoys are outside a crypt off a side path in Glenumbra Moors."},
			["Kill Faolchu 2"] =
				{appendText=", the doors are off the main path in Glenumbra Moors. He's at the end of the Lair.", stepTextKey="I decided to deal with Faolchu personally. His lair is through the large doors ahead of me. I'm still not sure what his weakness is, but he died once in this time frame. I'll find a way to kill him again."},
			["Return to the Present 2"] =
				{appendText=". There is a portal that will end the spell in Faolchu's Lair, the entrance of which is off the main path in Glenumbra Moors.", stepTextKey="Fire was the answer and Faolchu has been slain. The spirit of the knight whose place I took appeared before me and told me to use the nearby portal to return to the present."},
			["Leave the Crypt and Talk to Sarvith"] =
				{appendText=". He's outside a crypt off a side path in Glenumbra Moors."},
			["Talk to Grahla 1"] =
				{appendText=", she's at the camp at the entrance of the path through Glenumbra Moors.", stepTextKey="I should let Grahla know about Faolchu's weakness as soon as possible."},
			["Talk to Grahla 2"] =
				{appendText=", she's at the camp at the entrance of the path through Glenumbra Moors.", stepTextKey="I should let Grahla know about Faolchu's weakness as soon as possible."},
			["Talk to Grahla 3"] =
				{appendText=" and Alana. I seem to have altered the timeline. I should find out what's changed and tell them Faolchu's weakness. I can find them at the camp at the entrance of the path through Glenumbra Moors.", stepTextKey="I need to speak to a mage named Alana. Could she somehow be related to the Alana I saved in the past? I should talk to her and find out."},
		},
		[GetQuestName(3330)] = { -- "Retaking Camlorn"				-- NaeomiFriz
			["Find the Lion Guard Soldiers at Camlorn"] =
				{appendText=", they're on the road between the Moors and Camlorn, at the southeaster gate of the city's forward siege camp."},
		},
		[GetQuestName(3064)] = { -- "Rally Cry"						-- NaeomiFriz
			["Help Shaza Reclaim the Siege Camp"] =
