			["Talk to General Gautier 1"] =
				{appendText=" just south of the main gate.", stepTextKey="I should find General Gautier and let him know that I fought through to General Mandin. She still has almost a full contingent of soldiers to lend to the cause."},
			["Lock the Main Camlorn Gate"] =
				{appendText=", I should find the mechanism through a hatch in the bottom of the north courtyard tower."},
			["Talk to General Gautier 2"] =
				{appendText=" in the city's southern courtyard.", stepTextKey="I locked Camlorn's main gate. I should let General Gautier know I was successful."},
			["Talk to General Gautier 3"] =
				{appendText=" in the city's southern courtyard.", stepTextKey="I locked Camlorn's main gate. I should let General Gautier know I was successful."},
		},
