		[GetQuestName(3017)] = { -- "Back-Alley Murders"			-- Westrany
			["Search the South Trade District Alley"] =
				{appendText=" for clues of the brutal murders.\n\nYou might want to check the road behind Captain Margaux's Place.\n"},
			["Search the West Trade District Alley"] =
				{appendText=" for more clues.\n\nThe West Trade District is just south of the Bank of Daggerfall.\n"},
			["Investigate the River"] =
				{appendText=" northwest of the Rededication Shrine.\n\n\n"},
			["Talk to Lieutenant Dubois"] =
				{appendText=" at the plaza in front of the Mages Guild.\n\nAccording to Matthew, the Lieutenant might reward you for dealing with the werewolf.\n"},
		},
		[GetQuestName(4088)] = { -- "Can't Take It With Them"		-- Johnyfreeman
			["Recover Ceremonial Gems"] =
				{appendText=". In addition to the bones of the unfortunate ones who were sacrificed and the skeletons that still roam the dark tunnels, there are new skeletons scattered everywhere in the central and southern part. These skeletons still have the gems that were used to summon the Dremora."},
			["Return to Finvir"] =
				{appendText=" in the eastern tunnel near a hole in the ground that provides access to the tunnel leading west."},
		},
		[GetQuestName(4535)] = { -- "The Dagger's Edge"				-- Westrany
			["Talk to Bumnog 1"] =
				{appendText=" the mercenary Orc.\n", stepTextKey="One member of the Daggers did make it back to camp. Lord Diel and his sons have asked me to help Bumnog find the Daggers and finish their job. I should talk to Bumnog and get more information."},
			["Assist the Remly Brothers"] =
				{appendText=" on a hill southwest of Shriking Scar. \n"},
			["Assist Gelvin"] =
				{appendText=" along the inner curve of a crescent-shaped road winding up a hillside, northeast of Shrieking Scar. The leader of the Daggers, Gelvin Feldrin, has been tasked with gathering unhatched Eggs from Harpies at their nests.\n"},
			["Defeat the Harpy Matriarch, Foulwing"] =
				{appendText=", up a western hill overlooking her kind. Rumor has it that the Harpy Matriarch remains hidden until the very last moment, ambushing unsuspecting travelers with her razor-sharp claws. You will know you are close when you find traces of her brutal activities."},
			["Return to Camp"] =
				{appendText=" east of Shriking Scar with Bumnog."},
			["Talk to Bumnog 2"] =
				{appendText=" on the outskirts of the Daggers camp.", stepTextKey="I should stop and see what Bumnog wants to talk about."},
			["Talk to Lord Diel 1"] =
				{appendText=" at the heart of the Daggers camp, east of Shrieking Scar.", stepTextKey="Bumnog let me know that he expects the Daggers to get paid, no matter what Lord Diel is actually up to. I should speak to Lord Diel back at the camp and let him know that his research has been collected."},
			["Talk to Granette"] =
				{appendText=" Feldrin by the fire of the Daggers camp about the whereabouts of her brother, Gelvin.\n\nBumnog's suspicion, the harpy cruelty you witnessed, and the harsh instructions Lord Diel gave you start to stir something within your mind. What is Lord Alain Diel hiding from you?"},
			["Investigate the Fishing House"] =
				{appendText=" on an island west of Shrieking Scar."},
			["Tell Gelvin to Finish the Job"] =
				{appendText="."},
			["Tell Gelvin to Confront Lord Diel"] =
				{appendText="."},
			["Talk to Lord Diel 2"] =
				{appendText=" outside the Fishing House on the island west of Shrieking Scar.", stepTextKey="I agreed to help Gelvin deal with Lord Diel. I need to talk to Diel and keep him distracted while Gelvin figures out how to make his lordship pay."},
			["Talk to Bumnog 3"] =
				{appendText=" by the Fishing House on the island west of Shrieking Scar.", stepTextKey="Lord Diel was killed by one of the harpies he was planning to sell on the open market after Gelvin set it free. The Daggers are finished here and they won't be getting paid. I should tell Bumnog what happened."},
			["Talk to Gelvin 1"] =
				{appendText=" back at the mainland shore, west of Shrieking Scar.\n\nGelvin awaits you at the beach closer to the island, surrounded by seaweed and his fellow Daggers.", stepTextKey="Bumnog managed to snatch a small bag of gems from Lord Diel's camp. It doesn't completely cover the pay the Daggers were promised, but it should be enough to keep them going. I should speak to Gelvin."},
			["Talk to Gelvin 2"] =
				{appendText=" back at the mainland shore, west of Shrieking Scar.\n\nGelvin seems quite happy and in his happiness seems to have gotten something for you.", stepTextKey="Bumnog managed to snatch a small bag of gems from Lord Diel's camp. It doesn't completely cover the pay the Daggers were promised, but it should be enough to keep them going. I should speak to Gelvin."},
			["Give the Egg to Lord Diel"] =
				{appendText=" on the pier outside the Fishing House, on the island west of Shrieking Scar."},
			["Talk to Lord Diel 3"] =
				{appendText=" on the pier outside the Fishing House, on the island west of Shrieking Scar.", stepTextKey="I convinced Gelvin to ignore the evidence against Lord Diel and just finish the job so the Daggers can get paid. I'll meet him outside after I give the fifth harpy egg to Lord Diel."},
		},
		[GetQuestName(3003)] = { -- "Disorganized Crime"			-- Westrany
			["Find the Hunting Horn"] =
				{appendText=" Case in the Noellaume Estate at Red Rook Camp.\n"},
			["Burn the Longboat"] =
				{appendText=" on the small pier southeast of Red Rook Camp.\n"},
			["Burn the Archery Platform"] =
				{appendText=" west of Red Rook Camp.\n"},
			["Disarm Red Rook Traps"] =
				{appendText=" scattered around the camp.\n"},
			["Sound the Hunting Horn"] =
				{appendText=" to distract the bandits of Red Rook Camp.\n"},
			["Talk to Captain Farlivere"] =
				{appendText=" back at the road bifurcation southwest of Red Rook Camp.\n\nCaptain Farlivere stands besides a broken supplies cart.\n"},
		}, 
		[GetQuestName(3322)] = { -- "The Dresan Index"				-- Johnyfreeman
			["Find Evoker Valinwe in Aldcroft"] =
				{appendText=" Mages Guild tent."},
			["Talk to Evoker Valinwe"] =
				{appendText=""},
		},
		[GetQuestName(3001)] = { -- "Farlivere's Gambit"			-- Westrany
			["Talk to Captain Farlivere"] =
				{appendText=" by a broken cart on the road fork southwest of Red Rook Camp.\n"},
			["Find a Red Rook Keyring"] =
				{appendText=" kept by one of the bandits at Red Rook Camp.\n"},
			["Collect Wolf's Woe"] =
				{appendText="\n\nWolf's Woe is a bush with small red flowers which can be found growing in Glenumbra. When the plant is crushed, it produces an odor which scent-sensitive creatures like wolves will actively try to avoid.\n\nYou can find these bushes growing all over Red Rook Camp.\n"},
			["Find the Hostages"] =
				{appendText=" inside the Noellaume Estate at Red Rook Camp.\n"},
		},
		[GetQuestName(3315)] = { -- "The Hidden Treasure"			-- Johnyfreeman
			["Collect Dusant's Backpack"] =
				{appendText=" on the bridge just south of Dresan Keep."},
			["Make Offerings to the Heralds"] =
				{appendText=". Within the ruins, three statues stand, worn by the relentless jaws of time.  Three Heralds, the Herald of Illumination, the Herald of Thirst and Herald of Memory. The first one rests beside a skyshard in the eastern side of the ruins. The second, now broken, rests not too far from the bridge. The third rests near a broken arch, close to a old tower."},
			["Find the Old Well"] =
				{appendText=" at the heart of the ruins, in the midst of the road just north of the bridge."},
			["Search the Underground Vault"] =
				{appendText=""},
			["Talk to the Keeper of Knowledge"] =
				{appendText=". A ghostly specter in the corridor old and dusty of Dresan Keep vaults, lost in time's decay."},
			["Return to Richard Dusant"] =
				{appendText=" in the bridge southern side of the ruins."},
			["Talk to Richard Dusant"] =
				{appendText=". His ghostly figure remains near his body, on the southern bridge of Dresan Keep."},
		},
		[GetQuestName(3004)] = { -- "Lady Eloise's Lockbox"			-- Westrany
			["Find the Gilded Lockbox"]=
				{appendText=" in a barn north of the Noellaume Estate at Red Rook Camp.\n"},
			["Talk to Lady Noellaume"]=
				{appendText=" on the road bifurcation west of Red Rook Camp's barn, near Captain Farlivere.\n"},
		},
		[GetQuestName(3414)] = { -- "Legacy of Baelborne Rock"		-- Westrany
			["Search the Ruins"] =
				{appendText=" on Baelborne Rock.\n\nClimb the first set of stairs on the road and look behind the broken wall to find a pile of suspicious-looking rubble.\n\nTurn west, and climb another set of stairs. At the landing, turn left and search the next pile.\n\nThe last pile is up the next set of stairs, near the base of an old tower at the tallest point of the ruins.\n"},
			["Investigate the Tower"] =
				{appendText=" where Claudie spent her last days.\n\nThe tower is on the west side of Baelborne Rock.\n\n"},
			["Inform Athel of Your Findings"] =
				{appendText=".\n\nAthel stands by a fire on the road north of Baelborne Rock Wayshrine.\n"},
			["Find a Book About Spirit Summoning"] =
				{appendText=" inside the Mages Guild hall in Daggerfall.\n\nEilina, a Redguard magus, might help you find some books.\n"},
			["Talk to the Cloaked Man"] =
				{appendText=", Tsiniuc, that approached you as you read the book on spirits at Daggerfall's Mages Guild.\n"},
			["Talk to Claudie Themond 1"] =
				{appendText="'s ghost at the graveyard behind Daggerfall's Cathedral.\n", stepTextKey="Claudie's ghost has appeared nearby. I should speak to her."},
			["Break the Curse"] =
				{appendText=" by examining a small Daedric Warding Stone at the base of a waterfall west from the stone of The Lady, northeast of Daggerfall.\n"},
			["Tell Athel Baelborne to Leave"] =
				{appendText=".\n\nAthel is around a ruined tower northeast of Baelborne Rock.\n"},
			["Talk to Athel Baelborne"] =
				{appendText=" inside the tower north of the stone of The Lady.\n"},
			["Find Athel Baelborne"] =
				{appendText=".\n\nYou saw Athel run towards the cliff overlooking the Vale of the Guardians.\n"},
			["Talk to Claudie Themond 2"] =
				{appendText=" at the edge the cliff overlooking the Vale of the Guardians.\n\nClaudie stands beside a Dremora called Tachnim, Tsiniuc's mysterious master.\n\nLooking down from the cliff, you find an unsettling sight.\n", stepTextKey="Athel Baelborne's dead. I should talk to Claudie."},
			["Bury Claudie's Items in the Themond Mine"] =
				{appendText=", west of the Rededication Shrine in Daggerfall.\n"},
					["Talk to Claudie Themond 3"] =
				{appendText=" by the exit of Themond Mine, west of the Rededication Srine in Daggerfall."},
		},
		[GetQuestName(3437)] = { -- "A Mysterious Curio"			-- Westrany
			["Read the Scroll"] =
				{appendText=" you found inside the first cell on the left of Dresan Keep.\n"},
			["Open the Ancient Coffer"] =
				{appendText=" inside the first cell on the left of Dresan Keep.\n"},
			["Talk to the Ayleid Ghost 1"] =
				{appendText=" inside the first cell on the left of Dresan Keep.\n", stepTextKey="When I opened the ancient coffer, a ghost appeared before me. I should speak with this spirit and see what it wants."},
			["Look for a Way to Communicate"] =
				{appendText=" with the ghost.\n\nA certain reliquary inside one of the chambers might help you.\n"},
			["Talk to the Ayleid Ghost 2"] =
				{appendText=" and see if touching the golden tongue pendant helps you understand the ghost's language.\n\nThe Ayleid ghost is inside the first cell on the left of Dresan Keep.\n", stepTextKey="I found a pendant shaped like a golden tongue. It disintegrated when I touched it, but not before I heard magical whispers all around me. I should return and see if I can communicate with the ghost now."},
			["Destroy the Binding Artifacts"] =
				{appendText="\n\nThe artifacts are scattered around the cells of Dresan Keep.\n"},
			["Talk to the Ayleid Ghost 3"] =
				{appendText=" and let him know you have successfully destroyd the artifacts. \n\nThe Ayleid Ghost is inside the first cell on the left of Dresan Keep.\n", stepTextKey="I destroyed the artifacts used to bind the Ayleid spirit. I should return to him and let him know I was successful."},
			["Talk to the Ayleid Ghost 4"] =
				{appendText=" and see him on his way to explore Tamriel.\n\nThe Ayleid Ghost is inside the first cell on the left of Dresan Keep.\n", stepTextKey="I convinced the Ayleid spirit to explore modern Tamriel. Now he can see what Glenumbra has become after the defeat of the Alessians. I should talk to him a final time and see him on his way."},
			["Talk to the Ayleid Ghost 5"] =
				{appendText=" a final time and urge him on his way to Aetherius.\n\nThe Ayleid Ghost is inside the first cell on the left of Dresan Keep.\n", stepTextKey="I convinced the Ayleid spirit to pass on to Aetherius and leave this world behind.\n\nI should talk to him a final time and urge him on his way."},
		},
		[GetQuestName(4529)] = { -- "Red Rook Resources"			-- Devinstrike
			["Talk to a Daggerfall Guard Near the Manor"] =
				{appendText=" on the road north of Deleyn's Mill and warn them of the impending assault before they're caught ill-prepared.\n"},
		},
		[GetQuestName(4080)] = { -- "Season of Harvest"				-- Johnyfreeman
			["Collect Apples"] =
				{appendText=". As an offering, people bring a range of fruits and other products from their harvests. Baskets with apples are scattered around the big tree.\n"},
			["Collect Grain"] =
				{appendText=". There are small sacks of grains in a tent near the tree."},
			["Place the Offerings"] =
				{appendText=". Around the tree many scrolls are scattered. Two bowls are mark the place of the offering altar."},
			["Watch the Ceremony"] =
				{appendText=" near the big tree."},
			["Talk to Curator Nicholas"] =
				{appendText=". Fire burs the offerings. After the strange cerimony, the Curator waits near the trees."},
			["Throw Dirt in the Fire"] =
				{appendText=". The fervent blaze's warmth dances, enveloping the oferings in the altar in a shroud of ravenous hunger."},
			["Search the Tunnels"] =
				{appendText=". Amidst the thorny roots a woman in a blue dress apears to be trapped at the entrance of the tunnels."},
			["Free Eveline Vette"] =
				{appendText=". The is a dead Shalk not far away, just southeast of the bone pile of the unfortunate ones who were sacrificed before. The inflammable gland can help release Eveline by burning the roots."},
			["Talk to Eveline Vette 1"] =
				{appendText=". After the roots were consumed by the fire's embrace. A haunting sound of anguish echoed through the tunnels. Eveline may know more about this strange place, she is near the water close to the eastern tunnel entrance.", stepTextKey="Eveline Vette is free of the roots. I should speak to her and find out just what's going on here."},
			["Burn Newly Grown Roots"] =
				{appendText=". Shalks roam around the tunnels, their flammable glands will be useful against the small thorny roots that grow in the place."},
			["Talk to Eveline Vette 2"] =
				{appendText=", she is waiting near a portal in the southern end of the tunnel.", stepTextKey="Eveline Vette is waiting for me to return with good news. I should speak to her."},
			["Defeat the Bad Man"] =
				{appendText=". The portal to leave is in the southern edge of the tunnels. The Dremora killed all the cultists around, but Nicholas managed to survive. He is near a rock to the north of the tree."},
			["Talk to Eveline Vette 3"] =
				{appendText=". With the defeat of the Dremora who was posing as Bad Man, Glenumbra is a little safer not. Eveline is near a portal north of the tree.", stepTextKey="The Bad Man has been destroyed. I should tell Eveline Vette."},
		},
		[GetQuestName(3416)] = { -- "Signals of Dominion"			-- Westrany
			["Collect Dominion Messages"] =
				{appendText=" at their command camp across from the tower, northeast of the Farwatch Wayshrine.\n\nThe messages can be found at an Aldmeri Strongbox inside a tent.\n"},
			["Talk to Captain Gilame 1"] =
				{appendText=" besides a bridge the base of Farwatch tower, just west of the Dominion Camp.\n", stepTextKey="I managed to intercept the Dominion's messages. I should find Captain Gilame near the tower and give them to her."},
			["Douse the Fires Atop the Tower"] =
				{appendText=" northwest of Farwatch Wayshrine.\n"},
			["Talk to Captain Gilame 2"] =
				{appendText=" at the bottom of the staircase northeast of Farwatch Tower.\n", stepTextKey="I doused the signal fires atop Farwatch Tower. I should find Captain Gilame at the base of the tower and find out if that prevented the Dominion's attack."},
		},
		[GetQuestName(3011)] = { -- "Swine Thief"					-- Westrany
			["Talk to Gregoire Lafont"] =
				{appendText=" at the Rosy Lion inn, just northeast of where you met swineherd Wickton.\n"},
			["Find Northeast Alley"] =
				{appendText=".\n\nLeave the inn and go east from the entrance. When you pass pigs inside of a wooden fence, turn northeast and head down the street next to the houses.\n"},
			["Grab Glutton"] =
				{appendText=", a pig standing against the east wall next to a dead body and some vines poking out of the ground. \n"},
			["Talk to Swineherd Wickton"] =
				{appendText=" back at his pig pen south of the Rosy Lion Inn.\n"},
			["Talk to Zhagush gro-Korlag"] =
				{appendText=" outside of the Mages Guild.\n"},
		},
		[GetQuestName(3440)] = { -- "Wayward Scouts"				-- Johnyfreeman
			["Find Recruit Sorais"] =
				{appendText=". Northwest of the Wyrd Tree, Farwatch Tower rises on the horizon. Near the path leading south, across the bridge, someone appears to be trying to avoid detection.\n"},
			["Find Recruit Helene"] =
				{appendText=". Close to the wooden bridge, someone seems to be trying to hide near a tree."},
			["Rescue Recruit Cecile"] =
				{appendText=". Two Dominion ships can be seen not far from Farwatch Tower on the eastern coast of Glenumbra, their camp must be nearby."},
			["Talk to Recruit Cecile"] =
				{appendText=" near the blocked door on the northern side of the tower. Farwatch Tower stands imposingly on the eastern coast of Glenumbra."},
		},
		[GetQuestName(4531)] = { -- "A Brush With Death"			-- Westrany
			["Talk to Odette Vinielle"] =
				{appendText=", a Breton member of the Mages Guild, and return her journal.\n\nOdette is at Glenumbra Moors, northwest of Aldcroft.\n"},
		},
		[GetQuestName(3039)] = { -- "Crocodile Bounty"				-- Westrany
			["Read the Note"] =
				{appendText=" besides the body of the dead mercenary on the road north of The Wolf's Camp.\n"},
			["Collect Crocodile Teeth"] =
				{appendText="\n\nTwo to three crocodiles should suffice to collect the twenty five teeth, including the five already gathered by the mercenary, needed to turn in the bounty.\n"},
			["Find Hoster Marceau near Dwynnarth Ruins"] =
				{appendText=", north of Hag Fen.\n\nHoster Marceau is in a small camp between Lion Guard Redoubt and the ruins.\n"},
		},
		[GetQuestName(4341)] = { -- "Cutting Off the Source"		-- Westrany
			["Talk to Tamien Sellan 1"] =
				{appendText=" in his house overlooking the sea.", stepTextKey="Merien Sellan outlined a plan to stop the Bloodthorn. I should speak to his son, Tamien Sellan, and get his thoughts."},
			["Burn Bloodthorn Boats"] =
				{appendText=". The cultists are swarming the docks and beachhead. They won't give up their vessels without a battle.\n"},
			["Return to Sellan House"] =
				{appendText=" and discover the fate of the Tamiens.\n"},
			["Talk to Tamien Sellan 2"] =
				{appendText="\n", stepTextKey="I returned to the Sellan family home. Tamien is inside, beside his father's body. I should speak with him."},
			["Talk to Dame Clarique 1"] =
				{appendText=" at the east of town. With the Bloodthorn cornered, she and her men should have been able to cut down the fleeing cultists.", stepTextKey="Tamien Sellan asked me to speak with Dame Clarique while he buries his father. She'll want to hear about the victory over the Bloodthorn."},
			["Enter the Bloodthorn House"] =
				{appendText=". Amid the ruined structures lies only one other house still intact.\n"},
			["Enter the Pocket Plane"] =
				{appendText=". A slight vibration moves through the floor. Magic stirs within the basement.\n"},
			["Find Merien Sellan"] =
				{appendText=" before the plane collapses. I can enter the plane through a portal in the Bloodthorn occupied house in town."},
			["Kill the Shade of Lord Velian"] =
				{appendText="\n"},
			["Talk to Merien Sellan"] =
				{appendText=" and assess his condition. You can find him in a pocket plane entered through a portal in the Bloodthorn occupied house in town."},
			["Return to Eagle's Brook"] =
				{appendText=" and collapse the Daedric plane found in the Bloodthorn occupied house in town."},
			["Talk to Tamien Sellan 3"] =
				{appendText=" in the Bloodthorn occupied house and inform him of your success.\n", stepTextKey="I made it back, and Merien is with me. I should speak to Tamien, who's waiting for us."},
			["Talk to Dame Clarique 2"] =
				{appendText=" at their position just outside of the village's remnants.\n", stepTextKey="With Tamien's help, I rescued Merien Sellan. I should report to Dame Clarique and let her know what happened."},
		},
		[GetQuestName(4528)] = { -- "Garments by Odei"				-- Devinstrike
			["Collect the Sewing Box"] =
				{appendText=". Near one of the wolf dens within the ruins, a small wooden box lies in the grass.\n"},
			["Collect a Pack of Silk Threads"] =
				{appendText=" further along, just outside another wolf's den.\n"},
			["Collect Tailor's Book of Patterns"] =
				{appendText=". Beneath a dilapidated tower and beside yet another den rests an unassuming book, with werewolves crouching nearby.\n"},
			["Meet Odei at the North End of the Pass"] =
				{appendText=", beyond the ruins.\n"},
			["Talk to the Lion Guard Soldier"] =
				{appendText=" and discover what's drawn her here.\n"},
			["Talk to Dame Veronica"] =
				{appendText=" and inform her of Odei's whereabouts.\n"},
		},
		[GetQuestName(3019)] = { -- "The Ghosts of Westtry"			-- Westrany
			["Talk to Leon Milielle 1"] =
				{appendText=". Near the road, to the north of the lake, the ghost awaits. Having likely frightened countless travelers that passed by unaware over the years.", stepTextKey="Leon Milielle said I could lift the curse by reliving the last moments of his wife Rosalind's life. I should ask him how I should proceed."},
			["Collect a Keepsake of Rosalind"] =
				{appendText=". The remains of the nord invaders roam the area as skeletal figures, lost in time."},
			["Activate the Signal Fire"] =
				{appendText=" on a small island in the middle of the lake."},
			["Talk to Edgard the Innkeeper"] =
				{appendText=" in the southernmost house of the town."},
			["Collect Hawthorn Berries"] =
				{appendText="\nAround the town. The berries have a reddish contrast compared to the local vegetation."},
			["Talk to Apothecary Muriel"] =
				{appendText=". Her shop is in the northern part of the town, near a large stump of a dead tree."},
			["Use Poultices on Injured Guards"] =
				{appendText="\nThe specters of what were once the town guards are scattered throughout the place."},
			["Talk to Lieutenant Marlene"] =
				{appendText=" near the old well in the middle of the town."},
			["Go to Rosalind and Leon's Home"] =
				{appendText=". The house in the southern side of the graveyard."},
			["Listen to Rosalind and Leon's Discussion"] =
				{appendText=" in Leon's house south of the graveyard."},
			["Talk to Leon Milielle 2"] =
				{appendText=" in his house south of the town graveyard.", stepTextKey="I witnessed the events leading to Leon's betrayal of Westtry. Leon rejected Stendarr and sold his soul to Molag Bal while Rosalind watched. I should talk to Leon about this."},
		},
		[GetQuestName(3020)] = { -- "Memento Mori"					-- Johnyfreeman
			["Retrieve Rosalind's Sword"] =
				{appendText=" from the chapel north of the graveyard."},
			["Enter the Tomb"] =
				{appendText=". The old graveyard has fallen into disrepair over the years, with all the town habitants dead, now broken tombstones populate the place. The only thing that seems to remain mostly intact is the old burial vault."},
			["Bring Rosalind Her Sword"] =
				{appendText=" at the old burial vault in the graveyard."},
			["Defeat the Cursed Shade of Rosalind"] =
				{appendText=". The dense and humid air fills the old burial vault.  Rosalin's shade floats in the distance."},
			["Talk to Rosalind Milielle"] =
				{appendText=" just after entrance of the old burial vault in the town graveyard."},
			["Use Rosalind's Blade to Defeat Wraiths"] =
				{appendText="\nSome are scattered around the town alongside the skeletons."},
			["Return to Leon and Rosalind's Home 1"] =
				{appendText=", the big house south of the graveyard.", stepTextKey="I used Rosalind's sword to defeat the wraiths of Westtry. I should return to Leon and Rosalind's home, as Rosalind requested."},
			["Talk to Leon Milielle 1"] =
				{appendText=" in their house south of the graveyard.", stepTextKey="Leon and Rosalind are together inside the house. I should speak with Leon and tell him what I accomplished."},
			["Use the Gem to Free Villager Spirits"] =
				{appendText="\nThe spirits of the former residents of the town still occupy their houses, frozen in time since the day of invasion."},
			["Return to Leon and Rosalind's Home 2"] =
				{appendText=", the big house south of the graveyard.", stepTextKey="I set the innocent spirits of Westtry free. I should return to Leon and Rosalind's home, as Rosalind requested."},
			["Talk to Leon Milielle 2"] =
				{appendText=" in their house south of the graveyard.", stepTextKey="Leon and Rosalind are together inside the house. I should speak with Leon and tell him what I accomplished."},
		},
		[GetQuestName(4335)] = { -- "Pride of the Lion Guard"		-- Westrany
			["Find Recruit Gorak"] =
				{appendText=" south of Mire Falls.\n"},
			["Find the General's Dispatch"] =
				{appendText=" kept by the Bloodthorn cultists at one of their camps at Mire Falls.\n"},
			["Return to Aldcroft"] =
				{appendText=", east of Mire Falls.\n"},
			["Talk to Captain Vistra"] =
				{appendText=" at the Lion Guard camp in Aldcroft.\n"},
		},
		[GetQuestName(3040)] = { -- "Vital Inheritance"				-- Johnyfreeman
			["Find Edrien's Pipe"] =
				{appendText="\n\nGazing upon the sea, the lighthouse stands\nA silent witness of history's tragedies."},
			["Talk to Edrien Dencent"] =
				{appendText=", after retrieving the pipe, the air grows heavy and cold. A pale and translucent figure emerges in front of the Edrien's house door."},
			["Find Edrien's Cache"] =
				{appendText=". In a location fitting the description, where the ghost claims to have buried its gold, near some rocks surrounded by trees, there is a peculiar mound of recently disturbed soil. It may be interesting, start looking there."},
			["Talk to Alexia Dencent"] =
				{appendText=" in her house near the road south of Aldcroft."},
		},
		[GetQuestName(3023)] = { -- "Wicked Trade"					-- Westrany
			["Find Guy LeBlanc"] =
				{appendText=" at the crossroads west of Tangle Rock.\n"},
			["Search for the Missing Women"] =
				{appendText=" in the Bloodthorn camps in the southern part of Hag Fen.\n"},
			["Search For the Contract"] =
				{appendText=" mentioned by Bethany LeBlanc. \n\nI should search the camps on the southern part of Hag Fen for the document.\n"},
			["Rescue Captives from the Tower"] =
				{appendText=" in the Hag Fen marsh.\n\nThe Tower is on a peninsula southeast of Hag Fen, at the end of a road.\n"},
			["Talk to Guy at the Wyrd Enclave"] =
				{appendText=" on the southmost peninsula from Hag Fen.\n\nThis is the same peninsula where you can find the Mines of Khuras.\n"},
		},
		[GetQuestName(3035)] = { -- "Wyrd and Coven"				-- Westrany
			["Talk to Sibellec 1"] =
				{appendText=" the Old in a camp northwest of the Hag Fen Wayshrine.\n", stepTextKey="Guy advised me to seek out the Reach witch Sibellec. She's staying at the northern wyress enclave. She may know a way to stop Mother Murk."},
			["Siphon Power from Hag Corpses"] =
				{appendText=" \n\nHags can be found in the area west of Sibellec's camp, in the northern region of Hag Fen.\n"},
			["Find and Kill Mother Murk"] =
				{appendText=" at her hut in the bog north of the Hag Fen Wayshrine.\n"},
			["Talk to Sibellec 2"] =
				{appendText=" the Old back at her camp northwest of the Hag Fen Wayshrine.\n", stepTextKey="I defeated Mother Murk. I should head back to the northern wyress camp and tell Sibellec."},
			["Talk to Sibellec the Old"] =
				{appendText=" at her camp northwest of the Hag Fen Wayshrine and tell her what happened.\n"},
		},
		[GetQuestName(4340)] = { -- "The White Mask of Merien"		-- Devinstrike
			["Talk to Tamien Sellan"] =
				{appendText=". The guards are holding him near the local wayshrine.\n"},
			["Talk to Dame Clarique"] =
				{appendText=" near the town's outskirts.\n"},
			["Free Captured Villagers"] =
				{appendText=".\nThe cult is guarding them closely along the edges of the bay. I should expect a fight.\n"},
			["Enter Sellan House"] =
				{appendText=" overlooking the sea.\n"},
			["Cast Merien's White Mask"] =
				{appendText=". A journal sits atop a stack of crates in the corner, no doubt belonging to Tamien's father. It may hold the key to successfully casting the spell and saving these people from the cult's forces. The flicker of candles emanate from upstairs, perhaps that's where Merien conducted the ritual?\n"},
			["Talk to Merien Sellan"] =
				{appendText=" in his house overlooking the sea."},
		},
		[GetQuestName(3314)] = { -- "The Corpse Horde"				-- Devinstrike
			["Sanctify Dead Soldiers in Merovec's Folly"] =
				{appendText=".\nThe bodies lie scattered across the ruins, guarded by necromancers and their ilk. I may have to confront them to reach the fallen soldiers.\n"},
			["Talk to Sir Malik Nasir"] =
				{appendText=" and ease his mind with the knowledge that the fallen can remain at rest.\n"},
		},
		[GetQuestName(3343)] = { -- "Crosswych Reclaimed"			-- Johnyfreeman
			["Kill Sternis Gelves"] =
				{appendText=". Now, finally, to put an end to the bandit issue. The mayor house is the big house near the river in the northeastern edge of the town."},
			["Talk to Tamien Sellan"] =
				{appendText=", now with the death of their leader, the bandits will surely leave the town and the things will slowly return to normal. Sellan should be at the inn."},
		},
		[GetQuestName(3050)] = { -- "Cursed Treasure"				-- Westrany
			["Retrieve the Stolen Regalia"] =
				{appendText="\n\nCultists are everywhere. Their voices echoes in the distance. A small house appears not far away south, guarded."},
			["Return the Regalia to the Proper Tombs"] =
				{appendText=". Four items stolen from four tombs. Most of them seem to be sealed, but there are some that the cultists managed to open."},
			["Find the Whisperer"] =
				{appendText=". After delivering the items, a small group of ghosts materializes in front of the tomb, their ethereal glow contrasting with the darkness of the tombs."},
		},
		[GetQuestName(3345)] = { -- "The End of Extortion"			-- Devinstrike
			["Help Harassed Crosswych Citizens"] =
				{appendText=" around town and give them hope of reclaiming their home.\n"},
			["Talk to Marent Ergend"] =
				{appendText=" in front of the inn and inform him that the Red Rook's thugs will think twice before returning.\n\n"},
		},
		[GetQuestName(3192)] = { -- "Forgotten Ancestry"			-- Devinstrike
			["Honor the Winvale Patriarch"] =
				{appendText=". The graves rest to the northeast edge of the mounds, perhaps to keep family together.\n"},
			["Honor the Winvale Matriarch"] =
				{appendText=". Hopefully her spirit will be appeased.\n"},
			["Honor the Winvale Scion"] =
				{appendText=". With the candles lit, they should return to their slumber.\n"},
			["Place a Candle at the Winvale Founder's Tomb"] =
				{appendText=" outside the graveyard to the southwest, and show the spirits that their memory is honored.\n"},
			["Talk to Silas Winvale"] =
				{appendText="'s ghost beside the final tomb.\n"},
			["Talk to Harald Winvale"] =
				{appendText=" of his ancestor's warning. He's followed me to the final tomb, expectantly awaiting news.\n"},
		},
		[GetQuestName(4533)] = { -- "Fortune in Failure"			-- Johnyfreeman
			["Talk to Healer Alezan"] =
				{appendText=" in the Redoubt, not far southwest of Cath Bedraud, the big circular graveyard in the northern part of Glenumbra. Alezan must be tending to the wounded."},
		},
		[GetQuestName(3285)] = { -- "The Jeweled Crown of Anton"	-- Westrany
			["Enter the Tomb"] =
				{appendText=" of Lost Kings, left of Lady Laurent's Excavation camp.\n\nThe Tomb of Lost Kings is a crypt in northeastern Glenumbra, south of Crosswych.\n"},
			["Talk to the Forgotten Seneschal 1"] =
				{appendText=", a spirit standing at the entrance of the Tomb of Lost Kings.\n", stepTextKey="I entered the tomb and saw a spirit standing before me. I should talk to it and see if it knows where I can find Lady Laurent."},
			["Talk to Lady Laurent"] =
				{appendText=" deeper inside the tomb.\n"},
			["Find the Key of Flames"] =
				{appendText=", on the back wall that is currently in flames at the western chamber.\n"},
			["Find the Key of Blades"] =
				{appendText=" hanging from the ceiling on the eastern chamber.\n"},
			["Find the Key of Strife"] =
				{appendText=", near tiny balls of light floating about on the northmost chamber.\n"},
			["Place the Key of Flames"] =
				{appendText=" on the southwest pilar on the upstairs room, outside of the Key of Blades chamber.\n"},
			["Place the Key of Blades"] =
				{appendText=" on the southeast pilar.\n"},
			["Place the Key of Strife"] =
				{appendText=" on the northwest pilar.\n"},
			["Place the Key of Crowns"] =
				{appendText=" on the northeast pilar.\n"},
			["Watch What Happens"] =
				{appendText=" on the upstairs room where you have placed the keys.\n\nThis is the room just up the stairs from the Key of Blades' chamber.\n"},
			["Talk to the Forgotten Seneschal 2"] =
				{appendText=" at the entrance of the Vault of Lost Kings.\n\nThe Vault is accessed by going up the eastern staircase outside the Key of Blades' chamber, then entering the wooden doors to the right.\n", stepTextKey="The Forgotten Seneschal's ritual is complete and the Vault of Lost Kings is unlocked. I should speak with the seneschal by the vault entrance."},
			["Enter the Vault"] =
				{appendText=" of Lost Kings.\n\nThe Vault is accessed by going up the eastern staircase outside the Key of Blades' chamber, then entering the wooden doors to the right.\n"},
			["Take the Jeweled Crown of Anton"] =
				{appendText=".\n\nThis is the legendary ancient relic Lady Laurent asked you to retrieve. \n"},
			["Take the Cursed Crown of Anton"] =
				{appendText=".\n\nThe Seneschal wants you to take this crown and free him. He tells you that he wants to doom Lady Laurent to the tomb for her greed, calling it justice.\n"},
			["Escape the Tomb of Lost Kings 1"] =
				{appendText=" by jumping down the hole west of the chamber, then exiting the Tomb.\n", stepTextKey="I retrieved the Jeweled Crown of Anton. Now I need to find my way out of the Tomb of Lost Kings."},
			["Talk to Lady Laurent at Her Camp 1"] =
				{appendText=" just outside the Tomb of Lost Kings.\n", stepTextKey="I escaped the Tomb of Lost Kings with the Jeweled Crown of Anton. I should give it to Lady Laurent at her camp."},
			["Escape the Tomb of Lost Kings 2"] =
				{appendText=" by jumping down the hole west of the chamber, then exiting the Tomb.\n", stepTextKey="I retrieved the Cursed Crown of Anton. Now I need to find my way out of the Tomb of Lost Kings."},
			["Talk to Lady Laurent at Her Camp 2"] =
				{appendText=" just outside the Tomb of Lost Kings.\n", stepTextKey="I escaped the Tomb of Lost Kings with the Cursed Crown of Anton. I should give it to Lady Laurent at her camp."},
		},
		[GetQuestName(3337)] = { -- "Legitimate Interests"			-- Devinstrike
			["Talk to Tamien Sellan at the Crosswych Inn"] =
				{appendText="."},
			["Rally the Crosswych Councilors"] =
				{appendText="\n\nTheodore lives near Crosswatch Inn, his house should be easy to find.\n\nVirgile's house is almost in the middle of the town, near Gestor's Fine Goods.\n\nDonella resides in a small house on the southeastern side of the town."},
			["Talk to Tamien Sellan"] =
				{appendText=". With the help of the councilors, it is now possible to organize a resistance, marking a significant stride towards driving out the Red Rook bandits from the city."},
		},
		[GetQuestName(3302)] = { -- "The Miners' Lament"			-- Johnyfreeman
			["Rescue Len Belland"] =
				{appendText=". Not far to the north of the city, wooden structures emerge from the ground, signaling the location of the mine. Red Hook bandits vigilantly oversee the miners working there, akin to a predator keeping a watchful eye on its prey. Len must be somewhere in the middle tunnels inside the mine.\n"},
			["Rescue Councilor Lia"] =
				{appendText=" on the northern tunnels.\n"},
			["Rescue Suriel the Smith"] =
				{appendText=" on the western tunnels."},
			["Kill Foreman Blaise"] =
				{appendText=", he must be somewhere inside the mines, most likely in the eastern tunnels, as he wasn't in the central or western sections."},
			["Meet Tamien Sellan at the Inn"] =
				{appendText=". The mine is now liberated, now to the next move against the bandits. Sellan must be waiting outside, in the back of the inn."},
			["Talk to Tamien Sellan"] =
				{appendText=" in the back of the inn."},
		},
		[GetQuestName(3059)] = { -- "Servants of Ancient Kings"		-- Johnyfreeman
			["Rescue the Subdued Spirits"] =
				{appendText="\nMisterious glowing lights emanate from the front of the sealed tombs in the Burial Mounds, as the cultists ensnare the restless souls of the long-deceased soldiers. A small number of zombies raised by the cultists mindlessly roam the place."},
			["Kill Sir Granden"] =
				{appendText=". The spirits of the soldiers have been released from the grasp of the cultists in the Burial Mounds, it is now time to face Sir Granden. As a highly esteemed hero of the past, it is only fitting that his tomb differs from the rest, a tomb that truly highlights his significance."},
			["Talk to King Donel Deleyn"] =
				{appendText=". With the spirit of Sir Granden put to rest, the cultists, with their plans compromised, will likely lose interest in the place."},
			["Release the Kings"] =
				{appendText=". They wait near the large tree, with the leaves tinged with a golden hue, in the center of the mounds."},
		},
		[GetQuestName(3509)] = { -- "Vines and Villains"			-- Westrany
			["Talk to the Red Rook Messenger"] =
				{appendText=" at the small Lion Guard camp west of the ruins.\n"},
			["Kill Envoy Caoiss"] =
				{appendText=" at the Red Rook camp at the Dwynnarth Ruins.\n\nEnvoy Caoiss is a Reachman member of the Bloodthorn Cult. His death will prevent an alliance between the Bloodthorn Cult and the Red Rook Bandits.\n"},
			["Talk to Provost Piper"] =
				{appendText=" at the small camp west of the ruins."},
		},


-- 		=========================================================================
--		  Stormhaven Main
-- 		=========================================================================
		[GetQuestName(3412)] = { -- "A Dangerous Dream"				-- Westrany
			["Find the Guard Captain"] =
				{appendText=" taken by the cultists.\n\nYou could try searching for a Supernatural Dreamers Camp on the high road from Koeglin Village, on the west lands of Stormhaven. \n"},
			["Find a Way to Wake the Guard Captain"] =
				{appendText=".\n\nDeep within the Supernatural Dreamers Camp, north of Koeglin Village on the western territory of Stormhaven, you found a pair of mystical braziers. \n\nSomething tells you the icy fire of these braziers might be the cause of the Captain's troubled slumber. Maybe dousing them off might wake the Captain?\n"},
			["Talk to Captain Jerick in Koeglin Village"] =
				{appendText=".\n\nAfter you rescued him, Captain Jerick made his way to the village's Sleepy Sailor Inn for a bit of warm and rest.\n\nYou should go talk to him and try to understand what happened to the Captain and his envoy.\n"},
		},
		[GetQuestName(2556)] = { -- "False Accusations"				-- Westrany
			["Talk to the Constable"] =
				{appendText=" down by Koeglin Village's docks.\n\nKoeglin Village, on the west lands of Stormhaven, was recently attacked by slavers the night after the arrival of Dame Dabienne, a Knight of the Flame. \n\nDame Dabienne claims to have been wrongly accused and begs you to talk to Constable Pascal to clear her name.\n"},
			["Find the Messenger"] =
				{appendText=" inside the warehouse of Koeglin Village's docks."},
			["Talk to Constable Pascal 1"] =
				{appendText=" west of the dock's warehouse in Koeglin Village.\n\nInform him you've spoken with the Duke's personal messenger, Cordier, and that he claims that Dame Dabienne is indeed a Knight of the Flame sent to aid the village.\n", stepTextKey="I should return to Constable Pascal on the west side of the docks. Now that he's spoken with Messenger Cordier, he should realize that Dame Dabienne isn't in league with the slavers."},
			["Talk to the Ship Captain"] =
				{appendText=", a Redguard named Currod, aboard the ship at the Koeglin Village docks.\n"},
			["Find The Tava's Bounty Ledger"] =
				{appendText=" belowdecks in The Tava, a merchant ship docked at Koeglin Village.\n\nCaptain Currod mentioned the ledger is at his desk.\n"},
			["Talk to Constable Pascal 2"] =
				{appendText=" outside the docks of Koeglin Village.\n\nHopefully you have now gathered enough evidence to prove the innocence of Dame Dabienne's and The Tava's Captain. \n", stepTextKey="I found the ledger from the ship, Tava's Bounty. I can return to Constable Pascal and give it to him as proof of the captain's claims. Perhaps now he'll listen to reason."},
			["Talk to Sabyssa the Blacksmith 1"] =
				{appendText=" and warn her of Constable Pascal's paranoia. \n\nSabyssa can be found in her blacksmithing shop west of the Sleepy Sailor Inn, just across the Town Square in Koeglin Village.\n", stepTextKey="The constable now says he's going to arrest the blacksmith for refusing to supply more weapons. Yet another person he's accusing of betrayal. I should go warn her of what he's planning."},
			["Search the Constable's House"] =
				{appendText=", a two story home just south of Sabyssa's Blacksmithing in Koeglin Village.\n\nSabyssa the blacksmith mentioned that she saw a Supernal Dreamer, a daedric cultist of Vaermina, leave the Constable's house.\n\nCould it be that the cultists you encountered before are planting acursed dreams on Constable Pascal?\n"},
			["Talk to Sabyssa the Blacksmith 2"] =
				{appendText=" in her shop north of the Constable's house in Koeglin Village.\n\nTell her of the dremora you fought in the Constable's bedroom, and the accursed skull with strange glowing symbols you found in his bed.\n", stepTextKey="The Dremora in the constable's house and this Daedric symbol would seem to confirm our suspicions. I should bring this back to Sabyssa and see what she thinks should be done next."},
			["Talk to Dame Dabienne"] =
				{appendText=" by the stocks at the Town Square of Koeglin Village.\n"},
		},
		[GetQuestName(4443)] = { -- "To Alcaire Castle"				-- Westrany
			["Talk to Messenger Cordier"] =
				{appendText=" by the fountain in front of Alcaire Keep, in Alcaire Castle.\n\nThe castle is ruled over by Duke Nathaniel and is where he and his wife, Duchess Lakana, make their home. Many Knights of the Flame also reside here as the protectors of the Duke and Duchess.\n\nYou can reach Alcaire Castle by heading up north from Koeglin Village, passing through the Daedra-infested lands around Nurin Farm. \n"},
		},
		[GetQuestName(2552)] = { -- "Army at the Gates"				-- Westrany
			["Talk to Dame Falhut"] =
				{appendText=" at the southern gate of Alcaire Castle.\n"},
			["Talk to Sir Hughes in Alcaire Castle"] =
				{appendText=" within the walls of Alcaire Keep.\n\nYou can find Sir Hughes standing guard over the Duke and Duchess in the throne room.\n"},
			["Find a way into the Library"] =
				{appendText=" of Alcaire Castle.\n\nOn the lower level of the Keep lies the Duke's personal library, guarded day and night by a rather stubborn knight.\n"},
			["Search for Clues to Identify \"Almandine\""] =
				{appendText=" within the Duke's personal library.\n\nThe library can be accessed by going downstairs the northeast staircase of Alcaire Castle.\n"},
			["Inform Sir Hughes about the Duchess 1"] =
				{appendText=" being known as the Star of the Almadine, according to a book you found on The Royal Lineage of Sentinel.\n\nSir Hughes is waiting for you on the staircase just outside the Library of Alcaire Castle.\n", stepTextKey="According to information I found in the library, the messages to Alik'r were written by Duchess Lakana herself. I should speak to Sir Hughes at once."},
			["Inform Sir Hughes about the Duchess 2"] =
				{appendText=" being known as the Star of the Almadine, according to a book you found on The Royal Lineage of Sentinel.\n\nSir Hughes is waiting for you on the staircase just outside the Library of Alcaire Castle.\n", stepTextKey="According to information I found in the library, the messages to Alik'r were written by Duchess Lakana herself. I should speak to Sir Hughes at once."},
		},
		[GetQuestName(2564)] = { -- "Two Sides to Every Coin"		-- Westrany
			["Talk to Duchess Lakana in Her Room"] =
				{appendText=" in the top floor of the Alcaire Castle."},
			["Challenge Alik'r Soldiers"] =
				{appendText="\n\nDuchess Lakana expressed her concerns for her own safety within Alcaire Castle. She's entrusted you to deliver her message to General Thoda, but to do so you will have to prove yourself by besting some of his soldiers. \n\nFollow the river from Alcaire Keep towards the Alik'r Camp where you must challenge Alik'r Bravos or Champions to duel you.\n"},
			["Speak to General Thoda"] =
				{appendText=" in southeastern house in the Alik'r camp outside Alcaire Keep.\n"},
			["Talk to Duchess Lakana"] =
				{appendText=" at her room inside Alcaire Castle, and warn her that Dame Falhut is behind the attempts on her life."},
		},
		[GetQuestName(2566)] = { -- "Life of the Duchess"			-- Westrany
			["Talk to Sir Hughes"] =
				{appendText=", leader of the Knights of the Flame, on the ground floor of Alcaire Castle.\n\nTell him that you have discovered Dame Falhut's betrayal and her attempt on Duchess Lakana's life.\n"},
			["Confront Dame Falhut"] =
				{appendText=" at house on the west side of the Alcaire Keep, north of the Old Goat Inn.\n\nYou must apprehend her on charge of treason for her attempt on the Duchess's life.\n"},
			["Talk to Sir Hughes Outside Dame Falhut's House"] =
				{appendText=", north of the Old Goat Inn, within the walls of Alcaire Castle. Sir Hughes, alongside two of his Knights of the Flame, is awaiting your report."},
		},
		[GetQuestName(2567)] = { -- "The Safety of the Kingdom"		-- Westrany
			["Meet Sir Hughes at His House"] =
				{appendText=" past the market, on the other side of Alcaire Keep from Dame Falhut's home.\n"},
			["Find Duchess Lakana"] =
				{appendText=" inside Alcaire Castle.\n"},
			["Talk to Duke Nathaniel"] =
				{appendText=" in Alcaire Castle and explain how Sir Hughes has gone mad.\n\nYou can't help but recall how Constable Pascal, back at Koeglin Village, had also gone mad due to nightmares caused by Supernal Dreamers cultists. \n\nCould this situation be related?\n"},
		},
		[GetQuestName(2576)] = { -- "Tracking Sir Hughes"			-- Westrany
			["Ask about Sir Hughes at Firebrand Keep"] =
				{appendText=", a stronghold of Knights of the Flame.\n\nHead south down the road from Alcaire Castle, then east to the keep. \n\nDame Quirin stands guard between the two flights of stairs at the westmost entryway of Firebrand Keep.\n"},
		},
		[GetQuestName(736)]  = { -- "The Flame of Dissent"			-- Westrany
			["Convince Knights to Join the Cause"] =
				{appendText="\n"},
			["Talk to Sir Edmund"] =
				{appendText=" by a small fire on the western exit of Firebrand Keep."},
		},
		[GetQuestName(737)]  = { -- "Retaking Firebrand Keep"		-- Westrany
			["Blow the Great Hall Siege Horn"] =
				{appendText=" inside Firebrand Keep.\n\nThe horn is located atop the main hall.\n"},
			["Talk to Sir Edmund 1"] =
				{appendText=" inside Firebrand Keep's Great Hall.\n", stepTextKey="I sounded the horn in Firebrand Keep's Great Hall. Sir Edmund has begun the assault. I must leave the hall and find him."},
			["Kill Sir Croix"] =
				{appendText=" at the eastern garrison within Firebreand Keep.\n\nExit the keep's Great Hall and head east, across a bridge, towards the garrison where you will find Sir Croix.\n"},
			["Blow Garrison Siege Horn"] =
				{appendText=" on the Garrison Tower on the east side of Firebrand Keep.\n\nYou will find two doors leading to the Garrison Tower inside the eastern garrison building.\n"},
			["Talk to Sir Edmund 2"] =
				{appendText=" outside the Great Hall on the west part of Firebrand Keep.\n", stepTextKey="I've sounded the garrison horn, claiming Firebrand Keep for Sir Edmund and his knights. The battle is over, but Sir Edmund received dire wounds in the assault. I should seek him at the entrance to the Great Hall to learn his fate."},
		},
		[GetQuestName(467)]  = { -- "Sir Hughes' Fate"				-- Westrany
			["Visit the Infirmary"] =
				{appendText=".\n\nSir Hughes should be there amongst the wounded.\n"},
			["Talk to Odette"] =
				{appendText=" in Firebrand Keep's Infirmary.\n\nThe Breton healer stands by Sir Hughes's bed. She might be able to provide more information on the knight's condition.\n"},
			["Examine Sir Hughes"] =
				{appendText=" in the Keep's Infirmary.\n"},
			["Explore the Castle's Upper Floor"] =
				{appendText=" within Sir Hughes's dream.\n"},
			["Kill the Omen of Fear"] =
				{appendText=".\n\nSir Hughes mentioned how the Omen of Fear seems to be drawn to his sword which, in the dream, he's left somewhere in the throne room.\n\n"},
			["Talk to Sir Hughes"] =
				{appendText=" across the throne room.\n"},
			["Talk to Duke Nathaniel 1"] =
				{appendText=" outside of Sir Hughes's dream.\n\nYou deduce that exiting through the main door of Alcaire Castle should bring you back to Firebrand Keep's Infirmary.\n", stepTextKey="I'll talk to Duke Nathaniel about the events in Sir Hughes' dream."},
			["Watch Sir Hughes' Execution"] =
				{appendText=" in the Infirmary of Firebrand Keep.\n"},
			["Talk to Duke Nathaniel 2"] =
				{appendText=" about his thoughts on Sir Hughes' fate.\n\nThe Duke stands besides Envoy Darima in the Infirmary of Firebrand Keep.\n", stepTextKey="I told Duke Nathaniel that I killed Omen of Fear. I've made my decision about Sir Hughes. I should talk to Duke Nathaniel again to hear his reaction."},
			["Watch Sir Hughes' Release"] =
				{appendText=" in the Infirmary of Firebrand Keep.\n"},
			["Talk to Duke Nathaniel 3"] =
				{appendText=" about his thoughts on Sir Hughes' fate.\n\nThe Duke stands besides Envoy Darima in the Infirmary of Firebrand Keep.\n", stepTextKey="I told Duke Nathaniel that I killed Omen of Fear. I've made my decision about Sir Hughes. I should talk to Duke Nathaniel again to hear his reaction."},
		},
		[GetQuestName(1735)] = { -- "Unanswered Questions"			-- Westrany
			["Talk to Muran at Pariah Abbey"] =
				{appendText=", not very far away southeast from Firebrand Keep.\n\nThe Pariah Abbey is a monastery dedicated to Azura in central Stormhaven, northwest of Wayrest. The abbey is home to the Spirit Wardens, a group of virtuous monks who worship the Daedric Prince Azura.\n\nBrother Muran is a Breton member of the Spirit Wardens found inside the chapel of Pariah Abbey.\n"},
		},
		[GetQuestName(1536)] = { -- "Fire in the Fields"			-- ARKANOBOT
			["Talk to Sister Safia 1"] =
				{appendText=" on the road near the burning fields and destroyed guest house, North-West of the Abbey", stepTextKey="A monk asked me to rush to Pariah Abbey on the hill behind him, saying I should talk to Sister Safia. Maybe I can help her and the rest of these monks."},
			["Fill the Bucket"] =
				{appendText=" in the well near the guest houses north of the Abbey"},
			["Put Out Fires"] =
				{appendText="\n\nThe bandits are trying to burn the supplies of the Abbey.  Use the filled water bucket to put out the fires of the flaming debris on the Abbey grounds in northern area of the Abbey!"},
			["Talk to Sister Safia 2"] =
				{appendText=" on the road near the burning fields and destroyed guest house, North-West of the Abbey", stepTextKey="I've put out fires all around Pariah Abbey. Sister Safia's waiting for me on the northwestern edge of the fields."},
		},
		[GetQuestName(1529)] = { -- "Azura's Guardian"				-- ARKANOBOT
			["Search for Brother Hakam"] =
				{appendText=" near the cave north of Pariah Abbey."},
			["Search Brother Hakam"] =
				{appendText="'s corpse at the entrance of the Cave of Dreams north of Pariah Abbey."},
			["Find Abbot Durak"] =
				{appendText=""},
			["Use Scroll of Summoning Near Large Fire"] =
				{appendText=" at the fields north of Pariah Abbey."},
			["Meet Master Altien at Pariah Abbey"] =
				{appendText=" in front of the Chapple."},
		},
		[GetQuestName(1541)] = { -- "A Prison of Sleep"				-- ARKANOBOT
			["Talk to Frizwyr"] =
				{appendText=" at the Pariah Abbey Chapel."},
			["Drink Dreamstride Potion"] =
				{appendText=" near Abbot Durak at the Pariah Abbey Chapel."},
			["Talk to Durak 1"] =
				{appendText=" at the Pariah Abbey Chapel.", stepTextKey="I've entered Durak's dream. If I can find him, I can ask what I must do to set him free."},
			["Get Durak's Key"] =
				{appendText=""},
			["Talk to Durak 2"] =
				{appendText=" at the Chapel.", stepTextKey="I've recovered the key to Durak's prison. I should return to Durak inside Pariah Abbey."},
			["Wake from the Dream"] =
				{appendText=""},
			["Talk to Durak 3"] =
				{appendText=" at the Pariah Abbey Chapel.", stepTextKey="When Durak awakened from his dream, I awoke as well. Durak asked me to speak to him when we were both awake. He wants to tell me more about what happened."},
		},
		[GetQuestName(499)]  = { -- "Pursuing the Shard"			-- ARKANOBOT
			["Talk to High King Emeric"] =
				{appendText=" at Wayrest Castle."},
			["Talk to a Gate Guard at At-Tura Estate"] =
				{appendText=" at a residence entrance, west of Wayrest and Soulshriven Wayshrine."},
			["Enter the At-Tura Estate"] =
				{appendText=""},
			["Talk to Count Hosni at-Tura"] =
				{appendText=" at the Manor Courtyard at his Estate."},
		},
		[GetQuestName(2495)] = { -- "The Signet Ring"				-- ARKANOBOT
			["Find Count Hosni's Father"] =
				{appendText=" at the at-Tura Estate."},
			["Find Lady Sirali at-Tura"] =
				{appendText=". As the owner of the estate, Lord Rihad might provide you with more specific directions. Since he is at the mercy of his son's hospitality, he remains in the Guest House, in the western section of the at-Tura estate."},
			["Talk to Lady Sirali at-Tura"] =
				{appendText=" at the Summer House, northwest of at-Tura Estate."},
		},
		[GetQuestName(2496)] = { -- "Evidence Against Adima"		-- ARKANOBOT
			["Find Evidence Incriminating Adima"] =
				{appendText=" near the docks south of at-Tura Estate."},
			["Talk to Lady Sirali at-Tura"] =
				{appendText=" at the Summer House, northwest of at-Tura Estate."},
		},
		[GetQuestName(2497)] = { -- "Saving Hosni"					-- ARKANOBOT
			["Talk to Destane the Bard"] =
				{appendText=" at the at-Tura Estate courtyard."},
			["Gain Access to Hosni's Dream"] =
				{appendText=" by drinking the sleeping potion at Count Hosni's House at the at-Tura Estate.\nI'll just have to try the potions in there until I find the correct one, the bard may give me a hint if I ask him forcefully."},
			["Talk to Sirali"] =
				{appendText=""},
			["Collect the Dream Shard to Free Hosni"] =
				{appendText=""},
			["Enter the Portal"] =
				{appendText=" at the Door of the Manor courtyard of at-Tura Estate."},
			["Talk to Count Hosni at-Tura"] =
				{appendText=" at his house in at-Tura Estate."},
		},
		[GetQuestName(1633)] = { -- "The Return of the Dream Shard"	-- ARKANOBOT
			["Return the Dream Shard to Abbot Durak"] =
				{appendText=" at the Chapel."},
			["Place the Shard Upon the Statue of Azura"] =
				{appendText=" in the Chapel."},
			["Talk to Abbot Durak"] =
				{appendText=""},
		},
		[GetQuestName(1639)] = { -- "Another Omen"					-- ARKANOBOT
			["Talk to High King Emeric in Wayrest"] =
				{appendText=" Castle."},
			["Talk to Captain Ernele"] =
				{appendText=" near the guillotine at the Merchant District."},
			["Meet Abbot Durak at Shinji's Scarp"] =
				{appendText="'s southern edge. You can find him in the Officer's Quarter near the crossroads east of Wayrest just past Aphren's Hold. If you reach Weeping Giant you've gone too far."},
		},
		[GetQuestName(1437)] = { -- "General Godrun's Orders"		-- ARKANOBOT
			["Talk to Sergeant Olfin"] =
				{appendText=" near the orcish tents near the road towards the south."},
			["Charge the Ogres on the Ridge"] =
				{appendText=" and reach the unbroken tower on the ridge, in the southern battlefield."},
			["Climb Tower and Blow Olfin's Warhorn"] =
				{appendText=" at the battlements on the southern battlefield."},
			["Talk to General Godrun"] =
				{appendText=" at the southern battlefield."},
		},
		[GetQuestName(1346)] = { -- "Ending the Ogre Threat"		-- ARKANOBOT
			["Find the Missing Miners"] =
				{appendText=" near the cave entrance towards the mountains northwest of Shinji's Scarp."},
			["Get a Pickaxe"] =
				{appendText=" to destroy the support beams of the cave in the mountains, northwest of Shinji's Scarp."},
			["Enter Mountain Cavern"] =
				{appendText=" northwest of Shinji's Scarp."},
			["Destroy the Support Beams"] =
				{appendText=" in the Mountain Caverns, northwest of Shinji's Scarp."},
			["Escape the Mine"] =
				{appendText=""},
			["Talk to Ghashur"] =
				{appendText=" near the Orcish tents towards the road south of Shinji's Scarp."},
			["Report back to the Command Center"] =
				{appendText=" in the Officers' Quarters near the crossroads South of Shinji's Scarp."},
		},
		[GetQuestName(3637)] = { -- "Godrun's Dream"				-- ARKANOBOT
			["Enter Godrun's Dream"] =
				{appendText=" by approaching General Godrun in the Officers' Quarters near the crossroads south of Shinji's Scarp."},
			["Find Godrun"] =
				{appendText=""},
			["Follow Godrun through His Dream"] =
				{appendText=""},
			["Continue to Follow Godrun through His Dream"] =
				{appendText=""},
			["Free Godrun"] =
				{appendText=""},
			["Defeat the Omen"] =
				{appendText=""},
			["Talk to Vaermina's Statue"] =
				{appendText=""},
			["Escape Quagmire"] =
				{appendText=""},
			["Talk to Abbot Durak"] =
				{appendText=" in the Officers' Quarters near the crossroads south of Shinji's Scarp."},
		},
		[GetQuestName(521)]  = { -- "Azura's Aid"					-- ARKANOBOT
			["Collect Glow Dust from Wisps"] =
				{appendText="\nThe wisps roam the shores south of Shinji's Scarp.\n"},
			["Gather Azurite from the Hills"] =
				{appendText="\nAbbot claims there are Azurite ores around Bearclaw Mine, southeast of Shinji's Scarp."},
			["Travel to Weeping Giant"] =
				{appendText=" , southeast of Shinji's Scarp & Bearclaw Mine."},
			["Find Azura's Shrine"] =
				{appendText=""},
			["Cleanse Azura's Shrine"] =
				{appendText=". It has befallen a sorry state with broken buildings and crumbling towers towards the top of Weeping Giant."},
			["Talk to the Winged Twilight"] =
				{appendText=" at the Shrine to Azura near the top of Weeping Giant."},
			["Talk to Abbot Durak"] =
				{appendText=" at Wayrest Castle."},
		},
		[GetQuestName(575)]  = { -- "Vaermina's Gambit"				-- ARKANOBOT
			["Enter High King Emeric's Dream"] =
				{appendText=" by approaching him in his bed, in Wayrest Castle."},
			["Find High King Emeric"] =
				{appendText=" in his nightmare.\n\nHint: Enter the High King's dream by approaching his bed in Wayrest Castle."},
			["Talk to High King Emeric 1"] =
				{appendText=" in his nightmare.\n\nHint: Enter the High King's dream by approaching his bed in Wayrest Castle.", stepTextKey="High King Emeric stands before the guillotine, surrounded by rioting citizens. If I speak to him, perhaps I can wake him from this dream."},
			["Collect Key of the Knight"] =
				{appendText=" stashed near Sir Hughes in the fighters guild."},
			["Collect Key of the Thief"] =
				{appendText=" stashed near Hosni at-Tura at the castle."},
			["Collect Key of the General"] =
				{appendText=" stashed near General Godrun near the mages guild.\n\n Possibly by entering the High King's dream by approaching his bed in Wayrest Castle."},
			["Enter High King Emeric's Palace"] =
				{appendText=", the Wayrest Castle in his nightmare.\n\nHint: Enter the High King's dream by approaching his bed in Wayrest Castle."},
			["Kill the Night Terror"] =
				{appendText=" disguised as High King Emeric."},
			["Free the High King"] =
				{appendText=" from his nightmare near the guillotine\n\nHint: Enter the High King's dream by approaching his bed in Wayrest Castle."},
			["Enter Vaermina's Mirror"] =
				{appendText=" near the guillotine in the High King Emeric's nightmare.\n\nHint: Enter the High King's dream by approaching his bed in Wayrest Castle."},
			["Talk to Vaermina"] =
				{appendText="'s Statue in Quagmire.\n\nHint: Enter the High King's dream by approaching his bed in Wayrest Castle, and find Vaermina's Mirror near the guillotine."},
			["Escape Quagmire"] =
				{appendText=""},
			["Talk to High King Emeric 2"] =
				{appendText=" in his bedroom in Wayrest Castle.", stepTextKey="I woke up in the king's bedroom. I should speak to the king."},
			["Meet High King Emeric in the Throne Room"] =
				{appendText=" of Wayrest Castle."},
			["Talk to High King Emeric 3"] =
				{appendText=" in Wayrest Castle.", stepTextKey="I should go to the throne room to speak with High King Emeric."},
		},
		[GetQuestName(5052)] = { -- "An Offering to Azura"			--Immy
				["Deliver Oorga's offering to Brother Doumant"] =
					{appendText=" on the road leading into the Pariah Abbey, a monastery devoted to Azura. It is situated in the heart of Stormhaven, to the northwest of Wayrest."},
		},
		[GetQuestName(5050)] = { -- "Waiting for Word"				--Immy
			["Deliver the Clan Murtag Dispatch"] =
				{appendText=". In the southwestern reaches of Stormhaven, you'll find the At-Tura Estate, situated to the west of Wayrest."},

	   },


-- 		=========================================================================
--		  Stormhaven Side
-- 		=========================================================================
		[GetQuestName(2494)] = { -- "Can't Leave Without Her"		-- Beastess -- KhajiitEscort
			["Talk to Marlene Vanne"] =
				{appendText=", she was likely under attack when she barricaded herself. I should look for a swarm of Daedra near one of the farmsteads."},
			["Reunite Marlene with Her Brother 1"] =
				{appendText=". I doubt Phinis will be hanging around so close to the Daedra still, the farms are no longer safe. Yet he can't have gone far, there aren't too many ways to cross the river without soaking your trousers.", stepTextKey="I've convinced Phinis' sister to follow me. I should escort her back to her brother, who said he would be inside a barn on the eastern edge of the farm."},
			["Talk to Phinis Vanne 1"] =
				{appendText=". He looked like he was staying put, for now. I should be able to find him by the northern river bridge, by Vanne farms.", stepTextKey="I brought Phinis Vanne's sister to him, but she just kept going. She wants to get the safety of the castle. I should talk to Phinis again."},
			["Collect Dremora Head"] =
				{appendText=", an easy task given that this whole place is swarming with Daedra and Supernal cultists. Vanne farm's very ground bleeds under their influence, the head of one Daedra should be easy enough to find, and relieve from its shoulders."},
			["Show the Dremora Head to Marlene Vanne"] =
				{appendText=". With this bloody dripping thing I should be able to convince her to come out of hiding. I doubt she has budged an inch, I can find her back at the Vanne farm."},
			["Reunite Marlene with Her Brother 2"] =
				{appendText=". I doubt Phinis will be hanging around so close to the Daedra still, the farms are no longer safe. Yet he can't have gone far, there aren't too many ways to cross the river without soaking your trousers.", stepTextKey="I've convinced Phinis' sister to follow me. I should escort her back to her brother, who said he was inside a barn on the eastern edge of the farm."},
			["Talk to Phinis Vanne 2"] =
				{appendText=". He looked like he was staying put, for now. I should be able to find him by the northern river bridge, by Vanne farms.", stepTextKey="I brought Phinis Vanne's sister to him, but she just kept going. She wants to get the safety of the castle. I should talk to Phinis again."},
		},
		[GetQuestName(4403)] = { -- "Captive Crewmembers"			-- Beastess -- KhajiitEscort
			["Free Salach"] =
				{appendText=". The makeshift campsite on the island looks like it's inhabited by more than just Ember-Eye slavers. I should see if he is captured along with the enslaved commonfolk.\n"},
			["Free Lidenar"] =
				{appendText=", the makeshift refuge on the island is swarming with guards. He is likely to be at the heart of them. I should search the tents to see if he is in any.\n"},
			["Free Ozor"] =
				{appendText=". Slavers are likely to take captives as quickly as they take their coin. Like it runs in their very blood. I should check the ship to be sure there are no crewmen stuck aboard it, they could be in more peril than the rest.\n"},
			["Kill Captain Angarthal"] =
				{appendText=". There would be no better holdout for a pirate captain than the bowels of his ship. I bet without a doubt that I can find him somewhere in the bowels of The Bloody Scupper, waiting for me to make my next move."},
			["Talk to Captain Marck"] =
				{appendText=", now that Angarthal has been taken care of and its crew pose no threat to Marck and his men. They can take refuge at The Bloody Scupper, the ship docked at the island south of Koeglin, for as long as they can maintain it."},
		},
		[GetQuestName(1637)] = { -- "Divert and Deliver"			-- Beastess -- KhajiitEscort
			["Collect Burning Log"] =
				{appendText=" at a coastal settlement south of Koeglin Village. An unattended fire can only cause trouble, I should see to it that this remains true."},
			["Burn the Slaver Tents"] =
				{appendText="\nThey are dry, and should catch flame like old parchment. The entry to the port will be funneling smoke as quickly as the torch touches them.\n"},
			["Burn Stolen Goods on the Docks"] =
				{appendText=". Nothing gets to bandits and looters like watching their devious earnings go up in smoke, I should see to it that they can't gain a single coin from the ashes."},
			["Steal Ma'jhad Kha's Key"] =
				{appendText=", he is nowhere to be seen, which means his house now lays unguarded. I will likely find the key within."},
			["Free Elvira's Crewmates"] =
				{appendText=". The tents are burning, the dock has been cleared, the only place left to search is Steelheart Cave itself."},
			["Return to Elvira"] =
				{appendText=". I should seek her out in Steelheart, she shouldn't be far, knowing her men were on the brink of being jailbroken."},
			["Talk to Ghash"] =
				{appendText=", he lies injured and writhing in the dirt behind Ma'jhad's home in Steelheart."},
			["Rescue Elvira"] =
				{appendText=". I need to scour the beach, she is in danger and might not have much time. Ma'jhad can't have dragged her far with her fighting against him."},
			["Talk to Elvira"] =
				{appendText=", she fled south of the beach after I freed her from Ma'jhad, the stony crags of the shoreline make for a good hiding place."},
		},
		[GetQuestName(4565)] = { -- "Do as I Say"					-- Beastess -- KhajiitEscort
			["Talk to Therron Berard"] =
				{appendText=". His brother gave little to no info on where or how to find him. Though it stands to reason that an ex-bandit like him likely grew up in cushy living, just to throw it away for the sake of adventure. Wayrest is the largest city in Stormhaven, I should check there, scour the busiest districts for any sign of his brother. There is bound to be crowds of people around the local Inn, Guild traders, and Merchant's district. One of those locations has to have a clue as to where I can find Therron."},
		},
		[GetQuestName(2569)] = { -- "Legacy of the Three"			-- Beastess -- KhajiitEscort
			["Find the Windridge Caves"] =
				{appendText=". In the northwest of Stormhaven a great gaping wound of earth and stone has bored itself into the side of the mountains towards Wrothgar. I should make my way inside and see what awaits me."},
			["Talk to the Spirit of Sir Edain"] =
				{appendText=", the restless soul looks like he has seen his fair share of excellence and failings."},
			["Take Sir Edain's Sword"] =
				{appendText=", with it I can make short work of the unruly undead inhabiting this desolate cave."},
			["Entrap Arie's Soul"] =
				{appendText=", her tomb lays in the darkest portion of this cave. Riddled with crystals and detritus.\n"},
			["Entrap Gilbert's Soul"] =
				{appendText=", his skeleton lies half defiled by looters still bearing the tools of their grim tasks.\n"},
			["Entrap Emory's Soul"] =
				{appendText=", his ancient body lays under the light of a distant opening in the cave's ceiling."},
			["Cast Sir Edain's Sword into the Fissure"] =
				{appendText=", purge the souls within to be judged for their past offences. Martial, spiritual, or otherwise."},
			["Talk to Sir Edain's Spirit"] =
				{appendText=", he awaits at the cross section of staircases in the deepest portion of the cave."},
		},
		[GetQuestName(4401)] = { -- "Lighthouse Attack Plans"		-- Beastess -- KhajiitEscort
			["Talk to a Deputy in Koeglin Village"] =
				{appendText=". I should search the town for a Deputy. The docks were recently under siege by the Ember-Eye, if one is still on duty, I bet he would still be on duty there."},
			["Give the Plans to Deputy Luric 1"] =
				{appendText=". He should still be on duty, I should check the Koeglin docks to find him.", stepTextKey="I should give the plans to a deputy in Koeglin Village."},
			["Give the Plans to Deputy Luric 2"] =
				{appendText=". He should still be on duty, I should check the Koeglin docks to find him.", stepTextKey="I should give the plans to a deputy in Koeglin Village."},
		},
		[GetQuestName(3783)] = { -- "Lost Lions"					-- Beastess -- KhajiitEscort
			["Rescue Renard"] =
				{appendText=". He cowers in a corner just before the precipice to a great lightless crevice. Trying to tunnel his way out of the ruins. The sounds of his shovel meeting the dirt with every motion, his only companion.\n"},
			["Rescue Elise"] =
				{appendText=", she hides close to the shadows, in a room crowded by a lumbering beast not far from her. Seeking protection from the gentle soothing light of a giant Ayleid crystal.\n"},
			["Rescue Laroche"] =
				{appendText=". Covered by the sounds of a rushing stream, tenuously close to the sheer drop of a waterfall, he is huddled close to the cascade, dangerously so to its edge."},
			["Talk to Sir Edgard"] =
				{appendText=", he will be happy that I recovered his men, and uncovered what was haunting them."},
		},
		[GetQuestName(2561)] = { -- "A Family Affair"				-- Beastess -- KhajiitEscort
			["Talk to Rosalie Nurin"] =
				{appendText=", I should be able to find her at the Nurin Farm, or what is left of it."},
			["Talk to Ganise 1"] =
				{appendText=", she is probably still inside the ruins of the house, scrounging for what she can.", stepTextKey="Rosalie asked me to tell her daughter, Ganise, to meet her at their house. Ganise is looking through the rubble in the westernmost house at Nurin Farms."},
			["Investigate the Barn"] =
				{appendText=", though I should tread carefully. Nurin Farm didn't burn down for no reason."},
			["Read Tattered Book"] =
				{appendText=". It looks like it was the only thing to survive the Nurin Farms barn being torched, it must be important."},
			["Meet Ganise at Her House"] =
				{appendText=", it's one of the last buildings that isn't a pile of rubble and cinders, it shouldn't be too hard to find on the property."},
			["Find the House Key"] =
				{appendText=", the Nurin Farm is crawling with these scamps, anyone of them could have it. I will have to cut down as many as I need to until I find it."},
			["Talk to Ganise in the House"] =
				{appendText=", its not going to sprout legs any time soon, but it might burn down again when I'm not looking. I should head to the farmhouse. Nurin farms should have one less in need soon."},
			["Rescue William Nurin"] =
				{appendText=", I should scour the property line for him. The damage was recent enough, and they can't have taken him far. The Nurin Farmland is mostly flat fields, and there are no basements left to keep him held up in after the fires. They must have him captive somewhere elevated, somewhere out of sight."},
			["Talk to Ganise 2"] =
				{appendText=". Her father made his way back to the Nurin Farms property, I should find the two of them there.", stepTextKey="William and Ganise are back at the farm. I should go speak with them."},
		},
		[GetQuestName(1687)] = { -- "False Knights"					-- Beastess -- KhajiitEscort
			["Collect Knight of the Flame Tabards"] =
				{appendText=".\nThe bandits are holed up just outside Firebrand Keep. They were smart enough to disguise themselves to trick the common folk and immigrants to Stormhaven. But they are still bandits. They are likely to keep their findings in their shoddy tents and dens. I should check to see if they have stashed any in the area."},
			["Talk to Sir Graham"] =
				{appendText=". He will be happy to have the tabards back in the rightful hands. He and what remained of his men were injured, they will likely still be huddling for safety under some trees near the stairs leading into Firebrand Keep."},
		},
		[GetQuestName(728)]  = { -- "Repair Koeglin Lighthouse"		-- Beastess -- KhajiitEscort
			["Recover the Focusing Crystals"] =
				{appendText=". The Ember-Eye raiders are scattered around the lighthouse, as is their plunder. I should check their makeshift camps for their ill-gotten gains, they are likely still guarding them. I should be prepared for a fight.\n"},
			["Search the Pirate Ship for Oil"] =
				{appendText=". The Bloody Scupper lies docked on the islet south of Koeglin Lighthouse. I should storm the deck and make my way through the guts of the ship. They are bound to have Kegs or Barrels nearby."},
			["Replace the Lighthouse Crystals"] =
				{appendText=". I should make my way to the top of the lighthouse, and get these crystals set."},
			["Light the Signal Fire"] =
				{appendText=". The final touch, setting the brazier alight with rekindle the lighthouse's heart, warding away the would-be invaders from transgressing any further on Koeglin Village."},
			["Talk to Tyree Marence"] =
				{appendText=", he should be at his post. Admiring the roaring hearth at the peak of the lighthouse."},
		},
		[GetQuestName(3784)] = { -- "Repairing the Cage"			-- Beastess -- KhajiitEscort
			["Collect Fragments"] =
				{appendText="\nBonesnap Ruins is perilous, a catacomb of tunnels and dusty corners. I should be sure to make a clean sweep of every room. The bone effigies containing the fragments could be littered anywhere, from the darkest corners, to the darkest of goblin altars."},
			["Bring the Fragments to Gaston"] =
				{appendText=", he should be waiting for me by the Aylied altar in the room adjacent to the entrance of this horrid place."},
			["Repair the Welkynd Stone"] =
				{appendText=", it lies within the Ayleid altar in the southeastern most room of the dungeon."},
			["Talk to Battlemage Gaston"] =
				{appendText=""},
		},
		[GetQuestName(1709)] = { -- "Rozenn's Dream"				-- Beastess -- KhajiitEscort
			["Read the Dreamers' Scroll of Power"] =
				{appendText=". The cult must have left some things laying around in their wake, I should search up the path to the crag south of Vanne farm and see if any buildings or guards are holding the scroll in safe keeping."},
			["Light the Ritual Braziers"] =
				{appendText=". The Nightmare Crag has braziers scattered on the cardinal directions of the ritual circle. I should see to them, and get the ritual started, so that I can see to its end."},
			["Summon and Kill the Daedra"] =
				{appendText=". The ritual worked! A portal tore its way into reality, beneath the great arch of the Nightmare Crag. I should make my way through it, and put an end to this Daedra's polluting presence."},
			["Free Rozenn Vanne"] =
				{appendText=". The ritual has been completed, and with it, the Daedra slain. Nightmare Crag should be free of its dark influence. I should see to Rozenn's bindings."},
			["Talk to Ingride Vanne"] =
				{appendText=". I should return back down the steps of the Nightmare Crag. To put this business to an end. Ingride is likely awaiting her daughter's return, and subsequently mine."},
		},
		[GetQuestName(2578)] = { -- "Scamp Invasion"				-- Beastess -- KhajiitEscort
			["Destroy the Daedric Portals"] =
				{appendText="\nI need to check the property high and low, from the fields to the ruins, the portals could be anywhere. They are likely to be close to the ruins of the houses, but I should be sure to check for congregations of scamps too. The little fiends can never stay away from conduits of mischief and magical torrents all in the same place."},
			["Talk to William Nurin"] =
				{appendText=", he should be back at the Nurin family farmstead."},
		},
		[GetQuestName(2558)] = { -- "The Slavers"					-- Beastess -- KhajiitEscort
			["Find Lucas Oscent"] =
				{appendText=". His mother said he liked to fish, likely to be last seen around the coast. I should check there first, and follow any slaver or bandit scum I find along the way. They might just lead me to what I am looking for."},
			["Talk to Margot Oscent"] =
				{appendText=". I should find the Oscent residence, Margot and her son should be waiting for me if all went well. Given her son's aptitude for fishing, I wouldn't be surprised if their house was close to the docks."},
		},
		[GetQuestName(1678)] = { -- "The Slumbering Farmer"			-- Beastess -- KhajiitEscort
			["Talk to Brother Perry"] =
				{appendText=", he said he would meet me just across the river, on the safe side of the bridge."},
			["Collect Scamp Heart"] =
				{appendText=", easy if I can catch one, the chaos of torching the Vanne farm's crops no doubt has them congregated in the fields. I should find one, or a dozen, and put them to the sword.\n"},
			["Collect Ritual Candle"] =
				{appendText=". The houses have likely been looted or raided, there has to be a storehouse within the property that I can find supplies in. A candle wouldn't be too farfetched to find among barrels and crates, would it?\n"},
			["Collect Dremora Heart"] =
				{appendText=". The fields and farmsteads of the Vanne Farms are littered with cultists and Daedra alike, any one of them should make for an easy target."},
			["Place the Dremora Heart"] =
				{appendText=". Ingride doesn't have much time. I should make my way to the mill across the river from Vanne Farms, and start the ritual. The heart should probably be placed closest to hers.\n"},
			["Place the Ritual Candle"] =
				{appendText=". It will make the perfect centerpiece for the ritual.\n"},
			["Place the Scamp Heart"] =
				{appendText=". It still beats, I should place it opposite of the Dremora heart."},
			["Perform the Ritual"] =
				{appendText=". at the mill across the river from Vanne Farms. I have to get this right, I don't know how much time Ingride has. I should double check to make sure I know what I am doing. Who knows what the ramifications of fumbling this ritual could be."},
			["Talk to Ingride Vanne"] =
				{appendText=". She looked weak, likely still shaken from the ritual, but the mill should be a safe place for her to recover in."},
		}, 
		[GetQuestName(2549)] = { -- "Abominations from Beyond"		-- Westrany
			["Rescue Captives"] =
				{appendText="\n\nWest of Wayrest, and south of the Soulshriven Wayshrine, lay the crumbling ruins of Soulshriven Tower.\n\nSkeletons made the ruins their home, and have recently captured three locals to sacrifice to Molag Bal.\n\nYou must search through the collapsed surroundings of Soulshriven Tower and save the locals, Adalard, Lucie and Thonine, before they meet their demise.\n"},
			["Talk to the Priestess of Stendarr"] =
				{appendText=" just north of the Soulshriven Tower, by the Soulshriven Wayshrine.\n\nPietine will surely be pleased with your success.\n"},
		},
		[GetQuestName(1554)] = { -- "Blood Revenge"					-- Westrany
			["Burn the Territory Markers"] =
				{appendText="\n\nSituated north of Wayrest and east of Pariah Abbey, the fort of Cumberland's Watch has survived countless goblin attacks. \n\nRecently, however, goblins from the Stonechewer Goblin Camp launched their most dreadful attack yet, breaching the gates and seizing the camp. \n\nTo mark the newly conquered fort, the goblins have placed territory markers around the camp. A Redguard Watch Captain by the name of Rama has tasked me with destroying them.\n\n"},
			["Talk to Watch Captain Rama"] =
				{appendText=" and inform him you have burned the goblin markers. \n\nWatch Captain Rama is at a southeast tower in Cumberland's Watch, a fort north of the city of Wayrest.\n"},
		},
		[GetQuestName(2550)] = { -- "Curse of Skulls"				-- Westrany
			["Gather Cursed Skulls"] =
				{appendText="\n\nI should collect the cursed skulls scattered around Soulshriven Tower, on a hill southwest of the city of Wayrest.\n\nHopefully this will allow me to free their defiled souls from Molag Bal’s torment.\n"},
			["Toss Skulls on Charnel Heap"] =
				{appendText=" on the first floor of the southmost tower of Soulshriven Tower.\n\nThe tower is located southwest of the city of Wayrest.\n"},
			["Talk to the Freed Soul"] =
				{appendText=" inside the southmost tower of Soulshrive Tower, southwest of the city of Wayrest.\n"},
		},
		[GetQuestName(2481)] = { -- "The Debt Collector's Debts"	-- Westrany
			["Talk to S'rashi 1"] =
				{appendText=" in his office at the second floor of the Cloudy Dregs Inn, a tavern in the Wayrest Residential District, near the north gate.\n\nTell him you come on behalf of his brother, M'jaddha, who requested you to help him.\n", stepTextKey="S'rashi's brother asked me to find him upstairs in the Cloudy Dregs Inn and find out how I can help."},
			["Collect Debt from Louis Ervine"] =
				{appendText=", a senseless gambler who's lost everything betting. \n\nS'rashi told you he's taken pity on him for too long, and time has come for Louis to pay his debts.\n\nLouis Ervine can be found in the Market Square of the Merchant District just south of the Cloudy Dregs Inn.\n"},
			["Collect Debt from Ugurz on Docks"] =
				{appendText=".\n\nUgurz and his gang can be found in a warehouse by the small docks west of Harbor Skiff in the southern quarter of Wayrest city.\n"},
			["Collect Debt from Padier Nytte 1"] =
				{appendText=", a nobleman who claims to have lost his family riches.\n\nPadier can be found by the eating area in the back gardens of the Wayrest Treasury, on the northeast quarter of the city.\n", stepTextKey="I should look for the second debtor now, the nobleman, Padier Nytte. S'rashi told me that Padier claimed to be broke, but that he comes from old money and S'rashi doesn't believe him."},
			["Collect Debt from Ugurz' Lockbox"] =
				{appendText=" besides him in a small warehouse west of Harbor Skiff.\n\nSomething doesn't feel quite right about the situation, I should be on the lookout. \n"},
			["Collect Stone from Grave Behind Temple"] =
				{appendText=" on the south gardens of the Rededication Shrine, on the west side of Wayrest, just north of the Wayrest Outlaws Refuge.\n\nYou should look for the grave of Vic Nytte.\n"},
			["Collect Debt from Padier Nytte 2"] =
				{appendText=" by implying that you might inform the guards about his involvement in grave robbing.\n", stepTextKey="Padier claims all his money is tied up in investments. However, he told me his grandfather was buried with some precious stones near the city's temple. If I dig up the grave and retrieve a stone, I can repay the debt to S'rashi."},
			["Look for Captain Marck at the Wayrest Docks"] =
				{appendText=" just west of Harbor Skiff.\n\nPoor Captain Marck was a just and smart man who lost his ship and borrowed money to buy a new one. Time has come for him to repay S'rashi.\n\nIf, by the Nine Divines, you can't find the Captain in the docks, you might want to chat to his First Mate, Elvira Derre.\n"},
			["Talk to Captain Albert Marck"] =
				{appendText=" at the Cloudy Dregs Inn, north of Harbor Skiff and the docks.\n\nThanks to the Captain's First Mate, Elvira Derre, you know he has gone to the Cloudy Dregs for a couple of drinks.\n"},
			["Talk to S'rashi 2"] =
				{appendText=" at his office upstairs in the Cloudy Dregs Inn. \n\nExplain what Captain Marck has told you about not having any money left to pay his debt. \n", stepTextKey="I should speak to S'rashi about the Captain's debt."},
			["Pay off Captain Marck's Debt"] =
				{appendText=" to S'rashi with your own gold.\n"},
			["Persuade S'rashi to Forgive the Debt"] =
				{appendText=" of Captain Marck.\n"},
			["Kill the Assassin"] =
				{appendText=", a Redbuard woman named Ramzip who is hiding in a home just down the street. Could it be that she is hiding somewhere inside the Red Squall Armory?\n"},
			["Talk to S'rashi 3"] =
				{appendText=" back at his office in the Cloudy Dregs Inn, just north of the Red Squall Armory.\n\nTell him you've killed the Redguard Assassin to settle Captain Marck's debt, and inquire him about your share for helping him out.\n", stepTextKey="I've collected payment from two men who owe S'rashi money, and we worked out the money that Captain Marck owed. I should talk to S'rashi and get the share he offered me."},
			["Talk to S'rashi 4"] =
				{appendText=" back at his office in the Cloudy Dregs Inn, in the north quarter of Wayrest city.\n\nAsk him about your cut of the gold as payment for helping him.\n", stepTextKey="I've collected payment from two men who owe S'rashi money, and we worked out the money that Captain Marck owed. I should talk to S'rashi and get the share he offered me."},
			["Talk to S'rashi 5"] =
				{appendText=" back at his office in the Cloudy Dregs Inn, in the north quarter of Wayrest city.\n\nAsk him about your cut of the gold as payment for helping him.\n", stepTextKey="I've collected payment from two men who owe S'rashi money, and we worked out the money that Captain Marck owed. I should talk to S'rashi and get the share he offered me."},
		},
		[GetQuestName(2046)] = { -- "Dreams to Nightmares"			-- Westrany
			["Find Brother Gerard"] =
				{appendText=" atop a hill on the way to in Moonlit Maw, close to a strange portal.\n\nYou might want to follow the northern road leading from Pariah Abbey Wayshrine.\n"},
			["Kill Scamps and Take Their Heads"] =
				{appendText="\n\nScamps are one of the lesser sentient Daedra of Oblivion, who often enter into the mortal world to cause mischief and carry out errands for their Princes.\n\nYou can find them roaming around the hill where you found Brother Gerard, just north of the Pariah Abbey Wayshrine.\n"},
			["Throw Scamp Heads into Portals"] =
				{appendText="\n\nThe Supernal Dreamers have set up portals to Quagmire, the realm of Daedric Prince Vaermina, all around the cave and nearby lake.\n\nBy throwing Scamp Heads into the portals, you should be able to force the portals close.\n"},
			["Enter Moonlit Maw Cave"] =
				{appendText=" and meet Brother Gerard inside.\n\nMoonlit Maw is a cave in northern Stormhaven, north of Wayrest.\n"},
			["Talk to Gerard Inside Cave"] =
				{appendText=". Tell him you have successfully closed the portals.\n"},
		},
		[GetQuestName(2068)] = { -- "The Dreugh Threat"				-- Westrany
		["Talk to Sergeant Stegine 1"] =
			{appendText=" outside Arbogasque's House in Dreughshire, a shanty town just outside the northwestern walls of Wayrest in Stormhaven.", stepTextKey="A panicked Wayrest guard told me Sergeant Stegine is in Dreughside, defending the citizens against attacking dreugh."},
		["Collect Dreugh Eggs"] =
			{appendText=" found around Dreughside.\n\nThe dreugh are an ancient species of aquatic, octopus-like beastfolk, commonly hunted for their hide and the wax scraped from their shells.\n\nThe Dreugh Eggs you were told to collect have a blue tonality and are surrounded by a protective jelly. Four should to be enough."},
		["Place Dreugh Eggs in Nests"] =
			{appendText=" made of mud by water bodies west of Dreughside.\n\nYou can find two nests by the first water body, and two more just down the eastmost waterfall."},
		["Talk to Sergeant Stegine 2"] =
			{appendText=" on the main road west from Dreughside, just outside the Wayrest city walls.", stepTextKey="I returned dreugh eggs to their nests and killed the creatures encroaching on Dreughside. That should discourage them from attacking again. Sergeant Stegine is still at his post. I should tell him about this."},
		},
		[GetQuestName(2488)] = { -- "A Gang of Thugs"				-- Westrany
			["Talk to the Guard Captain"] =
				{appendText=", a Breton named Mathias Etienne, who can be found in Wayrest Castle.\n\nAfter confronting some thugs in one of the alleys of Wayrest city, you found a bag with various stolen items. In your good will, you have decided to report the situation to the guards.\n\nWayrest Castle is the proud residence of High King Emeric, the leader of the Daggerfall Covenant. You can enter through its main gates by going up the stairs southwest from the city's Market District. \n"},
			["Kill Ondre the Grinder"] =
				{appendText=".\n\nAfter hearing of the atrocities committed by one of Wayrest's most foul gang leaders, you have decided to give the royal guard a hand and kill Ondre the Grinder yourself. \n\nHead to the Wayrest Docks, southeast of Wayrest Castle, and look around the warehouses on the lower levels of the docks for the Signal Drum on crate just outside a door.\n"},
			["Talk to Guard Captain Etienne"] =
				{appendText=" back at Wayrest Castle, northwest of the docks and up the southern stairs of the Market District. \n\nTell him the good news of Ondre's demise. Hopefully, this will be the end of this reign of torment and the scattering of the Backstreet Gang.\n"},
		},
		[GetQuestName(2047)] = { -- "The Gate to Quagmire"			-- Westrany
			["Talk to Master Muzgu 1"] =
				{appendText=" in Moonlit Maw. \n\nDecide whether to kill him or find a way to save him.\n", stepTextKey="Muzgu asked me to kill him. He thinks that's the only way to prevent the Daedric spirit from being unleashed. Maybe there's a way to save him, but the longer we delay, the greater the risk of the spirit taking over."},
			["Collect Scroll of Dream Trapping"] =
				{appendText=" from a stone table south of Master Muzgu's trap inside the Moonlit Maw cave, north of Wayrest city.\n"},
			["Use Scroll on Dreaming Cultist"] =
				{appendText=" in the area outside Moonlit Maw cave, north of Wayrest city.\n\nYou must find a sleeping cultist to be able to use the scroll successfully.\n"},
			["Lead the Cultist to the Cave"] =
				{appendText=" north of Moonlit Maw.\n\nBy the magic of the scroll, the cultist should get trapped in place of Master Muzgu.\n"},
			["Talk to Master Muzgu 2"] =
				{appendText=" about what to do next.\n\nMaster Muzgu is inside the Moonlit Maw cave, north of Wayrest city, by a ritual circle trap.\n", stepTextKey="The cultist is now trapped in the ritual circle. Muzgu can tell me what to do next."},
			["Use Daedric Circle to Sacrifice Cultist"] =
				{appendText=".\n\nThe Daedric Ritual Circle is inside Moonlit Maw cave, north of Wayrest. \n"},
			["Use Portal to Quagmire and Slay the Daedric Spirit 1"] =
				{appendText=". The Portal leads to the realm of Daedric Prince Vaermina, and can be found inside the cave in Moonlit Maw, north of Wayrest responsible for trapping Master Muzgu.\n\nThe Portal to Quagmire leads to the realm of Daedric Prince Vaermina, and can be found inside the cave in Moonlit Maw, north of Wayrest.\n", stepTextKey="The cultist has been slain. The Daedric spirit is now vulnerable. I can enter the portal and kill it."},
			["Talk to Master Muzgu 3"] =
				{appendText=" back at the cave in Moonlit Maw.\n\nYou can use the Daedric Portal to return to him.\n", stepTextKey="The Daedric spirit has been vanquished. Its threat has ended. \n\nI should speak with Muzgu and see what else must be done."},
			["Get the Poison"] =
				{appendText=" from a stone table south of Master Muzgu's ritual trap, inside the Moonlit Maw cave, north of Wayrest.\n"},
			["Give Poison to Muzgu"] =
				{appendText=", the Master Orc trapped in the daedric ritual circle inside Moonlit Maw cave, north of Wayrest city.\n"},
			["Use Portal to Quagmire and Slay the Daedric Spirit 2"] =
				{appendText=", saving many and honoring Master Muzgu's death.\n", stepTextKey="Muzgu sacrificed himself. The Daedric spirit is now vulnerable. I should enter the portal to the Daedric realm of Quagmire and kill it."},
			["Talk to Gerard"] =
				{appendText=" back at the cave in Moonlit Maw.\n"},
		},
		[GetQuestName(1591)] = { -- "Injured Spirit Wardens"		-- Westrany
			["Use the Healing Poultices on the Injured"] =
				{appendText="\n\nHeal the wounded Spirit Wardens found in the fields north of Pariah Abbey.\n"},
			["Talk to Falice"] =
				{appendText=" outside the northern walls of Pariah Abbey, and check if she needs more help.\n"},
		},
		[GetQuestName(1568)] = { -- "A Means to an End"				-- Westrany
			["Retrieve the Stonechewer Totem"] =
				{appendText=" atop the northern watchtower of the fortress.\n\nCommander Kurt firmly believes that the expulsion of the totem will compel the goblins to depart.\n"},
			["Talk to the Commander"] =
				{appendText=" Kurt at the base of the southern tower.\n\nYou hope that Commander Kurt hasn't succumbed to his injuries.\n"},
			["Talk to Nellic Sterone"] =
				{appendText=", a Breton scholar residing on the outskirts of the Stonechewer Goblin Camp. You can find him wandering near the western road as you exit Cumberland's Watch.\n"},
			["Return the Stonechewer Totem 1"] =
				{appendText=" to the goblin camp west of Cumberland's Watch. The exact location to place the totem remains a mystery.\n", stepTextKey="Watch Captain Ernard asked me to return the Stonechewer tribal totem to the Stonechewer Goblins. He suggested I might want to speak with a scholar named Nellic Sterone before I enter the Stonechewer camp."},
			["Talk to Watch Captain Ernard 1"] =
				{appendText=" back at the south watchtower of Cumberland's Watch.\n\nThe Captain will undoubtedly be pleased to hear of your success.\n", stepTextKey="I should report to Captain Ernard."},
			["Return the Stonechewer Totem 2"] =
				{appendText=" to the tunnels to the southwest of the Stonechewer Goblin Camp, west of Cumberland's Watch.\n\nThe breton scholar cautioned you about the shamans, mentioning that one of them has a shape-changing spell and a rather twisted sense of humor.\n", stepTextKey="I should return the Stonechewers' tribal totem to the Goblin cave north of Cumberland's Watch."},
			["Talk to Watch Captain Ernard 2"] =
				{appendText=" back at the south watchtower of Cumberland's Watch.\n\nThe Captain will undoubtedly be pleased to hear of your success.\n", stepTextKey="I should report to Captain Ernard."},
		},
		[GetQuestName(5935)] = { -- "The Missing Prophecy"			-- Westrany
			["Talk to Rhea 1"] =
				{appendText=", an Imperial oracle of Azura in her room at the inn.\n", stepTextKey="The letter instructed me to meet Rhea in Wayrest, in a tavern called The Cloudy Dregs Inn. I should go speak with her."},
			["Travel to Pariah Abbey"] =
				{appendText=" and commune with Azura.\n\nThe Pariah Abbey, formerly known as Menevia Abbey, stands as a monastery devoted to Azura in central Stormhaven, situated northwest of Wayrest. Within its walls reside the Spirit Wardens, a devout order of monks who revere the Daedric Prince Azura.\n"},
			["Talk to Azura 1"] =
				{appendText=" by venerating her statue located in the apse of the abbey chapel in Stormhaven.\n", stepTextKey="I've arrived in Pariah Abbey. I should seek out the statue of Azura and attempt to make contact with the Daedric Prince."},
			["Collect Daedric Essence"] =
				{appendText="\n\nDaedra, immortal beings from the planes of Oblivion, are a pervasive plague upon Tamriel. \n\nTheir presence can be detected in various corners of the land, with recent reports indicating a surge in Daedra sightings near Vanne Farm just east of Koeglin Village.\n"},
			["Talk to Rhea 2"] =
				{appendText=" at the courtyard of Pariah Abbey in Stormhaven.\n", stepTextKey="I filled Azura's crystal with Daedric Essence. I sense that the crystal, now flush with power, wants to return to Pariah Abbey. Perhaps Rhea waits for me there."},
			["Read Rhea's Letter"] =
				{appendText=" dropped in the courtyard of Pariah Abbey, in Stormhaven.\n"},
			["Rescue Kanzin"] =
				{appendText=", a Khajiit imprisoned inside Rubble Butte, an Ayleid ruin in western Bangkorai, northeast of Hallin's Stand.\n"},
			["Rescue Muz-Shah"] =
				{appendText=", an Argonian incarcerated inside Faldar's Tooth, a ruined fort in The Rift, east of Honrich Tower.\n"},
			["Rescue Rhea"] =
				{appendText=" from Mephala's Nest, a Daedric ruin in central Stonefalls, just south of Ebonheart.\n\nIn each location, you must first acquire a void key from a Daedric Chest situated near the delve's boss. Following this, you must use the key to free each oracle from a Pocket Realm of Oblivion portal deeper within the delve.\n"},
			["Talk to Azura 2"] =
				{appendText=" in the apse of the abbey chapel in Stormhaven, and inform her that you have successfully rescued her oracles.\n", stepTextKey="I rescued the abducted oracles. Rhea urged me to return to Pariah Abbey to seek Azura's counsel on what to do next."},
			["Travel to Cold-Blood Cavern"] =
				{appendText=" found east of the entrance of the Ruins of Mazzatun in Shadowfen.\n\nThe cavern is a Daedric ruin, potentially devoted to Clavicus Vile, and harbors numerous Skaafin, a breed of Daedra characterized by their yellow skin and humanoid countenances adorned with long white horns, who faithfully serve Clavicus Vile.\n"},
			["Search for Clues"] =
				{appendText=" within the Cold-Blood Cavern, situated to the east of the entrance of the Ruins of Mazzatun in Shadowfen.\n"},
			["Read Tommy Bones's Journal"] =
				{appendText=" found on a nook along the left wall next to a skeleton located within the entrance of the Cold-Blood Cavern, to the east of the Ruins of Mazzatun in Shadowfen.\n"},
			["Talk to Rhea 3"] =
				{appendText=" who has just arrived at the Cold-Blood Cavern, to the east of the Ruins of Mazzatun in Shadowfen.\n", stepTextKey="Rhea's arrived in Cold-Blood Cavern. I should speak to her about what we found."},
			["Collect Shadow Cowl"] =
				{appendText=" from the square chamber immediately northeast of the cavern entrance.\n"},
			["Collect Spinning Brooch"] =
				{appendText=" from the northmost square chamber.\n"},
			["Collect Bulging Purse"] =
				{appendText=" from the northeast square chamber accessed through the central circular chamber.\n\nThe three cursed treasures can be found inside Bandit Chests scattered all over the Cold-Blood Cavern, east of the Ruins of Mazzatun in Shadowfen. Access to this Daedric cave is granted through a trapdoor.\n"},
			["Defeat Dyzera"] =
				{appendText=" in the easternmost chamber of the Cold-Blood Cavern, situated to the east of the Ruins of Mazzatun in Shadowfen.\n\nDyzera, a Shrike, is accountable for the abduction of the Oracles of Azura. \n\nShrikes are towering, pale-skinned humanoid Daedra, pledged in servitude to Nocturnal. They possess striking red eyes and bear a resemblance to female humans, often seen scantily-clad with long hair concealing their breasts.\n"},
			["Return to Rhea"] =
				{appendText=", Kanzin and Muz-Shah in one of the southmost chambers of Cold-Blood Cavern, east of the Ruins of Mazzatun in Shadowfen.\n"},
			["Witness the Prophecy"] =
				{appendText=" that the three oracles invoke.\n\nRhea, Kanzin and Muz-Shah are gathered in a circle in one of the southmost chambers of Cold-Blood Cavern, east of the Ruins of Mazzatun in Shadowfen.\n"},
			["Talk to Azura 3"] =
				{appendText=" through Rhea's body in one of the southmost chambers of Cold-Blood Cavern, east of the Ruins of Mazzatun in Shadowfen.\n", stepTextKey="The Daedric Prince, Azura, took control of Rhea's body once the gazing rite was complete. I should speak with her."},
			["Talk to Rhea 4"] =
				{appendText=" in one of the southmost chambers of Cold-Blood Cavern, east of the Ruins of Mazzatun in Shadowfen.\n", stepTextKey="I saved Azura's oracles, but the specifics of the Daedric plot remain unclear. I should speak with Rhea to conclude our adventure."},
		},
		[GetQuestName(2436)] = { -- "One Last Game"					-- Chaos Blaze
			["Solve the Riddle 1"] =
				{appendText=". I should look near the Merchant District.", stepTextKey="Frodibert's Will posed the riddle: \"After day turns to night, you must follow the light.\" Hmm. What stays lit up at night in the streets of Wayrest?"},
			["Follow the Street Lamp Trail"] =
				{appendText=" in Wayrest."},
			["Search Under the Street Lamp"] =
				{appendText=" by a small bridge on the northmost part of town."},
			["Solve the Riddle 2"] =
				{appendText="", stepTextKey="At the end of the street lamp trail, I found a key with a note attached, offering this clue:\n\n\"You found the key in streets, but now you must search the sky. No time for sleep or drink, go straight to the top of the clouds.\""},
			["Search the Attic Room"] =
				{appendText=" of the Cloudy Dregs Inn."},
			["Open Frodibert Fontbonne's Chest"] =
				{appendText=" on the Cloudy Dregs Inn's attic room."},
			["Keep the Inheritance Money"] =
				{appendText=""},
			["Find Donel Fontbonne and Give Him the Inheritance"] =
				{appendText="\n\nI need to make this decision before taking the money from the chest on the Cloudy Dregs Inn's attic room."},
			["Ask the Wayrest Recruiter About Donel Fontbonne"] =
				{appendText=""},
			["Talk to Recruitment Officer Orgak"] =
				{appendText=" in Wayrest's marketplace."},
			["Take the Money Inside the Chest"] =
				{appendText=" on the Cloudy Dregs Inn's attic room."},
		},
		[GetQuestName(2451)] = { -- "A Ransom for Miranda"			-- Devinstrike
			["Collect Large Ruby"] =
				{appendText=". Looters are rifling through the contents of the nearby houses, no doubt searching for the same gems Serge mentioned. I could try using a disguise to blend in as he suggested or rely on a direct approach.\n"},
			["Collect Large Sapphire"] =
				{appendText=". One particular house stands alone, overlooking the creek below. It seems a fitting place for valuables.\n"},
			["Collect Puffball Caps"] =
				{appendText=". A heap of crates lies piled past the dock's ramp. They should hold the caps Serge needs for his potion.\n"},
			["Talk to Serge Arcole at Boathouse"] =
				{appendText=". If the sleeping potion fails, the gems shouldn't.\n"},
		},
		[GetQuestName(4472)] = { -- "Rat in a Trap"					-- Johnyfreeman
			["Find the Key"] =
				{appendText=". Within the fortification, the bodies of the fallen guards are scattered around, some may have already been looted by the goblins, but near the stable close to the western entrance there are some bodies that seems to be untouched."},
			["Talk to Pierre Lanier"] =
				{appendText=" in the tower where he is caged, east of the western entrance of the Watch."},
		},
		[GetQuestName(4473)] = { -- "Revenge Against Rama"			-- Westrany
			["Talk to Harimal"] =
				{appendText=", a Redguard hunter standing outside a small cave entrance in the northeast of Cumberland's Watch.\n\nRama is on the run after orchestrating the Goblin attack on Cumberland's Watch, which led to numerous deaths. Watch Captain Ernard has charged you with tracking him down and exacting revenge for the death of Commander Kurt by killing Rama.\n"},
			["Confront Rama"] =
				{appendText=" inside the hunter's cave northeast of Cumberland's Watch.\n"},
			["Collect Rama's Sword"] =
				{appendText=" that is lying next to Harimal and feign that you have taken Rama's life.\n"},
			["Talk to Watch Captain Ernard 1"] =
				{appendText=" back at the southeast tower of Cumberland's Watch. \n\nShow him the Rama's Sword as proof of his demise.\n", stepTextKey="I should return to Watch Captain Ernard and give him the story Harimal and I agreed upon."},
			["Talk to Watch Captain Ernard 2"] =
				{appendText=" back at the southeast tower of Cumberland's Watch. \n\nBring him the news of Rama's demise.\n", stepTextKey="Now that Rama is dead, I should return to Watch Captain Ernard and give him the news."},
		},
		[GetQuestName(4516)] = { -- "Stolen Ashes"					-- Devinstrike
			["Talk to Bastien Etanne"] =
				{appendText=". Local hearsay speaks of such a man with a fondness for coastal fishing.\n"},
		},
		[GetQuestName(1527)] = { -- "The Sower Reaps"				-- Immy
			["Search Body"] =
				{appendText=". After saving Arcady Charnis at the Dreugh spawning pools west of Wayrest you spot a body lying next to him in the water above one of the waterfalls."},
			["Search Barracks House"] =
				{appendText=" on the outskirts of Wayrest, according to the note we found Dreugh eggs have been smuggled in by the sack load, with any luck we can find some proof of this."},
			["Confront Baron Sorick"] =
				{appendText=" in the Wayrest outskirts. He's got some explaining to do."},
			["Decide Baron Sorick's Fate"] =
				{appendText=". The man is holed up in a house in Wayrest outskirts."},
			["Talk to Lord Sorick"] =
				{appendText=" in Arbogasque's house on the outskirts of Wayrest."},
			["Talk to Baron Sorick"] =
				{appendText=" in Arbogasque's house on the outskirts of Wayrest."},
			["Catch Baron Sorick"] =
				{appendText=" at the outskirts of Wayrest."},
			["Talk to Constable Charlic 1"] =
				{appendText=" at the outskirts of Wayrest.", stepTextKey="I need to decide if Baron Sorick should be left to the mob or turn in to the guard."},
			["Talk to Constable Charlic 2"] =
				{appendText=" at the outskirts of Wayrest.", stepTextKey="When Baron Sorick fled, the peasants downstairs caught him. He's at their mercy. I should speak to Constable Charlic about this."},
			["Talk to Padier Renoit"] =
				{appendText=" at the Wayrest outskirts. He's understandably angry at the Baron. I'd better have Constable Charlic take control before things get out of hand."},
		},
		[GetQuestName(1485)] = { -- "They Dragged Him Away"			-- Naughtyninja56
			["Find Arcady Charnis"] =
				{appendText=",\n\nThe Dreugh are a nasty breed of sorts. They tend to breed their spawn near a river to the west of Wayrest.\n\nIt is said they coat their prey in small towers of mud and fecal matter to preserve the nutritional value for their newborns.\n\nThe Dreugh are a nasty breed of sorts and will attack on sight. They tend to breed their spawn near the river, pools and waterfalls to the west of Wayrest. \n\nAdiel did mention that they recently took five of the locals. \n\nOnce you free the citizens listen closely as a villager tells you that Arcady Charnis was last seen by the Ancient Statues that are nestled next to the waterfalls at the cross section of the river.\n"},
			["Talk to Arcady Charnis"] =
				{appendText=" near the Ancient Statues in the Dreugh spawning spools west of Wayrest."},
		},
		[GetQuestName(2450)] = { -- "A Woman Wronged"				-- Devinstrike
			["Add Potion to Kegs"] =
				{appendText=".\nThe smugglers are disorganized, chaotic. Their cargo lies strewn around the buildings and beach. Drink tends to attract honest and dishonest alike, some may be guarding nearby.\n"},
			["Search the Counting House"] =
				{appendText=" at Farangel's Landing.'"},
			["Collect the Antidote"] =
				{appendText=" before Miranda meets the same fate as her guards.\n"},
			["Find Miranda"] =
				{appendText=". She was heavily defended by her guards. It's likely she would have stayed out of sight in one of the larger abodes at Farangel's Landing."},
			["Cure Miranda"] =
				{appendText=" in the manor at Farangel's Landing."},
			["Talk to Miranda 1"] =
				{appendText=" inside the manor at Farangel's Landing.", stepTextKey="I delivered the cure. I should speak to Miranda."},
		},
		[GetQuestName(2504)] = { -- "Azura's Relics"				-- Devinstrike
			["Retrieve Nchylbar's Box"] =
				{appendText=". It must be hidden somewhere along the mountainside, perhaps the Dreamers stowed it in a sack near one of their camps for safe keeping.\n"},
			["Retrieve Star Globe"] =
				{appendText=". Hushed whispers among the Dreamers hint the Star may be hidden in a basket within the valley.\n"},
			["Retrieve Scroll of the Morning"] =
				{appendText=". Below the carved mountain sits three tents on a plateau, with a decent grouping of recruits keeping watch among them. It should prove a good place to look.\n"},
			["Find the Captured Spirit Warden"] =
				{appendText=". They would have kept him somewhere protected and out of the way. I should try searching to the east of their encampments.\n"},
			["Collect Conjuration Box Key"] =
				{appendText=" and seal the boxes before the Dreamers can execute their plans. The key must be hidden somewhere nearby, among their packs.\n"},
			["Close Conjuration Box in North Tower"] =
				{appendText=" just above the waterfall.\n"},
			["Close Conjuration Box in South Tower"] =
				{appendText=", overlooking the valley below.\n"},
			["Talk to Spirit"] =
				{appendText=", they appear anxious.\n"},
			["Use Scroll to Reveal Daedra"] =
				{appendText=" and end the veiled threat."},
			["Slay the Daedra"] =
				{appendText=""},
			["Talk to Brother Perry 1"] =
				{appendText=".", stepTextKey="I closed the portal the Supernal Dreamers had opened and slew the Daedra they had summoned. I should rejoin Brother Perry at Tabakah's camp south of the Weeping Giant."},
			["Talk to Brother Perry 2"] =
				{appendText=".", stepTextKey="I closed the portal the Supernal Dreamers had opened and slew the Daedra they had summoned. I should rejoin Brother Perry at Tabakah's camp south of the Weeping Giant."},
		},
		[GetQuestName(2538)] = { -- "Gift from a Suitor"			-- Devinstrike
			["Talk to Mathias Raiment"] =
				{appendText=". He should be waiting somewhere outside Manteau Manor in Wind Keep.\n"},
			["Talk to Elin Gousse"] =
				{appendText=" outside Manteau Manor in Wind Keep, she should know what happened.\n"},
			["Talk to Yarelion"] =
				{appendText=". Rumor says he often pays visits to the local forge.\n"},
			["Talk to Alainne Babiloine"] =
				{appendText=". Her being the town's snoop, she's likely near the Manteau Manor trying to get the latest gossip.\n"},
			["Talk to Raolin or Sir Brice"] =
				{appendText=" at Wind Keep. Roalin is said to have a gift for horsemanship, while Brice has been seen near the local Tavern.\n"},
			["Talk to Sir Brice or Alainne Babiloine"] =
				{appendText=" at Wind Keep. Brice has been seen near the local Tavern. While Alainne, being the town's snoop, is likely near the Manteau Manor trying to get the latest gossiping.\n"},
			["Find Sirion"] =
				{appendText=" far north of Wind Keep at the end of the road at Cumberland Falls and discover the origin of the mirror. Keep an eye open for any of the other people you've met.\n"},
			["Warn the Countess"] =
				{appendText=" at Wind Keep's cemetery east of town before it's too late.\n"},
			["Defend Countess Ilise Manteau"] =
				{appendText="\n"},
			["Talk to Countess Ilise Manteau"] =
				{appendText=" within Wind Keep.\n"},
			["Talk to Raolin Munier or Alainne Babiloine"] =
				{appendText=" at Wind Keep. Roalin is said to have a gift for horsemanship. While Alainne, being the town's snoop, is likely near the Manteau Manor trying to get the latest gossip."},
		},
		[GetQuestName(2537)] = { -- "King Aphren's Sword"			-- Devinstrike
			["Recover the Blade"] =
				{appendText=". The glint of a chest can be seen from the southern Tower's Dilapidated top in Aphren's Ruins. "},
			["Recover the Hilt"] =
				{appendText=" from within the northern tower.\n"},
			["Recover the Pommel"] =
				{appendText=" in the eastern tower.\n"},
			["Enter Aphren's Tomb"] =
				{appendText=" within the ruins and restore the blade.\n"},
			["Find the King's Crypt"] =
				{appendText=" in Aphren's Tomb at the western end of Aphren's Hold."},
			["Talk to King Aphren 1"] =
				{appendText="'s specter in Aphren's Tomb at the western end of Aphren Hold.", stepTextKey="A shade of King Aphren appeared. Perhaps he knows what I need to do to reforge the sword."},
			["Take Aphren's Sword to Mira at Her Crypt"] =
				{appendText=" in Aphren's Tomb at the western end of Aphren Hold."},
			["Take Aphren's Sword to Blaise at the Ruin Entrance"] =
				{appendText=" located at the southern exit of Aphren's hold."},
			["Talk to King Aphren 2"] =
				{appendText=" at his Crypt in Aphren's Tomb at the western end of Aphren Hold.", stepTextKey="Princess Mira understood the significance of receiving her father's sword. She came to speak with him for the first time in centuries. I should speak with the king's spirit now to say goodbye."},
			["Talk to Blaise Pamarc"] =
				{appendText=" outside the ruins at the southern exit of Aphren Hold."},
		},
		[GetQuestName(614)]  = { -- "A Look in the Mirror"			-- Devinstrike
			["Talk to Countess Ilise Manteau 1"] =
				{appendText="\n", stepTextKey="I should seek out Countess Ilise Manteau in her home and see if I can help with whatever is affecting her."},
			["Examine Ilise's Mirror"] =
				{appendText=" in the Manteau Manor.\n"},
			["Talk to the Reflective Spirit"] =
				{appendText="at Manteau Manor and discover the source of Ilise's ruminations.\n"},
			["Enter Ilise's Mirror"] =
				{appendText=" and retrieve the Countess.\n"},
			["Rescue Countess Ilise Manteau"] =
				{appendText=" from the illusion.\n"},
			["Exit Ilise's Mirror"] =
				{appendText=" in Manteau Manor and retrieve the Countess."},
			["Talk to Countess Ilise Manteau 2"] =
				{appendText=" and make certain she's recovered.\n", stepTextKey="I rescued Countess Ilise Manteau from her mirror. Now that her mind is clear, I should speak to her about what happened."},
		},
		[GetQuestName(1615)] = { -- "Next of Kin"					-- Devinstrike
			["Talk to Mashana in Wind Keep"] =
				{appendText=", and inform them of the fate of Hubert and his wife and child. Hubert came to mine in the hopes of escaping debt. It stands to reason his relation would be among the settlement's working class.\n"},
		},
		[GetQuestName(1341)] = { -- "Ogre Teeth"					-- Westrany
			["Collect Ogre Teeth"] =
				{appendText="\n\nYou are tasked with gathering exactly 124 Ogre Teeth from the encroaching Ironhand Ogres of Shinji's Scrap.\n\nShinji's Scarp, located in eastern Stormhaven northeast of Aphren's Hold, hosts the Murtag Clan's encampment and a couple of scattered buildings to the south, where Ogres and Orcs are locked in ceaseless combat.\n"},
			["Talk to Captain Dugakh"] =
				{appendText=" outside the Fighters Guild tent in the Murtag Clan encampment, south of Shinji's Scrap.\n\nGive him the 124 Ogre Teeth he's asked you to collect.\n"},
		},
		[GetQuestName(1384)] = { -- "Old Adventurers"				-- Devinstrike
			["Free Dro-Dara"] =
				{appendText=", the magic user of the old band, from the looters who have them held nearby. The plantation is a mess of bodies and drowned crops. Even looters would take captives somewhere out of the elements.\n"},
			["Free Murk-Watcher"] =
				{appendText=". Janne mentioned that the workers had either fled or been slain, but the plantation's windmill turns steadily. Outside, looters stand as if on watch. What could they be guarding?\n"},
			["Free Knarstygg"] =
				{appendText=", who's being held by a band of looters. Janne said he'd been tied up and is likely being kept out of sight. The doors of an abandoned barn nearby have been swung wide; I should investigate.\n"},
			["Talk to Dro-Dara at the Storehouse"] =
				{appendText=". He ran towards the southwest, and a somewhat intact building between the ruined fields and windmill."},
		},
		[GetQuestName(1383)] = { -- "The Perfect Burial"			-- Devinstrike
			["Collect Fallen Blossoms"] =
				{appendText="\nWhile flowers often bloom along the hillside, I could ask Michel if he knowns a more specific place.\n"},
			["Collect Mudcrab Claws"] =
				{appendText="\nMichel might know where more can be found, but I also spotted several by the stream running beside his home.\n"},
			["Collect Wayside Inn House Wine"] =
				{appendText=". A few scattered townsfolk pace near the local tavern. It's a good bet some wine can be bought within. Being a local, Michel may know more.\n"},
			["Talk to Michel Helomaine"] =
				{appendText=" outside his home. Perhaps these will offer a semblance of closure.\n"},
		},
		[GetQuestName(2536)] = { -- "Plowshares to Swords"			-- Devinstrike
			["Talk to Knarstygg 1"] =
				{appendText=". He's behind the Storehouse, likely debating what path to tread.\n", stepTextKey="I should seek out Knarstygg and ask how he feels about leaving."},
			["Collect Knarstygg's Armor"] =
				{appendText=". Along the coast's northern edge, the levee has broken in two places, carving a small creek through the fields. Anything buried there would have surely been unearthed.\n"},
			["Collect Knarstygg's Axe"] =
				{appendText=". A section of the broken levee to the east has revealed disturbed soil in wake of the floodwaters.\n"},
			["Collect Knarstygg's Helm"] =
				{appendText=". The levee is in ruins to the north, east, and south. I should search every direction.\n"},
			["Talk to Knarstygg 2"] =
				{appendText=", who's probably waiting behind the Storehouse, growing increasingly eager to leave.", stepTextKey="I recovered Knarstygg's gear. I should give it to him."},
		},
		[GetQuestName(1339)] = { -- "A Predator's Heart"			-- Devinstrike
			["Talk to Murk-Watcher 1"] =
				{appendText=", who's watching a pair of crocodiles from the midst of the drowned fields.\n", stepTextKey="I need to speak with Murk-Watcher about leaving."},
			["Lure out Ripplestrike and Collect His Heart"] =
				{appendText=". Beside a large outcropping of boulders and facing the coast lies a nest built of wood and bone; this should be a good place to set Murk-Watcher's charm.\n"},
			["Talk to Murk-Watcher 2"] =
				{appendText=". With the heart in hand, I should return to her in the drowned fields so the ritual may begin.\n", stepTextKey="I must take Ripplestrike's heart back to Murk-Watcher."},
			["Talk to Murk-Watcher 3"] =
				{appendText=". She said her memory of me, of her friends, will soon fade once the transformation is complete. When we begin, I should act quickly.\n", stepTextKey="I should tell Murk-Watcher when I'm ready to help get revenge on the bandits."},
			["Kill Dalag-dar"] =
				{appendText=", whose encampment is nestled near the windmill.\n"},
			["Talk to Dro-Dara"] =
				{appendText=" back within the Storehouse.\n"},
		},
		[GetQuestName(4519)] = { -- "Word from the Dead"			-- Devinstrike
			["Talk to Augustine Derone"] =
				{appendText=". The largest nearby town is Wayrest, to the south. Assuming she knows he's missing, she could be praying for his safe return.\n"},
		},


-- 		=========================================================================
--		  Alik'r Desert Main
-- 		=========================================================================
		[GetQuestName(3333)] = { -- "Risen From the Depths"			-- NaeomiFriz
			["Find a Sentinel Docks Guard"] =
				{appendText=""},
			["Speak to Watchman Maujad"] =
				{appendText=" on the longest dock."},
			["Rescue Watchman Jessmyn"] =
				{appendText=" on the small dock southwest of the docked ship."},
			["Rescue Watchman Pierjean"] =
				{appendText=". Whom is holding out on a small docked sailboat."},
			["Rescue Watchman Emydal"] =
				{appendText=" in between the warehouses on the shore."},
			["Meet Watchman Maujad"] =
				{appendText=""},
			["Find the Dockmaster"] =
				{appendText=""},
			["Find the Ritual Location"] =
				{appendText=" a clue can be found at the western warehouse."},
			["Disrupt the Ritual"] =
				{appendText=" on the beach west of the docks."},
			["Talk to Watch Captain Zafira"] =
				{appendText=" on the west side of the docks."},
		},
		[GetQuestName(2130)] = { -- "Rise of the Dead"				-- NaeomiFriz
			["Talk to King Fahara'jad"] =
				{appendText=". His palace is in Sentinel."},
			["Talk to General Thoda"] =
				{appendText=". He lives east of of the palace in Sentinel."},
			["Find Prince Azah"] =
				{appendText=". I might find him in the building east of Scholars Way in Sentinel."},
			["Talk to Ilmaha at-Amil"] =
				{appendText=" in a royal building east of Scholar's Way in Sentinel."},
			["Pursue the Kidnappers"] =
				{appendText=" northwest of Scholar's Way in Sentinel."},
			["Search for Prince Azah"] =
				{appendText=" in a cave north of the Forebear's forge, underneath Sentinel."},
			["Free Prince Azah"] =
				{appendText=" in a cave north of Forebears Forge in sentinel, under the city."},
		},
		[GetQuestName(2146)] = { -- "The Impervious Vault"			-- NaeomiFriz
			["Escort the Prince to the Palace"] =
				{appendText=" in Sentinel. He's in a cave north of Forebear's Forge, outside and under the city."},
			["Meet Prince Azah at the Palace"] =
				{appendText=" in Sentinel."},
			["Talk to the King"] =
				{appendText=" in the palace in Sentinel."},
			["Talk to Gabrielle at the Mages Guild"] =
				{appendText=" Hall in Sentinel."},
			["Collect Flame Stalk"] =
				{appendText=". Lizards are known to like them. I should check around the Bazaar in Sentinel for someone who would sell them."},
			["Collect Worm's Head Cap"] =
				{appendText=". I should ask around the Bazaar in Sentinel."},
			["Meet Gabrielle Benele at the Impervious Vault"] =
				{appendText=". It is east of the Sentinel Palace."},
			["Talk to King Fahara'jad 1"] =
				{appendText=". He is within the entrance to the Vault, east of the palace in Sentinel.", stepTextKey="Gabrielle Benele can use the reagents I gathered to break the seal on the Impervious Vault just enough to let one person inside. Apparently, she and the king have nominated me. I should speak to the king before she begins the spell."},
			["Wait for Gabrielle Benele to Open Vault"] =
				{appendText=" east of the palace in Sentinel."},
			["Explore the Impervious Vault"] =
				{appendText=". The entrance is east of the palace in Sentinel."},
			["Talk to Ansei Radan"] =
				{appendText=" deep in the vault, the entrance is east of the palace in Sentinel."},
			["Talk to King Fahara'jad 2"] =
				{appendText=". He is within the entrance to the Vault, east of the palace in Sentinel.", stepTextKey="I defeated the Withered Hand in the vault, but it seems some of them escaped with the Ansei Wards. I should inform the king."},
		},
		[GetQuestName(2408)] = { -- "In Search of the Ash'abah"		-- NaeomiFriz
			["Find the Ash'abah Camp"] =
				{appendText=""},
			["Speak to Mazra"] =
				{appendText=" at the Ash'abah camp in Morwha's Bounty."},
		},
		[GetQuestName(4672)] = { -- "Morwha's Curse"				-- NaeomiFriz
			["Meet Talia At Her Tent"] =
				{appendText=". It is the one furthest east in the camp in Morwha's Bounty."},
			["Collect Dry Juniper Leaf"] =
				{appendText=". I can find this east of  the Ash'abah camp in Morwha's Bounty. The goats in this area love the taste of them in Morwha's Bounty."},
			["Collect Cave Palm Fruit"] =
				{appendText=". Unfortunately, some Hags have set up camp next to the only source of the fruit southeast of camp in Morwha's Bounty."},
			["Collect Satakal's Blossom"] =
				{appendText=".  I can find some of these flowers at one of the wells south of camp in Morwha's Bounty."},
			["Collect Cactus Powder"] =
				{appendText=". A little up the hill from the well where I found the blossom is a small shaded nook, I can find the cactus there near an unfortunate adventurer who's remains have been stripped by the elements in Morwha's Bounty."},
			["Go to Marimah's Tent"] =
				{appendText=" at the camp in Morwha's Bounty."},
			["Talk to Marimah 1"] =
				{appendText=" at the Ash'abah camp in Morwha's Bounty.", stepTextKey="Marimah, the Ash'abah chieftain, is sickened with poison, but he wishes to speak with me."},
			["Talk to Marimah 2"] =
				{appendText=" in his tent in the Ash'abah camp in Morwha's Bounty.", stepTextKey="Marimah revealed that the ingredients we gathered were not for his antidote but were for my initiation into the Ash'abah tribe. I should tell him when I'm ready to begin the initiation."},
		},
		[GetQuestName(4686)] = { -- "The Initiation"				-- NaeomiFriz
			["Talk to Talia 1"] = 
				{appendText=" in the Ash'abah camp in Morwha's Bounty.", stepTextKey="I must speak to Talia to get the potion for the ritual."}, 
			["Drink the Potion"] = 
				{appendText=". I should do so somewhere comfortable in the Ash'abah's camp in Morwha's Bounty.\n\nIn the hut west of a water pool should work."}, 
			["Talk to Prince Haqmir 1"] = 
				{appendText=" in his tent next to the fountain in the southern Ra Gada camp.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty.", stepTextKey="I am in a vision of the past. A prince named Haqmir has just woken me. I should speak to him and hear what he has to say."}, 
			["Go to the Courtyard"] = 
				{appendText=" in the Ash'abah pass in Morwha's Bounty.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Listen to the King's Speech"] = 
				{appendText=" in the courtyard of the Ra'Gada camp.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Talk to the King"] = 
				{appendText=" in the courtyard of the Ra'Gada camp.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Collect Your Brother From His Tent"] = 
				{appendText=", one of the larger of the two in the Ra Gada camp.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Reach the Elven Leader"] = 
				{appendText=". I should march north through the pass to find them. \n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Kill Kinlady Iniel"] = 
				{appendText=". She's through the north of the Ash'abah pass, near to the water. \n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Enter the Crypt Passage"] = 
				{appendText=" the crypt is to the east of where the path north through Ash'abah pass ends.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Enter the Palace"] = 
				{appendText=", I can find my way to it through the crypt east of where the path north through Ash'abah pass ends.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Talk to the Vizier 1"] = 
				{appendText=", I can find him at the fountain in the palace which I can access through the crypt at the northern end of the Ash'abah pass.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty.", stepTextKey="I am in a vision of the past. I killed an enemy Elven warlord who says she sent assassins to kill my father. I've returned to the castle. I should speak with the vizier to find out what's happened."}, 
			["Talk to Prince Haqmir 2"] = 
				{appendText=", I can find him at the fountain in the palace which I can access through the crypt at the northern end of the Ash'abah pass.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty.", stepTextKey="I am in a vision of the past. An Elven necromancer has killed and then raised my father, King Xakhwan. It would mean terrible dishonor to strike my father down. I must speak to my brother."}, 
			["Enter the Throne Room"] = 
				{appendText=". The entrance to it is north of a fountain in the palace which I can access through the crypt at the northern end of the Ash'abah pass.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Kill Wraithmaster Venerien"] = 
				{appendText=". The entrance to the throne room he is in is north of a fountain in the palace which I can access through the crypt at the northern end of the Ash'abah pass.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Talk to Prince Haqmir 3"] = 
				{appendText="", stepTextKey="I am in a vision of the past. An Elven necromancer killed and raised my father, King Xakhwan. It will be deemed a terrible dishonor, but I took it upon myself and struck him down. I must speak with my brother, Prince Haqmir."}, 
			["Talk to the Vizier 2"] = 
				{appendText=", I can find them at the fountain in the palace. Its entrance is through the crypt east of where the path north through Ash'abah pass ends.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty.", stepTextKey="I am in a vision of the past. An Elven necromancer killed and raised my father, King Xakhwan. It will be deemed a terrible dishonor, but I took it upon myself and struck him down. I must speak with my brother, Prince Haqmir."}, 
			["Leave the Palace 1"] = 
				{appendText=". The exit is south of the fountain in the palace which i can access through the crypt at the northern end of the Ash'abah pass.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty.", stepTextKey="I am in a vision of the past. An Elven necromancer killed and raised my father, King Xakhwan. Though I knew the consequences, I struck my father down and now face exile. I should leave the castle."}, 
			["Talk to Talia 2"] = 
				{appendText=" in the Ash'abah camp in Morwha's Bounty.", stepTextKey="I experienced a vision of the past in which a Yokudan Prince was exiled for striking down his undead father. I must speak with the Ash'abah chieftain's daughter, Talia."}, 
			["Talk to Talia 3"] = 
				{appendText=" in the Ash'abah camp in Morwha's Bounty.", stepTextKey="I experienced a vision of the past in which a Yokudan Prince was exiled for striking down his undead father. I must speak with the Ash'abah chieftain's daughter, Talia."}, 
			["Wait for the Deed to Be Done"] = 
				{appendText=" in the palace which I can access through the crypt at the northern end of the Ash'abah pass.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Speak to Your Brother"] = 
				{appendText=". He's in the ceremony room of the palace which I can access through the crypt at the northern end of the Ash'abah pass.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty."}, 
			["Leave the Palace 2"] = 
				{appendText=". The exit is south of the fountain in the palace which I can access through the crypt at the northern end of the Ash'abah pass.\n\nI can reenter the dream in the hut west of a water pool in the Ash'abah camp in the present, at Morwha's Bounty.", stepTextKey="I am in a vision of the past. An Elven necromancer killed and raised my father, King Xakhwan. Though he knew the consequences, my brother struck my father down and now faces exile. I should leave the castle."}, 
			["Speak to Talia 1"] = 
				{appendText=" in the Ash'abah camp in Morwha's Bounty.", stepTextKey="I experienced a vision of the past in which a Yokudan Prince was exiled for striking down his undead father. I must speak with the Ash'abah chieftain's daughter, Talia."}, 
			["Speak to Talia 2"] = 
