		[GetQuestName(4694)] = { -- "Word from the Throne"			-- NaeomiFriz
			["Speak to Vizier Bolura"] =
				{appendText=" at Sentinel Palace, a mighty structure within the southeast quarter of Sentinel.\n\nAmidst the vast sands of the Alik'r Desert, stands Tu'whacca's Throne, an ancient Yokudan temple. The sacred dead entombed within have mysteriously risen, yet striking them down would defile the Redguard's deepest beliefs.\n\nThrone Keeper Favard, a Redguard priest of Tu'whacca, implores you to carry word of this dire event to King Fahara'jad's Vizier without delay."},
		},
		[GetQuestName(4816)] = { -- "A Blessing for the Dead"		-- NaeomiFriz
			["Seek out Luala al-Tava"] =
				{appendText=", a Redguard Thronekeeper rumored to have established camp outside Tu'whacca's Throne, an ancient Yokudan temple nestled in the heart of the Alik'r Desert, southeast of Sentinel.\n\nOn your way to the porty city of Tava's Blessing, you encountered a red guard woman sobbing over the recently deceased body of her loved one. She begs you to find a priestess who can consecrate the body."},
		},
		[GetQuestName(4817)] = { -- "Tracking the Hand"				-- NaeomiFriz
			["Talk to Sergeant Hadima"] =
				{appendText=" at the city port of Tava's Blessing, in northeast Alik'r Desert.\n\nThe Motalion Necropolis, a vast and ancient Yokudan burial ground in the northeastern Alik'r Desert, has fallen under the control of the Withered Hand, a sinister group of Redguard necromancers spreading terror among the desert folk. \n\nYou’re not certain where Sergeant Hadima is within Tava's Blessing, but your instincts tell you she’s likely hiding in the southern outskirts of the city, concealed within one of the buildings."},
		},


