		[GetQuestName(4659)] = { -- "Lady Laurent's Favor"			-- NaeomiFriz
			["Talk to Tamien 1"] =
				{appendText=". He's on the top of a wood scaffold in the north east part of the ruins.", stepTextKey="Stibbons suggested I find and speak to Tamien."},
			["Collect Lost Tools"] =
				{appendText=".\nI could be persuasive to Tamien for a some tools.\nI can find the bags strewn about the ruins, just the same look as a common backpack. I should check hotspots of Dominion activity, as well."},
			["Return Tools to Stibbons"] =
				{appendText=". He's in a tent in the camp northeast of the central ruins."},
			["Return Tools to Tamien"] =
				{appendText=". He's on the top of a wood scaffold in the north east part of the ruins."},
			["Talk to Stibbons"] =
