		[GetQuestName(2161)] = { -- "Monkey Magic"					-- NaeomiFriz
			["Talk to Unishi 1"] =
				{appendText="\n", stepTextKey="I promised the monkey that I'd talk to Unishi in Sentinel's tavern and ask her to change him back."},
			["Deliver Potions"] =
				{appendText="\nWord around town is that one customer of Unishi's frequents the local Inn, while the other lives with their mate in a house near the docks.\n"},
			["Talk to Unishi 2"] =
				{appendText=" If these customers have revealed anything, it's that she'll likely stand by her word.\n", stepTextKey="I should return to and speak to Unishi."},
			["Take the Potion to the Monkey"] =
				{appendText=". He must be near where I first encountered him near the tavern."},
		},
		[GetQuestName(3353)] = { -- "The Nature of Fate"			-- SamPhysis
			["Talk to Anjan 1"] =
				{appendText=" behind a small house, located to the east of the Rain Catcher Fields or southwest of Alezer Kotu.", stepTextKey="To prove his beliefs, Anjan threw bones onto the sand and prophesied I would win a race against a storm. I must run across the desert, following the trail of blue flames, so I can reach the end before the storm does."},
			["Beat the Storm"] =
				{appendText=" forming around Alezer Kotu. The storm is circling northeast and then getting pulled back to the south, leaving fiery trails of lightning in its path."},
			["Talk to Anjan 2"] =
				{appendText=" kneeling on-top of his fortune telling bones, east of the Rain Catcher Fields.", stepTextKey="The storm beat me to the last fire. I should return to Anjan."},
			["Talk to Anjan 3"] =
				{appendText=" back at his little ritual site, southwest of Alezer Kotu.", stepTextKey="I beat the storm to the last fire! I must now speak to Anjan."},
		},
		[GetQuestName(3305)] = { -- "The Oldest Orc"				-- NaeomiFriz
