			["Talk to Herminius Sophus 2"] =
				{appendText=" at the camp south of a shipwreck.", stepTextKey="Though the sword may be cursed, I decided to give it to Herminius Sophus to take with him to Cyrodiil."},
		},
		[GetQuestName(2187)] = { -- "Revered Ancestors"				-- NaeomiFriz
			["Choose Healer"] =
