[GetQuestName(4783)] = { --"The Weight of Three Crowns"			--Rosque --Jordakai

    ["Return to Vanus Galerion"] = {
        appendStepText = {
            [ALLIANCE_ALDMERI_DOMINION] = "",
            [ALLIANCE_DAGGERFALL_COVENANT] = "",
            [ALLIANCE_EBONHEART_PACT] = ""
        },
        stepTextKey = "I wandered off before Vanus could begin casting the portal to Stirk. He'd probably like it if I returned.",
        appendText = {
            [ALLIANCE_ALDMERI_DOMINION] = " inside the Vulkhel Guard Fighters Guild in Auridon.",
            [ALLIANCE_DAGGERFALL_COVENANT] = " inside the Wayrest Fighters Guild in Stormhaven.",
            [ALLIANCE_EBONHEART_PACT] = " inside the Mournhold Fighters Guild in Deshaan."
        }
    },

    ["Wait for Portal 1"] = {
        appendStepText = {
            [ALLIANCE_ALDMERI_DOMINION] = "In Auridon at the Vulkhel Guard Fighters Guild, ",
            [ALLIANCE_DAGGERFALL_COVENANT] = "In Stormhaven at the Wayrest Fighters Guild, ",
            [ALLIANCE_EBONHEART_PACT] = "In Deshaan at the Mournhold Fighters Guild, "
        },
        stepTextKey = "I need to wait for Vanus Galerion to open the portal to Stirk.",
        appendText = {
            [ALLIANCE_ALDMERI_DOMINION] = " inside the guildhall.",
            [ALLIANCE_DAGGERFALL_COVENANT] = " inside the guildhall.",
            [ALLIANCE_EBONHEART_PACT] = " inside the guildhall."
        }
    },

    ["Enter Portal to Stirk"] = {
        appendStepText = {
            [ALLIANCE_ALDMERI_DOMINION] = "",
            [ALLIANCE_DAGGERFALL_COVENANT] = "",
            [ALLIANCE_EBONHEART_PACT] = ""
        },
        stepTextKey = "I need to enter Vanus Galerion's portal to travel to Stirk.",
        appendText = {
            [ALLIANCE_ALDMERI_DOMINION] = " inside the Vulkhel Guard Fighters Guild in Auridon.",
            [ALLIANCE_DAGGERFALL_COVENANT] = " inside the Wayrest Fighters Guild in Stormhaven.",
            [ALLIANCE_EBONHEART_PACT] = " inside the Mournhold Fighters Guild in Deshaan."
        }
    },

    ["Talk to Vanus Galerion 1"] = {
	appendText=" in front of ruined arches on a small Ayleid outcropping that extends into the ocean.",
	 stepTextKey="I arrived on the island of Stirk. Now I need to talk to Vanus Galerion."
    },

    ["Go to Summit Point"] = {
	appendText=" in the center of the ruins. Vanus suggested talking to some of the experts he's gathered along the way."
    },

    ["Listen to the Alliance Leaders"] = {
	appendText=" in the center of the ruins."
    },

    ["Talk to Vanus Galerion 2"] = {
	appendText=" in the center of the ruins.",
	stepTextKey="The alliance leaders can't reach an agreement. I should ask Vanus Galerion and Countess Hakruba what they think."
    },

    ["Talk to Countess Hakruba"] = {
	appendText=" in the center of the ruins."
    },

    ["Talk to the Alliance Leaders"] = {
	appendText=" in their Alliance camps on Stirk. They've spread out in cardinal directions to get distance from each other, but they may be more inclined to listen to reason if approached individually."
    },

    ["Talk to Vanus Galerion 3"] = {
	appendText=" in the middle of Stirk.",
	stepTextKey="I spoke to the alliance leaders. They seem willing to allow the Guilds to take the fight to Molag Bal, but still they hesitate. I should let Vanus Galerion know where things stand."
    },

    ["Close the Unstable Rifts"] = {
	appendText=" \n\nMolag Bal likely opened one in the middle of each Alliance's camp to cause as much damage as possible."
    },

    ["Talk to Vanus Galerion 4"] = {
	appendText=" in the center of Stirk.",
	stepTextKey="I closed the unstable rifts and saved the three alliance leaders. Now I should talk to Vanus Galerion."
    },

    ["Enter the Portal Valley"] = {
	appendText=" through the Ayleid door up the road into the deeper ruins of Stirk."
    },

    ["Talk to Vanus Galerion 5"] = {
	appendText=" within Stirk's interior ruins. It may be worth checking what members of the guilds survived and are still ready after Molag Bal's attack.",
	stepTextKey="With the permission of the Kings and Queen of the three alliances, the Mages Guild and the Fighters Guild have gathered in the portal valley to open a path to Coldharbour. I should talk to Vanus and make sure we're ready to go."
    },

    ["Wait for Portal 2"] = {
	appendText=" within the interior of Stirk's Ayleid ruins.",
	stepTextKey="I need to wait for Vanus Galerion to open the portal to Coldharbour."
    },

    ["Take Portal to Coldharbour"] = {
	appendText=" within the interior of Stirk's Ayleid ruins."
    },

    ["Talk to Cadwell"] = {
	appendText=" atop the stairs near his hovel, where burning blue braziers shine around the entrance to what looks like a massive stone tomb."
    },
},



		[GetQuestName(4605)] = { -- "The Hollow City"				-- Rosque
			["Find the Hollow City"] =
				{appendText=". Cadwell, sitting outside his hovel, isn't always coherent, but he may be able to provide better directions. If it really is a city, there must be someone inside that knows more about it. It may be a good idea to check around the entrances or any brightly-lit roads."},
			["Talk to The Groundskeeper 1"] =
				{appendText=" near The Shining Star.", stepTextKey="I should talk to the Groundskeeper to learn more about the Hollow City."},
			["Follow the Groundskeeper and Listen to Her Tale"] =
				{appendText="."},
			["Talk to The Groundskeeper 2"] =
				{appendText=" on the steps of the temple.", stepTextKey="The Groundskeeper has finished giving me a tour of the Hollow City. I should speak to her."},
			["Talk to The Groundskeeper 3"] =
				{appendText=" on the steps of the temple.", stepTextKey="I should speak to the Groundskeeper and see if she has a suggestion on how to proceed."},
			["Talk to The Groundskeeper 4"] =
				{appendText=" on the steps of the temple.", stepTextKey="I should speak to the Groundskeeper and see if she has a suggestion on how to proceed."},
		},
		[GetQuestName(4610)] = { -- "The Army of Meridia"			-- Rosque
			["Rescue King Laloriaran Dynar"] =
				{appendText=" from his dark tower prison and return him to the Hollow City's Fighters Guild. Before entering the Moonless Walk, it would be a good idea to scour the road for signs of life and any supplies that might have been left behind."},
			["Rescue Vanus Galerion"] =
				{appendText=" and return him to the Hollow City's Mages Guild. His exact location is unknown, but searching the roads east of the city for clues could be a good place to start."},
			["Restore the Hollow City"] =
				{appendText=". The Groundskeeper seems to be keeping an eye on the fighters and mages guildhalls, and may have an understanding of how to proceed and how many survivors remain outside in Coldharbour."},
			["Talk to the Groundskeeper outside the Chapel"] =
				{appendText="."},
			["Enter the Chapel of Light"] =
				{appendText=" in the Hollow City."},
			["Attend the Council of War"] =
				{appendText=". King Laloriaran Dynar seems to be taking the lead."},
			["Talk to King Laloriaran Dynar 1"] =
				{appendText=" inside the Chapel of Light in the Hollow City.", stepTextKey="We destroyed the Great Shackle, but the Planemeld continues. The Council of War has decided to assault the Chasm and fight our way to the remaining planar vortex. Only then can we sever the connection and save Nirn from the Planemeld."},
			["Talk to King Laloriaran Dynar 2"] =
				{appendText=" inside the Chapel of Light in the Hollow City.", stepTextKey="We destroyed the Great Shackle, but the Planemeld continues. The Council of War has decided to assault the Chasm and fight our way to the remaining planar vortex. Only then can we sever the connection and save Nirn from the Planemeld."},
		},



[GetQuestName(4399)] = { --"Into the Woods"				-- Rosque -- Jordakai
       ["Examine the Note Nearby"] =
            {appendText=" the abandoned pack, hiding behind a spire of stone just past the bridge south of Spurned Peak."},
       ["Search the Camp"] =
            {appendText=" on the road past the Library of Dusk, just before the Moonless Walk."},
        ["Find the Fighters Guild Members"] =
            {appendText=" in the Moonless Walk. The abandoned camp on the road just past the Library of Dusk Wayshrine should be a good starting point. A common navigation tactic is to move while keeping close to the left-most wall. The Fighters Guild may have followed that tactic as they traveled into the woods, and may have left additional clues."},
        ["Talk to Faraniel 1"] =
            {appendText=" at the burning campfire halfway between the Lightless Oubliette and the abandoned camp on the road just past the Library of Dusk Wayshrine.", stepTextKey="At a campfire that was still burning, I found one of the Fighters Guild members. He was dead and Faraniel stood over his body. She claims she didn't kill him. I should talk to her and see what she knows."},
        ["Collect Spriggan Bark"] =
            {appendText=". There should be some in the Moonless Walk."},
        ["Bring the Spriggan Bark to Faraniel"] =
            {appendText=" at the burning campfire halfway between the Lightless Oubliette and the abandoned camp on the road just past the Library of Dusk Wayshrine."},
        ["Follow a Shadow Runner"] =
            {appendText=" through the Moonless Walk. The other side of the bridge from Faraniel would be further east from the Lightless Oubliette. It may be necessary to keep touching wisps in case the magic begins to wane."},
        ["Talk to Sergeant Kamu"] =
            {appendText=" at the eastern wall in front of the Lightless Oubliette."},
        ["Ask the Lamia for Help"] =
            {appendText=" just east of the Lightless Oubliette."},
        ["Ask the Wood Elf for Help"] =
            {appendText=" just east of the Lightless Oubliette."},
        ["Talk to Faraniel 2"] =
            {appendText=" just east of the Lightless Oubliette.", stepTextKey="Sergeant Kamu was trying to get into the tower at the edge of this dark forest. Both the lamia and the Wood Elf claim to know how to get inside. I should decide which of the two to ask for help."},
        ["Talk to Tzik'nith"] =
            {appendText=", just east of the Lightless Oubliette."},
        ["Talk to Faraniel 2"] =
            {appendText=", just east of the Lightless Oubliette.", stepTextKey="Sergeant Kamu was trying to get into the tower at the edge of this dark forest. Both the lamia and the Wood Elf claim to know how to get inside. I should decide which of the two to ask for help."},
    },
		[GetQuestName(4654)] = { -- "An Unusual Circumstance"		-- Rosque
			["Collect the Stolen Lamia Eggs"] =
				{appendText="\nThe Shadow Walkers make their homes in the northeast part of The Moonless Walk."},
			["Talk to Tzik'nith Near the Wood Elf Camp"] =
				{appendText=". She should be hiding somewhere under the base of one of their empty tree platforms in the northeastern part of The Moonless Walk."},
			["Collect the Shard of Darkness"] =
				{appendText=" from one of the the hollow Shadow Walker treehouses in the northeastern part of The Moonless Walk."},
			["Collect the Shard of Light"] =
				{appendText=" from one of the the hollow Shadow Walker treehouses in the northeastern part of The Moonless Walk."},
			["Meet the Lamias at the Central Camp"] =
				{appendText=" at the ruins next to the burning campfire in the middle of The Moonless Walk. The fire is visible from both the ruined Ayleid bridge and the sagging rope bridge that crosses the river of azure plasm."},
			["Use the Shards to Open the Council Portal"] =
				{appendText=" at the ruins next to the burning campfire in the middle of The Moonless Walk. The fire is visible from both the ruined Ayleid bridge and the sagging rope bridge that crosses the river of azure plasm."},
			["Talk to Queen Fah'jik"] =
				{appendText=" through the portal in the ruins next to the burning campfire in the middle of The Moonless Walk. The fire is visible from both the ruined Ayleid bridge and the sagging rope bridge that crosses the river of azure plasm."},
			["Talk to Tzik'nith"] =
				{appendText=" by the Moonless Walk Wayshrine."},
			["Enter the Ruined Passage"] =
				{appendText=" near the Moonless Walk Wayshrine."},
			["Collect Light of Meridia"] =
				{appendText=", the imprisoned crystal inside the Ruined Passage near the Moonless Walk Wayshrine."},
			["Talk to the Projection of King Laloriaran Dynar 1"] =
				{appendText=" inside the Ruined Passage near the Moonless Walk Wayshrine.", stepTextKey="I collected the Light of Meridia. Now I should speak to the projection of the Ayleid King and see what I should do next."},
			["Talk to the Projection of King Laloriaran Dynar 2"] =
				{appendText=" inside the Ruined Passage near the Moonless Walk Wayshrine.", stepTextKey="I collected the Light of Meridia. Now I should speak to the projection of the Ayleid King and see what I should do next."},
		},
		[GetQuestName(4679)] = { -- "The Shadow's Embrace"			-- Jordakai
			["Meet Faraniel at the Bridge"] =
				{appendText=" of rope and wood that spans the luminous waters in the Moonless Walk.\n"},
			["Talk to Faraniel 1"] =
				{appendText=" on the wooden span in the Moonless Walk.\n", stepTextKey="As I reached the bridge, Faraniel came running out of the woods. I should speak to her."},
			["Defeat the Lamia Champion"] =
				{appendText=" in her cave on a ridge above the Lamias' camps, south of the Lightless Oubliette.\n"},
			["Cause Chaos In the Lamia Camps"] =
				{appendText="\n\nThe lamias live at the edge of the Moonless Walk.\n"},
			["Return to the Center Camp"] =
				{appendText=" near The Moonless Walk's two bridges.\n"},
			["Talk to Faraniel 2"] =
				{appendText=" here by the fire in the Moonless Walk.\n", stepTextKey="There are more Shadow Walkers at the camp and they haven't attacked me yet. That's a good sign. I should talk to Faraniel and see what I need to do next."},
			["Talk to the Wood Elves"] =
				{appendText="\n\nThe Moonless Walk Shadow Walkers are suspicious as they wait near the dancing flames.\n"},
			["Talk to Faraniel 3"] =
				{appendText=" in the Moonless Walk near the portal stone by the campfire.\n", stepTextKey="Faraniel has returned and apparently has good news. I should speak to her."},
			["Convince the Council to Break Its Vow"] =
				{appendText="\n\nThe Shadow Walkers have disappeared into the woods, but what was learned by speaking with them may be helpful.\n"},
			["Use the Portal to Return to Faraniel"] =
				{appendText=".\n"},
			["Talk to Faraniel 4"] =
				{appendText=", who waits below the Council's platform, near The Moonless Walk's central camp.\n", stepTextKey="I should talk to Faraniel and tell her how things went with the Council of Elders."},
			["Talk to Elder Erthor"] =
				{appendText=" at The Moonless Walk's portal stones.\n"},
			["Talk to Faraniel 5"] =
				{appendText=", who is waiting near the central campfire in The Moonless Walk.\n", stepTextKey="I should discuss the Council's decision with Faraniel."},
			["Enter the Ruined Passage"] =
				{appendText=" to the Lightless Oubliette.\n"},
			["Collect Light of Meridia"] =
				{appendText=" by searching the first area entered in the Lightless Oubliette.\n"},
			["Talk to the Projection of King Laloriaran Dynar 1"] =
				{appendText=" standing on the landing of the stairs that lead farther into the Lightless Oubliette.\n", stepTextKey="I collected the Light of Meridia. Now I should speak to the projection of the Ayleid King and see what I should do next."},
			["Talk to the Projection of King Laloriaran Dynar 2"] =
				{appendText=" standing on the landing of the stairs that lead farther into the Lightless Oubliette.\n", stepTextKey="I collected the Light of Meridia. Now I should speak to the projection of the Ayleid King and see what I should do next."},
		},
		[GetQuestName(4602)] = { -- "Light from the Darkness"		-- Rosque
			["Enter the Tower"] =
				{appendText=" from the Ruined Passage near the Moonless Walk Wayshrine."},
			["Recover Oubliette Crystals"] =
				{appendText=" from the tower inside the Ruined Passage near the Moonless Walk Wayshrine. There seems to be little option but to thoroughly search through the darkness for any sign of them. The prison door should be just past the King's projection."},
			["Enter King Dynar's Prison"] =
				{appendText=", just past the crystals inside the Ruined Passage near the Moonless Walk Wayshrine."},
			["Set King Laloriaran Dynar Free"] =
				{appendText=" from his prison, just past the crystals inside the Ruined Passage near the Moonless Walk Wayshrine. The sconces and prisms that control the release mechanism are spread throughout the room."},
			["Talk to King Laloriaran Dynar 1"] =
				{appendText=" in his prison, just past the crystals inside the Ruined Passage near the Moonless Walk Wayshrine.", stepTextKey="I released King Laloriaran Dynar from the dark energy that bound him. I should talk to him and make sure he's alright."},
			["Meet King Laloriaran Dynar in the Hollow City"] =
				{appendText="."},
			["Talk to King Laloriaran Dynar 2"] =
				{appendText=". His sword suggests skill with weapons; he may be working to restore the Fighters Guildhall.", stepTextKey="I'm back in the Hollow City. I should locate King Laloriaran Dynar and make sure he arrived safely."},
		},
		[GetQuestName(4626)] = { -- "Vanus Unleashed"				-- Rosque
			["Find Vanus Galerion 1"] =
				{appendText=". His message used the term \"side door\", but an unguarded entrance to Molag Bal's arms factory is likely more of a dangerous service route or an overheated outflow pipe. Once inside, Vanus could be anywhere.", stepTextKey="I should enter the Black Forge and try to find Vanus Galerion. The message suggested I go in through the side door."},
			["Talk to Galerion's Essence 1"] =
				{appendText=" past the door beneath the lava outflow.", stepTextKey="Inside the Black Forge, I found Vanus Galerion. At least, I found a part of the Great Mage. I should talk to the essence of the mage."},
			["Collect Galerion's Health"] =
				{appendText="\nAccording to Vanus, there should be vampires stationed around the forge through the door in the lava lake."},
			["Talk to Galerion's Essence 2"] =
				{appendText=" past the door beneath the lava outflow.", stepTextKey="I recovered the health that the vampires stole from Galerion. I should talk to the mage's essence and return the health energy."},
			["Enter the Slave Quarters"] =
				{appendText=" somewhere past the door beneath the lava outflow."},
			["Talk to Galerion's Essence 3"] =
				{appendText=" further into the complex, past the door beneath the lava outflow.", stepTextKey="I made my way to the slave quarters. Now I should find Galerion's essence and see what it has to say."},
			["Collect Galerion's Stamina"] =
				{appendText="\nIf his stamina is being used to feed the slaves, it'll likely only be present within slaves still in the Slave Quarters, past the door beneath the lava outflow. Taskmasters should be somewhere nearby as well."},
			["Talk to Galerion's Essence 4"] =
				{appendText=" inside the Slave Quarters further into the complex, past the door beneath the lava outflow.", stepTextKey="I recovered the energy taken from Galerion's stamina. I should talk to the mage's essence and return the energy."},
			["Enter the Foundry"] =
				{appendText=", past the door beneath the lava outflow and through the Slave Quarters."},
			["Talk to Galerion's Essence 5"] =
				{appendText=", past the door beneath the lava outflow and through the Slave Quarters.", stepTextKey="I made my way to the Foundry. Now I should find Galerion's essence and see what it has to say."},
			["Unlock the Seals of Binding"] =
				{appendText="\nThe foundry is deep inside the Black Forge, past the door beneath the lava outflow and through the Slave Quarters."},
			["Talk to Galerion's Essence 6"] =
				{appendText=" within the foundry, past the door beneath the lava outflow and deep through the Slave Quarters.", stepTextKey="I released the seals that contained the magic holding Galerion's essence. I should talk to the mage's essence and see if it can break free."},
			["Find Vanus Galerion 2"] =
				{appendText=" within the Boiler Tunnels, past the door beneath the lava outflow and deep within the Black Forge's passageways. Vanus said his body was being guarded by Kothutuilk, so they should be near each other.", stepTextKey="Now that I've collected all of Vanus' essences, I need to find the body of the Great Mage."},
			["Release Vanus Galerion"] =
				{appendText=". He must be being held in the Boiler, past the door beneath the lava outflow and deep within the forge's passageways."},
			["Follow Vanus Galerion"] =
				{appendText=". He went further in toward the Great Shackle, past the door beneath the lava outflow and deep within the Black Forge's passageways."},
			["Talk to Vanus Galerion"] =
				{appendText=" at the Great Shackle Wayshrine, past the door beneath the lava outflow, through The Black Forge's deeper passageways."},
		},
		[GetQuestName(4730)] = { -- "Breaking the Shackle"			-- Rosque
			["Talk to Vanus Galerion 1"] =
				{appendText=" at the Great Shackle Wayshrine.", stepTextKey="I should talk to Vanus Galerion when I'm ready to head for the Great Shackle."},
			["Follow Vanus Galerion"] =
				{appendText=" from the Great Shackle Wayshrine."},
			["Enter the Great Shackle"] =
				{appendText="."},
			["Explore the Great Shackle"] =
				{appendText=". Vanus may have more details on how Molag Bal's mechanisms work."},
			["Enter the Mooring"] =
				{appendText=" on the ground floor of the Power Chamber in The Great Shackle."},
			["Defend Vanus Galerion"] =
				{appendText=". Cadwell can likely take care of himself."},
			["Observe the Great Shackle"] =
				{appendText="'s destruction."},
			["Return to the Hollow City"] =
				{appendText=". Since there is a Mages Guildhall there, it is unlikely that Vanus would be found at any other location within the city limits."},
			["Talk to Vanus Galerion 2"] =
				{appendText=" at the Mages Guildhall in the city.", stepTextKey="We destroyed the Great Shackle, but Cadwell claims the Planemeld hasn't been completely defeated yet. I should talk to Vanus Galerion and see what he thinks about the situation."},
		},
		[GetQuestName(4701)] = { -- "Crossing the Chasm"			-- Rosque
			["Talk to Cadwell 1"] =
				{appendText=" at the Hollow City's north gate.", stepTextKey="I need to locate Cadwell and find out what the scouts have learned about the situation at the Chasm."},
			["Go to the Chasm"] =
				{appendText="."},
			["Destroy the Focus Stones"] =
				{appendText="\nGathwen and Cadwell near the wayshrine may know more."},
			["Talk to Cadwell 2"] =
				{appendText=". With this section controlled, he likely found his way further along.", stepTextKey="I destroyed the focus stones. Now we're in control of this section of the Chasm and the portal that leads to the second tier. I should talk to Cadwell and make sure things are good here before I continue."},
			["Close the West Portal"] =
				{appendText="."},
			["Close the East Portal"] =
				{appendText="."},
			["Talk to Cadwell at the Gatehouse"] =
				{appendText=" at the end of The Chasm."},
			["Enter the Gatehouse Span"] =
				{appendText=" at the end of The Chasm."},
			["Cross the Span"] =
				{appendText="."},
			["Start the North Flywheel"] =
				{appendText="."},
			["Start the South Flywheel"] =
				{appendText="."},
			["Unlock the Gatehouse"] =
				{appendText="."},
			["Kill Molag Grunda"] =
				{appendText="."},
			["Exit the Gatehouse"] =
				{appendText="."},
			["Meet Vanus Galerion Outside"] =
				{appendText=" the gatehouse north of The Chasm."},
			["Talk to Vanus Galerion"] =
				{appendText=" by The Orchard Wayshrine."},
		},
		[GetQuestName(4715)] = { -- "The Harvest Heart"				-- Rosque
			["Mark Vampire Lairs"] =
				{appendText="\nBraziers burn above likely mausoleums."},
			["Locate the Harvest Heart"] =
				{appendText=". The six prongs of its enclosure can be seen from the fountain north of The Orchard Wayshrine, framing an archway like a crown of spikes."},
			["Talk to Virgar the Red 1"] =
				{appendText=" just north of the center of The Orchard.", stepTextKey="Virgar the Red apparently has something to say, but Vanus doesn't appear to trust her. I should talk to her and see what she wants from us."},
			["Support Vanus Galerion"] =
				{appendText=" just north of the center of The Orchard."},
			["Support Virgar the Red"] =
				{appendText=" just north of the center of The Orchard."},
			["Defend West Ritual Site 1"] =
				{appendText=". A faded statue of a man holding a staff and the symbol of Arkay stands tall above it.", stepTextKey="I decided to support Vanus' solution. I should lead him to the ritual sites and defend him while he casts his spells."},
			["Defend East Ritual Site 1"] =
				{appendText=". A faded statue of a man holding a staff and the symbol of Arkay stands tall above it.", stepTextKey="I decided to support Vanus' solution. I should lead him to the ritual sites and defend him while he casts his spells."},
			["Return to the Harvest Heart 1"] =
				{appendText=" just north of the center of The Orchard.", stepTextKey="Vanus cast his spells at the ritual sites around the Orchard. Now we should return to the Harvest Heart so he can complete the ritual."},
			["Talk to Vanus Galerion 1"] =
				{appendText=" just north of the center of The Orchard.", stepTextKey="We returned to the Harvest Heart. Vanus Galerion wants to speak to me before we begin the final phase of the ritual."},
			["Help Vanus Complete the Ritual"] =
				{appendText=" just north of the center of The Orchard."},
			["Talk to Vanus Galerion 2"] =
				{appendText=" just north of the center of The Orchard.", stepTextKey="The ritual is complete and the Harvest Heart has been destroyed. I should talk to Vanus Galerion."},
			["Defend West Ritual Site 2"] =
				{appendText=". A faded statue of a man holding a staff and the symbol of Arkay stands tall above it.", stepTextKey="I decided to support Virgar's solution. I should lead her to the ritual sites and defend her while she casts her spells."},
			["Defend East Ritual Site 2"] =
				{appendText=". A faded statue of a man holding a staff and the symbol of Arkay stands tall above it.", stepTextKey="I decided to support Virgar's solution. I should lead her to the ritual sites and defend her while she casts her spells."},
			["Return to the Harvest Heart 2"] =
				{appendText=" just north of the center of The Orchard.", stepTextKey="Virgar the Red cast her spells at the ritual sites around the Orchard. Now we should return to the Harvest Heart so she can complete the ritual."},
			["Talk to Virgar the Red 2"] =
				{appendText=" just north of the center of The Orchard.", stepTextKey="We returned to the Harvest Heart. Virgar the Red wants to speak to me before we begin the final phase of her ritual."},
			["Help Virgar and Vanus Complete the Ritual"] =
				{appendText=" just north of the center of The Orchard."},
			["Talk to Virgar the Red 3"] =
				{appendText=" just north of the center of The Orchard.", stepTextKey="The ritual is complete and the Harvest Heart has been destroyed. I should talk to Virgar the Red."},
		},
		[GetQuestName(4774)] = { -- "The Citadel Must Fall"			-- Rosque
			["Collect Fighters Guild Ward Key"] =
				{appendText=". King Dynar at Reaver Citadel Wayshrine may be willing to offer advice, though searching for clues near the Fighters Guild Hall once inside the citadel may still prove necessary."},
			["Deactivate the Guild Hall Wards"] =
				{appendText=" within the citadel."},
			["Talk to King Laloriaran Dynar in the Fighters Guild Hall"] =
				{appendText="."},
			["Go to the Upper City"] =
				{appendText="."},
			["Collect Portal Stones"] =
				{appendText="\nThe blue stones should be somewhere around the Upper City of Reaver Citadel."},
			["Restore the Portal Stones"] =
				{appendText="\nThe Mages Guild Hall should be in the Upper City of The Reaver Citadel."},
			["Talk to Vanus Galerion 1"] =
				{appendText=" inside the Mages Guild Hall in the Upper City of The Reaver Citadel.", stepTextKey="Now that the Mages Guild Hall portal has been activated and the mages have teleported through, I should talk to Vanus Galerion."},
			["Find the Pyramid Entrance"] =
				{appendText=", high above the citadel and before The Endless Stair."},
			["Talk to Lyranth"] =
				{appendText=", east of Molag Bal's seal above The Reaver Citadel."},
			["Enter the Pyramid"] =
				{appendText=" east of Molag Bal's seal above The Reaver Citadel."},
			["Defeat Enemies in the Stronghold"] =
				{appendText=" east of Molag Bal's seal above The Reaver Citadel."},
			["Find the Labyrinth Key"] =
				{appendText=" in the pyramid east of Molag Bal's seal above The Reaver Citadel."},
			["Find Vanus Galerion"] =
				{appendText=" at the entrance to The Endless Stair."},
			["Talk to Vanus Galerion 2"] =
				{appendText=" at the entrance to The Endless Stair.", stepTextKey="With Lyranth now in charge of the Citadel, we have safe passage to the Labyrinth and the Endless Stair beyond. And I have the key that gets us inside. I should speak to Vanus Galerion and see how he and King Dynar want to proceed."},
		},
		[GetQuestName(4758)] = { -- "The Final Assault"				-- Rosque
			["Talk to Hahnin"] =
				{appendText=" near the Endless Stair Wayshrine."},
			["Talk to Gabrielle 1"] =
				{appendText=" near the Endless Stair Wayshrine.", stepTextKey="I need to speak to Hahnin and Gabrielle to receive their briefings on the Fighters Guild and Mages Guild battle plans."},
			["Choose a Companion for the Initial Assault"] =
				{appendText=" near the Endless Stair Wayshrine."},
			["Talk to King Dynar 1"] =
				{appendText=" near the Endless Stair Wayshrine.", stepTextKey="I selected a companion to accompany me on my initial foray into Molag Bal's inner domain. I should tell King Dynar that I'm ready to go."},
			["Receive King Dynar's Briefing"] =
				{appendText="."},
			["Go to the Reinforcement Portal"] =
				{appendText=", far up the path past The Reaver Citadel."},
			["Defeat the Guardian of the Gate"] =
				{appendText=" past the Endless Overlook."},
			["Close the Reinforcement Portal"] =
				{appendText=" past the Endless Overlook."},
			["Open the Labyrinth"] =
				{appendText=" to The Endless Stair."},
			["Talk to Vanus Galerion 1"] =
				{appendText=" by the entrance to The Endless Stair.", stepTextKey="I unlocked the way into the Labyrinth and then Vanus Galerion opened a portal behind me. I should speak to him before I enter."},
			["Enter the Labyrinth"] =
				{appendText=" that leads to The Endless Stair."},
			["Talk to Gabrielle 2"] =
				{appendText=" within the Labyrinth that leads to The Endless Stair.", stepTextKey="I should speak to Gabrielle and see if she has any advice on how I should proceed through the Labyrinth."},
			["Open the Library Gate"] =
				{appendText=" within the Labyrinth to The Endless Stair. Hopefully such a massive library also contains clues somewhere about its operation, although Molag Bal isn't likely to simply leave them on the bookshelves."},
			["Enter the Next Area 1"] =
				{appendText=" within the Labyrinth to The Endless Stair.", stepTextKey="I used the device and opened the door to the next area of the Labyrinth. I should proceed through the door and continue my search for the planar vortex."},
			["Cross the Dark Chamber"] =
				{appendText=" within the Labyrinth to The Endless Stair. Sources of mundane or magical light may make it easier to navigate and avoid danger."},
			["Cross the Bridge"] =
				{appendText=" past the darkness within the Labyrinth to The Endless Stair."},
			["Enter the Next Area 2"] =
				{appendText=" within the Labyrinth, past the bridge overlooking The Endless Stair.", stepTextKey="I need to continue deeper into the Labyrinth if I'm going to locate the planar vortex."},
			["Find a Path Through the Statue Room"] =
				{appendText=", deep within the Labyrinth to The Endless Stair. Gabrielle seems to be waiting for the signal to move forwards."},
			["Exit the Statue Room"] =
				{appendText=" to The Endless Stair."},
			["Talk to Vanus Galerion 2"] =
				{appendText=" beyond the Labyrinth to The Endless Stair.", stepTextKey="Only Gabrielle and I made it into the next area before the door sealed behind us. But then a portal opened and Vanus Galerion appeared. I should talk to him."},
			["Find the Planar Vortex Portal"] =
				{appendText=" at The Endless Stair beyond the Labyrinth."},
			["Defeat the Guardian of the Portal"] =
				{appendText=" at The Endless Stair beyond the Labyrinth."},
			["Talk to the Groundskeeper"] =
				{appendText=" at The Endless Stair beyond the Labyrinth."},
			["Enter the Planar Vortex Portal"] =
				{appendText=" at the heart of The Endless Stair beyond the Labyrinth."},
			["Destroy the First Dark Anchor"] =
				{appendText=" tethering Nirn to Coldharbour."},
			["Talk to Meridia 1"] =
				{appendText=".", stepTextKey="Well, that makes a certain amount of sense. The Groundskeeper is Meridia! She wants to talk to me before we proceed."},
			["Let Meridia Know When You Are Ready"] =
				{appendText="."},
			["Destroy the Remaining Dark Anchors"] =
				{appendText=" tethering Nirn to Coldharbour."},
			["Place the Light of Meridia"] =
				{appendText=" in the cemetary, past the ruins of Nirn."},
			["Confront the Council of Molag Bal"] =
				{appendText=" in the cemetary, past the ruins of Nirn."},
			["Survive Molag Bal's Assault"] =
				{appendText=" in the cemetary, past the ruins of Nirn."},
			["Activate the Light of Meridia"] =
				{appendText=" in the cemetary, past the ruins of Nirn."},
			["Talk to Meridia 2"] =
				{appendText=" in the Hollow City Chapel of Light.", stepTextKey="It appears that we succeeded. The Planemeld has been defeated, and it looks like I'm still alive. I should speak to Meridia and ask her what happened."},
			["Talk to King Dynar 2"] =
				{appendText=" in the Hollow City Chapel of Light.", stepTextKey="Even though we stopped the Planemeld, it looks like King Dynar was mortally wounded. I should speak to him while there's still time."},
			["Talk to King Dynar 3"] =
				{appendText=" in the Hollow City Chapel of Light.", stepTextKey="We stopped the Planemeld and saved Nirn, but at what cost? King Dynar lies dying before me. I should speak to him before it's too late."},
		},


