--		  Coldharbour Side
-- 		=========================================================================


[GetQuestName(4351)] = { --"Through the Daedric Lens"		-- Octavare
        ["Destroy the Daedric Lenses"] =
            {appendText=".\n\nThe Daedric lenses are black structures holding up a blue, oval-shaped disk. They emit a soft blue light. They can be found within the outer perimeter of the ruins, in the center of circular spires."},
        ["Enter the Gallery"] =
            {appendText=". The entrance is at the bottom of a spiral staircase in the center of the ruins, marked by broken spires and a pedestal holding a glowing cluster of crystals."},
        ["Find Kireth Vanos"] =
            {appendText=". She is likely inside the library, near the entrance."},
        ["Talk to Kireth Vanos"] =
            {appendText=". She is next to the first cell on the right from the entrance."},
    },
[GetQuestName(4352)] = { --"The Library of Dusk"		-- Octavare
["Examine the Prisoner Notes"] =
{appendText=".\nKireth, the dark elf who asked for my assistance, may know where they can be found. She is inside the Library of Dusk, the entrance to which is found in the center of the Ayleid ruin sharing its name."},
["Enter the Library of Dusk"] =
{appendText=". The entrance is just down the stairs from inside the gallery."},
["Find Raynor Vanos"] =
{appendText=". He was taken prisoner by the Dusk Scholars inside the library. He is inside one of the rooms on the balcony level."},
["Talk to Raynor Vanos 1"] =
{appendText=". From the entrance of the library, he can be found in the third room from the right on the balcony level.", stepTextKey="I found the real Raynor Vanos. Now I need to convince him to leave the library."},
["Talk to Kireth Vanos"] =
{appendText=". She waits at the entrance of the library, next to a glowing blue cluster of crystals."},
["Return to Raynor Vanos"] =
{appendText=". From the entrance of the library, he can be found in the third room from the right on the balcony level."},
["Talk to Raynor Vanos 2"] =
{appendText=". From the entrance of the library, he can be found in the third room from the right on the balcony level.", stepTextKey="Now that Raynor has been freed from the Daedric spell, I should talk to him."},
["Find Lady Clarisse Laurent"] =
{appendText=". She was taken prisoner by the Dusk Scholars inside the library. She is inside one of the rooms on the balcony level."},
["Find Telenger the Artificer 1"] =
{appendText=". He was taken prisoner by the Dusk Scholars inside the library. He is inside one of the rooms on the balcony level. If I can't find him, I should check for any clues hinting at his location.", stepTextKey="Lady Clarisse Laurent told me that Telenger discovered something important, but she couldn't remember what it was. I need to find Telenger."},
["Read Telenger's Note"] =
{appendText="."},
["Find Telenger the Artificer 2"] =
{appendText=". He went to the lower level of the library, accessible via a tunnel located in the center of the main room.", stepTextKey="Telenger the Artificer locked himself inside a vault on the lower level of the library in an attempt to slow the effects of the spell assaulting his mind. I should look for him there."},
["Talk to Telenger the Artificer 1"] =
{appendText=". The vault is on the lowest level of the library, accessed from the tunnel in the center of the main room. He is behind a large Ayleid gate all the way in the back.", stepTextKey="I found Telenger the Artificer locked inside a vault on the library's lowest level. I should speak to him."},
["Enter the Vault"] =
{appendText=" on the lowest level of the library, accessed from the tunnel in the center of the main room. It is all the way in the back, behind a large Ayleid gate."},
["Talk to Telenger the Artificer 2"] =
{appendText=". The vault is on the lowest level of the library, accessed from the tunnel in the center of the main room. He is behind a large Ayleid gate all the way in the back.", stepTextKey="I entered the vault. I should talk to Telenger and see what he wants to do next."},
["Enter the Library Vault Portal"] =
{appendText=". The portal is in the vault on the lowest level of the library, accessed from the tunnel in the center of the main room."},
["Find the Source of Power"] =
{appendText="."},
["Take the Light of Meridia"] =
{appendText="."},
["Leave the Floating Rock"] =
{appendText=". The last Ayleid King has promised that he will protect me if I jump down from this height."},
["Talk to Telenger the Artificer 3"] =
{appendText=". He is waiting at the Library of Dusk Wayshrine, northwest of the ruin.", stepTextKey="I returned from the floating rock with a Light of Meridia. I should speak with Telenger the Artificer at his camp outside the library ruins."},
},


   [GetQuestName(4743)] = { --"The Lost Lute"					-- MartinToms
        ["Find Minstrel Idria"] =
            {appendText=".\nIdria sounds like a Dunmer name... If the Minstrel is alive, they are bound to be in the Hollow City. Perhaps I should check The Shining Star tavern? Where else would one find a bard?"},
    },


	[GetQuestName(4392)] = { --"Truth, Lies, and Prisoners"				--octavare  --Jordakai
		[1] = 
			{appendStepText="Northwest of the Hollow City I met a Wood Elf at a gazebo. ", stepTextKey="Apparently, the only way to enter the Tower of Lies is to jump in. Gwilir thinks the water is deep enough to break my fall. I hope he's right about that."},
		["Jump Into the Water"] =
			{appendText=" from the gazebo. I hope Gwilir is right about this."},
		[2] = 
			{appendStepText="From the gazebo northwest of the Hollow City, ", stepTextKey="I survived the leap into the Tower of Lies. Now I should look for Skordo. Gwilir suggested that he'd be able to tell me what's going on inside the prison."},
		["Talk to Skordo 1"] =
			{appendText=" the Knife, an imposing, shirtless Orc leaning against a support beam under a crate suspended high above him. He is near a small, wooden bridge over the azure water, northwest of where I jumped.", stepTextKey="I survived the leap into the Tower of Lies. Now I should look for Skordo. Gwilir suggested that he'd be able to tell me what's going on inside the prison."},
		[3] = 
			{appendStepText="At the base of the Tower of Lies prison northwest of the Hollow City, ", stepTextKey="Skordo wants me to rescue his three Fighters Guild companions: Sinfay, Borgath, and Vikord. He says they were taken by the ogrims and are being tortured."},
		["Rescue Sinfay, Borgath, and Vikord Skullcleaver"] =
			{appendText="\n\nVikord is a male Nord who has been tied up inside a small alcove on the bottom level of the mines, with its entrance marked by a blue-flamed brazier.\n\nSinfay is a female Redguard. She is inside another alcove, where some crates and a lone torch sit by the opening.\n\nBorgath is a male Orc, whose alcove is directly across from the boat that washed ashore at the bottom of the mine. The entrance is beneath several wooden support beams that make the upper levels of the mines navigable.\n\nI should speak with the robed Dremora standing at the low bridge crossing the azure water."},
		[4] = 
			{appendStepText="Northwest of the Hollow City, on the lowest level of the Tower of Lies, ", stepTextKey="I rescued two of Skordo's companions, but the third one was dead when I found him. I should find Skordo and tell him what happened."},
		["Meet Skordo Outside the Overseer's Chamber"] =
			{appendText=". The entrance is lit by two blue-flamed braziers beneath a wooden overhang. It can be reached by walking up a wooden ramp."},
		[5] = 
			{appendStepText="In the Tower of Lies' lowest level, we found the Overseer's Chamber, up a short wooden ramp, marked by two blue-flame braziers. ", stepTextKey="Skordo says that Overseer Aruz, a powerful Daedra, has a key to a passage that leads up to the next level. We need to get that key. It should be in Aruz's chamber, which is just through the door where I talked to Skordo."},
		["Get the Key to the Passage"] =
			{appendText=", inside Overseer Aruz's Chamber.\n"},
		["Kill Overseer Aruz"] =
			{appendText=" inside his chamber."},
		[6] = 
			{appendStepText="", stepTextKey="I have the Overseer's key. I should use it to head up to the next level of the Tower of Lies."},
		["Locate the Liar's Passage"] =
			{appendText=". The entrance is near the northern area of the prison, behind the tents and wooden sheds. My allies wait for me in front of the entrance."},
		[7] = 
			{appendStepText="I entered the Liar's Passage in the northern area of the prison's lowest level. ", stepTextKey="While Skordo musters his soldiers, I've made my way to the upper level of the prison to find Captain Eilram."},
		["Talk to Captain Eilram"] =
			{appendText=". If I follow the path to the right of the exit from the Liar's Passage, I will run into him standing on the wooden supports next to a small, checkered tent.\n\nOn the way, I may want to speak with the robed Dremora again."},
		[8] = 
			{appendStepText="After using the Liar's Passage to reach the upper level's southern side, I found the captain up near a checkered tent. ", stepTextKey="Captain Eilram won't work with me until I convince him that I'm not a spy or an illusion. He wants me to recover the sword that he dropped while fighting the ogrims."},
		["Find Captain Eilram's Sword"] =
			{appendText=". The ogrims he encountered were in the eastern portion of the upper level of the prison. Daedric arches can be found within the area, along with a small tent. His sword might be among the armaments left at the tent."},
		[9] = 
			{appendStepText="On the prison's upper level reached through the Liar's Passage, I found the captain's sword. ", stepTextKey="Eilram and Arakh both seem to be suffering from the terrible effects of this place. I recovered Eilram's sword, so maybe he'll trust me now. I should meet him near Arakh's camp and see if I can help him talk some sense into the other captain."},
		["Go to Captain Arakh's Camp"] =
			{appendText=" in the northern section of the upper level of the prison. I should backtrack to the exit of the Liar's Passage and go in the opposite direction. The camp is barricaded with wooden walls."},
		[10] = 
			{appendStepText="The Liar's Passage brought me to the upper level where I found the captain's sword. Now ", stepTextKey="I should find Captain Eilram and give him his sword."},
		["Return the Sword to Eilram"] =
			{appendText=". He is in Arakh's Camp, just outside of a tent with a firepit in front of it."},
		[11] = 
			{appendStepText="On the prison's upper level, north of where I entered through the Liar's Passage, I realized that ", stepTextKey="Captain Arakh is more paranoid than Captain Eilram. She says the voices are making her crazy. She won't even talk to Eilram until someone recovers her helmet from the watchers. I guess I'm elected."},
		["Find Captain Arakh's Helm"] =
			{appendText=". From Arakh's Camp, exit and follow the path right of the entrance. A tentacled watcher observes this path and may need to be dispatched. I should check near the watchers, since they stole her helmet. Her helmet is hanging from a wooden crane."},
		[12] = 
			{appendStepText="Liar's Passage. Maybe the name doesn't apply to what I hear up on this level of the prison. ", stepTextKey="I recovered Captain Arakh's helmet from the watchers. I should return it to her and see if it calms her down enough that Eilram can talk to her."},
		["Return the Helmet to Arakh"] =
			{appendText=". She is inside Arakh's Camp, north of the crane where I found her helmet. The camp is surrounded by a wooden barricade."},
		[13] = 
			{appendStepText="At the barricaded camp on the upper level, north of the exit from Liar's Passage, I returned the helmet. ", stepTextKey="The helmet seems to have calmed Captain Arakh. Now Captain Eilram wants to talk to her. I should listen to what they have to say."},
		["Listen to the Two Captains"] =
			{appendText="."},
		[14] = 
			{appendStepText="At the barricaded camp north of the upper level exit of the Liar's Passage, a visitor! ", stepTextKey="The Dremora Lyranth appeared. She claims that we have a common enemy in Ifriz. I should talk to her and see what she has to say."},
		["Talk to Lyranth"] =
			{appendText="."},
		[15] = 
			{appendStepText="After rescuing fighters on the lower level, using the Liar's Passage to reach the upper level, and retrieving the Captains' gear, I now have a name for the enemy. ", stepTextKey="A Dremora named Ifriz seems to be in charge of this prison. According to Lyranth, the only way to remove the barrier blocking the exit is to kill Ifriz. Of course, she wants him dead, too. She banished the illusions that had been hiding him."},
		["Kill Ifriz"] =
			{appendText=", beyond Arakh's Camp. Lyranth the Dremora may know where he is."},
		[16] = 
			{appendStepText="At the top of Liar's Passage, in the northern area of the upper level, I found the enemy at a Daedric platform. Now ", stepTextKey="Ifriz the Unraveler is dead and the barrier blocking the way out should be down now. I should meet the Fighters Guild captains at the bridge and make sure we can get out of here now."},
		["Talk to Captain Arakh"] =
			{appendText=". She is in front of a land bridge leading to a floating island."},
		[17] = 
			{appendStepText="After leaping into azure water, finding the Liar's Passage, and reaching the upper areas, it is finally time to leave this prison. ", stepTextKey="I should head for the portal now."},
		["Go to the Portal"] =
			{appendText=" on the floating island at the top of the land bridge."},
		[18] = 
			{appendStepText="After leaping into azure water, finding the Liar's Passage, and reaching the upper areas, it is finally time to leave this prison.\n\nAt the exit portal there is a large crystal. ", stepTextKey="According to the two captains, the nearby crystal is a Light of Meridia. I should take it with me when I leave."},
		["Take the Light of Meridia"] =
			{appendText=" from the floating island at the top of the land bridge."},
		[19] = 
			{appendStepText="", stepTextKey="Now that I have the Light of Meridia, I should use the portal and get out of here."},
		["Use the Portal"] =
			{appendText=" to return to the Hollow City."},
		[20] = 
			{appendStepText="", stepTextKey="The Fighters Guild members have escaped from the Tower of Lies and plan to regroup in the Hollow City. I should find Skordo, who wants to speak to me."},
		["Talk to Skordo 2"] =
			{appendText=" the Knife. He is at the roundabout along the northwestern path from the Hollow City, the settlement in the heart of Coldharbour.", stepTextKey="The Fighters Guild members have escaped from the Tower of Lies and plan to regroup in the Hollow City. I should find Skordo, who wants to speak to me."},
	},
		[GetQuestName(4748)] = { -- "Saving Stibbons"				-- MartinToms
			["Rescue Stibbons"] =
				{appendText=".\nI am looking for a tower somewhere in the northwestern region. The tower is likely full of Dark Seducers, as they rarely operate alone."},
			["Talk to Stibbons"] =
				{appendText=" at the wayshrine near Drasilla's Spurned Peak."},
		},
[GetQuestName(4371)] = { --"Wisdom of the Ages"						--Jordakai
		["Go to Haj Uxith"] =
			{appendText=", a city of pyramids in the southwest surrounded by rivers and ponds of azure plasm. Xohaneel may run ahead and may be near the torchlight north of the Haj Uxith Wayshrine.\n"},
		["Listen to Xohaneel and An-Jeen-Sakka"] =
			{appendText=" speak with each other in the torchlight east of the city's Hist tree. They are north of the Haj Uxith Wayshrine.\n"},
		["Talk to Treeminder Xohaneel 1"] =
			{appendText=", north of the Haj Uxith Wayshrine. She waits with An-Jeen-Sakka in the torchlight east of the Hist tree.\n", stepTextKey="Now that Treeminder Xohaneel has finished her conversation with An-Jeen-Sakka, I should speak to her and find out what they expect of me."},
		["Talk to Treeminder Xohaneel 2"] =
			{appendText=" east of the Hist tree, in the torchlight north of the wayshrine.\n", stepTextKey="I can perform the Haj Uxith tests in any order I choose. I should speak to Treeminder Xohaneel to start the Trial of Spirit or An-Jeen-Sakka to start the Trial of Body."},
		["Talk to An-Jeen-Sakka 1"] =
			{appendText=". He stands ready in the torchlight, just east of the Hist tree that is northwest of the city's wayshrine.\n", stepTextKey="I can perform the Haj Uxith tests in any order I choose. I should speak to Treeminder Xohaneel to start the Trial of Spirit or An-Jeen-Sakka to start the Trial of Body."},
		["Give Amulet to Ashgar"] =
			{appendText=". He stands behind a table facing a large tree that looms overhead. Stools are available for those who wish to study from his stacks of books. In my pack is an amulet for him.\n"},
		["Give Amulet to Teelawei"] =
			{appendText=" as he ponders in his semi-private perch with an expansive view. There are many scrolls on his table. He will want the proper amulet.\n"},
		["Give Amulet to Desh-Wazei"] =
			{appendText=", a female scholar working near two tables near containers of food. Speaking with her should help in selecting the correct amulet from my pack.\n"},
		["Place the Gems"] =
			{appendText=". The scholar Teelawei may have a helpful scroll.\n"},
		["Talk to Xohaneel"] =
			{appendText=", who stands between banners on the lowest platform of the south pyramid where the fishers are filleting the day's catch. The warrior An-Jeen-Sakka is with her.\n"},
		["Talk to An-Jeen-Sakka 2"] =
			{appendText=", standing near Treeminder Xohaneel by the banners and close to the fishers filleting fish on the lowest platform of the south pyramid.\n", stepTextKey="I finished the Trial of Spirit. Now I should speak to An-Jeen-Sakka and start the Trial of Body."},
		["Enter Sap Collection Facility"] =
			{appendText=" through a trapdoor at the top of the city's north pyramid. Then search the chambers within until the main facility is found.\n"},
		["Overheat the Sap Vats"] =
			{appendText=" by adding treated wood to the red-hot coals burning beneath each to create greater flames.\n"},
		["Exit the Facility"] =
			{appendText=" in the city's north pyramid through a door at the end of the southern hallway leading from where the sap vats' fires burn brightly.\n"},
		["Talk to An-Jeen-Sakka 3"] =
			{appendText=". He stands ready north of the wayshrine and east of the Hist tree. Treeminder Xohaneel is with him.\n", stepTextKey="I overheated the Hist sap vats and completed the Trial of Body. Now I should return to An-Jeen-Sakka and let him know about my success."},
		["Agree with the Scholars"] =
			{appendText=" that the Hist tree west of where we stand will suffer no more.\n"},
		["Agree with the Warriors"] =
			{appendText=" that the Hist tree, northwest of the Haj Uxith Wayshrine, will continue as it is.\n"},
		["Talk to An-Jeen-Sakka 4"] =
			{appendText=", standing near Treeminder Xohaneel in the torchlight north of the city's wayshrine and east of the Hist tree.\n", stepTextKey="I decided to side with the scholars and end the Hist tree's eternal suffering. I need to tell An-Jeen-Sakka my decision."},
		["Go to the Challenge Grounds"] =
			{appendText=" at the west end of the city. The warriors' champion stands at the ready in the azure plasm.\n"},
		["Defeat the Champion 1"] =
			{appendText=" in the city's west end. Spectators are there to witness the challenge.\n", stepTextKey="I need to defeat the warriors' champion before they will accept my decision."},
		["Destroy the Vampiric Shard"] =
			{appendText=" located on the west side of the Hist tree, nestled among its roots and the totems where it glows, northwest of the city's wayshrine.\n"},
		["Talk to Treeminder Xohaneel 3"] =
			{appendText=" on the west side of the Hist tree, northwest of the city's wayshrine.\n", stepTextKey="I helped settle the debate over the fate of Haj Uxith's Hist tree. I destroyed the vampiric shard, which means the Hist will eventually die. I should talk to Xohaneel before I leave."},
		["Talk to Treeminder Xohaneel 4"] =
			{appendText=". She is near An-Jeen-Sakka, east of the Hist tree and north of the wayshrine.\n", stepTextKey="I completed the Trial of Body. Now I should speak to Treeminder Xohaneel and start the Trial of Spirit."},
		["Talk to Treeminder Xohaneel 5"] =
			{appendText=". She is near An-Jeen-Sakka, east of the Hist tree and north of the wayshrine.\n", stepTextKey="I decided to side with the warriors and allow the Hist tree to live. I need to tell Treeminder Xohaneel my decision."},
		["Go to the Challange Grounds"] =
			{appendText=" at the west end of the city. The scholars' champion waits in the azure plasm there.\n"},
		["Defeat the Champion 2"] =
			{appendText=" in the city's west end. Spectators will watch the challenge.\n", stepTextKey="I must defeat the scholars' champion before they accept my decision."},
		["Talk to An-Jeen-Sakka 5"] =
			{appendText=". He is at the top of the stairs at the entrance to the Challenge Grounds in the city's west end.\n", stepTextKey="I convinced the scholars that my decision was correct and helped settle the debate over the fate of Haj Uxith's Hist tree. I should talk to An-Jeen-Sakka and let him know that the Hist will live."},
	},
		[GetQuestName(4354)] = { -- "The Endless War"				-- MartinToms
			["Aid the Mages Guild Members"] =
				{appendText=".\n\nThe game takes place at the Cliffs of Failure, the Battlegrounds Antechamber awaits.\n\nI am looking for three mages - Juline Ginis, Mim, and Relmus. They will be able to guide me further."},
			["Talk to the Observer"] =
				{appendText=" directly through the Battlegrounds Antechamber."},
			["Talk to The Observer"] =
				{appendText=" at the Observer's Watch."},
		},


[GetQuestName(4370)] = { --"A Bargain With Shadows"							-- MartinToms
["Talk to High Kinlady Estre"] =
{appendText=" at the Cliffs of Failure. I should look for Veiled Heritance soldiers."},
["Defeat Angof's Champion"] =
{appendText=", probably some kind of a Bloodthorn zombie or a cultist at the Cliffs of Failure."},
["Defeat Thallik's Champion"] =
{appendText=", likely a skeleton or a Worm Cultist."},
["Return to the Cave Entrance"] =
{appendText=" in front of the Battlegrounds Antechamber of the Cliffs of Failure in the east."},
["Talk to Relmus 1"] =
{appendText=", the Dark Elf, in front of the Battlegrounds Antechamber of the Cliffs of Failure in the east.", stepTextKey="As I reached the entrance to the Observer's watch, I spotted Relmus waiting for me. I should speak to him."},
["Enter the Observer's Watch"] =
{appendText=" through the Battlegrounds Antechamber of the Cliffs of Failure in the east."},
["Survive the Observer's Challenge"] =
{appendText=" within the Battlegrounds Antechamber of the Cliffs of Failure."},
["Defeat the Observer"] =
{appendText=" at the Observer's Watch of the Cliffs of Failure."},
["Find the Mages"] =
{appendText=" past the portal from the Observer's Watch to Coldharbour."},
["Talk to the Observer"] =
{appendText=" at the southern part of the Cliffs of Failure.\n\nI may wish to consult Lady Estre, she seems the cunning type."},
["Talk to Estre 1"] =
{appendText=" south of the Cliffs of Failure.", stepTextKey="I decided to push back against the Observer and take everyone out of the game. Now I have Estre and the mages at my side. I should speak to Estre and send them all to the Hollow City."},
["Talk to Estre 2"] =
{appendText=" south of the Cliffs of Failure.", stepTextKey="I decided to save Lady Estre from the Observer's game. It was the only real choice if I want to defeat Molag Bal. I should talk to Estre and send her to the Hollow City."},
["Talk to Relmus 2"] =
{appendText=" south of the Cliffs of Failure.", stepTextKey="I decided to save the Mages Guild members from the Observer's game. I should talk to Relmus and send them to the Hollow City."},
},
[GetQuestName(4364)] = { --"A Thorn in Your Side"						--Jordakai
        ["Talk to Angof the Undying"] =
            {appendText=" in the Cliffs of Failure. He will probably have his Bloodthorn minions near him, perhaps surveying the field of battle.\n"},
        ["Defeat Thallik's Champion"] =
            {appendText=", likely a Worm cultist or skeleton warrior of renown.\n"},
        ["Defeat Estre's Champion"] =
            {appendText=", probably one of her favored Veiled Heritance loyalists.\n"},
        ["Return to the Cave Entrance"] =
            {appendText=" of the antechamber in the eastern battlegrounds within the Cliffs of Failure.\n"},
        ["Talk to Juline Ginis"] =
            {appendText=" at the eastern battlegrounds within the Cliffs of Failure.\n"},
        ["Enter the Observer's Watch"] =
            {appendText=" through the door of the Battlegrounds Antechamber at the east end of the battlegrounds within the Cliffs of Failure.\n"},
        ["Survive the Observer's Challenge"] =
            {appendText=" within the Battlegrounds Antechamber of the Cliffs of Failure.\n"},
        ["Defeat the Observer"] =
            {appendText=" at the Observer's Watch near the two main portals in the Cliffs of Failure.\n"},
        ["Find the Mages"] =
            {appendText=" somewhere outside the Cliffs of Failure's portal to Coldharbour.\n"},
        ["Talk to the Observer"] =
            {appendText=" at the east edge of the Observer's Watch platform in the Cliffs of Failure.\n\nPerhaps Angof or one of the mages can provide some insight into what is going on.\n"},
        ["Talk to Angof 1"] =
            {appendText=", who is with the rescued Mages Guild members, just southwest of the Cliffs of Failure.\n", stepTextKey="I decided to push back against the Observer and take everyone out of the game. Now I have Angof and the mages at my side. I should speak to Angof and send them all to the Hollow City."},
        ["Talk to Angof 2"] =
            {appendText=", who is just southwest of the Cliffs of Failure.\n", stepTextKey="I decided to save Angof from the Observer's game. It was the only real choice if I want to defeat Molag Bal. I should talk to Angof and send him to the Hollow City."},
        ["Talk to Juline"] =
            {appendText=", who is with Mim and Relmus. They are southwest of the Cliffs of Failure.\n"},
    },
[GetQuestName(4369)] = { --"The Will of the Worm"						--Jordakai
        ["Talk to Thallik Wormfather"] =
            {appendText=" within the Cliffs of Failure. He will likely be accompanied by his Worm cultists and skeletal warriors, perhaps studying the battlegrounds.\n"},
        ["Defeat Angof's Champion"] =
            {appendText=", probably a trusted member of his Bloothorn minions here in the Cliffs of Failure.\n"},
        ["Defeat Estre's Champion"] =
            {appendText=", likely one of her favored Veiled Heritance loyalists.\n"},
        ["Return to the Cave Entrance"] =
            {appendText=" of the antechamber in the eastern battlegrounds within the Cliffs of Failure.\n"},
        ["Talk to Mim 1"] =
            {appendText=" at the battlegrounds' east end within the Cliffs of Failure.\n", stepTextKey="As I reached the entrance to the Observer's watch, I spotted Mim waiting for me. I should speak to him."},
        ["Enter the Observer's Watch"] =
            {appendText=" through the door of the Battlegrounds Antechamber at the east end of the battleground within the Cliffs of Failure.\n"},
        ["Survive the Observer's Challenge"] =
            {appendText=" within the Battlegrounds Antechamber in the Cliffs of Failure.\n"},
        ["Defeat the Observer"] =
            {appendText=" at the Observer's Watch near the two main portals in the Cliffs of Failure.\n"},
        ["Find the Mages"] =
            {appendText=" somewhere outside the Cliffs of Failure's portal to Coldharbour.\n"},
        ["Talk to the Observer"] =
            {appendText=" at the east edge of the Observer's Watch platform in the Cliffs of Failure.\n\nPerhaps Thallik or one of the mages can provide some insight into what is going on.\n"},
        ["Talk to Mim 2"] =
            {appendText=", who is with Juline and Relmus. They are southwest of the Cliffs of Failure.\n", stepTextKey="I decided to save the Mages Guild members from the Observer's game. I should talk to Mim and send them to the Hollow City."},
        ["Talk to Thallik 1"] =
            {appendText=", just southwest of the Cliffs of Failure.\n", stepTextKey="I decided to save Thallik from the Observer's game. It was the only real choice if I want to defeat Molag Bal. I should talk to Thallik and send him to the Hollow City."},
        ["Talk to Thallik 2"] =
            {appendText=", who is with the rescued Mages Guild members, just southwest of the Cliffs of Failure.\n", stepTextKey="I decided to push back against the Observer and take everyone out of the game. Now I have Thallik and the mages at my side. I should speak to Thallik and send them all to the Hollow City."},
    },

[GetQuestName(4642)] = { --"Hall of Judgment"					-- MartinToms
["Destroy Elemental Crystals"] =
{appendText=".\nThe towers can be found at the Court of Contempt east of The Hollow City. The crystals are bound to be up top.\n"},
["Collect the Gate Key"] =
{appendText=".\nKnowing the Daedra, the Coffer will be in one of their small spiky urns."},
["Talk to Malkur Valos 1"] =
{appendText=".\nHe is a skilled conjurer, maybe he has already begun summoning some aid. I should look for atronachs and a gate.", stepTextKey="I destroyed the elemental crystals and collected the gate key. Now I should meet Malkur Valos at the entrance to the Hall of Judgment."},
["Enter the Hall of Judgment"] =
{appendText=" through the gate in the northeastern part of the ruins."},
["Enter the Holding Cells"] =
{appendText=" just beyond the gate in the northeastern part of the ruins."},
["Collect the Cage Key"] =
{appendText=" in the Holding Cells past the gate in the northeastern part of the ruins."},
["Rescue Tarrami"] =
{appendText=" from the southwestern cell."},
["Rescue Dithis Romori"] =
{appendText=" from the southeastern cell."},
["Rescue Denthis Romori"] =
{appendText=" from the northeastern cell.\n\nThe Holding Cells can be found past the gate in the northeastern part of the ruins."},
["Talk to Tarrami"] =
{appendText=" at the Holding Cells past the gate in the northeastern part of the ruins."},
["Meet the Mages Outside 1"] =
{appendText=" the Holding Cells past the gate in the northeastern part of the ruins.", stepTextKey="The rescued mages have headed outside to meet up with Malkur. I should join them."},
["Defend the Mages"] =
{appendText=" in the Hall of Judgment past the gate in the northeastern part of the ruins."},
["Exit the Hall of Judgment"] =
{appendText="."},
["Meet the Mages Outside 2"] =
{appendText=", south of the Court.", stepTextKey="The mages cast spells to cause chaos and better cover our escape. I should find Malkur Valos and the other mages on the road outside the Court of Contempt."},
["Talk to Malkur Valos 2"] =
{appendText=" south of the Court.", stepTextKey="I found the mages on the road outside the Court of Contempt. They've already opened a portal. I should talk to Malkur Valos and make sure they're alright."},
},
    [GetQuestName(4543)] = { --"Holes in the World"			-- MartinToms
        ["Seal Tear in Dushnikh's Shadow"] =
            {appendText=" in the east."},
        ["Seal Tear in Khaj'yahai"] =
            {appendText=" in the west."},
        ["Seal Tear in Silver Run"] =
            {appendText=", the central stolen village.\n\nThe tears in the Village of the Lost should be fairly visible, even from afar, but the villages themselves may be difficult to navigate. Perhaps there are portals around?\n\nTo get a better view, I could take a look around from the floating isles, they seem to be good vantage points for the isles in the Azure Plasm sea below."},
        ["Talk to Mezha-dro"] =
            {appendText=" in the Village of the Lost."},
    },


  [GetQuestName(4746)] = { --"A Misplaced Pendant"			-- MartinToms
        ["Find Ahirunz or Ernabi"] =
            {appendText=".\nLeave the Cave of Trophies and follow the path until it meets the main road. From there, head west, the Khajiit may be nearby."},
        ["Talk to Ahirunz"] =
            {appendText=" directly east of the walls of The Hollow City."},
    },
	[GetQuestName(4623)] = { --"The Soul-Meld Mage"						--HavocSource	--CyberJanet	
		[1] = 
			{appendStepText="I met Gadris on a platform up a ramp on the road leading south from the eastern exit from the Hollow City. He seemed to be talking to himself, but was actually talking to another melded soul. He tried to demonstrate the problem.\n\n", stepTextKey="The Dark Elf mage I was talking to transformed into a Khajiit. I should talk to him and get more details about their strange malady."},
		["Talk to Zur 1"] =
			{appendText=" , the Khajiit, on the platform where Gadris stood just moments ago!", stepTextKey="The Dark Elf mage I was talking to transformed into a Khajiit. I should talk to him and get more details about their strange malady."},
		[2] = 
			{appendStepText="I met them on a platform off the road leading south from the east exit of the Hollow City. ", stepTextKey="Zur the alchemist can craft a potion to get me past the rubble and into the laboratory, if I collect his notes and a rare tincture. They were scattered around the area when he accidentally blew up a Dwarven machine."},
		["Gather Zur's Notes and Tincture"] =
			{appendText=" \nThey are scattered around the road leading to the Vile Laboratory. \n\nThe tincture is in a small tower surrounded by zombies. It's to the right as you go south, almost directly opposite a ramp leading to the platform. An illusion of Zur in the room may have something to say. \n\nOne note is next to a bookcase by a crumbling wall, opposite the path leading to the small tower. \n\nThe other note is further south, on a low wall with a lamppost. You can see the entrance to the Vile Laboratory from there."},
		[3] = 
			{appendStepText="Zur is an alchemist and can make a potion to help me get into the Vile Laboratory. He needs his notes and a tincture that were scattered around the area. ", stepTextKey="I gathered Zur's materials. I should look for the entrance to the laboratory, where I hope to find him and Gadris."},
		["Find the Entrance"] =
			{appendText=" just near a low wall with a lamppost, on the road leading south to the Vile Laboratory."},
		[4] = 
			{appendStepText="To help them, I collected some items that were scattered when Zur accidentally exploded some dwarven machinery.\n\n", stepTextKey="I should enter the laboratory and give the notes and tincture to Gadris or Zur. I'm not sure which one of the soul-melded mages will be available when I reach them."},
		["Give Items to the Soul-Meld Mage"] =
			{appendText=" inside the Vile Laboratory. The entrance is to the east of a low wall with a lamppost, on the road leading south."},
		[5] = 
			{appendStepText="To help them, I collected some items that were scattered when Zur accidentally exploded some dwarven machinery.\n\n", stepTextKey="I need to wait for Zur to craft a potion that will temporarily reduce my size so that I can squeeze through a hole in the rubble and enter the Vile Laboratory."},
		["Wait While Zur Makes Potion"] =
			{appendText=" just inside the Vile Laboratory. There is a lot of rubble blocking further progress inside."},
		[6] = 
			{appendStepText="I collected some materials that Zur needed to help me get past the rubble in the Vile Laboratory, and gave them to him.\n\n", stepTextKey="Zur completed the potion that will make me small enough to slip through a gap in the rubble and enter the Vile Laboratory. I should talk to the soul-melded mage and get the potion."},
		["Get the Transmutation Potion"] =
			{appendText=" from the soul-melded mage just inside the Vile Laboratory."},
		[7] = 
			{appendStepText="To help them, I gathered materials to help Zur create a potion that would get me past the rubble blocking the passage to the workshop.\n\n", stepTextKey="The potion turned me into a monkey! Now I can squeeze through the rubble and enter the ancient Dwarven laboratory."},
		["Squeeze Through the Rubble"] =
			{appendText=" blocking further progress into the Vile Laboratory. There are a lot of stones and broken pipes, too heavy to move."},
		[8] = 
			{appendStepText="Zur made a potion that turned me into a monkey. In this form, ", stepTextKey="I squeezed through the rubble and entered the Vile Laboratory. Now I have to find the metallurgy workshop."},
		["Find the Metallurgy Workshop"] =
			{appendText=" past the rubble inside the Vile Laboratory. There is a maze of broken pipes to follow and climb."},
		[9] = 
			{appendStepText="Zur made a potion that turned me into a monkey, small enough to scramble through the broken pipes and rubble blocking the passageway.\n\n", stepTextKey="I made it to the metallurgy workshop and reverted back into my normal form. Now I need to find Gadris's notebook."},
		["Read Gadris's Notebook"] =
			{appendText=" on a table in the middle of the workshop. The water around it is very green."},
		[10] = 
			{appendStepText="Zur made a potion that turned me into a monkey, and I was able to scramble through the rocks, rubble, and broken pipes leading to the workshop to find Gadris' notebook.\n\n", stepTextKey="Gadris listed the items necessary to make the antipodal rods. I need to gather refined void salts, a crystalline essence matrix, and ebony ore from somewhere in this workshop."},
		["Gather Ebony Ore"] =
			{appendText=" from a green pool on the western side of the room, opposite the blocked entrance passage."},
		["Gather Crystalline Essence Matrix"] =
			{appendText=" from a table against the northwest wall, next to a toppled bookshelf. The table is cluttered with books."},
		["Gather Refined Void Salts"] =
			{appendText=" from a much neater table in the southeast part of the room. It's in front of an inactive forge, next to the blocked entrance.\n"},
		[11] = 
			{appendStepText="Zur turned me into a monkey so that I could scrabble past the rubble, stones and broken pipes to get into the workshop. There I read Gadris' notes for further instructions.\n\n", stepTextKey="I have the items from Gadris' notes, but he also mentioned a catalyst for the forging process. I should check to see if he left any notes on what this catalyst might be."},
		["Read Catalyst Note"] =
			{appendText=" on the table in the middle of the green water."},
		[12] = 
			{appendStepText="Zur made a potion that turned me into a monkey briefly, so that I could scramble through the rubble and along the broken pipes leading to the workshop. I found Gadris's notes, collected the materials he listed, but now I need a catalyst.\n\n", stepTextKey="According to Gadris' notes, corrupted blood would be the best catalyst for forging the antipodal rods. The experiment chamber should contain corrupted blood created by the Daedra. Some kind of monster guards the chamber, however."},
		["Gather Corrupted Blood"] =
			{appendText=" from a table in the Experiment Chamber. Its entrance is to the south of the main chamber, next to a green pool, and opposite a corpse staked to a table with a gem.\n\nInside, all except one of the tables has a corpse staked to it."},
		[13] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes to reach the workshop. There I found the materials needed, as well as a catalyst from the experiments room.\n\n", stepTextKey="Now that I have the components and the catalyst to forge the antipodal rods, I should look for a furnace in the metallurgy workshop."},
		["Melt the Components"] =
			{appendText=" at a forge in the workshop. A projection of Gadris has appeared and may have some advice. \n\nThe working furnace is just to the west of the passage from the experiments room, between two green pools."},
		[14] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken poles leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\n", stepTextKey="Now I need to forge the melted components into the antipodal rods. There must be a weapon anvil around here that I can use."},
		["Craft the Antipodal Rods"] =
			{appendText="\nThe weapon anvil is next to the glowing pit of coals, beside the working forge in the metallurgy workshop."},
		[15] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken poles leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\n", stepTextKey="I forged the antipodal rods for the Dwarven device that the Soul-Meld Mage told me about. I should make my way to the Overseer's workroom and meet up with Gadris or Zur."},
		["Meet the Soul-Meld Mage 1"] =
			{appendText=" deeper within the Vile Laboratory.  Go through the door next to some large pipes in the workshop, and follow the corridor. When you come to a crossroads, take the right turn and continue on.", stepTextKey="I forged the antipodal rods for the Dwarven device that the Soul-Meld Mage told me about. I should make my way to the Overseer's workroom and meet up with Gadris or Zur."},
		[16] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld, and made my way through a door leading deeper into the laboratory.\n\n", stepTextKey="I found Gadris near the door to the Overseer's workroom. I should talk to him and find out what I need to do next."},
		["Talk to the Soul-Meld Mage"] =
			{appendText=" next to the door at the end of the corridor."},
		[17] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\nThen I went through a door to the north and along the corridor to use the equipment. ", stepTextKey="I need to enter the Overseer's atelier and find the crystal that was used to power the Dwarven device."},
		["Find the Power Crystal"] =
			{appendText=" inside the Overseers Atelier. It's on a pedestal in the center of the green pool."},
		[18] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\nThen I went through a door to the north and along the corridor to the Overseer's Atelier, where the meld took place.", stepTextKey="Now that I have the power crystal, I need to locate the device that melded Gadris and Zur's souls."},
		["Find the Dwarven Device"] =
			{appendText=" against the west wall of the Overseer's Atelier. It's directly across from the entrance."},
		[19] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\nThen I went through a door to the north and along the corridor to the Overseer's Atelier, where the meld took place. ", stepTextKey="I found a strange-looking Dwarven device. This should be the machine that can reverse the soul-meld and set Gadris and Zur free. I should talk to the mage and get any final instructions."},
		["Meet the Soul-Meld Mage 2"] =
			{appendText=" next to the Dwarven device against the west wall of the Overseer's Atelier.", stepTextKey="I found a strange-looking Dwarven device. This should be the machine that can reverse the soul-meld and set Gadris and Zur free. I should talk to the mage and get any final instructions."},
		[20] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\nThen I went through a door to the north and along the corridor to the Overseer's Atelier, where the meld took place. Here I found a power crystal and a Dwarven device. ", stepTextKey="I need to place the crystal into the Dwarven device to provide the power necessary to separate the mages' souls."},
		["Place the Crystal"] =
			{appendText=" on the Dwarven Power Mechanism against the west wall of the Overseer's Atelier."},
		[21] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\nThen I went through a door to the north and along the corridor to the Overseer's Atelier, where the meld took place, and found a power crystal and a Dwarven device.\n\n", stepTextKey="Two pillars connect to the Dwarven device. I need to insert an antipodal rod into each pillar. That should begin the process of reversing the soul-meld."},
		["Insert the Left Antipodal Rod"] =
			{appendText=" into the left pillar of the Dwarven device against the west wall of the Overseer's Atelier."},
		["Insert the Right Antipodal Rod"] =
			{appendText=" into the right pillar of the Dwarven mechanism against the west wall."},
		[22] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\nThen I went through a door to the north and along the corridor to the Overseer's Atelier, where I activated a Dwarven mechanism. \n\n", stepTextKey="The soul-meld is unraveling. The souls of the two mages have each been drawn to one of the antipodal rods. Now I need to pull one of the levers to save either Zur or Gadris."},
		["Choose One Soul to Restore"] =
			{appendText=". There is only one body, but there are two souls, one next to each pillar. Pull the lever next to the soul you want to restore."},
		[23] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\nThen I went through a door to the north and along the corridor to the Overseer's Atelier, and activated a Dwarven mechanism against the west wall. It separated the souls, but there is only one body to use.\n\n", stepTextKey="I decided to save Zur. I should talk to him and see if he's recovered from the soul-meld reversal."},
		["Talk to Zur 2"] =
			{appendText=" next to the Dwarven machinery inside the Overseer's Atelier.", stepTextKey="I decided to save Zur. I should talk to him and see if he's recovered from the soul-meld reversal."},
		[24] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\nThen I went through a door to the north and along the corridor to the Overseer's Atelier, where I activated a Dwarven mechanism against the west wall to unmeld the souls.\n\n", stepTextKey="I found a strange crystal attached to the device. I should take the crystal."},
		["Take the Crystal"] =
			{appendText=" from the Dwarven device against the west wall of the Overseer's Atelier."},
		[25] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\nThen I went through a door to the north and along the corridor to the Overseer's Atelier, where I activated a Dwarven mechanism against the west wall. The souls unmelded, but only one could be saved.\n\nThe power crystal used in the process was not destroyed, so I retrieved it. ", stepTextKey="Now that I have the crystal, I should find the exit door and leave this Vile Laboratory."},
		["Leave the Laboratory 1"] =
			{appendText=" through the door at the end of a small passage next to a bookshelf against a wall engraved with runes.", stepTextKey="Now that I have the crystal, I should find the exit door and leave this Vile Laboratory."},
		[26] = 
			{appendStepText="I found everything needed to free them both, but only one soul could be saved. ", stepTextKey="I should meet Zur outside the Vile Laboratory and speak to him."},
		["Talk to Zur 3"] =
			{appendText=" outside the Vile Laboratory, at the very end of the road leading south.", stepTextKey="I should meet Zur outside the Vile Laboratory and speak to him."},
		[27] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld. \n\nThen I went through a door to the north and along the corridor to the Overseer's Atelier, where I activated a Dwarven mechanism against the west wall.  It separated the souls, but there is only one body to use.\n\n", stepTextKey="I decided to save Gadris. I should talk to him and see if he's recovered from the soul-meld reversal."},
		["Talk to Gadris 1"] =
			{appendText=" next to the Dwarven machinery inside the Overseer's Atelier.", stepTextKey="I decided to save Gadris. I should talk to him and see if he's recovered from the soul-meld reversal."},
		[28] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\nThen I went through a door to the north and along the corridor to the Overseer's Atelier, where I activated a Dwarven mechanism against the west wall to unmeld the souls.\n\n", stepTextKey="Gadris thinks that the powerful crystal attached to the device is one of the legendary Lights of Meridia. I should take the crystal."},
		["Take the Light of Meridia"] =
			{appendText=" that powered the unmeld on the Dwarven machine."},
		[29] = 
			{appendStepText="Zur turned me into a monkey so that I could scramble through the rubble and along the broken pipes leading to the metallurgy workshop. There I found the materials needed to create some rods to help undo the meld.\n\nThen I went through a door to the north and along the corridor to the Overseer's Atelier, where I activated a Dwarven mechanism against the west wall to unmeld the souls. The crystal that powered the process was not destroyed, so I retrieved it.\n\n", stepTextKey="Now that I have the Light of Meridia, I should find the exit door and leave this Vile Laboratory."},
		["Leave the Laboratory 2"] =
			{appendText=" through the door at the end of a small passage next to a bookshelf against a wall engraved with runes.", stepTextKey="Now that I have the Light of Meridia, I should find the exit door and leave this Vile Laboratory."},
		[30] = 
			{appendStepText="I found everything needed to free them both, but only one soul could be saved. ", stepTextKey="I should meet Gadris outside the Vile Laboratory and speak with him."},
		["Talk to Gadris 2"] =
			{appendText=" outside the Vile Laboratory, at the very end of the road leading south.", stepTextKey="I should meet Gadris outside the Vile Laboratory and speak with him."},
	},
[GetQuestName(4541)] = { --"Soul Survivors"					--MartinToms
        ["Talk to Zirani"] =
            {appendText=", the Khajiiti mayor of the village to the west.\n"},
        ["Talk to Ugorz"] =
            {appendText=", the Orc leader in the stronghold to the east.\n\nThe Village of the Lost may be difficult to navigate. Perhaps there are portals around? Some jumping may be required too."},
        ["Go to the Overseer's Overlook"] =
            {appendText=".\nThere are bound to be portals for the Taskmasters and Overseers to get around the Village of the Lost."},
        ["Talk to Suronii 1"] =
            {appendText=" in the Overseer's Overlook within the central mountain up north.", stepTextKey="I reached the overlook. I should talk to Suronii."},
        ["Jump Off The Cliff"] =
            {appendText=" at the Overseer's Overlook within the central mountain up north - and die."},
        ["Talk to Suronii 2"] =
            {appendText=" at the entrance to The Village of the Lost.", stepTextKey="I died, powering Suronii's spell. The image of Suronii remains. Perhaps I should speak to it."},
        ["Talk to Suronii 3"] =
            {appendText=" at the entrance to The Village of the Lost.", stepTextKey="I died, powering Suronii's spell. The image of Suronii remains. Perhaps I should speak to it."},
    },

[GetQuestName(4347)] = { --"Special Blend"					-- HavocSource
["Read the Note"] =
{appendText=" next to the body of Gamirth. The note and the body are at the end of the southeastern road."},
["Talk to Tavern Patrons"] =
{appendText=" inside the Everfull Flagon Tavern, at the end of the southeastern road."},
["Talk to Nelhilda 1"] =
{appendText=" upstairs in the bedroom.", stepTextKey="Something is definitely wrong at this tavern. I met a Nord named Bernt, who urged me to speak to his daughter, Nelhilda. It was her late husband who wrote the note. I should be able to find her upstairs."},
["Locate Kyne's Shrine"] =
{appendText=" southeast from the tavern past a small lake. There is a gigantic spiked rock next to the path up to it."},
["Find a Runestone of Kyne"] =
{appendText=" on the altar made of three dolmens with various inscriptions. The altar is up a path southeast of the tavern, past a lake. There is a gigantic spiked rock next to the way up."},
["Gather Kyne's Tears"] =
{appendText=".\nThese are small red flowers surrounded by a whirly aura. They bloom under large old trees southeast of the Everfull Flagon."},
["Give Kyne's Tears to Nelhilda"] =
{appendText=" upstairs in the Everfull Flagon."},
["Take the Purifying Potion"] =
{appendText=" on the bedroom table upstairs in the Everfull Flagon."},
["Purify the Casks of Special Blend"] =
{appendText=" in the Everfull Flagon, downstairs."},
["Talk to Bernt the Brittle"] =
{appendText="in the Everfull Flagon, downstairs."},
["Find Hridi's Dueling Daggers"] =
{appendText=".\nShe is standing upstairs in the Everfull Flagon and might remember what she did with them if you push her hard enough.\n"},
["Find Hautt's Lute"] =
{appendText=".\nHe is leaning against a wall in the Everfull Flagon. He might remember where he last had it provided you're a sweet-talker; the lute must be in a container large enough for it."},
["Return to the Everfull Flagon 1"] =
{appendText=".", stepTextKey=".\n I found Hridi's daggers and Hautt's lute. I should give them to Bernt so he can return them to their rightful owners. He thinks it will help restore self-respect and set a good example for the others."},
["Talk to Bernt 1"] =
{appendText=" upstairs in the Everfull Flagon.", stepTextKey="Inside the Flagon, the now sober villagers confronted the mysterious Thane, who revealed himself to be some sort of Daedra. I need to find Bernt and speak to him."},
["Find the Thane's Lair"] =
{appendText=" west of the Everfull Flagon in the small village. A lair is almost always underground. I should keep my eyes on the ground."},
["Defeat the Thane"] =
{appendText=" inside their lair, east of the Everfull Flagon and underground."},
["Set the Villagers' Souls Free"] =
{appendText=".\nThe soul gem containing the villagers' souls is east of the Everfull Flagon in the Thane's underground lair."},
["Return to the Everfull Flagon 2"] =
{appendText=".", stepTextKey=".\nI freed the souls of the villagers. I should go back to the Everfull Flagon and find Bernt."},
["Talk to Bernt 2"] =
{appendText=" upstairs.", stepTextKey="I made it back to the Everfull Flagon. I should find Bernt and see what he plans to do next."},
["Talk to Nelhilda 2"] =
{appendText=", who stormed downstairs.", stepTextKey="Nelhilda was understandably upset when she realized that her father originated the curse that plagued the Everfull Flagon and caused the loss of her husband. I should talk to her."},
["Talk to Nelhilda 3"] =
{appendText=", who stormed downstairs.", stepTextKey="Nelhilda decided to forgive her father. She will lead any villagers who wish to leave the Everfull Flagon to the Hollow City."},
["Talk to Nelhilda 4"] =
{appendText=", who stormed downstairs.", stepTextKey="Nelhilda won't forgive her father for the trouble he caused. She will lead any villagers who wish to join her to the Hollow City. But Bernt will remain here."},

},

 [GetQuestName(4348)] = { --"A Graveyard of Ships"			-- MartinToms
        ["Find First Mate Jalan"] =
            {appendText=".\nJalan sounds like a Khajiit name. I should begin the search in the center of The Lost Fleet."},
        ["Protect First Mate Jalan"] =
            {appendText=" from the skeletons in the center of The Lost Fleet."},
        ["Follow First Mate Jalan"] =
            {appendText=" into the cabin of the wreck within The Lost Fleet."},
        ["Defeat First Mate Jalan"] =
            {appendText=" within the cabin of the wreck within The Lost Fleet."},
        ["Find One-Eye"] =
            {appendText=".\nThere are two other wrecks south and north of the central area of The Lost Fleet. Perhaps One-Eye is within one of them."},
        ["Talk to One-Eye"] =
            {appendText=" in the cabin of the Wreck of the Bonnie Spriggan northeast of The Lost Fleet."},
    },
[GetQuestName(4358)] = { --"Between Blood and Bone"				--Jordakai
		[1] = 
			{appendStepText="East of the Reaver Citadel Wayshrine, on the Bonnie Spriggan shipwreck in The Lost Fleet, Captain One-Eye and I were interrupted. ", stepTextKey="An Argonian Skeleton has appeared before us. It has something it wants to say."},
		["Listen to the Argonian Skeleton"] =
			{appendText=" inside the shipwreck's cabin."},
		[2] = 
			{appendStepText="East of the Reaver Citadel Wayshrine, on the Bonnie Spriggan shipwreck in The Lost Fleet, Captain One-Eye and I were interrupted. ", stepTextKey="An Argonian Skeleton has appeared before us. It has something it wants to say."},
		["Talk to the Argonian Skeleton"] =
			{appendText=" inside the shipwreck's cabin."},
		[3] = 
			{appendStepText="East of Reaver Citadel Wayshrine, in the cabin of the Bonnie Spriggan shipwreck of The Lost Fleet, Captain ", stepTextKey="One-Eye killed the Argonian Skeleton after the apparition of the Admiral ordered it to attack. I should talk to her to coordinate our next move."},
		["Talk to Captain One-Eye 1"] =
			{appendText=".", stepTextKey="One-Eye killed the Argonian Skeleton after the apparition of the Admiral ordered it to attack. I should talk to her to coordinate our next move."},
		[4] = 
			{appendStepText="In The Lost Fleet, we must search another shipwreck. ", stepTextKey="The Argonian Skeleton's journal holds the secret to finding the Admiral. He hid the journal in his ship, the Golden Era, now part of the skeleton village. Captain One-Eye has gone on ahead to look for the journal. I should meet her there."},
		["Enter the Golden Era's Hold"] =
			{appendText=". The skeletons have built nice boardwalks to the upright ship at the southern end of the azure plasm lake."},
		[5] = 
			{appendStepText="At the southern end of The Lost Fleet's azure plasm lake, ", stepTextKey="I entered the Golden Era's hold. The Argonian Skeleton said he hid his journal somewhere inside. I'll try to find it."},
		["Find the Journal"] =
			{appendText=" that holds the key to revenge for Captain One-Eye."},
		[6] = 
			{appendStepText="At the southern end of The Lost Fleet's azure plasm lake, in the Golden Era's hold, ", stepTextKey="Captain One-Eye came in the doorway. I should speak to her."},
		["Talk to Captain One-Eye 2"] =
			{appendText=" about the Journal of Tsona-Ei that I found.", stepTextKey="Captain One-Eye came in the doorway. I should speak to her."},
		[7] = 
			{appendStepText="In the Golden Era's shiphold at the southern end of The Lost Fleet, I learned that ", stepTextKey="Captain One-Eye wants me to use the key to open the tunnel that leads to the Coral Tower."},
		["Enter the Tunnel"] =
			{appendText=" that leads up to the tower. Its wooden entrance is in the southeast."},
		[8] = 
			{appendStepText="In The Lost Fleet's southeast, I entered the tunnel. ", stepTextKey="With the path cleared, I'm free to make my way to the Coral Tower."},
		["Go to the Coral Tower"] =
			{appendText=", up through the tunnel and along the boardwalk on the upper plateau. This Admiral sure likes boardwalks."},
		[9] = 
			{appendStepText="In The Lost Fleet's southeast, up through a tunnel to a plateau with a lovely  boardwalk, ", stepTextKey="I found the Coral Tower and should now enter."},
		["Enter the Coral Tower"] =
			{appendText=" through a door that was likely designed by the Prince of Schemes."},
		[10] = 
			{appendStepText="Up on the plateau in The Lost Fleet's southeast, I entered the Coral Tower. ", stepTextKey="Captain One-Eye asked me to get the Crown of Bones from the Admiral. Meanwhile she will be searching for other undead \"relatives\" from Alten Corimont."},
		["Get the Crown of Bones"] =
			{appendText=" off the skull of The Lost Fleet Admiral."},
		[11] = 
			{appendStepText="In The Lost Fleet's southeast, at the top of the Coral Tower, ", stepTextKey="I defeated the Admiral and retrieved his Crown of Bones. I should find Captain One-Eye and see how the rest of her plan turned out."},
		["Talk to Captain One-Eye 3"] =
			{appendText=". She waits for her prize of revenge across from the tower's entrance.", stepTextKey="I defeated the Admiral and retrieved his Crown of Bones. I should find Captain One-Eye and see how the rest of her plan turned out."},
		[12] = 
			{appendStepText="Up on the plateau reached through the tunnel in The Lost Fleet's southeast, ", stepTextKey="I agreed to give Captain One-Eye the Crown of Bones. It's evil, but perhaps she can control it."},
		["Talk to Captain One-Eye 4"] =
			{appendText=" across from the Coral Tower's entrance.", stepTextKey="I agreed to give Captain One-Eye the Crown of Bones. It's evil, but perhaps she can control it."},
		[13] = 
			{appendStepText="Up on the plateau reached through the tunnel in The Lost Fleet's southeast, ", stepTextKey="I refused to give Captain One-Eye the Crown of Bones. I should talk to her and see how she's taking my decision."},
		["Talk to Captain One-Eye 5"] =
			{appendText=" across from the Coral Tower's entrance.", stepTextKey="I refused to give Captain One-Eye the Crown of Bones. I should talk to her and see how she's taking my decision."},
	},

 [GetQuestName(4747)] = { --"The Anguish Gem"				-- MartinToms
        ["Destroy the Anguish Gem"] =
            {appendText=" within the Wailing Maw in the northeasternmost region. If it is precious, it is bound to be deep within the caverns. Since it's holding a soul, it's going to resemble a soul gem - if it isn't one."},
        ["Talk to Dralnas Moryon"] =
            {appendText=" at the entrance to The Wailing Maw."},
    },

[GetQuestName(4814)] = { --"News of Fallen Kin"			-- MartinToms
        ["Talk to Grundskar"] =
            {appendText=".\nIf he is alive, he will be within The Hollow City. Perhaps I should look in the Inn first? Coldharbour can be quite depressing and he is likely drinking his sorrows away. If he is Nettira's cousin, he is also a Nord."},
    },
    [GetQuestName(4374)] = { --"Old Bones"			-- MartinToms
        ["Collect Leg Bones"] =
            {appendText="."},
        ["Collect Ribcage"] =
            {appendText="."},
        ["Collect Arm Bones"] =
            {appendText="."},
        ["Collect Hip Bone"] =
            {appendText=".\n\nThe skeletons south of The Lost Fleet have an abundance of bones..."},
        ["Talk to Bosun Bones 1"] =
            {appendText=", the skull on top of a crate near a candelabra southwest of The Lost Fleet, next to the entrance to the Coral Tower Tunnel.", stepTextKey="I found the bones, now I should return them."},
        ["Place Bones"] =
            {appendText=" on the mound next to the crates southwest of The Lost Fleet, next to the entrance to the Coral Tower Tunnel."},
        ["Talk to Bosun Bones 2"] =
            {appendText=", the assembled skeleton next to the crates near a candelabra southwest of The Lost Fleet, next to the entrance to the Coral Tower Tunnel.", stepTextKey="Bosun Bones is whole again. I should speak to him."},
    },

[GetQuestName(4757)] = { --"What the Heart Wants"			-- MartinToms
["Enter the Manor"] =
{appendText=", the Redguard fortress in the northern region."},
["Talk to Stibbons 1"] =
{appendText=", the iconic balding man wearing stylish leather clothing. He is probably not in the main building yet... so maybe somewhere in front of it?", stepTextKey="Now that I'm inside the Manor of Revelry, I should find Stibbons and speak with him."},
["Meet Stibbons at the Banquet"] =
{appendText=".\nHe left for somewhere up north, the tables are bound to be there. I should look for Rayyaima.\n\nI may also wish to speak with others along the way."},
["Go to the Pools"] =
{appendText=", which are bound to be near the majestic Redguard palace. Perhaps following the vegetation is wise, it has to get its water somewhere."},
["Talk to Shayaifa"] =
{appendText=" at the small structure near the eastern pools."},
["Talk to Fatahala 1"] =
{appendText=" at the eastern pools.", stepTextKey="On my way to use the pool, Fatahala appeared. I should talk to Fatahala."},
["Use the Basin"] =
{appendText=", which Shayaifa told you to cleanse yourself in before soaking."},
["Talk to Fatahala 2"] =
{appendText=", the Dark Seducer by the eastern bridge.", stepTextKey="I used the cleansing reagents and everything has changed. I should talk to Fatahala and find out what happened."},
["Enter the Manor House"] =
{appendText=", if it can be called that. The Manor of Revelry is the grand Redguard palace that overshadows the entire desert."},
["Find Stibbons"] =
{appendText=". There are only so many places he could be."},
["Collect the Cage Key"] =
{appendText=" from the Mazken sisters in the Manor. Dark Seducers are far too careful to leave it on a table; it will be in a container somewhere near one of them."},
["Free Stibbons"] =
{appendText=" from the Stargate Room on the second floor of the Manor."},
["Talk to Stibbons 2"] =
{appendText=" in the Stargate Room on the second floor of the Manor.", stepTextKey="Fatahala knows a way out of the manor, but Stibbons won't leave until he retrieves his lady's jewels. I should speak to Stibbons."},
["Collect Lady Laurent's Emerald"] =
{appendText=". Nuzara seems like the type to prefer emeralds."},
["Collect Lady Laurent's Diamond"] =
{appendText=". Rayaima seems like the type to prefer diamonds.\n\nBoth must still be within the Manor, perhaps on the ground floor. As with the key, it is likely the Mazken put the gems in coffers for safekeeping."},
["Talk to Stibbons 3"] =
{appendText=" somewhere east of the Manor. I should look for a cave, as that is where Fatahala said they were going.", stepTextKey="I recovered Lady Laurent's stolen jewels. Now I should make my way to the pools and find Stibbons at the entrance to the secret tunnel."},
["Reach the Far Side of the Cave"] =
{appendText=" past the rock in the southeast desert."},
["Leave the Manor of Revelry"] =
{appendText="."},
["Talk to Stibbons 4"] =
{appendText=" by the exit from the Manor of Revelry Cave, south of the Manor itself.", stepTextKey="I should talk to Stibbons and make sure he's alright."},
},

-- ==================================================================================================================================================
--	Craglorn																															Craglorn
-- ==================================================================================================================================================


-- 		=========================================================================
--		  Craglorn Main
-- 		=========================================================================
		[GetQuestName(5747)] = { -- "The Star-Gazers"				-- MartinToms
			["Travel to Craglorn"] =
				{appendText="'s south-central town of Belkarth from Hallin's Stand in Bangkorai, or through other means."},
			["Ask About Star-Gazers In Town"] =
				{appendText=".\nBelkarth should have some kind of structure where the Star-Gazers operate."},
			["Find Hara"] =
				{appendText="."},
			["Talk to Hara 1"] =
				{appendText=", the robed Redguard lady praying in the middle of the Observatory.", stepTextKey="I found Hara in the Star-Gazer's headquarters in Belkarth. She may be able to tell me more about events in Craglorn, as well as the Star-Gazers."},
			["Talk to Hara 2"] =
				{appendText=" within the Belkarth Observatory and give her my decision as to whether I wish to face the Celestials.", stepTextKey="Hara asked me to join the Star-Gazers and aid her in unraveling the problems facing Craglorn. I must agree to help her before we can proceed."},
			["Experience the Ritual"] =
				{appendText=" by entering the circle of stars within the Belkarth Observatory and accepting the blessing of the Star-Gazers."},
			["Talk to the Thief"] =
				{appendText="."},
			["Return to the Star-Gazers"] =
				{appendText=" in Belkarth's Observatory."},
			["Talk to Hara 3"] =
				{appendText=" in the Belkarth Observatory to become a Star-Gazer proper and discuss the next steps.", stepTextKey="I have been accepted as a Star-Gazer. I must complete my initiation by speaking to Hara."},
		},
		[GetQuestName(5746)] = { -- "The Corrupted Stone"			-- Jordakai -- MartinToms
			["Talk to Erold"] =
				{appendText=" in Belkarth's Crossroads Tavern."},
			["Search for the Skystone Amulet"] =
				{appendText=".\nPerhaps I should ask Hara for directions and information."},
			["Listen to the Thief"] =
				{appendText=" in Mtharnaz."},
			["Visit the Lord Mundus Stone"] =
				{appendText=" on a hill near water."},
			["Visit the Lady Mundus Stone"] =
				{appendText=" on an island."},
			["Visit the Steed Mundus Stone"] =
				{appendText=" on a rocky ridge near some ruins.\n\nThere's really no other way to go about this than scouring Craglorn. If the Warrior is not protecting the stones, they are likely broken or corrupted.\n\nSince the amulet was found in Mtharnaz, chances are the Mundus stones are nearby in the western, lower Craglorn area."},
			["Search the Inner Ruins of Kardala"] =
				{appendText=".\nThe Thief Celestial told me that Kardala lies at the center point from where the three broken mundus stones rest - again within western, lower Craglorn."},
			["Reach the Warrior's Apex Stone"] =
				{appendText=".\nThe Thief warned me that the traps in the ruins are still active."},
			["Restore the Warrior's Apex Stone"] =
				{appendText=" deep within the Yokudan Kardala ruins at the Throne of the Warrior."},
			["Return to Star-Gazer Erold in Belkarth"] =
				{appendText="'s Crossroads Tavern."},
		},
		[GetQuestName(5748)] = { -- "The Warrior's Call"			-- Jordakai -- MartinToms
			["Search for the Indecent Imperial at Bangkorai Gate"] =
				{appendText=". Perhaps I should speak with Hara again before departing."},
			["Free Titus Valerius"] =
				{appendText=" from his bonds within the tent at the Bangkorai Gate."},
			["Travel to Buried Sands"] =
				{appendText=". Titus said it is a cave. He headed north from the tents at Bangkorai Gate."},
			["Search for the Burial Chamber"] =
				{appendText=" inside, possibly towards the rear of the caverns."},
			["Listen to Titus Valerius"] =
				{appendText=" within the Forgotten Burial Chamber of Buried Sands."},
			["Find the Ruined Library"] =
				{appendText=". Ruins of a large settlement can be found southwest of Belkarth. Perhaps the ancient records will be hidden nearby."},
			["Enter the Ruined Library"] =
				{appendText=" in the cliffs at the southern end of Scorpion Ravine."},
			["Help Titus Locate the Legend of Tarish-Zi"] =
				{appendText=" within the Ruined Library carved into the cliffs southwest of Rahni'Za. There are many records, perhaps I should examine them all."},
			["Retrieve Tahmin's Royal Seal"] =
				{appendText="."},
			["Retrieve Riza's Royal Seal"] =
				{appendText=".\n\nRecords indicate that each of these Anka-Ra retainers have separate Ancient Tombs. I should explore the ritual sites north of Rahni'Za and its library."},
			["Meet Titus In the Tombs of the Na-Totambu"] =
				{appendText=" west of Rahni'Za, above the Scorpion Ravine."},
			["Search for Emperor Tarish-Zi"] =
				{appendText=" in his Crypt within the Tombs of the Na-Totambu."},
			["Defeat Emperor Tarish-Zi"] =
				{appendText=" in his Crypt within the Tombs of the Na-Totambu."},
			["Talk to the Thief 1"] =
				{appendText=" in the Crypt of Tarish-Zi within the Tombs of the Na-Totambu.", stepTextKey="The Thief suddenly appeared before me after Tarish-Zi was vanquished. I should speak with her."},
			["Talk to the Thief 2"] =
				{appendText=" in the Crypt of Tarish-Zi within the Tombs of the Na-Totambu.", stepTextKey="The Thief suddenly appeared before me after Tarish-Zi was vanquished. I should speak with her."},
		},
		[GetQuestName(5761)] = { -- "Elemental Army"				-- Jordakai -- MartinToms
			["Investigate the Proving Grounds Dolmen"] =
				{appendText=". Perhaps I should speak with Hara, as she may know more about this dolmen."},
			["Talk to the Thief 1"] =
				{appendText=" at Proving Grounds Dolmen.", stepTextKey="The Celestial Thief appeared before me at the Proving Grounds Dolmen in Craglorn. I should speak with her."},
			["Talk to the Thief 2"] =
				{appendText=" at Proving Grounds Dolmen.", stepTextKey="I should talk to the Thief to learn where to find Kelmen Locke."},
			["Find Kelmen Locke"] =
				{appendText=". Trade markets are often near major roads between cities. Perhaps I should start looking east of Belkarth, but not as far as Elinhir."},
			["Talk to Kelmen Locke"] =
				{appendText=" deep within the tower."},
			["Defeat the Flame Monarch"] =
				{appendText=" in its lair within an Ayleid ruin breached by volcanic lava flows. Perhaps I should search south of the Conflagration Anomaly.\n"},
			["Defeat the Frost Monarch"] =
				{appendText=" in its lair. Rumors whisper of what could be hidden behind the serpent's dark doors in the cliffs far north of the Fulminant Anomaly.\n"},
			["Defeat the Storm Monarch"] =
				{appendText=" in its lair. A single Ayleid doorway set in a natural stone monolith has been spotted on a rocky ridge overlooking Lower Craglorn's east-west road. Perhaps I should investigate the area between the Fulminant Anomaly and the Conflagration Anomaly.\n\nThe Gem of Celestial Command in my possession will bind each Monarch as I defeat them."},
			["Find Kelmen Locke at Ritual Site"] =
				{appendText=". With the defeated Monarchs being in eastern Craglorn and Kelmen being a mage from Elinhir, I may want to look east of Elinhir for the place he plans to use."},
			["Summon the Frost Monarch"] =
				{appendText="."},
			["Summon the Flame Monarch"] =
				{appendText="."},
			["Summon the Storm Monarch"] =
				{appendText=".\n\nThe ritual site is south of Falkreath Hold, at the top of some stone stairs."},
			["Listen to the Atronachs"] =
				{appendText=" at the ritual site south of Falkreath Hold."},
			["Talk to Kelmen 1"] =
				{appendText=" at the ritual site south of Falkreath Hold.", stepTextKey="The monarchs confirmed that there is a fourth atronach, created by the Serpent. I should talk to Kelmen Locke about this news."},
			["Kill the Air Monarch"] =
				{appendText=" in the Ayleid ruins of Balamath near the Fulminant Anomaly."},
			["Talk to Kelmen 2"] =
				{appendText=" outside of Balamath Hall in the ruins of Balamath.", stepTextKey="I defeated the Serpent's monarch air atronach. I should speak to Kelmen Locke."},
		},
		[GetQuestName(5763)] = { -- "The Shattered and the Lost"	-- Jordakai -- MartinToms
			["Find the High Elves In the Crossroads Tavern"] =
				{appendText="."},
			["Observe the High Elves"] =
				{appendText=" in the northern wing of the Crossroads Tavern in Belkarth."},
			["Talk to Valla 1"] =
				{appendText=", the bright-haired female with a shining staff by the chef's tables in the Crossroads Tavern of Belkarth.", stepTextKey="I should talk to the High Elf and see what she has to say."},
			["Observe What Happened to the Mage"] =
				{appendText="."},
			["Talk to Valla 2"] =
				{appendText=", who awaits you within the Crossroads Tavern of Belkarth.", stepTextKey="I witnessed events as they transpired between the Serpent and the Celestial Mage. I should talk to Valla and find out what it all means."},
			["Gather the Seeker's Sight Gems"] =
				{appendText=". \nThere are stories about a gigantic obelisk that fell to Nirn in central Craglorn. Some folks believe it is the Celestial Mage’s staff that fell from the sky. It is said that atronachs of frost, flame, storm, and air infest the region north of Belkarth. \n\nThe gems should be large enough to find. With the force of the obelisk’s impact, the gems were probably thrown just beyond the crater’s edges. They could be in a river near a waterfall, or close to an Orc camp by a lake, or even in a ravine with a lonely storm atronach not far from a winery! This may take some time."},
			["Meet the Mage's Aspects at the Winery"] =
				{appendText="."},
			["Talk to Ahlora 1"] =
				{appendText=" on top of the Ogondar's Winery.", stepTextKey="I should talk to Ahlora about the Seeker's Sight."},
			["Defeat the Guardians to Charge the Gems"] =
				{appendText=". \n\nI should find Anomalies with their highly visible, dense magicka, probably emanating from large crystals. These sites are likely beyond the edges of Spellscar’s crater. I should look to the north, east, southeast, and south."},
			["Meet the Aspects at the Star-Gazers' Observatory"] =
				{appendText=" in Belkarth."},
			["Talk to Hara"] =
				{appendText="."},
			["Place the Seeker's Sight and Observe"] =
				{appendText=". The star map is in the center of the Belkarth Star-Gazer’s Observatory."},
			["Talk to Ahlora 2"] =
				{appendText=", the blonde aspect of the Mage, in the Star-Gazer’s Observatory at Belkarth.", stepTextKey="The Seeker's Sight has shown us where we can find other aspects of the Celestial Mage. I should talk to Ahlora about our next steps."},
			["Find the First Mage Aspect"] =
				{appendText=" hidden within a Dwemer ruin, probably in the area east of the crater where one of the gems was found."},
			["Find the Second Mage Aspect"] =
				{appendText=", who has taken refuge among Hircine’s ravenous werewolves. Probably in caverns near a river and possibly near where another gem was found.\nThe powered relic I have, the Seeker’s Sight, should help me locate an Aspect of the Mage when I am near where they hide."},
			["Meet the Aspects at the Winery"] =
				{appendText=" to discuss the next steps."},
			["Talk to Valla 3"] =
				{appendText=" inside Ogondar’s Winery. Perhaps I should speak with each of the Aspects.", stepTextKey="I arrived at the winery. I should talk to Valla."},
			["Find the Sewer Entrance Beneath Elinhir"] =
				{appendText=", known as the City of Mages, in the region’s southeast.\n\nThe relic, Seeker’s Sight, should help me find the Lost One. I was warned that if The Mage’s Apex Stone were to be destroyed, Mundus would be destroyed, too. I should prepare to defeat the Lost One in battle."},
			["Find the Apex Stone"] =
				{appendText=" near the western cistern within Elinhir Sewerworks."},
			["Find and Defeat the Lost One"] =
				{appendText=" in the Apex Stone chamber near the western cistern of the Elinhir Sewerworks."},
			["Inform the Star-Gazers of the Mage's Joining"] =
				{appendText=". I should meet Trilion at Ogondar's Winery."},
		},
		[GetQuestName(5760)] = { -- "The Missing Guardian"			-- Jordakai -- MartinToms
			["Talk to Nazdura"] =
				{appendText=", the Orc at the Star-Gazer's Observatory."},
			["Find Hara at the Star-Gazer's Observatory"] =
				{appendText=" in Belkarth. She should be in her private quarters on the upper floor."},
			["Talk to Titus Valerius"] =
				{appendText=" in Hara's private quarters in the Star-Gazer's Observatory."},
			["Meet Titus and Kelmen at the Lake"] =
				{appendText=" south of Belkarth, where the Nedic ruins touch the shore."},
			["Talk to Kelmen Locke"] =
				{appendText=" south of Belkarth, where an ancient bridge leads towards the lake’s submerged Nedic ruins."},
			["Find a Way Inside Reinhold's Retreat"] =
				{appendText=", the sunken Nedic ruin in the middle of Belkarth’s southern lake."},
			["Enter Reinhold's Retreat"] =
				{appendText=" by diving into the whirlpool in the middle of the lake south of Belkarth."},
			["Search the Ruins"] =
				{appendText=" beneath the lake of Belkarth."},
			["Defeat Madleena Blackvein"] =
				{appendText=" deep within the ruins beneath Belkarth's lake."},
			["Search for the Apex Stone"] =
				{appendText=" in Reinhold's Retreat beneath Belkarth's lake."},
			["Stop the Serpent and Free the Thief's Apex Stone"] =
				{appendText=" in Reinhold's Retreat beneath Belkarth's lake."},
			["Talk to Hara"] =
				{appendText=" in front of her Apex Mundus Stone in the Star-Gazers Sanctuary, deep within Reinhold's Retreat beneath Belkarth's lake."},
			["Meet Hara at the Star-Gazer Observatory"] =
				{appendText=" in Belkarth."},
		},
		[GetQuestName(5769)] = { -- "The Serpent's Fang"			-- Jordakai -- MartinToms
			["Meet Little Leaf in Ilthag's Undertower"] =
				{appendText=" near the Valley of Scars Wayshrine."},
			["Kill Ilthag Ironblood"] =
				{appendText=", the Orc warrior who can supposedly train anything."},
			["Talk to Little Leaf"] =
				{appendText=" within Ilthag's Undertower, where she waits next to the gate to the outer hallway."},
			["Meet Little Leaf at the Valley of Scars"] =
				{appendText=" to the north. Its river flows down from the secluded mountain valley past the Valley of Scars Wayshrine."},
			["Kill Runescriber Kulth"] =
				{appendText=", who endows their ink with nirncrux and carves runes directly into the trolls' flesh... a shaman like that is bound to have their own large house, likely guarded by the trolls."},
			["Kill Armorer Uthik"] =
				{appendText=", who imbues the troll armor with nircrux dust and forges magnificent works. There must be a huge forge somewhere, if it creates troll armor."},
			["Enter Exarch's Stronghold"] =
				{appendText=" in the far north of Upper Craglorn valley. In fact, it may be the northernmost place in Craglorn."},
			["Enter the Throne Room"] =
				{appendText=" of Braandoth the Ophidian Exarch of Undulating Destruction."},
			["Kill Exarch Braadoth and Kurzoth"] =
				{appendText=" within the Throne Room in the Exarch's Stronghold."},
			["Talk to Little Leaf Outside"] =
				{appendText=" the Exarch's Stronghold in the northernmost part of Upper Craglorn."},
		},
		[GetQuestName(5775)] = { -- "Holding Court"					-- Jordakai -- MartinToms
			["Talk to Regent Cassipia in Dragonstar"] =
				{appendText=", the northwestern settlement. If the Scaled Court is not welcome there, she may be outside the gates, perhaps at a farm."},
		},
		[GetQuestName(5194)] = { -- "Slithering Brood"				-- Jordakai -- MartinToms
			["Meet Regent Cassipia Near Dragonstar 1"] =
				{appendText=", the northeastern settlement. Thaenaneth said she would be at a farm.", stepTextKey="I should look for her near Dragonstar."},
			["Kill the Scorpion Matron"] =
				{appendText="."},
			["Destroy the Scorpion Nests"] =
				{appendText=".\nThe Matron very likely has her bone-filled nests near her.\n\nGiven where we met, the Fearfangs Cavern must be in the valley to the west of Dragonstar, as the town is north, and to the south there are only jagged mountains - hardly ideal breeding grounds."},
			["Talk to Cassipia"] =
				{appendText=" inside Fearfangs Cavern."},
			["Kill the Wamasu Eggbearer"] =
				{appendText="."},
			["Destroy the Wamasu Eggs"] =
				{appendText=".\nThey are surely near the Eggbearer.\n\nThe cave in this valley cannot be far. It is safe to say if I venture from Fearfangs Cavern to Dragonstar, I've gone too far... as that is where the Regent will wait for me to get the job done.\n\nWamasu eggs look like very large chaurus eggs, blue and round. As for the wamasu? Those heavyweights would be hard to overlook."},
			["Meet Regent Cassipia Near Dragonstar 2"] =
				{appendText=", most likely in the burned-down farmhouse near the wayshrine.", stepTextKey="I entered the wamasu den and slayed the wamasu eggbearer. I should find Regent Cassipia near the town of Dragonstar and let her know that I accomplished her task."},
			["Kill the Progenitor Mantikora"] =
				{appendText=", the creature that is capable of breeding, in Serpent's Nest east of Dragonstar."},
			["Set the Prisoners Free"] =
				{appendText=".\nMen and Mer are the final component in Mantikora creation..."},
			["Confront Regent Boward"] =
				{appendText=" in the Spawning Pools of Serpent's Lair."},
			["Meet Regent Cassipia Outside"] =
				{appendText=" of Serpent's Lair."},
		},
		[GetQuestName(5774)] = { -- "A Leaf in the Wind"			-- Jordakai
			["Talk to Little Leaf"] =
				{appendText=". She waits south of a merchant caravan in need of assistance, not far from the fortified passage gates."},
		},
		[GetQuestName(5771)] = { -- "Dawn of the Exalted Viper"		-- Jordakai -- MartinToms
			["Talk to Titus in Belkarth"] =
				{appendText=", where he 'paces like the great tiger he is.'"},
			["Enter the Howling Sepulchers"] =
				{appendText=" in the far north near the nirncrux mines. Titus, still outside the Observatory in Belkarth, may tell me the directions if I ask. It's going to be a long trek."},
			["Enter the Sanctum of Farsight"] =
				{appendText=" through the door just west of where we entered and then along the river. Titus knows the way."},
			["Activate the Ritual Fires"] =
				{appendText=" within the Sanctum of Farsight in The Howling Sepulchers."},
			["Observe the Farsight"] =
				{appendText=" within the Sanctum of Farsight in The Howling Sepulchers."},
			["Talk to the Thief 1"] =
				{appendText=" about the vision we saw within the Sanctum of Farsight in The Howling Sepulchers.", stepTextKey="The ritual worked. It showed us Regent Cassipia, the apparent source of the magical disturbance. She killed Kelmen when he tried to stop her. I should talk to the Thief and see what she has to say about all this."},
			["Enter Loth'Na Caverns"] =
				{appendText=" in the glade with cascading waterfalls, east of Dragonstar and beyond Crossroads Encampment. There are bound to be Scaled Court cultists there."},
			["Meet the Thief at the Top of the Rise"] =
				{appendText=" before the transformation."},
			["Enter Skyreach Temple"] =
				{appendText=" through the Loth'Na Caverns' Rise."},
			["Defeat the Exalted Viper"] =
				{appendText=" within the temple chambers past the Loth'Na Caverns' Rise and across the Aetherial bridge. I may have to kill Little Leaf as well."},
			["Return to the Star-Gazer's Observatory"] =
				{appendText=", either through the portal or other means."},
			["Talk to the Thief 2"] =
				{appendText=" on the upper floor of the Observatory", stepTextKey="Now that the Exalted Viper has been defeated and we're back in Belkarth, I should talk to the Thief."},
		},
		[GetQuestName(5258)] = { -- "The Time-Lost Warrior"			-- Jordakai -- MartinToms
			["Find Titus Valerius"] =
				{appendText=". Titus was very familiar with the Howling Sepulchers area. Perhaps his wife's grave is near there."},
			["Talk to Titus Valerius"] =
				{appendText=", kneeling at a gravesite with pink flowering trees, just a few paces southwest of the Howling Sepulchers."},
			["Talk to the Celestial Warrior"] =
				{appendText=" watching over Titus from a nearby boulder, just southwest of the Howling Sepulchers."},
			["Retrieve the Warrior's Blade"] =
				{appendText=" from the unworthy Orc whose camp is likely not far from Valley of Scars Wayshrine."},
			["Deliver War-Sworn to Titus Valerius"] =
				{appendText=". He stands at his wife's grave with the flowering trees near a small pond, southwest of the Howling Sepulchers."},
		},


-- 		=========================================================================
--		  Craglorn Side
-- 		=========================================================================
		[GetQuestName(5756)] = { -- "Critical Mass"					-- Jordakai -- MartinToms
			["Talk to Sara 1"] =
				{appendText=" Benele, a member of the Mages Guild near the destroyed village northeast of Spellscar.", stepTextKey="I should talk to Sara Benele to learn more about the Mage's Staff."},
			["Bring Storm, Fire, and Frost Infusions to Sara"] =
				{appendText=" after charging the Mage Crystal she gave me. With the different magicka infusions needed, I suspect that the shards may manifest differing displays of magicka. I should find her on the northeast side of the gigantic obelisk at Spellscar.\n\nThere are three gaps in the crater's ring. One north, one southwest, and one southeast. Perhaps I should seek shards in those places for infusions."},
			["Watch Sara Open the Mage's Staff"] =
				{appendText=" using the power of Storm, Fire, and Frost at a large smooth section on the northeast side of the gigantic obelisk at Spellscar."},
			["Enter the Staff"] =
				{appendText=" through the shining Portal to the Mage's Staff at the large smooth section on the gigantic obelisk's northeast side."},
			["Approach the Core"] =
				{appendText=". We will need to work together to traverse the floating islands - she with her magical talents and I with my ability to protect her as we go. I suspect there will be plenty of spellfiends and atronachs on the way."},
			["Protect Sara as She Stabilizes the Core"] =
				{appendText=". More powerful atronachs are likely to be near the dense sources of unstable magicka. Sara is an exceptional mage, summoning bridges to get us where we need to go."},
			["Talk to Sara 2"] =
				{appendText=" on the northeast side of the gigantic obelisk at Spellscar, where we entered the portal to the Mage's Staff."},
		},
		[GetQuestName(5750)] = { --"The Fallen City of Shada"					-- Octavare
		["Enter Shada's Tear"] =
			{appendText=". A supply tarp and scaffolding mark the way to enter the underground ruin at the bottom of a waterfall. I can use the ladder under a banner on the scaffolding, or I can jump into the water below. At the bottom there are dark Nedic doors that open into the ruin."},
		["Talk to Sali'ma 1"] =
			{appendText="|. He is inside the ruins, at the top entrance of the room where the ruin's water sources converge. \n\nA supply tarp and scaffolding mark the way to enter the underground ruin at the bottom of a waterfall.", stepTextKey="I should talk to the leader of the researchers, Sali'ma, about the strange things that have been happening in the ruins."},
		["Cleanse the Waters of the City Wing"] =
			{appendText=". I'll need to travel through the double doors located on the east side of the main chamber, just up a staircase. \n\nSali'ma indicated that some researchers hadn't returned. Perhaps if I locate one inside, they can help me progress through the wing. \n\nI'll need to defeat the Nereid at the end of the wing to cleanse the water. I can reconvene with Sali'ma through the doors at the other end of the wing. They will take me to the beginning of the wing so that I can head back to the main chamber. \n"},
		["Cleanse the Waters of the Crypt Wing"] =
			{appendText=". I'll need to travel through the double doors located on the west side of the main chamber, just up a staircase. \n\nA large barrier of poison mist blocks the path about halfway in. However, near the entrance of this wing, a mysterious man stands across from a sinkhole filled with contaminated water. Perhaps he can help me traverse the crypt wing. \n\nI'll need to defeat the Nereid at the end of the wing to cleanse the water. I can reconvene with Sali'ma through the doors at the other end of the wing. They will take me to the beginning of the wing so that I can head back to the main chamber. \n\nA supply tarp and scaffolding mark the way to enter the underground ruin at the bottom of a waterfall."},
		["Return to the Researchers"] =
			{appendText=". They are in the central section of the ruin, where both water sources converge into a large pool of water. \n\nA supply tarp and scaffolding mark the way to enter the underground ruin at the bottom of a waterfall."},
		["Talk to Sali'ma 2"] =
			{appendText=". He is located between two broken pillars, leaning over the chamber's main pool of water. It is the convergeance of both wings' water sources. \n\nA supply tarp and scaffolding mark the way to enter the underground ruin at the bottom of a waterfall.", stepTextKey="I should talk to Sali'ma about ending the corruption in Shada's Tear."},
		["Enter the Temple Wing of Shada's Tear"] =
			{appendText=". It can be accessed from the central section of the ruin, where both water sources converge into a large pool of water. I need to swim through the water to the staircase on the other side, and follow the stairs leading up to the large double doors. \n\nA supply tarp and scaffolding mark the way to enter the underground ruin at the bottom of a waterfall."},
		["Find Shada's Chambers"] =
			{appendText=". She is at the end of the Hall of Worship. It can be accessed from the central section of the ruin, where both water sources converge into a large pool of water. I need to swim through the water to the staircase on the other side, and follow the stairs leading up to the large double doors. \n\nA supply tarp and scaffolding mark the way to enter the underground ruin at the bottom of a waterfall."},
		["Defeat Shada"] =
			{appendText=". She is at the end of the Hall of Worship. It can be accessed from the central section of the ruin, where both water sources converge into a large pool of water. I need to swim through the water to the staircase on the other side, and follow the stairs leading up to the large double doors. \n\nA supply tarp and scaffolding mark the way to enter the underground ruin at the bottom of a waterfall."},
		["Talk to Sali'ma Back at Camp"] =
			{appendText=". There is a door behind where I defeated Shada that will quickly take me back to the beginning of the ruin. Sali'ma waits for me on the path between the two smaller bodies of water in the main room. \n\nAlternatively, if I left the area, I can return to the supply tarp and scaffolding that mark the way to enter the underground ruin at the bottom of a waterfall."},
	},
		[GetQuestName(5762)] = { --"The Reason We Fight"					-- Octavare
	[1] = 
		{appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the western doors. Within the Burial Grounds, ", stepTextKey="I should talk to Nhalan to learn more about him and the curse."},
		["Talk to Nhalan"] =
			{appendText=", a Nedic star priest. He stands with his staff near the entrance."},
	[2] = 
		{appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the western Burial Grounds. ", stepTextKey="Nhalan told me that he opposed the bargain the Nedes made with Shada and was punished for it. His spirit can't rest until Zal'ik, the general who made the deal with Shada, is slain. I should try to find Zal'ik."},
		["Watch Visions to Find Zal'ik"] =
			{appendText=". The visions are dispersed throughout the crypt wing of Shada's Tear."},
	[3] = 
		{appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the western Burial Grounds. ", stepTextKey="I saw a vision of Zal'ik creating a barrier in the crypt to keep the Yokudan invaders out. The barrier is defended by a flesh atronach. I should defeat the flesh atronach."},
		["Destroy the Abomination Protecting the Curse"] =
			{appendText=" in the northwestern chamber of the crypt wing."},
	[4] = 
		{appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the western Burial Grounds. ", stepTextKey="I defeated the flesh atronach that protected Zal'ik's barrier. I should speak to Nhalan before proceeding deeper into the Burial grounds."},
		["Talk to Nhalan 1"] =
			{appendText=". He waits for me on the first staircase in the crypt wing, holding a torch to get my attention.", stepTextKey="I defeated the flesh atronach that protected Zal'ik's barrier. I should speak to Nhalan before proceeding deeper into the Burial Grounds."},
	[5] = 
		{appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the western Burial Grounds. ", stepTextKey="Nhalan told me to find Zal'ik and defeat him in order to release Nhalan from his imprisonment."},
		["Find Zal'ik's Crypt"] =
			{appendText=". He can be found further along in the crypt wing, but I need to be wary of the moving barrier of poison mist."},
	[6] = 
		{appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the western Burial Grounds. ", stepTextKey="I found Zal'ik within the crypt. I should find a way to awaken Zal'ik and defeat him."},
		["Awaken and Defeat Zal'ik"] =
			{appendText=". He is in a large ceremonial room. His corpse sits on an altar in the center, and the perimeter is lined with soul shard chests. I will need to open all of the soul shard chests to awaken Zal'ik."},
	[7] = 
		{appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the western Burial Grounds. ", stepTextKey="I defeated Zal'ik. I should speak to Nhalan and determine if there is anything else I need to do."},
		["Talk to Nhalan 2"] =
			{appendText=" on the other side of the black double doors, in the ceremonial room of the crypt wing. This room can be identified by the many shallow graves of slain undead, and banners weathered by time. Once I exit this room, I will need to again circumvent the green cloud of poison mist. He waits for me at the end of this hallway at the staircase leading to the reservoir.", stepTextKey="I defeated Zal'ik. I should speak to Nhalan and determine if there is anything else I need to do."},
	[8] = 
		{appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. I entered the Crypt Wing through the western doors of the ruin's central chamber of pools. ", stepTextKey="Before he left, Nhalan gave me a book that he believes contains a way to reverse the effects of the water in its early stages. I should go back to the researchers' camp and see if anyone can use it to help the afflicted researchers."},
		["Bring Nhalan's Journal Back to Camp"] =
			{appendText=". The Khajiit researcher Tishi will likely take an interest in this journal. He is in the room before the central chamber containing the reservoir, next to a wooden cage containing an afflicted researcher. \n\nI need to defeat the nereid Emi'liah first, who hovers over the basin of contaminated water at the end of the crypt wing. After she is dealt with, I can exit through the pair of double doors left of the waterfall and up the stairs. I can then take a right to find the main room."},
	},
	[GetQuestName(5754)] = { --"Waters Run Foul"					-- Octavare
    [1] = 
        {appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the eastern doors into the City District and made my way to a large chamber with two pools. At an altar being used as a desk, up on the east end, I spoke with an injured Wood Elf researcher called Ralai. ", stepTextKey="I should read the scroll on the altar and use the prayer wheel to unlock the door deeper into the city wing."},
        ["Unlock the Door By Completing the Puzzle"] =
            {appendText=". Ralai may have an idea on how to dispel the ward on the Nedic doors south of this large northern chamber."},
        [2] = 
            {appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the eastern City District. ", stepTextKey="I unlocked the door. I should follow Ralai deeper into the city wing to find Nahlia."},
        ["Follow Ralai into the Chambers"] =
            {appendText=". She went south through the double doors that were warded."},
        [3] = 
            {appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the eastern City District and then the Inner City south of the first chamber. Now ", stepTextKey="I need to find the mad researchers so I can save Nahlia."},
        ["Find Researcher Klause"] =
            {appendText=". He is in the first room off of the main hallway, in the city wing's southwest.\n"},
        ["Find Researcher Squan"] =
            {appendText=". He is in the second room off of the main hallway, in the city wing's south.\n"},
        ["Find Researcher Zifri"] =
            {appendText=". She is in the third room off of the main hallway, in the city wing's southeast."},
        [4] = 
            {appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the eastern City District and dealt with the three former researchers. Now ", stepTextKey="I should find Nahlia and free her."},
        ["Find Nahlia and Free Her"] =
            {appendText=". She is likely in a place with Nedic wheel locks binding her, perhaps the eastern chamber with the small, rectangular pool. Like those first warded doors, I should look for clues about the correct sequence to use."},
        [5] = 
            {appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the eastern City District. ", stepTextKey="I freed Nahlia. I should talk to her and see what she learned about the mad researchers."},
        ["Talk to Nahlia"] =
            {appendText=". She is in the eastern chamber with the rectangular pool of foul water where she was previously bound."},
        [6] = 
            {appendStepText="A supply tarp and scaffolding mark the way to enter the underground ruins at the bottom of a waterfall. From Shada's Tear's large chamber of pools, I entered the eastern City District. In the eastern chamber with the small, rectangular pool, ", stepTextKey="I freed Nahlia. Ralai has joined us. I should talk to her."},
        ["Talk to Ralai"] =
            {appendText="."},
    },
[GetQuestName(5749)] = { --"The Seeker's Archive"					-- Jordakai -- MartinToms
        ["Activate Northeastern Beam"] =
            {appendText="."},
        ["Activate Northwestern Beam"] =
            {appendText="."},
        ["Activate Southwestern Beam"] =
            {appendText=".\n\nThe temple ruins with the beams is northwest of Belkarth. The beams will likely involve mounted crystals on raised platforms. Ibrula mentioned the presence of Anka-Ra soldiers impeding her journey. She seems well versed in the history of this place."},
        ["Enter the Temple"] =
            {appendText=" down the stairs at the base of the receiving crystal's structure. There is a book on a pedestal, but it is unreadable. The archive's ancient door retains its beauty."},
        ["Talk to Ibrula 1"] =
            {appendText=" just inside the archive's entrance.", stepTextKey="I entered the temple. Ibrula wishes to speak to me. I should hear what she has to say."},
        ["Reach Hermaeus Mora's Shrine"] =
            {appendText=" in the deepest part of the archive. Since the Anka-Ra sealed the entry, it is doubtful the place is abandoned."},
        ["Talk to Hermaeus Mora's Statue"] =
            {appendText=" at his shrine in the depths below the archives."},
        ["Talk to Ibrula 2"] =
            {appendText=" at Hermaeus Mora's shrine in the depths below the archives.", stepTextKey="Hermaeus Mora revealed secret information concerning the origins of the Anka-Ra, but he refuses to reveal more unless I bring him an offering. I should ask Ibrula what he means."},
    },
[GetQuestName(5755)] = { --"Supreme Power"					-- Octavare
[1] = 
{appendStepText="", stepTextKey="I should enter the Elinhir sewers and find Minerva Lauzon."},
["Enter the Elinhir Sewerworks"] =
{appendText=". The entrance to the sewers can be found by following the stream in the front of the city up to the walls of the city's upper level. The remains of a broken bridge can be seen in the water."},
[2] = 
{appendStepText="", stepTextKey="I entered the sewers. Now I should find Minerva Lauzon."},
["Find Minerva"] =
{appendText=", who is in the Elinhir Sewerworks. The entrance to the sewers can be found by following the reservoir in the front of the city up to the walls of the city's upper level. The remains of a broken bridge can be seen in the water.\n\nMinerva is likely hiding deeper in the sewers with the rest of the city's survivors. I should check the sewers thoroughly."},
[3] = 
{appendStepText="", stepTextKey="I found Minerva Lauzon. Now I should talk to her."},
["Talk to Minerva 1"] =
{appendText=" in the Elinhir Sewerworks. The entrance to the sewers can be found by following the stream in front of the city up to the walls of the city's upper level. The remains of a broken bridge can be seen in the water.\n\nMinerva is with the rest of the city's survivors, hiding within the sewers. She is in the room to the northwest.", stepTextKey="I found Minerva Lauzon. Now I should talk to her."},
[4] = 
{appendStepText="", stepTextKey="Minerva told me that Arch-Mage Yamanu-ko is responsible for the devastation in Elinhir. She is in the Apex Tower, being warded by her apprentices in the surrounding towers. I should go to the towers and destroy the wards."},
["Exit Elinhir Sewerworks"] =
{appendText=". I should exit from the ladder in the room with Minerva and the rest of the survivors.\n\nThe survivors are in the northwest room in Elinhir Sewerworks. The entrance to the sewers can be found by following the stream in front of the city up to the walls of the city's upper level. The remains of a broken bridge can be seen in the water."},
[5] = 
{appendStepText="", stepTextKey="I need to destroy the wards protecting the Apex Tower."},
["Destroy West Tower Magic Focus"] =
{appendText=". The focuses can be found within the two towers of Elinhir, which can be identified by their height and large doorways, engraved with a skull and snakes.\n\nThe focuses are atop stone altars on the top floor of each tower."},
["Destroy East Tower Magic Focus"] =
{appendText=". The focuses can be found within the two towers of Elinhir, which can be identified by their height and large doorways, engraved with a skull and snakes.\n\nThe focuses are atop stone altars on the top floor of each tower.\n\nThe second floor of the eastern tower contains a puzzle that can be activated by touching the guide projector, found on a pedestal next to the bookshelf left of the entrance."},
[6] = 
{appendStepText="", stepTextKey="I destroyed the wards. I should meet Minerva at the base of the Apex Tower and talk to her."},
["Talk to Minerva 2"] =
{appendText=". She is near the entrance to the Apex Tower Courtyard, which can be found by climbing a series of staircases in the southernmost part of the city.", stepTextKey="I destroyed the wards. I should meet Minerva at the base of the Apex Tower and talk to her."},
[7] = 
{appendStepText="", stepTextKey="I made it to the base of the Apex Tower. I should wait while Minerva dispels the ward."},
["Watch Minerva Dispel Ward"] =
{appendText=". She is near the entrance to the Apex Tower Courtyard, which can be found by climbing a series of staircases in the southernmost part of the city. The tower's door is warded by a pink, circular barrier."},
[8] = 
{appendStepText="", stepTextKey="The ward has been taken care of. Now I should enter the Apex Tower and locate Yamanu-ko."},
["Enter the Apex Tower"] =
{appendText=". The Apex Tower Courtyard can be found by climbing a series of staircases in the southernmost part of the city. Once inside, follow the stone path to the tower proper."},
[9] = 
{appendStepText="", stepTextKey="I should defeat Yamanu-ko and end the threat to Elinhir."},
["Defeat Yamanu-ko"] =
{appendText=". He is inside Apex Tower, accessed via the Apex Tower Courtyard. It can be found by climbing a series of staircases in the southernmost part of the city. Once inside, follow the stone path to the tower proper."},
[10] = 
{appendStepText="", stepTextKey="I defeated Yamanu-ko. I should tell Minerva what happened."},
["Talk to Minerva 3"] =
{appendText=". She is in the lowest chamber of the Apex Tower, accessed via the Apex Tower Courtyard. It can be found by climbing a series of staircases in the southernmost part of the city. Once inside, follow the stone path to the tower proper.", stepTextKey="I defeated Yamanu-ko. I should tell Minerva what happened."},
},

[GetQuestName(5751)] = { --"The Trials of Rahni'Za"						-- JayAstrophel
        ["Light the Braziers of Rahni'Za"] =
            {appendText="\nFada at-Glina, a Redguard near a campfire at the north entrance of the path leading to the school, has information on the first trial. A light blue mist marks the place to summon the flame. From there, seek statues along the path with swords raised and unlit braziers before them.\n"},
        ["Defeat Kalith, the Champion of the Trial of Fire"] =
            {appendText=". He prepares to face you near the end of the winding path leading up to the school. Three blue flames in tall braziers flicker above him.\n"},
        ["Enter the School of Rahni'Za"] =
            {appendText=" through the door at the very top of the path leading up to the school. Fire Master Lan'ah, a golden spirit, guards the way.\n"},
        ["Talk to Zabeth"] =
            {appendText=" on the far end of the tunnel that leads into Rahni'za. He can be found kneeling on the ground.\n"},
        ["Complete the Trial of the Arena"] =
            {appendText=". Seek a large, open circle of sand within the school, stained with blood and framed by wooden fencing. Speak with Master Nadar there to begin.\n"},
        ["Complete the Trial of Air"] =
            {appendText=". The starting point is on the northwest side of the school's grounds, at the end of a path up a small hill. Lion statues will help guide your way along this trial.\n"},
        ["Complete the Trial of Martial Knowledge"] =
            {appendText=".\n\nOne book can be found during the Trial of Air, guarded by Birdmaster Dehanar on the north side of the school grounds.\n\nThe second book can be found on the roof of the barracks, a building on the west side of the school's courtyard. Just to the south, large wooden posts of varying heights stick out of a patch of sand.\n\nThe third book is within the armory, a building east of the barracks on the other side of the courtyard. Search the armory's first floor for this book.\n\nThe final book is found within the beast pits, an underground section of the school. The entrance is to the far east of the school grounds, just past the arena. Once within, you'll find the book in the largest chamber near the foe Wapzgin, lit by a half-buried lantern.\n\nOnce all of the books are found, they must be placed within the library, the large building on the northeast of the school grounds. Once inside, place the books on empty pedestals lit by blue flames, near a door encrusted with ice. Once the books are placed, head through the door near the books.\n\nZabeth, the spirit kneeling on the far end of the tunnel that leads into Rahni'za, may have more information about all three trials.\n"},
        ["Complete the Trial of the True Path"] =
            {appendText=", found by descending through the trapdoor at the far end of the school's library. The library itself is within the school grounds, on the northeast side.\n\nOnce within, touch the orb of light, and do not stray into the darkness.\n"},
        ["Talk to Master Timen"] =
            {appendText=" just within the school, at the far end of the tunnel that leads into Rahni'za. The blue spirit stands next to Zabeth.\n"},
        ["Return to Fada Outside Rahni'Za"] =
            {appendText=". She rests near a campfire at the north end of the path leading to the school.\n"},
    },
[GetQuestName(5757)] = { --"Gem of the Stars"					-- Jordakai
        ["Take Gem to Hermaeus Mora"] =
            {appendText="'s summoning pedestal with the open book. It is above the ancient entry to the archives. There is something etched on the blackened gem that I cannot read. Perhaps this will be a worthy offering."},
    },
 [GetQuestName(5759)] = { --"Message Unknown"					-- Jordakai
        ["Bring Rubbing to Hermaeus Mora"] =
            {appendText="'s summoning pedestal with the open book. It is above the entrance to The Seeker's Archive. The carved stone seems ancient, but what is its meaning?"},
    },
[GetQuestName(5758)] = { --"Strange Lexicon"					-- Jordakai
        ["Bring Lexicon to Hermaeus Mora"] =
            {appendText="'s summoning pedestal with its opened book, just above the ancient archive's entry. This Dwemeri tablet should be of great interest."},
    },


-- 		=========================================================================
--		  Craglorn Dailies
-- 		=========================================================================
		[GetQuestName(5767)] = { -- "The Blood of Nirn"				-- Octavare
			["Enter Skyreach Hold"] =
				{appendText=". The entrance is a large black door, engraved with a skull and snakes. It can be found across the bridge east of the Skyreach Wayshrine."},
			["Explore Skyreach Hold"] =
				{appendText=". The entrance is a large black door, engraved with a skull and snakes. It can be found across the bridge east of the Skyreach Wayshrine. \n\nI need to make my way through Skyreach Pass at the far end of the first chamber. The door leading to the pass has an identical design as the entrance to the ruins. Then I can proceed through the rest of the ruins."},
			["Defeat Exarch Arnoth"] =
				{appendText=". He is at the very end of the ruins.\n\nThe entrance is a large black door, engraved with a skull and snakes. It can be found across the bridge east of the Skyreach Wayshrine. \n\nI need to make my way through Skyreach Pass at the far end of the first chamber. The door leading to the pass has an identical design as the entrance to the ruins. Then I can proceed through the rest of the ruins."},
			["Leave Skyreach Hold"] =
				{appendText=" and head to Dragonstar, in the far northwest of Craglorn."},
			["Talk to Nendirume in Dragonstar"] =
				{appendText=" in northwest Craglorn. She can be found in front of a shed left of the entrance to the nearby nirncrux mine, north of The Cracked Anvil."},
		},
		[GetQuestName(5777)] = { -- "The Gray Passage"				-- cyberjanet -- MartinToms
			["Visit the Gray Menhir"] =
			{appendText=" after reading the old book on the balcony of the Pub. The Menhir is west of the Dragonstar Wayshrine.  There is a little fenced off field with goats in it. Take the road past the field and follow it till you get to an obelisk on top of a rocky mound, to the left after you pass some stairs. Search for a little shrine covered in flowers.\n\n"},
			["Complete the Pilgrimage"] =
			{appendText="\nYour starting point is the Grey Menhir, west of the Dragonstar Wayshrine, past the field of goats and along the road until just past some stone stairs. A flower-covered shrine is set against an obelisk on top of a rocky mound.\n\nFrom the shrine, you can see the stairs leading into Fearfangs Cavern, your first objective. When you enter, there is a large bookcase in front of you. Take the right-hand exit and follow the rooms until you get to one with large statues of snakes coiled around pillars. The shrine is covered in flowers, just like the one at the obelisk. It is against the wall in a recess between two bookshelves.\n\nLeave Fearfangs Cavern, and head back toward Dragonstar. Continue on the road past a farmstead, a broken wagon, another farmstead, and the Crossroads Encampment until you see a waterfall. Just before the waterfall, turn away from the water onto a short path leading to the door of The Serpent's Nest. Follow the rocky tunnel, across a pool of water, until it opens into a larger cavern. The shrine is under a rocky overhang near the far exit.\n\nExit the Serpent's nest and go back to the main road. Continue left, past the waterfall. Follow the road across two bridges, turn left and follow the water to the wooden ramp leading to Loth'Na Caverns. A short rocky tunnel leads into a wide open area. Cross the wooden bridge, bear right, and continue on, keeping the large rocky wall to your right. Take the turnoff that leads to a wooden structure and continue uphill. Just past the tree stump is a rocky bridge leading to the shrine.\n\nLeave Loth'Na and head for the main road. Cross a well-made bridge and continue on the road past a defunct Nirncrux Mine. Don't cross the wooden bridge when you get there, turn left and follow the water under skeletons hanging from ropes. The path leads to an area where Iron Orcs are mining nirncrux. Take the stone stairs next to the wooden ramp and continue up more stone stairs to find Exarch's Stronghold.\n\nYou enter a large room with a door at the far end. Go through the door onto a stone bridge, leading to another door into a tunnel with a tusked arch opening into a large room. Take the squared arch exit to the left and follow the tunnel to the wooden door, which leads into a large underground cavern. Turn right immediately and make your way through the rocks to the shrine.\n\nLeave the Exarch's Stronghold and make your way down the stone stairs and waterway back to the main road. The Valley of the Scars Wayshrine is visible. Follow the road past it and take the turnoff after the wagon accident, which leads to a tower. Use the hatch to enter Ulthag's Undertower, then take the ladder in the middle of the wooden ramp bridge to get downstairs.\n\nIn the room below, take the exit just beyond the cages and then go through a narrow opening in a wooden palisade. Take the stairs leading up into a bar area. The only exit has a small stairway just beyond it; the shrine is on the landing at the top of the stairs.\n\nAfter leaving the tower, head back toward the Valley of the Scars Wayshrine and take the road by the broken tower. It goes uphill between many rocks, broken buildings, and monoliths, as well as two broken archways. Continue on until you see a tree growing out of a rock next to a turnoff. Take that turnoff to reach The Howling Sepulchers.\n\nTurn left as soon as you enter and follow the short path to a door. Cross the water to the path next to the waterfall, across some rocks, to find the shrine hidden in a recess."},
			["Return to the Gray Menhir 1"] =
			{appendText=". Exit the tower and use the nearby wayshrine to travel to Dragonstar. Run past the field with the goats, stay on the road till you pass the stairs, and look for the obelisk with its shrine.", stepTextKey="I completed Ranev's pilgrimage. I should return to the Gray Menhir to see if I have found favor with the Stars."},
			["Return to the Gray Menhir 2"] =
			{appendText=" west of the Dragonstar wayshrine, past the field of goats and along the road until just past some stone stairs.", stepTextKey="I completed Ranev's pilgrimage. I should return to the Gray Menhir to see if I have found favor with the Stars."},
			["Return to the Gray Menhir 3"] =
			{appendText=" in the extreme northwest of Craglorn, between The Sunken Lair and Fearfangs Delve.", stepTextKey="I completed Ranev's pilgrimage. I should return to the Gray Menhir to see if I have found favor with the Stars."},
		},
		[GetQuestName(5766)] = { -- "Iron and Scales"				-- Jordakai -- MartinToms
			["Burn the Northern Standard"] =
				{appendText="."},
			["Burn the Southern Standard"] =
				{appendText="."},
			["Burn the Western Standard"] =
				{appendText=".\n\nI should travel north along the river, from where I found Lashburr, to reach the Valley of Scars fortress in Upper Craglorn's central north. The tall banners display a serpent, standing in makeshift ritual sites."},
			["Slay Agganor and Take His Helmet"] =
				{appendText=". The usurper is probably inside the Valley of Scars' stronghold, carved into the northernmost mountains overlooking Upper Craglorn's central river valley."},
			["Mount Agganor's Helmet On a Pike"] =
				{appendText=" on top of the stone watchtower in the river south of this north-central fortress' massive entry gates. It stands northwest of the Valley of Scars Wayshrine."},
			["Return to Lashburr Tooth-Breaker"] =
				{appendText=", resting by his campfire near the wooden bridge over the river flowing from the Valley of Scars' fortress, west of the wayshrine."},
		},
		[GetQuestName(5770)] = { -- "Souls of the Betrayed"			-- Jordakai -- MartinToms
			["Enter Skyreach Catacombs"] =
				{appendText=" in Upper Craglorn. Although the main entrance to the catacombs was sealed long ago, the Scaled Court tunneled an entrance near the Crusader. Given the stories of a powerful necromancer, there will likely be many undead within."},
			["Open the Way to the Lower Catacombs"] =
				{appendText=". Its entrance is east of the catacomb's tunnel entrance, across a chamber with a living tree, yet it is sealed by some necromantic power. Perhaps defeating the undead, especially the most powerful ones in this upper area, may provide the power to counter the dark magic ward. If one door is warded, perhaps others will have wards, too.\n\nThe Crusader spoke of Nedic kings and others betrayed within the chambers of this ancient complex. I suspect I will soon learn what remains of them."},
			["Enter the Lower Catacombs"] =
				{appendText=" through the door east of the living tree in the upper catacombs. With what I encountered in this upper area, there will undoubtedly be many challenges ahead."},
			["Find Virmaril the Betrayer"] =
				{appendText=" within the Lower Catacombs through the door opposite the entrance in the western part of the Upper Catacombs.\n\nThe layout has been straightforward so far, I am probably looking for another tomb door. Perhaps a prison even? Surely a necromancer of this power would have left this watery grave if he could... unless it is a prison."},
			["Remove the Soul Ward"] =
				{appendText=".\n\nWithin these Lower Catacombs, I have passed many undead and lost souls. Now there is a chamber with purple crystal sconces. The crystals look like soul gems."},
			["Defeat Virmaril the Betrayer"] =
				{appendText=", former friend and later traitor to High King Durac of Skyreach. No longer just an Elven necromancer, he reigns constrained in a unique prison within the depths of the Lower Catacombs."},
			["Exit Skyreach Catacombs"] =
				{appendText=" using the northwestern passageway leading out of Virmaril's Seat of the Betrayer in the Lower Catacombs."},
			["Talk to Crusader Dalamar"] =
				{appendText=". The Knight of the Eight may still be praying to the Aedric gods at the altar north of the catacombs' entrance."},
		},
		[GetQuestName(5174)] = { -- "Taken Alive"					-- Jordakai -- MartinToms
			["Find the Caravan Guards"] =
				{appendText=" along the river through the central northern valley of Upper Craglorn. I should watch for signs of the caravan, like supplies or carts, to help me find them. I hope they are still alive."},
			["Defeat Gulzog the Butcher"] =
				{appendText=". Hjargredda, a surviving guard standing near some stolen carts, pointed me south, farther up the trail and past the blacksmiths, into the stronghold's southwestern area."},
			["Search Remains for Personal Effects"] =
				{appendText=". A stack of skulls tops a large pile of remains in the feeding area where I killed Gulzog and his troll in the southwestern part of the stronghold."},
			["Return to Scattered-Leaves"] =
				{appendText=", who waits at the ransacked caravan along the road northeast of the Valley of Scars Wayshrine."},
		},
		[GetQuestName(5764)] = { -- "The Truer Fangs"				-- Jordakai -- MartinToms
			["Kill Raziyya"] =
				{appendText=" at an ancient Nedic ritual site high atop a ridge at the end of a winding trail that begins near a bridge over a river. It is southwest of the broken bridge in the sky and south of where the Ancients are buried."},
			["Kill Anyaq"] =
				{appendText=", who is animating an atronach at an abandoned dolmen in a meadow northeast of a wooden bridge and a ransacked merchant caravan."},
			["Kill Mazaluhad"] =
				{appendText=", who may be meeting a member of the Scaled Court among a few Nedic columns in a secluded spot where the central valley's river drops to a lake far below.\n\nAll three are to the east of Dragonstar in the Upper Craglorn region."},
			["Talk to Safa al-Satakalaam"] =
				{appendText=" inside the Caravan Company Depot."},
		},
		[GetQuestName(5772)] = { -- "Uncaged"						-- Octavare
			["Enter Skyreach Pinnacle"] =
				{appendText=". The entrance to the ruins is a large door engraved with a skull and snakes."},
			["Clear the Way for Mederic Vyger"] =
				{appendText=" inside the ruins. The entrance to the ruins is a large door engraved with a skull and snakes."},
			["Defend Mederic Vyger"] =
				{appendText=". He is deep inside the ruins, standing at a celestial ward. I need to touch the ward to begin the process. After each corner is dealt with, I will need to touch the ward again to start the next corner.\n\nThe entrance to the ruins is a large door engraved with a skull and snakes."},
			["Defeat Aetherion"] =
				{appendText=". He is deep inside the ruins, in the main room that houses the celestial ward. \n\nThe entrance to the ruins is a large door engraved with a skull and snakes."},
			["Exit Skyreach Pinnacle"] =
				{appendText="."},
			["Talk to Mederic Vyger"] =
				{appendText=". Mederic can be found outside of the entrance to Skyreach Pinnacle, beside the bridge, next to a wooden wagon and crate."},
		},

