[GetQuestName(5483)] = { --"The Imperial Standard"			--Aashiana
        [1] = 
            {appendStepText="In the Imperial City, ", stepTextKey="The scout urged me to head to the garrison at the center of the Nobles District. Once inside, I should seek out Captain Caudex to learn how they have resisted the Daedric onslaught for so long."},
        ["Talk to Captain Caudex 1"] =
            {appendText=" within the central garrison. The entrance is across from the Nobles District flag. The Captain is overlooking the field from his base on the second floor.", stepTextKey="The scout urged me to head to the garrison at the center of the Nobles District. Once inside, I should seek out Captain Caudex to learn how they have resisted the Daedric onslaught for so long."},
        [2] = 
            {appendStepText="In the Nobles District of the Imperial City, ", stepTextKey="Daedra will soon assault the doors of the garrison. I must defend the doors from all attackers."},
        ["Defend the North Door"] =
            {appendText=" against several waves of Legion Zero soldiers and Daedra, with the help of Dulcilla Iullus, one of the Commander's soldiers."},
        ["Defend the West Door"] =
            {appendText=" against several waves of Legion Zero soldiers and Daedra, with the help of Statius Vettiena, one of the Commander's soldiers."},
        ["Defend the South Door"] =
            {appendText=" against several waves of Legion Zero soldiers and Daedra, with the help of Justianas Gratus, one of the Commander's soldiers."},
        [3] = 
            {appendStepText="In the Nobles District of the Imperial City, ", stepTextKey="We've pushed back the Daedric invaders assaulting the garrison. Now that I've proven myself an ally, Captain Caudex may tell me more about how he and his soldiers have held out for so long."},
        ["Talk to Captain Caudex 2"] =
            {appendText=" on the second floor of the Improvised Garrison in the center of the Nobles District.", stepTextKey="We've pushed back the Daedric invaders assaulting the garrison. Now that I've proven myself an ally, Captain Caudex may tell me more about how he and his soldiers have held out for so long."},
        [4] = 
            {appendStepText="In the Nobles District of the Imperial City, in a makeshift garrison in the center of the district, ", stepTextKey="Captain Caudex gave me an ancient scroll. According to him, it has the power to make people immortal and may even bestow prophetic dreams. He had a dream that I would deliver this scroll to the Drake of Blades."},
        ["Talk to the Drake of Blades"] =
            {appendText=" back in my Alliance base in the sewers and bring her the scroll Captain Caudex gave me. Entrances to the sewers can be found along the outer wall of each City District"},
    },

[GetQuestName(5480)] = { --"The Bleeding Temple"			--Aashiana
        [1] = 
            {appendStepText="In my Alliance base in the Temple District of the Imperial City, ", stepTextKey="The Drake of Blades told me that Egnatius is likely being held prisoner near one of the Temple District's shrines. I should proceed to these shrines and free any captives I find. One of them may be the priest we seek."},
        ["Free the Clergy near the Shrine of Mara"] =
            {appendText=", in the northwest corner of the District."},
        ["Free the Clergy near the Shrine of Dibella"] =
            {appendText=", in the southwest corner of the District."},
        ["Free the Clergy near the Shrine of Julianos"] =
            {appendText=", in the northeast corner of the District."},
        [2] = 
            {appendStepText="In the Temple District of the Imperial City, ", stepTextKey="I freed several priests from the Daedra, but Engatius was not among them. One of the priests indicated that the Daedra took Egnatius to the Temple of the One. I should reunite with the Drake of Blades and tell her what I've learned."},
        ["Talk to the Drake of Blades 1"] =
            {appendText=" in the Bleeding Temple Rectory, in the southeast area of the district, next to an empty building.", stepTextKey="I freed several priests from the Daedra, but Engatius was not among them. One of the priests indicated that the Daedra took Egnatius to the Temple of the One. I should reunite with the Drake of Blades and tell her what I've learned."},
        [3] = 
            {appendStepText="In the Temple District of the Imperial City, ", stepTextKey="The Drake of Blades told me that we must attack the Temple of the One now to prevent Egnatius from being killed. I should make my way there and rescue him from his Daedric captors."},
        ["Defeat Molag Bal's Temple Forces"] =
            {appendText=" at the Temple of the One in the center of the district. Gathering some allies may be helpful in overcoming Molag Bal's forces."},
        [4] = 
            {appendStepText="In the Temple District of the Imperial City, ", stepTextKey="Egnatius appears to have escaped the Temple of the One alive. I should track him down in the southwest corner of the district and speak to him, underground in a hideout reached by climbing down a well."},
        ["Talk to Egnatius"] =
            {appendText="."},
        [5] = 
            {appendStepText="In his hideout in the Temple District of the Imperial City, ", stepTextKey="Egnatius informed me that Molag Bal's servants are looking for information on a scroll he found just prior to the invasion. A scroll that only he can read. I should tell the Drake of Blades what I learned."},
        ["Talk to the Drake of Blades 2"] =
            {appendText=", back in the central Alliance Base in the sewers. Entrances to the sewers can be found along the outer wall of each District.", stepTextKey="Egnatius informed me that Molag Bal's servants are looking for information on a scroll he found just prior to the invasion. A scroll that only he can read. I should tell the Drake of Blades what I learned."},
    },

[GetQuestName(5477)] = { --"The Watcher in the Walls"			--Aashiana
        [1] = 
            {appendStepText="In the Arena District, ", stepTextKey="I must travel to the Imperial Arena, enter the Daedra's bloody martial contest, and defeat all comers."},
        ["Defeat All Daedra in the Arena"] =
            {appendText=". The arena is within the massive circular structure in the center of the Arena District.\n\nI may require the aid of my fellow Alliance members, as these Daedric champions are bound to be the best of the best."},
        [2] = 
            {appendStepText="In the Imperial City, ", stepTextKey="I've slaughtered all Daedra in the Imperial Arena. Perhaps this will catch The Rat's attention. I should wait to be contacted."},
        ["Wait for The Rat to Contact You"] =
            {appendText=". After the battle, I hear a whisper at a door in the back of the Arena."},
        [3] = 
            {appendStepText="In the Imperial City, ", stepTextKey="After I slaughtered the Daedra in the Imperial Arena, a threadbare figure appeared outside the arena and called to me.\n\nThis may be The Rat. I should follow him."},
        ["Find The Rat's Hideout"] =
            {appendText=", beyond the door to the Arena Storage Room, through a large trapdoor."},
        [4] = 
            {appendStepText="In the Imperial City, ", stepTextKey="I've discovered The Rat's hideout, a small room beneath the Imperial Arena. I should see what he has to say about Molag Bal's plans for Imperial City."},
        ["Talk to The Rat"] =
            {appendText=". He has learned more about the true purpose of the Daedric incursion than all the Alliance forces put together, it seems."},
        [5] = 
            {appendStepText="In his hideout underneath the Imperial Arena, ", stepTextKey="The Rat told me that Molag Bal somehow plans to \"erase\" the Dragonfires, which prevent Daedric invasions so long as an emperor descended from Saint Alessia holds the throne. He suggested I bring this news to the Drake of Blades in the sewers."},
        ["Talk to the Drake of Blades"] =
            {appendText=", waiting in the center of my Alliance base in the Imperial City sewers for some actionable information. Entrances to the sewers can be found along the outer walls of each City District."},
    },

[GetQuestName(5473)] = { --"Of Brands and Bones"			--Aashiana
		[1] = 
			{appendStepText="In the Memorial District of the Imperial City, ", stepTextKey="I must kill Worm Cultists to find a Daedric Brand and a key to the chapel."},
		["Collect the Chapel Key"] =
			{appendText=", by killing Worm Cultists anywhere in the district and looting their possessions. The larger Daedra overseeing operations are more likely to have the keys."},
		["Collect a Daedric Brand"] =
			{appendText=", by killing Worm Cultists."},
		[2] = 
			{appendStepText="In the Memorial District in the Imperial City, ", stepTextKey="I should enter the chapel to use the Daedric Brand and discover what the Worm Cult is doing with the exhumed skeletons."},
		["Go to the Chapel"] =
			{appendText=" on the south side of the main western road. The doorway is marked by large rocky Daedric spikes."},
		[3] = 
			{appendStepText="", stepTextKey="Now that I have a Daedric Brand and access to the chapel, I must brand a skeleton. The skeleton should recite its orders, revealing why it is digging in the Memorial District and what it hopes to find."},
		["Brand a Skeleton to Hear Its Confession"] =
			{appendText=". Some piles of bones in front of the altar may provide what I need."},
		[4] = 
			{appendStepText="I dug up my own skeleton in the defiled Chapel of Arkay. ", stepTextKey="The Worm Cult has been using the exhumed skeletons to excavate something called the Dragonfire Cathedral. I should meet up with the Drake of Blades in the Undertaker's Office to plan our next move."},
		["Meet the Drake in the Undertaker's Office"] =
			{appendText=". The entrance is in the outer wall of the northwest Memorial District, flanked by two coffin lids carved with swords."},
		[5] = 
			{appendStepText="Inside the Undertaker's Office in the northwest wall of the Memorial District, ", stepTextKey="I should tell the Drake of Blades about what I discovered in the chapel."},
		["Talk to the Drake of Blades 1"] =
			{appendText=" about what the skeleton I dug up told me.", stepTextKey="I should tell the Drake of Blades about what I discovered in the chapel."},
		[6] = 
			{appendStepText="", stepTextKey="The map that the Drake of Blades found indicates that the Worm Cult's skeletal minions are digging beneath the crematorium. I should collect concentrated kindlepitch from Xivkyn Soulbranders. I may be able to cause a cave in with the right amount."},
		["Collect Concentrated Kindlepitch"] =
			{appendText=" \n\nXivkyn Soulbranders appear to be supervising and are generally taller than the other Daedra. They can be found in any area of the Memorial District."},
		[7] = 
			{appendStepText="", stepTextKey="I've acquired the concentrated kindlepitch. I should make my way to the crematorium to meet up with the Drake of Blades."},
		["Meet the Drake in the Crematorium"] =
			{appendText=" on the main eastern road. The doorway is on the south side marked by large rocky Daedric spikes."},
		[8] = 
			{appendStepText="Inside the Crematorium, ", stepTextKey="I must use the concentrated kindlepitch to destroy the Worm Cult's secret dig site. This should cripple their attempt to find the Dragonfire Cathedral."},
		["Destroy the Secret Dig Site"] =
			{appendText=", by placing the kindlepitch near the wooden doorway to a newly discovered mineshaft in the center of the Crematorium."},
		[9] = 
			{appendStepText="Within the Crematorium on the east side of the Memorial District, ", stepTextKey="I've destroyed the site where Molag Bal's skeletons were searching for something called the \"Dragonfire Cathedral.\" Their digging operation is crippled. I should return to the alliance base and speak with the Drake of Blades about our next move."},
		["Talk to the Drake of Blades 2"] =
			{appendText=" in the central area of my Alliance base in the Imperial City sewers. Entrances to the Imperial City Sewers can be found along the outer walls of each City District.", stepTextKey="I've destroyed the site where Molag Bal's skeletons were searching for something called the \"Dragonfire Cathedral.\" Their digging operation is crippled. I should return to the alliance base and speak with the Drake of Blades about our next move."},
	},

[GetQuestName(5489)] = { --"The Lock and the Legion"			--Aashiana
        [1] = 
            {appendStepText="In the Imperial City, the Drake of Blades said ", stepTextKey="I should draw the Dragonguard Seal on a wall in the Elven Gardens District. This should alert the Drake of Blades' contact, and draw him to the meet."},
        ["Draw the Dragonguard Seal"] =
            {appendText=" on a wall in the very center of the district, where it is sure to attract attention."},
        [2] = 
            {appendStepText="In the Elven Gardens District of the Imperial City, ", stepTextKey="I should speak with Captain Regilus, the Drake's contact in Legion Zero."},
        ["Meet with Captain Regilus"] =
            {appendText=" in his hideout directly underneath the Elven Gardens district flag - a bold choice of location indeed."},
        [3] = 
            {appendStepText="In the Elven Gardens District of the Imperial City, ", stepTextKey="I need to find some scrap metal to make the false key. Any Legionary or Xivkyn might have some."},
        ["Collect Scrap Metal"] =
            {appendText=" \n\nThe metal can be used to forge a key to steal the relic the Daedra have found."},
        [4] = 
            {appendStepText="In the Elven Gardens District of the Imperial City, ", stepTextKey="I've acquired enough scrap metal to craft the false key. I need to travel to the western forge. Once there, I must use the key mold to create the fake key that we will switch for the real one."},
        ["Create the False Key"] =
            {appendText=" at a blacksmithing area on the southwest wall near the sewer entrance."},
        [5] = 
            {appendStepText="In the Elven Gardens District of the Imperial City, I made an iron key to unlock a chest holding a Daedric artifact. ", stepTextKey="In order to make the key look worn, I need to treat it with acid. Regilus said there should be some in the Daedric laboratory on the north side of the district."},
        ["Treat the Key with Acid"] =
            {appendText=" in a vat next to an enchanting area and large Daedric bookshelves."},
        [6] = 
            {appendStepText="In the Elven Gardens District of the Imperial City, ", stepTextKey="I must find Captain Regilus again, this time in the Groundskeeper's Storehouse on the northwestern wall."},
        ["Find Regilus in the Groundskeeper's Storehouse"] =
            {appendText=". It is the southernmost of the three buildings along the northwestern outer wall, marked by a tattered red banner with a diamond symbol."},
        [7] = 
            {appendStepText="In the Elven Gardens District of the Imperial City, ", stepTextKey="Captain Regilus is going to distract the guardian of the key while I perform the switch."},
        ["Switch the Keys"] =
            {appendText=" in a chest in the Plundered Counting House within the outer wall northwest of the Great Forge."},
        [8] = 
            {appendStepText="In the Elven Gardens District of the Imperial City, ", stepTextKey="I have the real key. I need to find Captain Regilus back in the sewer hideout."},
        ["Meet Captain Regilus at the Safe House"] =
            {appendText=" under the Elven Gardens District flag."},
        [9] = 
            {appendStepText="", stepTextKey="I should return to the Drake and inform her of what transpired."},
        ["Bring the Key to the Drake of Blades"] =
            {appendText=", waiting in the central chamber of my Alliance base in the sewers."},
        [10] = 
            {appendStepText="In my Alliance base in the Imperial City Sewers, ", stepTextKey="I should finish my business with the Drake of Blades."},
        ["Talk to the Drake of Blades"] =
            {appendText=" and tell her what happened when I met with Captain Regilus."},
    },

[GetQuestName(5490)] = { --"Knowledge is Power"			--Aashiana
        [1] = 
            {appendStepText="In the Arboretum District of the Imperial City, ", stepTextKey="The Daedra keep the book locked away in a strongbox near the central pavilion."},
        ["Recover the Coded Book"] =
            {appendText=". I'll need to find the key to the strongbox first. Any of these Daedra could be carrying it."},
        [2] = 
            {appendStepText="In the Arboretum District of the Imperial City, ", stepTextKey="I must rescue the Chief Archivist before the Daedra put him to the sword. He may know more about this book."},
        ["Rescue the Chief Archivist"] =
            {appendText=", tied up near the outer wall just across from the platform where I found the book."},
        [3] = 
            {appendStepText="", stepTextKey="The Chief Archivist told me that he masked the contents of this book with a spell before the Daedra got to it. Unfortunately, they are now unwittingly burning the ciphers that can decode it. I must find them before they can be burned."},
        ["Find the Spell Ciphers"] =
            {appendText=" \n\nThe ciphers glow with a golden light, and are scattered around the four corners of the Arboretum District near circular pavilions with large fiery braziers."},
        [4] = 
            {appendStepText="In the Arboretum District of the Imperial City, ", stepTextKey="Now that I have all of the spell ciphers, I need to find the Chief Archivist. He said he would meet me in the nearby Archives."},
        ["Find the Chief Archivist in the Archives"] =
            {appendText=". The entrance to the Ruined Archives is flanked by two pillars on the outer wall to the north, just to the right of the sewer entrance."},
        [5] = 
            {appendStepText="In the Ruined Archives of the Imperial City, hidden within the outer wall of the northern Arboretum District, ", stepTextKey="The Chief Archivist has begun to cast the translation spell. I need to add the ciphers to the ritual."},
        ["Cast the Translation Spell"] =
            {appendText=" within the golden light."},
        [6] = 
            {appendStepText="In the Ruined Archives of the Imperial City, hidden within the outer wall of the northern Arboretum District, ", stepTextKey="I have decoded the book titled, \"The Sublime Brazier.\" I should take it back to the Drake of Blades and see if she can make sense of its contents."},
        ["Take \"The Sublime Brazier\" to the Drake of Blades"] =
            {appendText=", waiting in the central chamber of my Alliance base in the sewers."},
        [7] = 
            {appendStepText="", stepTextKey="I should finish talking with the Drake of Blades."},
        ["Talk to the Drake of Blades"] =
            {appendText=" and await further instructions."},
    },


[GetQuestName(5482)] = { --"The Sublime Brazier"		--Aashiana
		[1] = 
			{appendStepText="In my Alliance base in the Imperial City sewers, I discussed what we have learned so far with the Drake of Blades, but there are still some questions to be answered. ", stepTextKey="Before we enter the Dragonfire Cathedral, I must retrieve a message from our unlikely ally, The Rat. According to The Drake of Blades, it may provide some vital information about Molag Bal's plans."},
		["Find The Rat's Message"] =
			{appendText=" in the sewers near my Alliance Base, probably in a crate or barrel at the base of one of the nearby ladders to the upper city for easy access."},
		[2] = 
			{appendStepText="In the Imperial City sewers near my Alliance base, ", stepTextKey="I have The Rat's message. I must return to the Drake of Blades to finalize our plans for defending the Sublime Brazier."},
		["Talk to the Drake of Blades"] =
			{appendText=" in the central area of my Alliance base in the sewers."},
		[3] = 
			{appendStepText="In the central area of my Alliance Base in the Imperial City sewers, ", stepTextKey="The Drake of Blades has decided to become the Sublime Brazier's immortal guardian. We must go to the Dragonfire Cathedral, buried deep beneath Imperial City, and perform a ritual to complete the Drake's transformation."},
		["Travel to the Dragonfire Cathedral"] =
			{appendText=", through a large Ayleid door glowing with runes behind a crumbling wall near my Alliance base in the sewers. It is in a side passage I may have passed by while searching for The Rat's message earlier."},
		[4] = 
			{appendStepText="Through a large Ayleid door in the sewers near my Alliance base, ", stepTextKey="We've reached a large cave beneath Imperial City containing the Dragonfire Cathedral. I must follow the Drake of Blades, Father Egnatius, and Captain Caudex inside to perform the ritual."},
		["Follow The Drake of Blades into the Cathedral"] =
			{appendText="."},
		[5] = 
			{appendStepText="Through a large Ayleid door in the sewers near my Alliance base, ", stepTextKey="We've reached a large cave beneath Imperial City containing the Dragonfire Cathedral. I must follow The Drake of Blades, Father Egnatius, and Captain Caudex inside to perform the ritual."},
		["Watch Father Egnatius Prepare the Ritual"] =
			{appendText="."},
		[6] = 
			{appendStepText="Through a large Ayleid door in the sewers near my Alliance base, in the Dragonfire Cathedral, ", stepTextKey="Father Egnatius has begun the ritual to imbue The Drake of Blades with Akatosh's power, but the Dragonfire Cathedral is under assault by the forces of Molag Bal. I must hold them off until Egnatius completes the ritual."},
		["Go to the Siege Platform"] =
			{appendText=" in the next room."},
		[7] = 
			{appendStepText="Through a large Ayleid door in the sewers near my Alliance base, in the Dragonfire Cathedral, ", stepTextKey="Captain Caudex set up siege weapons to allow me to defend Dragonfire Cathedral's barricades against invading Daedra. I must hold them off long enough for Father Egnatius to complete the ritual."},
		["Defeat Daedra to Repel the Assault"] =
			{appendText=". Hold off the attacking enemies by using the ballistae as well as defeating any Daedra that come through portals."},
		[8] = 
			{appendStepText="Through a large Ayleid door in the sewers near my Alliance base, ", stepTextKey="Daedra are assaulting the Dragonfire Cathedral from all sides. I must defend the barricades with the ballista while also fighting off Daedra who try to stop me."},
		["Defeat the Gate Crasher"] =
			{appendText=" after successfully defeating all the other Daedra."},
		[9] = 
			{appendStepText="Through a large Ayleid door in the sewers near my Alliance base, within the Dragonfire Cathedral, ", stepTextKey="The Daedra have smashed the barricades and forced their way into the Dragonfire Cathedral. I must defend the Sublime Brazier at all costs."},
		["Defend the Sublime Brazier"] =
			{appendText=", by defeating all the Daedra coming through portals."},
		[10] = 
			{appendStepText="Through a large Ayleid door in the sewers near my Alliance base, within the Dragonfire Cathedral, ", stepTextKey="The Daedra are defeated and Father Egnatius has completed the ritual to imbue The Drake of Blades with Akatosh's power. I must witness the ritual's completion."},
		["Witness the Ritual"] =
			{appendText=", as the Drake of Blades ascends to become the immortal guardian of the Sublime Brazier."},
		[11] = 
			{appendStepText="Through a large Ayleid door in the sewers near my Alliance base, within the Dragonfire Cathedral, ", stepTextKey="The Drake of Blades has been transformed into the Sublime Brazier's immortal guardian. She wields the power of Akatosh, and will live forever, but cannot leave the Dragonfire Cathedral. I should see if she has any last words before we part."},
		["Talk to The Drake of Blades"] =
			{appendText=", glowing with a golden light near the Sublime Brazier."},
		[12] = 
			{appendStepText="Through a large Ayleid door in the sewers near my Alliance base, within the Dragonfire Cathedral, ", stepTextKey="The Drake of Blades has become Akatosh's immortal guardian. She will remain in the Dragonfire Cathedral, defending the Sublime Brazier from any who would seek to destroy it for all time. I should speak with Father Egnatius back in the Alliance base."},
		["Talk to Father Egnatius in the Alliance Base"] =
			{appendText=" in the Imperial City sewers, using the portal near the Sublime Brazier."},
	},
-- 		=========================================================================
--		  Imperial City Sides
-- 		=========================================================================

[GetQuestName(5508)] = { --"Scouting the Arboretum"			--Aashiana -- MartinToms
        ["Investigate the Arboretum"] =
            {appendText=". The ladders leading up to the Imperial City districts are all in one area of my Alliance's base in the sewers, one of them is the correct one."},
        ["Plant the Alliance Banner"] =
            {appendText=" near where the sewer ladder exits into the city above."},
    },

[GetQuestName(5510)] = { --"Scouting the Arboretum"			-- MartinToms
        ["Investigate the Arena District"] =
            {appendText=". The ladders leading up to the Imperial City districts are all in one area of my Alliance's base in the sewers... now I just need to find the right one."},
        ["Plant the Alliance Banner"] =
            {appendText=" near where the sewer ladder exits into the city above."},
    },

[GetQuestName(5511)] = { --"Scouting the Arboretum"			-- MartinToms
        ["Investigate the Elven Gardens District"] =
            {appendText=". The ladders leading up to the Imperial City districts are all in one area of my Alliance's base in the sewers... now I just need to find the right one."},
        ["Plant the Alliance Banner"] =
            {appendText=" near where the sewer ladder exits into the city above."},
    },

[GetQuestName(5506)] = { --"Scouting the Arboretum"			-- MartinToms
        ["Investigate the Memorial District"] =
            {appendText=". The ladders leading up to the Imperial City districts are all in one area of my Alliance's base in the sewers... now I just need to find the right one."},
        ["Plant the Alliance Banner"] =
            {appendText=" near where the sewer ladder exits into the city above."},
    },


[GetQuestName(5512)] = { --"Scouting the Arboretum"			-- MartinToms
        ["Investigate the Nobles District"] =
            {appendText=". The ladders leading up to the Imperial City districts are all in one area of my Alliance's base in the sewers... now I just need to find the right one."},
        ["Plant the Alliance Banner"] =
            {appendText=" near where the sewer ladder exits into the city above."},
    },

[GetQuestName(5513)] = { --"Scouting the Arboretum"			-- MartinToms
        ["Investigate the Temple District"] =
            {appendText=". The ladders leading up to the Imperial City districts are all in one area of my Alliance's base in the sewers... now I just need to find the right one."},
        ["Plant the Alliance Banner"] =
            {appendText=" near where the sewer ladder exits into the city above."},
    },

-- 		=========================================================================
--		  Imperial City Dalies
-- 		=========================================================================


[GetQuestName(5500)] = { --"Dousing the Fires of Industry"			--Aashiana 
        [1] = 
            {appendStepText="In the Elven Gardens District ", stepTextKey="Legion Zero is producing more and more ballistae to continue the bombardment of Imperial City and lands beyond. Quintia Rullus asked if I could cut down on their numbers by setting the unused ones ablaze."},
        ["Destroy the Ballistae"] =
            {appendText=" \n\nThey are scattered around the northern half of the district."},
        [2] = 
            {appendStepText="", stepTextKey="Quintia Rullus told me of a great forge being used to create more siege engines for Molag Bal. I should find some tar. I can use it to ruin the forge and slow down production."},
        ["Find a Barrel of Tar"] =
            {appendText=". There are several located in and around buildings in the north-central part of the District."},
        [3] = 
            {appendStepText="", stepTextKey="Now that I have the tar Quintia Rullus spoke of, I should go to the great forge and dump it on their coals to ruin their engine-building operation."},
        ["Sabotage the Western Forge"] =
            {appendText=", a large circular structure guarded by Daedra in the southwestern part of the district."},
        [4] = 
            {appendStepText="", stepTextKey="I've seriously disrupted Legion Zero's attempts to build a new fleet of siege engines. I should travel to my Alliance's base and let Quintia Rullus know what I've accomplished."},
        ["Find Quintia Rullus in the Alliance Base"] =
            {appendText=", in the central chamber of my Alliance base in the sewers, or near the forge in the crafting area."},
        [5] = 
            {appendStepText="", stepTextKey="I've seriously disrupted Legion Zero's attempts to build a new fleet of siege engines. I should travel to my Alliance's base and let Quintia Rullus know what I've accomplished."},
        ["Talk to Quintia Rullus in the Alliance Base"] =
            {appendText=" to regale her with accounts of your successful sabotage. She may be in the central chamber or near the forge in the crafting area."},
    },

[GetQuestName(5498)] = { --"Historical Accuracy"			--Aashiana 
        [1] = 
            {appendStepText="At my Alliance Base in the Arboretum District of the Imperial City, ", stepTextKey="Loncano believes the archivists have fled to the outskirts of the district. \n\nHe told me that I must stop the Flame Atronachs and Daedroth from indiscriminately burning the city's histories and records. Some of the Dremora may be carrying them as well."},
        ["Slay Daedroth and Flame Atronachs in the Arboretum"] =
            {appendText=" \n\n"},
        ["Find Missing Imperial Records"] =
            {appendText=" "},
        [2] = 
            {appendStepText="", stepTextKey="I've gathered some records from the Arboretum. I should bring them to Loncano in the Alliance base."},
        ["Find Loncano in the Alliance Base"] =
            {appendText=" in the sewers. He is waiting in the crafting area, hopeful that you have saved some important records from ruin."},
        [3] = 
            {appendStepText="", stepTextKey="I've gathered some Imperial records from the Arboretum. I should bring them to Loncano in the Alliance base."},
        ["Bring the records to Loncano in the Alliance Base"] =
            {appendText=" to receive your reward and his gratitude."},
    },

[GetQuestName(5492)] = { --"The Lifeblood of an Empire"			--Aashiana 
        [1] = 
            {appendStepText="", stepTextKey="I need to rescue a handful of Imperial citizens. They can be found throughout the Arena District."},
        ["Rescue Imperial Citizens"] =
            {appendText=" \n\nThey may be hiding in inconspicuous places, cowering near Daedra, or even locked in cages."},
        [2] = 
            {appendStepText="", stepTextKey="I've found a handful of survivors, though there are undoubtedly more. I should return to Valga."},
        ["Return to Valga Atrius"] =
            {appendText=", in the central area of your Alliance base in the Imperial City sewers."},
    },

[GetQuestName(5495)] = { --"Priceless Treasures"			--Aashiana 
        [1] = 
            {appendStepText="In my Alliance base in Temple District of the Imperial City, ", stepTextKey="Sister J'Reeza knows a ritual that can protect an object for a time. I'll need to find a Bottle of Ritual Wine and collect Grievous Claws from the Daedra around the district."},
        ["Collect Grievous Claws"] =
            {appendText=" \n\nGrievous Twilight Daedra roam the District  terrorizing the citizens. If they were to lose their claws or even their lives, their victims may escape a grim fate.\n"},
        ["Find a Bottle of Ritual Wine"] =
            {appendText=", stored in several buildings in the District."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I've gathered the components, I should find the brazier Sister J'Reeza mentioned and burn them to make an ash."},
        ["Bring the Components to the Ritual Brazier"] =
            {appendText=". Its holy presence allows purple flowers to bloom around it despite the eternal moonlight, within one of the buildings."},
        [3] = 
            {appendStepText="", stepTextKey="I've obtained the Claw Ash from the brazier. Now I need to find the casks of consecrated oil Sister J'Reeza spoke of and use it on them."},
        ["Anoint Artifacts with the Claw Ash"] =
            {appendText=" \n\nThe artifacts are large urns filled with sacred oil, scattered around the district."},
        [4] = 
            {appendStepText="", stepTextKey="I've cast the ritual on the casks of consecrated oil. I should return to Sister J'Reeza in my Alliance base and let her know that the task is complete."},
        ["Find Sister J'Reeza in the Alliance Base"] =
            {appendText=" in the central area."},
        [5] = 
            {appendStepText="", stepTextKey="I've cast the ritual on the artifacts I could find in the Temple District. I should return to Sister J'Reeza in my Alliance base and let her know."},
        ["Talk to Sister J'Reeza in the Alliance Base"] =
            {appendText=", to receive her appreciation and a reward for your efforts."},
    },

[GetQuestName(5491)] = { --"Speaking For The Dead"			--Aashiana 
        [1] = 
            {appendStepText="In the Imperial City, ", stepTextKey="I need to kill Xivkyn in the Memorial District to empower Legate Gallus's auricular geodes."},
        ["Kill Xivkyn in the Memorial District"] =
            {appendText=" \n\n"},
        [2] = 
            {appendStepText="In the Imperial City, ", stepTextKey="I empowered Legate Gallus's auricular geodes. Now I need to place them in undead laborers in the Memorial District."},
        ["Place Auricular Geodes in Skeletons"] =
            {appendText=" \n\nThe skeletons can be found near the dig sites in the central area."},
        [3] = 
            {appendStepText="In the Memorial District of the Imperial City, ", stepTextKey="I placed all of Legate Gallus's auricular geodes. I should meet him at my base of operations in the Imperial Sewers."},
        ["Find Legate Gallus at the Alliance Base"] =
            {appendText=" in the central chamber."},
        [4] = 
            {appendStepText="In the central area of my Alliance base in the Imperial City sewers, ", stepTextKey="I should inform Legate Gallus that I placed all of his auricular geodes."},
        ["Talk to Legate Gallus"] =
            {appendText=" to receive my reward. A ghostly apparition appeared once my conversation was concluded..."},
    },

[GetQuestName(5501)] = { --"Watch Your Step"			--Aashiana 
        [1] = 
            {appendStepText="In the Nobles District of the Imperial City, ", stepTextKey="Brihana asked me to reset her Ogrim traps and kill any meddlesome Legion Zero soldiers I find."},
        ["Bait and Set Ogrim Traps"] =
            {appendText=" \n\nOne trap is located in each of the four quadrants of the city, somewhere near the outer walls.\n"},
        ["Kill Legion Zero Soldiers"] =
            {appendText=""},
        [2] = 
            {appendStepText="In the Nobles District of the Imperial City, ", stepTextKey="I've finished resetting Brihana's traps and slaying Legion Zero soldiers. I should look for her in my Alliance base."},
        ["Find Brihana in the Alliance Base"] =
            {appendText=" in the sewers, near the ladder to the Nobles District."},
        [3] = 
            {appendStepText="In the Nobles District of the Imperial City, ", stepTextKey="I've killed several legionaries and reset Brihana's traps. I should meet with her in the Alliance base to receive my payment."},
        ["Talk to Brihana in the Alliance Base"] =
            {appendText=" in the sewers, near the ladder to the Nobles District. "},
    },

