		[GetQuestName(4704)] = { --"Welcome to Cyrodiil" --AD -- DC -- EP 			-- OneSkyGod
        [1] = 
            {appendStepText="", stepTextKey="I should use the Transitus Shrine to travel to the Eastern Elsweyr gate."},
        ["Travel to Eastern Elsweyr Gate 1"] =
            {appendText=" by using a Transitus Shrine.\nIt's a small square stone column, with a brazier alight with bright azure flame, found within gates, castles, and keeps currently held by the Aldmeri Dominion.", stepTextKey="I should use the Transitus Shrine to travel to the Eastern Elsweyr gate."},
        [2] = 
            {appendStepText="", stepTextKey="I can find Zan at the siege range. Alternately, if I wish to skip training, I should go speak with Grand Warlord Sorcalin."},
        ["Go to the Siege Range"] =
            {appendText=" by crossing the bridge by the weaponsmith’s forge within the Eastern Elsweyr Gate. Descend from the upper level to the road below and travel along it to a crossroads, then head downhill to the range.\n"},
        ["Talk to Grand Warlord Sorcalin to Skip Training"] =
            {appendText=".\nThe Grand Warlord is a High Elf commander for the Queen at the Eastern Elsweyr Gate, studying battle tactics over the map and intelligence reports spread across her desk in front of the Aldmeri Dominion’s main command tent."},
        [3] = 
            {appendStepText="", stepTextKey="I chose to skip the training. I need to get Grand Warlord Sorcalin's permission to go straight to battle."},
        ["Talk to Grand Warlord Sorcalin 1"] =
            {appendText=" at the Eastern Elsweyr Gate, studying battle tactics and intelligence reports spread across her desk near the Aldmeri Dominion’s main command tent.", stepTextKey="I chose to skip the training. I need to get Grand Warlord Sorcalin's permission to go straight to battle."},
        [4] = 
            {appendStepText="At the Western Elsweyr Gate, ", stepTextKey="I should speak to Fangil to pick up the munitions."},
        ["Talk to Fangil"] =
            {appendText=", currently overseeing the siege equipment beside the Armory."},
        [5] = 
            {appendStepText="", stepTextKey="I should use the Transitus Shrine to return to the Eastern Elsweyr gate and then find Zan at the siege range west of the gate."},
        ["Travel to Eastern Elsweyr Gate 2"] =
            {appendText=" by using a Transitus Shrine. It's a small square stone column, with a brazier alight with bright azure flame, found within gates, castles, and keeps currently held by the Aldmeri Dominion.", stepTextKey="I should use the Transitus Shrine to return to the Eastern Elsweyr gate and then find Zan at the siege range west of the gate."},
        [6] = 
            {appendStepText="I arrived at the Eastern Elsweyr Gate. ", stepTextKey="Now to find Zan and deliver the munitions."},
        ["Talk to Zan at Siege Range 1"] =
            {appendText=", a Khajiit reviewing siege reports behind his desk. To reach him, cross the bridge by the weaponsmith’s forge. Descend from the upper level to the road below and travel along it to a crossroads, then head downhill to the range.", stepTextKey="Now to find Zan and deliver the munitions."},
        [7] = 
            {appendStepText="", stepTextKey="Arcalin asked me to start my training by picking up munitions from the Western Elsweyr gate. I should use the Transitus Shrine to travel there. Or, I can skip training by talking to Grand Warlord Sorcalin. "},
        ["Travel to Western Elsweyr Gate"] =
            {appendText=". Viriniel has information about traveling using Transitus Shrines, she is near a brazier alight with bright azure flame at the Western Elsweyr Gate.\n"},
        ["Talk to Grand Warlord Sorcalin to Skip Training"] =
            {appendText=". The Grand Warlord is a High Elf commander for the Queen at the Eastern Elsweyr Gate, studying battle tactics over the map and intelligence reports spread across her desk in front of the Aldmeri Dominion’s main command tent."},
        [8] = 
            {appendStepText="", stepTextKey="Veronard Liancourt asked me to start my training by picking up munitions from the Northern High Rock gate. I should use the Transitus Shrine to travel there. Or I can skip training by talking to Grand Warlord Dortene."},
        ["Travel to Northern High Rock Gate"] =
            {appendText=". Felycie Canis has information about the travel between Transitus Shrines, she is near a brazier alight with bright azure flame at the Southern High Rock Gate.\n\n"},
        ["Talk to Grand Warlord Dortene 1"] =
            {appendText=" currently overseeing the maps for the King and Covenant at the command tent at Southern High Rock Gate.", stepTextKey="Veronard Liancourt asked me to start my training by picking up munitions from the Northern High Rock gate. I should use the Transitus Shrine to travel there. Or I can skip training by talking to Grand Warlord Dortene."},
        [9] = 
            {appendStepText="", stepTextKey="I decided to skip the introduction to Cyrodiil. I should talk to Grand Warlord Dortene to confirm."},
        ["Talk to Grand Warlord Dortene 2"] =
            {appendText=" to pledge your weapon to the King and Covenant at the command tent at Southern High Rock Gate.", stepTextKey="I decided to skip the introduction to Cyrodiil. I should talk to Grand Warlord Dortene to confirm."},
        [10] = 
            {appendStepText="", stepTextKey="I can find Bugbesh at the siege range. Alternately, if I wish to skip training, I should go speak with Grand Warlord Dortene."},
        ["Travel to the Siege Range"] =
            {appendText=". Arnousten Boulat atop the Southern High Rock Gate stone and wood watchtower, positioned next to the main archery range, has the signal horn to alert the siege practice grounds below. The siege range tower is barely visible through the dense woodland below.\n"},
        ["Talk to Grand Warlord Dortene 3"] =
            {appendText=" to pledge your weapon to the King and Covenant at the command tent at Southern High Rock Gate.", stepTextKey="I can find Bugbesh at the siege range. Alternately, if I wish to skip training, I should go speak with Grand Warlord Dortene."},
        [11] = 
            {appendStepText="The Northern High Rock Gate is well protected, ", stepTextKey="I should speak to Zahreh to pick up the munitions."},
        ["Talk to Zahreh"] =
            {appendText=", currently overseeing the siege equipment."},
        [12] = 
            {appendStepText="", stepTextKey="I should use the Transitus Shrine to return to the Southern High Rock gate, then find Bugbesh at the siege range north of the gate."},
        ["Travel to Southern High Rock Gate"] =
            {appendText=" by using a Transitus Shrine. It is a small square stone column, with a brazier alight with bright azure flame, found within gates, castles, and keeps currently held by the Daggerfall Covenant."},
        [13] = 
            {appendStepText="I have arrived at Southern High Rock Gate. ", stepTextKey="Now to find Bugbesh and deliver the munitions."},
        ["Talk to Bugbesh"] =
            {appendText=", the Orc siege engineer standing behind her desk at the far end of the siege range. The siege range's tower is barely visible through the dense woodland below the archery range at Southern High Rock Gate."},
    [14] = 
        {appendStepText="", stepTextKey="I should use the Transitus Shrine to travel to the Southern High Rock gate."},
    ["Travel to Southern High Rock Gate 1"] =
        {appendText=" by using a Transitus Shrine.\nIt is a small square stone column, with a brazier alight with bright azure flame, found within gates, castles, and keeps currently held by the Daggerfall Covenant.", stepTextKey="I should use the Transitus Shrine to travel to the Southern High Rock gate."},
        [15] = 
            {appendStepText="", stepTextKey="Olvyia Indaram asked me to start my training by picking up munitions from the Southern Morrowind gate. I should use the Transitus Shrine to travel there. Or I can skip training by talking to Grand Warlord Zimmeron."},
        ["Travel to Southern Morrowind Gate"] =
            {appendText=". Vother Herendas has information about travel between Transitus Shrines. He is near a brazier alight with bright azure flame at the Northern Morrowind Gate.\n"},
        ["Talk to Grand Warlord Zimmeron to Skip Training 1"] =
            {appendText=" if I am eager to spill blood for the Pact. Zimmeron is currently studying maps at the command tent at the Northern Morrowind Gate.", stepTextKey="Olvyia Indaram asked me to start my training by picking up munitions from the Southern Morrowind gate. I should use the Transitus Shrine to travel there. Or I can skip training by talking to Grand Warlord Zimmeron."},
        [16] = 
            {appendStepText="", stepTextKey="I chose to skip the introduction to Cyrodiil. I should talk to Grand Warlord Zimmeron to confirm."},
        ["Talk to Grand Warlord Zimmeron"] =
            {appendText=" to begin spilling blood for the Pact. \nZimmeron is currently studying maps at the command tent at the Northern Morrowind Gate."},
        [17] = 
            {appendStepText="", stepTextKey="Now that I'm at the Southern Morrowind gate, I should pick up munitions from Mirrored-Skin."},
        ["Talk to Mirrored-Skin"] =
            {appendText=", inspecting crates near the Transitus Shrine."},
        [18] = 
            {appendStepText="", stepTextKey="I should use the Transitus Shrine to return to the Northern Morrowind gate, then find Adalmor at the siege range south of the gate."},
        ["Travel to Northern Morrowind Gate"] =
            {appendText=" by using a Transitus Shrine, a small square stone column with a brazier alight with bright azure flame, found within gates, castles, and keeps currently held by the Ebonheart Pact."},
        [19] = 
            {appendStepText="I have arrived at the Northern Morrowind Gate. \n\n", stepTextKey="Now to find Adalmor and deliver the munitions."},
        ["Talk to Adalmor"] =
            {appendText=" at the siege range, downhill from the Northern Morrowind Gate along the southeastern road. He standing in front of a large Ebonheart Pact banner next to some crates."},
        [20] = 
            {appendStepText="", stepTextKey="I can find Adalmor at the siege range. Alternately, if I wish to skip training, I should go speak with Grand Warlord Zimmeron."},
        ["Travel to the Siege Range"] =
            {appendText=", downhill from the Northern Morrowind Gate along the southeastern road.\n"},
        ["Talk to Grand Warlord Zimmeron to Skip Training 2"] =
            {appendText=" if I am eager to spill blood for the Pact. Zimmeron is currently studying maps at the command tent at the Northern Morrowind Gate.", stepTextKey="I can find Adalmor at the siege range. Alternately, if I wish to skip training, I should go speak with Grand Warlord Zimmeron."},
        [21] = 
            {appendStepText="", stepTextKey="I should use the Transitus Shrine to travel to the Northern Morrowind gate."},
        ["Travel to Northern Morrowind Gate"] =
            {appendText=" by using a Transitus Shrine, a small square stone column with a brazier alight with bright azure flame, found within gates, castles, and keeps currently held by the Ebonheart Pact."},    
  
    },

