		[GetQuestName(6373)] = { --"Chaos Magic"		--JayAstrophel
		[1] = 
			{appendStepText="", stepTextKey="I should speak to Sheogorath to see what he wants to teach me."},
		["Talk to Sheogorath 1"] =
			{appendText=". Dressed in purple and red regalia, he stands next to a tiny soldier crafted from produce and discarded armor. Did he create such a thing himself?\n", stepTextKey="I should speak to Sheogorath to see what he wants to teach me."},
		[2] = 
			{appendStepText="", stepTextKey="Sheogorath has Volendrung, a legendary Daedric artifact belonging to Malacath. I should travel to Cheesemonger's Hollow to use it."},
		["Enter Cheesemonger's Hollow"] =
			{appendText=", by traveling through the swirling red portal near the bounty boards at one of your alliance camps, near a tiny soldier crafted from produce and discarded armor. How much cheese might await within?\n"},
		[3] = 
			{appendStepText="Within the portal to Cheesemonger's Hollow, ", stepTextKey="I should take Volendrung from the weapon rack."},
		["Take Volendrung"] =
			{appendText=", the large spiked hamer, from the weapon rack just to the right after entering the portal. True to its name, the Hollow is filled with all sorts of different cheeses, but there's no time for tasting when there's fighting to be done.\n"},
		[4] = 
			{appendStepText="Within the portal to Cheesemonger's Hollow, ", stepTextKey="I should use Rourken's Rebuke on a Heavy Xivkyn target dummy to satisfy Sheogorath."},
		["Use Rourken's Rebuke on Heavy Xivkyn Dummy"] =
			{appendText=". It awaits within Cheesemonger's Hollow. A waterfall just behind the dummy roars loudly.\n"},
		[5] = 
			{appendStepText="Within the portal to Cheesemonger's Hollow, ", stepTextKey="I should use Malacath's Vengeance on a Light Xivkyn target dummy to satisfy Sheogorath."},
		["Use Malacath's Vengeance on Light Xivkyn Dummy"] =
			{appendText=". It awaits within Cheesemonger's Hollow, on a raised stone dias to the far east. This far in, the lack of cheese is quite noticeable. Instead, orange glowstalks light the way.\n"},
		[6] = 
			{appendStepText="Within the portal to Cheesemonger's Hollow, ", stepTextKey="I should defeat a Light Xivkyn Dummy to show Sheogorath that I know how to wield Volendrung."},
		["Kill Light Xivkyn Dummy"] =
			{appendText=". It awaits within Cheesemonger's Hollow, on a raised stone dias to the far east. This far in, the lack of cheese is quite noticeable. Instead, orange glowstalks light the way.\n"},
		[7] = 
			{appendStepText="Within the portal to Cheesemonger's Hollow, ", stepTextKey="I should use Accursed Charge on a horde of gibbering idiots to satisfy Sheogorath."},
		["Use Accursed Charge on Gibbering Idiots"] =
			{appendText=" within Cheesemonger's Hollow. They celebrate merrily on a raised stone dias on the north end of the Hollow, lit by dancing blue flames.\n"},
		[8] = 
			{appendStepText="Within the portal to Cheesemonger's Hollow, ", stepTextKey="I should charge Volendrung by killing gibbering idiots, then use Ruinous Cyclone on the horde to satisfy Sheogorath."},
		["Use Ruinous Cyclone on Gibbering Idiots"] =
			{appendText=" within Cheesemonger's Hollow. They celebrate merrily on a raised stone dias on the north end of the Hollow, lit by dancing blue flames.\n"},
		[9] = 
			{appendStepText="Within the portal to Cheesemonger's Hollow, witness Volendrung's power.\n", stepTextKey=""},
		["Witness the Destruction"] =
			{appendText=" within Cheesemonger's Hollow, on a raised stone dias on the north end of the Hollow, lit by dancing blue flames. This is a powerful artifact indeed.\n"},
		[10] = 
			{appendStepText="Within the portal to Cheesemonger's Hollow, ", stepTextKey="I defeated enough summoned soldiers and target dummies to satisfy Sheogorath. I can now return Volendrung, continue to destroy soldiers with it, or, if I wait too long without killing, allow the weapon to devour my soul."},
		["Return Volendrung"] =
			{appendText=" to an armor rack at the entrance of Cheesemonger's Hollow. Such a dangerous force can only be wielded for so long, it seems...\n"},
		[11] = 
			{appendStepText="Within the portal to Cheesemonger's Hollow, ", stepTextKey="I should speak to Sheogorath to learn more about Volendrung."},
		["Talk to Sheogorath 2"] =
			{appendText=" at the entrance to Cheesemonger's Hollow, near the stacks of cheese. He appears almost gleeful at the chaos you have caused.\n", stepTextKey="I should speak to Sheogorath to learn more about Volendrung."},
		[12] = 
			{appendStepText="Within the portal to Cheesemonger's Hollow, ", stepTextKey="Sheogorath offered to let me use Volendrung during the Three Banners War in Cyrodiil, but it will cost me my soul. I should speak to him to finish our business."},
		["Talk to Sheogorath 3"] =
			{appendText=" at the entrance to Cheesemonger's Hollow, near the stacks of cheese. He appears almost gleeful at the chaos you have caused.\n", stepTextKey="Sheogorath offered to let me use Volendrung during the Three Banners War in Cyrodiil, but it will cost me my soul. I should speak to him to finish our business."},
	},

[GetQuestName(4628)] = { --"Supplies for Applewatch"		-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should bring Leono's order for new supplies to Hafza in Bruma."},
        ["Travel to Bruma"] =
            {appendText=". The village is south of Fort Dragonclaw in the snowy, northern mountains."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I've reached Bruma, I should give the supplies list to Hafza."},
        ["Talk to Hafza"] =
            {appendText=", who is seeking solace in a place of worship."},
    },

[GetQuestName(4629)] = { --"Secrets Revealed"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should journey to Bruma and let Wardiya know someone is trying to kill her."},
        ["Travel to Bruma Anchor"] =
            {appendText=". The village is south of Fort Dragonclaw in the snowy, northern mountains."},
        [2] = 
    {appendStepText="", stepTextKey="Now that I've reached Bruma Anchor, I should find Wardiya."},
        ["Speak to Wardiya"] =
            {appendText=", who is probably in a safe house given that Dremora are raiding the town."},
    },

		[GetQuestName(4630)] = { -- "Regret"						-- Octavare
			[1] = 
				{appendStepText="", stepTextKey="I should travel to Cropsford and find Bosekus."},
			["Travel to Cropsford"] =
				{appendText=". This small farming town is located southwest of Drakelowe Keep and connects directly to the Southern Morrowind Gate via the Transitus Network."},
			[2] = 
				{appendStepText="", stepTextKey="Now that I've reached Cropsford, I should inform Bosekus of his brother's death."},
			["Talk to Bosekus"] =
				{appendText=". He is chopping wood next to the Cropsford Armory on the southwest outskirts of town."},
		},
[GetQuestName(4632)] = { --"Special Delivery"					-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Cropsford and find Skulreid Foxbite."},
        ["Travel to Cropsford"] =
            {appendText=", a southeastern town. It is southwest of Drakelowe Keep and southeast of Castle Alessia."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I'm in Cropsford, I should bring the fertilizer to Skulreid Foxbite."},
        ["Talk to Skulreid Foxbite"] =
            {appendText=" at his pumpkin patch near the shrine on the town's east side."},
    },
   [GetQuestName(4635)] = { --"Heirloom"					-- Octavare
        [1] = 
            {appendStepText="", stepTextKey="I should see if any of the goods remain."},
        ["Search Area for Goods"] =
            {appendText=". I should check the crates surrounding the cart where I found the note. The cart is located on the road leading north from Vlastarus, the town in the southeast. It is adjacent to the Ayleid ruins of Ceyatatar."},
        [2] = 
            {appendStepText="", stepTextKey="Only a rag doll remains of Lorene Menillet's goods. I should travel to Cropsford to deliver it to her."},
        ["Travel to Cropsford"] =
            {appendText=". This small farming town is located southwest of Drakelowe Keep."},
        [3] = 
            {appendStepText="", stepTextKey="Now that I'm in Cropsford, I should deliver the rag doll to Lorene Menillet."},
        ["Talk to Lorene Menillet"] =
            {appendText=", leaning against a clothesline next to a house near the Cropsford Central Flag."},
    },
[GetQuestName(4637)] = { --"The Message"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I need to journey to Cropsford and deliver the letter to Octavimus Bincal."},
        ["Travel to Cropsford"] =
            {appendText=", a southeastern town, southeast of Castle Alessia and southwest of Drakelowe Keep."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I'm finally in Cropsford, I should bring Octavimus Bincal the letter."},
        ["Talk to Octavimus Bincal"] =
            {appendText=" at his house on the outskirts of town."},
    },
	    [GetQuestName(4639)] = { --"Better Late Than Never"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should journey to Bruma and deliver them to Kjakur Gray-Fists."},
        ["Travel to Bruma Anchor"] =
            {appendText=". The village is south of Fort Dragonclaw in the snowy northern mountains."},
        [2] = 
            {appendStepText="", stepTextKey="I've reached Bruma Anchor. Now to find Kjakur Gray-Fists and deliver his gifts."},
        ["Talk to Kjakur Gray-Fists"] =
            {appendText=". With the Dremora raiding the town, he may be sheltering in a safe place."},
    },
    [GetQuestName(4640)] = { --"Sands of Sentinel"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="Now to travel to Cropsford and find Hisham."},
        ["Travel to Cropsford"] =
            {appendText=", a southeastern town that is east of the Niben River and southwest of Drakelowe Keep."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I've reached Cropsford, I should find Hisham and give him the pouch of sand."},
        ["Talk to Hisham"] =
            {appendText=" who is working outside Dralen's Warehouse, just north of the central flag."},
    },
    [GetQuestName(4658)] = { --"Misplaced Knowledge"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Weynon Priory."},
        ["Travel to Weynon Priory"] =
            {appendText=". It is east of Chorrol and southeast of Fort Rayles in the region's northwest."},
        [2] = 
            {appendStepText="", stepTextKey="I should deliver this notebook to Atia Tucca."},
        ["Talk to Atia at Weynon Priory"] =
            {appendText=". She is near the burning brazier at the Priory's central square."},
    },
    [GetQuestName(4660)] = { --"The Devils You Know"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Bruma and find Trelon Valen."},
        ["Travel to Bruma Anchor"] =
            {appendText=", a small city south of Fort Dragonclaw in the north's snowy mountains."},
        [2] = 
            {appendStepText="I arrived in this small northern city south of Fort Dragonclaw. I found a Daedric raid with Dremora attacking anyone in the streets. At least ", stepTextKey="I'm in Bruma. Now to find Trelon Valen."},
        ["Talk to Trelon Valen"] =
            {appendText=". He is probably in the large Manor House seeking safety."},
    },


    [GetQuestName(4662)] = { --"Articles of Faith"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Weynon Priory."},
        ["Travel to Weynon Priory"] =
            {appendText=". It is east of Chorrol and southeast of Fort Rayles in the region's northwest."},
        [2] = 
            {appendStepText="", stepTextKey="The label on the robes indicates they were intended for Verro Sertorius in Weynon Priory. He might want them back."},
        ["Find Verro at Weynon Priory"] =
            {appendText=". He is often near the priory's square with the burning brazier."},
    },
    [GetQuestName(4663)] = { --"Out for a Walk"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="If I travel to Cheydinhal, I should look for Kirandas Falto and tell her that Tertius is still looking."},
        ["Travel to Cheydinhal"] =
            {appendText=", a northeastern town on a long, narrow lake. It is southeast of Arrius Keep and southwest of Farragut Keep."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I'm in Cheydinhal I should find Kirandas Falto."},
        ["Talk to Kirandas Falto"] =
            {appendText=" at her boarded-up house with crates on the steps. Her home is near a bridge in the south end of town."},
    },
[GetQuestName(4666)] = { --"The Silver Flute"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Chorrol."},
        ["Travel to Chorrol"] =
            {appendText=", a northwestern town suffering from lava-filled fissures. It is south of Fort Rayles."},
        [2] = 
            {appendStepText="", stepTextKey="I should bring the flute to Halion in Chorrol."},
        ["Talk to Halion"] =
            {appendText=". He entertains with music and song at the plaza with a statue on the town's east side."},
    },
[GetQuestName(4671)] = { --"Distant Relatives"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should find Asvorn."},
        ["Travel to Chorrol"] =
            {appendText=", a northwestern town suffering from lava-filled fissures. It is south of Fort Rayles."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I've reached Chorrol, time to find Asvorn and give him Gungrim's letter."},
        ["Talk to Asvorn"] =
            {appendText=" Hairy-Legs, who is relaxing outside the Oak and Crosier tavern on the town's east side."},
    },		
[GetQuestName(4674)] = { --"Spoils of War"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Cheydinhal and warn Jena."},
        ["Travel to Cheydinhal"] =
            {appendText=", a northeastern town on a long, narrow lake. It is southeast of Arrius Keep."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I'm in Cheydinhal, I should find the Jena mentioned in the note."},
        ["Find Jena"] =
            {appendText=". She may be in a ransacked house in the eastern part of town."},
    },	
    [GetQuestName(4678)] = { --"Catch of the Day"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Chorrol and find Hannura."},
        ["Travel to Chorrol"] =
            {appendText=", a town in the northwest, south of Fort Rayles."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I'm in Chorrol, I should deliver the fish to Hannura."},
        ["Talk to Hannura"] =
            {appendText=". She may be working outside of a large stone tavern called Oak and Crosier, near a broken house on the edge of the fiery chasm."},
    },
    [GetQuestName(4682)] = { --"The Doctor's Bag"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Cheydinhal to see if I can find him."},
        ["Travel to Cheydinhal"] =
            {appendText=", a northeastern town on a long, narrow lake. It is southeast of Arrius Keep."},
        [2] = 
            {appendStepText="", stepTextKey="I've reached Cheydinhal. Now to find Hilio Attius and give him his bag."},
        ["Talk to Hilio Attius"] =
            {appendText=", attending to the injured at a damaged structure in the town's northwest area."},
    },
		[GetQuestName(4683)] = { -- "Medicinal Herbs"				-- Octavare
			[1] = 
				{appendStepText="", stepTextKey="I should travel to the Bruma Anchor to see if I can find her."},
			["Travel to Bruma Anchor"] =
				{appendText=". The Bruma Anchor is located in the town of Bruma, the northernmost town in Cyrodiil. It is directly south of Fort Dragonclaw."},
			[2] = 
				{appendStepText="", stepTextKey="Now that I'm in Bruma, I should deliver the herbs to Jafola."},
			["Talk to Jafola"] =
				{appendText=". She is tending to the injured in Bruma Chapel, south of the Bruma Dolmen and west of the Bruma Armory.\n"},
		},
[GetQuestName(4684)] = { --"Congratulations!"				-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Cheydinhal to deliver the news."},
        ["Travel to Cheydinhal"] =
            {appendText=", a northeastern town on a long, narrow lake. It is southeast of Arrius Keep and southwest of Farragut Keep."},
        [2] = 
            {appendStepText="", stepTextKey="I reached Cheydinhal at last. Now to find Brielus Colus and let him know the good news."},
        ["Talk to Brielus Colus"] =
            {appendText=" at his tent near the well by the lake."},
    },	
[GetQuestName(4691)] = { --"Cause and Effect"				-- Jordakai
[1] = 
{appendStepText="", stepTextKey="I should travel to Cheydinhal and return the letter to Iocundus."},
["Travel to Cheydinhal"] =
{appendText=", a northeastern town on a long, narrow lake. It is southeast of Arrius Keep."},
[2] = 
{appendStepText="", stepTextKey="Now that I'm in Cheydinhal, I should deliver this letter to Iocundus."},
["Find Iocundus"] =
{appendText=". He was seen near the town's southeast gate."},
[3] = 
{appendStepText="", stepTextKey="Now that I'm in Cheydinhal, I should deliver this letter to Iocundus."},
["Talk to Iocundus"] =
{appendText=". He was seen near the town's southeast gate."},
},		
		[GetQuestName(4695)] = { -- "Homeward"						-- Jordakai
			[1] = 
				{appendStepText="", stepTextKey="Travel to Vlastarus"},
			["Travel to Vlastarus"] =
				{appendText=", a southwestern town that is southeast of Castle Brindle and northwest of Castle Black Boot."},
			[2] = 
				{appendStepText="I arrived in this southwestern town that is about halfway between two castles. It is southeast of Castle Brindle and northwest of Castle Black Boot. ", stepTextKey="Now that I've reached Vlastarus, I should look for Thiirril"},
			["Talk to Thiirril"] =
				{appendText=" who may be chatting with someone at the town's well, near the Vlastarus Armory."},
		},
[GetQuestName(4696)] = { --"The High Cost of Travel"						-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I need to travel to Vlastarus and find Angiente."},
        ["Travel to Vlastarus"] =
            {appendText=", a southwestern town that is southeast of Castle Brindle and northwest of Castle Black Boot. It is about halfway between the two castles."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I've reached Vlastarus, I need to find Angiente."},
        ["Talk to Angiente"] =
            {appendText=", a High Elf wandering around the center of town."},
    },
[GetQuestName(4707)] = { --"Best Left Unknown"						-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Vlastarus to deliver the note."},
        ["Travel to Vlastarus"] =
            {appendText=", a southwestern town that is southeast of Castle Brindle and northwest of Castle Black Boot. It is about halfway between the two castles."},
        [2] = 
            {appendStepText="", stepTextKey="I've reached Vlastarus. I should find Marodeen now and deliver the note."},
        ["Talk to Marodeen"] =
            {appendText=" in his house on the west edge of town."},
    },
    [GetQuestName(4714)] = { --"The Changing Kind"					-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Vlastarus and warn Engitaale."},
        ["Travel to Vlastarus"] =
            {appendText=", a southwestern town halfway between Castle Brindle and Castle Black Boot."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I'm in Vlastarus, I should speak to Engitaale."},
        ["Speak to Engitaale in Vlastarus"] =
            {appendText=", hammering on the door of the Worker Barracks near the Central Flag."},
    },
[GetQuestName(4716)] = { --"The Shurgak Job"					-- Octavare
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Vlastarus and speak to Klovag."},
        ["Travel to Vlastarus"] =
            {appendText=" in the southwest, directly southeast of Castle Brindle."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I'm in Vlastarus, I need to find Klovag."},
        ["Speak to Klovag"] =
            {appendText=". He is chopping a tree along the road just south of the Watchtower Tavern."},
    },
 [GetQuestName(4777)] = { --"The List"					-- Octavare
        [1] = 
            {appendStepText="", stepTextKey="I should return the victims' belongings to their relatives."},
        ["Find Belongings"] =
            {appendText=". I should check the sacks in Tappo's boat. It is located on the east side of the small lake north of Farragut Keep."},
        [2] = 
            {appendStepText="", stepTextKey="I found items belonging to Severus Tappo's victims. I should try to find their relatives."},
        ["Find a Blasio in Vlastarus"] =
            {appendText=", a town in western Cyrodiil, southeast of Castle Brindle. A man with this surname walks around the stables in the northernmost section of town."},
        ["Find a Dorvayn in Bruma"] =
            {appendText=", the northernmost town in Cyrodiil, directly south of Fort Dragonclaw. A man with this surname is recovering on a cot in the Bruma Chapel in the south of Bruma and west of the Bruma Armory."},
        ["Find a Geta in Chorrol"] =
            {appendText=", in western Cyrodiil, directly south of Fort Rayles. Aberius Geta lives in Chorrol and may be related to the victim. He is inside the Castorius House, reading a book."},
        ["Find a Scaeva in Cropsford"] =
            {appendText=", located southwest of Drakelowe Keep. There is a house in central Cropsford called the Scaeva House. Maybe one of the victim's relatives can be found there."},
        [3] = 
            {appendStepText="", stepTextKey="I returned items to family members of Tappo's victims. Several mentioned they paid a hunter named Thaellin. \n\nI should try to find her on the northeastern shore of Lake Rumare."},
        ["Talk to Thaellin"] =
            {appendText=". Lake Rumare surrounds the Imperial City. The section I should investigate is just south of Chalman Keep. She walks around a small campsite, occassionally going to chop wood or sit by the fire."},
    },
    [GetQuestName(4811)] = { --"Nirnroot Wine"					-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The ash can be collected from Red Mountain Tuff, found around Lake Rumare in the center of Cyrodiil."},
        ["Collect Red Mountain Ash"] =
            {appendText=" \n\nAlso known as Red Mountain Tuff, it is rounded and pale brown in its appearance. As it is rare, I may need to search a long stretch of the nearest lakeshore. \n\nRumor has it that the lake is infested with vicious fish. Probably not good for swimming but fishing might be good."},
        [2] = 
            {appendStepText="", stepTextKey="I've collected enough Red Mountain Ash. I should return to Zimar."},
        ["Talk to Zimar"] =
            {appendText=" at his winery, northeast of Fort Warden near the northernmost bend of the road."},
        [3] = 
            {appendStepText="", stepTextKey="I've collected enough Red Mountain Ash. I should return to Wilminn."},
        ["Talk to Wilminn"] =
            {appendText=" at his winery, northeast of Chalman Keep and southeast of Horunn Milegate at the end of a side road."},
        [4] = 
            {appendStepText="", stepTextKey="I've collected enough Red Mountain Ash. I should return to Thalara."},
        ["Talk to Thalara"] =
            {appendText=" at her winery, hidden by large trees atop a rocky ridge overlooking a lake northwest of Castle Black Boot."},
    },


-- 		=========================================================================
--		  Bruma Dailies
-- 		=========================================================================
		[GetQuestName(4561)] = { -- "Dangerously Low"				-- JayAstrophel
			[1] = 
				{appendStepText="", stepTextKey="I should search the ruins in Bruma for water and bandages."},
			["Collect Clothes"] =
				{appendText="\nThe clothes can be found in baskets around the town, mainly in the ruins of former homes.\n"},
			["Fill Jug with Water"] =
				{appendText=" using the well on the north side of town. It is between two tall trees, to the east of one of the alliance flags.\n"},
			[2] = 
				{appendStepText="Within Bruma, ", stepTextKey="I've found the supplies Hjorik needs. I should bring them to him."},
			["Talk to Hjorik"] =
				{appendText=". He tends to the sick and injured within the Bruma Chapel, a tall building on the south side of town.\n"},
		},
		[GetQuestName(4563)] = { -- "Capstone Caps"					-- JayAstrophel
			["Collect Capstone Cap"] =
				{appendText="\nThe bandit-infested cave where the mushrooms are lies to the northwest of Bruma and south of Cloud Ruler Temple. Its exterior is surrounded by wooden crates and barrels guarded by the bandits, and icicles hang above the wooden entrance door.\n\nOnce inside, the mushrooms are found in groups throughout the cavern, but especially along its walls.\n"},
			["Talk to Hjorik"] =
				{appendText=". He tends to the sick and injured within the Bruma Chapel, a tall building on the south side of town.\n"},
		},
		[GetQuestName(4564)] = { -- "Lost and Alone"				-- JayAstrophel
			[1] = 
				{appendStepText="", stepTextKey="Hjorik asked me to search for survivors and give each an invisibility potion to reach the church safely."},
			["Rescue Villagers"] =
				{appendText="\nThe villagers can be found hiding in and around Bruma. Some places to search might be within burned buildings or along the city's wall.\n"},
			[2] = 
				{appendStepText="", stepTextKey="I should return to Hjorik to see if the survivors I found made it back."},
			["Talk to Hjorik"] =
				{appendText=". He tends to the sick and injured within the Bruma Chapel, a tall building on the south side of town.\n"},
		},
		[GetQuestName(4568)] = { -- "The Standing Stones"			-- JayAstrophel
			[1] = 
				{appendStepText="", stepTextKey="I should use the standing stones southeast of Bruma to charge Hjorik's scrolls."},
			["Use the Standing Stones"] =
				{appendText=". This set of tall, pointed stones forms a circle of sorts. They can be found west of the Ayleid ruin Anga and east of Toadstool Hollow. Touch the centermost stone."},
			[2] = 
				{appendStepText="", stepTextKey="I charged Hjorik's scrolls at the Anga stones. I should return to him in Bruma."},
			["Talk to Hjorik"] =
				{appendText=". He tends to the sick and injured within the Bruma Chapel, a tall building on the south side of town.\n"},
		},
		[GetQuestName(4569)] = { -- "Enemy Reinforcements"			-- JayAstrophel
			["Stop Dremora from Entering Bruma"] =
				{appendText=". Aluri, a Dunmer scout, keeps watch along the road north of Bruma. She is crouched down near a tall pine tree and has further information for you. As for the Dremora themselves, they can be found flanking a bright portal.\n"},
			["Talk to Hjorik"] =
				{appendText=". He tends to the sick and injured within the Bruma Chapel, a tall building on the south side of town.\n"},
		},
		[GetQuestName(4570)] = { -- "Know thy Enemy"				-- JayAstrophel
			["Kill a Dremora Churl"] =
				{appendText=". These Daedra carry a one-handed weapon.\n"},
			["Kill a Dremora Caitiff"] =
				{appendText=". These Daedra carry powerful greatswords.\n"},
			["Kill a Dremora Kyngald"] =
				{appendText=". These Daedra wield staves tipped with orange flame.\n"},
			["Kill a Dremora Narkynaz"] =
				{appendText=". These Daedra wield two-tiered spiked staves tipped with blue light.\n"},
			["Talk to Grigerda"] =
				{appendText=" within the Manor House, the largest building on the west side of Bruma. She sits on the ground, leaning one arm on a table halfway up the stairs to the second floor.\n"},
		},
		[GetQuestName(4572)] = { -- "Requests for Aid"				-- JayAstrophel
			["Place Supplies for Runners"] =
				{appendText=" in the lockbox near Bruma. The box is along the path just outside the city's western gate, behind a waist-high wall and pillar. A lantern illuminates the front side of this wall like a bright beacon.\n"},
			["Talk to Grigerda"] =
				{appendText=" within the Manor House, the largest building on the west side of Bruma. She sits on the ground, leaning one arm on a table halfway up the stairs to the second floor.\n"},
		},
		[GetQuestName(4579)] = { -- "Bring Down the Magister"		-- JayAstrophel
			[1] = 
				{appendStepText="", stepTextKey="She asked me to kill him."},
			["Kill the Magister"] =
				{appendText=" within Grigerda's old house. Said house is but a smoldering ruin now, found on the east side of Bruma.\n"},
			[2] = 
				{appendStepText="", stepTextKey="I killed the Shadowed Path Magister. Now to let Grigerda know."},
			["Talk to Grigerda"] =
				{appendText=" within the Manor House, the largest building on the west side of Bruma. She sits on the ground, leaning one arm on a table halfway up the stairs to the second floor.\n"},
		},
		[GetQuestName(4581)] = { -- "The Unseen"					-- JayAstrophel
			[1] = 
				{appendStepText="Within Bruma, ", stepTextKey="I'll use the crystal she gave me to search, destroying any I find."},
			["Close Portals"] =
				{appendText="\nThe portals can be found within Bruma Manor, the largest building on the west side of town. Look for bright light coming from each portal.\n"},
			[2] = 
				{appendStepText="In Bruma, ", stepTextKey="I found several Dremora portals with Grigerda's crystal. I should let her know."},
			["Talk to Grigerda"] =
				{appendText=" within the Manor House, the largest building on the west side of Bruma. She sits on the ground, leaning one arm on a table halfway up the stairs to the second floor.\n"},
		},
		[GetQuestName(4591)] = { -- "Timely Intervention"			-- JayAstrophel
			[1] = 
				{appendStepText="", stepTextKey="I should search around Bruma for them."},
			["Find Halfara Black-Bear"] =
				{appendText=". The northernmost houses are in the most disrepair, but could offer some shelter for wayward warriors.\n"},
			["Find Methas Andavel"] =
				{appendText=". Perhaps the fighter could be restocking near the Bruma Armory.\n"},
			[2] = 
				{appendStepText="Within Bruma, ", stepTextKey="I found the missing warriors. They're alive but refuse to return to the manor. I should let Grigerda know."},
			["Talk to Grigerda"] =
				{appendText=" within the Manor House, the largest building on the west side of Bruma. She sits on the ground, leaning one arm on a table halfway up the stairs to the second floor.\n"},
		},


-- 		=========================================================================
--		  Cheydinhal Dailies
-- 		=========================================================================
  [GetQuestName(4421)] = { --"Thorns in Our Side"							-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="Vyctoria asked me to travel to Thorn Lodge and bring back any valuables I find."},
        ["Collect Valuables from Thorn Lodge"] =
            {appendText=", down the road to the east of Blue Road Keep and north of the Burned Estate. I should probably make sure to bring a few lockpicks with me. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I found some of the rebels' valuables. I should bring them to Vyctoria Girien."},
        ["Return to Vyctoria Girien"] =
            {appendText=", waiting for your return inside a crumbling shack in the city, east of Blue Road Keep. \n"},
    },
   [GetQuestName(4422)] = { --"Spice"							-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I need to cross into Imperial territory and poison the food stored in a house and in the old church."},
        ["Poison Food"] =
            {appendText=" in the old church that can be seen across the river from the city of Cheydinhal in the east, down the road from Blue Road Keep, past the Burned Estate. I should check the houses near the church as well. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I tainted the food with Vyctoria's spice. I should return to the rebel side of Cheydinhal and let her know."},
        ["Talk to Vyctoria Girien"] =
            {appendText=", waiting for your return inside a crumbling shack in the city, east of Blue Road Keep. \n"},
    },
   [GetQuestName(4425)] = { --"Prisoners of War"							-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I should travel to the graveyard on the eastern side of Cheydinhal and free them."},
        ["Rescue Captured Rebels"] =
            {appendText=", being held hostage in the middle of the graveyard behind the old church across the river. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I freed the captured rebel soldiers. I should return to Vyctoria Girien."},
        ["Talk to Vyctoria Girien"] =
            {appendText=", waiting for your return inside a crumbling shack in Cheydinhal, east of Blue Road Keep. \n"},
    },
   [GetQuestName(4430)] = { --"The Burned Estate"							-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="Vyctoria asked me to travel to the estate and destroy the stones."},
        ["Destroy Daedric Stones"] =
            {appendText=". The Burned Estate sits on top of a hill to the southwest of the city, east of Blue Road Keep. Vyctoria might know more about what to expect at the estate. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I destroyed the Shadowed Path's Daedric stones. I should update Vyctoria Girien in Cheydinhal."},
        ["Talk to Vyctoria Girien"] =
            {appendText=", waiting for your return inside a crumbling shack in the city, east of Blue Road Keep. \n"},
    },
   [GetQuestName(4433)] = { --"Ayleid Treasure"							-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="She asked me to search the ruins of Vahtacen for her and collect any Ayleid items I find."},
        ["Collect Ayleid Object"] =
            {appendText=". The ruins to delve into are southeast of Cheydinhal, by Harlun’s Outpost. An Ayleid chest is on an altar next to a skyshard at the end of the delve. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I found an Ayleid object within Vahtacen. I should bring it to Vyctoria Girien."},
        ["Return to Vyctoria Girien"] =
            {appendText=", waiting for your return inside a crumbling shack in Cheydinhal, east of Blue Road Keep. \n"},
    },
   [GetQuestName(4417)] = { --"Bloodied Waters"							-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="Sylvian Herius asked me to kill Imperial Archers to help the rebels."},
        ["Kill Four Imperial Archers"] =
            {appendText=". Sylvian said that the Imperial Archers are posted on the riverbanks and are preventing the rebel troops from crossing the river. I should head toward one of the bridges in Cheydinhal and look for archers along the river banks.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed several Imperial archers. I should let Sylvian know."},
        ["Return to Sylvian Herius"] =
            {appendText=", patrolling the waterfront campsite across the river in the rebel-controlled side of Cheydinhal, north of The Steed mundus stone, ready to hear that you successfully secured the river crossing for his troops. \n"},
    },
   [GetQuestName(4420)] = { --"Keepsake"							-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I need to try to get it back for him."},
        ["Find Sylvian's Heirloom"] =
            {appendText=" in the ruins of the old church across the river, in the Imperial-controlled part of Cheydinhal. Sylvian’s lockbox is tucked away behind some crates, at the far end of the church ruins. Dibella looks down on it from her stained-glass window, as if waiting in anticipation for someone to discover the treasure locked inside. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I found Sylvian's family heirloom. I should return to the rebel camp."},
        ["Talk to Sylvian Herius"] =
            {appendText=", patrolling the waterfront campsite across the river in the rebel-controlled side of Cheydinhal, north of The Steed mundus stone, hoping to hear some good news about his keepsake. \n"},
    },
  [GetQuestName(4424)] = { --"A Debt Come Due"							-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I need to infiltrate the Imperial-held part of Cheydinhal and kill one of their lieutenants."},
        ["Kill Imperial Lieutenant"] =
            {appendText=". I should be able to find one across the river patrolling the main road on the Imperial-controlled side of the city, north of Harlun’s Outpost. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed an Imperial lieutenant. I should cross the river and inform Sylvian Herius."},
        ["Talk to Sylvian Herius"] =
            {appendText=", patrolling the waterfront campsite across the river in the rebel-controlled side of Cheydinhal, north of The Steed mundus stone, as he waits for your report. \n"},
    },
   [GetQuestName(4426)] = { --"Stacking the Odds"						-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I need to locate the spy and give him the new orders."},
        ["Deliver Orders to the Spy"] =
            {appendText=", currently embedded in the Imperial-controlled side of the city, across the river. He will probably be crouched in the shadow of some building observing Imperial patrols. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I delivered Sylvian's orders. I should let him know."},
        ["Return to Sylvian"] =
            {appendText=", patrolling the waterfront campsite across the river in the rebel-controlled side of the city, north of The Steed mundus stone, as he waits for your confirmation that his new orders have been delivered. \n"},
    },
    [GetQuestName(4434)] = { --"For Piety's Sake"						-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="Sylvian asked me to deliver these petitions to a shrine west of Cheydinhal."},
        ["Deliver Petitions to Shrine"] =
            {appendText=". Follow the road out the western gate. Look for a small rock formation with three trees forming a triangle around it on the right side of the road. From there, the ruins that house the shrine can be seen off in the distance, up the hill. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I delivered the rebels' petitions to the shrine, despite an Imperial ambush. I should let Sylvian know."},
        ["Talk to Sylvian"] =
            {appendText=", patrolling the waterfront campsite in Cheydinhal, north of The Steed mundus stone, as he waits for your report. \n"},
    },


-- 		=========================================================================
--		  Chorral Dailies
-- 		=========================================================================
    [GetQuestName(4226)] = { --"Death to the Black Daggers!"						-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="Lliae the Quick asked me to kill ten Black Dagger bandits in Hackdirt."},
        ["Kill Black Dagger Bandits"] =
            {appendText=". I need to go to the village south of here, past the Chorrol Milegate. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed some Black Daggers in Hackdirt and should return to Lliae the Quick in Chorrol."},
        ["Return to Lliae the Quick in Chorrol"] =
            {appendText=", just south of Fort Rayles. She is patrolling the area behind the storehouse, across the fissure from an old church. \n"},
    },
   [GetQuestName(4247)] = { --"Guard Work is Never Done"						-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I need to get to Narsinfel and kill Minwe."},
        ["Kill Captain Minwe"] =
            {appendText=", whose spirit has been raised from the dead to haunt the ruins to the southeast, just outside of Carmala Outpost. \n"},
        [2] = 
            {appendStepText="", stepTextKey="Time to return to Chorrol and inform Lliae the Quick of my success."},
        ["Return to Lliae the Quick in Chorrol"] =
            {appendText=", just south of Fort Rayles. She is patrolling the area behind the storehouse, across the fissure from the old church. \n"},
    },
    [GetQuestName(4263)] = { --"Field of Fire"						-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I need to hunt down four flame atronachs to help keep the citizens of Chorrol safe."},
        ["Kill Four Flame Atronachs"] =
            {appendText=". I will find them down in the fissure that runs through the town. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I eliminated four flame atronachs. I should let Lliae the Quick know."},
        ["Speak to Lliae the Quick"] =
            {appendText=", who is waiting for your report as she patrols the area behind the storehouse, across the fissure from the old church. \n"},
    },
   [GetQuestName(4265)] = { --"The High Cost of Lying"						-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I need to find the ambush site and trigger the attack."},
        ["Trigger Black Dagger Ambush"] =
            {appendText=". The ambush site is northeast of Fort Rayles, near The Mage mundus stone. It is nestled in between a big rock formation and a V-shaped tree. I need to investigate the Suspicious Backpack at the makeshift campsite to trigger the attack. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I triggered the Black Dagger ambush and survived. I should return to Chorrol and talk to Lliae."},
        ["Speak to Lliae"] =
            {appendText=". She is patrolling the area behind the Storehouse, across the fissure from the old church. \n"},
    },
   [GetQuestName(4270)] = { --"The Cache"						-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I need to find the supply cache Lliae told me about and drop off the supplies she gave me."},
        ["Resupply Lliae's Cache"] =
            {appendText=". The supply cache is stashed just northeast of Fort Glademist, tucked away between two big rocks near a lumber pile by the Fort Glademist Lumbermill in the foothills south of Moranda. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I resupplied Lliae's cache. I should return to Chorrol and let her know."},
        ["Speak to Lliae"] =
            {appendText=", who is south of Fort Rayles, patrolling the area behind the storehouse in town, waiting for me to report back to her about her supply cache. \n"},
    },


-- 		=========================================================================
--		  Weynon Priory Dailies
-- 		=========================================================================
    [GetQuestName(4224)] = { --"Abominations"				-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I need to find the corpses and burn them."},
        ["Burn Corpses"] =
            {appendText=" /n/nThe corpses are inside the Lipsand Tarn delve, which can be found among some Ayleid ruins in the foothills north of Fort Rayles and northeast of the Scroll Temple of Alma Ruma. \n"},
        [2] = 
            {appendStepText="", stepTextKey="The villager corpses have been disposed of. I should return to Weynon Priory and let Mael know."},
        ["Talk to Mael"] =
            {appendText=", who is waiting for your return just outside the doors to the Priory. \n"},
    },
  [GetQuestName(4228)] = { --"Claw of Akatosh"				-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="The Black Daggers are camped on an island west of Weynon Priory. I should travel there and recover the Claw of Akatosh."},
        ["Recover Claw of Akatosh"] =
            {appendText=" from a crate at a bandit camp on an island in the river northwest of Chorrol Milegate. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I recovered the claw. I should bring it to Mael at Weynon Priory."},
        ["Talk to Mael"] =
            {appendText=", who is waiting for your return just outside the doors to the Priory.\n"},
    },
   [GetQuestName(4238)] = { --"Overdue Supplies"				-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I should search Coldcorn Ruin for any sign of Lucius."},
        ["Investigate Coldcorn Ruins"] =
            {appendText=", just north of Fort Ash, near The Thief mundus stone. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I found Lucius' corpse. He had a note and a key on his body. I should read the note."},
        ["Examine Note"] =
            {appendText=". I can find it in my Quest Items, or I can interact with Lucius’ corpse inside the Coldcorn Ruin to read Lucius’ Note. \n"},
        [3] = 
            {appendStepText="", stepTextKey="Lucius' note said the supplies are hidden at the top of the tower. I should look for them up there."},
        ["Collect Supplies"] =
            {appendText=" from the chest at the top of the Coldcorn Ruin tower. \n"},
        [4] = 
            {appendStepText="", stepTextKey="Now that I have the supplies, I should return to Weynon Priory and give them to Mael."},
        ["Talk to Mael"] =
            {appendText=", who is waiting for your return just outside the doors to the Priory. \n"},
    },
   [GetQuestName(4242)] = { --"The Lich"				-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="Mael has asked me to travel there and destroy it."},
        ["Destroy the Lich"] =
            {appendText=" at Lindai, the Ayleid ruins east of Weynon Priory, on a hill northwest of Fort Ash. \n"},
        [2] = 
            {appendStepText="", stepTextKey="The lich is gone. I should return to Weynon Priory and inform Mael."},
        ["Talk to Mael"] =
            {appendText=", who is waiting for your return just outside the doors to the Priory. \n"},
    },
   [GetQuestName(4244)] = { --"Black Dagger Supplies"				-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="Mael asked me to travel there and poison the Black Dagger food supplies."},
        ["Taint Supplies"] =
            {appendText=" /n/nThe house where the supplies are being stored is located along the river, to the west of Weynon Priory. Black Daggers can be seen patrolling around outside the house. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I've poisoned the food. I should return to Weynon Priory and inform Mael."},
        ["Talk to Mael"] =
            {appendText=", who is waiting for your return just outside the doors to the Priory. \n"},
    },


-- 		=========================================================================
--		  Cropsford Dailies
-- 		=========================================================================
   [GetQuestName(4505)] = { --"Seeds of Hope"			-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I need to get those seeds back from the Goblins."},
        ["Collect Seeds"] =
            {appendText=" from deep within Cracked Wood Cave, northwest of Cropsford. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I recovered the seeds. I should bring them to Prefect Antias in Cropsford."},
        ["Talk to Prefect Antias"] =
            {appendText=", who is waiting for you inside of Antias’ House, by the town center. \n"},
    },
   [GetQuestName(4507)] = { --"Offerings to Zenithar"			-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="The villagers yet to give offerings are Lorene Menillet, Lulius Asellio, Bosekus Sun-Belly, and Shagol gro-Gular. I should speak with them."},
        ["Collect Offerings"] =
            {appendText=". \nThe villagers are spread out across the area just south of the town center. I might need to be intimidating or persuasive with some of them. \n"},
        [2] = 
            {appendStepText="", stepTextKey="Now that I've collected the offerings, I should bring them to Zenithar's shrine in the village."},
        ["Take Offerings to Shrine"] =
            {appendText=". The shrine is next to a waterfall just east of the town center. Villagers can occasionally be seen toiling in the pumpkin patch in front of it or praying at the shrine. \n"},
        [3] = 
            {appendStepText="", stepTextKey="I should return to Prefect Antias and let her know I've gathered the offerings and brought them to the shrine."},
        ["Talk to Prefect Antias"] =
            {appendText=", who is waiting for you inside of Antias’ House, by the town center. \n"},
    },
[GetQuestName(4509)] = { --"Harvest Time"			--SaipanDamashii
        [1] = 
            {appendStepText="Distributed near carts and dining areas and stored in crates and barrels, ", stepTextKey="Ufgra asked me to gather produce from around Cropsford and bring it to her in the center of town."},
        ["Collect 6 Sacks of Produce"] =
            {appendText=" ", stepTextKey="Ufgra asked me to gather produce from around Cropsford and bring it to her in the center of town."},
        [2] = 
            {appendStepText="", stepTextKey="I've collected six sacks of produce for Ufgra and should return to her."},
        ["Talk to Ufgra"] =
            {appendText=", awaiting your return behind the central flag."},
    },
[GetQuestName(4512)] = { --"The Dead of Culotte"			-- SaipanDamashii
        [1] = 
            {appendStepText="She heard that there has been some undead activity south of the Niben River Bridge.   ", stepTextKey="She asked me to travel to Culotte and kill some of the undead I find there."},
        ["Kill 8 Undead in Culotte"] =
            {appendText="", stepTextKey="She asked me to travel to Culotte and kill some of the undead I find there."},
        [2] = 
            {appendStepText="", stepTextKey="I thinned the number of dead in Culotte and should inform Ufgra gra-Gum."},
        ["Talk to Ufgra gra-Gum"] =
            {appendText=", waiting behind the flag in the center of Cropsford."},
    },
  [GetQuestName(4517)] = { --"Crown Point"			-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="First, I need to collect some firewood from Bosekus' house."},
        ["Collect Firewood"] =
            {appendText=" from Bosekus’ house to the southwest, just outside of Cropsford. The house can be seen just past the trees from the town center. \n"},
        [2] = 
            {appendStepText="", stepTextKey="Now that I have firewood, I should travel to Crown Point and re-light the flame."},
        ["Light Flame Atop Crown Point"] =
            {appendText=", on a hill southwest of Cropsford. Bosekus might be able to point me in the right direction. \n"},
        [3] = 
            {appendStepText="", stepTextKey="I should return to Prefect Antias and let her know the flame in the tower is lit again."},
        ["Talk to Prefect Antias"] =
            {appendText=", who is waiting for me to return with the good news inside of Antias’ House, by the town center in Cropsford. \n"},
    },
[GetQuestName(4520)] = { --"Bloody Hand Spies!"			-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="If I spot any of them, I should kill them and report back to Ufgra."},
        ["Kill a Bloody Hand Skirmisher"] =
            {appendText=". I should circle around the outer edges of the town of Cropsford, southwest of Drakelowe Keep, where they are likely to be monitoring our troop movements and waiting for the perfect time to descend upon the unsuspecting town. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed a Goblin skirmisher and should let Ufgra know."},
        ["Speak to Ufgra gra-Gum"] =
            {appendText=", who is waiting for me to report back to her in the heart of the southeastern town of Cropsford, behind the Cropsford Central Flag and the huge stone pillar in the center of town. \n"},
    },
   [GetQuestName(4522)] = { --"The Hedoran Estate"		-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I should travel to the Hedoran estate to see what I can find."},
        ["Collect Hedoran Treasure"] =
            {appendText=". What remains of the Hedoran estate is southeast of Cropsford, along the road to Newt Cave. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I found an item at the Hedoran estate. I should bring it to Prefect Antias in Cropsford."},
        ["Talk to Prefect Antias"] =
            {appendText=", who is waiting for you to return with the Hedoran Treasure inside of Antias’ House, by the town center. \n"},
    },
 [GetQuestName(4527)] = { --"Securing Knowledge"		-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="She asked me to hide some of them in a chest on the outskirts of town."},
        ["Stow Books in Chest"] =
            {appendText=". I should look for the chest stashed among the rocks at the top of a small waterfall on the northeastern edge of town. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I hid some of Cropsford's books and survived a goblin ambush. I should let Ufgra know."},
        ["Speak to Ufgra"] =
            {appendText=", behind the Cropsford Central Flag and the huge stone pillar in the center of the town, waiting for you to report back to her. \n"},
    },
    [GetQuestName(4540)] = { --"Timberscar Troubles"		-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="She asked me to kill the Goblin tribe's leader, which should make them less of a threat."},
        ["Kill Timberscar Leader"] =
            {appendText=", Chief Three-Fang, in a small goblin camp just south of Cropsford. I should be able to find it if I follow the road south, but there might be someone along the road who knows exactly where I need to go. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed the Goblin chieftain. I should return to Cropsford and let Ufgra know."},
        ["Talk to Ufgra gra-Gum"] =
            {appendText=", who awaits your return just behind the huge stone pillar at the center of the town. \n"},
    },
   [GetQuestName(4530)] = { --"Goblin's Delight"		-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I should talk to Chef Amadour and get some of the food he feeds the Goblin."},
        ["Talk to Chef Amadour 1"] =
            {appendText=", who is preparing food outside of a boarded-up house on the eastern outskirts of Cropsford. \n", stepTextKey="I should talk to Chef Amadour and get some of the food he feeds the Goblin."},
        [2] = 
            {appendStepText="", stepTextKey="Sugar leaf is the secret ingredient in Goblin's Delight. I've offered to collect some in return for a sample of the food."},
        ["Collect Sugar Leaf"] =
            {appendText=" \n\nI should search the area around Chef Amadour’s house on the eastern outskirts of Cropsford. \n"},
        [3] = 
            {appendStepText="", stepTextKey="I've collected enough sugar leaf. I should bring it to Chef Amadour."},
        ["Talk to Chef Amadour 2"] =
            {appendText=", who is still preparing food outside his house on the eastern outskirts of Cropsford. \n", stepTextKey="I've collected enough sugar leaf. I should bring it to Chef Amadour."},
        [4] = 
            {appendStepText="", stepTextKey="Chef Amadour gave me a bowl of Goblin's Delight. Now I need to find Aemilia Hadrianus so she can add her special ingredient."},
        ["Talk to Aemilia Hadrianus 1"] =
            {appendText=", who is still sneaking around near a bridge east of Cropsford, waiting for your return. \n", stepTextKey="Chef Amadour gave me a bowl of Goblin's Delight. Now I need to find Aemilia Hadrianus so she can add her special ingredient."},
        [5] = 
            {appendStepText="", stepTextKey="Aemilia Hadrianus has poisoned the Goblin's Delight. I need to place the food on Zich's pallet."},
        ["Poison Zich"] =
            {appendText=". The bridge is directly east of Cropsford. \n"},
        [6] = 
            {appendStepText="", stepTextKey="Zich is dead. I should let Aemilia Hadrianus know."},
        ["Talk to Aemilia Hadrianus 2"] =
            {appendText=", who is waiting for your return near the bridge east of Cropsford. She can be seen sneaking around the area. \n", stepTextKey="Zich is dead. I should let Aemilia Hadrianus know."},
    },


-- 		=========================================================================
--		  Vlastarus Dailies
-- 		=========================================================================
    [GetQuestName(4048)] = { --"The Direct Approach"		-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I should kill the necromancers in Haynote Cave."},
        ["Kill Shadowed Path Necromancers"] =
            {appendText=" \nThe cave is past the Ayleid ruins of Ceyatatar and directly east of Castle Brindle.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed several Shadowed Path necromancers. I should return to Vlastarus and tell Nelerien."},
        ["Speak to Nelerien in Vlastarus"] =
            {appendText=". He is awaiting your return inside the Worker Barracks, near the Vlastarus Central Flag. \n"},
    },
   [GetQuestName(4052)] = { --"Death to the Crone"		-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="I should kill Barasatii."},
        ["Kill Barasatii"] =
            {appendText=". The cave is southeast of the town. Follow the road south from the town until you reach the Ayleid ruins of Nornalhorst on your right, then turn left and follow the dirt path up through the foothills, past several lumber piles and rock formations, and past a Shadowed Path campsite on top of a hill. The cave entrance is across from another Shadowed Path campsite just over that hill. \n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed Barasatii. I should return to Vlastarus and let Nelerien know."},
        ["Speak to Nelerien"] =
            {appendText=", waiting for your return inside the Worker Barracks in town, near the Vlastarus Central Flag. \n"},
    },
   [GetQuestName(4065)] = { --"An Evil Presence"		-- SaipanDamashii
        [1] = 
            {appendStepText="For a lot of trades, war is an opportunity to practice, for some it even provides the materials needed. Such is the case with necromancy, but while some mages ply their trade on the battlefield or wait for the aftermath, some decided to skulk far from the front lines. These necromancers leave only desecrated graveyards and empty towns in their wake. One such graveyard, to the southwest of Vlastarus, is a place of rest no longer. ", stepTextKey="I should search the graveyard and nearby cave to discover what's causing the dead to rise."},
        ["Investigate Graveyard and Cave"] =
            {appendText=" southwest of Vlastarus, beyond the pond.\n"},
        [2] = 
            {appendStepText="", stepTextKey="The dead are rising here. I need to find the necromancer responsible and deal with him."},
        ["Kill Atirion"] =
            {appendText=" in his lair in the Howling Cave. The graveyard at the mouth of the cave feeds his experiments. For now.\n"},
        [3] = 
            {appendStepText="", stepTextKey="Now that I've killed Atirion, I should return to Jurana to tell her the news."},
        ["Talk to Jurana"] =
            {appendText=", back on the main square in Vlastarus.\n"},
    },
    [GetQuestName(4066)] = { --"Bear Essentials"		-- SaipanDamashii
        [1] = 
            {appendStepText="", stepTextKey="Nelerien asked me to head northeast of Vlastarus to kill it."},
        ["Kill Gaping Maw"] =
            {appendText=". The bear can be found in the foothills northeast of the town, near a cluster of trees surrounding a large rock formation. The path to the bear is lined with the ruins of a small stone wall. \n"},
        [2] = 
            {appendStepText="", stepTextKey="Now that Gaping Maw is dead, I should let Nelerien know."},
        ["Speak to Nelerien"] =
            {appendText=", waiting for your return inside the Worker Barracks, near the Vlastarus Central Flag. \n"},
    },
  [GetQuestName(4068)] = { --"Mementos"		-- TheoWriter
        [1] = 
            {appendStepText="Brigands roaming these once peaceful fields just take anything they can and run back to their hideouts. Even on these plains there are a lot of such places, secluded or simply forgotten. Nornalhost is one such place, an Ayleid ruin overlooking the road to the south of Vlastarus.\n", stepTextKey="Jurana asked me to travel to Nornalhorst to see if I can recover any stolen items."},
        ["Recover Stolen Items"] =
            {appendText=".\n\nI should look for anything out of place in those weathered ruins, something the bandits can use for storage.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I recovered several items from Nornalhorst. I should bring them back to Jurana in Vlastarus."},
        ["Talk to Jurana"] =
            {appendText=" back in the main square in Vlastarus.\n"},
    },
[GetQuestName(4072)] = { --"Rock Bone Diplomacy"	-- TheoWriter
        [1] = 
            {appendStepText="Rebuilding is hard, more so amid an unending war. When Vlastarus required more lumber, they went northeast, but their efforts drew the ire of a goblin tribe. The clearing the lumberjacks created is now a camp swarming with goblins, the surrounding rocks protecting them from almost every direction. Vlastarus still needs lumber, but more than that it needs safety, so ", stepTextKey="Nelerien asked me to kill some Rock Bone Goblins, to stop them from attacking the town."},
        ["Kill Rock Bone Goblins"] =
            {appendText=". \n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed some Rock Bone Goblins. I should let Nelerien know."},
        ["Speak to Nelerien"] =
            {appendText=" back in the Worker Barracks in Vlastarus.\n"},
    },
    [GetQuestName(4074)] = { --"For a Friend"	-- TheoWriter
        [1] = 
            {appendStepText="It is not just the unscrupulous mages that deign to bend the natural order of life to their will. The war itself disturbs the course of life and death, bringing back old oaths and grudges. One such unfortunate soul is the Captain that died in Juras Falls, an Ayleid ruin overlooking Castle Faregyl. ", stepTextKey="Nelerien asked me to put Captain Juras to rest."},
        ["Kill Captain Juras"] =
            {appendText=" and bring his soul peace.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed Captain Juras. I need to return to Vlastarus and let Nelerien know."},
        ["Speak to Nelerien"] =
            {appendText=" back in the Worker Barracks.\n"},
    },
    [GetQuestName(4079)] = { --"Essence of Flame"	-- TheoWriter
        [1] = 
            {appendStepText="Hate fills the air along with the smell of burning ash, which seeps in to the ground, nurturing the evil buried beneath. Some places, like the Ayleid ruins of Ceyatatar north of Vlastarus, are suffused with it, becoming a fertile ground for evil to take root. The flames of war burn brighter with every day. It is no wonder that they are now taking shape and will of their own, although subdued by their summoners. ", stepTextKey="Jurana asked me to travel there and use a special crystal to absorb the flame atronachs' essences and lessen the danger to Vlastarus."},
        ["Collect Essence of Flame"] =
            {appendText=".\n\nTrapped flame will consume itself in time, waning until it's snuffed out completely.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I've collected the flame atronach essences. Time to return to Jurana in Vlastarus."},
        ["Talk to Jurana"] =
            {appendText=", back in the main square in Vlastarus.\n"},
    },
    [GetQuestName(4081)] = { --"Silver Scales"	-- TheoWriter
        [1] = 
            {appendStepText="Desperation strikes in many forms, but with some it simply reveals their greed. The serene pond southwest of Vlastarus was once a quiet place, but now the sun barely shines through the smoke of the war. It can no longer dance on the silver scales of the fish that filled the waters of the pond before the poachers came. Perhaps Mayya can bring back some of that lost serenity using the silver scales. ", stepTextKey="Poachers at Silverscale Pond should have some that I can steal."},
        ["Collect Silver Scale"] =
            {appendText=" \n"},
        [2] = 
            {appendStepText="", stepTextKey="I stole several silver scales from the poachers. I should bring them back to Jurana."},
        ["Talk to Jurana"] =
            {appendText=" back in the main square in Vlastarus.\n"},
    },
		    [GetQuestName(4073)] = { --"Stolen Banner"			-- Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should leave the tavern."},
        ["Leave the Tavern"] =
            {appendText="."},
        [2] = 
            {appendStepText="In this southwestern town, just outside of the Watchtower Tavern, ", stepTextKey="Paints-the-Sky wishes to speak with me about something. I should see what she wants."},
        ["Talk to Paints-the-Sky 1"] =
            {appendText=". The female Argonian is working on a cart near some crates.", stepTextKey="Paints-the-Sky wishes to speak with me about something. I should see what she wants."},
        [3] = 
            {appendStepText="From this southwestern town, ", stepTextKey="I should travel to the bandit camp in the towers west of Vlastarus and recover the banner."},
        ["Collect Banner"] =
            {appendText=". Paints-the-Sky believes Talmo is a Dominion spy and that the banner should be destroyed."},
        [4] = 
            {appendStepText="At the ruined watchtowers west of the southwestern town of Vlastarus, ", stepTextKey="I recovered the banner. Talmo didn't mention that it features an Aldmeri symbol. I can return it to him or just burn it here, in a nearby campfire."},
        ["Return to Vlastarus 1"] =
            {appendText=". He should be waiting for me at the Watchtower Tavern in town.\n", stepTextKey="I recovered the banner. Talmo didn't mention that it features an Aldmeri symbol. I can return it to him or just burn it here, in a nearby campfire."},
        ["Burn Banner in Campfire"] =
            {appendText=" at the ruined watchtowers where the bandits are camped."},
        [5] = 
            {appendStepText="I left the ruined watchtowers in the southwest where ", stepTextKey="I recovered Talmo's banner. I should return it to him in Vlastarus."},
        ["Talk to Talmo"] =
            {appendText=" inside the town's Watchtower Tavern."},
        [6] = 
            {appendStepText="", stepTextKey="I burned Talmo's banner. I should return and let Paints-the-Sky know."},
        ["Return to Vlastarus 2"] =
            {appendText=", the southwestern town.", stepTextKey="I burned Talmo's banner. I should return and let Paints-the-Sky know."},
        [7] = 
            {appendStepText="", stepTextKey="I burned the banner. I should return to Paints-the-Sky in Vlastarus to let her know."},
        ["Talk to Paints-the-Sky 2"] =
            {appendText=", the female Argonian. She should be reparing a cart near the Wandering Tavern of this southwestern town.", stepTextKey="I burned the banner. I should return to Paints-the-Sky in Vlastarus to let her know."},
    },


-- ==================================================================================================================================================
--	Wrothgar - Orsinium																											Wrothgar - Orsinium
-- ==================================================================================================================================================


-- 		=========================================================================
--		  Wrothgar Main
-- 		=========================================================================

[GetQuestName(5450)] = { --"Invitation to Orsinium"		-- Jordakai
		[1] = 
			{appendStepText="", stepTextKey="I received an invitation to Orsinium and have been instructed to visit the Wrothgar ambassador in the city of Daggerfall, Davon's Watch, or Vulkhel Guard. I should speak to the ambassador when I'm ready to go."},
		["Talk to Wrothgar Ambassador"] =
			{appendText=". In the city of my choice, she can be found studying a map of Wrothgar near a sturdy wagon. Her echatere, a tusked, pointy-hoofed, six-legged beast with a massive antler, is resting in anticipation of a long journey."},
		[2] = 
			{appendStepText="", stepTextKey="Once I enter Wrothgar, I need to find the caravan."},
		["Rendezvous with the Caravan"] =
			{appendText=". It should be along the road, north of Merchant's Gate and south of the wayshrine."},
		[3] = 
			{appendStepText="Eveli Sharp-Arrow, a Wood Elf adventurer with an invitation, told me about the Winterborn Reachmen ambushing the caravan.\n\nIn the eastern hills and mountains between Merchant's Gate and its wayshrine, ", stepTextKey="I need to find Chief Bazrag and help rescue the Orc peasants from the Winterborn marauders."},
		["Rescue the Orc Peasants"] =
			{appendText=". They may be scattered, perhaps near the stone tower."},
		[4] = 
			{appendStepText="North of Merchant's Gate, I followed the loop of road to the east and reached a stone tower. ", stepTextKey="The group of Orc peasants I rescued said that there was another group of peasants hiding in the cave near the waterfall. I should go rescue them as well."},
		["Rescue the Remaining Orc Peasants"] =
			{appendText=". The cave is hidden by large icicles, up a snowy incline north of the stone tower."},
		[5] = 
			{appendStepText="Southeast of Merchant's Gate Wayshrine, behind the frozen waterfall, I found the cave. ", stepTextKey="The Orcs in the cave were frozen by the warlord Ice-Heart. Chief Bazrag is attempting to recover the stolen supplies, though. I should look around and try to help him pick up the trail."},
		["Discover the Location of the Stolen Supplies"] =
			{appendText=" by thoroughly searching the crates and barrels near the river by the frozen waterfall."},
		[6] = 
			{appendStepText="Near Merchant's Gate Wayshrine, or perhaps on the road heading north, ", stepTextKey="I should find Chief Bazrag and show him the note I found that talked about the stolen supplies."},
		["Show the Note to Chief Bazrag"] =
			{appendText="."},
		[7] = 
			{appendStepText="North of Merchant's Gate Wayshrine, on the road going north towards the southeastern city of Orsinium, I spoke with Chief Bazrag of the Fharun clan. ", stepTextKey="Chief Bazrag asked me to try to uncover the traitor and track down the stolen supplies. He suggested I start my search at the inn in Orsinium."},
		["Visit the Inn in Orsinium"] =
			{appendText=". When I reach the city, I should check my map to find an inn or tavern. That would be a good place to start asking around about someone with a lot of gold to spend."},
		[8] = 
			{appendStepText="I entered The Greedy Gut in the city. ", stepTextKey="I should ask around in the inn and see if anyone can lead me to the traitor."},
		["Ask About the Traitor"] =
			{appendText="."},
		[9] = 
			{appendStepText="I spoke with a bartender at The Greedy Gut in Orsinium. ", stepTextKey="It seems that a trader who's friendly with a group of Khajiit has recently come into possession of a good deal of gold. He wears a very distinctive fragrance that should help me find him."},
		["Find Gulug"] =
			{appendText=". It seems I have picked up the scent of a trail in this city."},
		[10] = 
			{appendStepText="In the streets of Orsinium, my nose was ambushed. ", stepTextKey="There's certainly an odd smell in the air. I should follow the scent and see if it leads me to Gulug."},
		["Follow the Scent"] =
			{appendText=" through the city. I may find a Khajiit trader or others who know where he went."},
		[11] = 
			{appendStepText="North of King's Cornerclub, across the road and upstairs, is Ufgel's. That's where ", stepTextKey="I found Gulug in a bath house in Orsinium. I should confront him and find out what he knows about the stolen supplies."},
		["Confront the Traitor, Gulug"] =
			{appendText=", who is bathing downstairs."},
		[12] = 
			{appendStepText="In Orsinium's southeast is the King's palatial residence, Scarp Keep. ", stepTextKey="I should go to the keep and let them know what I found out. Besides, the letter I received said I should present myself to Forge-Mother Alga when I arrive in Orsinium."},
		["Report to the Keep"] =
			{appendText="."},
		[13] = 
			{appendStepText="In the city's southeast, at the top of the stairs leading to the palatial Scarp Keep, ", stepTextKey="I see a Priestess of Trinimac welcoming adventurers to Orsinium. I should speak to her and see if she can direct me to Forge-Mother Alga."},
		["Talk to High Priestess Solgra 1"] =
			{appendText=" wearing fine robes.", stepTextKey="I see a Priestess of Trinimac welcoming adventurers to Orsinium. I should speak to her and see if she can direct me to Forge-Mother Alga."},
		[14] = 
			{appendStepText="In the city's southeast, at the top of the stairs leading to the palatial Scarp Keep, ", stepTextKey="I told High Priestess Solgra about the traitor and the location of the stolen supplies. Now I need to see if she can direct me to Forge-Mother Alga."},
		["Talk to High Priestess Solgra 2"] =
			{appendText=" wearing fine robes.", stepTextKey="I told High Priestess Solgra about the traitor and the location of the stolen supplies. Now I need to see if she can direct me to Forge-Mother Alga."},
		[15] = 
			{appendStepText="In the city's southeast, at the top of the stairs leading to the palatial Scarp Keep, ", stepTextKey="I told High Priestess Solgra where to find the stolen supplies, but I left out Gulug's name as the traitor. Now I need to see if she can direct me to Forge-Mother Alga."},
		["Talk to High Priestess Solgra 3"] =
			{appendText=" wearing fine robes.", stepTextKey="I told High Priestess Solgra where to find the stolen supplies, but I left out Gulug's name as the traitor. Now I need to see if she can direct me to Forge-Mother Alga."},
	},

	[GetQuestName(5329)] = { --"For King and Glory"				-- Jordakai
		[1] = 
			{appendStepText="There is an old Breton fort southwest of Orsinium in the south-central mountains. ", stepTextKey="I should make my way to Frostbreak Fortress to meet with King Kurog. I need to tell him that the stolen supplies are being held there."},
		["Travel to Frostbreak Fortress"] =
			{appendText=", one of the last strongholds from the days of Reachmen rule in Wrothgar, during the reign of the Longhouse Emperors. \n\nI may wish to speak with High Priestess Solgra near Scarp Keep again before leaving Orsinium."},
		[2] = 
			{appendStepText="South of Frostbreak Ridge Wayshrine, ", stepTextKey="I arrived at the siege camp outside Frostbreak Fortress. I should find King Kurog and speak to him."},
		["Talk to King Kurog 1"] =
			{appendText=" in his tent at the west end of the siege camp. He's doing the things he loves - battles and eating. \n\nIf I haven't done so yet, I should also speak with Siege Commander Dulph in front of his tent just north of The King's Mess tent.", stepTextKey="I arrived at the siege camp outside Frostbreak Fortress. I should find King Kurog and speak to him."},
		[3] = 
			{appendStepText="South of Frostbreak Ridge Wayshrine, I found King Kurog enjoying a meal in the siege camp. He is ready to defeat Urfon Ice-Heart, the last Reachmen warlord in Wrothgar. ", stepTextKey="We need to find a way inside the Fortress."},
		["Find A Way Inside Frostbreak Fortress"] =
			{appendText=". The Winterborn Reachmen have briarhearts and harpies helping them defend the fortress. I am sure the king will enjoy a good fight. I should make sure I have all my allies with me before entering the fortress."},
		[4] = 
			{appendStepText="We have worked our way up through the fortress grounds and found a doorway lit by a single torch, next to a large fortress gate. We are in the upper southern courtyard area near a Winterborn camp. ", stepTextKey="King Kurog wants me to lead the way as we search Frostbreak Fortress and seek out the stolen supplies and the Winterborn warlord, Urfon Ice-Heart."},
		["Find Urfon Ice-Heart"] =
			{appendText=", the last of the old Reachmen leaders in Wrothgar. He is probably deep within the safety of the fortress."},
		[5] = 
			{appendStepText="In the far northwest of Frostbreak Fortress, north of the Briarheart Tree, we found Ice-Heart's Lair. ", stepTextKey="I should help King Kurog kill the Winterborn warlord, Urfon Ice-Heart."},
		["Kill Urfon Ice-Heart"] =
			{appendText="."},
		[6] = 
			{appendStepText="In the far northwest of Frostbreak Fortress there is an icy lair. ", stepTextKey="Urfon Ice-Heart is dead. I should speak to King Kurog before we leave the fortress."},
		["Talk to King Kurog 2"] =
			{appendText=".", stepTextKey="Urfon Ice-Heart is dead. I should speak to King Kurog before we leave the fortress."},
		[7] = 
			{appendStepText="", stepTextKey="King Kurog asked me to meet him at Scarp Keep the next time I'm back in Orsinium."},
		["Return to Scarp Keep"] =
			{appendText=" in the eastern part of the city after finishing any other tasks I may have at the fortress. If he is not in the entry hall, I can look for him in the throne room."},
		[8] = 
			{appendStepText="I am back in Orsinium and ", stepTextKey="I returned to the keep to find some kind of meeting taking place. I should speak to Forge-Mother Alga as soon as an opportunity presents itself."},
		["Talk to Forge-Mother Alga"] =
			{appendText=" on the dais of Scarp Keep's Throne Room. It seems the chiefs and the priestess are at odds."},
		[9] = 
			{appendStepText="In Orsinium's Scarp Keep, ", stepTextKey="King Kurog has arrived. I should listen to what he has to say."},
		["Listen to King Kurog's Exchange"] =
			{appendText=" with the chieftains."},
		[10] = 
			{appendStepText="The remaining chieftains left Scarp Keep's Throne Room. ", stepTextKey="The meeting didn't go as King Kurog planned. I should talk to him."},
		["Talk to King Kurog 3"] =
			{appendText=" where he stands near his throne with Ice-Heart's sword in hand. There's a bit of blood on its blade.", stepTextKey="The meeting didn't go as King Kurog planned. I should talk to him."},
		[11] = 
			{appendStepText="The remaining chieftains left Scarp Keep's Throne Room. ", stepTextKey="The meeting didn't go as King Kurog planned. I should talk to him."},
		["Talk to King Kurog 4"] =
			{appendText=" where he stands near his throne with Ice-Heart's sword in hand. There's a bit of blood on its blade.", stepTextKey="The meeting didn't go as King Kurog planned. I should talk to him."},
	},
	[GetQuestName(5318)] = { --"The Hidden Harvest"				-- Jordakai
		[1] = 
			{appendStepText="South of Frostbreak Ridge Wayshrine near the old Breton fort, ", stepTextKey="I need to report to Siege Commander Dulph within the siege camp to find out how I can help the Orc soldiers get into Frostbreak Fortress."},
		["Report to Siege Commander Dulph"] =
			{appendText="."},
		[2] = 
			{appendStepText="South of Frostbreak Ridge Wayshrine in the siege camp near the fortress, ", stepTextKey="I should speak to Siege Commander Dulph and see what kind of help he needs."},
		["Talk to Siege Commander Dulph"] =
			{appendText=", standing in front of his tent just north of The King's Mess tent. \n\nIf I haven't already helped King Kurog here at the fortress, I should speak with him in his tent at the west end of the siege camp."},
		[3] = 
			{appendStepText="South of Frostbreak Ridge Wayshrine, ", stepTextKey="I need to get inside Frostbreak Fortress and find the two squads of Orc soldiers Siege Commander Dulph sent in to distract the harpies and destroy the source of the briarheart warriors."},
		["Rendezvous with the Orc Squads"] =
			{appendText="."},
		[4] = 
			{appendStepText="Inside a barricaded tower, I found the squad assigned to destroy the harpy aeries. ", stepTextKey="I need to clear a path to the two towers with clear lines of sight to the harpy aeries. Then Eveli can mark the targets with a flaming arrow so that the catapults can destroy the aeries."},
		["Destroy the Harpy Aeries"] =
			{appendText=".\n\nFrom this position in the barricaded tower we will need to go to the southeast for one tower and to the southwest for the other. At the top, we should be able to see a taller tower topped with a harpy aerie - a large nest.\n\nI should talk to Eveli Sharp-Arrow before we head out. And I may need to remind her when to shoot her flaming arrow at the top of each tower."},
		[5] = 
			{appendStepText="", stepTextKey="Now that the harpy aeries have been destroyed, I should look for the alchemist and the squad escorting him. They should be trying to find a way into the fortress."},
		["Find the Alchemist"] =
			{appendText=". He is likely hiding from the Winterborn in the upper southwest grounds if his soldiers died protecting him."},
		[6] = 
			{appendStepText="In a corner hidden by a large rock, beyond a Winterborn campsite in the upper southwest courtyard, ", stepTextKey="I found the alchemist and his soldier escort. I should talk to the alchemist and find out how he wants to proceed."},
		["Talk to Alinon the Alchemist 1"] =
			{appendText=". He is the one that knows how to defeat the briarheart zombies.", stepTextKey="I found the alchemist and his soldier escort. I should talk to the alchemist and find out how he wants to proceed."},
		[7] = 
			{appendStepText="From where I found him hiding behind a large rock in a corner of the fort's upper southwest courtyard, ", stepTextKey="I need to escort Alinon the Alchemist into Frostbreak Fortress."},
		["Get Alinon Inside the Fort"] =
			{appendText=". South of the nearby Winterborn campsite is a doorway illuminated by a single torch and a banner standing guard. It is adjacent to a large fortress gate."},
		[8] = 
			{appendStepText="", stepTextKey="We're inside Frostbreak Fortress. Alinon wants us to look around and see if we notice any unusual plants or flowers. He thinks there must be something to lead us to the source of the briarhearts."},
		["Help Investigate the Briarheart"] =
			{appendText="."},
		[9] = 
			{appendStepText="We entered the fortress through a doorway from the southern, outer courtyard. I see Eveli on her guard. ", stepTextKey="It looks like Alinon found something important. I should talk to him and find out what he discovered."},
		["Talk to Alinon the Alchemist 2"] =
			{appendText=", not far from the foot of the stairs by the entrance. He stands with his torch, looking at a sapling.", stepTextKey="It looks like Alinon found something important. I should talk to him and find out what he discovered."},
		[10] = 
			{appendStepText="", stepTextKey="Alinon the Alchemist claims that the source of the briarheart warriors is a large plant or tree. But before we can destroy the source, we need to weaken its defenses by burning the corrupted saplings scattered throughout the fortress."},
		["Destroy Briarheart Saplings"] =
			{appendText=". I think I will start by looking in this southeastern area of the fortress."},
		[11] = 
			{appendStepText="Inside the fortress, in the southeast area, ", stepTextKey="I burned a number of the briarheart saplings and Alinon's plan appears to be working. I should return to Alinon and Eveli and determine our next step."},
		["Return to Alinon and Eveli"] =
			{appendText=". They should be near the entrance, back where the first root-sapling was found."},
		[12] = 
			{appendStepText="Near the entrance inside the fortress, I found Eveli, but ", stepTextKey="Alinon has disappeared. I need to find him in order to finish our mission."},
		["Find Alinon the Alchemist"] =
			{appendText=", wherever he went. Eveli thought I should go to the northwest to look for him."},
		[13] = 
			{appendStepText="In a northern room of the fortress, there he was... suspended in a cage above a roaring fire. Well, ", stepTextKey="I found Alinon. I should talk to him and find out how he got into this predicament."},
		["Talk to Alinon the Alchemist 3"] =
			{appendText=". He does seem anxious to talk.", stepTextKey="I found Alinon. I should talk to him and find out how he got into this predicament."},
		[14] = 
			{appendStepText="In the fortress' northern room, ", stepTextKey="Eveli Sharp-Arrow has arrived. Maybe she can rescue Alinon while I recover his missing alchemy bag and the elixir to destroy the source of the briarheart. I should talk to her."},
		["Talk to Eveli Sharp-Arrow"] =
			{appendText=" as she stares up at the roasting alchemist."},
		[15] = 
			{appendStepText="In the northern room of the fortress, Eveli will rescue the caged alchemist. ", stepTextKey="To put an end to the briarheart warriors, I need to use Alinon's elixir to destroy the tree that is the source of the briarhearts."},
		["Destroy the Briarheart Tree"] =
			{appendText=". It appears that there is a large courtyard to the west. I'll bet the briarheart tree is there.\n\nSince I haven't seen any hagravens with Alinon's alchemical bag yet, it must be in that area, too. Or maybe in the cavern to the south."},
		[16] = 
			{appendStepText="", stepTextKey="I should exit the fortress and make sure that Eveli and Alinon the Alchemist are all right."},
		["Exit the Fortress"] =
			{appendText=" after finishing any other tasks I may have here. There is a doorway to the west of the destroyed Briarheart Tree that I should use to find Eveli and Alinon."},
		[17] = 
			{appendStepText="After leaving the fortress through the southwestern tower, I found the alchemist and Eveli outside near a waterfall. Its river flows north under a makeshift bridge and falls over a cliff to a valley far below. ", stepTextKey="I should talk to Alinon the Alchemist and make sure the source of the briarhearts was really destroyed."},
		["Talk to Alinon the Alchemist 4"] =
			{appendText=". He is conversing with Eveli and an Orc soldier.", stepTextKey="I should talk to Alinon the Alchemist and make sure the source of the briarhearts was really destroyed."},
	},

	[GetQuestName(5447)] = { --"A King-Sized Problem"				-- Jordakai
		[1] = 
			{appendStepText="", stepTextKey="I should go to the King's Cornerclub in Orsinium and report to King Kurog, as requested."},
		["Talk to King Kurog 1"] =
			{appendText=" to see what he wants. If he's at his private club, I bet he's enjoying a good drink."},
		[2] = 
			{appendStepText="At his table, ", stepTextKey="King Kurog wants to speak to me about problems that require a personal approach."},
		["Talk to King Kurog 2"] =
			{appendText=" as he enjoys a mug of ice-berry ale."},
		[3] = 
			{appendStepText="", stepTextKey="King Kurog's shield-wives entered the tavern to give him a report concerning an attack inside the city. I should listen to what they have to say."},
		["Listen to the Shield-Wives' Report"] =
			{appendText="."},
		[4] = 
			{appendStepText="The king's mother joined us in the King's Cornerclub. ", stepTextKey="Forge-Mother Alga thinks the attack on the Trinimac temple might be a trap. She wants to discuss a different approach to this problem. I should talk to her."},
		["Talk to Forge-Mother Alga 1"] =
			{appendText=" to see what she recommends.", stepTextKey="Forge-Mother Alga thinks the attack on the Trinimac temple might be a trap. She wants to discuss a different approach to this problem. I should talk to her."},
		[5] = 
			{appendStepText="", stepTextKey="Fanatics have taken control of the Trinimac temple in Orsinium and are holding hostages. Forge-Mother Alga thinks it's a trap for King Kurog. She asked me to go to the temple in his place and rescue the hostages."},
		["Go to the Temple"] =
			{appendText=" of Ire, the city's majestic western structure, which also houses the Mages Guild and magic-related shops. The temple's main double-door entrance, flanked with banners of purple and gold, is on the north side of the building, off the main road heading south out of the city. A crowd has gathered at its steps."},
		[6] = 
			{appendStepText="I arrived at the Temple of Ire's main doors, ", stepTextKey="I see that King Kurog's soldiers have taken up a position outside the temple. I should talk to the captain and see what the situation is."},
		["Talk to Captain Zugnor"] =
			{appendText=", who appears to be in charge of crowd control as a couple of soldiers try to get inside. I wonder if the Mages Guild in this building is affected."},
		[7] = 
			{appendStepText="I spoke with the guard captain on the front steps of the Temple of Ire's main doors, ", stepTextKey="The fanatics have barred the temple's main entrance from the inside. I need to find another way to get inside. The captain suggested there might be a back entrance. I should search around for that."},
		["Find a Way Into the Temple"] =
			{appendText=". The captain has not heard from the soldiers he sent to investigate. Maybe Eveli has an idea about getting inside. She is at a wagon across from the temple's main doors. \n\nI should go up the stairs to the left of the Mages Guild's main entrance, across from the city's waterwheel. Heading north, I should pass through an angular arch and go down the stairs near Fabasi's shop. Then continue around to the north to look for another way into the Temple of Ire."},
		[8] = 
			{appendStepText="West of the House of Orsimer Glories and up the stairs, I followed a trail of dead soldiers, heading downstairs in front of the enchanter's shop. A little farther and I met a priest of the temple at the stairs leading up to the back entrance. ", stepTextKey="Now that I'm inside the Temple of Ire, I need to avoid the torch-bearer patrols and acquire the key to unlock the rectory where the fanatics are holding the captured priests. The key may be in their commander's possession."},
		["Get the Key to the Rectory"] =
			{appendText=". From where I entered I do not see any place that might have a desk or table with a lockbox for a key. Perhaps it is below me. \n\nThe torch-bearers seem to have assigned routes. I can use that to my advantage."},
		[9] = 
			{appendStepText="Across from the city's waterwheel and up the stairs to the left of the guildhall entrance, I circled around the west side, going down the stairs in front of Fabasi's shop. I went a little farther north and up more stairs to find the back door. I am inside the Temple of Ire and ", stepTextKey="I have the key that unlocks the door to the rectory. Now I need to get inside and set the captured priests free."},
		["Enter the Temple Rectory"] =
			{appendText=". The Rectory is likely through the tall doors to the south on the temple's ground floor."},
		[10] = 
			{appendStepText="", stepTextKey="Inside the rectory, I found the captured priests. I need to save Priest Uugus so I can ask him about High Priestess Solgra."},
		["Save Priest Uugus"] =
			{appendText="."},
		[11] = 
			{appendStepText="", stepTextKey="High Priestess Solgra went to defend the temple sanctuary. I need to find her and make sure the fanatics don't hurt her."},
		["Find High Priestess Solgra"] =
			{appendText=" further inside the Rectory."},
		[12] = 
			{appendStepText="", stepTextKey="I found High Priestess Solgra, but one of the fanatics has threatened to kill her. I need to save her."},
		["Rescue High Priestess Solgra"] =
			{appendText="."},
		[13] = 
			{appendStepText="", stepTextKey="I rescued High Priestess Solgra. I should talk to her and see what she can tell me about the attack on the temple."},
		["Talk to High Priestess Solgra"] =
			{appendText=" near the altar."},
		[14] = 
			{appendStepText="In the city's Temple of Ire, I learned that ", stepTextKey="High Priestess Solgra suspects Chief Bazrag is behind the attack on the temple. I need to get the news to the forge-mother as soon as possible."},
		["Talk to Forge-Mother Alga 2"] =
			{appendText=". I should leave the Rectory and look for the King's mother.", stepTextKey="High Priestess Solgra suspects Chief Bazrag is behind the attack on the temple. I need to get the news to the forge-mother as soon as possible."},
		[15] = 
			{appendStepText="In the city's Temple of Ire, I learned that ", stepTextKey="High Priestess Solgra suspects Chief Bazrag is behind the attack on the temple. I need to get the news to the forge-mother as soon as possible."},
		["Talk to Forge-Mother Alga 3"] =
			{appendText=". I should leave the Rectory and look for the King's mother.", stepTextKey="High Priestess Solgra suspects Chief Bazrag is behind the attack on the temple. I need to get the news to the forge-mother as soon as possible."},
	},
    [GetQuestName(5458)] = { --"In the Name of the King"				-- Jordakai
        [1] = 
            {appendStepText="In Orsinium, I need to go to the keep on the east side of the city. ", stepTextKey="I should go to the throne room and speak with King Kurog."},
        ["Talk to King Kurog 1"] =
            {appendText=".", stepTextKey="I should go to the throne room and speak with King Kurog."},
        [2] = 
            {appendStepText="In the keep in eastern Orsinium, ", stepTextKey="I should talk to King Kurog to find out more about what he wants me to do to facilitate his Great Moot."},
        ["Talk to Kurog"] =
            {appendText=" as he sits upon his throne."},
        [3] = 
            {appendStepText="As he sat upon his throne in Orsinium's keep, King Kurog shared his ideas about getting some of the clan chiefs to gather. ", stepTextKey="The clans I need to aid include Tumnosh, Morkul, and Shatul. Once I help them in the king's name, Kurog believes their chiefs will be obligated to attend the Great Moot."},
        ["Recruit the Chief of Clan Tumnosh"] =
            {appendText=", Ramash. His clan mines stone from the Graystone Quarry's pit, southwest of Orsinium and east of Frostbreak Fortress.\n"},
        ["Recruit the Chief of Clan Morkul"] =
            {appendText=", Abzug. Known for their exceptional blacksmithing skills, their clanhold is northwest of Orsinium, near the coast just south of the icy northern shores.\n"},
        ["Recruit the Chief of Clan Shatul"] =
            {appendText=". They are expert at raising echatere and are reliable providers of food. The clan's tents are north and east of Orsinium's northern gate. There is a wayshrine bearing the clan's name west of their settlement.\n\nIf I have already helped any of these clans before King Kurog spoke with me, I must return to the clan's home to invite their Chief to the Great Moot."},
        [4] = 
            {appendStepText="I have helped the clans of Tumnosh, Morkul, and Shatul. ", stepTextKey="The clan chiefs have all agreed to attend the Great Moot. I should report back to King Kurog at his cornerclub in Orsinium and give him the news."},
        ["Report to King Kurog"] =
            {appendText="."},
        [5] = 
            {appendStepText="", stepTextKey="The clan chiefs have all agreed to attend King Kurog's Great Moot. I should talk to King Kurog."},
        ["Talk to King Kurog 2"] =
            {appendText=" at the King’s Cornerclub in Orsinium.", stepTextKey="The clan chiefs have all agreed to attend King Kurog's Great Moot. I should talk to King Kurog."},
    },

	[GetQuestName(5326)] = { --"Quarry Conundrum"				-- Jordakai
		[1] = 
			{appendStepText="Southwest of Orsinium, I found a large mining operation. ", stepTextKey="I should go down into Graystone Quarry to see if I can find out what happened there and check on the quarry workers."},
		["Investigate the Quarry"] =
			{appendText=" pit to the south of the work village. I should search for clues in its depths."},
		[2] = 
			{appendStepText="I climbed down into Graystone Quarry Depths and ", stepTextKey="I met one of the Orcs that accompanied the chief on his aborted rescue mission. He says that hunt-wife Bolgar is still in the quarry, looking for the High Elf and her daughter. I need to find her."},
		["Find Hunt-Wife Bolgar"] =
			{appendText=". If she survived, she will undoubtedly be hiding from the constructs. I should search every nook and cranny."},
		[3] = 
			{appendStepText="In the Dwemer depths, I found the chief's wife, injured, in a nook next to some stairs. ", stepTextKey="Hunt-Wife Bolgar asked me to continue searching for her daughter, Shabon. She thinks I'll find her with the High Elf."},
		["Find Shabon"] =
			{appendText=". She and the Altmer will be farther into the Dwemer ruin. And probably deeper, to a place with water where they could survive for some time."},
		[4] = 
			{appendStepText="In the Dwemer depths' southern cavern, ", stepTextKey="I found the hunt-wife's daughter, Shabon. She said that the High Elf went to investigate the central structure. I should go in there and locate him."},
		["Find the High Elf"] =
			{appendText=". This place is like an oasis within the ruins. I should head up the Dwemer path to the center of this deep quarry.\n"},
		[5] = 
			{appendStepText="In the center of the depths' large southern cavern, I found the High Elf in a Dwemer area studying a drawing of an ancient machine. ", stepTextKey="Neramo believes a control center operates the Dwarven constructs and that it's located somewhere in the ruin. I should look for the control center."},
		["Find the Dwarven Control Center"] =
			{appendText=", which must be to the north and east of this southern cavern. Maybe the drawing is similar to the control center Neramo mentioned."},
		[6] = 
			{appendStepText="In the easternmost chamber of the Dwemer ruin in Graystone Quarry Depths, ", stepTextKey="I found the Dwarven control center and so did Neramo. I should talk to him."},
		["Talk to Neramo 1"] =
			{appendText=" to see if he has any idea how this ancient machinery works.", stepTextKey="I found the Dwarven control center and so did Neramo. I should talk to him."},
		[7] = 
			{appendStepText="", stepTextKey="I need to strike the kinetic resonators to rotate the rings and adjust the lenses until they align with the emitters. That should unlock the Orb of Illumination and open the way to the construct control room."},
		["Solve the Puzzle of the Orb of Illumination"] =
			{appendText=" by striking each of the three kinetic resonators: south, central, and north. Perhaps each resonator controls a specific ring of lenses. I may need to strike a resonator more than once to get it into the correct position."},
		[8] = 
			{appendStepText="Within the eastern chamber of the depths' Dwemer ruin, ", stepTextKey="I successfully calibrated the Orb of Illumination and unlocked the chest. I should talk to Neramo to see what he found inside."},
		["Talk to Neramo 2"] =
			{appendText=".", stepTextKey="I successfully calibrated the Orb of Illumination and unlocked the chest. I should talk to Neramo to see what he found inside."},
		[9] = 
			{appendStepText="", stepTextKey="Neramo can now prevent the Dwarven constructs from attacking the quarry. I should go back to the surface and let the Orcs know that it's safe to return to work."},
		["Talk to Forge-Wife Kharza 1"] =
			{appendText=" in Graystone Quarry's pit near the entrance to the Depths.", stepTextKey="Neramo can now prevent the Dwarven constructs from attacking the quarry. I should go back to the surface and let the Orcs know that it's safe to return to work."},
		[10] = 
			{appendStepText="In the pit at Graystone Quarry, ", stepTextKey="Neramo brought some of the Dwarven machines out of the ruins as some sort of gift to make up for the trouble he caused, but the Orcs want to destroy them and him, I should talk to Kharza and try to make this right."},
		["Talk to Forge-Wife Kharza 2"] =
			{appendText=".", stepTextKey="Neramo brought some of the Dwarven machines out of the ruins as some sort of gift to make up for the trouble he caused, but the Orcs want to destroy them and him, I should talk to Kharza and try to make this right."},
		[11] = 
			{appendStepText="", stepTextKey="I persuaded the Tumnosh clan to utilize the Dwarven constructs to work Graystone Quarry until they can recover from the losses they suffered. I should talk to Forge-Wife Kharza and complete the deal."},
		["Talk to Forge-Wife Kharza 3"] =
			{appendText=" in the quarry's pit.", stepTextKey="I persuaded the Tumnosh clan to utilize the Dwarven constructs to work Graystone Quarry until they can recover from the losses they suffered. I should talk to Forge-Wife Kharza and complete the deal."},
		[12] = 
			{appendStepText="In the pit of Graystone Quarry, ", stepTextKey="I suggested that the Tumnosh clan exile Neramo and send him and the Dwarven constructs away. I should talk to Forge-Wife Kharza and complete the deal."},
		["Talk to Forge-Wife Kharza 4"] =
			{appendText=".", stepTextKey="I suggested that the Tumnosh clan exile Neramo and send him and the Dwarven constructs away. I should talk to Forge-Wife Kharza and complete the deal."},
		[13] = 
			{appendStepText="In the pit of Graystone Quarry, ", stepTextKey="I suggested that the Tumnosh clan petition the king and ask him what to do with the Dwarven constructs. I should talk to Forge-Wife Kharza and complete the deal."},
		["Talk to Forge-Wife Kharza 5"] =
			{appendText=".", stepTextKey="I suggested that the Tumnosh clan petition the king and ask him what to do with the Dwarven constructs. I should talk to Forge-Wife Kharza and complete the deal."},
	},
[GetQuestName(5441)] = { --"The Hand of Morkul"				-- Jordakai
		[1] = 
			{appendStepText="In Morkul Stronghold, Wrothgar's west-central town, I stopped by the blacksmith. ", stepTextKey="Lazghal is very worried for her daughter. I agreed to look for Ashaka in Morkul Descent. I should travel there."},
		["Travel to Morkul Descent"] =
			{appendText=", a cavern at the base of the cliffs east of Morkul Stronghold, beyond Icy Shores Wayshrine, at the end of a snowy footpath. It is rumored to contain ancient relics of the Morkul clan. \n\nLazghal mentioned that Ashaka's younger sister is King Kurog's forge-wife."},
		[2] = 
			{appendStepText="I found the entrance to the cavern at the base of the cliffs at the end of a snowy footpath, east of Icy Shores Wayshrine. ", stepTextKey="According to Lazghal, her daughter is somewhere in Morkul Descent. I should search for Ashaka."},
		["Search for Ashaka"] =
			{appendText=" in the caverns of this ancient, icy place."},
		[3] = 
			{appendStepText="East of Icy Shores Wayshrine, ", stepTextKey="I found Ashaka in Morkul Descent, but she seems wounded. I should speak with her."},
		["Talk to Ashaka 1"] =
			{appendText=" at the stone bier in the southern end of the cavern.", stepTextKey="I found Ashaka in Morkul Descent, but she seems wounded. I should speak with her."},
		[4] = 
			{appendStepText="At the southern end of the cavern known as Morkul Descent that is east of Icy Shores Wayshrine, I spoke with Lazghal's daughter. ", stepTextKey="Ashaka seeks Morkuldin, the ancient home of her clan, which holds a relic known as the Hand of Morkul. I should help her search for the hidden entrance. She believes the nearby statues are clues to finding Morkuldin."},
		["Open the Way to Morkuldin"] =
			{appendText=". Ashaka mentioned something about three heroes from a poem she heard. I should see what I can learn."},
		[5] = 
			{appendStepText="In Morkul Descent east of Icy Shores Wayshrine, I lit the braziers to reveal an entrance to the east of this southernmost cavern. ", stepTextKey="Ashaka and I found our way into Morkuldin. I should explore the lost home of the Morkul clan."},
		["Explore Morkuldin"] =
			{appendText=". Perhaps we will find the relic Ashaka seeks."},
		[6] = 
			{appendStepText="In Morkul Descent east of Icy Shores Wayshrine, we entered Morkuldin from the southernmost cavern. The ancient ruins are spectacular. \n\n", stepTextKey="I discovered a great forge, and what seems to be the Hand of Morkul. Unfortunately, it is trapped within the forge itself. I should speak with Ashaka and see if she has any ideas on how to release it."},
		["Talk to Ashaka 2"] =
			{appendText=".", stepTextKey="I discovered a great forge, and what seems to be the Hand of Morkul. Unfortunately, it is trapped within the forge itself. I should speak with Ashaka and see if she has any ideas on how to release it."},
		[7] = 
			{appendStepText="In Morkul Descent east of Icy Shores Wayshrine, beyond the southernmost cavern, we found the Hand of Morkul in the ancient forge. ", stepTextKey="Ashaka asked me to rekindle Morkuldin's great forge. She thinks that doing so will release the Hand of Morkul. I should activate the blast furnace and the bellows."},
		["Activate the Blast Furnace"] =
			{appendText=". The furnace will need to generate heat. It is likely some place with a great heat source."},
		["Activate the Bellows"] =
			{appendText=". There should be some sort of mechanism to control the flow of air for the furnace. Perhaps I will find locks or counterbalances. \n\nMaybe I can find things that will help me understand more about this place."},
		[8] = 
			{appendStepText="In Morkul Descent east of Icy Shores Wayshrine, beyond the southernmost cavern, ", stepTextKey="I rekindled Morkuldin's great forge. I should return to Ashaka."},
		["Return to Ashaka"] =
			{appendText=". She should be by the Hand of Morkul in the first chamber we entered."},
		[9] = 
			{appendStepText="In Morkul Descent east of Icy Shores Wayshrine, beyond the southernmost cavern, the secrets of Morkuldin were revealed. ", stepTextKey="Ashaka discovered a terrible truth. The Hand of Morkul was long ago locked away by her clan because it was the centerpiece of a bloodforge—a terrible device that fused living captives into weapons and armor. I should speak with her."},
		["Talk to Ashaka 3"] =
			{appendText=" about what we have learned.", stepTextKey="Ashaka discovered a terrible truth. The Hand of Morkul was long ago locked away by her clan because it was the centerpiece of a bloodforge—a terrible device that fused living captives into weapons and armor. I should speak with her."},
		[10] = 
			{appendStepText="At the blood-forge of Morkuldin, ", stepTextKey="I convinced Ashaka to return the Hand of Morkul to her clan. I should meet her at Morkul Stronghold."},
		["Return to Morkul Stronghold 1"] =
			{appendText=", the west-central town near the coast.", stepTextKey="I convinced Ashaka to return the Hand of Morkul to her clan. I should meet her at Morkul Stronghold."},
		[11] = 
			{appendStepText="", stepTextKey="I should meet Ashaka in Morkul Stronghold. She said she would wait for my arrival to address her clan about the Hand of Morkul's fate."},
		["Meet Ashaka"] =
			{appendText=". She is standing on the platform near the longhouse in town."},
		[12] = 
			{appendStepText="", stepTextKey="Morkul clan seemed content with Ashaka's explanation. I should speak with her before they depart."},
		["Talk to Ashaka 4"] =
			{appendText=" on the platform in front of the longhouse in town.", stepTextKey="Morkul clan seemed content with Ashaka's explanation. I should speak with her before they depart."},
		[13] = 
			{appendStepText="At the blood-forge of Morkuldin, ", stepTextKey="I convinced Ashaka to hide the Hand of Morkul from her clan. I should meet her at Morkul Stronghold."},
		["Return to Morkul Stronghold 2"] =
			{appendText=", the town near the west-central coast.", stepTextKey="I convinced Ashaka to hide the Hand of Morkul from her clan. I should meet her at Morkul Stronghold."},
		[14] = 
			{appendStepText="", stepTextKey="Morkul clan seemed content with Ashaka's explanation. I should speak with her before they depart."},
		["Talk to Ashaka 5"] =
			{appendText=" on the platform in front of the longhouse in town.", stepTextKey="Morkul clan seemed content with Ashaka's explanation. I should speak with her before they depart."},
	},
	
	[GetQuestName(5337)] = { --"A Question of Succession"				-- Jordakai
		[1] = 
			{appendStepText="The Shatul clan are encamped with their hide tents at Shatul Range, north of Orsinium and east of a wayshrine. ", stepTextKey="Laurig, one of Shatul's warriors, wants me to help him track down the giant responsible for the Chief's injuries. Laurig thinks this will both pull the clan together and show him as a good candidate to become the new Chief."},
		["Kill Urgkail the Cleaver"] =
			{appendText=", a mean, dangerous, and often drunk giant that usually roams north of Shatul Clan's settlement. \n\nShugzur, a female Orc of Clan Shatul, stands by a dead echatere northeast of the Chief's tent. I should start there, crouching to look for signs in the scattered brush down along the riverbank. A giant would not use the broken bridge, so likely crossed the river west of it, heading north near the jagged rocks that slow the water's flow. I may see dead elk and echatere along the way. \n\nFarther north where tall trees dot the land southeast of a stone bridge that crosses the northbound river, a curved, dead tree creates an arch in the snow. The giant is probably there."},
		[2] = 
			{appendStepText="North of the Shatul Range settlement, we found and defeated the dangerous giant. ", stepTextKey="Chief Ogzor is avenged. Laurig and I should return to the chief's tent with the trophy from Urgkail the Cleaver."},
		["Return to Chief Ogzor's Tent"] =
			{appendText=" at the clan's settlement."},
		[3] = 
			{appendStepText="We returned to the Shatul Range camp. ", stepTextKey="Laurig has something to say about about the fight with Urgkail the Cleaver. I should speak with him."},
		["Talk to Laurig"] =
			{appendText=" near the dying Chief's tent."},
		[4] = 
			{appendStepText="At Shatul Range, near the dying Chief's tent, ", stepTextKey="Yazara, Chief Ogzor's mother, wants to speak with me."},
		["Talk to Yazara 1"] =
			{appendText=". Laurig considers her the wise woman of the camp.", stepTextKey="Yazara, Chief Ogzor's mother, wants to speak with me."},
		[5] = 
			{appendStepText="", stepTextKey="Yazara sent me to meet Ulghesh, one of Shatul's warriors. I should find him near Shatul."},
		["Find Ulghesh 1"] =
			{appendText=". Yazara told me he is tracking an echatere named Scamper. He is probably near the wayshrine, west of Shatul Range.", stepTextKey="Yazara sent me to meet Ulghesh, one of Shatul's warriors. I should find him near Shatul."},
		[6] = 
			{appendStepText="Just southeast of Shatul Wayshrine, I met Ulghesh, still dressed in full Orsinium guard armor. ", stepTextKey="Ulghesh needs some help wrangling Scamper, one of Shatul's prized echatere. Once I wake it, I need to work with Ulghesh to guide Scamper as it hunts for a snow truffle."},
		["Wake the Echatere"] =
			{appendText=" by kicking the mound of snow."},
		[7] = 
			{appendStepText="Southeast of Shatul Wayshrine, ", stepTextKey="Ulghesh and I guided Scamper to dig up a snow truffle. I should take it."},
		["Find a Snow Truffle"] =
			{appendText=". I should search the patches of bare ground in this area west of Shatul Range."},
		[8] = 
			{appendStepText="In the area east of Shatul Wayshrine, Scamper, the lazy echatere, came through. ", stepTextKey="With the snow truffle in hand, Ulghesh and I should return to Shatul."},
		["Return to Shatul"] =
			{appendText=" Range where Yazara waits."},
		[9] = 
			{appendStepText="Before leaving me as we approached Shatul Range, ", stepTextKey="Ulghesh asked me to bring the snow truffle to Yazara."},
		["Talk to Yazara 2"] =
			{appendText=" in the chief's tent at the south end of the settlement.", stepTextKey="Ulghesh asked me to bring the snow truffle to Yazara."},
		[10] = 
			{appendStepText="In the dying chief's tent at Shatul Range, ", stepTextKey="Yazara asked me to inform Ulghesh that he is a contender for chief. He will oppose Laurig in the Bloody Knoll."},
		["Find Ulghesh 2"] =
			{appendText=". He should be in his tent at the northeast end of the settlement. There is a large, angular rock in front of it.", stepTextKey="Yazara asked me to inform Ulghesh that he is a contender for chief. He will oppose Laurig in the Bloody Knoll."},
		[11] = 
			{appendStepText="I spoke to Ulghesh in Shatul Range, but ", stepTextKey="\"Ulghesh\" is really Ushruka, the exiled daughter of Chief Ogzor. She posed as Ulghesh so she could be named a contender, and wants to be the new chief of Shatul. She asked me to tell her grandmother Yazara that she is headed to the Bloody Knoll to fight Laurig."},
		["Talk to Yazara 3"] =
			{appendText=", kneeling in her tent. Her covered cart is just outside.", stepTextKey="\"Ulghesh\" is really Ushruka, the exiled daughter of Chief Ogzor. She posed as Ulghesh so she could be named a contender, and wants to be the new chief of Shatul. She asked me to tell her grandmother Yazara that she is headed to the Bloody Knoll to fight Laurig."},
		[12] = 
			{appendStepText="", stepTextKey="According to Yazara, Shatul will have a difficult time accepting Ushruka or Laurig as chief. She asked me to slip a flawed blade to the weakest contender."},
		["Replace Laurig or Ushruka's Sword"] =
			{appendText=" with the Untempered Sword she gave me. \n\nThe contenders will be fighting at the Bloody Knoll, an ancient, indoor arena built into the rocky hillside, north across the river from Shatul Range. \n\nIn the arena, the contenders will begin from opposite sides, one northwest and one southeast. I should look for their weapon racks."},
		[13] = 
			{appendStepText="I am inside the Bloody Knoll, an ancient, indoor arena built into the rocky hillside, north across the river from Shatul Range. ", stepTextKey="I placed the flawed blade. I should hide and see who is victorious."},
		["Hide Before the Duelists Arrive"] =
			{appendText=", up on one of the stone spectator platforms overlooking the arena."},
		[14] = 
			{appendStepText="I watched Laurig and Ushruka fight at the ancient Bloody Knoll's indoor arena, north of Shatul Range. ", stepTextKey="The duel is over. If I wish to become chief of Shatul, I need to kill the victor in the Bloody Knoll."},
		["Follow the Victor"] =
			{appendText=". I should go to the Sanctum of Prowess, east of where the battle was fought."},
		[15] = 
			{appendStepText="I entered the Sanctum of Prowess in this ancient hillside arena north of Shatul Range. ", stepTextKey="To become chief of Shatul, I need to kill the victor in the Bloody Knoll."},
		["Kill the Victor"] =
			{appendText=" at the shrine to Malacath."},
		[16] = 
			{appendStepText="", stepTextKey="I am the new chief of Shatul. I should inform Yazara."},
		["Talk to Yazara 4"] =
			{appendText=" at the north end of the clan's Shatul Range settlement.", stepTextKey="I am the new chief of Shatul. I should inform Yazara."},
		[17] = 
			{appendStepText="", stepTextKey="As the new chief. I should inform Yazara."},
		["Talk to Yazara 5"] =
			{appendText=" at the north end of the clan's Shatul Range settlement.", stepTextKey="As the new chief. I should inform Yazara."},
		[18] = 
			{appendStepText="", stepTextKey="Shatul has a new chief. I should speak with Yazara about what I witnessed in the Bloody Knoll."},
		["Talk to Yazara 6"] =
			{appendText=" at the north end of the clan's Shatul Range settlement.", stepTextKey="Shatul has a new chief. I should speak with Yazara about what I witnessed in the Bloody Knoll."},
		[19] = 
			{appendStepText="", stepTextKey="Ushruka is the new chief of Shatul. I should inform Yazara."},
		["Talk to Yazara 7"] =
			{appendText=" at the north end of the clan's Shatul Range settlement.", stepTextKey="Ushruka is the new chief of Shatul. I should inform Yazara."},		
		[20] = 
			{appendStepText="", stepTextKey="Laurig is the new chief of Shatul. I should inform Yazara."},
		["Talk to Yazara 8"] =
			{appendText=" at the north end of the clan's Shatul Range settlement.", stepTextKey="Laurig is the new chief of Shatul. I should inform Yazara."},
	},
	[GetQuestName(5348)] = { --"To Save a Chief"				-- Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Eveli said the High Priestess wants to talk to me. I should go to the Temple of Ire in Orsinium and find out what this is all about."},
		["Talk to High Priestess Solgra"] =
			{appendText=" near the statue of Trinimac. It is nice to be able to use the temple's main doors on the north side of the building once again."},
		[2] = 
			{appendStepText="I met with the High Priestess in Orsinium's Temple of Ire. ", stepTextKey="High Priestess Solgra received news that one of the clan chiefs was taken captive by Trinimac extremists known as the Vosh Rakh. She asked me to go to Fharun Stronghold, meet up with Eveli, and find a way to rescue the chief."},
		["Meet Eveli at Fharun Stronghold"] =
			{appendText="'s southern approach. The massive stronghold is on the north side of a river in the icy northwest of Wrothgar.\n\nIf she is not at the gate, I could sneak inside the first arched gateway to see if she left a message or something. She was excited about going on a secret mission where we would need to avoid being seen."},
		[3] = 
			{appendStepText="Following her trail of arrows, ", stepTextKey="I found Eveli at Fharun Stronghold. I should talk to her and see if she's learned anything that can aid us in this situation."},
		["Talk to Eveli Sharp-Arrow 1"] =
			{appendText=". She picked a good spot under the boardwalks in the stronghold's southwest.", stepTextKey="I found Eveli at Fharun Stronghold. I should talk to her and see if she's learned anything that can aid us in this situation."},
		[4] = 
			{appendStepText="", stepTextKey="Eveli discovered that there's a large prison of some sort somewhere within Fharun Stronghold. I need to look around and see if I can determine the location of the prison without raising the alarm."},
		["Locate the Hidden Prison"] =
			{appendText=". Eveli said that the Vosh Rakh cultists like to talk a lot. Perhaps I can eavesdrop and learn something from those who gather in the courtyard. She also noticed a disgruntled cultist storm off towards the western lookout tower."},
		[5] = 
			{appendStepText="", stepTextKey="I discovered that the prison is hidden beneath Fharun Stronghold. I should meet Eveli behind the great hall and exchange information before we attempt to get inside."},
		["Rendezvous with Eveli Sharp-Arrow"] =
			{appendText=". The great hall is a longhouse on the western edge of the stronghold's upper area."},
		[6] = 
			{appendStepText="In the upper northwest of Fharun Stronghold, near the large longhouse, ", stepTextKey="Eveli secured the rope and dropped it into the well. I should climb down and see if I can locate the clan chief that the cult has taken prisoner."},
		["Enter the Underground Prison"] =
			{appendText=" at the bottom of the well."},
		[7] = 
			{appendStepText="In the upper northwest of Fharun Stronghold, near the large longhouse, I climbed down the rope in the well. ", stepTextKey="I need to search the underground prison and find the Orc chief taken captive by the Vosh Rakh."},
		["Rescue the Orc Chief"] =
			{appendText=", being held somewhere within the prison. Looks like I will have to fight my way through to him."},
		[8] = 
			{appendStepText="In the upper northwest of Fharun Stronghold, near the large longhouse, I climbed down the rope in the well and entered the prison. \n\n", stepTextKey="Chief Bazrag is the prisoner? I should talk to him and find out what's going on here."},
		["Talk to Chief Bazrag 1"] =
			{appendText=" in the northeasternmost cell of Fharun Prison.", stepTextKey="Chief Bazrag is the prisoner? I should talk to him and find out what's going on here."},
		[9] = 
			{appendStepText="In the upper northwest of Fharun Stronghold, near the large longhouse, I climbed down the rope in the well. Now ", stepTextKey="I need to escort Chief Bazrag safely out of the prison and back to High Priestess Solgra. Then maybe we can figure out what's really going on here."},
		["Escort Chief Bazrag to Safety"] =
			{appendText=" from his northeast cell, through Fharun Prison's defenses, and out the main entrance to the northwest."},
		[10] = 
			{appendStepText="We are inside Fharun Keep at the stronghold's northern end. ", stepTextKey="I escorted Chief Bazrag out of the Fharun prison. I should talk to him and see if I can figure out what's really going on here."},
		["Talk to Chief Bazrag 2"] =
			{appendText=" at the bottom of the circular staircase.", stepTextKey="I escorted Chief Bazrag out of the Fharun prison. I should talk to him and see if I can figure out what's really going on here."},
		[11] = 
			{appendStepText="We are inside Fharun Keep at the stronghold's northern end. ", stepTextKey="Eveli arrived and helped defuse the situation before Chief Bazrag did something rash. I should talk to her and decide what we ought to do with the chief."},
		["Talk to Eveli Sharp-Arrow 2"] =
			{appendText=" at the bottom of the circular staircase.", stepTextKey="Eveli arrived and helped defuse the situation before Chief Bazrag did something rash. I should talk to her and decide what we ought to do with the chief."},
		[12] = 
			{appendStepText="", stepTextKey="While Eveli escorts Chief Bazrag to meet with High Priestess Solgra, I need to find Ulsha outside of Fharun Stronghold. Maybe she can give me proof that Bazrag wasn't involved in the temple attack."},
		["Find Ulsha Outside Fharun"] =
			{appendText=". Chief Bazrag said she had a campsite there, across the bridge and to the south of the stronghold."},
		[13] = 
			{appendStepText="I found the campsite on a hill south of Fharun Stronghold. ", stepTextKey="Ulsha confirmed that Chief Bazrag was being attacked by the Vosh Rakh at the same time as the temple was under assault in Orsinium. She has agreed to investigate the event as long as I do the same."},
		["Talk to Ulsha"] =
			{appendText="."},
	},
	[GetQuestName(5468)] = { --"The Anger of a King"				-- Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Shield-wife Razbela brought me a message from King Kurog. He wants me to appear before him at the keep in Orsinium. I should go and see what he wants."},
		["Talk to King Kurog"] =
			{appendText=", who is contemplating a statue in the great hall. Razbela said he is in a very bad mood, but would not tell me why."},
		[2] = 
			{appendStepText="I spoke with the king at Scarp Keep in Orsinium. ", stepTextKey="King Kurog has discovered that Eveli Sharp-Arrow is trying to get Chief Bazrag to High-Priestess Solgra safely. I should try to find Eveli and warn her that the king is looking for her."},
		["Find Eveli Sharp-Arrow"] =
			{appendText=". Hopefully she and Chief Bazrag made it to the city."},
		[3] = 
			{appendStepText="After speaking with King Kurog, I left Orsinium's Scarp Keep. ", stepTextKey="A messenger brought me a letter. He said he received it from a Wood Elf. I should open my Inventory and read the letter."},
		["Read the Letter in Your Inventory"] =
			{appendText=". The messenger, Owayine, also said that Eveli told him the contents of the letter were not as important as the beginning of each thought."},
		[4] = 
			{appendStepText="Just outside of Orsinium's Scarp Keep, I read the letter I received from Owayine, the messenger. ", stepTextKey="Eveli's message is in some sort of code. She told the messenger that the letter itself wasn't important, that what really matters is the beginning of every thought. I wonder if that's a clue to help me decipher the message?"},
		["Decipher the Letter to Find Eveli"] =
			{appendText=". Perhaps Owayine can help with this. Or someone else can decipher her message."},
		[5] = 
			{appendStepText="I am at Orsinium's inn and tavern. ", stepTextKey="The innkeeper's daughter directed me to a hidden passage in the lower storage area of the Greedy Gut. She said it would lead to a secret room where Eveli and Solgra are waiting for me. I should go and meet them there."},
		["Enter the Secret Room"] =
			{appendText=" down the stairs south of the inn's upper floor sleeping rooms."},
		[6] = 
			{appendStepText="In Orsinium's The Greedy Gut, down the stairs south of the sleeping area on the inn's upper level, and through a storage area, ", stepTextKey="I entered the secret area and heard Eveli, Solgra, and Bazrag talking in the room above. I should join them and talk to High Priestess Solgra."},
		["Talk to High Priestess Solgra"] =
			{appendText="."},
		[7] = 
			{appendStepText="In Orsinium's The Greedy Gut, down the stairs south of the sleeping area on the inn's upper level, and through a storage area, I found the secret area. ", stepTextKey="High-Priestess Solgra explained her position. The Vosh Rakh are the real threat and they have to be contained. I should talk to Eveli and see if I can make her understand what's at stake here."},
		["Talk to Eveli Sharp-Arrow 1"] =
			{appendText=", who went upstairs in these secret rooms to think this through.", stepTextKey="High-Priestess Solgra explained her position. The Vosh Rakh are the real threat and they have to be contained. I should talk to Eveli and see if I can make her understand what's at stake here."},
		[8] = 
			{appendStepText="", stepTextKey="I need to meet up with Eveli and the scouts at the ruins of Paragon's Remembrance."},
		["Meet the Scouts at Paragon's Remembrance"] =
			{appendText=", an ancient temple of Trinimac in the far southwest of Wrothgar. They should be waiting for me near the wayshrine."},
		[9] = 
			{appendStepText="At a rocky outcrop near the Siege Road Wayshrine, ", stepTextKey="I rendezvoused with Eveli and the scouts, Talviah and Flies-in-Wind. I should talk to Eveli and find out what they've learned about the area around Paragon's Remembrance."},
		["Talk to Eveli Sharp-Arrow 2"] =
			{appendText=". She is scouting the Vosh Rakh with Talviah, the High Elf mage, and the Argonian, Flies-in-Wind.", stepTextKey="I rendezvoused with Eveli and the scouts, Talviah and Flies-in-Wind. I should talk to Eveli and find out what they've learned about the area around Paragon's Remembrance."},
		[10] = 
			{appendStepText="Near the Siege Road Wayshrine, ", stepTextKey="I need to find a way to disguise ourselves as a Vosh Rakh cultist so that Eveli, the scouts, and I can gain entry to the ruins. Eveli suggested I follow the group that went west toward the echatere mating grounds."},
		["Find a Vosh Rakh Disguise"] =
			{appendText=" and be aware of any echatere in the area."},
		[11] = 
			{appendStepText="West of Siege Road Wayshrine, I found the dead cultists. ", stepTextKey="With the amulet I found, I should be able to enter the ruins of Paragon's Remembrance undetected."},
		["Enter Paragon's Remembrance"] =
			{appendText=" in my disguise. The ruin is an ancient temple of Trinimac set in the westernmost mountains of the region."},
		[12] = 
			{appendStepText="With the amulet in my possession, ", stepTextKey="I'm disguised as a Vosh Rakh cultist and I'm inside the ruins of Paragon's Remembrance. Now I should find Eveli and the scouts and see what we can learn about the cult's plans."},
		["Find Your Companions"] =
			{appendText=", who should be nearby, probably in the northeast foyer. I should speak with the cultist just inside the entrance. "},
		[13] = 
			{appendStepText="In the region's far southwest, we have entered Paragon's Remembrance. Eveli and Flies are disguised and will search the main areas. And ", stepTextKey="Talviah and I have our disguises. Now to head into the Chambers of Loyalty and see what the high-ranking cultists are meeting about."},
		["Enter the Chambers of Loyalty"] =
			{appendText=" through the doors in the main area's northeast foyer. I should speak with Talviah to see if he is ready before we enter."},
		[14] = 
			{appendStepText="Within Paragon's Remembrance, with Talviah, ", stepTextKey="I entered the Chambers of Loyalty. I need to find out what the high-ranking Vosh Rakh are meeting about. Then I should rendezvous with Talviah and compare notes."},
		["Discover the Purpose of the Meeting"] =
			{appendText=" by going to the southwestern chamber, the first after entering."},
		[15] = 
			{appendStepText="In the Chambers of Loyalty within Paragon's Remembrance, ", stepTextKey="I need to complete the trials in order to learn what the Vosh Rakh are planning for Orsinium. Apparently, I can read the scrolls and select one of Trinimac's blessings to aid me."},
		["Complete the Trials"] =
			{appendText=". First, I must speak to Elder Abzug. \n\nThen I should read each of the three scrolls found on small pedestals in this second chamber north of the entrance.\n\nAnd then I must speak with Elder Akarah.\n\nPerhaps I should check on Talviah before I enter the Trials."},
		[16] = 
			{appendStepText="In Paragon's Remembrance's Chambers of Loyalty, I began the Trials. ", stepTextKey="Now that we completed the Gauntlet, I need to find the Vosh Rakh council so they can tell me about \"the sacred\" mission."},
		["Find the Vosh Rakh Council"] =
			{appendText=" in the chamber through the doors to the south. I see that Talviah made it through the Gauntlet, too. I should speak with him."},
		[17] = 
			{appendStepText="Within Paragon's Remembrance, I made it to the Council Chamber in the Chambers of Loyalty with Talviah. ", stepTextKey="The Vosh Rakh council seems to know who I am. They want me to kill Talviah to prove my devotion to Trinimac. If I do that, they'll tell me the information I came here to uncover. So, should I kill my ally or attack the Vosh Rakh?"},
		["Sacrifice Talviah to Learn Valuable Information"] =
			{appendText=".\n"},
		["Kill the Vosh Rakh"] =
			{appendText="."},
		[18] = 
			{appendStepText="Within the Chambers of Loyalty north of Paragon's Remembrance, I made my choice. ", stepTextKey="After I killed Talviah, Forge-Mother Alga appeared as a vision in the council chamber. I should talk to her and find out what the Vosh Rakh are actually planning."},
		["Talk to the Vision of Alga"] =
			{appendText="."},
		[19] = 
			{appendStepText="Within the Chambers of Loyalty north of Paragon's Remembrance, ", stepTextKey="I learned the Vosh Rakh's plan to eliminate the chiefs at the moot and blame High Priestess Solgra from Forge-Mother Alga. I should rendezvous with Eveli and Flies-in-Wind to let them know."},
		["Rendezvous with Eveli Sharp-Arrow 1"] =
			{appendText=" and Flies-in-Wind by heading south to Paragon's Remembrance.", stepTextKey="I learned the Vosh Rakh's plan to eliminate the chiefs at the moot and blame High Priestess Solgra from Forge-Mother Alga. I should rendezvous with Eveli and Flies-in-Wind to let them know."},
		[20] = 
			{appendStepText="I found Eveli and Flies in the northeastern chamber of Paragon's Remembrance. ", stepTextKey="I need to talk to Eveli and explain what happened to Talviah. She also needs to know what I learned from Forge-Mother Alga."},
		["Talk to Eveli Sharp-Arrow 3"] =
			{appendText=".", stepTextKey="I need to talk to Eveli and explain what happened to Talviah. She also needs to know what I learned from Forge-Mother Alga."},
		[21] = 
			{appendStepText="Within the Chambers of Loyalty at Paragon's Remembrance. I made my choice. ", stepTextKey="I need to search the council chamber and see if I can discover the nature of the Vosh Rakh's plan for disrupting the king's moot."},
		["Find the Information You Seek"] =
			{appendText=". Since the one who unmasked me was on the upper dais, perhaps I should start there."},
		[22] = 
			{appendStepText="North of Paragon's Remembrance, ", stepTextKey="I need to leave the Chambers of Loyalty and find Eveli and Flies-In-Wind. Chief Bazrag and Eveli are in danger, and the Vosh Rakh plan to kill the clan chiefs at the moot."},
		["Rendezvous with Eveli Sharp-Arrow 2"] =
			{appendText=" and Flies-in-Wind by heading south to Paragon's Remembrance.", stepTextKey="I need to leave the Chambers of Loyalty and find Eveli and Flies-In-Wind. Chief Bazrag and Eveli are in danger, and the Vosh Rakh plan to kill the clan chiefs at the moot."},
		[23] = 
			{appendStepText="I found Eveli and Flies in the northeastern chamber of Paragon's Remembrance. ", stepTextKey="I should talk to Eveli and let her know what we uncovered before I head back to Orsinium to warn about the upcoming attack on the moot."},
		["Talk to Eveli Sharp-Arrow 4"] =
			{appendText=".", stepTextKey="I should talk to Eveli and let her know what we uncovered before I head back to Orsinium to warn about the upcoming attack on the moot."},
	},
	[GetQuestName(5349)] = { --"The King's Gambit"				-- Jordakai
		[1] = 
			{appendStepText="In Orsinium, I spoke with Mulzah, the innkeeper. She is upset about the king's guards taking over her inn. ", stepTextKey="I need to find a way to get inside the Greedy Gut inn so that I can check on Chief Bazrag and Eveli. I could follow the soldier to the ramparts near the stables, or I could steal a key from the soldier on duty near the King's Cornerclub."},
		["Find a Way Inside the Inn"] =
			{appendText=". In speaking with Mulzah, I learned that her key was taken by Sergeant Vulmon, stationed near the King's Cornerclub. Also, there is a guard meeting with the Captain up on the city's far northwestern rampart. A key may be stashed there. And if Gulug is still around, he'd likely be at Ufgel's Bathhouse. One way or another, I will get a key."},
		[2] = 
			{appendStepText="In Orsinium, ", stepTextKey="I dealt with some Vosh Rakh fanatics disguised as Orsimer soldiers and recovered the key to the Greedy Gut inn. Now I should enter the inn and find Chief Bazrag and Eveli."},
		["Meet Allies in the Greedy Gut"] =
			{appendText=". They are probably being held in the secret rooms through the inn's storage area off the upstairs sleeping rooms."},
		[3] = 
			{appendStepText="In Orsinium, ", stepTextKey="I recovered the key to the Greedy Gut inn. Now I should enter the inn and find Chief Bazrag and Eveli."},
		["Meet Allies in the Greedy Gut"] =
			{appendText=". They are probably being held in the secret rooms through the inn's storage area off the upstairs sleeping rooms."},
		[4] = 
			{appendStepText="I am at Orisinium's The Greedy Gut, in the secret rooms through the inn's storage area off the upstairs sleeping rooms. ", stepTextKey="I managed to get inside the inn, but everyone's gone except the messenger who gave me Eveli's note. I should talk to him and find out what happened."},
		["Talk to Owayine"] =
			{appendText=", who is sitting on the floor. He appears to be injured."},
		[5] = 
			{appendStepText="", stepTextKey="Owayine said that soldiers took Eveli and Chief Bazrag on the king's orders. I should go talk to King Kurog at the keep and find out where they are holding my friends."},
		["Talk to King Kurog"] =
			{appendText=" in Orsinium's northeastern Scarp Keep. I doubt he is sitting on his throne. Perhaps I should check out the upper wooden walkways in the main entry hall."},
		[6] = 
			{appendStepText="", stepTextKey="Owayine claimed that King Kurog ordered the attack on the inn. I should go to the keep and find out what happened to Chief Bazrag and Eveli Sharp-Arrow."},
		["Go to the Dining Hall"] =
			{appendText=". \n\nI see the clan chiefs I invited are up here, too. Perhaps I should speak with them before I go back downstairs to the octagonal dining hall off the main entry hall."},
		[7] = 
			{appendStepText="In the dining hall of Orsinium's Scarp Keep, ", stepTextKey="Alga attacked me, but it appears that one of Kurog's shield-wives came to my rescue. I should speak to her to find out what's going on."},
		["Talk to Shield-Wife Razbela"] =
			{appendText=". We are in the southernmost room of Scarp Keep's main floor. Perhaps she can help me."},
		[8] = 
			{appendStepText="In the northern area of Orsinium's Scarp Keep, off the main entry hall and downstairs, ", stepTextKey="Chief Bazrag and Eveli are being held in the cells beneath the keep. I need to find them and set them free before I try to get to the moot."},
		["Rescue Chief Bazrag and Eveli"] =
			{appendText=". I should speak with them."},
		[9] = 
			{appendStepText="I am at Orisinium's The Greedy Gut, in the secret area through the inn's storage area off the upstairs sleeping rooms. ", stepTextKey="I found Chief Bazrag and Eveli inside the inn. I should talk to the chief and compare notes."},
		["Talk to Chief Bazrag 1"] =
			{appendText=". He and Eveli defeated the Vosh Rakh attackers.", stepTextKey="I found Chief Bazrag and Eveli inside the inn. I should talk to the chief and compare notes."},
		[10] = 
			{appendStepText="", stepTextKey="Chief Bazrag wants me to go warn King Kurog and try to convince him to postpone the moot while Eveli goes to protect High Priestess Solgra. I should head to the keep and talk to the king."},
		["Warn King Kurog"] =
			{appendText=" in Orsinium's eastern Scarp Keep. I doubt he is sitting on his throne. Perhaps I should check out the upper wooden walkways in the main entry hall."},
		[11] = 
			{appendStepText="Up on the wooden platforms in the main hall of Orsinium's Scarp Keep, the clan chiefs are gathered. The king was nearby. We spoke, but ", stepTextKey="King Kurog didn't want to talk in front of the clan chiefs. He asked me to meet him in the dining hall on the lower level of the keep to continue our conversation."},
		["Go to the Dining Hall"] =
			{appendText=". Perhaps I should speak with the Chiefs before I go back downstairs to the octagonal eating area that is off the main entry hall."},
		[12] = 
			{appendStepText="In the dining hall of Orsinium's Scarp Keep, ", stepTextKey="Forge-Mother Alga attacked me. I'm not completely certain what happened after that, but I seem to be somewhere safe with Chief Bazrag. I should talk to him."},
		["Talk to Chief Bazrag 2"] =
			{appendText=". We are in the southernmost room of Scarp Keep's main floor.", stepTextKey="Forge-Mother Alga attacked me. I'm not completely certain what happened after that, but I seem to be somewhere safe with Chief Bazrag. I should talk to him."},
		[13] = 
			{appendStepText="", stepTextKey="I need to get to the moot before Kurog and Alga eliminate the chiefs. There's a path in the throne room. I just need to get past the Vosh Rakh soldiers to utilize it."},
		["Find the Path in the Throne Room"] =
			{appendText=". Chief Bazrag said the path can get me to the moot's location. I suspect the hidden path would be near the throne.  If I have any problems, I should find him outside of the keep."},
		[14] = 
			{appendStepText="In the throne room of Orsinium's Scarp Keep, I found instructions from King Kurog to his Shield-Wives. ", stepTextKey="All of the paths to the moot have been sealed, except for the one through the temple. I need to find Chief Bazrag and let him know."},
		["Talk to Chief Bazrag 3"] =
			{appendText=". He said he would be outside, near the keep. He is probably someplace with a good view of the city, such as the platform above the city's Outlaw Refuge entrance.", stepTextKey="All of the paths to the moot have been sealed, except for the one through the temple. I need to find Chief Bazrag and let him know."},
		[15] = 
			{appendStepText="I found Chief Bazrag on the wooden platform above Orsinium's Outlaw Refuge entrance. ", stepTextKey="There's a way to the moot through the temple. I should talk to Chief Bazrag and figure out our next move."},
		["Talk to Chief Bazrag 4"] =
			{appendText=".", stepTextKey="There's a way to the moot through the temple. I should talk to Chief Bazrag and figure out our next move."},
	},
[GetQuestName(5481)] = { --"Blood on a King's Hands"				-- Jordakai
		[1] = 
			{appendStepText="Chief Bazrag and I spoke on the wooden platform above Orsinium's Outlaw Refuge entrance. ", stepTextKey="I need to get to the temple and protect High Priestess Solgra from Kurog's Vosh Rakh soldiers."},
		["Enter the Temple"] =
			{appendText=" of Ire through its main doors on the north side of the building that also houses the Mages Guild."},
		[2] = 
			{appendStepText="", stepTextKey="I'm in the temple but all I see are a few priests. I should ask them where High Priestess Solgra is so I can get to her before Kurog's soldiers."},
		["Talk to the Temple Priests"] =
			{appendText=" on the main floor. I see Priest Uugus near the staircase to the southwest."},
		[3] = 
			{appendStepText="In Orsinium's Temple of Ire, I found Priest Uugus and some other priests. ", stepTextKey="The priests explained that the soldiers chased High Priestess Solgra upstairs and out of the temple. I need to catch up with them before something terrible happens."},
		["Find High Priestess Solgra"] =
			{appendText=". She probably went out the northwestern back door at the very top of the stairs and ramps."},
		[4] = 
			{appendStepText="In Orsinium's Temple of Ire, I found Priest Uugus and some other priests. ", stepTextKey="The priests explained that the soldiers chased High Priestess Solgra and Eveli upstairs and out of the temple. I need to catch up with them before something terrible happens."},
		["Find High Priestess Solgra and Eveli"] =
			{appendText=". They probably went out the northwestern back door at the very top of the stairs and ramps."},
		[5] = 
			{appendStepText="On Orsinium's western upper stone rampart, west of the Temple and Mages Guild building, ", stepTextKey="I dealt with the Vosh Rakh soldiers sent by King Kurog to attack High Priestess Solgra. I should talk to her and make sure she's all right."},
		["Talk to High Priestess Solgra"] =
			{appendText=", standing on a raised dais overlooking the valley below."},
		[6] = 
			{appendStepText="High up on the city's west side, my friend was shot with an arrow. ", stepTextKey="My allies have been attacked by the king's soldiers. I need to find the attackers and make them pay for what they've done."},
		["Find the Attackers"] =
			{appendText=" up the nearby stairs from where I was speaking with the High Priestess."},
		[7] = 
			{appendStepText="High up on the city's west side, my friend was shot with an arrow. ", stepTextKey="I defeated the last of the Vosh Rakh sent to kill the high priestess. Now I should confront the assassin who's cowering on the platform above."},
		["Confront the Assassin"] =
			{appendText=", who is trapped in the open tower, west of the highest entrance to Fabasi's shop."},
		[8] = 
			{appendStepText="Since I am on Orisinium's upper western ramparts, I can use the Temple of Ire's back door, like I have before. ", stepTextKey="I should return to the temple and check on High Priestess Solgra."},
		["Check on Solgra in the Temple"] =
			{appendText=" of Ire. They will probably take her to the wooden platform to the northwest, just above the ground floor."},
		[9] = 
			{appendStepText="Since I am on Orisinium's upper western ramparts, I can use the Temple of Ire's back door, like I have before. ", stepTextKey="I should return to the temple and check on Eveli Sharp-Arrow."},
		["Check on Eveli in the Temple"] =
			{appendText=" of Ire. They will probably take her to the wooden platform to the northwest, just above the ground floor."},
		[10] = 
			{appendStepText="I am with Eveli and the High Priestess on the northwestern platform, just above the temple's ground floor. ", stepTextKey="Chief Bazrag arrived at the temple. He wants to speak to me before we go after Kurog."},
		["Talk to Chief Bazrag 1"] =
			{appendText=".", stepTextKey="Chief Bazrag arrived at the temple. He wants to speak to me before we go after Kurog."},
		[11] = 
			{appendStepText="", stepTextKey="To get to the moot, I need to find the tunnels hidden beneath the library in the Temple of Ire."},
		["Go to the Temple Library"] =
			{appendText=" through its large doors to the southeast, up one level from the main floor."},
		[12] = 
			{appendStepText="In the Temple of Ire's southeast, we found shelves and shelves of books. ", stepTextKey="We're in the temple library, looking for the secret passage that will take us to the tunnels beneath the city and eventually to the moot. I should investigate the library for any clues to the passage's location."},
		["Find the Secret Passage"] =
			{appendText=". Chief Bazrag came with me. If I can find a catalog or a couple of books to help me, that would be great."},
		[13] = 
			{appendStepText="Within the Temple Library ", stepTextKey="I found the secret passage that leads to the tunnels. Now I need to get to the moot and stop Kurog before he has the clan chiefs assassinated."},
		["Go to the Moot"] =
			{appendText=" through the Temple Undertunnels."},
		[14] = 
			{appendStepText="At the end of the Path to the Moot that we found through the Temple Library's undertunnels, ", stepTextKey="Kurog has begun his attack against the clan chiefs. I need to get inside and rescue as many of the chiefs as possible."},
		["Rescue the Chiefs"] =
			{appendText=" from the Vosh Rakh."},
		[15] = 
			{appendStepText="At the end of the Path to the Moot that we found through the Temple Library's undertunnels, we defeated the Vosh Rakh. ", stepTextKey="The chiefs are safe. Now I have to deal with King Kurog and Forge-Mother Alga."},
		["Defeat King Kurog"] =
			{appendText=" and Forge-Mother Alga."},
		[16] = 
			{appendStepText="At the end of the Path to the Moot that we found through the Temple Library's undertunnels, we encountered the King and the Forge-Mother. Now, ", stepTextKey="King Kurog and Forge-Mother Alga are dead. I should talk to Chief Bazrag and see what he wants to do next."},
		["Talk to Chief Bazrag 2"] =
			{appendText=" where we defeated Kurog and Alga.", stepTextKey="King Kurog and Forge-Mother Alga are dead. I should talk to Chief Bazrag and see what he wants to do next."},
		[17] = 
			{appendStepText="", stepTextKey="Chief Bazrag asked me to meet him back at the keep. I should leave the moot and return to the keep."},
		["Return to the Keep"] =
			{appendText=" in northeastern Orsinium."},
		[18] = 
			{appendStepText="In Orsinium, ", stepTextKey="I arrived back at the keep. I should talk to Chief Bazrag and find out if he's decided what to do now that the king is dead."},
		["Talk to Chief Bazrag 3"] =
			{appendText=" as he stands in Scarp Keep's main hall, contemplating the statue of a hero.", stepTextKey="I arrived back at the keep. I should talk to Chief Bazrag and find out if he's decided what to do now that the king is dead."},
		[19] = 
			{appendStepText="As we speak in the main hall of Orsinium's Scarp Keep, ", stepTextKey="Chief Bazrag has one more task for me to do before I leave Wrothgar. I should talk to him and find out what he needs."},
		["Talk to Chief Bazrag 4"] =
			{appendText=" at the hero's statue.", stepTextKey="Chief Bazrag has one more task for me to do before I leave Wrothgar. I should talk to him and find out what he needs."},
	},
[GetQuestName(5494)] = { --"Long Live the King"				-- Jordakai
        [1] = 
            {appendStepText="In Orsinium's Scarp Keep, ", stepTextKey="Chief Bazrag asked me to deliver these letters to our allies and a few of his old friends, inviting them to attend Kurog's funeral."},
        ["Gather Your Allies for the Funeral"] =
            {appendText="\n\nBazrag's old friends, Bizra and her partner, are probably near the eastside river crossing behind Rime Hammer Forge. \n\nPriest Uugus and a person I know at the Temple of Ire are being invited. \n\nMulzah, the innkeeper of The Greedy Gut, has an invitation. \n\nUlsha, the chief's shield-wife, may be standing outside the House of Orsimer Glories. \n\nAnd another that I know should be at Mazabakh's House, south of The Greedy Gut and east of the House of Orsimer Glories."},
        [2] = 
            {appendStepText="Around Orsinium, ", stepTextKey="I delivered all of Chief Bazrag's invitations. Now I should go to the King's Cornerclub and pick up a bottle of Kurog's favorite ale."},
        ["Go to the King's Cornerclub"] =
            {appendText=" and find the barkeeper."},
        [3] = 
            {appendStepText="", stepTextKey="I'm in the King's Cornerclub. Now I need to speak to the barkeep and get a bottle of Kurog's favorite ale for the ceremony."},
        ["Get Kurog's Favorite Ale"] =
            {appendText=" from Roxanne, Orsinium's brewer of Ice-Berry Ale."},
        [4] = 
            {appendStepText="Today is an important day in Orsinium. ", stepTextKey="It's time for me to attend King Kurog's funeral. I should return to the keep and look for Chief Bazrag on the castle overlook."},
        ["Go to the Castle Overlook"] =
            {appendText=". I should enter Scarp Keep and head up the stairs towards the throne room, but then follow the crooked hallway to the northwest."},
        [5] = 
            {appendStepText="I arrived at Castle Overlook through Scarp Keep's northwestern hallway near the throne room. ", stepTextKey="I should talk to Chief Bazrag before the funeral ceremony begins."},
        ["Talk to Chief Bazrag"] =
            {appendText=" at the apex of the overlook."},
        [6] = 
            {appendStepText="Atop Orsinium's Castle Overlook at the funeral site, ", stepTextKey="Chief Bazrag has tasks for me to accomplish throughout the ceremony. I should listen carefully to what he has to say."},
        ["Participate in the Funeral"] =
            {appendText=" by listening and lighting the funeral pyres."},
        [7] = 
            {appendStepText="In Orsinium, ", stepTextKey="Bazrag has been named king of the Orsimer. I should go to the keep and speak to him before I leave."},
        ["Talk to King Bazrag 1"] =
            {appendText=" in Orsinium's Scarp Keep. He is probably up on the wooden platform above the main hall.", stepTextKey="Bazrag has been named king of the Orsimer. I should go to the keep and speak to him before I leave."},
        [8] = 
            {appendStepText="In Orsinium, ", stepTextKey="Bazrag has been named king of Orsinium. I should speak to him before I leave."},
        ["Talk to King Bazrag 2"] =
            {appendText=" in Orsinium's Scarp Keep. He is up on the wooden platform above the main hall.", stepTextKey="Bazrag has been named king of Orsinium. I should speak to him before I leave."},
    },

-- 		=========================================================================
--		  Wrothgar Side
-- 		=========================================================================
		[GetQuestName(5462)] = { -- "The Ashes of Our Fathers" 		-- JayAstrophel
			[1] = 
				{appendStepText="At Honor's Rest, ", stepTextKey="Lozruth believes they found the tomb of Baloth Bloodtusk, a great Orc hero who died at the siege of Old Orsinium. I said I would speak with Sharela about her objections to his theory."},
			["Talk to Sharela 1"] =
				{appendText=", a Redguard scholar who busies herself with examining a pillar by the doors of the tomb. Ivy climbs up and over these long lost ruins, as if nature itself is working to cover up whatever truth hides within.\n", stepTextKey="Lozruth believes they found the tomb of Baloth Bloodtusk, a great Orc hero who died at the siege of Old Orsinium. I said I would speak with Sharela about her objections to his theory."},
			[2] = 
				{appendStepText="At Honor's Rest, ", stepTextKey="Sharela believes they found the tomb of Gaiden Shinji, a great Redguard hero who also died at the siege of Old Orsinium. She thinks the key to opening the tomb can be found in the nearby catacombs. I should search for the entrance to the catacombs."},
			["Find the Entrance to the Catacombs"] =
				{appendText=". From the sealed doors of the tomb, head west. Take the first right turn along a wooden path. After moving under an ancient stone archway, you'll find the entrance on your right. Sharela warns of Winterborn guarding it. Skull torches and bone totems decorate the way in, as this part of the ruin has not been reclaimed by nature alone, but by people as well.\n"},
			[3] = 
				{appendStepText="At Honor's Rest, I've been asked to investigate the catacombs. To reach them from the doors of the tomb, head west. Take the first right turn along a wooden path, then under an ancient stone archway. The entrance is on the right.\n\n", stepTextKey="Sharela thinks the key to opening the tomb can be found in the nearby catacombs. I should examine the monument stone near the catacomb entrance."},
			["Examine the Monument Stone"] =
				{appendText=". Once through the tunnel leading into the catacombs themselves, the Monument Stone stands proudly just past the first room. Candlelight shines on the geometric patterns of the statue, and wooden totems surround its base.\n"},
			[4] = 
				{appendStepText="At Honor's Rest, I've been asked to investigate the catacombs. To reach them from the doors of the tomb, head west. Take the first right turn along a wooden path, then under an ancient stone archway. The entrance is on the right.\n\n", stepTextKey="A pair of burial urns should unlock the tomb doors. It seems I must find and drink from a pair of memorial pools to release the urns. I should search for the pools in the catacombs near the tomb."},
			["Drink from the First Memorial Pool"] =
				{appendText=". Water flows swiftly downstream to the east, just behind the Monument Stone. Follow its path to its end, where faint light from the sky above peeks through cracks in the stone far above to nourish the greenery below. \n\nFrom there, continue through the tunnel to the Memorial Pool. It's flanked by spear-wielding statues and glowing with a faint light, the gentle sound of a waterfall flowing behind it.\n"},
			[5] = 
				{appendStepText="At Honor's Rest, I've been asked to investigate the catacombs. To reach them from the doors of the tomb, head west. Take the first right turn along a wooden path, then under an ancient stone archway. The entrance is on the right.\n\nOn the east side of the catacombs, I drank from a Memorial Pool. ", stepTextKey="I was drawn into a memory of past events, prior to the destruction of Old Orsinium. It seems I walk in the shoes of Tamahl, one of Gaiden Shinji's followers. I should speak with him and see what I can learn."},
			["Talk to Gaiden Shinji"] =
				{appendText=" within the memory. He stands inside the tent, katana on his back and a grim look in his eyes.\n"},
			[6] = 
				{appendStepText="At Honor's Rest, I've been asked to investigate the catacombs. To reach them from the doors of the tomb, head west. Take the first right turn along a wooden path, then under an ancient stone archway. The entrance is on the right.\n\nOn the east side of the catacombs, I drank from a Memorial Pool. ", stepTextKey="I was drawn into a memory of past events, prior to the destruction of Old Orsinium. It seems I walk in the shoes of Tamahl, one of Gaiden Shinji's followers. Now that I've learned what I could, I should find a way to awaken from this memory."},
			["Leave Tamahl's Memory"] =
				{appendText=". One of the tent's exits glows with a faint light. Perhaps this is the way out.\n"},
			[7] = 
				{appendStepText="At Honor's Rest, I've been asked to investigate the catacombs. To reach them from the doors of the tomb, head west. Take the first right turn along a wooden path, then under an ancient stone archway. The entrance is on the right.\n\nOn the east side of the catacombs, I experienced another's memory. ", stepTextKey="When I awoke from the memory of Tamahl and Gaiden Shinji, the waters parted to reveal a hidden alcove. I should collect Tamahl's burial urn."},
			["Take Tamahl's Burial Urn"] =
				{appendText=" from behind the eastern Memorial Pool within the catacombs. It gleams gold, as if time's slow decay of the rest of this place has left this one thing untouched.\n"},
			[8] = 
				{appendStepText="At Honor's Rest, I've been asked to investigate the catacombs. To reach them from the doors of the tomb, head west. Take the first right turn along a wooden path, then under an ancient stone archway. The entrance is on the right.\n\n", stepTextKey="I collected a burial urn filled with the ashes of Tamahl, one of Gaiden Shinji's followers. I should search the catacombs for another memorial pool to find the second burial urn."},
			["Drink from the Second Memorial Pool"] =
				{appendText=", on the west side of the catacombs. Just as the first had been, this pool is flanked by statues and marked by glowing water. A waterfall quietly splashes behind it.\n"},
			[9] = 
				{appendStepText="At Honor's Rest, I've been asked to investigate the catacombs. To reach them from the doors of the tomb, head west. Take the first right turn along a wooden path, then under an ancient stone archway. The entrance is on the right.\n\nOn the east side of the catacombs, I drank from another pool. ", stepTextKey="I was drawn into another memory of past events, prior to Old Orsinium's fall. Now I walk in the boots of Arakaul, one of Baloth Bloodtusk's followers. I should speak with him and see what I can learn."},
			["Talk to Baloth Bloodtusk"] =
				{appendText=" within the memory. He sits at one end of a long dining table, the light from a roaring campfire nearby.\n"},
			[10] = 
				{appendStepText="At Honor's Rest, I've been asked to investigate the catacombs. To reach them from the doors of the tomb, head west. Take the first right turn along a wooden path, then under an ancient stone archway. The entrance is on the right.\n\nOn the catacomb's west side, ", stepTextKey="I was drawn into another memory of past events, prior to Old Orsinium's fall. Now I walk in the boots of Arakaul, one of Baloth Bloodtusk's followers. I've learned what I could, so I should find a way to awaken from this memory."},
			["Leave Arakaul's Memory"] =
				{appendText=". The doorway leading outside gleams with a faint light. Perhaps this is the way out."},
			[11] = 
				{appendStepText="At Honor's Rest, I've been asked to investigate the catacombs. To reach them from the doors of the tomb, head west. Take the first right turn along a wooden path, then under an ancient stone archway. The entrance is on the right.\n\nOn the catacomb's west side, ", stepTextKey="when I awoke from the memory of Arakaul and Baloth Bloodtusk, the waters parted to reveal a hidden alcove. I should collect Arakaul's burial urn."},
			["Take Arakaul's Burial Urn"] =
				{appendText=" from behind the western Memorial Pool within the catacombs. It gleams silver, untarnished by wear or rust.\n"},
			[12] = 
				{appendStepText="At Honor's Rest, ", stepTextKey="I collected both burial urns: one of Arakaul, an Orc lieutenant of Baloth Bloodtusk, and the other of Tamahl, the Redguard disciple of Gaiden Shinji. I should bring them to Sharela."},
			["Bring Burial Urns to Sharela"] =
				{appendText=", who waits for you outside near the excavation camp, at the sealed door to the main tomb.\n"},
			[13] = 
				{appendStepText="At Honor's Rest, ", stepTextKey="I should place both burial urns to unlock the tomb doors."},
			["Place Arakaul's Burial Urn"] =
				{appendText=" in the alcove just to the north of the sealed door. On this side, the door depicts Bloodtusk wielding a mighty axe.\n"},
			["Place Tamahl's Burial Urn"] =
				{appendText=" in the alcove just to the south of the sealed door. On this side, the door depicts Shinji holding out his blade.\n"},
			[14] = 
				{appendStepText="At Honor's Rest, ", stepTextKey="I unlocked the tomb doors. I should enter with Lozruth and Sharela."},
			["Enter Honor's Rest"] =
				{appendText=" through the large stone doors depicting both Bloodtusk and Shinji to the south."},
			[15] = 
				{appendStepText="Within Honor's Rest, ", stepTextKey="it seems they were both right. This is the tomb of Gaiden Shinji and Baloth Bloodtusk—supposedly, two mortal enemies. I should look for an explanation of how this is possible."},
			["Explore Honor's Rest"] =
				{appendText=". Once through the entrance door, head down the long hallway into the Central Burial Chamber. If there's another Memorial Pool around here, it might help to uncover the truth.\n"},
			[16] = 
				{appendStepText="After drinking from the Memorial Pool within Honor's Rest, ", stepTextKey="I was drawn into another memory of past events, during the fall of Old Orsinium. I walk in the boots of Commander Reliana, a Knight of the Dragon. A wounded Orc has approached me. I should speak with him."},
			["Talk to Rokaug"] =
				{appendText=", who catches his breath near the entrance of the memory.\n"},
			[17] = 
				{appendStepText="After drinking from the Memorial Pool within Honor's Rest, ", stepTextKey="I was drawn into another memory of past events, during the fall of Old Orsinium. I walk in the boots of Commander Reliana, a Knight of the Dragon who learned General Mercedene planned to interfere with the duel between Gaiden Shinji and Baloth Bloodtusk. I should warn Lord Trystan, quickly!"},
			["Warn Lord Trystan of General Mercedene's Betrayal"] =
				{appendText=". He surely is somewhere further within the memory, up the passageway.\n"},
			[18] = 
				{appendStepText="After drinking from the Memorial Pool within Honor's Rest, ", stepTextKey="I was drawn into another memory of past events, during the fall of Old Orsinium. I walk in the boots of Commander Reliana, a Knight of the Dragon who arrived too late to stop General Mercedene's betrayal. Gaiden Shinji and Baloth Bloodtusk are dead. Lord Trystan is wounded—I should speak with him."},
			["Talk to Lord Trystan"] =
				{appendText=" in the memory, partway up the path. The wounded Lord stands above the bodies of both Shinji and Bloodtusk, still trying to comprehend this betrayal.\n"},
			[19] = 
				{appendStepText="After drinking from the Memorial Pool within Honor's Rest, ", stepTextKey="I was drawn into another memory of past events, during the fall of Old Orsinium. I walk in the boots of Commander Reliana, a Knight of the Dragon. Lord Trystan asked me to pursue and confront General Mercedene for the murder of Gaiden Shinji and Baloth Bloodtusk."},
			["Confront General Mercedene"] =
				{appendText=" by continuing west along the path in the memory. Conflict is inevitable.\n"},
			[20] = 
				{appendStepText="After drinking from the Memorial Pool within Honor's Rest, ", stepTextKey="I was drawn into another memory of past events, during the fall of Old Orsinium. I walk in the boots of Commander Reliana, a Knight of the Dragon. General Mercedene is dead. I should inform Lord Trystan."},
			["Report to Lord Trystan"] =
				{appendText="in the memory, partway up the path. The wounded Lord stands above the bodies of both Shinji and Bloodtusk, in deep contemplation.\n"},
			[21] = 
				{appendStepText="After drinking from the Memorial Pool within Honor's Rest, ", stepTextKey="I was drawn into another memory of past events, during the fall of Old Orsinium. I walk in the boots of Commander Reliana, a Knight of the Dragon. Her commander, Lord Trystan, vowed to honor the dead. I should find a way to awaken from this memory."},
			["Leave Commander Reliana's Memory"] =
				{appendText=". Having learned that the truth is more complex than either scholar believed, all that is left is to let them know. In front of Lord Trystan, the air glimmers with light. This must be the way out.\n"},
			[22] = 
				{appendStepText="Within Honor's Rest, I found out the truth. ", stepTextKey="This tomb is the resting place of both Gaiden Shinji and Baloth Bloodtusk. I should inform Lozruth of what I experienced."},
			["Talk to Lozruth"] =
				{appendText=", on the south side of the chamber inside Honor's Rest at the Memorial Pool. He stands before Baloth Bloodtusk's tomb.\n"},
			[23] = 
				{appendStepText="Within Honor's Rest, ", stepTextKey="I should speak with Sharela about the tomb."},
			["Talk to Sharela 2"] =
				{appendText=", on the north side of the chamber inside Honor's Rest at the Memorial Pool. She stands before Gaiden Shinji's tomb.\n", stepTextKey="I should speak with Sharela about the tomb."},
		},
		[GetQuestName(5497)] = { -- "Atypical Artistry"				-- JayAstrophel
			[1] = 
				{appendStepText="At Morkul Stronghold, ", stepTextKey="Doranar asked me to acquire authentic ogre \"artistic materials\" for his piece. He suggested I try the nearby ogre den in Morkul Descent."},
			["Gather Materials for Doranar's Artwork"] =
				{appendText="\nThe den can be found east of Morkul Stronghold, west of Morkuldin Forge, and north of the Forlorn Watchtower, all of which are north of Orsinium. The entrance is a wooden door leading into the icy cliffs.\n\nWithin the den, one option for art supplies might be in a sack near the entrance. Further within the cave, where the ogres live, several other options include hanging bones, a carved bone spoon, and a bowl containing a mysterious substance.\n"},
			[2] = 
				{appendStepText="", stepTextKey="I gathered some \"materials\" for Doranar's artwork. I should deliver what I found to him in Orsinium."},
			["Deliver the Items to Doranar in Orsinium"] =
				{appendText=". He waits to unleash his creativity within the House of Orsimer Glories, down the stairs.\n"},
		},
		[GetQuestName(5476)] = { -- "Awaken the Past"				-- JayAstrophel
			[1] = 
				{appendStepText="", stepTextKey="I found a notice from the House of Orsimer Glories. I should talk to the curator of the museum and find out more about the relics they're looking for."},
			["Talk to Curator Umutha 1"] =
				{appendText=" in the House of Orsimer Glories. Red banners, each depicting a ferocious face, are hanging around the outside. The curator is just inside, scribbling furiously on a piece of parchment.\n", stepTextKey="I found a notice from the House of Orsimer Glories. I should talk to the curator of the museum and find out more about the relics they're looking for."},
			[2] = 
				{appendStepText="", stepTextKey="Curator Umutha asked me to place the Agra Crun, the legendary \"blood shield\" of the Orcs, on display in the lower level of the museum."},
			["Place the Agra Crun on Display"] =
				{appendText=". It already has a labeled stand waiting for it, downstairs at the southwest end of the museum. Many other stands lie empty, waiting patiently for the mighty relics that may one day adorn them.\n"},
			[3] = 
				{appendStepText="", stepTextKey="I placed the \"blood shield\" on display in the museum. Now I should return to Curator Umutha and find out more about the historic relics the museum is seeking."},
			["Talk to Curator Umutha 2"] =
				{appendText=" in the House of Orsimer Glories. Red banners, each depicting a ferocious face, are hanging around the outside. The curator is just inside, scribbling furiously on a piece of parchment as she waits for your task to be done.\n", stepTextKey="I placed the \"blood shield\" on display in the museum. Now I should return to Curator Umutha and find out more about the historic relics the museum is seeking."},
			[4] = 
				{appendStepText="", stepTextKey="Curator Umutha says that another relic, Uzdabikh's Helm, lies somewhere near Sorrow, a mountain to the north of Orsinium. I should go there and try to find it."},
			["Find Uzdabikh's Helm"] =
				{appendText=". Curator Umutha can remind you of the helm's general location. Perhaps searching to the east of Sorrow and southeast of the Icereach dungeon could give results. Climb up and up, past bears and harpies, to the top of a once mighty wall. At the north end of that wall, your prize awaits.\n"},
			[5] = 
				{appendStepText="", stepTextKey="I found Uzdabikh's Helm. Now I should return to Curator Umutha and donate the relic to the House of Orsimer Glories."},
			["Talk to Curator Umutha 3"] =
				{appendText=", as before, in the House of Orsimer Glories. Red banners, each depicting a ferocious face, are hanging around the outside. The curator is just inside, scribbling furiously on a piece of parchment as she waits to hear if the search was successful.\n", stepTextKey="I found Uzdabikh's Helm. Now I should return to Curator Umutha and donate the relic to the House of Orsimer Glories."},
			[6] = 
				{appendStepText="", stepTextKey="Curator Umutha asked me to place Uzdabikh's Helm on display on the lower level of the museum."},
			["Place Uzdabikh's Helm"] =
				{appendText=". This rare artifact already has a place marked for it next to the Agra Crun shield, on the southwest end of the museum.\n"},
			[7] = 
				{appendStepText="", stepTextKey="Now that the helm is in its proper place, I can talk to Curator Umutha and find out what else is planned for the museum."},
			["Talk to Curator Umutha 4"] =
				{appendText=", just inside the entrance to the museum. Surely by now she has info on other rare artifacts to be found while wandering the vast expanse of Wrothgar.\n", stepTextKey="Now that the helm is in its proper place, I can talk to Curator Umutha and find out what else is planned for the museum."},
		},
		[GetQuestName(5319)] = { -- "Birdsong's Curse"				-- JayAstrophel
			[1] = 
				{appendStepText="Within the cave, ", stepTextKey="I should find Kraala's bird totem and see if I can use it to transform the birds back into people."},
			["Find the Bird Totem"] =
				{appendText=" on the east side of the cavern. Look for a place where the ceiling opens up to reveal the sky above, shining light down on a stone altar. In front of the altar, surrounded by bones and birds, a chest containing the totem can be found.\n"},
			[2] = 
				{appendStepText="", stepTextKey="I can't seem to make the bird totem work. Maybe someone at the Mages Guild in Orsinium can help me figure out how to reverse the Birdsong's curse."},
			["Take the Totem to the Orsinium Mages Guild"] =
				{appendText=" on the west side of the city.\n"},
			[3] = 
				{appendStepText="In Orsinium, ", stepTextKey="There's an Argonian in the Mages Guild named Deechee-Noo. I should ask if she knows how to reverse the bird totem's curse."},
			["Talk to Deechee-Noo 1"] =
				{appendText=", reading a book just within the entrance to the Guild. Surely explaining the bird totem's discovery is worth interrupting her.\n", stepTextKey="There's an Argonian in the Mages Guild named Deechee-Noo. I should ask if she knows how to reverse the bird totem's curse."},
			[4] = 
				{appendStepText="In the Orsinium Mage's Guild, ", stepTextKey="Deechee-Noo asked me to collect a few items so she can perform a ritual that will reverse the bird totem's curse."},
			["Acquire Ancient Wing Bone"] =
				{appendText=". Deechee-Noo sends you to the marketplace, Haggler's Bluff, on Orsinium's southwest side. Look for the Redguard Rasna, standing between the furniture sellers Maladdiq, a Khajiit, and Lozotusk, an Orc.\n"},
			["Acquire Potion of Feather Plucking"] =
				{appendText=". Deechee-Noo mentions an alchemy shop in town that might have what's needed. Conveniently, Hydalion's Potions & Elixrs can be reached through a door near the north end of the Mage's Guild. Once there, speak with the Altmer Telarnel.\n"},
			["Acquire Frozen Egg"] =
				{appendText=". Deechee-Noo suggests you try the marketplace, Haggler's Bluff. Banners of crossed forks and knives surround the stall you seek, and underneath, the Bosmer Nednor trades his wares.\n"},
			[5] = 
				{appendStepText="In Orsinium, ", stepTextKey="I gathered the items Deechee-Noo requested. I should bring them back to her so she can perform the ritual to reverse the bird totem's curse."},
			["Return to Deechee-Noo"] =
				{appendText=" in the Orsinium Mage's Guild. She waits for your return upstairs, on the east side. Her tail swishes in eagerness to begin.\n"},
			[6] = 
				{appendStepText="In Orsinium's Mages Guild, ", stepTextKey="Deechee-Noo performed the ritual and thinks it was successful. I should talk to her to make sure."},
			["Talk to Deechee-Noo 2"] =
				{appendText=" in the Orsinium Mage's Guild. She waits to tell you the ritual's results upstairs, on the east side.\n", stepTextKey="Deechee-Noo performed the ritual and thinks it was successful. I should talk to her to make sure."},
		},
		[GetQuestName(5340)] = { -- "Blood and the Sacred Words"	-- SaipanDamashii
			[1] = 
				{appendStepText="", stepTextKey="The dying archivist asked me to gather blood from all of the archivists that were killed by the Vosh Rakh, starting with her own. According to her, I'll need the blood to gain access to the sanctuary where the sacred words are stored."},
			["Gather Blood from the Archivists"] =
				{appendText=". \nArchivist Boldarkh’s corpse is inside Fharun Longhouse in the northwestern part of the Stronghold. \n\nArchivist Megorz’s corpse is inside the Ransacked Clan House at the top of some stairs, just behind a burning cart. \n\nArchivist Akur’s corpse is inside Fharun Feast Hall, down the stairs and across the courtyard from the Ransacked Clan House. \n"},
			[2] = 
				{appendStepText="", stepTextKey="A hooded Orc has appeared claiming to offer aid with my task. I should talk to him and see what he wants."},
			["Talk to Azrath 1"] =
				{appendText=", waiting to speak with you in front of the exit inside Fharun Feast Hall. \n", stepTextKey="A hooded Orc has appeared claiming to offer aid with my task. I should talk to him and see what he wants."},
			[3] = 
				{appendStepText="", stepTextKey="I gathered the blood of the fallen archivists and the Hooded Orc provided me with a book that should help me find the path to the sanctuary where the sacred words are stored. He said the path begins in Malacath's shrine in Fharun Keep."},
			["Find Malacath's Shrine in the Keep"] =
				{appendText=", the northernmost building in the Stronghold. \n"},
			[4] = 
				{appendStepText="", stepTextKey="I reached the shrine. According to the book, \"The shrine in Fharun Keep hides the path to the sanctuary. Only a gift of life's most precious fluid, freely given by the holy curators, will reveal the way.\" I need to figure out what this means."},
			["Open the Way to the Sanctuary"] =
				{appendText=". There are four Offering Bowls and I have four drops of Archivist Blood. \n"},
			[5] = 
				{appendStepText="", stepTextKey="Offering the blood of the archivists appears to have activated some ancient mechanism. I need to find the passage that leads to the hidden sanctuary."},
			["Search for Malacath's Hidden Sanctuary"] =
				{appendText=". I should read the Path of the Faithful to find out what to do next. \n"},
			[6] = 
				{appendStepText="", stepTextKey="I'm inside the hidden sanctuary beneath Fharun Stronghold. I should figure out how to retrieve the sacred words of Malacath as the dying archivist requested."},
			["Retrieve the Sacred Words"] =
				{appendText=". The Path of the Faithful tells me how to collect the Sacred Words. I should read it again. \n"},
			[7] = 
				{appendStepText="", stepTextKey="After I retrieved the scroll containing the sacred words of Malacath, Azrath appeared again. I should talk to him."},
			["Talk to Azrath 2"] =
				{appendText=", waiting to speak with me inside the Sanctuary of Malacath, deep within Fharun Keep. I need to take the first left upon entering the Keep and go down the stairs to reach the Shrine of Malacath, then follow the guidance of the Path of the Faithful again to reach the Sanctuary. \n", stepTextKey="After I retrieved the scroll containing the sacred words of Malacath, Azrath appeared again. I should talk to him."},
			[8] = 
				{appendStepText="", stepTextKey="Azrath asked me to deliver the scroll containing the sacred words of Malacath to someone named Kroma. I will find her in a house marked with Malacath's light in Orsinium's residential district."},
			["Deliver the Scroll"] =
				{appendText=". Kroma gra-Makla is inside Bludrath’s House, at the foot of the stairs leading up to Scarp Keep, across from the Orsinium Outlaws Refuge. \n"},
		},
	[GetQuestName(5469)] = { --"Blood Price"				-- Jordakai
		[1] = 
			{appendStepText="At Shatul Range, north of Orsinium, I spoke with the former Chief's hearth-wife in her tent. ", stepTextKey="Rogzesh asked me to find evidence of this Daedric connection. She suggested searching Glagosh's tent, as well as the giant camp where Chief Ogzor was struck. I should also ask Lugbagg if he noticed anything suspicious the night before the chief was wounded."},
		["Talk to Lugbagg"] =
			{appendText=". He is tending the echatere in their enclosure behind Rogzesh's tent.\n"},
		["Search the Giant Camp"] =
			{appendText=" southwest of the Shatul settlement. Perhaps I should start by looking around near the campfire.\n"},
		["Search Glagosh's Tent"] =
			{appendText=" in the south area of the settlement, next to the former Chief's tent where she kneels in grief."},
		[2] = 
			{appendStepText="", stepTextKey="I found a copy of Boethiah's Glory in Glagosh's tent, as well as Poisoned Hunting Blade in the giant camp where Chief Ogzor was wounded. Lugbagg and Stugbrulz heard her moving around the night before the chief was wounded. I should see what Glagosh has to say about this."},
		["Confront Glagosh"] =
			{appendText=". She remains at her husband's tent, next to hers, at the south end of the encampment."},
		[3] = 
			{appendStepText="At Shatul Range, I spoke with the former Chief's hunt-wife. ", stepTextKey="Glagosh claims she had nothing to do with Chief Ogzor's death. I should speak with Rogzesh and see what she thinks of Rogzesh's explanations."},
		["Talk to Rogzesh 1"] =
			{appendText=" at the cooking fire in her tent.", stepTextKey="Glagosh claims she had nothing to do with Chief Ogzor's death. I should speak with Rogzesh and see what she thinks of Rogzesh's explanations."},
		[4] = 
			{appendStepText="At Shatul Range, I spoke with the former Chief's hearth-wife. ", stepTextKey="Rogzesh would not listen to reason. Despite the lack of evidence, she is convinced Glagosh is to blame for Chief Ogzor's death. I should speak with her and see what she intends."},
		["Talk to Rogzesh 2"] =
			{appendText=" at the cooking fire in her tent.", stepTextKey="Rogzesh would not listen to reason. Despite the lack of evidence, she is convinced Glagosh is to blame for Chief Ogzor's death. I should speak with her and see what she intends."},
		[5] = 
			{appendStepText="At Shatul Range, I spoke with the former Chief's hearth-wife. ", stepTextKey="Rogzesh has demanded Glagosh pay the blood price for causing Chief Ogzor's death and named me her champion in the matter. I should speak with Glagosh about Rogzesh's demands."},
		["Extract the Blood Price from Glagosh"] =
			{appendText="."},
		[6] = 
			{appendStepText="At Shatul Range, I spoke with the former Chief's hunt-wife. ", stepTextKey="Glagosh refused to pay the blood price to Rogzesh, but chose exile to prevent further animosity in Shatul. I should speak with Rogzesh to make sure the grudge is settled."},
		["Talk to Rogzesh 3"] =
			{appendText=" at the cooking fire in her tent.", stepTextKey="Glagosh refused to pay the blood price to Rogzesh, but chose exile to prevent further animosity in Shatul. I should speak with Rogzesh to make sure the grudge is settled."},
		[7] = 
			{appendStepText="At Shatul Range, ", stepTextKey="I agreed to extract the blood price from Glagosh through honorable combat. I should meet her by the river."},
		["Defeat Glagosh"] =
			{appendText=". She will be near the river, beyond a stone bridge, far north of Shatul Range."},
		[8] = 
			{appendStepText="North of a stone bridge on the river's east bank, ", stepTextKey="I extracted the blood price from Glagosh through honorable combat. I should speak with Rogzesh to make sure the grudge is settled."},
		["Talk to Rogzesh 4"] =
			{appendText=" at the cooking fire in her tent.", stepTextKey="I extracted the blood price from Glagosh through honorable combat. I should speak with Rogzesh to make sure the grudge is settled."},
		[9] = 
			{appendStepText="At Shatul Range, I spoke with the former Chief's hunt-wife. ", stepTextKey="With my help, Glagosh agreed to pay the blood price to Rogzesh. I should speak with Rogzesh to make sure the grudge is settled."},
		["Talk to Rogzesh 5"] =
			{appendText=" at the cooking fire in her tent.", stepTextKey="With my help, Glagosh agreed to pay the blood price to Rogzesh. I should speak with Rogzesh to make sure the grudge is settled."},
		[10] = 
			{appendStepText="At Shatul Range, I spoke with the former Chief's hearth-wife. ", stepTextKey="I convinced Rogzesh that Glagosh was not to blame for Chief Ogzor's death. I should speak with her and see if she is willing to end her grudge."},
		["Talk to Rogzesh 6"] =
			{appendText=" at the cooking fire in her tent.", stepTextKey="I convinced Rogzesh that Glagosh was not to blame for Chief Ogzor's death. I should speak with her and see if she is willing to end her grudge."},
	},
		[GetQuestName(5317)] = { -- "Broken Promises"				-- SaipanDamashii
			[1] = 
				{appendStepText="", stepTextKey="I should search the ruins for clues to the Royal Messenger's fate."},
			["Search for King Emeric's Messenger"] =
				{appendText=". I should keep exploring the Hold to find the Royal Messenger. \n"},
			[2] = 
				{appendStepText="", stepTextKey="It seems High-King Emeric's Royal Messenger was killed. I should inform Sergeant Oufa in Orsinium."},
			["Talk to Sergeant Oufa"] =
				{appendText=", who has to put up with the sound of chickens clucking all day beneath her as she keeps a vigilant watch over the western gate, just up the hill from the Shatul Clan Corral. \n"},
		},
		[GetQuestName(5479)] = { -- "A Cold Wind From the Mountain"	-- JayAstrophel
			[1] = 
				{appendStepText="In Orsinium, ", stepTextKey="I found a notice asking me to speak with Curator Umutha."},
			["Talk to Curator Umutha 1"] =
				{appendText=" in the House of Orsimer Glories. Red banners, each depicting a ferocious face, are hanging on the outside. The curator waits just inside, keeping watch over the many artifacts now stored here.\n", stepTextKey="I found a notice asking me to speak with Curator Umutha."},
			[2] = 
				{appendStepText="", stepTextKey="Curator Umutha wants me to unearth the skull of the ancient snow bear, Coldwind. To recover Coldwind's Skull, I need to head to northern Wrothgar and locate the snow bear's den."},
			["Find Coldwind's Den"] =
				{appendText=". Far north of Orsinium, the den is northeast of the Two Rivers wayshrine, south of the boat to Icereach, and directly north of Sorrow's Kiss. A carved stone door at the end of a dirt path, set into the cliffside, leads into the den.\n"},
			[3] = 
				{appendStepText="To the north, the den's door is carved into the cliffs south of Icereach and north of Sorrow's Kiss. ", stepTextKey="The tomb is supposed to be somewhere inside Coldwind's ancient den. It may be protected from intruders."},
			["Enter Coldwind's Tomb"] =
				{appendText=" on the northeast side of the den.\n"},
			[4] = 
				{appendStepText="To the north, the den's door is carved into the cliffs south of Icereach and north of Sorrow's Kiss. On the northeast side of the den, I found a ghost. ", stepTextKey="The ancient shade beckons me. I should talk to him."},
			["Talk to the Shade of Torug"] =
				{appendText=". This golden ghost stands in the chamber on the northeast part of the den.\n"},
			[5] = 
				{appendStepText="To the north, the den's door is carved into the cliffs south of Icereach and north of Sorrow's Kiss. On the northeast side of the den, I found a ghost. ", stepTextKey="King Torug's shade wants me to learn about Wrothgar's past by placing ceremonial objects in the offering bowls situated around this room."},
			["Replay the Past"] =
				{appendText=". Take the items from the west side of the room. There are four in total, each one resting in a bowl behind one of the pillars. You must take one at a time and place them in the proper offering bowls around the center platform.\n"},
			[6] = 
				{appendStepText="To the north, the den's door is carved into the cliffs south of Icereach and north of Sorrow's Kiss. On the northeast side of the den, ", stepTextKey="I witnessed a reenactment of Torug uniting with Coldwind. I can take the snow bear's skull now."},
			["Take Coldwind's Skull"] =
				{appendText=", resting in the open coffin on the east side of the room. Having experienced the history of this mighty bear, I now have a tale to tell.\n"},
			[7] = 
				{appendStepText="", stepTextKey="Back at the House of Orsimer Glories, the curator waits for me to bring her the Skull of Coldwind."},
			["Talk to Curator Umutha 2"] =
				{appendText=" in Orsinium. Red banners, each depicting a ferocious face, are hanging on the outside. The curator waits just inside, hoping to hear of the relic's rediscovery.\n", stepTextKey="Back at the House of Orsimer Glories, the curator waits for me to bring her the Skull of Coldwind."},
		},
		[GetQuestName(5452)] = { -- "Corgrak's Cairn"				-- SaipanDamashii
			[1] = 
				{appendStepText="", stepTextKey="I should search Morkul Descent for the helm. Brulak last saw it in the possession of the ogre chief."},
			["Retrieve Corgrak's Helm"] =
				{appendText=". Morkul Descent is just west of the Morkuldin Forge and directly north of the Forlorn Watchtower. \n"},
			[2] = 
				{appendStepText="", stepTextKey="I recovered the helm. I should give it to Brulak."},
			["Talk to Brulak"] =
				{appendText=", who eagerly waits for you to return with his grandfather’s helm at his cairn just outside of Morkul, north of Morkul Plain Wayshrine. \n"},
		},
[GetQuestName(5442)] = { --"Cultural Affections"				--Aashiana
        [1] = 
            {appendStepText="Standing near his boat at the Morkul Stronghold docks in western Wrothgar, ", stepTextKey="Rigurt wants me to collect food that Orcs consider seductive so that he can prepare a romantic meal for Ambassador Lazdutha. He has given me Nordic equivalents to trade for Orc cheese and Orc ale. He also wants Orc poetry and perfume—just in case."},
        ["Find Orc Cheese"] =
            {appendText=". Before I go, I should speak with Rulfala about these Orcish delicacies. She is at the docks close to where Rigurt is standing. I am certain she has a wealth of knowledge about Orcish culture and looks eager to share it with me. \n\nNorth of Skalar's Hostel in Orsinium's northwestern outskirts, there is an echatere stable. Perhaps someone there knows how to make a special cheese."},
        ["Find Orc Ale"] =
            {appendText=". In southwest Wrothgar, a road leads east from the Siege Road Wayshrine. Look for a spectacular waterfall at a small lake. Then head north, up the hill to a rocky bluff with a small settlement. The bearded brewmaster, Lum gro-Buzbee, may be wiling to trade some of his famous ale for a bottle of rare Nord mead."},
        ["Find Orc Love Poem"] =
            {appendText=". Rulfala recommended a famed Redguard poet, currently seeking inspiration in the wilds of Wrothgar. \n\nFrom the Orc settlement west of the Morkul Plain Wayshrine, follow a path up a hill marked by dolmen archways. Near a small cart by a large tree stump, a robed Redguard stands high on the rocks, looking out over the landscape near Exile's Barrow. "},
        ["Find Orc Perfume"] =
            {appendText=". West of the northern settlement of Sorrow, Hunt-wife Yatzog crouches by a huge stone outcropping, looking out over an icy bay. Follow her advice for making a \"perfume\" that only an Orc could love. \n\nEast of Two Rivers Wayshrine and south of Sorrow, on the river below a stunning waterfall, a large white bear has what I seek."},
        [2] = 
            {appendStepText="", stepTextKey="I collected the items Rigurt needs to prepare a romantic dinner for Ambassador Lazdutha, the Orc he wants to woo. I should return to Morkul Clanhold and give him the items."},
        ["Talk to Rigurt 1"] =
            {appendText=", still standing near his boat moored at the docks.", stepTextKey="I collected the items Rigurt needs to prepare a romantic dinner for Ambassador Lazdutha, the Orc he wants to woo. I should return to Morkul Clanhold and give him the items."},
        [3] = 
            {appendStepText="At the western town of Morkul Stronghold, ", stepTextKey="I should talk to Rigurt and give him the things he needs to prepare a romantic evening for Ambassador Lazdutha."},
        ["Talk to Rigurt 2"] =
            {appendText=", still standing near his boat moored at the docks.", stepTextKey="I should talk to Rigurt and give him the things he needs to prepare a romantic evening for Ambassador Lazdutha."},
    },
    
[GetQuestName(5439)] = { --"Draugr Dilemma"				--Aashiana
[1] = 
{appendStepText="Southwest of the Morkul Plain Wayshrine, ", stepTextKey="I need to go to the old Nord barrow and check on the treasure hunter named Narsis Dren. I should look for him in the barrow at the top of the hill."},
["Find Narsis Dren"] =
{appendText=". For reasons known only to him, he is lying inside of a sarcophagus, just to the right of where I entered the barrow."},
[2] = 
{appendStepText="Just inside Exile's Barrow, on a hill southwest of the Morkul Plain Wayshrine, I learned that ", stepTextKey="Narsis Dren believes we can find a way to return the draugr to their rest in the barrow's main burial chamber. He wants me to lead the way as we search for it."},
["Find the Main Burial Chamber"] =
{appendText=", down the stairs and through the stone archway behind a broken throne."},
[3] = 
{appendStepText="On a hill southwest of the Morkul Plain Wayshrine, we entered Exile's Barrow. ", stepTextKey="Inside the antechamber, we found a large, impressive door that must lead to the main burial chamber. Maybe Narsis Dren has an idea about how we can open it. I should talk to him."},
["Talk to Narsis Dren 1"] =
{appendText=". He thinks the door can be unlocked using carved stone tablets that fit into the pillars in the antechamber. A book on a stone altar nearby may have some notes on the construction of this tomb.", stepTextKey="Inside the antechamber, we found a large, impressive door that must lead to the main burial chamber. Maybe Narsis Dren has an idea about how we can open it. I should talk to him."},
[4] = 
{appendStepText="Southwest of the Morkul Plain Wayshrine, inside the central antechamber of Exile's Barrow, ", stepTextKey="Narsis Dren thinks that we need to solve a puzzle lock to open the door to the main burial chamber. But three of the stone panels are broken. We need to find the missing pieces of the panels before we can attempt to solve the puzzle."},
["Find East Barrow Pieces"] =
{appendText=". I should search the eastern area for a small, pointed broken panel piece and anything else that can help us, maybe near a significant carving or artifact."},
["Find South Barrow Pieces"] =
{appendText=". I should search the southern chambers for the other broken panel pieces. In the first chamber, there is a dais with three tombs. Perhpas one of the panel pieces is there. The last broken panel piece could be in the next chamber, or perhaps in the northbound hallway that returns to the central antechamber."},
[5] = 
{appendStepText="Southwest of Morkul Plain Wayshrine, within Exile's Barrow, we returned to the central antechamber. ", stepTextKey="We have the broken puzzle pieces. Now we need to solve the puzzle lock to open the doors to the main burial chamber. Perhaps Narsis Dren has an idea about how we should proceed."},
["Unlock the Main Burial Chamber"] =
{appendText=" by placing the puzzle pieces in the broken panels of the columns. Narsis Dren asked me to activate the four panels in the correct order, based on the story told by the bas relief carvings we saw. If I can't remember the order, I'll just have to try them out and see what happens."},
[6] = 
{appendStepText="Inside Exile's Barrow, southwest of the Morkul Plain Wayshrine, Narsis Dren headed west from the central antechamber. ", stepTextKey="I should follow Narsis Dren through the door and speak to him on the other side."},
["Talk to Narsis Dren 2"] =
{appendText=", just inside the western main burial chamber.", stepTextKey="I should follow Narsis Dren through the door and speak to him on the other side."},
[7] = 
{appendStepText="Inside Exile's Barrow, southwest of the Morkul Plain Wayshrine, we left the central Antechamber. ", stepTextKey="Now that we have found the ancient tomb, we should see if we can find a way to end the draugr incursions."},
["Explore the Main Burial Chamber"] =
{appendText=". Apparently Narsis expects trouble since he wants me to enter first. Undoubtedly I will be fighting more draugr."},
[8] = 
{appendStepText="Inside Exile's Barrow, southwest of the Morkul Plain Wayshrine, in the western main burial chamber, ", stepTextKey="I defeated the ancient dragon priest of the barrow. Narsis Dren grabbed something and ran off, yelling about a treasure vault. I should catch up to him."},
["Follow Narsis to the Treasure Vault"] =
{appendText=" through the double doors on the north wall of the Dragon Priest's tomb. He is probably headed to the northernmost chamber of the barrow."},
[9] = 
{appendStepText="Southwest of the Morkul Plain Wayshrine, I entered the northernmost chamber of Exile's Barrow. ", stepTextKey="Narsis Dren led me to the treasure vault, which was likely his goal all along. I should speak to him."},
["Talk to Narsis Dren 3"] =
{appendText=" to find out what he was hoping to find here.", stepTextKey="Narsis Dren led me to the treasure vault, which was likely his goal all along. I should speak to him."},
[10] = 
{appendStepText="We found the Treasure Vault of Exile's Barrow, the burial site on a hill southwest of the Morkul Plain Wayshrine. And ", stepTextKey="I've had it up to here with Narsis Dren. It will serve him right if I trap him in a sarcophagus."},
["Trick Narsis"] =
{appendText=" by convincing him another Dragon Priest is nearby."},
[11] = 
{appendStepText="In the northernmost chamber, the Treasure Vault of Exile's Barrow, ", stepTextKey="I tricked Narsis Dren into a sarcophagus. Now I should close the lid."},
["Close the Sarcophagus"] =
{appendText=" and let the Orcs whose settlement these draugr invaded decide his fate."},
[12] = 
{appendStepText="The Orc village is down the hill, just north of Exile's Barrow. ", stepTextKey="I should return to the village and let Mazgroth know what Narsis Dren did. He may have caused the draugr problem, but at least he helped me fix it in the end."},
["Talk to Mazgroth 1"] =
{appendText=", standing near the village's stage where a musician is performing.", stepTextKey="I should return to the village and let Mazgroth know what Narsis Dren did. He may have caused the draugr problem, but at least he helped me fix it in the end."},
[13] = 
{appendStepText="In the Orc village, just north of the barrow, ", stepTextKey="I should tell Mazgroth the truth about what occurred in the Exile's Barrow."},
["Talk to Mazgroth 2"] =
{appendText=". She is standing near the stage listening to a musician.", stepTextKey="I should tell Mazgroth the truth about what occurred in the Exile's Barrow."},
[14] = 
{appendStepText="", stepTextKey="So all of this was Narsis Dren's fault. Still, we were able to defeat the Dragon priest and the draugr should start to settle down now. I should return to Mazgroth's clan and make sure everything is all right."},
["Return to Mazgroth's Village"] =
{appendText=", southeast of the Morkul Plain Wayshrine and just north of Exile's Barrow."},
[15] = 
{appendStepText="Southwest of the Morkul Plain Wayshrine, I returned to the Orc village north of Exile's Barrow. ", stepTextKey="I should talk to Narsis Dren and convince him to tell the Orcs the truth about Exile's Barrow."},
["Talk to Narsis Dren 4"] =
{appendText=", standing on a stage in the village, telling tales of his adventures in the barrow.", stepTextKey="I should talk to Narsis Dren and convince him to tell the Orcs the truth about Exile's Barrow."},
[16] = 
{appendStepText="Southwest of the Morkul Plain Wayshrine, I returned to the Orc village north of Exile's Barrow. ", stepTextKey="I should tell Mazgroth the truth about what occurred in the Exile's Barrow."},
["Talk to Mazgroth 3"] =
{appendText=", standing by a tent near the stage.", stepTextKey="I should tell Mazgroth the truth about what occurred in the Exile's Barrow."},
[17] = 
{appendStepText="Southwest of the Morkul Plain Wayshrine, I returned to the Orc village north of Exile's Barrow. ", stepTextKey="I convinced Narsis to offer the Orcs some gold for the trouble he caused them. I should let Mazgorth know that the draugr won't be bothering them any longer."},
["Talk to Mazgroth 4"] =
{appendText=", standing to the left of the stage by a tent.", stepTextKey="I convinced Narsis to offer the Orcs some gold for the trouble he caused them. I should let Mazgorth know that the draugr won't be bothering them any longer."},
},
[GetQuestName(5320)] = { --"The Durzog Whistle"				--Aashiana
        [1] = 
            {appendStepText="Nikolvara's Kennel is near the western shore of a lake at the bottom of a waterfall, northwest of Merchant's Gate Wayshrine and southeast of Trader's Road Wayshrine. Inside, ", stepTextKey="I should look for the durzog lair and find the beast-master's whistle."},
        ["Obtain Nikolvara's Whistle"] =
            {appendText=" from the kennels. I should explore the caverns and upper open area until I find it. Perhaps it will be at a campsite in a container, like a backpack."},
        [2] = 
            {appendStepText="Southwest of Trader's Road Wayshrine, at an upper western campsite in the kennels, ", stepTextKey="I found the whistle. I should test its beast-taming powers on the durzogs in Nikolvara's Kennel."},
        ["Test Nikolvara's Whistle on a Durzog"] =
            {appendText=" to see how it reacts to the whistle. There appear to be wild durzogs across the bridge, north of the campsite."},
        [3] = 
            {appendStepText="At the kennel, I learned what I needed to know about the durzog whistle. ", stepTextKey="When I used the whistle, the durzogs became agitated and attacked me. I should find Fedar and decide what to tell him about the true nature of the whistle."},
        ["Talk to Fedar Githrano 1"] =
            {appendText=". After that adventure, I could use an ale! Skalar's Hostel, northwest of Orsinium, is popular with traders. Perhaps I'll find the white-haired Dunmer, Fedar, near that tavern.", stepTextKey="When I used the whistle, the durzogs became agitated and attacked me. I should find Fedar and decide what to tell him about the true nature of the whistle."},
        [4] = 
            {appendStepText="Near Skalar's Hostel, the tavern northwest of Orsinium, ", stepTextKey="I told Fedar the truth about the whistle. I should speak to him to collect my reward."},
        ["Talk to Fedar Githrano 2"] =
            {appendText=". He wasn't happy, but I earned my reward!", stepTextKey="I told Fedar the truth about the whistle. I should speak to him to collect my reward."},
        [5] = 
            {appendStepText="Near Skalar's Hostel, the tavern northwest of Orsinium, ", stepTextKey="I lied to Fedar about the whistle. I should speak to him to collect my reward."},
        ["Talk to Fedar Githrano 3"] =
            {appendText=", and try not to feel guilty about what happens next!", stepTextKey="I lied to Fedar about the whistle. I should speak to him to collect my reward."},
    },
		[GetQuestName(5472)] = { -- "A Feast To Remember"			-- Aashiana
			[1] = 
				{appendStepText="At her pavilion near the Morkuldin Forge, ", stepTextKey="Orzorga asked me to bring her some glacial tomatoes, tundra truffles, and durzog lichen. Orzorga also wants me to collect a bear head from Gnarl-fang, the bear that broke into and ate one of her food shipments."},
			["Gather Glacial Tomato"] =
				{appendText="es from a farm on the northern outskirts of Orsinium."},
			["Gather Tundra Truffle"] =
				{appendText="s near the Aquaduct north of Frostbreak Fortress in southern Wrothgar. I'll have to compete with the bears, who also enjoy the tasty truffles."},
			["Gather Durzog Lichen"] =
				{appendText=", growing along a stream east of the Morkul Stronghold, near the Icy Shore."},
			["Get Bear Head from Gnarl-Fang"] =
				{appendText=", lying already dead on the ice west of Fharun Stronghold. The giant bear may have eaten all of Orzorga's coffee from a nearby shipwreck."},
			[2] = 
				{appendStepText="", stepTextKey="I have the ingredients Orzorga requested. I should bring them to her."},
			["Bring the Ingredients to Orzorga"] =
				{appendText=", who is preparing her feast in her kitchen north of the Morkuldin Forge."},
			[3] = 
				{appendStepText="", stepTextKey="I tasted the smoked bear's head. I should let Orzorga know what I thought of it."},
			["Talk to Orzorga 1"] =
				{appendText=" about this unusual dish with a hint of coffee, her centerpiece for the feast.", stepTextKey="I tasted the smoked bear's head. I should let Orzorga know what I thought of it."},
			[4] = 
				{appendStepText="", stepTextKey="I tasted the smoked bear's head. I should let Orzorga know what I thought of it."},
			["Talk to Orzorga 2"] =
				{appendText=" about whether it would be better to remove all the bear's teeth before serving the dish.", stepTextKey="I tasted the smoked bear's head. I should let Orzorga know what I thought of it."},
			[5] = 
				{appendStepText="", stepTextKey="I brought Orzorga what she wanted. I should speak with her."},
			["Talk to Orzorga 3"] =
				{appendText=" about her final culinary creation for the King's feast.", stepTextKey="I brought Orzorga what she wanted. I should speak with her."},
		},
[GetQuestName(5520)] = { --"Flames of Forge and Fallen"				-- Aashiana
		[1] = 
			{appendStepText="In western Wrothgar’s Old Orsinium, I spoke to Nashruth just inside the door. He gave me an important task to complete before he died of his injuries. A note on a rock at the base of the stairs outside leading up to the dungeon may provide a clue that will help me complete this task. ", stepTextKey="I need to light a brazier to begin the \"Rites of Praise and Scorn.\" If the Daedric Prince Malacath deems me worthy, he will supposedly guide me through something called Hammer's Bypass and Temper's Fork."},
		["Begin the Rites of Praise and Scorn"] =
			{appendText=" by lighting the brazier at the fork in the tunnel, just west of the entrance. Follow either tunnel to the southern exit. A double-bladed axe is set into the ground, an aspect of Malacath. Perhaps I should examine it to learn more."},
		[2] = 
			{appendStepText="I entered Old Orsinium's tunnels and followed them to the southern ruins. ", stepTextKey="I should seek the guidance of Malacath to get me through Hammer's Bypass."},
		["Talk to the Aspect of Malacath 1"] =
			{appendText=", hands gripping a shining, double-bladed axe with a red ribbon, just after entering the area.", stepTextKey="I should seek the guidance of Malacath to get me through Hammer's Bypass."},
		[3] = 
			{appendStepText="Within the southern ruins, ", stepTextKey="I must honor the clans who built Old Orsinium to unlock Hammer's Bypass. I should light the braziers to learn the founding clans."},
		["Honor Orsinium's Founding Clans"] =
			{appendText=" \n\nLight the braziers of the four clans and hear their contributions.\n\nLight the Morkul Clan brazier to the southeast, in front of a carving of a burning anvil.\n\nLight the Igrun Clan brazier to the north, below the golden banner of three towers.\n\nLight the Tumnosh Clan brazier to the northwest, near a carving of crossed pickaxes.\n\nLight the Shatul clan brazier to the southwest, near a blue banner with a golden sigil."},
		[4] = 
			{appendStepText="Within the southern ruins, I found an octagonal puzzle with clan sigils near carved stone doors in the northern wall. ", stepTextKey="The four honored clans who built Old Orsinium are the key to unlocking Hammer's Bypass. I should press the floor panels matching the honored clans."},
		["Unlock Hammer's Bypass"] =
			{appendText=". A body of a female orc lying near the puzzle bears a note that may be helpful. I must press the sigils of each of the four honored clans in a specific order to solve the puzzle and open the door. Listen to the words of Malacath once the puzzle is solved and continue through the door to the interior of Old Orsinium."},
		[5] = 
			{appendStepText="Within the southern ruins, I unlocked a door in the north wall leading into Old Orsinium.", stepTextKey="I should seek the guidance of Malacath to get me through Temper's Fork."},
		["Talk to the Aspect of Malacath 2"] =
			{appendText=". Travel along the passageway to a large octagonal room with a pillar in the center, then continue through the north hallway to find another Aspect of Malacath near a torn tapestry of war.", stepTextKey="I should seek the guidance of Malacath to get me through Temper's Fork."},
		[6] = 
			{appendStepText="Within the southern ruins, I unlocked a door in the north wall leading into Old Orsinium and continued to the north. Malacath told me ", stepTextKey="I must curse the clans that caused Old Orsinium's downfall to unlock Temper's Fork. I should light the braziers to learn which clans failed Malacath."},
		["Curse Orsinium's Fallen Clans"] =
			{appendText=". \n\n Continue north to the large open area in the center of the city. Light the braziers of the four clans and hear how they contributed to the downfall of Old Orsinium.\n\nLight the brazier of Bagrath, on the floor below near the wooden ramp.\n\nLight the brazier of Shatul, up a platform to the east, through the eastern archway in the second room.\n\nLight the brazier of Fharun, up the stone stairs on the west side and through the northwestern archway, in an alcove to the southeast.\n\nLight the brazier of Igrun, up the stone stairs on the west side and through the northwestern archway, in a large square room to the northwest. The brazier is on a ledge in the northeast corner."},
		[7] = 
			{appendStepText=" Within the southern ruins, I unlocked a door in the north wall leading further north into the center of Old Orsinium. I have lit the four braziers of the cursed clans.", stepTextKey="The four cursed clans who caused Old Orsinium's downfall are the key to unlocking Temper's Fork. I should press the floor panels matching the cursed clans."},
		["Unlock Temper's Fork"] =
			{appendText=" at the top of the stone stairs on the west side of the central area. A skeleton with a journal just beyond the octagonal puzzle may provide useful clues."},
		[8] = 
			{appendStepText="Within the southern ruins, I unlocked a door in the north wall leading further north into the center of Old Orsinium. I unlocked another door at the top of the stone stairs on the west side of the central area leading to the Old Orsinium Forges.  ", stepTextKey="I must light the great pyre at the heart of Old Orsinium to complete the Rites of Praise and Scorn. Nashruth's order will try to stop me, as part of the rites."},
		["Light the Great Pyre"] =
			{appendText=", through the wooden door past the octagonal puzzle. Continue straight ahead, then go through another wooden door to the east into the central forge area. The Great Pyre is in the center of the northernmost chamber."},
		[9] = 
			{appendStepText="Within the southern ruins, I unlocked a door in the north wall leading further north into the center of Old Orsinium. I unlocked another door at the top of the stone stairs on the west side of the central area, leading to the Old Orsinium Forges. In the northernmost chamber, ", stepTextKey="I lit the great pyre at the heart of Old Orsinium. It seems Malacath, the Daedric Prince of Vengeance, has something to say to me. I should speak with him."},
		["Talk to Aspect of Malacath"] =
			{appendText=", up the stone stairs behind the Great Pyre."},
	},
[GetQuestName(5464)] = { --"Forcing the Faith"					--Aashiana
		[1] = 
			{appendStepText="Just west of the Siege Road Wayshrine, ", stepTextKey="I met an Orc artisan who claims to have been part of caravan that was attacked by the Vosh Rakh. He says that he and one other member of the caravan escaped, but the rest were taken captive. I should find Razasha and see what she knows."},
		["Talk to Razasha 1"] =
			{appendText=", crouching behind a stone wall near the trail outside the western citadel of Paragon's Remembrance.", stepTextKey="I met an Orc artisan who claims to have been part of caravan that was attacked by the Vosh Rakh. He says that he and one other member of the caravan escaped, but the rest were taken captive. I should find Razasha and see what she knows."},
		[2] = 
			{appendStepText="Near the western citadel of Paragon's Remembrance, ", stepTextKey="I agreed to aid Razasha and rescue Shaldagan and the other Orcs that were taken captive by the Vosh Rakh. I should enter the nearby ruins and look for the kidnapped travelers."},
		["Locate the Kidnapped Travelers"] =
			{appendText=". Enter Paragon's Remembrance. Travel straight ahead, up the stone stairs, to the central hall. In the first chamber to the south, there is a list of all the prisoners and their whereabouts on the table."},
		[3] = 
			{appendStepText="In the western citadel of Paragon's Remembrance, I reached the eastern room south of the central hall. ", stepTextKey="There's a captive in a cage near Glothun the Recruiter. I should set him free."},
		["Free Thorkh"] =
			{appendText=" from the cage to the left of the table."},
		[4] = 
			{appendStepText="In the western citadel of Paragon's Remembrance, I am in the eastern room south of the central hall. ", stepTextKey="Now that I set the captive free, I should talk to him and see what he can tell me about this place."},
		["Talk to Thorkh"] =
			{appendText="."},
		[5] = 
			{appendStepText="In the western citadel of Paragon's Remembrance, in the eastern room to the south of the central hall, ", stepTextKey="I freed Thorkh, one of the unwilling recruits brought to Paragon's Remembrance. According to Glothun's list I still need to find Shaldagan, Morushna, Batasha, and the two mages, Unsulag and Garhar."},
		["Find Other Captives"] =
			{appendText=". \n\nIn the western room south of the central hall, free Shaldagan from the fires by filling a bucket with water from the pool behind the forge. I should talk with her to learn more about what is going on here.\n\nIn the western room north of the central hall, talk to both Gahar and Unsulag and decide what to do. Notes in the room provide more information on the design of these traps.\n\nIn the eastern room north of the central hall, free Batasha from the northern cage."},
		[6] = 
			{appendStepText="", stepTextKey="I freed as many of the cult's captives as I could. I should eliminate the leader of the cultists here in Paragon's Remembrance, Azhnura the Proselytizer. That should curtail the Vosh Rakh's recruitment efforts in Wrothgar."},
		["Eliminate Azhnura the Proselytizer"] =
			{appendText=" in the room northwest of the central hall."},
		[7] = 
			{appendStepText="Northwest of the central hall, ", stepTextKey="I eliminated the Proselytizer and her lieutenants. Now I need to find the back way out of here so that I can lead the freed captives to safety."},
		["Find Paragon's Remembrance's Back Exit"] =
			{appendText=", directly south of where I killed the Proselytizer. The captives I rescued are waiting for me there."},
		[8] = 
			{appendStepText="", stepTextKey="I set all of the captured Orcs free. Now I need to safely lead them out of the ruins of Paragon's Remembrance."},
		["Lead the Rescued Captives to Safety"] =
			{appendText=". They are waiting for me to the west of the central hall in the southern passage. Continue south outside and then down the stairs to the east. Follow a wooden ramp outside the stone walls, then down more stone stairs. At the stone table, continue north and then east through the last chamber to exit Paragon's Remembrance."},
		[9] = 
			{appendStepText="", stepTextKey="I led the rescued Orcs out of Paragon's Remembrance. I should talk to Razasha and make sure everyone's all right."},
		["Talk to Razasha 2"] =
			{appendText=". She is waiting just below the exit, east of the ruins.", stepTextKey="I led the rescued Orcs out of Paragon's Remembrance. I should talk to Razasha and make sure everyone's all right."},
		[10] = 
			{appendStepText="", stepTextKey="I led the rescued Orcs, including Shaldagan, out of the ruins of Paragon's Remembrance. Now I should exit the ruins and talk to Razasha to make sure everyone is all right."},
		["Talk to Razasha 3"] =
			{appendText=". She is waiting just below the exit, east of the ruins.", stepTextKey="I led the rescued Orcs, including Shaldagan, out of the ruins of Paragon's Remembrance. Now I should exit the ruins and talk to Razasha to make sure everyone is all right."},
	},
		[GetQuestName(5470)] = { -- "A Healthy Choice"				-- Aashiana
			[1] = 
				{appendStepText="At her pavilion near the Morkuldin Forge, ", stepTextKey="Orzorga asked me to bring her harpy brains, some harpy bile, and sedge grass."},
			["Gather Harpy Brains"] =
				{appendText=". Harpies are rumored to nest on the cliffs above the Great Bay, far to the southwest."},
			["Gather Harpy Bile"] =
				{appendText=" along with the brains."},
			["Gather Sedge Grass"] =
				{appendText=" from the shoreline of the Great Bay. The echateres also seem rather fond of it."},
			[2] = 
				{appendStepText="", stepTextKey="I have the ingredients Orzorga requested. I should bring them to her."},
			["Bring the Ingredients to Orzorga"] =
				{appendText=" at her pavilion near the Morkuldin Forge."},
			[3] = 
				{appendStepText="", stepTextKey="I tasted the \"brain pocket.\" I should let Orzorga know what I thought of it."},
			["Talk to Orzorga 1"] =
				{appendText=", who enthusiastically shared the history of this unusual dish.", stepTextKey="I tasted the \"brain pocket.\" I should let Orzorga know what I thought of it."},
			[4] = 
				{appendStepText="", stepTextKey="I tasted the \"brain pocket.\" I should let Orzorga know what I thought of it."},
			["Talk to Orzorga 2"] =
				{appendText=" about what happened when I ate it, and wait for the side effects to wear off.", stepTextKey="I tasted the \"brain pocket.\" I should let Orzorga know what I thought of it."},
			[5] = 
				{appendStepText="", stepTextKey="I brought Orzorga what she wanted. I should speak with her."},
			["Talk to Orzorga 3"] =
				{appendText=", who seems surprised that I didn't want to try this unusual dish.", stepTextKey="I brought Orzorga what she wanted. I should speak with her."},
		},

[GetQuestName(5321)] = { --"A Heart of Brass"				-- Aashiana
		[1] = 
			{appendStepText="", stepTextKey="I should search the ruin for Dorand, the leader of this expedition. Glurbasha thinks he might still be alive."},
		["Search for Dorand"] =
			{appendText=" inside the ruins, through the icy tunnels to a large cavern in the northeast. He lies injured on a snowy ledge above an ice-cold stream."},
		[2] = 
			{appendStepText="Within a large cavern northeast of the entrance, on a snowy ledge above the stream, ", stepTextKey="I found Dorand, the expedition's leader. Before he died, he said there was a terrible threat within these ruins. I should examine his notes."},
		["Examine Dorand's Final Notes"] =
			{appendText="."},
		[3] = 
			{appendStepText="Within a large cavern northeast of the entrance, on a snowy ledge above the stream, I found Dorand dying. ", stepTextKey="According to Dorand's notes, three pressure valves direct vast amounts of heat and power to a locked central chamber. He believed it was for some nefarious purpose. I should find and close these valves."},
		["Close the Inceptive Valve"] =
			{appendText=" across the wooden bridge and through the eastern archway. The valve is inside curved stone walls just beyond the arch."},
		["Close the Transductive Valve"] =
			{appendText=". Continue east to the vast open area at the center of Rkindaleft. Follow the stone ramp down to the first platform, then travel up the stone ramp to the east. The valve is just inside the building at the top of the ramp."},
		["Close the Astrictive Valve"] =
			{appendText=". Follow the curving stone ramp down to the northwest, then continue west on the snowy path along an icy stream, then up into the rocky hills. Continue through an area with dwarven pipes, then south up the snowy path to an entranceway with large stone arches. The valve is at the center of the arches."},
		[4] = 
			{appendStepText="Far to the west in the central open area, near the final valve, ", stepTextKey="Dorand suspected there was a great threat within the Tonal Auditorium. With the pressure valves closed, I should explore the central chamber."},
		["Explore the Tonal Auditorium"] =
			{appendText=", through the door to the west of the valve."},
		[5] = 
			{appendStepText="Inside the Tonal Auditorium, through a door in the upper west area of central Rkindaleft, ", stepTextKey="It seems the pressure valves had something to do with a massive Dwarven construct! I should defeat this Vessel of the Auditor."},
		["Defeat Vessel of the Auditor"] =
			{appendText=" on the central platform."},
		[6] = 
			{appendStepText="Inside the Tonal Auditorium, through a door in the upper west area of central Rkindaleft, ", stepTextKey="I defeated Vessel of the Auditor, which was controlled by a person connected with Rkindaleft itself. I should speak with him about his intentions."},
		["Talk to Harmonic Auditor"] =
			{appendText=", on a throne on a metal platform to the west."},
		[7] = 
			{appendStepText="Inside the Tonal Auditorium, through a door in the upper west area of central Rkindaleft, ", stepTextKey="Harmonic Auditor no longer poses a threat to Rkindaleft. With his plans in ruins, he asked me to end his suffering. I must decide whether to close the final pressure valve and kill him, or return to Glurbasha and leave him to his fate."},
		["Close Auditorial Valve to Kill Harmonic Auditor"] =
			{appendText=", behind his throne. "},
		["Return to Glurbasha and Leave Harmonic Auditor Alive"] =
			{appendText="."},
		[8] = 
			{appendStepText="Inside the Tonal Auditorium, through a door in the upper west area of central Rkindaleft, ", stepTextKey="I decided to kill Harmonic Auditor. I should return to Glurbasha and let her know what happened."},
		["Talk to Glurbasha 1"] =
			{appendText=". Leave the Tonal Auditorium. Head down the stairs to the right and through another door set into the far wall. Follow the icy tunnels south, then east, and south again until you come to a western passage. Glurbasha waits on the other side of the door by her campfire.", stepTextKey="I decided to kill Harmonic Auditor. I should return to Glurbasha and let her know what happened."},
		[9] = 
			{appendStepText="Inside the Tonal Auditorium, through a door in the upper west area of central Rkindaleft, ", stepTextKey="I decided to leave Harmonic Auditor to his fate. I should tell Glurbasha what happened."},
		["Talk to Glurbasha 2"] =
			{appendText=". Leave the Tonal Auditorium. Head down the stairs to the right and through another door set into the far wall. Follow the icy tunnels south, then east, and south again until you come to a western passage. Glurbasha waits on the other side of the door by her campfire.", stepTextKey="I decided to leave Harmonic Auditor to his fate. I should tell Glurbasha what happened."},
	},
[GetQuestName(5328)] = { --"Hidden History"				-- Aashiana
        [1] = 
            {appendStepText="", stepTextKey="I should search the ruins for evidence of what was done to the Orcs."},
        ["Search for Evidence"] =
            {appendText="  \n\nSouth of the waterfall in western Rkindaleft, a forgotten backpack against the rock wall may contain something of interest.\n\nIn northwest Rkindaleft, in an area of dwarven steamworks, crystal fragments in a pile of dwarven debris behind a wall may provide clues.\n\nAt the eastern end of the stream in central Rkindaleft, a biological specimen behind some urns near a large pillar looks interesting.\n\nIn the caves near the entrance to Rkindaleft, a dwarven platform along the north wall of the north-central cave appears to have some orcish remains.\n\nIn an alcove along the northern wall of the southern cave, there is a strange jug containing something unpleasant.\n\nIn a small square room to the northwest of the caves, a dwarven helmet sits on a table next to a dead orc."},
        [2] = 
            {appendStepText="Scattered throughout Rkindaleft, ", stepTextKey="I found several disturbing things which seem related to strange experiments and rituals performed on the Rkindaleft Orcs. I should bring them to Cinosarion."},
        ["Talk to Cinosarion 1"] =
            {appendText=", who has returned to the entrance to Rkindaleft, through the large metal door west of the cave complex.", stepTextKey="I found several disturbing things which seem related to strange experiments and rituals performed on the Rkindaleft Orcs. I should bring them to Cinosarion."},
        [3] = 
            {appendStepText="", stepTextKey="I should speak with Cinosarion about the evidence I found in the ruins."},
        ["Talk to Cinosarion 2"] =
            {appendText=", at the entrance to Rkindaleft.", stepTextKey="I should speak with Cinosarion about the evidence I found in the ruins."},
    },
[GetQuestName(5453)] = { --"A Khajiit's Tale"				-- Aashiana
		[1] = 
			{appendStepText="Past a small lake in Bonerock Caverns, in a large stone room with strange pillars, I found an old pack on a stone table. ", stepTextKey="The pack contained a medallion etched with two moons that appears to be the work of a Khajiit crafter. I should show it to Zhasim"},
		["Show the Medallion to Zhasim"] =
			{appendText="."},
		[2] = 
			{appendStepText="Past a small lake in Bonerock Caverns, in a large stone room with strange pillars, ", stepTextKey="Zhasim thinks the prayer wheel may reveal something about the medallion we found. There might be a hint around here to help us solve the puzzle."},
		["Solve the Puzzle"] =
			{appendText=". A journal near a stone pillar provides some clues. I should turn the pedestals by the table until the images match the clues."},
		[3] = 
			{appendStepText="Past a small lake in Bonerock Caverns, in a large stone room with strange pillars, ", stepTextKey="After we solved the prayer wheel puzzle, a coffer appeared. I should examine the coffer and see what's inside."},
		["Search the Coffer 1"] =
			{appendText=" that appeared inside the stone octagon on the floor when the puzzle was solved.", stepTextKey="After we solved the prayer wheel puzzle, a coffer appeared. I should examine the coffer and see what's inside."},
		[4] = 
			{appendStepText="Past a small lake in Bonerock Caverns, in a large stone room with strange pillars, ", stepTextKey="I found a scroll inside the coffer. I should talk to Zhasim about the contents of the scroll."},
		["Talk to Zhasim 1"] =
			{appendText=" about the letter that may have been left by his mother for him.", stepTextKey="I found a scroll inside the coffer. I should talk to Zhasim about the contents of the scroll."},
		[5] = 
			{appendStepText="Past a small lake in Bonerock Caverns, in a large stone room with strange pillars, ", stepTextKey="Zhasim ran deeper into the ruins to look for more clues about his past. I should look for him."},
		["Help Zhasim Explore the Ruins"] =
			{appendText=", looking for clues, like the note on the table in the next room. The carvings in the room may help unravel this riddle. I should activate the carvings in the correct order."},
		[6] = 
			{appendStepText="In the southeast room of Bonerock Caverns, ", stepTextKey="Another coffer appeared when we solved the riddle of the poem. I should see if it contains another scroll."},
		["Search the Coffer 2"] =
			{appendText=", which contains another letter from Zhasim's mother.", stepTextKey="Another coffer appeared when we solved the riddle of the poem. I should see if it contains another scroll."},
		[7] = 
			{appendStepText="In the southeast room of Bonerock Caverns, ", stepTextKey="I should talk to Zhasim about the contents of the second scroll."},
		["Talk to Zhasim 2"] =
			{appendText=" about the letter.", stepTextKey="I should talk to Zhasim about the contents of the second scroll."},
		[8] = 
			{appendStepText="In Bonerock Caverns, ", stepTextKey="Zhasim's mother used simple spells and children's puzzles to leave messages for him. I should help him find and solve the next puzzle."},
		["Determine the Next Puzzle"] =
			{appendText=", described in the note using a moon rhyme, in the northernmost room of the eastern passage. I should find the items described and place them as directed."},
		[9] = 
			{appendStepText="In the northernmost room along the eastern passage in Bonerock Caverns, ", stepTextKey="Now that I collected the three vases, I need to place them in the correct order on the pedestals near the small, tranquil pool."},
		["Place the Vases"] =
			{appendText=" in the correct order around the small pool behind the table."},
		[10] = 
			{appendStepText="In the northernmost room along the eastern passage in Bonerock Caverns, ", stepTextKey="A third coffer appeared when we solved the moons puzzle. I should check to see if it contains another scroll."},
		["Search the Coffer 3"] =
			{appendText=".", stepTextKey="A third coffer appeared when we solved the moons puzzle. I should check to see if it contains another scroll."},
		[11] = 
			{appendStepText="In the northernmost room along the eastern passage in Bonerock Caverns, ", stepTextKey="I found another scroll inside the coffer. I should talk to Zhasim about the contents of the third scroll."},
		["Talk to Zhasim 3"] =
			{appendText=", waiting by the table.", stepTextKey="I found another scroll inside the coffer. I should talk to Zhasim about the contents of the third scroll."},
		[12] = 
			{appendStepText="In the northeast area of Bonerock Caverns, ", stepTextKey="Zhasim ran ahead again, still looking for his cat and hoping to find another note from his mother. I should keep an eye out for him."},
		["Find Zhasim"] =
			{appendText=" to the west, in a small room to the north of the central northern cavern."},
		[13] = 
			{appendStepText="In Bonerock Caverns, in a small room to the north of the central northern cavern, ", stepTextKey="Zhasim found his mother's remains. I should speak to him and make sure he's all right."},
		["Talk to Zhasim 4"] =
			{appendText=". He has a lot to think about, and he still needs to find his cat!", stepTextKey="Zhasim found his mother's remains. I should speak to him and make sure he's all right."},
	},
		[GetQuestName(5454)] = { -- "Kindred Spirits"				-- Aashiana
			[1] = 
				{appendStepText="At a pavilion near the Morkuldin Forge, ", stepTextKey="Orzorga asked me to bring her wrathberries and a skin of ice stream water."},
			["Gather Wrathberries"] =
				{appendText=" along an ice-cold stream fed by a torrential waterfall in the eastern mountains. The red berries can be gathered from small shrubs near the water."},
			["Gather Skin of Ice Stream Water"] =
				{appendText=" at the base of the waterfall."},
			[2] = 
				{appendStepText="", stepTextKey="I have the ingredients Orzorga requested. I should bring them to her."},
			["Bring the Ingredients to Orzorga"] =
				{appendText=" at her pavilion near the Morkuldin Forge."},
			[3] = 
				{appendStepText="", stepTextKey="I tasted the \"cup of wrath.\" I should let Orzorga know what I thought of it."},
			["Talk to Orzorga 1"] =
				{appendText=", she seems very interested in hearing my impression of the drink!", stepTextKey="I tasted the \"cup of wrath.\" I should let Orzorga know what I thought of it."},
			[4] = 
				{appendStepText="", stepTextKey="I tasted the \"cup of wrath.\" I should let Orzorga know what I thought of it."},
			["Talk to Orzorga 2"] =
				{appendText=" about how to modify the recipe to avoid burning your tongue.", stepTextKey="I tasted the \"cup of wrath.\" I should let Orzorga know what I thought of it."},
			[5] = 
				{appendStepText="", stepTextKey="I brought Orzorga what she wanted. I should speak with her."},
			["Talk to Orzorga 3"] =
				{appendText=". She seems disappointed that I chose not to try the drink.", stepTextKey="I brought Orzorga what she wanted. I should speak with her."},
		},
