[GetQuestName(5484)] = { --"Of Sentimental Value"			-- Aashiana
        [1] = 
            {appendStepText="At a makeshift camp for shipwreck survivors northwest of the Icy Shore Wayshrine, ", stepTextKey="I agreed to try to find the gold pendant that Youss lost when he fled from the wrecked ships. I'll see if I can locate it among the wreckage of the frozen fleet."},
        ["Find the Pendant"] =
            {appendText=" among the shipwrecks north of the camp. A small coffer lies within a half-sunken ship, between two staircases."},
        [2] = 
            {appendStepText="North of a makeshift camp for shipwreck survivors in the Icy Shore, ", stepTextKey="I found a pendant while exploring the wrecked ships. I should bring it back to Youss and determine if it's the one he lost."},
        ["Return the Pendant to Youss"] =
            {appendText=", waiting at the camp to the south."},
        [3] = 
            {appendStepText="At the makeshift camp for shipwreck survivors northwest of the Icy Point Wayshrine, ", stepTextKey="One of the other survivors wants to talk to me. I should see what she wants before I return the pendant to Youss."},
        ["Talk to Azeeda 1"] =
            {appendText=", standing just down the hill from Youss by a crate and barrel.", stepTextKey="One of the other survivors wants to talk to me. I should see what she wants before I return the pendant to Youss."},
        [4] = 
            {appendStepText="At the makeshift camp for shipwreck survivors northwest of the Icy Point Wayshrine, ", stepTextKey="A woman claims the pendant belongs to her. I should try to determine who the piece of jewelry actually belongs to before I turn it over to either of them."},
        ["Talk to Youss"] =
            {appendText=", just up the hill from Azeeda, about his claim that the pendant belongs to him. Decide who you should give the pendant to."},
        ["Talk to Azeeda 2"] =
            {appendText=" about her claim that the pendant belongs to her. Decide who you should give the pendant to.", stepTextKey="A woman claims the pendant belongs to her. I should try to determine who the piece of jewelry actually belongs to before I turn it over to either of them."},
        [5] = 
            {appendStepText="At the makeshift camp for shipwreck survivors northwest of the Icy Point Wayshrine, ", stepTextKey="Azeeda claims that the pendant belongs to her and that Youss is lying so that he can sell the pendant and make some gold. I decided that Azeeda is telling the truth and will turn the pendant over to her."},
        ["Give the Pendant to Azeeda"] =
            {appendText="."},
        [6] = 
            {appendStepText="At the makeshift camp for shipwreck survivors northwest of the Icy Point Wayshrine, ", stepTextKey="Youss claims that the pendant belongs to him and that Azeeda is lying just to punish him for rejecting her advances. I decided that Youss is telling the truth and will turn the pendant over to him."},
        ["Give the Pendant to Youss"] =
            {appendText="."},
    },
[GetQuestName(5474)] = { --"One Ugly Mug"			-- Aashiana
		[1] = 
			{appendStepText="When I met with Zabani in the jail beneath Scarp Keep in Orsinium, she mentioned that ", stepTextKey="In the brief time Zabani traveled with Agolas, she noticed he was obsessive about keeping a journal. She believes the journal will help prove her innocence."},
		["Find Agolas's Journal"] =
			{appendText=". Before I leave the jail, perhaps I should speak with Warden Oorg, sitting near Zabani's cell. Agolas's journal is sitting on a table between two tents at his campsite near Aqueduct Rock, west of Trader's Road Wayshrine."},
		[2] = 
			{appendStepText="Near the aquaduct west of Orsinium, ", stepTextKey="I should search for the stolen goods. The journal said they were located just north of Aqueduct Rock, at the intersection of \"aqueduct legs, narrow tree, gray serpent.\""},
		["Find the Stolen Goods"] =
			{appendText=" buried at the location described in the journal I have."},
		[3] = 
			{appendStepText="", stepTextKey="I should decide what to do with this hideous mug. I could speak with Zabani about what I dug up. However, Agolas's journal mentioned a buyer. If I wanted, I could sell the mug to Astilme."},
		["Talk to Zabani 1"] =
			{appendText=", in the jail beneath Scarp Keep in Orsinium.", stepTextKey="I should decide what to do with this hideous mug. I could speak with Zabani about what I dug up. However, Agolas's journal mentioned a buyer. If I wanted, I could sell the mug to Astilme."},
		["Sell Mug to Astilme"] =
			{appendText=", currently enjoying a glass of wine at The Greedy Gut in Orsinium."},
		[4] = 
			{appendStepText="In the jail beneath Scarp Keep in Orsinium, ", stepTextKey="Zabani wants me to turn over the hideous mug. I should speak with Warden Oorg to determine her fate. However, Agolas's journal mentioned a buyer. If I wanted, I could sell the mug to Astilme."},
		["Talk to Warden Oorg or Sell Mug to Astilme"] =
			{appendText=". Warden Oorg is sitting nearby at his desk in the jail below Scarp Keep. Astilme is not far away, enjoying a glass of wine in the Greedy Gut Tavern in Orsinium."},
		[5] = 
			{appendStepText="In The Greedy Gut tavern in Orsinium, ", stepTextKey="Astilme agreed to purchase the hideous mug. I should speak with her about my cut."},
		["Sell the Mug to Astilme 1"] =
			{appendText=".", stepTextKey="Astilme agreed to purchase the hideous mug. I should speak with her about my cut."},
		[6] = 
			{appendStepText="At his desk in the jail below Scarp Keep in Orsinium, ", stepTextKey="I returned the mug to Warden Oorg. I should speak with him about a reward."},
		["Talk to Warden Oorg 1"] =
			{appendText=" to receive your reward.", stepTextKey="I returned the mug to Warden Oorg. I should speak with him about a reward."},
		[7] = 
			{appendStepText="At his desk in the jail below Scarp Keep in Orsinium, ", stepTextKey="I returned the mug to Warden Oorg. I should speak with him about releasing Zabani."},
		["Talk to Warden Oorg 2"] =
			{appendText=" to release Zabani and receive your reward.", stepTextKey="I returned the mug to Warden Oorg. I should speak with him about releasing Zabani."},
		[8] = 
			{appendStepText="In The Greedy Gut tavern in Orsinium, ", stepTextKey="Astilme agreed to purchase the hideous mug. I should speak with her about my cut."},
		["Sell the Mug to Astilme 2"] =
			{appendText=".", stepTextKey="Astilme agreed to purchase the hideous mug. I should speak with her about my cut."},
		[9] = 
			{appendStepText="At his desk in the jail below Scarp Keep in Orsinium, ", stepTextKey="I returned the mug to Warden Oorg. I should speak with him about releasing Zabani."},
		["Talk to Warden Oorg 3"] =
			{appendText=" to release Zabani and receive your reward.", stepTextKey="I returned the mug to Warden Oorg. I should speak with him about releasing Zabani."},
		[10] = 
			{appendStepText="In Orsinium, ", stepTextKey="Zabani agreed to give me a cut of her loot from the sale of the hideous mug. I should meet her in the Greedy Gut to settle up."},
		["Talk to Zabani 2"] =
			{appendText=" to receive my cut of the profits.", stepTextKey="Zabani agreed to give me a cut of her loot from the sale of the hideous mug. I should meet her in the Greedy Gut to settle up."},
	},
[GetQuestName(5449)] = { --"Riekr Revenge"			-- Aashiana
    [1] = {appendStepText="", stepTextKey="Orgotha asked me to find Murukh and the hunters who went after the Riekrs and their captives. She thinks they may have headed toward the cave in the cliffside."},
    ["Find Murukh"] = {appendText=", sitting injured near the corner of a rock wall below the Forlorn Watchtower, northeast of Orgotha's camp."},
    [2] = {appendStepText="Near the corner of a rock wall below the Forlorn Watchtower, northeast of Orgotha's camp, ", stepTextKey="Murukh asked me to find the hunters, Avreg and Zhasim. They followed the Riekrs toward the cave in the cliffside."},
    ["Find Avreg"] = {appendText=", just inside Bonerock Cavern south of Orgotha's camp. The entrance is hidden halfway up the cliff between two large rocks and through broken wooden beams."},
    [3] = {appendStepText="Just inside the entrance to Bonerock Cavern, ", stepTextKey="Avreg said that his brother Zhasim was still looking for the Orc captives deeper within the cave. I should try to find him before he gets into too much trouble."},
    ["Find Zhasim"] = {appendText=", hiding along the wall just past the wooden fence to the left."},
    [4] = {appendStepText="Inside Bleakrock Cavern in central Wrothgar, ", stepTextKey="Zhasim won't leave until he finds his cat, so I should continue to look for the other hunters."},
    ["Search the Riekr Lair"] = {appendText=". Continue along the central path, past ogre and Reikr camps and a small lake, to a large open cavern with rock walls and pillars. Go through the wooden doors on the far side and continue up the stone stairs. One of the missing hunters can be found in a far corner of a cave to the east. He asks you to look for Zubesha in the chambers to the west."},
    [5] = {appendStepText="In the Riekr throne room in northwest Bonerock Cavern, ", stepTextKey="The totem is beside the Riekr chief's throne. I should grab the totem so I can give it to Orgotha."},
    ["Take the Riekr Totem"] = {appendText=" next to the throne, after killing the Chief."},
    [6] = {appendStepText="In the Riekr throne room in northwest Bonerock Cavern, ", stepTextKey="Now that I have the Riekr chief's totem, I should find Zubesha and set her free."},
    ["Rescue Zubesha"] = {appendText=", tied up on an altar behind the throne."},
    [7] = {appendStepText="Deep in Bonerock Cavern, ", stepTextKey="I found the missing hunters and collected the Riekr chief's totem. Now I should meet the Orc hunting party and give the totem to Orgotha."},
    ["Give the Totem to Orgotha"] = {appendText=". I can use the back exit through the wooden doors behind the Reikr throne room. Orgotha and the hunters are just past the ornate stone bridge to the south of Forlorn Watchtower, east of Bonerock Cavern."},
    [8] = {appendStepText="", stepTextKey="I found the missing hunters and collected the Riekr chief's totem. Now I should meet the Orc hunting party and give the totem to Orgotha."},
    ["Talk to Orgotha"] = {appendText=" to learn her plans and receive my reward. She is with her hunting party, south of Forlorn Watchtower."},
    },
[GetQuestName(5335)] = { --"Silver Linings"			-- Aashiana
        [1] = 
            {appendStepText="Lying injured outside the Argent Mine west of Orsinium, near a massive waterfall falling from upper to lower Wrothgar, ", stepTextKey="Dirdre asked me to recover the sacred banner of the Order of the Silver Dawn from the depths of the Argent Mine. She had to leave it behind when she fled the attack by the Magnar Pack werewolves."},
        ["Recover the Silver Dawn Banner"] =
            {appendText=". The blue banner hides in the shadows near a stone forge in the northeastern cavern of this mine of winding tunnels and sparkling silver. Perhaps I can find a note or book that recounts what has happened."},
        [2] = 
            {appendStepText="West of Orsinium, deep within the Argent Mine near an old stone forge, ", stepTextKey="I recovered the sacred banner of the Order of the Silver Dawn. I should return it to Dirdre."},
        ["Talk to Dirdre"] =
            {appendText=" just outside the Argent Mine. Dirdre is standing by a large tree at the bottom of the wooden ramps, hoping that you are still alive and successful in your mission."},
    },
[GetQuestName(5444)] = { --"Sorrow's Kiss"			-- Aashiana
		[1] = 
			{appendStepText="At their camp at the base of Sorrow Mountain, far to the icy north, ", stepTextKey="Stibbons said I should talk to Lady Laurent. He thinks she needs help completing this particular expedition. She should be coming down the trail any moment now. I should head up there and meet her."},
		["Talk to Lady Laurent 1"] =
			{appendText=", on the trail heading up to Sorrow Mountain behind Stibbons. She stands on a wooden platform overlooking the frozen wastes.", stepTextKey="Stibbons said I should talk to Lady Laurent. He thinks she needs help completing this particular expedition. She should be coming down the trail any moment now. I should head up there and meet her."},
		[2] = 
			{appendStepText="On the trail heading up to Sorrow Mountain behind Stibbons' camp, I found Lady Laurent on a wooden platform waiting for assistance. ", stepTextKey="Lady Laurent asked me to head up the mountain and present myself to Kharsthun, her liaison from the House of Orsimer Glories."},
		["Talk to Kharsthun 1"] =
			{appendText=", farther up the winding path and up several stone staircases to the entrance of the Path to Sorrow. Continue up the stone stairs inside to Kharsthun's camp, near imposing metal statues and stone carvings on the walls.", stepTextKey="Lady Laurent asked me to head up the mountain and present myself to Kharsthun, her liaison from the House of Orsimer Glories."},
		[3] = 
			{appendStepText="After traveling up the path to Sorrow Mountain in the far north, and through the wooden double doors to Karsthun's camp, ", stepTextKey="Kharsthun explained that some members of their expedition may have survived. He wants me to head farther up the mountain and look for any survivors while I also try to find the shrine of Torug."},
		["Search for Expedition Survivors"] =
			{appendText=" through the door with an icy mist flowing in underneath. \n\nClimb up the icy path, watching out for avalanches. Red banners mark areas with dangerous icefalls. Other creatures better adapted to the snow and ice may be lurking along the way. At the third banner, Kuhlon is sitting behind a large rock to the right. Perhaps she was injured by the icefall...\n\nFarther up the path, past an ogre guarding a rope bridge, an icy cave awaits. Explore the first passage to the left, which seems a likely place for the expedition to rest and evade the ogres."},
		[4] = 
			{appendStepText="In the far north, the path up Sorrow Mountain to Torug's Shrine is proving to be dangerous. In an icy cave above a series of avalanches and a rope bridge, ", stepTextKey="I discovered the missing members of Lady Laurent's expedition. It appears that none of them survived. One member appears to have made a rubbing of some sort. I should talk to Kharsthun and see if he knows what it means."},
		["Talk to Kharsthun 2"] =
			{appendText=" about the rubbing and what to do next to find Torug's Shrine. Lady Laurent and Stibbons have joined us.", stepTextKey="I discovered the missing members of Lady Laurent's expedition. It appears that none of them survived. One member appears to have made a rubbing of some sort. I should talk to Kharsthun and see if he knows what it means."},
		[5] = 
			{appendStepText="In the far north, along the path up Sorrow Mountain in an icy cave beyond a rope bridge, ", stepTextKey="Kharsthun wants me to search for the remaining stanzas in Torug's epitaph while I also look for his shrine. He thinks the complete epitaph might lead us to the location of the Armlet of Torug."},
		["Find the Remaining Stanzas"] =
			{appendText=". \n\nContinue north through the cave and the ogre camp and out into the frigid ice and snow. Stone stairs lead up the icy path to a cold stone door with a tablet in front of it. Inside Torug's Shrine, up the first flight of stairs, another tablet rests on a stone table in front of Torug's statue.\n\nContinue through the ancient halls behind Torug's statue. Up a steep flight of stairs is a stone tablet on a dais, in front of an altar and another statue."},
		[6] = 
			{appendStepText="In Torug's Shrine near the top of Sorrow Mountain in the icy north, I have found several tablets with inscriptions. ", stepTextKey="Now that Kharsthun translated the ancient Orcish inscriptions I found, I should talk to Lady Laurent and see what she thinks."},
		["Talk to Lady Laurent 2"] =
			{appendText=" about what she would like me to do next.", stepTextKey="Now that Kharsthun translated the ancient Orcish inscriptions I found, I should talk to Lady Laurent and see what she thinks."},
		[7] = 
			{appendStepText="In Torug's Shrine near the top of Sorrow Mountain in the icy north, ", stepTextKey="Lady Laurent wants me to ascend to Sorrow's peak and retrieve the enchanted bracer known as the Armlet of Torug."},
		["Retrieve the Armlet of Torug"] =
			{appendText=", which Lady Laurent hopes is at the summit of Sorrow Mountain, further up the path through the wooden doors with icy mist flowing underneath them. The path to the summit is frigid and there is constant danger of avalanches. Near the top, I may find a frozen Orc wearing the armband..."},
		[8] = 
			{appendStepText="At the summit of Sorrow Mountain, far to the icy north, ", stepTextKey="I recovered the Armlet of Torug, but I'm starting to feel a little light-headed. I should return to the relative safety of the shrine as quickly as I can."},
		["Return to Torug's Shrine"] =
			{appendText=". After wresting the armband from the frozen Orc, I tried to turn back, but the cold overcame me. Somehow, I am still alive and reunited with the other members of the expedition."},
		[9] = 
			{appendStepText="High upon Sorrow Mountain in the icy north, I appear to have been rescued from the cold. ", stepTextKey="While Lady Laurent and Kharsthun argue, I should talk to Stibbons and see what this is all about."},
		["Talk to Stibbons"] =
			{appendText="."},
		[10] = 
			{appendStepText="Far to the icy north, ", stepTextKey="I recovered the Armlet of Torug from Sorrow's summit. In my absence, Lady Laurent and Kharsthun's disagreement seems to have grown. Now I need to decide who to give this ancient treasure to. I should talk to both of them before I make my decision."},
		["Grant Relic to Kharsthun"] =
			{appendText=". His proposal honors Torug's strength and leadership and exemplifies Orcish tradition."},
		["Grant Relic to Lady Laurent"] =
			{appendText=". Her plan to display it at the House of Orsimer Glories will provide the community greater opportunity to learn about Orcish history and accomplishments, alongside other important relics."},
		[11] = 
			{appendStepText="Far to the icy north, near the summit of Sorrow Mountain, ", stepTextKey="I decided to let Kharsthun keep the Armlet at Torug's shrine. I should let Lady Laurent know about my decision."},
		["Talk to Lady Laurent 3"] =
			{appendText=". She was disappointed, but found a way to make the best of it.", stepTextKey="I decided to let Kharsthun keep the Armlet at Torug's shrine. I should let Lady Laurent know about my decision."},
		[12] = 
			{appendStepText="Far to the icy north, near the summit of Sorrow Mountain, ", stepTextKey="It appears that the Armlet of Torug turned Stibbons into a block of ice. I should talk to Lady Laurent about this."},
		["Talk to Lady Laurent 4"] =
			{appendText=" about how to get Stibbons out of his predicament.", stepTextKey="It appears that the Armlet of Torug turned Stibbons into a block of ice. I should talk to Lady Laurent about this."},
		[13] = 
			{appendStepText="Far to the icy north, near the summit of Sorrow Mountain, ", stepTextKey="I decided to let Lady Laurent take the relic to the museum. I should talk to her and find out what we need to do next."},
		["Talk to Lady Laurent 5"] =
			{appendText=". She wants to see what the armlet does...", stepTextKey="I decided to let Lady Laurent take the relic to the museum. I should talk to her and find out what we need to do next."},
		[14] = 
			{appendStepText="Far to the icy north, near the summit of Sorrow Mountain, ", stepTextKey="It appears that the Armlet of Torug turned Stibbons into a block of ice. I should talk to Lady Laurent about this."},
		["Talk to Lady Laurent 6"] =
			{appendText=" about how to get Stibbons out of his latest predicament.", stepTextKey="It appears that the Armlet of Torug turned Stibbons into a block of ice. I should talk to Lady Laurent about this."},
	},
		[GetQuestName(5471)] = { -- "Thicker Than Water"			-- Aashiana
			[1] = 
				{appendStepText="At her pavilion near the Morkuldin Forge, ", stepTextKey="Orzorga asked me to bring her echatere moss, some ogre intestines, and an ogre heart."},
			["Gather Ogre Intestines"] =
				{appendText=" from a particular ogre who only eats healthy foods. He has a shelter near a large stone outcrop east of the Morkuldin Forge, with various fruits and vegetables strewn about. If I wish to spare this seemingly intelligent ogre, lesser ogres would also serve, but the dish may not be as tasty."},
			["Gather Ogre Heart"] =
				{appendText=" along with the intestines after the battle."},
			["Gather Echatere Moss"] =
				{appendText=", growing in small shrubs near the ogre's shelter."},
			[2] = 
				{appendStepText="", stepTextKey="I have the ingredients Orzorga requested. I should bring them to her."},
			["Bring the Ingredients to Orzorga"] =
				{appendText=", at her pavilion near the Morkuldin Forge."},
			[3] = 
				{appendStepText="", stepTextKey="I tasted the \"ventricle pie.\" I should let Orzorga know what I thought of it."},
			["Talk to Orzorga 1"] =
				{appendText=" about her surprisingly enjoyable pie.", stepTextKey="I tasted the \"ventricle pie.\" I should let Orzorga know what I thought of it."},
			[4] = 
				{appendStepText="", stepTextKey="I tasted the \"ventricle pie.\" I should let Orzorga know what I thought of it."},
			["Talk to Orzorga 2"] =
				{appendText=" about the unusual reaction I had to the pie. She has an idea about how to adjust the recipe based on my experience.", stepTextKey="I tasted the \"ventricle pie.\" I should let Orzorga know what I thought of it."},
			[5] = 
				{appendStepText="", stepTextKey="I brought Orzorga what she wanted. I should speak with her."},
			["Talk to Orzorga 3"] =
				{appendText=". I declined to try the pie, but she still plans to include it in the feast.", stepTextKey="I brought Orzorga what she wanted. I should speak with her."},
		},
[GetQuestName(5485)] = { --"Those Truly Favored"			-- Aashiana
		[1] = 
			{appendStepText="In Malacath's Shrine, hidden deep in Bludruth's house near the steps leading up to Scarp Keep in Orsinium, ", stepTextKey="Dagarha believes the Vengeful Eye is in the recently uncovered catacombs of Honor's Rest. I should head there and search for the relic."},
		["Search for the Vengeful Eye 1"] =
			{appendText=" in Honor's Rest, far southwest of Orsinium, where a waterfall flows through stone walls. The rocky cave entrance is above the stream to the west, marked by a stone pillar. Inside the cave, pass through large wooden doors to the catacombs.", stepTextKey="Dagarha believes the Vengeful Eye is in the recently uncovered catacombs of Honor's Rest. I should head there and search for the relic."},
		[2] = 
			{appendStepText="Far southwest of Orsinium, where a waterfall flows through stone walls, the entrance to Honor's Rest catacombs is above the stream to the west, marked by stone pillars. Inside the cave, pass through large wooden doors to the catacombs. ", stepTextKey="When I entered the catacombs near Honor's Rest, one of the Winterborn approached me. He wants to speak, and apparently doesn't want his fellow tribesman to hear. I should see what he has to say."},
		["Talk to Kyrtos 1"] =
			{appendText=", who wants me to find and remove the Vengeful Eye to avoid war between the Reachmen and the Orcs.", stepTextKey="When I entered the catacombs near Honor's Rest, one of the Winterborn approached me. He wants to speak, and apparently doesn't want his fellow tribesman to hear. I should see what he has to say."},
		[3] = 
			{appendStepText="Far southwest of Orsinium, where a waterfall flows through stone walls, the entrance to the Honor's Rest catacombs is above the stream to the west, marked by stone pillars. Pass through large wooden doors to the catacombs, where ", stepTextKey="Kyrtos wants me to recover the Vengeful Eye so this tribe will no longer be a pawn to the whims of Malacath. He suggested I search the Honor's Rest catacombs, near the grave goods."},
		["Search for the Vengeful Eye 2"] =
			{appendText=" in the catacombs through the archway. Follow the stream through rocky passages until it opens into a large cave with stonework and pillars. Across the cave is a skeleton lying on an altar, with a small weathered box on the ground in front of it.", stepTextKey="Kyrtos wants me to recover the Vengeful Eye so this tribe will no longer be a pawn to the whims of Malacath. He suggested I search the Honor's Rest catacombs, near the grave goods."},
		[4] = 
			{appendStepText="Far southwest of Orsinium, in Honor's Rest catacombs, a rushing stream led to a large cave, where ", stepTextKey="I found the Vengeful Eye near some grave goods. I should retrieve it before the Winterborn can."},
		["Retrieve the Vengeful Eye"] =
			{appendText=" from the small weathered box in front of the altar."},
		[5] = 
			{appendStepText="Far southwest of Orsinium, I entered Honor's Rest catacombs and found the Vengeful Eye. ", stepTextKey="Now that I have the Vengeful Eye, I should return to Kyrtos and see what can be done with it."},
		["Talk to Kyrtos 2"] =
			{appendText=", who waits for me at the entrance to the catacombs, back along the stream and through the archway to the right.", stepTextKey="Now that I have the Vengeful Eye, I should return to Kyrtos and see what can be done with it."},
		[6] = 
			{appendStepText="In Honor's Rest Catacombs, Kyrtos said ", stepTextKey="I must decide what to do with the Vengeful Eye. I could return it to the Malacath faithful in Orsinium, rededicate it at the statue of Malacath, or destroy it for good in the forges behind the statue."},
		["Take the Vengeful Eye to Orsinium"] =
			{appendText=", where Dagarha waits for me in the small Malacath shrine within Blurath's house near the stairs to Scarp Keep. She would prefer to win it in battle, but will accept it from you as a gift."},
		["Take the Vengeful Eye to Malacath's Shrine"] =
			{appendText=" and present it to Malacath's statue as an offering."},
		["Destroy the Vengeful Eye"] =
			{appendText=" at Malacath's Shrine, by throwing it into the glowing bed of coals in the great forge behind the statue of Malacath. \n\nMalacath's Shrine is northeast of Orsinium. Follow the icy cliffs north from the city, past a waterfall, and up a mountain path to reach the shrine."},
		[7] = 
			{appendStepText="In Malacath's Shrine within Bludruth's house, near the base of the stairs leading to Scarp Keep in Orsinium, I made my decision. ", stepTextKey="The relic belongs with the Malacath faithful. I should speak with Dagarha about my reward."},
		["Talk to Dagarha"] =
			{appendText="."},
		[8] = 
			{appendStepText="At Malacath's Shrine, high in the mountains northeast of Orsinium, ", stepTextKey="The relic must be rededicated. I should pray in the shadow of Malacath's statue."},
		["Pray at the Shrine of Malacath"] =
			{appendText=" and receive Malacath's gift."},
		[9] = 
			{appendStepText="At the great forge behind Malacath's Statue, in the mountains northeast of Orsinium, ", stepTextKey="I destroyed the relic. Kyrtos seems incredibly relieved. I should speak with him."},
		["Talk to Kyrtos 3"] =
			{appendText=", who must have followed me to see what I would do.", stepTextKey="I destroyed the relic. Kyrtos seems incredibly relieved. I should speak with him."},
	},

[GetQuestName(5443)] = { --"Thukhozod the Eternal"			-- Aashiana
        [1] = 
            {appendStepText="Outside Thukhozod's Sanctum, an imposing semicircular Ayleid ruin just southeast of the Great Bay Wayshrine, ", stepTextKey="I agreed to help Meram and Bardun complete their contract. I should check inside the ruins for the missing Orc, Khoruzoth."},
        ["Search for Khoruzoth"] =
            {appendText=" inside the ruins. Follow the corridor to the right, down the stairs and through the next room, dispatching any undead you come across. Continue further downward and straight ahead, then up the stairs and to the left. Across a wooden walkway, Khoruzoth can be found up the stairs in the back of the stone platform. A book on the altar and another note on a nearby stone table may explain why he came. A family relic that may be of interest to the House of Orsimer Glories can be found in a far corner of the room below."},
        [2] = 
            {appendStepText="At an altar behind a stone platform at the southwestern end of Thukhozod's Sanctum, near the Great Bay Wayshrine, ", stepTextKey="I found Khoruzoth but unfortunately he was dead. I took an amulet he was wearing that bore his name so it can be returned to his mother. I should take it to Meram and let her know what I found."},
        ["Talk to Meram Farr 1"] =
            {appendText=", down the stairs outside the ruins, standing by a tree.", stepTextKey="I found Khoruzoth but unfortunately he was dead. I took an amulet he was wearing that bore his name so it can be returned to his mother. I should take it to Meram and let her know what I found."},
        [3] = 
            {appendStepText="In front of Thukhozod's Sanctum, southeast of the Great Bay Wayshrine, ", stepTextKey="Meram offered to buy the amulet from me in the hope that she can sell it for a profit to someone interested in the legend of Thukhozod. But Khoruzoth's mother would likely want it to remember her son by. I need to decide what to do with the amulet."},
        ["Sell the Amulet to Meram Farr"] =
            {appendText="."},
        ["Find Khoruzoth's Mother"] =
            {appendText=" in Exile's Barrow, an Orc settlement southeast of the Morkul Plain Wayshrine. She is standing in front of a tent to the right of the stables."},
        [4] = 
            {appendStepText="", stepTextKey="I decided to sell the amulet to Meram. I should talk to her and complete the deal."},
        ["Talk to Meram Farr 2"] =
            {appendText=".", stepTextKey="I decided to sell the amulet to Meram. I should talk to her and complete the deal."},
        [5] = 
            {appendStepText="In Exile's Barrow, southeast of the Morkul Plain Wayshrine, ", stepTextKey="I decided to track down Khoruzoth's mother, Yazoga, to give her his amulet and tell her what happened to her son."},
        ["Talk to Yazoga"] =
            {appendText=" about her son's fate."},
    },
[GetQuestName(5466)] = { --"Tinker Trouble"			-- Aashiana
		[1] = 
			{appendStepText="Northwest of the Siege Road Wayshrine and up the hill from Grudge-Rock Falls, I found Kireth Vanos inside a large camp with a unique echatere skull above its entrance. ", stepTextKey="I should talk to Kireth and find out more about the construct that Raynor tinkered with."},
		["Talk to Kireth Vanos 1"] =
			{appendText="."},
		[2] = 
			{appendStepText="Northwest of the Siege Road Wayshrine and up the hill from Grudge-Rock Falls, I found Kireth Vanos inside a large camp with an echatere skull above its entrance. ", stepTextKey="The nearby wreckage appears to be the result of Raynor's latest experiment—a reactivated Dwarven sphere. If I use the lightning prod that Kireth gave me, I might be able to track the sphere by its energy discharges."},
		["Use Lightning Prod Near Wreckage"] =
			{appendText=" of a wooden cart just outside the camp entrance. "},
		[3] = 
			{appendStepText="Just outside the entrance to a large camp up the hill from Grudge-Rock Falls, ", stepTextKey="The lightning prod revealed after-images of the sphere and showed me which direction it headed in. I should follow the trail and see if it leads me to Raynor."},
		["Follow the Dwarven Sphere"] =
			{appendText=" through the camp to a stream east of the camp. Although its energy signature disappeared, it must have continued east, up the hill past the large fallen tree, and just east of some ancient aqueduct pillars. Raynor is standing next to a tree by a rocky hillside."},
		[4] = 
			{appendStepText="I found Raynor east of Grudge-Rock Falls and south of the Great Bay Wayshrine. ", stepTextKey="The sphere's energy trail led me to Raynor Vanos. I should talk to him and find out what happened after Kireth was knocked unconscious."},
		["Talk to Raynor Vanos 1"] =
			{appendText=" to find out what he thinks is wrong with the sphere and what we should do next.", stepTextKey="The sphere's energy trail led me to Raynor Vanos. I should talk to him and find out what happened after Kireth was knocked unconscious."},
		[5] = 
			{appendStepText="", stepTextKey="I should use the lightning prod again so that I can continue to track the runaway Dwarven sphere."},
		["Use the Lightning Prod"] =
			{appendText=".", stepTextKey="I should use the lightning prod again so that I can continue to track the runaway Dwarven sphere."},
		[6] = 
			{appendStepText="On the path leading north to the Great Bay Wayshrine, south of Thukhozod's Sanctum, ", stepTextKey="The lightning prod revealed after-images of the runaway Dwarven sphere. I should follow the images and try to find the overcharged construct."},
		["Follow the Overcharged Dwarven Sphere 1"] =
			{appendText="north along the winding path until you reach a large lake. Cross the lake to a large bent tree on the far shoreline. Just up the hill in a small Orc settlement, something is rampaging around...", stepTextKey="The lightning prod revealed after-images of the runaway Dwarven sphere. I should follow the images and try to find the overcharged construct."},
		[7] = 
			{appendStepText="East of the Great Bay Wayshrine at an Orc camp, ", stepTextKey="I finally caught up to the runaway Dwarven sphere. Raynor said I should use the lightning prod to siphon off some of the sphere's excess energy."},
		["Use the Lightning Prod on the Overcharged Dwarven Sphere"] =
			{appendText=" to get it to settle down and stop attacking the camp."},
		[8] = 
			{appendStepText="At the Orc camp east of the Great Bay Wayshrine, I used the lightning prod. ", stepTextKey="Just as I drove off the runaway sphere, Kireth and Raynor arrived. I think Kireth wants to talk to me. I should speak with her."},
		["Talk to Kireth Vanos 2"] =
			{appendText=". She asked me to continue following the sphere so we can put an end to the chaos. An injured Orc in the camp and another by the lake may be able to tell me more about what happened here. Raynor seems more optimistic about \"curing\" the sphere than Kireth and wants me to keep trying.", stepTextKey="Just as I drove off the runaway sphere, Kireth and Raynor arrived. I think Kireth wants to talk to me. I should speak with her."},
		[9] = 
			{appendStepText="At the Orc camp east of the Great Bay Wayshrine, ", stepTextKey="Kireth and Raynor want me to use the lightning prod again so that I can follow the runaway sphere. They'll catch up with me after they help the Orcs that the sphere attacked."},
		["Follow the Overcharged Dwarven Sphere 2"] =
			{appendText=" heading north from the Orc camp along the road. After crossing a stone bridge, farther along the road there is another damaged wooden cart. A young woman is crying, not far from the destroyed cart. Perhaps the sphere is around here somewhere.", stepTextKey="Kireth and Raynor want me to use the lightning prod again so that I can follow the runaway sphere. They'll catch up with me after they help the Orcs that the sphere attacked."},
		[10] = 
			{appendStepText="Near the broken-down cart on the road east of Poacher's Encampment, I used Raynor's tool again. ", stepTextKey="The lightning prod revealed another after-image. If I follow it, I should be able to find the runaway Dwarven sphere."},
		["Follow the Overcharged Dwarven Sphere 3"] =
			{appendText=" northeast along the road. Keep following it as it turns onto a path heading up the hillside marked by dolmens and torches, leading to Exile's Barrow. Continue up the hill behind the barrow and use the lightning rod again. Follow the ruined pillars of the aqueduct east until coming to a path leading toward a ruined stone building.", stepTextKey="The lightning prod revealed another after-image. If I follow it, I should be able to find the runaway Dwarven sphere."},
		[11] = 
			{appendStepText="North of Trader's Road Wayshrine, in a Winterborn camp near stone ruins, ", stepTextKey="I finally caught up with the runaway Dwarven sphere at a camp of Reachmen raiders. I need to deal with the raiders and use the lightning prod on the sphere."},
		["Retrieve the Runaway Sphere"] =
			{appendText="."},
		[12] = 
			{appendStepText="North of Trader's Road Wayshrine in a Winterborn camp, I found the Dwarven sphere being attacked. ", stepTextKey="After defeating the Reachmen, the Dwarven sphere took off again. I should follow it."},
		["Follow the Overcharged Dwarven Sphere 4"] =
			{appendText=" back toward the aqueduct just northeast of the wayshrine.", stepTextKey="After defeating the Reachmen, the Dwarven sphere took off again. I should follow it."},
		[13] = 
			{appendStepText="Near the aqueduct north of the Trader's Road Wayshrine, I finally located the Dwarven sphere. ", stepTextKey="Now that the Dwarven sphere has stopped rolling around, I should talk to Kireth and Raynor. Kireth wants to destroy it, but Raynor wants to repair it. I should see what they both have to say before we decide what to do with the construct."},
		["Talk to Raynor Vanos 2"] =
			{appendText=".", stepTextKey="Now that the Dwarven sphere has stopped rolling around, I should talk to Kireth and Raynor. Kireth wants to destroy it, but Raynor wants to repair it. I should see what they both have to say before we decide what to do with the construct."},
		["Talk to Kireth Vanos 3"] =
			{appendText=".", stepTextKey="Now that the Dwarven sphere has stopped rolling around, I should talk to Kireth and Raynor. Kireth wants to destroy it, but Raynor wants to repair it. I should see what they both have to say before we decide what to do with the construct."},
		[14] = 
			{appendStepText="Near the aqueduct north of the Trader's Road Wayshrine, ", stepTextKey="I agreed with Raynor and let him fix the Dwarven sphere. It looks like he fixed it all right, but then it rolled off into the wilderness and Raynor went after it. I should talk to Kireth and see what she wants to do now."},
		["Talk to Kireth Vanos 4"] =
			{appendText=".", stepTextKey="I agreed with Raynor and let him fix the Dwarven sphere. It looks like he fixed it all right, but then it rolled off into the wilderness and Raynor went after it. I should talk to Kireth and see what she wants to do now."},
		[15] = 
			{appendStepText="Near the aqueduct north of the Trader's Road Wayshrine, ", stepTextKey="I agreed with Raynor and let him fix the Dwarven sphere. It looks like he fixed it all right, but then it rolled off into the wilderness and Raynor went after it. I should talk to Kireth and see what she wants to do now."},
		["Talk to Kireth Vanos 5"] =
			{appendText=".", stepTextKey="I agreed with Raynor and let him fix the Dwarven sphere. It looks like he fixed it all right, but then it rolled off into the wilderness and Raynor went after it. I should talk to Kireth and see what she wants to do now."},
		[16] = 
			{appendStepText="Near the aqueduct north of the Trader's Road Wayshrine, ", stepTextKey="I agreed with Kireth that the Dwarven sphere needed to be destroyed. I should talk to her to make sure the task was accomplished."},
		["Talk to Kireth Vanos 6"] =
			{appendText=".", stepTextKey="I agreed with Kireth that the Dwarven sphere needed to be destroyed. I should talk to her to make sure the task was accomplished."},
	},
[GetQuestName(5445)] = { --"A Treasure in Need of a Home"			-- Aashiana
        [1] = 
            {appendStepText="In Exile's Barrow, a draugr barrow at the top of a hill southeast of the Morkul Plains Wayshrine, I found some interesting Nord relics. One was in a chest at the end of a passageway northeast of the central antechamber, and some other items were in a small urn in a passageway southwest of the central antechamber. ", stepTextKey="I should look for a researcher who's interested in ancient Nord curiosities and see if they want the relics I found."},
        ["Find a Researcher Interested in Nord Antiquities"] =
            {appendText=", just outside the entrance to the barrow."},
        [2] = 
            {appendStepText="Just outside the entrance to Exile's Barrow south of the Morkul Plain Wayshrine, ", stepTextKey="Berrice said I should look her up at the museum in Orsinium. If the relics I provided her with turn out to have any historical value, she promised me a reward."},
        ["Meet Berrice in Orsinium"] =
            {appendText=", just across the stone bridge north of the Orsinium Wayshrine. She is inside the House of Orsimer Glories, reading a book near a desk on the upper floor."},
        [3] = 
            {appendStepText="Inside the House of Orsimer Glories in the center of Orsinium, ", stepTextKey="I should talk to Berrice and find out what she plans to do with the Nord relics I gave to her."},
        ["Talk to Berrice Notte"] =
            {appendText=" about the relics I found in Exile's Barrow."},
    },
[GetQuestName(5316)] = { --"An Unexpected Fall"			-- Aashiana
        [1] = 
            {appendStepText="Across a small stone bridge west of the Two Rivers Wayshrine, straight ahead between two large rocks and an icy cave, Raynor Vanos told me his sister has fallen into the cave. ", stepTextKey="I should enter the cave and see if I can find Kireth Vanos somewhere in the ruins of Zthenganaz."},
        ["Find Kireth Vanos"] =
            {appendText=", who has left some notes along the way as she traveled further into the cave. Straight ahead, a large cave with stone pillars and dwarven artifacts would probably have interested her. Just to the north, a room split by a deep central chasm has some dwarven gears at the bottom. Perhaps she is exploring down there?"},
        [2] = 
            {appendStepText="Deep in the center of Zthenganaz, southwest of the Two Rivers Wayshrine, ", stepTextKey="Kireth asked me to collect the power core guarded by the Dwarven centurion known as the Ztheng Guardian. Apparently, Raynor can use the power core to create one of his arcane devices."},
        ["Acquire Dwarven Power Core"] =
            {appendText=", up the ramp from the central chasm where Kireth is examining a Dwarven artifact, through a corridor to the north, and into a large room at the northeast corner of the ruins. The power core is behind the Ztheng Guardian on a pedestal."},
        [3] = 
            {appendStepText="Deep in the northeast corner of Zthenganaz, southwest of the Two Rivers Wayshrine, ", stepTextKey="I acquired the power core that was protected by the Ztheng Guardian. I should meet Raynor at the ruin's main entrance, give him the core, and make sure Kireth made it out of the ruins safely."},
        ["Return to Raynor Vanos"] =
            {appendText=" through a large cave to the west, then continuing through a corridor to the south to an exit tunnel leading east out of the cave. Raynor is waiting there with Kireth."},
    },
[GetQuestName(5446)] = { --"Where Loyalty Lies"		-- Aashiana
		[1] = 
			{appendStepText="", stepTextKey="I met a survivor from the fleet of ships that smashed upon the ice on Wrothgar's northwestern shore. The survivor asked me to find Lord Ethian at the makeshift camp they set up near the ice."},
		["Talk to Lord Ethian 1"] =
			{appendText=", near the campfire northwest of the Icy Shore Wayshrine.", stepTextKey="I met a survivor from the fleet of ships that smashed upon the ice on Wrothgar's northwestern shore. The survivor asked me to find Lord Ethian at the makeshift camp they set up near the ice."},
		[2] = 
			{appendStepText="Northwest of the Icy Shore Wayshrine, ", stepTextKey="I should search the wrecked ships for the ambassador, Lady Sovelle, or any other survivors. I can also speak to survivors in the camp to see if they have any useful information about what happened out there."},
		["Search Wrecks for Survivors"] =
			{appendText=", northwest along the Icy Shore. The First Mate can be found inside the Materre's Fortune, a ship with imposing staircases and a dead orc at the door. He has some memory of what happened."},
		[3] = 
			{appendStepText="North of the Frozen Fleet camp near the Icy Shore, ", stepTextKey="I found First Mate Holbert in one of the wrecked ships. Now I need to look for the ambassador and her bodyguard."},
		["Find the Ambassador or Skordo"] =
			{appendText=". Skordo is trapped within the Pride of Northpoint, wrecked on a high snowy hill near the shoreline. He has some suspicions about what happened, and a nearby note on the table seems to confirm them."},
		[4] = 
			{appendStepText="Within the Pride of Northpoint, wrecked on a snowy hill near the Icy Shore, ", stepTextKey="I found Lady Sovelle's bodyguard, Skordo the Knife. Now I need to locate the ambassador."},
		["Search for Lady Sovelle"] =
			{appendText=". A conversation Skordo overheard and a note on a nearby cabinet suggest some foul play may be afoot. She may be in one of the nearby ships or a tower Skordo spotted to the southeast of the wreck of the Pride of Northpoint."},
		[5] = 
			{appendStepText="North of the Icy Shore wayshrine, ", stepTextKey="While searching for any sign of Lady Sovelle, Skordo and I ran into Holbert and Lord Ethian. I should talk to Ethian and find out if he has any news."},
		["Talk to Lord Ethian 2"] =
			{appendText=". He also thinks the Ambassador may have taken refuge in the signal tower, a tall stone structure to the west.", stepTextKey="While searching for any sign of Lady Sovelle, Skordo and I ran into Holbert and Lord Ethian. I should talk to Ethian and find out if he has any news."},
		[6] = 
			{appendStepText="North of the Icy Shore Wayshrine, ", stepTextKey="Lord Ethian ran off. He thinks his wife might be at the nearby signal tower. I should follow after him and make sure he doesn't get into any trouble."},
		["Follow Lord Ethian to the Signal Tower"] =
			{appendText=", a tall stone structure to the west. A mage stands guard, and a note just inside the door provides further proof of a conspiracy. Continue to the top of the tower to find Lord Ethian."},
		[7] = 
			{appendStepText="North of the Icy Shore Wayshrine, ", stepTextKey="I caught up to Lord Ethian on top of the signal tower. I should talk to him."},
		["Talk to Lord Ethian 3"] =
			{appendText=" about his part in all this.", stepTextKey="I caught up to Lord Ethian on top of the signal tower. I should talk to him."},
		[8] = 
			{appendStepText="On top of the signal tower to the north of the Icy Shore Wayshrine, ", stepTextKey="Lord Ethian admitted that his father wanted to sabotage the ambassador's mission. But he also claims that there was no plan for anyone to get hurt and that he doesn't know where Sovelle is. We should return to Skordo and Holbert."},
		["Return to Skordo and Holbert"] =
			{appendText=" outside the tower."},
		[9] = 
			{appendStepText="Outside the signal tower north of the Icy Shore Wayshrine, ", stepTextKey="Holbert the first mate explained that Skordo spotted an old smuggler's cave and went to investigate. He thinks that Captain Henrisa and the ambassador may be there. I should go and meet him."},
		["Find Skordo the Knife"] =
			{appendText="."},
		[10] = 
			{appendStepText="North of the Signal Tower beyond the Icy Point Wayshrine, ", stepTextKey="I met Skordo outside an old smuggler's cave. I should talk to him and see what he found out."},
		["Talk to Skordo the Knife"] =
			{appendText="."},
		[11] = 
			{appendStepText="Outside the cave north of the Signal Tower and the Icy Shore Wayshrine, ", stepTextKey="Lord Ethian was wounded trying to confront Captain Henrisa. I should follow the captain into the smuggler's cave and avenge Lord Ethian. If Lady Sovelle is inside, perhaps I can help her as well."},
		["Search the Smuggler's Cave"] =
			{appendText=" and confront Captain Henrisa."},
		[12] = 
			{appendStepText="Inside the smuggler's cave north of the Signal Tower and the Icy Shore Wayshrine, ", stepTextKey="I killed Henrisa and found Lady Sovelle. I should talk to her and set her free."},
		["Talk to Lady Sovelle"] =
			{appendText=" about what happened here."},
		[13] = 
			{appendStepText="Inside the smuggler's cave north of the Signal Tower and the Icy Shore Wayshrine, ", stepTextKey="I rescued Lady Sovelle and she left the smuggler's cave to check on her wounded husband. I should catch up with her and see if there's anything else I can do."},
		["Talk to Lady Sovelle Outside"] =
			{appendText=" the cave."},
	},
		[GetQuestName(5499)] = { -- "Wrecked"						-- SaipanDamashii
			[1] = 
				{appendStepText="", stepTextKey="Nammadin seems a little shaken after his cart crashed. He wants me to find his partners, who he fears went over the cliff with his cart. I'll search near the wreckage and see if I can find them."},
			["Find the Merchants"] =
				{appendText=". I should check further down the cliff, near the water. \n"},
			[2] = 
				{appendStepText="", stepTextKey="According to Travofia, harpies carried off the third merchant and took her high up into the rocks. To make matters worse, Jaeloreh was carrying the merchant's permit that gave the trio permission to buy and sell in Orsinium. I should try to find them."},
			["Find Jaeloreh"] =
				{appendText=". I need to find a way up those rocks across the river, above Nikolvara's Kennel. They might be keeping her in one of their harpy nests. \n"},
			[3] = 
				{appendStepText="", stepTextKey="I found the corpse of the third merchant. I need to search and see if I can find the Orsinium Permit of Trade."},
			["Gather Orsinium Permit of Trade"] =
				{appendText=". Travofia said that Jaeloreh was carrying the Permit when she was captured by the harpies. I should check her corpse, which is nestled among some harpy nests on a rock formation high above Nikolvara’s Kennel. \n"},
			[4] = 
				{appendStepText="", stepTextKey="I've recovered the merchants' Trade Writ but not their lost friend—she was killed by the harpies. I need to take the Orsinium Permit of Trade back to Nammadin on the road to Orsinium."},
			["Take Orsinium Permit of Trade to Nammadin"] =
				{appendText=", who is waiting with Travofia, hoping for you to return with some good news. He is just down the road from where you first met him, in front of a small bridge on the road to Orsinium. \n"},
		},


-- 		=========================================================================
--		  Wrothgar Dailies
-- 		=========================================================================
    [GetQuestName(5507)] = { --"Breakfast of the Bizarre"		-- JayAstrophel
        [1] = 
            {appendStepText="The cavern lies northeast of Orsinium, southeast of Shatul Wayshrine, and directly east of the King-Chief's Throne. The entrance is up a path past Ice Wraiths, leading into the cliffside itself. Once inside, ", stepTextKey="I must retrieve the unusual eggs and slay the hagraven, Kraala Birdsong."},
        ["Gather Unusual Eggs"] =
            {appendText=". Orange-hued with red markings, these eggs can be found throughout the cavern. It may also be worth fighting any enemies in the area to check if they are carrying eggs.\n"},
        ["Kill Kraala Birdsong"] =
            {appendText=". This hagraven hides on the east side of the cave, in a room where the ceiling opens up to reveal the sky above. Surrounded by bones and birds, Kraala performs her dark rituals.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I gathered the unusual eggs and killed the hagraven. I should return to Nednor and collect my reward."},
        ["Talk to Nednor"] =
            {appendText=" in Morkul Stronghold, northeast of the Morkul Plain wayshrine. Upon entering the Clan Longhouse, the Wood Elf can be found in the room to the right, just behind the wall.\n"},
    },
[GetQuestName(5505)] = { --"Fire in the Hold"		--TheoWriter
        [1] = 
            {appendStepText="Southeast of Siege Road Wayshrine in the far southwestern mountains, the ruined keep's walls overlooking a lake offer protection, but what the bandits value more is easy access to Friendship Gate. \n\nThe ruin is a great place to store their spoils and supplies and is easy to defend, like a dungeon one would find through a trapdoor in a tower. Once inside,  ", stepTextKey="I must burn the bandits' supplies and kill their leader, Sir Marq Tailas, to fulfill the contract."},
        ["Burn Bandit Supplies"] =
            {appendText=" \n\nIt's a pity their Wayward Supply Cache crates are so flammable.\n"},
        ["Kill Sir Marq Tailas"] =
            {appendText=" in the ruined keep's dungeon in the southwestern mountains of Wrothgar. He is likely to be as far from the entrance as possible."},
        [2] = 
            {appendStepText="", stepTextKey="I destroyed the bandits' supplies and dealt with their treacherous leader. I should meet Sergeant Oufa in Orsinium to receive my payment."},
        ["Talk to Sergeant Oufa"] =
            {appendText=", a female Redguard member of the Lion Guard. She is at her post at the ballistae overlooking the western road into the city, past the Shatul Clan Corral stables."},
    },
[GetQuestName(5515)] = { --"Free Spirits"	-- Aashiana
        [1] = 
            {appendStepText="In the Longhouse at Morkul Stronghold, Guruzug said ", stepTextKey="The Phial of Tranquility should allow me to free the spirits trapped in Thukhozod's Sanctum, provided I do enough damage to their undead husks first. I must also kill the necromancer responsible."},
        ["Defeat Undead and Use Phial of Tranquility to Free Them"] =
            {appendText=" \n\nPriest Thazeg is praying at an altar in his room at the northeast end of the Longhouse. He can tell me more about the Phial of Tranquility and how to use it. When I am ready, I should travel to Thukhozod's Sanctum, an imposing Ayleid ruin with a blue flame brazier near the Great Bay Wayshrine.\n"},
        ["Defeat Gorlar the Dark"] =
            {appendText=" at his altar in the southeast chamber of the Sanctum."},
        [2] = 
            {appendStepText="", stepTextKey="I freed many of the spirits trapped in Thukhozod's Sanctum and killed the necromancer, Gorlar the Dark. I should seek out the priest, Thazeg, to discuss my payment."},
        ["Talk to Thazeg"] =
            {appendText=", in his room in the longhouse at Morkul Stronghold."},
    },
  [GetQuestName(5514)] = { --"Getting a Bellyful"		--TheoWriter
        [1] = 
            {appendStepText="Arushna is near the entrance of the Clan Longhouse with her durzog. Merchants have long complained about the caves southeast of Trader's Road Wayshrine, infested by these creatures. By their accounts, each year they only get bigger and more organized - no doubt the result of special diet and extensive training. ", stepTextKey="I must collect some of this special durzog feed and slay the master durzog handler, Nikolvara the Durzog Trainer."},
        ["Collect Durzog Feed"] =
            {appendText=" \n\nWhile durzog are not picky eaters, meat storage conditions inside this kennel could be improved. \n"},
        ["Kill Nikolvara the Durzog Trainer"] =
            {appendText=" deep in her Kennel."},
        [2] = 
            {appendStepText="", stepTextKey="I collected the special durzog feed and killed Nikolvara the Durzog Trainer. I should meet with Arushna to discuss my payment."},
        ["Talk to Arushna"] =
            {appendText=" near the Clan Longhouse of Morkul Stronghold."},
    },
    [GetQuestName(5522)] = { --"Heresy of Ignorance"		--TheoWriter
        [1] = 
            {appendStepText="Travelers speak of robed men with pickaxes digging through the frozen tundra. Some were seen on the coast, northwest of the Morkul Plain Wayshrine. More groups were spotted inland, one southwest of the Trader's Road Wayshrine and one at the lake southeast of the Great Bay Wayshrine. ", stepTextKey="I need to seek out and disrupt the Worm Cult's bizarre obelisks in order to destroy Zandadunoz the Reborn."},
        ["Disrupt Strange Obelisks"] =
            {appendText=". \n"},
        ["Defeat Zandadunoz the Reborn"] =
            {appendText="'s summoned form at the Old Dolmen, south of the Great Bay Wayshrine. It seems that, as with all powerful daedra, his attention must be earned by first slaying his minions that guard the ritual site.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I disrupted the cultists' rituals and defeated Zandadunoz the Reborn. I should return to Orsinium and speak to Lilyameh."},
        ["Talk to Lilyameh"] =
            {appendText=" in Skalar's Hostel.\n"},
    },

  [GetQuestName(5521)] = { --"Nature's Bounty"		--TheoWriter
        [1] = 
            {appendStepText="Mad beasts attacking caravans is not new for Wrothgar, but new are stories of a red mist that provoked them. Some tell of a similar red mist, but coalesced into orbs, seemingly resisting the push and pull of harsh cold winds. ", stepTextKey="I must cleanse the corruption gnawing at the heart of the Wrothgar wilderness using Ushang's totem and destroy the blight's originator, Corintthac the Abomination."},
        ["Cleanse Aura of Corruption"] =
            {appendText=" \n\nMost of the reported red mist sightings were in the plains between Morkul Plain and Trader's Road Wayshrines.\n"},
        ["Defeat Corintthac the Abomination"] =
            {appendText=" and the Winterborn savages and hags praying to the tree spirit. Perhaps when their blood covers the stone altar their protector will appear to avenge his flock. Or join them in death.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I cleansed the forest's corruption and killed Corintthac. I should return to Ushang to claim my reward."},
        ["Talk to Ushang the Untamed"] =
            {appendText=" in Skalar's Hostel.\n"},
    },
[GetQuestName(5509)] = { --"Parts of the Whole"		-- JayAstrophel
        [1] =            
           {appendStepText="This hidden ruin lies northeast of the Morkul Stronghold, north of Orsinium, and southwest of the Two Rivers Wayshrine. Near one of the roads, look for spikes of ice jutting up and down around the entrance. Once inside, ", stepTextKey="I need to use Raynor's mysterious orb to collect data on the mechanical constructs of Zthenganaz. I must also destroy the dreaded Ztheng Guardian."},
        ["Analyze Dwarven Constructs"] =
            {appendText=" \n\nDuel any constructs you find in the area, but be sure to use Raynor's orb on them before they are fully defeated. It may need some time to recharge between uses.\n"},
        ["Destroy the Ztheng Guardian"] =
            {appendText=" in the northeast room of the ruin. A crackling fire in the center of the room is the backdrop to your upcoming battle.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I destroyed the Guardian and collected data on the Dwarven constructs. I should find Raynor Vanos and collect my reward."},
        ["Talk to Raynor Vanos"] =
            {appendText=" in Morkul Stronghold, northeast of the Morkul Plain wayshrine. Within the Clan Longhouse, Raynor is just to the left, sitting at a table.\n"},
    },
[GetQuestName(5518)] = { --"Meat for the Masses"	-- Aashiana
        [1] = 
            {appendStepText="In Skalar's Hostel outside Orsinium, Bagrugbesh said ", stepTextKey="I should hunt some of Wrothgar's larger animals for their meat. I should also slay the poachers who are disrupting the city's food supply."},
        ["Gather Stew Meat"] =
            {appendText=" \nThe larger animals of Wrothgar will provide the most meat.\n"},
        ["Stop the Poachers"] =
            {appendText=", at their camp on the wild eastern shore of the Great Bay, far to the west of Orsinium. The camp is strongly defended by hardy warriors and trained echateres."},
        [2] = 
            {appendStepText="", stepTextKey="I should deliver this meat to Bagrugbesh. She'll also want to hear how I dispatched the poachers."},
        ["Talk to Bagrugbesh"] =
            {appendText=", standing by the bar back at Skalar's Hostel outside of Orsinium."},
    },
[GetQuestName(5524)] = { --"Reeking of Foul Play"					-- Aashiana
        [1] = 
            {appendStepText="Sonolia Muspidius, one of the organizers of the caravans, is asking for my help in ending these raids. ", stepTextKey="I must rescue the prisoners and kill the Riekr leader, King-Chief Edu."},
        ["Rescue Prisoners"] =
            {appendText=" \n\nThe raids are attacking caravans coming into Orsinium from the north - the uninhabited areas northeast of the city could be one place to look. \n"},
        ["Defeat King-Chief Edu"] =
            {appendText=". \n\nA large compound on wooden platforms build into the eastern cliffs seems a likely base of operations for the Riekrs and their Chief. Be prepared for a vigorous defense!"},
        [2] = 
            {appendStepText="At his mountain base northeast of Orsinium, ", stepTextKey="I rescued the prisoners and killed King-Chief Edu. I should return to Sonolia Muspidius and inform her of my success."},
        ["Talk to Sonolia Muspidius"] =
            {appendText=", back at Skalar's Hostel just outside of Orsinium."},
    },
    [GetQuestName(5519)] = { --"Scholarly Salvage"		--TheoWriter
        [1] = 
            {appendStepText="While the surviving scholar managed to get to the safety of Skalar's Hostel, the ogres that attacked her caravan are still roaming the snowy forests, looking for new victims among the old ruins. ", stepTextKey="I must reclaim Cirantille's stolen pages from the ogres of Wrothgar and kill their leader, Mad Urkazbur."},
        ["Gather Torn Pages"] =
            {appendText=". \n"},
        ["Defeat Mad Urkazbur"] =
            {appendText=" in his camp in the valley between the northernmost mountain stream and the mountain stronghold of clan Fharun. This also just might make the nearby road to Jehanna Docks that much safer.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I recovered Cirantille's book and killed Mad Urkazbur. I should return to Orsinium and inform Cirantille of my success."},
        ["Talk to Cirantille"] =
            {appendText=" in Skalar's Hostel.\n", stepTextKey="I recovered Cirantille's book and killed Mad Urkazbur. I should return to Orsinium and inform Cirantille of my success."},
    },
   [GetQuestName(5523)] = { --"Snow and Steam"		--TheoWriter
        [1] = 
            {appendStepText="The snows between the mountain streams in the eastern fringes of Wrothgar are dangerous, in part due to the scattered remnants of dwemer mechanisms. That doesn't stop treasure hunters, of course - dwemer machinery has long attracted scholars, looters, and even goblins. ", stepTextKey="I need to seek out these buried Dwarven mechanisms and destroy the Dwarven Centurion, Nyzchaleft."},
        ["Investigate the Dwarven Mechanisms"] =
            {appendText=" \n\nBeing valuable both culturally and monetarily, there are likely scavenging parties of goblins and bandits digging through the snow to get to them first.\n"},
        ["Defeat Nyzchaleft"] =
            {appendText=" in the dwemer ruins he protects. Rumor is, that traveling northeast from the Shatul Wayshrine on a good day, the ruins can be seen from the skull bridge. \n\nCenturion is unlikely to face me himself, unless he sees his honor guard turned to scrap.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I disrupted the Dwarven mechanisms and defeated the construct known as Nyzchaleft. Now I should talk to Birkhu the Bold about my reward."},
        ["Talk to Birkhu the Bold"] =
            {appendText=" in Skalar's Hostel.\n"},
    },
   [GetQuestName(5504)] = { --"The Skin Trade"					-- JayAstrophel
        [1] = 
            {appendStepText="The mine can be found northwest of Orsinium, south of the Morkul Stronghold, and north of the Trader's Road Wayshrine. Wooden planks lead up to the entrance. Once inside, ", stepTextKey="I must slay the werewolves of Argent Mine to collect their pelts. I must also kill their leader, Magnar Child-Eater."},
        ["Collect High Quality Werewolf Pelts"] =
            {appendText=". Slay and loot any werewolves you see within the mine, and also keep a lookout for any especially good pelts left on the ground.\n"},
        ["Kill Magnar Child-Eater"] =
            {appendText=". This fierce lycanthrope dwells on the northeast side of the mine, and is surely guarded by others in the pack.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed Magnar and collected the werewolf pelts. I should return to Menninia to collect my reward."},
        ["Return to Menninia"] =
            {appendText=" at Morkul Stronghold, north of Argent Mine. She sits at a table just within the Clan Longhouse.\n"},
        [3] = 
            {appendStepText="", stepTextKey="I killed Magnar and collected the werewolf pelts. I should return to Menninia to collect my reward."},
        ["Talk to Menninia"] =
            {appendText=" at Morkul Stronghold, north of Argent Mine. She sits at a table just within the Clan Longhouse.\n"},
    },



-- ==================================================================================================================================================
--	Vvardenfell																															Undaunted
-- ==================================================================================================================================================

-- 		=========================================================================
--		 Vvardenfell - Main Quest
-- 		=========================================================================

	[GetQuestName(5803)] = { --"Divine Conundrum"					--Jordakai

		[1] = 
			{appendStepText="", stepTextKey="I should travel to Vvardenfell, in Morrowind, and see what's going on in that part of the world."},
		["Travel to Vvardenfell"] =
			{appendText=" to the town of Seyda Neen. I may need to use a wayshrine or travel by ship."},
		[2] = 
			{appendStepText="", stepTextKey="I should travel to Vvardenfell, in Morrowind, and locate Canon Llevule of the Tribunal outside the town of Seyda Neen."},
		["Travel to Vvardenfell"] =
			{appendText=". I may need to use a wayshrine or travel by ship."},
		[3] = 
			{appendStepText="", stepTextKey="I need to travel to the road outside Seyda Neen and locate Canon Valasa and the wounded Buoyant Armiger."},
		["Talk to Canon Valasa"] =
			{appendText=", who is kneeling by the prone armiger."},
		[4] = 
			{appendStepText="", stepTextKey="Canon Llevule remained behind at the Andrano Ancestral Tomb after the attack. The priest asked me to go to the tomb and help Llevule complete their mission for Lord Vivec."},
		["Go to the Andrano Ancestral Tomb"] =
			{appendText=" near a pond a short distance east, where the winding road from Seyda Neen meets another wide road. Canon Llevule is probably outside the dangerous tomb, near its entrance."},
		[5] = 
			{appendStepText="Across from a pond, ", stepTextKey="I located the Andrano Ancestral Tomb and found Canon Llevule. I should talk to him and determine how I can help him complete his mission for Lord Vivec."},
		["Talk to Canon Llevule"] =
			{appendText="."},
		[6] = 
			{appendStepText="Canon Llevule gave me a scroll with Lord Vivec's questions. Now, ", stepTextKey="I should enter the Andrano Ancestral Tomb and escort Canon Llevule to the summoning chamber."},
		["Enter the Andrano Ancestral Tomb"] =
			{appendText=", east of the village and across the road from a pond. Small braziers blaze at the entrance."},
		[7] = 
			{appendStepText="After speaking with Canon Llevule east of the village, I followed him. ", stepTextKey="We're inside the Andrano Ancestral Tomb. Now I need to escort Canon Llevule to the summoning chamber so that he can call forth his ancestor and we can ask Lord Vivec's questions."},
		["Escort Canon Llevule to the Summoning Chamber"] =
			{appendText=" within this Daedra-infested tomb."},
		[8] = 
			{appendStepText="Within the Andrano Ancestral Tomb, east of the village, ", stepTextKey="I should wait while Canon Llevule summons the spirit of his ancestor."},
		["Talk to the Ancestral Spirit 1"] =
			{appendText=" of Farena Andrano.", stepTextKey="I should wait while Canon Llevule summons the spirit of his ancestor."},
		[9] = 
			{appendStepText="Within the Andrano Ancestral Tomb, east of the village, ", stepTextKey="Canon Llevule summoned the spirit of his ancestor. He wants me to talk to her and present Lord Vivec's questions while he maintains the connection that allows her to materialize before us."},
		["Talk to the Ancestral Spirit 2"] =
			{appendText=" of Farena Andrano.", stepTextKey="Canon Llevule summoned the spirit of his ancestor. He wants me to talk to her and present Lord Vivec's questions while he maintains the connection that allows her to materialize before us."},
		[10] = 
			{appendStepText="", stepTextKey="Now that we got the answers to Lord Vivec's questions, Canon Llevule wants me to meet him outside the tomb to discuss what we learned."},
		["Talk to Canon Llevule Outside the Tomb"] =
			{appendText=" of the Andrano ancestors, near the pond where we first met. It is a short distance east of where the winding road from Seyda Neen meets another wide road."},
		[11] = 
			{appendStepText="", stepTextKey="Canon Llevule asked me to meet him at Vivec's Palace in Vivec City. I suppose I shouldn't keep the priest or Lord Vivec waiting."},
		["Enter Vivec's Palace"] =
			{appendText=" in the city of ziggurats rising from the water with a moonlet suspended above. The island's southernmost city is a marvelous sight."},
		[12] = 
			{appendStepText="Within his splendid palace in the city bearing his name, ", stepTextKey="I should present myself to Lord Vivec as soon as he's available."},
		["Talk to Vivec 1"] =
			{appendText=", hovering in radiant light.", stepTextKey="I should present myself to Lord Vivec as soon as he's available."},
		[13] = 
			{appendStepText="Within his splendid palace in the city bearing his name, ", stepTextKey="Lord Vivec has asked to speak with me. I should talk to him now."},
		["Talk to Vivec 2"] =
			{appendText=", the God-Monarch hovering in radiant light. Canon Llevule is already here.", stepTextKey="Lord Vivec has asked to speak with me. I should talk to him now."},
		[14] = 
			{appendStepText="In his palace, ", stepTextKey="Lord Vivec asked me to talk to Archcanon Tarvus to receive instructions on what I need to do next. I should be able to find Tarvus in the Archcanon's office."},
		["Talk to Archcanon Tarvus 1"] =
			{appendText=". His office is on the upper level of the administrative ziggurat that connects the palace to the rest of Vivec City.", stepTextKey="Lord Vivec asked me to talk to Archcanon Tarvus to receive instructions on what I need to do next. I should be able to find Tarvus in the Archcanon's office."},
		[15] = 
			{appendStepText="", stepTextKey="Lord Vivec requires a Blessing Stone to perform a ritual of divination. Archcanon Tarvus suggested I borrow one from the ziggurat still under construction in Vivec City. I need to head over there and talk to the Overseer."},
		["Talk to Overseer Shiralas"] =
			{appendText=" at the westernmost construction site."},
		[16] = 
			{appendStepText="Work at Vivec City's ziggurat construction site has stopped. ", stepTextKey="The passage to the Blessing Stone chamber collapsed. I need to clear the passage and rescue the workers before I can retrieve the Blessing Stone."},
		["Rescue the Workers"] =
			{appendText=" \n\nI may need to help remove some debris."},
		[17] = 
			{appendStepText="", stepTextKey="Now that the passage is clear and the workers are free, I can retrieve the Blessing Stone for Lord Vivec's ritual."},
		["Retrieve the Blessing Stone"] =
			{appendText=", a hanging yellow crystal."},
		[18] = 
			{appendStepText="After helping the workers at Vivec City's construction site, ", stepTextKey="I retrieved the Blessing Stone. Now I should return to Vivec's Palace and present the stone to Archcanon Tarvus."},
		["Talk to Archcanon Tarvus 2"] =
			{appendText=" inside the palace.", stepTextKey="I retrieved the Blessing Stone. Now I should return to Vivec's Palace and present the stone to Archcanon Tarvus."},
		[19] = 
			{appendStepText="I returned from the Vivec City construction site with the Blessing Stone and entered the palace. ", stepTextKey="Archcanon Tarvus wants me to participate in the divination ritual. He told me to stand in position as the third corner of the ritual triangle and place the Blessing Stone when I'm ready for him to begin the ritual."},
		["Start the Divination Ritual"] =
			{appendText="."},
		[20] = 
			{appendStepText="Inside the serenity of Vivec's Palace, we are isolated from the city's everyday life. Now, ", stepTextKey="I need to participate in the ritual and see what it reveals."},
		["Perform the Divination Ritual"] =
			{appendText="."},
		[21] = 
			{appendStepText="Although away from Vivec City's distractions within the palace's walls, ", stepTextKey="I don't think the divination ritual worked the way Archcanon Tarvus expected. I should talk to Lord Vivec and find out if he was able to learn what he had hoped."},
		["Talk to Vivec 3"] =
			{appendText=" as he hovers in radiance.", stepTextKey="I don't think the divination ritual worked the way Archcanon Tarvus expected. I should talk to Lord Vivec and find out if he was able to learn what he had hoped."},
		[22] = 
			{appendStepText="", stepTextKey="Lord Vivec didn't learn what he had hoped from the divination ritual. I should talk to him and see what he needs me to do next."},
		["Talk to Vivec 4"] =
			{appendText=" inside his palace in the southern city that bears his name.", stepTextKey="Lord Vivec didn't learn what he had hoped from the divination ritual. I should talk to him and see what he needs me to do next."},
	},

    [GetQuestName(5880)] = { --"Divine Inquiries"					--Jordakai
        [1] = 
            {appendStepText="In Vivec City, on the island's southern coast, ", stepTextKey="I should talk to Archcanon Tarvus in his office and find out what he needs me to investigate."},
        ["Talk to Archcanon Tarvus 1"] =
            {appendText=". His office is on the upper level of the city's Temple Canton.", stepTextKey="I should talk to Archcanon Tarvus in his office and find out what he needs me to investigate."},
        [2] = 
            {appendStepText="In his office at Vivec City's Temple Canton, ", stepTextKey="Archcanon Tarvus asked me to investigate three sites to search for clues concerning the source of whatever is draining Vivec's divine energy. These sites include Barilzar's tower, Balmora, and Ald'ruhn."},
        ["Investigate Barilzar's Tower"] =
            {appendText=", a short, round tower in the island's southeast on the easternmost inlet of shallow seawater. It is secluded south of a Dwemer ruin. I could use the Silt-Strider caravaner service to get from Vivec City to Suran and on to Molag Mar. And then travel farther east on foot."},
        ["Investigate Balmora"] =
            {appendText=", a city on a river to the northwest of Vivec City along a wide, winding road that connects the two cities. It has two mines nearby, a small one to the west on a trail at the edge of the swamp, and a large one to the south. Perhaps I should start by asking around in a local inn or tavern. \n\nI can travel by road, Silt-Strider caravaner, or wayshrine. Or I can venture cross-country and explore the wilds of Red Mountain's island."},
        ["Investigate Ald'ruhn"] =
            {appendText=", a gathering of Ashlander tribes. They are encamped in a curved foyada - a fire-river - north of Balmora. There is a wayshrine nearby. Perhaps I can find an Ashlander willing to speak with me on the road leading into the area, south of the wayshrine. \n\nI can travel by road or wayshrine. Or I can venture cross-country and explore the wilds of Red Mountain's island."},
        [3] = 
            {appendStepText="", stepTextKey="I investigated the locations Archcanon Tarvus suggested and collected the cult's ritual bag, the Red Exiles instructions, Chodala's writings, and Barilzar's notes. The Archcanon sent me a message. He needs me back at Vivec's Palace."},
        ["Return to the Archcanon's Office"] =
            {appendText=" on the upper level of Vivec City's Temple Canton."},
        [4] = 
            {appendStepText="", stepTextKey="I returned to Vivec City. Now I should talk to Archcanon Tarvus, let him know what I found out at Balmora, Ald'ruhn, and Barilzar's tower, and find out what emergency transpired that he saw fit to send me a message."},
        ["Talk to Archcanon Tarvus 2"] =
            {appendText=" in his office on the upper level of the city's Temple Canton.", stepTextKey="I returned to Vivec City. Now I should talk to Archcanon Tarvus, let him know what I found out at Balmora, Ald'ruhn, and Barilzar's tower, and find out what emergency transpired that he saw fit to send me a message."},
        [5] = 
            {appendStepText="I returned to Vivec City and spoke with the Archcanon. ", stepTextKey="While Archcanon Tarvus reviews what I uncovered during my investigations, I should report to Lord Vivec and let him know I returned."},
        ["Talk to Vivec"] =
            {appendText=" in his palace, south of the Temple Canton."},
    },

	[GetQuestName(5888)] = { --"Divine Delusions"					--Jordakai
		[1] = 
			{appendStepText="In Vivec City, Canon Valasa said ", stepTextKey="I should enter the Hall of Wisdom and go to Archcanon Tarvus's office. Then I can learn more about what the Archcanon has planned."},
		["Talk to Archcanon Tarvus"] =
			{appendText=". He should be in his office on the upper level of the city's Temple Canton.\n\nIt seems that Canon Valasa is aware of the planned expansion of the canton that will be known as the Hall of Wisdom."},
		[2] = 
			{appendStepText="", stepTextKey="Instead of confronting Chodala directly, the Archcanon suggests I return to Ald'ruhn and talk to his sister, Seryn. She was willing to help me last time and might be willing to do so again."},
		["Return to Ald'ruhn"] =
			{appendText=", the Ashlander encampment in the curved foyada north of Balmora. There is a wayshrine nearby. Seryn should be somewhere in the camp."},
		[3] = 
			{appendStepText="", stepTextKey="I reached Ald'ruhn and located Seryn. It looks like she was expecting me. I should talk to her."},
		["Talk to Seryn 1"] =
			{appendText=". She holds her staff at a campfire in the Ashlander encampment's northeast, near a gigantic crab-like formation.", stepTextKey="I reached Ald'ruhn and located Seryn. It looks like she was expecting me. I should talk to her."},
		[4] = 
			{appendStepText="In Ald'ruhn, at the Ashlander encampment near a gigantic crab-like formation, ", stepTextKey="Seryn wants to try to talk to her brother. She warned me that we need to follow Ashlander traditions in this; if I attack Chodala, it will just lead to war. I should follow her into the Wise Woman's hut and talk to her."},
		["Talk to Seryn 2"] =
			{appendText=" inside Wise Woman Dovrosi's Hut. It has a covered entrance.", stepTextKey="Seryn wants to try to talk to her brother. She warned me that we need to follow Ashlander traditions in this; if I attack Chodala, it will just lead to war. I should follow her into the Wise Woman's hut and talk to her."},
		[5] = 
			{appendStepText="Within Wise Woman Dovrosi's Hut in northeastern Ald'ruhn, ", stepTextKey="Seryn asked me to journey to the Cavern of the Incarnate and talk to the Wise Woman. She wants me to convince her not to support Chodala's claim that he's the Nerevarine."},
		["Go to the Cavern of the Incarnate"] =
			{appendText=". Seryn said it is northeast of Ald'ruhn, on the far side of Red Mountain. As a shrine to Azura, I suspect it will be in a secluded place. \n\nThe cavern is likely at the end of a curved trail in the island's northern mountains, east of a foyada."},
		[6] = 
			{appendStepText="I journeyed to the ashen mountains of northern Vvardenfell, then south of the Valley of the Wind Wayshrine to the end of a curved trail. ", stepTextKey="I reached the Cavern of the Incarnate to find the Wise Woman under attack! I need to rescue her."},
		["Rescue the Wise Woman"] =
			{appendText=" from the taunting Daedra."},
		[7] = 
			{appendStepText="In the ashen mountains of northern Vvardenfell, south of the Valley of the Wind Wayshrine, I found Dovrosi at the end of a curved trail. ", stepTextKey="I rescued the Wise Woman from her Daedric attackers. Now I should meet her inside the Cavern of the Incarnate and talk to her about Chodala's claim."},
		["Talk to the Wise Woman in the Cavern"] =
			{appendText=" of the Incarnate."},
		[8] = 
			{appendStepText="South of the Valley of the Wind Wayshrine in the island's northern mountains is the Cavern of The Incarnate. ", stepTextKey="The Wise Woman said we need knowledge to discredit Chodala's claim. She gave me grave dust so I can commune with the spirits of the Incarnates — failed Nerevarine from previous generations — to build an argument against Chodala."},
		["Commune with Incarnate Ranso"] =
			{appendText=".\n"},
		["Commune with Incarnate Aduri"] =
			{appendText=".\n"},
		["Commune with Incarnate Danaat"] =
			{appendText=".\n\nTo speak to each failed incarnate, I must sprinkle a pouch of the blessed grave dust I have upon each corpse."},
		[9] = 
			{appendStepText="South of the Valley of the Wind Wayshrine in the island's northern mountains is the Cavern of The Incarnate. ", stepTextKey="Azura, the Daedric Prince of Dawn and Dusk, manifests from the great statue and commands that I speak with her."},
		["Talk to Azura 1"] =
			{appendText=".", stepTextKey="Azura, the Daedric Prince of Dawn and Dusk, manifests from the great statue and commands that I speak with her."},
		[10] = 
			{appendStepText="I spoke with The Lady of Dusk and Dawn in the Cavern of The Incarnate. ", stepTextKey="Azura bade me to take the words of the Incarnates and return to Ald'ruhn. I need to let Seryn know what I discovered."},
		["Talk to Seryn 3"] =
			{appendText=" at Ald'ruhn, the Ashlander encampment near the curved foyada on western Red Mountain.\n\nShe is probably at the campsite in the settlement's northeast, near the large crab-like formation. I should let her know about the three scrolls I received, the Failed Incarnates, and Azura.", stepTextKey="Azura bade me to take the words of the Incarnates and return to Ald'ruhn. I need to let Seryn know what I discovered."},
		[11] = 
			{appendStepText="", stepTextKey="The Ashlander tribal council is meeting inside Skar in Ald'ruhn. I should go inside so I can help Seryn convince the tribes that Chodala isn't the Nerevarine."},
		["Enter Skar"] =
			{appendText=", the gigantic Emperor land-crab shell that has been hollowed out to use as a meeting hall.\n\nI have the scrolls of the Failed Incarnates with me to help Seryn."},
		[12] = 
			{appendStepText="I am inside Skar, the gigantic crab-shell meeting hall in Ald'ruhn. ", stepTextKey="Since I can't speak in the Ashlander council, I need to provide Seryn with the proper scroll at the proper time. Hopefully, the examples each scroll demonstrates will convince the tribes not to accept Chodala as the Nerevarine."},
		["Help Seryn Disprove Chodala's Claim"] =
			{appendText=" using the scrolls I have. I should stand by Seryn."},
		[13] = 
			{appendStepText="Inside Skar, the gigantic crab-shell meeting hall in Ald'ruhn, ", stepTextKey="Chodala refused to bow to the Wise Woman's decision and revealed that the staff protects him from harm. He ordered the Red Exiles to destroy the council of tribes. I need to protect the tribe members and stop the Red Exiles."},
		["Defeat the Red Exiles"] =
			{appendText="."},
		[14] = 
			{appendStepText="Chodala ran from the council meeting in Skar, and ", stepTextKey="Seryn went after her brother. I should follow her."},
		["Follow Seryn"] =
			{appendText=" outside Skar and find her near the northeast campsite in Ald'ruhn."},
		[15] = 
			{appendStepText="I found Seryn in the northeastern camp at Ald'ruhn. ", stepTextKey="Azura has taken possession of Seryn and wants to talk to me. I should see what she has to say."},
		["Talk to Azura 2"] =
			{appendText=", the Lady of Dawn and Dusk.", stepTextKey="Azura has taken possession of Seryn and wants to talk to me. I should see what she has to say."},
		[16] = 
			{appendStepText="In Ald'ruhn, ", stepTextKey="Azura urged me to return to Vivec's Palace immediately. I need to see how Vivec's doing while Seryn tracks down her brother, Chodala."},
		["Return to Vivec's Palace"] =
			{appendText=" in Vivec City on the southern coast. I should speak with Seryn before I go."},
		[17] = 
			{appendStepText="I entered Vivec's Palace in his southern city. ", stepTextKey="Lord Vivec looks terrible! He's even weaker and more enfeebled than he was the last time I saw him. I should talk to him and see if there's anything I can do to help."},
		["Talk to Vivec"] =
			{appendText=" as he sits and rests. The archcanon is here, too."},
	},

	[GetQuestName(5893)] = { --"Divine Intervention"					--Jordakai
		[1] = 
			{appendStepText="I spoke with the Archcanon in Vivec's Palace. ", stepTextKey="Archcanon Tarvus wants me to return to Barilzar's tower and ask the mage if he knows how we can overcome the power of Chodala's staff, Sunna'rah."},
		["Return to Barilzar's Tower"] =
			{appendText=". The Clockwork mage's home is an ancient Velothi stone stucture, east of Molag Mar on the east bank of a large inlet in southeast Vvardenfell."},
		[2] = 
			{appendStepText="East of Molag Mar on the east bank of a large inlet, I returned to the Clockwork mage's home. ", stepTextKey="I need to search Barilzar's tower and find the mage."},
		["Find Barilzar"] =
			{appendText=" inside."},
		[3] = 
			{appendStepText="I returned to the tower on the east bank of a large inlet in southeast Vvardenfell. ", stepTextKey="Inside Barilzar's tower, I found that the place was overrun by Daedra! I need to deal with the monsters before I can talk to Barilzar."},
		["Rescue Barilzar"] =
			{appendText="."},
		[4] = 
			{appendStepText="In Barilzar's Velothi tower on the east bank of a large inlet in southeast Vvardenfell, ", stepTextKey="I defeated the Daedra. Now I can talk to Barilzar and ask him if he knows of a way to circumvent the powers of Chodala's staff, Sunna'rah."},
		["Talk to Barilzar 1"] =
			{appendText=" within his inner sanctum where he fiddles with a Dwemer construct.", stepTextKey="I defeated the Daedra. Now I can talk to Barilzar and ask him if he knows of a way to circumvent the powers of Chodala's staff, Sunna'rah."},
		[5] = 
			{appendStepText="Inside his tower on the east bank of a large inlet in southeast Vvardenfell, I spoke with the Clockwork mage. ", stepTextKey="Barilzar thinks he can build a tonal inverter to counter the power of Chodala's staff. He needs me to collect the components to craft the device and has sent me to Molag Mar to get help from hirelings he's used in the past."},
		["Talk to Leona Blasio"] =
			{appendText=", a well-educated Imperial who is experienced in exploring Dwemer ruins.\n"},
		["Talk to Volrina Quarra"] =
			{appendText=", a highly intelligent Imperial who studied with Barilzar. She works with her brother.\n"},
		["Talk to Snorfin"] =
			{appendText=", a Nord with a knack for finding rare things. He may be at the town's small dock.\n\nBarilzar gave me a document listing the hirelings and components he will need. Time to visit the southeastern town of Molag Mar, with a single ziggurat."},
		[6] = 
			{appendStepText="At the southeastern town of Molag Mar, I found Leona, Volrina, and Snorfin. ", stepTextKey="Barilzar's former hirelings pointed me toward three ruins where I can find the components he needs to craft the tonal inverter: Nchuleft, Arkngthunch-Sturdumz, and Galom Daeus. I just need to overcome any obstacles in the ruins to retrieve the items."},
		["Retrieve Nchuleft Component"] =
			{appendText=" from the Dwemer ruin on the eastern side of the mountains southwest of Vos in northeast Vvardenfell. From Molag Mar I can take a Silt-Strider to Tel Mora or use the Tel Mora wayshrine. I need to find a Manual Clockwork Shaft there. Its ornate chest is likely secluded in the northern, deepest depths of the ruin.\n"},
		["Retrieve Arkngthunch-Sturdumz Component"] =
			{appendText=" from the Dwemer ruin atop a high cliff on the coast northwest of the northwestern town of Gnisis. I must find Snorfin's notes to help me find the Sonance Generator, which is protected within an ornate chest.\n"},
		["Retrieve Galom Daeus Component"] =
			{appendText=" from the vampire lair in a ruin on the southeastern slopes of Red Mountain. It is on the edge of a foyada near the southern junction of the area's winding north-south road, northwest of the Nchuleftingth Wayshrine. I should find the notes Volrina said she left. The Inversion Conduit is probably in another ornate chest.\n"},
		[7] = 
			{appendStepText="", stepTextKey="I retrieved all three components needed to create the tonal inverter. Now to see if Barilzar can build the device he promised."},
		["Give Barilzar the Components"] =
			{appendText=" from the Dwemer chests found in the ruins. He will be in his laboratory at his tower on the east bank of a large inlet in southeast Vvardenfell."},
		[8] = 
			{appendStepText="I returned to Barilzar's Tower on the east bank of a large inlet in southeast Vvardenfell. ", stepTextKey="It looks like Barilzar completed the construction of the tonal inverter. I should retrieve it from his work table."},
		["Get the Tonal Inverter"] =
			{appendText="."},
		[9] = 
			{appendStepText="I watched Barilzar build the device at his tower on the east bank of a large inlet in southeast Vvardenfell. ", stepTextKey="Now that I have the tonal inverter, I should ask Barilzar how it works."},
		["Talk to Barilzar 2"] =
			{appendText=" in his laboratory.", stepTextKey="Now that I have the tonal inverter, I should ask Barilzar how it works."},
		[10] = 
			{appendStepText="", stepTextKey="I received the tonal inverter and instructions on how to use the device from Barilzar. Now I should return to the Archcanon's office in Vivec City and let Archcanon Tarvus know that we have a way to disrupt Chodala's power."},
		["Report to Archcanon Tarvus"] =
			{appendText=" at his office in the city's Temple Canton."},
		[11] = 
			{appendStepText="In his office in Vivec City’s Temple Canton, ", stepTextKey="Archcanon Tarvus is holding Seryn. I should talk to him to let him know I have Barilzar's device and convince him to allow Seryn to help me use it against Chodala."},
		["Talk to Archcanon Tarvus 1"] =
			{appendText=".", stepTextKey="Archcanon Tarvus is holding Seryn. I should talk to him to let him know I have Barilzar's device and convince him to allow Seryn to help me use it against Chodala."},
		[12] = 
			{appendStepText="I spoke to the Archcanon in his Temple Canton office in Vivec City. ", stepTextKey="Now that that's settled and I convinced the Archcanon to let Seryn assist me, I should talk to Seryn and decide our next course of action."},
		["Talk to Seryn 1"] =
			{appendText=".", stepTextKey="Now that that's settled and I convinced the Archcanon to let Seryn assist me, I should talk to Seryn and decide our next course of action."},
		[13] = 
			{appendStepText="", stepTextKey="Seryn says that her brother and a few of his followers have taken refuge in a shrine to the Daedric Prince Malacath. I should meet her there."},
		["Meet Seryn at Kaushtarari"] =
			{appendText=", a Daedric shrine south of the eastern city of Sadrith Mora and east of the Halls of Fabrication. \n\nI should travel by boat to Sadrith Mora from Vivec City's small dock near the Caravaner Tower, or use the Sadrith Mora Wayshrine."},
		[14] = 
			{appendStepText="South of Sadrith Mora, ", stepTextKey="I rendezvoused with Seryn at the ruins of Kaushtarari. I should give her the tonal inverter before we go inside to confront Chodala."},
		["Give Seryn the Tonal Inverter"] =
			{appendText="."},
		[15] = 
			{appendStepText="South of Sadrith Mora, we prepare to confront Chodala inside the shrine to the Daedric Prince Malacath. ", stepTextKey="Seryn has the tonal inverter. Now to head into the shrine and confront Chodala."},
		["Enter Kaushtarari"] =
			{appendText="."},
		[16] = 
			{appendStepText="South of Sadrith Mora, ", stepTextKey="Seryn and I have entered the ruins of Kaushtarari. Now we need to locate Chodala and defeat him so that we can recover the staff, Sunna'rah."},
		["Defeat Chodala"] =
			{appendText="."},
		[17] = 
			{appendStepText="South of Sadrith Mora, within Kaushtarari, the Daedric shrine to Malacath, we found Chodala, but with minions of a different Daedric Prince. ", stepTextKey="We defeated Chodala. I should talk to Seryn and see how she's handling all this."},
		["Talk to Seryn 2"] =
			{appendText=".", stepTextKey="We defeated Chodala. I should talk to Seryn and see how she's handling all this."},
		[18] = 
			{appendStepText="In the shrine to Malacath within Kaushtarari, the Daedric ruin south of Sadrith Mora, Seryn and I did what was necessary. ", stepTextKey="Now that Chodala has been defeated, I should gather up the staff called Sunna'rah."},
		["Take Sunna'rah"] =
			{appendText=", the blessed staff, and return to Vivec City."},
		[19] = 
			{appendStepText="", stepTextKey="I have Sotha Sil's device, Sunna'rah. Now I need to return to Vivec City and see if the staff can be used to restore Lord Vivec. Seryn said she'd meet me there after she takes care of her brother's remains."},
		["Return to Vivec's Palace"] =
			{appendText="."},
		[20] = 
			{appendStepText="I returned to Vivec City and entered the palace. Lord Vivec was not in his usual place. ", stepTextKey="I need to talk to Archcanon Tarvus. I'll probably find him in Vivec's chambers, tending to the weakened god."},
		["Talk to Archcanon Tarvus 2"] =
			{appendText=", downstairs in Vivec's Private Chambers.", stepTextKey="I need to talk to Archcanon Tarvus. I'll probably find him in Vivec's chambers, tending to the weakened god."},
		[21] = 
			{appendStepText="Within Lord Vivec's Private Chambers in Vivec City's palace, ", stepTextKey="Archcanon Tarvus wants me to use Sunna'rah on Lord Vivec so that his divine energy is returned to him."},
		["Use Sunna'rah"] =
			{appendText=" by placing it in the holder near the foot of Vivec's bed."},
		[22] = 
			{appendStepText="Within Lord Vivec's Private Chambers in Vivec City's palace, ", stepTextKey="I used Sunna'rah as the Archcanon suggested, but something's wrong! It's hurting Vivec, not helping him! Why has the Archcanon betrayed us?"},
		["Witness the Archcanon's Betrayal"] =
			{appendText="."},
		[23] = 
			{appendStepText="Within Lord Vivec's Private Chambers in Vivec City's palace, ", stepTextKey="Seryn thought quickly and used the tonal inverter to once again stop Sunna'rah. I should talk to her and see if we can make sense of what just happened."},
		["Talk to Seryn 3"] =
			{appendText=", standing near Vivec's hovering spirit.", stepTextKey="Seryn thought quickly and used the tonal inverter to once again stop Sunna'rah. I should talk to her and see if we can make sense of what just happened."},
		[24] = 
			{appendStepText="Within Lord Vivec's Private Chambers in Vivec City's palace, ", stepTextKey="Vivec survived that last attempt—barely. I need to talk to him and find out if he can tell me more about Barbas and what just happened here."},
		["Talk to Vivec"] =
			{appendText="'s spirit hovering over his body."},
	},

    [GetQuestName(5902)] = { --"Divine Disaster"					--Jordakai
        [1] = 
            {appendStepText="Within Lord Vivec's Private Chambers in Vivec City's palace, ", stepTextKey="Canon Llevule suggested that we retrieve another Blessing Stone from the construction site so that Vivec can use it to restore some of his stolen energy. I need to find the Overseer to get the stone."},
        ["Find the Overseer"] =
            {appendText=", Shiralas, at Vivec City's construction site. People near the site may be able to help me. There is a well-dressed female Dunmer at the site, she seems distraught and out of place..."},
        [2] = 
            {appendStepText="Near the Vivec City construction site, I spoke with her wife, Valora Beloren. ", stepTextKey="The Overseer raced into the construction site to chase after looters. I need to find her to get the Blessing Stone for Lord Vivec. Besides, the Overseer might need help against the looters."},
        ["Search the Construction Site"] =
            {appendText=". I should ask the workers if they have seen the Overseer. She's probably at the northern site attached to St. Delyn's Canton."},
        [3] = 
            {appendStepText="In Vivec City's northern construction site, I found her. ", stepTextKey="Now that the looters have been dealt with, I need to talk to Overseer Shiralas and see about getting another Blessing Stone."},
        ["Talk to Overseer Shiralas"] =
            {appendText="."},
        [4] = 
            {appendStepText="The northeastern part of Vivec City's construction site is locked, but Shiralas gave me a key. ", stepTextKey="I need to use the key and enter the sealed portion of the construction site where the third canton is being built. Then I can retrieve the remaining Blessing Stone for Lord Vivec."},
        ["Retrieve the Blessing Stone"] =
            {appendText=" from where it hangs on a tripod in the western part of the third canton work site."},
        [5] = 
            {appendStepText="From the third canton in Vivec City's construction site, ", stepTextKey="I collected the Blessing Stone. Now I need to return to Canon Llevule and Lord Vivec."},
        ["Return to Vivec's Chambers"] =
            {appendText=" in the palace. I should be able to leave the third canton site from the southeastern walkway leading to St. Olms Canton."},
        [6] = 
            {appendStepText="I returned to Vivec's Private Chambers within his palace. ", stepTextKey="Now I need to see if Canon Llevule can use the Blessing Stone to restore at least a little of Lord Vivec's energy."},
        ["Talk to Canon Llevule 1"] =
            {appendText=", who is standing near Vivec's spirit.", stepTextKey="Now I need to see if Canon Llevule can use the Blessing Stone to restore at least a little of Lord Vivec's energy."},
        [7] = 
            {appendStepText="Within Vivec's Private Chambers in Vivec City's palace, Canon Llevule used the Blessing Stone. ", stepTextKey="The boost of energy from the Blessing Stone seems to have helped Lord Vivec, at least a little. I should talk to Canon Llevule and see if there's anything else we need to do before I try to track down Barbas."},
        ["Talk to Canon Llevule 2"] =
            {appendText=".", stepTextKey="The boost of energy from the Blessing Stone seems to have helped Lord Vivec, at least a little. I should talk to Canon Llevule and see if there's anything else we need to do before I try to track down Barbas."},
    },

	[GetQuestName(5905)] = { --"Divine Restoration"					--Jordakai
		[1] = 
			{appendStepText="I spoke with Lord Vivec in his Private Chambers within Vivec City's palace. ", stepTextKey="Lord Vivec wants me to consult with Azura's champion, Seryn, and see if her patron has any wisdom to share concerning Clavicus Vile and Barbas. She should be in the Archcanon's office, looking for clues."},
		["Find Seryn"] =
			{appendText=", the Ashlander who is Azura's  Champion."},
		[2] = 
			{appendStepText="I entered the Archcanon's office in Vivec City's Temple Canton. Just as I was ready to speak with her, ", stepTextKey="Azura possessed Seryn again. I should talk to her and see if she has any advice on how we deal with Clavicus Vile and Barbas."},
		["Talk to Azura"] =
			{appendText=", the Lady of Twilight."},
		[3] = 
			{appendStepText="In the Archcanon's office in Vivec City, ", stepTextKey="Azura summoned Barilzar to help me get to the Clockwork City. I should talk to him and see if he knows where Sotha Sil's creation is hidden."},
		["Talk to Barilzar 1"] =
			{appendText=", the Clockwork mage.", stepTextKey="Azura summoned Barilzar to help me get to the Clockwork City. I should talk to him and see if he knows where Sotha Sil's creation is hidden."},
		[4] = 
			{appendStepText="", stepTextKey="Barilzar can't teleport us directly to the Clockwork City, but he can open the secret entrance to the city, located underneath the Tribunal Temple in Mournhold. I should enter the portal and follow Barilzar."},
		["Enter Barilzar's Portal"] =
			{appendText=" to Seht's Vault that he opened in the Archcanon's office in Vivec City."},
		[5] = 
			{appendStepText="Within Seht's Vault, ", stepTextKey="I need to clear a path through the Daedra so that Barilzar and I can reach the entrance to the Clockwork City."},
		["Reach the Entrance to the Clockwork City"] =
			{appendText=" through the passageway and across a bridge. The entrance will probably be guarded."},
		[6] = 
			{appendStepText="After entering the Portal to Seht's Vault that Barilzar opened in the Archcanon's office in Vivec City, we arrived at the entrance to the Clockwork City. ", stepTextKey="We made it past the Daedra and defeated the Clockwork Guardian. Now to enter the Clockwork City and see what's waiting for us inside."},
		["Explore the Clockwork City"] =
			{appendText=" with Barilzar. I suspect we will find Barbas, too."},
		[7] = 
			{appendStepText="In the Clockwork City, ", stepTextKey="Barbas locked the path ahead of us. To follow him, we need to enter the maintenance junction and navigate through its twisting paths."},
		["Navigate the Maintenance Junction"] =
			{appendText=" with Barilzar's help. I should speak to him since he has been here before."},
		[8] = 
			{appendStepText="In the Clockwork City's maintenance area, ", stepTextKey="I need to disable the repair factotums and the couplings to open the way ahead so I can get past the gate."},
		["Get Past the Gate"] =
			{appendText="."},
		[9] = 
			{appendStepText="We got through the Gate in the Clockwork City's Maintenance Junction. ", stepTextKey="We spotted Barbas. I should find a way to follow him."},
		["Follow Barbas"] =
			{appendText=", who headed off to the northwest. If he blocks my path again, I should find another way into the next area."},
		[10] = 
			{appendStepText="Within the Clockwork City, we found The Divine Atelier. ", stepTextKey="The workshop where Vivec's divine energy is stored is just ahead. I should go inside and try to stop Barbas before he gains access to all that power."},
		["Enter the Divinity Atelier"] =
			{appendText=" and defeat Barbas. I should speak with Barilzar before entering the workshop."},
		[11] = 
			{appendStepText="Within Sotha Sil's Clockwork City workshop, The Divine Atelier, ", stepTextKey="I need to find a way to access the energy reservoir before I can retrieve Vivec's stolen power and get my hands on Barbas and the staff."},
		["Enter the Energy Reservoir"] =
			{appendText=". I will need to disable or destroy any defenses and unlock access to the platforms."},
		[12] = 
			{appendStepText="I destroyed the defenses and gained access in Sotha Sil's Clockwork City workshop. ", stepTextKey="Now I need to enter the final chamber to defeat Barbas and take back Sotha Sil's staff, Sunna'rah."},
		["Defeat Barbas"] =
			{appendText="."},
		[13] = 
			{appendStepText="In the Energy Reservoir area of The Divine Atelier, ", stepTextKey="I defeated Barbas. Now I need to take Sunna'rah and use it to reverse the flow of divine energy."},
		["Reverse the Energy Flow"] =
			{appendText=" by pointing the staff at the reservoir."},
		[14] = 
			{appendStepText="In the Energy Reservoir area of The Divine Atelier, ", stepTextKey="I stopped Barbas and gathered Vivec's divine energy into Sunna'rah. Now I should use the portal and return to Vivec City."},
		["Return to Vivec's Palace"] =
			{appendText=" via the portal."},
		[15] = 
			{appendStepText="", stepTextKey="The portal didn't return me to Vivec City. Instead, I appear to be inside some sort of Daedric shrine. And Clavicus Vile just addressed me. I guess I should talk to him."},
		["Talk to Clavicus Vile"] =
			{appendText=", the Daedric Prince of Trickery and Bargains. I suppose he will want me to talk to his statue."},
		[16] = 
			{appendStepText="", stepTextKey="Barilzar has projected an image of himself into this strange place. I should talk to him."},
		["Talk to Barilzar 2"] =
			{appendText=".", stepTextKey="Barilzar has projected an image of himself into this strange place. I should talk to him."},
		[17] = 
			{appendStepText="I spoke to a projection of Barilzar in this shrine to Clavicus Vile. ", stepTextKey="Barilzar suggests that I use a small portion of Vivec's energy to distract Clavicus Vile so that he can pull me out of this place. I should use Sunna'rah on Vile's statue."},
		["Use Sunna'rah on Clavicus Vile"] =
			{appendText="."},
		[18] = 
			{appendStepText="", stepTextKey="Barilzar succeeded and returned me to Vivec's Palace. I should talk to Lord Vivec and see what I need to do to restore his stolen energy."},
		["Talk to Vivec 1"] =
			{appendText="'s spirit in his private chambers within the palace.", stepTextKey="Barilzar succeeded and returned me to Vivec's Palace. I should talk to Lord Vivec and see what I need to do to restore his stolen energy."},
		[19] = 
			{appendStepText="I spoke with Vivec's spirit in the palace's private chambers. ", stepTextKey="Lord Vivec wants me to use Sunna'rah and restore to him his divine energy."},
		["Use Sunna'rah to Restore Vivec"] =
			{appendText="'s energy by pointing it at him."},
		[20] = 
			{appendStepText="In his private chambers in the Vivec City palace, ", stepTextKey="I did as Vivec asked and restored his divine energy. I should talk to him and make sure he's all right now."},
		["Talk to Vivec 2"] =
			{appendText=", who is again hovering in radiance.", stepTextKey="I did as Vivec asked and restored his divine energy. I should talk to him and make sure he's all right now."},
	},

    [GetQuestName(6003)] = { --"Divine Blessings"					--Jordakai
        [1] = 
            {appendStepText="In his Vivec City palace, ", stepTextKey="Vivec asked me to retrieve the Archcanon's Signet from Tarvus's office in the Hall of Wisdom."},
        ["Retrieve the Archcanon's Signet"] =
            {appendText="."},
        [2] = 
            {appendStepText="", stepTextKey="Vivec told me to meet him at the city's central canton, near the statue erected in his honor, after I retrieved the Archcanon's Signet."},
        ["Meet Vivec"] =
            {appendText="."},
        [3] = 
            {appendStepText="We are gathered in the northwest area of Vivec City's Temple Canton. ", stepTextKey="I should talk to Vivec and let him know I found the signet so that he can continue his ceremony with the assembled crowd."},
        ["Talk to Vivec 1"] =
            {appendText=".", stepTextKey="I should talk to Vivec and let him know I found the signet so that he can continue his ceremony with the assembled crowd."},
        [4] = 
            {appendStepText="We are gathered in the northwest area of Vivec City's Temple Canton. ", stepTextKey="Overseer Shiralas gave me the Blessing Stones Vivec needed and helped protect the cantons during the disaster. I should reach into the sack and give her her reward."},
        ["Reward Overseer Shiralas"] =
            {appendText="."},
        [5] = 
            {appendStepText="We are gathered in the northwest area of Vivec City's Temple Canton. ", stepTextKey="Barilzar taught me about the transfer of divine energy and helped me get into the Clockwork City. I should reach into the sack and find his reward."},
        ["Reward Barilzar"] =
            {appendText=", the Clockwork mage."},
        [6] = 
            {appendStepText="We are gathered in the northwest area of Vivec City's Temple Canton. ", stepTextKey="Without Canon Llevule, I never would have come to Vivec's aid. I should reach into the sack and see what reward Vivec has decided to bestow upon him."},
        ["Reward Canon Llevule"] =
            {appendText=" with the signet ring of the archcanon."},
        [7] = 
            {appendStepText="We are gathered in the northwest area of Vivec City's Temple Canton. ", stepTextKey="Lord Vivec has called me forth. I should present myself and talk to him."},
        ["Talk to Vivec 2"] =
            {appendText=".", stepTextKey="Lord Vivec has called me forth. I should present myself and talk to him."},
    },

	[GetQuestName(5887)] = { --"Fleeing the Past"					--Jordakai
		[1] = 
			{appendStepText="In the western city of Balmora, I spoke with a Redoran soldier. ", stepTextKey="If I want to help find the missing Dark Elf named Veya, I need to go to the Redoran Kinhouse and talk to Councilor Eris Releth."},
		["Talk to Councilor Eris 1"] =
			{appendText=" about his daughter. He should be at the Redoran Kinhouse in the city's west, south of the Balmora Tribunal Temple.", stepTextKey="If I want to help find the missing Dark Elf named Veya, I need to go to the Redoran Kinhouse and talk to Councilor Eris Releth."},
		[2] = 
			{appendStepText="Inside his Redoran Kinhouse in Balmora, ", stepTextKey="Councilor Eris asked me to investigate the disappearance of his daughter, Veya. He suggested I start by talking to Captain Brivan before I try to track down some of her friends around the town of Balmora."},
		["Talk to Captain Brivan"] =
			{appendText=", who should be on patrol near the town square, south of The Randy Netch Inn."},
		[3] = 
			{appendStepText="In the town square, ", stepTextKey="Captain Brivan suggested I try to track down some of Veya's friends around the town of Balmora. Maybe they can point me toward the councilor's daughter."},
		["Track Veya's Friends"] =
			{appendText=", gathered on the east side of town, chatting and enjoying drinks in the open air. The captain suspects they act as messengers, running notes for Veya."},
		[4] = 
			{appendStepText="In Balmora, ", stepTextKey="I followed the note carriers to the inn, where they delivered a letter to someone named Drevis. I should confront him and see what he knows about Veya's whereabouts."},
		["Confront Drevis"] =
			{appendText=" inside The Randy Netch Inn."},
		[5] = 
			{appendStepText="Inside The Randy Netch Inn, ", stepTextKey="Drevis explained that he passes notes to a local tough named Ashur who's in contact with Veya. They meet with him just outside Balmora, to the north and east of the city. I should try to find this agent."},
		["Find Ashur"] =
			{appendText=". He shouldn't be too far away but may be off to the side of the road to remain unnoticed."},
		[6] = 
			{appendStepText="Outside of Balmora, east of a blue-flame brazier on the northbound road, ", stepTextKey="I found Ashur and helped him fight off some hostile townsfolk. Now I should talk to him and find out if he can point me in Veya's direction."},
		["Talk to Ashur"] =
			{appendText=", who moved farther to the east, away from the road. He stands near a gigantic mushroom."},
		[7] = 
			{appendStepText="I spoke with an assassin outside of Balmora's northeast gate. He was a short distance east of the road. ", stepTextKey="Ashur suggested that I could find Veya's mentor performing a job at the ruins to the west of Balmora. If I want to track down Veya, that's my best lead so far."},
		["Find Veya's Mentor at the Western Ruins"] =
			{appendText=", beyond the marshes west of Balmora's wayshrine, on the coast. I should follow the torchlit path through the swamp. If Veya's mentor is as ruthless as Ashur implied, I may find a body or two along the way, especially beside the trail as I approach the Daedric ruin."},
		[8] = 
			{appendStepText="On the coast west of the Balmora Wayshrine, ", stepTextKey="Veya's mentor is somewhere inside the Ashurnibibi Ruins. I need to track her down and find her."},
		["Find Veya's Mentor in the Western Ruins"] =
			{appendText="."},
		[9] = 
			{appendStepText="Inside the Ashurnibibi ruin on the coast west of Balmora's wayshrine, I learned that ", stepTextKey="Naryu Virian, a Morag Tong agent, is Veya's mentor. Currently she's working on a writ and will not speak to me until she's done. I should help her finish the job so I can get some answers about Veya's whereabouts."},
		["Help Naryu Complete Her Writ"] =
			{appendText=" by working my way through the caverns and ruins until I reach the northern chamber."},
		[10] = 
			{appendStepText="Inside the Ashurnibibi ruin on the coast west of Balmora's wayshrine, after helping her in the northern chamber, Naryu went through a Daedric door. ", stepTextKey="I should follow Naryu into the inner chamber."},
		["Enter the Inner Chambers"] =
			{appendText=" through the round door to the southwest."},
		[11] = 
			{appendStepText="On the coast west of Balmora's wayshrine, inside Ashurnibibi's Inner Chamber that I entered from the ruin's northernmost chamber, ", stepTextKey="I watched as Naryu Virian killed the Orc cult leader. Now that she's finished, I should talk to her."},
		["Talk to Naryu Virian"] =
			{appendText=", the assassin."},
		[12] = 
			{appendStepText="In the Ashurnibibi ruin west of Balmora, I learned that ", stepTextKey="Veya's safe and under the protection of a Morag Tong agent known as Naryu Virian. Naryu promised to arrange a meeting with Veya if I tell Councilor Eris that his daughter is safe and convince him to stop hiring outsiders."},
		["Talk to Councilor Eris 2"] =
			{appendText=" Releth in Balmora's westside Redoran Kinhouse, south of the temple.", stepTextKey="Veya's safe and under the protection of a Morag Tong agent known as Naryu Virian. Naryu promised to arrange a meeting with Veya if I tell Councilor Eris that his daughter is safe and convince him to stop hiring outsiders."},
		[13] = 
			{appendStepText="", stepTextKey="I returned to Balmora to tell Councilor Eris that his daughter is safe and has joined the Morag Tong. If he promised to stop hiring outsider freelancers, Naryu said she'd arrange for me to meet with Veya."},
		["Talk to Councilor Eris 3"] =
			{appendText=" in the Redoran Kinhouse south of the Balmora Tribunal Temple.", stepTextKey="I returned to Balmora to tell Councilor Eris that his daughter is safe and has joined the Morag Tong. If he promised to stop hiring outsider freelancers, Naryu said she'd arrange for me to meet with Veya."},
	},

	[GetQuestName(5919)] = { --"Of Faith and Family"					--Jordakai
		[1] = 
			{appendStepText="I spoke with Councilor Eris Releth in his Redoran Kinhouse on Balmora's westside. After sharing what I learned, he again requested to meet his daughter. ", stepTextKey="In order to arrange a meeting, I need to talk to Veya. Naryu said she'd contact me, but I should try to find her first."},
		["Find a Way to Contact Veya"] =
			{appendText=". Perhaps I can find Naryu or Ashur in town."},
		[2] = 
			{appendStepText="I found Ashur, or he found me, in Balmora near the Redoran Kinhouse, south of the temple on the town's westside. ", stepTextKey="Ashur, who's also a Morag Tong agent, gave me a map that contains clues to lead me to where Naryu wants to meet. I should puzzle out the clues so I can find Naryu."},
		["Use the Map to Find Naryu"] =
			{appendText=". Ashur said it will help me find a key and another map stashed in town."},
		[3] = 
			{appendStepText="In the alley behind The Randy Netch Inn, ", stepTextKey="I located the Morag Tong safe-house beneath Balmora. Now I just need to talk to Naryu and ask her where Veya is."},
		["Talk to Naryu Virian 1"] =
			{appendText=".", stepTextKey="I located the Morag Tong safe-house beneath Balmora. Now I just need to talk to Naryu and ask her where Veya is."},
		[4] = 
			{appendStepText="I met with Naryu at her safe-house in the alley behind The Randy Netch Inn. ", stepTextKey="To prove to Veya that I can be trusted, Naryu wants me to sneak into Lord Drono's townhouse in Balmora and steal the House Redoran Registry without getting caught by Drono's security."},
		["Steal the Redoran Registry"] =
			{appendText=". His home is probably among the residences on the east side of the river in town. And the registry? I suspect it will be in a private area on the lowest level of his house."},
		[5] = 
			{appendStepText="From Lord Drono's townhouse in Balmora, ", stepTextKey="I acquired the House Redoran Registry. Now to get back to the Morag Tong safe-house and give it to Naryu."},
		["Bring the Registry to Naryu"] =
			{appendText=". She is waiting at the Morag Tong safe-house in the alley behind The Randy Netch Inn."},
		[6] = 
			{appendStepText="", stepTextKey="Naryu says that Veya is hiding in the swamp to the northwest of Balmora. She's supposed to be in a cave, but Naryu said she often wanders around the area. I should keep an eye out for any signs of her as I look for the cave in the swamp."},
		["Go to the Swamp"] =
			{appendText="."},
		[7] = 
			{appendStepText="Northwest of Balmora, ", stepTextKey="I came across Captain Brivan and a group of Khajiiti mercenaries out in the swamp. They also appear to be searching for Veya. I should speak to Brivan to learn what he's doing."},
		["Talk to Captain Brivan"] =
			{appendText=" on a trail in the swamp. He is with a Khajiiti mercenary."},
		[8] = 
			{appendStepText="Northwest of Balmora, I met Captain Brivan and Ferhara, a Khajiiti mercenary. ", stepTextKey="House Redoran and its mercenaries have spotted Veya in the swamp and are searching for her. I need to find Veya before they do."},
		["Search the Swamp for Veya"] =
			{appendText=". The captain said she was seen at the north end of the swamp. The mercenaries already left to find her. He also knew a lot about her brother's exile."},
		[9] = 
			{appendStepText="Northwest of Balmora, in the swamp's north end, I found Councilor Eris' daughter. Veya wants me to meet her at a cave northeast of here. ", stepTextKey="There's a group of Warclaw mercenaries blocking the way to Veya's cave. I need to deal with the mercenaries so Veya can safely get to the cave."},
		["Defeat the Warclaws"] =
			{appendText=" at the swampy area in the curve of the trail by the coast, southwest of Ald'ruhn."},
		[10] = 
			{appendStepText="East of Khartag Point and west of the Ald'ruhn Wayshrine, at a large curve in the coastal trail, there is a rocky rise overlooking the swamp where I defeated the Warclaws. ", stepTextKey="Veya went into the cave. I should head inside and talk to her."},
		["Talk to Veya Inside the Cave"] =
			{appendText=" up in the rocky outcropping. Mallapi Cave's entrance is illuminated by a burning torch."},
		[11] = 
			{appendStepText="Inside Mallapi Cave, east of Khartag Point and west of the Ald'ruhn Wayshrine, ", stepTextKey="Naryu entered the cave and brought a warning. It appears that House Redoran forces are closing in on the cave. I should talk to Naryu and figure out our next move."},
		["Talk to Naryu Virian 2"] =
			{appendText=".", stepTextKey="Naryu entered the cave and brought a warning. It appears that House Redoran forces are closing in on the cave. I should talk to Naryu and figure out our next move."},
		[12] = 
			{appendStepText="Inside Mallapi Cave, east of Khartag Point and west of the Ald'ruhn Wayshrine, Naryu warned us. ", stepTextKey="I need to get Veya out of the cave  using the back tunnels. We may run into some resistance, but Naryu thinks the way will be clearer than going out the front door."},
		["Escape Using the Back Tunnels"] =
			{appendText=" of Mallapi to reach an exit in its eastern cavern."},
		[13] = 
			{appendStepText="We found ourselves up in the rocks southwest of the large bend in the main road north of Balmora, just a short distance northwest of the fork that leads to Ald'ruhn. ", stepTextKey="We escaped from the cave tunnels but there's a small army nearby. I should talk to Veya and see if she has any ideas."},
		["Talk to Veya 1"] =
			{appendText=".", stepTextKey="We escaped from the cave tunnels but there's a small army nearby. I should talk to Veya and see if she has any ideas."},
		[14] = 
			{appendStepText="We are far north of Balmora on the main road, just north of the fork that leads to Ald'ruhn. ", stepTextKey="I should talk to Councilor Eris and distract him and his soldiers so that Veya can slip away and get to the Ashlander camp to the south."},
		["Confront Councilor Eris"] =
			{appendText=". He seems to be a rather impatient Dunmer."},
		[15] = 
			{appendStepText="Far north of Balmora near the main road, just north of the fork that leads to Ald'ruhn, ", stepTextKey="I gave my report to Councilor Eris and asked him to give me a little more time to set up a meeting between him and Veya. Now I should go to the Ashlander camp and rendezvous with Veya."},
		["Go to the Ashlander Camp"] =
			{appendText=", due south of Ald'ruhn Wayshrine. It is in the foothills on the south side of the main road. Veya is likely to be just outside of the camp to the east."},
		[16] = 
			{appendStepText="I found the camp in the foothills, due south of the Ald'ruhn Wayshrine. ", stepTextKey="The Ashlander camp has been overrun by the Warclaw mercenaries, but I met up with Veya and Naryu. I should talk to Veya and see if she knows what's going on here."},
		["Talk to Veya 2"] =
			{appendText=", who is with Naryu on a hillside east of the camp and south of a junction in the road.", stepTextKey="The Ashlander camp has been overrun by the Warclaw mercenaries, but I met up with Veya and Naryu. I should talk to Veya and see if she knows what's going on here."},
		[17] = 
			{appendStepText="", stepTextKey="Veya asked me to search the Ashlander camp. Maybe I can find out what happened to the Ashlanders and her brother."},
		["Search the Ashlander Camp"] =
			{appendText=", due south of the Ald'ruhn Wayshrine, in the foothills near the junction in the road. I expect the Warclaws will be less than happy to see me."},
		[18] = 
			{appendStepText="In the Aahlander camp due south of the Ald'ruhn Wayshrine, I dealt with some Warclaws and searched the camp. ", stepTextKey="The Wise Woman explained that many of the Ashlanders were locked in the Kudanat Mine. I can acquire a key from Warclaw Irgazzar or from the supply yurt."},
		["Find the Mine Key"] =
			{appendText=" for the Kudanat Mine."},
		[19] = 
			{appendStepText="In the Ashlander camp at the junction in the road due south of the Ald'ruhn Wayshrine, ", stepTextKey="I acquired the key to the Kudanat Mine. Now to get inside and see what happened to the Ashlanders and Veya's brother Ulran."},
		["Enter Kudanat Mine"] =
			{appendText=" at the south end of the camp near the Wise Woman's yurt."},
		[20] = 
			{appendStepText="Kudanat Mine is at the south end of the Ashlander camp, near the junction in the road due south of the Ald'ruhn Wayshrine. ", stepTextKey="Now that I'm inside the mine, I should look around and try to find the Ashlander prisoners or Veya's brother Ulran."},
		["Search the Kudanat Mine"] =
			{appendText="."},
		[21] = 
			{appendStepText="South of Ald'ruhn Wayshine near the Ashlander camp is the Kudanat Mine. I entered the mine after defeating more Warclaws. ", stepTextKey="The Warclaws massacred these Ashlanders and they killed Veya's brother Ulran. I need to talk to Naryu and see if she can make sense of all this."},
		["Talk to Naryu Virian 3"] =
			{appendText=". I should tell her about the speaking stone I found with Ulran.", stepTextKey="The Warclaws massacred these Ashlanders and they killed Veya's brother Ulran. I need to talk to Naryu and see if she can make sense of all this."},
		[22] = 
			{appendStepText="Within Kudunat Mine at the Ashlander camp south of the Ald'ruhn Wayshine, ", stepTextKey="Naryu activated the speaking stone I found on Ulran's body. I should pay attention and see what kind of message he left for us."},
		["Listen to the Speaking Stone"] =
			{appendText=" of Ulran Releth."},
		[23] = 
			{appendStepText="In the mine at the Ashlander camp south of Ald'ruhn, Naryu activated the speaking stone. ", stepTextKey="Ulran thinks he was set up to be exiled. His message indicated that someone sent the Ashlanders to Balmora under false pretenses, and that Ulran was summoned specifically to deal with the situation."},
		["Talk to Naryu Virian 4"] =
			{appendText=" and Veya within Kudanat Mine.", stepTextKey="Ulran thinks he was set up to be exiled. His message indicated that someone sent the Ashlanders to Balmora under false pretenses, and that Ulran was summoned specifically to deal with the situation."},
		[24] = 
			{appendStepText="", stepTextKey="Ulran's dead. It appears that his loss of rank, exile, and subsequent murder were set up by some enemy—perhaps even someone inside House Redoran. I should return to Balmora and tell Councilor Eris what I discovered."},
		["Talk to Councilor Eris 1"] =
			{appendText=" Releth at his westside Redoran Kinhouse.", stepTextKey="Ulran's dead. It appears that his loss of rank, exile, and subsequent murder were set up by some enemy—perhaps even someone inside House Redoran. I should return to Balmora and tell Councilor Eris what I discovered."},
		[25] = 
			{appendStepText="At his Redoran Kinhouse, south of the temple in Balmora, ", stepTextKey="I told Councilor Eris about the fate of his son. Now he has another task for me to do. I should talk to him and get the details."},
		["Talk to Councilor Eris 2"] =
			{appendText=".", stepTextKey="I told Councilor Eris about the fate of his son. Now he has another task for me to do. I should talk to him and get the details."},
	},

	[GetQuestName(5933)] = { --"A Purposeful Writ"					--Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Naryu had to deal with a Morag Tong assignment and left Ashur to watch over Veya. He was having some trouble with her and asked me to go and talk to her. She should be in the safe-house beneath Balmora."},
		["Talk to Veya 1"] =
			{appendText=" at the Morag Tong's cellar in the alley behind The Randy Netch Inn.", stepTextKey="Naryu had to deal with a Morag Tong assignment and left Ashur to watch over Veya. He was having some trouble with her and asked me to go and talk to her. She should be in the safe-house beneath Balmora."},
		[2] = 
			{appendStepText="In the Balmora Morag Tong safe-house, ", stepTextKey="Veya asked me to meet Naryu at Aremin Manor and see if I could find out what the councilor knows about her brother before Naryu carries out her writ. The manor is located in the swamp near the cave where Veya was hiding."},
		["Go to Arenim Manor"] =
			{appendText=", northwest of Balmora on a small island on the western seacoast. It probably has a bridge or a dock.\n\nSince Naryu has a job there, I suspect she is surveying the site before entering. Looking at my map, a good viewpoint may be southeast of the manor's island, near a Dwemer ruin."},
		[3] = 
			{appendStepText="On the north side of the Dwemer ruin of Aleft, southeast of the manor, ", stepTextKey="I found Naryu outside the Arenim Manor. I should talk to her and see if she'll let me look for information pertaining to Ulran's exile while she executes her writ."},
		["Talk to Naryu Virian 1"] =
			{appendText=".", stepTextKey="I found Naryu outside the Arenim Manor. I should talk to her and see if she'll let me look for information pertaining to Ulran's exile while she executes her writ."},
		[4] = 
			{appendStepText="On the north side of the Dwemer ruin of Aleft, southeast of the manor, we came up with a plan. ", stepTextKey="Naryu and I need to find a way to get into the manor. Then I can look for information regarding Ulran's exile and she can execute her writ against Councilor Dolvara."},
		["Find a Way Into the Manor"] =
			{appendText=". I should avoid Redoran soldiers to make this easier for Naryu."},
		[5] = 
			{appendStepText="We found a way into the manor on the island northwest of the Dwemer ruin of Aleft. ", stepTextKey="Now that Naryu and I have entered Arenim Manor, I need to see if I can find any information pertaining to Ulran's exile while Naryu locates Councilor Dolvara and executes her writ."},
		["Search Arenim Manor"] =
			{appendText="."},
		[6] = 
			{appendStepText="Northwest of Aleft, we searched the main level of Arenim Manor before heading upstairs and out to its balcony. ", stepTextKey="We learned a few things about House Redoran during our investigation of Arenim Manor, but the most significant detail might be that Councilor Dolvara participated in Ulran's trial. I should discuss this with Naryu."},
		["Talk to Naryu Virian 2"] =
			{appendText=".", stepTextKey="We learned a few things about House Redoran during our investigation of Arenim Manor, but the most significant detail might be that Councilor Dolvara participated in Ulran's trial. I should discuss this with Naryu."},
		[7] = 
			{appendStepText="Inside Arenim Manor, northwest of Aleft, ", stepTextKey="Naryu has agreed to allow me to question Councilor Dolvara about Ulran before she executes her writ."},
		["Confront Councilor Dolvara"] =
			{appendText=" in her private quarters on the upper floor."},
		[8] = 
			{appendStepText="Northwest of Aleft, inside her private quarters on Arenim Manor's upper floor, ", stepTextKey="Councilor Dolvara shed some light on Ulran's banishment before Naryu carried out her execution. I should take a quick look around the chamber and see if there's any other relevant information."},
		["Search the Councilor's Quarters"] =
			{appendText="."},
		[9] = 
			{appendStepText="Northwest of Aleft, inside Arenim Manor, ", stepTextKey="I should discuss what we learned in Councilor Dolvara's quarters with Naryu."},
		["Talk to Naryu Virian 3"] =
			{appendText=" before we leave the private quarters.", stepTextKey="I should discuss what we learned in Councilor Dolvara's quarters with Naryu."},
		[10] = 
			{appendStepText="", stepTextKey="It seems that Captain Brivan may have played a role in Ulran's banishment and possibly even his death. I might be able to learn more from the soldiers scouting the old fort near Balmora, but first I need to return to Veya and bring her up to speed."},
		["Talk to Veya 2"] =
			{appendText=". She should be at the safe-house in the alley behind The Randy Netch Inn in Balmora.", stepTextKey="It seems that Captain Brivan may have played a role in Ulran's banishment and possibly even his death. I might be able to learn more from the soldiers scouting the old fort near Balmora, but first I need to return to Veya and bring her up to speed."},
		[11] = 
			{appendStepText="Inside the abandoned cellar behind The Randy Netch Inn in Balmora, ", stepTextKey="I told Veya about the soldiers scouting the old fort. I should also let her know that Captain Brivan may have had a role in everything that happened to Ulran before we make our way to the fort."},
		["Talk to Veya 3"] =
			{appendText=".", stepTextKey="I told Veya about the soldiers scouting the old fort. I should also let her know that Captain Brivan may have had a role in everything that happened to Ulran before we make our way to the fort."},
	},

	[GetQuestName(5948)] = { --"Family Reunion"					--Jordakai
		[1] = 
			{appendStepText="In Balmora'a Morag Tong safe-house behind The Randy Netch, Veya and I discussed what has been learned. ", stepTextKey="Veya believes time is of the essence, so we aren't going to wait for Naryu to return. I'll meet Veya at the old fort and then we'll try to find the Redoran soldiers."},
		["Meet Veya Near the Hlormaren Stronghold"] =
			{appendText=", an ancient Velothi fortress built of stone blocks. It is near the western trail in the swamp west of Balmora. She wants to meet me in the swampland, a short distance south of the structure."},
		[2] = 
			{appendStepText="In the swamp west of Balmora, I found Veya south of the old fortress. ", stepTextKey="The Redoran soldiers sent to scout the old stronghold must be around here somewhere. We need to find them before they run into the cultists that occupy Hlormaren."},
		["Search for the Redoran Soldiers"] =
			{appendText=". We should start looking for a small camp or some sign of them just east of the trail, barely south of the stronghold, perhaps near a small ruin. Then we can head towards the fortress, searching the grounds and exterior before entering it."},
		[3] = 
			{appendStepText="We spotted cultists at Hlormaren Stronghold on the swamp trail west of Balmora. ", stepTextKey="After a search of the exterior, we found signs of the Redoran soldiers and a dead scout, but not Vatola or the rest of his squad. Veya thinks they may be inside the ancient stronghold. We need to find a way to get inside."},
		["Enter the Hlormaren Stronghold"] =
			{appendText=", the ancient Velothi fortress, using the key I got from a cultist."},
		[4] = 
			{appendStepText="", stepTextKey="We entered the ancient stronghold. Now we just need to find the Redoran soldiers."},
		["Find the Redoran Soldiers"] =
			{appendText=" inside Hlormaren, the Velothi fortress west of Balmora on the swamp trail."},
		[5] = 
			{appendStepText="We entered the old stronghold on the swamp trail west of Balmora. ", stepTextKey="We found Vatola Telem and what's left of his squad locked up inside Hlormaren stronghold. I should talk to him and find out what's going on here."},
		["Talk to Vatola Telem 1"] =
			{appendText=" in the cage.", stepTextKey="We found Vatola Telem and what's left of his squad locked up inside Hlormaren stronghold. I should talk to him and find out what's going on here."},
		[6] = 
			{appendStepText="West of Balmora on the swamp trail, we entered the Velothi fortress of Hlormaren Stronghold. We found Vatola, one of the missing Redoran soldiers, in a cage. But ", stepTextKey="Vatola won't talk to us until we set him and his soldiers free. I need to find the key that opens the cells on one of the cultists."},
		["Get the Cell Key"] =
			{appendText=" for Vatola’s cage."},
		[7] = 
			{appendStepText="Inside the Hlormaren Stronghold west of Balmora, I found the key. ", stepTextKey="It sounds like there's some kind of trouble back at the prisoner cells. Now that I have the key that opens the cells, I should get back there as quickly as possible."},
		["Talk to Vatola Telem 2"] =
			{appendText=" in the cage.", stepTextKey="It sounds like there's some kind of trouble back at the prisoner cells. Now that I have the key that opens the cells, I should get back there as quickly as possible."},
		[8] = 
			{appendStepText="", stepTextKey="According to Vatola, Captain Brivan issued the orders that got Ulran exiled and led to his death at the Ashlander camp. I think Veya is going to Balmora to kill him. I need to reach her before she does something she'll regret."},
		["Find Veya in Balmora"] =
			{appendText="."},
		[9] = 
			{appendStepText="As soon as I arrived in Balmora, Naryu came to me. ", stepTextKey="Naryu thinks Veya got into the Redoran Kinhouse to find Captain Brivan. She wants me to investigate, find out what happened, and see if I can locate Veya. Meanwhile, she's going to search the streets, just in case."},
		["Investigate the Redoran Kinhouse"] =
			{appendText=" on the city's west side. It is south of the Balmora Tribunal Temple."},
		[10] = 
			{appendStepText="", stepTextKey="I need to let Naryu know that Veya's going after Captain Brivan at the Redoran council meeting taking place at the garrison outside of Balmora."},
		["Talk to Naryu Virian 1"] =
			{appendText=", waiting in the street below the kinhouse on the city's west side, south of the Balmora Tribunal Temple.", stepTextKey="I need to let Naryu know that Veya's going after Captain Brivan at the Redoran council meeting taking place at the garrison outside of Balmora."},
		[11] = 
			{appendStepText="I spoke with Naryu in the street south of the Balmora Tribunal Temple. I let her know where Veya went. ", stepTextKey="Naryu wants to stop Veya before she reaches Captain Brivan. I need to rendezvous with her at the Redoran garrison that's north of Balmora."},
		["Meet Naryu at the Redoran Garrison"] =
			{appendText=" the Captain's wife mentioned. The Morag Tong assassin will likely be surveying the site from a short distance away, probably south of the garrison's entrance. The garrison is on the road, north of Balmora."},
		[12] = 
			{appendStepText="North of Balmora, we noticed the Warclaws at the garrison. ", stepTextKey="We need to get inside the Redoran garrison so we can find Captain Brivan before Veya reaches him and does something we'll all regret."},
		["Enter the Redoran Garrison"] =
			{appendText=". Fighting Warclaws should be easier to explain than dealing with Redoran soldiers."},
		[13] = 
			{appendStepText="We entered the Redoran garrison on the road north of Balmora. ", stepTextKey="We need to search the garrison and locate Captain Brivan before Veya reaches him."},
		["Find Captain Brivan"] =
			{appendText=" in the garrison. I should speak with Naryu while we look. And keep my eyes open for anything that may help, too."},
		[14] = 
			{appendStepText="Inside Redoran garrison, north of Balmora, I found the wine cellar downstairs. In its northwestern area, ", stepTextKey="I finished dealing with Ferhara and her Warclaws just as Captain Brivan walked in. I need to tell him what's going on before Veya arrives."},
		["Talk to Captain Brivan"] =
			{appendText="."},
		[15] = 
			{appendStepText="North of Balmora, inside the Redoran garrison's lower halls, I was speaking with the Captain when Veya appeared. ", stepTextKey="Veya killed Captain Brivan and learned that her father was behind the test that exiled Ulran and ultimately led to his death. She's going after Eris and the other councilors now. I need to tell Naryu what happened."},
		["Talk to Naryu Virian 2"] =
			{appendText=".", stepTextKey="Veya killed Captain Brivan and learned that her father was behind the test that exiled Ulran and ultimately led to his death. She's going after Eris and the other councilors now. I need to tell Naryu what happened."},
		[16] = 
			{appendStepText="The Redoran garrision north of Balmora is no longer a safe place. ", stepTextKey="We have to stop Veya before she kills her father and the rest of the Redoran council currently meeting here in the garrison."},
		["Stop Veya 1"] =
			{appendText=". She locked the door to the Redoran Inner Halls on this lower floor, so we must find another way to reach her. We need to get to the north end of the garrison's main level where the councilors are meeting.", stepTextKey="We have to stop Veya before she kills her father and the rest of the Redoran council currently meeting here in the garrison."},
		[17] = 
			{appendStepText="North of Balmora at the Redoran garrison's northernmost chamber we struggled to get through a locked gate. ", stepTextKey="We weren't able to stop Veya from killing her father. Now she's going after the rest of the Redoran councilors to avenge her brother. Naryu is determined to stop her and I agreed to help."},
		["Stop Veya 2"] =
			{appendText=" before more councilors die.", stepTextKey="We weren't able to stop Veya from killing her father. Now she's going after the rest of the Redoran councilors to avenge her brother. Naryu is determined to stop her and I agreed to help."},
		[18] = 
			{appendStepText="At the Redoran garrison, north of Balmora, we confronted Veya. ", stepTextKey="Veya has been defeated and now the Redoran High Councilor wants to talk. I should find out what she wants."},
		["Talk to High Councilor Meriath"] =
			{appendText=" here, in the garrison's northernmost chamber."},
		[19] = 
			{appendStepText="North of Balmora, in the Redoran garrison's northern chamber, I spoke with High Councilor Meriath. ", stepTextKey="The High Councilor offered to sweep everything under the rug provided we go along with her story. I need to talk to Naryu and see what she thinks about this."},
		["Talk to Naryu"] =
			{appendText=", standing near the bodies of Veya and her father."},
		[20] = 
			{appendStepText="", stepTextKey="We decided that Veya had to die. Naryu will finish the task. I need to return to the Morag Tong safe-house in Balmora and see if Naryu needs my assistance with anything else."},
		["Return to the Morag Tong Safe-House 1"] =
			{appendText=" behind The Randy Netch Inn.", stepTextKey="We decided that Veya had to die. Naryu will finish the task. I need to return to the Morag Tong safe-house in Balmora and see if Naryu needs my assistance with anything else."},
		[21] = 
			{appendStepText="In the Balmora safe-house behind The Randy Netch Inn, ", stepTextKey="Naryu seems to be taking Veya's death hard. I wonder if there's anything I can say to make her feel any better. I should talk to her one more time before I take my leave."},
		["Talk to Naryu Virian 3"] =
			{appendText=" as she sits and drinks.", stepTextKey="Naryu seems to be taking Veya's death hard. I wonder if there's anything I can say to make her feel any better. I should talk to her one more time before I take my leave."},
		[22] = 
			{appendStepText="", stepTextKey="We decided to give Veya a second chance and let her live. I should meet Naryu and Veya at the Morag Tong safe-house in Balmora and see if they need any additional assistance."},
		["Return to the Morag Tong Safe-House 2"] =
			{appendText=" in the alley behind The Randy Netch Inn.", stepTextKey="We decided to give Veya a second chance and let her live. I should meet Naryu and Veya at the Morag Tong safe-house in Balmora and see if they need any additional assistance."},
		[23] = 
			{appendStepText="In the Balmora safe-house behind The Randy Netch Inn, Ashur is healing Veya. ", stepTextKey="Naryu plans to send Veya away, somewhere where she can start over. I should talk to her one last time before I leave."},
		["Talk to Naryu Virian 4"] =
			{appendText=".", stepTextKey="Naryu plans to send Veya away, somewhere where she can start over. I should talk to her one last time before I leave."},
	},

	[GetQuestName(5799)] = { --"A Hireling of House Telvanni"					--Jordakai
		[1] = 
			{appendStepText="I met Eoki, a male Argonian slave in the eastern city of Sadrith Mora, and agreed to help him. ", stepTextKey="I should go talk to Eoki's love, Sun-in-Shadow. I'll likely find her working in Tel Naga."},
		["Talk to Sun-in-Shadow 1"] =
			{appendText=", a female Argonian, inside the city's central mushroom tower.", stepTextKey="I should go talk to Eoki's love, Sun-in-Shadow. I'll likely find her working in Tel Naga."},
		[2] = 
			{appendStepText="Within Sadrith Mora's Tel Naga, I spoke with Eoki's friend. ", stepTextKey="Sun-in-Shadow believes that Magister Therana's Mouth, Eraven Onthim, possesses a letter that could reveal what Therana is looking for in Zaintiraris. I should search his chambers in the Council House for the letter."},
		["Find Eraven Onthim's Chambers"] =
			{appendText=" on the main floor of the city's smaller, northern mushroom tower."},
		[3] = 
			{appendStepText="Eraven Onthim's chambers were off the main entry hall of Sadrith Mora's northern tower. ", stepTextKey="The Tel Branora Mouth is not in his chambers, but one of his assistants is. I should speak to Brelan Neloren."},
		["Talk to Brelan"] =
			{appendText="."},
		[4] = 
			{appendStepText="In Eraven Onthim's chambers off the main entry hall of Sadrith Mora's northern Council House tower, I spoke with Brelan Neloren. ", stepTextKey="Brelan, Eraven's secretary, agreed to give me the information Sun-in-Shadow needs if I do him a favor first. I need to retrieve a bad poem he gave to another mage, so he can avoid embarrassment."},
		["Pickpocket the \"Ode to Ethrandora\""] =
			{appendText=" that Brelan wrote to her. A Bosmer, she should be in the Wizard's Study nearby."},
		[5] = 
			{appendStepText="Ethrandora was in the Wizard's Study off the main floor of Sadrith Mora's Council House tower. ", stepTextKey="I have the poem, now I just need Magister Therana's note about Zaintiraris. I should return to Brelan."},
		["Return the Poem to Brelan"] =
			{appendText=" in Eraven Onthim's Chanbers nearby. He should be very grateful to get this back."},
		[6] = 
			{appendStepText="Inside Eraven Onthim's chambers in Sadrith Mora's Council House, ", stepTextKey="I worked out a deal with Brelan, and having held up my end, he has obligingly unlocked the correspondence box and is turning a blind eye to my taking the needed information."},
		["Take Magister Therana's Correspondence"] =
			{appendText=" from the box on the desk."},
		[7] = 
			{appendStepText="In Sadrith Mora's Council House, ", stepTextKey="I found out what Magister Therana seeks in the Daedric shrine, Zaintiraris. I should return to Sun-in-Shadow to plan our next move."},
		["Talk to Sun-in-Shadow 2"] =
			{appendText=" on the main floor inside Tel Naga, the city’s central tower.", stepTextKey="I found out what Magister Therana seeks in the Daedric shrine, Zaintiraris. I should return to Sun-in-Shadow to plan our next move."},
		[8] = 
			{appendStepText="According to the letter I have, a relic, a finger bone of St. Felms, is rumored to be in the ruin. ", stepTextKey="I need to make my way to the Daedric shrine, Zaintiraris."},
		["Travel to Zaintiraris"] =
			{appendText=", south of Molag Mar. I kept Eraven's letter about the relic."},
		[9] = 
			{appendStepText="I found the Daedric shrine south of Molag Mar. ", stepTextKey="A complex puzzle-ward blocks the entrance to Zaintiraris. I should search the grounds to find some way to unlock the door."},
		["Enter Zaintiraris"] =
			{appendText=". The letter I have talks about skulls. They must be near the shrine's entry."},
		[10] = 
			{appendStepText="In the Daedric ruins south of Molag Mar, ", stepTextKey="I gained access to Zaintiraris shrine. I need to find a way into the shrine's central chamber. The relic is most likely there."},
		["Find a Way to Access the Central Chamber"] =
			{appendText=". I should search for clues on how to get into that chamber."},
		[11] = 
			{appendStepText="In the Daedric ruins south of Molag Mar, ", stepTextKey="I found a key that will unlock the central chamber in Zaintiraris shrine. The finger bone of Saint Felms should be found in that area."},
		["Find the Finger Bone of Saint Felms"] =
			{appendText=". With the peculiar key I found, I can unlock the door on the south side of the central chamber and continue my search."},
		[12] = 
			{appendStepText="South of Molag Mar, ", stepTextKey="I retrieved Saint Felms's finger bone from Zaintiraris. I should take it to Magister Therana at Tel Branora."},
		["Take the Relic to Tel Branora"] =
			{appendText=", a newer Telvanni mushroom tower, far to the south of Molag Mar on a small island."},
		[13] = 
			{appendStepText="I found Tel Branora and its wayshrine on its southern island. Now, ", stepTextKey="I need to convince Magister Therana to support Sun-in-Shadow's appeal for emancipation."},
		["Talk to Therana about Sun-in-Shadow"] =
			{appendText=". The magister is probably in her chambers, up from the main entrance."},
		[14] = 
			{appendStepText="In her Tel Branora chambers, ", stepTextKey="Magister Therana has agreed to provide a Writ of Sponsorship for Sun-in-Shadow."},
		["Take the Writ of Sponsorship"] =
			{appendText=" from the desk."},
		[15] = 
			{appendStepText="In Tel Branora, ", stepTextKey="Magister Therana provided a document that supports Sun-in-Shadow's bid for emancipation, and encourages the Council to bestow upon her the rank of House Hireling. I must take it to Therana's Mouth, Eraven Onthim."},
		["Deliver the Writ to Eraven Onthim"] =
			{appendText=" in his chambers at the Council House in the eastern city of Sadrith Mora."},
		[16] = 
			{appendStepText="In Sadrith Mora's Council House, ", stepTextKey="Eraven will have Sun-in-Shadow called before the council. I can go up to the Council Hall to witness her change in status."},
		["Meet Sun-in-Shadow in the Council Chamber"] =
			{appendText=". The audience chamber is up from the main floor."},
		[17] = 
			{appendStepText="", stepTextKey="A council emissary called Sun-in-Shadow to the council audience chamber. I should speak to her before she faces the Telvanni Council."},
		["Talk To Sun-in-Shadow in the Audience Chamber"] =
			{appendText=" in the upper level of Sadrith Mora’s Council House."},
		[18] = 
			{appendStepText="In the upper level of Sadrith Mora's Council House, I am with Sun-in-Shadow.  ", stepTextKey="The Telvanni Council is preparing to free Sun-in-Shadow. I should speak to her before the council makes their pronouncement."},
		["Talk to Sun-in-Shadow in the Council House"] =
			{appendText="."},
	},

	[GetQuestName(5859)] = { --"Rising to Retainer"					--Jordakai
		[1] = 
			{appendStepText="In Vvardenfell's eastern city of Sadrith Mora, ", stepTextKey="I should find Sun-in-Shadow's new home and talk to her about her plans to rise further in the ranks of House Telvanni."},
		["Talk to Sun-in-Shadow in Private"] =
			{appendText=" at her southeastern house."},
		[2] = 
			{appendStepText="I spoke with Sun-in-Shadow at her new home in the eastern city of Sadrith Mora. She learned that Master Firuth wants to buy some land. Now, ", stepTextKey="I must travel to Vos and find someone who is willing to sell their land."},
		["Find Someone Willing to Sell Land Near Vos"] =
			{appendText=", a northeastern town near Magister Dratha's mushroom tower, Tel Mora.\n\nEoki is probably working on a farm southwest of Sadrith Mora, near a small dock."},
		[3] = 
			{appendStepText="I learned more about land for sale in the northeastern town of Vos. ", stepTextKey="Apparently, a farmer named Barys Rendo may be willing to sell his plot. I should talk to him."},
		["Talk to Barys Rendo 1"] =
			{appendText=" on his property north of town.", stepTextKey="Apparently, a farmer named Barys Rendo may be willing to sell his plot. I should talk to him."},
		[4] = 
			{appendStepText="I found the farm north of Vos. ", stepTextKey="The farmer, Barys Rendo, agreed to sell me his land, but not before I find his son, Seythen. According to Barys, Seythen probably lost his way inside the Daedric ruin, Esutanamus. I should go to the ruin to look for him."},
		["Go to Esutanamus Shrine"] =
			{appendText=", on an island southeast of Vos."},
		[5] = 
			{appendStepText="Southeast of Vos, ", stepTextKey="I found Esutanamus. I must find Seythen and urge him to return to the Rendo family farm."},
		["Find Seythen Rendo"] =
			{appendText=" somewhere in the Daedric ruin."},
		[6] = 
			{appendStepText="In the Daedric ruins southeast of Vos, ", stepTextKey="I rescued Seythen Rendo from a roost of troublesome winged twilights. He ran on ahead, toward Vos. I should catch up to him and make sure he makes it home."},
		["Meet Seythen Rendo"] =
			{appendText=" south of town and east of the Tel Mora Wayshrine."},
		[7] = 
			{appendStepText="South of Vos in a rocky area east of the wayshrine, ", stepTextKey="Barys was out looking for his son and met up with him. I should talk to him and settle the purchase the Rendo farm plot."},
		["Talk to Barys Rendo 2"] =
			{appendText=" after he finishes speaking with his son.", stepTextKey="Barys was out looking for his son and met up with him. I should talk to him and settle the purchase the Rendo farm plot."},
		[8] = 
			{appendStepText="", stepTextKey="Someone named Mertis purchased the deed to Barys Rendo's property before I returned from Esutanamus. I should track this imposter down."},
		["Track Down Mertis Othren"] =
			{appendText=". Berys said he was going to Vos, but I suspect he would avoid being seen by townsfolk. He's probably on the road west of town."},
		[9] = 
			{appendStepText="West of Vos at a small campsite, a portal closed just as I found Mertis. ", stepTextKey="It seems that a wizard named Jinrisa engineered the plot to steal the deed from me. I should tell Sun-in-Shadow that Jinrisa acquired the Rendo's farm."},
		["Talk to Sun-in-Shadow 1"] =
			{appendText=" at her house in southeastern Sadrith Mora.", stepTextKey="It seems that a wizard named Jinrisa engineered the plot to steal the deed from me. I should tell Sun-in-Shadow that Jinrisa acquired the Rendo's farm."},
		[10] = 
			{appendStepText="Back in Sadrith Mora, now ", stepTextKey="I must find a way to retrieve the land deed from Jinrisa. According to Sun-in-Shadow, Jinrisa probably hid the document in the Tel Naga Adept's Hall."},
		["Get the Deed From Jinrisa"] =
			{appendText=". It is probably in a dresser or nightstand."},
		[11] = 
			{appendStepText="In Sadrith Mora's Tel Naga Adept's Hall, ", stepTextKey="I retrieved the deed. I should give it to Sun-in-Shadow."},
		["Talk to Sun-in-Shadow 2"] =
			{appendText=" outside of Tel Naga, near the wayshrine.", stepTextKey="I retrieved the deed. I should give it to Sun-in-Shadow."},
		[12] = 
			{appendStepText="We spoke in Sadrith Mora, near the wayshrine. ", stepTextKey="Sun-in-Shadow urged me to deliver the deed to Magister Firuth on her behalf. Hopefully he'll furnish me with a writ of endorsement, encouraging the council to elevate Sun-in-Shadow to Retainer."},
		["Deliver the Deed to Master Firuth"] =
			{appendText=". An eccentric Telvanni who prizes his privacy, I should find him at Hanud Tower. It is northwest of Sadrith Mora, about halfway to Vos."},
		[13] = 
			{appendStepText="At the ruin near Hanud Tower, northwest of Sadrith Mora and Tel Aruhn, ", stepTextKey="Firuth completed Sun-in-Shadow's writ of endorsement. I should take it."},
		["Take Firuth's Writ"] =
			{appendText=" of Endorsement from the table."},
		[14] = 
			{appendStepText="At the Velothi ruin near Hanud Tower, ", stepTextKey="Master Firuth agreed to Sun-in-Shadow's terms and gave me a writ of endorsement in exchange for the land deed. I should take the writ to Sun-in-Shadow."},
		["Deliver the Writ to Sun-in-Shadow"] =
			{appendText=". She said I should meet her at Sadrith Mora's Council House, the city's northern mushroom tower."},
		[15] = 
			{appendStepText="", stepTextKey="I should deliver Firuth's writ of endorsement to Sun-in-Shadow."},
		["Talk to Sun-in-Shadow 3"] =
			{appendText=" at the Council House, Sadrith Mora's northern mushroom tower.", stepTextKey="I should deliver Firuth's writ of endorsement to Sun-in-Shadow."},
	},

	[GetQuestName(5901)] = { --"Objections and Obstacles"					--Jordakai
		[1] = 
			{appendStepText="In the eastern city of Sadrith Mora, ", stepTextKey="I should visit Sun-in-Shadow in her residence. She'll likely need my help to reach the next rank in House Telvanni."},
		["Talk to Sun-in-Shadow 1"] =
			{appendText=" at her home, south of the city's Gateway Inn.", stepTextKey="I should visit Sun-in-Shadow in her residence. She'll likely need my help to reach the next rank in House Telvanni."},
		[2] = 
			{appendStepText="I spoke with Sun-in-Shadow in Sadrith Mora. ", stepTextKey="The Telvanni Council called Sun-in-Shadow to a meeting, but she suspects a plot. She asked me to go in her stead as a show of strength. I should make my way to the Council Hall."},
		["Go Before the Council"] =
			{appendText=" in the Audience Chamber on the upper level of the city's northern mushroom tower, the Council House."},
		[3] = 
			{appendStepText="I entered the Audience Chamber of the Council House in northern Sadrith Mora. ", stepTextKey="Before I could even speak on behalf of Sun-in-Shadow, it seemed that a decision had already been reached to reject the request for additional rank. I should speak to Angharal Suth, the lead councilor."},
		["Talk to Angharal"] =
			{appendText=" on the floor of the chamber."},
		[4] = 
			{appendStepText="", stepTextKey="The Council rejected Sun-in-Shadow's petition for advancement. One of the Council Mouths, Ralasa Delvi, seemed pleased with the verdict. I should inform Sun-in-Shadow of the Council's decision."},
		["Report Back to Sun-in-Shadow"] =
			{appendText=" inside the Council House in northern Sadrith Mora, after I speak with Ralasa Delvi."},
		[5] = 
			{appendStepText="In speaking with her in the Council House in northern Sadrith Mora, ", stepTextKey="Sun-in-Shadow has a hunch that Ralasa Delvi may be refusing her petition without Gothren's consent. I'll have to talk to Magister Gothren to find out if Sun-in-Shadow's suspicions are true. I'll find him in Tel Aruhn."},
		["Travel to Tel Aruhn"] =
			{appendText=", a Telvanni tower west of Sadrith Mora."},
		[6] = 
			{appendStepText="", stepTextKey="A guard blocks the door to Tel Aruhn. I should speak with her."},
		["Gain an Audience with Magister Gothren"] =
			{appendText="."},
		[7] = 
			{appendStepText="", stepTextKey="I managed to convince the guard to let me into Tel Aruhn. I should make my way to Magister Gothren's chambers."},
		["Enter Tel Aruhn 1"] =
			{appendText="", stepTextKey="I managed to convince the guard to let me into Tel Aruhn. I should make my way to Magister Gothren's chambers."},
		[8] = 
			{appendStepText="Inside Tel Aruhn, ", stepTextKey="I must find Magister Gothren and speak to him on Sun-in-Shadow's behalf. Hopefully he can clear up this unfortunate business with his Mouth, Ralasa Delvi."},
		["Talk to Magister Gothren"] =
			{appendText=", who is probably in an upper chamber."},
		[9] = 
			{appendStepText="In Tel Aruhn's upper audience chamber, ", stepTextKey="I found Magister Gothren, but he stormed out before we had a chance to speak. He seemed intent on berating one of his minions, Arith Sendrul. I should speak with this servant. Maybe he can provide some insight on what to do next."},
		["Talk to Arith Sendrul"] =
			{appendText="."},
		[10] = 
			{appendStepText="In Tel Aruhn, one of Magister Gothren's servants spoke with me. ", stepTextKey="Arith Sendrul told me that returning Magister Gothren's stolen goods might earn me an audience and should result in Ralasa's downfall. I must travel to Shashpilamat to look for Gothren's property."},
		["Travel to Shashpilamat"] =
			{appendText=", a large Daedric ruin infested with bandits. It is far to the south of Sadrith Mora and northeast of Molag Mar's wayshrine. \n\nPerhaps I should speak with Captain Giravel in the entrance hall before leaving Tel Aruhn."},
		[11] = 
			{appendStepText="Northeast of Molag Mar and southwest of an old monastary, ", stepTextKey="I've arrived in Shashpilamat. Now I need to find Magister Gothren's stolen goods and missing slaves."},
		["Explore Shashpilamat"] =
			{appendText="."},
		[12] = 
			{appendStepText="At the large ruin of Shashpilamat, northeast of Molag Mar and southwest of Holamayan Monastery, ", stepTextKey="I found the \"stolen goods.\" Most of it was escaping Khajiit slaves who had paid the bandits to help them get away from Telvanni lands."},
		["Talk to the Escaping Khajiit"] =
			{appendText="."},
		[13] = 
			{appendStepText="At the large ruin of Shashpilamat, northeast of Molag Mar and southwest of Holamayan Monastery I found slaves and some stolen goods. ", stepTextKey="Seems like Ralasa Delvi was a step ahead of Sun-in-Shadow. Her guard captain had his men retrieve the stolen goods and take the escaping slaves back to Tel Aruhn."},
		["Confront Captain Giravel"] =
			{appendText="."},
		[14] = 
			{appendStepText="", stepTextKey="Ralasa Delvi confounded Arith's plan and used me to capture Gothren's lost slaves. I should return to Sun-in-Shadow to plan our next move."},
		["Talk to Sun-in-Shadow 2"] =
			{appendText=" in her home south of Sadrith Mora's Gateway Inn.", stepTextKey="Ralasa Delvi confounded Arith's plan and used me to capture Gothren's lost slaves. I should return to Sun-in-Shadow to plan our next move."},
		[15] = 
			{appendStepText="When she proposed it at her home, ", stepTextKey="I refused to murder Ralsa Delvi. Sun-in-Shadow suggested bribery as an alternative. I should deliver the marshmerrow cakes to Ralasa, on behalf of Sun-in-Shadow."},
		["Deliver Sun-in-Shadow's Gift to Ralasa"] =
			{appendText=" Delvi at the Council House in northern Sadrith Mora. She is probably in the Council Hall on the main floor."},
		[16] = 
			{appendStepText="", stepTextKey="Sun-in-Shadow tricked me into delivering poisoned food to Ralasa Delvi. I should find and confront her."},
		["Talk to Sun-in-Shadow 3"] =
			{appendText=" near the Council House in northern Sadrith Mora.", stepTextKey="Sun-in-Shadow tricked me into delivering poisoned food to Ralasa Delvi. I should find and confront her."},
		[17] = 
			{appendStepText="At Magister Gothren's Tevlanni tower west of Sadrith Mora, ", stepTextKey="I'll need to find some way to distract the guards if I'm to gain access to Tel Aruhn."},
		["Distract the Guards"] =
			{appendText=". Perhaps I should speak with a Khajiiti slave."},
		[18] = 
			{appendStepText="At the Tevlanni tower west of Sadrith Mora, ", stepTextKey="Kizmar distracted the guards long enough for me to enter Tel Aruhn. I should make my way to Magister Gothren's chambers."},
		["Enter Tel Aruhn 2"] =
			{appendText=".", stepTextKey="Kizmar distracted the guards long enough for me to enter Tel Aruhn. I should make my way to Magister Gothren's chambers."},
	},

	[GetQuestName(5914)] = { --"The Magister Makes a Move"					--Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Sun-in-Shadow is probably hatching her next scheme in the Sadrith Mora Hireling House. I should seek her out."},
		["Meet Sun-in-Shadow in Her Home"] =
			{appendText=" south of the city's Gateway Inn."},
		[2] = 
			{appendStepText="South of Sadrith Mora's Gateway Inn, I entered the Argonian's house. ", stepTextKey="Someone ransacked Sun-in-Shadow's home. I should investigate."},
		["Examine Sun-in-Shadow's Home"] =
			{appendText=" to see what can be learned."},
		[3] = 
			{appendStepText="", stepTextKey="It appears that Magister Gothren's henchmen abducted Sun-in-Shadow from her home. I must travel to Gothren's stronghold, Tel Aruhn. According to Arith, confronting him directly provides the best chance of diffusing the situation."},
		["Talk to Magister Gothren 1"] =
			{appendText=" in Tel Aruhn, west of Sadrith Mora.", stepTextKey="It appears that Magister Gothren's henchmen abducted Sun-in-Shadow from her home. I must travel to Gothren's stronghold, Tel Aruhn. According to Arith, confronting him directly provides the best chance of diffusing the situation."},
		[4] = 
			{appendStepText="In Tel Aruhn, ", stepTextKey="Magister Gothren blackmailed me into stealing valuable information from Magister Otheri. If I complete this task, he might release Sun-in-Shadow and bury his grudge against us. Otheri probably tucked his journal away somewhere in Tel Naga."},
		["Steal Magister Otheri's Journal"] =
			{appendText=" from his retreat up in Sadrith Mora's central mushroom tower of Tel Naga. A journal can be found near bookcases in a reading nook."},
		[5] = 
			{appendStepText="In Sadrith Mora's Tel Naga, ", stepTextKey="I secured Magister Otheri's Research Journal. I should deliver it to Gothren's Mouth, Arith Sendrul. He waits for me in the Council House."},
		["Talk to Arith Sendrul"] =
			{appendText=" in the Council Hall on the main floor."},
		[6] = 
			{appendStepText="In the Council Hall of Sadrith Mora's Council House, Arith Sendrul, Gothren's Mouth, channeled his muthsera's image. ", stepTextKey=""},
		["Talk to Gothren's Projection"] =
			{appendText="."},
		[7] = 
			{appendStepText="", stepTextKey="It seems that Gothren's not done with me yet. He demanded that I seek out Otheri's Dwarven Prism in a kwama mine called Zalkin-Sul."},
		["Travel to Zalkin-Sul"] =
			{appendText=", a kwama egg mine owned by Magister Otheri. It is likely off limits for me. I should speak with Arith before I leave. \n\nZalkin-Sul is west of Sadrith Mora on the winding north-south road, near a foyada. It has wooden ramps leading to its entrance."},
		[8] = 
			{appendStepText="When I neared the mine, ", stepTextKey="I found a Nord miner stretching his legs outside Zalkin-Sul. I should see if he knows anything about the mine."},
		["Talk to Lothnarth 1"] =
			{appendText=" as he enjoys a break.", stepTextKey="I found a Nord miner stretching his legs outside Zalkin-Sul. I should see if he knows anything about the mine."},
		[9] = 
			{appendStepText="", stepTextKey="The Nord miner, Lothnarth, warned me about Otheri's guards patrolling the Zalkin-Sul egg mine. I should try to find Otheri's Dwarven Prism without rousing suspicion."},
		["Explore the Zalkin-Sul Egg Mine"] =
			{appendText=". Lothnarth also mentioned a Dwemer ruin."},
		[10] = 
			{appendStepText="Deep within Zalkin-Sul, the egg mine near the forked foyada north of Nchuleftingh Wayshrine, ", stepTextKey="I found Magister Otheri's mysterious Dwarven Prism, firmly locked into an ancient device. Lothnarth arrived shortly after I did. I should speak with him."},
		["Talk to Lothnarth 2"] =
			{appendText=".", stepTextKey="I found Magister Otheri's mysterious Dwarven Prism, firmly locked into an ancient device. Lothnarth arrived shortly after I did. I should speak with him."},
		[11] = 
			{appendStepText="Toward the southeastern area of Zulkin-Sul Egg Mine, ", stepTextKey="Lothnarth gave me a key to the Dwarven ruin, Mzanchend. I must scour the ruins for a few tools to help me unlock Otheri's Dwarven Prism and technical documents for my Nord companion."},
		["Enter Mzanchend"] =
			{appendText=" through the northern door in the machine's small cavern. I should look for a crank, a gear, a piston, and a handle."},
		[12] = 
			{appendStepText="From Zulkin-Sul, ", stepTextKey="I entered Mzanchend. Now I just need to find the parts to unlock Otheri's Dwarven Prism."},
		["Find the Tools to Release the Crystal"] =
			{appendText=" \n\nLothnarth said I need a crank, a gear, a piston, and a handle. Perhaps I will find some notes, too."},
		[13] = 
			{appendStepText="In the Dwemer ruin of Mzanchend, ", stepTextKey="I collected all the requisite tools to operate Otheri's device. I should use them to unlock the Dwarven Prism."},
		["Release the Dwarven Prism"] =
			{appendText=" from its machine in the small cave in the southeastern area of the Zulkin-Sul egg mine."},
		[14] = 
			{appendStepText="In the Zulkin-Sul Egg Mine, ", stepTextKey="Removing the Dwarven Prism caused some kind of groundquake. I should make haste to the exit."},
		["Escape the Mine"] =
			{appendText=" through the southeasternmost cavern."},
		[15] = 
			{appendStepText="", stepTextKey="I've escaped from the collapsing mine with the unique dwarven prism that Magister Gothren wanted. I should bring it to Tel Aruhn."},
		["Return to Tel Aruhn"] =
			{appendText=" from the Zulkin-Sul Egg Mine's eastern exit, on the north side of a foyada, north of the Nchuleftingh Wayshrine.\n\nBefore I return, I should speak with Keesu, the Argonian who warned me to escape."},
		[16] = 
			{appendStepText="", stepTextKey="I escaped the Zalkin-Sul egg mine before it collapsed. Only one task remains—delivering Otheri's Dwarven Prism to Magister Gothren in Tel Aruhn."},
		["Talk to Magister Gothren 2"] =
			{appendText=" inside his mushroom tower's audience chamber.", stepTextKey="I escaped the Zalkin-Sul egg mine before it collapsed. Only one task remains—delivering Otheri's Dwarven Prism to Magister Gothren in Tel Aruhn."},
		[17] = 
			{appendStepText="In his chamber within Tel Aruhn, ", stepTextKey="Magister Gothren accepted the Dwarven Prism as recompense for our debt and released Sun-in-Shadow. I should talk to her so we can end this business with the cruel master of Tel Aruhn."},
		["Talk to Sun-in-Shadow"] =
			{appendText=" in Gothren's chamber."},
	},

	[GetQuestName(5922)] = { --"The Heart of a Telvanni"					--Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Sun-in-Shadow mentioned that she needed some time to reflect. I should visit her to see if she's made any progress."},
		["Talk to Sun-in-Shadow in Sadrith Mora"] =
			{appendText=" at her house south of the Gateway Inn."},
		[2] = 
			{appendStepText="", stepTextKey="Eoki stormed out of Sun-in-Shadow's house after scolding her for turning her back on other Telvanni slaves. Sun-in-Shadow asked me to speak with Eoki. She hopes I can persuade him not to do anything rash."},
		["Talk to Eoki 1"] =
			{appendText=", working at the Sadrith Mora Docks.", stepTextKey="Eoki stormed out of Sun-in-Shadow's house after scolding her for turning her back on other Telvanni slaves. Sun-in-Shadow asked me to speak with Eoki. She hopes I can persuade him not to do anything rash."},
		[3] = 
			{appendStepText="At the Sadrith Mora Docks, ", stepTextKey="I agreed to help Eoki and some other slaves escape Sadrith Mora. I need to deliver Eoki's payment to Atarga, a member of the Ropefish mercenaries who help slaves escape. I can find her in the Gateway Inn."},
		["Deliver Payment to the Ropefish Contact"] =
			{appendText=", Atarga."},
		[4] = 
			{appendStepText="At Sadrith Mora's Gateway Inn, ", stepTextKey="Eoki's contact, Atarga, was incapacitated. I should speak to her companion, Lagdabash."},
		["Speak to Lagdabash"] =
			{appendText=", a flame-haired, female Orc."},
		[5] = 
			{appendStepText="", stepTextKey="My contact, Atarga, staggered off drunk. When I turned to leave the inn, I found Sun-in-Shadow waiting for me. She's likely been following me. I should talk to her before I set out to find the Ropefish leader, Bothamul."},
		["Talk to Sun-in-Shadow 1"] =
			{appendText=" inside the Gateway Inn of Sadrith Mora.", stepTextKey="My contact, Atarga, staggered off drunk. When I turned to leave the inn, I found Sun-in-Shadow waiting for me. She's likely been following me. I should talk to her before I set out to find the Ropefish leader, Bothamul."},
		[6] = 
			{appendStepText="", stepTextKey="I must travel to a small island near Tel Aruhn to deliver Eoki's payment to the Ropefish leader, Bothamul."},
		["Deliver the Payment to Bothamul"] =
			{appendText=". Lagdabash said her boss is on the island west of Tel Aruhn."},
		[7] = 
			{appendStepText="I found Bothamul on the island northwest of Tel Aruhn, where Vassamsi Mine is located. ", stepTextKey="I delivered Eoki's payment to the Ropefish. I should meet him at Vassamsi Mine and give him the news."},
		["Talk to Eoki 2"] =
			{appendText=". Bothamul said the Argonian is waiting near the mine on the island north of Tel Aruhn.", stepTextKey="I delivered Eoki's payment to the Ropefish. I should meet him at Vassamsi Mine and give him the news."},
		[8] = 
			{appendStepText="On the island north of Tel Aruhn, ", stepTextKey="I agreed to help Eoki free the slaves locked away in the Vassamsi Mine. I should enter the mine and take a look around."},
		["Enter the Vassamsi Mine"] =
			{appendText=" through the door at the dock with the cargo boat."},
		[9] = 
			{appendStepText="On the island north of Tel Aruhn, I have entered Vassamsi Mine. ", stepTextKey="I must eliminate the guards near the mine's entrance to prevent them from raising an alarm."},
		["Deal with the Guards at the Front of Vassamsi"] =
			{appendText=" Mine."},
		[10] = 
			{appendStepText="I entered Vassamsi Mine on the island north of Tel Aruhn. ", stepTextKey="Now that the guards are subdued, I should free the slaves from their cages."},
		["Free the Slaves"] =
			{appendText=" \n\nThey are in elevated wooden cages in Vassamsi's first cavern."},
		[11] = 
			{appendStepText="Inside Vassamsi Mine, north of Tel Aruhn, ", stepTextKey="Eoki told me that the Vassamsi guard captain may be nearby. Without their leader, the other guards may scatter. I must find this captain and slay him."},
		["Defeat the Guard Captain"] =
			{appendText="."},
		[12] = 
			{appendStepText="North of Tel Aruhn, in Vassamsi Mine, I defeated Captain Flaeus. ", stepTextKey="A larger contingent of guards waits for me deeper inside the mine. I must defeat them so the remaining slaves can escape."},
		["Help The Slaves in the Mine Escape"] =
			{appendText=" from the large, eastern cavern known as the Work Area."},
		[13] = 
			{appendStepText="In Vassamsi Mine's eastern Work Area cavern, ", stepTextKey="Eoki led Sun-in-Shadow to the back exit of the mine. Most of the slaves went out that way too. I should follow."},
		["Escape the Mine"] =
			{appendText=" through the Work Area's southern door."},
		[14] = 
			{appendStepText="From Vassamsi Mine's eastern cavern, the Work Area, ", stepTextKey="Sun-in-Shadow and Eoki fled through the door. I have a bad feeling about what lurks on the other side. I must hurry to their defense."},
		["Help Sun-in-Shadow Defeat Slavemaster Arenim"] =
			{appendText=" in the southernmost cavern."},
		[15] = 
			{appendStepText="North of Tel Aruhn, in Vassamsi Mine's southernmost cavern, ", stepTextKey="I defeated the Slavemaster Arenim. I should talk to Sun-in-Shadow to decide where to go from here."},
		["Talk to Sun-in-Shadow 2"] =
			{appendText=" inside the cavern.", stepTextKey="I defeated the Slavemaster Arenim. I should talk to Sun-in-Shadow to decide where to go from here."},
		[16] = 
			{appendStepText="", stepTextKey="Sun-in-Shadow decided to let Eoki go. I should talk to her one last time."},
		["Talk to Sun-in-Shadow Outside 1"] =
			{appendText=" of the mine on the island north of Tel Aruhn."},
		[17] = 
			{appendStepText="", stepTextKey="Sun-in-Shadow resolved to keep Eoki as a slave, hoping to win him back over time. I should talk to her one last time."},
		["Talk to Sun-in-Shadow Outside 2"] =
			{appendText=" of the mine on the island north of Tel Aruhn."},
	},

-- 		=========================================================================
--		 Vvardenfell - Side Quest
-- 		=========================================================================

    [GetQuestName(5950)] = { --"The Ancestral Tombs"					--Jordakai
        [1] = 
            {appendStepText="At Vivec City's Temple Canton, I met with Librarian Bradyn in the Library of Vivec. ", stepTextKey="To start the process of solving the mystery of the lost library, I need to take a rubbing at the Othrelas Ancestral Tomb, to the north of Vivec City."},
        ["Take Rubbing at Othrelas Ancestral Tomb"] =
            {appendText=". It is on the bay's northwestern shore, just south of a bridge."},
        [2] = 
            {appendStepText="At Vivec City's Temple Canton, I met with Librarian Bradyn in the Library of Vivec. ", stepTextKey="To start the process of solving the mystery of the lost library, I need to take a rubbing at the Othrelas Ancestral Tomb, to the north of Vivec City."},
        ["Give Rubbing to Librarian Bradyn"] =
            {appendText=" at the library. I have it with me."},
        [3] = 
            {appendStepText="", stepTextKey="I took the rubbing at the Othrelas Ancestral Tomb. Now I should return to the library in Vivec City and give the rubbing to Librarian Bradyn."},
        ["Talk to Librarian Bradyn 1"] =
            {appendText=" in the Library of Vivec at the Temple Canton."},
        [4] = 
            {appendStepText="At Vivec City's Temple Canton, in the Library of Vivec, ", stepTextKey="I gave Librarian Bradyn the rubbing. Now I should talk to him and ask what happens next."},
        ["Talk to Librarian Bradyn 2"] =
            {appendText=".", stepTextKey="I gave Librarian Bradyn the rubbing. Now I should talk to him and ask what happens next."},
        [5] = 
            {appendStepText="At the Temple Canton of Vivec City, I gave the tomb rubbing to Librarian Bradyn in the Library of Vivec. ", stepTextKey="The Librarian utilized some sort of magic to add a new section to the miniature model of Vvardenfell. I should talk to him and find out how I can help him complete the model and locate the lost Library of Andule."},
        ["Talk to Librarian Bradyn 3"] =
            {appendText=".", stepTextKey="The Librarian utilized some sort of magic to add a new section to the miniature model of Vvardenfell. I should talk to him and find out how I can help him complete the model and locate the lost Library of Andule."},
    },

    [GetQuestName(5923)] = { --"The Lost Library"					--Jordakai
        [1] = 
            {appendStepText="At the Library of Vivec in Vivec City, ", stepTextKey="Librarian Bradyn asked me to go to the location in Vvardenfell that corresponds to the gap in the model. That's where he's sure we'll find the lost Library of Andule."},
        ["Find the Lost Library"] =
            {appendText=". It appears that I should search the area north of the Nchuleftingth Wayshrine, beyond a stone bridge cossing the fire-river and a Dwemer ruin. It is probably in the vicinity of the tight bend in the main road west of Sadrith Mora."},
        [2] = 
            {appendStepText="North of Nchuleftingth Wayshrine and west of Sadrith Mora, northwest of a tight bend in the road I found another Ancestral Tomb. ", stepTextKey="I located the entrance to the Library of Andule. I should go inside and look around."},
        ["Enter the Lost Library"] =
            {appendText=" of Andule."},
        [3] = 
            {appendStepText="North of Nchuleftingth Wayshrine and west of Sadrith Mora, northwest of a tight bend in the road, ", stepTextKey="I entered the Library of Andule. I should look around and see if I can find anything to bring back to Librarian Bradyn in Vivec City."},
        ["Explore the Library"] =
            {appendText=". To the south, there is a large statue with a pedestal holding a stone tablet. I should start my search there."},
        [4] = 
            {appendStepText="In the Library of Andule, north of Nchuleftingth and west of Sadrith Mora, I read a stone tablet. ", stepTextKey="To gain access to the stored knowledge of the Library of Andule, I need to walk the tile path that reflects Veloth's journey from Summerset to Exodus to Morrowind to light the Braziers of Knowledge and Wisdom."},
        ["Light the Brazier of Knowledge"] =
            {appendText=" in the northeastern chamber.\n"},
        ["Light the Brazier of Wisdom"] =
            {appendText=" in the southeastern chamber."},
        [5] = 
            {appendStepText="In the Library of Andule, north of Nchuleftingth and west of Sadrith Mora, ", stepTextKey="I solved the puzzle and ignited the braziers. Now to enter the ancient vaults and see what I can find."},
        ["Enter the Ancient Vaults"] =
            {appendText=" through the passageway that opened in the east wall of the central chamber."},
        [6] = 
            {appendStepText="In the Library of Andule, north of Nchuleftingth and west of Sadrith Mora, ", stepTextKey="I reached the ancient storage vaults for the library. Now I should try to find a few Dark Elf genealogies to bring to Librarian Bradyn back in Vivec City."},
        ["Retrieve Indoril Genealogy"] =
            {appendText=".\n"},
        ["Retrieve Redoran Genealogy"] =
            {appendText=".\n"},
        ["Retrieve Hlaalu Genealogy"] =
            {appendText=".\n"},
        ["Retrieve Dres Genealogy"] =
            {appendText="."},
        [7] = 
            {appendStepText="", stepTextKey="I reached the ancient storage vaults for the library. Now I should try to find a few Dark Elf genealogies to bring back to Librarian Bradyn back in Vivec City."},
        ["Retrieve Telvanni Genealogy"] =
            {appendText=" that has appeared in the easternmost chamber with the flying books."},
        [8] = 
            {appendStepText="", stepTextKey="Now that I retrieved the genealogies of the Great Houses, I should return to the library in Vivec City and give them to Librarian Bradyn."},
        ["Return to the Librarian in Vivec City"] =
            {appendText="."},
        [9] = 
            {appendStepText="", stepTextKey="I found the lost library and recovered the genealogies of the Great Houses. Now I should return to the Library in Vivec City and talk to Librarian Bradyn."},
        ["Talk to Librarian Bradyn"] =
            {appendText="."},
    },

    [GetQuestName(6004)] = { --"A Late Delivery"					--Jordakai
        [1] = 
            {appendStepText="At Vivec City's Saint Olms Canton, ", stepTextKey="Edryno asked me to deliver the mushrooms to Divayth Fyr's Mouth, Vaelin Oren, on her behalf. I'll find him in Sadrith Mora."},
        ["Deliver Rare Mushrooms to Vaelin Oren"] =
            {appendText=". He is a well-dressed Dunmer conducting business in the northern Telvanni mushroom tower known as the Council House, in the eastern city of Sadrith Mora.\n\nThe navigator, Synda Imyam, keeps her boat at the small western dock near the city's Silt Strider Caravaner tower."},
        [2] = 
            {appendStepText="In the northern Telvanni mushroom tower known as the Council House in the eastern city of Sadrith Mora, ", stepTextKey="I've delivered the mushrooms to Vaelin Oren. I must speak to him to collect my payment."},
        ["Talk to Vaelin Oren"] =
            {appendText="."},
    },

	[GetQuestName(5864)] = { --"Nothing to Sneeze At"					--Jordakai
		[1] = 
			{appendStepText="In Suran, ", stepTextKey="Tilenra asked me to talk to Menaldinion. Perhaps I can convince him to apologize to Tilenra and stop posting slanderous bills around town."},
		["Talk to Menaldinion 1"] =
			{appendText=", an Altmer, at his Clinic in the southern part of Suran. The clinic is at the top of a set of stairs and at the foot of another set. Lovely blue flowers enhance the clinic's doorway.\n\nI could read his Advertisement posted on the bulletin board at the town's northern gateway.", stepTextKey="Tilenra asked me to talk to Menaldinion. Perhaps I can convince him to apologize to Tilenra and stop posting slanderous bills around town."},
		[2] = 
			{appendStepText="I spoke with the Altmer mage at his clinic in south Suran. ", stepTextKey="As expected, Menaldinion has no intention of apologizing for his rude behavior and libelous advertisements. I should talk to Tilenra to discuss her next move."},
		["Talk to Tilenra 1"] =
			{appendText=" Sildreth at her alchemy work area downstairs from Menaldinion's Clinic, at the entry stairs for Desele's tavern in south Suran. Her place is well stocked for herbal alchemy. I should return her book to her, too.", stepTextKey="As expected, Menaldinion has no intention of apologizing for his rude behavior and libelous advertisements. I should talk to Tilenra to discuss her next move."},
		[3] = 
			{appendStepText="In south Suran, at her alchemy place by Desele's tavern, I learned that ", stepTextKey="Tilenra plans to exact her revenge on Menaldinion by using a mysterious potion. She asked me to gather up a vital ingredient—a lichen that grows at the base of the emperor parasol mushrooms."},
		["Harvest Emperor Parasol Lichen"] =
			{appendText=". I can find the sky blue lichen at the base of giant emperor parasol mushrooms that grow near the eastern bay of Lake Amaya, west of Suran's wayshrine."},
		[4] = 
			{appendStepText="On Lake Amaya's banks, ", stepTextKey="I gathered the lichen from an emperor parasol. I should meet with Tilenra near Menaldinion's Clinic."},
		["Talk to Tilenra 2"] =
			{appendText=" near the Altmer mage's Clinic with the potted blue flowers. It is between two sets of stairs in south Suran.", stepTextKey="I gathered the lichen from an emperor parasol. I should meet with Tilenra near Menaldinion's clinic."},
		[5] = 
			{appendStepText="At Menaldinion's Clinic between two sets of stairs in south Suran, Tilenra shared her plan. ", stepTextKey="Apparently, Tilenra's mysterious potion is a potent cat lure. Given that Menaldinion is violently allergic to cats, things should get interesting. I need only pour the mixture over the High Elf's plants and observe the results."},
		["Pour the Potion on the Plants"] =
			{appendText=", the lovely blue flowers on each side of the clinic's door."},
		[6] = 
			{appendStepText="At Menaldinion's Clinic, between the two sets of stairs in south Suran, I poured Tilenra's Potion on the flowering plants at the Altmer mage's door. ", stepTextKey="Tilenra's potion worked perfectly. Menaldinion fled from the cats, sneezing all the while. I should talk to Tilenra about what to do next."},
		["Talk to Tilenra 3"] =
			{appendText=", standing with the crowd outside the clinic.", stepTextKey="Tilenra's potion worked perfectly. Menaldinion fled from the cats, sneezing all the while. I should talk to Tilenra about what to do next."},
		[7] = 
			{appendStepText="Outside Menaldinion's Clinic, between the two sets of stairs in south Suran, ", stepTextKey="Tilenra gave me a tea that should alleviate Menaldinion's symptoms, but I'm only to give it to him if he agrees to make a public apology."},
		["Talk to Menaldinion 2"] =
			{appendText=" inside his clinic.", stepTextKey="Tilenra gave me a tea that should alleviate Menaldinion's symptoms, but I'm only to give it to him if he agrees to make a public apology."},
		[8] = 
			{appendStepText="In Menaldinion's Clinic, between the two sets of stairs in south Suran, I spoke with the Altmer mage. ", stepTextKey="Menaldinion agreed to apologize. I should tell Tilenra that a public apology is forthcoming."},
		["Talk to Tilenra 4"] =
			{appendText=" Sildreth. She waits outside the clinic with the crowd.", stepTextKey="Menaldinion agreed to apologize. I should tell Tilenra that a public apology is forthcoming."},
	},

	[GetQuestName(5862)] = { --"The Scarlet Judge"					 --Jordakai

		[1] = 
			{appendStepText="I was on the road west of the south-central town of Suran. ", stepTextKey="A frantic Dark Elf requested my aid in saving his father from marauding bandits. I should hurry to this innocent's defense."},
		["Save Avo's Father"] =
			{appendText=" near the western bridge into Suran."},
		[2] = 
			{appendStepText="Just east of the town's wayshrine, near the bridge west of Suran, ", stepTextKey="I encountered a mysterious, masked warrior. I should speak with him."},
		["Talk to the Masked Warrior"] =
			{appendText="."},

		[3] = 
			{appendStepText="Near the bridge west of Suran, Vvardenfell's south-central town, I spoke with The Scarlet Judge. ", stepTextKey="The Judge wants me to speak with one of Marshal Hlaren's prisoners. They could provide valuable insight into Hlaren's misconduct. They should be laboring in a field nearby."},
		["Talk to a Prisoner"] =
			{appendText=" working in the fields of the plantation across the river, south of Suran Wayshrine."},
		[4] = 
			{appendStepText="At the plantation across the river southwest of Suran, ", stepTextKey="Marshal Hlaren's prisoners refuse to speak to me—fearing reprisal from the cruel Overseer Torvayn. I must kill him if I'm to learn more about Hlaren's plot."},
		["Kill Overseer Torvayn"] =
			{appendText=". The taskmaster is watching the fields from a platform near the manor house, east of the fields."},
		[5] = 
			{appendStepText="Southwest of Suran, near the plantation's manor house on the south side of the river, ", stepTextKey="I killed the vile Overseer Torvayn. Now, I must gather testimony from the prisoners."},
		["Gather Testimony From Prisoners"] =
			{appendText=" \n\nOne is chopping wood south of the manor house.\nAnother is digging in the field southwest of the manor.\nA third is raking in the field west of the manor."},
		[6] = 
			{appendStepText="At the plantation south of the river and southwest of Suran, I spoke with some prisoners working at the property. ", stepTextKey="The prisoners I interviewed confirmed the Scarlet Judge's suspicions and indicated there may be hard evidence nearby. I should look for some documents to verify their claims."},
		["Investigate Mistress Dren's Manor"] =
			{appendText=". She resides on the shores of Lake Amaya, west of Suran, where the road snakes around her property. Her private residence is at the top of the manor."},
		["Investigate Master Kharekh's Manor"] =
			{appendText=". His property is southwest of Suran and north of Vivec City on a small estuary, surrounded by roads. He likely keeps his important papers downstairs."},
		[7] = 
			{appendStepText="In the manor houses, ", stepTextKey="I discovered ample evidence of Marshal Hlaren's corruption. I should take my findings to the Scarlet Judge at Ules Manor."},
		["Meet the Judge at Ules Manor"] =
			{appendText=", west of Suran. The house is near Suran's wayshrine and bridge on the river."},
		[8] = 
			{appendStepText="", stepTextKey="The Scarlet Judge disappeared through a secret passage in Ules Manor. I should see where this passage leads."},
		["Talk to the Scarlet Judge"] =
			{appendText=" in his secret chambers behind the bookcase in the lower level of his Ules Manor.  The manor is west of Suran, near the bridge and across from the wayshrine."},
		[9] = 
			{appendStepText="", stepTextKey="The Scarlet Judge fears that Marshal Hlaren's Iron Hounds will wreak havoc on Suran if we move too quickly. I must raid the mercenaries' camp to sow discord and confusion in the ranks."},
		["Go to Iron Hound Camp"] =
			{appendText=" in the Daedric ruin north of Suran. I should be able to follow the river north to reach the ruin."},
		[10] = 
			{appendStepText="North of Suran, I reached the Iron Hound camp in the Daedric ruin on the river. ", stepTextKey="The Scarlet Judge fears that Marshal Hlaren's Iron Hounds will wreak havoc on Suran if we move too quickly. I must raid the mercenaries' camp to sew discord and confusion in the ranks."},
		["Smash Supply Crates"] =
			{appendText=" \n\n"},
		["Burn Weapon Caches"] =
			{appendText=" \n\nCaches and Crates are scattered in and around the ruin."},
		[11] = 
			{appendStepText="At their camp in the Daedric ruin north of town, ", stepTextKey="I dealt a heavy blow to Marshal Hlaren's Iron Hounds. I should seek out the Scarlet Judge in Suran to plan our next move."},
		["Find the Scarlet Judge in Suran"] =
			{appendText=". I should enter the town through its northern gateway."},
		[12] = 
			{appendStepText="I returned to the north end of town. ", stepTextKey="A Nord constable approached me on the streets of Suran. I should see what she has to say."},
		["Talk to Constable Gretga 1"] =
			{appendText=". In a Dunmer town, the blonde Nord with an eye patch stands out. She may want to find a quiet place nearby before speaking with me.", stepTextKey="A Nord constable approached me on the streets of Suran. I should see what she has to say."},
		[13] = 
			{appendStepText="In Suran, ", stepTextKey="Marshal Hlaren's henchmen have captured and imprisoned the Scarlet Judge. I must find a way to gain access to the prison."},
		["Find a Way Into Suran Prison"] =
			{appendText=":\n- Constable Kren is having a drink at the local tavern, Desele's House of Earthly Delights, in the southern part of town.\n- As for a locksmith, Remas Belan secludes himself in Keymaster's Tower up in the town's southwest, near Suran Temple.\n- Dredyni Imayn works at Desele's tavern. She may know how to get into the prison. I'll probably have to do something for her, like find someone at a Dwemer ruin on an island southeast of Suran!"},
		[14] = 
			{appendStepText="", stepTextKey="I acquired a key to the Suran jailhouse. I must infiltrate this prison and find the Scarlet Judge."},
		["Enter Suran Prison"] =
			{appendText=". It is the first building on the east side, south of the town's northern gateway.\n\nConstable Drivam sits outside the prison, perhaps I should speak with him."},
		[15] = 
			{appendStepText="The Suran Prison is south of the town's northern gateway. ", stepTextKey="Now that I'm inside the prison, I should find the Scarlet Judge."},
		["Talk to The Scarlet Judge"] =
			{appendText=". He is being kept on the lower level."},
		[16] = 
			{appendStepText="In Suran Prison, ", stepTextKey="I agreed to take on the mantle of the Scarlet Judge. Unfortunately, the Judge's regalia has been confiscated by the prison's overseer, Warden Libo. I must travel to the Warden's hunting camp to steal it back."},
		["Find Warden Libo's Hunting Camp"] =
			{appendText=" on the southern shore of Lake Nabia, north of Suran. Just west of town, I should follow the Nabia River north to reach the lake, and then travel west along the shoreline."},
		[17] = 
			{appendStepText="North of Suran on the southern shore of Lake Nabia, ", stepTextKey="I arrived at Warden Libo's hunting camp. Now I must find the Judge's regalia."},
		["Take the Scarlet Judge's Regalia"] =
			{appendText=" from the Warden's Trophy Chest at the base of a tree."},
		[18] = 
			{appendStepText="I retrieved the Scarlet Judge Regalia from the warden's camp at Lake Nabia, northwest of Suran. ", stepTextKey="I became the Scarlet Judge. Now I should return to Suran and find Constable Gretga to plot our next move."},
		["Talk to Constable Gretga 2"] =
			{appendText=". The blonde Nord will be on the balcony of the house next door to the town's prison, south of the northern gateway.", stepTextKey="I became the Scarlet Judge. Now I should return to Suran and find Constable Gretga to plot our next move."},
		[19] = 
			{appendStepText="In Suran, Constable Gretga gave me a key to a mine and let me know that ", stepTextKey="Marshal Hlaren and her confederates have gathered in the Inanius Egg Mine for a secret meeting. I must infiltrate the mine, find the confiscated evidence, and track down the corrupt marshal."},
		["Enter Inanius Egg Mine"] =
			{appendText=" east of Suran, on the other side of the mountain. I am looking for a recessed back entrance with fungal growth. It is a short distance north on the narrower road that intersects a big curve of the main road.\n\nI should leave town through the south gateway and follow the main road to the intersection, then north."},
		[20] = 
			{appendStepText="East of Suran, on the opposite side of the mountain, I entered the Inanius Egg Mine through its recessed back entrance with fungal growth, north of the big curve of the main road.\n\n", stepTextKey="Marshal Hlaren must have hidden the evidence she confiscated in the mine. I should search any areas used for storage as I explore the mine."},
		["Retrieve Stolen Evidence"] =
			{appendText=" \n\nThe documents may be in broken or open cargo boxes. I should search the northern cavern area, just below where I entered. Then the central cavern, and then the third cavern before reaching the large southern area."},
		[21] = 
			{appendStepText="East of Suran, on the opposite side of the mountain, I entered the Inanius Egg Mine through its recessed back entrance with fungal growth, north of the big curve of the main road.\n\n", stepTextKey="I found the evidence Marshal Hlaren confiscated from the Scarlet Judge. Now I must find the marshal herself."},
		["Find Marshal Hlaren"] =
			{appendText=" farther south in the  mine. If there is a fenced overlook I should use it to see what I can."},
		[22] = 
			{appendStepText="East of Suran, on the opposite side of the mountain, I entered the Inanius Egg Mine through its recessed back entrance with fungal growth, north of the big curve of the main road.\n\n", stepTextKey="I found Marshal Hlaren and her co-conspirators. It's unlikely that the marshal will come quietly. I should be prepared to end her dirty dealings with lethal force."},
		["Confront Marshal Hlaren"] =
			{appendText=" near the mine's main entrance at the southeastern area of the mine."},
		[23] = 
			{appendStepText="I left the mine east of Suran. ", stepTextKey="All the incriminating evidence is accounted for. I should give it to Constable Gretga."},
		["Give Evidence to Constable Gretga"] =
			{appendText=" outside the Inanius Egg Mine's main entrance by the shed and cart on the road southeast of Suran."},
		[24] = 
			{appendStepText="", stepTextKey="Marshal Hlaren is dead and her co-conspirators are in chains. I should find the former Scarlet Judge, Melar Sadus, and inform him of our success."},
		["Talk to Melar Sadus, the former Scarlet Judge"] =
			{appendText=". He should be sitting under a tree near the Suran Prison, south of the town's northern gateway."},
	},

	[GetQuestName(5885)] = { --"Ancestral Ties"					--Jordakai
		[1] = 
			{appendStepText="", stepTextKey="To earn the Ashlander's respect, I must honor the First Ashkhans. I should seek out Farseer Kuamta to receive her blessing."},
		["Receive the Farseer's Blessing"] =
			{appendText=". She wears a blindfold at the northeastern camp, next to the Emperor Crab's shell, Skar."},
		[2] = 
			{appendStepText="In Ald'ruhn's Ashlander camp, I spoke with Farseer Kuamta about honoring the First Ashkhans. ", stepTextKey="Each of the four great tribes require a unique offering. I must claim four rare objects to place before the cairns of the First Ashkhans."},
		["Obtain an Ashen Fern"] =
			{appendText=". They grow on the small islands on the coast southwest of Ald'ruhn, near a Redoran manor north of a Dwemer ruin.\n"},
		["Obtain the Weapon of an Exiled Ashlander"] =
			{appendText=". There should be a large camp west of Ald'ruhn, in the rocky area west of the road and southwest of the West Gash Wayshrine.\n"},
		["Obtain the Bones of a Fallen Guar"] =
			{appendText=" along the footpath rising from the north end of the western swampland, where tall trees and flowers appear. It is southeast of a camp of Exiles.\n"},
		["Obtain a Jeweled Cuttle"] =
			{appendText=" from a Kwama Queen. Her nest will be far from the entrance. There is a place, Ashimanu Cave, with wild kwama. It is northwest of Ald'ruhn and north of the West Gash Wayshrine, off the main road to the east."},
		[3] = 
			{appendStepText="I can return to the Ashlander encampment at Ald'ruhn. ", stepTextKey="I claimed all four offerings. I should place them near the four cairns of the First Ashkhans."},
		["Place the Ahemmusa Offering"] =
			{appendText=" at the Cairn of Nalor Ahemmusa at the base of a burnt tree on a rise south of the encampment. It is behind the tall rocks of the southern campsite. I may speak with the Ashlander at the cairn.\n"},
		["Place the Erabenimsun Offering"] =
			{appendText=" at the Cairn of Shadar Erabenimsun. It is southeast of the encampment, just off the road leading to ruins and lava. I may speak with the Ashlander at the cairn.\n"},
		["Place the Urshilaku Offering"] =
			{appendText=" at the Cairn of Lammak Urshilaku in the encampment's northeast near Skar, in a rocky cove. It is near his descendants' camp. I may speak with the Ashlander at the cairn.\n"},
		["Place the Zainab Offering"] =
			{appendText=" at the Cairn of Akami Zainab in the encampment's northwest, near the large foyada. It is not far along the path from the western camp of the Zainab tribe. I may speak with the Ashlander at the cairn."},
		[4] = 
			{appendStepText="In Ald'ruhn, I have placed gifts at each of the cairns for the First Ashkhans. Now ", stepTextKey="I should seek out the tribe's Wise Woman. She might know more about the Hleran Ancestral Tomb."},
		["Talk to the Tribe's Wise Woman"] =
			{appendText=" in her yurt at the camp west of Skar's entrance. An Ashlander merchant camps there, too."},
		[5] = 
			{appendStepText="In Ald'ruhn, I spoke to the Ashlander Wise Woman. ", stepTextKey="According to Wise Woman Asani, the Hleran Ancestral Tomb may be nearby. Unfortunately, angry spirits lurk within. I should give the news to Drelyth."},
		["Talk to Drelyth Hleran 1"] =
			{appendText=". I suspect he is waiting on the outskirts of the encampment, near the totems, just northeast of the wayshrine.", stepTextKey="According to Wise Woman Asani, the Hleran Ancestral Tomb may be nearby. Unfortunately, angry spirits lurk within. I should give the news to Drelyth."},
		[6] = 
			{appendStepText="Near the totems on the path northeast of the wayshrine, I spoke with Drelyth again. ", stepTextKey="I agreed to search the nearby ancestral tomb, but I'll have to find it first."},
		["Find the Ancestral Tomb"] =
			{appendText=" of the Hleran family. Drelyth mentinoed his ancestor, Dranoth, was the family's patriach. Wise Woman Asani said there is a tomb that hides in the rocks on the other side of the fire-river, west of the encampment."},
		[7] = 
			{appendStepText="On the western shore of the fire-river the Ashlanders call Druru, northwest of the wayshrine, ", stepTextKey="I discovered the ancestral tomb the Wise Woman told me about. Now I must look for evidence of a Hleran family connection."},
		["Search the Tomb"] =
			{appendText=". I hope the Hleran Heraldry Sash that Drelyth gave me helps."},
		[8] = 
			{appendStepText="In the rocky western bank of Ald'ruhn's fire-river, I entered the Hleran Ancestral Tomb. ", stepTextKey="One of Drelyth's ancestors, Dranoth, challenged me to prove the purity of my intent. I should pay my respects to the Hleran family shrines."},
		["Pay Respects at the Shrines"] =
			{appendText=" \n\nThe Hleran shrines are stone altars with flanking braziers. They are in the center, the southeast, the southwest, and the northwest of the tomb. A small rug for kneeling is at each shrine."},
		[9] = 
			{appendStepText="West of Ald'ruhn's fire-river, I entered the Hleran Ancestral Tomb. Then ", stepTextKey="I paid my respects to the Hleran family shrines and listened to Dranoth's story. I should seek him out in his personal crypt. Apparently, he has more to tell me."},
		["Enter Dranoth's Burial Chamber"] =
			{appendText=" in the northernmost area of the Hleran Ancestral Tomb."},
		[10] = 
			{appendStepText="West of Ald'ruhn's fire-river, at the northernmost area inside the Hleran Ancestral Tomb, ", stepTextKey="I found Dranoth Hleran's spirit waiting for me in his personal crypt. I should see what he has to say."},
		["Talk to Dranoth Hleran"] =
			{appendText="."},
		[11] = 
			{appendStepText="West of Ald'ruhn's fire-river at the Hleran Ancestrral Tomb, in its northernmost area, ", stepTextKey="Dranoth wants me to take up his ancient spear—a weapon with great symbolic power."},
		["Take Dranoth's Spear"] =
			{appendText=", Calderas, from the shrine's altar in his private burial chamber."},
		[12] = 
			{appendStepText="", stepTextKey="I must deliver Dranoth's spear, Calderas, to his descendant, Drelyth Hleran."},
		["Deliver the Spear to Drelyth"] =
			{appendText=". He should be waiting at the Ashlander encampment. Perhaps he ventured in to speak with someone."},
		[13] = 
			{appendStepText="In Ald'ruhn's northeastern Ashlander camp, ", stepTextKey="I should talk to Drelyth about what he plans to do now that he knows his family's story."},
		["Talk to Drelyth Hleran 2"] =
			{appendText=" as he holds Calderas, his ancestor's spear that killed the Emperor Crab.", stepTextKey="I should talk to Drelyth about what he plans to do now that he knows his family's story."},
	},

    [GetQuestName(5900)] = { --"Echoes of a Fallen House"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should travel north through the Ashlands into the Forgotten Wastes. I might be able to find some sign of Tythis or Nevena there."},
        ["Find Tythis Nirith"] =
            {appendText=", an Ordinator, in the Forgotten Wastes near the island's northern coast."},
        [2] = 
            {appendStepText="On the island's northern coast, I found the Ordinator, Tythis. ", stepTextKey="I need to search the ruins and tombs dotting the Forgotten Wastes for clues as to where Nevena might be."},
        ["Find Clues to Nevena's Whereabouts"] =
            {appendText=" \n\nTythis mentioned seeing robed figures after his sister stabbed him. What kind of relic was it?\nDown the western path, there may be an entrance to a tomb - as good a place to start as any. I should look for journals, scrolls, orders, or other writings that may point me in the right direction."},
        [3] = 
            {appendStepText="I found clues in the Drinith Ancestral Tomb. Then I found more down in the Wastes' northern volcanic cavern. ", stepTextKey="I learned that Nevena is being held inside the Wakener's Hall by the leader of the Sixth House cultists in this area. The hall is sealed by some sort of device. I need to find a way inside if I'm going to help Nevena."},
        ["Find a Way Inside the Wakener's Hall"] =
            {appendText=". Waken from what? Nightmares? Dreams?\n\nA southwestern door in the volcanic cavern leads to the Forgotten Depths. The Wakener's Hall is likely to the southeast in that deeper cavern. The Sixth House cultists have probably blocked the way. The ancient Daedric arches are fascinating."},
        [4] = 
            {appendStepText="In the Wastes' southwestern cavern, the Forgotten Depths, striking the ancient bells lit up the arch to open the way into the Wakener's Hall. Inside, ", stepTextKey="Wakener Maras has Nevena. I'll have to defeat him if I hope to rescue her."},
        ["Defeat Wakener Maras"] =
            {appendText=", the leader of the Sixth House cultists."},
        [5] = 
            {appendStepText="In the Wastes' southeastern, underground ruin, the Wakener's Hall, ", stepTextKey="I defeated Wakener Maras, but had to kill Nevena after she attacked me alongside him. I can see a diary nearby that they were attempting to burn. I should collect it for Tythis."},
        ["Take Nevena's Diary"] =
            {appendText=" from the floor near the raging blaze."},
        [6] = 
            {appendStepText="Within the Wakener's Hall, I defeated the Sixth House cult leader. ", stepTextKey="In the end, Nevena gave me no choice but to end her life along with the cult leader's. I should report back to Tythis and deliver the news."},
        ["Talk to Tythis"] =
            {appendText=". He should be waiting near the entrance inside the Forgotten Wastes. I will give him his sister's journal, too."},
    },

	[GetQuestName(5882)] = { --"Ancestral Adversity"				--Jordakai
		[1] = 
			{appendStepText="In the Azura's Coast region, far south of the eastern city of Sadrith Mora, I found a small camp with a couple of people. A female Nord called ", stepTextKey="Elfbetta asked me to enter the Dreloth Ancestral Tomb and check on Narsis Dren. He's been gone for a long time and she's starting to get worried."},
		["Find Narsis Dren in Dreloth Ancestral Tomb"] =
			{appendText=" near the camp."},
		[2] = 
			{appendStepText="The Dreloth Ancestral Tomb is in the Azura's Coast region, far south of the eastern city of Sadrith Mora. ", stepTextKey="Narsis has been observing a creature in the next chamber, watching its shadow and waiting for it to make its move. He wants me to slip into the chamber and see what the creature's true intentions are before we explore the rest of the tomb."},
		["Investigate the Creature"] =
			{appendText=" in the eastern chamber near the tomb's entrance."},
		[3] = 
			{appendStepText="In the Azura's Coast region, far south of the eastern city of Sadrith Mora, ", stepTextKey="Narsis wants me to help him explore the Dreloth Ancestral Tomb."},
		["Explore Dreloth Ancestral Tomb"] =
			{appendText=". I should go down the stairs to the west, through the chambers, following Narsis."},
		[4] = 
			{appendStepText="The Dreloth Ancestral Tomb is in the Azura's Coast region, far south of the eastern city of Sadrith Mora. In the tomb, ", stepTextKey="Narsis seems disappointed that we didn't find anything significant down here. I should talk to him."},
		["Talk to Narsis Dren 1"] =
			{appendText=" in the tomb's south-central Ancestral Prayer Room.", stepTextKey="Narsis seems disappointed that we didn't find anything significant down here. I should talk to him."},
		[5] = 
			{appendStepText="The Dreloth Ancestral Tomb is in the Azura's Coast region, far south of the eastern city of Sadrith Mora. In the tomb, ", stepTextKey="Narsis seems disappointed that we didn't find anything significant down here. I should talk to him."},
		["See What Narsis Plans to Do"] =
			{appendText="."},
		[6] = 
			{appendStepText="The Dreloth Ancestral Tomb is in the Azura's Coast region, far south of the eastern city of Sadrith Mora. In the tomb, the great explorer pushed a switch and a door unlocked. ", stepTextKey="I should follow Narsis Dren and listen to what he has to say."},
		["Follow Narsis Dren"] =
			{appendText=" to the west, through the door."},
		[7] = 
			{appendStepText="At the Dreloth Ancestral Tomb in the Azura's Coast region, far south of the eastern city of Sadrith Mora, ", stepTextKey="Narsis made a significant discovery and ran off, telling me to talk to his assistant back outside the Dreloth tomb. Unfortunately, he also accidentally called forth a monster and left me to deal with it. Thanks, Narsis!"},
		["Meet Elfbetta Outside the Tomb"] =
			{appendText=" at their camp, to the northeast if I use the nearby southwestern exit."},
		[8] = 
			{appendStepText="At the Dreloth Ancestral Tomb, ", stepTextKey="Elfbetta said that Narsis went to the Veloth Ancestral Tomb, clear across Vvardenfell. It's on the western coast, just south of Gnisis. I should head there and see if Narsis needs any more help."},
		["Go to Veloth Ancestral Tomb"] =
			{appendText=", southeast of Gnisis Wayshrine along the coastal road in the northwestern area. It is northwest of West Gash Wayshrine, west of the intersection of the coastal road with the main road."},
		[9] = 
			{appendStepText="In the northwestern West Gash region, southeast of Gnisis Wayshrine and northwest of West Gash Wayshrine on the coastal road, I found the ancestral tomb Elfbetta mentioned. ", stepTextKey="I should enter the Veloth Ancestral Tomb and see if I can locate Narsis Dren."},
		["Find Narsis Dren In Veloth Ancestral Tomb"] =
			{appendText=". Braziers burn at the doorway with a traveler's cart nearby. He shouldn't be far into the tomb yet."},
		[10] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. Already, ", stepTextKey="Narsis Dren managed to lock himself behind a door in the Veloth tomb's first chamber, but I managed to set him free. I should talk to him."},
		["Talk to Narsis Dren 2"] =
			{appendText=" in the large southern chamber of the tomb.", stepTextKey="Narsis Dren managed to lock himself behind a door in the Veloth tomb's first chamber, but I managed to set him free. I should talk to him."},
		[11] = 
			{appendStepText="Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. ", stepTextKey="Narsis Dren insists that hidden passages in the Veloth tomb lead to historic relics and untold treasure. He wants me to help him search the tomb and find the hidden passage."},
		["Locate the Hidden Passage"] =
			{appendText=" farther into the tomb."},
		[12] = 
			{appendStepText="Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine, ", stepTextKey="We arrived at what looks like the final chamber in the Veloth tomb, but Narsis insists there is more to explore. We just need to locate a hidden passage. I should talk to him."},
		["Talk to Narsis Dren 3"] =
			{appendText=".", stepTextKey="We arrived at what looks like the final chamber in the Veloth tomb, but Narsis insists there is more to explore. We just need to locate a hidden passage. I should talk to him."},
		[13] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. In the large northwestern burial chamber, ", stepTextKey="Narsis wants me to examine the harp that stands on a pedestal in a prominent location in the chamber. It might reveal a clue as to how to find the entrance to the hidden passages."},
		["Find a Hidden Passage"] =
			{appendText=". I should read the open book and then look at the harp. There are ancient objects in the circular sand."},
		[14] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. In the northwestern burial chamber, ", stepTextKey="I solved the puzzle and revealed the entrance to the hidden passages Narsis was looking for. Of course, he ran ahead. I should follow him and enter the Undertomb."},
		["Enter the Undertomb"] =
			{appendText=" through the door behind the harp on the pedestal."},
		[15] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. ", stepTextKey="Narsis was right about there being a hidden section of Veloth tomb. I should talk to him and see how he wants to proceed."},
		["Talk to Narsis Dren 4"] =
			{appendText=". He raced into the Veloth Undertomb.", stepTextKey="Narsis was right about there being a hidden section of Veloth tomb. I should talk to him and see how he wants to proceed."},
		[16] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. From the northwestern chamber in the main tomb, we entered the Undertomb. ", stepTextKey="Narsis thinks the Undertomb must contain a valuable treasure. I agreed to help him find it."},
		["Find the Treasure"] =
			{appendText=". Narsis ran off again. I should search the passages as I head for the southern areas. And I should speak with Narsis from time to time along the way."},
		[17] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. We went through the main tomb, entered the Undertomb and continued south through the Mausoleum. In the far southern chamber we discovered a grid of lettered floor tiles. ", stepTextKey="To proceed deeper into the tomb, we need to open the locked gate. Narsis thinks the stone tiles set into the floor form a locking mechanism of some sort. We just need to solve the puzzle to move forward."},
		["Solve the Floor Puzzle"] =
			{appendText=". There must be a pattern of Daedric letters that I should follow. Now to find a clue about the letters to use."},
		[18] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road southeast of Gnisis Wayshrine. In the southernmost chamber of the Undertomb, I did it. ", stepTextKey="Solving the unusual Daedric puzzle revealed a golden skull in a hidden chamber. Narsis grabbed it and another passage opened. I should talk to Narsis and see what he thinks of all this."},
		["Talk to Narsis Dren 5"] =
			{appendText=" near the puzzle room.", stepTextKey="Solving the unusual Daedric puzzle revealed a golden skull in a hidden chamber. Narsis grabbed it and another passage opened. I should talk to Narsis and see what he thinks of all this."},
		[19] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. We passed through the tomb's upper area, then went to the southernmost chamber of the Veloth Undertomb. ", stepTextKey="Narsis wants to keep going, deeper into the tomb. I should follow him into the ancient crypt we just uncovered."},
		["Enter the Tomb of the Matriarch"] =
			{appendText=" through the door east of the Undertomb's southernmost chamber."},
		[20] = 
			{appendStepText="Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. I went through the tomb's main areas, then to the Undertomb's southeast area to reach the Tomb of the Matriarch. ", stepTextKey="Narsis is sure there is a treasure room or vault in the ancient crypt beneath the Veloth tomb. I should help him find it."},
		["Find the Treasure Vault"] =
			{appendText=". I should follow Narsis through the caverns."},
		[21] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. I went through the tomb's main areas, then to the Undertomb's southeast area to reach the Tomb of the Matriarch. ", stepTextKey="Narsis entered an old chamber that he believes must be the treasure vault. I should follow him."},
		["Enter the Treasure Vault"] =
			{appendText=" through a door from the northwestern cavern in the Tomb of the Matriarch."},
		[22] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. I went through the tomb's main areas, then to the Undertomb's southeast area to reach the Tomb of the Matriarch. Then through caverns and into the Treasury Vault. ", stepTextKey="This doesn't look like a treasure vault and Narsis is clearly disappointed. I should talk to him."},
		["Talk to Narsis Dren 6"] =
			{appendText=".", stepTextKey="This doesn't look like a treasure vault and Narsis is clearly disappointed. I should talk to him."},
		[23] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. ", stepTextKey="I should head back outside and let Elfbetta know that I helped Narsis complete another amazing adventure."},
		["Talk to Elfbetta 1"] =
			{appendText="."},
		[24] = 
			{appendStepText="The Veloth Ancestral Tomb is on the northwest's coastal road between Gnisis Wayshrine and West Gash Wayshrine. ", stepTextKey="I should head back outside and let Elfbetta know that Narsis isn't doing well."},
		["Talk to Elfbetta 2"] =
			{appendText="."},
	},


	[GetQuestName(5836)] = { --"Bound by Love"				--Jordakai
		[1] = 
			{appendStepText="When I spoke with him in the eastern city of Sadrith Mora, ", stepTextKey="Llonas asked me to inquire about purchasing Tirwin from Faras and discover what it would take for her to part with her slave."},
		["Talk to Faras Givyn"] =
			{appendText=" at her Telvanni mushroom tower in the southeast area of the city."},
		[2] = 
			{appendStepText="In front of her southeastern Telvanni tower in the eastern city of Sadrith Mora, I learned ", stepTextKey="Faras Givyn demands Red Star Shells for Tirwin. I should inform Llonas of what I learned."},
		["Tell Llonas Givyn His Mother's Price for Tirwin"] =
			{appendText=". He has wandered southeast from the city, standing near a roped path with Telvanni lanterns."},
		[3] = 
			{appendStepText="I found Llonas on a roped, illuminated path, southeast of the eastern city of Sadrith Mora. ", stepTextKey="Llonas loaned me a nix hound he's trained to sniff out Red Star Shells. When the creature points to the location of a shell, all I have to do is dig."},
		["Collect Red Star Shells"] =
			{appendText=" \n\nNixxie can help me find the shell mounds. I should walk the shores to the southwest, watching for the trained nix-hound. Skittish Nixxie may wander off as I search."},
		[4] = 
			{appendStepText="West of Tel Galen, a residence south of the eastern city of Sadrith Mora, not far from a Daedric ruin, ", stepTextKey="I finished collecting shells for Llonas, but a High Elf appeared as I was leaving. She wants to talk."},
		["Talk to Tirwin 1"] =
			{appendText=".", stepTextKey="I finished collecting shells for Llonas, but a High Elf appeared as I was leaving. She wants to talk."},
		[5] = 
			{appendStepText="West of Tel Galen, a residence south of the eastern city of Sadrith Mora, ", stepTextKey="I met Tirwin and she expressed her desire to escape from Faras and Llonas both. She's asked me to steal her Servitude Obligation from Faras for her. Alternatively, I already have the shells Llonas needs. Perhaps I should speak to him about all this."},
		["Agree to Buy Tirwin for Llonas Givyn"] =
			{appendText=". He is waiting with Nixxie on the city's eastern road near the Gateway Inn.\n"},
		["Steal Tirwin's Servitude Obligation"] =
			{appendText=". The document is in Faras Givyn's Telvanni tower in the southeast area of the city. It is likely in the basement, entered through a trapdoor on the main floor. I should look for an illuminated book nook."},
		[6] = 
			{appendStepText="In the eastern city of Sadrith Mora, ", stepTextKey="I stole Tirwin's Servitude Obligation. She'll be happy to hear that. I just need to deliver it to her."},
		["Give Servitude Obligation to Tirwin"] =
			{appendText=". She is oustide Fedoro's Place, east of the city's Fighter's Guild Encampment."},
		[7] = 
			{appendStepText="In the eastern city of Sadrith Mora, I found Tirwen. ", stepTextKey="I gave Tirwin the Servitude Obligation, but it looks like she wants to say something to me before she departs. I should speak to her."},
		["Talk to Tirwin 2"] =
			{appendText=" east of the city's southern Fighter's Guild Encampment, outside Fedoro's Place.", stepTextKey="I gave Tirwin the Servitude Obligation, but it looks like she wants to say something to me before she departs. I should speak to her."},
		[8] = 
			{appendStepText="In the eastern city of Sadrith Mora, I spoke with Llonas. ", stepTextKey="I agreed to continue with Llonas's plan to obtain Tirwin's freedom. Now I only need to complete the slave deal with Faras."},
		["Trade Shells to Faras Givyn"] =
			{appendText=", in front of her Telvanni tower home in the city's southeast."},
		[9] = 
			{appendStepText="In front of Givyn's House, the Tevlanni mushroom tower in southeast Sadrith Mora, ", stepTextKey="I completed the transaction for Tirwin with Faras. Llonas has arrived, with Tirwin in tow, to take the contract. I don't know what he's planning, but my part in this ends when I hand it over to him."},
		["Give Llonas Tirwin's Servitude Obligation"] =
			{appendText="."},
	},

    [GetQuestName(5876)] = { --"A Dangerous Breed"				--Jordakai
        [1] = 
            {appendStepText="While exploring the Azura'a Coast region, north of many ruins and west of the scenic Holamayan Monastery island, I noticed a dock. I followed a path under a natural arch to a mine. ", stepTextKey="I must venture into the Matus-Akin Egg Mine to find Drovos Nelvayn and his new, dangerous breed of kwama."},
        ["Enter Matus-Akin Egg Mine"] =
            {appendText=" near Ridena Devani, the House Hlaalu kwama expert I spoke with."},
        [2] = 
            {appendStepText="In the egg mine near a dock, west of scenic Holamayan Monastery and far south of Sadrith Mora, ", stepTextKey="I must destroy the Matus-Akin royal egg, wipe out the scribs that were bred to tend it, and slay the mad breedsman, Drovos Nelvayn."},
        ["Destroy the Royal Egg"] =
            {appendText=" in the northwesternmost cavern of the egg mine."},
        ["Kill Drovos Nelvayn"] =
            {appendText=" at his camp in the lower western cavern, south of the Royal Egg's northwesternmost cavern."},
        ["Wipe Out the Scribs-In-Waiting"] =
            {appendText=" in the far southwestern cavern of the mine."},
        [3] = 
            {appendStepText="In the egg mine near a dock, west of scenic Holamayan Monastery and far south of Sadrith Mora, ", stepTextKey="I wiped out the Matus-Akin kwama and killed the Dark Elf who created them. I should return to Ridena Devani and inform her of my success."},
        ["Talk to Ridena"] =
            {appendText=", standing outside near the egg mine's entrance."},
    },

	[GetQuestName(5964)] = { --"A Web of Troubles"				--Jordakai
		[1] = 
			{appendStepText="At her camp east of Vivec City on the southern shores of Azura's Coast, ", stepTextKey="Lady Laurent asked me to see if I could locate her missing research assistants. While I search the vicinity of the ruins, she also asked me to keep an eye out for her man-servant, Stibbons."},
		["Find the Missing Mages"] =
			{appendText=" at the Daedric ruin of Bal Fell, on the rocky island south of her ladyship's camp."},
		[2] = 
			{appendStepText="East of Vivec City, on the island with a snaking trail in the Daedric ruins of Bal Fell, ", stepTextKey="I found one of Lady Laurent's missing assistants. He rambled on about spiders and dancing. He said that Lady Laurent's man-servant, Stibbons, dropped a pouch nearby. Perhaps that's the start of a trail I can follow."},
		["Find the Start of Stibbons's Trail"] =
			{appendText=". Mehdbeq, the overwrought mage near the waters edge, pointed me east towards a large mushroom in the nearby rocks."},
		[3] = 
			{appendStepText="East of Vivec City, on the island with a snaking trail near the Daedric ruins of Bal Fell, I found a spice pouch near a mushroom in the rocks at the waters edge. ", stepTextKey="Stibbons must have dropped items as he fled. If I follow the trail of items, I should find Stibbons."},
		["Find the Next Dropped Item"] =
			{appendText=". I suspect that whoever or whatever captured Stibbons headed northeast from the mushroom, up the hill to the illuminated Daedric ruin."},
		[4] = 
			{appendStepText="", stepTextKey="Stibbons must have dropped items as he fled. If I follow the trail of items, I should find Stibbons."},
		["Find the Last Dropped Item"] =
			{appendText=". A spice bag and an Investigator Vale book. What's next? A bowl of soup for a cozy evening of reading? A bowl, maybe it is a bowl.\nI should continue searching the ruins, perhaps checking around the grounds outside of the northern walls, too."},
		[5] = 
			{appendStepText="East of Vivec City, on the island with a snaking trail, outside the northwest wall,  ", stepTextKey="I found Stibbons in the ruins of Bal Fell. I should talk to him and see if he's all right."},
		["Talk to Stibbons"] =
			{appendText=" as he hides behind a giant mushroom."},
		[6] = 
			{appendStepText="East of Vivec City, on the island with a snaking trail at the Daedric ruins, I spoke with Stibbons near a giant mushroom. ", stepTextKey="Another of the mages hired by Lady Laurent is with Stibbons. I should talk to this mage and try to learn more about what's happening at these ruins."},
		["Talk to Dralane Elarven"] =
			{appendText=", a female Dunmer sitting on the ground at the base of the giant mushroom by the northern wall."},
		[7] = 
			{appendStepText="East of Vivec City, on the island with a snaking trail in the Daedric ruins, near a giant mushroom by the north wall, I was speaking with Dralane. ", stepTextKey="The mage ranted about spiders and ran off. I should follow her and see where she's going."},
		["Follow Dralane Elarven"] =
			{appendText=" around the wall, into the ruins, and to the warded entrance of Bal Fell."},
		[8] = 
			{appendStepText="East of Vivec City, on the island with a snaking trail in the Daedric ruins of Bal Fell, I stand at the entrance. ", stepTextKey="The mage entered the ruins, but there appears to be a magical barrier that I can't pass through. I should return to Stibbons and use the signal wand to summon Lady Laurent."},
		["Signal Lady Laurent"] =
			{appendText=" with Stibbons. He is still at the giant mushroom by the northwest wall."},
		[9] = 
			{appendStepText="East of Vivec City, on the island with a snaking trail in the Daedric ruins, at the giant mushroom by the northwest wall, ", stepTextKey="Lady Laurent arrived in response to my use of the signal wand. I should talk to her and let her know what I've discovered so far."},
		["Talk to Lady Laurent 1"] =
			{appendText=".", stepTextKey="Lady Laurent arrived in response to my use of the signal wand. I should talk to her and let her know what I've discovered so far."},
		[10] = 
			{appendStepText="East of Vivec City, at her camp just northwest of the Daedric ruins on the island with the snaking trail, ", stepTextKey="Lady Laurent will brew a potent tea so that Stibbons can follow the spider's voices and open the way into the ruins. Meanwhile, she asked me to capture a tiny spider we can use to test if her tea is potent enough to keep him from fainting."},
		["Capture a Mind Spider"] =
			{appendText=" at the ruins of Bal Fell. The small arachnids may be near the webs up on the higher platforms."},
		[11] = 
			{appendStepText="East of Vivec City, on the island with the snaking trail, ", stepTextKey="I captured one of the strange spiders from the ruins. I should return to Lady Laurent's camp so we can test the potency of her tea."},
		["Return to Lady Laurent's Camp 1"] =
			{appendText=", northwest of the ruins.", stepTextKey="I captured one of the strange spiders from the ruins. I should return to Lady Laurent's camp so we can test the potency of her tea."},
		[12] = 
			{appendStepText="East of Vivec City, I returned to Lady Laurent's camp from the ruins on the island with the snaking trail. ", stepTextKey="The captured spider is in my backpack. I should release it to see if Stibbons faints or if Lady Laurent's tea is potent enough for him to retain his senses."},
		["Release Spider at Camp"] =
			{appendText="."},
		[13] = 
			{appendStepText="East of Vivec City, from Lady Laurent's camp, Stibbons headed for the ruins on the island with the snaking trail. ", stepTextKey="We need to follow Stibbons to the ruins and hope the tea is strong enough to keep him awake long enough for us to get through the barrier."},
		["Follow Stibbons"] =
			{appendText=" to the Daedric ruin."},
		[14] = 
			{appendStepText="East of Vivec City, on the island with the snaking trail, ", stepTextKey="Stibbons heard the spiders and the tea prevented him from fainting. When he passed through the barrier, the path was opened and Lady Laurent followed him inside. I should enter the ruins to help them."},
		["Enter Bal Fell"] =
			{appendText="."},
		[15] = 
			{appendStepText="East of Vivec City, on the island with the snaking trail, we followed Stibbons into the Daedric ruin. ", stepTextKey="Lady Laurent appears to have found something. I should talk to her to learn more."},
		["Talk to Lady Laurent 2"] =
			{appendText=" in the entry hallway of Bal Fell.", stepTextKey="Lady Laurent appears to have found something. I should talk to her to learn more."},
		[16] = 
			{appendStepText="East of Vivec City, in the Daedric shrine of Bal Fell on the island with the snaking trail, ", stepTextKey="Lady Laurent wants me to interrupt the ritual and make Stibbons and the others stop dancing. I assume that will involve dealing with the Daedric priest."},
		["Stop the Ritual"] =
			{appendText="."},
		[17] = 
			{appendStepText="East of Vivec City, in the Daedric ruins of Bal Fell, ", stepTextKey="I stopped the ritual and broke the spell that was making Stibbons and the others dance. Now I need to return to Lady Laurent's camp."},
		["Return to Lady Laurent's Camp 2"] =
			{appendText=".", stepTextKey="I stopped the ritual and broke the spell that was making Stibbons and the others dance. Now I need to return to Lady Laurent's camp."},
		[18] = 
			{appendStepText="East of Vivec City, ", stepTextKey="I made it back to the camp. I should talk to Lady Laurent and make sure everyone is all right."},
		["Talk to Lady Laurent 3"] =
			{appendText=".", stepTextKey="I made it back to the camp. I should talk to Lady Laurent and make sure everyone is all right."},
		[19] = 
			{appendStepText="", stepTextKey="I saved Lady Laurent's apprentices and man-servant from the clutches of a Daedric priest. She found some scrolls in the ruins, however, and wants Stibbons to read them. I don't know if that's wise, but I should talk to her and collect my reward."},
		["Talk to Lady Laurent 4"] =
			{appendText=" at her camp east of Vivec City on the southern shores of Azura's Coast.", stepTextKey="I saved Lady Laurent's apprentices and man-servant from the clutches of a Daedric priest. She found some scrolls in the ruins, however, and wants Stibbons to read them. I don't know if that's wise, but I should talk to her and collect my reward."},
	},

	[GetQuestName(5920)] = { --"Breaking Through the Fog"				--Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Sergeant Delms was on duty the night the light went dark. I should start my investigation by speaking to him."},
		["Talk to Sergeant Delms"] =
			{appendText=". He is stationed at the top of the town's lighthouse, keeping watch over its flaming brazier."},
		[2] = 
			{appendStepText="I spoke with a House Guard at the town's lighthouse. ", stepTextKey="Sergeant Delms said the entire watch was indisposed that night after celebrating their captain's birthday. Delms thinks Cherishes-Water might have seen something, though. I should talk to her."},
		["Talk to Cherishes-Water"] =
			{appendText=", a female Argonian, as she relaxes in the shallow water of the pond north of the town's lighthouse."},
		[3] = 
			{appendStepText="I found the female Argonian in the pond north of the lighthouse. ", stepTextKey="Cherishes-Water refuses to tell me what she knows unless I bring her Findun's Special Blend for her pond. I can gather some where the sea tide meets the swamp water, or I can buy it from Findun's Goods in Seyda Neen."},
		["Acquire Findun's Special Blend"] =
			{appendText=". \nFindun's merchant shop is by the pond, next to the town's small bridge that leads to the wayshrine. \nNear the town's Silt Strider tower, mushrooms grow on a dead tree trunk that has fallen across the inlet that nourishes the pond."},
		[4] = 
			{appendStepText="", stepTextKey="I obtained some of Findun's Special Blend.  I should pour it into Cherishes-Water's pond so she'll tell me what she saw the night of the shipwreck."},
		["Pour Findun's Special Blend"] =
			{appendText=" into the pond water close to Cherishes-Water."},
		[5] = 
			{appendStepText="", stepTextKey="Cherishes-Water felt someone sneak through the pond and stop at the tree on the far side before heading in the direction of the lighthouse. I should search the tree and see what I can find."},
		["Search the Tree"] =
			{appendText=" hollow in the large tree at the edge of the town's pond, near Findun's Goods."},
		[6] = 
			{appendStepText="At the edge of the pond north of the lighthouse, ", stepTextKey="I found a ruby and a note in the tree. The note addresses the saboteur and ends with a pass phrase containing the word ALMSIVI.  I should use the pass phrase on various townsfolk and see if I get a response."},
		["Ask Townsfolk About ALMSIVI"] =
			{appendText="."},
		[7] = 
			{appendStepText="", stepTextKey="I discovered that Marise Rothrano sabotaged the lighthouse. She believes she is working for the Tribunal. I should tell Deminah Salvi what I've learned."},
		["Talk to Deminah Salvi 1"] =
			{appendText=". She is on the fore-deck of the ship at the town's long, main dock.", stepTextKey="I discovered that Marise Rothrano sabotaged the lighthouse. She believes she is working for the Tribunal. I should tell Deminah Salvi what I've learned."},
		[8] = 
			{appendStepText="", stepTextKey="Deminah Salvi thinks the note is written on a sheet of the governor's special parchment, but she needs a sample to be sure. I can steal a sheet from the governor's private quarters in the guard tower or I can trick Marise into stealing it for me."},
		["Steal the Governor's Parchment"] =
			{appendText=". The Guard House by the docks probably has a guard on duty inside.\n"},
		["Ask Marise to Steal the Parchment"] =
			{appendText=". She should still be at Findun's Goods, the merchant shop in town. I'll see if I can persuade her to help."},
		[9] = 
			{appendStepText="", stepTextKey="I convinced Marise to steal a sheet of the governor's parchment. She wants me to distract the guard in front of the guard house so she can sneak inside."},
		["Distract the Tower Guard"] =
			{appendText=" standing at the door of the town's Guard House, not far from the long, main dock."},
		[10] = 
			{appendStepText="At the Guard House, I distracted Sergeant Delms. Now ", stepTextKey="I should meet Marise at the tree at the end of the lighthouse's dock so I can collect whatever she finds in the governor's private quarters."},
		["Meet Marise at the Rendezvous"] =
			{appendText=". Perhaps I should sneak to make this look good."},
		[11] = 
			{appendStepText="I entered the Governor's private quarters. ", stepTextKey="While obtaining a sheet of the governor's special parchment, I noticed an unfinished report nearby. I should read the report before I head back to Deminah Salvi."},
		["Read the Unfinished Report"] =
			{appendText=" on the table by the desk."},
		[12] = 
			{appendStepText="", stepTextKey="I acquired a sheet of the governor's special parchment and also learned about a report that assured there was no slaver activity on Firemoth Island. I should bring the parchment to Deminah Salvi and tell her what I discovered."},
		["Talk to Deminah Salvi 2"] =
			{appendText=". She waits on the fore-deck of the large ship at the town's long, main dock.", stepTextKey="I acquired a sheet of the governor's special parchment and also learned about a report that assured there was no slaver activity on Firemoth Island. I should bring the parchment to Deminah Salvi and tell her what I discovered."},
		[13] = 
			{appendStepText="", stepTextKey="Deminah Salvi threw me in a cell for stealing Nivel Omellian's Ordinator helm. Luckily, Marise Rothrano freed me and said Deminah Salvi headed to Firemoth Island. I should follow her and see if I can redeem myself."},
		["Escape the Guard House"] =
			{appendText=" and take the largest ship at the long, main dock to Firemoth Island."},
		[14] = 
			{appendStepText="", stepTextKey="A distress signal fired from Firemoth Island indicates that something is happening there. I need to get to the island, rescue the captured prisoners, and find evidence confirming Governor Omellian's involvement."},
		["Rescue Slaves"] =
			{appendText=" \n\n"},
		["Search for Evidence"] =
			{appendText=". Some kind of document would be very helpful. \nI must pilot the largest ship at the long, main dock using the wheel on the lower deck to reach the island."},
		[15] = 
			{appendStepText="", stepTextKey="I freed the captives on Firemoth Island and found a letter from the slaver captain. It indicated that the governor was involved and tried to clean up behind him by having the captain assassinated. I should report back to Deminah Salvi in Seyda Neen."},
		["Talk to Deminah Salvi 3"] =
			{appendText=". She may be confronting the Governor. I should enter the Census and Excise Office at the main dock and then enter the Governor's Office.", stepTextKey="I freed the captives on Firemoth Island and found a letter from the slaver captain. It indicated that the governor was involved and tried to clean up behind him by having the captain assassinated. I should report back to Deminah Salvi in Seyda Neen."},
	},


    [GetQuestName(5881)] = { --"A Hidden Harvest"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should venture into Zainsipilu to take stock of the bandit infestation."},
        ["Enter Zainsipilu"] =
            {appendText=", northwest of Seyda Neen Wayshrine, near a campfire on the coastal road."},
        [2] = 
            {appendStepText="Northwest of Seyda Neen Wayshrine, near a campfire on the coastal road, ", stepTextKey="I entered Zainsipilu. Now I should search for Halinjirr's notes and the plant toxin he mentioned."},
        ["Obtain Halinjirr's Toxin"] =
            {appendText=" from the secluded southwestern cavern.\n"},
        ["Find Halinjirr's Notes"] =
            {appendText=". He left his book near the northern waterfall in the large central cavern."},
        [3] = 
            {appendStepText="I found Halinjirr's notes and his sugar toxin in Zainsipilu, near the coastal road northwest of Seyda Neen Wayshrine. ", stepTextKey="I should pour the toxin I found into the underground spring. That should destroy Halinjirr's captured crop."},
        ["Poison the Crop"] =
            {appendText=". The Underground Spring is up the middle stream in the pool on the west side of the main cavern."},
        [4] = 
            {appendStepText="In Zainsipilu, near the coastal road northwest of Seyda Neen Wayshrine, ", stepTextKey="I claimed the missing notes and poisoned the crops. I should return to Halinjirr to inform him of my success."},
        ["Leave Zainsipilu"] =
            {appendText="."},
        [5] = 
            {appendStepText="Near the coastal road northwest of Seyda Neen Wayshrine, ", stepTextKey="Halinjirr's farmhand, Falura, beckoned me over. I should speak with her."},
        ["Talk to Falura"] =
            {appendText=", a female Dunmer, near the campfire outside Zainsipilu."},
        [6] = 
            {appendStepText="Near Zainsipilu, ", stepTextKey="Falura urged me to report Halinjirr to the authorities. I should speak with him to verify Falura's claims."},
        ["Talk to Halinjirr 1"] =
            {appendText=", the Khajiit on the road southeast of Zainsipilu and north of Seyda Neen Wayshrine.", stepTextKey="Falura urged me to report Halinjirr to the authorities. I should speak with him to verify Falura's claims."},
        [7] = 
            {appendStepText="", stepTextKey="I decided to keep Halinjirr's activities in Zainsipilu a secret. I should bid him farewell."},
        ["Talk to Halinjirr 2"] =
            {appendText=", the Khajiit on the road north of Seyda Neen Wayshrine and southeast of Zainsipilu.", stepTextKey="I decided to keep Halinjirr's activities in Zainsipilu a secret. I should bid him farewell."},
        [8] = 
            {appendStepText="", stepTextKey="I decided to report Halinjirr to Captain Bethes in Seyda Neen. I should track this officer down and tell him about what I discovered."},
        ["Talk to Captain Bethes"] =
            {appendText=". The Watch captain should be near the center of town."},
    },

    [GetQuestName(5857)] = { --"A Smuggler's Last Stand"				--Jordakai
        [1] = 
            {appendStepText="I spoke with Nakhul, an Orc, on the small dock at Khartag Point on the Bitter Coast south of Gnisis and far north of Seyda Neen. ", stepTextKey="I should enter the nearby cavern to search for Khartag and the missing slaves."},
        ["Enter Khartag Point"] =
            {appendText=". Nakhul warned me about members of the Camona Tong, a powerful crime family, being in the cavern."},
        [2] = 
            {appendStepText="On the Bitter Coast, south of Gnisis and far north of Seyda Neen, ", stepTextKey="I entered the cavern at Khartag Point. I must try to find the three slaves Nakhul mentioned, then find Khartag."},
        ["Find Mabkir"] =
            {appendText=". I should start my search in the cavern's eastern passageway and check any side tunnels I find."},
        ["Find Jaree-Eeto"] =
            {appendText=", hiding in a northern cavern on the west side, up on a ledge, avoiding the Camona Tong."},
        ["Find Wih-Waska"] =
            {appendText=", secluded in the watery northeastern cavern."},
        ["Find Khartag"] =
            {appendText=". If he is alive, he is probably up on the ledge north of the cavern's entrance. I will need to circle around through the tunnels to reach him."},
        [3] = 
            {appendStepText="On the Bitter Coast, south of Gnisis and far north of Seyda Neen, ", stepTextKey="Khartag succumbed to his wounds and perished in the cavern. I should return to Nakhul and deliver Khartag's final words."},
        ["Talk to Nakhul"] =
            {appendText=", the Orc. He is with the surviving slaves on the dock at Khartag Point."},
    },

    [GetQuestName(5841)] = { --"At Any Cost"				--Jordakai
        [1] = 
            {appendStepText="In Tel Mora, east of Vos, Mistress Dratha's Mouth, Llayne Sadri, helped me make a list for my journal. ", stepTextKey="According to Mistress Dratha, the Stones of Cold Fire are hidden away in seven Daedric shrines: Ashalmawia, Bal Ur, Esutanamus, Kushtashpi, Ramimilk, Yansirramus, and Tusenend. I must seek out these shrines and claim one stone from each."},
        ["Retrieve the Stones of Cold Fire"] =
            {appendText=", named for their appearance.\n\nI will need to explore many parts of Vvardenfell, searching these Daedric ruins:\n- Ashalmawia is north of Gnisis, southwest of Urshilaku Wayshrine. Its Stone is deep in its shrine.\n- Bal Ur is on a river, north of Suran. The Stone is in its shrine.\n- Esutanamus is on an island southeast of Vos. Its Stone is outdoors, high up on a platform.\n- Kushtashpi is on the coast northwest of Vos. The Stone is on the upper, northernmost platform.\n- Ramimilk is by a foyada southeast of Ald'ruhn. Its Stone is inside the shrine.\n- Tusenend is north of Molag Mar, east of Nchuleftingth. The Stone is wihin its shrine.\n- Yansirramus is on an island west of Sadrith Mora. Its Stone may be in use by Dremora, outdoors on an elevated platform.\n\nI'll keep each Stone I find in my pack. Wayshrines, boats, and Silt Strider caravaners may help me in my travels."},
        [2] = 
            {appendStepText="", stepTextKey="I retrieved all seven Stones of Cold Fire. Now I must deliver them to Mistress Dratha in Tel Mora."},
        ["Talk to Mistress Dratha 1"] =
            {appendText=" in Tel Mora, her Telvanni tower east of Vos.", stepTextKey="I retrieved all seven Stones of Cold Fire. Now I must deliver them to Mistress Dratha in Tel Mora."},
        [3] = 
            {appendStepText="I returned to Tel Mora, east of Vos. ", stepTextKey="In order to use the Stones of Cold Fire, Mistress Dratha needs me to weaken a Dremora hidden away in the realm of Oblivion. I should go through the portal to find this Daedra."},
        ["Enter the Portal"] =
            {appendText=" on the main floor of the tower to the Prison of Xykenaz."},
        [4] = 
            {appendStepText="From the portal Mistress Dratha opened in her Tel Mora tower east of Vos, ", stepTextKey="I arrived in Oblivion. I must defeat the vile Dremora, Xykenaz."},
        ["Defeat Xykenaz"] =
            {appendText=" in his prison."},
        [5] = 
            {appendStepText="In his prison, ", stepTextKey="I defeated Xykenaz. I should enter Mistress Dratha's portal and return to Nirn."},
        ["Return to Tel Mora"] =
            {appendText=" through the glowing white portal."},
        [6] = 
            {appendStepText="From Xykenaz' prison in Oblivion, ", stepTextKey="I returned safely to Tel Mora. I should talk to Mistress Dratha."},
        ["Talk to Mistress Dratha 2"] =
            {appendText=" in her tower east of Vos.", stepTextKey="I returned safely to Tel Mora. I should talk to Mistress Dratha."},
        [7] = 
            {appendStepText="", stepTextKey="I completed all of Mistress Dratha's tasks. I should talk to her to receive my reward."},
        ["Talk to Mistress Dratha 3"] =
            {appendText=" in her tower of Tel Mora, east of Vos.", stepTextKey="I completed all of Mistress Dratha's tasks. I should talk to her to receive my reward."},
    },

    [GetQuestName(5835)] = { --"If the Spell Fits"				--Jordakai
        [1] = 
            {appendStepText="Northwest of Tel Aruhn and Sadrith Mora, south of Vos, in the Grazelands, I found a nearly naked Nord. ", stepTextKey="I should look for Stromgruf's witch. He thinks she's probably somewhere back the way he came. He suggested I might be able to follow the trail of bottles she threw at him as he fled."},
        ["Search for the Witch"] =
            {appendText=", a female Dunmer. I should search the ground for bottles of mead, going west, through brush, a burned patch, and then to a small campfire, just east of the big bend in the road."},
        [2] = 
            {appendStepText="At a small campsite, east of Pulk in the Grazelands, ", stepTextKey="I followed Stromgruf's trail and located his \"witch,\" Nerise Venim. I should talk to her and get her side of the story."},
        ["Talk to Nerise Venim 1"] =
            {appendText=" near the camfire. She is rather well-dressed for hiking through the wilds.", stepTextKey="I followed Stromgruf's trail and located his \"witch,\" Nerise Venim. I should talk to her and get her side of the story."},
        [3] = 
            {appendStepText="Near her campfire at her camp east of Pulk, I spoke with Stromgruf's \"witch\". ", stepTextKey="Nerise Venim isn't a witch. She's an alchemist who knows a few spells. She hired Stromgruf to escort her safely to Vivec City when the pair were beset by Goblins. Nerise asked me to find the Goblins and recover her stolen pack and sword."},
        ["Locate the Goblin Camp"] =
            {appendText=". Nerise said it is to the northeast. She also mentioned that the chief Goblin took the Nord's pants."},
        [4] = 
            {appendStepText="Northeast of Pulk on a rocky hill with a couple of short Emperor Parisol mushrooms, ", stepTextKey="I located the Goblin camp. Now I should look around and see if I can find Nerise's stolen pack and sword."},
        ["Recover Nerise's Pack"] =
            {appendText=" at an Ancestral Tomb guarded by a strong Goblin.\n"},
        ["Find Nerise's Sword"] =
            {appendText=". The fine Elven Sword is probably on the ground, up a hill southwest of Hanud Tower. A hostile Goblin may be protecting it."},
        [5] = 
            {appendStepText="Northeast of Pulk in the rocky hills, ", stepTextKey="I recovered Nerise Venim's stolen possessions from the Goblins. Now I should return to Stromgruf and find out if Nerise has released him from her spell of holding."},
        ["Talk to Stromgruf"] =
            {appendText=", still being held by Nerise's spell, south of the Ancestral Tomb where I found the pack. He is east of Pulk and the campsite, near large boulders, big shade trees, and mushrooms."},
        [6] = 
            {appendStepText="East of Pulk by the boulders, shade trees, and mushrooms, I spoke with the nearly naked Nord again. ", stepTextKey="Apparently, Stromgruf was drunk and tired when he accused Nerise Venim of being a witch. Here she comes now. I should talk to her and return her pack and sword that I recovered from the Goblins."},
        ["Return Items to Nerise Venim"] =
            {appendText="."},
        [7] = 
            {appendStepText="In the Grazelands east of Pulk, near large boulders, big shade trees, and mushrooms, I returned the sword and pack to the Dunmer alchemist. ", stepTextKey=""},
        ["Talk to Nerise Venim 2"] =
            {appendText=" to receive my reward for assisting her.", stepTextKey=""},
    },

	[GetQuestName(5840)] = { --"Reclaiming Vos"				--Jordakai
		[1] = 
			{appendStepText="I arrived at the northeastern city of Vos and its Tel Mora Wayshrine. ", stepTextKey="An Argonian named Gray-Skies encouraged me to talk to Savarak myself. I'll pay this new magistrate a visit."},
		["Talk to Savarak"] =
			{appendText=" Fels at the Gathering House in the center of the city."},
		[2] = 
			{appendStepText="At the northeastern city's Gathering House, ", stepTextKey="Savarak admitted to mistreating the people of Vos. He noted that Mistress Dratha's Mouth, Llayne Sadri, is fomenting unrest from inside the tower, Tel Mora. I should talk to her to get her perspective."},
		["Talk to Llayne 1"] =
			{appendText=" Sadri at Tel Mora, the tall Telvanni mushroom tower east of the city. She is probably on an upper floor with Mistress Dratha.", stepTextKey="Savarak admitted to mistreating the people of Vos. He noted that Mistress Dratha's Mouth, Llayne Sadri, is fomenting unrest from inside the tower, Tel Mora. I should talk to her to get her perspective."},
		[3] = 
			{appendStepText="At Tel Mora, east of the northeastern city of Vos, I spoke with Mistress Dratha's Mouth. ", stepTextKey="Llayne suspects that the truth about Savarak's sudden wealth and power may be hidden away in his manse. I must break into his house and search for any evidence of corruption."},
		["Find Evidence of Corruption"] =
			{appendText=" \n\nSavarak's Manse, the old Berano house, is on the west side of Vos's circular fountain."},
		[4] = 
			{appendStepText="In the northeastern city of Vos, ", stepTextKey="I found an assortment of documents in Savarak's manse: a letter to Savarak from House Hlaalu, a shipping notice directing Black Snails to Selvil Island, and a note pertaining to a secret meeting. I should share my discoveries with Llayne."},
		["Talk to Llayne 2"] =
			{appendText=" Sadri, Mistress Dratha's Mouth, in the Telvanni mushroom tower of Tel Mora, east of Vos near the city's docks.", stepTextKey="I found an assortment of documents in Savarak's manse: a letter to Savarak from House Hlaalu, a shipping notice directing Black Snails to Selvil Island, and a note pertaining to a secret meeting. I should share my discoveries with Llayne."},
		[5] = 
			{appendStepText="In Tel Mora, east of the northeastern city of Vos, ", stepTextKey="Llayne and I hatched a plan to squeeze information out of one of Savarak's co-conspirators, Nerandas. I must travel to the wharf outside Vos and impersonate one of Savarak's henchmen. Nerandas might just share some important information with me."},
		["Meet with Nerandas"] =
			{appendText=" on a small sailing ship at the city's docks near Tel Mora."},
		[6] = 
			{appendStepText="At the docks of the northeastern city of Vos, ", stepTextKey="Nerandas revealed that House Hlaalu conspired with Savarak to poison Mistress Dratha. Apparently, the source of her illness lies at the base of Tel Mora's fungal growth. Now I just need to find it."},
		["Investigate the Base of Tel Mora Tower"] =
			{appendText=" to find the infected area, probably in a place less noticeable, around back on the east side of the tower. The toxin's greenish malignant growth will appear different than the normally tan mushrooms."},
		[7] = 
			{appendStepText="East of the northeastern city of Vos, ", stepTextKey="I found the malignant growth at the base of Tel Mora. I must show it to Llayne so we can plan our next move."},
		["Talk to Llayne 3"] =
			{appendText=" Sadri inside the Telvanni mushroom tower. If she's not on the main floor, she will be up above caring for her Mistress.", stepTextKey="I found the malignant growth at the base of Tel Mora. I must show it to Llayne so we can plan our next move."},
		[8] = 
			{appendStepText="Next to Tel Mora, east of the northeastern city of Vos, the herbalist keeps a shop. ", stepTextKey="Llayne urged me to show the malignant growth to a local herbalist named Menwendel. She might know how to heal the towering mushroom and reverse the toxin's effect."},
		["Go to Menwendel's Nursery"] =
			{appendText=", a few paces east of the tower's entrance."},
		[9] = 
			{appendStepText="East of northeastern Vos, next to Tel Mora, ", stepTextKey="Menwendel's nursery appears to have been ransacked. I should speak with Gray-Skies to see if he knows anything about the attack."},
		["Talk to Gray-Skies"] =
			{appendText=". He is still in the lower area of the nursery."},
		[10] = 
			{appendStepText="At the nursery next to Tel Mora, east of northeastern Vos, ", stepTextKey="Gray-Skies told me that the Black Snails took Mendwendel to a hideout south of Tel Mora. Hopefully Mendwendel left some kind of trail I can follow."},
		["Follow Clues to Track Menwendel's Captors"] =
			{appendText=". Southwest of the nursery, I should cross the water. Then continue south along the west bank of the waterway. Gray-Skies mentioned pirate hideouts. Maybe I'll find a Black Snail boat at a dock with a convenient cavern nearby."},
		[11] = 
			{appendStepText="Southeast of the northeastern city of Vos, on the west bank of the waterway, ", stepTextKey="I found the coastal hideout where Nerandas and the Black Snails took Menwendel. I should look for the herbalist."},
		["Search for Menwendel"] =
			{appendText=" the herbalist in Pinsun, an old pirate's cavern near a dock. I should start by checking an eastern alcove just south of the entrance."},
		[12] = 
			{appendStepText="Southeast of the northeastern city of Vos, on the west bank of the waterway in the cavern of Pinsun, ", stepTextKey="I found Menwendel. I should see what she has to say."},
		["Talk to Menwendel 1"] =
			{appendText=" in an alcove, up a few steps and not far from the entrance.", stepTextKey="I found Menwendel. I should see what she has to say."},
		[13] = 
			{appendStepText="Southwest of the northeastern city of Vos, near a dock, lies Pinsun cavern. I spoke with Menwendel, the herbalist. ", stepTextKey="In order to heal the Tel Mora mushroom and Mistress Dratha, Menwendel will need a sample of the Hlaalu conspirators' toxin. She also urged me to deal with Nerendas. Killing him should scatter his forces, but I'll have to find him first."},
		["Find Nerandas"] =
			{appendText=" deeper into the old pirate's hideout of Pinsun."},
		[14] = 
			{appendStepText="Southeast of the northeastern city of Vos, near a dock on the waterway, lies Pinsun. In the southwestern cavern, ", stepTextKey="I found Nerandas. Now I should deal with him."},
		["Defeat Nerandas"] =
			{appendText="."},
		[15] = 
			{appendStepText="Southeast of the northeastern city of Vos, near a dock on the west bank of the waterway, I found Nerandus in the southwestern cavern of Pinsun. ", stepTextKey="I killed Nerandas. Now to find a clue to the toxin's location."},
		["Find a Clue to the Toxin's Location"] =
			{appendText=". It should be in this southwestern area."},
		[16] = 
			{appendStepText="In the southwestern area of Pinsun, the pirate hideout near a dock on the waterway southeast of the northeastern city of Vos, ", stepTextKey="I found a note that described where to find Nerandas's toxin. I should collect a sample for Menwendel."},
		["Gather the Toxin Sample"] =
			{appendText=" from a workshop in the southeastern passageway. It is likely in a glass tube or bottle."},
		[17] = 
			{appendStepText="In Pinsun, ", stepTextKey="I collected a sample of the Nerandas's fungal toxin. I should deliver it to Menwendel in Tel Mora. She'll need it to brew an antidote for Dratha."},
		["Bring the Toxin Sample to Tel Mora"] =
			{appendText=", east of northeastern Vos. It's for the herbalist."},
		[18] = 
			{appendStepText="East of the northeastern city of Vos, ", stepTextKey="I arrived in Tel Mora. I should talk to Menwendel."},
		["Talk to Menwendel 2"] =
			{appendText=" up in Mistress Dratha's Chambers.", stepTextKey="I arrived in Tel Mora. I should talk to Menwendel."},
		[19] = 
			{appendStepText="At Tel Mora, east of the northeastern city of Vos, I delivered the toxin to the herbalist. ", stepTextKey="According to Menwendel, Llayne set off toward Vos with a handful of guardsmen to arrest Savarak. I should track her down to see if she needs my help."},
		["Find Llayne"] =
			{appendText=" Sadri."},
		[20] = 
			{appendStepText="East of the northeastern city of Vos, at Tel Mora's stairs, ", stepTextKey="I found a flustered Llayne. I should find out what troubles her."},
		["Talk to Llayne 4"] =
			{appendText=", standing with a couple of guards.", stepTextKey="I found a flustered Llayne. I should find out what troubles her."},
		[21] = 
			{appendStepText="I spoke with Llayne at Tel Mora. ", stepTextKey="I suspect that Savarak plans to flee Vos via Selvil Island. I must track him down and deal with him before he escapes."},
		["Defeat Savarak"] =
			{appendText=" at Selvil Island, northeast of Tel Mora and the northeastern city of Vos."},
		[22] = 
			{appendStepText="On the far northeastern Selvil Island, ", stepTextKey="I defeated Savarak and thwarted House Hlaalu's attempt to claim Vos and Tel Mora for themselves. I should return to Tel Mora and inform Llayne of our success."},
		["Talk to Llayne 5"] =
			{appendText=" Sadri, Mistress Dratha's Mouth. She is in Tel Mora, the Telvanni tower east of the northeastern city of Vos.", stepTextKey="I defeated Savarak and thwarted House Hlaalu's attempt to claim Vos and Tel Mora for themselves. I should return to Tel Mora and inform Llayne of our success."},
	},


	[GetQuestName(5877)] = { --"An Armiger's Duty"				--Jordakai
		[1] = 
			{appendStepText="At the southeastern town of Molag Mar, ", stepTextKey="I should find Captain Naros at the canton and offer my assistance."},
		["Talk to Captain Naros 1"] =
			{appendText=". She has a desk on the top floor in The Penitent Pilgrim Inn.", stepTextKey="I should find Captain Naros at the canton and offer my assistance."},
		[2] = 
			{appendStepText="At Molag Mar's Penitent Pilgrim Inn, I spoke with a Buoyant Armiger officer. ", stepTextKey="Captain Naros suspects a nearby Ashlander camp is behind the attacks and asked me to search their camp for evidence of their guilt."},
		["Search Ashlander Camp For Evidence"] =
			{appendText="\n\nThe Ashlanders are at the Daedric ruins east of Molag Mar. There may be some sort of written evidence, probably near the large bonfire up on a platform at the south end of the camp, and in a food preparation area in the north end."},
		[3] = 
			{appendStepText="In the Molag Amur region, at their camp in the Daedric ruins east of Molag Mar, ", stepTextKey="I discovered evidence that the Ashlanders are making blood sacrifices, but found nothing conclusive. I should investigate their sacrifice site for any sign of the missing pilgrims."},
		["Search the Ritual Site"] =
			{appendText=" at the south end of the camp, up on a platform with a bonfire, wooden totems, and a round, sacrificial altar."},
		[4] = 
			{appendStepText="East of Molag Mar at the Daedric ruins, I was investigating the camp. ", stepTextKey="An Ashlander discovered me searching the ritual site. He hasn't attacked, so he might cooperate. I should speak to him."},
		["Talk to Ibaal 1"] =
			{appendText=" at the platform at the camp's southern end.", stepTextKey="An Ashlander discovered me searching the ritual site. He hasn't attacked, so he might cooperate. I should speak to him."},
		[5] = 
			{appendStepText="At their camp in the Daedric ruins east of Molag Mar, I spoke with one of the tribe's warriors. ", stepTextKey="Ibaal claims the Ashlanders have not been attacking pilgrims and said some of his own people have also disappeared. We agreed to cooperate and he gave me the locations of pilgrim camps that he found ransacked."},
		["Search Pilgrim Campsites"] =
			{appendText=" \n\nIbaal marked my map with locations north of his camp:\n- There is a rowboat in a rocky cove near a tree. I should look around the boat and nearby tree.\n- There is a boat near a camp, farther north of the Daedric ruins and west across the water from a tall Dwemer site.\n- There is a camp on ashen ground near the rocks in the narrow valley, north of the Molag Mar Wayshrine.\n\nAfter I investigate, I should meet him at the Helan Ancestral Tomb."},
		[6] = 
			{appendStepText="In the rocky Molag Amur area near the wayshrine and northeast of Molag Mar, I investigated three pilgrim sites. ", stepTextKey="What I saw at the campsites adds credence to Ibaal's claim that the Ashlanders aren't responsible. The pilgrims looked like they were devoured by some sort of monster."},
		["Talk to Ibaal 2"] =
			{appendText=", the Ashlander, near the Helan Ancestral Tomb. The burial site is northwest of the wayshrine on the east side of the road after a sharp curve.", stepTextKey="What I saw at the campsites adds credence to Ibaal's claim that the Ashlanders aren't responsible. The pilgrims looked like they were devoured by some sort of monster."},
		[7] = 
			{appendStepText="", stepTextKey="Ibaal claims he's heard strange sounds coming from an ancestor tomb near the camps. He suspects something inside may be responsible for the recent deaths, but won't disturb the tomb. I'll have to investigate myself."},
		["Explore Helan Ancestral Tomb"] =
			{appendText=". The burial site is northwest of the Molag Mar Wayshrine on the east side of the road after a sharp curve."},
		[8] = 
			{appendStepText="I entered Helan Ancestral Tomb, northwest of the Molag Mar Wayshrine near the curve in the road. ", stepTextKey="The sounds coming from the ancestor tomb turned out to be a pilgrim in hiding. He might be able to tell me who has been attacking others like him."},
		["Talk to Baren Maloren"] =
			{appendText="."},
		[9] = 
			{appendStepText="Northwest of the Molag Mar Wayshrine near the curve in the road, ", stepTextKey="I discovered a pilgrim hiding in the ancestor tomb Ibaal lead me to. He claims to have survived an attack by the Ruddy Man, a monster of myth. There is no sign of the creature, so I should lead him to safety."},
		["Lead Baren Out of the Tomb"] =
			{appendText="."},
		[10] = 
			{appendStepText="", stepTextKey="The survivor I found is safe for now. Ibaal will want to know what I learned about the attacks from him."},
		["Talk to Ibaal 3"] =
			{appendText=", standing outside of the tomb near the curve in the road northwest of the Molag Mar Wayshrine.", stepTextKey="The survivor I found is safe for now. Ibaal will want to know what I learned about the attacks from him."},
		[11] = 
			{appendStepText="Northwest of the Molag Mar Wayshrine, near the tomb on the east side of the curved road, the Ashlander and I discussed what we've learned. ", stepTextKey="Ibaal doesn't believe that our culprit is the Ruddy Man, but suggests the tracks might lead us to where our quarry lives."},
		["Search for the Ruddy Man"] =
			{appendText=". It appears that the creature headed west, across the roads and up the ramps towards the mine."},
		[12] = 
			{appendStepText="From the Helan Ancestral Tomb on the east side of the road where it curves northwest of the Molag Mar Wayshrine, we headed west. ", stepTextKey="We followed the tracks to a cliff face near the glass mine and the monster has appeared. I should be ready if it attacks."},
		["Observe the Monster"] =
			{appendText=" high above on the wooden ramps of the mine."},
		[13] = 
			{appendStepText="We are at the ramps of the mine, north of Molag Mar on the west side of the winding trail that curves from the main road and then returns to it. ", stepTextKey="We spotted the monster on the cliffs near the glass mine. It was watching us, but fled when it was detected. I should speak with Ibaal about what we saw."},
		["Talk to Ibaal 4"] =
			{appendText=".", stepTextKey="We spotted the monster on the cliffs near the glass mine. It was watching us, but fled when it was detected. I should speak with Ibaal about what we saw."},
		[14] = 
			{appendStepText="", stepTextKey="I found evidence that a monster, possibly the Ruddy Man, has attacked both pilgrims and Ashlanders on the road by Molag Mar. I should bring my findings to Captain Naros. She mentioned heading to the glass mine, so I should look for her there."},
		["Talk to Captain Naros at the Glass Mine"] =
			{appendText="'s entrance in the valley north of the main east-west road's stub, northwest of Molag Mar. From the road stub, there is a dusty trail leading up the hill to the mine."},
		[15] = 
			{appendStepText="Up the trail from the short stub of road, north of the main east-west road and northwest of Molag Mar, we discussed what I have learned. ", stepTextKey="Captain Naros refuses to believe the monster I discovered is the Ruddy Man, but has agreed to allow me to enter the mine to hunt it and Ibaal has returned from speaking to the Ashlander Wise Women. I should see what he learned."},
		["Take Potion from Ibaal"] =
			{appendText=" and speak with him."},
		[16] = 
			{appendStepText="In the valley north of the main east-west road and northwest of Molag Mar, ", stepTextKey="Ibaal gave me a potion to shatter in the supposed Ruddy Man's lair that should bring the creature out of hiding. First, I must find its den within the glass mine."},
		["Find the Monster's Hiding Spot"] =
			{appendText=" in Dreudarai Glass Mine. I should search the entire mine as there may be hidden survivors, since dreugh use mud cocoons to trap their prey."},
		[17] = 
			{appendStepText="Northwest of Molag Mar, in the Dreudarai Glass Mine a short distance north of the east-west road, I came across a pile of dark mud and bones. ", stepTextKey="I found the monster's lair, but it hasn't revealed itself. Ibaal claimed the potion he gave me would drive the creature out of hiding. I should smash it to force the Ruddy Broodmother into the open."},
		["Kill the Ruddy Man Spawn"] =
			{appendText="."},
		[18] = 
			{appendStepText="", stepTextKey="The monster was ferocious, but I prevailed. It will not harm anyone again. I should let Captain Naros know the true threat has been dealt with."},
		["Talk to Captain Naros 2"] =
			{appendText=" after I finish finding any remaining survivors, in hiding or in mud cocoons. She will be outside the Dreudarai Glass Mine's entrance, a short distance north of the east-west road, and northwest of Molag Mar.", stepTextKey="The monster was ferocious, but I prevailed. It will not harm anyone again. I should let Captain Naros know the true threat has been dealt with."},
		[19] = 
			{appendStepText="Outside the Dreudarai Glass Mine's entrance, a short distance north of the east-west road and northwest of Molag Mar, I spoke with the Buoyant Armiger officer. ", stepTextKey="Captain Naros has accepted that the monster in the mine was the culprit, exonerating the Ashlanders. I should let Ibaal know that our plan worked."},
		["Talk to Ibaal 5"] =
			{appendText=".", stepTextKey="Captain Naros has accepted that the monster in the mine was the culprit, exonerating the Ashlanders. I should let Ibaal know that our plan worked."},
		[20] = 
			{appendStepText="Outside the Dreudarai Glass Mine's entrance, a short distance north of the east-west road and northwest of Molag Mar, I spoke with the Ashlander warrior. ", stepTextKey="Ibaal said he and his kind would be leaving soon. I should say my goodbyes before he returns to the Ashlands."},
		["Talk to Ibaal 6"] =
			{appendText=".", stepTextKey="Ibaal said he and his kind would be leaving soon. I should say my goodbyes before he returns to the Ashlands."},
	},

	[GetQuestName(5886)] = { --"The Heart's Desire"					--Jordakai
		[1] = 
			{appendStepText="Southeast of Red Mountain, south of its wayshrine, ", stepTextKey="I should enter the Dwarven ruin of Nchuleftingth."},
		["Enter Nchuleftingth"] =
			{appendText="."},
		[2] = 
			{appendStepText="", stepTextKey="I arrived in Nchuleftingth. Now I should seek out Neramo's bodyguard and assistant, Vimy Lacroix."},
		["Find Vimy Lacroix"] =
			{appendText=" in the southern chamber of the Nchuleftingth Approach."},
		[3] = 
			{appendStepText="In the barricaded southern chamber of the Nchuleftingth Approach, ", stepTextKey="I found Vimy Lacroix. I should speak to her."},
		["Talk to Vimy Lacroix"] =
			{appendText="."},
		[4] = 
			{appendStepText="In the southern chamber of the Nchuleftingth Approach, ", stepTextKey="Vimy asked me to look for her compatriots, who are scattered through the ruins. I should start by finding Thollidor."},
		["Find Thollidor"] =
			{appendText=". I should use the ramps in the western chamber to get down into the caverns of the Approach. I expect the sharp-eyed Bosmer won't be far from where I enter."},
		[5] = 
			{appendStepText="Just after entering the western lower depths of the Nchuleftingth Approach, ", stepTextKey="I rescued Thollidor. I should keep looking for additional survivors."},
		["Find Tyrnea Stone"] =
			{appendText=". I should head east, down into the larger caverns to search for the female Nord warrior. If she is alive, she may be bound and guarded, probably in a remote place like the platform up in the northern area of the southeastern cavern.", stepTextKey="I rescued Thollidor. I should keep looking for additional survivors."},
		[6] = 
			{appendStepText="Against a northern Dwarven wall in the southeeastern cavern of the lower Nchuleftingth Approach, ", stepTextKey="I rescued Tyrnea Stone. I should keep looking for additional survivors."},
		["Find Kasouda"] =
			{appendText=", a female Redguard. There is an exit from the Approach's southeastern cavern. A Dwarven door leads into the Nchuleftingth Bailey. I should go east into the cavernous Nchuleftingth Ruins. \n\nIn the Ruins' northern area, there is another Dwarven door at the bottom of some stairs. The door leads to the Nchuleftingth Lavaworks. Then, I will follow the Dwemer bridges until I find her, probably to the northeast.", stepTextKey="I rescued Tyrnea Stone. I should keep looking for additional survivors."},
		[7] = 
			{appendStepText="Within Nchuleftingth, ", stepTextKey="I must rescue three of Vimy's compatriots, and recover Neramo's Dwemer control rod."},
		["Retrieve Dwemer Control Rod"] =
			{appendText=". In the northeastern area of the Nchuleftingth Lavaworks, Kasouda encouraged me to continue down a battered Dwarven bridge over the lava to the southeastern area. At the bottom of the bridge, on the eastern wall, is the Dwemer entry to the Nchuleftingth Control Room.", stepTextKey="I must rescue three of Vimy's compatriots, and recover Neramo's Dwemer control rod."},
		[8] = 
			{appendStepText="Deep in the ruins of Nchuleftingth, ", stepTextKey="I set Vimy's compatriots free and recovered Neramo's control rod. I should find him to discuss our next move."},
		["Talk to Neramo 1"] =
			{appendText=". He waits near the southwestern exit hallway of the Nchuleftingth Lavaworks.", stepTextKey="I set Vimy's compatriots free and recovered Neramo's control rod. I should find him to discuss our next move."},
		[9] = 
			{appendStepText="From the lower caverns of the Nchuleftingth Approach, through the Bailey and beyond the Ruins, we retrieved Neramo's rod from a control room off the Lavaworks. Then we left the Lavaworks and returned to the Ruins. It is time. ", stepTextKey="I must defeat Neramo's vile competitor, Artisan Lenarmen."},
		["Defeat Artisan Lenarmen"] =
			{appendText=" in the Nchuleftingth Sanctum. \n\nIts entrance is in the far eastern end of the Nchuleftingth Ruins, up some stairs and through the Nchuleftingth Cathedra door."},
		[10] = 
			{appendStepText="Within the Nchuleftingth Sanctum, off the eastern end of the Ruins, ", stepTextKey="Neramo, Vimy and I defeated Artisan Lenarmen. Now we must find Neramo's prize, the Bthark Prism."},
		["Retrieve the Bthark Prism"] =
			{appendText=" from a Dwarven Strongbox in the northern chamber of the Sanctum."},
		[11] = 
			{appendStepText="", stepTextKey="I retrieved the Bthark Prism from the Dwarven vault. I should return to the surface to inform Neramo and Vimy of our success."},
		["Return to the Surface"] =
			{appendText=" from the Nchuleftingth Sanctum. There is a passage through doors on the northern chamber's west wall. I should see what I can learn about this place before leaving."},
		[12] = 
			{appendStepText="", stepTextKey="I finally escaped from the Dwarven ruin of Nchuleftingth. I should deliver the Bthark Prism to Neramo."},
		["Talk to Neramo 2"] =
			{appendText=" at his expedition's campsite near the main entrance to the ruins.", stepTextKey="I finally escaped from the Dwarven ruin of Nchuleftingth. I should deliver the Bthark Prism to Neramo."},
		[13] = 
			{appendStepText="At his expedition's campsite at Nchuleftingth, ", stepTextKey="I should talk to Neramo and find out about my reward."},
		["Talk to Neramo 3"] =
			{appendText=".", stepTextKey="I should talk to Neramo and find out about my reward."},
	},

	[GetQuestName(5832)] = { --"Like Blood from a Stone"				--Jordakai
		[1] = 
			{appendStepText="Near the mine's main entrance, south of Balmora, I spoke with Malur and agreed to help him. ", stepTextKey="I need a key to gain access to the mine. The mine's foreman, Nox, carries one that I could pickpocket. Benar also keeps one under guard in the Rethan manor house."},
		["Obtain Benar Rethan's Key"] =
			{appendText=". The key will be secured in an upper level office in a desk. The house may have guards inside. Rethan Manor is located at the end of a narrow road near the Odai River, southwest of Balmora.\n"},
		["Obtain the Foreman's Key"] =
			{appendText=". He is likely near the city's small plaza, just inside the city's southern gate."},
		[2] = 
			{appendStepText="", stepTextKey="I acquired a key. I should use it to gain access to the mine."},
		["Unlock the Vassir-Didanat Mine"] =
			{appendText=", south of Balmora."},
		[3] = 
			{appendStepText="I entered the ebony mine south of Balmora. ", stepTextKey="I must search the mine for any evidence of wrongdoing."},
		["Search the Mine"] =
			{appendText=". I should look for documents or a scroll in the mine's southern area."},
		[4] = 
			{appendStepText="At the southern end of the mine, in a makeshift office, I found a Letter to Master Rethan. ", stepTextKey="According to a document I found, an alchemist named Gavros is conducting vile experiments in a Daedric shrine deep within the mine. I should explore this ruin."},
		["Search the Daedric Ruins"] =
			{appendText=". The ebony-purple mists seem to be more potent as I go through the western ruins. There must be a laboratory the alchemist uses with more documents or evidence."},
		[5] = 
			{appendStepText="In the Daedric ruin's northwestern Labratory, ", stepTextKey="I found even more incriminating documents describing Gavros's experiments. I must find this mysterious alchemist."},
		["Find Gavros"] =
			{appendText=" in his chamber southeast of the Laboratory."},
		[6] = 
			{appendStepText="South of Balmora, deep in the mine's Daedric ruin, ", stepTextKey="I found Gavros. He appears to be in poor condition. I should talk to him."},
		["Talk to Gavros"] =
			{appendText=" in his study, southeast of his western Laboratory."},
		[7] = 
			{appendStepText="In the mine south of Balmora, I spoke with the alchemist in his study, southeast of his western Laboratory in the mine's Daedric ruins. ", stepTextKey="Gavros utilized a Daedric alchemical formula to turn people into something resembling ebony. I should claim the scroll containing the formula before it falls into the wrong hands."},
		["Take the Mysterious Formula"] =
			{appendText=" scroll from the table with the books near the eastern wall of the study."},
		[8] = 
			{appendStepText="In the ruins of the ebony mine south of Balmora, ", stepTextKey="I discovered the secret of Vassir-Didanat's success and acquired the Daedric formula that made it possible. I should report my findings to Malur Rethan."},
		["Talk to Malur Rethan"] =
			{appendText=". He is waiting north of the mine on the road, southwest of the Balmora Wayshrine.\n\nI can return to the upper level of the mine using a lift in the room north of the study."},
		[9] = 
			{appendStepText="South of Balmora on the road north of the mine, I found Malur. ", stepTextKey="I gave Malur a summary of the mine's condition, as well as the scroll containing the Daedric formula. While he reports these findings to a Hlaalu councilman, I must track down Benar and detain him until Hlaalu constables arrive."},
		["Find Benar at Rethan Manor"] =
			{appendText=". He is on the northern patio of the house. Rethan Manor is located at the end of a narrow road near the Odai River, southwest of Balmora."},
		[10] = 
			{appendStepText="Rethan Manor is located at the end of a narrow road near the Odai River, southwest of Balmora. On the house's northern patio ", stepTextKey="Benar lays slain, and I've been ambushed by his murderer. I must kill this mysterious assassin."},
		["Defeat the Assassin"] =
			{appendText="."},
		[11] = 
			{appendStepText="At Rethan Manor, located at the end of a narrow road near the Odai River, southwest of Balmora, I defeated an assassin. ", stepTextKey="The assassin dropped an interesting document. I should read it."},
		["Take the Assassin's Orders"] =
			{appendText=". The document is on the ground near the northern patio's fireplace."},
		[12] = 
			{appendStepText="", stepTextKey="It appears that Malur, not Benar, orchestrated the horrors in the Vassir-Didanat ebony mine. He plotted to frame Benar and I to avoid suspicion. I must track him down in the nearby town of Balmora."},
		["Go to Malur's Meeting with Councilor Rayveth"] =
			{appendText=" at the city's tavern, The Randy Netch Inn."},
		[13] = 
			{appendStepText="I entered The Randy Netch Inn in Balmora. ", stepTextKey="Malur is no where to be found, but the Hlaalu trade baron he reports to, Councilor Rayveth, lounges nearby. I should talk to him."},
		["Talk to Councilor Rayveth 1"] =
			{appendText=".", stepTextKey="Malur is no where to be found, but the Hlaalu trade baron he reports to, Councilor Rayveth, lounges nearby. I should talk to him."},
		[14] = 
			{appendStepText="At The Randy Netch Inn, ", stepTextKey="Councilor Rayveth urged me to kill Malur to resolve the situation in the Vassir-Didanat mine. I must track the corrupt businessman to his residence in Balmora and end his vile scheme."},
		["Kill Malur Rethan"] =
			{appendText=" at his house in the city's upper east side."},
		[15] = 
			{appendStepText="Inside his house on Balmora's east side, ", stepTextKey="I dealt with Malur. The Daedric formula rests on a table in his bed chamber. I should take it back."},
		["Take the Formula"] =
			{appendText=" scroll on the table at the foot of the bed."},
		[16] = 
			{appendStepText="", stepTextKey="I killed Malur and reacquired the formula. I should return to Rayveth to resolve this business. He will likely ask for the scroll. I must decide what to do with this powerful document."},
		["Return to Councilor Rayveth"] =
			{appendText=" of House Hlaalu at The Randy Netch Inn of Balmora."},
		[17] = 
			{appendStepText="I met with the House Hlaalu Councilor at The Randy Netch Inn of Balmora. ", stepTextKey="I decided to give the Daedric scroll to Rayveth. I should talk to him to receive my reward."},
		["Talk to Councilor Rayveth 2"] =
			{appendText=".", stepTextKey="I decided to give the Daedric scroll to Rayveth. I should talk to him to receive my reward."},
		[18] = 
			{appendStepText="I spoke with the Councilor at The Randy Netch Inn in Balmora. ", stepTextKey="I decided to destroy the Daedric scroll. I should discuss my reward with Rayveth. The payment may be significantly reduced, but he still owes me something."},
		["Talk to Councilor Rayveth 3"] =
			{appendText=" of House Hlaalu.", stepTextKey="I decided to destroy the Daedric scroll. I should discuss my reward with Rayveth. The payment may be significantly reduced, but he still owes me something."},
	},

[GetQuestName(5883)] = { --"Hatching a Plan"				--Jordakai
		[1] = 
			{appendStepText="In the northwestern city of Gnisis, outside The Resting Kwama tavern, ", stepTextKey="Foreman Lathdar demanded that Revus make good on his pledge to aid the miners. I must find the Telvanni mage and secure his help."},
		["Find Revus"] =
			{appendText=" Demnevanni at his egg research camp in the rocks northwest of Gnisis. It is southeast of a Daedric shrine. \nI should go west on the road by the city's tavern, following the trail past a tower, continuing north, not east, under a span bridge, then up stone steps on the east side of the trail. From the top of the steps, I'll head north across the span bridge, then northwest to cross another span bridge."},
		[2] = 
			{appendStepText="Northwest of Gnisis, up in the rocks at his egg hatchery camp, ", stepTextKey="I located Revus. I should speak to him about Foreman Lathdar's demands."},
		["Talk to Revus 1"] =
			{appendText=" Demnevanni, the Telvanni mage.\nHis camp is above a ravine, in the rocks at the end of the northwestern span bridge that is north of another span bridge and south of the Daedric shrine's massive bridge.", stepTextKey="I located Revus. I should speak to him about Foreman Lathdar's demands."},
		[3] = 
			{appendStepText="At his egg hatchery camp in the rocks northwest of Gnisis, I spoke with the mage. ", stepTextKey="Revus insists that he had a kwama queen egg in his nursery, but cliff striders snatched it while he was studying the Dwarven resonator. I must locate his stolen eggs and mark them with a divining stone so Revus can recover them."},
		["Mark the Egg-Heaps with Revus's Divining Stone"] =
			{appendText=". There are three cliff strider nests to mark.\nFrom Revus' camp, I should go east across the span bridge, then south across another span bridge and find a third span bridge to the south, just south of the top of the stone steps by the tall mushrooms. At that bridge's end stands a brown Cliff Strider Egg-Heap, taller than an Altmer.\nFrom the first egg-heap, return across the span bridge and then go west across another span bridge, just south of the two tall mushrooms at the top of the stone steps. The egg-heap is in a small clearing north of the trail. The clearing is at the north end of the narrow, oblong trail in the maze's southwest.\nThe third location is north of the city. From the second egg-heap, I should go back across the span bridge and find the two tall mushrooms at the top of the stone steps. Then go down the steps and head east, passing under a span bridge and across a smaller span bridge. The tall, brown egg-heap is on the north side of the trail."},
		[4] = 
			{appendStepText="Northwest of Gnisis, in the maze of trails, ", stepTextKey="I marked the egg-heaps with Revus' divining stone. I should return to Revus' nursery to let him know."},
		["Meet Revus at the Hatchery"] =
			{appendText=" up in the rocks. I should return to the stone steps located north of the southern span bridge. The torchlit steps are on the north side of a large boulder and have two tall mushrooms at their top. Head up the steps and across the northbound span bridge, then across the western bridge to reach the mage's camp. A Dwemer ruin rises in the background."},
		[5] = 
			{appendStepText="Northwest of Gnisis, in the maze of trails, ", stepTextKey="I marked the egg-heaps with Revus' divining stone. I should return to Revus' nursery to let him know."},
		["Talk to Revus 2"] =
			{appendText=" Demnevanni, the Telvanni mage.\nHis camp is above a ravine, in the rocks at the end of the northwestern span bridge that is north of another span bridge and south of the Dwemer ruin's massive bridge."},
		[6] = 
			{appendStepText="At his egg hatchery camp northwest of Gnisis, ", stepTextKey="Revus urged me to return to town while he arranges transportation for the eggs. I should tell Foreman Lathdar what's going on."},
		["Return to the Foreman"] =
			{appendText=", talking with the House Redoran Dunmer in front of the city's tavern, The Resting Kwama."},
		[7] = 
			{appendStepText="", stepTextKey="Revus delivered the eggs, but something is amiss. I should speak to him about it."},
		["Talk to Revus 3"] =
			{appendText=" in front of The Resting Kwama tavern in Gnisis.", stepTextKey="Revus delivered the eggs, but something is amiss. I should speak to him about it."},
		[8] = 
			{appendStepText="", stepTextKey="Revus fears that the kwama queen might hatch prematurely. Soothing music should keep the queen sedate. Revus recommended a singer named Vigard. I should search for this bard to the south of town."},
		["Recruit Vigard the Sparrow"] =
			{appendText=". I should look for the bard on the coastal road, south of Gnisis. He may be on or below a large rock at the water's edge near the curve with a short, four-post, rope fence."},
		[9] = 
			{appendStepText="I found the bard on the coastal road south of Gnisis. ", stepTextKey="The singer, Vigard, agreed to help. I should return to Gnisis."},
		["Return to Gnisis"] =
			{appendText=" and go to the docks."},
		[10] = 
			{appendStepText="I returned to Gnisis. ", stepTextKey="The Redoran deputy-prefect, Manore, asked to speak with me. He looks upset."},
		["Talk to Manore"] =
			{appendText=" Mobaner."},
		[11] = 
			{appendStepText="At the northwestern city of Gnisis, ", stepTextKey="Revus is prepared to break the royal egg free from its casing. I should meet him by the dock to make sure everything goes as planned."},
		["Help Uncover the Royal Egg"] =
			{appendText=". I should talk to Revus down at the southern dock on the western waterfront."},
		[12] = 
			{appendStepText="At the waterfront west of Gnisis, ", stepTextKey="Revus broke the royal egg free from it's egg-heap. Unfortunately, one of the eggs contained a raging cliff strider. I killed the beast, but not before it slew the singer, Vigard. I should find Revus to discuss our next move."},
		["Talk to Revus 4"] =
			{appendText=" Demnevanni standing part way up from the lower docks.", stepTextKey="Revus broke the royal egg free from it's egg-heap. Unfortunately, one of the eggs contained a raging cliff strider. I killed the beast, but not before it slew the singer, Vigard. I should find Revus to discuss our next move."},
		[13] = 
			{appendStepText="Back at the Gnisis Egg Mine up the hill northeast of the city, ", stepTextKey="Our last best chance at saving the egg mine is to plant the royal egg directly into the mine's nursery chamber. I should meet Revus at the door to the nursery, inside the mine."},
		["Meet Revus at the Nursery"] =
			{appendText=" in the mine's southernmost cavern, not far from the main entrance. When I see him there, I should talk to him."},
		[14] = 
			{appendStepText="In the Gnisis Egg Mine northeast of the city, I met and spoke with Revus. ", stepTextKey="The royal egg is preparing to hatch. I must plant it in the nursery chamber before that happens. Kwama workers will almost certainly attack. I should be prepared to fight."},
		["Hatch the Royal Egg in the Nursery"] =
			{appendText=", the egg mine's southernmost cavern. In the center of the Nursery is a good spot to hold the egg."},
		[15] = 
			{appendStepText="Northeast of the city, in the Gnisis Egg Mine's Nursery cavern, ", stepTextKey="I defended the royal egg long enough for the new kwama queen to emerge. Both the colony and the Gnisis mining operation are saved. I should inform Foreman Lathdar of our success."},
		["Talk to Foreman Lathdar"] =
			{appendText=", standing outside the mine by the span bridge."},
		[16] = 
			{appendStepText="Near the mine's bridge, up the hill north of Gnisis, I found Revus, the Redoran, and the Foreman Lathdar. ", stepTextKey="With a new queen, the Gnisis egg mine will start producing again soon. I should have a final word with Foreman Lathdar."},
		["Talk to the Foreman"] =
			{appendText=" again."},
	},

	[GetQuestName(5863)] = { --"Haunted Grounds"				--Jordakai
		[1] = 
			{appendStepText="In the lower level of the Egg Mine Barracks, the southeastern tower of the northwestern city of Gnisis, I spoke with Theyo Prevette, the group's leader. ", stepTextKey="Theyo instructed me to meet his team at an Ashlander camp in the northern reaches of Vvardenfell. We'll gather supplies and information there before heading to the site of the haunting."},
		["Go to the Ashlander Urshilaku Camp"] =
			{appendText=" near the coast northeast of Gnisis. There is a wayshrine southwest of the tribe's camp.\nBefore I go, I should talk to Theyo's associates, Farwen and Sharz."},
		[2] = 
			{appendStepText="I arrived at the Urshilaku Camp near the northern coast, northeast of its wayshrine and the city of Gnisis. ", stepTextKey="The ghost hunters are no where to be found, but Lord Thanlen, the one who hired them, is here. I should speak to him and find out what's going on."},
		["Talk to Lord Thanlen"] =
			{appendText=" standing by a tall tree at the camp."},
		[3] = 
			{appendStepText="From the Urshilaku Camp near the northern coast, northeast of Urshilaku Wayshrine, ", stepTextKey="Lord Thanlen sent the ghost hunters ahead. I'll have to catch up with them at an ancient fort called Valenvaryon."},
		["Find the Ghost Hunters at Valenvaryon"] =
			{appendText=", an ancient stone-block structure overlooking the Sea of Ghosts, far to the east of the Urshilaku Camp. I should follow the northern coastal path until I reach the bottom of the zigzag path leading up to the old fortress.\nThe Ashlander speaking to Thanlon when I arrived, Asha-awa, stands by the fire in his yurt near the tall tree."},
		[4] = 
			{appendStepText="Near the northern coast far to the east of the Urhshilaku Camp, ", stepTextKey="I found the ghost hunters at the haunting site. I should speak to Theyo and see what he needs me to do."},
		["Talk to Theyo 1"] =
			{appendText=" Prevette at the bottom of the zigzag path leading up to Valenvaryon.", stepTextKey="I found the ghost hunters at the haunting site. I should speak to Theyo and see what he needs me to do."},
		[5] = 
			{appendStepText="On the northern coast where Valenvaryon rises above the Sea of Ghosts, I spoke with the ghosthunter. ", stepTextKey="Theyo has asked that I seek out Farwen, the magic user of the group. She's looking to set up wards of protection around them in the area, and may need my help finishing her task."},
		["Find Farwen"] =
			{appendText=", the religious Altmer. She may have started setting her wards near the path to the east, south of a Daedric ruin."},
		[6] = 
			{appendStepText="On the northern coast, east of Valenvaryon, I learned that ", stepTextKey="Farwen will be vulnerable while setting up her wards of protection against malicious spirits. I need to escort her to the locations she indicated would be best to set them up and prevent any hostile ghosts from interfering with her work."},
		["Set the Magical Wards"] =
			{appendText=" \n\nThe first ward will be placed in the Daedric ruin east of Valenvaryon. Ghosts may appear at a sphere of light between the eastern Daedric tower with banners and the wall to its east.\nThe second ward will be placed south of Valenvaryon, on a slope near the path to the Kushalit Sanctuary residence.\nThe third ward will be placed near the path southwest of the old fortress."},
		[7] = 
			{appendStepText="Southwest of Valenvaryon on the northern coast, ", stepTextKey="Galgalah snatched Farwen away before the final ward was set. I completed the ritual in her stead, but the other ghost hunters need to know she is in danger."},
		["Return to the Group"] =
			{appendText=" at the bottom of the zigzag path leading up to Valenwaryon."},
		[8] = 
			{appendStepText="Warded from the spirits haunting Valenvaryon, Theyo explained how we can find Galgalah. ", stepTextKey="Theyo says we need to capture a spirit in the service of Galgalah and interrogate it. I need to destroy the roaming spirits until I find one powerful enough that its essence remains intact. When I have that, I should bring it to Theyo."},
		["Destroy Ghosts to Find a Potent Spirit Essence"] =
			{appendText=". Theyo will be ready when I return to him in the warded circle on the path south of the haunted grounds."},
		[9] = 
			{appendStepText="Near the northern coast, I hunted spirits at Valenvaryon. ", stepTextKey="I have the essence of a powerful spirit. Now I need to get it back to Theyo and the ward."},
		["Bring the Essence Back to the Ward"] =
			{appendText=" at the bottom of the zigzag path."},
		[10] = 
			{appendStepText="At Valenvaryon on the northern coast, I placed the essence in the warded circle. ", stepTextKey="We summoned the defeated spirit, but it refuses to talk to anyone but me. I'll have to question it."},
		["Talk to the Captive Spirit"] =
			{appendText=" in the circle at the bottom of the path below the old fortress."},
		[11] = 
			{appendStepText="At the bottom of the southern path of Valenvaryon, I questioned the captive spirit. ", stepTextKey="The spirit dissipated, along with the ward,  but it also told us where Galgalah is holding Farwen. I should speak to Theyo about what we learned."},
		["Talk to Theyo 2"] =
			{appendText=" Prevette.", stepTextKey="The spirit dissipated, along with the ward,  but it also told us where Galgalah is holding Farwen. I should speak to Theyo about what we learned."},
		[12] = 
			{appendStepText="On the northern coast near the old fortress of Valenvaryon, Theyo let me know that ", stepTextKey="Galgalah resides in an ancient fortress near a lava path under a stone bridge. I need to search the area to find him."},
		["Find Galgalah's Lair"] =
			{appendText=" in a fortress ruin. I should search a narrow valley of lava, south of Valenvaryon. As I go, I may pass the glow of the southern ward Farwen set. When I see a stone arch, I should be close."},
		[13] = 
			{appendStepText="I found the old fortress south of a stone arch, near lava in a narrow valley south of Valvaryon on the northern coast. ", stepTextKey="Galgalah has lured me here to take my body. I must destroy him."},
		["Defeat Galgalah"] =
			{appendText="."},
		[14] = 
			{appendStepText="At an old fortress south of a stone arch, near lava in a narrow valley south of Valvaryon on the northern coast, ", stepTextKey="I defeated Galgalah, but his spirit fled into Farwen's body. She fled in a delirious panic. I need to catch her."},
		["Talk to Farwen"] =
			{appendText=" at the base of Galgalah's fortress lair."},
		[15] = 
			{appendStepText="At the old fortress near a stone arch and lava, south of Valenvaryon, ", stepTextKey="I killed Farwen and banished Galgalah, who was occupying her body. I need to get back to Theyo and let him know what happened."},
		["Meet the Ghost Hunters in Gnisis 1"] =
			{appendText=". They should be at the Egg Mine Barracks, the city's southeastern tower.", stepTextKey="I killed Farwen and banished Galgalah, who was occupying her body. I need to get back to Theyo and let him know what happened."},
		[16] = 
			{appendStepText="At the old fortress near a stone arch and lava, south of Valenvaryon, ", stepTextKey="I killed Farwen and banished Galgalah, who was occupying her body. Theyo half-expected this outcome, but he's glad Farwen's sacrifice wasn't in vain. I should speak to him again before we part ways."},
		["Talk to Theyo 3"] =
			{appendText=" at the Egg Mine Barracks, the tower in southeast Gnisis.", stepTextKey="I killed Farwen and banished Galgalah, who was occupying her body. Theyo half-expected this outcome, but he's glad Farwen's sacrifice wasn't in vain. I should speak to him again before we part ways."},
		[17] = 
			{appendStepText="", stepTextKey="Galgalah inhabits Farwen's body, but I refused to sacrifice her to destroy him. I have to hope she can resist his control. The other ghost hunters will be glad to see her regardless."},
		["Meet the Ghost Hunters in Gnisis 2"] =
			{appendText=" at its southeastern tower, the Egg Mine Barracks.", stepTextKey="Galgalah inhabits Farwen's body, but I refused to sacrifice her to destroy him. I have to hope she can resist his control. The other ghost hunters will be glad to see her regardless."},
		[18] = 
			{appendStepText="", stepTextKey="Galgalah inhabits Farwen's body, but I refused to sacrifice her to destroy him. I have to hope she can resist his control. Her companions are glad to see her alive in any case. I should speak to Theyo."},
		["Talk to Theyo 4"] =
			{appendText=" Prevette in the Egg Mine Barracks, the southeastern tower of the northwestern city of Gnisis.", stepTextKey="Galgalah inhabits Farwen's body, but I refused to sacrifice her to destroy him. I have to hope she can resist his control. Her companions are glad to see her alive in any case. I should speak to Theyo."},
	},

	[GetQuestName(5872)] = { --"A Melodic Mistake"				--Jordakai
		[1] = 
			{appendStepText="I arrived in the northwestern city of Gnisis and spoke with a well-dressed member of House Redoran, Manore Mobaner. ", stepTextKey="The egg-mine's foreman, Lathdar, is keeping an eye on things near the mine entrance. I should speak to him."},
		["Talk to the Foreman Lathdar"] =
			{appendText=" at the egg mine up the hill in the city's northeast."},
		[2] = 
			{appendStepText="Up the hill in the city's northeast, I spoke with the mine's foreman. ", stepTextKey="The egg-hands trapped within the mine are acting strangely and refusing to come out. I must enter the mine to determine what's causing their erratic behavior."},
		["Investigate the Disturbance in the Mine"] =
			{appendText=". I should look for a couple of miners in the southwestern alcoves and tunnels first. "},
		[3] = 
			{appendStepText="In the southwestern tunnels of the Gnisis Egg Mine up on the hill northeast of the city, ", stepTextKey="I found several deranged egg-hands, all of whom were babbling about a strange song. I'll need to delve deeper into the mine if I'm to find out where this \"music\" is coming from."},
		["Delve Deeper into the Mine"] =
			{appendText=". I should check on the Kwama's Queen in the lower southern caverns before heading north through the tunnels."},
		[4] = 
			{appendStepText="In the hill northeast of the city, in the southern chamber of the Gnisis Egg Mine, ", stepTextKey="I found the corpse of the kwama's queen, killed by her own workers. While I was examining the remains, another crazed egg-hand appeared. I should see what he has to say."},
		["Talk to Destaine"] =
			{appendText=" in the queen's cavern."},
		[5] = 
			{appendStepText="I'm in the mine up the hill northeast of Gnisis. ", stepTextKey="A string of groundquakes have opened a breach in the mine's wall. The sound appears to be coming from that direction. I should delve deeper to find the source."},
		["Locate the Source of the Sound"] =
			{appendText=". I should go north through the tunnels and then into the areas beyond."},
		[6] = 
			{appendStepText="In the egg mine up the hill in Gnisis, I found and entered a Dwemer ruin. Not a big surprise as Vvardenfell is a Dwemer word. It means \"City of the Strong Shield\", the name the Dwemer gave to the island's Red Mountain. In the ruin, ", stepTextKey="I encountered a powerful barrier, erected by a Dwarven machine, that's blocking my progress. I'll need to find some way to get past this strange obstacle."},
		["Find a Way Past the Dwarven Barrier"] =
			{appendText=". In the lava chamber, on the west side of the center column there is a Tonal Prism crystal. Perhaps I can use its power to break the barrier."},
		[7] = 
			{appendStepText="Northeast of Gnisis in the egg mine, I removed a barrier in the northern lava chamber of the Dwarven ruin. ", stepTextKey="The eerie tones are getting louder. I need to delve even deeper into the ruins to find the source of the sound."},
		["Find the Source of the Sound"] =
			{appendText=". I should continue through the eastern hallway into the large cavern, continue east, and enter the Dwarven door."},
		[8] = 
			{appendStepText="Northeast of Gnisis, deep within an egg mine in the far eastern Dwemer ruins, ", stepTextKey="I found a Dark Elf tinkering with a strange Dwarven mechanism. He may know more about what's causing the sound, or better yet, how to stop it."},
		["Talk to Revus 1"] =
			{appendText=" Demnevanni near the large Dwemer machine.", stepTextKey="I found a Dark Elf tinkering with a strange Dwarven mechanism. He may know more about what's causing the sound, or better yet, how to stop it."},
		[9] = 
			{appendStepText="At the Dwemer machine in the far eastern chamber of the ruins, in the egg mine northeast of Gnisis, I communicated with the mage. ", stepTextKey="The Dark Elf, Revus, needs my help to fix the Dwarven resonator. I must set the valves in the correct position, then pull the release lever. The egg-hands have been humming a song since I arrived. Maybe there's a clue hidden in the melody."},
		["Fix the Dwarven Resonator"] =
			{appendText=". There are five levers on the machine. Reverberating through the complex, there has been a repetitive sequence of five notes. And the egg-handlers were all humming the same tune. A medium pitched note, then a low one, then two high notes, and last, a low note. After throwing the five levers, I will need to throw the lever at the switch box in front of the machine."},
		[10] = 
			{appendStepText="At the Dwemer machine in the far eastern chamber of the ruins, in the egg mine northeast of Gnisis, ", stepTextKey="I fixed the Dwarven resonator and liberated the egg-hands. I should speak to the Dark Elf mage, Revus, and find out why this happened."},
		["Talk to Revus 2"] =
			{appendText=" Demnevanni. He ran out the door, heading southwest from the machine's chamber.", stepTextKey="I fixed the Dwarven resonator and liberated the egg-hands. I should speak to the Dark Elf mage, Revus, and find out why this happened."},
		[11] = 
			{appendStepText="At the Dwemer machine in the far eastern chamber of the ruins, in the egg mine northeast of Gnisis, ", stepTextKey="I deactivated the Dwarven resonator and saved Gnisis' egg-hands. I should get back to Foreman Lathdar in Gnisis and catch him up on all that's happened."},
		["Talk to Foreman Lathdar 1"] =
			{appendText=". I should use the Dwarven door southeast of Revus' camp in the ruin. The foreman is in front of the city's  tavern, The Resting Kwama, near the Temple in Gnisis.", stepTextKey="I deactivated the Dwarven resonator and saved Gnisis' egg-hands. I should get back to Foreman Lathdar in Gnisis and catch him up on all that's happened."},
		[12] = 
			{appendStepText="At the Dwemer machine in the far eastern chamber of the ruins, in the egg mine northeast of Gnisis, ", stepTextKey="I deactivated the Dwarven resonator and saved Gnisis' egg-hands. I should get back to Foreman Lathdar in Gnisis and catch him up on all that's happened."},
		["Talk to Foreman Lathdar 2"] =
			{appendText=". I should use the Dwarven door southeast of Revus' camp in the ruin. The foreman is in front of the city's  tavern, The Resting Kwama, near the Temple in Gnisis.", stepTextKey="I deactivated the Dwarven resonator and saved Gnisis' egg-hands. I should get back to Foreman Lathdar in Gnisis and catch him up on all that's happened."},
	},

	[GetQuestName(5903)] = { --"The Memory Stone"				--Jordakai
		[1] = 
			{appendStepText="I was in the southwestern city of Balmora, near The Randy Netch Inn on the city's riverfront. I spoke with Gilan outside his house, north of the inn. He gave me his Memory Stone. ", stepTextKey="The first memory Gilan wishes to retrieve is in a valley near Balmora."},
		["Go to Balmora Valley"] =
			{appendText=" outside the city, to the east. I should look for a spot near the northern end of valley, not far from the northeastern corner of the city walls.\n\nMils Lerano, Gilan's son, went back down to fish in the river near his house. Neria works at the Riverside Riding Company."},
		[2] = 
			{appendStepText="East of Balmora, outside the city's northwestern corner, ", stepTextKey="I reached the valley, but I must use Gilan's memory stone to trigger and store his memories of this place."},
		["Use Gilan's Memory Stone 1"] =
			{appendText=" near a tree at the north end of the narrow Balmora Valley.", stepTextKey="I reached the valley, but I must use Gilan's memory stone to trigger and store his memories of this place."},
		[3] = 
			{appendStepText="", stepTextKey="Using Gilan's memory stone caused one of his past memories to appear as a magical projection. The next spot he marked on my map is the Caldera Crater."},
		["Travel to the Caldera Crater"] =
			{appendText=", northwest of Balmora. I should use the northern road from the city, passing the lake, and going a short distance beyond the Redoran fort. To the southwest is a valley that narrows into the rocky crater. I should look for a spot on a small hill, north of the crater's center."},
		[4] = 
			{appendStepText="Northwest of Balmora and a short distance from a Redoran fort, ", stepTextKey="I reached the Caldera Crater. Using Gilan's memory stone should trigger and store his memories of this place."},
		["Use Gilan's Memory Stone 2"] =
			{appendText=" on the small hill near a large boulder, ", stepTextKey="I reached the Caldera Crater. Using Gilan's memory stone should trigger and store his memories of this place."},
		[5] = 
			{appendStepText="", stepTextKey="Using Gilan's memory stone caused one of his past memories to appear as a magical projection. The next spot he marked on my map is on the road to Balmora."},
		["Travel to the Balmora Overlook"] =
			{appendText=" on the road north of the city, between the lake and the Redoran fort. The spot is near a roadside brazier."},
		[6] = 
			{appendStepText="On the road north of Balmora, between the lake and the Redoran fort, ", stepTextKey="I reached another destination Gilan marked on my map. Using Gilan's memory stone should trigger and store his memories of this place."},
		["Use Gilan's Memory Stone 3"] =
			{appendText=" near a roadside brazier.", stepTextKey="I reached another destination Gilan marked on my map. Using Gilan's memory stone should trigger and store his memories of this place."},
		[7] = 
			{appendStepText="", stepTextKey="Using Gilan's memory stone caused one of his past memories to appear as a magical projection. The next spot he marked on my map is within Balmora itself."},
		["Travel to Balmora"] =
			{appendText=". The spot is near the northeastern riverwalk, just north of the city's gate."},
		[8] = 
			{appendStepText="North of Balmora's northeastern gate, near twin trees, ", stepTextKey="I reached the last destination Gilan marked on my map. Using Gilan's memory stone should trigger and store his memories of this place."},
		["Use Gilan's Memory Stone 4"] =
			{appendText=".", stepTextKey="I reached the last destination Gilan marked on my map. Using Gilan's memory stone should trigger and store his memories of this place."},
		[9] = 
			{appendStepText="", stepTextKey="I visited all the locations Gilan marked on my map and stored his memories in the memory stone. I should return it to Gilan."},
		["Talk to Gilan Lerano 1"] =
			{appendText=" at his house, north of Balmora's tavern, The Randy Netch Inn.", stepTextKey="I visited all the locations Gilan marked on my map and stored his memories in the memory stone. I should return it to Gilan."},
		[10] = 
			{appendStepText="At his house in Balmora, I spoke with Gilan Lerano. ", stepTextKey="Gilan seems drained by the experience of reliving his past. He asked me to invite his children, Neria and Mils, to speak with him about the memory stone and their mother."},
		["Talk to Mils Lerano"] =
			{appendText=", who is fishing in the city's canal."},
		[11] = 
			{appendStepText="", stepTextKey="Gilan seems drained by the experience of reliving his past. He asked me to invite his children, Neria and Mils, to speak with him about the memory stone and their mother."},
		["Talk to Neria Lerano 1"] =
			{appendText=" at the city's stables, the Riverside Riding Company.", stepTextKey="Gilan seems drained by the experience of reliving his past. He asked me to invite his children, Neria and Mils, to speak with him about the memory stone and their mother."},
		[12] = 
			{appendStepText="In Balmora, ", stepTextKey="I convinced Neria and Mils to visit their father. I should return to Gilan and let him know they agreed."},
		["Talk to Gilan Lerano 2"] =
			{appendText=" in his house, north of the city's inn.", stepTextKey="I convinced Neria and Mils to visit their father. I should return to Gilan and let him know they agreed."},
		[13] = 
			{appendStepText="At the Lerano House in Balmora, ", stepTextKey="Gilan passed away while I was gone, and Neria and Mils arrived too late to speak to their father. I should talk to Neria about Gilan's last wishes."},
		["Talk to Neria Lerano 2"] =
			{appendText=". She and Mils are upstairs in their home.", stepTextKey="Gilan passed away while I was gone, and Neria and Mils arrived too late to speak to their father. I should talk to Neria about Gilan's last wishes."},
		[14] = 
			{appendStepText="", stepTextKey="Though Gilan is dead, the Memory Stone he created for his children is now complete. Perhaps they can draw some measure of closure from what it contains."},
		["Talk to Neria Lerano 3"] =
			{appendText=" in the her house in Balmora, north of the inn.", stepTextKey="Though Gilan is dead, the Memory Stone he created for his children is now complete. Perhaps they can draw some measure of closure from what it contains."},
	},
-- 		=========================================================================
--		 Vvardenfell - Dailies Quest
-- 		=========================================================================
		    [GetQuestName(6008)] = { --"Ashlander Relations"				--Jordakai
        [1] = 
            {appendStepText="I spoke with an Ashlander at their camp. ", stepTextKey="I should speak to Zanammu in Ald'ruhn to learn how to best build a relationship with the Ashlanders."},
        ["Talk to Zanammu 1"] =
            {appendText=" inside a yurt next to a merchant in the Ashlander campsite, just west of Skar's entrance.", stepTextKey="I should speak to Zanammu in Ald'ruhn to learn how to best build a relationship with the Ashlanders."},
        [2] = 
            {appendStepText="At Ald'ruhn, in a yurt next to a merchant at the Ashlander campsite, just west of Skar's entrance, I spoke with a Zainab Ashlander. He recommends that I speak with Ashlanders from all of the tribes, learn of their ways, and help them as I can.", stepTextKey=""},
        ["Talk to Zanammu 2"] =
            {appendText=".", stepTextKey=""},
    },

    [GetQuestName(5927)] = { --"Relics of Ashurnabitashpi"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The Ashurnabitashpi shrine stands along the northern coast, to the west of the Forgotten Wastes. I need to defeat the Ashlander exiles there and retrieve any relics they removed from the ruins."},
        ["Gather Ashurnabitashpi Relics"] =
            {appendText=" \n\nThe small Daedric ruin is on the central northern coast, east of Urshilaku Wayshrine and west of the Valley of the Wind Wayshrine. There are battle banners to the south."},
        [2] = 
            {appendStepText="On the northern coast, east of the Urshilaku camp and west of the Forgotten Wastes, ", stepTextKey="I retrieved historic relics stolen from the ruins of Ashurnabitashpi. Now I should return to Numani-Rasi in the Urshilaku camp in Ald'ruhn."},
        ["Return to Numani-Rasi"] =
            {appendText=" in her yurt at the northeastern camp, near Skar."},
    },

    [GetQuestName(5928)] = { --"Relics of Ebernanit"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The Ebernanit shrine stands far to the north, west of the Forgotten Wastes. I need to find the ruins and recover as many relics of historic significance as I can."},
        ["Gather Ebernanit Relics"] =
            {appendText=" \n\nThe Daedric ruin is east of the Urshilaku camp near an ancient Velothi fortress on the coast. Uncover the relics where atronachs roam."},
        [2] = 
            {appendStepText="Despite the roaming atronachs at the ruin east of the Urshilaku camp, near an ancient Velothi fortress on the northern coast, ", stepTextKey="I retrieved historic relics from the ruins of Ebernanit. Now I should return to Numani-Rasi in the Urshilaku camp in Ald'ruhn."},
        ["Return to Numani-Rasi"] =
            {appendText=" in her yurt at the northeastern campsite of the Ashlander encampment at Ald'ruhn."},
    },

   [GetQuestName(5924)] = { --"Relics of Yasammidan"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The Yasammidan shrine lies along the western coast, overlooking the sea. The Daedric Prince Mehrunes Dagon was worshiped there in times past."},
        ["Gather Yasammidan Relics"] =
            {appendText=" \n\nThe ruin is on the sinking tip of a peninsula far to the west of the Urshilaku Camp, in the northwest West Gash."},
        [2] = 
            {appendStepText="At the sinking shrine to Mehrunes Dagon, far to the west of the Urshilaku camp, ", stepTextKey="I gathered historic relics from the ruins of Yasammidan. Now I should return to Numani-Rasi in the Urshilaku camp in Ald'ruhn."},
        ["Return to Numani-Rasi"] =
            {appendText=" in her yurt near Skar in the northeastern campsite of the Ashlander encampment."},
    },

    [GetQuestName(5925)] = { --"Relics of Assarnatamat"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The Assarnatamat shrine stands in the barrens between Ald'ruhn and Balmora. I need to defeat the brigands and retrieve any relics they stole from the ruins."},
        ["Gather Assarnatamat Relics"] =
            {appendText=" \n\nThe ruin is east of the lake feeding the Odai River that flows through the city known as Stonewood in the Dunmeri language."},
        [2] = 
            {appendStepText="Near the headwaters of the Odai River, ", stepTextKey="I retrieved historic relics stolen from the ruins of Assarnatamat. Now I should return to Numani-Rasi in the Urshilaku camp in Ald'ruhn."},
        ["Return to Numani-Rasi"] =
            {appendText=" in her yurt at the northeeastern Ashlander campsite of Ald'ruhn."},
    },

    [GetQuestName(5929)] = { --"Relics of Dushariran"			--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The Dushariran shrine lies to the northwest of Ald'ruhn. I should go to the ruins, deal with the vampires, and recover as many relics as I can find."},
        ["Gather Dushariran Relics"] =
            {appendText=" \n\nThe Berne Clan claims the Daedric ruin in the rocky hills of the West Gash region. It is east of Gnisis and north of the West Gash Wayshrine."},
        [2] = 
            {appendStepText="In the West Gash, northwest of Ald'ruhn and southeast of Gnisis, ", stepTextKey="I retrieved historic relics from the ruins of Dushariran after dealing with vampires that had overrun the shrine. Now I should return to Numani-Rasi in the Urshilaku camp in Ald'ruhn."},
        ["Return to Numani-Rasi"] =
            {appendText=" in her yurt in the northeastern campsite of Ashlanders."},
    },

    [GetQuestName(5930)] = { --"Relics of Ashalmawia"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The Ashalmawia shrine lies to the north and west of Ald'ruhn, near the coast. I should gather relics from the exterior ruins and avoid entering the shrine itself."},
        ["Gather Ashalmawia Relics"] =
            {appendText=" \n\nThe Daedric ruin is southwest of the Urshilaku camp in northern West Gash. Cultists may have buried any relics they've found."},
        [2] = 
            {appendStepText="Southwest of the Urshilaku camp, ", stepTextKey="I retrieved historic relics from the ruins of Ashalmawia. Now I should return to Numani-Rasi in the Urshilaku camp in Ald'ruhn."},
        ["Return to Numani-Rasi"] =
            {appendText=" in her yurt in the northeastern Ashlander campsite, near Skar."},
    },

    [GetQuestName(5926)] = { --"Relics of Maelkashishi"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The Maelkashishi shrine lies to the east of West Gash, to the north of Ald'ruhn. I need to defeat the cultists and retrieve any relics they stole from the ruins."},
        ["Gather Maelkashishi Relics"] =
            {appendText=" \n\nThe ancient shrine is southeast of the wayshrine near the Urshilaku camp in the island's northwestern area known as West Gash."},
        [2] = 
            {appendStepText="In the eastern West Gash area of the island, southeast of the Urshilaku Wayshrine, ", stepTextKey="I retrieved historic relics stolen from the ruins of Maelkashishi. Now I should return to Numani-Rasi in the Urshilaku camp in Ald'ruhn."},
        ["Return to Numani-Rasi"] =
            {appendText=" in her yurt at the northeastern camp, near Skar."},
    },

    [GetQuestName(5910)] = { --"Mother Jagged-Claw Hunt"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="Mother Jagged-Claw has been spotted along the southeast coast, in the vicinity of the great Shrine of Azura. The Huntmaster suggests I disturb the mounds of mud to attract the attention of the giant mudcrab."},
        ["Hunt Down Mother Jagged-Claw"] =
            {appendText=" on the shores of Azura's Coast, probably south of the shrine of the Prince of Dawn and Dusk."},
        [2] = 
            {appendStepText="On the shores of the Inner Sea of southeastern Azura's Coast, ", stepTextKey="I successfully hunted the giant mudcrab known to the Erabenimsun as Mother Jagged-Claw. Now I should return to the Huntmaster and present him with the trophy."},
        ["Return to Huntmaster Sorim-Nakar"] =
            {appendText=" in his yurt at the southern campsite of the Ashlander encampment at Ald'ruhn."},
    },

    [GetQuestName(5911)] = { --"Ash-Eater Hunt"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="Ash-Eater and its ilk have been spotted in the ashfalls east of the Erabenimsun camp. The Huntmaster suggests I disturb the mounds of ash to attract the attention of the dire beetle."},
        ["Hunt Down Ash-Eater"] =
            {appendText=" in the high mountain vale where the Shalk roam among the beetle mounds. North of the heretical settlement of Molag Mar, up through an ashen ravine of peaceful netches, the hunted awaits."},
        [2] = 
            {appendStepText="In a high mountain ashen vale, east of the Erabenimsun camp and north of Molag Mar, ", stepTextKey="I successfully hunted the dire ash beetle known to the Erabenimsun as Ash-Eater. Now I should return to the Huntmaster and present him with the trophy."},
        ["Return to Huntmaster Sorim-Nakar"] =
            {appendText=", the Erabenimsun Ashlander, in his yurt at the southern campsite of the Ald'ruhn encampment."},
    },

    [GetQuestName(5908)] = { --"Tarra-Suj Hunt"			--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The Huntmaster requested that I eliminate the threat of the deadly nix-hound the Erabenimsun call Tarra-Suj. It was last seen terrorizing the camp to the southeast, near Nchuleftingth."},
        ["Hunt Down Tarra-Suj"] =
            {appendText=", the powerful nix-hound. It is probably in the mountains northeast of the Erabenimsun Camp and east of Nchuleftinghth. Once there, I should hunt nix-hounds to attract it."},
        [2] = 
            {appendStepText="In the Ashlands northeast of the Erabenimsun Camp, ", stepTextKey="I successfully hunted the deadly nix-hound known to the Erabenimsun as Tarra-Suj. Now I should return to the Huntmaster and present him with the trophy."},
        ["Return to Huntmaster Sorim-Nakar"] =
            {appendText=" at his yurt in the southern Ashlander campsite of Ald'ruhn."},
    },

    [GetQuestName(5909)] = { --"Writhing Sveeth Hunt"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The greater hive golem known as Writhing Sveeth has been terrorizing the area to the northwest of the Erabenimsun camp near Nchuleftingth. The Huntmaster suggests I destroy fetcherfly nests to attract the attention of the golem."},
        ["Hunt Down Writhing Sveeth"] =
            {appendText=". It has been seen in a secluded mountain valley with a small hot springs, east of a large foyada, and west of a Dwemer ruin and a wayshrine."},
        [2] = 
            {appendStepText="In a secluded mountain valley with a hot springs, northwest of the Erabenimsun camp near Nchuleftingth, ", stepTextKey="I successfully hunted the greater hive golem known to the Erabenimsun as Writhing Sveeth. Now I should return to the Huntmaster and present him with the trophy."},
        ["Return to Huntmaster Sorim-Nakar"] =
            {appendText=" in his yurt at the southern campsite of the Ashlander encampment at Ald'ruhn."},
    },

    [GetQuestName(5912)] = { --"Old Stomper Hunt"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The crazed cliff strider known as Old Stomper is apparently attacking another Erabenimsun camp to the southeast. The Huntmaster wants me to track the creature, locate its nest, and dispatch it with due haste."},
        ["Hunt Down Old Stomper"] =
            {appendText=". Southwest of Nchuleftingth, and south of an ancient Velothi tower, I should track the beast along an ashen trail, Perhaps I will find remains of its kills and its nest. \n\nThe Nchuleftingth Dwemer ruin is secluded in the mountainous Ashlands southeast of Red Mountain's large foyadas. Its wayshrine is by the fire-rivers where the winding north-south road meets the east-west road."},
        [2] = 
            {appendStepText="Far south on an ashen trail southwest of Nchuleftingth, ", stepTextKey="I successfully hunted the ancient cliff strider known to the Erabenimsun as Old Stomper. Now I should return to the Huntmaster and present him with the trophy."},
        ["Return to Huntmaster Sorim-Nakar"] =
            {appendText=" in his yurt in the southern campsite of Ashlanders at Ald'ruhn."},
    },

    [GetQuestName(5913)] = { --"King Razor-Tusk Hunt"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="King Razor-Tusk and its pack have been spotted to the east, on the other side of Red Mountain. The Huntmaster suggests I slaughter a few lesser kagouti to draw out the pack leader."},
        ["Hunt Down King Razor-Tusk"] =
            {appendText=" in the northern Molag Amur area, north of Ncheuleftingth. Kagouti often roam near the winding main road. One popular kagouti range is east of an ancient fortress. \n\nThe Nchuleftingth Dwemer ruin is secluded in the mountainous Ashlands southeast of Red Mountain's large foyadas. Its wayshrine is by the fire-rivers where the winding north-south road meets the east-west road."},
        [2] = 
            {appendStepText="East of the ancient Velothi fortress called Falensarano Ruin, ", stepTextKey="I successfully hunted the kagouti pack leader known to the Erabenimsun as King Razor-Tusk. Now I should return to the Huntmaster and present him with the trophy."},
        ["Return to Huntmaster Sorim-Nakar"] =
            {appendText=" in his yurt in the southern camp of Ashlanders at Ald'ruhn."},
    },

[GetQuestName(5907)] = { --"Great Zexxin Hunt"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The Huntmaster requested that I eliminate the threat of the deadly nix-ox the Erabenimsun call Great Zexxin. It was last seen to the northeast of the Erabenimsun camp, near Nchuleftingth."},
        ["Hunt Down Great Zexxin"] =
            {appendText=". By now it has probably roamed farther east. I should begin tracking the dangerous nix-ox far east of Nchuleftingth, near the eastern road's end, just west of a dock with a boat. There is a solitary, yellowed fern near two large rocks. \n\nThe nix-ox's tracks lead west along the road to a patch of foul water with animal remains.\n\nThen the tracks head northwest along an ashen trail, to a large rock west of a campsite at an arch.\n\nMore tracks, now going north beyond a small pond, but not as far as the second pond. The beast seemed to stop near a formation of white spikes at a tall, pointed rock.\n\nThe Great Zexxin appears to have gone northwest from there to the second pond's eastern edge."},
        [2] = 
            {appendStepText="East of a small pond, far to the north of the Erabenimsun Camp, ", stepTextKey="I successfully hunted the deadly nix-ox known to the Erabenimsun as Great Zexxin. Now I should return to the Huntmaster and present him with the trophy."},
        ["Return to Huntmaster Sorim-Nakar"] =
            {appendText=" at his yurt in the southern campsite of Ashlanders in Ald'ruhn."},
    },

    [GetQuestName(6007)] = { --"A Call For Aid"			--Jordakai
        [1] = 
            {appendStepText="Adventurers Wanted! That is what the notice in Vivec City announced. ", stepTextKey="I should find Unel Darano and speak to him for more information."},
        ["Talk to Unel Darano"] =
            {appendText=". The Hall of Justice is on the bridge level of the southern city's Temple Canton.", stepTextKey="I should find Unel Darano and speak to him for more information."},
    },

    [GetQuestName(5916)] = { --"The Anxious Apprentice"		--Jordakai
        [1] = 
            {appendStepText="Beleru Omoril of Vivec City's Hall of Justice said that Nara Varam may know more. She is probably relaxing in the central area of Saint Olms Waistworks' lower level.\n\nWhen I'm ready, ", stepTextKey="I should travel to Dubdil Alar's tower in order to find his research notes and stop his experiment."},
        ["Stop Dubdil Alar's Experiment"] =
            {appendText=" at his Telvanni tower in the Grazelands. The tall mushroom creation rises up from the rocky roadside south of Vos's Tel Mora Wayshrine. East of the Zainab Camp, and north of the bandit's den of Pulk, Telvanni lights illuminate a narrow path to the mage's domain.\n"},
        ["Retrieve Research Notes"] =
            {appendText=" from an illuminated stone in the courtyard's southwest."},
        [2] = 
            {appendStepText="South of Vos' Tel Mora Wayshrine, I found the mage in the courtyard of his Telvanni mushroom tower. Now, ", stepTextKey="I should travel to Nara Varam in Vivec City to tell her that I've successfully stopped Dubdil Alar's experiment. She'll also have my reward."},
        ["Talk to Nara Varam"] =
            {appendText=" who drinks as she waits for me in the central area of Saint Olms Waistworks' lower level."},
    },

    [GetQuestName(5918)] = { --"A Creeping Hunger"				--Jordakai
        [1] = 
            {appendStepText="Beleru Omoril of Vivec City's Hall of Justice mentioned the researchers. One may be sitting in the hall by the Tailors and Dyers Hall's north door in Vivec City's Saint Olms Waistworks.\n\nWhen I'm ready, ", stepTextKey="I should travel to Sulipund Grange in order to gather the relics and defeat the Hunger."},
        ["Defeat Wuyuvus"] =
            {appendText=", Boethiah's minion, in its rocky lair near an ancient Velothi tower. The ruins are at the foot of Red Mountain, northwest of the lake east of Balmora and north of Suran.\n"},
        ["Gather Relic Bones"] =
            {appendText=". Just above the trail along the lake's northwestern edge, hidden by rocks, with one angular rock towering above, the bones rest at the foot of a lone tree.\n"},
        ["Gather Relic Tablet"] =
            {appendText=". It lies just west of the researchers' abandoned camp at the north end of the lake.\n"},
        ["Gather Relic Skull"] =
            {appendText=". It rests on the ashen northernmost shore of the lake, close to the water."},
        [2] = 
            {appendStepText="At Sulipund Grange, northwest of the lake east of Balmora, I defeated Wuyuvus the Hunger and found some relics. Now, ", stepTextKey="I should travel to Tirvina Avani in Vivec City to collect my reward."},
        ["Talk to Tirvina Avani"] =
            {appendText=", the researcher waiting in the hall by the Tailors and Dyers Hall's north door in Saint Olms Waistworks."},
    },

    [GetQuestName(5865)] = { --"Culling the Swarm"				--Jordakai
        [1] = 
            {appendStepText="In Vivec City's Hall of Justice, Beleru Omoril said that Dinor may know more. He is waiting near the north door of the Farmers and Laborers Hall in Saint Olms Waistworks. \n\nWhen I'm ready, ", stepTextKey="I should travel to Missir-Dadalit Egg Mine to kill excess kwama and defeat the kwama warrior guarding the queen."},
        ["Defeat The Queen's Consort"] =
            {appendText=" in its cavern lair. Vines and roots obscure the entrance, east of the trail where the kwama roam.\n"},
        ["Kill Kwama Near Missir-Dadalit Egg Mine"] =
            {appendText="\n\nThey can be found on the eastern, northbound Ashlands trail, northeast of Nchuleftingth Wayshine, near an archway where a guar sleeps peacefully by a warming campfire."},
        [2] = 
            {appendStepText="In the Ashlands northeast of Nchuleftingth Wayshrine, I defeated the Queen's Consort in its lair. And I killed some of the roaming kwama, too. Now ", stepTextKey="I should travel to Dinor Salvi in Vivec City to collect my reward."},
        ["Talk to Dinor Salvi"] =
            {appendText=". He is probably still writing in his journal near the north door of the Farmers and Laborers Hall in Saint Olms Waistworks."},
    },

    [GetQuestName(5866)] = { --"Oxen Free"				--Jordakai
        [1] = 
            {appendStepText="Beleru Omoril in Vivec City's Hall of Justice mentioned the Telvanni mage. He may be reading while listening to lute music in St. Olm's Waistworks' lowest level.\n\nWhen I'm ready, ", stepTextKey="I should travel to the caldera north of Balmora in order to collect mushroom samples and defeat the nix-ox."},
        ["Defeat Nilthog the Unbroken"] =
            {appendText=" at its mountain hollow, west of the Odai River's headwaters and south of Ald'ruhn.\n"},
        ["Gather Mushrooms"] =
            {appendText=" \n\nThe pale cup and cap fungi known as Caldera Mushrooms grow around the edges of the caldera."},
        [2] = 
            {appendStepText="In the caldera north of Balmora and south of Ald'ruhn, I defeated Nilthog the Unbroken and gathered Caldera Mushrooms. Now ", stepTextKey="I should travel to Bravosi Felder in Vivec City to collect my reward."},
        ["Talk to Bravosi Felder"] =
            {appendText=", the Telvanni mage. He is probably still reading in St. Olm's Waistworks' lowest level, near the musician."},
    },

    [GetQuestName(5904)] = { --"Salothan's Curse"				--Jordakai
        [1] = 
            {appendStepText="Beleru Omoril of Vivec City's Hall of Justice mentioned that a historian, Ivulen Andromo, may know more. He is probably in Saint Olms Waistworks on the mezzanine above the lower level's central area, writing as he sits on a long bench. \n\nWhen I'm ready, ", stepTextKey="I should go to the Salothan tomb in order to defeat wraiths and the spirit of Orator Salothan."},
        ["Defeat Orator Salothan"] =
            {appendText=". He may be with other spirits.\n"},
        ["Defeat Wraiths"] =
            {appendText=" \n\nFrom the Gnisis Wayshrine in the northern West Gash region, I should follow the eastbound road until I reach a tall tree with a streetlamp. Paths diverge, but I should head north on a torchlit path past a fungus-sprouting boulder, then beyond a secluded campfire. The path curves east and then south into a rocky area haunted by wraiths. The Orator's tomb looks like a cavernous amphitheater with several braziers aflame."},
        [2] = 
            {appendStepText="East of Gnisis, I defeated the Orator along with other spirits and wraiths. ", stepTextKey="I should travel to Ivulen Andromo in Vivec City to collect my reward."},
        ["Talk to Ivulen Andromo"] =
            {appendText=". The surly, well-dressed historian is probably still writing while sitting on the same long bench on the mezzanine in Saint Olms Waistworks."},
    },

[GetQuestName(5906)] = { --"Siren's Song"				--Jordakai
        [1] = 
            {appendStepText="Beleru Omoril of Vivec City's Hall of Justice mentioned a female Imperial, Valga Celatus. She is in Saint Olms Waistworks' southeast hallway used by Tanners and Miners Hall patrons.\n\nWhen I'm ready, ", stepTextKey="I should travel to Shipwreck Cove to defeat the Nereid and collect the cargo scattered along the shoreline."},
        ["Defeat Kimbrudhil the Songbird"] =
            {appendText=" and her spellbound guardians.\n"},
        ["Recover Cargo"] =
            {appendText="\n\nOn the island's southern shoreline in a secluded cove of the Azura's Coast region, east of Vivec City and northwest of Tel Branora, there is a shipwreck."},
        [2] = 
            {appendStepText="I defeated the nereid and recovered the cargo from the shipwreck on the southern shoreline of Azura's Coast. ", stepTextKey="I should travel to Valga Celatus in Vivec City to collect my reward."},
        ["Talk to Valga Celatus"] =
            {appendText=". The stylish Imperial waits for me in the hallway near the Tanners and Miners Hall in Saint Olms Waistworks."},
    },

[GetQuestName(5956)] = { --"Daedric Disruptions"				--Jordakai
        [1] = 
            {appendStepText="Traylan Omoril in Vivec City's Hall of Justice has given me an assignment. North of Gnisis and west of the Urshilaku Wayshrine in the West Gash, I should find an ancient Daedric shrine. ", stepTextKey="I must prevent the Worm Cult from completing their work by disrupting all of their rituals."},
        ["Disrupt the Dark Ritual"] =
            {appendText=". The Worm Cultists are summoning outside on one of the ruin's platforms.\n"},
        ["Disrupt the Ritual of Knowledge"] =
            {appendText=" in the lower, southernmost Sunken Vault chamber. It can be reached through the western hallway after entering the shrine.\n"},
        ["Disrupt the Dremora Worship Ritual"] =
            {appendText=". There is a platform up in the northeastern area of the Sunken Vault cavern.\n"},
        ["Disrupt the Clannfear Feast"] =
            {appendText=" in the Sunken Vault's northern cavern, up on the highest platform to the northwest. \n\nOrdinator Savile Alam is in St. Delyn Plaza, the uppermost chamber of that canton."},
        [2] = 
            {appendStepText="", stepTextKey="Now that I have disrupted the Daedra summoning rituals at Ashalmawia I should inform Savile Alam of my success."},
        ["Talk to Savile Alam"] =
            {appendText=", the Ordinator. She is likely at Vivec City's St. Delyn Plaza in the uppermost level of that canton."},
    },

    [GetQuestName(5962)] = { --"Kwama Conundrum"				--Jordakai
        [1] = 
            {appendStepText="Traylan Omoril of Vivec City's Hall of Justice mentioned Kylia Thande. She is in the Saint Delyn Plaza, the top level of the canton.\n\nThe mine is in a remote area of Azura's Coast, far south of the eastern city of Sadrith Mora. ", stepTextKey="I should head to Matus-Akin Egg Mine in order to acquire breeding research and a kwama egg from the primary egg chamber. I must also plant poisoned kwama feed in the mine's food storage area."},
        ["Plant Poisoned Feed"] =
            {appendText=". The feedstocks are kept in a storage area near the egg mine's entrance, but I will need to circle around through the tunnels to reach it.\n"},
        ["Retrieve a Kwama Egg"] =
            {appendText=". The kwama usually keep their eggs in a cavern far from a mine's entrance. I should check the southwestern cavern first.\n"},
        ["Acquire Breeding Research"] =
            {appendText=" Notes. I suspect there will be a makeshift work area, perhaps in the small cavern north of the large, central cavern.\n\nFrom the eastern city of Sadrith Mora, travel far south to an inlet with a dock where two Dunmer and a Nix-Ox met their end. A path leads to the west, under an arch and on to the mine's entrance."},
        [2] = 
            {appendStepText="Now that I have done what I was asked to do at the egg mine, ", stepTextKey="I should return to Kylia Thande for my reward."},
        ["Talk to Kylia Thande"] =
            {appendText=". She is in Vivec City's Saint Delyn Plaza, the uppermost chamber of its canton."},
},

    [GetQuestName(5961)] = { --"Planting Misinformation"				--Jordakai
        [1] = 
            {appendStepText="Traylan Omoril of Vivec City's Hall of Justice mentioned Evos Hlades. He is in Saint Delyn Plaza, the top level of the canton.\n\nThe cavern's entrance is marked by a campfire along the Bitter Coast's swamp trail, northwest of Seyda Neen. ", stepTextKey="I should head to Zainsipilu in order to leave the false notes near the primary moon-sugar crop and on the bandits research table."},
        ["Place Unintelligible Instructions Near the Crops"] =
            {appendText=" growing in the center pond of the large cavern. An illuminated table sits near the fire-river's gorge.\n"},
        ["Place Misleading Notes on the Research Table"] =
            {appendText=" located in the smaller, southwestern cavern."},
        [2] = 
            {appendStepText="I placed the notes on tables in the moon-sugar cavern northwest of Seyda Neen. ", stepTextKey="I should return to Evos Hledas for my reward."},
        ["Talk to Evos Hledas"] =
            {appendText=" as he enjoys a drink in Vivec City's Saint Delyn Plaza, the uppermost chamber of its canton."},
    },

    [GetQuestName(5934)] = { --"Tax Deduction"				--Jordakai
        [1] = 
            {appendStepText="Traylan Omoril of Vivec City's Hall of Justice mentioned Alves Droth. She is sitting across from the musician in Saint Delyn Plaza, the uppermost chamber of the canton. \n\nI should follow the road south from the Tel Mora Wayshrine until I reach a sharp westerly bend in the road. The cavern is east of that bend. ", stepTextKey="The thieves responsible are believed to be hiding out in Pulk. I should search for the missing records and gold there."},
        ["Collect Vos Tax Records"] =
            {appendText=" sitting on a cabinet with a candelabra in the southwestern cavern on the lower level.\n"},
        ["Collect Sadrith Mora Tax Records"] =
            {appendText=" from a barrel shelf in the wooden alcove of the northern cavern on the lower level.\n"},
        ["Collect Molag Mar Tax Records"] =
            {appendText=" sitting on top of a drum near a stack of barrels roped together in the northeast corner hallway of the upper level."},
        [2] = 
            {appendStepText="In Pulk, the bandit hideout south of Tel Mora Wayshrine near the sharp bend in the road, I was successful. ", stepTextKey="Now that I have the tax records in hand, I should retreive the stolen taxes from Bralsa Inlador."},
        ["Collect Stolen Taxes"] =
            {appendText=" from the large chest in a cart by the water's edge in the easternmost lower level area. Bralsa Inlador, the bandit leader, may be nearby."},
        [3] = 
            {appendStepText="In Pulk, ", stepTextKey="I collected the tax records and stolen taxes from Pulk. I should deliver the goods to Alves Droth in Vivec City."},
        ["Return to Alves Droth in Vivec City"] =
            {appendText=". She is waiting in Saint Delyn Plaza, the uppermost level of its canton."},
    },

    [GetQuestName(5915)] = { --"Tribal Troubles"				--Jordakai
        [1] = 
            {appendStepText="In Vivec City's Hall of Justice, Traylan Omoril mentioned I should speak with Dredase-Hlarar, an Ashlander resting in Saint Delyn Plaza in the uppermost chamber of its canton. \n\nThe Dwemer ruin is secluded in the craggy rocks of the Grazelands' western edge, northwest of Zainab Camp and west of Tel Mora Wayshrine. ", stepTextKey="I should head to Nchuleft in order to collect a Dwarven cog, rod, gear, and core for the Ashlanders of Zainab."},
        ["Collect the Cog"] =
            {appendText=" from a lone crate in the only room of Nchuleft Ruins reached through the northernmost door from the Nchuleft Ingress.\n"},
        ["Collect the Rod"] =
            {appendText=" from a lone crate with a pale blue lamp on the ground on the west side of the cavern, just south of the doors to Nchuleft Ruins. The lowest level's central chamber, where the Far-Hurler appears, is across the pipes spanning the lava flow nearby.\n"},
        ["Collect the Gear"] =
            {appendText=" from a wooden crate near a Dwemer lamp. From the Depth's top central chamber, follow the curved bridge to reach the northwestern platform.\n"},
        ["Collect the Core"] =
            {appendText=" from the construct called the Nchuthand Far-Hurler. It appears in the central chamber of the Depth's lowest level. \n\nNchuleft Depths has a ruin of four levels: the top, first level reached from the central hallway of Nchuleft's Ingress upon entering the site. The second and third levels are down from the top, and finally the fourth and lowest level is on the cavern's ground floor. \n\nFrom the Nchuleft Ingress, the central door opens to the Nchuleft Depth's top level. From the Ingress' northern door into the Nchuleft Ruins, one can quickly reach the lowest level of the Depths."},
        [2] = 
            {appendStepText="In the Dwemer ruins at the western edge of the Grazelands, west of Tel Mora Wayshrine, I found the four Dwarven parts. Now that I have them with me, ", stepTextKey="I should talk to Dredase-Hlarar to collect my reward."},
        ["Talk to Dredase-Hlarar"] =
            {appendText=". The Ashlander is likely enjoying a drink in Vivec City's Saint Delyn Plaza, the uppermost chamber of its canton."},
    },

    [GetQuestName(5958)] = { --"Unsettled Syndicate"				--Jordakai
        [1] = 
            {appendStepText="In Vivec City's Hall of Justice, Traylan Omoril mentioned I could speak with Vorar Vendu at Saint Delyn Plaza in the uppermost chamber of its canton, to get more information.\n\nMy destination is a cavern near a dock on the coast south of Gnisis and southwest of West Gash Wayshrine. It is not far from an ancient Velothi fortress. ", stepTextKey="I should head to Khartag Point in order to kill the Camonna Tong's commander and find evidence of slave activity within their campsite."},
        ["Search the Campsite for Slave Activity"] =
            {appendText=". I should look for evidence in the caverns, most likely in the northern cave farthest from the entrance.\n"},
        ["Kill Avrusa Duleri"] =
            {appendText=". He has a camp on the ledge overlooking the entrance. I will need to circle around to reach him."},
        [2] = 
            {appendStepText="At Khartag Point, on the coast south of Gnisis, I defeated the Camona Tong's commander and found evidence of their slave trade. ", stepTextKey="I should head back to Vorar Vendu to collect my reward."},
        ["Talk to Vorar Vendu"] =
            {appendText=". He waits in Vivec City's Saint Delyn Plaza, on the uppermost level of its canton, standing near a pillar."},
    },
					

-- ==================================================================================================================================================
--	Clockwork City																														Undaunted
-- ==================================================================================================================================================

	[GetQuestName(6050)] = { --"To The Clockwork City"				--Jordakai
		[1] = 
			{appendStepText="", stepTextKey="I must seek out the legendary Dark Elf mage, Divayth Fyr, in the Mournhold Tribunal Temple."},
		["Talk to Divayth Fyr 1"] =
			{appendText=".\n\nVivec has his palace at Vivec City in Vvardenfell. Almalexia has her temple at Mournhold in Deshaan. And Sotha Sil has his Clockwork City.\n\nDivayth Fyr travels, wherever he chooses.", stepTextKey="I must seek out the legendary Dark Elf mage, Divayth Fyr, in the Mournhold Tribunal Temple."},
		[2] = 
			{appendStepText="In the Tribunal Temple at Deshaan's central city of Mournhold, I met the legendary mage. ", stepTextKey="I decided to join Divayth Fyr on his expedition to the Clockwork City. Our journey begins at the waterfall just north of Mournhold."},
		["Meet Divayth Fyr at the Waterfall"] =
			{appendText=" behind the temple."},
		[3] = 
			{appendStepText="Just north of Deshaan's central city, ", stepTextKey="Divayth revealed a secret door behind the waterfall that leads to a cavern deep beneath Mournhold. We must navigate this cave network to find the Clockwork City entrance."},
		["Enter the Secret Cavern"] =
			{appendText="."},
		[4] = 
			{appendStepText="North of Deshaan's central city of Mournhold, we entered a cavern hidden by a waterfall. ", stepTextKey="Divayth told me that the entrance to Clockwork City waits just ahead. I should delve deeper into the cavern."},
		["Find the Entrance to the Clockwork City"] =
			{appendText=". I should follow Divayth to the far end of the cavern and through Seht's Vault."},
		[5] = 
			{appendStepText="North of Deshaan's central city of Mournhold, behind a waterfall and through a cavern and a vault, ", stepTextKey="I discovered an ornate clockwork globe, housing a miniature Clockwork City. I should use the device to enter Sotha Sil's realm."},
		["Use the Clockwork Globe"] =
			{appendText="."},
		[6] = 
			{appendStepText="From the secret cavern and Seht's Vault hidden by a waterfall north of Deshaan's Mournhold, ", stepTextKey="Divayth Fyr and I arrived in a remote, underground section of the Clockwork City. Divayth Fyr seems concerned. I should stand ready to defend against any attack."},
		["Protect Divayth Fyr 1"] =
			{appendText=".", stepTextKey="Divayth Fyr and I arrived in a remote, underground section of the Clockwork City. Divayth Fyr seems concerned. I should stand ready to defend against any attack."},
		[7] = 
			{appendStepText="In the Clockwork City Vaults, ", stepTextKey="Divayth Fyr's shadow suddenly came to life and attacked its owner. It did not strike a mortal blow, but Divayth is clearly weakened. I must pursue this shadowy attacker deeper into the clockwork underground."},
		["Chase Divayth's Shadow 1"] =
			{appendText=" into the Factotum Depository.", stepTextKey="Divayth Fyr's shadow suddenly came to life and attacked its owner. It did not strike a mortal blow, but Divayth is clearly weakened. I must pursue this shadowy attacker deeper into the clockwork underground."},
		[8] = 
			{appendStepText="In the Clockwork City Vaults, ", stepTextKey="Divayth's treacherous shadow led us into a room guarded by clockwork factotums. I must defeat them to clear the way forward."},
		["Defeat the Factotums"] =
			{appendText="."},
		[9] = 
			{appendStepText="In the Clockwork City Vaults, ", stepTextKey="Defeating the factotums appears to have opened a door to the next section of the clockwork underground. I must continue my search for Divayth's shadow."},
		["Chase Divayth's Shadow 2"] =
			{appendText=" through the north door.", stepTextKey="Defeating the factotums appears to have opened a door to the next section of the clockwork underground. I must continue my search for Divayth's shadow."},
		[10] = 
			{appendStepText="In the Clockwork City Vaults, we entered the northeastern area, the Scrubbing Bore. \n\n", stepTextKey="In his weakened state, Divayth Fyr cannot safely bypass the clockwork underground's defenses. I must move ahead and find a way to shut down the traps so he can travel safely through the halls."},
		["Disable the Traps"] =
			{appendText=". The first switch is likely in the square northern chamber. The second is probably farther into the facility, perhaps in a short side passage near the round chamber. I should speak with Divayth, too."},
		[11] = 
			{appendStepText="In the Clockwork City Vaults, I found the switches. ", stepTextKey="A slightly stronger Divayth Fyr arrived shortly after I disabled the final traps. We have to keep moving forward. His shadow must be nearby."},
		["Chase Divayth's Shadow 3"] =
			{appendText=" southeast of the round chamber through the narrow passage leading into the Pneumatic Forge, the large southern area.\n\nThen west into the Pneumatic Approach and north through the passageways.", stepTextKey="A slightly stronger Divayth Fyr arrived shortly after I disabled the final traps. We have to keep moving forward. His shadow must be nearby."},
		[12] = 
			{appendStepText="We reached the northwestern chamber known as the Prime Pneumatorium in the Clockwork City Vaults. ", stepTextKey="We finally caught up to Divayth's Shadow. Now we must defeat it so Divayth Fyr can reclaim his lost power."},
		["Defeat Divayth's Shadow"] =
			{appendText=" in the Prime Pneumatorium."},
		[13] = 
			{appendStepText="Within the northwestern chamber known as the Prime Pneumatorium, we succeeded. ", stepTextKey="With Divayth's help, I beat the treacherous shadow into submission. I must defend Divayth as he attempts to recover his power."},
		["Protect Divayth Fyr 2"] =
			{appendText=" again.", stepTextKey="With Divayth's help, I beat the treacherous shadow into submission. I must defend Divayth as he attempts to recover his power."},
		[14] = 
			{appendStepText="There was another assault by factotums in the Clockwork City Vaults' northwestern chamber. ", stepTextKey="A fully restored Divayth Fyr defeated the last of the factotums, allowing us to escape the Pneumatic Forge. We should make our way to the surface."},
		["Exit the Pneumatic Forge"] =
			{appendText=" through the northern door."},
		[15] = 
			{appendStepText="", stepTextKey="We finally reached the surface of the Clockwork City! Divayth Fyr suggested we take the road to the Brass Fortress—Sotha Sil's seat of power. I should make my way there."},
		["Reach the Brass Fortress"] =
			{appendText=". It is northwest of the Pneumatic Forge we exited and north of the Clockwork Crossroads Wayshrine."},
		[16] = 
			{appendStepText="", stepTextKey="I have reached the gates of the Brass Fortress and must escort Divayth Fyr inside."},
		["Escort Divayth Fyr"] =
			{appendText="."},
		[17] = 
			{appendStepText="", stepTextKey="An imposing clockwork mage confronted us outside the gates to the Brass Fortress. She made it clear that she disapproves of Divayth's presence. I should try to defuse the situation."},
		["Talk to Proctor Luciana Pullo"] =
			{appendText=", a striking woman with a large weapon."},
		[18] = 
			{appendStepText="", stepTextKey="Protor Luciana Pullo, leader of the Clockwork Apostles, told me that all newcomers to the Brass Fortress must be sponsored before they can gain full access. Perhaps Divayth Fyr can act as my sponsor. I should speak with him."},
		["Talk to Divayth Fyr 2"] =
			{appendText=" outside the gates of the fortress.", stepTextKey="Protor Luciana Pullo, leader of the Clockwork Apostles, told me that all newcomers to the Brass Fortress must be sponsored before they can gain full access. Perhaps Divayth Fyr can act as my sponsor. I should speak with him."},
		[19] = 
			{appendStepText="", stepTextKey="Divayth Fyr may be able to sponsor me for Brass Fortress access. I should speak with him outside the gates."},
		["Talk to Divayth Fyr 3"] =
			{appendText=".", stepTextKey="Divayth Fyr may be able to sponsor me for Brass Fortress access. I should speak with him outside the gates."},
	},

[GetQuestName(6057)] = { --"In Search of a Sponsor"				--Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Neramo told me that Kireth and Raynor might need my help to acquire a gift for our potential sponsor, Varuni Arvel. I should talk to Kireth outside the gates of the Brass Fortress."},
		["Talk to Kireth 1"] =
			{appendText=" as she takes in the view from the edge of the nearby cliff.", stepTextKey="Neramo told me that Kireth and Raynor might need my help to acquire a gift for our potential sponsor, Varuni Arvel. I should talk to Kireth outside the gates of the Brass Fortress."},
		[2] = 
			{appendStepText="", stepTextKey="Kireth asked me to check on her brother, Raynor, in the ravine surrounding the Brass Fortress. The firepot spiders lurking down there sound particularly dangerous. Raynor might need my help."},
		["Talk to Raynor 1"] =
			{appendText=". There is an illuminated path to the west of the city gates that zigzags down into the ravine.", stepTextKey="Kireth asked me to check on her brother, Raynor, in the ravine surrounding the Brass Fortress. The firepot spiders lurking down there sound particularly dangerous. Raynor might need my help."},
		[3] = 
			{appendStepText="Near the bottom of the illuminated, zigzag trail, west of the city gates, I found Kireth's brother. ", stepTextKey="Raynor intends to drain a valuable substance from nearby Firepot Spiders. Unfortunately, they tend to explode when disturbed. Raynor created a device to suppress this behavior. I must disable the spiders so he can drain the liquid."},
		["Help Raynor Collect Firepot Oil"] =
			{appendText=" \n\nAfter I disable the firepot spiders, Raynor can use his latest invention. The glowing machines are scattered around the oil ponds of the Insalubrious Effluvium."},
		[4] = 
			{appendStepText="From the firepot spiders in oil ponds of the Insalugrious Effluvium ravine below the city, ", stepTextKey="Raynor collected enough firepot oil to satisfy our potential sponsor, Varuni. I must collect the oil from him before returning to the Brass Fortress."},
		["Talk to Raynor 2"] =
			{appendText=" and get the oil.", stepTextKey="Raynor collected enough firepot oil to satisfy our potential sponsor, Varuni. I must collect the oil from him before returning to the Brass Fortress."},
		[5] = 
			{appendStepText="From the Insalubrious Effluvium ravine, ", stepTextKey="Raynor and I successfully obtained the firepot spider oil. Now I must deliver it to Varuni Arvel. I'll find her office in the Clockwork Basilica."},
		["Deliver Oil to Varuni"] =
			{appendText=". I have the explosive distillate that Raynor made from the firepot spider oil.\n\nThe Clockwork Basilica is a towering structure that dominates the city's north. Her office is on the main floor, to the southwest."},
		[6] = 
			{appendStepText="The Clockwork Basilica dominates the north of the Brass Fortress. In the southeast of the building's main floor, ", stepTextKey="Neramo arrived in Varuni's office ahead of me. It looks like he already has a plan for our next move. I should speak to him."},
		["Talk to Neramo 1"] =
			{appendText=".", stepTextKey="Neramo arrived in Varuni's office ahead of me. It looks like he already has a plan for our next move. I should speak to him."},
		[7] = 
			{appendStepText="", stepTextKey="Neramo co-opted a small clockwork automaton known as a skeevaton. We can use this creature to retrieve vital information from the Brass Fortress' Depository Documatis. I should meet Neramo outside the building to activate it."},
		["Activate the Skeevaton"] =
			{appendText=" after we are in place to send it into the Depository Documatis.\n\nNeramo found a hole in a grate at the back of a building that is southeast of the Basilica, and next to Daram Stables. I should meet him there."},
		[8] = 
			{appendStepText="Near Brass Fortress' Daram Stables, we found a hole in a grate and put the skeevaton inside. ", stepTextKey="I am remotely controlling Neramo's co-opted skeevaton, and must navigate it through a maze of pipes called the serviflume. The tunnels should lead into the Depository Documatis."},
		["Navigate the Serviflume"] =
			{appendText=". There is an entrance in the eastern area. I should avoid any hostile factotums."},
		[9] = 
			{appendStepText="", stepTextKey="I directed the skeevaton into the Depository Documatis. Now I must search the building for the evidence Varuni requested."},
		["Search for Evidence"] =
			{appendText=". I must avoid being seen.\n\nThere is a large circular repository in first area's southern chamber and another in the northern chamber. The exit is a ventilation grate in the northern chamber's northeast wall.\n\nIn the second area, there is a circular repository in the northern chamber's west. In the southern chamber there are two. I should use the northern repository. Then I should exit through the door at the south end of the southern chamber."},
		[10] = 
			{appendStepText="", stepTextKey="My skeevaton infiltration of the Depository Documatis was a success! I guided the skeevaton out of the building. I should meet Neramo at the building's exit."},
		["Find Neramo"] =
			{appendText=". He is waiting on the northwest side of the building that is by Daram Stables in Brass Fortress."},
		[11] = 
			{appendStepText="On the northwest side of the building by Daram Stables in Brass Fortress, ", stepTextKey="I found Neramo outside the Depository Documatis. I should speak with him."},
		["Talk to Neramo 2"] =
			{appendText=".", stepTextKey="I found Neramo outside the Depository Documatis. I should speak with him."},
		[12] = 
			{appendStepText="", stepTextKey="While Neramo and I searched the Depository Documatis, Kireth has been conducting her own investigation on Varuni's behalf. I should see if she needs any help."},
		["Talk to Kireth 2"] =
			{appendText=". She is on the west side of The Grand Depository, the bank of Brass Fortress.", stepTextKey="While Neramo and I searched the Depository Documatis, Kireth has been conducting her own investigation on Varuni's behalf. I should see if she needs any help."},
		[13] = 
			{appendStepText="I spoke with Kireth by The Grand Depository of the Brass Fortress. ", stepTextKey="Kireth suspects that one of the city constables, Baldan,  is sponsoring newcomers in exchange for bribes. She asked me to record her conversation with him. I should get into position in the storage loft."},
		["Enter the Storage Loft"] =
			{appendText=" of the building that is northwest of the bank, probably from its northeast side up near the basilica."},
		[14] = 
			{appendStepText="I entered the Storage Loft in the top of Baldan's building, northwest of The Grand Depository. ", stepTextKey="I must observe Kireth's conversation with Constable Baldan and archive their words on the memory stone she provided."},
		["Observe Kireth's Conversation"] =
			{appendText="."},
		[15] = 
			{appendStepText="In the Storage Loft above Baldan's office near the Brass Fortress' basilica, I saw it. ", stepTextKey="Constable Baldan's henchmen knocked out and abducted Kireth! I need to see if I can get into the building where she was knocked out and save her."},
		["Look for Kireth"] =
			{appendText=". I should go to the entrance of Baldan's building, northwest of The Great Depository."},
		[16] = 
			{appendStepText="Northwest of The Grand Depository, the bank of Brass Fortress, I went to Baldan's building. ", stepTextKey="The door to Constable Baldan's office is locked, but I found Raynor. I should inform him of Kireth's abduction and send him for help."},
		["Talk to Raynor 3"] =
			{appendText=".", stepTextKey="The door to Constable Baldan's office is locked, but I found Raynor. I should inform him of Kireth's abduction and send him for help."},
		[17] = 
			{appendStepText="In front of the building northwest of Brass Fortress' bank, The Grand Depository, I spoke with Kireth's brother. ", stepTextKey="Raynor suggested I talk to the residents of Slag Town—a slum in the Brass Fortress. They might have an idea of where the constables would take Kireth."},
		["Investigate Kireth's Abduction"] =
			{appendText=". Raynor recommended I start in Slag Town, the city's northeastern tenement area. I think I will start by speaking with people near Daram Stables, before I head into the Outlaw Refuge."},
		[18] = 
			{appendStepText="In Slag Town, ", stepTextKey="I discovered that the constables often throw undesirables into the Mechanical Fundament—a network of tunnels beneath the Brass Fortress. I must descend into the Fundament to find Kireth."},
		["Enter the Mechanical Fundament"] =
			{appendText=" in the Reactor District's far northwest. The Reactor District's entrance is west of the city's tavern, The Cloisters. To reach the Fundament, I will follow the road through the district."},
		[19] = 
			{appendStepText="In the Brass Fortress' Reactor District, to the far northwest, ", stepTextKey="I must find Kireth in the Mechanical Fundament."},
		["Find Kireth"] =
			{appendText="."},
		[20] = 
			{appendStepText="In Mechanical Fundament in the far northwest of the Brasswork Fortress' Reacter District, ", stepTextKey="I found Kireth, alive and unharmed, but she refuses to leave. Apparently, Baldan threw another newcomer into the Fundament before her—a Khajiit named Lankin. We must find him before we escape."},
		["Search for Lankin"] =
			{appendText=" at his camp in the cavern. If Kireth and I don't find the Khajiit there, we may need to go farther into the Fundament, going into every nook and cranny in all areas of the facility."},
		[21] = 
			{appendStepText="In Mechanical Fundament in the far northwest of the Brasswork Fortress' Reacter District, we did not find Lankin in the cavern. ", stepTextKey="Kireth believes we are very close to finding Lankin. We should keep looking."},
		["Find Lankin"] =
			{appendText=". We must go farther into the Fundament, going into every nook and cranny in all areas of the facility."},
		[22] = 
			{appendStepText="In the depths of the Mechanical Fundament, far from its entrance in the Brass Fortress' Reactor District, ", stepTextKey="Kireth and I found Lankin. We must all exit the Mechanical Fundament as soon as possible."},
		["Escape the Mechanical Fundament"] =
			{appendText=", starting with dropping through a hole in the floor near a locked door to the south."},
		[23] = 
			{appendStepText="", stepTextKey="Raynor succeeded in finding help. Proctor Luciana, Varuni Arvel, Constable Baldan, and others were waiting for us when we emerged from the lower sections of the Fundament. I should tell Luciana about Baldan's illegal activities."},
		["Talk to Luciana"] =
			{appendText=". She and the others met us on the main level of the Brass Fortress' northwesternmost facility, just inside the entrance. "},
		[24] = 
			{appendStepText="Just inside of Brass Fortress' Mechanical Fundament's entrance near lower entrance of The Grand Depository, I finished speaking with Proctor Luciana Pullo. ", stepTextKey="In a strange turn of events, Varuni demanded that Luciana turn Constable Baldan over to her. I should speak to her to make sure Baldan faces justice."},
		["Talk to Varuni"] =
			{appendText=" Arvel, the Provost."},
		[25] = 
			{appendStepText="", stepTextKey="An appreciative Varuni finally agreed to sponsor me, Neramo, Kireth, and Raynor for citizenship in the Brass Fortress. I must report to the Clockwork Registrar to make it official."},
		["Talk to the Clockwork Registrar"] =
			{appendText=" in the Chancel of Records, northwest of the city's tavern, The Cloisters."},
		[26] = 
			{appendStepText="In the Chancel of Records, northwest of The Cloisters tavern in Brass Fortress, I became a citizen. ", stepTextKey="Neramo followed me to the Clockwork Registrar. I should speak to him about his plans."},
		["Talk to Neramo 3"] =
			{appendText=".", stepTextKey="Neramo followed me to the Clockwork Registrar. I should speak to him about his plans."},
		[27] = 
			{appendStepText="In the Chancel of Records, northwest of The Cloisters tavern in Brass Fortress, I became a citizen. ", stepTextKey="Neramo followed me to the clockwork registrar. I should speak to him about his plans."},
		["Talk to Neramo 4"] =
			{appendText=".", stepTextKey="Neramo followed me to the clockwork registrar. I should speak to him about his plans."},
	},

	[GetQuestName(6063)] = { --"The Strangeness of Seht"				--Jordakai
		[1] = 
			{appendStepText="In the Chancel of Records, west of The Great Depository in the Brass Fortress, ", stepTextKey="I should speak to Divayth about his plans to discover the source of Sotha Sil's new and peculiar behavior."},
		["Talk to Divayth Fyr 1"] =
			{appendText=".", stepTextKey="I should speak to Divayth about his plans to discover the source of Sotha Sil's new and peculiar behavior."},
		[2] = 
			{appendStepText="", stepTextKey="Divayth wants me to conduct quiet inquiries in the Clockwork Basilica. He seems convinced that the various aides who work there will know more about Sotha Sil's recent behavior. I should talk to as many as I can find."},
		["Ask Aides about Sotha Sil"] =
			{appendText=" \n\nThe Basilica is the Brass Fortress' imposing northern structure. I should be able to find aides on the main floor there."},
		[3] = 
			{appendStepText="From the aides at the Clockwork Basilica in Brass Fortress, ", stepTextKey="I collected a number of complaints about Sotha Sil's bizarre and annoying behavior. I should inform Divayth Fyr."},
		["Talk to Divayth Fyr 2"] =
			{appendText=" inside the Basilica's entry.", stepTextKey="I collected a number of complaints about Sotha Sil's bizarre and annoying behavior. I should inform Divayth Fyr."},
		[4] = 
			{appendStepText="I spoke with Divayth in the Brass Fortress' Clockwork Basilica. ", stepTextKey="Divayth Fyr wants me to find out why Sotha Sil ordered the lights removed from the loqutorium, and perhaps construct a light of our own. I'll need Neramo's help."},
		["Talk to Neramo 1"] =
			{appendText=". He is probably checking for Dwarven parts with a merchant in the Chancel of Transaction plaza.", stepTextKey="Divayth Fyr wants me to find out why Sotha Sil ordered the lights removed from the loqutorium, and perhaps construct a light of our own. I'll need Neramo's help."},
		[5] = 
			{appendStepText="I'll use an entrance to the Brass Fortress' Mechanical Fundament near the merchants' plaza, by the lower door of The Grand Depository. After speaking with Neramo, ", stepTextKey="I agreed to enter the Mechanical Fundament to look for clues. According to the aides, the factotums may have discarded some of the lamps there. Perhaps Neramo can determine what makes them so unique."},
		["Investigate Dented Lamp Tube"] =
			{appendText="."},
		["Investigate Charred Filaments"] =
			{appendText="."},
		["Investigate Broken Compressor"] =
			{appendText="."},
		["Investigate Broken Modulator"] =
			{appendText=".\n\nNeramo and I should be able to find all four items around the main area's central, narrow hallways. We will need to inspect every part, whether in a crate or on the floor."},
		[6] = 
			{appendStepText="In the main area of the Mechanical Fundament at the Brass Fortress, we found the lamp parts in the central, narrow hallways. ", stepTextKey="It seems that Neramo has discerned the unique lamps' function. I should talk to him."},
		["Talk to Neramo 2"] =
			{appendText=".", stepTextKey="It seems that Neramo has discerned the unique lamps' function. I should talk to him."},
		[7] = 
			{appendStepText="", stepTextKey="Neramo believes he can build a lamp just like the broken ones we found in the Fundament, but he needs a number of very specific components. I must buy, barter, or hunt fabricants for those parts."},
		["Collect Lamp Tube"] =
			{appendText=". I should just buy this lamp part. At the Domicile Enhancement Hub by the Brass Fortress wayshrine, a Redguard stands near a barrel and two crates.\n"},
		["Collect Clockwork Filaments"] =
			{appendText=" \n\nFactotums and Fabricants have filaments.\n"},
		["Collect Modulated Compressor"] =
			{appendText=" from a Verminous Fabricant, often found in the eastern area's southernmost hall.\n\nFactotums and Fabricants roam the southern and eastern areas of the Fundament's main floor."},
		[8] = 
			{appendStepText="", stepTextKey="I collected all the parts Neramo requested. I should deliver these components so he can complete our unique lamp. I can find him in the Hall of Refined Techniques."},
		["Deliver Parts to Neramo"] =
			{appendText=" in the Hall, east of the Chancel of Transactions in the central Brass Fortress."},
		[9] = 
			{appendStepText="In the Brass Fortress' Hall of Refined Techniques, ", stepTextKey="Neramo and Raynor should complete work on the lamp soon. In the meantime, I should make my way to the Clockwork Basilica and inform Divayth Fyr of our progress."},
		["Talk to Divayth Fyr 3"] =
			{appendText=" on the main floor in the city's northern structure.", stepTextKey="Neramo and Raynor should complete work on the lamp soon. In the meantime, I should make my way to the Clockwork Basilica and inform Divayth Fyr of our progress."},
		[10] = 
			{appendStepText="", stepTextKey="Kireth arrived with the completed lamp, but she seems concerned. I should talk to her."},
		["Talk to Kireth"] =
			{appendText="."},
		[11] = 
			{appendStepText="Kireth delivered the new lamp to me in the Clockwork Basilica, the Brass Fortress' northern structure. Now ", stepTextKey="I must make my way to the balcony that overlooks the loqutorium and place our unique light in a place where it can shine down on the stage below. Unfortunately, the upper floors are crawling with guards. I must be cautious."},
		["Place the Lamp"] =
			{appendText=" on the balcony overlookng the north-central chamber.\n\nTo get to the upper floor, I should use the northern lift device in the first chamber east of the Basilica's entry."},
		[12] = 
			{appendStepText="In the Brass Fortress' northern structure, the Clockwork Basilica, ", stepTextKey="I placed the lamp on the balcony. I should inform Divayth Fyr."},
		["Talk to Divayth Fyr 4"] =
			{appendText=". He is waiting in the first chamber east of the Basilica's entry.", stepTextKey="I placed the lamp on the balcony. I should inform Divayth Fyr."},
		[13] = 
			{appendStepText="In the Clockwork Basilica, the northern structure of the Brass Fortress, I spoke with Divayth again. ", stepTextKey="When Sotha Sil steps out on stage and begins his lecture, I must activate the lamp and observe the results."},
		["Activate the Lamp"] =
			{appendText=". I should go to a switch in the Basilica's northern chamber on the main floor."},
		[14] = 
			{appendStepText="In the northern conversation chamber of the Clockwork Basilica, when I switched on the new lamp, ", stepTextKey="I revealed Sotha Sil as an imposter! Apparently, a malevolent shadow took his place. It fled into Sotha Sil's private rectory. I must track it down and defeat it before it gets away."},
		["Defeat the Shadow of Sotha Sil"] =
			{appendText=" that fled through the northwest door to the Sotha Sacristy."},
		[15] = 
			{appendStepText="Within the Sotha Sacristy in the Clockwork Basilica of the Brass Fortress, ", stepTextKey="I defeated the Shadow of Sotha Sil. I should speak to Divayth Fyr and see if he has any thoughts on what just occurred."},
		["Talk to Divayth Fyr 5"] =
			{appendText=" in the Loqutorium, the basilica's northern conversation chamber.", stepTextKey="I defeated the Shadow of Sotha Sil. I should speak to Divayth Fyr and see if he has any thoughts on what just occurred."},
		[16] = 
			{appendStepText="In the Brass Fortress' northern structure, I conversed with Divayth Fyr. ", stepTextKey="A very concerned Divayth Fyr encouraged me to talk to Varuni Arvel. I should speak with her."},
		["Talk to Varuni 1"] =
			{appendText=" Arvel, the Proctor, in the northern conversation chamber, the Loqutorium of the Clockwork Basilica.", stepTextKey="A very concerned Divayth Fyr encouraged me to talk to Varuni Arvel. I should speak with her."},
		[17] = 
			{appendStepText="In the northern conversation chamber of the Clockwork Basilica in Brass Fortress, I spoke with the Proctor. ", stepTextKey="Varuni is very concerned about the future of Clockwork City. I should talk to her to see how she'd like to proceed."},
		["Talk to Varuni 2"] =
			{appendText=" in the Loqutorium.", stepTextKey="Varuni is very concerned about the future of Clockwork City. I should talk to her to see how she'd like to proceed."},
	},

[GetQuestName(6025)] = { --"Deepening Shadows"				--Jordakai
		[1] = 
			{appendStepText="At the Clockwork Basilica, the northernmost structure in the Brass Fortress, ", stepTextKey="Provost Varuni asked me to find Chancellor Gascone. She seems confident that I'll find him in his rectory in the west wing of the Clockwork Basilica."},
		["Search Gascone's Rectory"] =
			{appendText=", the westernmost chamber on the Basilica's main floor."},
		[2] = 
			{appendStepText="At the Clockwork Basilica in the Brass Fortress, ", stepTextKey="I discovered a Nocturnal Shrike in Chancellor Gascone's office. She seemed to be looking for something. I also found a farewell memorandum penned by Gascone. I should tell Varuni about all I've seen."},
		["Talk to Varuni 1"] =
			{appendText=" in the eastern chamber of the Clockwork Nave in the Basilica, just outside Gascone's Rectory.", stepTextKey="I discovered a Nocturnal Shrike in Chancellor Gascone's office. She seemed to be looking for something. I also found a farewell memorandum penned by Gascone. I should tell Varuni about all I've seen."},
		[3] = 
			{appendStepText="At the Clockwork Basilica in the Brass Fortress, ", stepTextKey="Varuni urged me to find Proctor Luciana. The battlemage might be able to help me find Gascone. She should be just outside the Clockwork Basilica."},
		["Talk to Luciana 1"] =
			{appendText=", the Proctor.", stepTextKey="Varuni urged me to find Proctor Luciana. The battlemage might be able to help me find Gascone. She should be just outside the Clockwork Basilica."},
		[4] = 
			{appendStepText="", stepTextKey="The people of Clockwork City have started to gather outside the Basilica. Some appear panicked. I should talk to Luciana about how to proceed from here."},
		["Talk to Luciana 2"] =
			{appendText=".", stepTextKey="The people of Clockwork City have started to gather outside the Basilica. Some appear panicked. I should talk to Luciana about how to proceed from here."},
		[5] = 
			{appendStepText="In speaking with her in the Brass Fortress, I learned that ", stepTextKey="Proctor Luciana has no forces to lend. Fortunately, she has another resource that might be of use—an artificer named Dalomar. She insists that he might have something to aid me in my search. I should talk to him."},
		["Talk to Artificer Dalomar"] =
			{appendText=" in Slag Town in the northeast city. I'll look for him south of Daram Stables."},
		[6] = 
			{appendStepText="In the Brass Fortress' Slag Town, south of Daram Stables, ", stepTextKey="Artificer Dalomar lent me his prized tracker, a nix-hound fabricant called Snuffler. I should let Snuffler smell Gascone's note to help it pick up the scent."},
		["Let Snuffler Smell the Note"] =
			{appendText=" I took from Gascone's office."},
		[7] = 
			{appendStepText="South of Daram Stables in the Brass Fortress' northeast tenement of Slag Town, Dalomar is helping me. ", stepTextKey="The nix-hound fabricant, Snuffler, picked up Gascone's scent. I should follow it."},
		["Follow Snuffler 1"] =
			{appendText=" as he races off past the wayshrine.", stepTextKey="The nix-hound fabricant, Snuffler, picked up Gascone's scent. I should follow it."},
		[8] = 
			{appendStepText="", stepTextKey="Snuffler tracked Gascone's scent to the main gate of the Brass Fortress. I must follow the fabricant out into the Clockwork wilds—also known as the Radius."},
		["Follow Snuffler 2"] =
			{appendText=" as it heads west on the illuminated path, zigzagging down to the Insalubrious Effluvium ravine. ", stepTextKey="Snuffler tracked Gascone's scent to the main gate of the Brass Fortress. I must follow the fabricant out into the Clockwork wilds—also known as the Radius."},
		[9] = 
			{appendStepText="Snuffler led me to a small campfire in the Insalubrious Effluvium ravine. ", stepTextKey="According to the Nords, a distraught Gascone ran past them not long ago, tracking oil behind him. The oil masks his scent from Snuffler, but the footprints should be easy to follow. I must keep pursuing the fleeing chancellor."},
		["Follow Gascone's Footprints"] =
			{appendText=". The oily tracks start out north then head west from the small campfire in the ravine. The tracks seem to follow the oil ponds west and then northwest."},
		[10] = 
			{appendStepText="Following Gascone's tracks led me to the east end of a large oil pond, just west and below a northbound bridge. ", stepTextKey="I found a wounded cultist in the ravine.  I should see if she will tell me anything about Gascone's whereabouts."},
		["Talk to the Wounded Cultist"] =
			{appendText=" sitting with her back against a boulder."},
		[11] = 
			{appendStepText="", stepTextKey="According to the cultist, Gascone fled west along the ravine to a place called the Ventral Terminus. I should head that way to continue my search."},
		["Find Gascone's Hideout"] =
			{appendText=". Ventral Terminus is to the southwest. I should get to the winding road and follow it."},
		[12] = 
			{appendStepText="On the winding road in the southwest, ", stepTextKey="I found a narrow canyon leading to the Ventral Terminus. I should investigate this approach. If I can find some evidence of Gascone's passage, Snuffler might be able to pick up the chancellor's scent again."},
		["Investigate the Canyon"] =
			{appendText=" for anything Gascone may have dropped along the way. Perhaps Snuffler can pick up Gascone's scent again."},
		[13] = 
			{appendStepText="In the narrow canyon near the southwestern Ventral Terminus, ", stepTextKey="Snuffler picked up Gascone's scent once again. I should follow it."},
		["Follow Snuffler 3"] =
			{appendText=" to the Ventral Terminus gates.", stepTextKey="Snuffler picked up Gascone's scent once again. I should follow it."},
		[14] = 
			{appendStepText="We reached the Ventral Terminus in the southwest region. ", stepTextKey="Snuffler led me to a locked door. I heard Gascone's voice coming from the door as soon as we arrived. I should talk to him."},
		["Talk to Gascone 1"] =
			{appendText=", using the Ventral Audiometer device at the gate.", stepTextKey="Snuffler led me to a locked door. I heard Gascone's voice coming from the door as soon as we arrived. I should talk to him."},
		[15] = 
			{appendStepText="At the southwestern Ventral Terminus, I contacted Gascone using a audiometer device. ", stepTextKey="A panicked Gascone barricaded himself behind a massive door and refuses to come out. I must find another way into this mysterious facility—the Ventral Terminus."},
		["Find Another Entrance to the Ventral Terminus"] =
			{appendText=". Perhaps if I head up the path to the right of Ventral Terminus' main gate and look around, I'll find a smaller door."},
		[16] = 
			{appendStepText="In the southwest, at the Ventral Terminus, I followed a path up from the main gate, crossed a bridge, and then ", stepTextKey="I found a second door into the Ventral Terminus. I should go inside to continue my search for Gascone."},
		["Enter the Ventral Terminus"] =
			{appendText="."},
		[17] = 
			{appendStepText="In the southwest, through a small door above the main gate, ", stepTextKey="I entered the Ventral Terminus, but Gascone is nowhere in sight. I must explore this facility and to find the chancellor."},
		["Find Gascone"] =
			{appendText=". He is most likely by the main entrance."},
		[18] = 
			{appendStepText="I was able to enter the southwestern facility of the Ventral Terminus through a small door above the main gate.\n\nIn its northern chamber, I spotted a book on the floor. ", stepTextKey="According to Gascone, a wall of solid rock stands between us. If I want to find the chancellor, I'll need to come up with a way to break through this stone wall. Perhaps something in this room can help."},
		["Find a Way Through the Wall"] =
			{appendText=" to the south."},
		[19] = 
			{appendStepText="I was able to enter the southwestern facility of the Ventral Terminus through a small door above the main gate.\n\nIn its northern chamber, ", stepTextKey="I found a massive clockwork automaton called an Imperfect. This gigantic machine might be capable of smashing through the stone wall that separates me from Gascone. I need to activate it first. To begin, I must open and align the nearby flow valves."},
		["Align the Flow Valves"] =
			{appendText=". The book can help. I need to turn valves until I see leaking steam along pipes that lead to the south end near the Imperfect automaton."},
		[20] = 
			{appendStepText="I was able to enter the southwestern facility of the Ventral Terminus through a small door above the main gate.\n\nNow, in its northern chamber, ", stepTextKey="I successfully filled and charged an animo core. I should remove it from its filling bracket."},
		["Take the Charged Animo Core"] =
			{appendText="."},
		[21] = 
			{appendStepText="I was able to enter the southwestern facility of the Ventral Terminus through a small door above the main gate.\n\n", stepTextKey="In order to activate the Imperfect, I need to slide the animo core into its charging socket."},
		["Put the Animo Core in the Imperfect 1"] =
			{appendText=" automaton at the south end of the northern chamber.", stepTextKey="In order to activate the Imperfect, I need to slide the animo core into its charging socket."},
		[22] = 
			{appendStepText="I was able to enter the southwestern facility of the Ventral Terminus through a small door above the main gate.\n\nAt the south end of the northern chamber, ", stepTextKey="I activated the Imperfect and, as expected, it smashed its way forward. I should follow the machine to make sure it makes it all the way to our destination."},
		["Follow the Imperfect"] =
			{appendText=" south through the wall and beyond."},
		[23] = 
			{appendStepText="I was able to enter the southwestern facility of the Ventral Terminus through a small door above the main gate.\n\nWe made good progress moving south from the northern chamber. ", stepTextKey="It appears that the Imperfect ran out of fuel. I must find another animo core to get it moving again."},
		["Find Another Animo Core"] =
			{appendText=". Perhaps I should search upstairs for one."},
		[24] = 
			{appendStepText="I was able to enter the southwestern facility of the Ventral Terminus through a small door above the main gate. South of the northern chamber, I went upstairs and found another core. ", stepTextKey="In order to reactivate the Imperfect, I need to slide the animo core into its charging socket."},
		["Put the Animo Core in the Imperfect 2"] =
			{appendText=".", stepTextKey="In order to reactivate the Imperfect, I need to slide the animo core into its charging socket."},
		[25] = 
			{appendStepText="I was able to enter the southwestern facility of the Ventral Terminus through a small door above the main gate. Then, from the northern chamber, we headed south.\n\n", stepTextKey="I successfuly used the giant clockwork automaton to smash my way to a different part of the Terminus. Gascone must be around here somewhere. I should find and confront him."},
		["Confront Gascone"] =
			{appendText=". If there are more obstacles, perhaps I can go upstairs and go around behind them. I will find a way to reach Gascone."},
		[26] = 
			{appendStepText="I was able to enter the southwestern facility of the Ventral Terminus through a small door above the main gate.\n\nI found ways to get through the facility and reach Gascone in the southwest area inside the main gate. ", stepTextKey="Gascone yielded and left the Terminus. I must talk to him and decide his fate."},
		["Talk to Gascone 2"] =
			{appendText=" outside the main gate of the Ventral Terminus.", stepTextKey="Gascone yielded and left the Terminus. I must talk to him and decide his fate."},
		[27] = 
			{appendStepText="Near the main gate of the Ventral Terminus, the facility in the southwest, ", stepTextKey="I elected to kill the treacherous Chancellor Gascone. I should return to Varuni and tell her what happened."},
		["Talk to Varuni 2"] =
			{appendText=". She will be at the Clockwork Basilica in the northern Brass Fortress, on the main floor in the eastern chamber known as the Ineluctable Fold.", stepTextKey="I elected to kill the treacherous Chancellor Gascone. I should return to Varuni and tell her what happened."},
		[28] = 
			{appendStepText="At the Clockwork Basilica in the northern Brass Fortress, ", stepTextKey="I told Varuni about Gascone's death. I should speak to her to gain my reward."},
		["Talk to Varuni 3"] =
			{appendText=" in the eastern chamber on the main floor, known as the Ineluctable Fold.", stepTextKey="I told Varuni about Gascone's death. I should speak to her to gain my reward."},
		[29] = 
			{appendStepText="In the southwest, outside the main gate of the Ventral Terminus, ", stepTextKey="I decided to spare Chancellor Gascone. I should return to Varuni and tell tell her all that's transpired."},
		["Talk to Varuni 4"] =
			{appendText=" Arvel, the Proctor, at the Clockwork Basilica in the northern Brass Fortress. She should be in the main floor's eastern chamber known as the Ineluctable Fold. ", stepTextKey="I decided to spare Chancellor Gascone. I should return to Varuni and tell tell her all that's transpired."},
		[30] = 
			{appendStepText="At the Clockwork Basilica in the northern Brass Fortress, ", stepTextKey="I told Varuni about my encounter with Gascone. I should talk to her to claim my reward."},
		["Talk to Varuni 5"] =
			{appendText=" in the eastern chamber on the main floor known as the Ineluctable Fold.", stepTextKey="I told Varuni about my encounter with Gascone. I should talk to her to claim my reward."},
	},

	[GetQuestName(6052)] = { --"Lost in the Gloam"				--Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Odd, talking crows took up residence in the Brass Fortress while I hunted Gascone. I need to learn more about their motives and habits. I should ask someone in the city if they know more. The Chancel of Transaction might be a good place to start."},
		["Learn about the Mysterious Crows"] =
			{appendText="."},
		[2] = 
			{appendStepText="", stepTextKey="Constable Drados told me that a lot of the loudest crows gather around a tree near the Clockwork Basilica. I should go talk to them."},
		["Talk to the Crows"] =
			{appendText=" gathered northwest of the Brass Fortress' bank, The Grand Depository, at the far end of a remote courtyard with lavender, flowering trees."},
		[3] = 
			{appendStepText="Northwest of The Grand Depository, in the courtyard with a lavender tree, I spoke with a crow of the Blackfeather Court. ", stepTextKey="The Knave of Rooks agreed to give me information in exchange for one of Constable Drados's belongings—a \"silver treasure.\" I must ask Drados for this item, or steal it from his bunk in the Cloisters."},
		["Talk to Drados"] =
			{appendText=", the constable standing at the statue of Seht in the Chancel of Transaction plaza.\n"},
		["Steal Drados's Trinket"] =
			{appendText=" from his trunk in Brass Fortress' tavern. His bed is in the northwest corner, one floor up from the main floor."},
		[4] = 
			{appendStepText="Constable Drados's canteen? Well, ", stepTextKey="I secured the crows' \"silver treasure.\" I should bring it to the Knave of Rooks as tribute."},
		["Talk to the Knave of Rooks"] =
			{appendText=" by the lavender tree in the courtyard park northwest of The Grand Depository in the Brass Fortress."},
		[5] = 
			{appendStepText="", stepTextKey="The Knave of Rooks told me that in order to get an audience with the Duke of Crows, I'd need a well-respected escort. He suggested the Knight of Marrow. This Knight should be somewhere near a waterfall in the Brass Fortress."},
		["Find the Knight of Marrow"] =
			{appendText=", a lovesick crow that knows about the key. There is a waterfall south of the city's wayshrine."},
		[6] = 
			{appendStepText="Near a waterfall south of the Brass Fortress Wayshrine, ", stepTextKey="I found the Knight of Marrow. I should talk to him."},
		["Talk to the Knight of Marrow 1"] =
			{appendText=", the Blackfeather Court's hero who stole the key.", stepTextKey="I found the Knight of Marrow. I should talk to him."},
		[7] = 
			{appendStepText="", stepTextKey="The Knight of Marrow said he would escort me to the Duke of Crows if I help him win the affection of his lady love, Lady Blightwing. I need to find a poem for him to recite."},
		["Choose a Poem"] =
			{appendText=" to help the Knight woo his Lady love.\n\nThe Archivox is west of The Grand Depository in the Brass Fortress. After speaking with someone about a poem, a poem will be available to read on a bookcase spool near them. A parchment is available on a writing desk for copying my chosen poem."},
		[8] = 
			{appendStepText="In the Archivox, west of The Grand Depository in the Brass Fortress, ", stepTextKey="I selected a love poem for the Knight of Marrow. I should give it to him."},
		["Talk to the Knight of Marrow 2"] =
			{appendText=" perched on the rail of the stairs at the Archivox building.", stepTextKey="I selected a love poem for the Knight of Marrow. I should give it to him."},
		[9] = 
			{appendStepText="Outside the Archivox in the Brass Fortress, ", stepTextKey="I gave the Knight of Marrow a poem to recite to his love, Lady Blightwing. I should meet with him outside the gate to the Machine District."},
		["Join the Knight of Marrow in the Machine District"] =
			{appendText=" in the southeastern corner of the city, near the wayshrine."},
		[10] = 
			{appendStepText="In the southeastern Brass Fortress, ", stepTextKey="I arrived at the gate leading to the Machine District. Luciana and a few of her soldiers are here too. I should talk to Luciana to find out what they're doing here."},
		["Talk to Luciana 1"] =
			{appendText=", the Proctor.", stepTextKey="I arrived at the gate leading to the Machine District. Luciana and a few of her soldiers are here too. I should talk to Luciana to find out what they're doing here."},
		[11] = 
			{appendStepText="In the southeastern Brass Fortress, ", stepTextKey="I must follow the Knight of Marrow into the Machine District. I must watch him recite his poem before we can move on to my audience with the Duke of Crows."},
		["Observe the Knight of Marrow's Recitation"] =
			{appendText=" of the love poem to Lady Blightwing at the southeastern end of the district."},
		[12] = 
			{appendStepText="With Proctor Luciana, I accompanied the Knight of Marrow to the southeastern area of the Brass Fortress' Machine District. ", stepTextKey="Now that the Knight has finished wooing Lady Blightwing, he should introduce me to his liege, the Duke of Crows."},
		["Talk to the Duke of Crows 1"] =
			{appendText=", perched on a clockwork table with a brazier in a rocky alcove southwest of the Incarnatorium's door.", stepTextKey="Now that the Knight has finished wooing Lady Blightwing, he should introduce me to his liege, the Duke of Crows."},
		[13] = 
			{appendStepText="In the Machine District of southeastern Brass Fortress, I met with the leader of the Blackfeather Court. ", stepTextKey="The Duke of Crows agreed to give me the key if I help defeat his enemies, the Exarchs of Dross. I should begin by scattering the crows surrounding the Duke's position."},
		["Scatter the Exarchs of Dross"] =
			{appendText=" \n\nEnemies of the Duke's Court, the Exarchs have allied with the shadows and cultists who are determined to steal the key. We should go down into the ravine."},
		[14] = 
			{appendStepText="In a ravine in the southeastern Machine District of the Brass Fortress, ", stepTextKey="I scattered the Exarchs gathered around the Duke's position. I should discuss our next move with the Knight of Marrow."},
		["Talk to the Knight of Marrow 3"] =
			{appendText=", perched on a flat outcropping in the ravine.", stepTextKey="I scattered the Exarchs gathered around the Duke's position. I should discuss our next move with the Knight of Marrow."},
		[15] = 
			{appendStepText="In the southeastern Machine District of the Brass Fortress, I spoke again with the Blackfeather  Court's hero. ", stepTextKey="The Knight of Marrow wants me to destroy something called \"The Motionless Guardian.\" I should find and destroy this mysterious foe."},
		["Destroy the Motionless Guardian"] =
			{appendText=" in the far northeast of the city."},
		[16] = 
			{appendStepText="In the far northeast Machine District in the Brass Fortress, ", stepTextKey="I defeated the guardian scarecrow. I should return to Blackfeather Castle. Hopefully the Duke of Crows will honor our agreement."},
		["Return to Blackfeather Castle"] =
			{appendText=", the rocky alcove with the clockwork table and brazier in the southeast Machine District."},
		[17] = 
			{appendStepText="In the southeast Machine District of the Brass Fortress, in his \"castle\" alcove of rock, ", stepTextKey="I should talk to the Duke of Crows. Hopefully he'll tell me the location of the key."},
		["Talk to the Duke of Crows 2"] =
			{appendText=", perched regally on a clockwork table by a brazier.", stepTextKey="I should talk to the Duke of Crows. Hopefully he'll tell me the location of the key."},
		[18] = 
			{appendStepText="In the southeastern Machine District of the Brass Fortress, I met with the Duke again. ", stepTextKey="The Duke of Crows needs me to help him with a scheme to frighten the Exarch's leader, The Queen of Chaff. I should follow him into the Incarnatorium."},
		["Enter the Incarnatorium"] =
			{appendText=" through the door in the wall near the southeastern end of the bridge spanning the ravine leading from the district's main gate."},
		[19] = 
			{appendStepText="Inside the Incarnatorium, southeast of the Machine District's main gate in the southeastern Brass Fortress, ", stepTextKey="I must talk to the Duke of Crows about his plot to get rid of the Queen of Chaff."},
		["Talk to the Duke of Crows 3"] =
			{appendText=". The Blackfeather leader flew to the Factory Floor's west central area. To get there, I should use the lift just inside the facility's entry.", stepTextKey="I must talk to the Duke of Crows about his plot to get rid of the Queen of Chaff."},
		[20] = 
			{appendStepText="I am inside the Incarnatorium, southeast of the Machine District's main gate in the southeastern Brass Fortress. I used a lift to reach the central west circular Factory Floor where there are some crates and switch consoles.\n\n", stepTextKey="The Queen of Chaff and her entourage entered the Incarnatorium. I should hide and listen to the Duke and the Queen's negotiation."},
		["Hide and Listen to the Negotiation"] =
			{appendText="."},
		[21] = 
			{appendStepText="I am inside the Incarnatorium, southeast of the Machine District's main gate in the southeastern Brass Fortress. I used a lift to reach the central west circular Factory Floor where there are some crates and switch consoles.\n\n", stepTextKey="The Duke of Crows gave me the signal to throw a switch. I should pull one of these levers and see what happens."},
		["Pull a Lever"] =
			{appendText=" at the left wheel console."},
		[22] = 
			{appendStepText="I am inside the Incarnatorium, southeast of the Machine District's main gate in the southeastern Brass Fortress. I used a lift to reach the central west circular Factory Floor where there are some crates and switch consoles.\n\n", stepTextKey="The Duke of Crows gave me the signal to throw another switch. I should pull one of these levers and see what happens."},
		["Pull Another Lever"] =
			{appendText=" at the right wheel console."},
		[23] = 
			{appendStepText="I am inside the Incarnatorium, southeast of the Machine District's main gate in the southeastern Brass Fortress. I used a lift to reach the central west circular Factory Floor where there are some crates and switch consoles.\n\n", stepTextKey="The Duke of Crows gave me the signal to throw another switch. I should pull one of these levers and see what happens."},
		["Pull a Third Lever"] =
			{appendText=", the left bar lever."},
		[24] = 
			{appendStepText="I am inside the Incarnatorium, southeast of the Machine District's main gate in the southeastern Brass Fortress. I used a lift to reach the central west circular Factory Floor where there are some crates and switch consoles.\n\n", stepTextKey="The Duke gave me the final signal. I should pull one last lever and see what happens."},
		["Pull the Final Lever"] =
			{appendText=", the right bar lever."},
		[25] = 
			{appendStepText="I am inside the Incarnatorium, southeast of the Machine District's main gate in the southeastern Brass Fortress. I used a lift to reach the central west circular Factory Floor.\n\n", stepTextKey="The Duke seems pleased that we were able to drive out the Exarchs of Dross. I should talk to him."},
		["Talk to the Duke of Crows 4"] =
			{appendText=", perched on a large crate near the lever consoles.", stepTextKey="The Duke seems pleased that we were able to drive out the Exarchs of Dross. I should talk to him."},
		[26] = 
			{appendStepText="I am inside the Incarnatorium, southeast of the Machine District's main gate in the southeast Brass Fortress. I used a lift to reach the central west circular Factory Floor, where ", stepTextKey="I helped the Duke scare off the Queen of Chaff, but the key remains just out of reach—locked behind a door. I must make my way through the Incarnatorium to claim the key."},
		["Claim the Key"] =
			{appendText=". With the short route blocked, I should travel through the factory to reach the southeasternmost area. Then through the door to the circular, southwestern area. The Knight of Marrow will help guide me."},
		[27] = 
			{appendStepText="I am inside the Incarnatorium, southeast of the Machine District's main gate in the southeastern Brass Fortress. I used a lift to reach the Factory Floor, circled around and entered the circular southwestern area. ", stepTextKey="I have the key in sight. I should take it."},
		["Take the Key"] =
			{appendText="."},
		[28] = 
			{appendStepText="I am inside the Incarnatorium, southeast of the Machine District's main gate in the southeastern Brass Fortress. I used a lift to reach the Factory Floor, circled around and entered the circular southwestern area. ", stepTextKey="The Shadow of Sotha Sil stole the key and unleashed a terrifying Wraith-of-Crows. I must defeat this otherworldly creature."},
		["Defeat the Wraith-of-Crows"] =
			{appendText="."},
		[29] = 
			{appendStepText="I am inside the Incarnatorium, southeast of the Machine District's main gate in the southeastern Brass Fortress. I used a lift to reach the Factory Floor. In the circular southwestern area, the Shadow of Sotha Sil appeared and summoned a shadow minion. ", stepTextKey="I defeated the Wraith-of-Crows. I should find the Duke of Crows and discuss our next move."},
		["Talk to the Duke of Crows 5"] =
			{appendText=" outside of the Incarnatorium at the rocky alcove, the Blackfeather Castle, to the southeast.", stepTextKey="I defeated the Wraith-of-Crows. I should find the Duke of Crows and discuss our next move."},
		[30] = 
			{appendStepText="At the Incarnatorium in the southeastern Brass Fortress. I entered the chamber where the Duke of Crows had hidden the key. ", stepTextKey="The Shadow snatched the Skeleton Key right out from under me. I should inform Luciana of all that's happened."},
		["Talk to Luciana 2"] =
			{appendText=". She waits near the door to the Incarnatorium, southeast across the bridge from the Machine District's main gate.", stepTextKey="The Shadow snatched the Skeleton Key right out from under me. I should inform Luciana of all that's happened."},
		[31] = 
			{appendStepText="", stepTextKey="An alarm sounded in the Machine District. I should meet Luciana back at the Clockwork Basilica to figure out what is going on."},
		["Talk to Luciana at the Basilica 1"] =
			{appendText="'s west wing in the northern Brass Fortress.", stepTextKey="An alarm sounded in the Machine District. I should meet Luciana back at the Clockwork Basilica to figure out what is going on."},
		[32] = 
			{appendStepText="", stepTextKey="An alarm sounded in the Machine District. I should meet Luciana back at the Clockwork Basilica to figure out what is going on."},
		["Talk to Luciana at the Basilica 2"] =
			{appendText="'s west wing in the northern Brass Fortress.", stepTextKey="An alarm sounded in the Machine District. I should meet Luciana back at the Clockwork Basilica to figure out what is going on."},
	},

	[GetQuestName(6046)] = { --"Unto the Dark"				--Jordakai
		[1] = 
			{appendStepText="I spoke with Proctor Luciana Pullo in the Brass Fortress' northern structure, the Clockwork Basilica. Now, ", stepTextKey="I need to talk to former Chancellor Gascone to see if he knows how the Whispering Shadows cultists are moving through the city. We may be able to use their own methods against them."},
		["Talk to Chancellor Gascone"] =
			{appendText=". He is in the Ineluctable Fold in the east wing of the Basilica's main floor."},
		[2] = 
			{appendStepText="At the northern structure of Brass Fortress, I spoke with the former Chancellor in the Clockwork Basilica's east wing's Ineluctable Fold.", stepTextKey="Gascone claims to have the information I need, but he wants a favor in return. I either need to help him retrieve a mysterious contract, or convince him to tell me now."},
		["Get the Information from Gascone"] =
			{appendText=". If I choose to find Gascone's Contract, I should look in a secluded alcove with a switch, in the north-central area of the Mechanical Fundament's sandy, lower level."},
		[3] = 
			{appendStepText="At the Clockwork Basilica in the Brass Fortress, I met with the former Chancellor in the east wing's Ineluctable Fold. In speaking with Gascone, ", stepTextKey="I learned that Whispering Shadows cultists use portals called Gloaming Gates to navigate the city in secret. Luciana and I could use these gates to reach the Cogitum Centralis—and Sotha Sil. I should inform Luciana."},
		["Talk to Luciana 1"] =
			{appendText=". The Proctor should be in the west wing of the Basilica.", stepTextKey="I learned that Whispering Shadows cultists use portals called Gloaming Gates to navigate the city in secret. Luciana and I could use these gates to reach the Cogitum Centralis—and Sotha Sil. I should inform Luciana."},
		[4] = 
			{appendStepText="At the Clockwork Basilica in the Brass Fortress, ", stepTextKey="Luciana and I decided to split up and explore separate Gloaming Gates. I must travel to the eastern reaches of the Radius to find one of these gates."},
		["Find and Enter the Gloaming Gate"] =
			{appendText=" at the Radius' far eastern edge. The gate should be in a rocky tunnel in the ravine northeast of the Mire Mechanica Wayshrine and north of the easternmost bridge.\n\nThe Radius is the name of the areas of Clockwork City that are outside the Brass Fortress."},
		[5] = 
			{appendStepText="In the Radius' far northeast, in the ravine north of the easternmost bridge, I found the gate in a tunnel. ", stepTextKey="I entered the Gloaming Gate and found myself in the Evergloam—the realm of the Daedric Prince, Nocturnal. I need to look for other portals that might lead me to my destination: the Cogitum Centralis."},
		["Navigate the Evergloam"] =
			{appendText=". I should find my way to the north-central ruins to enter another portal. Then along a road up to the final portal.\n\n The Knave of Rooks is here and can help guide me."},
		[6] = 
			{appendStepText="In the Radius' far northeast, in the ravine north of the easternmost bridge, I entered the Gloaming Gate and navigated Evergloam to reach the eastern mountaintop ruin. ", stepTextKey="An imposing Nocturnal Shrike, Nightmaiden Viriana, captured Luciana. I must defeat this Daedric creature to free my companion."},
		["Defeat Nightmaiden Viriana"] =
			{appendText="."},
		[7] = 
			{appendStepText="In the Radius' far northeast, in the ravine north of the easternmost bridge, I use the Gloaming Gate portal and then navigated the shadowy realm. At the mountaintop ruin in eastern Evergloam, ", stepTextKey="I defeated Nightmaiden Viriana. I should follow Luciana through the nearby Gloaming Gate. Hopefully this one leads back to the Clockwork City."},
		["Enter the Final Gloaming Gate"] =
			{appendText=" at the ruin."},
		[8] = 
			{appendStepText="In the Radius' far northeast, in the ravine north of the easternmost bridge, I entered the Gloaming Gate. After leaving Evergloam through the eastern, mountaintop portal we returned to Brass Fortress' Mechanical Fundament. ", stepTextKey="We successfully navigated the Evergloam and found our way to the Cogitum Centralis. I should talk to Luciana about our next move."},
		["Talk to Luciana 2"] =
			{appendText=" at the north end of the Fundament, at the door to The Cogitum Centralis.", stepTextKey="We successfully navigated the Evergloam and found our way to the Cogitum Centralis. I should talk to Luciana about our next move."},
		[9] = 
			{appendStepText="From the sandy, lower level of the Mechanical Fundament, ", stepTextKey="I retrieved Chancellor Gascone's contract from the Skaafin. I should deliver it to him."},
		["Deliver the Contract to Gascone"] =
			{appendText=" in the Ineluctable Fold of the eastern wing of the Clockwork Basilica's main floor. The Basilica is north of the Brass Fortress' bank, The Great Depository."},

	},


[GetQuestName(6047)] = { --"Where Shadows Lie"				--Jordakai
		[1] = 
			{appendStepText="There is a lift in the eastern wing of the Brass Fortress' Clockwork Basilica for entry into the Mechanical Fundament. ", stepTextKey="Luciana and I must pursue the Shadow of Sotha Sil into the mysterious Cogitum Centralis."},
		["Enter the Cogitum Centralis"] =
			{appendText=". Its door is at the northeastern end of the Mechanical Fundament's halls."},
		[2] = 
			{appendStepText="The lift in the eastern wing of the Brass Fortress' Clockwork Basilica led to the Mechanical Fundament. We entered the Cogitum Centralis through the northeast door in the Fundament. ", stepTextKey="The Cogitum's automated security system rotated the central bridge, making it impassable. Luciana believes she can override the lock, but she needs more power. I must find two nearby power terminals and activate them."},
		["Activate the Left Core Pump"] =
			{appendText=" at the end of a hall northwest of the central area.\n"},
		["Activate the Right Core Pump"] =
			{appendText=" at the end of a hall northeast of the central area."},
		[3] = 
			{appendStepText="A lift in the eastern wing of the Brass Fortress' Clockwork Basilica led to the Mechanical Fundament, and the northeast door in the Fundament took us to the Cogitum Centralis. Now, ", stepTextKey="I should follow Luciana deeper into the Cogitum Centralis."},
		["Follow Luciana"] =
			{appendText=" across the bridge and through the door into the Halls of Convention."},
		[4] = 
			{appendStepText="A lift in the eastern wing of the Brass Fortress' Clockwork Basilica led to the Mechanical Fundament, and the northeast door in the Fundament took us to the Cogitum Centralis. North through the foyer, we entered the Halls of Convention. ", stepTextKey="Otherworldly shadows block our way forward, and Luciana's magic is spent. We have to find another way through."},
		["Find a Path Through the Shadows"] =
			{appendText=" by using the nearby switches in the southeastern chamber."},
		[5] = 
			{appendStepText="A lift in the eastern wing of the Brass Fortress' Clockwork Basilica led to the Mechanical Fundament, and then we went into the Halls of Convention. ", stepTextKey="Luciana and I discovered lights capable of dissolving the Daedric shadows. We can use them to clear the way to Sotha Sil's central chamber: the Throne Aligned."},
		["Find Sotha Sil"] =
			{appendText=". Luciana went into The Inner Curiosity. I should find her in the large central chamber. Then we will go north and see what we find in the next area. The Throne Aligned is likely on the lowest level, away from the main areas."},
		[6] = 
			{appendStepText="We entered the Throne Aligned at the bottom of the Axle, after passing through all the areas of the Cogitum Centralis that we first reached through the Mechanical Fundament in the Brass Fortress.\n\n", stepTextKey="We found the Shadow of Sotha Sil preparing to kill and replace the real Sotha Sil. We must defeat this creature and save the true Clockwork God."},
		["Confront the Shadow of Sotha Sil"] =
			{appendText="."},
		[7] = 
			{appendStepText="We entered the Throne Aligned at the bottom of the Axle, after passing through all the areas of the Cogitum Centralis that we first reached through the Mechanical Fundament in the Brass Fortress.\n\n", stepTextKey="We found the Shadow of Sotha Sil preparing to kill and replace the real Sotha Sil. We must defeat this creature and save the true Clockwork God."},
		["Defeat the Shadow of Sotha Sil"] =
			{appendText="."},
		[8] = 
			{appendStepText="We entered the Throne Aligned at the bottom of the Axle, after passing through all the areas of the Cogitum Centralis that we first reached through the Mechanical Fundament in the Brass Fortress.\n\n", stepTextKey="Nocturnal's fury encroaches from all sides! I need to turn the Skeleton Key and wake Sotha Sil before it's too late."},
		["Wake Sotha Sil"] =
			{appendText=" using the Skeleton Key."},
		[9] = 
			{appendStepText="", stepTextKey="It's time to leave the Cogitum Centralis. I can speak to everyone once I'm back in the Clockwork Basilica."},
		["Exit the Cogitum Centralis"] =
			{appendText="."},
		[10] = 
			{appendStepText="", stepTextKey="I managed to wake Sotha Sil just in time. He used his divine power to cast out Nocturnal, then teleported all of us back to the Brass Fortress. It looks like Sotha Sil wants to talk to me."},
		["Talk to Sotha Sil 1"] =
			{appendText=" in the Loquitorium of the Clockwork Basilica.", stepTextKey="I managed to wake Sotha Sil just in time. He used his divine power to cast out Nocturnal, then teleported all of us back to the Brass Fortress. It looks like Sotha Sil wants to talk to me."},
		[11] = 
			{appendStepText="In the Brass Fortress, ", stepTextKey="I should talk to Sotha Sil to claim my reward."},
		["Talk to Sotha Sil 2"] =
			{appendText=" in the Loquitorium of the Clockwork Basilica.", stepTextKey="I should talk to Sotha Sil to claim my reward."},
		[12] = 
			{appendStepText="In the Brass Fortress, ", stepTextKey="I should talk to Sotha Sil to claim my reward."},
		["Talk to Sotha Sil 2"] =
			{appendText=" in the Loquitorium of the Clockwork Basilica.", stepTextKey="I should talk to Sotha Sil to claim my reward."},
	},


    [GetQuestName(6048)] = { --"The Light of Knowledge"				--Jordakai
        [1] = 
            {appendStepText="At the Brass Fortress' Clockwork Basilica, ", stepTextKey="Sotha Sil asked me to find Divayth Fyr and then meet him at the Elegiac Replication."},
        ["Talk to Divayth Fyr"] =
            {appendText=". He is probably outside the Brass Fortress. I'll look for him on the bridge south of the city gates."},
        [2] = 
            {appendStepText="I found the legendary mage, Divayth Fyr, on the bridge south of the Brass Fortress' main gate. He was enjoying the view and contemplating. ", stepTextKey="I told Divayth Fyr to meet Sotha Sil in the Elegiac Replication. I should go there myself."},
        ["Meet with Sotha Sil and Divayth Fyr"] =
            {appendText=". Our meeting place is southeast of the Clockwork Crossroads Wayshrinie, a short distance south of where the eastern road splits in two."},
        [3] = 
            {appendStepText="I found the Clockwork God and the legendary mage in a beautiful garden surrounded by hoodoos. Clockwork objects adorn the grounds. I should study them when I can.\n\n", stepTextKey="Sotha Sil appears to have something to say to Divayth Fyr. I should let this exchange play out."},
        ["Listen to Sotha Sil's Conversation"] =
            {appendText=" with Divayth Fyr."},
        [4] = 
            {appendStepText="East of the Clockwork Crossroads Wayshrine at Elegiac Replication, I am with Seht, one of the Tribunal. ", stepTextKey="The Clockwork God, Sotha Sil, wants to talk to me. I should see what he has to say."},
        ["Talk to Sotha Sil 1"] =
            {appendText=".", stepTextKey="The Clockwork God, Sotha Sil, wants to talk to me. I should see what he has to say."},

    },


-- 		=========================================================================
--		 Clockwork City - Side Quest
-- 		=========================================================================

	[GetQuestName(6056)] = { --"The Astronomer's Apprentice" --Yutoma --Jordakai
		[1] = 
			{appendStepText="In the Radius of Clockwork City, the lands outside of The Brass Fortress, I spoke with Amili at the entrance to the towering facility east of the Clockwork Crossroads Wayshrine. ", stepTextKey="I should follow Amili into the Mnemonic Planisphere to learn more about the situation."},
		["Talk to Amili Lloryn 1"] =
			{appendText=", a Clockwork Apostle, in the Planisphere's central chamber.", stepTextKey="I should follow Amili into the Mnemonic Planisphere to learn more about the situation."},
		[2] = 
			{appendStepText="In the Mnemonic Planisphere, ", stepTextKey="I need to collect errant stars in order to return them to the Planisphere's sky. I should search the halls surrounding the Planisphere to find them."},
		["Collect Errant Stars"] =
			{appendText=" \n\nThe glowing, sky-blue orbs float through the hallways in the wings of the facility. Use the Star Scooper to take a star when it is close enough. \n\nFrom the central Planisphere chamber, the Warrior's Wing is to the west, the Mage's Wing is to the north, and the Thief's Wing is to the east."},
		[3] = 
			{appendStepText="There were stars in the hallways of the Warrior, the Mage, and the Thief. ", stepTextKey="I've collected the errant stars needed. I should return them to the Astronomer so he can place them back into the Planisphere's sky."},
		["Give the Star-Scooper to the Astronomer"] =
			{appendText=". He is with Amili in the large central Planishere chamber on the main floor."},
		[4] = 
			{appendStepText="In the central Planisphere chamber, I gave the stars I collected to the Astronomer to put back in the sky. ", stepTextKey="Something went wrong with returning the stars. I should speak to Amili to find out more."},
		["Talk to the Astronomer 1"] =
			{appendText=" instead of Amili. She left to check on something.", stepTextKey="Something went wrong with returning the stars. I should speak to Amili to find out more."},
		[5] = 
			{appendStepText="I spoke with the Astronomer in the central Planisphere. ", stepTextKey="The primary stars have been corrupted. I need to head to the three viewing platforms and use the calibration guides to show each star its place in the Planisphere's sky."},
		["Return Stars to the Warrior Constellation"] =
			{appendText=" first, at the western platform entered through the Hall of the Warrior.\n"},
		["Return Stars to the Mage Constellation"] =
			{appendText=" at the northern platform entered through the Hall of the Mage.\n"},
		["Return Stars to the Thief Constellation"] =
			{appendText=" at the eastern platform entered through the Hall of the Thief. \n\n- Amili can explain what to do with the telescope and floor pattern at each platform. \n- To reach the upper wings above the main floor, lifts in the westernmost and easternmost lift chambers are used. \n- On the upper wing level, hallways connect the western Warrior, the northern Mage, and the eastern Thief areas. \n- To reach the top level of the Halls and platforms, there are lifts in the central lift chambers, west, north, and east."},
		[6] = 
			{appendStepText="", stepTextKey="I've returned all of the corrupted stars to their proper places in the Planisphere's sky. I should speak to Amili to find out what to do next."},
		["Talk to Amili Lloryn 2"] =
			{appendText=". She said to meet her at the large, central chamber on the main floor.", stepTextKey="I've returned all of the corrupted stars to their proper places in the Planisphere's sky. I should speak to Amili to find out what to do next."},
		[7] = 
			{appendStepText="In the central chamber of the Planisphere, ", stepTextKey="I should watch the stolen memory."},
		["Watch the Stolen Memory"] =
			{appendText="."},
		[8] = 
			{appendStepText="I watched the display of the memory in the central chamber of the Planisphere. ", stepTextKey="The stolen memory has revealed that Orvas willingly gave his memories to Sotha Sil to become the Astronomer. I should speak to Amili about what just happened."},
		["Talk to Amili Lloryn 3"] =
			{appendText=". The Astronomer's apprentice left through the southern door to the Antechamber.\n\nPerhaps I should speak with the Astronomer first.", stepTextKey="The stolen memory has revealed that Orvas willingly gave his memories to Sotha Sil to become the Astronomer. I should speak to Amili about what just happened."},
		[9] = 
			{appendStepText="", stepTextKey="Amili has decided to leave the Planisphere and retain her memories. I should stay with her as she tells the Astronomer."},
		["Witness the Departure"] =
			{appendText="."},
		[10] = 
			{appendStepText="", stepTextKey="Amili has refused to give up her memories and has left the Planisphere. I should speak to the Astronomer."},
		["Talk to the Astronomer 2"] =
			{appendText=" in the central chamber.", stepTextKey="Amili has refused to give up her memories and has left the Planisphere. I should speak to the Astronomer."},
		[11] = 
			{appendStepText="", stepTextKey="Amili has decided to give up her memories and become the new Astronomer. I should stay with her as the process is performed."},
		["Witness the Succession"] =
			{appendText=" in the central chamber, the Planisphere."},
		[12] = 
			{appendStepText="In the central chamber of the Planisphere, I witnessed the succession. ", stepTextKey="Amili has made her choice to become the Astronomer, sacrificing her memories to do so. I should speak to her."},
		["Talk to the Astronomer 3"] =
			{appendText=".", stepTextKey="Amili has made her choice to become the Astronomer, sacrificing her memories to do so. I should speak to her."},
	},

    [GetQuestName(6094)] = { --"The Broken Brassilisk"				--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The brassilisk ran out of power beneath a pipeline leading to the Brass Fortress. It most likely used that pipeline to travel to this location. Frynga must be somewhere in the fortress."},
        ["Find Frynga"] =
            {appendText=" in the Outlaws' Refuge."},
        [2] = 
            {appendStepText="Within the Brass Fortress, ", stepTextKey="I've found Frynga in Slag Town. I should speak to her about the inactive brassilisk I collected."},
        ["Talk to Frynga 1"] =
            {appendText=", looking down the pipe her brassilisk likely fell down.", stepTextKey="I've found Frynga in Slag Town. I should speak to her about the inactive brassilisk I collected."},
        [3] = 
            {appendStepText="Within the Brass Fortress's Slag Town Outlaw Refuge, ", stepTextKey="I've found Frynga. I should return the brassilisk to her and discuss a reward."},
        ["Talk to Frynga 2"] =
            {appendText=" where I last saw her, in the northwest part of the refuge, standing over the pipe where her brassilisk went down.", stepTextKey="I've found Frynga. I should return the brassilisk to her and discuss a reward."},
    },

	[GetQuestName(6074)] = { --"Cogs of Fate" --Yutoma --Jordakai		
		[1] = 
			{appendStepText="At Daram Stables, near the eastern tenement of The Brass Fortress, I spoke with an elderly Dunmer as he was eating. ", stepTextKey="Palbatan asked me to go to the Outlaws Refuge in Slag Town and talk to Kamid. He wants me to find out what the young man is planning and see if I can help him and keep him safe."},
		["Talk to Kamid 1"] =
			{appendText=", a young Redguard. He is probably getting his backpack ready for his pilgrimage.", stepTextKey="Palbatan asked me to go to the Outlaws Refuge in Slag Town and talk to Kamid. He wants me to find out what the young man is planning and see if I can help him and keep him safe."},
		[2] = 
			{appendStepText="", stepTextKey="Kamid plans to find the Grand Prognosticator and destroy it to show his people that they can determine their own fates. He asked me to meet him at the Vale of Tiers."},
		["Meet Kamid at the Vale of Tiers"] =
			{appendText=". He should be just southwest of the road in a small, illuminated clearing with pipes, switches, and a shade tree, west of the Clockwork Crossroads Wayshrine and northeast of the tall fan-towers of the Vale."},
		[3] = 
			{appendStepText="In a small, illuminated clearing with pipes and a shade tree, northeast of the tall fan-towers of the Vale, I found the young Redguard. ", stepTextKey="Kamid wants to activate the Grand Prognosticator so he can prove that it lies. To do that, he asked me to descend into the Vale of Tiers and acquire a working animo core from a roaming factotum."},
		["Find a Working Animo Core"] =
			{appendText=" from a factotum down in the oily valley where the towers stand. Damaged cores will not work. As for Kamid's mother, perhaps she was trapped in a narrow dead end of the oily vale.\n\nIf I need help, I can use the whistle Kamid gave me."},
		[4] = 
			{appendStepText="Among the factotums and towers down in the oily Vale of Tiers, ", stepTextKey="I acquired a working animo core. I should return to Kamid and see if we can use it to activate the Grand Prognosticator."},
		["Talk to Kamid 2"] =
			{appendText=" in the small, illuminated clearing with pipes and a shade tree, above and northeast of the tall fan-towers down in the Vale.", stepTextKey="I acquired a working animo core. I should return to Kamid and see if we can use it to activate the Grand Prognosticator."},
		[5] = 
			{appendStepText="I returned to Kamid in the small, illuminated clearing with pipes, a machine, and a shade tree, northeast of the tall fan-towers of the Vale. ", stepTextKey="Kamid asked me to insert the animo core into the machine to power up the factotum. Then he can ask it to reveal his fortune."},
		["Place the Animo Core"] =
			{appendText=" in the machine with the large bar switch, by the Grand Prognosticator factotum."},
		[6] = 
			{appendStepText="At the small, illuminated clearing with pipes, switches, and a shade tree northeast of the tall fan-towers of the Vale, I activated the factotum. ", stepTextKey="The Grand Prognosticator provided a fortune to Kamid that matches the ones given to all the pilgrims from Slag Town. It couldn't furnish me with a fortune, however. I should talk to Kamid and see what he thinks."},
		["Talk to Kamid 3"] =
			{appendText=".", stepTextKey="The Grand Prognosticator provided a fortune to Kamid that matches the ones given to all the pilgrims from Slag Town. It couldn't furnish me with a fortune, however. I should talk to Kamid and see what he thinks."},
		[7] = 
			{appendStepText="After hearing what the Grand Prognosticator factotum told him, ", stepTextKey="Kamid plans to recover a lost treasure to change his fate. We need to return to the Brass Fortress and find Palbatan, who Kamid believes knows the secret for locating the treasure."},
		["Meet Kamid in the Brass Fortress"] =
			{appendText=" at Daram Stables, near the city's eastern tenement of Slag Town."},
		[8] = 
			{appendStepText="I left the southwestern lands of the Radius to meet Kamid inside the city. ", stepTextKey="Now that I'm back in the Brass Fortress, I should locate Palbatan and see what he can tell Kamid and me about the lost treasure of the Radius."},
		["Talk to Palbatan"] =
			{appendText=". The elderly Dunmer is with Kamid near the wall west of Daram Stables and northeast of The Grand Depository."},
		[9] = 
			{appendStepText="After speaking with him in The Brass Fortress, ", stepTextKey="Palbatan provided us with the location of the wrecked caravan where Kamid hopes to recover a lost treasure. We just need to get past the fabricant called Gear Grinder and search the area."},
		["Find the Merchant's Lost Treasure"] =
			{appendText=" after defeating the giant fabricant. Palbatan said the site was up in the southernmost mountains of the Radius, the lands outside of the city. Kamid said he would be near the caravan site, probably hiding behind a large boulder northwest of the destroyed caravan.\n\nIt is southeast of the Clockwork Crossroads Wayshrine, southwest of a giant broken clock tower on the southeastern road, and west of the Clockwork structure in the far southeast."},
		[10] = 
			{appendStepText="I defeated Gear Grinder at the caravan site southeast of the Clockwork Crossroads Wayshrine, southwest of a giant broken clock tower on the southeastern road, and west of the Clockwork structure in the far southeast. Then ", stepTextKey="I recovered the treasure. Now to turn it over to Kamid."},
		["Talk to Kamid 4"] =
			{appendText=". He's waiting behind the large boulder northwest of the destroyed merchant caravan.", stepTextKey="I recovered the treasure. Now to turn it over to Kamid."},
		[11] = 
			{appendStepText="", stepTextKey="The lost treasure of the Radius consists of valuable spices that Kamid can sell for a small fortune in a metallic desert like Clockwork City. He asked me to meet him back in Slag Town to settle our accounts."},
		["Meet Kamid in Slag Town"] =
			{appendText=", the eastern tenement of The Brass Fortress, near Daram Stables."},
		[12] = 
			{appendStepText="", stepTextKey="We found the lost treasure. Kamid claims that the treasure—crates of spices—is extremely valuable in the Clockwork City since nothing organic grows here. He wants me to meet him back in Slagtown for my reward."},
		["Talk to Kamid 5"] =
			{appendText=". He is standing on a ledge with a barrel and a crate, just below Daram Stables in the eastern tenement of The Brass Fortress. A crowd has gathered to hear his story.", stepTextKey="We found the lost treasure. Kamid claims that the treasure—crates of spices—is extremely valuable in the Clockwork City since nothing organic grows here. He wants me to meet him back in Slagtown for my reward."},
	},
    [GetQuestName(6078)] = { --"Family Feud"			 --Jordakai
        [1] = 
            {appendStepText="In the Hall of Refined Techniques at the Brass Fortress, I spoke with Kireth Vanos. ", stepTextKey="I need to find Raynor somewhere in the Clockwork City. Kireth asked me to not mention that she sent me, but I don't know how I feel about lying to Raynor."},
        ["Find Raynor Vanos"] =
            {appendText=" in the Radius, the lands outside of the city. I should use the zigzag path down to the ravine, the one Raynor used before. It begins just west of the city's main gate. He may be surveying the ravine from atop a cliff, part way down the path."},
        [2] = 
            {appendStepText="Standing on a cliff overlooking the Radius' ravine, part way down the zigzag trail west of the Brass Fortress main gate, I found Raynor. ", stepTextKey="I agreed to help Raynor conduct his research of the Clockwork City. He wants to investigate the Resonant Sphere, the Vale of Tiers, and the Broken Clock Tower."},
        ["Explore the Clockwork City"] =
            {appendText=" and speak with Raynor about:\n- The Resonant Sphere of brass is in the Insalubrious Effluvium, the ravine. It is at the west end of the oily lakes, northeast of the Sanctuary Wayshrine. \n- The Vale of Tiers is the area south of the Sanctuary Wayshrine. There are two tall, slender, round towers best viewed from a nearby northeastern ramp, east of the enormous turbine towers.\n- The Broken Clock Tower is near the northeastern road, east of the Clockwork Crossroads Wayshrine and southeast of the Mnemonic Planisphere."},
        [3] = 
            {appendStepText="In the Radius, the lands outside of the Brass Fortress, we went exploring. Now, ", stepTextKey="I should talk to Raynor so we can finalize our conclusions concerning the sites we explored."},
        ["Talk to Raynor Vanos"] =
            {appendText="."},
        [4] = 
            {appendStepText="", stepTextKey="I convinced Raynor to stand up for himself. He wants me to talk to Kireth first before he tells his sister what he thinks of her for berating him after the shadow affair."},
        ["Talk to Kireth Vanos 1"] =
            {appendText=" in the Hall of Refined Techniques in the Brass Fortress.", stepTextKey="I convinced Raynor to stand up for himself. He wants me to talk to Kireth first before he tells his sister what he thinks of her for berating him after the shadow affair."},
        [5] = 
            {appendStepText="", stepTextKey="I convinced Raynor to apologize to his sister Kireth. He wants me to talk to her and make sure she isn't too angry with him before he makes his apology."},
        ["Talk to Kireth Vanos 2"] =
            {appendText=" in the Brass Fortress' Hall of Refined Techniques.", stepTextKey="I convinced Raynor to apologize to his sister Kireth. He wants me to talk to her and make sure she isn't too angry with him before he makes his apology."},
    },

    [GetQuestName(6058)] = { --"The Halls of Regulation"		--Yutoma
        [1] = 
            {appendStepText="", stepTextKey="Tilelle's schematics show that both the Vapor Manifold and Distillation Initiator are in need of repair. I should collect replacement parts, including a Ventilation Gear and Cleansing Crystal, to fix these machines."},
        ["Collect Ventilation Gear"] =
            {appendText=". The Gear looks like a cog, and can be found behind pipes in the northern area of the Hall."},
        ["Collect Cleansing Crystal"] =
            {appendText=". The Crystal is in the southern area of the Hall, in a flooded hallway."},
        ["Repair Vapor Manifold"] =
            {appendText=" in the Humidity Chamber, a small room at the northernmost point of the Hall."},
        ["Repair Distillation Initiator"] =
            {appendText=", located on the second level of the Hall, in the Purification Chamber."},
        [2] = 
            {appendStepText="", stepTextKey="I should talk to Tilelle to learn of our next task."},
        ["Talk to Tilelle the Mender 1"] =
            {appendText=". She is waiting for me in the Halls of Regulation.", stepTextKey="I should talk to Tilelle to learn of our next task."},
        [3] = 
            {appendStepText="", stepTextKey="I should enter the Regulation Chamber."},
        ["Enter the Regulation Chamber"] =
            {appendText=", the largest chamber on the easternmost side of the Hall."},
        [4] = 
            {appendStepText="", stepTextKey="I should secure the Regulation Chamber by disabling the guardian factotum. I'll then need to collect a Geodic Dynamo in order to allow Tilelle to repair the Galvanic Engine."},
        ["Collect Geodic Dynamo"] =
            {appendText=" located in the Dynamo Reserve Storage - which is fiercely guarded by The Steadfast Regulator."},
        [5] = 
            {appendStepText="", stepTextKey="I should help Tilelle repair the Galvanic Engine."},
        ["Repair the Galvanic Engine"] =
            {appendText=". Tilelle is waiting for you there in the largest and easternmost Chamber of the Hall."},
        [6] = 
            {appendStepText="", stepTextKey="I should talk to Tilelle the Mender."},
        ["Talk to Tilelle the Mender 2"] =
            {appendText=", waiting in the largest and easternmost Chamber of the Hall, by the Galvanic Engine to the southwest.", stepTextKey="I should talk to Tilelle the Mender."},
    },

   [GetQuestName(6093)] = { --"The Mage's Dog"				--Yutoma
        [1] = 
            {appendStepText="", stepTextKey="Orinol mentioned that his cousin Brelenel lives in Cormount. If I travel to Cormount and find Brelenel, I can ask her to take care of Jona for Orinol."},
        ["Find Brelenel in Cormount"] =
            {appendText=", a small village found by following the road north of Elden Root. Brelenel lives in the Graht-oak tree northeast of the main tree. Follow the road up the trunk of the tree to find Brelenel's home."},
        [2] = 
            {appendStepText="In Cormount, ", stepTextKey="I found Orinol's cousin, Brelenel. I should deliver the news of his death and discuss the matter of his dog with her."},
        ["Talk to Brelenel 1"] =
            {appendText=" in her home inside the Graht-oak tree northeast of the main tree. By following the road up the trunk of the tree her home can be found.", stepTextKey="I found Orinol's cousin, Brelenel. I should deliver the news of his death and discuss the matter of his dog with her."},
        [3] = 
            {appendStepText="In Cormount, ", stepTextKey="I found Orinol's cousin, Brelenel, and delivered the news of her cousin's death. I should discuss the matter of his dog with her."},
        ["Talk to Brelenel 2"] =
            {appendText=" inside her home in the Graht-oak tree northeast of the main tree. Follow the road up the trunk of the tree to find her home.", stepTextKey="I found Orinol's cousin, Brelenel, and delivered the news of her cousin's death. I should discuss the matter of his dog with her."},
    },


   [GetQuestName(6061)] = { --"A Matter of Tenderness"				--Yutoma --Jordakai
        [1] = 
            {appendStepText="", stepTextKey="Brengolin requested I acquire the flank of some wild fabricants, which will likely require some hunting, and some hand-raised nix-hound meat from Bratheru Daram's larder. With or without his permission."},
        ["Gather Wild Fabricant Meats"] =
            {appendText=" \n\nWild Fabricants roam the wilds of the Clockwork City.\n"},
        ["Get Hand-Raised Nix Meat"] =
            {appendText=". Brengolin might be able to give me some insight as to where the meat is stored if I talk to him again. Bratheru Daram also lingers near his nix-hounds, tending to their needs. "},
        [2] = 
            {appendStepText="", stepTextKey="I procured all the cuts of meat that Brengolin requested. I should return to him in Slag Town."},
        ["Talk to Brengolin in Slag Town"] =
            {appendText=". He is just outside the entrance to the Outlaws Refuge, in the market."},
        [3] = 
            {appendStepText="", stepTextKey="I gave Brengolin the meat he requested and he rushed off to begin preparing a meal. He invited me to join him in Slag Town to see the fruits of my labor."},
        ["Meet Brengolin in Slag Town Outlaws Refuge"] =
            {appendText="."},
        [4] = 
            {appendStepText="", stepTextKey="Brengolin offered his prepared meals to his friends, and asked me to speak to him so that he can give me something as well."},
        ["Talk to Brengolin"] =
            {appendText=" in the Slag Towns' Outlaw Refuge."},
    },

   [GetQuestName(6092)] = { --"The Merchant's Heirloom"				--Wex
        [1] = 
            {appendStepText="", stepTextKey="An Orcish sword remains upright in the sand, even after all this time. This may be the heirloom sword of Dulza's clan, Morkul of Fell's Run. If I bring it to one of her descendants in Rivenspire, they may reward me."},
        ["Take Morkul Family Sword"] =
            {appendText=". It lies near a stone overhang southwest of the Clockwork Crossroads Wayshrine."},
        [2] = 
            {appendStepText="", stepTextKey="I retrieved the Morkul family sword. If I bring it to Rivenspire and return the sword to one of Dulza's descendants in Fell's Run, they may reward me."},
        ["Find a Morkul Descendent"] =
            {appendText=". Fell's Run is a small village along the road south of Northpoint. The Run Inn would be a good place to start looking. The descendant would likely be an Orc."},
        [3] = 
            {appendStepText="In Rivenspire, ", stepTextKey="I located a descendant of Dulza. I should speak with him about his ancestor and the sword I found."},
        ["Talk to Ghakorz gro-Morkul 1"] =
            {appendText=" in The Run Inn by the fireplace.", stepTextKey="I located a descendant of Dulza. I should speak with him about his ancestor and the sword I found."},
        [4] = 
            {appendStepText="In Rivenspire, ", stepTextKey="I met Dulza's nephew, Ghakorz gro-Morkul. He's grateful I returned his clan's ancestral sword. I should discuss a reward with him."},
        ["Talk to Ghakorz gro-Morkul 2"] =
            {appendText=", raising a pint to his Aunt Dulza by the fire at The Run Inn.", stepTextKey="I met Dulza's nephew, Ghakorz gro-Morkul. He's grateful I returned his clan's ancestral sword. I should discuss a reward with him."},
    },

	[GetQuestName(6036)] = { --"Most Complicated Machine" --Yutoma --Jordakai
		[1] = 
			{appendStepText="In The Cloisters, the inn and tavern of The Brass Fortress, Proctor ", stepTextKey="Sovor told me that searching for Terari's failed experiment may be the best means of finding her. He's provided me with the Apostle's best guess as to where it might be. I should search the area for signs of the experiment and Terari."},
		["Search for Terari"] =
			{appendText=". Proctor Sovor Saryoni can tell me where I should start looking in the district. I suspect I won't have to go far. \n\nTo find the rogue experiment, I should look for and follow any signs, such as Terari's Notes, Factotum Gear in a pile of scrap, and a Gutted Factotum."},
		[2] = 
			{appendStepText="In the Reactor District in the southwest of The Brass Fortress, ", stepTextKey="I found signs that Terari and her failed experiment are in the area. I should concentrate my efforts on a more thorough search of the area."},
		["Find Terari"] =
			{appendText=". Her notes should be helpful and the damaged factotum was by the district's entry to the skybridge."},
		[3] = 
			{appendStepText="Up at the northeastern end of the skybridge in the city's Reactor District, ", stepTextKey="I have located Terari Heladren in a derelict laboratory. I should speak to her about Sovor's request."},
		["Talk to Terari Heladren 1"] =
			{appendText=".", stepTextKey="I have located Terari Heladren in a derelict laboratory. I should speak to her about Sovor's request."},
		[4] = 
			{appendStepText="In the southwestern district of The Brass Fortress, I met the exile up in her derelict laboratory at the northeastern end of the skybridge. ", stepTextKey="Terari revealed that her experiment was an attempt to save her lover's life by installing his soul in a factotum. She was successful, but the process drove him mad. I agreed to destroy it and retrieve the black soul gem holding Bolin's soul."},
		["Find and Destroy Bolin's Body"] =
			{appendText=" in the northwestern area of the Reactor District."},
		[5] = 
			{appendStepText="In the northwestern area of the Reactor District of The Brass Fortress, ", stepTextKey="I destroyed the factotum housing the black soul gem containing Bolin's soul. I should extract it from the wreckage and return to Terari."},
		["Extract the Black Soul Gem"] =
			{appendText=" from Bolin, the factotum."},
		[6] = 
			{appendStepText="In the Reactor District of The Brass Fortress, ", stepTextKey="I retrieved the black soul gem containing Bolin's soul from the wreckage of his machine body. I should bring it to Terari as soon as possible."},
		["Return to Terari's Workshop"] =
			{appendText=" in the derelict laboratory at the northeastern end of the district's skybridge.\n\nThe entry to the skybridge is in the district's northwest."},
		[7] = 
			{appendStepText="In the Reactor District of The Brass Fortress, I returned to Terari's laboratory up on the skybridge's northeastern end. ", stepTextKey="It appears Sovor has convinced Terari to perform her experiment once again and she's preparing another factotum for his procedure. She'll want to know that I have Bolin's black soul gem."},
		["Talk to Terari Heladren 2"] =
			{appendText=".", stepTextKey="It appears Sovor has convinced Terari to perform her experiment once again and she's preparing another factotum for his procedure. She'll want to know that I have Bolin's black soul gem."},
		[8] = 
			{appendStepText="I gave the soul gem to Terari at her laboratory up on the skybridge's northeastern end in the Reactor District of The Brass Fortress. ", stepTextKey="Terari is going to attempt to transfer Sovor's soul into a factotum and release Bolin from the black soul gem. I have agreed to assist in case things spin out of control again. I should initiate the procedure once I'm prepared."},
		["Flip the Switch to Initiate the Transfer"] =
			{appendText=" at the console by Terari."},
		[9] = 
			{appendStepText="In the Reactor District of The Brass Fortress, up in her derelict laboratory at the northeastern end of the skybridge, ", stepTextKey="Terari and I performed the experiment to transfer Sovor's soul into the factotum and free Bolin's spirit. It appears that the procedure was a success. I should speak to Terari about the results."},
		["Talk to Terari Heladren 3"] =
			{appendText=" and the others.", stepTextKey="Terari and I performed the experiment to transfer Sovor's soul into the factotum and free Bolin's spirit. It appears that the procedure was a success. I should speak to Terari about the results."},
	},

[GetQuestName(6045)] = { --"Oasis in a Metal Desert"	--Yutoma --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Sherizar, a Clockwork Apostle initiate who hopes to be selected as this year's apprentice, asked me to accompany her to the entrance to the Wellspring."},
		["Approach the Gate"] =
			{appendText=" of the Everwound Wellspring at the end of the northeastern road in the Radius, the lands outside of the Brass Fortress. It is at the eastern end of a bridge.", stepTextKey="Sherizar, a Clockwork Apostle initiate who hopes to be selected as this year's apprentice, asked me to accompany her to the entrance to the Wellspring."},
		[2] = 
			{appendStepText="", stepTextKey="Lector Naril selected Sherizar to be this year's apprentice and invited the rest of us to come inside. I should enter the Everwound Wellspring and talk to him."},
		["Talk to Lector Naril 1"] =
			{appendText=" up the lift, in the Audience Hall.", stepTextKey="Lector Naril selected Sherizar to be this year's apprentice and invited the rest of us to come inside. I should enter the Everwound Wellspring and talk to him."},
		[3] = 
			{appendStepText="Within the Everwound Wellspring, I met Lector Naril. ", stepTextKey="Lector Naril wants to show off the wonders of this oasis. I should follow him."},
		["Follow Lector Naril"] =
			{appendText=" into the Viewing Garden on level two of the Everwound Wellspring."},
		[4] = 
			{appendStepText="", stepTextKey="Lector Naril finished his tour and noticed that Sherizar has wandered off. I should talk to him."},
		["Talk to Lector Naril 2"] =
			{appendText=" in the Viewing Garden on the second level of the Everwound Wellspring.", stepTextKey="Lector Naril finished his tour and noticed that Sherizar has wandered off. I should talk to him."},
		[5] = 
			{appendStepText="I arrived in the Viewing Garden on level two of the Everwound Wellspring. The new apprentice has dissapeared and ", stepTextKey="Lector Naril wants me to find Sherizar and bring her back so he can get her started on her new duties here in the Everwound Wellspring."},
		["Find Sherizar"] =
			{appendText=". I should start by looking in the Fungal Workshop and Gardens, north of the garden."},
		[6] = 
			{appendStepText="In the Viewing Garden on level two of the Everwound Wellspring, ", stepTextKey="I found Sherizar in one of the Wellspring's fungal workshops. I should talk to her and see what she's up to."},
		["Talk to Sherizar 1"] =
			{appendText=".", stepTextKey="I found Sherizar in one of the Wellspring's fungal workshops. I should talk to her and see what she's up to."},
		[7] = 
			{appendStepText="In the Fungal Workshop and Garden, the northernmost room from the Viewing Garden on level two of the Wellspring, I found Sherizar. ", stepTextKey="Sherizar asked me to help her get past the factotums so she can talk to her old friend, Chirrhari, who also currently serves as one of Lector Naril's apprentices."},
		["Talk to Apprentice Chirrhari"] =
			{appendText=", who should be in the first room, working on her assignments on the left."},
		[8] = 
			{appendStepText="", stepTextKey="Chirrhari suggested we bring a few samples of her fungi to another apprentice named Idrono. It might help endear us to him and get him to answer Sherizar's questions. But she stressed that we should only bring him the safe mushrooms."},
		["Gather Safe Mushroom Samples"] =
			{appendText=" \n\nThe mushrooms are scattered throughout the Fungal Workshop and Gardens, on the second level of the Everwound Wellspring, in the northernmost room in the Viewing Garden."},
		[9] = 
			{appendStepText="On the second level of the Everwound Wellspring, in the Viewing Gardens' northernmost room, the Fungal Workshops and Gardens, I encountered Chirrhari. ", stepTextKey="We gathered the safe mushroom samples as Chirrhari requested. Now we need to deliver them to Apprentice Idrono."},
		["Talk to Apprentice Idrono"] =
			{appendText=". I can get to him using the first set of elevators within the Fungal Workshop and Gardens. He should be working on the third level of the Wellspring, in the Sunless Garden Workshop. Lector Naril may also have something to say."},
		[10] = 
			{appendStepText="In the Sunless Garden, on level three of the Wellspring, accessed through the Viewing Gardens' northernmost room, the Fungal Workshop and Gardens, we found Apprentice Idrono. ", stepTextKey="We need to cross the Sunless Garden to talk to Apprentice Ohtowen. Apprentice Idrono warned us to watch out for the fabricants that invaded his garden as we pass through that area."},
		["Talk to Apprentice Ohtowen"] =
			{appendText=", using the elevator to the Botanical Garden, through its Antechamber. She should be in the first room. Lector Naril may also have something to say."},
		[11] = 
			{appendStepText="On level four of the Wellspring, in the Botanical Garden, accessed through the Viewing Gardens' northernmost room, the Fungal Workshop and Gardens, and through the Sunless Garden, we found Apprentice Ohtowen. ", stepTextKey="Ohtowen suggested there might be evidence of the other apprentices in Lector Naril's private workshop. A broken vent is our best way to reach the restricted area."},
		["Reach the Private Workshop"] =
			{appendText="."},
		[12] = 
			{appendStepText="On level four of the Wellspring, in the Botanical Garden, accessed through the Viewing Gardens' northernmost room, the Fungal Workshop and Gardens, and through the Sunless Garden, we found Apprentice Ohtowen. She directed us into a broken vent in order to access Lector Naril's office. \n\n", stepTextKey="We entered Lector Naril's restricted area. Sherizar suggested we examine his notes to see if he makes any mention of the apprentices that appear to be unaccounted for."},
		["Examine Lector Naril's Notes"] =
			{appendText=" \n\nI'm sure they're scattered around this area."},
		[13] = 
			{appendStepText="On level four of the Wellspring, in the Botanical Garden, accessed through the Viewing Gardens' northernmost room, the Fungal Workshop and Gardens, and through the Sunless Garden, we found Apprentice Ohtowen. Ohtowen told us to enter the broken vent in order to access Naril's private workshop.\n\n", stepTextKey="Lector Naril's notes indicate that the Wellspring is fueled by the life force of the missing apprentices. I should follow Sherizar into the Simulated Sunlight Atelier and see what she thinks about all this."},
		["Enter the Atelier and Talk to Sherizar"] =
			{appendText="."},
		[14] = 
			{appendStepText="On level four of the Wellspring, in the Botanical Garden, accessed through the Viewing Gardens' northernmost room, the Fungal Workshop and Gardens, and through the Sunless Garden, we found Apprentice Ohtowen. Ohtowen told us to enter the broken vent in order to access Naril's private workshop.\n\n", stepTextKey="I have to stop Lector Naril's mad plan to sacrifice Sherizar and myself in order to fuel the simulated sunlight that keeps the plants alive."},
		["Defeat Lector Naril"] =
			{appendText=" in his Private Workshop, accessed through the Atelier."},
		[15] = 
			{appendStepText="On level four of the Wellspring, in the Botanical Garden, accessed through the Viewing Gardens' northernmost room, the Fungal Workshop and Gardens, and through the Sunless Garden, we found Apprentice Ohtowen. Ohtowen told us to enter the broken vent in order to access Naril's private workshop. Through the vent we found Naril's Atelier and managed to get into his workshop.\n\n", stepTextKey="I defeated Lector Naril. Now I should talk to Sherizar and decide what to do with the simulated sunlight inductor."},
		["Talk to Sherizar 2"] =
			{appendText=" back in the Atelier.", stepTextKey="I defeated Lector Naril. Now I should talk to Sherizar and decide what to do with the simulated sunlight inductor."},
		[16] = 
			{appendStepText="On level four of the Wellspring, in the Botanical Garden, accessed through the Viewing Gardens' northernmost room, the Fungal Workshop and Gardens, and through the Sunless Garden, we found Apprentice Ohtowen. Ohtowen told us to enter the broken vent in order to access Naril's private workshop. Through the vent we found Naril's Atelier, where I eventually defeated Lector Naril.\n\n", stepTextKey="I advised Sherizar to call for volunteers to sacrifice themselves to keep the inductor running and the Wellspring producing food."},
		["Talk to Sherizar 3"] =
			{appendText=" in the Atelier.", stepTextKey="I advised Sherizar to call for volunteers to sacrifice themselves to keep the inductor running and the Wellspring producing food."},
		[17] = 
			{appendStepText="On level four of the Wellspring, in the Botanical Garden, accessed through the Viewing Gardens' northernmost room, the Fungal Workshop and Gardens, and through the Sunless Garden, we found Apprentice Ohtowen. Ohtowen told us to enter the broken vent in order to access Naril's private workshop. Through the vent we found Naril's Atelier, where I eventually defeated Lector Naril.\n\n", stepTextKey="I advised Sherizar to shut down the inductor. No amount of food is worth sacrificing vibrant, healthy lives."},
		["Talk to Sherizar 4"] =
			{appendText=" in the Atelier.", stepTextKey="I advised Sherizar to shut down the inductor. No amount of food is worth sacrificing vibrant, healthy lives."},
	},

    [GetQuestName(6060)] = { --"Tasty Tongue Varnish"			--Yutoma
        [1] = 
            {appendStepText="", stepTextKey="Brengolin's friend, Maurice, suggested I might find where more Root Liqueur can be found by asking around at the Brass Fortress Guild Traders."},
        ["Learn the Location of the Root Liqueur"] =
            {appendText="."},
        [2] = 
            {appendStepText="", stepTextKey="Maurice Ouren confessed that he counterfeited the Root Liqueur. He will need Wellspring Hooch from the Catalog of Rote Duplication and Port Hunding Reserve from Port Hunding in Stros M'kai to recreate the concoction."},
        ["Steal Port Hunding Reserve in Stros M'kai"] =
            {appendText="'s tavern, the Screaming Mermaid. The Crate of Port Hunding Reserve is hiding behind some chairs in the largest bedroom, on the second level of the tavern."},
        ["Steal Wellspring Hooch"] =
            {appendText=", from the Catalog of Rote Duplication. The Catalog is on the second level of the Clockwork Bassilica, directly north of the main square in the Brass Fortress. The Wellspring Hooch should be behind some bookcases, on the east side of the Catalog."},
        [3] = 
            {appendStepText="", stepTextKey="I have the Wellspring Hooch and Port Hunding Reserve that Maurice Ouren needs to brew his counterfeit Root Liqueur. I should return it to him in Slag Town."},
        ["Return to Maurice in Slag Town"] =
            {appendText="'s Outlaw Refuge."},
        [4] = 
            {appendStepText="", stepTextKey="I gave Maurice the Wellspring Hooch and Port Hunding Reserve. Now he's working on creating another batch of his counterfeit Root Liqueur. Once it's ready, Maurice will provide it to me."},
        ["Get the Counterfeit Liqueur from Maurice"] =
            {appendText=" in Slag Town's Outlaw Refuge."},
        [5] = 
            {appendStepText="", stepTextKey="I have the \"Root Liqueur\" Brengolin asked for. I should bring it to him in Slag Town."},
        ["Take the Root Liqueur to Brengolin"] =
            {appendText=", likely working on his recipes in the Outlaws Refuge."},
    },

[GetQuestName(6066)] = { --"The Precursor"			--Yutoma
        [1] = 
            {appendStepText="Within the Brass Fortress, ", stepTextKey="I should seek Associate Zanon in his workshop to inquire about the task."},
        ["Talk to Associate Zanon 1"] =
            {appendText=" within his workshop, in the southern area of the Reactor District within the Brass City. ", stepTextKey="I should seek Associate Zanon in his workshop to inquire about the task."},
        [2] = 
            {appendStepText="The Integral of Memory is within the Mnemonic Planisphere's Upper Thief's Wing. The Planisphere is a large building east of the main path to the Brass Fortress.\n\n", stepTextKey="The factotum's head contains a repeating message stating where to find its Integral of Memory. I should go to the Mnemonic Planisphere to find the missing component."},
        ["Obtain the Integral of Memory"] =
            {appendText=". The Integral resembles a crystal, with gold sparks radiating from it."},
        [3] = 
            {appendStepText="", stepTextKey="I should bring the Integral of Memory back to Associate Zanon."},
        ["Talk to Associate Zanon 2"] =
            {appendText=" within his workshop, in the southern area of the Reactor District within the Brass City. ", stepTextKey="I should bring the Integral of Memory back to Associate Zanon."},
        [4] = 
            {appendStepText="Within his workship, in the southern area of Reactor District of the Brass City, ", stepTextKey="Associate Zanon has given me the honors of installing the Integral of Memory. I should do so."},
        ["Use the Framework to Install the Integral"] =
            {appendText="."},
        [5] = 
            {appendStepText="Within his workshop, in the southern area of the Reactor District within the Brass City, ", stepTextKey="I installed the Integral of Memory. I should see how the factotum head responds."},
        ["Talk to the Factotum Head."] =
            {appendText="."},
        [6] = 
            {appendStepText="Within his workshop, in the southern area of the Reactor District within the Brass City, ", stepTextKey="I've spoken to the Precursor and have learned that the rest of the factotum's memory is contained in its other missing parts. I should speak to Associate Zanon about this development."},
        ["Talk to Associate Zanon 3"] =
            {appendText=".", stepTextKey="I've spoken to the Precursor and have learned that the rest of the factotum's memory is contained in its other missing parts. I should speak to Associate Zanon about this development."},
    },

   [GetQuestName(6095)] = { --"The Registrar's Request"			--Wex
        [1] = 
            {appendStepText="", stepTextKey="I found one sequence plaque so far. If I follow the road, there may be more ahead. If I find more sequence plaques and return them, perhaps I'll receive a reward."},
        ["Search for the Third Plaque"] =
            {appendText=". The path begins in a canyon underneath the bridge leading to Everwound Wellspring. The path is barely visible, but littered with Dwemer scraps going to the south."},
        [2] = 
            {appendStepText="", stepTextKey="I found sequence plaques CCHW-04 and CCHW-03. This suggests two plaques remain. I should keep looking."},
        ["Search for the Second Plaque"] =
            {appendText=". The path cuts to the west and heads uphill to the far side of the canyon from Everwound Wellspring."},
        [3] = 
            {appendStepText="", stepTextKey="I found sequence plaques CCHW-04, CCHW-03, and CCHW-02. This suggests only one plaque remains. I should keep looking."},
        ["Search for the First Plaque"] =
            {appendText=". The path is much more visible now, and continues uphill. It should take me to the opposite end of the bridge from Everwound Wellspring."},
        [4] = 
            {appendStepText="", stepTextKey="I found all four sequence plaques. Now I should return these plaques to the Clockwork Registrar in the Brass Fortress to receive my reward."},
        ["Deliver the Plaques to the Clockwork Registrar"] =
            {appendText=" within the Chancel of Records, the upper level of the Archivox to the west of The Grand Depository."},
        [5] = 
            {appendStepText="", stepTextKey="The Clockwork Registrar confirmed that it wants these sequence plaques. I should ask if there's a reward for returning them."},
        ["Talk to the Clockwork Registrar"] =
            {appendText=" within the Chancel of Records above the Archivox."},
    },

    [GetQuestName(6049)] = { --"The Shadow Cleft"			--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="When I'm ready to begin my investigation, I should enter the mysterious portal."},
        ["Enter the Mysterious Portal"] =
            {appendText=".\n\nThe Shadow Cleft portal is southwest of the Sanctuary Wayshrine in southwestern Radius, the lands outside of Brass Fortress."},
        [2] = 
            {appendStepText="I entered the dark, shadowy portal a short distance southwest of Sanctuary Wayshrine in the southwest Radius, outside the Brass Fortress. ", stepTextKey="Now that I'm inside the Shadow Cleft, I should look around for Acolyte Variah and try to determine the nature of this place."},
        ["Search the Area"] =
            {appendText=" by following the path through the shadowy realm to the northeast. I should watch for any evidence of the Acolyte's travel and location."},
        [3] = 
            {appendStepText="I entered The Shadow Cleft's portal a short distance southwest of Sanctuary Wayshrine in the southwest Radius, outside the Brass Fortress. Then ", stepTextKey="I came across some unusual scarecrows while searching the Shadow Cleft. I should use the perception tabulator on them and see what happens."},
        ["Investigate Scarecrows"] =
            {appendText=" \n\nIn the realm's northeast, near fields of pumpkins, I should find the scarecrows."},
        [4] = 
            {appendStepText="The Shadow Cleft's entry portal is a short distance southwest of Sanctuary Wayshrine in the southwest Radius, outside the Brass Fortress. ", stepTextKey="Acolyte Variah asked me to destroy the shadow array that keeps her and the other souls trapped within the scarecrows. I should locate it and destroy it to deal a blow to Night Sister Kamira."},
        ["Destroy the Shadow Array"] =
            {appendText=" near the ruins to the northwest. The Array sits on an altar between two crows."},
        [5] = 
            {appendStepText="In The Shadow Cleft, ", stepTextKey="I destroyed the shadow array and freed the trapped souls. Now I should find Adjunct Daro, return the perception tabulator, and tell him what happened to Acolyte Variah."},
        ["Talk to Adjunct Daro"] =
            {appendText=". He waits near The Shadow Cleft portal, a short distance southwest of the Sanctuary Wayshrine in the southwest Radius, outside the Brass Fortress."},
    },

    [GetQuestName(6059)] = { --"Tarnished Truffles"		--Yutoma
        [1] = 
            {appendStepText="", stepTextKey="Brengolin has asked me to harvest some rare mushrooms from the Halls of Regulation, but he also needs me to acquire the secret techniques used to prepare them from an uncooperative shroommonger named Salas Ramothran."},
        ["Find Ironstalk Mushroom"] =
            {appendText=" \n\nThe Halls of Regulation are located east of the Clockwork Crossroads, on a island. The Ironstalk Mushrooms are small brown mushrooms which grow near or in shallow water. Two mushrooms can be found in the main Hall, and one in the Regulation Chamber, the largest chamber in the Halls."},
        ["Steal Salas Ramothran's Notes"] =
            {appendText=". Brengolin can provide more insight as to where these notes might be. Salas works on the second level of The Hall of Refined Techniques."},
        [2] = 
            {appendStepText="", stepTextKey="I gathered the mushrooms and stole Salas's notes, as Brengolin asked. I should give them to him next time I'm in Slag Town."},
        ["Talk to Brengolin"] =
            {appendText=", trying to perfect his recipes in the Outlaws Refuge."},
    },

    [GetQuestName(6075)] = { --"The Oscillating Son"			--Jordakai
        [1] = 
            {appendStepText="I spoke with Zanon at his workshop in the south Reactor District in the western Brass Fortress. ", stepTextKey="I should seek out Lector Trivura in the Mechanical Fundament and convince her to come evaluate the Precursor."},
        ["Talk to Lector Trivura"] =
            {appendText=". She is often in the southwestern area on the main level of the Fundament.\n\nAn entrance to the Mechanical Fundament is by the lower entrance to The Grand Depository in the Brass Fortress."},
        [2] = 
            {appendStepText="I found Trivura meditating in the Mechanical Fundament of the Brass Fortress. ", stepTextKey="Lector Trivura has agreed to evaluate the Precursor. I should speak to Associate Zanon and let him know."},
        ["Talk to Associate Zanon"] =
            {appendText=" on the lower level of his workshop in a southern alley of the city's western Reactor District."},
    },

