    [GetQuestName(6107)] = { --"A Matter of Leisure" --Jordakai
        [1] = 
            {appendStepText="In the Brass Fortress' eastern tenement of Slag Town, I agreed to acquire some items for the Blackfeather Court. ", stepTextKey="The Bursar of Tributes requested I steal trinkets of leisure for the Blackfeather Court to play with."},
        ["Gather Toys and Games"] =
            {appendText=" \n\nThe crows will accept these items, whether laundered or not, from wherever I can acquire them."},
        [2] = 
            {appendStepText="In the Brass Fortress' eastern tenement of Slag Town, I agreed to acquire some items for the Blackfeather Court. ", stepTextKey="The Bursar of Tributes requested I steal trinkets of leisure for the Blackfeather Court to play with."},
        ["Bring Items to Bursar of Tributes"] =
            {appendText=" in the Brass Fortress' eastern tenement of Slag Town, south of Daram Stables."},
        [3] = 
            {appendStepText="", stepTextKey="I gathered toys and games as the Bursar of Tributes requested. Now I should return to him and claim my reward."},
        ["Talk to the Bursar of Tributes"] =
            {appendText=" in the Brass Fortress' eastern tenement of Slag Town, south of Daram Stables."},
    },

