    [GetQuestName(6024)] = { --"Glitter and Gleam" --Jordakai
        [1] = 
            {appendStepText="In the Brass Fortress' eastern tenement of Slag Town, south of Daram Stables, I met with an important crow of the Court. ", stepTextKey="The Bursar of Tributes requested I acquire pieces of ornate armor from Clockwork City and beyond to add to the Blackfeather Court's collection of glittering and gleaming objects."},
        ["Find Ornate Armor"] =
            {appendText=" \n\nThe Blackfeather Court will accept any kind of ornate armor, including shields."},
        [2] = 
            {appendStepText="In the Brass Fortress' eastern tenement of Slag Town, south of Daram Stables, I met with an important crow of the Court. ", stepTextKey="The Bursar of Tributes requested I acquire pieces of ornate armor from Clockwork City and beyond to add to the Blackfeather Court's collection of glittering and gleaming objects."},
        ["Bring Items to Bursar of Tributes"] =
            {appendText=" in the Brass Fortress' eastern tenement of Slag Town, south of Daram Stables."},
        [3] = 
            {appendStepText="", stepTextKey="I collected ornate pieces of armor for the Blackfeather Court. I should bring them to the Bursar of Tributes and claim my reward."},
        ["Talk to the Bursar of Tributes"] = 
            {appendText=" in the Brass Fortress' eastern tenement of Slag Town, south of Daram Stables."},
    },

    [GetQuestName(6071)] = { --"Morsels and Pecks" --Jordakai
        [1] = 
            {appendStepText="In the Brass Fortress' eastern tenement of Slag Town, south of Daram Stables, I met with an important crow of the Court. ", stepTextKey="The Bursar of Tributes requested I scavenge elemental essence, supple roots, and ectoplasm to help feed the Blackfeather Court."},
        ["Scavenge Elemental Essence"] =
