    [GetQuestName(6070)] = { --"Nibbles and Bits"				--Jordakai
        [1] = 
            {appendStepText="In the Brass Fortress' eastern tenement of Slag Town, south of Daram Stables, I met with an important crow of the Court. ", stepTextKey="The Bursar of Tributes requested I scavenge carapaces, foul hides, and Daedra husks that he can add to the Blackfeather Court's collection of fleshy bits."},
        ["Scavenge Carapaces"] =
            {appendText=" \n\n"},
        ["Scavenge Foul Hides"] =
            {appendText=" \n\n"},
        ["Scavenge Daedra Husks"] =
            {appendText=" \n\n"},
        [2] = 
            {appendStepText="In the Brass Fortress' eastern tenement of Slag Town, south of Daram Stables, I met with an important crow of the Court. ", stepTextKey="The Bursar of Tributes requested I scavenge carapaces, foul hides, and Daedra husks that he can add to the Blackfeather Court's collection of fleshy bits."},
        ["Bring Items to Bursar of Tributes"] =
            {appendText=" in the Brass Fortress' eastern tenement of Slag Town, south of Daram Stables."},
        [3] = 
            {appendStepText="", stepTextKey="I scavenged bits of carcasses for the Blackfeather Court. I should bring them to the Bursar of Tributes and collect my reward."},
        ["Talk to the Bursar of Tributes"] =
            {appendText=" in the Brass Fortress' eastern tenement of Slag Town, south of Daram Stables."},
    },

    [GetQuestName(6042)] = { --"A Bitter Pill"				--Jordakai
        [1] = 
            {appendStepText="South of Daram Stables in the Brass Fortress' eastern tenement of Slag Town, I accepted work from Razgurug. ", stepTextKey="I should harvest sources of alchemy plants in Clockwork City and see if I can find herbalist's satchels. I'll also need to collect specious syrup in the Everwound Wellspring."},
        ["Collect Herbalist's Satchel"] =
            {appendText=" \n\nI should look for brown satchels on the ground in the Radius, the lands outside of the Brass Fortress.\n\nBefore I go, I should speak with Aveberl Tremouille cooking at a large cauldron near Razgurug.\n"},
        ["Collect Specious Syrup"] =
            {appendText=" \n\nThe Everwound Wellspring is in the Radius, across a bridge at the end of the northeastern road, east of Mire Mechanica Wayshrine. I should use the lift to the Audience Hall, then go out the east door to the Viewing Garden. In the Fungal Gardens and other areas of the facility, I should look for Specious Syrup Cache chests."},
        [2] = 
            {appendStepText="", stepTextKey="I have all the resources. I should deliver them to Razgurug."},
        ["Talk to Razgurug"] =
            {appendText=". He is south of Daram Stables in the Brass Fortress' eastern tenement of Slag Town."},
    },

   [GetQuestName(6038)] = { --"A Daily Grind"				--Jordakai
        [1] = 
            {appendStepText="South of Daram Stables in Brass Fortress' eastern tenement of Slag Town, I accepted work from Razgurug. ", stepTextKey="I should harvest sources of ore within Clockwork City and see if I can find flash stone. I also need to collect metal pellets in the Mechanical Fundament."},
        ["Collect Flash Stone from Sources of Ore"] =
            {appendText=" \n\nI should mine Ores in the Radius, the lands outside of the Brass Fortress.\n"},
        ["Collect Metal Pellets"] =
            {appendText=" \n\nDoors to the Fundament are by the lower door of the city's Great Depository. Stockpile chests can be found in the facility.\n\nDuldrar Belan is mining a stone wall not far from Razgurug."},
        [2] = 
            {appendStepText="", stepTextKey="I have all the resources. I should deliver them to Razgurug."},
        ["Talk to Razgurug"] =
            {appendText=". He is south of Daram Stables in the Brass Fortress' eastern tenement of Slag Town."},
    },

    [GetQuestName(6040)] = { --"A Sticky Solution"			--Jordakai
        [1] = 
            {appendStepText="South of Daram Stables in the Brass Fortress' eastern tenement of Slag Town, I accepted work from Razgurug. ", stepTextKey="I should harvest sources of wood within Clockwork City and see if I can find fabricated husk. I also need to collect counterfeit coal in the Reactor District."},
        ["Collect Fabricated Husk from Wood Sources"] =
            {appendText=" \n\nI should look for scrap wood to harvest in the Radius, the lands outside of the Brass Fortress."},
        ["Collect Counterfeit Coal"] =
            {appendText=" \n\nI should find chests of stockpiled counterfeit coal in the Reactor District of the western Brass Fortress.\n\nBefore I start, I should speak with Njordemar. He is tinkering next to Razgurug."},
        [2] = 
            {appendStepText="", stepTextKey="I have all the resources. I should deliver them to Razgurug."},
        ["Talk to Razgurug"] =
            {appendText=". He is waiting south of Daram Stables in the Brass Fortress' eastern tenement of Slag Town."},
    },

    [GetQuestName(6041)] = { --"Enchanted Accumulation"			--Jordakai
        [1] = 
            {appendStepText="South of Daram Stables in Brass Fortress' eastern tenement of Slag Town, I accepted work from Razgurug. ", stepTextKey="I should harvest runestones in Clockwork City to see if I can find runic residue. I'll also need to collect runelights in a mysterious realm."},
        ["Collect Runic Residue from Clockwork Runestones"] =
            {appendText=" \n\nI should look for Runestones in the Radius, the lands outside of Brass Fortress."},
        ["Collect Inert Runelights"] =
            {appendText=" \n\nRunelight Cache chests are in The Shadow Cleft. Its entry portal is a short distance southwest of Sanctuary Wayshrine in the Radius.\n\nI should speak with Mindora working at her desk near Razgurug."},
        [2] = 
            {appendStepText="", stepTextKey="I have all the resources. I should deliver them to Razgurug."},
        ["Talk to Razgurug"] =
            {appendText=". He is south of Daram Stables in Brass Fortress' eastern tenement of Slag Town."},
    },

    [GetQuestName(6037)] = { --"Fuel for our Fires"		--Jordakai
        [1] = 
            {appendStepText="South of Daram Stables in the Brass Fortress' eastern tenement of Slag Town, I accepted work from Razgurug. ", stepTextKey="I should harvest sources of water and see if I can find synthetic oils. I also need to collect skimmer mesh in the Halls of Regulation."},
        ["Collect Synthetic Oils from Water Sources"] =
            {appendText=" \n\nWater sources, such as Water Skins, can be found in the Radius, the lands outside of the Brass Fortress.\n"},
        ["Collect Skimmer Mesh"] =
            {appendText=" \n\nIn the southeast Radius, on an island in an oily lake, the facility has Rubble Piles that should be a good source for the mesh."},
        [2] = 
            {appendStepText="", stepTextKey="I have all the resources. I should deliver them to Razgurug."},
        ["Talk to Razgurug"] =
            {appendText=", south of Daram Stables in the Brass Fortress' eastern tenement of Slag Town."},
    },

    [GetQuestName(6039)] = { --"Loose Strands"		--Jordakai
        [1] = 
            {appendStepText="South of Daram Stables in the Brass Fortress' eastern tenement of Slag Town, I accepted work from Razgurug. ", stepTextKey="I should harvest sources of cloth within Clockwork City and see if I can find metallic fibers. I also need to collect lodestone parts in the Mnemonic Planisphere."},
        ["Collect Metallic Fibers from Cloth Sources"] =
            {appendText=" \n\nI should look for Torn Cloth in the Radius, the lands outside of the Brass Fortress.\n"},
        ["Collect Artificial Lodestone Parts"] =
            {appendText=" \n\nThe Planisphere is in the Radius, south of Brass Fortress and east of Clockwork Crossroads Wayshine. Rubble Piles can be found in the wings of the planisphere.\n\nI should speak with Avaryz, a female Altmer working on a grate-roof, just east of Razgurug."},
        [2] = 
            {appendStepText="", stepTextKey="I have all the resources. I should deliver them to Razgurug."},
        ["Talk to Razgurug"] =
            {appendText=". He is south of Daram Stables in the Brass Fortress' eastern tenement of Slag Town."},
    },

    [GetQuestName(6077)] = { --"A Fine-Feathered Foe"			--Jordakai
        [1] = 
            {appendStepText="North of the Brass Fortress Wayshrine, a Clockwork Facilitator provided me with contract work.\n\n", stepTextKey="I should travel to Exarchs' Egress in order to defeat the Daedric creatures and the Wraith-of-Crows."},
        ["Defeat the Wraith-of-Crows"] =
            {appendText=" within its cavernous lair, accessed via a portal in a tunnel in the rock formation north of the Mire Mechanica Wayshrine in the northeastern Radius outside of the Brass Fortress.\n\n"},
        ["Stop Daedric Incursions"] =
            {appendText=" \n\nAs I approach Exarch's Egress, I should watch for shadowy incursions."},
        [2] = 
            {appendStepText="", stepTextKey="I should return to the Brass Fortress to collect my reward from the Clockwork Facilitator."},
        ["Talk to the Clockwork Facilitator"] =
            {appendText=" north of the Brass Fortress Wayshrine."},
    },

[GetQuestName(6076)] = { --"Inciting the Imperfect"			--Jordakai
        [1] = 
            {appendStepText="On the north side of the Brass Fortress Wayshrine, a Clockwork Facilitator provided me with contract work. ", stepTextKey="I should head to the Sanctuary of Verification in order to defeat the Imperfect and collect the sequence plaques."},
        ["Defeat the Imperfect"] =
            {appendText=" in the Sanctuary of Verification. It is west of the Brass Fortress, across the bridge north of the Sanctuary Wayshrine.\n"},
        ["Collect Sequence Plaques"] =
            {appendText=" \n\nAs I approach the Sanctuary of Verification, I should gather plaques from Rubble Piles. Rubble may be on or under the bridge, in the facility, or perhaps I can get a plaque from the Imperfect."},
        [2] = 
            {appendStepText="", stepTextKey="I should return to the Brass Fortress to collect my reward from the Clockwork Facilitator."},
        ["Talk to the Clockwork Facilitator"] =
            {appendText=" on the north side of the Brass Fortress Wayshrine."},
    },

    [GetQuestName(6079)] = { --"Again Into the Shadows"			--Jordakai
        [1] = 
            {appendStepText="East of the Brass Fortress Wayshrine, I accepted an assignment from Novice Holli. ", stepTextKey="I should enter the Shadow Cleft and locate Evoker Tadari and the missing perception tabulator the apostles provided her with."},
        ["Find Evoker Tadari"] =
            {appendText=", a Khajiiti mage, who may be hiding in a ruin to the northeast in the shadow realm.\n"},
        ["Find the Perception Tabulator"] =
            {appendText=" in a backpack, north of a bridge to the northeast./nThe Shadow Cleft's entry portal is a short distance southwest of the Sanctuary Wayshrine in the southwest Radius, outside the Brass Fortress."},
        [2] = 
            {appendStepText="In the Shadow Cleft's realm, ", stepTextKey="I rescued Evoker Tadari and found the missing perception tabulator. Now I should leave the Shadow Cleft and return to Adjunct Daro."},
        ["Talk to Adjunct Daro"] =
            {appendText=". He will be waiting at his worktable on the top floor of The Grand Depository in the Brass Fortress."},
    },

    [GetQuestName(6080)] = { --"A Shadow Malfunction"		--Jordakai
        [1] = 
            {appendStepText="East of the Brass Fortress Wayshrine, I accepted an assignment from Novice Holli. ", stepTextKey="I agreed to enter the Shadow Cleft, locate the missing apostle, and use the perception tabulator to perform additional research on the dark realm."},
        ["Find Initiate Favar"] =
            {appendText=", an inexperienced Apostle. He may be seeking refuge in a ruin in the far eastern shadow realm."},
        ["Use the Perception Tabulator"] =
            {appendText=" \n\nOnce near a ruin in the center of the realm, then near a ruin in the northwest, and finally at a ruin in the southwest.\nThe Shadow Cleft's entry portal is a short distance southwest of Sanctuary Wayshrine in the southwest Radius, outside the Brass Fortress."},
        [2] = 
            {appendStepText="In the Shadow Cleft's realm, ", stepTextKey="I found Initiate Favar's body. There was nothing I could do for him, but I was able to complete his analysis of the Shadow Cleft. I should return to the Grand Depository and let Adjunct Daro know."},
        ["Talk to Adjunct Daro"] =
            {appendText=". He will be waiting at his worktable on the top floor in The Grand Depository of the Brass Fortress."},
    },

   [GetQuestName(6073)] = { --"A Shadow Misplaced"		--Jordakai
        [1] = 
            {appendStepText="On the east side of the Brass Fortress Wayshrine, I accepted an assignment from Novice Holli. ", stepTextKey="I should enter the portal to the Shadow Cleft and look for the lost apostle, Novice Oscard, and his research notes."},
        ["Find Novice Oscard"] =
            {appendText=". He may be seeking refuge in a ruin in the shadow realm to the northwest. Adjunct Daro, at his office on the top floor of The Grand Depository, knows more about him.\n"},
        ["Gather Oscard's Notes"] =
            {appendText=" in a ruin at the center of the realm.\n\nThe Shadow Cleft's entry portal is a short distance southwest of Sanctuary Wayshrine in the Radius' southwest, outside the Brass Fortress."},
        [2] = 
            {appendStepText="In the Shadow Cleft's realm, ", stepTextKey="I rescued Novice Oscard and gathered his research notes. Now I should leave the Shadow Cleft and return to Adjunct Daro at the Grand Depository."},
        ["Talk to Adjunct Daro"] =
            {appendText=" in his office on the top floor of The Grand Depository in the Brass Fortress."},
    },

    [GetQuestName(6088)] = { --"Changing the Filters"		--Jordakai
        [1] = 
            {appendStepText="East of the Brass Fortress Wayshrine, I accepted an assignment from Novice Holli. ", stepTextKey="I should travel to the Halls of Regulation and find water filters. I'll need to defeat repair factotums in order to do so."},
        ["Collect Water Filters"] =
            {appendText=" \n\nThe Halls of Regulation facility is on an island in an oily lake in southwestern Radius, outside the Brass Fortress.\n\nInitiate Tilelle is in the entry area of the Clockwork Basilica, north of The Grand Depository in the Brass Fortress."},
        [2] = 
            {appendStepText="In the Halls of Regulation, on an island in an oily lake in southeastern Radius, outside the Brass Fortress, ", stepTextKey="I should head to the Purification Chamber to replace the water filters."},
        ["Replenish the Filtration System"] =
            {appendText=" in the facility's southern chamber with the rectangular pool."},
        [3] = 
            {appendStepText="In the Halls of Regulation, ", stepTextKey="I've successfully replaced the water filters. I should return to the Brass Fortress to claim my reward."},
        ["Talk to Initiate Tilelle"] =
            {appendText=" in the entry area of the Clockwork Basilica, north of The Grand Depository at the Brass Fortress."},
    },

    [GetQuestName(6081)] = { --"Oiling the Fans"		--Jordakai
        [1] = 
            {appendStepText="On the east side of the Brass Fortress Wayshrine, I accepted an assignment from Novice Holli. ", stepTextKey="I should travel to the Halls of Regulation and find saturated oil. I'll need to defeat repair factotums in order to do so."},
        ["Collect Saturated Oil"] =
            {appendText=" \n\nThe Halls of Regulation is located on an island in an oily lake in the eastern Radius, outside of the Brass Fortress.\nBefore I go to the facility, I can speak with the Initiate inside the entrance to the city's Clockwork Basilica, north of The Grand Depository."},
        [2] = 
            {appendStepText="In the Halls of Regulation on the island in the eastern, oily lake of the Radius, ", stepTextKey="I should head to the Humidity Chamber to oil the ventilation fan."},
        ["Oil the Ventilation Fan"] =
            {appendText=". The Humidity Chamber is in the northwest area."},
        [3] = 
            {appendStepText="In the Humidity Chamber of the Halls of Regulation, ", stepTextKey="I've successfully oiled the ventilation fan. I should return to the Brass Fortress to claim my reward."},
        ["Talk to Initiate Tilelle"] =
            {appendText=" inside the Clockwork Basilica, north of The Grand Depository in the Brass Fortress."},
    },

          [GetQuestName(6089)] = { --"Replacing the Commutators"		--Jordakai
        [1] = 
            {appendStepText="On the east side of the Brass Fortress Wayshrine, I accepted an assignment from Novice Holli. ", stepTextKey="I should travel to the Halls of Regulation and find brass commutators. I'll need to defeat repair factotums in order to do so."},
        ["Collect Commutators"] =
            {appendText=" \nThe Halls of Regulation facility is on the island in the oily lake of southwestern Radius, outside the Brass Fortress.\n\nInitiate Tilelle is in the entry area of the Clockwork Basilica, north of The Grand Depository in the Brass Fortress."},
        [2] = 
            {appendStepText="In the Halls of Regulation on the island in the oily lake in the southeastern Radius, outside the Brass Fortress, ", stepTextKey="I should head to the Regulation Chamber to replace the brass commutators."},
        ["Repair the Galvanic Engine"] =
            {appendText=" in the facility's eastern Regulation Chamber in the large cavern. The engine repair console is at the end of the southwestern bridge on the upper platform."},
        [3] = 
            {appendStepText="In the Halls of Regulation, ", stepTextKey="I successfully replaced the brass commutators. I should return to the Brass Fortress to claim my reward."},
        ["Talk to Initiate Tilelle"] =
            {appendText=" in the entry area of the Clockwork Basilica, north of The Grand Depository in the Brass Fortress."},
    },
-- ==================================================================================================================================================
--	Summerset																															Undaunted
-- ==================================================================================================================================================

-- 		=========================================================================
--		  Summerset - Main Quest 
-- 		=========================================================================

[GetQuestName(6097)] = { --"Through a Veil Darkly" --Jordakai

    ["Talk to Vanus Galerion 1"] = {
		appendStepText="",
		stepTextKey="After I activated the message stone, a projection of Vanus Galerion appeared before me. I should speak to the mage's projection.",
		appendText="'s projection."
    },
    ["Talk to Vanus Galerion in the Mages Guild"] = {
        appendStepText = {
            [ALLIANCE_ALDMERI_DOMINION] = "",
            [ALLIANCE_DAGGERFALL_COVENANT] = "",
            [ALLIANCE_EBONHEART_PACT] = ""
        },
        stepTextKey = "Vanus Galerion claims to have a message for me from an Oracle. I should talk to him in the Mages Guild and see what this is all about.",
        appendText = {
            [ALLIANCE_ALDMERI_DOMINION] = " in Vulkhel Guard, the southern port city of Auridon.",
            [ALLIANCE_DAGGERFALL_COVENANT] = " in Daggerfall, the southern port city of Glenumbra.",
            [ALLIANCE_EBONHEART_PACT] = " in Davon's Watch, the northeastern city of Stonefalls."
        }
    },
    ["Travel Via the Enchanted Boat"] = {
        appendStepText = {
            [ALLIANCE_ALDMERI_DOMINION] = "In the Mages Guild at Auridon's southern port city of Vulkhel Guard, I spoke with the mage. ",
            [ALLIANCE_DAGGERFALL_COVENANT] = "In the Mages Guild at Glenumbra's southern port city of Daggerfall, I spoke with the mage. ",
            [ALLIANCE_EBONHEART_PACT] = "In the Mages Guild at Stonefalls' northeastern city of Davon's Watch, I spoke with the mage. "
        },
        stepTextKey = "Vanus arranged an enchanted boat to take me to where Marieve was last seen. I should find that boat near the docks.",
        appendText = {
            [ALLIANCE_ALDMERI_DOMINION] = ". It landed east of the Harbor Skiffs, just beyond the eastern wooden docks.",
            [ALLIANCE_DAGGERFALL_COVENANT] = ". It landed by the Lighthouse at the northern end of the city's western docks.",
            [ALLIANCE_EBONHEART_PACT] = ". It landed on the shore not far from the city's docks. It is east of The Fish Stink tavern and south of the ship \"Summerwind\" anchored at the eastern dock."
        }
    },

    ["Find the Oracle of the Wyrd"] = {
        appendStepText = {
            [ALLIANCE_ALDMERI_DOMINION] = "From Auridon's southern port city of Vulkhel Guard, I left the eastern dock area. ",
            [ALLIANCE_DAGGERFALL_COVENANT] = "From Glenumbra's southern city of Daggerfall, I left the shore by the Lighthouse at the north end of the city's western docks. ",
            [ALLIANCE_EBONHEART_PACT] = "From Stonefalls' northeastern port city of Davon's Watch, I left the shore east of the tavern, near the docks. "
        },
        stepTextKey = "Vanus's enchanted boat deposited me near where the Oracle dwells. The Oracle should be nearby. I should try to find her.",
        appendText = {
            [ALLIANCE_ALDMERI_DOMINION] = ". She should be a short distance to the west of where the enchanted boat beached on Bleakrock Isle's eastern, enclosed bay.",
            [ALLIANCE_DAGGERFALL_COVENANT] = ". She should be a short distance to the northwest of where the enchanted boat landed at the western edge of the island, northeast of Glenumbra's eastern port city of Aldcroft.",
            [ALLIANCE_EBONHEART_PACT] = ". She should be a short distance to the west of where the enchanted boat beached on the southern shore of Bangkorai's northeastern bay, far northeast of Evermore and a short distance west of Troll's Toothpick Wayshrine."
        }
    },
    ["Investigate the Oracle's Dwelling"] = {
        appendStepText = {
            [ALLIANCE_ALDMERI_DOMINION] = "West of Bleakrock Isle's eastern enclosed bay, ",
            [ALLIANCE_DAGGERFALL_COVENANT] = "On a hill west of the island northeast of Glenumbra's eastern port city of Aldcroft, ",
            [ALLIANCE_EBONHEART_PACT] = "On the southern shore of the bay, west of Bangkorai's northeastern Troll's Toothpick Wayshrine, "
        },
        stepTextKey = "Daedra swarm around the Oracle's dwelling. I should investigate and figure out what's going on here.",
        appendText = {
            [ALLIANCE_ALDMERI_DOMINION] = ".",
            [ALLIANCE_DAGGERFALL_COVENANT] = ".",
            [ALLIANCE_EBONHEART_PACT] = "."
        }
    },
    ["Talk to Wyress Aelynn"] = {
        appendStepText = {
            [ALLIANCE_ALDMERI_DOMINION] = "I sailed Vanus' enchanted boat from the eastern beach near the docks in Vulkhel Guard in Auridon and arrived at Bleakrock Isle. West of the northern point of the isle's eastern, enclosed bay where I beached the boat, I found the camp with hide-tarps sheltered by a snow-covered overhang. ",
            [ALLIANCE_DAGGERFALL_COVENANT] = "I sailed Vanus' enchanted boat from the beach by the Lighthouse north of the western docks of Daggerfall in Glenumbra and arrived northeast of the eastern port city of Aldcroft. On a rocky rise, west of where I landed the boat, I found a stone house. ",
            [ALLIANCE_EBONHEART_PACT] = "I sailed Vanus' enchanted boat from the eastern beach near the docks of Davon's Watch in Stonefalls and arrived in Bangkorai. West of the Troll's Toothpick Wayshrine, on the bay's southern shore where I landed the boat, I found a stone house. "
        },
        stepTextKey = "There's a wyress inside the dwelling, but she isn't the Oracle. I should talk to her.",
        appendText = {
            [ALLIANCE_ALDMERI_DOMINION] = " in the round, thatch-roofed dwelling.",
            [ALLIANCE_DAGGERFALL_COVENANT] = " near the campfire.",
            [ALLIANCE_EBONHEART_PACT] = " in the round, thatch-roofed dwelling."
        }
    },
    ["Go to the Mines of Khuras"] = {
        appendStepText = {
            [ALLIANCE_ALDMERI_DOMINION] = "After sailing from the beach east of the dock of Vulkhel Guard in Auridon, I found a campsite on Bleakrock Isle, west of the northern point of the isle's eastern, enclosed bay where I landed. ",
            [ALLIANCE_DAGGERFALL_COVENANT] = "After sailing from the beach by the Lighthouse north of the western docks of Daggerfall in Glenumbra, I arrived northeast of the eastern port city of Aldcroft. On a rocky rise west of where I landed, I found a thatched roof house. ",
            [ALLIANCE_EBONHEART_PACT] = "After sailing from the beach southeast of the docks of Davon's Watch in Stonefalls, I found a thatched roof house on the southern shore of Bangkorai's northeastern bay where I landed, west of the Troll's Toothpick Wayshrine. "
        },
        stepTextKey = "A wyress thinks that Marieve may have sought shelter in an old wyrd site inside the Mines of Khuras. I should use Vanus' enchanted boat to travel there.",
        appendText = {
            [ALLIANCE_ALDMERI_DOMINION] = " to look for Oracle Marieve.\n\nI should check the house for anything of interest before I go.",
            [ALLIANCE_DAGGERFALL_COVENANT] = " to look for Oracle Marieve.\n\nI should check the campsite for anything of interest before I go.",
            [ALLIANCE_EBONHEART_PACT] = " to look for Oracle Marieve.\n\nI should check the house for anything of interest before I go."
        }
    },
    ["Find Oracle Marieve in the Mines"] = {
	appendStepText="Using Vanus' enchanted boat, I arrived at the mines northeast of Ashcroft in Glenumbra. ",
	stepTextKey="Oracle Marieve sought shelter somewhere inside the Mines of Khuras, I need to find her.",
	appendText=". If she is hiding, the northwestern cavern with the large pool of water may have a secluded entrance to a secure place, probably at the water's edge on the eastern side.\n\nWhen I find her hideout, if she is not there, I should search for clues about where she may have gone."
    },
    ["Use Medallion of Summoning"] = {
	appendStepText="Northeast of Ashcroft in eastern Glenumbra, ",
	stepTextKey="I tracked Oracle Marieve to the old wyrd site inside the Mines of Khuras, but she isn't here. She left a cryptic note for Vanus. I should use the medallion of summoning he provided and call him here. Maybe he'll notice something I missed.",
	appendText=" inside the Old Wyrd Site in the northeastern area of the mines."
    },
    ["Talk to Vanus Galerion 2"] = {
	appendStepText="Northeast of Ashcroft in eastern Glenumbra, in the Old Wyrd Site in the northeast part of the Mines of Kharus, I used the medallion. ",
	stepTextKey="The medallion of summoning brought Vanus to my location. I should show him the Oracle's note and see what he thinks.",
	appendText=" in the Oracle's hideout."
    },
    ["Find the Elemental Items"] = {
	appendStepText="Northeast of Ashcroft in eastern Glenumbra, in the Old Wyrd Site in the northeast part of the Mines of Kharus, Vanus read the Oracle's note. ",
	stepTextKey="Vanus believes the Oracle left a secret message in this cave and the key to unlocking it requires finding elemental items with some connection to air, earth, and water.",
	appendText=" within the cavern."
    },
    ["Place the Elemental Items"] = {
	appendStepText="Northeast of Ashcroft in eastern Glenumbra, in the Old Wyrd Site in the northeast part of the Mines of Kharus, I found a gemstone, a feather, and a gourd of water. ",
	stepTextKey="I should place the items that represent the elements of air, water, and earth in the proper ritual bowls. Vanus believes that will reveal a message from Oracle Marieve.",
	appendText=" in their proper ritual bowls."
    },
    ["Talk to Oracle Marieve 1"] = {
	appendStepText="Northeast of Ashcroft in eastern Glenumbra, in the Old Wyrd Site in the northeast part of the Mines of Kharus, I followed the note's ritual. ",
	stepTextKey="When I placed the items in the correct ritual bowls, a projection of Oracle Marieve appeared. I should talk to her.",
	appendText="'s projection."
    },
    ["Go to Bewan"] = {
	appendStepText="Northeast of Ashcroft in eastern Glenumbra, in the Old Wyrd Site within the Mines of Kharus, the Oracle recognized me. ",
	stepTextKey="Oracle Marieve thinks she's being taken to an Aldmeri ruin in Auridon called Bewan. I should go to Bewan and attempt to rescue her.",
	appendText=", an Ayleid ruin on the west coast of Auridon, northwest of Skywatch.\n\nI should speak with Vanus before I sail there using the enchanted boat outside the mine."
    },
    ["Search for the Oracle in Bewan"] = {
	appendStepText="On the west coast of Auridon, northwest of Skywatch, I arrived to find that ",
	stepTextKey="Sea Elves overrun the ruins of Bewan. I need to get past them and find Oracle Marieve somewhere deeper within the ruins.",
	appendText=". She will likely be held captive far from the entrance, probably in the southernmost chamber."
    },
    ["Enter the Spiral Skein"] = {
	appendStepText="I reached the southern chamber of Bewan on Auridon's west coast, northwest of Skywatch. ",
	stepTextKey="They forced the Oracle through a portal. I should enter the portal and follow her.",
	appendText=" through the portal on the dais in the southernmost chamber of Bewan."
    },
    ["Find Oracle Marieve"] = {
	appendStepText="I entered the portal in the southern chamber of Bewan, the Ayleid ruin on Auridon's west coast, northwest of Skywatch. ",
	stepTextKey="I appear to be in Mephala's realm, the Spiral Skein. I need to look around and find Oracle Marieve.",
	appendText=" in the eastern cavern of the Skein."
    },
    ["Talk to Oracle Marieve 2"] = {
	appendStepText="I entered the portal in the southern chamber of Bewan, the Ayleid ruin on Auridon's west coast. In the Spiral Skein's eastern cavern, I found Marieve. ",
	stepTextKey="The Oracle appears trapped by some sort of Daedric magic and connected to the strange portal behind her. I should talk to her.",
	appendText="."
    },
    ["Break the South Binding Pinion"] = {
	appendStepText="Using the portal in the southern chamber of Bewan, the Ayleid ruin on Auridon's west coast, I arrived in Mephala's realm of The Spiral Skein. I spoke with the Oracle, bound in the eastern cavern. ",
	stepTextKey="I need to defeat the weavers, break the binding pinions, and destroy the center fulcrum to set the Oracle free.",
	appendText=".\n"
    },
    ["Break the North Binding Pinion"] = {
	appendStepText="Using the portal in the southern chamber of Bewan, the Ayleid ruin on Auridon's west coast, I arrived in Mephala's realm of The Spiral Skein. I spoke with the Oracle, bound in the eastern cavern. ",
	stepTextKey="I need to defeat the weavers, break the binding pinions, and destroy the center fulcrum to set the Oracle free.",
	appendText=".\n"
    },
    ["Destroy the Center Fulcrum"] = {
	appendStepText="Using the portal in the southern chamber of Bewan, the Ayleid ruin on Auridon's west coast, I arrived in Mephala's realm of The Spiral Skein. ",
	stepTextKey="Now that the binding pinions have been released, I need to destroy the center fulcrum to free the Oracle.",
	appendText=" that binds Marieve."
    },
    ["Leave the Spiral Skein"] = {
	appendStepText="In The Spiral Skein, Oracle ",
	stepTextKey="Marieve is free. She has enough energy to open a portal. We should leave Mephala's realm before the energy fades.",
	appendText=" through the portal the Oracle opened in the eastern cavern of the Skein. It will take me to Skywatch, Auridon's eastern port city."
    },
    ["Talk to Oracle Marieve in Skywatch"] = {
	appendStepText="I arrived in Skywatch in eastern Auridon. ",
	stepTextKey="I should talk to Oracle Marieve in Skywatch and make sure she's all right.",
	appendText="'s circular garden, at the bottom of the stairs west of the city's Mages Guild."
    },
    ["Talk to Vanus Galerion 3"] = {
	appendStepText="As I was speaking with the Oracle, Vanus joined us in the circular garden west of the Skywatch Mages Guild in Auridon. ",
	stepTextKey="I should talk to Vanus Galerion and let him know that the Oracle is safe now.",
	appendText="."
    },
    ["Talk to Vanus Galerion 4"] = {
	appendStepText="In Skywatch in eastern Auridon, ",
	stepTextKey="I should talk to Vanus Galerion and find out what happens to the Oracle now.",
	appendText=" at Skywatch's circular garden west of the Mages Guild."
    },
},

	[GetQuestName(6096)] = { --"The Queen's Decree" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Now that the Queen has decreed the island of the High Elves as open for trade and travel, I should go to Summerset. A boat leaves regularly from most major cities."},
		["Travel to Shimmerene in Summerset"] =
			{appendText=". Ciryelda, a female Altmer, provides passage on a ship sailing for the Alinor Docks, north of Alinor in Summerset. From there, I will need to travel the roads or use a wayshrine to reach the eastern city of Shimmerene.", stepTextKey="Now that the Queen has decreed the island of the High Elves as open for trade and travel, I should go to Summerset. A boat leaves regularly from most major cities."},
		[2] = 
			{appendStepText="On Summerset Isle, known as the Eternal Isle or Blessed Isle, I traveled to the eastern city of Shimmerene. ", stepTextKey="A High Elf told me that a Khajiit named Razum-dar is up ahead and might need some help. I should find him and talk to him."},
		["Talk to Razum-dar 1"] =
			{appendText=" on the road southwest of Shimmerene, Summerset's eastern port city.", stepTextKey="A High Elf told me that a Khajiit named Razum-dar is up ahead and might need some help. I should find him and talk to him."},
		[3] = 
			{appendStepText="I spoke with the red-crested Khajiit on the road southwest of Shimmerene, Summerset's eastern city. ", stepTextKey="Razum-dar asked me to talk to a few people from Shimmerene to gauge reactions to the Queen's decree to open Summerset to newcomers. He suggested I speak with Olnewil, Rhanul, and Tsoxolza."},
		["Talk to Olnewil"] =
			{appendText=". She should be south of the city, on the eastern beach collecting shells for her paints and dyes.\n"},
		["Talk to Rhanul"] =
			{appendText=", a respected Redguard trader. He should be at his dockside warehouse at the city's northern port.\n"},
		["Talk to Tsoxolza"] =
			{appendText=". The Argonian headed west out of town. He may be at the river, southwest of the bridge near the city's wayshrine."},
		[4] = 
			{appendStepText="Around Shimmerene, ", stepTextKey="I finished interviewing the people Razum-dar suggested. I should find him near the entrance to Shimmerene and let him know what I found out."},
		["Talk to Razum-dar 2"] =
			{appendText=" at Shimmerene's main gate, southeast of the wayshrine.", stepTextKey="I finished interviewing the people Razum-dar suggested. I should find him near the entrance to Shimmerene and let him know what I found out."},
		[5] = 
			{appendStepText="", stepTextKey="Razum-dar asked me to take a look around the Monastery of Serene Harmony in Shimmerene to determine what's happening with the sequestered newcomers. I just need to wait for Raz to distract the sentry before I can slip inside."},
		["Enter the Monastery of Serene Harmony"] =
			{appendText=". It is the beautiful edifice at the top of the curving road in northeast Shimmerene."},
		[6] = 
			{appendStepText="At the top of the curved road in northeast Shimmerene, Razum-dar distracted a guard. ", stepTextKey="Now that I'm inside the monastery, I should look around and try to find out what's happened to the newcomers and other non-High Elves that have been sequestered."},
		["Investigate the Monastery"] =
			{appendText=" of Serene Harmony. I should look for papers and speak with a Monastic on the main floor. Then I can investigate the upper rooms."},
		[7] = 
			{appendStepText="In northeast Shimmerene, in an upstairs room of the Monastery of Serene Harmony, I found a strange sphere. Then ", stepTextKey="I encountered a High Elf who clearly isn't one of the Aldarch's monks. I should talk to her and find out what she's doing in the monastery."},
		["Talk to Valsirenn 1"] =
			{appendText=".", stepTextKey="I encountered a High Elf who clearly isn't one of the Aldarch's monks. I should talk to her and find out what she's doing in the monastery."},
		[8] = 
			{appendStepText="At the Monastery of Serene Harmony in Shimmerene, ", stepTextKey="Valsirenn claims she's trying to find a friend who might have been caught up in the sequestering. She feels there's more going on than simple politics and suggested we explore the monastery undercroft together."},
		["Investigate the Undercroft"] =
			{appendText=" of the monastery. I should use the southeastern stairs to get down below the main floor."},
		[9] = 
			{appendStepText="The monastery in northeast Shimmerene has an undercroft that is not what is should be. ", stepTextKey="There's a prisoner in a cage down here. I should talk to her and set her free."},
		["Free the Prisoner"] =
			{appendText=", Minone Aloette. She is in the first cage at the bottom of the stairs after entering the undercroft."},
		[10] = 
			{appendStepText="In the undercroft of the monastery in northeast Shimmerene, ", stepTextKey="I set the newcomer free. Now I should talk to Valsirenn before we move deeper into the undercroft."},
		["Talk to Valsirenn 2"] =
			{appendText=" at the southern end of the first chamber.", stepTextKey="I set the newcomer free. Now I should talk to Valsirenn before we move deeper into the undercroft."},
		[11] = 
			{appendStepText="At the monastery in northeast Shimmerene, ", stepTextKey="I should follow Valsirenn deeper into the undercroft so we can locate the rest of the newcomers that are imprisoned here."},
		["Find the Missing Prisoners"] =
			{appendText=" in the large Great Hall, west of the first chamber I entered."},
		[12] = 
			{appendStepText="In northeast Shimmerene, we entered the Great Hall of the Monastery's Undercroft. ", stepTextKey="A Daedric cultist channeled magicka through a pearl similar to the one we saw in the office. It drained the life from the captured newcomers. Now the pearl seems to be summoning yaghra. I need to protect Valsirenn while she deals with the pearl."},
		["Defend Valsirenn"] =
			{appendText=" in the south-central Great Hall."},
		[13] = 
			{appendStepText="In northeast Shimmerene, in the undercroft of the Monastery of Serene Harmony, ", stepTextKey="Valsirenn cast some sort of spell and the pearl disappeared. I should exit the great hall and talk to her."},
		["Talk to Valsirenn 3"] =
			{appendText=". She exited the Great Hall in the Monastery Undercroft through its western doors.", stepTextKey="Valsirenn cast some sort of spell and the pearl disappeared. I should exit the great hall and talk to her."},
		[14] = 
			{appendStepText="In the undercroft of the Monastery of Serene Harmony in northeast Shimmerene, ", stepTextKey="Valsirenn revealed that she's a mage of the Psijic Order, sent to investigate a threat to Summerset. We were too late to save the newcomers, but we did stop the yaghra and transport the pearl to Artaeum for safekeeping. Now to leave this place."},
		["Escape the Undercroft"] =
			{appendText=" through the halls and chambers west and north."},
		[15] = 
			{appendStepText="I exited the Undercroft Labyrinth and found myself in a hedge maze behind the inn on the south side of Shimmerene's large port. ", stepTextKey="Valsirenn suggested I find Razum-dar at the local inn and let him know what we discovered beneath the Monastery of Serene Harmony."},
		["Talk to Razum-dar, 3"] =
			{appendText=" in an upstairs room at the Anchors Aweigh Inn in Shimmerene.", stepTextKey="Valsirenn suggested I find Razum-dar at the local inn and let him know what we discovered beneath the Monastery of Serene Harmony."},
		[16] = 
			{appendStepText="At Shimmerene's Anchors Aweigh Inn, ", stepTextKey="Razum-dar asked me to attend a meeting at Kinlady Avinisse's mansion. He wants me to speak to her to determine what she knows about the happenings in the monastery. He provided me with an invitation and set of elegant clothes to get me inside."},
		["Attend the Kinlady's Meeting"] =
			{appendText=" at her mansion in the eastern city, partway up the curved road that leads to the monastery.\n\nOnce inside, I should put on the elegant clothing, then go to the room to the right of the staircase and present myself. At the gathering in the garden, I should speak with those attending."},
		[17] = 
			{appendStepText="At her mansion on the curved road in eastern Shimmerene, I was attending her gathering, when ", stepTextKey="Kinlady Avinisse left her guests and went into her mansion. I should head inside and speak to her."},
		["Talk to Kinlady Avinisse"] =
			{appendText=" inside her home. She is likely upstairs in a private area. Before I speak with her, the Aldarch is here in the garden. I should talk to him."},
		[18] = 
			{appendStepText="In her mansion in eastern Shimmerene, ", stepTextKey="Kinlady Avinisse seemed genuinely surprised to hear that the newcomers were being killed beneath the monastery. I should report to Razum-dar outside the mansion and let him know what I learned here."},
		["Talk to Razum-dar 4"] =
			{appendText=". The Eye of the Queen waits near the bridge at the bottom of Shimmerene's eastern, curved road.", stepTextKey="Kinlady Avinisse seemed genuinely surprised to hear that the newcomers were being killed beneath the monastery. I should report to Razum-dar outside the mansion and let him know what I learned here."},
		[19] = 
			{appendStepText="In Shimmerene, ", stepTextKey="Razum-dar and Valsirenn agreed to work together to discover what the Aldarch is up to. We learned that he's meeting the Kinlady south of the city, in the Coral Forest. I should go and meet Valsirenn there."},
		["Meet Valsirenn at the Coral Forest"] =
			{appendText=", south of Shimmerene on the coast and east of where the road first forks. It is named for its exquisite coral formations accented by crystal-blue pools of water."},
		[20] = 
			{appendStepText="South of Shimmerene on the eastern coast, near where the road first forks, ", stepTextKey="I met Valsirenn outside the Coral Forest, but there's no sign of Razum-dar as of yet. We should enter the Coral Forest and start searching for the Kinlady and the Aldarch."},
		["Search the Coral Forest"] =
			{appendText=" for the Aldarch and Kinlady. With all the strange creatures and Daedra I've encountered to this point, I should be prepared."},
		[21] = 
			{appendStepText="Far south of Shimmerene and northeast of the Sil-Var-Woad Wayshrine, in the eastern coast's Coral Forest, we spotted the Aldarch. ", stepTextKey="We saw Aldarch Tilcalar threaten the Kinlady before she fled. Valsirenn pursued the Kinlady. I should go after the Aldarch."},
		["Confront Aldarch Tilcalar"] =
			{appendText=" at a pool circled by tall coral formations. Another large pearl floats above the water."},
		[22] = 
			{appendStepText="Far south of Shimmerene and northeast of the Sil-Var-Woad Wayshrine, in the eastern coast's Coral Forest, ", stepTextKey="I defeated Aldarch Tilcalar, but the abyssal pearl continues to call forth the strange sea creatures called yaghra. I need to destroy that pearl."},
		["Destroy the Abyssal Pearl"] =
			{appendText=" in the pool circled by tall coral formations."},
		[23] = 
			{appendStepText="At a pool in the Coral Forest, far south of Shimmerene and northeast of the Sil-Var-Woad Wayshrine, I stopped the Aldarch's ritual. ", stepTextKey="Now that I dealt with the Aldarch and the abyssal pearl, I should locate Valsirenn and the Kinlady."},
		["Talk to Valsirenn 4"] =
			{appendText=". She should be among the coral formations inland from the pool, towards the Sil-Var-Woad Wayshrine.", stepTextKey="Now that I dealt with the Aldarch and the abyssal pearl, I should locate Valsirenn and the Kinlady."},
		[24] = 
			{appendStepText="On the eastern coast, northeast of the Sil-Var-Woad Wayshrine, I spoke with the Psijic mage Valsirenn in the Coral Forest. Before she left, she attuned me to Artaeum so that I could travel there. ", stepTextKey="Now I need to find Razum-dar, let him know what happened in the Coral Forest and see what he plans to do with Kinlady Avinisse."},
		["Talk to Razum-dar 5"] =
			{appendText=". He is near the edge of the Coral Forest, a short distance north of the Sil-Var-Woad Wayshrine in southeast Summerset.", stepTextKey="Now I need to find Razum-dar, let him know what happened in the Coral Forest and see what he plans to do with Kinlady Avinisse."},
		[25] = 
			{appendStepText="", stepTextKey="Valsirenn invited me to come to Artaeum and help her explain events in Shimmerene to the Psijic Order's Ritemaster. She attuned me to a portal that will transport me to the hidden island. I should use the portal at the first opportunity."},
		["Travel to Artaeum"] =
			{appendText=". Its portal is at the Keep of the Eleven Forces, an ancient Altmer ruin bridging the southern portion of the looping road southwest of Shimmerene.\n\nBefore I leave the Coral Forest to go to Artaeum, I should speak with Kinlady Avinisse."},
		[26] = 
			{appendStepText="From the portal at Summerset's Keep of the Eleven Forces, ", stepTextKey="I arrived on Artaeum and there's a tower in the distance. That's probably where I'll find Valsirenn and the Ritemaster."},
		["Talk to Ritemaster Iachesis 1"] =
			{appendText=" at the northern end of the island.", stepTextKey="I arrived on Artaeum and there's a tower in the distance. That's probably where I'll find Valsirenn and the Ritemaster."},
		[27] = 
			{appendStepText="At Ceporah Tower on Artaeum, ", stepTextKey="I should talk to the Ritemaster and see what I can do to help."},
		["Talk to Ritemaster Iachesis 2"] =
			{appendText=".", stepTextKey="I should talk to the Ritemaster and see what I can do to help."},
	},

[GetQuestName(6112)] = { --"A Pearl of Great Price" --Jordakai
		[1] = 
			{appendStepText="Iradal, a member of the Psijic Order, found me. ", stepTextKey="The Ritemaster has requested my assistance at Ceporah Tower on the island of Artaeum. I should go and see what he wants."},
		["Talk to the Ritemaster 1"] =
			{appendText=" at Ceporah Tower on northern Artaeum.\n\nI can use the portal in the Keep of the Eleven Forces, the ancient ruin southwest of Shimmerene, or I can travel via wayshrine.", stepTextKey="The Ritemaster has requested my assistance at Ceporah Tower on the island of Artaeum. I should go and see what he wants."},
		[2] = 
			{appendStepText="On Artaeum, I found Iachesis at Ceporah Tower. ", stepTextKey="The Ritemaster asked me to go to Sotha Sil's study and find his acolyte, Oriandra. I need to ask her for the amplification elixir to increase the power of the Order's augury ritual cast on the pearl."},
		["Talk to Oriandra"] =
			{appendText=". I should use the western turquoise portal on the tower's main gallery floor to enter the study."},
		[3] = 
			{appendStepText="In Ceporah Tower on Artaeum, I talked with the Ritemaster's acolyte. ", stepTextKey="Oriandra says the amplification elixir the Ritemaster sent me to get is in Sotha Sil's study. I should locate it so I can bring it to the Ritemaster."},
		["Collect Amplification Elixir"] =
			{appendText=" in the shiny bottle on the table. The table is left of the Clockwork dais and its wall device, artifacts, and books."},
		[4] = 
			{appendStepText="In Ceporah Tower on Artaeum, ", stepTextKey="I retrieved the amplification elixir from Sotha Sil's study. Now I need to bring the elixir to the Ritemaster."},
		["Talk to the Ritemaster 2"] =
			{appendText=" at the ritual pool in the tower's main gallery.", stepTextKey="I retrieved the amplification elixir from Sotha Sil's study. Now I need to bring the elixir to the Ritemaster."},
		[5] = 
			{appendStepText="In the main gallery of Ceporah Tower on Artaeum, Iachesis asked me to help. ", stepTextKey="The Ritemaster asked me to pour the elixir into the scrying pool to amplify the augury ritual's power."},
		["Use the Amplification Elixir"] =
			{appendText=" by pouring it into the scrying pool containing the pearl."},
		[6] = 
			{appendStepText="In the main gallery of the Ceporah Tower on Artaeum, I poured the elixir into the scrying pool. ", stepTextKey="The augury ritual revealed the false Aldarch meeting with two other members of a Daedric cult that calls itself the Court of Bedlam. They mentioned plans for Rellenthil, a town in Summerset. I should discuss what we saw with the Ritemaster."},
		["Talk to the Ritemaster 3"] =
			{appendText=" at the pool's edge.", stepTextKey="The augury ritual revealed the false Aldarch meeting with two other members of a Daedric cult that calls itself the Court of Bedlam. They mentioned plans for Rellenthil, a town in Summerset. I should discuss what we saw with the Ritemaster."},
		[7] = 
			{appendStepText="In Ceporah Tower on Artaeum, I learned there is a Daedric cult called the Court of Bedlam. The cultists worship Clavicus Vile, Mephala, or Nocturnal. ", stepTextKey="The Ritemaster suggested that Valsirenn and I travel to the town of Rellenthil in Summerset and talk to the Canonreeve. If anything unusual is going on there, the Canonreeve should be able to tell us about it."},
		["Travel to Rellenthil"] =
			{appendText=". Near the mountains, the small city is on the road far west of the eastern city of Shimmerene, northeast of the western city of Alinor, and a short distance east of the Alinor Docks.\n\nI may wish to speak with Valsirenn before I go to Summerset."},
		[8] = 
			{appendStepText="", stepTextKey="As I arrived in Rellenthil, Razum-dar appeared and ran toward me. He obviously wants to talk to me."},
		["Talk to Razum-dar 1"] =
			{appendText=". The Khajiiti Eye of the Queen is on the bridge in Rellenthil.", stepTextKey="As I arrived in Rellenthil, Razum-dar appeared and ran toward me. He obviously wants to talk to me."},
		[9] = 
			{appendStepText="I met Razum-dar. He mentioned seeing Valsirenn. Now, ", stepTextKey="I should talk to Canonreeve Farmeldo and find out what's been happening here in Rellenthil."},
		["Talk to Canonreeve Farmeldo 1"] =
			{appendText=" at his house just southwest of Rellenthil's bridge over the river.", stepTextKey="I should talk to Canonreeve Farmeldo and find out what's been happening here in Rellenthil."},
		[10] = 
			{appendStepText="", stepTextKey="The Canonreeve said a large sinkhole opened near the city. He suggested that his son Nedoril has gotten involved with a group of young High Elves who have been meeting near the sinkhole for some reason. I should enter the sinkhole and investigate."},
		["Enter the Rellenthil Sinkhole"] =
			{appendText=" with Valsirenn. The sinkhole is northeast of Rellenthil, just southwest of a wayshrine."},
		[11] = 
			{appendStepText="Northeast of the west-central city of Rellenthil, we found a cavern entrance. ", stepTextKey="Now that we're inside the sinkhole, I should consult with Valsirenn about what we should do next."},
		["Talk to Valsirenn 1"] =
			{appendText=", the Psijic sage, a short distance into the cavern.", stepTextKey="Now that we're inside the sinkhole, I should consult with Valsirenn about what we should do next."},
		[12] = 
			{appendStepText="Northeast of Rellenthil, we entered the sinkhole. ", stepTextKey="The sinkhole opens into a network of underground caverns. I should explore them and see what I can find."},
		["Explore the Sinkhole Caverns"] =
			{appendText=" with Valsirenn. We should work our way to near the center of the caverns. There may be an overlook I can use to see the north-central pool area. Then I should find a way to reach that pool."},
		[13] = 
			{appendStepText="Northeast of Rellenthil in the Rellenthil Sinkhole, Valsirenn teleported away and will meet me deeper into the caverns.\n\n", stepTextKey="While exploring the network of caverns and passages in the sinkhole near Rellenthil, I heard someone call for help. I should talk to him."},
		["Talk to Eldhon"] =
			{appendText=", sitting near the southern pool."},
		[14] = 
			{appendStepText="In the Rellenthil Sinkhole northeast of the city, I spoke briefly with Eldhon before he succumbed to his wounds. ", stepTextKey="Nedoril has apparently joined the Court of Bedlam and killed one of his friends for disparaging the cult's crazy plans. I should continue exploring the caverns and attempt to find Nedoril."},
		["Continue Exploring the Sinkhole Caverns 1"] =
			{appendText=". I should see what I can find in the southeastern passages. I should watch for Valsirenn, too.", stepTextKey="Nedoril has apparently joined the Court of Bedlam and killed one of his friends for disparaging the cult's crazy plans. I should continue exploring the caverns and attempt to find Nedoril."},
		[15] = 
			{appendStepText="Northeast of Rellenthil, in the Sinkhole caverns' southeastern passageway, ", stepTextKey="Valsirenn appeared just ahead of me. She wants me to see something across the large cavern. I should talk to her."},
		["Talk to Valsirenn 2"] =
			{appendText=". She is near an overlook at the southeastern edge of the central pool.", stepTextKey="Valsirenn appeared just ahead of me. She wants me to see something across the large cavern. I should talk to her."},
		[16] = 
			{appendStepText="Northeast of Rellenthil, in the Sinkhole caverns, we witnessed the young Altmer, Nedoril, being instructed by K'Tora of the Abyssal Cabal. ", stepTextKey="While Valsirenn attempts to reach the Sea Sload, I need to destroy the abyssal pearls before they attract more of those yaghra creatures."},
		["Destroy Abyssal Pearls"] =
			{appendText=" down in the central pool."},
		[17] = 
			{appendStepText="Northeast of Rellenthil, in the Sinkhole caverns, we went down to the central pool. ", stepTextKey="We destroyed the abyssal pearls, but the Sea Sload and its hooded companion got away. I should talk to Valsirenn."},
		["Continue Exploring the Sinkhole Caverns 2"] =
			{appendText=". Now I should go up into the northern passage of the caverns. If I see Valsirenn, I should follow her. She may have something to say to me. Then we can continue towards the northern pool.", stepTextKey="We destroyed the abyssal pearls, but the Sea Sload and its hooded companion got away. I should talk to Valsirenn."},
		[18] = 
			{appendStepText="", stepTextKey="The Sea Sload left a terrible yaghra monster behind. I need to deal with the creature before it brings the entire sinkhole down on top of us."},
		["Destroy the Yaghra Monstrosity"] =
			{appendText=" in the northern pool."},
		[19] = 
			{appendStepText="In the Sinkhole caverns northeast of Rellenthil, I defeated a creature that K'Tora the Sea Sload left in the northern pool. ", stepTextKey="Valsirenn found a way for us to exit the sinkhole. I should take advantage of it and get out of here."},
		["Exit the Sinkhole"] =
			{appendText=" through the small passage to the north."},
		[20] = 
			{appendStepText="We left the Sinkhole Caverns to reach the surface, north of the road and northwest of the Russafeld Wayshrine. ", stepTextKey="Once outside, we ran into Razum-dar. I should talk to Razum-dar and let him know what happened in the sinkhole."},
		["Talk to Razum-dar 2"] =
			{appendText=" at the northern edge of the sinkhole.", stepTextKey="Once outside, we ran into Razum-dar. I should talk to Razum-dar and let him know what happened in the sinkhole."},
		[21] = 
			{appendStepText="", stepTextKey="Razum-dar asked me to meet him at the Canonreeve's house. He plans to deal with the Canonreeve's traitorous son, Nedoril. I should report to the Canonreeve and inform him about what we found out."},
		["Talk to Canonreeve Farmeldo 2"] =
			{appendText=". His house is just southwest of the bridge in Rellenthil.", stepTextKey="Razum-dar asked me to meet him at the Canonreeve's house. He plans to deal with the Canonreeve's traitorous son, Nedoril. I should report to the Canonreeve and inform him about what we found out."},
		[22] = 
			{appendStepText="In the Canonreeve's House in Rellenthil, ", stepTextKey="Razum-dar served the Queen's justice and executed the traitor Nedoril. I should speak to him about this."},
		["Talk to Razum-dar 3"] =
			{appendText=".", stepTextKey="Razum-dar served the Queen's justice and executed the traitor Nedoril. I should speak to him about this."},
		[23] = 
			{appendStepText="", stepTextKey="I should go back to Artaeum and speak to the Ritemaster about what Valsirenn and I found in Rellenthil."},
		["Talk to the Ritemaster on Artaeum"] =
			{appendText=". He should be in his study at Ceporah Tower. I can reach the Ritemaster's Study through the southeastern turquoise portal in the tower's main gallery."},
		[24] = 
			{appendStepText="On Artaeum in the Ceporah Tower, ", stepTextKey="I should talk to the Ritemaster about the Sea Sloads and the Daedric Princes."},
		["Talk to Ritemaster Iachesis"] =
			{appendText=" in his study. I should use the southeastern turquoise portal in the tower's main gallery."},
	},

	[GetQuestName(6132)] = { --"Buried Memories" --Jordakai
		[1] = 
			{appendStepText="The Ritemaster's acolyte, Oriandra, had a message for me. ", stepTextKey="I need to meet the Ritemaster in Ceporah Tower's main gallery and talk to him there."},
		["Talk to Ritemaster Iachesis 1"] =
			{appendText=" on Artaeum. I can use the portal at the ancient ruin of the Keep of the Eleven Forces southwest of Shimmerene, or travel via wayshrine.", stepTextKey="I need to meet the Ritemaster in Ceporah Tower's main gallery and talk to him there."},
		[2] = 
			{appendStepText="I am on Artaeum. ", stepTextKey="The Ritemaster headed for the southeast beach to deal with the yaghra incursion. I should meet him in that location."},
		["Go to the Southeast Beach"] =
			{appendText=". To reach the beach, I should follow the Ritemaster through the College of Psijics ruin. The College is part of the massive structure built into the island's mountains, south of Ceporah Tower. From the tower, I can follow the road past the merchant and then where the road splits, continue up the southbound road to the Vault's entrance. Once inside, go down the stairs from the entrance, south and up another set of stairs, then out of the first southern exit."},
		[3] = 
			{appendStepText="On Artaeum, ", stepTextKey="I followed the Ritemaster through the ruins of the College of Psijics and onto the southeastern shore of the island. I should talk to the Ritemaster before we proceed."},
		["Talk to the Ritemaster 1"] =
			{appendText=" on the patio above Artaeum Beach, just outside of the first southern exit from the College's halls.", stepTextKey="I followed the Ritemaster through the ruins of the College of Psijics and onto the southeastern shore of the island. I should talk to the Ritemaster before we proceed."},
		[4] = 
			{appendStepText="I followed the Ritemaster through the halls of the College of Psijics ruin in Artaeum's central mountain to reach the beach. ", stepTextKey="I need to destroy the abyssal pearl to close the portal that gives the yaghra access to Artaeum."},
		["Destroy the Abyssal Pearl"] =
			{appendText=" down at the water's edge on the beach."},
		[5] = 
			{appendStepText="After going through the halls of the College of Psijics ruin in the central mountain of Artaeum, I exited through a southern door and then destroyed the Abyssal Pearl down on the beach. ", stepTextKey="Now that the yaghra portal has been destroyed, I should accompany the Ritemaster to the old vaults to make sure the Psijic relics are secure."},
		["Enter the Vaults"] =
			{appendText=" of Psijic relics at the southern end of the southermost road on the island. There should be a path leading up from the beach."},
		[6] = 
			{appendStepText="At the southern end of Artaeum's southermost road, from the beach ", stepTextKey="I entered the Psijic relic vaults. I should talk to the Ritemaster and determine what he thinks we need to do in here."},
		["Talk to the Ritemaster 2"] =
			{appendText=", just inside the southern entrance of the vaults.", stepTextKey="I entered the Psijic relic vaults. I should talk to the Ritemaster and determine what he thinks we need to do in here."},
		[7] = 
			{appendStepText="I entered the Psijic Relic Vaults on Artaeum. ", stepTextKey="The Ritemaster suggested that we start our search of the vaults in the central rotunda at the top of the stairs. I should follow him."},
		["Go to the Central Rotunda"] =
			{appendText=", up the stairs, north of the southern entrance."},
		[8] = 
			{appendStepText="In the Psijic Relic Vaults of Artaeum, ", stepTextKey="Mephala's Daedra stand guard at the entrance to the central rotunda, and some sort of webbed barrier has sealed the door. I need to defeat the Daedra before we can proceed."},
		["Defeat Mephala's Daedra"] =
			{appendText="."},
		[9] = 
			{appendStepText="In the Psijic Relic Vaults of Artaeum, I defeated Mephala's Daedra. ", stepTextKey="The Ritemaster suggested I try to burn the barrier of webbing so we can enter the central rotunda."},
		["Burn Mephala's Barrier"] =
			{appendText=" at the Central Rotunda's door."},
		[10] = 
			{appendStepText="In the Psijic Relic Vaults of Artaeum, the Central Rotunda's door was blocked, ", stepTextKey="The barrier of webbing wouldn't burn, but the Golden Knight appeared again and opened the way with his glowing sword before vanishing. I should enter the central rotunda now."},
		["Enter the Central Rotunda"] =
			{appendText="."},
		[11] = 
			{appendStepText="", stepTextKey="The Ritemaster moved to confront the Sea Sload, K'Tora. I should wait and see what happens."},
		["Let the Ritemaster Confront the Sea Sload"] =
			{appendText=" in the central rotunda of the Psijics Relic Vaults."},
		[12] = 
			{appendStepText="In the central rotunda of the Psijic Relic Vaults, K'Tora the Sea Sload has the Ritemaster spellbound. ", stepTextKey="Valsirenn has called to me from outside the central rotunda. I should go and talk to her so we can figure out how to help the Ritemaster."},
		["Talk to Valsirenn 1"] =
			{appendText=" in the southern chamber.", stepTextKey="Valsirenn has called to me from outside the central rotunda. I should go and talk to her so we can figure out how to help the Ritemaster."},
		[13] = 
			{appendStepText="In the Psijic Relic Vaults, ", stepTextKey="Valsirenn sent me in search of one of the relics in the vault, the Ul'vor Staff. She said she can use it to free the Ritemaster from K'Tora's mind magic. I can use the wardkey she provided to open the various repositories as I search."},
		["Find the Ul'vor Staff"] =
			{appendText=". I should start by searching the western wing of the vaults. There are storage chambers to the northwest, north, and northeast. The staff is likely in a tall cabinet or display. The Wardkey Valsirenn gave me will remove the relic repository's shimmering ward. Then I can retrieve the staff."},
		[14] = 
			{appendStepText="In the northeastern chamber of the Psijic Relic Vaults, ", stepTextKey="I found the Ul'vor Staff. Now to take it to Valsirenn and see if it can help us free the Ritemaster."},
		["Talk to Valsirenn 2"] =
			{appendText=" in the central rotunda. I should return through the western wing of the vaults.", stepTextKey="I found the Ul'vor Staff. Now to take it to Valsirenn and see if it can help us free the Ritemaster."},
		[15] = 
			{appendStepText="In the central rotunda of the Psijic Relic Vaults, ", stepTextKey="Valsirenn has opened a path to the mindscape with the Ul'vor Staff. I need to touch it so I can enter the mindscape and save the Ritemaster."},
		["Enter the Mindscape"] =
			{appendText="."},
		[16] = 
			{appendStepText="From the central rotunda of the Psijic Relic Vaults on Artaeum, I entered a mindscape that Valsirenn opened for me using the Staff of Ul'vor. ", stepTextKey="Valsirenn says I need to defeat K'Tora's guardian to reveal the memory it's defending. Only then can I continue to search for the Ritemaster in this alien mindscape."},
		["Reveal the First Memory"] =
			{appendText=" along the path."},
		[17] = 
			{appendStepText="From the central rotunda of the Psijic Relic Vaults on Artaeum, I entered a mindscape that Valsirenn opened for me using the Staff of Ul'vor. I've witnessed one memory. ", stepTextKey="Another guardian and another memory to uncover. I need to defeat the guardian before I can find the Ritemaster."},
		["Reveal the Second Memory"] =
			{appendText=" along the path."},
		[18] = 
			{appendStepText="From the central rotunda of the Psijic Relic Vaults on Artaeum, I entered a mindscape that Valsirenn opened for me using the Staff of Ul'vor. I've seen two memories. ", stepTextKey="One last memory guardian to vanquish and then I should be able to reach the Ritemaster and K'Tora."},
		["Reveal the Third Memory"] =
			{appendText="."},
		[19] = 
			{appendStepText="From the central rotunda of the Psijic Relic Vaults on Artaeum, I entered a mindscape that Valsirenn opened for me using the Staff of Ul'vor. ", stepTextKey="I revealed K'Tora's memories and saw how the cabal made a deal with the Daedric Princes, defeated the Ritemaster, altered his memories, and forced him to take the Heart of Transparent Law and hide it. I need to defeat K'Tora and free the Ritemaster."},
		["Defeat K'Tora"] =
			{appendText=" at the end of the path."},
		[20] = 
			{appendStepText="From the central rotunda of the Psijic Relic Vaults on Artaeum, I entered a mindscape that Valsirenn opened for me using the Staff of Ul'vor. At the end of the spiral path, ", stepTextKey="I freed the Ritemaster and defeated K'Tora. I need to use the Ul'vor Staff to exit this mindscape before it completely fades away and I'm trapped inside forever."},
		["Use the Staff to Exit the Mindscape"] =
			{appendText="."},
		[21] = 
			{appendStepText="After touching the Staff of Ul'vor, ", stepTextKey="I emerged from the mindscape to find Sotha Sil standing before me. I should speak to him."},
		["Talk to Sotha Sil"] =
			{appendText=" in the central rotundra of the Psijic Relic Vaults."},
		[22] = 
			{appendStepText="I shared what I learned with Sotha Sil in the central rotunda of the Psijic Relic Vaults. ", stepTextKey="I need to leave these vaults and return to Ceporah Tower so I can see how the Ritemaster is faring after his ordeal in the mindscape."},
		["Exit the Vaults"] =
			{appendText=". I should leave the central rotunda, enter the Eastern Wing and take the stairs to the north through the Cargo Entrance. Then into the Upper Ruin of the College of Psijics to leave through its northern doors."},
		[23] = 
			{appendStepText="On Artaeum, ", stepTextKey="I need to return to Ceporah Tower and see how the Ritemaster is faring after his ordeal in the mindscape."},
		["Talk to Ritemaster Iachesis 2"] =
			{appendText=". I should use the southeastern turquoise portal off the tower's main gallery to reach his study.", stepTextKey="I need to return to Ceporah Tower and see how the Ritemaster is faring after his ordeal in the mindscape."},
		[24] = 
			{appendStepText="", stepTextKey="K'Tora forced the Ritemaster to steal the Heart of Transparent Law from the Crystal Tower, but he doesn't remember where he hid it. I should talk to him and see what I can do to help restore his memory."},
		["Talk to Ritemaster Iachesis 3"] =
			{appendText=" in his study at Ceporah Tower on Artaeum. I should use the tower's southeeastern turquoise portal to visit him.", stepTextKey="K'Tora forced the Ritemaster to steal the Heart of Transparent Law from the Crystal Tower, but he doesn't remember where he hid it. I should talk to him and see what I can do to help restore his memory."},
	},

	[GetQuestName(6142)] = { --"The Tower Sentinels" --Jordakai
		[1] = 
			{appendStepText="I continue to work with the Psijic Order of Artaeum. ", stepTextKey="I need to travel to the Royal Palace in Alinor so I can secure permission from Proxy Queen Alwinarwe that will grant me access to the College of Sapiarchs in Lillandril."},
		["Go to Alinor's Royal Palace"] =
			{appendText=" in the city's northeast. It towers above the splendor of Altmeri architecture in the western city of Alinor, the capital of the Summerset Isles."},
		[2] = 
			{appendStepText="High up in the city's northeast, ", stepTextKey="I reached the Royal Palace in Alinor. Now I need to speak to Proxy Queen Alwinarwe and gain access to the College of Sapiarchs in Lillandril."},
		["Talk to Proxy Queen Alwinarwe"] =
			{appendText=" on the dais in the throne room of the palace."},
		[3] = 
			{appendStepText="At the Alinor Royal Palace in the city's northeast, I spoke with Queen Ayrenn's cousin, Alwinarwe. ", stepTextKey="The Proxy Queen said she would send word to the Sapiarch portal master so that I could enter the College of Sapiarchs and warn their leader, Larnatille. I can find the portal master in Lillandril."},
		["Talk to the Portal Master in Lillandril"] =
			{appendText=", up in the city's western plaza. Lillandril is the western coastal city near the island where the Sapiarchs study. The city is across the bay and some distance northwest of Alinor Docks.\n\nIf I see Valsirenn near the Sapiarch's portal, I should speak with her."},
		[4] = 
			{appendStepText="In the western coastal city of Lillandril, I spoke with the portal master at the large portal up in the city's western plaza. Now, ", stepTextKey="The portal master has activated the portal dais to transport me to the College of Sapiarchs. I should use the portal dais to reach the college compound."},
		["Use the Portal Dais"] =
			{appendText="."},
		[5] = 
			{appendStepText="I used the portal in the western coastal city of Lillandril to reach the Sapiarchs' island. ", stepTextKey="Something's happening in the College of Sapiarchs. I should talk to Sapiarch Ellimil and find out what's going on here."},
		["Talk to Sapiarch Ellimil"] =
			{appendText=". He is near where I entered the College grounds through the portal."},
		[6] = 
			{appendStepText="After arriving via the portal at the western plaza of Lillandril, we learned that Daedra were attacking the college. ", stepTextKey="Sapiarch Ellimil explained that the head of the College of Sapiarchs is trapped inside with the Daedra. He suggested I use the lower halls of the Labyrinth to enter the college compound."},
		["Enter the Sapiarchs' Labyrinth"] =
			{appendText=". I should leave the portal area, head down the stairs to the south, go to the right past the fountain, then up to the north. At the end of a short path I should see the illuminated doors."},
		[7] = 
			{appendStepText="I arrived at the College of Sapiarchs using a portal in the western plaza of Lillandril. Then I went south, down the stairs and to the right, past a fountain and up a short path to illuminated doors. ", stepTextKey="Now that we're in the Sapiarchs' Labyrinth, I should confer with Valsirenn about our next move."},
		["Talk to Valsirenn 1"] =
			{appendText=", just inside the labyrinth's southeastern entrance.", stepTextKey="Now that we're in the Sapiarchs' Labyrinth, I should confer with Valsirenn about our next move."},
		[8] = 
			{appendStepText="From the portal in the western plaza of the western coastal city of Lillandril, I went to the College of Sapiarchs. Then I went south, down the stairs, to the right past a fountain, and up a short path to illuminated doors. Now inside, ", stepTextKey="I need to navigate the Labyrinth's lower halls to reach the upper levels of the College of Sapiarchs."},
		["Navigate the Labyrinth"] =
			{appendText=", through the halls and rooms until I reach the southwestern hallway. Then upstairs and around through the next level of the college to reach the southeastern octagonal room. And then through its eastern doors."},
		[9] = 
			{appendStepText="I arrived at the College of Sapiarchs through a portal from Lillandril's western plaza. Then I went down the stairs, past a fountain and up a short path to illuminated doors. In the labyrinth's lower level, I went to the southwest, then up and around to the southeast, and through the doors into the octagonal room. ", stepTextKey="I reached the upper levels of the College of Sapiarchs. Now I need to find Sapiarch Larnatille and the other trapped sages."},
		["Find Sapiarch Larnatille"] =
			{appendText=", the Arcanologist, in her study through a door in the northwest corner of the large central chamber of the College of Sapiarchs' upper level."},
		[10] = 
			{appendStepText="I traveled through a portal from Lillandril's western plaza to the College of Sapiarchs. Then I went down the stairs, past a fountain and up a short path to illuminated doors. In the labyrinth's lower level, I went to the southwest, then up and around to the southeast to an octagonal room. The Arcanologist's study is near the northwest corner of the large, central chamber. Inside, ", stepTextKey="Valsirenn cast a spell of binding on a Daedric cultist and seems to have the situation well in hand. I should speak to Sapiarch Larnatille and tell her what happened to the Heart of Transparent Law."},
		["Talk to Sapiarch Larnatille"] =
			{appendText=", the Arcanologist, standing near the bound cultist."},
		[11] = 
			{appendStepText="I traveled through a portal from Lillandril's western plaza to the College of Sapiarchs. Then I went down the stairs, past a fountain and up a short path to illuminated doors. In the labyrinth's lower level, I went to the southwest, then up and around to the southeast to an octagonal room, and reached the Arcanologist's Study to the northwest. ", stepTextKey="I should speak to Valsirenn and the captive cultist before I go look for the tower sentinels."},
		["Talk to Valsirenn 2"] =
			{appendText=", the Psijic mage.", stepTextKey="I should speak to Valsirenn and the captive cultist before I go look for the tower sentinels.\n"},
		["Talk to Earl Leythen"] =
			{appendText=", a Daedric cult leader."},
		[12] = 
			{appendStepText="My work at the College of Sapiarchs is finished. ", stepTextKey="While Valsirenn takes the imprisoned Leythen, formerly of the Psijic Order and now an earl in the Court of Bedlam, to Artaeum, I need to travel to the Illumination Academy and locate the two tower sentinels, Hannayel and Imedril."},
		["Go to the Illumination Academy"] =
			{appendText=" situated on a mountainside, northeast of the western coastal city of Lillandril and northwest of the Ebon Stadmont Wayshrine."},
		[13] = 
			{appendStepText="I arrived at the Illumination Academy, northeast of Lillandril and northwest of the Ebon Stadmonth Wayshrine.\n\n", stepTextKey="Razum-dar? I wonder what he's doing at the Illumination Academy? I should talk to him and find out."},
		["Talk to Razum-dar"] =
			{appendText=" on the grounds of the academy, near the southern gateway."},
		[14] = 
			{appendStepText="Northwest of the Ebon Stadmont Wayshrine, ", stepTextKey="I need to find the tower sentinels somewhere here in the Illumination Academy. Raz suggested that we start our search in the Academy Guest Wing on the western side of the campus."},
		["Find the Tower Sentinels"] =
			{appendText=", Hannayel and Imedril. I should ask a servant if she knows where they might be."},
		[15] = 
			{appendStepText="I found Razum-dar at the Illumination Academy on the mountainside northwest of the Ebon Stadmont Wayshrine. ", stepTextKey="We reached the Academy Guest Wing. Now I should search Sapiarch Hannayel's room."},
		["Search Hannayel's Room"] =
			{appendText=", on the left side of the Guest Wing."},
		[16] = 
			{appendStepText="At the Illumination Academy on the mountainside northwest of the Ebon Stadmont Wayshrine, in Hannayel's room in the Guest Wing, I found a Letter to Imedril. ", stepTextKey="Raz thinks that Hannayel hid a coded message in her letter to Imedril. He thinks the key to finding her hidden quiet room involves four specific books and reading podiums."},
		["Find Hannayel's Quiet Room"] =
			{appendText=". I should use the Letter to Imedril I have to gather the four books she mentioned. They should be in the Hall of Illumination, across the campus on its east side. I should check tables, dressers, bookshelves, and desks. There should be pedestals in the upstairs Study Hall."},
		[17] = 
			{appendStepText="At the Illumination Academy northwest of the Ebon Stadmont Wayshrine, in its eastern Hall of Illumination, ", stepTextKey="I solved the book puzzle and it revealed Sapiarch Hannayel's hiding place. I should talk to her to make sure she's all right and to find out where Sapiarch Imedril can be found."},
		["Talk to Sapiarch Hannayel"] =
			{appendText=" in her quiet room, hidden behind an illusory bookcase in the upstairs Study Hall."},
		[18] = 
			{appendStepText="At the Illumination Academy, Sapiarch ", stepTextKey="Hannayel said that I can find Sapiarch Imedril in King's Haven Pass, studying the old ruins at that location. I should go there and find the second tower sentinel."},
		["Find the King's Haven Pass Ruins"] =
			{appendText=". Near the academy's eastern gate, follow a footpath leading up to the northwest, with limestone steps. At the top, a beautiful bridge spans the ravine north of the Ebon Stadmont Wayshrine. At its eastern end is the entrance to the pass.\nTo find the ruins, I should take the lower trail along the river, across wooden ramps to the south, and enter Coral-Splitter Caves. Then snake through the caverns to reach the southern Ancient Ruins through a straight hallway."},
		[19] = 
			{appendStepText="North of the Ebon Stadmont Wayshrine in King's Haven Pass' southern Coral-Splitter Caves, I entered and found the south-central Ancient Ruins of the caverns. ", stepTextKey="Now that I reached the ruins at King's Haven Pass, I need to find Sapiarch Imedril and make sure he's all right."},
		["Find Sapiarch Imedril"] =
			{appendText=" in the cavernous, eastern ruin. If he is not there, I should continue searching, circling to the north into the Ancient Ruins."},
		[20] = 
			{appendStepText="In King's Haven Pass' southern Coral-Splitter Caves, I entered the south-central Ancient Ruins and made my way to the northeastern, angular chamber. ", stepTextKey="I found Sapiarch Imedril, but he's in trouble. Something is pulling him toward that gaping portal. The Golden Knight is trying to help him. I should lend a hand."},
		["Help Save Sapiarch Imedril"] =
			{appendText=" by burning the portal's webs."},
		[21] = 
			{appendStepText="In King's Haven Pass' southern Coral-Splitter Caves, I entered the south-central Ancient Ruins where I searched for the Sapiarch. He was in the northeastern, angular chamber. ", stepTextKey="Something reached out of the portal and whisked the Golden Knight away. A gem was knocked out of the hilt of his sword. Before he disappeared, the Golden Knight asked me to retrieve it."},
		["Take the Dawnstar Gem"] =
			{appendText=" lying on the stone floor behind Sapiarch Imedril."},
		[22] = 
			{appendStepText="In King's Haven Pass' southern Coral-Splitter Caves, I entered the south-central Ancient Ruins, where I searched for the Sapiarch. He was in the northeastern, angular chamber. ", stepTextKey="I should see how the tower sentinel is doing."},
		["Talk to Sapiarch Imedril"] =
			{appendText="."},
		[23] = 
			{appendStepText="In the Ancient Ruins within Coral-Splitter Caves at the King's Haven Pass, ", stepTextKey="Sapiarch Imedril succumbed to the spider poison coursing through his body. I have his Resolute Diamond and the Dawnstar Gem. Now I should leave these ruins before Mephala's servants decide to try another attack."},
		["Leave the Ruins"] =
			{appendText=", through the northern door in the northeast angular chamber."},
		[24] = 
			{appendStepText="", stepTextKey="Valsirenn appeared and asked me to return to Artaeum. Apparently, the Ritemaster has need of me. I should go to Artaeum as soon as I can."},
		["Return to Artaeum"] =
			{appendText="."},
		[25] = 
			{appendStepText="", stepTextKey="Now that I returned to Artaeum, I should head to Ceporah Tower and talk to the Ritemaster. I need to tell him what I learned and find out why he had Valsirenn summon me."},
		["Talk to Ritemaster Iachesis"] =
			{appendText=" in his study. I should use the tower's southeastern turquoise portal to meet him."},
		[26] = 
			{appendStepText="I returned to Arteaum. ", stepTextKey="The Ritemaster summoned me to Ceporah Tower for a reason. Now that I've told him about the tower sentinels and the Golden Knight, I should find out what else he wanted to tell me."},
		["Talk to the Ritemaster"] =
			{appendText=" in his study, through the tower's southeastern turquoise portal."},
	},

	[GetQuestName(6109)] = { --"The Dreaming Cave" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Oriandra told me that the Ritemaster wants to see me in his study in Ceporah Tower on Artaeum. I should go there and talk to him."},
		["Talk to Ritemaster Iachesis 1"] =
			{appendText=". I should use the tower's southeastern turquoise portal to meet with him.", stepTextKey="Oriandra told me that the Ritemaster wants to see me in his study in Ceporah Tower on Artaeum. I should go there and talk to him."},
		[2] = 
			{appendStepText="I met Iachesis in his study on Artaeum. ", stepTextKey="The Ritemaster asked me to meet him in the Dreaming Cave beneath Ceporah Tower. He wants to show me something that concerns the location of the Heart of Transparent Law."},
		["Meet the Ritemaster in the Dreaming Cave"] =
			{appendText=". Its entrance is outside at the bottom of the stairs circling the tower's main entrance portal."},
		[3] = 
			{appendStepText="On Artaeum, I descended the stairs circling the main entrance portal beneath the tower to enter the cave. ", stepTextKey="The Ritemaster asked me to hold the Dawnstar gem I retrieved up to the barrier that blocks the portal. He thinks that the path beyond the barrier leads to where he hid the Heart of Transparent Law."},
		["Use the Dawnstar Gem"] =
			{appendText=" on the cloudy, violet ward."},
		[4] = 
			{appendStepText="In the Dreaming Cave beneath Artaeum's Ceporah Tower, I used the gem. ", stepTextKey="The Daedric barrier reacted when I held the Dawnstar gem toward it. It withdrew slightly. I should talk to the Ritemaster and find out what this means."},
		["Talk to Ritemaster Iachesis 2"] =
			{appendText=".", stepTextKey="The Daedric barrier reacted when I held the Dawnstar gem toward it. It withdrew slightly. I should talk to the Ritemaster and find out what this means."},
		[5] = 
			{appendStepText="I spoke with Iachesis in the Dreaming Cave beneath Artaeum's Ceporah Tower. ", stepTextKey="The Ritemaster believes that Leythen might be able to tell us how to find a priest of Meridia. I should talk to him. He's on the island of Artaeum, talking to Valsirenn."},
		["Talk to Earl Leythen"] =
			{appendText=". I'll start looking for Leythen in the island's fields overlooking the sea, southwest of the tower."},
		[6] = 
			{appendStepText="I found Valsirenn with Leythen at Artaeum's overlook above the sea. ", stepTextKey="We need to find a Meridia cultist. Valsirenn has an idea. I should speak to her."},
		["Talk to Valsirenn 1"] =
			{appendText=" about Leythen's report of the slaughter of Meridia's followers on the Blessed Isle.", stepTextKey="We need to find a Meridia cultist. Valsirenn has an idea. I should speak to her."},
		[7] = 
			{appendStepText="On Artaeum, ", stepTextKey="Leythen suggested that a cult of Meridia was operating north of Shimmerene, but that the Court of Bedlam eliminated them. Valsirenn reminded me that Razum-dar was investigating Daedric cults. I should be able to find him in Shimmerene."},
		["Find Razum-dar in Shimmerene"] =
			{appendText=", Summerset Isle's eastern city. He is likely just east of the city's fountain plaza by the main gates."},
		[8] = 
			{appendStepText="East of the fountain plaza near the main gates of the island's eastern city, I was looking for Razum-dar. ", stepTextKey="The Divine Prosecution appears to be examining some strange scribbles of skeever heads on the walls of Shimmerene. I should ask them if they've seen Razum-dar."},
		["Talk to Bailiff Roland"] =
			{appendText=" at the archway east of the fountain."},
		[9] = 
			{appendStepText="I spoke with a bailiff of the Divine Prosecution at the archway east of the city's main gates. ", stepTextKey="Scribbles of skeevers on the walls of Shimmerene might lead me to Razum-dar's current location."},
		["Follow the Scribbles to Razum-dar"] =
			{appendText=". The painted skeever seems to be pointing with its nose."},
		[10] = 
			{appendStepText="In a secluded patio, southeast behind Shimmerene's Anchors Aweigh Inn, ", stepTextKey="I found Razum-dar interrogating a pair of Peryite cultists. I should talk to him and ask him if he knows where I can find a priest of Meridia."},
		["Talk to Razum-dar"] =
			{appendText=" near the cultists at the braizer."},
		[11] = 
			{appendStepText="", stepTextKey="Raz has a friend who belongs to the Meridia cult. He's going to make contact with her and then meet me outside the ruins of Eton Nir Grotto."},
		["Meet Razum-dar at Eton Nir Grotto"] =
			{appendText=", far north of the eastern city of Shimmerene, and north of ruins with a high bridge, a wayshrine, and a river crossing. When I see a broken wagon by the road, I should look west across the river for a dirt trail leading up to the grotto in the western mountain cliffs."},
		[12] = 
			{appendStepText="Far north of Shimmerene, north of Eldbur Ruins and its wayshrine, and just north of a broken wagon, I crossed the river and headed west up a dirt trail towards the cliffs. ", stepTextKey="I reached Eton Nir Grotto and located Razum-dar and his old friend Sadara-do. I should talk to her and see if she can help me make contact with Meridia."},
		["Talk to Sadara-do"] =
			{appendText=" on the mountain slope outside of the grotto."},
		[13] = 
			{appendStepText="In the mountains northwest of Shimmerene, I spoke with Razum-dar's friend, a priest of Meridia. ", stepTextKey="Sadara-do said that there's a Meridia shrine somewhere within the ruins of Eton Nir Grotto. She thinks we can contact her Prince once we reach that location."},
		["Search Eton Nir Grotto for the Meridia Shrine"] =
			{appendText=" in the northwestern cavern."},
		[14] = 
			{appendStepText="In the mountains northwest of Shimmerene in the Eton Nir Grotto's northwestern cavern, we found a shrine. ", stepTextKey="Sadara-do confirmed that the shrine to Meridia is just inside. I should proceed with caution in case the Court of Bedlam left something behind."},
		["Investigate the Shrine"] =
			{appendText=" through the Aldmeri doors in the western wall."},
		[15] = 
			{appendStepText="Northwest of Shimmerne, from Eton Nir Grotto's northwestern cavern, I entered Meridia's shrine and approached the altar. ", stepTextKey="A voice has called to us from the statue of Meridia. I should approach the statue and speak to Meridia."},
		["Talk to Meridia"] =
			{appendText=", the Lady of Light."},
		[16] = 
			{appendStepText="In her shrine at Eton Nir Grotto on the Blessed Isle, ", stepTextKey="Meridia informed me that the Golden Knight is Darien Gautier and wants me to rescue him. The Psijics can use the Dawnstar Gem to locate Darien in Mephala's Spiral Skein. I should return to the Dreaming Cave on Artaeum and inform the Ritemaster."},
		["Tell the Ritemaster What You Learned"] =
			{appendText=". He should be in the cave at the bottom of the stairs circling the main entrance portal of Ceporah Tower.\n\nI should speak with Razum-dar before I leave for Artaeum."},
		[17] = 
			{appendStepText="I reported to Iachesis on Artaeum. ", stepTextKey="The Ritemaster has opened a portal in the Dreaming Cave to send me and Valsirenn to Mephala's realm, the Spiral Skein."},
		["Use the Dreaming Cave Portal"] =
			{appendText=". The cave is at the bottom of the stairs circling the tower's main entrance portal."},
		[18] = 
			{appendStepText="On Artaeum, at the bottom of the stairs circling the tower's main portal, I entered the cave and used its portal. ", stepTextKey="The Dreaming Cave transported me to the Spiral Skein, but Valsirenn and I were separated. I need to find her before we start looking for Darien."},
		["Find Valsirenn"] =
			{appendText=" in a cavern illuminated with vibrant orange antler coral. I may need to travel through several caverns in Meridia's realm. I can burn through webs blocking my way and use the Dawnstar Gem to reveal paths through pools. I will need to check ledges and side passages along the way, in case she was captured and bound in a web cocoon."},
		[19] = 
			{appendStepText="Beneath the Artaeum tower's main entrance, I used the cave's portal to reach Mephala's Spiral Skein. I searched caverns, dove into a couple of pools, then went up on a southern ledge, ", stepTextKey="I found Valsirenn and freed her from a web cocoon. I should make sure she's all right before we continue our search for Darien."},
		["Talk to Valsirenn 2"] =
			{appendText=", the Psijic mage.", stepTextKey="I found Valsirenn and freed her from a web cocoon. I should make sure she's all right before we continue our search for Darien."},
		[20] = 
			{appendStepText="Beneath the Artaeum tower's main entrance, I used the cave's portal to reach Mephala's Spiral Skein. I searched caverns, dove into a couple of pools, then up on a southern ledge, I found the Psijic mage. ", stepTextKey="Now that Valsirenn and I are together, we need to find the Golden Knight, Darien Gautier."},
		["Find Darien Gautier"] =
			{appendText=". He is likely being kept at the large northwestern structure of the realm.\n\nFrom the ledge where I found Valsirenn, I should head west, reveal a path through a pool, and continue northwards. Then follow a path east and cross bridges to reach the northwestern area."},
		[21] = 
			{appendStepText="Beneath the Artaeum tower's main entrance, I used the cave's portal to reach Mephala's Spiral Skein. I traveled through caverns and dove into pools to reach the southeastern realm. Then east on a path and across bridges to reach the northwest. ", stepTextKey="We found the Golden Knight, Darien Gautier. He's caught in a giant web and surrounded by Mephala's Daedra. I need to defeat them before I can set him free."},
		["Rescue Darien Gautier"] =
			{appendText=" from his captors at the northeastern edge of the realm."},
		[22] = 
			{appendStepText="Beneath the Artaeum tower's main entrance, I used the cave's portal to reach Mephala's Spiral Skein. I traveled through caverns and dove into pools to reach the southeast area, and then east on a path, across bridges and to the northwestern structure. ", stepTextKey="The Dawnstar's light shredded the webs and set the Golden Knight free. Now I should talk to Darien and see if he can restore the Dawnbreaker."},
		["Talk to Darien Gautier"] =
			{appendText="."},
		[23] = 
			{appendStepText="Beneath the Artaeum tower's main entrance, I used the cave's portal to reach Mephala's Spiral Skein. I traveled through caverns and dove into pools to reach the southeastern realm. Then east on a path and across bridges to reach the northwest. ", stepTextKey="Now that we have Darien, we need to find a way to contact the Ritemaster so he can get us back to the Dreaming Cave. I should talk to Valsirenn outside the Spider Citadel."},
		["Talk to Valsirenn 3"] =
			{appendText=". She and Darien exited through a door in the citadel's northeast.", stepTextKey="Now that we have Darien, we need to find a way to contact the Ritemaster so he can get us back to the Dreaming Cave. I should talk to Valsirenn outside the Spider Citadel."},
		[24] = 
			{appendStepText="Beneath the Artaeum tower's main entrance, I used the cave's portal to reach Mephala's Spiral Skein. I traveled through caverns and dove into pools to reach the southeastern realm. Then east on a path and across bridges to reach the northwest. In the courtyard northeast of the Citadel, ", stepTextKey="Valsirenn is attempting to open a portal back to the Dreaming Cave. We have to survive long enough for her to succeed."},
		["Wait for the Portal to Open"] =
			{appendText="."},
		[25] = 
			{appendStepText="In Mephala's Spiral Skein, ", stepTextKey="Valsirenn opened a portal back to the Dreaming Cave. I should use the portal so I can return to the Ritemaster and let him know what happened."},
		["Talk to Ritemaster Iachesis 3"] =
			{appendText=" in the cave beneath Artaeum's Ceporah Tower.", stepTextKey="Valsirenn opened a portal back to the Dreaming Cave. I should use the portal so I can return to the Ritemaster and let him know what happened."},
		[26] = 
			{appendStepText="I returned to Artaeum. ", stepTextKey="Now that I'm back in the Dreaming Cave, I should consult with the Ritemaster about what we need to do next."},
		["Talk to Ritemaster Iachesis 4"] =
			{appendText=" near the portal in the cave beneath Ceporah Tower.", stepTextKey="Now that I'm back in the Dreaming Cave, I should consult with the Ritemaster about what we need to do next."},
	},

[GetQuestName(6113)] = { --"Lost in Translation" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="I should return to the Dreaming Cave and talk to the Ritemaster about the memory he recovered."},
		["Talk to Ritemaster Iachesis 1"] =
			{appendText=" on Artaeum. The cave's entrance is at the bottom of the stairs circling Ceporah Tower's main entrance portal.", stepTextKey="I should return to the Dreaming Cave and talk to the Ritemaster about the memory he recovered."},
		[2] = 
			{appendStepText="I spoke with Iachesis in The Dreaming Cave on Artaeum. ", stepTextKey="The Ritemaster asked me to go to his study in Ceporah Tower and check on Oriandra's progress in translating the ancient words."},
		["Talk to Oriandra in the Ritemaster's Study"] =
			{appendText=". In the tower's main gallery, I should use the southeastern turquoise portal."},
		[3] = 
			{appendStepText="In the Ritemaster's Study at Ceporah Tower on Artaeum, I spoke with Iachesis' acolyte. ", stepTextKey="Oriandra has asked that I take the notes on this ancient language to Leythen. Showing them to him might convince Leythen to help us."},
		["Take the Notes on the Ancient Language"] =
			{appendText=", \"Grand Maestro Forte's Research\", from the desktop near Oriandra."},
		[4] = 
			{appendStepText="In the Ritemaster's Study at Ceporah Tower on Artaeum, Acolyte ", stepTextKey="Oriandra suggested that Leythen could help translate the ancient words, since he was the Psijic Order's language expert before he left to join the Court of Bedlam. I should talk to Leythen in Valsirenn's study."},
		["Talk to Earl Leythen 1"] =
			{appendText=". In the tower's main gallery, I should use the northeastern turquoise portal.", stepTextKey="Oriandra suggested that Leythen could help translate the ancient words, since he was the Psijic Order's language expert before he left to join the Court of Bedlam. I should talk to Leythen in Valsirenn's study."},
		[5] = 
			{appendStepText="On Artaeum, in Valsirenn's Study at Ceporah Tower, ", stepTextKey="Leythen provided me with a rune. He says if I use it in Ebon Stadmont, he'll be able to see what I see. I need to go to Ebon Stadmont, find the ancient writing, and use Leythen's rune."},
		["Use Leythen's Rune in Ebon Stadmont"] =
			{appendText=". It is a magical ruin on Summerset, situated in the wooded foothills southeast of Ebon Stadmont Wayshrine. I should use the southeastern entrance to the secluded site, near the river that empties into the northeast bay. From the bay road, north on the river road, I should go to the second short Altmer wall and, between the wall and a flowering tree on the riverbank, head west on a rocky river crossing. I can use Leythen's Rune to help me from there."},
		[6] = 
			{appendStepText="On the southeastern side of Ebon Stadmont, on the western riverbank near the second Altmer wall on the road by the river that empties into the bay, I used the rune. ", stepTextKey="Leythen's rune has allowed him to project himself to my location. I should talk to him and see if he knows what I should be looking for."},
		["Talk to Earl Leythen 2"] =
			{appendText="'s projection.", stepTextKey="Leythen's rune has allowed him to project himself to my location. I should talk to him and see if he knows what I should be looking for."},
		[7] = 
			{appendStepText="Near the northern river that flows into the island's western bay, I spoke with the former Psijic. ", stepTextKey="Leythen thinks the translated passages about crows will help guide me through the Ebon Stadmont forest. I should refer to the passages as I search for the stone inscribed with the ancient writing."},
		["Navigate the Ebon Stadmont Forest"] =
			{appendText=". There was a campsite near an archway in the woods southeast of the wayshrine. If there is a crow on that arch ... I should read the notes I carry, \"The Grand Maestro's Research\"."},
		[8] = 
			{appendStepText="After entering Ebon Stadmont through an archway from the campsite near the wayshrine, I found an archway with two crows. I'm in the Ebon Sanctum. ", stepTextKey="This might be the area where I'll find the stone inscribed with the ancient language. I should use the rune so Leythen can assist me."},
		["Locate the Inscribed Stone"] =
			{appendText=" by following the path to reach the eastern structure in the Sanctum."},
		[9] = 
			{appendStepText="After entering Ebon Stadmont through an archway from the campsite near the wayshrine, I found an archway with two crows. In the Ebon Sanctum's eastern ruin, ", stepTextKey="I found the inscribed stone mentioned in the Grand Maestro's Research, but before Leythen could translate it, he was replaced by another member of the Court of Bedlam. I should talk to her."},
		["Talk to Nocturnal's Earl"] =
			{appendText="."},
		[10] = 
			{appendStepText="After entering Ebon Stadmont through an archway from the campsite near the wayshrine, I found an archway with two crows. I'm in the Ebon Sanctum near the eastern ruin. ", stepTextKey="Leythen has reestablished his connection to the rune. I should talk to him."},
		["Talk to Earl Leythen 3"] =
			{appendText=" after moving away from Nocturnal's Earl.", stepTextKey="Leythen has reestablished his connection to the rune. I should talk to him."},
		[11] = 
			{appendStepText="", stepTextKey="I need to return to Ceporah Tower on Artaeum and tell the Ritemaster what Nocturnal's earl revealed about the ancient phrase."},
		["Talk to Ritemaster Iachesis in Ceporah Tower"] =
			{appendText=" in the main gallery's southwestern chamber."},
		[12] = 
			{appendStepText="", stepTextKey="The Ritemaster asked me to check on Darien and make sure he's ready to help us breach the barrier in the Dreaming Cave."},
		["Talk to Darien Gautier"] =
			{appendText=". He's enjoying the outdoors, east of Artaeum's wayshrine."},
		[13] = 
			{appendStepText="Above the eastern sea of Artaeum, I chatted with Meridia's champion. ", stepTextKey="Darien's ready. Now I should head into the Dreaming Cave and meet up with the Ritemaster."},
		["Meet in the Dreaming Cave"] =
			{appendText=" at the bottom of the stairs circling Ceporah Tower's main entrance portal."},
		[14] = 
			{appendStepText="On Artaeum, in The Dreaming Cave at the bottom of the stairs circling Ceporah Tower's main entrance portal, ", stepTextKey="Darien removed the barrier and opened the way to wherever the Ritemaster hid the Heart of Transparent Law. I should enter the portal and see where it leads."},
		["Use the Dreaming Cave Portal"] =
			{appendText="."},
		[15] = 
			{appendStepText="We left the cave below Ceporah Tower on Artaeum. ", stepTextKey="We emerged from the Dreaming Cave portal. Now I should talk to the Ritemaster and see if this place triggered any of his missing memories."},
		["Talk to Ritemaster Iachesis 2"] =
			{appendText=".", stepTextKey="We emerged from the Dreaming Cave portal. Now I should talk to the Ritemaster and see if this place triggered any of his missing memories."},
		[16] = 
			{appendStepText="We are in Nocturnal's realm of Evergloam. ", stepTextKey="The Ritemaster was weakened by the effort of opening the portal in the Dreaming Cave. He asked me to scout ahead and clear the path while Valsirenn helps him follow after."},
		["Follow the Path 1"] =
			{appendText=". Darien will accompany me with his powerful sword, Dawnbreaker. I may wish to explore side trails, too.", stepTextKey="The Ritemaster was weakened by the effort of opening the portal in the Dreaming Cave. He asked me to scout ahead and clear the path while Valsirenn helps him follow after."},
		[17] = 
			{appendStepText="We are on the path south of the lake in Evergloam. ", stepTextKey="The crows seemed to recognize the Ritemaster. I should ask him about that."},
		["Talk to Ritemaster Iachesis 3"] =
			{appendText=".", stepTextKey="The crows seemed to recognize the Ritemaster. I should ask him about that."},
		[18] = 
			{appendStepText="In the Evergloam, ", stepTextKey="I should continue to scout ahead and clear the path for the Ritemaster until we find the Heart of Transparent Law."},
		["Follow the Path 2"] =
			{appendText=" up the stairs and on toward the top of the mountain.", stepTextKey="I should continue to scout ahead and clear the path for the Ritemaster until we find the Heart of Transparent Law."},
		[19] = 
			{appendStepText="We are up on the path northwest of the lake in the Evergloam. ", stepTextKey="The crows said something about an offer from their mistress. I should ask the Ritemaster if he knows what they were talking about."},
		["Talk to Ritemaster Iachesis 4"] =
			{appendText=".", stepTextKey="The crows said something about an offer from their mistress. I should ask the Ritemaster if he knows what they were talking about."},
		[20] = 
			{appendStepText="In the Evergloam, ", stepTextKey="I need to continue to scout ahead and clear the path up the mountain so we can find the hiding place of the Heart of Transparent Law."},
		["Follow the Path 3"] =
			{appendText=". I may wish to explore a side path to the northwest.", stepTextKey="I need to continue to scout ahead and clear the path up the mountain so we can find the hiding place of the Heart of Transparent Law."},
		[21] = 
			{appendStepText="", stepTextKey="We reached the top of the path and it's a dead end. The Ritemaster seems to have remembered something important, though. I should talk to him."},
		["Talk to Ritemaster Iachesis 5"] =
			{appendText=" near a dark, shadowy circle on the ground in northwest Evergloam.", stepTextKey="We reached the top of the path and it's a dead end. The Ritemaster seems to have remembered something important, though. I should talk to him."},
		[22] = 
			{appendStepText="", stepTextKey="The Ritemaster remembered that he took the Heart through this portal and made some sort of deal with Nocturnal to hide it safely. I should use the portal and see where it leads."},
		["Use the Portal"] =
			{appendText=" to the mountaintop."},
		[23] = 
			{appendStepText="", stepTextKey="The Ritemaster said he remembered an ancient ruin. I should head toward that and see what's there."},
		["Approach the Mountain Top Ruin"] =
			{appendText=" in northern Evergloam."},
		[24] = 
			{appendStepText="We arrived at Evergloam's northern mountaintop. ", stepTextKey="This is the ancient ruin where the Ritemaster remembers casting the spell and hiding away the Heart. I should talk to him before he reveals the hiding place."},
		["Talk to Ritemaster Iachesis 6"] =
			{appendText=".", stepTextKey="This is the ancient ruin where the Ritemaster remembers casting the spell and hiding away the Heart. I should talk to him before he reveals the hiding place."},
		[25] = 
			{appendStepText="On Evergloam's northern mountaintop, Iachesis climbed up on a rock. ", stepTextKey="The Ritemaster said the ancient words, but Clavicus Vile and Mephala appeared. We need to defend ourselves from the Daedric horde."},
		["Defend Against the Daedric Attack"] =
			{appendText="."},
		[26] = 
			{appendStepText="At Evergloam's northern mountaintop, ", stepTextKey="Nocturnal appeared, banished the other Princes, and ripped the Heart of Transparent Law from its hiding place inside the Ritemaster's chest. We need to hold on long enough for Valsirenn to finish casting her teleportation spell."},
		["Escape Nocturnal's Realm"] =
			{appendText=". Valsirenn is opening a portal."},
		[27] = 
			{appendStepText="", stepTextKey="Ritemaster Iachesis is dead, the Heart of Transparent Law is in Nocturnal's hands, the triad of Daedric Princes has been dissolved, and Darien lost Meridia's sword, Dawnbreaker. I need to let Oriandra know everything that happened."},
		["Talk to Oriandra 1"] =
			{appendText=" in The Dreaming Cave below Ceporah Tower on Artaeum.", stepTextKey="Ritemaster Iachesis is dead, the Heart of Transparent Law is in Nocturnal's hands, the triad of Daedric Princes has been dissolved, and Darien lost Meridia's sword, Dawnbreaker. I need to let Oriandra know everything that happened."},
		[28] = 
			{appendStepText="In The Dreaming Cave below Ceporah Tower on Artaeum, ", stepTextKey="I need to talk to Oriandra so we can determine a new course of action in the wake of the Ritemaster's death."},
		["Talk to Oriandra 2"] =
			{appendText=".", stepTextKey="I need to talk to Oriandra so we can determine a new course of action in the wake of the Ritemaster's death."},
	},

[GetQuestName(6125)] = { --"A Necessary Alliance" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Sotha Sil has news for the Ritemaster. I should go to his study in Ceporah Tower and try to convince him to share that news with me."},
		["Talk to Sotha Sil"] =
			{appendText=" on Artaeum. I should use the western turquoise portal in the tower's main gallery."},
		[2] = 
			{appendStepText="In his study at Ceporah Tower on Artaeum, ", stepTextKey="Sotha Sil suggested I go to Valsirenn and inform her of his speculations concerning Nocturnal and the Crystal Tower."},
		["Go to Valsirenn's Study"] =
			{appendText=". I should use the northeastern turquoise portal in the tower's main gallery."},
		[3] = 
			{appendStepText="In the Ceporah Tower of Artaeum, ", stepTextKey="I reached Valsirenn's study to find her trying to force information out of Leythen. She wants me to talk to him and finish the interrogation."},
		["Interrogate Earl Leythen"] =
			{appendText="."},
		[4] = 
			{appendStepText="In Valsirenn's  study at Ceporah Tower on Artaeum, ", stepTextKey="Leythen suggested we make an alliance with Mephala to gain her help against Nocturnal. I should talk to Valsirenn and she what she thinks about that proposal."},
		["Talk to Valsirenn 1"] =
			{appendText=".", stepTextKey="Leythen suggested we make an alliance with Mephala to gain her help against Nocturnal. I should talk to Valsirenn and she what she thinks about that proposal."},
		[5] = 
			{appendStepText="", stepTextKey="I need to go to the Crystal Tower Gatehouse, northeast of Lillandril, to meet Valsirenn and Darien. We're going to see how the Sapiarchs are progressing with their attempt to create two new tower sentinels."},
		["Go to the Crystal Tower Gatehouse 1"] =
			{appendText=" in northwest Summerset. It is near the end of the road north of Illumination Academy, up a staircase east of a wayshrine.", stepTextKey="I need to go to the Crystal Tower Gatehouse, northeast of Lillandril, to meet Valsirenn and Darien. We're going to see how the Sapiarchs are progressing with their attempt to create two new tower sentinels."},
		[6] = 
			{appendStepText="In northwest Summerset, east of the Crystal Tower Wayshrine, I was ascending the stairs to the gatehouse when I saw the Eye of the Queen. ", stepTextKey="Razum-dar ran into the nearby watchtower. I should follow him and find out what he's doing here."},
		["Talk to Razum-dar in the Watchtower"] =
			{appendText=" with the illuminated entry. He may be up top looking for something."},
		[7] = 
			{appendStepText="In northwest Summerset, east of the Crystal Tower Wayshrine, I spoke with Razum-dar on a watchtower's turret. ", stepTextKey="Something terrible happened to the Crystal Tower. I need to get to the gatehouse and see how the Sapiarchs' ritual is coming along."},
		["Go to the Crystal Tower Gatehouse 2"] =
			{appendText=" at the top of the stairs.", stepTextKey="Something terrible happened to the Crystal Tower. I need to get to the gatehouse and see how the Sapiarchs' ritual is coming along."},
		[8] = 
			{appendStepText="In northwest Summerset, east of the Crystal Tower Wayshrine, I climbed the stairs to reach the gatehouse. ", stepTextKey="Valsirenn appears to be helping the Sapiarchs with their ritual. I should talk to her and see if she has any information about what's happening here."},
		["Talk to Valsirenn 2"] =
			{appendText=", the Psijic mage.", stepTextKey="Valsirenn appears to be helping the Sapiarchs with their ritual. I should talk to her and see if she has any information about what's happening here."},
		[9] = 
			{appendStepText="In northwest Summerset, east of the Crystal Tower Wayshrine, I climbed the stairs to reach the Gatehouse. On each side of the Gatehouse's entrance there is a circular pavilion. ", stepTextKey="I need to help defend the ritual platforms against the Daedric attack in order to give the Sapiarchs enough time to complete their ritual to attune the tower sentinels."},
		["Defend the North Ritual Platform"] =
			{appendText=" with Darien.\n"},
		["Defend the South Ritual Platform"] =
			{appendText=" with Razum-dar."},
		[10] = 
			{appendStepText="In northwest Summerset, east of the Crystal Tower Wayshrine, I climbed the stairs to reach the Gatehouse. ", stepTextKey="We defended against the Daedra attacks on the ritual platforms. Now I should check on the new Tower Sentinels and see if they've completed the attunement to the diamond keys."},
		["Check on the Tower Sentinels"] =
			{appendText=" at the Gatehouse entry between the two platforms."},
		[11] = 
			{appendStepText="In northwest Summerset east of the Crystal Tower Wayshrine, at the top of the stairs to the Crystal Tower, I reached the Gatehouse's entry. ", stepTextKey="The Sapiarchs trying to attune themselves to the diamond keys so they could open the way to the Crystal Tower are dead. I should talk to Valsirenn and find out what our next option is."},
		["Talk to Valsirenn 3"] =
			{appendText=".", stepTextKey="The Sapiarchs trying to attune themselves to the diamond keys so they could open the way to the Crystal Tower are dead. I should talk to Valsirenn and find out what our next option is."},
		[12] = 
			{appendStepText="", stepTextKey="I need to meet Razum-dar in Alinor so we can warn the Proxy Queen about Nocturnal's assault on the Crystal Tower."},
		["Talk to Razum-dar in Alinor"] =
			{appendText=", near the northern gate by The Golden Gryphon tavern."},
		[13] = 
			{appendStepText="Near the northern gate of Alinor in western Summerset, ", stepTextKey="Razum-dar said I should go to the gardens in Alinor to look for a strange talking dog that has a message for me."},
		["Meet the Dog in the Alinor Gardens"] =
			{appendText=" near the city's central crafting area, Rinmawen's Plaza."},
		[14] = 
			{appendStepText="From Alinor's central Rinmawen's Plaza, ", stepTextKey="I should follow the strange talking dog. Raz said it has a message to pass on to me."},
		["Follow the Strange Dog"] =
			{appendText=" up past the wayshrine, south across the bridge, then west down some stairs and a sharp right to reach the riverside stairs."},
		[15] = 
			{appendStepText="From Alinor's central Rinmawen Plaza, the dog ran up past the wayshrine, then south across the bridge. It immediately turned right, went down some stairs, and turned right again to the stairs down to the river. ", stepTextKey="I followed the dog to an isolated location. I suppose I should talk to him now."},
		["Talk to Barbas"] =
			{appendText=" the Hound."},
		[16] = 
			{appendStepText="In Alinor, I spoke with Barbas, the talking dog Raum-dar met. ", stepTextKey="The Hound of Clavicus Vile directed me to the caves north of Alinor. He said that his master would meet me and talk to me there."},
		["Find Clavicus Vile's Cave"] =
			{appendText=" northeast of Alinor in the mountains south of Rellenthil. It is up the narrow river valley behind the Manor of Masques. The cave's hidden entrance is in the rocks on the west side of a lake."},
		[17] = 
			{appendStepText="South of Rellenthil and up the narrow river valley behind the Manor of Masques, I found Clavicus Vile's hidden cave in the rocks on the west side of a lake. ", stepTextKey="Clavicus Vile wants to talk to me somewhere in this cave. I need to find him."},
		["Find Clavicus Vile"] =
			{appendText=" in the Vaults of Heinarwe. I should head for the ruins across a bridge to the northwest. Once I enter, I should wait in the ruin's southwestern chamber."},
		[18] = 
			{appendStepText="South of Rellenthil and up the narrow river valley behind the Manor of Masques, I found Vile's hidden cave in the rocks on the west side of a lake. I entered the Vaults of Heinarwe and crossed a bridge, entered a ruin and went to its southwestern chamber. ", stepTextKey="Clavicus Vile has killed and possessed one of his own cultists. Now he wants to talk to me."},
		["Talk to Clavicus Vile"] =
			{appendText="."},
		[19] = 
			{appendStepText="South of Rellenthil and up the narrow river valley behind the Manor of Masques, I found Vile's hidden cave in the rocks on the west side of a lake. In the northwestern ruin of the Vaults of Heinarwe, I spoke with Vile. ", stepTextKey="Clavicus Vile placed a key in the upper portion of the ruins. He says the Psijics can use the key to get me to Vile's Oblivion realm, and from there he can grant me access to the Crystal Tower. I should go and find the key."},
		["Gather Vile's Key"] =
			{appendText=" from a safebox, upstairs on an altar by a Clavicus Vile banner."},
		[20] = 
			{appendStepText="South of Rellenthil and up the narrow river valley behind the Manor of Masques, I found Clavicus Vile's hidden cave in the rocks on the west side of a lake. In the northwestern ruin of the Vaults of Heinarwe, ", stepTextKey="I acquired the key to Clavicus Vile's realm. Now Valsirenn has appeared to me as a projection. She seems upset. I should talk to her."},
		["Talk to Valsirenn 4"] =
			{appendText=" in the upstairs chamber near the altar.", stepTextKey="I acquired the key to Clavicus Vile's realm. Now Valsirenn has appeared to me as a projection. She seems upset. I should talk to her."},
		[21] = 
			{appendStepText="", stepTextKey="Before I try to figure out how to best make use of Clavicus Vile's offer to grant me access to the Crystal Tower, Valsirenn asked me to find Darien and Leythen in the northwest region of Summerset and see what they're up to."},
		["Search for Darien and Leythen"] =
			{appendText=". Leythen was adamant about contacting Mephala, and Darien was growing impatient. Perhaps I should search the ruin at the end of the northwestern road on the peninsula north of the western coastal city of Lillandril."},
		[22] = 
			{appendStepText="At the Cathedral of Webs, a ruin north of the western coastal city of Lillandril, ", stepTextKey="I found Darien and Leythen. I should talk to Darien and find out what they're doing out here."},
		["Talk to Darien Gautier"] =
			{appendText=" near an old Aldmeri doorway."},
		[23] = 
			{appendStepText="At the Cathedral of Webs, a ruin north of the western coastal city of Lillandril, I spoke to Meridia's champion. ", stepTextKey="Darien says that we need to get the help of the betrayed Daedric Princes and that Leythen has agreed to put us in contact with Mephala. I should talk to Leythen and see what he has planned."},
		["Talk to Earl Leythen 1"] =
			{appendText=" at the cathedral's doorway.", stepTextKey="Darien says that we need to get the help of the betrayed Daedric Princes and that Leythen has agreed to put us in contact with Mephala. I should talk to Leythen and see what he has planned."},
		[24] = 
			{appendStepText="At the Cathedral of Webs, northwest of the western coastal city of Lillandril, I spoke with Leythen. ", stepTextKey="We need to enter the headquarters of Mephala's cult and find her shrine. Then Leythen can help us contact his Prince."},
		["Enter the Cathedral of Webs"] =
			{appendText="."},
		[25] = 
			{appendStepText="North of the western coastal city of Lillandril, we entered the Cathedral of Webs. ", stepTextKey="We need to find Mephala's shrine so that Leythen can put us in contact with his Prince."},
		["Explore the Cathedral of Webs"] =
			{appendText=" with Leythen and Darien. We should go south to the central area with a pool."},
		[26] = 
			{appendStepText="Northwest of the western coastal city of Lillandril, we reached the central chamber of the Cathedral of Webs. ", stepTextKey="Nocturnal's earl has given us a cryptic warning. I should talk to Leythen and see if he knows what she's talking about."},
		["Talk to Earl Leythen 2"] =
			{appendText=".", stepTextKey="Nocturnal's earl has given us a cryptic warning. I should talk to Leythen and see if he knows what she's talking about."},
		[27] = 
			{appendStepText="Northwest of the western coastal city of Lillandril, from the central chamber of the Cathedral of Webs. ", stepTextKey="Leythen left us and went with Nocturnal's earl deeper into the ruins. We have to follow them."},
		["Follow Leythen and Nocturnal's Earl"] =
			{appendText="."},
		[28] = 
			{appendStepText="Northwest of the western coastal city of Lillandril, in the southwestern shrine to Mephala in the Cathedral of Webs, ", stepTextKey="Nocturnal's earl is willing to talk. I should follow Leythen's advice and try to get her to reveal her master's plans."},
		["Talk to Nocturnal's Earl"] =
			{appendText="."},
		[29] = 
			{appendStepText="Northwest of the western coastal city of Lillandril, in the southwestern shrine to Mephala in the Cathedral of Webs, I learned ", stepTextKey="Nocturnal plans to siphon the life energy of Nirn to increase the power of the Crystal Tower. And with that power, she plans to remake all of reality. I should talk to Leythen and see if he's willing to contact Mephala now."},
		["Talk to Earl Leythen 3"] =
			{appendText=" at the desecrated statue of Mephala.", stepTextKey="Nocturnal plans to siphon the life energy of Nirn to increase the power of the Crystal Tower. And with that power, she plans to remake all of reality. I should talk to Leythen and see if he's willing to contact Mephala now."},
		[30] = 
			{appendStepText="In the Cathedral of Webs northwest of Lillandril, ", stepTextKey="Leythen thinks he can contact Mephala if we go to his private chamber. I should follow him there."},
		["Go to Leythen's Chamber"] =
			{appendText=" in the southeast ruins."},
		[31] = 
			{appendStepText="In his southeastern chamber in the Cathedral of Webs, northwest of Lillandril, ", stepTextKey="Leythen said I should meet him outside so we can make contact with Mephala."},
		["Contact Mephala Outside the Ruins"] =
			{appendText=" through the northern door in Leythen's Chamber. The exit is near the water's edge, southeast of the Cathedral's entry and west of an abyssal geyser."},
		[32] = 
			{appendStepText="Near the water's edge southeast of the Cathedral of Webs, northwest of Lillandril and west of an abyssal geyser, ", stepTextKey="Mephala has answered Leythen's summons. I should talk to the Daedric Prince."},
		["Talk to Mephala"] =
			{appendText="."},
		[33] = 
			{appendStepText="", stepTextKey="I made deals with both of the betrayed Princes. I should return to Artaeum and talk to Valsirenn. She needs to hear what happened, and I should see if the Psijics have figured out how to use the diamond keys yet."},
		["Talk to Valsirenn 5"] =
			{appendText=" in the main gallery of Ceporah Tower.", stepTextKey="I made deals with both of the betrayed Princes. I should return to Artaeum and talk to Valsirenn. She needs to hear what happened, and I should see if the Psijics have figured out how to use the diamond keys yet."},
		[34] = 
			{appendStepText="In the main gallery of Ceporah Tower on Artaeum, ", stepTextKey="I told Valsirenn that Clavicus Vile has agreed to get us to the Crystal Tower through his realm. Now I should let her know that Mephala is considering helping us attune the diamond keys."},
		["Talk to Valsirenn 6"] =
			{appendText=".", stepTextKey="I told Valsirenn that Clavicus Vile has agreed to get us to the Crystal Tower through his realm. Now I should let her know that Mephala is considering helping us attune the diamond keys."},
	},

	[GetQuestName(6126)] = { --"The Crystal Tower" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="I should go to Ceporah Tower on Artaeum and talk to Valsirenn."},
		["Talk to Valsirenn 1"] =
			{appendText=" in the tower's main gallery.", stepTextKey="I should go to Ceporah Tower on Artaeum and talk to Valsirenn."},
		[2] = 
			{appendStepText="On Artaeum, I spoke with Valsirenn. ", stepTextKey="Sotha Sil has asked to speak with me. I should go to his study in Ceporah Tower and talk to him."},
		["Talk to Sotha Sil 1"] =
			{appendText=". I should use the tower's western turquoise portal.", stepTextKey="Sotha Sil has asked to speak with me. I should go to his study in Ceporah Tower and talk to him."},
		[3] = 
			{appendStepText="I spoke with Sotha Sil in his study at Ceporah Tower on Artaeum. We will be gathering in the cave below the tower. ", stepTextKey="Before heading to the Dreaming Cave, I should speak to my companions around the island. This might be my last chance to speak to them before we assault the Crystal Tower."},
		["Talk to Your Companions"] =
			{appendText=". Darien is in the southern chamber of the tower's main gallery. Razum-dar is near the wayshrine. Valsirenn and Leythen are south of the wayshrine, at a small shrine at the foot of the cliffs, up behind the island's Craftworks."},
		[4] = 
			{appendStepText="I visited with my companions on Artaeum. ", stepTextKey="Sotha Sil said to meet him in the Dreaming Cave."},
		["Enter the Dreaming Cave"] =
			{appendText=" at the bottom of the stairs circling Ceporah Tower's main entrance portal."},
		[5] = 
			{appendStepText="On Artaeum, in The Dreaming Cave at the bottom of the stairs circling Ceporah Tower's main entrance portal, ", stepTextKey="Sotha Sil wants me to speak to him when I'm ready to start the assault on the Crystal Tower."},
		["Talk to Sotha Sil 2"] =
			{appendText=".", stepTextKey="Sotha Sil wants me to speak to him when I'm ready to start the assault on the Crystal Tower."},
		[6] = 
			{appendStepText="On Artaeum, ", stepTextKey="Sotha Sil has opened a path for Mephala into the Dreaming Cave. I should observe what happens."},
		["Attend the Meeting in the Dreaming Cave"] =
			{appendText=" at the bottom of the stairs circling Ceporah Tower's main entrance portal."},
		[7] = 
			{appendStepText="On Artaeum, in the cave below Ceporah Tower, ", stepTextKey="Mephala stepped out of the Dreaming Cave and called me forward. I should speak to the Daedric Prince."},
		["Talk to Mephala"] =
			{appendText="."},
		[8] = 
			{appendStepText="", stepTextKey="Mephala forged the two Resolute Diamonds into a single gem that serves as both an anchor and a key. I should wait while the portal to Clavicus Vile's realm opens."},
		["Wait for the Portal to Reset"] =
			{appendText="."},
		[9] = 
			{appendStepText="In The Dreaming Cave at the bottom of the stairs circling Ceporah Tower's main entrance portal, ", stepTextKey="I should follow Barbas to Clavicus Vile's realm so he can show us the way to the Crystal Tower."},
		["Follow Barbas into the Fields of Regret"] =
			{appendText=" through the portal, leaving Artaeum behind."},
		[10] = 
			{appendStepText="From The Dreaming Cave below Artaeum's Ceporah Tower, I arrived with Leythen and Darien in a portion of Vile's realm. ", stepTextKey="Despite our agreement with Clavicus Vile, it looks like we're going to have to fight our way to the Crystal Tower."},
		["Reach the Entrance of the Crystal Tower"] =
			{appendText=" at the southeastern end of the path."},
		[11] = 
			{appendStepText="In Vile's Fields of Regret, we reached the southeastern tower. ", stepTextKey="Barbas wants to talk to me. I should see what he has to say."},
		["Talk to Barbas"] =
			{appendText=" at his master's entrance to the Crystal Tower."},
		[12] = 
			{appendStepText="At the southeastern end of Vile's Fields of Regret, we entered the tower. ", stepTextKey="The Resolute Anchor serves as both a key to the Crystal Tower and an anchor to our reality. Since I have it, we should be able to enter the Crystal Tower."},
		["Enter the Crystal Tower"] =
			{appendText="."},
		[13] = 
			{appendStepText="After using The Dreaming Cave's portal below Artaeum's Ceporah Tower, we entered the tower in the southeast of Vile's realm. ", stepTextKey="We need to reach the top of the Crystal Tower to confront Nocturnal."},
		["Ascend the Crystal Tower 1"] =
			{appendText=".", stepTextKey="We need to reach the top of the Crystal Tower to confront Nocturnal."},
		[14] = 
			{appendStepText="We entered a large chamber in the Crystal Tower. ", stepTextKey="This artifact vault is surprisingly free of Nocturnal's shadow creatures. But I also don't see a way to continue our journey to the top of the tower. I need to find an exit."},
		["Find a Way Out of the Artifact Vault"] =
			{appendText="."},
		[15] = 
			{appendStepText="In the Artifact Vault of the Crystal Tower, we found someone. ", stepTextKey="A Sapiarch, and she's still alive. I should talk to her."},
		["Talk to the Sapiarch"] =
			{appendText=" in a chamber at the north end of the vault's main floor."},
		[16] = 
			{appendStepText="In the Artifact Vault of the Crystal Tower, Leythen eased the pain of the sage we met. ", stepTextKey="The dying Sapiarch mentioned a broken ballista. If I can find it and repair it, I might be able to use it to clear the debris that's blocking the path up the tower."},
		["Find the Broken Ballista"] =
			{appendText=". If the blocked passage is above the main Vault area, maybe the ancient ballista the sage mentioned is up there, too."},
		[17] = 
			{appendStepText="In the Crystal Tower's Artifact Vault, Darien looked at the ancient ballista on the upper walkway. ", stepTextKey="The ballista isn't broken, it just needs to be reassembled. I should locate the missing pieces so Darien can put it back together."},
		["Find the Missing Pieces to the Ballista"] =
			{appendText=". I should search the main floor chambers to the northeast, the southeast, and the southwest. We need a coil of rope, a ballista crank, and ballista bolts."},
		[18] = 
			{appendStepText="In the Crystal Tower's Artifact Vault, ", stepTextKey="I gathered the parts to repair the ballista. I need to bring them back to Darien so he can put the siege engine into working order."},
		["Bring the Ballista Parts to Darien"] =
			{appendText=" at the ancient ballista up on the Vault's walkway."},
		[19] = 
			{appendStepText="Up on the walkway in the Crystal Tower's Artifact Vault, Darien reassembled the ancient ballista. ", stepTextKey="The ballista is ready. I should be able to use it to open the way forward now."},
		["Use the Ballista on the Blocked Passage"] =
			{appendText=" to break up the rubble at the walkway's southern doorway."},
		[20] = 
			{appendStepText="On the upper walkway of the Crystal Tower's Artifact Vault, I used the repaired ballista to clear the rubble blocking the southern exit. ", stepTextKey="We need to ascend the tower to confront Nocturnal."},
		["Ascend the Crystal Tower 2"] =
			{appendText=" by first entering the Tower Library.", stepTextKey="We need to ascend the tower to confront Nocturnal."},
		[21] = 
			{appendStepText="In the Crystal Tower, we left the Artifact Vault through a door on its upper walkway. ", stepTextKey="This appears to be the tower's library. We need to find a way to move forward."},
		["Find a Way Through the Library"] =
			{appendText=". I should check the north end of the library's main floor first. "},
		[22] = 
			{appendStepText="In the Crystal Tower's Library, we found a gate key. ", stepTextKey="The library's gate is closed. We need to find a way through it if we want to continue."},
		["Open the Library Gate"] =
			{appendText=". Upstairs on the library's west side is the key pedestal that unlocks the gate. The gate is on the upper east side."},
		[23] = 
			{appendStepText="In the Crystal Tower's Libary, I found the gate key. ", stepTextKey="Leythen seems to know how this gate mechanism works. I should talk to him."},
		["Talk to Earl Leythen 1"] =
			{appendText=" by the key pedestal up on the library's western walkway.", stepTextKey="Leythen seems to know how this gate mechanism works. I should talk to him."},
		[24] = 
			{appendStepText="In the Crystal Tower's Library, ", stepTextKey="Leythen managed to get the gate open. Now we just have to get behind it before his magic fades."},
		["Get Through the Opened Gate"] =
			{appendText=" on the Library's upper east side."},
		[25] = 
			{appendStepText="In the Crystal Tower's Library, ", stepTextKey="Leythen wasn't able to get through the gate before it closed. I should talk to him."},
		["Talk to Earl Leythen 2"] =
			{appendText=" at the Library's gate.", stepTextKey="Leythen wasn't able to get through the gate before it closed. I should talk to him."},
		[26] = 
			{appendStepText="We must leave the Crystal Tower's Library. ", stepTextKey="Our only way is up. We need to find our way to stop Nocturnal."},
		["Ascend the Tower"] =
			{appendText=" by going west through its Mausoleum to reach the Tower's Summit."},
		[27] = 
			{appendStepText="On our way to the Crystal Tower's Summit, ", stepTextKey="Nocturnal's champion stands in our way with the corrupted Dawnbreaker sword. We need to stop her before we can continue."},
		["Defeat Nocturnal's Champion"] =
			{appendText="."},
		[28] = 
			{appendStepText="I defeated Nocturnal's champion in the antechamber of the Crystal Tower's Summit. ", stepTextKey="We retrieved the Dawnbreaker sword, but it has been corrupted by Nocturnal. I should talk to Darien to see if he can restore the blade."},
		["Talk to Darien Gautier"] =
			{appendText="."},
		[29] = 
			{appendStepText="I defeated Nocturnal's champion in the antechamber of the Crystal Tower's Summit. Then I spoke with Darien. ", stepTextKey="We need to find a way to cleanse the Dawnbreaker."},
		["Cleanse the Dawnbreaker"] =
			{appendText="."},
		[30] = 
			{appendStepText="In the antechamber of the Crystal Tower's Summit, ", stepTextKey="Darien sacrificed himself to restore the power of the Dawnbreaker. I should retrieve the restored sword."},
		["Take the Restored Dawnbreaker"] =
			{appendText="."},
		[31] = 
			{appendStepText="In the antechamber of the Crystal Tower's Summit, Darien gave his divine energy to restore the sword. Now, ", stepTextKey="I have the Dawnbreaker in my possession. The only thing left is to climb the tower and confront Nocturnal once and for all."},
		["Use the Dawnbreaker to Confront Nocturnal"] =
			{appendText=". I should go through the Pinnacle of Transparent Law and use a portal to reach the Summit's apex."},
		[32] = 
			{appendStepText="At the Crystal Tower's Summit, ", stepTextKey="I need to put a stop to Nocturnal and use the Dawnbreaker on the tower crystal when the time is right."},
		["Stop Nocturnal"] =
			{appendText="."},
		[33] = 
			{appendStepText="At the Crystal Tower's Summit, ", stepTextKey="Nocturnal has once again sent her champion against me. I need to defeat her."},
		["Destroy Nocturnal's Shadow"] =
			{appendText="."},
		[34] = 
			{appendStepText="At the apex of the Crystal Tower's Summit, I defeated the Daedric Prince's minions and shadows. ", stepTextKey="Nocturnal is weakened. I need to use the Dawnbreaker on the crystal called Transparent Law before she can recover."},
		["Reforge Transparent Law"] =
			{appendText=" by using the Dawnbreaker at the crystal's pedestal."},
		[35] = 
			{appendStepText="", stepTextKey="Nocturnal has been banished. The Transparent Law crystal has been restored, and for now, it seems the threat has ended. Valsirenn has been able to get into the tower though, so I should speak to her and find out what's happening."},
		["Talk to Valsirenn 2"] =
			{appendText=" near the portal she opened at the Crystal Tower's Summit. ", stepTextKey="Nocturnal has been banished. The Transparent Law crystal has been restored, and for now, it seems the threat has ended. Valsirenn has been able to get into the tower though, so I should speak to her and find out what's happening."},
		[36] = 
			{appendStepText="I spoke with Valsirenn briefly at the Summit of the Crystal Tower. ", stepTextKey="We stopped Nocturnal. We should leave and let the others know of our success."},
		["Leave the Crystal Tower"] =
			{appendText=" and return to Artaeum to speak with Sotha Sil."},
		[37] = 
			{appendStepText="On Artaeum, in The Dreaming Cave at the bottom of the stairs circling Ceporah Tower's main entrance portal, ", stepTextKey="Sotha Sil awaits. I should speak to him and tell him of our success."},
		["Talk to Sotha Sil 3"] =
			{appendText=".", stepTextKey="Sotha Sil awaits. I should speak to him and tell him of our success."},
		[38] = 
			{appendStepText="On Artaeum, in The Dreaming Cave at the bottom of the stairs circling Ceporah Tower's main entrance portal, ", stepTextKey="Sotha Sil awaits. I should speak to him and tell him of our success."},
		["Talk to Sotha Sil 4"] =
			{appendText=".", stepTextKey="Sotha Sil awaits. I should speak to him and tell him of our success."},
	},

	[GetQuestName(6153)] = { --"A New Alliance"		--Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Valsirenn wishes to ensure the Crystal Tower stays protected now that we've saved it. She's requested I speak to her in the Dreaming Cave to discuss her plans."},
		["Talk to Valsirenn 1"] =
			{appendText=" in the Dreaming Cave at the bottom of the stairs circling Ceporah Tower's main entrance portal on Artaeum.", stepTextKey="Valsirenn wishes to ensure the Crystal Tower stays protected now that we've saved it. She's requested I speak to her in the Dreaming Cave to discuss her plans."},
		[2] = 
			{appendStepText="I spoke with Valsirenn in the Dreaming Cave on Artaeum. ", stepTextKey="I need to speak to Oriandra and ask her to send messages to influential members of the Summerset Isles."},
		["Talk to Oriandra 1"] =
			{appendText=" at Ceporah Tower, in the main gallery's central chamber.", stepTextKey="I need to speak to Oriandra and ask her to send messages to influential members of the Summerset Isles."},
		[3] = 
			{appendStepText="On Artaeum at Ceporah Tower, I spoke with Oriandra. ", stepTextKey="I need to speak to Sotha Sil before he leaves and ask him if he will join us for the council meeting."},
		["Talk to Sotha Sil"] =
			{appendText=". I should use the main gallery's western turquoise portal to reach his study."},
		[4] = 
			{appendStepText="The Clockwork God returned to his city. Now I should go to Summerset. ", stepTextKey="Oriandra asked me to meet her in front of the Royal Palace in Alinor. I should go there as soon as possible."},
		["Go to the Royal Palace in Alinor"] =
			{appendText=", the Blessed Isle's western city. The palace towers above the city from its perch in the northeast."},
		[5] = 
			{appendStepText="Up in northeast Alinor, ", stepTextKey="Oriandra is waiting for me in front of the Royal Palace in Alinor. I should talk to her."},
		["Talk to Oriandra 2"] =
			{appendText=" at the top of the steps.", stepTextKey="Oriandra is waiting for me in front of the Royal Palace in Alinor. I should talk to her."},
		[6] = 
			{appendStepText="I arrived at the Royal Palace up in northeast Alinor. ", stepTextKey="The meeting has already begun. I should make my way inside and try to convince the Sapiarchs."},
		["Attend the Palace Meeting"] =
			{appendText=" being held in the palace's southeastern Council Chamber."},
		[7] = 
			{appendStepText="In northeast Alinor, I joined the meeting at the Royal Palace. ", stepTextKey="Sapiarch Larnatille refuses to accept assistance in protecting the Crystal Tower. I should try and speak to her to see if I can convince her otherwise."},
		["Talk to Sapiarch Larnatille 1"] =
			{appendText=" in the palace's Council Chamber.", stepTextKey="Sapiarch Larnatille refuses to accept assistance in protecting the Crystal Tower. I should try and speak to her to see if I can convince her otherwise."},
		[8] = 
			{appendStepText="In northeast Alinor, I am attending a meeting at the Royal Palace. ", stepTextKey="It appears Razum-dar and Oriandra have summoned those who I've helped from across Summerset to vouch for me. I should listen as they make their case."},
		["Listen to Your Allies"] =
			{appendText=" as they speak in the palace's Council Chamber."},
		[9] = 
			{appendStepText="In northeast Alinor, I am attending a meeting in the Council Chamber at the Royal Palace. ", stepTextKey="Now that everyone has vouched for me, I need to speak to the Sapiarch and see if she'll reconsider getting additional help to protect the Crystal Tower."},
		["Talk to Sapiarch Larnatille 2"] =
			{appendText=".", stepTextKey="Now that everyone has vouched for me, I need to speak to the Sapiarch and see if she'll reconsider getting additional help to protect the Crystal Tower."},
		[10] = 
			{appendStepText="In northeast Alinor, I attended a meeting in the Council Chamber at the Royal Palace. ", stepTextKey="I managed to convince the Sapiarchs to accept help protecting the Crystal Tower, but Valsirenn still has something to tell me. I should speak to her."},
		["Talk to Valsirenn 2"] =
			{appendText=".", stepTextKey="I managed to convince the Sapiarchs to accept help protecting the Crystal Tower, but Valsirenn still has something to tell me. I should speak to her."},
		[11] = 
			{appendStepText="In northeast Alinor, the meeting has concluded in the Council Chamber at the Royal Palace. ", stepTextKey="Valsirenn has informed me that the Psijic Order will be leaving Summerset. Now that I've said goodbye, I should go to the throne room and speak to Razum-dar."},
		["Talk to Razum-dar 1"] =
			{appendText=", the Eye of the Queen.", stepTextKey="Valsirenn has informed me that the Psijic Order will be leaving Summerset. Now that I've said goodbye, I should go to the throne room and speak to Razum-dar."},
		[12] = 
			{appendStepText="In northeast Alinor, the meeting in the Council Chamber at the Royal Palace has ended. ", stepTextKey="Though the meeting was successful, Razum-dar still wishes to speak to me. I should see what he has to tell me."},
		["Talk to Razum-dar 2"] =
			{appendText=" in the throne room.", stepTextKey="Though the meeting was successful, Razum-dar still wishes to speak to me. I should see what he has to tell me."},
	},

-- 		=========================================================================
--		  Artaeum  - Main Quest 
-- 		=========================================================================

	[GetQuestName(6172)] = { --"The Psijics' Calling"	--Jordakai
		[1] = 
			{appendStepText="Celarus is the chief Loremaster in Artaeum. ", stepTextKey="I must go speak with Loremaster Celarus' apprentice, Josajeh, in the Athenaeum. She should be able to direct me to the objects I need to complete my task."},
		["Talk to Josajeh 1"] =
			{appendText=" in the Ceporah Tower.  The Athenaeum is a large room between the portals to the Ritemaster's Study and Sotha Sil's Study.\n", stepTextKey="I must go speak with Loremaster Celarus's apprentice, Josajeh, in the Athenaeum. She should be able to direct me to the objects I need to complete my task."},
		[2] = 
			{appendStepText="He sent me to his assistant, Josajeh, in a large room between the portals to Sotha Sil's study and the Ritemaster's Study. She has everything I should need to complete this task.\n\n", stepTextKey="Josajeh transcribed a map of Summerset that details the approximate locations of the time breaches I need to seal. I should take it."},
		["Take the Psijic Map of Summerset"] =
			{appendText=" from the desk in front of the small painting of a tower."},
		[3] = 
			{appendStepText="His assistant gave me some of the items I need for the task. ", stepTextKey="Now that I have the Psijic Map of Summerset and the Psijic Seals, I need to track down the final item—the Augur of the Obscure. According to Josajeh, I'll find it somewhere along the coast of Wasten Coraldale."},
		["Find the Augur of the Obscure"] =
			{appendText=" on the island Josajeh mentioned. A small boat on the coast north of Alinor will take you there. The boat is between a large rock and a long stone jetty.\n\nThe Augur was captured by smugglers and locked in a chest. They have a tented camp on the beach, on the far east of the island, but the chest has been left unattended under a tree a little further along."},
		[4] = 
			{appendStepText="His assistant gave me a map and some seals, but not the Augur of the Obscure, which I need to actually see the time rifts. It escaped and was captured by smugglers in Wasten Coraldale.\n\n", stepTextKey="I discovered the talkative Augur of the Obscure hidden in a chest. I should talk to it."},
		["Talk to The Augur of the Obscure"] =
			{appendText=" after freeing it from the chest. The smugglers' tented camp is on the shore at the far eastern end of the island, but their captive has been left unguarded under a small tree a little further along."},
		[5] = 
			{appendStepText="", stepTextKey="The Psijic Order has marked the possible location of time breaches in Summerset on the map Josajeh gave me. I should look at the map so I know where to start my journey."},
		["Inspect the Psijic Map of Summerset"] =
			{appendText=" in your backpack. It's a very detailed quest item."},
		[6] = 
			{appendStepText="I have a map in my backpack, I have seals, and I have an Augur of the Obscure to help me see the time rifts. Now, ", stepTextKey="I should travel to Summerset to begin my search for the time breaches."},
		["Return to Summerset"] =
			{appendText=" to start searching for the time breaches. The map in your backpack shows several dotted around the coastline of the island. A disciplined approach will be needed, and a good starting point looks like Alinor or Shimmerene."},
		[7] = 
			{appendStepText="", stepTextKey="I sealed the time breaches that appeared on Summerset Isle. I must return to Loremaster Celarus on Artaeum and update him on my progress."},
		["Talk to Loremaster Celarus"] =
			{appendText=" in Artaeum. He's in a large room in the Ceporah tower, between the portals to Valsirenn's study and the Ritemaster's study. There's an undisclosed portal at its center, and doors with mystic seals on several walls."},
		[8] = 
			{appendStepText="I've sealed them all and returned to Artaeum to give my report. ", stepTextKey="Loremaster Celarus urged me to speak with his apprentice, Josajeh. I should meet with her in the Athenaeum."},
		["Talk to Josajeh 2"] =
			{appendText=" in the Ceporah Tower. The Athenaeum is a large room between the portals to The Ritemaster's Study and Sotha Sil's Study.", stepTextKey="Loremaster Celarus urged me to speak with his apprentice, Josajeh. I should meet with her in the Athenaeum."},
		[9] = 
			{appendStepText="", stepTextKey="I must use the map Josajeh provided and the Augur of the Obscure to find the time breaches on Summerset Isle. Activating a Psijic Seal near a breach should repair the veil and close the gap."},
		["Seal Time Breaches on Summerset Isle"] =
			{appendText=" \n\nUse the map in your backpack. The locations of the breaches are clearly marked on it, but you will need a disciplined approach. The Augur of the Obscure will alert you when you approach one, listen carefully to what it says. The open time rifts become quite distinctive when the Augur is active, and you will see a black haze with a blue aura.", stepTextKey="I must use the map Josajeh provided and the Augur of the Obscure to find the time breaches on Summerset Isle. Activating a Psijic Seal near a breach should repair the veil and close the gap."},
},

    [GetQuestName(6181)] = { --"Breaches On the Bay"	--Jordakai
        [1] = 	
            {appendStepText="Alik'r is her homeland, and she's naturally worried about it. There is little she can do here in Artaeum, other than give me the tools I need to seal the breaches. ", stepTextKey="I should talk to Josajeh before I set out."},
        ["Talk to Josajeh 1"] =
            {appendText=" in the Ceporah Tower. She's in a large room between the portals to Sotha Sil's study and the Ritemaster's study.", stepTextKey="I should talk to Josajeh before I set out."},
        [2] = 
            {appendStepText="Alik'r is her homeland, and she's naturally worried about this threat. She's given me everything I need to seal the breaches and ease her mind. First, ", stepTextKey="I should review the map of Time Breaches around the Iliac Bay and plan my route."},
        ["Examine the Psijic Map"] =
            {appendText=" in your backpack. You will notice the breaches cover all the lands around the bay: Glenumbra, Stormhaven and Alik'r. It would be best to complete an area before moving on to the next one."},
        [3] = 
            {appendStepText="Glenumbra, Stormhaven and Alik'r seem to be affected. ", stepTextKey="Josajeh furnished me with a new map, more Psijic Seals, and the Augur of the Obscure. I must set out for the Iliac Bay and seal these time breaches."},
        ["Seal Breaches in the Iliac Bay Region"] =
            {appendText=" \n\nUse the map in your backpack. The locations of the breaches are clearly marked on it. The Augur of the Obscure will alert you when you approach one, listen carefully to what it says. The  time rifts become quite distinctive when the Augur is active, and you will see a black haze with a blue aura.\n\nIt would be sensible to tackle one area at a time."},
        [4] = 
            {appendStepText="", stepTextKey="I sealed all the time breaches around the Iliac Bay. I should return to Artaeum and inform Josajeh of my success."},
        ["Talk to Josajeh 2"] =
            {appendText=" in the Ceporah tower in Artaeum. She's in a large room between the portals to the studies of Sotha Sil and the Ritemaster.", stepTextKey="I sealed all the time breaches around the Iliac Bay. I should return to Artaeum and inform Josajeh of my success."},
    },

    [GetQuestName(6185)] = { --"Breaches of Frost and Fire"	--Jordakai
        [1] = 
            {appendStepText="I returned to Artaeum after sealing the breaches in Glenumbra, Stormhaven, and the Alik'r Desert. I have the Augur of the Obscure with me, but I need a new map. ", stepTextKey="I should talk to Josajeh before I set out."},
        ["Talk to Josajeh"] =
            {appendText=" in the Athenaeum in Ceporah Tower. It is the southwestern chamber between the portal to Sotha Sil's Study and the portal to the Ritemaster's Study."},
        [2] = 
            {appendStepText="In Ceporah Tower on Artaeum, I spoke with Josajeh in the Athenaeum, the southwestern chamber between the portals to the studies of Sotha Sil and the Ritemaster.\n\nShe mentioned a powerful staff they are researching. Before I go, ", stepTextKey="I should review the map of Time Breaches in Stonefalls, Eastmarch, and The Rift to plan my route."},
        ["Examine the Psijic Map"] =
            {appendText=" of Morrowind and Skyrim she gave me. It's in my backpack and, like the previous map, has marks showing me where breaches should be, this time in the lands of Stonefalls, Eastmarch, and The Rift."},
        [3] = 
            {appendStepText="Josajeh provided me with more Psijic Seals and a new map. Now, ", stepTextKey="I must explore the lands of Eastmarch, The Rift, and Stonefalls. My map should help narrow the search. Once I arrive at the X, I must use the Augur to find the breach and the Psijic Seals to close it."},
        ["Seal Breaches in Stonefalls and Skyrim"] =
            {appendText=" \n\nThe Augur of the Obscure will alert me when I am near a breach. I should listen carefully to what it says. With the Augur active, time breaches will appear as a black haze with a blue aura."},
        [4] = 
            {appendStepText="I returned to Ceporah Tower on Artaeum since ", stepTextKey="I successfully sealed all the time breaches in Eastmarch, The Rift, and Stonefalls. I should return to Loremaster Celarus. Josajeh said he'd like to speak with me."},
        ["Talk to Loremaster Celarus"] =
            {appendText=" in his eastern Chamber of Observation, between the portals to Valsirenn's quarters and The Ritemaster's Study."},
        [5] = 
            {appendStepText="In Ceporah Tower on Artaeum, ", stepTextKey="I must talk to Loremaster Celarus to complete my task."},
        ["Talk to Celarus"] =
            {appendText=" in his eastern Chamber of Observation."},
    },

    [GetQuestName(6197)] = { --"The Shattered Staff"	--Jordakai
        [1] = 
            {appendStepText="In his eastern chamber at Ceporah Tower on Artaeum, ", stepTextKey="Loremaster Celarus indicated I should talk to Josajeh before I set out."},
        ["Talk to Josajeh"] =
            {appendText=" in the Athenaeum, the tower's southwestern chamber between the portals to Sotha Sil's Study and the Ritemaster's Study."},
        [2] = 
            {appendStepText="At the Loremaster's request, I spoke with Josajeh about the staff and the fragment locations. And I have the Augur of the Obscure with me. I should find time breaches to close and then follow any clues to find the fragments. ", stepTextKey="I should travel to the four locations Loremaster Celarus mentioned and find the Staff fragments hidden there."},
        ["Find the Fragment near Pelin Graveyard"] =
            {appendText=" southwest of Evermore in northeastern Bangkorai. There is a time breach behind the graveyard's Pelin Chapel. After I close it, I should be guided to a mound of dense earth by a tree, north of the nearby crossroads."},
        ["Find the Fragment near Leki's Blade"] =
            {appendText=" near the central city of the Alik'r Desert. A time breach is up in the sandy cliffs at the foot of the tall rock formation known as Leki's Blade, southwest of the city's wayshrine. Once closed, I should be guided to a mound of dense earth by a palm at a boulder southwest of Aswala's Remembrance and west of Sep's Spine."},
        ["Find the Fragment near the Hist"] =
            {appendText=" at the center of the Hatching Pools in central Shadowfen. A time breach is underneath the sacred Hist Tree. Once closed, I will be guided to a hilltop with two tall trees, on the west side of the lake in the horseshoe road north of the southern city of Hissimir."},
        ["Find the Fragment near Fang Spires"] =
            {appendText=" on a hilltop southwest of the Silent Mire Wayshrine and far south of the eastern city of Selfora in Deshaan. Between the two fang spires, a time breach can be closed. Then I should follow the guiding path to the dense earth mound in a patch of large mushrooms in front of Taleon's Crag."},
        [3] = 
            {appendStepText="Adamantine, orichalc, crystal, and walk-brass. ", stepTextKey="I collected all four staff fragments. I should return to Artaeum and deliver them to Loremaster Celarus."},
        ["Talk to Loremaster Celarus"] =
            {appendText=" in his eastern Chamber of Observation, between the portals to the studies, at Ceporah Tower on Artaeum."},
        [4] = 
            {appendStepText="Adamantine, orichalc, crystal, and walk-brass. ", stepTextKey="I collected all four staff fragments and delivered them to Loremaster Celarus. I should talk to him to receive my reward."},
        ["Talk to Celarus"] =
            {appendText=", the Loremaster, in his eastern chamber at Ceporah Tower on Artaeum."},
    },

    [GetQuestName(6194)] = { --"A Breach Amid the Trees" --Jordakai
        [1] = 
            {appendStepText="I spoke with the Loremaster in his eastern chamber in Ceporah Tower on Artaeum. ", stepTextKey="Celarus would like me to talk to Josajeh before I set out. I can find her in the Athenaeum."},
        ["Talk to Josajeh 1"] =
            {appendText=". The Athenaeum is the southwestern chamber between the portal to Sotha Sil's Study and the portal to the Ritemaster's Study.", stepTextKey="Celarus would like me to talk to Josajeh before I set out. I can find her in the Athenaeum."},
        [2] = 
            {appendStepText="At the Athenaeum, the southwestern chamber of Ceporah Tower on Artaeum, Josajeh gave me more Psijic Seals and a map. ", stepTextKey="I should review the map of Time Breaches in Valenwood and plan my route."},
        ["Examine the Psijic Map"] =
            {appendText=" of Grahtwood, Greenshade, and Malabal Tor. It's in my backpack and has marks showing me where breaches should be."},
        [3] = 
            {appendStepText="The map I carry in my backpack shows Grahtwood, Greenshade, and Malabal Tor. ", stepTextKey="I must travel to Valenwood and use the Psijic Seals to close the time breaches that appeared there."},
        ["Seal Breaches in Valenwood"] =
            {appendText=" \n\nThe Augur of the Obscure will alert me when I am near a breach. I should listen carefully to what it says. With the Augur active, time breaches will appear as a black haze with a blue aura."},
        [4] = 
            {appendStepText="I returned to Ceporah Tower on Artaeum since ", stepTextKey="I successfully sealed all the time breaches in Grahtwood, Greenshade, and Malabal Tor. I should return to Josajeh to inform her of my success."},
        ["Talk to Josajeh 2"] =
            {appendText=" in the Athenaeum, the southwestern chamber of the tower, between the portals for the studies of Sotha Sil and the Ritemaster.", stepTextKey="I successfully sealed all the time breaches in Grahtwood, Greenshade, and Malabal Tor. I should return to Josajeh to inform her of my success."},
        [5] = 
            {appendStepText="In the book-filled southwestern chamber of Ceporah Tower on Artaeum, ", stepTextKey="I should talk to Josajeh to receive my reward."},
        ["Talk to Josajeh 3"] =
            {appendText=" in the Athenaeum.", stepTextKey="I should talk to Josajeh to receive my reward."},
    },

    [GetQuestName(6190)] = { --"A Time for Mud and Mushrooms" --Jordakai
        [1] = 
            {appendStepText="I spoke with Josajeh in the Athenaeum at Ceporah Tower on Artaeum. She gave me a new map and more Psijic Seals for my backpack. And I have the Augur with me, too. ", stepTextKey="I should talk to Loremaster Celarus before I set out for Deshaan and Shadowfen."},
        ["Talk to Loremaster Celarus 1"] =
            {appendText=" in his eastern Chamber of Observation.", stepTextKey="I should talk to Loremaster Celarus before I set out for Deshaan and Shadowfen."},
        [2] = 
            {appendStepText="In his eastern Chamber of Observations at Ceporah Tower on Artaeum, I discussed our progress with the Loremaster. Celarus mentioned that keeping the four staff fragments separated is proving difficult.\n\nAs I have more breaches to seal, ", stepTextKey="I should review the map of Time Breaches in Shadowfen and Deshaan and plan my route."},
        ["Examine the Psijic Map"] =
            {appendText=" of Black Marsh I have in my backpack. It has marks showing me where I should go."},
        [3] = 
            {appendStepText="My map covers the northern edges of Black Marsh. ", stepTextKey="I must explore the lands of Shadowfen and Deshaan to find and seal these breaches in time."},
        ["Seal Breaches North of Black Marsh"] =
            {appendText=" \n\nThe Augur of the Obscure will alert me when I am near a breach. I should listen carefully to what it says. With the Augur active, time breaches will appear as a black haze with a blue aura."},
        [4] = 
            {appendStepText="I returned to Ceporah Tower on Artaeum since ", stepTextKey="I sealed the time breaches north of Black Marsh. I should return to Josajeh and share the good news."},
        ["Talk to Josajeh"] =
            {appendText=" in the Athenaeum, the southwestern chamber of the tower, between the portals for the studies of Sotha Sil and the Ritemaster."},
        [5] = 
            {appendStepText="I spoke with Josajeh in the Athenaeum in Ceporah Tower on Artaeum. Now, ", stepTextKey="I should go speak with Loremaster Celarus. Hopefully he knows the locations of the four remaining staff fragments."},
        ["Talk to Loremaster Celarus 2"] =
            {appendText=" in his Chamber of Observation in the tower's east.", stepTextKey="I should go speak with Loremaster Celarus. Hopefully he knows the locations of the four remaining staff fragments."},
    },

    [GetQuestName(6198)] = { --"The Towers' Remains" --Jordakai
        [1] = 
            {appendStepText="When I spoke with the Loremaster at Ceporah Tower on Artaeum, he advised me to bring the remaining four fragments directly to him. I will be using the Augur of the Obscure again. It's in my backpack. Now, ", stepTextKey="I should travel to the four locations Loremaster Celarus mentioned and find the staff fragments hidden there."},
        ["Find Fragment Near the Brothers of Strife"] =
            {appendText=" in central Stonefalls, south of Ebonheart. The mundus tear is up on a Deadric platform in a ruin south of the Brothers of Strife Wayshrine. Once closed, I will be guided around to the west, climbing the northeastern slope of the Tormented Spire. Just south of a lava flow, a mound of dense earth is nestled in the steep cliffs."},
        ["Find Fragment Near the Weeping Giant"] =
            {appendText=" in far eastern Stormhaven. The mundus tear is northeast of the Weeping Giant Wayshrine, among the ruins in the wetlands. After closing the tear, I will be guided west to the stone stairs and wooden ramps, up to a small ring of tents by a ruined tower, west of the river. A mound of dense earth hides behind the tallest tree."},
        ["Find Fragment Near Greenheart"] =
            {appendText=" in southern Greenshade. The mundus tear is due north of the Greenheart Wayshrine, just north of the river, not far from a waterfall. Once closed, I will be guided north and west to a small stand of trees near the rocks, due south of Hollow Den. The leafy, green trees hide the mound of dense earth."},
        ["Find Fragment Near Spellscar"] =
            {appendText=" in central Craglorn. The mundus tear is just southwest, below an ancient tower north of Ogandar's Winery and northeast of Spellscar Wayshrine. I will be guided around the south side of the gigantic Spellscar obelisk to its northwestern side. A mound of dense earth lies beneath a dead tree."},
        [2] = 
            {appendStepText="Snow Throat, Green Sap, Red Staff, and White-Gold Staff. ", stepTextKey="I collected all four staff fragments. I should return to Artaeum and deliver them to Loremaster Celarus."},
        ["Talk to Loremaster Celarus 1"] =
            {appendText=" in his eastern Chamber of Observation at Ceporah Tower.", stepTextKey="I collected all four staff fragments. I should return to Artaeum and deliver them to Loremaster Celarus."},
        [3] = 
            {appendStepText="In Ceporah Tower on Artaeum, ", stepTextKey="I should talk to Loremaster Celarus to receive my reward."},
        ["Talk to Loremaster Celarus 2"] =
            {appendText=" in his eastern chamber, between portals to Valsirenn's quarters and the Ritemaster's Study.", stepTextKey="I should talk to Loremaster Celarus to receive my reward."},
    },

   [GetQuestName(6195)] = { --"Time in Doomcrag's Shadow" --Jordakai
        [1] = 
            {appendStepText="On Artaeum, ", stepTextKey="I should talk to Josajeh and collect the tools I need to seal these breaches."},
        ["Talk to Josajeh"] =
            {appendText=" in the Athenaeum, the southwestern chamber of Ceporah Tower."},
        [2] = 
            {appendStepText="I met with Josajeh in the Athenaeum at Ceporah Tower on Artaeum. I put the map and Psijic Seals in my pack with the Augur. ", stepTextKey="I should review the map of Time Breaches in Rivenspire and plan my route."},
        ["Examine the Psijic Map"] =
            {appendText=" of Rivenspire with its marks showing me where the breaches should be."},
        [3] = 
            {appendStepText="Now that I have what I need, ", stepTextKey="I should travel to Rivenspire and seal any time breaches I find there."},
        ["Seal Breaches in Rivenspire"] =
            {appendText=" \n\nThe Augur of the Obscure will alert me when I am near a breach. I should listen carefully to what it says. With the Augur active, time breaches will appear as a black haze with a blue aura."},
        [4] = 
            {appendStepText="I returned to Ceporah Tower on Artaeum, since ", stepTextKey="I sealed all the time breaches in Rivenspire. I should return to Loremaster Celarus and inform him of my success."},
        ["Talk to Loremaster Celarus 1"] =
            {appendText=" in his eastern chamber, between the portals to Valsirenn's quarters and the Ritemaster's Study.", stepTextKey="I sealed all the time breaches in Rivenspire. I should return to Loremaster Celarus and inform him of my success."},
        [5] = 
            {appendStepText="In his eastern chamber at Ceporah Tower on Artaeum, ", stepTextKey="I should speak with Loremaster Celarus so I can collect my reward."},
        ["Talk to Loremaster Celarus 2"] =
            {appendText=".", stepTextKey="I should speak with Loremaster Celarus so I can collect my reward."},
    },

    [GetQuestName(6196)] = { --"A Breach Beyond the Crags" --Jordakai
        [1] = 
            {appendStepText="In the eastern chamber of Ceporah Tower on Artaeum, I spoke with the Loremaster about their research on the staff. ", stepTextKey="I should talk to Josajeh. She can give me the equipment I need, and she probably has a lot to say about our current situation."},
        ["Talk to Josajeh"] =
            {appendText=" in the Athenaeum. She should have the Augur, the Psijic Seals, and the Map of Craglorn I will need."},
        [2] = 
            {appendStepText="At Ceporah Tower on Artaeum, I packed the Augur, map, and seals. Josajeh is struggling with the Order having the staff fragments. Me? ", stepTextKey="I should review the map of Time Breaches in Craglorn and plan my route."},
        ["Examine the Psijic Map"] =
            {appendText=" of Craglorn. As usual, the locations for the time breaches are marked, but only six this time."},
        [3] = 
            {appendStepText="Now that I have the Augur, map, and seals, ", stepTextKey="I must explore the land of Craglorn and seal any time breaches I find."},
        ["Seal Breaches in Craglorn"] =
            {appendText=" \n\nThe Augur of the Obscure will alert me when I am near a breach. I should listen carefully to what it says. With the Augur active, time breaches will appear as a black haze with a blue aura."},
        [4] = 
            {appendStepText="", stepTextKey="As soon as I sealed the final time breach in Craglorn, Loremaster Celarus appeared. He urged me to return to Artaeum at once. I should hurry back and find out what's happened."},
        ["Talk to Loremaster Celarus 1"] =
            {appendText=" at Ceporah Tower on Artaeum. He should be in the tower's eastern chamber.", stepTextKey="As soon as I sealed the final time breach in Craglorn, Loremaster Celarus appeared. He urged me to return to Artaeum at once. I should hurry back and find out what's happened."},
        [5] = 
            {appendStepText="In the eastern chamber of Ceporah Tower on Artaeum, ", stepTextKey="I should talk to Loremaster Celarus to receive my reward."},
        ["Talk to Loremaster Celarus 2"] =
            {appendText=".", stepTextKey="I should talk to Loremaster Celarus to receive my reward."},
    },

	[GetQuestName(6199)] = { --"The Towers' Fall" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="According to Loremaster Celarus, his apprentice probably went to a mine called Divad's Chagrin. I should travel to this mine to look for Josajeh."},
		["Find the Time Breach in Divad's Chagrin"] =
			{appendText=" in central Alik'r Desert. The mine is southwest of the ruins of Tu'whacca's Throne. I should follow the road up into the cliffs, north of Divad's Chagrin Mine Wayshrine. The mine's entrance is recessed into the rocks.\n\nI have The Augur of the Obscure and some Psijic Seals in my backpack."},
		[2] = 
			{appendStepText="I entered Divad's Chagrin Mine in central Alik'r Desert. I searched through the mine and was heading for the mine's eastern cavern, but now  ", stepTextKey="The Augur senses a time breach nearby. I must use its sight to locate the time breach."},
		["Use the Augur of the Obscure"] =
			{appendText=" in the mine's eastern cavern."},
		[3] = 
			{appendStepText="I entered Divad's Chagrin Mine in central Alik'r Desert. I reached the mine's eastern cavern. The Augur helped me and ", stepTextKey="I found a gaping time breach that Josajeh likely used as a portal. I should follow her through it to see where (or when) it leads."},
		["Find Josajeh"] =
			{appendText=". It appears I am in an Imperial Throne Room. Josajeh is at a door at the top of the stairs across this large, circular room."},
		[4] = 
			{appendStepText="I entered Divad's Chagrin Mine in central Alik'r Desert. I searched through the mine and reached the mine's eastern cavern, where I entered a major time breach. ", stepTextKey="I found Josajeh in a bizarre alternative version of the Imperial Throne room! I must stop her ritual before it spins completely out of control."},
		["Stop Josajeh"] =
			{appendText=". Alternate realities of Josajeh appear through time breaches. I will need to defend myself and close the breaches."},
		[5] = 
			{appendStepText="I entered Divad's Chagrin Mine in central Alik'r Desert. From the mine's eastern cavern, I entered a major time breach. In the alternative Imperial Throne Room, ", stepTextKey="I turned back the tide of converging time-lines and freed Josajeh from the staff's violent influence. Now that the threat has passed, I should talk to her."},
		["Talk to Josajeh 1"] =
			{appendText=" up on the stairs of the throne room. The Loremaster and Relicmaster have joined us.", stepTextKey="I turned back the tide of converging time-lines and freed Josajeh from the staff's violent influence. Now that the threat has passed, I should talk to her."},
		[6] = 
			{appendStepText="", stepTextKey="Josajeh agreed to respect the Psijics' decision for her future. I should return to Artaeum to see how this plays out."},
		["Return to Artaeum"] =
			{appendText=". I can use the portal the Loremaster and Relicmaster used to find us."},
		[7] = 
			{appendStepText="On Artaeum, ", stepTextKey="I must enter Ceporah Tower to speak with Celarus about everything that happened with Josajeh."},
		["Enter Ceporah Tower"] =
			{appendText="."},
		[8] = 
			{appendStepText="I entered Ceporah Tower on Artaeum. ", stepTextKey="The Augur asked to speak with me privately before I return to Loremaster Celarus. I should take it to the Athenaeum and find out what it wants."},
		["Place the Augur in the Athenaeum"] =
			{appendText=" on the tabletop by the northwestern pillar of the book-filled chamber."},
		[9] = 
			{appendStepText="On Artaeum, ", stepTextKey="I placed the Augur on a table in Ceporah Tower's Athenaeum so we can speak at length."},
		["Talk to the Augur of the Obscure 1"] =
			{appendText=", the glowing crystal-blue skull resting on the tabletop by a pillar in the book-filled chamber.", stepTextKey="I placed the Augur on a table in Ceporah Tower's Athenaeum so we can speak at length."},
		[10] = 
			{appendStepText="In the Athenaeum, the southwestern chamber of Ceporah Tower on Artaeum, ", stepTextKey="I gave the Augur a hearing. Perhaps I will ask it a question or two before we set out."},
		["Talk to the Augur of the Obscure 2"] =
			{appendText=" on the tabletop.", stepTextKey="I gave the Augur a hearing. Perhaps I will ask it a question or two before we set out."},
		[11] = 
			{appendStepText="", stepTextKey="Now that I've settled my business with the Augur, I should return to Loremaster Celarus."},
		["Talk to Loremaster Celarus 1"] =
			{appendText=" in his eastern chamber in Ceporah Tower on Artaeum.", stepTextKey="Now that I've settled my business with the Augur, I should return to Loremaster Celarus."},
		[12] = 
			{appendStepText="I am meeting with the Loremaster in his eastern chamber in Ceporah Tower on Artaeum. ", stepTextKey="The Augur of the Obscure's fate rests in my hands. I must choose whether to return it to the Psijic Vault, or give it to Josajeh for safekeeping."},
		["Give the Augur to Josajeh"] =
			{appendText=", allowing the Augur some freedom.\n"},
		["Return the Augur to the Vault"] =
			{appendText=" for safekeeping by the Psijic Order."},
		[13] = 
			{appendStepText="At Ceporah Tower on Artaeum, I spoke with Loremaster Celarus. ", stepTextKey="I chose to return the Augur to the Psijic Vault. I should make my way there and place the Augur where it belongs."},
		["Place the Augur in the Vault"] =
			{appendText=" of Moawita. To reach the Vault, I should enter the College of Psijics ruin at the south end of Artaeum. After entering, I should go down one flight of stairs on my left, then enter the vault to my right. I'll set the Augur of the Obscure on the southwest tabletop in the vault."},
		[14] = 
			{appendStepText="On Artaeum, ", stepTextKey="I returned the Augur to the vault. Now, I should catch up with Josajeh before she leaves the island."},
		["Talk to Josajeh 2"] =
			{appendText=" at the portal up at the end of the winding southern path by the waterfall, west of the vaults within the College of Psijics ruin.", stepTextKey="I returned the Augur to the vault. Now, I should catch up with Josajeh before she leaves the island."},
		[15] = 
			{appendStepText="Near the portal at the end of the winding path on Artaeum, I spoke with Josajeh. Now, ", stepTextKey="I should talk to Loremaster Celarus to receive my final reward."},
		["Talk to Loremaster Celarus 2"] =
			{appendText=".", stepTextKey="I should talk to Loremaster Celarus to receive my final reward."},
		[16] = 
			{appendStepText="I spoke with the Loremaster Celarus in his eastern chamber at Ceporah Tower on Artaeum. After discussing it with him, ", stepTextKey="I chose to free the Augur. I should deliver the oddity to Josajeh."},
		["Talk to Josajeh 3"] =
			{appendText=". She is outside on the balcony overlooking the sea, northeast of the tower's main portal entrance.", stepTextKey="I chose to free the Augur. I should deliver the oddity to Josajeh."},
		[17] = 
			{appendStepText="I found Josajeh on a balcony by Ceporah Tower on Artaeum. ", stepTextKey="Josajeh agreed to take the Augur. I should inform the Psijic Relicmaster of my choice."},
		["Talk to Relicmaster Glenadir"] =
			{appendText=" on the southern path heading toward the College of Psijics ruin where the Vaults of Moawita are housed. He is near the pond northwest of Artaeum Craftworks and northeast of the Portal to Summerset."},
		[18] = 
			{appendStepText="At the pond northeast of the Portal to Summerset in Artaeum's southern area, ", stepTextKey="I informed the Relicmaster that the Augur was leaving. Now, I should catch up with Josajeh before she leaves the island."},
		["Talk to Josajeh 4"] =
			{appendText=" near the portal. She is with the Loremaster.", stepTextKey="I informed the Relicmaster that the Augur was leaving. Now, I should catch up with Josajeh before she leaves the island."},
		[19] = 
			{appendStepText="Near the Portal to Summerset at the southern end of the winding path on Artaeum, ", stepTextKey="I should talk to Loremaster Celarus to receive my final reward."},
		["Talk to Loremaster Celarus 3"] =
			{appendText=".", stepTextKey="I should talk to Loremaster Celarus to receive my final reward."},
	},






-- 		=========================================================================
--		  Summerset - Side Quest 
-- 		=========================================================================

[GetQuestName(6165)] = { --"The Abyssal Cabal"		--Strangelove
		[1] = 
			{appendStepText="The main entrance to the Karnwasten caves lies north of The Crystal Tower Wayshrine, which is at the end of the second road leading north from the eastern side of Lilandrel. ", stepTextKey="The Battlereeve asked me to go to the Karnwasten caves to locate the mage Cainar and his companions. I need to find out what they learned."},
		["Talk to Cainar 1"] =
			{appendText=". Marines likely travelled there by boat, I should check for a small boat landing at the northwest end of the large bay inside the cave.", stepTextKey="The Battlereeve asked me to go to the Karnwasten caves to locate the mage Cainar and his companions. I need to find out what they learned."},
		[2] = 
			{appendStepText="Karnwasten caves is where ", stepTextKey="Cainar's associate Grog has been captured and left as a gift for the Sea Sload. I need to find him before anything awful happens."},
		["Find Grog"] =
			{appendText=". Cainar mentioned that the sload that holds him captive is in a cove in the southeast of the caves."},
		[3] = 
			{appendStepText="Karnwasten caves is where ", stepTextKey="I need to either get the key to unlock the chains that bind Grog, or I can pick the lock. Either way, I need to get him out of those chains."},
		["Rescue Grog"] =
			{appendText=" from the cove before the Sload turns its attention to him."},
		[4] = 
			{appendStepText="Karnwasten caves is where ", stepTextKey="I unlocked the chains and set Grog free. Now I should talk to him and find out what he's learned about the Sea Sload."},
		["Talk to Grog"] =
			{appendText=" in the cove where I rescued him."},
		[5] = 
			{appendStepText="There's a path leading up to a vantage point overlooking the large bay of Karnwasten Caves where ", stepTextKey="Grog suggested that the smugglers' captain keeps a journal in which she recorded information concerning her dealings with the Karnwasten Sea Sload. I should look for it near their shanty above the bay."},
		["Find the Captain's Journal"] =
			{appendText=" on top of a barrel."},
		[6] = 
			{appendStepText="Karnwasten caves is where ", stepTextKey="I should return to Cainar and show him the captain's journal. It contains some interesting information concerning the Sea Sload."},
		["Talk to Cainar 2"] =
			{appendText=" where I found him, at the boat landing in the bay.", stepTextKey="I should return to Cainar and show him the captain's journal. It contains some interesting information concerning the Sea Sload."},
		[7] = 
			{appendStepText="", stepTextKey="To find information on the other Sloads in Summerset, I should meet with Miriya. Her expedition was last seen southwest of Alinor."},
		["Talk to Miriya"] =
			{appendText=", who has been investigating a dangerous Sload and an abyssal geyser near the coast. If she's still alive, she may be injured and hunkered down in the area."},
		[8] = 
			{appendStepText="", stepTextKey="The marines accompanying Miriya retreated down the coast after they were ambushed by the yaghra. I need to find them and their mage, Indirim, who assembled a report about the Sea Sload's geysers."},
		["Find Miriya's Marines"] =
			{appendText=". I should check the coast west of Alinor for signs of them."},
		[9] = 
			{appendStepText="", stepTextKey="I found a page from Indirim's report on the Sea Sload threat. I need to continue to search the coastline and find the rest of the report."},
		["Assemble the Report"] =
			{appendText=" \n\nThe reports mention a Sload named B'Korgen. I should search around its lair in Welenkin Cove, which is west of Alinor, and continue checking down the coast nearby for more pages."},
		[10] = 
			{appendStepText="", stepTextKey="I should bring the reassembled report to Battlereeve Tanerline in Alinor."},
		["Talk to Battlereeve Tanerline 1"] =
			{appendText=", who is taking a report from Cainar and his cohort, Grog, at a spot overlooking the canal across from Rinmawen's Plaza.", stepTextKey="I should bring the reassembled report to Battlereeve Tanerline in Alinor."},
		[11] = 
			{appendStepText="", stepTextKey="I should talk to Battlereeve Tanerline about the Sea Sload threat we uncovered."},
		["Talk to Battlereeve Tanerline 2"] =
			{appendText=", who is where I left her, on a spot overlooking the canal opposite Rinmawen's Plaza.", stepTextKey="I should talk to Battlereeve Tanerline about the Sea Sload threat we uncovered."},
		[12] = 
			{appendStepText="", stepTextKey="I should escort Grog back to Cainar so we can tell him what we know."},
		["Return to Cainar"] =
			{appendText=" where I found him, at the boat landing in the bay in Karnwasten caves."},
		[13] = 
			{appendStepText="", stepTextKey="I should talk to Cainar and tell him what Grog learned in Karnwasten."},
		["Talk to Cainar 3"] =
			{appendText=" where I found him, at the boat landing in the bay in Karnwasten caves.", stepTextKey="I should talk to Cainar and tell him what Grog learned in Karnwasten."},
	},

	[GetQuestName(6140)] = { --"Bantering with Bandits"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="Manacar asked me to check in on Tableau at her debut gallery showing in the Oleander Coast Winery. I should speak to her patron, Lilawen, to find out where she is."},
		["Talk to Lilawen"] =
			{appendText=", who can be found within the winery outside of Alinor's walls, proudly displaying her collected artworks.\n"},
		[2] = 
			{appendStepText="", stepTextKey="Lilawen is concerned that Tableau hasn't come out of her studio to present herself at the showing. I should check on her upstairs."},
		["Enter Tableau's Studio"] =
			{appendText=" within the winery outside of Alinor's walls.\n"},
		[3] = 
			{appendStepText="", stepTextKey="I've entered Tableau's studio, but she's nowhere to be found. There's a conspicuous note. I should read it and see what happened."},
		["Read the Note"] =
			{appendText=" within the winery outside of Alinor's walls.\n"},
		[4] = 
			{appendStepText="", stepTextKey="A group of bandits called the Blackbirds kidnapped Tableau and are holding her for ransom. I should return to Manacar and tell him what has happened."},
		["Talk to Manacar 1"] =
			{appendText=", behind the vineyard across the road from the winery outside of Alinor's walls.\n", stepTextKey="A group of bandits called the Blackbirds kidnapped Tableau and are holding her for ransom. I should return to Manacar and tell him what has happened."},
		[5] = 
			{appendStepText="", stepTextKey="The ransom note mentioned a fence named Ghrum, who Manacar knows. I should go to the Alinor Outlaw's Refuge and ask the Orc about the Blackbirds."},
		["Talk to Ghrum"] =
			{appendText=".\n"},
		[6] = 
			{appendStepText="King's Haven Pass can be found on the mountainside north of the Ebon Stadmont Wayshrine, along the road north from Alinor on the north side of the bay just before reaching the Illumination Academy.\n\n", stepTextKey="Ghrum told us that we could find the Blackbirds in King's Haven Pass. I should chase down the Blackbirds while Manacar sets up an ambush at the far end of the pass."},
		["Chase Down the Blackbirds"] =
			{appendText=". I should look for signs of their passing along the road through the pass.\n"},
		[7] = 
			{appendStepText="", stepTextKey="I found a broken cart in King's Haven Pass. I should search the cart for any clues as to what happened here."},
		["Investigate the Wrecked Cart"] =
			{appendText=".\n"},
		[8] = 
			{appendStepText="", stepTextKey="I found a broken cart in King's Haven Pass with a locket nearby. There are no bodies or signs of survivors. I should meet up with Manacar and see if Tableau and the Blackbirds escaped."},
		["Talk to Manacar 2"] =
			{appendText=" outside the east entrance of the pass.", stepTextKey="I found a broken cart in King's Haven Pass with a locket nearby it. There are no bodies or signs of survivors. I should meet up with Manacar and see if Tableau and the Blackbirds escaped."},
		[9] = 
			{appendStepText="", stepTextKey="Using Tableau's locket, Cur was able to pick up a scent. I should follow Cur to Tableau."},
		["Follow Cur"] =
			{appendText=". He started his trek at the east entrance to King's Haven Pass. I should keep close, he doesn't seem too keen on waiting for me.\n"},
		[10] = 
			{appendStepText="", stepTextKey="Manacar and I confronted the Blackbirds, only to have Tableau jump up and apologize as the Blackbirds ran off. I should speak with her and see what's going on."},
		["Talk to Tableau 1"] =
			{appendText=" where Cur led me, north of Gryphon Aerie on the northeast shore of Summerset.\n", stepTextKey="Manacar and I confronted the Blackbirds, only to have Tableau jump up and apologize as the Blackbirds ran off. I should speak with her and see what's going on."},
		[11] = 
			{appendStepText="The quarreling companions are north of Gryphon Aerie on the northeast shore of Summerset. ", stepTextKey="Tableau used her former troupe members to fake her kidnapping so that she could reconnect with Manacar. I should speak with them and resolve this dispute."},
		["Convince Tableau to Go Back"] =
			{appendText=".\n"},
		["Convince Manacar to Let Tableau Stay"] =
			{appendText=".\n"},
		[12] = 
			{appendStepText="", stepTextKey="I convinced Tableau that Manacar wants her to succeed as an artist and thus, he cannot be her friend."},
		["Talk to Tableau 2"] =
			{appendText=". She is still where I left her north of Gryphon Aerie on the northeast shore of Summerset.\n", stepTextKey="I convinced Tableau that Manacar wants her to succeed as an artist and thus, he cannot be her friend."},
		[13] = 
			{appendStepText="", stepTextKey="I convinced Manacar that Tableau has a right to choose what makes her happiest, regardless of what Manacar thinks is best."},
		["Talk to Manacar 3"] =
			{appendText=". He is still where I left him to the north of Gryphon Aerie on the northeast shore of Summerset.\n", stepTextKey="I convinced Manacar that Tableau has a right to choose what makes her happiest, regardless of what Manacar thinks is best."},
	},

    [GetQuestName(6141)] = { --"Culture Clash"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="Rigurt asked me to talk to Courtier Vindilween and find out how we go about acquiring a proper introduction to see the Proxy Queen."},
        ["Talk to Courtier Vindilween 1"] =
            {appendText=", who can be found inside the Alinor Royal Palace, likely near the throne.\n", stepTextKey="Rigurt asked me to talk to Courtier Vindilween and find out how we go about acquiring a proper introduction to see the Proxy Queen."},
        [2] = 
            {appendStepText="", stepTextKey="I need to get Rigurt a recommendation from Sapiarch Tandemen, a writ of authenticity from Justiciar Rolumdel, and tickets from Enigma to her next performance. Vindilween suggests I use the currency of favors to accomplish these tasks."},
        ["Favor for Sapiarch Tandemen"] =
            {appendText=". I can find him in Alinor enjoying his wine by the bank. And the newcomers he would like to aquire culturally significant items from can be found nearby around Rinmawen's Plaza.\n"},
        ["Favor for Enigma"] =
            {appendText=". I can find her wearing a very blue ensemble rehearsing her latest role outside of the Rellenthil Bathhouse on the west end of Rellenthil. Perhaps Rigurt can consult with her for her role and give her the inspiration she needs.\n"},
        ["Favor for Justiciar Rolumdel"] =
            {appendText=". I can find him standing by a fountain outside of the Mage's Guild in Lillandril. He suggested I look for his stolen goods in the possession of pirates, possibly in their backpacks, in Wasten Coraldale. I can get there via a raft west of the Cey-Tarn Keep Wayshrine.\n"},
        [3] = 
            {appendStepText="", stepTextKey="Now that we acquired the items she asked for, I should return to Alinor and talk to Courtier Vindilween."},
        ["Talk to Courtier Vindilween 2"] =
            {appendText=". I can find her waiting in the council chambers of the Alinor Royal Palace.\n", stepTextKey="Now that we acquired the items she asked for, I should return to Alinor and talk to Courtier Vindilween."},
        [4] = 
            {appendStepText="", stepTextKey="Courtier Vindilween gave Rigurt an appointment with the Proxy Queen, but it's a long way off. I should talk to him and see what he wants to do now."},
        ["Talk to Rigurt the Brash 1"] =
            {appendText=". He followed me to the council chambers of the Alinor Royal Palace, anticipating successful negotiations with the courtier.\n", stepTextKey="Courtier Vindilween gave Rigurt an appointment with the Proxy Queen, but it's a long way off. I should talk to him and see what he wants to do now."},
        [5] = 
            {appendStepText="", stepTextKey="I suggested that we use the information Justiciar Rolumdel provided to convince Vindilween to get Rigurt an immediate audience with the Proxy Queen. Rigurt agreed but suggested the threat would be better coming from me."},
        ["Talk to Courtier Vindilween 3"] =
            {appendText=", who is right where I left her in the council chambers of the Alinor Royal Palace.\n", stepTextKey="I suggested that we use the information Justiciar Rolumdel provided to convince Vindilween to get Rigurt an immediate audience with the Proxy Queen. Rigurt agreed but suggested the threat would be better coming from me."},
        [6] = 
            {appendStepText="", stepTextKey="Courtier Vindilween finally agreed to allow Rigurt to meet with the Proxy Queen. I should let Rigurt know so he can prepare for the meeting."},
        ["Talk to Rigurt the Brash 2"] =
            {appendText=", still patienly waiting for the good news I bear in the council chambers of the Alinor Royal Palace.\n", stepTextKey="Courtier Vindilween finally agreed to allow Rigurt to meet with the Proxy Queen. I should let Rigurt know so he can prepare for the meeting."},
    },

    [GetQuestName(6170)] = { --"Divine Deputation"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="Chief Justiciar Carawen can deputize me so I can take on contract work for the Divine Prosecution. I should speak to her."},
        ["Talk to Chief Justiciar Carawen 1"] =
            {appendText=" in Rinmawen's Plaza in Alinor, standing in a stall with two other Justiciars who are calling for adventurers to take on their Divine tasks.", stepTextKey="Chief Justiciar Carawen can deputize me so I can take on contract work for the Divine Prosecution. I should speak to her."},
        [2] = 
            {appendStepText="", stepTextKey="I should speak to Chief Justiciar Carawen in order to be deputized as a contract agent for the Divine Prosecution."},
        ["Talk to Chief Justiciar Carawen 2"] =
            {appendText=". She is still where I last saw her, in Rinmawen's Plaza in Alinor, standing in a stall with two other Justiciars who are calling for adventurers to take on their Divine tasks.", stepTextKey="I should speak to Chief Justiciar Carawen in order to be deputized as a contract agent for the Divine Prosecution."},
    },


	[GetQuestName(6151)] = { --"A Duelist's Dilemma"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="I should talk to Lirendel. Hopefully he'll shed some light on the High Elves' dueling customs."},
		["Talk to Lirendel"] =
			{appendText=". Roguzog mentioned Lirendel had stirred up trouble with him in the Golden Gryphon, maybe I can find him there."},
		[2] = 
			{appendStepText="", stepTextKey="Lirendel refused to explain the High Elf dueling customs, but directed me to a book that might help. I should collect it."},
		["Collect the Altmer Cultural Guide"] =
			{appendText=" from the table on the top floor of The Golden Gryphon in Alinor, directly in front of Lirendel."},
		[3] = 
			{appendStepText="", stepTextKey="I should take the Altmer Cultural Guide to Roguzog. The chapter on dueling customs will probably be helpful."},
		["Talk to Roguzog 1"] =
			{appendText=" where I met him, next to the central gate out of Alinor.", stepTextKey="I should take the Altmer Cultural Guide to Roguzog. The chapter on dueling customs will probably be helpful."},
		[4] = 
			{appendStepText="", stepTextKey="Apparently, High Elf dueling customs require the duelists to use traditional Altmer dueling foils. I'll need to purchase or steal one from a person in Alinor."},
		["Collect an Altmer Dueling Foil"] =
			{appendText=". There is a Khajiit housekeeper named Nahdahni in the west part of town near the Gilded Fork who is known to sell her master's missing baubles, perhaps I should talk to her about acquiring one. I could also see if I can't add to her master's list of missing trinkets myself."},
		[5] = 
			{appendStepText="", stepTextKey="I should travel to Lirendel's family shrine and learn his full name. I will need to recite it before the duel can commence."},
		["Learn Lirendel's Full Name"] =
			{appendText=". Roguzog told me I can find Lirendel's full name inscribed on his family shrine within Tor-Hame-Khard, a ruin which lies at the end of the looped road southwest of Shimmerene. I should check for inscriptions on the statues there."},
		[6] = 
			{appendStepText="", stepTextKey="I collected the dueling foil and learned Lirendel's full name. Now all I need to do is issue the challenge to Lirendel's second, Fandilol."},
		["Talk to Fandilol 1"] =
			{appendText=". I saw him with Lirendel on the top floor of The Golden Gryphon in Alinor.", stepTextKey="I collected the dueling foil and learned Lirendel's full name. Now all I need to do is issue the challenge to Lirendel's second, Fandilol."},
		[7] = 
			{appendStepText="", stepTextKey="I delivered Roguzog's challenge to Lirendel's second. The duel will commence soon. I should go talk to Roguzog and make sure he's prepared."},
		["Talk to Roguzog 2"] =
			{appendText=" at the ruins directly west of Alinor, where he told me to meet him when all was prepared.", stepTextKey="I delivered Roguzog's challenge to Lirendel's second. The duel will commence soon. I should go talk to Roguzog and make sure he's prepared."},
		[8] = 
			{appendStepText="", stepTextKey="Lirendel and his second have finally arrived at the ruins. I should issue the formal challenge to Fandilol."},
		["Talk to Fandilol 2"] =
			{appendText=" at the ruins directly west of Alinor. I have to recite Lirendel's full name myself, it seems. I should refer to the rubbing I made at Lirendel's family shrine to make sure I get this right.", stepTextKey="Lirendel and his second have finally arrived at the ruins. I should issue the formal challenge to Fandilol."},
		[9] = 
			{appendStepText="", stepTextKey="Lirendel has finally accepted Roguzog's challenge. Time to find out how this duel will pan out."},
		["Witness the Duel"] =
			{appendText=" at the ruins directly west of Alinor."},
		[10] = 
			{appendStepText="", stepTextKey="Roguzog won the duel. I should speak with him."},
		["Talk to Roguzog 3"] =
			{appendText=" at the ruins directly west of Alinor.", stepTextKey="Roguzog won the duel. I should speak with him."},
	},

[GetQuestName(6119)] = { --"The Ebon Sanctum"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="I should speak to Andewen, the academic leading this expedition. I can find her on the other side of the forest."},
		["Talk to Andewen 1"] =
			{appendText=" by the entrance to Ebon Stadmont.", stepTextKey="I should speak to Andewen, the academic leading this expedition. I can find her on the other side of the forest."},
		[2] = 
			{appendStepText="", stepTextKey="I've been hired as Andewen's escort through Ebon Stadmont. I should be on a lookout for anything  that can lead us to the temple, as well as protect her from any danger we come across."},
		["Assist Andewen 1"] =
			{appendText=". I should listen to Andewen to learn what she might need inside the forest.", stepTextKey="I've been hired as Andewen's escort through Ebon Stadmont. I should be on a lookout for anything  that can lead us to the temple, as well as protect her from any danger we come across."},
		[3] = 
			{appendStepText="", stepTextKey="Andewen's translation indicates a ruin farther along the path. I should follow her to this ruin."},
		["Find the Path to the Ruin"] =
			{appendText="."},
		[4] = 
			{appendStepText="", stepTextKey="Despite being mysteriously separated, Andewen and I found each other. I should help her look for another inscription."},
		["Assist Andewen 2"] =
			{appendText=".", stepTextKey="Despite being mysteriously separated, Andewen and I found each other. I should help her look for another inscription."},
		[5] = 
			{appendStepText="", stepTextKey="The second inscription has revealed the ruin's location at the end of the path. I should see if I can find anything in the ruin that can help Andewen."},
		["Search the Ruin"] =
			{appendText=". I'll have to find my way to the Ebon Sanctum.\n"},
		[6] = 
			{appendStepText="", stepTextKey="Andewen and I were separated again. I headed inside the ruin to look for her, and found a note next to a strange, glowing stone. I should read the note."},
		["Examine the Note"] =
			{appendText="."},
		[7] = 
			{appendStepText="", stepTextKey="Andewen's note told me to follow her. I should activate the stone in order to do so."},
		["Examine the Stone"] =
			{appendText="."},
		[8] = 
			{appendStepText="", stepTextKey="I've activated the stone in order to open the doorway. A mysterious voice spoke to me about the past. I should enter the doorway to seek out Andewen."},
		["Find Andewen"] =
			{appendText="."},
		[9] = 
			{appendStepText="", stepTextKey="I've found Andewen being attacked by a Daedra. I should protect her by defeating the Daedra."},
		["Kill the Daedra"] =
			{appendText="."},
		[10] = 
			{appendStepText="", stepTextKey="Andewen found a High Elf severely wounded. I should help bandage his wounds while Andewen heals him."},
		["Help Andewen Heal Fletch"] =
			{appendText="."},
		[11] = 
			{appendStepText="", stepTextKey="The dying High Elf that Andewen healed has regained consciousness. We should talk with him and find out what happened."},
		["Talk to Fletch 1"] =
			{appendText=".", stepTextKey="The dying High Elf that Andewen healed has regained consciousness. We should talk with him and find out what happened."},
		[12] = 
			{appendStepText="", stepTextKey="Fletch doesn't remember what attacked him, but believes his troupe may be in danger. We should speak to his troupe leader Maestro Forte about these concerns."},
		["Talk to Maestro Forte"] =
			{appendText=" in the garden."},
		[13] = 
			{appendStepText="", stepTextKey="We warned Maestro Forte about the Daedra threat. Suspecting the stones like the one we found next to Fletch, he asked Andewen and I to inspect one nearby. I should go find the northern stone."},
		["Investigate the Northern Stone"] =
			{appendText="."},
		[14] = 
			{appendStepText="", stepTextKey="I activated the northern stone, and once again heard a woman's voice, which spoke of the future. I should speak to Andewen about these strange events."},
		["Talk to Andewen 2"] =
			{appendText=".", stepTextKey="I activated the northern stone, and once again heard a woman's voice, which spoke of the future. I should speak to Andewen about these strange events."},
		[15] = 
			{appendStepText="", stepTextKey="Andewen and I have discovered that we're actually in the past. I should use the northern stone to return to my own time."},
		["Travel Back to the Present"] =
			{appendText="."},
		[16] = 
			{appendStepText="", stepTextKey="I took the door to the future, and arrived in a clearing during a massive storm. An older Andewen is standing next to one of the stones. I should talk with her and find out what happened."},
		["Talk to Andewen 3"] =
			{appendText=".", stepTextKey="I took the door to the future, and arrived in a clearing during a massive storm. An older Andewen is standing next to one of the stones. I should talk with her and find out what happened."},
		[17] = 
			{appendStepText="", stepTextKey="Fletch has arrived in the clearing, and has struck Andewen with an arrow. I should listen to what he has to say."},
		["Listen to Fletch"] =
			{appendText="."},
		[18] = 
			{appendStepText="", stepTextKey="Andewen has been gravely wounded by Fletch. I should speak to her."},
		["Talk to Andewen 4"] =
			{appendText=".", stepTextKey="Andewen has been gravely wounded by Fletch. I should speak to her."},
		[19] = 
			{appendStepText="", stepTextKey="I've activated the stone, which opened the door to the temple. I must travel within the temple to stop Andewen from ever going back in time."},
		["Follow Fletch"] =
			{appendText="."},
		[20] = 
			{appendStepText="", stepTextKey="I've entered the temple, only to be ambushed by Fletch. I should defeat him."},
		["Defeat Fletch"] =
			{appendText="."},
		[21] = 
			{appendStepText="", stepTextKey="I need to return to my own time to stop Andewen from ever traveling back to the past. I should activate the Southern stone in order to travel back to the present."},
		["Activate the Southern Stone"] =
			{appendText="."},
		[22] = 
			{appendStepText="", stepTextKey="A portal has opened before me, with a voice beckoning me to enter. I should go through it."},
		["Enter Portal"] =
			{appendText="."},
		[23] = 
			{appendStepText="", stepTextKey="I've arrived back in my time, with Fletch standing before me. I should speak to him and discovery how this is possible."},
		["Talk to Fletch 2"] =
			{appendText=".", stepTextKey="I've arrived back in my time, with Fletch standing before me. I should speak to him and discovery how this is possible."},
		[24] = 
			{appendStepText="", stepTextKey="Fletch has explained that Andewen was trapped by the Spirit of the Sanctum, but that I can stop it from ever happening. I should convince Andewen to leave Ebon Stadmont, before she is trapped."},
		["Talk to Andewen 5"] =
			{appendText=". I need to hurry back to the path out of the Ebon Stadmont and intercept Andewen before she ever enters the Ebon Sanctum.", stepTextKey="Fletch has explained that Andewen was trapped by the Spirit of the Sanctum, but that I can stop it from ever happening. I should convince Andewen to leave Ebon Stadmont, before she is trapped."},
		[25] = 
			{appendStepText="", stepTextKey="I convinced Andewen to leave, thus saving her from becoming trapped. I should talk to her and collect my reward."},
		["Talk to Andewen 6"] =
			{appendText=" where I last spoke to her, outside of the door to the Ebon Sanctum.", stepTextKey="I convinced Andewen to leave, thus saving her from becoming trapped. I should talk to her and collect my reward."},
	},


	[GetQuestName(6178)] = { --"The Forest Vandal"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="Vinafwe suspects a Wood Elf named Eslion is responsible for her problems and requested that I search her defaced arrangements for evidence tying him to the crimes."},
		["Investigate the First Arrangement"] =
			{appendText=". I should begin by looking further into her garden, westward along Summerset's southern road between Vinafwe's house and the Sunhold Wayshrine."},
		[2] = 
			{appendStepText="", stepTextKey="I discovered a long abandoned gardening tool that has seen recent use, but I will need more than that to prove Eslion is responsible. I need to search some of Vinafwe's other arrangements."},
		["Investigate the Second Arrangement"] =
			{appendText=". I should continue my search for a another one of Vinafwe's botanical arrangements by looking further into her garden, west along Summerset's southern road between Vinafwe's house and the Sunhold Wayshrine. Possibly more off the beaten track."},
		[3] = 
			{appendStepText="", stepTextKey="I found an animal hide bag still containing seeds not native to Summerset. It's a good step toward identifying Eslion as the vandal, but I should search the remaining arrangement as well."},
		["Investigate the Third Arrangement"] =
			{appendText=". I may have passed another of Vinafwe's arrangements while looking for the last one, to the south of Summerset's southern road between Vinafwe's house and the Sunhold Wayshrine."},
		[4] = 
			{appendStepText="", stepTextKey="Stranglers erupted from the ground while I was searching one of Vinafwe's plots. They are too dangerous to leave behind. I should kill them off."},
		["Defeat the Stranglers"] =
			{appendText=" that I found at the last arrangement south of Summerset's southern road between Vinafwe's house and the Sunhold Wayshrine."},
		[5] = 
			{appendStepText="", stepTextKey="A Wood Elf called out to me after I dealt with the stranglers in Vinafwe's arrangement. I should see what he has to say."},
		["Talk to Eslion 1"] =
			{appendText=", who spoke to me from under a tree south of along Summerset's southern road between Vinafwe's house and the Sunhold Wayshrine by Vinafwe's garden arrangement.", stepTextKey="A Wood Elf called out to me after I dealt with the stranglers in Vinafwe's arrangement. I should see what he has to say."},
		[6] = 
			{appendStepText="", stepTextKey="I found Eslion, who admits he's been planting foreign plants in Vinafwe's arrangements, but claims the stranglers are an accident. He asked me to help poison them to correct his mistake and provided me with a mixture to pour into local water sources."},
		["Pour Strangler-Poison into Water Sources"] =
			{appendText=" \n\nI should spread the poison out along the water to get to the whole area. I can likely find some good water sources to poison by following the streams to the north, west, and south of Summerset's southern road near the Sunhold Wayshrine."},
		[7] = 
			{appendStepText="", stepTextKey="I added the poison Eslion concocted to the local water sources, which should end the strangler threat. Now I should inform Vinafwe about what I discovered."},
		["Return to Vinafwe"] =
			{appendText=" at her home south of Summerset's southern road, where Esilon said he'd go to clear up this misunderstanding."},
		[8] = 
			{appendStepText="", stepTextKey="It appears Eslion's apologies fell on deaf ears, as I found him in the custody of the Divine Prosecution at Vinafwe's home. I should talk to him about his predicament."},
		["Talk to Eslion 2"] =
			{appendText=", who has been apprehended by the authorites at Vinafwe's house south of Summerset's southern road.", stepTextKey="It appears Eslion's apologies fell on deaf ears, as I found him in the custody of the Divine Prosecution at Vinafwe's home. I should talk to him about his predicament."},
		[9] = 
			{appendStepText="Eslion is being detained at Vinafwe's house south of Summerset's southern road. ", stepTextKey="Eslion believes he's going to be arrested and thrown in jail for his actions and has begged me to speak to the Divine Prosecution on his behalf. I need to decide what to tell them."},
		["Provide Evidence Against Eslion"] =
			{appendText=".\n"},
		["Clear Eslion of Wrongdoing"] =
			{appendText="."},
		[10] = 
			{appendStepText="", stepTextKey="Regardless of Eslion's intentions, what he did was illegal and harmful. He has to face the consequences for what he did. I need to tell Justiciar Oradel that Eslion is guilty."},
		["Talk to Justiciar Oradel 1"] =
			{appendText=" at Vinafwe's house south of the Summerset's southern road. ", stepTextKey="Regardless of Eslion's intentions, what he did was illegal and harmful. He has to face the consequences for what he did. I need to tell Justiciar Oradel that Eslion is guilty."},
		[11] = 
			{appendStepText="", stepTextKey="Despite his culpability, I decided that Eslion's attempt to fix his mistake deserves leniency. I should ask Justiciar Oradel to consider that when rendering his judgment."},
		["Talk to Justiciar Oradel 2"] =
			{appendText=" at Vinafwe's house south of the Summerset's southern road. ", stepTextKey="Despite his culpability, I decided that Eslion's attempt to fix his mistake deserves leniency. I should ask Justiciar Oradel to consider that when rendering his judgment."},
	},

  [GetQuestName(6177)] = { --"Gjadil's Legacy"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="Igeke has offered me a map in order to locate Gjadil's treasure map. I should collect it."},
        ["Examine Gjadil's Treasure Map"] =
            {appendText=" at Ideke's camp on the island off the southeastern coast of Summerset."},
        [2] = 
            {appendStepText="", stepTextKey="Igeke's treasure map can be used to locate Gjadil's chest. I should look at the map and travel to the marked location."},
        ["Find Gjadil's Chest"] =
            {appendText=". The landmark in the map is likely nearby, perhaps around the bend to the south of Igeke's camp."},
        [3] = 
            {appendStepText="", stepTextKey="I found Gjadil's treasure chest. I should return it to Igeke Rat-Bite and collect my reward."},
        ["Talk to Igeke Rat-Bite"] =
            {appendText=" at her camp on the island off the southeastern coast of Summerset."},
    },


	[GetQuestName(6127)] = { --"Half-Formed Understandings"		--Devinstrike 
		[1] = 
			{appendStepText="", stepTextKey="Ulliceta said there are library pedestals in this ruin which may react to the Eye of Remembrance, revealing the secrets of why this vault was sealed away. I should search for the first library pedestal and defeat any undead in my way."},
		["Find the First Library Pedestal"] =
			{appendText=". Skeletal bones clack throughout this place. A faint teal glow emanates from a small pedestal along the midsection of what was once the cross bridge of a library. I should investigate."},
		[2] = 
			{appendStepText="", stepTextKey="I discovered a strange pedestal atop a bridge deeper in the ruins. Perhaps this is the library pedestal Ulliceta mentioned. I should use the Eye of Remembrance nearby and see if the pedestal reacts."},
		["Use the Eye on the Bridge"] =
			{appendText=" and uncover a clue to the past."},
		[3] = 
			{appendStepText="", stepTextKey="When I used the Eye of Remembrance near the pedestal, I witnessed a memory of Vanus Galerion and Mannimarco. I can feel the eye drawing me deeper in the ruins. There must be more pedestals to find. I should keep looking."},
		["Find the Next Library Pedestal 1"] =
			{appendText=". This feeling draws me past the increased dangers and toward a flight of stairs, as if willing me to venture down. Within the next room, the whir of Psijic magic stirs, preserved for untold years. It could help shed light on this place alongside my search.", stepTextKey="When I used the Eye of Remembrance near the pedestal, I witnessed a memory of Vanus Galerion and Mannimarco. I can feel the eye drawing me deeper in the ruins. There must be more pedestals to find. I should keep looking."},
		[4] = 
			{appendStepText="", stepTextKey="I found another library pedestal inside what may be a gathering hall or a presentation chamber. I should use the Eye near the pedestal to reveal the next memory."},
		["Use the Eye in the Presentation Chamber"] =
			{appendText=" and witness past events."},
		[5] = 
			{appendStepText="", stepTextKey="The Eye of Remembrance draws me deeper in the ruin. The next library pedestal is close. I must find it."},
		["Find the Next Library Pedestal 2"] =
			{appendText=". The feeling pulls me toward a hallway exposed to the light and onward still, past a pile of decrepit books and further down past long-dead DragonKnights. Past a terrace and within another room, this pull becomes stronger. My goal is near.", stepTextKey="The Eye of Remembrance draws me deeper in the ruin. The next library pedestal is close. I must find it."},
		[6] = 
			{appendStepText="", stepTextKey="The pull of the Eye has led me to what appears to be a ruined laboratory. I should use the Eye to discover the next memory."},
		["Use the Eye in the Laboratory"] =
			{appendText=" and uncover more of Mannimarco's experiments."},
		[7] = 
			{appendStepText="", stepTextKey="The pull of the Eye is stronger than ever. It feels like it is consciously directing me now, to what may be the memory that finally reveals why this library was sealed. I should see if I can find the fourth library pedestal."},
		["Find the Fourth Library Pedestal"] =
			{appendText=". The pull draws me back toward a previous pile of books bathed in light."},
		[8] = 
			{appendStepText="", stepTextKey="I've found what may be the last library pedestal in the ruins. I should use the Eye again. Perhaps I'll finally learn the truth about why the ruins were sealed."},
		["Use the Eye Outside the Sealed Hall"] =
			{appendText=" and follow where the trail leads."},
		[9] = 
			{appendStepText="", stepTextKey="The Eye revealed what might have been the final confrontation between Mannimarco and Vanus Galerion. I should learn all I can, then continue on."},
		["Observe the Scene"] =
			{appendText="  of Mannimarco's betrayal.\n"},
		["Enter the Sealed Hall"] =
			{appendText=" and discover what lies within."},
		[10] = 
			{appendStepText="", stepTextKey="After defeating Vanus Galerion in the last memory I witnessed, Mannimarco departed for a sealed room. Though something horrible may wait inside, I feel the Eye drawing me on. I must enter the sealed room to learn why these ruins were sealed."},
		["Enter Mannimarco's Secret Chamber"] =
			{appendText="."},
		[11] = 
			{appendStepText="", stepTextKey="Mannimarco's sealed room likely contain horrors I have yet to discover. I should tread carefully as I search."},
		["Search the Chamber"] =
			{appendText=". A sense of danger fills me. Something remains here, and I must steel myself."},
		[12] = 
			{appendStepText="", stepTextKey="An undead creature rose from a tomb in the secret chamber—no doubt left here by Mannimarco and sealed in by the Psijic Order. Now that it has revealed itself, I must destroy it."},
		["Kill Vessel of Worms"] =
			{appendText=" and put these haunted halls to rest."},
		[13] = 
			{appendStepText="", stepTextKey="Ulliceta urged me to meet her outside. I should leave the vault and talk to her."},
		["Talk to Ulliceta"] =
			{appendText=". She must be near the entrance, safely where I met her outside the Traitor's Vault."},
	},

   [GetQuestName(6176)] = { --"His Final Gift"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="I found a High Elf corpse. I should read the note next to his body to find out what happened."},
        ["Collect Nafarion's Note"] =
            {appendText="."},
        [2] = 
            {appendStepText="", stepTextKey="I've read the note, and discovered that Nafarion wished to give Felawen a pendant to remember him by. I should retrieve the pendant."},
        ["Retrieve the Pendant"] =
            {appendText=" close to Nefarion's body out in this shack east of Veyond Wyte Wayshrine."},
        [3] = 
            {appendStepText="", stepTextKey="I've collected Nafarion's pendant. I should find Felawen and deliver it to her. She'll be in Lillandril."},
        ["Find Felawen"] =
            {appendText=". Perhaps I should look near the memorial park and shrine for lost loved ones that overlooks the cliffs off the north road out of the town proper."},
        [4] = 
            {appendStepText="", stepTextKey="I found Felawen. I should speak to her about what happened to Nafarion."},
        ["Talk to Felawen 1"] =
            {appendText=" in the little park overlooking the cliffs north of Lilandrel's town proper.", stepTextKey="I found Felawen. I should speak to her about what happened to Nafarion."},
        [5] = 
            {appendStepText="", stepTextKey="I should talk to Felawen."},
        ["Talk to Felawen 2"] =
            {appendText=" in the little park overlooking the cliffs north of Lilandrel's town proper.", stepTextKey="I should talk to Felawen."},
    },

    [GetQuestName(6139)] = { --"The Hulkynd's Heart"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="I've been requested to find the hulkynd who is currently in the wilderness outside Rellenthil. I should head there to begin my search."},
        ["Find the Hulkynd"] =
            {appendText=". Perhaps I should check outside of Tor-Hame-Khard, at the end of the looped road southwest of Shimmerine.\n"},
        [2] = 
            {appendStepText="", stepTextKey="The Hulkynd that Tableau wishes to meet has addressed me. I should speak to him."},
        ["Talk to the Hulkynd"] =
            {appendText=" outside of Tor-Hame-Khard.\n"},
        [3] = 
            {appendStepText="", stepTextKey="Manacar has agreed to meet Tableau if I fulfill his current contract. I should follow his pet wolf Cur to track down the indrik so I can collect its heart."},
        ["Kill the Indrik"] =
            {appendText=". Cur starts his trek on the road outside of Tor-Hame-Kharn.\n"},
        [4] = 
            {appendStepText="", stepTextKey="I've killed the indrik. I should collect its heart for Manacar."},
        ["Collect the Indrik's Heart"] =
            {appendText=". Cur will lead me to the heart just outside the Keep of the Elven Forces beside some large boulders.\n"},
        [5] = 
            {appendStepText="", stepTextKey="I've collected the indrik heart. I should meet Tableau and Manacar at the sinkhole outside of Rellenthil."},
        ["Talk to Manacar"] =
            {appendText=". The sinkhole I'm to meet him and Tableau at is north of the Russafeld Heights Wayshrine, which lies along the road directly west of Shimmerene.\n"},
        [6] = 
            {appendStepText="", stepTextKey="Manacar asked me to deliver the heart to a noble named Valtarion. I should travel to the inn in Lillandril to find him."},
        ["Talk to Valtarion"] =
            {appendText=". Lillandril is a port city that lays on the northwest coast of Summerset.\n"},
    },

	[GetQuestName(6115)] = { --"Illusions of Grandeur"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="A clearly mad student of the Illumination Academy mentioned that an Elf named Erudil tried to talk some sense into her. I should find Erudil and talk to him."},
		["Talk to Erudil 1"] =
			{appendText=", a male High-Elf who is attmepting to corral students in the central courtyard.", stepTextKey="A clearly mad student of the Illumination Academy mentioned that an Elf named Erudil tried to talk some sense into her. I should find Erudil and talk to him."},
		[2] = 
			{appendStepText="", stepTextKey="I should talk to Erudil to find out what he plans to do about this enchantment run amok."},
		["Talk to Erudil 2"] =
			{appendText=" in the central courtyard.", stepTextKey="I should talk to Erudil to find out what he plans to do about this enchantment run amok."},
		[3] = 
			{appendStepText="", stepTextKey="Erudil mentioned that a mysterious book called the Illuminus might be the source of the enchantment. I should take a look at this suspicious tome."},
		["Read the Illuminus 1"] =
			{appendText=" next to Erudil in the central courtyard.", stepTextKey="Erudil mentioned that a mysterious book called the Illuminus might be the source of the enchantment. I should take a look at this suspicious tome."},
		[4] = 
			{appendStepText="", stepTextKey="The Illuminus contained no text. I should ask Erudil about it."},
		["Talk to Erudil 3"] =
			{appendText=" in the central courtyard.", stepTextKey="The Illuminus contained no text. I should ask Erudil about it."},
		[5] = 
			{appendStepText="", stepTextKey="Erudil thinks that if we break the enchantment on his friends, they might be able to come up with a broader and more effective solution. I should follow him."},
		["Follow Erudil"] =
			{appendText="."},
		[6] = 
			{appendStepText="", stepTextKey="We encountered one of Erudil's classmates—a Wood Elf named Glardir. I should ask Erudil about her and how she fits into all this."},
		["Talk to Erudil 4"] =
			{appendText=" in the central courtyard.", stepTextKey="We encountered one of Erudil's classmates—a Wood Elf named Glardir. I should ask Erudil about her and how she fits into all this."},
		[7] = 
			{appendStepText="", stepTextKey="Erudil thinks we can break the Illuminus enchantment by convincing the victims to act contrary to their new persona. I should try this idea out on his friends."},
		["Locate Erudil's Friends"] =
			{appendText=". Eurdil mentioned that Pavo is by the East Wall."},
		[8] = 
			{appendStepText="", stepTextKey="Erudil's friend, Pavo, is tucked away near the eastern wall of the academy. I should talk to him."},
		["Talk to Pavo 1"] =
			{appendText=".", stepTextKey="Erudil's friend, Pavo, is tucked away near the eastern wall of the academy. I should talk to him."},
		[9] = 
			{appendStepText="", stepTextKey="Pavo has taken on the persona of some sort of beggar. I should look through the nearby books to see if I can determine his false identity."},
		["Find Pavo's Story"] =
			{appendText="."},
		[10] = 
			{appendStepText="", stepTextKey="It seems that Pavo has taken on the role of the Beggar Prince. I can use this information to my advantage when I talk to him again."},
		["Talk to Pavo 2"] =
			{appendText=" by the eastern wall.", stepTextKey="It seems that Pavo has taken on the role of the Beggar Prince. I can use this information to my advantage when I talk to him again."},
		[11] = 
			{appendStepText="", stepTextKey="I've convinced Pavo that I can lift his curse. I should put on a show to convince him I've used my \"Daedric power.\""},
		["Lift Pavo's \"Curse\""] =
			{appendText="."},
		[12] = 
			{appendStepText="", stepTextKey="In \"lifting the curse,\" I've broken the Beggar Prince's central character trait. I should talk to Pavo again to see if this freed him from the Illuminus's enchantment."},
		["Talk to Pavo 3"] =
			{appendText=" by the eastern wall.", stepTextKey="In \"lifting the curse,\" I've broken the Beggar Prince's central character trait. I should talk to Pavo again to see if this freed him from the Illuminus's enchantment."},
		[13] = 
			{appendStepText="", stepTextKey="I should urge Pavo to return to Erudil in the central courtyard."},
		["Talk to Pavo 4"] =
			{appendText=" by the eastern wall.", stepTextKey="I should urge Pavo to return to Erudil in the central courtyard."},
		[14] = 
			{appendStepText="", stepTextKey="I broke the enchantment on Pavo. I should return to Erudil and give him the news."},
		["Talk to Erudil 5"] =
			{appendText=" in the central courtyard.", stepTextKey="I broke the enchantment on Pavo. I should return to Erudil and give him the news."},
		[15] = 
			{appendStepText="", stepTextKey="I should read the Illuminus to see how the pages have changed."},
		["Read the Illuminus 2"] =
			{appendText="on the bench next to Glardir in the central courtyard.", stepTextKey="I should read the Illuminus to see how the pages have changed."},
		[16] = 
			{appendStepText="", stepTextKey="New text has appeared in the Illuminus. I should discuss this new development with Erudil."},
		["Talk to Erudil 6"] =
			{appendText=" in the central courtyard.", stepTextKey="New text has appeared in the Illuminus. I should discuss this new development with Erudil."},
		[17] = 
			{appendStepText="", stepTextKey="Erudil's friend, Tanelwen, should be lingering in the lecture garden. I should talk to her."},
		["Talk to Tanelwen 1"] =
			{appendText=" in the northern garden.", stepTextKey="Erudil's friend, Tanelwen, should be lingering in the lecture garden. I should talk to her."},
		[18] = 
			{appendStepText="", stepTextKey="Tanelwen insists she's some kind of investigator. I should read some of the books nearby to determine her adopted persona."},
		["Find Tanelwen's Story"] =
			{appendText="."},
		[19] = 
			{appendStepText="", stepTextKey="I found a book detailing the adventures of a fictional detective, Investigator Vale. This must be Tanelwen's persona. Now that I know who she is, I should talk to her again."},
		["Talk to Tanelwen 2"] =
			{appendText=" in the lecture garden.", stepTextKey="I found a book detailing the adventures of a fictional detective, Investigator Vale. This must be Tanelwen's persona. Now that I know who she is, I should talk to her again."},
		[20] = 
			{appendStepText="", stepTextKey="Acting out the role of Investigator Vale, Tanelwen is sure that she knows the identity of the pie thief. Perhaps if I prove her wrong, her enchantment will break."},
		["Find the Real Pie Thief"] =
			{appendText=". I should check for clues and listen to the witnesses in the lecture garden."},
		[21] = 
			{appendStepText="", stepTextKey="I found a guilty-looking dog sitting near a half-eaten pie. This is clearly the culprit. I should take the half-eaten pie as evidence."},
		["Gather the Evidence"] =
			{appendText="."},
		[22] = 
			{appendStepText="", stepTextKey="I should take the half-eaten pie back to Tanelwen and prove her wrong. Hopefully that will break the Illuminus enchantment."},
		["Talk to Tanelwen 3"] =
			{appendText=" in the lecture garden.", stepTextKey="I should take the half-eaten pie back to Tanelwen and prove her wrong. Hopefully that will break the Illuminus enchantment."},
		[23] = 
			{appendStepText="", stepTextKey="I should urge Tanelwen to meet up with Erduil in the central courtyard."},
		["Talk to Tanelwen 4"] =
			{appendText=" in the lecture garden.", stepTextKey="I should urge Tanelwen to meet up with Erduil in the central courtyard."},
		[24] = 
			{appendStepText="", stepTextKey="I broke the enchantment on Tanelwen. I should return to Erudil and give him the news."},
		["Talk to Erudil 7"] =
			{appendText=" back in the central courtyard.", stepTextKey="I broke the enchantment on Tanelwen. I should return to Erudil and give him the news."},
		[25] = 
			{appendStepText="", stepTextKey="Erudil's friend, Selynia, is standing high atop the Academy's walls. I should go talk to her. Perhaps I can find a way to break the enchantment's hold on her."},
		["Talk to Selynia 1"] =
			{appendText=". I can get to the top of the walls through the Faculty Hall.", stepTextKey="Erudil's friend, Selynia, is standing high atop the Academy's walls. I should go talk to her. Perhaps I can find a way to break the enchantment's hold on her."},
		[26] = 
			{appendStepText="", stepTextKey="Selynia mentioned that the key to her identity is nearby. I should sift through these books to find some clues."},
		["Find Selynia's Story"] =
			{appendText="."},
		[27] = 
			{appendStepText="", stepTextKey="I discovered Selynia's persona: The Brave Little Scrib. I should talk to her again. Maybe I can use this information to help break the enchantment."},
		["Talk to Selynia 2"] =
			{appendText=" at the top of the eastern wall.", stepTextKey="I discovered Selynia's persona: The Brave Little Scrib. I should talk to her again. Maybe I can use this information to help break the enchantment."},
		[28] = 
			{appendStepText="", stepTextKey="Selynia's persona, the Brave Little Scrib, isn't afraid of anything. If I can find something that frightens Selynia, I might be able to force her out of character and break the enchantment."},
		["Collect a Spider to Scare Selynia"] =
			{appendText=". I should check the gardens for one."},
		[29] = 
			{appendStepText="", stepTextKey="I found and captured a spider in the Academy courtyard. I should release it near Selynia to scare her. Hopefully this will break the Illuminus's enchantment."},
		["Scare Selynia"] =
			{appendText="."},
		[30] = 
			{appendStepText="", stepTextKey="Scaring Selynia seems to have worked! I should talk to her and send her back to Erudil."},
		["Talk to Selynia 3"] =
			{appendText=". I saw her run back into the academy.", stepTextKey="Scaring Selynia seems to have worked! I should talk to her and send her back to Erudil."},
		[31] = 
			{appendStepText="", stepTextKey="I rescued Selynia from the Illuminus's enchantment. I should return to Erudil so we can plot our next move."},
		["Talk to Erudil 8"] =
			{appendText=" in the central courtyard.", stepTextKey="I rescued Selynia from the Illuminus's enchantment. I should return to Erudil so we can plot our next move."},
		[32] = 
			{appendStepText="", stepTextKey="The persona that has taken hold of Glardir is clearly linked to the Illuminus's shifting and ominous text. I should confront Glardir and learn her role in this once and for all."},
		["Talk to Glardir"] =
			{appendText=" in the central courtyard."},
		[33] = 
			{appendStepText="", stepTextKey="Glardir took the Illuminus and fled toward the Hall of Illumination! I need to track her down."},
		["Talk to Erudil 9"] =
			{appendText=" in the central courtyard.", stepTextKey="Glardir took the Illuminus and fled toward the Hall of Illumination! I need to track her down."},
		[34] = 
			{appendStepText="", stepTextKey="It appears that Glardir has taken refuge in the Academy Stacks. I must pursue her."},
		["Explore the Academy Stacks"] =
			{appendText=". I can get in through a door in the lecture garden."},
		[35] = 
			{appendStepText="", stepTextKey="The Stacks are in a state of magical chaos. Perhaps the archivist can help shed some light on the situation."},
		["Talk to Meredil the Archivist"] =
			{appendText="."},
		[36] = 
			{appendStepText="", stepTextKey="The archivist was clearly affected by the enchantment, but he still managed to give me good advice. I must dispel the Illuminus's hostile illusions by closing the book they sprung from and filing it away in the stacks."},
		["Dispel the Illusions 1"] =
			{appendText=". I should pay attention to the subject matter of the story so I file it away in the correct place.", stepTextKey="The archivist was clearly affected by the enchantment, but he still managed to give me good advice. I must dispel the Illuminus's hostile illusions by closing the book they sprung from and filing it away in the stacks."},
		[37] = 
			{appendStepText="", stepTextKey="I dispelled the forest illusions. I should delve deeper into the archives and dispel any other illusions I find."},
		["Dispel the Illusions 2"] =
			{appendText=". I should pay attention to the subject matter of the story so I file it away in the correct place.", stepTextKey="I dispelled the forest illusions. I should delve deeper into the archives and dispel any other illusions I find."},
		[38] = 
			{appendStepText="", stepTextKey="I managed to dispel the Imperial illusions. I should delve deeper into the archives and banish any other illusions I find."},
		["Dispel the Illusions 3"] =
			{appendText=". I should pay attention to the subject matter of the story so I file it away in the correct place.", stepTextKey="I managed to dispel the Imperial illusions. I should delve deeper into the archives and banish any other illusions I find."},
		[39] = 
			{appendStepText="", stepTextKey="I banished the minotaur illusions, clearing the way to the archives' central chamber. I must defeat the source of this enchantment."},
		["Kill the Illuminated One"] =
			{appendText="."},
		[40] = 
			{appendStepText="", stepTextKey="I defeated the Illuminated One. Now, I must place the book back on the shelf to break the enchantment once and for all."},
		["Shelve the Illuminus"] =
			{appendText=" on the strange, glowing shelf that houses the Shrieking Tomes."},
		[41] = 
			{appendStepText="", stepTextKey="I defeated and locked away the spirit of the Illuminus. I should inform Erudil of my success."},
		["Talk to Erudil 10"] =
			{appendText=" back in the lecture garden.", stepTextKey="I defeated and locked away the spirit of the Illuminus. I should inform Erudil of my success."},
	},

	[GetQuestName(6118)] = { --"Lauriel's Lament"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="Bailiff Erator gave me his blessing to search the acropolis grounds. Perhaps I can find some clues as to what happened here."},
		["Search the Acropolis Grounds"] =
			{appendText=" and Manor."},
		[2] = 
			{appendStepText="", stepTextKey="The note I found indicated that a group of Elves called the Keepers were charged with protecting something in the castle catacombs. This one is carrying a key and a seal. I might be able to use them to explore further."},
		["Take the Golden Seal"] =
			{appendText=" from the coffer."},
		["Take the Keeper's Key"] =
			{appendText=" from the coffer."},
		[3] = 
			{appendStepText="", stepTextKey="I should use the key I found to enter the catacombs. Perhaps I'll find more answers there."},
		["Explore the Catacombs"] =
			{appendText=" that run beneath the manor. I can get into them from the grounds to the east."},
		[4] = 
			{appendStepText="", stepTextKey="I discovered an ancient stone tablet. I should examine it to see what it says. It might explain how to use this golden seal."},
		["Examine the Inscription"] =
			{appendText=" in the entrance to the catacombs."},
		[5] = 
			{appendStepText="", stepTextKey="The inscription on the tablet referenced the \"Eyes of the Keepers\" looking upon something below. A recess in a nearby pillar looks like a perfect fit for the seal. I should slot it in and see what happens."},
		["Place the Golden Seal"] =
			{appendText=" in the pillar."},
		[6] = 
			{appendStepText="", stepTextKey="A ghost suddenly appeared. I should talk to it."},
		["Talk to Lauriel 1"] =
			{appendText=" within the catacombs.", stepTextKey="A ghost suddenly appeared. I should talk to it."},
		[7] = 
			{appendStepText="", stepTextKey="The ghost identified itself as Lauriel and told me that it was bound to the lower catacombs, deep beneath the acropolis. I must find a Crimson Seal to gain entry to the acropolis' nethermost depths."},
		["Search for the Crimson Seal"] =
			{appendText=" within the Shattered Halls. Lauriel said to follow her voice."},
		[8] = 
			{appendStepText="", stepTextKey="I found the remains of a Keeper and the Crimson Seal. I should take it back to the main foyer of the catacombs."},
		["Take the Crimson Seal"] =
			{appendText="."},
		[9] = 
			{appendStepText="", stepTextKey="Now that I have the Crimson Seal I can place it on the pillar opposite the Golden Seal and open the way to the lower catacombs."},
		["Place the Crimson Seal"] =
			{appendText=" in the pillar."},
		[10] = 
			{appendStepText="", stepTextKey="I should search the lower catacombs for whatever is tormenting Lauriel's spirit."},
		["Find the Source of Lauriel's Binding"] =
			{appendText=" within the her crypt through the Forsaken Undercroft."},
		[11] = 
			{appendStepText="", stepTextKey="I found Lauriel's physical remains. They've been preserved and bound here for some reason. I should ask Lauriel's ghost about this."},
		["Talk to Lauriel 2"] =
			{appendText=" within her crypt.", stepTextKey="I found Lauriel's physical remains. They've been preserved and bound here for some reason. I should ask Lauriel's ghost about this."},
		[12] = 
			{appendStepText="", stepTextKey="Lauriel wants me to free her spirit by burning her remains. Conversely, I could light the Sanctified Brazier and bind her spirit back to her corpse, preventing her escape. I must take up the Keeper's flame and choose."},
		["Take the Keeper's Flame"] =
			{appendText=" from Lauriel's tomb."},
		[13] = 
			{appendStepText="", stepTextKey="With the Keeper's Flame in hand, I must choose whether to burn Lauriel's remains and free her spirit, or light the sanctified brazier to bind her once more."},
		["Burn the Remains to Free Lauriel"] =
			{appendText="."},
		["Light the Sanctified Brazier to Bind Lauriel"] =
			{appendText="."},
		[14] = 
			{appendStepText="", stepTextKey="I elected to free Lauriel's spirit. She said some unnerving things, then vanished shortly thereafter. I should return to Erator to inform him of all that's happened."},
		["Talk to Erator 1"] =
			{appendText=" in the small camp southeast of the Acropolis.", stepTextKey="I elected to free Lauriel's spirit. She said some unnerving things, then vanished shortly thereafter. I should return to Erator to inform him of all that's happened."},
		[15] = 
			{appendStepText="", stepTextKey="I elected to light the Sanctified Brazier, thus binding Lauriel's spirit to her tomb once again. I should return to Erator and tell him about all that's transpired."},
		["Talk to Erator 2"] =
			{appendText=" in the small camp southeast of the Acropolis.", stepTextKey="I elected to light the Sanctified Brazier, thus binding Lauriel's spirit to her tomb once again. I should return to Erator and tell him about all that's transpired."},
	},

   [GetQuestName(6137)] = { --"Looting the Light"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="Seeks-the-Dark needs me to collect several tokens of Meridia from Eton Nir. I should search within the cult's camp. I should also see if I can find his assistant, Erilthel."},
        ["Obtain Tokens of Meridia"] =
            {appendText=" \n\nThe cult's camp is in the north section of the grotto guarded by daedra.\n"},
        ["Find Erilthel"] =
            {appendText=". If she still lives, the spiders may have taken her further southwest into the caves to feed on her."},
        [2] = 
            {appendStepText="", stepTextKey="I've recovered the tokens and saved Erilthel. I should let Seeks-the-Dark know."},
        ["Talk to Seeks-the-Dark"] =
            {appendText=" at the entrance to Nir Grotto."},
    },

   [GetQuestName(6149)] = { --"Lost at Sea"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="I have arrived at Wasten Coraldale without incident to begin my search for Curtaros."},
        ["Locate Curtaros"] =
            {appendText=". I should check for secluded spots along the beach here. He's probably got a camp set up somewhere."},
        [2] = 
            {appendStepText="", stepTextKey="Wasten Coraldale has been invaded by hostile Sea Elf raiders, but I found Curtaros asleep and unharmed. After I informed him of the danger he asked me to find the other members of his angler fleet while he keeps an eye on the invaders."},
        ["Find the Missing Crewmembers"] =
            {appendText=" \n\nIf they're alive and not captured yet, they're probably well away from the majority of the pirates lurking about. I should check for decent hiding spots.\n\nPerhaps I can use the hidden overlook in the central Salamander den to scope out any hard to find members of Curtaros's crew."},
        [3] = 
            {appendStepText="", stepTextKey="I located the other anglers, but one of them didn't survive the sudden Sea Elf occupation. I should meet up with Curtaros and the survivors."},
        ["Talk to Curtaros"] =
            {appendText=". He said to meet him under the lovers' tree on the east end of the island."},
        [4] = 
            {appendStepText="", stepTextKey="Curtaros told me that the Sea Elves have already begun to entrench themselves in Wasten Coraldale and will pose a significant threat to Summerset and its navy if they're allowed to establish a foothold. I agreed to help him disrupt their efforts."},
        ["Defend the Ballista"] =
            {appendText=", while Curtaros mans the Ballista in the main Sea Elf encampment on the shore."},
        [5] = 
            {appendStepText="", stepTextKey="Curtaros and I heavily damaged a Sea Elf ship. I should use this chance to make my escape from Wasten Coraldale."},
        ["Leave Wasten Coraldale"] =
            {appendText="."},
        [6] = 
            {appendStepText="", stepTextKey="Curtaros and I heavily damaged a Sea Elf ship and caused enough chaos to make a successful escape from Wasten Coraldale. I should speak to Hiranesse now that I have returned her father safely home."},
        ["Talk to Hiranesse"] =
            {appendText=", on the beach next to the raft to Wasten Coraldale."},
    },


[GetQuestName(6114)] = { --"Manor of Masques"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="I should find out more about Larydel from his sister, Rinyde."},
		["Talk to Rinyde 1"] =
			{appendText=" in the center of Rellenthil.", stepTextKey="I should find out more about Larydel from his sister, Rinyde."},
		[2] = 
			{appendStepText="", stepTextKey="Rinyde gave me enchanted daggers that will allow me to impress Alchemy, a House of Reveries sponsor. I must perform for her at the ampitheater in Rellenthil."},
		["Perform for Alchemy"] =
			{appendText=" by the soapbox that has been set up for auditioners on the stage.\n"},
		[3] = 
			{appendStepText="", stepTextKey="Alchemy seems impressed by my performance. I should speak with her."},
		["Talk to Alchemy 1"] =
			{appendText=" in the amphitheater in Rellenthil.", stepTextKey="Alchemy seems impressed by my performance. I should speak with her."},
		[4] = 
			{appendStepText="", stepTextKey="Alchemy tasked me to find a gryphon feather for the mask I will wear as a Hopeful of the House of Reveries. I should look for a nest by a lake near Rellenthil."},
		["Find a Gryphon Feather"] =
			{appendText="."},
		[5] = 
			{appendStepText="", stepTextKey="I acquired a gryphon feather. I should present it to Alchemy."},
		["Talk to Alchemy 2"] =
			{appendText=" in front of the Manor of Masques in Rellenthil.", stepTextKey="I acquired a gryphon feather. I should present it to Alchemy."},
		[6] = 
			{appendStepText="", stepTextKey="I successfully became a Hopeful, a potential House of Reveries member. I should inform Rinyde and learn our next step."},
		["Talk to Rinyde 2"] =
			{appendText=" in the little bar below the Manor of Masques in Rellenthil.", stepTextKey="I successfully became a Hopeful, a potential House of Reveries member. I should inform Rinyde and learn our next step."},
		[7] = 
			{appendStepText="", stepTextKey="Rinyde kept a journal of her interactions with her brother, Larydel. Reading the journal may help me know what to look for when interviewing the other potentials."},
		["Read Rinyde's Journal"] =
			{appendText=" next to Rinyde in the little bar below the Manor of Masques in Rellenthil."},
		[8] = 
			{appendStepText="", stepTextKey="The first masked potential calls himself Firebird. I should play the Game of Boasts and try to learn if he is Larydel in disguise."},
		["Talk to Firebird 1"] =
			{appendText=" within the Manor of Masques in Rellenthil. I should wear my newly aquired mask to better fit in.", stepTextKey="The first masked potential calls himself Firebird. I should play the Game of Boasts and try to learn if he is Larydel in disguise."},
		[9] = 
			{appendStepText="", stepTextKey="Firebird asked me to juggle daggers while he breathes flame, so we can practice performing together. This is required before we can play the Game of Boasts."},
		["Perform with Firebird"] =
			{appendText=" within the Manor of Masques in Rellenthil."},
		[10] = 
			{appendStepText="", stepTextKey="I performed with Firebird and can now ask one question. I should ask him a question that might help me discover if he is Larydel."},
		["Talk to Firebird 2"] =
			{appendText=" within the Manor of Masques in Rellenthil.", stepTextKey="I performed with Firebird and can now ask one question. I should ask him a question that might help me discover if he is Larydel."},
		[11] = 
			{appendStepText="", stepTextKey="The second masked potential calls herself Clever. I should play the Game of Boasts and try to learn if she is Larydel in disguise."},
		["Talk to Clever 1"] =
			{appendText=" within the Manor of Masques in Rellenthil.", stepTextKey="The second masked potential calls herself Clever. I should play the Game of Boasts and try to learn if she is Larydel in disguise."},
		[12] = 
			{appendStepText="", stepTextKey="Clever cannot speak while performing her act, sword swallowing. I should announce her performance."},
		["Announce Clever's Performance"] =
			{appendText=" by the soapbox next to Clever within the Manor of Masques in Rellenthil."},
		[13] = 
			{appendStepText="", stepTextKey="I performed with Clever, and we may now play the Game of Boasts. I should ask her a question that might help me discover if she is Larydel."},
		["Talk to Clever 2"] =
			{appendText=" within the Manor of Masques in Rellenthil.", stepTextKey="I performed with Clever, and we may now play the Game of Boasts. I should ask her a question that might help me discover if she is Larydel."},
		[14] = 
			{appendStepText="", stepTextKey="The third masked potential calls himself Feathermoth. I should play the Game of Boasts and try to learn if he is Larydel in disguise."},
		["Talk to Feathermoth 1"] =
			{appendText=" within the dance studio in the Manor of Masques in Rellenthil.", stepTextKey="The third masked potential calls himself Feathermoth. I should play the Game of Boasts and try to learn if he is Larydel in disguise."},
		[15] = 
			{appendStepText="", stepTextKey="Feathermoth asked me to drum in time to his dancing. I must perform with him before he will play the Game of Boasts."},
		["Follow Feathermoth's Performance"] =
			{appendText=". I should read the sheet music to keep time for him within the dance studio in the Manor of Masques in Rellenthil."},
		[16] = 
			{appendStepText="", stepTextKey="I satisfied Feathermoth's desire for a joint performance. I should ask him a question to decide if he might be Larydel in disguise."},
		["Talk to Feathermoth 2"] =
			{appendText=" within the dance studio in the Manor of Masques in Rellenthil.", stepTextKey="I satisfied Feathermoth's desire for a joint performance. I should ask him a question to decide if he might be Larydel in disguise."},
		[17] = 
			{appendStepText="", stepTextKey="I spoke with the three Hopefuls who may be Larydel. Now I should talk to Rinyde and announce my conclusions."},
		["Talk to Rinyde 3"] =
			{appendText=" in the little bar below the Manor of Masques in Rellenthil.", stepTextKey="I spoke with the three Hopefuls who may be Larydel. Now I should talk to Rinyde and announce my conclusions."},
		[18] = 
			{appendStepText="", stepTextKey="Rinyde was not present when I arrived. Instead, Alchemy was waiting for me. I should speak to her and find out what she wants."},
		["Talk to Alchemy 3"] =
			{appendText=" in the little bar below the Manor of Masques in Rellenthil.", stepTextKey="Rinyde was not present when I arrived. Instead, Alchemy was waiting for me. I should speak to her and find out what she wants."},
		[19] = 
			{appendStepText="", stepTextKey="Alchemy is aware I have been trying to find Larydel! She is now curious who I think Larydel might be. I should share my theories."},
		["Guess Larydel's Identity"] =
			{appendText=" in the little bar below the Manor of Masques in Rellenthil. I should consult Rinyde's journal and compare it to my findings from my interactions with everyone I've met so far."},
		[20] = 
			{appendStepText="", stepTextKey="Alchemy asked me to leave Larydel alone, and to inform Rinyde she should do the same. I should speak to her about finding Larydel."},
		["Talk to Alchemy 4"] =
			{appendText=" in the little bar below the Manor of Masques in Rellenthil.", stepTextKey="Alchemy asked me to leave Larydel alone, and to inform Rinyde she should do the same. I should speak to her about finding Larydel."},
		[21] = 
			{appendStepText="", stepTextKey="Alchemy said that Larydel has always envied Rinyde's talent with magic, which is why he left. I should tell Rinyde what I discovered."},
		["Talk to Rinyde 4"] =
			{appendText=" on the beach near the docks west of Rellenthil.", stepTextKey="Alchemy said that Larydel has always envied Rinyde's talent with magic, which is why he left. I should tell Rinyde what I discovered."},
		[22] = 
			{appendStepText="", stepTextKey="Rinyde decided to reveal all the performers during their audition for the Grand Maestro using magic. This could prevent innocent performers from being able to join the troupe. I can warn Alchemy about this or let Rinyde cast her spell."},
		["Warn Alchemy"] =
			{appendText=" in the amphitheater in Rellenthil."},
		["Lie to Alchemy"] =
			{appendText=" in the amphitheater in Rellenthil."},
		[23] = 
			{appendStepText="", stepTextKey="I decided to let Rinyde cast her spell and reveal the performers auditioning for the House of Reveries. I should watch the audition."},
		["Watch Audition"] =
			{appendText=" in the amphitheater in Rellenthil."},
		[24] = 
			{appendStepText="", stepTextKey="I decided to let Rinyde cast her spell and reveal the performers auditioning for the House of Reveries. I should wait for Grand Maestro Forte to start the audition."},
		["Wait for the Grand Maestro"] =
			{appendText=" in the amphitheater in Rellenthil."},
		[25] = 
			{appendStepText="", stepTextKey="I decided to let Rinyde cast her spell and reveal the performers auditioning for the House of Reveries. I should stand aside and watch the drama play out."},
		["Wait for Rinyde"] =
			{appendText=" in the ampitheater in Rellenthil."},
		[26] = 
			{appendStepText="", stepTextKey="Alchemy left the ampitheater after Rinyde cast her spell. I should speak to Alchemy about what happened."},
		["Talk to Alchemy 5"] =
			{appendText=" in front of or perhaps within the Manor of Masques in Rellenthil.", stepTextKey="Alchemy left the ampitheater after Rinyde cast her spell. I should speak to Alchemy about what happened."},
		[27] = 
			{appendStepText="", stepTextKey="Alchemy has revealed that she is Larydel! She's been a member of the House of Reveries for a year, but feared telling her sister would convince Rinyde not to follow her dream. I can advise Alchemy to tell her sister the truth or to keep lying."},
		["Suggest The Truth"] =
			{appendText=" in front of the Manor of Masques in Rellenthil."},
		["Suggest A Lie"] =
			{appendText=" in front of the Manor of Masques in Rellenthil."},
		[28] = 
			{appendStepText="", stepTextKey="I advised Alchemy to tell her sister the truth about who she is. I should find Rinyde before she leaves Rellenthil and make sure she stays to speak to Alchemy."},
		["Talk To Rinyde 5"] =
			{appendText=" on the beach near the docks west of Rellenthil."},
		[29] = 
			{appendStepText="", stepTextKey="I advised Alchemy to tell her sister the truth about who she is. I must find Rinyde before she leaves Rellenthil and make sure she stays to speak to Alchemy."},
		["Talk to Rinyde 6"] =
			{appendText=" where I left her on the beach near the docks west of Rellenthil.", stepTextKey="I advised Alchemy to tell her sister the truth about who she is. I must find Rinyde before she leaves Rellenthil and make sure she stays to speak to Alchemy."},
		[30] = 
			{appendStepText="", stepTextKey="I agreed to work with Alchemy to absorb the spell cast by Rinyde, revealing my identity but protecting the others. I should first join the audition so Rinyde doesn't suspect anything."},
		["Take the Stage"] =
			{appendText=" in the amphitheater in Rellenthil."},
		[31] = 
			{appendStepText="", stepTextKey="I agreed to work with Alchemy to absorb the spell cast by Rinyde, revealing my identity but protecting the others. I should listen to my cue to start my audition."},
		["Listen for Your Cue"] =
			{appendText=" in the amphitheater in Rellenthil."},
		[32] = 
			{appendStepText="", stepTextKey="I agreed to work with Alchemy to absorb the spell cast by Rinyde, revealing my identity but protecting the others. I should begin the audition by juggling alongside Firebird."},
		["Juggle"] =
			{appendText=" in the amphitheater in Rellenthil."},
		[33] = 
			{appendStepText="", stepTextKey="I agreed to work with Alchemy to absorb the spell cast by Rinyde, revealing my identity but protecting the others. I should go to my next mark."},
		["Go To Your Mark 1"] =
			{appendText=" in the amphitheater in Rellenthil.", stepTextKey="I agreed to work with Alchemy to absorb the spell cast by Rinyde, revealing my identity but protecting the others. I should go to my next mark."},
		[34] = 
			{appendStepText="", stepTextKey="I've agreed to work with Alchemy to absorb the spell cast by Rinyde, revealing my identity but protecting the others. I should cheer Clever's performance to pump up the crowd."},
		["Cheer"] =
			{appendText=" in the amphitheater in Rellenthil."},
		[35] = 
			{appendStepText="", stepTextKey="I've agreed to work with Alchemy to absorb the spell cast by Rinyde, revealing my identity but protecting the others. I should go to my next mark."},
		["Go To Your Mark 2"] =
			{appendText=" in the amphitheater in Rellenthil.", stepTextKey="I've agreed to work with Alchemy to absorb the spell cast by Rinyde, revealing my identity but protecting the others. I should go to my next mark."},
		[36] = 
			{appendStepText="", stepTextKey="I've agreed to work with Alchemy to absorb the spell cast by Rinyde, revealing my identity but protecting the others. I should play the drum to help Feathermoth keep his rhythm."},
		["Drum"] =
			{appendText=" in the amphitheater in Rellenthil."},
		[37] = 
			{appendStepText="", stepTextKey="I successfully gained Rinyde's attention. I should now wait to be unmasked on stage."},
		["Wait to Be Unmasked"] =
			{appendText=" in the amphitheater in Rellenthil."},
		[38] = 
			{appendStepText="", stepTextKey="I advised Alchemy to write a letter to her sister after she's settled in Lillandril, explaining who she really is and why she lied. I must find Rinyde and ensure she knows a letter is coming."},
		["Talk to Rinyde 7"] =
			{appendText=" on the beach near the docks west of Rellenthil.", stepTextKey="I advised Alchemy to write a letter to her sister after she's settled in Lillandril, explaining who she really is and why she lied. I must find Rinyde and ensure she knows a letter is coming."},
		[39] = 
			{appendStepText="", stepTextKey="I advised Alchemy to write a letter to her sister once she arrives in Lillandril, explaining who she really is and why she lied. I must find Rinyde and ensure she knows a letter is coming."},
		["Talk to Rinyde 8"] =
			{appendText=" on the beach near the docks west of Rellenthil.", stepTextKey="I advised Alchemy to write a letter to her sister once she arrives in Lillandril, explaining who she really is and why she lied. I must find Rinyde and ensure she knows a letter is coming."},
	},

[GetQuestName(6111)] = { --"Murder In Lillandril"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="I should ask Vivienne what else she knows about Haladan's murder, and why she believes Emile is innocent despite admitting to the crime."},
		["Talk to Vivienne"] =
			{appendText=" outside the Fighters Guild."},
		[2] = 
			{appendStepText="", stepTextKey="Vivienne asked me to speak to Emile and convince him to recant his murder confession. Though she does not know why he would falsely confess, she is convinced he did not kill Haladan, the Sapiarch who was murdered."},
		["Talk to Emile 1"] =
			{appendText=" within the Fighters Guild.", stepTextKey="Vivienne asked me to speak to Emile and convince him to recant his murder confession. Though she does not know why he would falsely confess, she is convinced he did not kill Haladan, the Sapiarch who was murdered."},
		[3] = 
			{appendStepText="", stepTextKey="A High Elf arrived shortly after I finished questioning Emile. I should talk to her."},
		["Talk to Calawende 1"] =
			{appendText=" within the Fighters Guild.", stepTextKey="A High Elf arrived shortly after I finished questioning Emile. I should talk to her."},
		[4] = 
			{appendStepText="", stepTextKey="Calawende suggested I search Galidor's ledger to find out what dealings he had with Emile. The ledger is magically warded, but I can make it readable by learning and reciting a passphrase. Perhaps I'll find some clues in Galidor's room."},
		["Enter Galidor's Room"] =
			{appendText=" on the top floor of the Shrewd Brew."},
		[5] = 
			{appendStepText="", stepTextKey="Calawende suggested I search Galidor's ledger to find out what dealings he had with Emile. The ledger is magically warded, but I can make it readable by learning and reciting a passphrase. Perhaps I'll find some clues in Galidor's room."},
		["Search Galidor's Room"] =
			{appendText=" on the top floor of the Shrewd Brew."},
		[6] = 
			{appendStepText="", stepTextKey="I found several words in Galidor's notes that seem significant. If I say these words in the correct order, perhaps I can reveal the contents of Galidor's black market ledger."},
		["Unlock Galidor's Ledger"] =
			{appendText=" on the top floor of the Shrewd Brew."},
		[7] = 
			{appendStepText="", stepTextKey="I successfully revealed the contents of Galidor's black market ledger! I should read it to determine what he sold Emile in the days before Haladan's murder."},
		["Read Galidor's Ledger"] =
			{appendText=" on the top floor of the Shrewd Brew."},
		[8] = 
			{appendStepText="", stepTextKey="According to Galidor's ledger, Emile made a very unusual purchase: a keg filled with sheep's blood and several alchemical syringes. I should speak with Calawende. Perhaps she can shed some light on this."},
		["Talk to Calawende 2"] =
			{appendText=" outside of the Shrewd Brew.", stepTextKey="According to Galidor's ledger, Emile made a very unusual purchase: a keg filled with sheep's blood and several alchemical syringes. I should speak with Calawende. Perhaps she can shed some light on this."},
		[9] = 
			{appendStepText="", stepTextKey="When he returned to Lillandril, Emile confessed his guilt to a local Lillandril Guard named Milerond. Calawende suggested I speak to Milerond to learn more about Emile's confession and see if there's anything she missed."},
		["Talk to Milerond"] =
			{appendText=". Calawende may be able to tell me where he is."},
		[10] = 
			{appendStepText="", stepTextKey="The guard, Milerond, seems convinced that the answers I seek can be found in the nearby Saltbreeze Cave. I should search this cavern for clues."},
		["Explore Saltbreeze Cave"] =
			{appendText=". Milerond told me that the cave is along the coast south of Lillandril with mages' tools scattered about the entrance."},
		[11] = 
			{appendStepText="", stepTextKey="A shambling stone-skinned creature lurks near a locked door deep within the seaside cave. I must defeat this abomination if I wish to continue my investigation."},
		["Kill Gerwerdel"] =
			{appendText="."},
		[12] = 
			{appendStepText="", stepTextKey="The stone creature, Gerwerdel, lingered near a chest that might belong to Haladan. I should see what's inside. Perhaps it will help me gain entry to the locked room nearby."},
		["Collect the Laboratory Key"] =
			{appendText="."},
		[13] = 
			{appendStepText="", stepTextKey="The key I found allows me to access the locked room—some kind of laboratory. I should explore this subterranean workshop. Perhaps I can discover what Haladan and Emile were doing here before the murder."},
		["Explore the Laboratory"] =
			{appendText="."},
		[14] = 
			{appendStepText="", stepTextKey="I found a blind vampire hiding in Haladan's laboratory. She does not appear hostile. I should speak with her."},
		["Talk to Norasea"] =
			{appendText="."},
		[15] = 
			{appendStepText="", stepTextKey="The vampire, Norasea, explained that the stone abomination, not Emile, murdered Haladan. Haladan's notes and my testimony could exonerate Emile. I should collect these notes."},
		["Collect Haladan's Notes"] =
			{appendText="."},
		[16] = 
			{appendStepText="", stepTextKey="Haladan's notes corroborate Norasea's story. Emile and Haladan treated her illness with vampirism, and Norasea's deranged companion killed Haladan. Emile's made a false confession to protect Haldan's legacy. I must speak with Emile to settle this."},
		["Talk to Emile 2"] =
			{appendText=" within the Fighters Guild.", stepTextKey="Haladan's notes corroborate Norasea's story. Emile and Haladan treated her illness with vampirism, and Norasea's deranged companion killed Haladan. Emile's made a false confession to protect Haldan's legacy. I must speak with Emile to settle this."},
		[17] = 
			{appendStepText="While still being held within the Fighters Guild, ", stepTextKey="Emile pleaded with me to keep what I found a secret. I can respect Emile's wishes and allow him to be falsely imprisoned, or I can tell the Sapiarchs the truth, thus destroying Haladan's reputation, and potentially putting Norasea's life in jeopardy."},
		["Prove Emile Innocent"] =
			{appendText=".\n"},
		["Respect Emile's Wishes"] =
			{appendText="."},
		[18] = 
			{appendStepText="", stepTextKey="I chose to ignore Emile's wishes and tell Sapiarch Soraturil that Emile did not kill Haladan. Emile will go free, but Haladan's reputation will be ruined, and Norasea's life will be imperiled."},
		["Talk to Sapiarch Soraturil 1"] =
			{appendText=" within the Fighters Guild.", stepTextKey="I chose to ignore Emile's wishes and tell Sapiarch Soraturil that Emile did not kill Haladan. Emile will go free, but Haladan's reputation will be ruined, and Norasea's life will be imperiled."},
		[19] = 
			{appendStepText="", stepTextKey="I chose to respect Emile's wishes and lie to Sapiarch Soraturil, confirming that Emile murdered Haladan. This will ensure the Sapiarchs don't go looking for Norasea, Haladan's friend, and keep Haladan's reputation intact."},
		["Talk to Sapiarch Soraturil 2"] =
			{appendText=" within the Fighters Guild.", stepTextKey="I chose to respect Emile's wishes and lie to Sapiarch Soraturil, confirming that Emile murdered Haladan. This will ensure the Sapiarchs don't go looking for Norasea, Haladan's friend, and keep Haladan's reputation intact."},
		[20] = 
			{appendStepText="", stepTextKey="I chose to respect Emile's wishes and lie to Sapiarch Soraturil, confirming Emile murdered Haladan. This will ensure the Sapiarchs don't go looking for Norasea, Haladan's friend, and ensure Haladan's reputation remains respected."},
		["Talk to Sapiarch Soraturil 3"] =
			{appendText=" within the Fighters Guild.", stepTextKey="I chose to respect Emile's wishes and lie to Sapiarch Soraturil, confirming Emile murdered Haladan. This will ensure the Sapiarchs don't go looking for Norasea, Haladan's friend, and ensure Haladan's reputation remains respected."},
	},

    [GetQuestName(6180)] = { --"Obedience Issues"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="Kinlady Ilunsare told me that her husband, Durell, chased after their dog, Eustasia, who ran off into the wilderness. They were headed north the last time she saw them."},
        ["Find Durell and Eustasia"] =
            {appendText=". Kinlady Ilunare, whom I met on the southern coast of Summerset near Sunhold, mentioned they'd run east, back up the road, towards the Sunhold Wayshrine."},
        [2] = 
            {appendStepText="", stepTextKey="I found Eustasia and Durell. Unfortunately, Durell has met an untimely end. I should calm Eustasia and retrieve something from the body for Kinlady Ilunsare to identify."},
        ["Console Eustasia"] =
            {appendText=". The poor dog is standing vigil over his lifeless master."},
        ["Identify Durell"] =
            {appendText=", the male High Elf, lying dead by his dog east of the Sunhold Wayshrine near a rushing river with large rocks looming overhead."},
        [3] = 
            {appendStepText="", stepTextKey="I returned Eustasia safely to Kinlady Ilunsare, but she will want to hear about her late husband's fate. I should speak to her."},
        ["Talk to Kinlady Ilunsare"] =
            {appendText=", who I last saw on the southern coast of Summerset near Sunhold, and return her Husband's Locket as proof of death."},
    },

	[GetQuestName(6135)] = { --"Old Wounds"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="I should travel to Russafeld and speak with the Elves investigating this murder."},
		["Talk to Tarnamir"] =
			{appendText=", who is discussing the investigative procedure with his two colleagues in the center of Russafeld."},
		[2] = 
			{appendStepText="", stepTextKey="I should talk to High Examiner Lorne."},
		["Talk to Lorne 1"] =
			{appendText=", who can be found examining a corpse with her partner, Soravil, and mentor, Tarnamir, in the center of Russafeld, a vineyard west of Shimmerene.", stepTextKey="I should talk to High Examiner Lorne."},
		[3] = 
			{appendStepText="", stepTextKey="Lorne indicated that I should search for more clues in the grape-fields surrounding the murder scene. I should have a look around."},
		["Search the Fields"] =
			{appendText=" to the southwest of Russafeld. I should check for hiding spots like copses of trees and hollows. I should also question the bystanders near the fountain to find out what they know."},
		[4] = 
			{appendStepText="", stepTextKey="I discovered the body of a young Wood Elf in the fields, not far from the original murder scene. I should blow the whistle Lorne gave me to summon her and Soravil."},
		["Use the Whistle"] =
			{appendText=" to summon the invesigators to the large tree southwest of of Russafeld where I found the body."},
		[5] = 
			{appendStepText="", stepTextKey="The young Wood Elf's dress is spattered with blood, but I found no lacerations on her body. It's possible that she injured her assailant. I should search for more clues."},
		["Search the Vineyard for Clues"] =
			{appendText=". Jurisreeve Lorne asked me to find the source of the blood. There seems to be a trail leading southeast of Russafeld into a crevice between two large boulders."},
		[6] = 
			{appendStepText="", stepTextKey="I found a bloody sack. I should see if it contains any vital evidence."},
		["Search the Suspicious Sack"] =
			{appendText=" in the crevice between the rocks southeast of Russafeld."},
		[7] = 
			{appendStepText="", stepTextKey="I found a bloody sickle in the discarded sack. I should take it back to Lorne and tell her all that I've seen."},
		["Talk to Lorne 2"] =
			{appendText=", by the big tree and the female elf's body southwest of Russafeld.", stepTextKey="I found a bloody sickle in the discarded sack. I should take it back to Lorne and tell her all that I've seen."},
		[8] = 
			{appendStepText="", stepTextKey="Lorne asked me to search Halimorion's villa. She suspects that we might find evidence there that could give us insight into the murderer's motive."},
		["Search Halimorion's Villa"] =
			{appendText=". Jurisreeve Lorne said I could find it southwest of where I found the body, just to the east of Russafeld's wayshrine. I should check his private quarters for any documents or letters that might indicate a motive for his murder once I get there."},
		[9] = 
			{appendStepText="", stepTextKey="I found an unsent letter in Halimorion's villa that might implicate the nearby Bosmer in his murder. I should bring this information to Lorne."},
		["Talk to Lorne 3"] =
			{appendText=". She is waiting for me outside of Halimorion's villa, east of the Russafeld Wayshrine.", stepTextKey="I found an unsent letter in Halimorion's villa that might implicate the nearby Bosmer in his murder. I should bring this information to Lorne."},
		[10] = 
			{appendStepText="", stepTextKey="Evidence of bad-blood between Halimorion and the nearby Wood Elves keeps piling up. Lorne wants me to investigate the Wood Elf cottage. I'll meet her partner, Soravil, there."},
		["Investigate the Wood Elf Cottage"] =
			{appendText=". Jurisreeve Lorne said it could be found down the road east of the Russafeld Wayshrine close to the river."},
		[11] = 
			{appendStepText="", stepTextKey="It seems like the clan chief's wife might know something. I should speak to her."},
		["Talk to Elsoreth 1"] =
			{appendText=" inside the Wood Elf cottage on the southeast edge of Russafeld.", stepTextKey="It seems like the clan chief's wife might know something. I should speak to her."},
		[12] = 
			{appendStepText="", stepTextKey="It sounds like Elsoreth's son might be involved in the murders in one way or another. I should check his room."},
		["Search Celan's Room"] =
			{appendText=" on the second floor of the Wood Elf cottage on the southeast edge of Russafeld."},
		[13] = 
			{appendStepText="", stepTextKey="I found Celan's journal tucked under his bed. It may contain some useful clues. I should examine it."},
		["Examine Celan's Journal"] =
			{appendText=" on the second floor of the Wood Elf cottage on the southeast edge of Russafeld."},
		[14] = 
			{appendStepText="", stepTextKey="Celan's journal contains a confession that he killed the vintner, Halimorion. It looks like he fled to a nearby shrine to pray for forgiveness. I should tell Soravil about this."},
		["Talk to Soravil 1"] =
			{appendText= " outside of the Wood Elf cottage on the southeast edge of Russafeld.", stepTextKey="Celan's journal contains a confession that he killed the vintner, Halimorion. It looks like he fled to a nearby shrine to pray for forgiveness. I should tell Soravil about this."},
		[15] = 
			{appendStepText="", stepTextKey="Together with Soravil, I need to search the Red Temple for Celan and bring him to justice."},
		["Search the Red Temple"] =
			{appendText=". Jurisreeve Lorne said he knows of a shrine to Y'ffre to the west of the Wood Elf cottage on the southeast edge of Russafeld. There seems to be a path and torch light just visible from the cottage's front lawn."},
		[16] = 
			{appendStepText="", stepTextKey="Soravil and I split up to cover more ground. I should keep looking for Celan."},
		["Search for Celan"] =
			{appendText=". I should go east down the stairs and search the lower floors."},
		[17] = 
			{appendStepText="", stepTextKey="I found Celan, but the Ghost of the Green shot him with an arrow. He likely won't survive, but perhaps I can get some information from him before he dies."},
		["Talk to Celan"] =
			{appendText=", who lies expiring on the bottom floor of the Red Temple on the south edge of Russafeld."},
		[18] = 
			{appendStepText="", stepTextKey="Celan's wound proved fatal. The arrow that killed Celan resembles the one that killed Halimorion. I should take it. It might prove to be a useful clue."},
		["Take the Arrow That Killed Celan"] =
			{appendText=""},
		[19] = 
			{appendStepText="", stepTextKey="I should try to find Soravil before I leave the shrine."},
		["Talk to Soravil 2"] =
			{appendText=". Perhaps he's at the entrance of the Red Temple on the south edge of Russafeld.", stepTextKey="I should try to find Soravil before I leave the shrine."},
		[20] = 
			{appendStepText="", stepTextKey="I should take the arrow that killed Celan back to Lorne. Perhaps she can use her alchemical prowess to glean something from it."},
		["Talk to Lorne 4"] =
			{appendText=". She has returned to the scene of the crime in the center of Russafeld by the fountain.", stepTextKey="I should take the arrow that killed Celan back to Lorne. Perhaps she can use her alchemical prowess to glean something from it."},
		[21] = 
			{appendStepText="", stepTextKey="The blood sample was not a match for the bloody weapon found near Farril's body. Lorne believes this new Ghost of the Green killed her, but the trail is growing cold. She believes her friend Tarnamir can help us. I need to follow her to his manor."},
		["Go to Tarnamir's Manor"] =
			{appendText=". Jurisreeve Lorne took off towards the hill northwest of Russafeld with Tarnamir's large abode."},
		[22] = 
			{appendStepText="", stepTextKey="Someone ransacked the manor before we got here. I should examine the scene."},
		["Search the Area"] =
			{appendText=". I believe someone has vandalized the wall of the room where the bodies are arranged in Tarnamir's Manor northwest of Russafeld."},
		[23] = 
			{appendStepText="", stepTextKey="It appears that the Ghost of the Green arrived before us and killed Tarnamir. I should talk to Lorne."},
		["Talk to Lorne 5"] =
			{appendText=" at the crime scene in Tarnamir's Manor northwest of Russafeld.", stepTextKey="It appears that the Ghost of the Green arrived before us and killed Tarnamir. I should talk to Lorne."},
		[24] = 
			{appendStepText="", stepTextKey="Lorne chose to use a forbidden spell to learn the truth of these murders. I should stand back and observe."},
		["Observe Lorne's Spell"] =
			{appendText=" at the crime scene in Tarnamir's Manor northwest of Russafeld."},
		[25] = 
			{appendStepText="", stepTextKey="Lorne used a highly restricted spell to witness the last moments of the Ghost's victims' lives. It seems to be troubling her greatly that she resorted to using it. I should speak with her."},
		["Talk to Lorne 6"] =
			{appendText=". She left the manor in a hurry. The mostly clueless guard posted outside of Tarnamir's abode was looking westward down the road away from Russafeld towards a graveyard.", stepTextKey="Lorne used a highly restricted spell to witness the last moments of the Ghost's victims' lives. It seems to be troubling her greatly that she resorted to using it. I should speak with her."},
		[26] = 
			{appendStepText="", stepTextKey="Lorne's spell revealed that Soravil engineered all the murders in Russafeld. He wants Lorne to confront him in the Red Temple catacombs. I should accompany her there."},
		["Enter the Red Temple"] =
			{appendText=". It lies west down the road from Russafeld, in the graveyard where Jurisreeve Lorne said that Soravil's wife is interred."},
		[27] = 
			{appendStepText="", stepTextKey="I need to find Soravil before he escapes. He must be somewhere in the depths of the Red Temple."},
		["Pursue Soravil"] =
			{appendText=" deeper into the Red Temple, which lies west down the road from Russafeld."},
		[28] = 
			{appendStepText="", stepTextKey="I found Soravil in the depths of the Red Temple. There's nowhere left for him to run. It's obvious he won't allow himself to be arrested, so I have no choice but to end this by force."},
		["Kill Soravil"] =
			{appendText=" in the final chamber of the Red Temple, west down the road from Russafeld."},
		[29] = 
			{appendStepText="", stepTextKey="I defeated Soravil. I should return to Lorne to see if she's all right and inform her that Soravil is dealt with."},
		["Talk to Lorne 7"] =
			{appendText=" in the first chamber of the Red Temple that lies west down the road from Russafeld.", stepTextKey="I defeated Soravil. I should return to Lorne to see if she's all right and inform her that Soravil is dealt with."},
		[30] = 
			{appendStepText="", stepTextKey="With Soravil defeated, all that remains is to tell Celan's mother what happened to her son. I should go back to town to deliver the bad news."},
		["Talk to Elsoreth 2"] =
			{appendText=" in the center of Russafeld.", stepTextKey="With Soravil defeated, all that remains is to tell Celan's mother what happened to her son. I should go back to town to deliver the bad news."},
	},

    [GetQuestName(6144)] = { --"Pearls Before Traitors"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="I should try to find Captain Telomure and learn what happened."},
        ["Talk to Captain Telomure 1"] =
            {appendText=" at Tor-Hame-Khard, at the end of the looped road southwest of Shimmerene.", stepTextKey="I should try to find Captain Telomure and learn what happened."},
        [2] = 
            {appendStepText="", stepTextKey="Justiciar Avanaire fled deep into the ruins. I should find her and put a stop to her plan."},
        ["Kill Justiciar Avanaire"] =
            {appendText=". I'll have to fight my way through the ruins to get to her."},
        [3] = 
            {appendStepText="", stepTextKey="Justiciar Avanaire is dead. I should find and destroy the pearl."},
        ["Destroy the Pearl"] =
            {appendText=". It hovers there in the center of the room swirling dark, humming with eldritch energy."},
        [4] = 
            {appendStepText="", stepTextKey="I helped destroy the pearl and prevented Justiciar Avanaire from abusing its power. I should speak to Captain Telomure."},
        ["Talk to Captain Telomure 2"] =
            {appendText=". I should leave the ruins and see if he still waits for me outside. The journal of the fallen traitor in the corner of the room where I fought her and destroyed the pearl may prove of interest to him.", stepTextKey="I helped destroy the pearl and prevented Justiciar Avanaire from abusing its power. I should speak to Captain Telomure."},
    },

	[GetQuestName(6129)] = { --"The Perils of Art"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="The first ingredient on Tindoria's list can be obtained from an alchemist named Haenamil, who lives in a small hut in a remote area of Summerset. I should speak to her."},
		["Talk to Haenamil"] =
			{appendText=". Her home lies on a hill southwest of Cloudrest between Ebon Stadmont and the Aldmora Ruins."},
		[2] = 
			{appendStepText="", stepTextKey="It's time to collect the next ingredient on Tindoria's list, a bug carapace. I can acquire one at Brodran's bug farm, located in southeastern Summerset. I should speak to him."},
		["Talk to Brodran 1"] =
			{appendText=", whose home lies in the hills directly south of the fork in the road south of Shimmerene.", stepTextKey="It's time to collect the next ingredient on Tindoria's list, a bug carapace. I can acquire one at Brodran's bug farm, located in southeastern Summerset. I should speak to him."},
		[3] = 
			{appendStepText="", stepTextKey="Brodran refuses to give me a bug carapace because he believes Tindoria did something that dramatically lowered the hatchling numbers of his bugs. I should search for signs of sabotage on the farm."},
		["Look for Signs of Sabotage"] =
			{appendText=". Perhaps the saboteur is still nearby, hiding in the rocky terrain near Bro'Dran's home south of the fork in the road south of Shimmerene."},
		[4] = 
			{appendStepText="", stepTextKey="When I approached a barrel emitting a suspicious odor, I caught a High Elf pouring something into it. He seems alarmed. I should make him explain himself."},
		["Talk to Coreyon"] =
			{appendText=", south of the fork in the road south of Shimmerene near Bro'Dran's home."},
		[5] = 
			{appendStepText="", stepTextKey="The fumes from the barrel I found are suppressing the desire of Brodran's bugs to mate, leading to his problems with egg numbers. The saboteur I found claims Vaerelel put him up to it. I should smash the barrel to end the malaise."},
		["Destroy Fume Barrel"] =
			{appendText=", south of the fork in the road south of Shimmerene near Bro'Dran's home."},
		[6] = 
			{appendStepText="", stepTextKey="Vaerelel, not Tindoria, was responsible for sabotaging Brodran's farm by planting a barrel that created fumes which prevented his bugs from mating. I should inform Brodran of this."},
		["Talk to Brodran 2"] =
			{appendText=", back in his farm south of the fork in the road south of Shimmerene.", stepTextKey="Vaerelel, not Tindoria, was responsible for sabotaging Brodran's farm by planting a barrel that created fumes which prevented his bugs from mating. I should inform Brodran of this."},
		[7] = 
			{appendStepText="", stepTextKey="The last item on Tindoria's list is the rare plant aurialis, located near the sea on a remote hilltop. I should travel there."},
		["Reach the Hilltop"] =
			{appendText=" garden tended by a High Elf gardener on the southern tip of a large island just off Summerset's southeastern shore. I can find the flowers there."},
		[8] = 
			{appendStepText="", stepTextKey="When I arrived at the location of the aurialis, I encountered a High Elf demanding I speak to him. I should ask him where I can find an aurialis."},
		["Talk to Ingarlas 1"] =
			{appendText=" at the hilltop garden.", stepTextKey="When I arrived at the location of the aurialis, I encountered a High Elf demanding I speak to him. I should ask him where I can find an aurialis."},
		[9] = 
			{appendStepText="The hilltop garden is on the southern hill of the large island just off Summerset's southeastern shore. \n\n", stepTextKey="The hilltop gardener claims there is no aurialis left, but he may be lying. I can search the garden for the plant or press him further and see if he'll tell me more."},
		["Search the Garden"] =
			{appendText=".\n"},
		["Question Ingarlas"] =
			{appendText="."},
		[10] = 
			{appendStepText="", stepTextKey="Turning over a basket revealed a hidden plant. I should examine this plant to see if it matches the description of aurialis in Tindoria's notes."},
		["Examine the Plant"] =
			{appendText=" in the hilltop garden on the southern hill of the large island just off Summerset's southeastern shore."},
		[11] = 
			{appendStepText="", stepTextKey="I have found an aurialis, but Ingarlas has begged me not to uproot it. I should speak to him to learn his reasons for asking me not to take the plant."},
		["Talk to Ingarlas 2"] =
			{appendText=" in the hilltop garden on the southern hill of the large island just off Summerset's southeastern shore.", stepTextKey="I have found an aurialis, but Ingarlas has begged me not to uproot it. I should speak to him to learn his reasons for asking me not to take the plant."},
		[12] = 
			{appendStepText="The hilltop garden is on the southern hill of the large island just off Summerset's southeastern shore. \n\n", stepTextKey="Ingarlas claims this aurialis plant may be the last of its kind, and if I uproot it aurialis could be extinct forever. I can take the plant, as Tindoria requested, or leave it in hopes it will not go extinct."},
		["Take the Last Aurialis Plant"] =
			{appendText=".\n"},
		["Leave the Last Aurialis Plant"] =
			{appendText="."},
		[13] = 
			{appendStepText="", stepTextKey="I've decided to take the aurialis for Tindoria's art supplies. I should pull the plant from the ground."},
		["Take Plant"] =
			{appendText=" from the hilltop garden on the southern hill of the large island just off Summerset's southeastern shore."},
		[14] = 
			{appendStepText="", stepTextKey="I have visited all locations on Tindoria's list. I should return to Tindoria and deliver the ingredients I've gathered."},
		["Return to Tindoria"] =
			{appendText=" on Lillandrel's docks."},
		[15] = 
			{appendStepText="", stepTextKey="I met Vaerelel, Tindoria's rival, on the way to speak with her. I should speak to him."},
		["Talk to Vaerelel 1"] =
			{appendText=" on Lillandrel's docks.", stepTextKey="I met Vaerelel, Tindoria's rival, on the way to speak with her. I should speak to him."},
		[16] = 
			{appendStepText="On Lillandrel's docks, ", stepTextKey="Vaerelel has given me a choice. I can sell him Tindoria's art supplies for significantly more than Tindoria would pay me, or remain loyal to my original employer and take the supplies to her. I should tell him my decision."},
		["Stay Loyal to Tindoria"] =
			{appendText=".\n"},
		["Abandon Tindoria for Vaerelel"] =
			{appendText="."},
		[17] = 
			{appendStepText="", stepTextKey="Vaerelel is pleased I agreed to sell him the supplies instead of Tindoria, and is prepared to pay me extra for what I've gathered. I should speak to him to collect my reward."},
		["Talk to Vaerelel 2"] =
			{appendText=" on Lillandrel's docks.", stepTextKey="Vaerelel is pleased I agreed to sell him the supplies instead of Tindoria, and is prepared to pay me extra for what I've gathered. I should speak to him to collect my reward."},
		[18] = 
			{appendStepText="", stepTextKey="I chose to honor my original contract and deliver the art supplies to Tindoria. I should speak with her."},
		["Deliver Reagents to Tindoria"] =
			{appendText=" on Lillandrel's docks."},
		[19] = 
			{appendStepText="", stepTextKey="Tindoria is grateful to have the supplies she needs for her painting. I should speak to her about my payment."},
		["Talk to Tindoria"] =
			{appendText=" on Lillandrel's docks."},
	},

    [GetQuestName(6145)] = { --"The Runaway's Tale"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="Celinar told me about a High Elf named Esterdel who was also searching for Brengas and Niralin. He may have more information about the situation. He should be near Archon's Grove."},
        ["Talk to Esterdel 1"] =
            {appendText=". Archon's Grove can be found by a large lake with a cascading waterfall south of Shimmerene.", stepTextKey="Celinar told me about a High Elf named Esterdel who was also searching for Brengas and Niralin. He may have more information about the situation. He should be near Archon's Grove."},
        [2] = 
            {appendStepText="", stepTextKey="Niralin is somewhere within Archon's Grove. If she's alive I need to safely return her to Shimmerene. If she's dead, I need to collect proof of her death. I should search the grove for signs of her."},
        ["Find Niralin"] =
            {appendText=". I'll have to fight my way through the pack to find her alive or dead."},
        [3] = 
            {appendStepText="", stepTextKey="I found Niralin, bloodied but alive in the back of the grove. I should talk with her and see what happened."},
        ["Talk to Niralin"] =
            {appendText=" beneath a tall tree on a cliff with a breathtaking view of Summerset. She mistook me for one of the pack when i approached, screaming for me to leave her alone."},
        [4] = 
            {appendStepText="", stepTextKey="Niralin was forcibly turned into a werewolf and requested I kill her to end her suffering. I refused, but took her signet ring as proof of our meeting. I should return to Shimmerene."},
        ["Talk to Esterdel 2"] =
            {appendText=", who told me he'd be waiting outside of the Mage's Guild for my return.", stepTextKey="Niralin was forcibly turned into a werewolf and requested I kill her to end her suffering. I refused, but took her signet ring as proof of our meeting. I should return to Shimmerene."},
        [5] = 
            {appendStepText="", stepTextKey="Niralin was forcibly turned into a werewolf and requested I kill her to end her suffering. I convinced her that she control her werewolf instincts, and she agreed to return to Esterdel. I should travel to Shimmerene to collect my reward."},
        ["Talk to Esterdel 3"] =
            {appendText=", waiting outside of the Mage's Guild for my return.", stepTextKey="Niralin was forcibly turned into a werewolf and requested I kill her to end her suffering. I convinced her that she control her werewolf instincts, and she agreed to return to Esterdel. I should travel to Shimmerene to collect my reward."},
        [6] = 
            {appendStepText="", stepTextKey="Niralin was forcibly turned into a werewolf and requested I end her suffering. I agreed to this last request. I should kill her now."},
        ["Kill Niralin"] =
            {appendText=", beneath a tall tree on a cliff with a breathtaking view of Summerset, at the very back of Archon's Grove."},
        [7] = 
            {appendStepText="", stepTextKey="Niralin was forcibly turned into a werewolf and requested I kill her to end her suffering. I agreed, and afterwards took her signet ring as proof of our meeting. I should return to Shimmerene."},
        ["Talk to Esterdel 4"] =
            {appendText=", waiting outside of the Mage's Guild for my return.", stepTextKey="Niralin was forcibly turned into a werewolf and requested I kill her to end her suffering. I agreed, and afterwards took her signet ring as proof of our meeting. I should return to Shimmerene."},
    },

    [GetQuestName(6138)] = { --"Savage Truths"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="Mehdze's scribe, Naliara, was kidnapped by Goblins and is in need of rescue. He told me they took her into the nearby caves. I should search for her there."},
        ["Find Naliara"] =
            {appendText=" in the caves to the north of where I met Mehdze."},
        [2] = 
            {appendStepText="", stepTextKey="Naliara told me she pursued the Goblins here to recover notes stolen from Mehdze's camp. She's requested my help searching for them scattered throughout the caves of King's Haven Pass."},
        ["Recover Naliara's Notes"] =
            {appendText=" \n\nI'll have to dig through goblin encampments both in and out of the caves and perhaps a rock alcove out of the northwestern exit of the caves to find all of the pages."},
        [3] = 
            {appendStepText="", stepTextKey="I recovered Naliara's lost notes. I should return them to her near the eastern exit from the Coral-Splitter Caves in King's Haven Pass."},
        ["Talk to Naliara"] =
            {appendText="."},
        [4] = 
            {appendStepText="", stepTextKey="Naliara requested one last favor from me. She asked me to bring the research notes I collected to Mehdze, and inform him she won't be continuing their partnership."},
        ["Talk to Mehdze 1"] =
            {appendText=" near the eastern exit from the Coral-Splitter Caves.", stepTextKey="Naliara requested one last favor from me. She asked me to bring the research notes I collected to Mehdze, and inform him she won't be continuing their partnership."},
        [5] = 
            {appendStepText="", stepTextKey="I delivered his lost notes to Mehdze and he has asked me to help him in Naliara's stead. He's searching for an ancient battle site hidden in the caves of King's Haven Pass. I should find the entrance \"where two falls meet stone.\""},
        ["Escort Mehdze to the Ruins"] =
            {appendText="."},
        [6] = 
            {appendStepText="", stepTextKey="I found the hidden ruins. I should help Mehdze search for objects of interest to his research on the war between the Goblins and High Elves."},
        ["Help Mehdze Find Clues"] =
            {appendText="."},
        [7] = 
            {appendStepText="", stepTextKey="I examined the ruins with Mehdze and discovered some records that implies more happened here than just a war. I should speak with Mehdze to see if he found what he came for."},
        ["Talk to Mehdze 2"] =
            {appendText=".", stepTextKey="I examined the ruins with Mehdze and discovered some records that implies more happened here than just a war. I should speak with Mehdze to see if he found what he came for."},
        [8] = 
            {appendStepText="", stepTextKey="I convinced Mehdze to tell the truth and share it with the world. I should talk to him one more time and make sure he's still good with that decision."},
        ["Talk to Mehdze 3"] =
            {appendText="in the ruins.", stepTextKey="I convinced Mehdze to tell the truth and share it with the world. I should talk to him one more time and make sure he's still good with that decision."},
    },

	[GetQuestName(6131)] = { --"Storming the Walls"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="I have volunteered to help Pandermalion, Sea Keep's displaced commander, stop the Sea Mage conjuring the storm. He asked me to join him at the ruins beneath the keep when I'm ready to begin."},
		["Meet Pandermalion at the Ruins"] =
			{appendText="."},
		[2] = 
			{appendStepText="", stepTextKey="Pandermalion is waiting at the ruins underneath Sea Keep. I should speak to him about our plan to infiltrate the fortress."},
		["Talk to Pandermalion 1"] =
			{appendText=".", stepTextKey="Pandermalion is waiting at the ruins underneath Sea Keep. I should speak to him about our plan to infiltrate the fortress."},
		[3] = 
			{appendStepText="", stepTextKey="Pandermalion informed me that we'll need to follow a whirlpool's current to reach the interior of the ruins beneath Sea Keep. I should follow him through."},
		["Infiltrate the Ruins"] =
			{appendText="."},
		[4] = 
			{appendStepText="", stepTextKey="Pandermalion and I were able to navigate the whirlpool's currents and reach the ruin's interior. Now that we're here I should speak to him about our next objective."},
		["Talk to Pandermalion 2"] =
			{appendText=".", stepTextKey="Pandermalion and I were able to navigate the whirlpool's currents and reach the ruin's interior. Now that we're here I should speak to him about our next objective."},
		[5] = 
			{appendStepText="", stepTextKey="Pandermalion confessed that he had another reason to return to Sea Keep. His Maormer lover is being held captive in the dungeon. I've agreed to help him rescue her. We can reach the dungeon through a secret door."},
		["Use the Secret Door to Enter the Keep"] =
			{appendText="."},
		[6] = 
			{appendStepText="", stepTextKey="After entering the dungeon through a secret door known to Pandermalion, we found his lover, Castire, chained up in a cell. I should find out what she knows while Pandermalion unfastens her bonds."},
		["Talk to Castire 1"] =
			{appendText=".", stepTextKey="After entering the dungeon through a secret door known to Pandermalion, we found his lover, Castire, chained up in a cell. I should find out what she knows while Pandermalion unfastens her bonds."},
		[7] = 
			{appendStepText="", stepTextKey="Castire confirmed that the Maormer are planning to destroy Sea Keep and that their Sea Mage is on the battlements gathering a storm with the power to do so. Pandermalion seems to have an idea of how we might thwart their plans."},
		["Talk to Pandermalion 3"] =
			{appendText=" in the dungeon.\n", stepTextKey="Castire confirmed that the Maormer are planning to destroy Sea Keep and that their Sea Mage is on the battlements gathering a storm with the power to do so. Pandermalion seems to have an idea of how we might thwart their plans."},
		[8] = 
			{appendStepText="", stepTextKey="Pandermalion told me that there are several Magicka Fonts that channel power to the battlements from the Aldmer ruins below. If we seal those fonts, we may cut the Sea Mage off from his main source of power."},
		["Seal the Magicka Fonts"] =
			{appendText=".\n"},
		[9] = 
			{appendStepText="", stepTextKey="We successfully sealed all the Magicka Fonts, cutting the Sea Mage, Urlsar, off from his main source of power. Now we need to reach Sea Keep's courtyard to put ourselves within striking distance of the Sea Mage."},
		["Reach the Keep's Courtyard"] =
			{appendText=""},
		[10] = 
			{appendStepText="", stepTextKey="We reached the courtyard, but the battlement gates are blocking our path. The mechanisms controlling the gates are in two towers overlooking the courtyard.  Castire will make for one while Pandermalion and I head for the other."},
		["Raise the Outer Gate"] =
			{appendText=".\n\n"},
		["Raise the Inner Gate"] =
			{appendText="."},
		[11] = 
			{appendStepText="", stepTextKey="We have unbarred the gate to the battlements, leaving nothing standing between us and Urlsar, the Sea Mage. I need to reach the battlements and put a stop to his storm."},
		["Reach the Battlements"] =
			{appendText="."},
		[12] = 
			{appendStepText="", stepTextKey="We cut Urlsar off from the magic of Sea Keep, but not before he conjured a storm of considerable power. I will have to overcome it and stop him before he unleashes it on the Altmer homeland."},
		["Defeat Urlsar"] =
			{appendText="."},
		[13] = 
			{appendStepText="", stepTextKey="The storm dissipated after I defeated Urlsar. With the Sea Mage dead, the threat to Sea Keep is all but gone and the Altmer reinforcements can handle the rest. That only leaves the matter of Castire and Pandermalion's future. I should speak with them"},
		["Talk to Castire 2"] =
			{appendText=" on the northeastern ramparts.", stepTextKey="The storm dissipated after I defeated Urlsar. With the Sea Mage dead, the threat to Sea Keep is all but gone and the Altmer reinforcements can handle the rest. That only leaves the matter of Castire and Pandermalion's future. I should speak with them."},
		[14] = 
			{appendStepText="", stepTextKey="Castire has decided to return to her people, leaving Pandermalion with his own. I should talk to him about what will come next for him."},
		["Talk to Pandermalion 4"] =
			{appendText=" on the northeastern ramparts.", stepTextKey="Castire has decided to return to her people, leaving Pandermalion with his own. I should talk to him about what will come next for him."},
		[15] = 
			{appendStepText="", stepTextKey="Castire and Pandermalion parted ways before the Altmer reinforcements arrived. Their commander will want to know what transpired here, but should I tell her the truth or keep Pandermalion's secret?"},
		["Talk to Battlereeve Farwenya 1"] =
			{appendText=" outside of Sea Keep.", stepTextKey="Castire and Pandermalion parted ways before the Altmer reinforcements arrived. Their commander will want to know what transpired here, but should I tell her the truth or keep Pandermalion's secret?"},
		[16] = 
			{appendStepText="", stepTextKey="I chose to tell Battlereeve Farwenya the truth about the attack on Sea Keep. She awaits my proof that he was the one responsible for the sacking of the keep."},
		["Talk to Battlereeve Farwenya 2"] =
			{appendText=" outside of Sea Keep.", stepTextKey="I chose to tell Battlereeve Farwenya the truth about the attack on Sea Keep. She awaits my proof that he was the one responsible for the sacking of the keep."},
		[17] = 
			{appendStepText="", stepTextKey="I chose to leave Pandermalion's secret out of my report to Battlereeve Farwenya. I should make sure his heroics are noted in the record of what transpired here."},
		["Talk to Battlereeve Farwenya 3"] =
			{appendText=" outside of Sea Keep.", stepTextKey="I chose to leave Pandermalion's secret out of my report to Battlereeve Farwenya. I should make sure his heroics are noted in the record of what transpired here."},
		[18] = 
			{appendStepText="", stepTextKey="Castire appears to be wrestling with what to do now that the mutiny against her has been quelled. I should speak to Castire about her plans."},
		["Talk to Pandermalion 5"] =
			{appendText=" on the northeastern ramparts.", stepTextKey="Castire appears to be wrestling with what to do now that the mutiny against her has been quelled. I should speak to Castire about her plans."},
		[19] = 
			{appendStepText="", stepTextKey="I advised Castire and Pandermalion to abandon the duties keeping them apart. They dove into the sea together, to head for Castire's ship. Pandermalion asked me to report his death to the commander of the arriving reinforcements."},
		["Talk to Battlereeve Farwenya 4"] =
			{appendText=" outside of Sea Keep.", stepTextKey="I advised Castire and Pandermalion to abandon the duties keeping them apart. They dove into the sea together, to head for Castire's ship. Pandermalion asked me to report his death to the commander of the arriving reinforcements."},
	},

[GetQuestName(6150)] = { --"Sunhold Sundered"		--Wex
        [1] = 
            {appendStepText="", stepTextKey="I've been asked to help Sunhold in several ways. I should destroy Maormer supplies in the harbor, free chained citizens, and save the gryphon Sunnawel."},
        ["Destroy Maormer Supplies"] =
            {appendText=" \n\nThe Maormer have supply crates scattered around the docks and beach surrounding their ship. They'll likely be placed next to Sea Elf banners.\n"},
        ["Rescue Chained Sunhold Citizens"] =
            {appendText=" \n\nThe citizens are scattered throughout the city, but the Maormer seem to be rounding them up in the central and eastern districts. I should keep an eye out for anyone chained up, while also listening to cries for help.\n"},
        ["Free Sunnawel"] =
            {appendText=". Gryphons are powerful beasts. The Maormer are likely using magic chains and large cages to bind the creature. She could be kept anywhere, although the elevated regions of the city, like the area northwest of the docks, would be a good place to start looking."},
        [2] = 
            {appendStepText="", stepTextKey="I've completed the tasks Kinlady Helenaere asked of me. I should meet with her and Khavid in Sunhold's merchant district."},
        ["Meet with Kinlady Helenaere"] =
            {appendText=". The merchant district is the far northwestern sector of the city."},
        [3] = 
            {appendStepText="", stepTextKey="According to Khavid, Kinlady Helenaere has been captured by the Maormer. I should stop her execution by defeating Admiral Viscarne."},
        ["Kill Admiral Viscarne"] =
            {appendText=" in the manor courtyard far to the northwest, beneath a statue of an Altmer woman holding a staff."},
        [4] = 
            {appendStepText="", stepTextKey="I've defeated Admiral Viscarne. I should speak to Kinlady Helenaere."},
        ["Talk to Kinlady Helenaere"] =
            {appendText=" in the courtyard to the northwest, where Admiral Viscarne once held her captive."},
    },

[GetQuestName(6116)] = { --"A Tale of Two Mothers"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="Lanarie insists that the Justiciar of Remand, Talerion, knows more about Arathel's disappearance than he's letting on. I should speak with him in the kinlady's manor."},
		["Talk to Talerion 1"] =
			{appendText=" down in the dungeon in the manor of the kinlady of Shimmerene.", stepTextKey="Lanarie insists that the Justiciar of Remand, Talerion, knows more about Arathel's disappearance than he's letting on. I should speak with him in the kinlady's manor."},
		[2] = 
			{appendStepText="", stepTextKey="According to Talerion, the guards seized a crude map from Arathel when he turned himself in. This map might contain valuable clues. I can find a copy near the kinlady's hearth."},
		["Take the Map"] =
			{appendText=" within the kinlady of Shimmerene's manor."},
		[3] = 
			{appendStepText="", stepTextKey="I took a faithful copy of Arathel's map. Hopefully it will lead me to another clue."},
		["Find the Marked Location"] =
			{appendText=" within Shimmerene."},
		[4] = 
			{appendStepText="", stepTextKey="Arathel's map led me to a scroll tucked away in a hedge maze. I should read this scroll and see what it says."},
		["Read the Scroll"] =
			{appendText=" in Shimmerene."},
		[5] = 
			{appendStepText="", stepTextKey="The note I found urged Arathel to meet a mysterious figure in the Anchors Aweigh Inn in Shimmerene. I can either follow the note's instructions or report what I found to the Justiciar of Remand, Talerion."},
		["Talk to Talerion 2"] =
			{appendText=" in the kinlady of Shimmerene's manor.", stepTextKey="The note I found urged Arathel to meet a mysterious figure in the Anchors Aweigh Inn in Shimmerene. I can either follow the note's instructions or report what I found to the Justiciar of Remand, Talerion."},
		["Go to the Anchors Aweigh Inn"] =
			{appendText="."},
		[6] = 
			{appendStepText="", stepTextKey="I chose to return to Talerion. I should show him the scroll I found."},
		["Talk to Talerion 3"] =
			{appendText=" in the kinlady of Shimmerene's manor.", stepTextKey="I chose to return to Talerion. I should show him the scroll I found."},
		[7] = 
			{appendStepText="", stepTextKey="Talerion agreed to let me follow the path Arathel took out of his cell into the underground. I must delve into the sewers to find a mysterious figure—the Mother of Rats."},
		["Enter the Broken Passage to the Underground"] =
			{appendText=" down in the dungeon in the manor of the kinlady of Shimmerene.\n"},
		[8] = 
			{appendStepText="", stepTextKey="Now that I've entered the city's underground, I need to find the Mother of Rats. Perhaps the rats themselves can show me the way."},
		["Follow the Rats"] =
			{appendText=" within Shimmerene's underbelly."},
		[9] = 
			{appendStepText="", stepTextKey="I found Mother's Den, the Mother of Rats's underground hideout. I should talk to the Mother of Rats and find out what she knows about Arathel."},
		["Talk to the Mother of Rats 1"] =
			{appendText=" within Shimmerene's underbelly.", stepTextKey="I found Mother's Den, the Mother of Rats's underground hideout. I should talk to the Mother of Rats and find out what she knows about Arathel."},
		[10] = 
			{appendStepText="", stepTextKey="The Mother of Rats told me about a rival group that seeks a more violent resolution to the plight of Summerset's underclass. One of her spies, Zan'hi, is looking into it. I should track him down and see if he knows anything about Arathel."},
		["Find Zan'hi"] =
			{appendText=" within Shimmerene's underbelly."},
		[11] = 
			{appendStepText="", stepTextKey="I found Zan'hi, urging a friend to flee the underground. I should talk to him."},
		["Talk to Zan'hi"] =
			{appendText=" within Shimmerene's underbelly."},
		[12] = 
			{appendStepText="", stepTextKey="Zan'hi told me a sorcerer called Mirulon took Arathel deep within the caverns beneath Shimmerene. I must navigate these caves to find him."},
		["Find Arathel"] =
			{appendText=" deeper within Shimmerene's underbelly."},
		[13] = 
			{appendStepText="", stepTextKey="I found Arathel. I must kill his captor, Mirulon, to aid his escape."},
		["Kill Mirulon"] =
			{appendText=" within Shimmerene's underbelly."},
		[14] = 
			{appendStepText="", stepTextKey="Mirulon might have some evidence that could exonerate Arathel. I should take a look around to see what I can find."},
		["Retrieve the Evidence"] =
			{appendText=" within Mirulon's lair in Shimmerene's underbelly."},
		[15] = 
			{appendStepText="", stepTextKey="I found some convincing evidence that clarifies Arathel's role in the plot to kill the Sapiarch. Unfortunately, Arathel ran off during the fight with Mirulon. I must track him down."},
		["Talk to Arathel"] =
			{appendText=" within Shimmerene's underbelly."},
		[16] = 
			{appendStepText="", stepTextKey="I should bring Arathel back to Mother's Den where he'll be safe."},
		["Escort Arathel to Mother's Den"] =
			{appendText=" within Shimmerene's underbelly."},
		[17] = 
			{appendStepText="", stepTextKey="Talerion appeared at Mother's Den with questions. Since I met him earlier, he might listen to what I have to say. The evidence I collected will prove Mirulon was behind this."},
		["Give the Evidence to Talerion"] =
			{appendText=" within Shimmerene's underbelly."},
		[18] = 
			{appendStepText="", stepTextKey="I've convinced Talerion of Arathel's innocence. I should talk to the Mother of Rats. She'll want to know that the Divine Prosecution won't be raiding Mother's Den anytime soon."},
		["Talk to the Mother of Rats 2"] =
			{appendText=" within Shimmerene's underbelly.", stepTextKey="I've convinced Talerion of Arathel's innocence. I should talk to the Mother of Rats. She'll want to know that the Divine Prosecution won't be raiding Mother's Den anytime soon."},
		[19] = 
			{appendStepText="", stepTextKey="I chose to follow the scroll's instructions. I should talk to the Khajiiti barkeep in the Anchors Aweigh Inn."},
		["Talk to Riharai"] =
			{appendText="."},
		[20] = 
			{appendStepText="", stepTextKey="The barkeep urged me to talk with a hooded man on the second floor of the inn. I should find this mysterious figure."},
		["Talk to the Hooded Man"] =
			{appendText=" in the Anchor's Aweigh Inn."},
		[21] = 
			{appendStepText="", stepTextKey="The hooded man, Edgar, urged me to find his mistress, the Mother of Rats. She might know more about Arathel's disappearance. I'll need to find the entrance to Shimmerene's underground if I'm going to meet her. It should be near the docks."},
		["Enter the Shimmerene Underground"] =
			{appendText=". I can find a way into the waterworks by the docks."},
	},


	[GetQuestName(6117)] = { --"The Taste of Fear"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="I must talk to Silurie to learn how we plan to get inside Cey-Tarn Keep."},
		["Talk to Silurie 1"] =
			{appendText=" outside the gate of the keep.", stepTextKey="I must talk to Silurie to learn how we plan to get inside Cey-Tarn Keep."},
		[2] = 
			{appendStepText="", stepTextKey="Silurie gave me a fake mandate from the Proxy Queen that should get me inside the keep, but I must speak to Lindafwe who is controlling the Divine Prosecution's cordon, and distract her so Silurie can sneak inside."},
		["Distract Revelator Lindafwe"] =
			{appendText=" at the gate of the keep."},
		[3] = 
			{appendStepText="", stepTextKey="I was able to distract Lindafwe long enough for Silurie to pass unnoticed and successfully passed myself off as an investigator sent by the Proxy Queen. Now I need to find Silurie and learn our next move."},
		["Talk to Silurie 2"] =
			{appendText=", hiding on the ramparts within the keep.", stepTextKey="I was able to distract Lindafwe long enough for Silurie to pass unnoticed and successfully passed myself off as an investigator sent by the Proxy Queen. Now I need to find Silurie and learn our next move."},
		[4] = 
			{appendStepText="", stepTextKey="Silurie has something up her sleeve to help our search and instructed me to observe her technique."},
		["Watch Silurie's Spell"] =
			{appendText=" on the ramparts of the keep."},
		[5] = 
			{appendStepText="", stepTextKey="Silurie's spell created two orbs of light. While Silurie follows one orb, I must follow the other and learn where it leads."},
		["Follow the Light of Stendarr"] =
			{appendText=" throughout the keep."},
		[6] = 
			{appendStepText="", stepTextKey="Silurie's orb of light vanished into a solid wall. It may conceal a hidden room. I should check the candelabra and pedestal for a means to open it."},
		["Examine the Candelabra"] =
			{appendText=" on the second floor of the Cey-Tarn Keep Barracks."},
		[7] = 
			{appendStepText="", stepTextKey="I found a hidden room in Cey-Tarn Keep containing signs some sort of ghastly ritual took place in here. This may be where the Daedra was summoned. I should look for clues to confirm my suspicions."},
		["Examine the Book"] =
			{appendText=".\n"},
		["Examine the Desiccated Corpse"] =
			{appendText=".\n"},
		["Examine the Smeared Footprints"] =
			{appendText="."},
		[8] = 
			{appendStepText="", stepTextKey="I found a book speaking of something called \"The Insatiable\" and signs that its summoning ritual was performed in the hidden room. Silurie will want to see this. I should find her in Cey-Tarn Keep's refectory, like she asked."},
		["Meet Silurie in the Refectory"] =
			{appendText="."},
		[9] = 
			{appendStepText="", stepTextKey="Silurie has been captured by Lindafwe, the Divine Prosecution officer I met at the gate, and another Altmer dressed in their uniform. He has beckoned me over to talk."},
		["Talk to Justiciar Hyircil 1"] =
			{appendText=", who has captured Silurie in the refectory.", stepTextKey="Silurie has been captured by Lindafwe, the Divine Prosecution officer I met at the gate, and another Altmer dressed in their uniform. He has beckoned me over to talk."},
		[10] = 
			{appendStepText="", stepTextKey="Using the evidence I found, I have convinced Hyircil to allow Silurie to lead us on the hunt for the killer. Her trail is leading us to the keep's cellar."},
		["Explore the Cellar"] =
			{appendText="."},
		[11] = 
			{appendStepText="", stepTextKey="I must follow Silurie, Hyircil, and Lindafwe as we search for the Daedra in the cellar of Cey-Tarn Keep."},
		["Follow Silurie"] =
			{appendText="."},
		[12] = 
			{appendStepText="", stepTextKey="A monstrous Daedra appeared and snatched Lindafwe away through a portal! Silurie, Hyircil, and I must give chase through the opening before she is lost."},
		["Chase the Insatiable"] =
			{appendText=" through the portal in the refectory cellar."},
		[13] = 
			{appendStepText="", stepTextKey="I arrived in a place that looks similar to the basement of Cey-Tarn Keep, yet twisted and wrong. Silurie and Hyircil have split up to search for Lindafwe, leaving me one final avenue to explore."},
		["Search the Side Passage"] =
			{appendText=" for any evidence in The Gorge."},
		[14] = 
			{appendStepText="", stepTextKey="I found evidence a mage named Teraniel summoned a monster called \"the Insatiable\" at the behest of some unknown benefactor. I should find the others and tell them what I discovered."},
		["See Where the Side Passage Leads"] =
			{appendText=" within the Gorge."},
		[15] = 
			{appendStepText="", stepTextKey="Hyircil was injured in a fight with an unknown assailant. I should check on him and see if he can tell me more about what happened."},
		["Talk to Justiciar Hyircil 2"] =
			{appendText=", who lies injured on the floor past the Watcher in the Gorge.", stepTextKey="Hyircil was injured in a fight with an unknown assailant. I should check on him and see if he can tell me more about what happened."},
		[16] = 
			{appendStepText="", stepTextKey="Hyircil's attacker was the summoner of the Daedra stalking Cey-Tarn Keep, but that is a less pressing concern than saving Lindafwe before the Insatiable devours her. He told me Silurie followed them through the door to the wine cellar. I should too."},
		["Find Revelator Lindafwe"] =
			{appendText=" within the gorge."},
		[17] = 
			{appendStepText="", stepTextKey="The Insatiable is attempting to devour Lindafwe! I must defeat it to save her."},
		["Defeat the Insatiable and Save Revelator Lindafwe"] =
			{appendText=" within the gorge."},
		[18] = 
			{appendStepText="", stepTextKey="With Silurie's help, I defeated the Insatiable and saved Lindafwe. We should leave the lair and plan our next move."},
		["Meet Your Allies Outside the Lair"] =
			{appendText=" in the gorge."},
		[19] = 
			{appendStepText="", stepTextKey="The mage who summoned the hunger, Teraniel, escaped into a portal. Silurie asked me to chase Teraniel down while she goes back to rescue Hyircil."},
		["Pursue Teraniel"] =
			{appendText=" through the portal in the gorge."},
		[20] = 
			{appendStepText="", stepTextKey="When Lindafwe and I exited Teraniel's portal, it closed behind us, trapping Silurie and Hyircil in the Gorge. There must be some way to rescue them. Perhaps Lindafwe will have some ideas."},
		["Talk to Revelator Lindafwe 1"] =
			{appendText=" within the Vaults of Heinarwe.", stepTextKey="When Lindafwe and I exited Teraniel's portal, it closed behind us, trapping Silurie and Hyircil in the Gorge. There must be some way to rescue them. Perhaps Lindafwe will have some ideas."},
		[21] = 
			{appendStepText="", stepTextKey="Lindafwe believes finding Teraniel will be our best chance of rescuing her friends from the Gorge. As we talked about where to search in this familiar ruin, she felt a ripple of magicka coming from across the bridge before us. We should investigate."},
		["Find the Source of the Magicka Ripple"] =
			{appendText=" within the Vaults of Heinarwe."},
		[22] = 
			{appendStepText="", stepTextKey="I found an ancient Aldmer altar room, but no sign of Teraniel or a portal. I should speak to Lindafwe and see if she knows what we should be looking for."},
		["Talk to Revelator Lindafwe 2"] =
			{appendText=" within the Vaults of Heinarwe.", stepTextKey="I found an ancient Aldmer altar room, but no sign of Teraniel or a portal. I should speak to Lindafwe and see if she knows what we should be looking for."},
		[23] = 
			{appendStepText="", stepTextKey="Lindafwe believes the altar is being used as an anchor to the Gorge, but we need to undo Teraniel's anchor spell before we can create an opening of our own. The books in this chamber should reveal how we can accomplish that."},
		["Reverse Teraniel's Attunement Ritual"] =
			{appendText=" within the Vaults of Heinarwe."},
		[24] = 
			{appendStepText="", stepTextKey="I successfully undid Teraniel's spell and Lindafwe is creating an achor of her own."},
		[25] = 
			{appendStepText="", stepTextKey="Lindafwe has opened a portal to the Gorge. I need to use it to find Silurie and Hyircil."},
		["Enter the Gorge"] =
			{appendText=" within the Vaults of Heinarwe."},
		[26] = 
			{appendStepText="", stepTextKey="Teraniel is conducting some dark ritual using Hyircil and Silurie as sacrifices. I must stop her and save them both."},
		["Save Silurie and Justiciar Hyircil"] =
			{appendText=" within the Gorge."},
		[27] = 
			{appendStepText="", stepTextKey="Silurie and Hyiricil are safe and Teraniel is dead. Now we must escape the Gorge before Lindafwe loses her grip on the portal."},
		["Escape the Gorge"] =
			{appendText="."},
		[28] = 
			{appendStepText="", stepTextKey="We are safe, the Insatiable is defeated, and the mage who summoned it is dead. I should speak to Silurie to see where we go from here."},
		["Talk to Silurie 3"] =
			{appendText=" outside the Vaults of Heinarwe.", stepTextKey="We are safe, the Insatiable is defeated, and the mage who summoned it is dead. I should speak to Silurie to see where we go from here."},
	},

    [GetQuestName(6162)] = { --"An Unexpected Betrayal"		--Strangelove
        [1] = 
            {appendStepText="The former captain directed me to Karnwasten. ", stepTextKey="Renzir's trade shipments are scattered in caches throughout the cave system. I should collect them. I should also kill his traitorous first mate, Madja."},
        ["Recover Trade Shipments"] =
            {appendText=" /n/nI should check for hordes near the more dangerous entities inhabiting the cavern./n/n"},
        ["Kill Madja"] =
            {appendText=". I should look for her in the bay near the ship she took from Renzir."},
        [2] = 
            {appendStepText="", stepTextKey="I recovered Renzir's goods and killed Madja. Now I should find out what happened to Renzir's lover, Nubani."},
        ["Find Nubani"] =
            {appendText=". I should check Renzir's ship moored in the bay in Karnwasten."},
        [3] = 
            {appendStepText="", stepTextKey="I found Nubani calmly waiting for me in Renzir's ship. I should talk to her and see what's going on."},
        ["Talk to Nubani"] =
            {appendText=" in Karnwasten."},
        [4] = 
            {appendStepText="", stepTextKey="Nubani revealed that Renzir's a smuggler, and she worries he's addicted to the lifestyle and will never settle down. She asked me to dump Renzir's goods in order to force him to retire, which I refused to do. I should speak to Renzir."},
        ["Talk to Renzir 1"] =
            {appendText=" outside of Karnwasten.", stepTextKey="Nubani revealed that Renzir's a smuggler, and she worries he's addicted to the lifestyle and will never settle down. She asked me to dump Renzir's goods in order to force him to retire, which I refused to do. I should speak to Renzir."},
        [5] = 
            {appendStepText="", stepTextKey="Nubani wanted me to destroy Renzir's goods to force him to retire, but I chose to honor our original agreement. I should collect my reward."},
        ["Talk to Renzir 2"] =
            {appendText=", outside of Karnwasten.", stepTextKey="Nubani wanted me to destroy Renzir's goods to force him to retire, but I chose to honor our original agreement. I should collect my reward."},
        [6] = 
            {appendStepText="", stepTextKey="Nubani revealed that Renzir's a smuggler, and she worries he's addicted to the lifestyle and will never settle down. She asked me to dump Renzir's goods in order to force him to retire, which I agreed to do so. I should dump the goods."},
        ["Dump the Shipments"] =
            {appendText=" into the frothing deep waters just off the adjacent jetty."},
        [7] = 
            {appendStepText="", stepTextKey="I dumped Renzir's goods so that Nubani can force him to retire. I should go to him and tell him that Madja is dead, Nubani is safe, and his shipments have been lost to the sea."},
        ["Talk to Renzir 3"] =
            {appendText="outside of Karnwasten.", stepTextKey="I dumped Renzir's goods so that Nubani can force him to retire. I should go to him and tell him that Madja is dead, Nubani is safe, and his shipments have been lost to the sea."},
        [8] = 
            {appendStepText="", stepTextKey="I returned Renzir's shipments to him, but I persuaded him that Nubani is truly worried about him choosing his smuggling exploits over their future. I should collect my reward."},
        ["Talk to Renzir 4"] =
            {appendText="where I left him, outside of Karnwasten.", stepTextKey="I returned Renzir's shipments to him, but I persuaded him that Nubani is truly worried about him choosing his smuggling exploits over their future. I should collect my reward."},
    },

	[GetQuestName(6121)] = { --"Untamed and Unleashed"		--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="I agreed to help Talomar search for his indrik, Lotus. We should look around the grounds for any sign of her."},
		["Search For Lotus"] =
			{appendText=". I should start by searching for places within the menagerie that an indrik would go. Perhaps I should start at her enclosure towards the eastern part of the grounds or find some of the nearby trees they're known to feed on. Talomar knows the grounds much better than I do. I should stick close to him and listen to what he has to say."},
		[2] = 
			{appendStepText="", stepTextKey="I agreed to help Talomar search for his indrik, Lotus. We should look around the grounds for any sign of her."},
		["Search for Any Clues"] =
			{appendText=". That dead mammoth likely spooked our indrik when it broke her enclosure. I should search around it and the enclosure for clues. Perhaps the animals' feed will hold some answers."},
		[3] = 
			{appendStepText="", stepTextKey="I came across a dead mammoth that appears to have bashed its own brains out toppling an enclosure wall. I should speak to Talomar about this discovery."},
		["Talk to Talomar 1"] =
			{appendText=" near the dead mammoth I discovered.", stepTextKey="I came across a dead mammoth that appears to have bashed its own brains out toppling an enclosure wall. I should speak to Talomar about this discovery."},
		[4] = 
			{appendStepText="", stepTextKey="The feed left in Lotus's enclosure is discolored and smells strangely. I should take some to Talomar and see what he thinks."},
		["Talk to Talomar 2"] =
			{appendText=" by the missing indrik's enclosure.", stepTextKey="The feed left in Lotus's enclosure is discolored and smells strangely. I should take some to Talomar and see what he thinks."},
		[5] = 
			{appendStepText="", stepTextKey="Talomar and I found signs that the animals might have been exposed to tainted feed, which could explain their aggression. We haven't found any sign of Lotus, however, and should continue our search."},
		["Search for Lotus"] =
			{appendText="."},
		[6] = 
			{appendStepText="", stepTextKey="Talomar and I heard a cry of distress during our search. He ran off to lend assistance. I should follow suit."},
		["Find the Source of the Cry"] =
			{appendText=". It came from the west side of the menagerie grounds."},
		[7] = 
			{appendStepText="", stepTextKey="The source of the cry is another keeper being cornered by a pride of lions. I should help her."},
		["Rescue the Cornered Keeper"] =
			{appendText=" on the western side of the menagerie."},
		[8] = 
			{appendStepText="", stepTextKey="I saved the distressed keeper from the lions. Talomar recognized her as someone named Elise. I should speak to her about what happened."},
		["Talk to Elise Mallon 1"] =
			{appendText=", who is hiding in the corner between a rock and bars on the western side of the menagerie grounds.", stepTextKey="I saved the distressed keeper from the lions. Talomar recognized her as someone named Elise. I should speak to her about what happened."},
		[9] = 
			{appendStepText="", stepTextKey="Elise did not stick around to help with our search, but mentioned that she saw Lotus by the reflecting pool. We should continue our search there."},
		["Search for Lotus Near the Reflecting Pool"] =
			{appendText=" in the southwest grounds."},
		[10] = 
			{appendStepText="", stepTextKey="We spotted Lotus at the reflecting pool, like Elise said, but she got spooked and fled from us. Talomar took off in pursuit of her. I should follow them."},
		["Pursue Lotus"] =
			{appendText=" along the road towards the east side of the grounds."},
		[11] = 
			{appendStepText="", stepTextKey="Lotus was caught by some other menagerie staff. Their leader, Conservator Vinelore, wants to have words with me."},
		["Talk to Conservator Vinelore"] =
			{appendText=", who is currently wrangling the lost indrik on the east side of the grounds."},
		[12] = 
			{appendStepText="", stepTextKey="Conservator Vinelore said she would handle Lotus and commanded Talomar and I to leave the menagerie grounds. I should speak to Talomar about this."},
		["Talk to Talomar 3"] =
			{appendText=" outside of earshot of the rangers on the east side of the grounds.", stepTextKey="Conservator Vinelore said she would handle Lotus and commanded Talomar and I to leave the menagerie grounds. I should speak to Talomar about this."},
		[13] = 
			{appendStepText="", stepTextKey="The young keeper I rescued earlier called out to us. She appears to want to speak with me."},
		["Talk to Elise Mallon 2"] =
			{appendText=", skulking around a tree on the east side of the grounds.", stepTextKey="The young keeper I rescued earlier called out to us. She appears to want to speak with me."},
		[14] = 
			{appendStepText="", stepTextKey="Elise confessed to drugging the animals, but claims she did so only for an opportunity to collect evidence of mistreatment of the animals. She's asked us to help her. I should speak to Talomar about this."},
		["Talk to Talomar 4"] =
			{appendText=", staring daggers at Elise on the east side of the grounds.", stepTextKey="Elise confessed to drugging the animals, but claims she did so only for an opportunity to collect evidence of mistreatment of the animals. She's asked us to help her. I should speak to Talomar about this."},
		[15] = 
			{appendStepText="", stepTextKey="Talomar is skeptical, but I convinced him to investigate the Conservatory. He says I might find a key on the body of one of Vinelore's rangers."},
		["Find a Way into the Conservatory"] =
			{appendText=". Talomar mentioned that some of the rangers fell to a mammoth by a fountain near the main entrance towards the northern grounds."},
		[16] = 
			{appendStepText="", stepTextKey="I found a key to the Conservatory on the body of one of Vinelore's rangers. I should use it to gain access to the inside."},
		["Enter the Conservatory"] =
			{appendText=", the large building towards the southwest of the grounds, where Elise and Talomar await my arrival."},
		[17] = 
			{appendStepText="", stepTextKey="The inside of the Conservatory contains all manner of alchemical equipment. I should search for some proof of wrongdoing going on here."},
		["Search the Conservatory"] =
			{appendText="."},
		[18] = 
			{appendStepText="", stepTextKey="I discovered some sort of laboratory filled with test subjects and records. I should search the records for something incriminating."},
		["Search Conservatory Records for Evidence"] =
			{appendText=" within the various bookshelves used to file their misdeeds."},
		[19] = 
			{appendStepText="", stepTextKey="I found a lab report that confirms dangerous experiments are being conducted on the indriks here. Elise will want to see what I found."},
		["Talk to Elise"] =
			{appendText=" in the top floor of the conservatory."},
		[20] = 
			{appendStepText="", stepTextKey="Talomar is no longer in the Conservatory. Elise suspects he's taken off after Lotus himself and we can head after him to the inner paddocks by heading through the Conservatory. We should find him."},
		["Find Talomar"] =
			{appendText=". Elise went through the door that leads out to the paddocks."},
		[21] = 
			{appendStepText="", stepTextKey="I found Talomar being held at arrowpoint by Conservator Vinelore. I should confront her about what we discovered about the experiments."},
		["Talk to Vinelore"] =
			{appendText=", who is being confronted by Elise and Talomar in the paddocks behind a wall of wards."},
		[22] = 
			{appendStepText="", stepTextKey="Elise sabotaged the containment measures for the inner paddocks, setting the indriks loose and forcing Vinelore to flee, but Talomar was wounded during her escape. Elise is tending to Talomar, I should speak to her about him."},
		["Talk to Elise Mallon 3"] =
			{appendText=".", stepTextKey="Elise sabotaged the containment measures for the inner paddocks, setting the indriks loose and forcing Vinelore to flee, but Talomar was wounded during her escape. Elise is tending to Talomar, I should speak to her about him."},
		[23] = 
			{appendStepText="", stepTextKey="I promised Talomar that I would find Lotus and bring her to safety. She's being held somewhere in the inner paddocks, but with the indriks and Vinelore on the loose, mounting a rescue will be dangerous."},
		["Find Lotus"] =
			{appendText=" through the gates, further into the paddocks."},
		[24] = 
			{appendStepText="", stepTextKey="Conservator Vinelore and one of her test subjects have blocked my path through the inner paddocks. I will have to fight my way past to reach Lotus."},
		["Defeat Conservator Vinelore and Her Experiment"] =
			{appendText=". Even her loyal rangers have abandoned her, fleeing screaming towards the entrance of the paddocks."},
		[25] = 
			{appendStepText="", stepTextKey="I found Lotus cowering in a cage not far from where I fought Vinelore. I should use the ward breaker Elise gave me to free her."},
		["Disrupt Wards to Free Lotus"] =
			{appendText=" from the paddocks."},
		[26] = 
			{appendStepText="", stepTextKey="Lotus escaped her cage and seems to be responding positively to me. It seems she wants me to follow her through the mystical portal she created."},
		["Follow Lotus to Safety"] =
			{appendText=" through the portal in the back of the paddocks."},
		[27] = 
			{appendStepText="", stepTextKey="I was able to reunite Talomar with Lotus. He seems to have forgotten all about his injury, but I should see how he is doing."},
		["Talk to Talomar 5"] =
			{appendText=", who is consoling the Queen's indrik near the southwest entrance to the grounds.", stepTextKey="I was able to reunite Talomar with Lotus. He seems to have forgotten all about his injury, but I should see how he is doing."},
		[28] = 
			{appendStepText="", stepTextKey="I convinced Talomar that he will be happier if he leaves the Royal Menagerie behind him."},
		["Talk to Talomar 6"] =
			{appendText=", who is still consoling the Queen's indrik near the southwest entrance to the grounds as they prepare to depart.", stepTextKey="I convinced Talomar that he will be happier if he leaves the Royal Menagerie behind him."},
		[29] = 
			{appendStepText="", stepTextKey="I convinced Talomar that he can do more good by staying and making sure the menagerie is properly cared for."},
		["Talk to Talomar 7"] =
			{appendText=", who is consoling the Queen's indrik near the southwest entrance to the grounds as he prepares to fix the damage that has been wrought upon the grounds.", stepTextKey="I convinced Talomar that he can do more good by staying and making sure the menagerie is properly cared for."},
	},

    [GetQuestName(6136)] = { --"The Vault of Moawita"		--Devinstrike
        [1] = 
            {appendStepText="", stepTextKey="A member of the Psijic Order asked me to speak to Relicmaster Glenadir about some missing relics. I'll find him in the old Psijics College on Artaeum."},
        ["Talk to Relicmaster Glenadir 1"] =
            {appendText=" within the ancient chambers. Passersby say he studies night or day on the first level of a room designed to house these missing relics, a room now filled with empty cases.\n", stepTextKey="A member of the Psijic Order asked me to speak to Relicmaster Glenadir about some missing relics. I'll find him in the old Psijics College on Artaeum."},
        [2] = 
            {appendStepText="", stepTextKey="I've just learned about the stolen relics. I should ask Relicmaster Glenadir for more details."},
        ["Talk to Relicmaster Glenadir 2"] =
            {appendText=" inside the college of Psijic Ruins on Artaeum to discover what part fate would have me play in resolving this crisis.\n", stepTextKey="I've just learned about the stolen relics. I should ask Relicmaster Glenadir for more details."},
        [3] = 
            {appendStepText="", stepTextKey="The Psijic Codex can tell me the location of the relics. I should read it."},
        ["Read the Psijic Codex"] =
            {appendText=" within Artaeum's Psijic Ruins to locate these relics before they are lost forever. The book rests near the Relicmaster on a desk overlooking the reflective waters of a small pool, but remains pristine. I should see what information it contains.\n"},
        [4] = 
            {appendStepText="", stepTextKey="I'm unable to take the Psijic Codex with me. I should copy down the locations described in the book."},
        ["Copy the Psijic Codex"] =
            {appendText=" in the Psijic Ruins on Artaeum near the Relicmaster. Without a reference, it would be difficult for me to intercept the relics in time.\n"},
        [5] = 
            {appendStepText="", stepTextKey="I've copied down the locations of the relics. I should speak to Relicmaster Glenadir once more."},
        ["Talk to Relicmaster Glenadir 3"] =
            {appendText=" inside Artaeum's Psijic Ruins and inform him of my success in deciphering the relic locations from the tome's pages.\n", stepTextKey="I've copied down the locations of the relics. I should speak to Relicmaster Glenadir once more."},
        [6] = 
            {appendStepText="", stepTextKey="I have everything I need to find the relics. I should speak to Relicmaster Glenadir for my reward."},
        ["Talk to Relicmaster Glenadir 4"] =
            {appendText=" in the Psijic Ruins on Artaeum. He may have more information on these relics and their dangers before I set out.\n ", stepTextKey="I have everything I need to find the relics. I should speak to Relicmaster Glenadir for my reward."},
    },

[GetQuestName(6146)] = { --"Wasting Away"			--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="An escaping vagrant told me Ruliel and some others are still waiting for the missing to return and told me where I could find their camp. I should speak to Ruliel about the disappearances."},
		["Talk to Ruliel 1"] =
			{appendText=". His camp is south of the Corgrad Wastes.", stepTextKey="An escaping vagrant told me Ruliel and some others are still waiting for the missing to return and told me where I could find their camp. I should speak to Ruliel about the disappearances."},
		[2] = 
			{appendStepText="", stepTextKey="Ruliel, one of the outcasts, suggested I talk to the agitated Altmer who's been harassing his group. The High Elf claims to be the heir to the estate and has been pressuring the outcasts to leave his land."},
		["Talk to Faidur 1"] =
			{appendText=" at the camp south of the Corgrad Wastes.", stepTextKey="Ruliel, one of the outcasts, suggested I talk to the agitated Altmer who's been harassing his group. The High Elf claims to be the heir to the estate and has been pressuring the outcasts to leave his land."},
		[3] = 
			{appendStepText="", stepTextKey="I spoke to the heir to the lands Ruliel's people are squatting on, Faidur, and he denies any knowledge of the disappearances. He claims he only recently arrived to explore his lost family holdings. We agreed to search the ruins together."},
		["Head to the Ruins of Corgrad"] =
			{appendText="."},
		[4] = 
			{appendStepText="", stepTextKey="Much of Congrad appears to have sunken into the sea, but some of the buildings still poke above the surface. Faidur and I need to find a way inside."},
		["Find a Way Inside the Ruins"] =
			{appendText=". Perhaps I should check for broken windows or cracks in the walls."},
		[5] = 
			{appendStepText="", stepTextKey="Faidur and I were able to enter a buried manor through a broken window. The place is in total ruin and there's no sign of the missing people yet. I should confer with Faidur about what we're looking for here."},
		["Talk to Faidur 2"] =
			{appendText=".", stepTextKey="Faidur and I were able to enter a buried manor through a broken window. The place is in total ruin and there's no sign of the missing people yet. I should confer with Faidur about what we're looking for here."},
		[6] = 
			{appendStepText="", stepTextKey="Faidur asked me to help him search the manor for anything that might tell us about the history of the place. I am not sure there will be much left untouched by the elements, but I will keep an eye out regardless."},
		["Search the Buried Manor for Clues to Its Past"] =
			{appendText=". That crumbled statue in the corner seems to be of interest."},
		[7] = 
			{appendStepText="", stepTextKey="There is a badly weathered statue in the foyer that appears to be of the head of the household. Faidur will want to hear about this."},
		["Talk to Faidur 3"] =
			{appendText=".", stepTextKey="There is a badly weathered statue in the foyer that appears to be of the head of the household. Faidur will want to hear about this."},
		[8] = 
			{appendStepText="", stepTextKey="Faidur was intrigued by the possibility that his family has ties to nobility, but it only makes the mystery of their disappearance from history all the more strange. Faidur wants to continue searching for clues."},
		["Search the Upstairs Landing"] =
			{appendText="."},
		[9] = 
			{appendStepText="", stepTextKey="I found a journal belonging to one of Faidur's ancestors. I should show it to him."},
		["Talk to Faidur 4"] =
			{appendText=" within the buried manor.", stepTextKey="I found a journal belonging to one of Faidur's ancestors. I should show it to him."},
		[10] = 
			{appendStepText="", stepTextKey="Faidur believes the journal I found comes from the time of the Thrassian Plague, possibly explaining why the town disappeared. He suggested we continue our search of the remaining upstairs rooms for more clues."},
		["Search the Adjacent Room"] =
			{appendText="."},
		[11] = 
			{appendStepText="", stepTextKey="The documents we found imply that there are burial vaults beneath the manor where the family took shelter as the plague worsened. I should speak to Faidur about our next move."},
		["Talk to Faidur 5"] =
			{appendText=".", stepTextKey="The documents we found imply that there are burial vaults beneath the manor where the family took shelter as the plague worsened. I should speak to Faidur about our next move."},
		[12] = 
			{appendStepText="", stepTextKey="A crumbling wall has exposed a tunnel of eroded stone leading deeper under the estate. Faidur thought he heard movement coming from the passage, which might be a sign of the missing persons. We should continue our search."},
		["Search the Underground Passages"] =
			{appendText="."},
		[13] = 
			{appendStepText="", stepTextKey="Faidur and I spotted a figure lurking in the shadows who fled as we approached. We found no sign of the figure, but there is a recently used camp. We should look for clues there."},
		["Search Campsite"] =
			{appendText=" within the underground passages."},
		[14] = 
			{appendStepText="", stepTextKey="The tunnel Ruliel's people traveled down leads to a large cavern, though there are signs of architecture as well. I need to pick up their trail again."},
		["Search the Cavern"] =
			{appendText="."},
		[15] = 
			{appendStepText="", stepTextKey="We stumbled across an encampment of people huddled around a fire in the cavern. They seem almost primitive, definitely not Ruliel's friends. One of the group invited us to join them."},
		["Talk to Cavern Dwellers"] =
			{appendText="."},
		[16] = 
			{appendStepText="", stepTextKey="Arillas told me he saw strangers from the surface head deeper into buried Corgrad, through a narrow tunnel to the north. Faidur has decided to remain with Arillas to learn more about this place. I will continue to search for the missing persons."},
		["Find Missing Persons"] =
			{appendText="."},
		[17] = 
			{appendStepText="", stepTextKey="The narrow passage lead to a dead end. There are bodies here that may be those of the missing squatters. I should search them for anything that would identify who they are."},
		["Search the Bodies"] =
			{appendText="."},
		[18] = 
			{appendStepText="", stepTextKey="The letter was a warning from Karnhar about the cave people, who ambushed me shortly after I discovered the truth. I need to find Faidur and get him out of here before he comes to harm."},
		["Find Faidur"] =
			{appendText=". The trogolodytes that took him scampered down the southern passage."},
		[19] = 
			{appendStepText="", stepTextKey="The cave people appear to have taken Faidur. Following the sound of his cries led me into the vaults beneath the Corgrad estate. I should search the chambers for him."},
		["Pursue Faidur's Abductors"] =
			{appendText="."},
		[20] = 
			{appendStepText="", stepTextKey="I found several missing persons being held captive in the estate's vaults. The appear to have been tortured. I should speak to them and find out what's going on."},
		["Talk to Henrigg 1"] =
			{appendText=".", stepTextKey="I found several missing persons being held captive in the estate's vaults. The appear to have been tortured. I should speak to them and find out what's going on."},
		[21] = 
			{appendStepText="", stepTextKey="The prisoners have been subjected to ghastly acts for some unknown purpose. They say that Faidur was taken to the Saviors, but I won't reach them without Arillas's keys. I need to find them, quickly."},
		["Find Arillas's Keys"] =
			{appendText="."},
		[22] = 
			{appendStepText="", stepTextKey="I found Arillas's keys in some sort of alchemical laboratory. I should be able to use them to free the prisoners from their bonds and open the door leading to Faidur and the Saviors."},
		["Rescue the Prisoners"] =
			{appendText="."},
		[23] = 
			{appendStepText="", stepTextKey="I freed the captive squatters. The one named Henrigg wishes to speak to me."},
		["Talk to Henrigg 2"] =
			{appendText=" within the underground vault.", stepTextKey="I freed the captive squatters. The one named Henrigg wishes to speak to me."},
		[24] = 
			{appendStepText="", stepTextKey="Henrigg told me Faidur is trapped in the crypts with the Saviors. I need to find him and rescue him before it is too late."},
		["Save Faidur"] =
			{appendText="."},
		[25] = 
			{appendStepText="", stepTextKey="I found Faidur inside the Saviors' crypt being subjected to some sort of ritual. Though their bodies are nothing more than desiccated husks, the Saviors appear aware. At least one of them has bid me to speak to him."},
		["Talk to Nemfarion"] =
			{appendText="."},
		[26] = 
			{appendStepText="", stepTextKey="The Saviors intend to use Faidur to revive themselves, condemning him to their sad state. I can't let them use him like that. There is a strange stone at the center of their ritual. I need to destroy it."},
		["Destroy the Embalming Stone"] =
			{appendText=" within the crypt."},
		[27] = 
			{appendStepText="", stepTextKey="Destroying the stone freed Faidur from its influence and appeared to kill the Saviors. I should see if Faidur is all right."},
		["Talk to Faidur 6"] =
			{appendText=" within the crypt.", stepTextKey="Destroying the stone freed Faidur from its influence and appeared to kill the Saviors. I should see if Faidur is all right."},
		[28] = 
			{appendStepText="", stepTextKey="Now that I have freed Faidur and the other prisoners we'll need to escape the underground before the Saviors' followers attempt to capture or kill us."},
		["Help the Prisoners Escape"] =
			{appendText="."},
		[29] = 
			{appendStepText="", stepTextKey="Arillas is livid about me killing his Saviors. He's blocked off our escape route. We'll have to go through him to make our escape from the ruins of Corgrad."},
		["Kill Arillas"] =
			{appendText="."},
		[30] = 
			{appendStepText="", stepTextKey="Crazed by the death of his Saviors, Arillas attempted to stop our escape, but I was able to best him in combat. We should be close to the surface now. We just need to reach it."},
		["Escape to the Surface"] =
			{appendText="."},
		[31] = 
			{appendStepText="", stepTextKey="I managed to lead Faidur and the others to the surface safely. Ruliel will want to hear about what has transpired down in those ruins and the fates of those who didn't escape."},
		["Talk to Ruliel 2"] =
			{appendText=", back at the camp south of the Corgrad Wastes.", stepTextKey="I managed to lead Faidur and the others to the surface safely. Ruliel will want to hear about what has transpired down in those ruins and the fates of those who didn't escape."},
		[32] = 
			{appendStepText="", stepTextKey="The Saviors are truly dead and their captives released, but the cave dwellers still remain in buried Corgrad. I should speak to Faidur about what he learned about his family's past and his own future."},
		["Talk to Faidur 7"] =
			{appendText=", back at the camp south of the Corgrad Wastes.", stepTextKey="The Saviors are truly dead and their captives released, but the cave dwellers still remain in buried Corgrad. I should speak to Faidur about what he learned about his family's past and his own future."},
	},

    [GetQuestName(6193)] = { --"Checking on Cloudrest"			--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="I should speak to Vandoril's mother, Belarin. I'll find her in the city of Cloudrest."},
        ["Talk to Belarin 1"] =
            {appendText=", a female High Elf that can be found tending to the wounded in Cloudrest. The cart to Cloudrest travels from the southwest road out of Alinor straight to the back way in.\n", stepTextKey="I should speak to Vandoril's mother, Belarin. I'll find her in the city of Cloudrest."},
        [2] = 
            {appendStepText="", stepTextKey=""},
        ["Talk to Belarin 2"] =
            {appendText=", a female High Elf that can be found where I left her, tending to the wounded in Cloudrest.", stepTextKey=""},
    },

	[GetQuestName(6174)] = { --"Whispers from the Deep"	--Strangelove
		[1] = 
			{appendStepText="", stepTextKey="The first adventurer Oriandra asked me to set free is a mage called Cainar. She thinks he can help us rescue the others once he's released from his mind trap."},
		["Find Cainar"] =
			{appendText=", deep within the Eldbur Ruins. Oriandra's connection with him is drawing me to the western chamber."},
		[2] = 
			{appendStepText="", stepTextKey="Cainar wants samples of the spell particles for his research. I need to find some for him before he will agree to leave. They should be nearby."},
		["Gather Spell Particles"] =
			{appendText=". I can find them within Cainar's trapped mindscape. Cainar may be able to tell me more about what to look for."},
		[3] = 
			{appendStepText="", stepTextKey="I have the spell particles Cainar asked for. I should bring them to him."},
		["Talk to Cainar"] =
			{appendText=" within his trapped mind."},
		[4] = 
			{appendStepText="", stepTextKey="Next I need to search for an Orc warrior called Grog. He should be in the ruins somewhere nearby."},
		["Find Grog"] =
			{appendText=". The connection Oriandra formed with me earlier is pulling me to the northern part of the Edbur Ruins."},
		[5] = 
			{appendStepText="", stepTextKey="It appears that Grog resisted the mind trap on his own, but he's still unconscious. I need to find a way to wake him up. I should look around for something that will help in that regard."},
		["Wake Grog Up"] =
			{appendText=", whom I found lying on the floor in a drunken state in the northern section of the Eldbur Ruins."},
		[6] = 
			{appendStepText="", stepTextKey="I found a bucket of water. That should do the trick. I just need to toss it on Grog to wake him up."},
		["Use the Bucket"] =
			{appendText=" on the passed out Orc, lying on the floor in the northern section of the Eldbur Ruins."},
		[7] = 
			{appendStepText="", stepTextKey="Now I need to find the adventurer named Miriya. She must be somewhere deeper in the ruins."},
		["Find Miriya"] =
			{appendText=". Oriandra's connection to her is pulling me to the southern chamber of the Eldbur Ruins."},
		[8] = 
			{appendStepText="", stepTextKey="I found Miriya, but the mind trap that has her in its grip has progressed to an almost inescapable point. Oriandra says that her sense of self is breaking apart. I need to find a way to help her."},
		["Follow Miriya's Path 1"] =
			{appendText=". I should follow the path within her trapped mind and watch as her core memories play themselves out along the way.", stepTextKey="I found Miriya, but the mind trap that has her in its grip has progressed to an almost inescapable point. Oriandra says that her sense of self is breaking apart. I need to find a way to help her."},
		[9] = 
			{appendStepText="", stepTextKey="Oriandra thinks that the items she's leaving behind might be the key to helping her remember herself. I should see if there are any other items I need to collect as I follow her path."},
		["Follow Miriya's Path 2"] =
			{appendText=". I should continue to follow the path within her trapped mind and watch as her core memories play themselves out along the way.", stepTextKey="Oriandra thinks that the items she's leaving behind might be the key to helping her remember herself. I should see if there are any other items I need to collect as I follow her path."},
		[10] = 
			{appendStepText="", stepTextKey="I collected a number of items that seem to be important to Miriya. I should give them to her and try to convince her to wake up now."},
		["Talk to Miriya"] =
			{appendText=" at the end of the path within her trapped mind."},
		[11] = 
			{appendStepText="", stepTextKey="After Oriandra pulled us out of Miriya's mindscape, something happened. I need to return to Oriandra and make sure everything is all right."},
		["Return to Oriandra"] =
			{appendText=". My connection to her is pulling me towards the central chamber of the Eldbur Ruins."},
		[12] = 
			{appendStepText="", stepTextKey="K'Tora left a trap that attacked Oriandra's mind. Cainar reestablished the mind link so I can enter the mind trap and rescue her. I need to hurry."},
		["Rescue Oriandra"] =
			{appendText=" within her trapped mind."},
		[13] = 
			{appendStepText="", stepTextKey="Now that we defeated the mind traps, I should talk to Oriandra and make sure the danger is over."},
		["Talk to Oriandra"] =
			{appendText=", back within the central chamber of the Eldbur Ruins."},
	},

   [GetQuestName(6175)] = { --"Lost Libations"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="Alamar believes his wine bottles were dropped throughout the surrounding wineries. I should search the nearby arbors."},
        ["Retrieve the Wine Bottles"] =
            {appendText=" \n\nPerhaps Alamar can pierce the veil of his drunken haze long enough to recall more information about where he left said bottles strewn about the vineyards of Russafeld."},
        [2] = 
            {appendStepText="", stepTextKey="I found the wine bottles. I should talk to Alamar and claim my reward."},
        ["Talk to Alamar"] =
            {appendText=", down the road south of Russafeld by the large, pink tree where I found him."},
    },
-- 		=========================================================================
--		  Summerset - Daily Quest 
-- 		=========================================================================

[GetQuestName(6084)] = { --"The Abyssal Alchemist"		--OneSkyGod
        [1] = 
            {appendStepText="Where a river west of Alinor cascades into a great waterfall, a cave is nearby.\n\n", stepTextKey="I need to head for Welenkin Cove, west of Alinor, and destroy any patches of tainted coral I come upon. Then I need to kill the Sea Sload alchemist that calls itself B'Korgen."},
        ["Kill B'Korgen"] =
            {appendText=". The entrance to its grotto is south of the waterfall.\n\n"},
        ["Destroy Tainted Coral"] =
            {appendText=" \n\nThe corals hum with a brown fouled glow, they are found on the beach from the base of the waterfall to further south."},
        [2] = 
            {appendStepText="", stepTextKey="I killed B'Korgen the Sea Sload and destroyed the patches of coral the creature corrupted. Now I should return to Justiciar Farowel and claim my reward."},
        ["Talk to Justiciar Farowel"] =
            {appendText=" at the busy stalls of Rinmawen's Plaza, at the heart of Alinor."},
    },

  [GetQuestName(6085)] = { --"Birds of a Feather"	--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="The gryphons nest on the northeast shore of the Isle. I should travel there and kill the creatures, as well as collect their feathers."},
        ["Kill Haeliata and Nagravia"] =
            {appendText=" at their aerie known as Gryphon Run.\n"},
        ["Collect Gryphon Feathers"] =
            {appendText=" \nI should gather feathers from Gryphon Moulting Piles around the edges of the aerie. The piles look like small hay stacks.\n\nNorthwest of the Kings Haven Pass Wayshrine is a span bridge. Across the bridge is the aerie Gryphon Run."},
        [2] = 
            {appendStepText="", stepTextKey="I've gathered the feathers and dealt with the gryphons Haeliata and Nagravia. I should return to Justiciar Farowel in Alinor."},
        ["Talk to Justiciar Farowel"] =
            {appendText=". I can find her where I left her in Rinmawen's Plaza in the center of Alinor.\n"},
    },

   [GetQuestName(6159)] = { --"Culling Serpents"	--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="I have agreed to go to Wasten Coraldale and destroy any reef viper nests I find there."},
        ["Destroy Reef Viper Nests"] =
            {appendText=" \nA boat to the island can be found along the shore southwest of the Cey-Tarn Keep Wayshrine, which is north of Alinor. The nests can be found in clutches of blue glowing egg sacs in and around the eastern part of the island where the vipers congregate.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I should return to Justiciar Tanorian and let him know that I destroyed the reef viper nests in Wasten Coraldale."},
        ["Talk to Justiciar Tanorian"] =
            {appendText=", who is where I left him in the center of Alinor in Rinmawen's Plaza.\n"},
    },


[GetQuestName(6086)] = { --"Never Forgotten"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="I have been tasked with killing Graveld and retrieving Scrolls of Oath from the fallen Justiciars."},
        ["Kill Graveld"] =
            {appendText=", a monstrous Salamander that can be found within her hideaway among the hills southwest of the Sil-Var-Woad wayshrine, which lies on the road southeast of Shimmerene.\n"},
        ["Recover Scrolls of Oath"] =
            {appendText=" \nThey can be found on the bodies of fallen Justiciars upon and around the rocky outcroppings of Graveld's Hideaway.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed Graveld. I should return to Justiciar Farowel and let her know."},
        ["Talk to Justiciar Farowel"] =
            {appendText=", where I left her in Rinmawen's Plaza in the center of Alinor.\n"},
    },

   [GetQuestName(6152)] = { --"Pilgrimage's End"	--TheoWriter 
        [1] = 
            {appendStepText="King's Haven pass runs through the mountain in the northern part of Summerset. Its lush serene river valley is, however, deceiving. One wrong step can spell the end a pilgrim's life. And for many traveling north from Ebon Stadmont Wayshrine, through the pass and east to the King's Haven Pass Wayshrine, it did. To bring peace to their souls, ", stepTextKey="I should travel to King's Haven Pass and see if I can recover articles of faith from the bodies of pilgrims who did not complete their journey through."},
        ["Recover Pilgrim Articles of Faith"] =
            {appendText=". \n\nLocals tell of a gryphon that made its nest in the pass, no doubt partaking in easy prey."},
        [2] = 
            {appendStepText="", stepTextKey="I have recovered articles of faith from pilgrims I found in King's Haven Pass. I should return them to Justiciar Tanorian."},
        ["Talk to Justiciar Tanorian"] =
            {appendText=" at the center of Rinmawen's Plaza in Alinor."},
    },

    [GetQuestName(6158)] = { --"Relic Runaround"	--Strangelove
        [1] = 
            {appendStepText="Tor-Hame-Khard lies at the end of the looped road to the southwest of Shimmerene. ", stepTextKey="I should travel to Tor-Hame-Khard to recover the relics. I should collect plans from fallen Sagacians."},
        ["Recover Stolen Relics"] =
            {appendText=" \n\nI can find them in reliquaries that look like coffers scattered throughout the ruins.\n"},
        ["Collect Sagacians' Plans"] =
            {appendText=" \n\n"},
        [2] = 
            {appendStepText="", stepTextKey="I've recovered the relics and collected the Sagacians' plans. I should return to Justiciar Tanorian in Alinor."},
        ["Talk to Justiciar Tanorian"] =
            {appendText=". I can find him where I left him, in Alinor's Rinmawen's Plaza."},
    },

[GetQuestName(6087)] = { --"Run Aground"		--TheoWriter 
        [1] = 
            {appendStepText="Alinor Bay, protected by the Sea Keep, should be one of the safest place to dock a ship on Summerset. Instead, there are reports of ships being attacked and sunk within the bay, with survivors feverishly speaking of a giant blue serpent that swallowed their mates whole. ", stepTextKey="I can find Keelsplitter in the bay near Sea Keep. The logs likely washed up on the shore nearby."},
        ["Kill Keelsplitter"] =
            {appendText=" in its lair on the other side of the Alinor Docks.\n\n"},
        ["Gather Ship's Logs"] =
            {appendText=" \n\nSea elves cannot be allowed to get their hands on them, no matter how much sand covers the pages."},
        [2] = 
            {appendStepText="", stepTextKey="I killed Keelsplitter and recovered the missing ships' logs. I should return to Justiciar Farowel."},
        ["Talk to Justiciar Farowel"] =
            {appendText=" at the center of Rinmawen's Plaza in Alinor."},
    },

[GetQuestName(6157)] = { --"A Rose's Beauty"		--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Archon's Grove and collect the blossoms."},
        ["Collect Rose-Of-Archon Blossoms"] =
            {appendText=" \n\nArchon's Grove lies at the end of a stone staircase on the southwestern shore of a large lake, south of Shimmerine. The roses I am looking for grow in clusters of large, red flowers."},
        [2] = 
            {appendStepText="", stepTextKey="I've recovered the Rose-Of-Archon blossoms from Archon's Grove. I should return them to Justiciar Tanorian in Alinor."},
        ["Talk to Justiciar Tanorian"] =
            {appendText=", standing in the center of Rimmawen's Plaza, where I last saw him."},
    },

    [GetQuestName(6082)] = { --"The Sickening Sea"		--TheoWriter 
        [1] = 
            {appendStepText="Some of the more prominent citizens of Lillandril take pride in their taste for decadent delicacies, eggs from Queen of the Reef being one of them. Such recklessness was in tiny defiance of the capital of Alinor, their neighbor across the bay to the south. But now, ", stepTextKey="Justiciar Farowel has instructed me to take several samples from the region where the Queen of the Reef dwells and deal with her accordingly if she has become a threat."},
        ["Kill Queen of the Reef"] =
            {appendText=" in her lair north of Lillandril. Summerset can no longer afford to ignore threats from the dark depths.\n"},
        ["Collect Coral Crab Eggs"] =
            {appendText=". \n\nBefore the corruption, locals would risk their lives to steal just a few from the clutches around the Sickening Sea.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I should return to Justiciar Farowel with the coral crab eggs I collected and let her know that the Queen of the Reef is dead."},
        ["Speak to Justiciar Farowel"] =
            {appendText=" at the center of Rinmawen's Plaza in Alinor.\n"},
    },


[GetQuestName(6166)] = { --"Sinking Summerset"			--Strangelove
        [1] = 
            {appendStepText="", stepTextKey="When I locate an abyssal geyser, I need to defeat its guardians, destroy the abyssal pearl, and shut down the geyser. I need to destroy at least one geyser to disrupt the Sea Sload threat."},
        ["Destroy an Abyssal Geyser"] =
            {appendText=". I can find one on the coast west of Alinor. The rest I will have to use other resources to find."},
        [2] = 
            {appendStepText="", stepTextKey="I destroyed an abyssal geyser. I should return to Battlereeve Tanerline and let her know I disrupted the plans of the Sea Sload cabal."},
        ["Talk to Battlereeve Tanerline"] =
            {appendText=", who is where I left her, on a spot overlooking the canal across from Rinmawen's Plaza."},
    },

    [GetQuestName(6156)] = { --"Snuffing Out the Light"		--Strangelove
        [1] = 
            {appendStepText="The entrance to Eton Nir Grotto is hidden within a crack in the wall of the rocky slope that lies northwest of the Eldbur Ruins Wayshrine, which can be found along the road north of Shimmerene adjacent to a marvelous stone archway. It lies at the midpoint of the ridge between the Eldbur Ruins proper and the eastern entrance of King's Haven Pass. ", stepTextKey="I should travel to the grotto and destroy the Daedra's cocoons. I should also burn any scriptures of Meridia I find."},
        ["Burn Scriptures of Meridia"] =
            {appendText=" \n\nI can find them in and around the remains of the Meridian cult's camp at the north side of the grotto.\n"},
        ["Destroy Cocoons"] =
            {appendText=" \n\nI can find them within the spiders' lair in the southwestern part of the grotto.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I've destroyed several Daedra cocoons and burned all the sacrilegious text I could find in Eton Nir Grotto. I should inform Justiciar Tanorian."},
        ["Talk to Justiciar Tanorian"] =
            {appendText=" where I left him, in Rinmawen's Plaza in central Alinor."},
    },

   [GetQuestName(6160)] = { --"Struck from Memory"	--TheoWriter 
        [1] = 
            {appendStepText="A person interested in tomes on forbidden magic will most likely stand out, even among the noblest of Altmers. Justiciars don't usually do favors, and even then one would have to be quite influential to curry such treatment.\n\n", stepTextKey="I must travel to the tavern in Alinor to meet with Justiciar Tanorian's associate, Esulo."},
        ["Talk to Esulo"] =
            {appendText=". Justiciar Tanorian mentioned that he frequents the bar at the Golden Gryphon."},
        [2] = 
            {appendStepText="Even on the small island of Artaeum, the Worm King found a place far from prying eyes. While the Psijic Order resided in the Ceporah Tower, he secluded himself in the western dungeons - now called Traitor's Vault. ", stepTextKey="According to Esulo, sealing these forbidden tomes away in Traitor's Vault will keep them out of the hands of would-be necromancers. I should travel to the ruin and lock Mannimarco's Forbidden Tomes away for good."},
        ["Seal Away the Forbidden Tomes"] =
            {appendText=". \n\nThe labyrynthian halls of Mannimarco's old laboratory on Artaeum are filled with horrors his experiments have wrought. I must find his chests to safely store the Forbidden Tomes, so that no-one will suffer the consequences of his pride again."},
        [3] = 
            {appendStepText="", stepTextKey="I disposed of Mannimarco's forbidden tomes on behalf of the Office of Divine Prosecution. I should return to Justiciar Tanorian and inform him of my success."},
        ["Talk to Justiciar Tanorian"] =
            {appendText=" at the center of Rinmawen's Plaza in Alinor."},
    },


   [GetQuestName(6083)] = { --"Taming the Wild"	--Strangelove
        [1] = 
            {appendStepText="Russafeld is on the road leading west from Shimmerene and Tor-Hame-Khard can be found at the end of the looped road southwest of the city. ", stepTextKey="I can find Caanerin's ancestral glade between Russafeld and Tor-Hame-Khard."},
        ["Kill Caanerin"] =
            {appendText=" within Indrik Folley.\n"},
        ["Activate the Warding Stones"] =
            {appendText=" \n\nI can find them outside of the rock formations that form a wall around Caanerin's glade.\n"},
        [2] = 
            {appendStepText="", stepTextKey="I killed Caanerin and penned its spirit within its ancestral grove. I should return to Justiciar Farowel."},
        ["Talk to Justiciar Farowel"] =
            {appendText=", where I last saw her, in Rinmawen's Plaza in central Alinor."},
    },



-- ==================================================================================================================================================
--	The Reach																															Undaunted
-- ==================================================================================================================================================

-- 		=========================================================================
--		  The Reach - Main Quest 
-- 		=========================================================================

	[GetQuestName(6549)] = { --"The Ravenwatch Inquiry" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="I need to meet with Gwendis, a member of the Ravenwatch, to find out more about the Gray Host."},
		["Talk to Gwendis 1"] =
			{appendText=". She should be near Evermore, the northeastern port city of Bangkorai, northeast of the East Evermore Wayshrine.", stepTextKey="I need to meet with Gwendis, a member of the Ravenwatch, to find out more about the Gray Host."},
		[2] = 
			{appendStepText="I met Gwendis by the eastern wayshrine of Evermore, the northeastern port city of Bangkorai. ", stepTextKey="The historians at Bangkorai Garrison might know more about the Gray Host. I should travel there with Gwendis."},
		["Travel to Bangkorai Garrison"] =
			{appendText=", a large fortress in the center of the region. I should follow the road south from Evermore. The garrison's northern entrance is east of a wayshrine."},
		[3] = 
			{appendStepText="I arrived at the northern gates of the fortress in central Bangkorai, south of Evermore. ", stepTextKey="Scholar Laurette Diel is an expert on Bangkorai Garrison battles. I should speak to her and see what I can learn about the Gray Host's defeat in the ancient past."},
		["Talk to Scholar Laurette Diel"] =
			{appendText=" at a small campsite a short distance northeast of the gates. Gwenis is already there."},
		[4] = 
			{appendStepText="Near the garrison in central Bangkorai, south of Evermore, I spoke with Scholar Laurette Diel. ", stepTextKey="The Imperial army recently attacked Bangkorai Garrison. Scholar Diel's fellow scholars fled with the aid of a Pyre Watch warrior. I should talk to Gwendis about what we need to do next."},
		["Talk to Gwendis 2"] =
			{appendText=" at the scholar's campsite northeast of the garrison's northern gates.", stepTextKey="The Imperial army recently attacked Bangkorai Garrison. Scholar Diel's fellow scholars fled with the aid of a Pyre Watch warrior. I should talk to Gwendis about what we need to do next."},
		[5] = 
			{appendStepText="At the scholars' camp near Bangkorai Garrison, south of Evermore, ", stepTextKey="Gwendis suggested I look for Scholars Cogline and Indouz, who headed for Evermore, while she looks for Scholar Jeanard, who headed for Kerbol's Hollow."},
		["Find Scholar Cogline"] =
			{appendText=". The bald man may be in an area with burial sites, south of Evermore and northwest of the Bangkorai Pass Wayshrine. He may be hiding behind a wall or a statue to stay safe.\n"},
		["Find Scholar Indouz"] =
			{appendText=". He is standing near a campfire in Martyr's Crossing, an encampment southeast of Evermore."},
		[6] = 
			{appendStepText="", stepTextKey="I found Scholar Indouz and Scholar Cogline. They survived thanks to the efforts of the Pyre Watch warrior, who is still missing. She was last seen retreating into the Crypt of the Exiles. I should check for her there."},
		["Find the Pyre Watch Warrior"] =
			{appendText=" in the underground crypt. Its trapdoor entry is south of Peylyn Graveyard and north of the Bangkorai Pass Wayshrine. If she was fighting Imperials, she may be in one of the the burial site's passages."},
		[7] = 
			{appendStepText="South of Peylyn Graveyard and north of the Bangkorai Pass Wayshrine, ", stepTextKey="I found the Pyre Watch warrior in the Crypt of the Exiles. I should speak with her."},
		["Talk to Shelaria 1"] =
			{appendText=", a Redguard, in the western passage.", stepTextKey="I found the Pyre Watch warrior in the Crypt of the Exiles. I should speak with her."},
		[8] = 
			{appendStepText="I spoke with the Redguard warrior in the western passage of the underground burial site, south of Peylyn Graveyard and north of the Bangkorai Pass Wayshrine. ", stepTextKey="I need to escort the Pyre Watch warrior, Shelaria, safely out of the Crypt of the Exiles. Then I can speak with her at length about the Gray Host."},
		["Escort Shelaria to Safety"] =
			{appendText=" outside of the crypt."},
		[9] = 
			{appendStepText="South of Peylyn Graveyard and north of the Bangkorai Pass Wayshrine, ", stepTextKey="I escorted Shelaria safely out of the Crypt of the Exiles. I should ask her what she knows about the Gray Host's defeat in the First Era."},
		["Talk to Shelaria 2"] =
			{appendText=" outside the entrance to the underground crypt.", stepTextKey="I escorted Shelaria safely out of the Crypt of the Exiles. I should ask her what she knows about the Gray Host's defeat in the First Era."},
		[10] = 
			{appendStepText="", stepTextKey="Shelaria says history suggests someone survived the Gray Host's defeat and fled to Viridian Watch after the fateful battle. I should meet Gwendis back at Bangkorai Garrison and tell her what I learned."},
		["Talk to Gwendis 3"] =
			{appendText=" at the scholars' campsite just northeast of the garrison's northern gates.", stepTextKey="Shelaria says history suggests someone survived the Gray Host's defeat and fled to Viridian Watch after the fateful battle. I should meet Gwendis back at Bangkorai Garrison and tell her what I learned."},
		[11] = 
			{appendStepText="At the scholars' campsite near the gates of the garrison in central Bangkorai, I shared with Gwendis what I learned from the Pyre Watch warrior. ", stepTextKey="Gwendis and I need to head to Viridian Watch to see if we can uncover any clues about the mysterious Gray Host survivor."},
		["Enter Viridian Watch"] =
			{appendText="'s underground through a trapdoor in a crumbling tower. It is east of the northeastern city of Evermore, on the eastern shore of a large lake, southwest of the Forsaken Stronghold."},
		[12] = 
			{appendStepText="We entered the Watch through a trapdoor in a crumbling tower on the eastern shore of a large lake, east of the northeastern city of Evermore. ", stepTextKey="Gwendis and I need to search for clues inside Viridian Watch about the Gray Host survivor."},
		["Search for the Gray Host Hideout 1"] =
			{appendText=" in the Watch's underground.", stepTextKey="Gwendis and I need to search for clues inside Viridian Watch about the Gray Host survivor."},
		[13] = 
			{appendStepText="We entered the Watch through a trapdoor in a crumbling tower on the eastern shore of a large lake, east of the northeastern city of Evermore. ", stepTextKey="Gwendis found strange sigils that can only be seen by vampires and werewolves in Viridian Watch. This must be a clue to where the rumored survivor found refuge. I should speak to Gwendis about the sigils."},
		["Talk to Gwendis 4"] =
			{appendText=" in the underground entry chamber.", stepTextKey="Gwendis found strange sigils that can only be seen by vampires and werewolves in Viridian Watch. This must be a clue to where the rumored survivor found refuge. I should speak to Gwendis about the sigils."},
		[14] = 
			{appendStepText="We entered the Watch through a trapdoor in a crumbling tower on the eastern shore of a large lake, east of the northeastern city of Evermore.  Gwendis found a vampiric sigil. ", stepTextKey="Gwendis and I need to search Viridian Watch for more of these sigils and, if possible, follow them to the place where the Gray Host survivor found refuge."},
		["Search for the Gray Host Hideout 2"] =
			{appendText=" by following the sigils.", stepTextKey="Gwendis and I need to search Viridian Watch for more of these sigils and, if possible, follow them to the place where the Gray Host survivor found refuge."},
		[15] = 
			{appendStepText="We entered the Watch through a trapdoor in a crumbling tower on the eastern shore of a large lake, east of the northeastern city of Evermore. Gwendis found vampiric sigils. ", stepTextKey="The sigils lead to what Gwendis believes is an entrance to the Gray Host hideout. Once she finds a way inside, we can investigate."},
		["Watch Gwendis 1"] =
			{appendText=" reveal a secret passage in the small eastern room in Viridian Watch.", stepTextKey="The sigils lead to what Gwendis believes is an entrance to the Gray Host hideout. Once she finds a way inside, we can investigate."},
		[16] = 
			{appendStepText="We entered the Watch through a trapdoor in a crumbling tower on the eastern shore of a large lake, east of the northeastern city of Evermore. Through its easternmost room we discovered a sanctuary. ", stepTextKey="Gwendis found a way into the Gray Host hideout. I should follow her."},
		["Search the Gray Host Hideout 1"] =
			{appendText=" after entering the secret passage to the Grey Host Sanctuary in the Watch's small eastern room.", stepTextKey="Gwendis found a way into the Gray Host hideout. I should follow her."},
		[17] = 
			{appendStepText="We entered the Watch through a trapdoor in a crumbling tower on the eastern shore of a large lake, east of the northeastern city of Evermore. Through its easternmost room we discovered a sanctuary. ", stepTextKey="Gwendis and I discovered a long abandoned room where a Gray Host survivor hid after the battle at Bangkorai Garrison. I should search for clues."},
		["Search the Gray Host Hideout 2"] =
			{appendText=" for a few more clues about an ancient visitor.", stepTextKey="Gwendis and I discovered a long abandoned room where a Gray Host survivor hid after the battle at Bangkorai Garrison. I should search for clues."},
		[18] = 
			{appendStepText="We entered the Watch through a trapdoor in a crumbling tower on the eastern shore of a large lake, east of the northeastern city of Evermore. From its easternmost room we entered a sanctuary. ", stepTextKey="Gwendis sounds concerned. I should speak to her about the signet I found."},
		["Talk to Gwendis 5"] =
			{appendText=" in the Grey Host Sanctuary.", stepTextKey="Gwendis sounds concerned. I should speak to her about the signet I found."},
		[19] = 
			{appendStepText="In the Grey Host Sanctuary we discovered at Veridian Watch, we found a signet. ", stepTextKey="Gwendis recognized the signet. She says her mentor, Count Verandis Ravenwatch, had one just like it. She asked me to meet her at Ravenwatch Castle in Rivenspire so we can investigate this matter further."},
		["Meet Gwendis at Ravenwatch Castle"] =
			{appendText=". She should be around back by the stables.\n\nRavenwatch Castle sits up in the mountains northwest of Rivenspire. It is west of the central city of Shornhelm, and up stone stairs from the village of Crestshade."},
		[20] = 
			{appendStepText="At Ravenwatch Castle, west of Rivenspire's central city of Shornhelm and on the mountainside north of the village of Crestshade, ", stepTextKey="I found Gwendis waiting in the courtyard behind Ravenwatch Castle. I should speak to her."},
		["Talk to Gwendis 6"] =
			{appendText=".", stepTextKey="I found Gwendis waiting in the courtyard behind Ravenwatch Castle. I should speak to her."},
		[21] = 
			{appendStepText="I found Gwendis at Ravenwatch Castle, west of Rivenspire's central city of Shornhelm and on the mountainside north of the village of Crestshade. ", stepTextKey="To avoid drawing attention, Gwendis wants to use a secret entrance to enter Ravenwatch Castle."},
		["Enter Ravenwatch Castle"] =
			{appendText="'s cellar through a trapdoor at the stables behind the castle."},
		[22] = 
			{appendStepText="Ravenwatch Castle is west of Rivenspire's central city of Shornhelm and on the mountainside north of the village of Crestshade. There, we used a secret passage from the stables behind the castle. ", stepTextKey="We successfully entered Ravenwatch Castle. I should follow Gwendis to the cellar, where Verandis stored his possessions."},
		["Follow Gwendis"] =
			{appendText=" to the cellar, down the stairs to the right."},
		[23] = 
			{appendStepText="At Ravenwatch Castle, west of Rivenspire's central city of Shornhelm and on the mountainside north of the village of Crestshade, ", stepTextKey="Gwendis wants to see if we can find a signet similar to the one we acquired at Viridian Watch. She's sure she remembers seeing Verandis with one. I should search the cellar for it."},
		["Search the Cellar"] =
			{appendText=". There are a lot of crates, cargo boxes, and other containers to search. And then there's an old armoire."},
		[24] = 
			{appendStepText="At Ravenwatch Castle, west of Rivenspire's central city of Shornhelm and on the mountainside north of the village of Crestshade, in its cellar there is an old armoire. ", stepTextKey="I discovered a secret door. It's locked, but Gwendis believes she can open it using the signet we found at Viridian Watch. I should wait while she attempts to get inside."},
		["Watch Gwendis 2"] =
			{appendText=".", stepTextKey="I discovered a secret door. It's locked, but Gwendis believes she can open it using the signet we found at Viridian Watch. I should wait while she attempts to get inside."},
		[25] = 
			{appendStepText="At Ravenwatch Castle, west of Rivenspire's central city of Shornhelm and on the mountainside north of the village of Crestshade, in its cellar there is an old armoire. ", stepTextKey="We found a secret study in the castle cellar. We should search for any evidence that connects Verandis to the Gray Host, or that exonerates him of any involvement."},
		["Search the Secret Room"] =
			{appendText="'s bookshelves and desk."},
		[26] = 
			{appendStepText="At Ravenwatch Castle, west of Rivenspire's central city of Shornhelm and on the mountainside north of the village of Crestshade, in its cellar there is an old armoire. The armoire is a secret door to a study. ", stepTextKey="I found a letter from Rada al-Saran to Verandis Ravenwatch. It confirms Verandis was a member of the Gray Host. I should speak to Gwendis about this."},
		["Talk to Gwendis 7"] =
			{appendText=" in Count Verandis' secret study.", stepTextKey="I found a letter from Rada al-Saran to Verandis Ravenwatch. It confirms Verandis was a member of the Gray Host. I should speak to Gwendis about this."},
		[27] = 
			{appendStepText="Ravenwatch Castle is west of Rivenspire's central city of Shornhelm and on the mountainside north of Crestshade. In the Castle's secret study I found a letter. ", stepTextKey="The letter from Rada al-Saran invited Verandis to visit him at an island castle and provided a map. Gwendis suggested our next step is to investigate this castle. She asked me to meet her at the cart outside."},
		["Meet Gwendis Outside"] =
			{appendText=" the castle by the horse and cart."},
		[28] = 
			{appendStepText="At Ravenwatch Castle, west of Rivenspire's central city of Shornhelm and on the mountainside north of the village of Crestshade, ", stepTextKey="I should speak to Gwendis one last time before we travel to the secret Gray Host island."},
		["Talk to Gwendis 8"] =
			{appendText=" near the horse and cart.", stepTextKey="I should speak to Gwendis one last time before we travel to the secret Gray Host island."},
	},

	[GetQuestName(6555)] = { --"The Gray Council" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Gwendis and I need to travel to the secret island of Grayhome, using the map on the back of Rada al-Saran's letter to Verandis. The journey begins with the cart waiting for us at Ravenwatch Castle."},
		["Travel to Grayhome"] =
			{appendText=" with Gwendis. She waits by the cart.\n\nRavenwatch Castle sits on the mountainside north of Crestshade and west of Rivenspire's central city of Shornhelm."},
		[2] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat. ", stepTextKey="We arrived on the secret Gray Host island. I should speak to Gwendis and find out what she wants to do now."},
		["Talk to Gwendis 1"] =
			{appendText=" at Grayhome's southern pier.", stepTextKey="We arrived on the secret Gray Host island. I should speak to Gwendis and find out what she wants to do now."},
		[3] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. ", stepTextKey="Gwendis wants to survey the island for traps and wildlife before we approach the castle. I should follow her."},
		["Follow Gwendis"] =
			{appendText="."},
		[4] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. We headed north on the pier to begin exploring the island. ", stepTextKey="We discovered an odd-looking crystal. When Gwendis approached, it pulsed. I should ask her what she thinks about this."},
		["Talk to Gwendis 2"] =
			{appendText=" at the north end of the island's pier.", stepTextKey="We discovered an odd-looking crystal. When Gwendis approached, it pulsed. I should ask her what she thinks about this."},
		[5] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. At the north end of the pier, ", stepTextKey="Gwendis thinks this crystal might be part of some sort of ward protecting the castle. She's seen something like this before. She asked me to try to deactivate the crystal."},
		["Deactivate the Crystal"] =
			{appendText=" near us."},
		[6] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. ", stepTextKey="Gwendis believes I successfully deactivated the first crystal. She thinks she sees more up ahead. I need to deactivate those as well before we can safely enter the castle."},
		["Deactivate the Western Crystal"] =
			{appendText=" in the western tower.\n"},
		["Deactivate the Northern Crystal"] =
			{appendText=" at the top of the tower in front of the castle.\n"},
		["Deactivate the Eastern Crystal"] =
			{appendText=" in the eastern tower."},
		[7] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. At each tower, I deactivated its warding crystal. ", stepTextKey="When I deactivated the last crystal, there was an audible rumble. We should check the front door and see if we can enter the castle now."},
		["Investigate the Castle"] =
			{appendText="."},
		[8] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. Deactivating the crystals worked. ", stepTextKey="We entered the ancient Gray Host castle. I should talk to Gwendis about where we should begin our search."},
		["Talk to Gwendis 3"] =
			{appendText=" in the castle's entry hall.", stepTextKey="We entered the ancient Gray Host castle. I should talk to Gwendis about where we should begin our search."},
		[9] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. In the castle, Gwendis prepared a potion for me. ", stepTextKey="I must drink the dream-walk potion mixed with a vial of Verandis Ravenwatch's blood so I can experience Verandis's memories of this place and discover the truth of his connection."},
		["Drink the Dream-Walk Potion 1"] =
			{appendText=" on the table in the entry hall.", stepTextKey="I must drink the dream-walk potion mixed with a vial of Verandis Ravenwatch's blood so I can experience Verandis's memories of this place and discover the truth of his connection."},
		[10] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. Now, I am dream-walking. ", stepTextKey="My journey through Verandis's memories begins. I arrived at the castle. The steward instructed me to speak with Verandis' fellow exarchs while his study is prepared."},
		["Talk to Exarch Ulfra"] =
			{appendText=" on the western terrace of the castle's main floor.\n"},
		["Talk to Exarch Tzinghalis"] =
			{appendText=". He is likely upstairs to the northwest, in his laboratory.\n\nI should speak to Steward Faustine in the entry hall before finding the exarchs."},
		[11] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. I am dream-walking. ", stepTextKey="My journey through Verandis' memories continues. As Verandis, I spoke with both Exarch Ulfra and Exarch Tzinghalis. Now, I need to seek out Rada al-Saran."},
		["Talk to Rada al-Saran"] =
			{appendText=" in the large southern chamber upstairs."},
		[12] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. I am dream-walking. ", stepTextKey="My journey through Verandis's memories continues. The steward moved Verandis' personal belongings to the study prepared for him. I should find it and see what clues it might hold."},
		["Find Verandis's Study"] =
			{appendText=" off the southeastern upper hallway of the castle."},
		[13] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. I am dream-walking. ", stepTextKey="My journey through Verandis's memories continues. I entered Verandis's study. Now I should read Verandis's journal. Maybe they will give me more insight into his connection to the Gray Host."},
		["Read Verandis's Journal 1"] =
			{appendText=" resting on his desk.", stepTextKey="My journey through Verandis's memories continues. I entered Verandis's study. Now I should read Verandis's journal. Maybe they will give me more insight into his connection to the Gray Host."},
		[14] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. I am dream-walking. ", stepTextKey="I attempted to read Verandis's notes, but could not. I heard Gwendis call out to me from the real world. I should find the dream-walk potion in the dream and drink it to wake up."},
		["Drink the Dream-Walk Potion 2"] =
			{appendText=" on Verandis' desk.", stepTextKey="I attempted to read Verandis's notes, but could not. I heard Gwendis call out to me from the real world. I should find the dream-walk potion in the dream and drink it to wake up."},
		[15] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. In the castle, ", stepTextKey="I exited the dream-walk. Now I should tell Gwendis what I learned about Verandis and his ties to the Gray Host."},
		["Talk to Gwendis 4"] =
			{appendText=" in the entry hall of the Grey Host castle of Grayhome.", stepTextKey="I exited the dream-walk. Now I should tell Gwendis what I learned about Verandis and his ties to the Gray Host."},
		[16] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. ", stepTextKey="In Verandis's memories, there was a journal in his study. I need to find the same study in the present and see if the ancient journal is still there."},
		["Read Verandis's Journal 2"] =
			{appendText=". His study was upstairs, off the southeastern hallway.", stepTextKey="In Verandis's memories, there was a journal in his study. I need to find the same study in the present and see if the ancient journal is still there."},
		[17] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. I entered Verandis's old study on the castle's upper floor in the southeast hallway, ", stepTextKey="Verandis's journal mentions a ritual involving stone husks. Apparently, when he attempted the ritual on a mortal, it drove her mad. I should tell Gwendis what I learned."},
		["Talk to Gwendis 5"] =
			{appendText=" in the study.", stepTextKey="Verandis's journal mentions a ritual involving stone husks. Apparently, when he attempted the ritual on a mortal, it drove her mad. I should tell Gwendis what I learned."},
		[18] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. Now, ", stepTextKey="Gwendis wants to use Verandis's ritual to try to resurrect a member of the Gray Council so she can interrogate them. I need to find the reliquary Verandis filled with some of his life essence and hid in the armory."},
		["Retrieve Verandis's Reliquary"] =
			{appendText=". The armory is in the central chamber of the lower level. I suspect the reliquary will be out of the way and possibly in a chest."},
		[19] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. In the castle's armory on the lower level, ", stepTextKey="I found Verandis's reliquary. Now I should meet Gwendis in the ritual chamber."},
		["Enter the Ritual Chamber"] =
			{appendText=", below the main floor. There are stairs leading down at the back of the castle, to the north."},
		[20] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. In the castle's Ritual Chamber, downstairs from the main floor's north end, ", stepTextKey="Gwendis prepared all elements of the ritual while I gathered the reliquary. I should do whatever she tells me to complete the ritual."},
		["Complete the Ritual"] =
			{appendText="."},
		[21] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. In the Ritual Chamber on the castle's northern, lowest level, I lit candles and place the reliquary. ", stepTextKey="The ritual seems to be working. I should get ready for whatever happens next."},
		["Observe the Ritual"] =
			{appendText="."},
		[22] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. In the Ritual Chamber on the castle's northern, lowest level, an ancient exarch appeared. ", stepTextKey="The vampire we resurrected is mad with hunger. Gwendis and I must subdue him before he kills us both."},
		["Defeat the Exarch"] =
			{appendText=" and his minions."},
		[23] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. In the Ritual Chamber ", stepTextKey="I should give Gwendis and Verandis a moment to catch up."},
		["Observe the Reunion"] =
			{appendText="."},
		[24] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. ", stepTextKey="I should head out of the ritual chamber and see what Count Verandis has to say."},
		["Meet Verandis Outside"] =
			{appendText=" in the castle's northernmost hallway."},
		[25] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. In the northernmost hallway of the castle's lower level, ", stepTextKey="I should speak to Count Verandis Ravenwatch and learn what I can about all that transpired."},
		["Talk to Count Verandis Ravenwatch"] =
			{appendText="."},
		[26] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. In the castle's northernmost hallway, ", stepTextKey="I should speak to Gwendis about everything we learned during our investigation."},
		["Talk to Gwendis 6"] =
			{appendText=".", stepTextKey="I should speak to Gwendis about everything we learned during our investigation."},
		[27] = 
			{appendStepText="We traveled by horse and cart from Ravenwatch Castle in northwestern Rivenspire, and then by boat to reach Grayhome. ", stepTextKey="Now that we finished investigating the Gray Host and Verandis's connection to them, I need to give Gwendis and Verandis time to catch up and figure out our next move against Rada al-Saran. I should see if she needs anything else in the meantime."},
		["Talk to Gwendis 7"] =
			{appendText=" in the Grayhome castle's northernmost hallway.", stepTextKey="Now that we finished investigating the Gray Host and Verandis's connection to them, I need to give Gwendis and Verandis time to catch up and figure out our next move against Rada al-Saran. I should see if she needs anything else in the meantime."},
	},


	[GetQuestName(6550)] = { --"The Despot of Markarth" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="I should go to the Reach and look for Count Verandis Ravenwatch."},
		["Talk to Count Verandis Ravenwatch 1"] =
			{appendText=". He should be outside the city of Markarth, not far from the North Markarth Wayshrine. Or if I arrive on the road from southwestern Western Skyrim, I may catch up with him on the eastern road.\n\nI can travel to The Reach's western city via wayshrine, by boat, by cart, or on the road from southwestern Western Skyrim.", stepTextKey="I should go to the Reach and look for Count Verandis Ravenwatch."},
		[2] = 
			{appendStepText="", stepTextKey="I should speak to Count Verandis and see what kind of information he suggests I seek out."},
		["Talk to Count Verandis Ravenwatch 2"] =
			{appendText=". He should be outside of the city of Markarth, not far from the North Markarth Wayshrine.", stepTextKey="I should speak to Count Verandis and see what kind of information he suggests I seek out."},
		[3] = 
			{appendStepText="I spoke with Count Ravenwatch about the situation in The Reach. ", stepTextKey="Verandis encouraged me to begin my investigation by speaking with the nearby Reach sentry. She might give me an idea as to what type of information Ard Caddach would consider important enough to meet with us about."},
		["Talk to Sentry Bodfe 1"] =
			{appendText=". She stands with her greatsword at the entrance to the western city of Markarth's fort, west of the North Markarth Wayshrine.", stepTextKey="Verandis encouraged me to begin my investigation by speaking with the nearby Reach sentry. She might give me an idea as to what type of information Ard Caddach would consider important enough to meet with us about."},
		[4] = 
			{appendStepText="At the fort's entrance to the city of Markarth, I spoke with Sentry Bodfe. ", stepTextKey="The sentry mentioned that the ard's soldiers have been called back to Markarth because Caddach feels the rebels are a bigger threat to the city than the Gray Host. I should explore east of the city and see what I can learn."},
		["Gather Information"] =
			{appendText="\n\nI should visit the small village, south across the first bridge east of the city.\nAnother note is at a camp up on the northern area of the mountain surrounded by roads, southeast of the North Markarth Wayshrine.\nAnother is near the bridge,  east of the North Markarth Wayshrine where its road ends at the northeastern, riverside road. There may be someone I can talk to near the merchant's camp."},
		[5] = 
			{appendStepText="", stepTextKey="I learned that the rebels may be gathering in the foothills east of Markarth, that someone named Arana may be their leader, and that the rebels are hunting the Gray Host. Now I should go to Understone Keep and find Verandis."},
		["Go to Understone Keep"] =
			{appendText=", Ard Caddach's palace in Markarth, up in the western end of the city."},
		[6] = 
			{appendStepText="Inside Understone Keep in western Markarth, ", stepTextKey="I need to tell Count Verandis what I learned about the rebels and the Gray Host."},
		["Talk to Count Verandis Ravenwatch 3"] =
			{appendText=" in the keep's northeastern entry hall.", stepTextKey="I need to tell Count Verandis what I learned about the rebels and the Gray Host."},
		[7] = 
			{appendStepText="In western Markarth, ", stepTextKey="I arrived in Understone Keep. Now, I should speak with Sentry Bodfe. Hopefully she'll give me permission to speak with Ard Caddach."},
		["Talk to Sentry Bodfe 2"] =
			{appendText=" in the keep's entry hall, near the archway leading to the Ard's throne room.", stepTextKey="I arrived in Understone Keep. Now, I should speak with Sentry Bodfe. Hopefully she'll give me permission to speak with Ard Caddach."},
		[8] = 
			{appendStepText="Inside Understone Keep in western Markarth, ", stepTextKey="I should approach the throne and share what I learned with Ard Caddach, the Despot of Markarth. Hopefully, this conversation will help us gain a better understanding of the Gray Host's plans for the region."},
		["Talk to Ard Caddach 1"] =
			{appendText=". He sits on his throne, through the hallway near the sentry and up the stairs west of the entry hall.", stepTextKey="I should approach the throne and share what I learned with Ard Caddach, the Despot of Markarth. Hopefully, this conversation will help us gain a better understanding of the Gray Host's plans for the region."},
		[9] = 
			{appendStepText="In Understone Keep in western Markarth, through a hallway and up the stairs west of the entry hall, I spoke with the Ard as he sat upon his throne. ", stepTextKey="Ard Caddach asked me to speak to his advisor, Lady Belain. He wants me to help her find the rebel leader Arana before he agrees to meet with Count Verandis."},
		["Talk to Lady Belain"] =
			{appendText=". The raven-haired woman is at the foot of the throne's steps."},
		[10] = 
			{appendStepText="In Markarth's Understone Keep, I spoke with the Ard's Breton keep-witch, his trusted advisor. ", stepTextKey="Lady Belain wants me to search for Arana and the rebels in the foothills to the east of Markarth. A favor for a favor, as she said."},
		["Find the Rebels"] =
			{appendText=" outside of the city. I should speak with Verandis in the keep's entry hall before I leave.\n\nI should travel southeast of the city, across a bridge south of the North Markarth Wayshrine, and along the western, southbound road. North of a second bridge near a waterfall, there are torches and fires burning above the western side of the road."},
		[11] = 
			{appendStepText="South of the North Markarth Wayshrine along the western, southbound road, just north of a second bridge, ", stepTextKey="I came across an encampment that may belong to Arana's rebels. A sentry noticed me and called out. I should talk to him."},
		["Talk to Tayfaern"] =
			{appendText=", a Reachman with a battle axe, near the camp's entrance."},
		[12] = 
			{appendStepText="", stepTextKey="Tayfaern, a member of Arana's rebels, wants me to investigate a few Gray Host stockpiles and tell him what they're storing there. If I perform this favor, he might introduce me to Arana."},
		["Investigate Gray Host Stockpiles"] =
			{appendText=" \n\nA cache is east of Arana's rebel camp, between the roads north of the river.\nAnother is southeast of the camp and northeast of Nalzthdbar Great Lift, south of the river and north of the road and a ritual site.\nAnd another cache is further southeast of the rebel camp, on the west side of the road that starts east of the curve in the rebel camp's road. It is northeast of Vateshran Hollows."},
		[13] = 
			{appendStepText="", stepTextKey="The Gray Host stockpiles contained gray reliquaries and witch pikes. I also found a letter that mentioned a gathering circle, northwest of Valthume Barrow, where a spy meets with the Gray Host. I should investigate before I return to the rebel camp."},
		["Investigate the Gathering Circle"] =
			{appendText=" on the ground between the roads east of Vateshran Hollows, southeast of Reachwind Depths."},
		[14] = 
			{appendStepText="Between the roads east of Vateshran Hollows, southeast of Reachwind Depths, and west of a clan camp, I descended the steps into the circle. ", stepTextKey="It looks like this gathering circle has seen recent use. There's a letter on the table. I should read it."},
		["Examine the Letter"] =
			{appendText="."},
		[15] = 
			{appendStepText="Between the roads east of Vateshran Hollows, southeast of Reachwind Depths, and west of a clan camp, I descended the steps into the circle and found a letter from Lady Belain. ", stepTextKey="As I prepared to leave the ruin, the rebel witch, Arana, appeared. I should speak with her."},
		["Talk to Arana"] =
			{appendText=" in the gathering circle."},
		[16] = 
			{appendStepText="", stepTextKey="A note in the gathering circle confirms that Lady Belain is working with the Gray Host, and Arana revealed that Belain is also a vampire. I need to go to Valthume and observe a meeting between her and the Gray Host leader."},
		["Go to Valthume"] =
			{appendText=", an ancient burial site at the end of the southernmost road in The Reach's southeast. It is east of Vateshran Hollows and south of the Shadefeather Clan Camp."},
		[17] = 
			{appendStepText="In The Reach's southeast, ", stepTextKey="I arrived at the barrow called Valthume. Now I need to find Lady Belain and the Gray Host leader."},
		["Find Lady Belain"] =
			{appendText=". She is likely meeting in the large southeastern chamber. I should go through the chambers and passages, south and east, to reach a spot above the west end of that large chamber."},
		[18] = 
			{appendStepText="At Valthume in the region's southeast, I reached a platform to the west and above the barrow's large southeastern chamber. ", stepTextKey="I found Lady Belain speaking to the leader of the Gray Host. I should observe from the shadows to learn their plans."},
		["Eavesdrop on Lady Belain"] =
			{appendText="."},
		[19] = 
			{appendStepText="At Valthume in the region's southeast, I reached a platform to the west and above the barrow's large southeastern chamber. After his conversation with Lady Belain, ", stepTextKey="Rada al-Saran, the leader of the Gray Host, sensed my presence. He requested that I follow him. This might be my only opportunity to see what he has to say."},
		["Talk to Rada al-Saran"] =
			{appendText=". He is probably in the barrow's northeastern chamber."},
		[20] = 
			{appendStepText="Now that I've spoken with Rada al-Saran at Valthume, ", stepTextKey="I should return to Ard Caddach's throne room in Understone Keep to tell Count Verandis and Ard Caddach what I learned about Lady Belain and the Gray Host's plans."},
		["Return to Ard Caddach's Throne Room"] =
			{appendText=" at Understone Keep in western Markarth."},
		[21] = 
			{appendStepText="Near the Ard's throne in Markarth's Understone Keep, ", stepTextKey="I should inform Count Verandis about what I learned before I speak to Ard Caddach."},
		["Talk to Count Verandis Ravenwatch 4"] =
			{appendText=".", stepTextKey="I should inform Count Verandis about what I learned before I speak to Ard Caddach."},
		[22] = 
			{appendStepText="In western Markarth's Understone Keep, ", stepTextKey="I should tell Ard Caddach about all that I discovered. Hopefully, we'll find out where he stands on the coming conflict with the Gray Host."},
		["Talk to Ard Caddach 2"] =
			{appendText=" sitting on his throne.", stepTextKey="I should tell Ard Caddach about all that I discovered. Hopefully, we'll find out where he stands on the coming conflict with the Gray Host."},
		[23] = 
			{appendStepText="Near the Ard's throne in Markarth's Understone Keep, ", stepTextKey="I should talk to Count Verandis Ravenwatch and let him know Ard Caddach's response."},
		["Talk to Count Verandis Ravenwatch 5"] =
			{appendText=".", stepTextKey="I should talk to Count Verandis Ravenwatch and let him know Ard Caddach's response."},
	},


	[GetQuestName(6551)] = { --"Blood of the Reach" --Jordakai
		[1] = 
			{appendStepText="Gwendis said ", stepTextKey="I need to return to Understone Keep in Markarth and talk to Verandis."},
		["Talk to Count Verandis Ravenwatch"] =
			{appendText=" near Ard Caddach's throne at the keep up in the west city."},
		[2] = 
			{appendStepText="In Markarth, ", stepTextKey="Verandis suggested that a local scrap dealer named Nolovan might be able to help us get a lead on the Arkthzand Keystone. While I find him in the southeast section of the city, Verandis plans to meet with Arana and the rebels."},
		["Go to Nolovan's Scrap House"] =
			{appendText=" in the city's southeast. It is tucked away east of the Guild Traders and northeast of the wayshrine. Just before entering the trader area are stairs to the east that lead up to its door."},
		[3] = 
			{appendStepText="East of the Guild Traders in southeastern Markarth, I found the place Verandis mentioned. ", stepTextKey="Now that I'm inside Nolovan's Scrap House, I should ask the proprietor about the Arkthzand Keystone."},
		["Talk to Nolovan"] =
			{appendText="."},
		[4] = 
			{appendStepText="East of the Guild Traders in southeastern Markarth, I met Nolovan in his house. ", stepTextKey="Nolovan thinks I may be able to find the Arkthzand Keystone in the ruins of Bthar-Zel. He has a map, but I need to buy it or complete a simple job for him to obtain it."},
		["Obtain the Map"] =
			{appendText=". If I choose to help him in return for the map, he has a package in a backpack he needs retrieved from the Abandoned House in the village southeast of the city, south across the first bridge."},
		[5] = 
			{appendStepText="At his house in southeastern Markarth, ", stepTextKey="Nolovan provided me with a map that may lead us to the keystone. Now I should exit the scrap house and find Verandis."},
		["Exit Nolovan's Scrap House"] =
			{appendText="."},
		[6] = 
			{appendStepText="", stepTextKey="As I was leaving the scrap house, Gwendis of the Ravenwatch showed up. I should talk to her."},
		["Talk to Gwendis"] =
			{appendText=" at Nolovan's Scrap House in southeastern Markarth."},
		[7] = 
			{appendStepText="At the scrap dealer's house in Markarth, ", stepTextKey="Gwendis told me that Verandis made contact with Arana's rebels. She wants me to join him at the Reachfolk's main encampment, Rebel's Retreat."},
		["Go to Rebel's Retreat"] =
			{appendText=". It is in the mountains far to the east of the city, on the eastern branch of the river. Trails lead up to it from the northeastern road and from the long southeastern road."},
		[8] = 
			{appendStepText="In the mountains far east of Markarth and northeast of its wayshrine, ", stepTextKey="I arrived at Rebel's Retreat. Verandis wants me to talk to Arana. I should speak to her."},
		["Talk to Arana 1"] =
			{appendText=" at the old Nord ruin.", stepTextKey="I arrived at Rebel's Retreat. Verandis wants me to talk to Arana. I should speak to her."},
		[9] = 
			{appendStepText="At Rebel's Retreat, an old Nord ruin in the eastern mountains, ", stepTextKey="Arana intends to conduct a ritual to seek the blessing of Hircine for our alliance. I need to gather the components she needs for the ritual—a briarheart seed, a hagraven's eye, and bright river-shale."},
		["Gather Ritual Components"] =
			{appendText=" \n\nA thorny Briarheart sapling grows near the fire at the Cinder-Heart Clan Camp to the south.\nA hagraven coven lives to the east, northwest of a ritual site, and northeast of the Cinder-Heart camp.\nBright river-shale can be found northwest of the rebel camp, on the ground near a tree at the tip of the river island, across from a fisherman's spot, where the eastern branch of the river flows back into the main current."},
		[10] = 
			{appendStepText="Around the mountainous eastern region, ", stepTextKey="I gathered the ritual components as Arana requested. I should return to Rebel's Retreat and deliver them to her."},
		["Talk to Arana 2"] =
			{appendText=" at the campfire northeast of the old Nord ruin.", stepTextKey="I gathered the ritual components as Arana requested. I should return to Rebel's Retreat and deliver them to her."},
		[11] = 
			{appendStepText="At the campfire northeast of the old ruin at Rebel's Retreat, ", stepTextKey="I should place the components into the fire to begin Arana's ritual."},
		["Begin the Ritual"] =
			{appendText=" by placing the Briarheart Seed, the Bright River-Shale, and the Hagraven Eye into the flames."},
		[12] = 
			{appendStepText="At the campfire northeast of the Nord ruin at Rebel's Retreat, ", stepTextKey="I should stand back as Arana performs the ritual."},
		["Observe the Ritual"] =
			{appendText="."},
		[13] = 
			{appendStepText="At the campfire northeast of the Nord ruin at Rebel's Retreat, ", stepTextKey="Arana performed the ritual, binding the Ravenwatch and her rebels together in the battle against the Gray Host. I should speak with her about what comes next."},
		["Talk to Arana 3"] =
			{appendText=" after speaking with Verandis.", stepTextKey="Arana performed the ritual, binding the Ravenwatch and her rebels together in the battle against the Gray Host. I should speak with her about what comes next."},
		[14] = 
			{appendStepText="", stepTextKey="The map I acquired in Markarth indicates that three locations hold the secret to finding the entrance to Bthar-Zel. Arana and I should go to these locations and look for clues."},
		["Investigate Map Locations"] =
			{appendText=" \n\nI should use the Bthar-Zel Map I received from Nolovan.\nAll three sites are along a footpath to the north of the North Markath Wayshrine. Arana will meet me at each Dwemer site where we can talk about what we find."},
		[15] = 
			{appendStepText="North of North Markarth Wayshrine, we used Nolovan's map and found three plaques: Thief, Mage, and Warrior. The Reachfolk call them the Hunter, Witch, and Headsman. ", stepTextKey="I think Arana may have figured out how to interpret the map. I should talk to her."},
		["Talk to Arana 4"] =
			{appendText=".", stepTextKey="I think Arana may have figured out how to interpret the map. I should talk to her."},
		[16] = 
			{appendStepText="After we found the three Guardian star tales along the footpath north of the North Markarth Wayshrine, ", stepTextKey="Arana told me where to find the entrance to Bthar-Zel. I should make my way to the hidden entrance."},
		["Find the Entrance to Bthar-Zel"] =
			{appendText=". Arana determined that the missing location is at the far north end of the footpath. Adding it would make the marks on the map reflect the star tale, the constellation, of the Snake."},
		[17] = 
			{appendStepText="We found Deep Folk Crossing in the far north and crossed its bridge. ", stepTextKey="We located the entrance to Bthar-Zel, but it appears to be locked behind some sort of elaborate lock. I must solve this puzzle to enter the Dwarven ruin."},
		["Open the Door to Bthar-Zel"] =
			{appendText=". The puzzle has three cubes. On our journey we found three plaques: the Witch, the Hunter, and the Headsman.\n\nVerandis and Gwendis have joined us."},
		[18] = 
			{appendStepText="In the far north near Deep Folk Crossing, ", stepTextKey="Arana and I must enter Bthar-Zel to look for the Arkthzand Keystone while Verandis and Gwendis search another section of the ruin."},
		["Enter Bthar-Zel"] =
			{appendText=". I should speak with Verandis before we enter."},
		[19] = 
			{appendStepText="We found the mysterious site in the region's far north, beyond Deep Folk Crossing. ", stepTextKey="We entered the Dwarven ruin of Bthar-Zel. Verandis and Gwendis went off to search on their own. Now Arana and I need to see if these ruins really contain the Arkthzand Keystone."},
		["Search for the Arkthzand Keystone 1"] =
			{appendText=" in its chamber. It is likely one or two levels below the main level of the ruin. There may be an entrance in the far south-central, circular chamber. I should start there and search unitl I find the keystone's chamber.", stepTextKey="We entered the Dwarven ruin of Bthar-Zel. Verandis and Gwendis went off to search on their own. Now Arana and I need to see if these ruins really contain the Arkthzand Keystone."},
		[20] = 
			{appendStepText="We found the mysterious site in the region's far north, beyond Deep Folk Crossing. From its main level, we took a lift down from its south-central circular chamber, then went through the vaults to another lift to the keystone's chamber, ", stepTextKey="I should continue my search for the Arkthzand Keystone in Bthar-Zel."},
		["Search for the Arkthzand Keystone 2"] =
			{appendText=". I should see what I can from the balcony east of the vault's lift where we entered.", stepTextKey="I should continue my search for the Arkthzand Keystone in Bthar-Zel."},
		[21] = 
			{appendStepText="We found the mysterious site in the region's far north, beyond Deep Folk Crossing. From its main level, we took a lift down from its south-central circular chamber, then went through the vaults to another lift to the keystone's chamber. ", stepTextKey="Verandis and Gwendis encountered Rada al-Saran and Lady Belain. Unfortunately, I'm too far away to intervene. I should watch to see what happens."},
		["Observe the Encounter"] =
			{appendText="."},
		[22] = 
			{appendStepText="We found the mysterious site in the region's far north, beyond Deep Folk Crossing. From its main level, we took a lift down from its south-central circular chamber, then went through the vaults to another lift to the keystone's chamber. ", stepTextKey="Rada al-Saran and Lady Belain snatched the keystone away from Verandis and Gwendis, which triggered some sort of alarm. Now I must fight an enormous Dwarven automaton to escape Bthar-Zel."},
		["Defeat the Dwarven Dynastor"] =
			{appendText=" in the Keystone Chamber."},
		[23] = 
			{appendStepText="We found the mysterious site in the region's far north, beyond Deep Folk Crossing. From its main level, we took a lift down from its south-central circular chamber, then went through the vaults to another lift to the keystone's chamber. I defeated the automaton. ", stepTextKey="There's nothing more to accomplish here. Arana and I should make our way out of the ruins of Bthar-Zel."},
		["Exit Bthar-Zel"] =
			{appendText=". There is another lift south of the large Keystone Chamber. It will take us to Arkthzand Cavern in Blackreach."},
		[24] = 
			{appendStepText="", stepTextKey="We exited Bthar-Zel, but Lady Belain wound up with the Arkthzand Keystone. I should talk to Arana and see what she thinks we should do now."},
		["Talk to Arana 5"] =
			{appendText=" by the Bthar-Zel site in the Arkthzand Cavern's northern area in Blackreach, northeast of the Arkthzand Wayshrine.", stepTextKey="We exited Bthar-Zel, but Lady Belain wound up with the Arkthzand Keystone. I should talk to Arana and see what she thinks we should do now."},
		[25] = 
			{appendStepText="", stepTextKey="Arana is returning to prepare her rebels for war. I should find Verandis and determine what we should do next."},
		["Find Count Verandis Ravenwatch"] =
			{appendText=" on the Dwemer balcony above the Arkthzand Wayshrine in the northwestern area of Blackreach's cavern."},
	},

	[GetQuestName(6547)] = { --"The Study of Souls" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Verandis wishes to speak with me outside the Bthar-Zel ruins in Blackreach. He believes he knows where Lady Belain and Rada al-Saran took the Arkthzand Keystone."},
		["Talk to Count Verandis Ravenwatch 1"] =
			{appendText=" up on the Dwemer balcony of Bthar-Zel, north of the Arkthzand Wayshrine in Arkthzand Cavern of Blackreach.", stepTextKey="Verandis wishes to speak with me outside the Bthar-Zel ruins in Blackreach. He believes he knows where Lady Belain and Rada al-Saran took the Arkthzand Keystone."},
		[2] = 
			{appendStepText="On a balcony above the Arkthzand Wayshrine in Blackreach, I spoke with Count Ravenwatch. ", stepTextKey="I should meet Verandis at the sprawling Dwarven ruin across the river from the exit out of Bthar-Zel."},
		["Go to the Dwarven Ruin"] =
			{appendText=" in western Arkthzand Cavern. I should meet Verandis in front of the main building within the curved walls."},
		[3] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, ", stepTextKey="I found Verandis at the Dwarven ruin. I should speak to him."},
		["Talk to Count Verandis Ravenwatch 2"] =
			{appendText=" on the front steps of the main building at the western ruins.", stepTextKey="I found Verandis at the Dwarven ruin. I should speak to him."},
		[4] = 
			{appendStepText="I met Verandis at the western ruin in Arkthzand Cavern of Blackreach. ", stepTextKey="The main door leading into the Dwarven ruin is locked. I should around the building and see if I can find another entrance nearby."},
		["Search for an Entrance"] =
			{appendText=". There should be a side entrance to the building and perhaps a clue on how to enter it. I should check the south side first."},
		[5] = 
			{appendStepText="I found a note describing a method to enter the building while checking a southern side entrance of the Library of Arkthzand in Blackreach. ", stepTextKey="Verandis wants to know what I learned from the note I found. I should talk to him and let him know."},
		["Talk to Count Verandis Ravenwatch 3"] =
			{appendText=" at the blocked, southern entrance to the Library.", stepTextKey="Verandis wants to know what I learned from the note I found. I should talk to him and let him know."},
		[6] = 
			{appendStepText="At the western ruin in Blackreach's Arkthzand Cavern, ", stepTextKey="Verandis wants to explore the other side of the structure. I should head to the north side of the library and look around."},
		["Investigate the Ruins"] =
			{appendText=" of the Library of Arkthzand. I should search the circle of shelves near the wall, between the northern gateway and the northeastern gateway of the curved wall."},
		[7] = 
			{appendStepText="At the western ruin in Arkthzand Cavern of Blackreach, in a circular space near the wall north of the main Library of Arkthzand, ", stepTextKey="I found more of the Gray Host pentarch's research and an eerie black shard. I should discuss these items with Verandis."},
		["Talk to Count Verandis Ravenwatch 4"] =
			{appendText=".", stepTextKey="I found more of the Gray Host pentarch's research and an eerie black shard. I should discuss these items with Verandis."},
		[8] = 
			{appendStepText="In the courtyard of the Library of Arkthzand in Blackreach's cavern, ", stepTextKey="I should be able to use the strange shard we found to propel us through the void portals. With any luck, we can use them to find a way into the Library of Arkthzand."},
		["Navigate the Void Portals"] =
			{appendText=" around the Library to find a way inside."},
		[9] = 
			{appendStepText="In the Library's courtyard in Blackreach's Arkthzand Cavern, we noticed a void portal above a terrace at the western wall, north of the main building. ", stepTextKey="We used the shard to navigate the void portals to the upper terraces of the library. Now to see if the door on this level can be opened so we can get inside."},
		["Enter the Library of Arkthzand"] =
			{appendText="."},
		[10] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance. ", stepTextKey="We made it inside the Library of Arkthzand. I should ask Verandis if he has any ideas on how we locate Rada al-Saran and Lady Belain."},
		["Talk to Count Verandis Ravenwatch 5"] =
			{appendText=" inside the main hall of the library.", stepTextKey="We made it inside the Library of Arkthzand. I should ask Verandis if he has any ideas on how we locate Rada al-Saran and Lady Belain."},
		[11] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance. ", stepTextKey="Verandis suggests we explore deeper into the library to search for Rada al-Saran, Lady Belain, and the source of the dark energy that seems to be powering the void portals."},
		["Explore the Library of Arkthzand"] =
			{appendText=". From the library proper, we need to reach the southwestern chamber of the Halls of Arkthzand. I should use the void shard and the void portals as needed."},
		[12] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance into the Library of Arkthzand. ", stepTextKey="Our progress through the library has led us to a dead end, but Verandis spotted a door higher up in the vast chamber. I need to find a way to reach it."},
		["Reach the Door on the Upper Level"] =
			{appendText=". I should speak with Count Verandis."},
		[13] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance into the Library of Arkthzand. ", stepTextKey="I used the void portals to reach the door on the upper level of the chamber. Now we should enter it and continue our hunt for Rada al-Saran and Lady Belain."},
		["Enter the Door on the Upper Level"] =
			{appendText=" of the southwestern chamber of the Halls of Arkthzand and head east."},
		[14] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance into the Library of Arkthzand. We have entered the south-central chamber in the Halls of Arkthzand. ", stepTextKey="This area seems to be some sort of containment chamber. A shade is imprisoned within a strange apparatus at the center. I should take a closer look."},
		["Investigate the Chamber"] =
			{appendText=". There appears to be a note near the western crystal."},
		[15] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance into the Library of Arkthzand. We traveled through the Halls. ", stepTextKey="I found another note from the Gray Host pentarch. Apparently, he discovered that the apparatus still functions and it can be manipulated by rotating the large void crystals set within the pedestals. I should let Verandis know what I found."},
		["Talk to Count Verandis Ravenwatch 6"] =
			{appendText=" near the western crystal in the south-central Containment Chamber.", stepTextKey="I found another note from the Gray Host pentarch. Apparently, he discovered that the apparatus still functions and it can be manipulated by rotating the large void crystals set within the pedestals. I should let Verandis know what I found."},
		[16] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance into the Library of Arkthzand. Within the south-central Containment Chamber of the Halls of Arkthzand, ", stepTextKey="Verandis wants to free the shade that used to be a Gray Host pentarch so we can question him. To do that, I need to rotate the void crystals and realign the dark energy flowing through the apparatus."},
		["Realign the Containment Apparatus"] =
			{appendText=" by rotating the crystals. I can refer to the pentarch's note I have, if needed. I should use the void shard to reach the upper platforms."},
		[17] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance into the Library of Arkthzand. Within the south-central Containment Chamber of the Halls of Arkthzand, ", stepTextKey="I set the tortured shade free. Verandis wants me to question the creature."},
		["Talk to the Shade"] =
			{appendText=" down in the center of the chamber."},
		[18] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance into the Library of Arkthzand. Within the south-central Containment Chamber of the Halls, I questioned the shade. "},
		["Talk to Count Verandis Ravenwatch 7"] =
			{appendText=" down in the center of the chamber.", stepTextKey="The shade spoke in riddles. I should discuss what the tormented creature told me with Verandis."},
		[19] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance into the Library of Arkthzand. We have passed through some chambers. ", stepTextKey="We need to continue our pursuit of Rada al-Saran and Lady Belain. Verandis wants to find them before they reach this so-called Dark Heart."},
		["Find Rada al-Saran and Lady Belain"] =
			{appendText=". We should head to the southeastern chamber of the Halls of Arkthzand, then use a lift to enter the Observation Deck."},
		[20] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance into the Library of Arkthzand. We traveled around to reach the southeastern chamber. There, we took a lift to the Observation Deck. ", stepTextKey="We located Rada al-Saran and Lady Belain. They're in the chamber below us. I should listen in on their conversation."},
		["Eavesdrop on the Conversation"] =
			{appendText="."},
		[21] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, we used a void shard and the void portals to find an entrance into the Library of Arkthzand. We traveled around to reach the southeastern chamber. There, we took a lift to the Observation Deck. ", stepTextKey="I should talk to Verandis and discuss what we just heard in the exchange between Rada al-Saran and Lady Belain."},
		["Talk to Count Verandis Ravenwatch 8"] =
			{appendText=".", stepTextKey="I should talk to Verandis and discuss what we just heard in the exchange between Rada al-Saran and Lady Belain."},
		[22] = 
			{appendStepText="", stepTextKey="According to Lady Belain, a Reach witch prophecy is somehow involved in their plan to awaken the Dark Heart. Verandis wants me to return to Rebel's Retreat and see what Arana can tell us about the topic."},
		["Return to Rebel's Retreat"] =
			{appendText=" in the eastern mountains of The Reach.\n\nI can leave the Observation Deck through the northern door. Then from the Library of Arkthzand, I can use the Dwemer Lift to the north to get to the surface, or a wayshrine."},
		[23] = 
			{appendStepText="In the eastern mountains, ", stepTextKey="I arrived back at Rebel's Retreat. I should talk to Arana about what happened at the Library of Arkthzand and what we learned there."},
		["Talk to Arana"] =
			{appendText=" on a wooden platform at the old Nord ruin."},
	},

	[GetQuestName(6548)] = { --"The Awakening Darkness" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Arana wants to talk to me at Rebel's Retreat. She may have information concerning the dark prophecy that Lady Belain talked about at the Library of Arkthzand."},
		["Talk to Arana 1"] =
			{appendText=" at the old Nord ruin in the eastern mountains.", stepTextKey="Arana wants to talk to me at Rebel's Retreat. She may have information concerning the dark prophecy that Lady Belain talked about at the Library of Arkthzand."},
		[2] = 
			{appendStepText="", stepTextKey="Arana suggests meeting with Bradan, a werewolf from her estranged clan, at a place called Hroldan Ring. I should find the meeting spot and see if Bradan can get us a meeting with Nathari."},
		["Find Bradan at Hroldan Ring"] =
			{appendText=". Its stone arches are across the river, north of the crossing roads, southeast of Rebel's Retreat and the Cinder-Heart camp, and northwest of a bridge."},
		[3] = 
			{appendStepText="In the region's east, ", stepTextKey="I found Bradan at Hroldan Ring. I should speak with him about the Ghostsong clan witches."},
		["Talk to Bradan 1"] =
			{appendText=".", stepTextKey="I found Bradan at Hroldan Ring. I should speak with him about the Ghostsong clan witches."},
		[4] = 
			{appendStepText="", stepTextKey="We learned from Bradan that Nathari led the Ghostsong clan to Lost Valley Redoubt, where she promised them some grand revelation. Arana wants to talk to her sister, so we need to go to Lost Valley."},
		["Go to Lost Valley Redoubt"] =
			{appendText=" at the ruins up in the far southeastern mountains."},
		[5] = 
			{appendStepText="", stepTextKey="I met Arana at the path leading into Lost Valley. She found a Gray Host scout who she thinks Bradan dealt with on his way inside. I should talk to her."},
		["Talk to Arana 2"] =
			{appendText=" at the entrance to Lost Valley Redoubt.", stepTextKey="I met Arana at the path leading into Lost Valley. She found a Gray Host scout who she thinks Bradan dealt with on his way inside. I should talk to her."},
		[6] = 
			{appendStepText="I arrived at the Lost Valley Redoubt in the southeastern mountains. ", stepTextKey="The redoubt appears to be overrun with Gray Host troops. We need to reach the entrance to the ancient barrow and try to find the Ghostsong clan."},
		["Search Lost Valley Redoubt"] =
			{appendText=". I should look for clues in the upper eastern area with a double-arched entry topped with two braziers and a pine tree."},
		[7] = 
			{appendStepText="At Lost Valley Redoubt in the far southeastern mountains, in an upper eastern area with a large double-arched entry, ", stepTextKey="Arana wants to know what the letter I found in the Gray Host camp has to say. I should talk to her and let her know that it appears Nathari is working with Lady Belain for some reason related to the dark prophecy."},
		["Talk to Arana 3"] =
			{appendText=".", stepTextKey="Arana wants to know what the letter I found in the Gray Host camp has to say. I should talk to her and let her know that it appears Nathari is working with Lady Belain for some reason related to the dark prophecy."},
		[8] = 
			{appendStepText="", stepTextKey="Lady Belain wants Nathari and the Ghostsongs to awaken the Dark Heart of their prophecy. Arana needs to get inside the Lost Valley barrow to stop Nathari from doing something terrible. We need to make our way to the barrow entrance."},
		["Find the Barrow"] =
			{appendText=" up from the eastern area with the double-arched entry and then west, in the uppermost area of the redoubt. Halfway across an ancient bridge, the entrance lies in the southernmost circular ruin."},
		[9] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, ", stepTextKey="I reached the Nord barrow above Lost Valley Redoubt. Arana says the entrance is somewhere nearby. I should search for it."},
		["Find the Barrow Entrance"] =
			{appendText="."},
		[10] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, ", stepTextKey="Arana opened the concealed door that leads into the ancient Nord barrow. Nathari and the Ghostsong clan should be down in the caves below the barrow. I should go inside and look for them."},
		["Search the Barrow"] =
			{appendText=", starting with the northeastern chamber's western alcove."},
		[11] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow and discovered a Ghostsong hunter dead on an altar. ", stepTextKey="We need to find Nathari before she sacrifices any more of the Ghostsong clan members."},
		["Find Nathari 1"] =
			{appendText=", deeper into the barrow.", stepTextKey="We need to find Nathari before she sacrifices any more of the Ghostsong clan members."},
		[12] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow and made our way to the central Chamber of the Dead. ", stepTextKey="We found Arana's sister, the witch Nathari, but she's already sacrificed members of the Ghostsong clan. While Arana sees to the dead, I should talk to Nathari."},
		["Talk to Nathari"] =
			{appendText="."},
		[13] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow and made our way to the central chamber. ", stepTextKey="Nathari told me that there are more Ghostsong clan members below, ready to be sacrificed to awaken the Dark Heart. I should talk to Arana."},
		["Talk to Arana 4"] =
			{appendText=" in the Chamber of the Dead.", stepTextKey="Nathari told me that there are more Ghostsong clan members below, ready to be sacrificed to awaken the Dark Heart. I should talk to Arana."},
		[14] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow and made our way to the central Chamber of the Dead. ", stepTextKey="Nathari is somewhere in the lower barrow, ready to sacrifice the rest of the Ghostsong clan to awaken the Dark Heart. I need to find her and try to put a stop to this."},
		["Search the Lower Barrow"] =
			{appendText=". I should check the three alcoves along the passages."},
		[15] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow and made our way to the central Chamber of the Dead. Then we entered the passages of the Lower Barrow. ", stepTextKey="We found another sacrificed member of the Ghostsong clan. There's a note beside this one. I should examine it."},
		["Examine the Note"] =
			{appendText=" beside the sacrificed Ghostsong clan member."},
		[16] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow and made our way to the central Chamber of the Dead. Then we entered the passages of the Lower Barrow. ", stepTextKey="The note next to the Ghostsong clan hunter contains the final words of Senan. He died fighting instead of allowing himself to be sacrificed. I should inform Arana."},
		["Talk to Arana 5"] =
			{appendText=".", stepTextKey="The note next to the Ghostsong clan hunter contains the final words of Senan. He died fighting instead of allowing himself to be sacrificed. I should inform Arana."},
		[17] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow, then made our way through the passages of the Lower Barrow. ", stepTextKey="We need to reach a ritual cavern called the Dark Descent and stop Nathari before she can sacrifice the rest of the Ghostsong clan."},
		["Enter the Dark Descent"] =
			{appendText=" down the barrow's southernmost stairs."},
		[18] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow, then made our way through the passages of the Lower Barrow, and down the southernmost stairs. ", stepTextKey="We entered the section of the lower barrow known as the Dark Descent. Now to find Nathari and stop her before she sacrifices the rest of the Ghostsong clan."},
		["Find Nathari 2"] =
			{appendText=" in the Dark Descent.", stepTextKey="We entered the section of the lower barrow known as the Dark Descent. Now to find Nathari and stop her before she sacrifices the rest of the Ghostsong clan."},
		[19] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow, then made our way through the passages of the Lower Barrow, and down the southernmost stairs. ", stepTextKey="Nathari retreated deeper into the caverns to continue her sacrifice of the Ghostsong clan and wake the Dark Heart. I should go after her."},
		["Pursue Nathari"] =
			{appendText=" farther into the Dark Descent, to the Ritual Cavern."},
		[20] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow, then made our way through the passages of the Lower Barrow, and down to the Dark Descent. ", stepTextKey="Arana and I have found a large pit at the bottom of the Dark Descent. Nathari has gathered her clan here. I should look for an opportunity to confront Nathari."},
		["Reach the Ritual Site"] =
			{appendText="."},
		[21] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow, then made our way through the passages of the Lower Barrow, and down to the Dark Descent and into the ritual site. ", stepTextKey="We must confront Nathari to stop her from awakening the Dark Heart. I should help Arana stop the ritual."},
		["Stop the Ritual"] =
			{appendText="."},
		[22] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow, then made our way through the passages of the Lower Barrow, and down to the Dark Descent and into the ritual site. ", stepTextKey="We defeated Nathari and stopped the Dark Heart from fully awakening. Now we need to find Bradan and any other Ghostsong clan survivors."},
		["Find Bradan"] =
			{appendText=" at the south wall of the ritual site."},
		[23] = 
			{appendStepText="In the far southeastern mountains, in the uppermost southern area halfway across a bridge, we entered the Lost Valley Barrow, then made our way through the passages of the Lower Barrow, and down to the Dark Descent and into the ritual site. ", stepTextKey="Arana and I found Bradan imprisoned with several other Ghostsong clan hunters. I should talk to him."},
		["Talk to Bradan 2"] =
			{appendText=".", stepTextKey="Arana and I found Bradan imprisoned with several other Ghostsong clan hunters. I should talk to him."},
		[24] = 
			{appendStepText="", stepTextKey="Bradan and the remaining Ghostsong clan hunters have agreed to join Arana's fight against Lady Belain and the Gray Host. I should meet them back at Rebel's Retreat to plan our next move."},
		["Return to Rebel's Retreat"] =
			{appendText=" in the eastern mountains of The Reach."},
		[25] = 
			{appendStepText="At the Lost Valley Redoubt, in the barrow's deepest cavern, we stopped the ritual. ", stepTextKey="We defeated Nathari and rescued Bradan and the surviving members of the Ghostsong clan. I should talk to Arana and determine our next course of action."},
		["Talk to Arana 6"] =
			{appendText=" at the old Nord ruin of Rebel's Retreat in the eastern mountains.", stepTextKey="We defeated Nathari and rescued Bradan and the surviving members of the Ghostsong clan. I should talk to Arana and determine our next course of action."},
	},

	[GetQuestName(6554)] = { --"The Dark Heart" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Gwendis asked me to meet Verandis at Nighthollow Keep, an ancient vampire fortress in Blackreach. The Dark Heart may be hidden somewhere inside."},
		["Go to Nighthollow Keep"] =
			{appendText=". An ancient, dark castle, it rises above the eastern lakes in Arkthzand Cavern.\n\nCount Ravenwatch is likely up on an overlook, west of the estate's western bridge, and northeast of its wayshrine."},
		[2] = 
			{appendStepText="Up on an overlook, partway along a brazier-lit trail, west of the estate's western bridge and northeast of its wayshrine, ", stepTextKey="I met Verandis on the way to Nighthollow Keep. I should talk to him."},
		["Talk to Count Verandis Ravenwatch 1"] =
			{appendText=" as he surveys the castle on the eastern lakes of Arkthzand Cavern. Gwendis is nearby, too.", stepTextKey="I met Verandis on the way to Nighthollow Keep. I should talk to him."},
		[3] = 
			{appendStepText="", stepTextKey="As we search Nighthollow Keep, Verandis wants me to look for personal objects that he can use his auramancy on to get impressions of what happened here and how it relates to the Dark Heart."},
		["Explore Nighthollow Keep 1"] =
			{appendText=", the ancient fortress at the eastern lake area of Arkthzand Cavern.", stepTextKey="As we search Nighthollow Keep, Verandis wants me to look for personal objects that he can use his auramancy on to get impressions of what happened here and how it relates to the Dark Heart."},
		[4] = 
			{appendStepText="In Nighthollow Keep at the eastern lakes of Arkthzand Cavern, ", stepTextKey="I wandered into an old study in Nighthollow Keep. I should search it for something Verandis can use to attempt to draw a memory from."},
		["Search the Nighthollow Study"] =
			{appendText=" for a personal item from the far past."},
		[5] = 
			{appendStepText="At the ancient keep in the Arkthzand Cavern of Blackreach, ", stepTextKey="I found a damaged insignia of some sort in the keep's study. I should ask Verandis whether this is a suitable target for his auramancy."},
		["Talk to Count Verandis Ravenwatch 2"] =
			{appendText=" in the Nighthollow Study.", stepTextKey="I found a damaged insignia of some sort in the keep's study. I should ask Verandis whether this is a suitable target for his auramancy."},
		[6] = 
			{appendStepText="In the Nighthollow Study within the ancient keep in the Arkthzand Cavern of Blackreach, ", stepTextKey="Verandis thinks he can coax a memory from the emotional aura clinging to this insignia. I should observe anything that appears."},
		["Observe the Auramancy Magic 1"] =
			{appendText=".", stepTextKey="Verandis thinks he can coax a memory from the emotional aura clinging to this insignia. I should observe anything that appears."},
		[7] = 
			{appendStepText="At the ancient keep in the Arkthzand Cavern of Blackreach, Verandis was able to show a vision. ", stepTextKey="The memory conjured from the insignia showed Lady Belain and another Nighthollow vampire talking about drinking from the Dark Heart. I should see what Verandis thinks of this revelation."},
		["Talk to Count Verandis Ravenwatch 3"] =
			{appendText=" in the Nighthollow Study.", stepTextKey="The memory conjured from the insignia showed Lady Belain and another Nighthollow vampire talking about drinking from the Dark Heart. I should see what Verandis thinks of this revelation."},
		[8] = 
			{appendStepText="At the ancient keep in the Arkthzand Cavern of Blackreach, ", stepTextKey="Verandis wants me to continue to explore. While the magic he cast on the damaged insignia might reveal more memories, he wants me to find an undamaged one. He also suggested the place may contain void portals that will help me navigate the keep."},
		["Explore Nighthollow Keep 2"] =
			{appendText=" further.", stepTextKey="Verandis wants me to continue to explore. While the magic he cast on the damaged insignia might reveal more memories, he wants me to find an undamaged one. He also suggested the place may contain void portals that will help me navigate the keep."},
		[9] = 
			{appendStepText="At the ancient keep in the Arkthzand Cavern of Blackreach, ", stepTextKey="I found a relatively undamaged portion of the keep. It looks like a noble's personal chamber. I should search the area for objects that Verandis can cast his auramancy upon."},
		["Explore the Nighthollow Suite"] =
			{appendText=", the southeastern chamber in the keep."},
		[10] = 
			{appendStepText="In the Nighthollow Suite, the southeastern chamber of the ancient keep in the Arkthzand Cavern of Blackreach, ", stepTextKey="I found an undamaged insignia in the Nighthollow suite. I should ask Verandis to try his auramancy magic on this new insignia."},
		["Talk to Count Verandis Ravenwatch 4"] =
			{appendText=" about the Dark Insignia I found in the Suite.", stepTextKey="I found an undamaged insignia in the Nighthollow suite. I should ask Verandis to try his auramancy magic on this new insignia."},
		[11] = 
			{appendStepText="In the southeastern chamber of the ancient keep in the Arkthzand Cavern of Blackreach, ", stepTextKey="I should watch and see what memory Verandis can draw from the insignia with his auramancy magic."},
		["Observe the Auramancy Magic 2"] =
			{appendText=" in the Nighthollow Suite.", stepTextKey="I should watch and see what memory Verandis can draw from the insignia with his auramancy magic."},
		[12] = 
			{appendStepText="In the southeastern chamber of the ancient keep in the Arkthzand Cavern of Blackreach, ", stepTextKey="I observed another Nighthollow memory conjured by Verandis's aurumancy. I should talk to Verandis about this latest memory."},
		["Talk to Count Verandis Ravenwatch 5"] =
			{appendText=" in the Nighthollow Suite.", stepTextKey="I observed another Nighthollow memory conjured by Verandis's aurumancy. I should talk to Verandis about this latest memory."},
		[13] = 
			{appendStepText="In the southeastern chamber of the ancient keep in the Arkthzand Cavern of Blackreach, ", stepTextKey="Verandis and I learned that the Nighthollow vampires accessed the Dark Heart through a passage they called the Dark Halls. I should continue to explore the keep in search of this passage."},
		["Find the Path to the Dark Heart"] =
			{appendText=" through the eastern halls north of the suite and the Grand Chamber of the Nighthollow to the Black Diamond chamber."},
		[14] = 
			{appendStepText="We traveled through the halls of the ancient keep in the Arkthzand Cavern of Blackreach. From the southeastern chamber, the Suite, we headed north and entered the Grand Chamber, and then the Black Diamond Chamber. ", stepTextKey="Verandis and I have found the passage to the Dark Halls, but the way is blocked by powerful magic. Verandis wants to try to draw a memory from this location with his auramancy. I should watch and see what happens."},
		["Observe the Auramancy Magic 3"] =
			{appendText=".", stepTextKey="Verandis and I have found the passage to the Dark Halls, but the way is blocked by powerful magic. Verandis wants to try to draw a memory from this location with his auramancy. I should watch and see what happens."},
		[15] = 
			{appendStepText="We traveled through the halls of the ancient keep in the Arkthzand Cavern of Blackreach. From the southeastern chamber, the Suite, we headed north and found the Grand Chamber, and then the Black Diamond Chamber. ", stepTextKey="At the entrance to the Dark Halls Verandis conjured an old memory of Rada al-Saran and Lady Belain discussing the Dark Heart. I should talk to Verandis about this latest memory."},
		["Talk to Count Verandis Ravenwatch 6"] =
			{appendText=" on the dais near the warded entry.", stepTextKey="At the entrance to the Dark Halls Verandis conjured an old memory of Rada al-Saran and Lady Belain discussing the Dark Heart. I should talk to Verandis about this latest memory."},
		[16] = 
			{appendStepText="We traveled through the halls of the ancient keep in the Arkthzand Cavern of Blackreach. From the southeastern chamber, the Suite, we headed north and entered the Grand Chamber, and then the Black Diamond Chamber. Now, ", stepTextKey="Verandis wants me to use the intact insignia and see if it opens the way to the Dark Halls."},
		["Dispel the Ward 1"] =
			{appendText=" using the Dark Insignia I have.", stepTextKey="Verandis wants me to use the intact insignia and see if it opens the way to the Dark Halls."},
		[17] = 
			{appendStepText="We traveled through the halls of the ancient keep in the Arkthzand Cavern of Blackreach. From the southeastern chamber, the Suite, we headed north and found the Grand Chamber, and then the Black Diamond Chamber. ", stepTextKey="The way is open. Now to explore the Dark Halls and see if we can find the Dark Heart."},
		["Explore the Dark Halls"] =
			{appendText="."},
		[18] = 
			{appendStepText="We traveled through the halls of the keep in the Arkthzand Cavern of Blackreach. From the southeastern chamber, the Suite, we entered the Grand Chamber and then the Black Diamond Chamber. ", stepTextKey="Verandis and I found a small shrine deep in the Dark Halls. The personal items left here seem to be good candidates for his auramancy. I should watch whatever memory Verandis is able to reveal."},
		["Observe the Auramancy Magic 4"] =
			{appendText=".", stepTextKey="Verandis and I found a small shrine deep in the Dark Halls. The personal items left here seem to be good candidates for his auramancy. I should watch whatever memory Verandis is able to reveal."},
		[19] = 
			{appendStepText="We traveled through the halls of the keep in the Arkthzand Cavern of Blackreach. From the southeastern chamber, the Suite, we entered the Grand Chamber and then the Black Diamond Chamber. In the northwestern end of the Dark Halls caverns, we found an altar. ", stepTextKey="It appears that when the Dark Heart began to slow many centuries ago, Lady Belain took the last of the power for herself. I should talk to Verandis about this."},
		["Talk to Count Verandis Ravenwatch 7"] =
			{appendText=".", stepTextKey="It appears that when the Dark Heart began to slow many centuries ago, Lady Belain took the last of the power for herself. I should talk to Verandis about this."},
		[20] = 
			{appendStepText="We traveled through the halls of the keep in the Arkthzand Cavern of Blackreach. From the southeastern chamber, the Suite, we entered the Grand Chamber and then the Black Diamond Chamber. In the northwestern end of the Dark Halls caverns, we found an altar. ", stepTextKey="Another magical barrier guards the end of the Dark Halls. I should use the intact insignia to dispel it as I did at the entrance to this passage. The Dark Heart must be close."},
		["Dispel the Ward 2"] =
			{appendText=" west of the altar.", stepTextKey="Another magical barrier guards the end of the Dark Halls. I should use the intact insignia to dispel it as I did at the entrance to this passage. The Dark Heart must be close."},
		[21] = 
			{appendStepText="We traveled through the halls of the keep in the Arkthzand Cavern of Blackreach. From the southeastern chamber, the Suite, we entered the Grand Chamber and then the Black Diamond Chamber. In the northwestern end of the Dark Halls caverns, we found an altar and a warded door. ", stepTextKey="With the last ward dispelled, I should head through the door and try to find the Dark Heart."},
		["Enter the Dark Heart Chamber"] =
			{appendText="."},
		[22] = 
			{appendStepText="We traveled through the halls of the keep in the Arkthzand Cavern of Blackreach. From the southeastern chamber, the Suite, we entered the Grand Chamber and the Black Diamond Chamber, and through the Dark Halls caverns. ", stepTextKey="We reached the chamber containing the Dark Heart, but Rada al-Saran and Lady Belain are already here. While Verandis attempts to stop Rada al-Saran, I need to keep Lady Belain's Nighthollow minions away from him."},
		["Protect Count Verandis Ravenwatch"] =
			{appendText="."},
		[23] = 
			{appendStepText="We traveled through the halls of the keep in the Arkthzand Cavern of Blackreach. From the southeastern chamber, the Suite, we entered the Grand Chamber and the Black Diamond Chamber, and through the Dark Halls caverns. We entered the Chamber of the Dark Heart. ", stepTextKey="The Dark Heart has awakened and is rising upward, but Rada al-Sraran and Lady Belain have gotten away. I should check on Verandis."},
		["Go to Count Verandis Ravenwatch"] =
			{appendText=" up on the Dwemer balcony."},
		[24] = 
			{appendStepText="We traveled through the halls of the keep in the Arkthzand Cavern of Blackreach. From the southeastern chamber, the Suite, we entered the Grand Chamber and the Black Diamond Chamber, and through the Dark Halls caverns. We entered the Chamber of the Dark Heart. ", stepTextKey="The Dark Heart has awakened. I should talk to Verandis and find out what we should do now."},
		["Talk to Count Verandis Ravenwatch 8"] =
			{appendText=" on the Dwemer balcony.", stepTextKey="The Dark Heart has awakened. I should talk to Verandis and find out what we should do now."},
		[25] = 
			{appendStepText="Verandis headed for a Dwarven lift to the west. ", stepTextKey="I need to follow Verandis and leave the Dark Heart chamber."},
		["Leave the Dark Heart Chamber"] =
			{appendText="."},
		[26] = 
			{appendStepText="", stepTextKey="The lift took me to an overlook across from the Library of Arkthzand. The orrery dome is now glowing. I should talk to Verandis."},
		["Talk to Count Verandis Ravenwatch 9"] =
			{appendText=", behind the library up on a balcony at the western wall of Arkthzand Cavern in Blackreach.", stepTextKey="The lift took me to an overlook across from the Library of Arkthzand. The orrery dome is now glowing. I should talk to Verandis."},
	},

	[GetQuestName(6566)] = { --"A Feast of Souls" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Verandis has asked me to go to Markarth and warn Ard Caddach. Instead of fighting back against the Gray Host, he needs to fall back and deny as many lives as possible to the Dark Heart."},
		["Go to Markarth"] =
			{appendText=". Before I speak with the Ard, I need to meet someone near Markarth Mercantile inside the gates, north of The Hunter's Repose tavern."},
		[2] = 
			{appendStepText="In the city near Markarth Mercantile, north of The Hunter's Repose tavern, ", stepTextKey="I should let Bradan know that the Gray Host wants a fight. They want to kill everyone to feed the Dark Heart. He needs to make sure Markarth's defenders work to keep everyone alive and not try to die in a blaze of glory."},
		["Talk to Bradan"] =
			{appendText=", a werewolf Reachman of the Ghostsong Clan."},
		[3] = 
			{appendStepText="", stepTextKey="Now that I brought Bradan up to speed, I need to go to Understone Keep and convince Ard Caddach and Arana that we need to deny the Dark Heart as many deaths as we can."},
		["Go to Understone Keep"] =
			{appendText=" up on the western side of Markarth."},
		[4] = 
			{appendStepText="In the streets of Markarth, I saw the dead and the dying. ", stepTextKey="Now that I reached Understone Keep, I should find Ard Caddach and let him know the true purpose of this assault on Markarth."},
		["Talk to Ard Caddach 1"] =
			{appendText=" in the entry hall of the keep.", stepTextKey="Now that I reached Understone Keep, I should find Ard Caddach and let him know the true purpose of this assault on Markarth."},
		[5] = 
			{appendStepText="In Understone Keep in Markarth, ", stepTextKey="Ard Caddach explained that Arana chased Lady Belain back into Nchuand-Zel. I should try to catch up to them and help the witch-rebel defeat the ancient vampire."},
		["Enter Nchuand-Zel"] =
			{appendText=". I should speak to Gwendis in the entry hall before I go to the Dwarven ruin's entrance in the southern chamber of the keep."},
		[6] = 
			{appendStepText="From the southern chamber in Understone Keep in Markarth, ", stepTextKey="I entered the undercity of Nchuand-Zel. Now to find Arana and help her deal with Lady Belain."},
		["Search for Arana"] =
			{appendText=", the Reach witch chasing the ancient Nighthollow vampire."},
		[7] = 
			{appendStepText="From the southern chamber in Understone Keep in Markarth, I entered Nchuand-Zel. ", stepTextKey="I found Arana, but she appears to have been seriously wounded. I should talk to her."},
		["Talk to Arana 1"] =
			{appendText=" at the central chamber in the Dwarven ruin.", stepTextKey="I found Arana, but she appears to have been seriously wounded. I should talk to her."},
		[8] = 
			{appendStepText="From the southern chamber in Understone Keep in Markarth, I entered the Dwarven ruin. ", stepTextKey="Arana was seriously wounded in her battle with Lady Belain, but she thinks she sensed the presence of another keystone in the Nchuand-Zel vaults below. I need to find that keystone so I can enter the orrery chamber in the Library of Arkthzand."},
		["Find the Keystone"] =
			{appendText=". The entry to the vaults is in the northwest corner of the central chamber with a river. To get below, I should find a lift and continue until I find the Keystone Chamber."},
		[9] = 
			{appendStepText="From the southern chamber in Understone Keep in Markarth, I entered the ruin, found the Vaults through the northwestern door in the central chamber, took a lift down and reached the Keystone Chamber. ", stepTextKey="I located the Nchuand-Zel Keystone, but it's protected by ancient Dwarven wards. I need to figure out a way past the defenses so that I can get the keystone and enter the Library of Arkthzand."},
		["Unlock the Nchuand-Zel Keystone"] =
			{appendText=". I should search for a book or journal I can pick up and use. The constellation stones, the star tales of the Reachfolk, are the key."},
		[10] = 
			{appendStepText="From the southern chamber in Understone Keep in Markarth, I entered the ruin, found the Vaults through the northwestern door in the central chamber, took a lift down and reached the Keystone Chamber. ", stepTextKey="I removed the keystone's protective wards. Time to take it and go to the orrery chamber in the Library of Arkthzand."},
		["Take the Keystone"] =
			{appendText=" from its chamber."},
		[11] = 
			{appendStepText="From the southern chamber in Understone Keep in Markarth, I entered the ruin, found the Vaults through the northwestern door in the central chamber, took a lift down and reached the Keystone Chamber. ", stepTextKey="Now that I have a keystone, I can access the orrery inside the Library of Arkthzand. I should head there and make my way to the orrery chamber."},
		["Go to the Library of Arkthzand"] =
			{appendText=". From the Keystone Chamber, I should exit to the southeast and use the lift in the next chamber in Nchuand-Zel. In the Blackreach cavern, I can cross a bridge to the northeast to reach the front entrance of the library."},
		[12] = 
			{appendStepText="In Arkthzand Cavern of Blackreach, ", stepTextKey="I reached the Library of Arkthzand and met Verandis, who has been seeking a way into the orrery chamber. I should tell him about the keystone I acquired in Nchuand-Zel."},
		["Talk to Count Verandis Ravenwatch 1"] =
			{appendText=" near the front entrance of the library. Gwendis is here, too.", stepTextKey="I reached the Library of Arkthzand and met Verandis, who has been seeking a way into the orrery chamber. I should tell him about the keystone I acquired in Nchuand-Zel."},
		[13] = 
			{appendStepText="I spoke with Verandis in front of the library in the Arkthzand Cavern of Blackreach. ", stepTextKey="It's time to use the keystone I acquired in Nchuand-Zel and enter the orrery chamber in the Library of Arkthzand."},
		["Enter the Orrery Chamber"] =
			{appendText=" by using the keystone on its door at the library."},
		[14] = 
			{appendStepText="The Nchuand-Zel keystone worked to open the door to the Library of Arkthzand. ", stepTextKey="We entered the orrery chamber to find Rada al-Saran doing something to the arcane machine. We need to try to stop him."},
		["Confront Rada al-Saran"] =
			{appendText=" on the far side of the chamber."},
		[15] = 
			{appendStepText="I had entered the Arkhzand Orrery, but ", stepTextKey="While Verandis and Gwendis attempt to stop Rada al-Saran and whatever he's doing with the orrery above, Lady Belain teleported me down below into the chamber with the Dark Heart. She's drawing power from it. I need to stop her while I still can."},
		["Defeat Lady Belain"] =
			{appendText=". She is being sustained by shades up on the surrounding outcroppings. Arana came to help, creating portals to reach the shades."},
		[16] = 
			{appendStepText="In the Chamber of the Dark Heart, using Arana's void portals, I defeated the shades and then fought the ancient Nighthollow vampire. ", stepTextKey="We defeated Lady Belain, but I heard Arana call out in pain. I should check on her."},
		["Talk to Arana 2"] =
			{appendText=" on the balcony.", stepTextKey="We defeated Lady Belain, but I heard Arana call out in pain. I should check on her."},
		[17] = 
			{appendStepText="", stepTextKey="With her dying breath, Arana opened a portal to return me to the orrery above. She said that Verandis needs my help. I should hurry through the portal."},
		["Return to the Orrery Chamber"] =
			{appendText="."},
		[18] = 
			{appendStepText="I returned to the Arkthzand Orrery within the Library of Arkthzand in Blackreach. ", stepTextKey="The ancient orrery is still operating at full power. Verandis told me to run to the far platform and throw the switch. It will take all of us to stop the machine."},
		["Stop the Orrery"] =
			{appendText=".", stepTextKey="The ancient orrery is still operating at full power. Verandis told me to run to the far platform and throw the switch. It will take all of us to stop the machine."},
		[19] = 
			{appendStepText="In the Arkthzand Orrery within the Library of Arkthzand in Blackreach, I threw the switch. ", stepTextKey="We powered down the orrery. I should let Verandis know what transpired in the Dark Heart chamber below."},
		["Talk to Count Verandis Ravenwatch 2"] =
			{appendText=" at the northeast platform of the orrery.", stepTextKey="We powered down the orrery. I should let Verandis know what transpired in the Dark Heart chamber below."},
		[20] = 
			{appendStepText="", stepTextKey="Verandis has asked me to return to Markarth and tell Ard Caddach that Belain has been defeated. I should go to Understone Keep and talk to the ard."},
		["Return to Understone Keep"] =
			{appendText=" in western Markarth."},
		[21] = 
			{appendStepText="I returned to Markarth. ", stepTextKey="Now that I'm back in Understone Keep, I should let Ard Caddach know what transpired in Blackreach."},
		["Talk to Ard Caddach 2"] =
			{appendText=" near his throne.", stepTextKey="Now that I'm back in Understone Keep, I should let Ard Caddach know what transpired in Blackreach."},
		[22] = 
			{appendStepText="In Markarth, ", stepTextKey="Verandis returned to Understone Keep. I should speak to him. Perhaps he learned something more from his study of the orrery."},
		["Talk to Count Verandis Ravenwatch 3"] =
			{appendText=". He is with Gwendis near the Ard's throne.", stepTextKey="Verandis returned to Understone Keep. I should speak to him. Perhaps he learned something more from his study of the orrery."},
		[23] = 
			{appendStepText="", stepTextKey="We killed Lady Belain, kept the Dark Heart from devouring all of Markarth, and scattered the Gray Host. But Rada al-Saran escaped. I should ask Verandis what we should do now."},
		["Talk to Count Verandis Ravenwatch 4"] =
			{appendText=" near Ard Caddach's throne in Understone Keep in Markath.", stepTextKey="We killed Lady Belain, kept the Dark Heart from devouring all of Markarth, and scattered the Gray Host. But Rada al-Saran escaped. I should ask Verandis what we should do now."},
	},

	[GetQuestName(6552)] = { --"The End of Eternity" --Jordakai
		[1] = 
			{appendStepText="I have been to Western Skyrim and now I have returned to The Reach. ", stepTextKey="Gwendis told me I can find Verandis in Markarth, in Understone Keep. I should talk with him."},
		["Talk to Count Verandis Ravenwatch 1"] =
			{appendText=". He should be near Ard Caddach's throne.", stepTextKey="Gwendis told me I can find Verandis in Markarth, in Understone Keep. I should talk with him."},
		[2] = 
			{appendStepText="In Understone Keep at Markarth, ", stepTextKey="Verandis has more he wishes to share with me. I should speak to him in Understone Keep."},
		["Talk to Count Verandis Ravenwatch 2"] =
			{appendText=".", stepTextKey="Verandis has more he wishes to share with me. I should speak to him in Understone Keep."},
		[3] = 
			{appendStepText="In Understone Keep at Markarth, I met with Verandis. ", stepTextKey="Rada al-Saran's forces are gathering to the north of Markarth, near Bthardamz. Verandis asked me to investigate and discover the Gray Host's plans."},
		["Investigate North of Markarth"] =
			{appendText=". There is a secluded, high-mountain valley. It is west of Bthardamz and southwest of the Druadach Mountains Wayshrine."},
		[4] = 
			{appendStepText="In a narrow mountain valley, southwest of the Druadach Mountains Wayshrine and west of Bthardamz, ", stepTextKey="I heard Rada al-Saran addressing his forces as I approached the Gray Host camp. I should try to find him."},
		["Find Rada al-Saran"] =
			{appendText="."},
		[5] = 
			{appendStepText="At an altar at the top of the narrow mountain valley, southwest of the Druadach Mountains Wayshrine and west of Bthardamz, ", stepTextKey="Lyris and Fennorian confronted Rada al-Saran as I approached, but the Ashen Lord and his commanders escaped without a fight. I should speak to Lyris and Fenn about what they're doing here."},
		["Talk to Lyris Titanborn"] =
			{appendText=".\n"},
		["Talk to Fennorian"] =
			{appendText=". He is examining a strange trinket by the altar."},
		[6] = 
			{appendStepText="In a narrow mountain valley, southwest of the Druadach Mountains Wayshrine and west of Bthardamz, ", stepTextKey="Rada al-Saran escaped, but Fennorian intercepted a coded communication important to the Gray Host. We should bring it to Verandis in the orrery chamber of the Library of Arkthzand in Blackreach."},
		["Go to the Orrery Chamber 1"] =
			{appendText=" through the Library's eastern front door. The library is in the western part of Arkthzand Cavern of Blackreach. \n\nI can use the Arkthzand Great Lift or I can travel via wayshrine.", stepTextKey="Rada al-Saran escaped, but Fennorian intercepted a coded communication important to the Gray Host. We should bring it to Verandis in the orrery chamber of the Library of Arkthzand in Blackreach."},
		[7] = 
			{appendStepText="In the Orrery at Arkthzand Library in the Arkthzand Cavern of Blackreach, ", stepTextKey="I should talk to Verandis about the Gray Host's intercepted message and what it means for us."},
		["Talk to Count Verandis Ravenwatch 3"] =
			{appendText=", down near the machine.", stepTextKey="I should talk to Verandis about the Gray Host's intercepted message and what it means for us."},
		[8] = 
			{appendStepText="I met with Verandis, Fennorian, Lyris, and Gwendis at the Arkthzand Orrery in the Blackreach cavern. Count Ravenwatch continues to struggle against the influence of the Dark Heart. He said the dispatch from Rada al-Saran was a letter meant for him. ", stepTextKey="The coded letter directed Verandis to three different locations. I should investigate each site in order to determine more about Rada al-Saran's ultimate plan."},
		["Find the Land Sundered from Tamriel"] =
			{appendText=". Lyris will join me in Underscore Keep at Markarth. I will speak with Ard Caddach. He should know about a sundered land. Its forbidden entry is likely just inside Nchuand-Zel, the Dwarven ruin in the keep's southern chamber. \n"},
		["Go to the Nighthollow Archive"] =
			{appendText=" near Nighthollow Keep in the Arkthzand Cavern's eastern lake area. I should meet Gwendis southeast of the Nighthollow Wayshrine, along the trail by the southern wall of the cavern. After we enter the Archive southwest of the keep, we can look for what we need to see. \n"},
		["Learn About Keystones in Bthar-Zel"] =
			{appendText=", the Dwarven ruin far north of Markarth, across the Deep Folk Crossing. Once inside, I should find Fennorian to help me learn more about keystones. He is probably ahead of me in the eastern chamber. We may need to explore that chamber's northeastern side."},
		[9] = 
			{appendStepText="", stepTextKey="I recovered an Oblivion stone from the sundered land in the Reach, the Nighthollow Testament, and an unassembled keystone. I should return to the orrery chamber and see what Verandis makes of all this."},
		["Go to the Orrery Chamber 2"] =
			{appendText=" in the Arkthzand Library, on the west side of Arkthzand Cavern in Blackreach. In addition to the items I carry, my companions and I have seen memories of Verandis and Rada al-Saran.", stepTextKey="I recovered an Oblivion stone from the sundered land in the Reach, the Nighthollow Testament, and an unassembled keystone. I should return to the orrery chamber and see what Verandis makes of all this."},
		[10] = 
			{appendStepText="In the western part of Arkthzand Cavern of Blackreach, I returned to the Orrery and found Gwendis, Fennorian, and Lyris already here. ", stepTextKey="Despite the others badgering Verandis about his past, I need to show the count what I found and see if these items help us get closer to determining Rada al-Saran's plans."},
		["Talk to Count Verandis Ravenwatch 4"] =
			{appendText=".", stepTextKey="Despite the others badgering Verandis about his past, I need to show the count what I found and see if these items help us get closer to determining Rada al-Saran's plans."},
		[11] = 
			{appendStepText="In the Arkthzand Orrery of the Library of Arkthzand in Blackreach's cavern, I gave the items I found to Count Ravenwatch and spoke with him. ", stepTextKey="Verandis said that Rada al-Saran has a hidden laboratory somewhere in the Library of Arkthzand, but he hasn't been able to pinpoint it. He asked all of us to help him search for it."},
		["Find the Hidden Laboratory"] =
			{appendText=". It is likely accessed through the Library's entrance in western Arkthzand Cavern's, above the courtyard south of the main building. Among the many bookshelves, high and low, there must be a hidden entrance that leads to a concealed wing with a laboratory."},
		[12] = 
			{appendStepText="We entered the Library's south courtyard entrance in the western Dwemer structure in Arkthzand Cavern of Blackreach. A hidden entrance at a bookshelf on the upper south side of the Library's first chamber lead us to a concealed wing in the Halls of Arkthzand and a lift. ", stepTextKey="We located Rada al-Saran's hidden laboratory. There are many experiments left inside. I should speak to Verandis about it."},
		["Talk to Count Verandis Ravenwatch 5"] =
			{appendText=" in the laboratory.", stepTextKey="We located Rada al-Saran's hidden laboratory. There are many experiments left inside. I should speak to Verandis about it."},
		[13] = 
			{appendStepText="We entered the Library's southern doorway from the courtyard, in the western Dwemer structure in Arkthzand Cavern of Blackreach. A hidden entrance on the upper south side of the Library's first chamber led us to a concealed wing and a lift. In the laboratory, ", stepTextKey="Verandis claims to understand how Rada al-Saran's experiment is intended to work, but he still doesn't understand the purpose. He believes Rada intended for him to repeat his work to discover what his true aims are. Verandis needs my help to succeed."},
		["Follow Verandis's Instructions"] =
			{appendText=" for using the three machines: the Aetheric Beacon with blue crystals, the Kinetic Manacle with its triangular arms extended, and the Tonal Cascade with a circular crest. I will also need to help Fennorian and Gwendis at their stations.\n\nI should listen carefully to the Count's instructions."},
		[14] = 
			{appendStepText="We entered the Library's southern doorway from the courtyard, in the western Dwemer structure in Arkthzand Cavern of Blackreach. A hidden entrance on the upper south side of the Library's first chamber led us to a concealed wing and a lift to the laboratory. ", stepTextKey="We succeeded in recreating whatever it was Rada al-Saran did here. It seemed to have had a profound impact on Verandis. I should speak to him about what he discovered."},
		["Talk to Count Verandis Ravenwatch 6"] =
			{appendText=" near the central platform.", stepTextKey="We succeeded in recreating whatever it was Rada al-Saran did here. It seemed to have had a profound impact on Verandis. I should speak to him about what he discovered."},
		[15] = 
			{appendStepText="We entered the Library's southern doorway from the courtyard, in the western Dwemer structure in Arkthzand Cavern of Blackreach. A hidden entrance on the upper south side of the Library's first chamber led us to a concealed wing and a lift. In the laboratory, ", stepTextKey="Verandis felt a great pain and says that Rada al-Saran is drawing on the power of the Dark Heart. We have to get to the orrery chamber as fast as we can."},
		["Go to the Orrery Chamber 3"] =
			{appendText=" using the nearby lift to return to the western area in Arkthzand Cavern of Blackreach. Then out through the eastern archway and around through the Library's courtyard to the Orrery's entrance at the front of the main building.", stepTextKey="Verandis felt a great pain and says that Rada al-Saran is drawing on the power of the Dark Heart. We have to get to the orrery chamber as fast as we can."},
		[16] = 
			{appendStepText="I entered the Arkthzand Orrery in the Blackreach cavern's western building, the Library of Arkthzand. ", stepTextKey="I found Rada al-Saran in the orrery chamber. He seems to be performing the same ritual we just did but on a grander scale. I must try to stop him."},
		["Confront Rada al-Saran"] =
			{appendText="."},
		[17] = 
			{appendStepText="From the Orrery Chamber in the Library in Arkthzand Cavern of Blackreach, ", stepTextKey="Rada al-Saran vanished after using the orrery. I should speak to Verandis about what happened."},
		["Talk to Count Verandis Ravenwatch 7"] =
			{appendText=" in the chamber near the orrery.", stepTextKey="Rada al-Saran vanished after using the orrery. I should speak to Verandis about what happened."},
		[18] = 
			{appendStepText="I spoke with Count Ravenwatch in the Orrery Chamber of the Library in Arkthzand Cavern of Blackreach. ", stepTextKey="Verandis thinks he can stop the Darkstorm, but he needs to enter Rada al-Saran's sanctuary realm to do so. I should ask him how we can do that."},
		["Talk to Count Verandis Ravenwatch 8"] =
			{appendText=".", stepTextKey="Verandis thinks he can stop the Darkstorm, but he needs to enter Rada al-Saran's sanctuary realm to do so. I should ask him how we can do that."},
	},

	[GetQuestName(6560)] = { --"Kingdom of Ash" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Gwendis wants me to get to the orrery chamber in the Library of Arkthzand and offer my assistance to Verandis."},
		["Talk to Count Verandis Ravenwatch 1"] =
			{appendText=". He should be at the Library's main building in the western area of Arkthzand Cavern in Blackreach.", stepTextKey="Gwendis wants me to get to the orrery chamber in the Library of Arkthzand and offer my assistance to Verandis."},
		[2] = 
			{appendStepText="I am at the Arkthzand Orrery in the Library, the Dwemer building on the west side of Arkthzand Cavern in Blackreach. ", stepTextKey="I need to reactivate the orrery to open the gateway to Rada al-Saran's sanctuary realm."},
		["Activate the Orrery"] =
			{appendText=". I should start by activating the Aetheric Beacon on the machine's northeastern platform. Next is the beacon on the western platform. And finally, the beacon on the southeastern platform of the orrery."},
		[3] = 
			{appendStepText="Verandis, Lyris, Fennorian, and Gwendis are with me in the Arkthzand Orrery chamber of the Library in Arkthzand Cavern in Blackreach. I have activated the orrery. ", stepTextKey="I may not return from this trek into the Void. I should speak to my companions before I depart."},
		["Talk to Count Verandis Ravenwatch 2"] =
			{appendText=" and my companions.", stepTextKey="I may not return from this trek into the Void. I should speak to my companions before I depart."},
		[4] = 
			{appendStepText="I spoke with Verandis, Lyris, Fennorian, and Gwendis in the Arkthzand Orrery chamber of the Library in Arkthzand Cavern in Blackreach. ", stepTextKey="I reactivated the orrery and opened a gateway through the Void. Hopefully, it will lead to Rada al-Saran's sanctuary realm."},
		["Enter the Gateway"] =
			{appendText=" to the Dark Heart. The portal is on the machine's western platform."},
		[5] = 
			{appendStepText="From the portal in the Arkthzand Orrery chamber of the Library in Arkthzand Cavern in Blackreach, ", stepTextKey="I emerged from the gateway into a strange Oblivion realm, but I'm alone. I should see if Lyris and Verandis made it through as well."},
		["Look for Your Companions"] =
			{appendText=" along the narrow valley path."},
		[6] = 
			{appendStepText="I used the portal in the Arkthzand Orrery chamber of the Library in the Arkthzand Cavern in Blackreach to reach the Oblivion realm of Grayhaven. I started along a trail, then ", stepTextKey="I heard Lyris nearby. She sounded like she was in trouble. I should find her."},
		["Find Lyris Titanborn"] =
			{appendText=". She should be near the trail."},
		[7] = 
			{appendStepText="I used the portal in the Arkthzand Orrery chamber of the Library in the Arkthzand Cavern in Blackreach to reach the Oblivion realm of Grayhaven. ", stepTextKey="I reunited with Lyris in Oblivion, but Verandis wasn't with her. We should search for him."},
		["Search for Count Verandis Ravenwatch"] =
			{appendText=" near the trail."},
		[8] = 
			{appendStepText="I used the portal in the Arkthzand Orrery chamber of the Library in Arkthzand Cavern in Blackreach to reach the Oblivion realm of Grayhaven. I found Lyris and we began looking for Verandis. Then, ", stepTextKey="Lyris and I spotted the Darkstorm forming in the distance. There's a good chance that's where we'll find Rada al-Saran, and possibly Verandis as well."},
		["Follow the Darkstorm"] =
			{appendText="."},
		[9] = 
			{appendStepText="I used the portal in the Arkthzand Orrery chamber of the Library in Arkthzand Cavern in Blackreach to reach the Oblivion realm of Grayhaven. Following the trail to its end, ", stepTextKey="Lyris and I heard Verandis arguing with Rada al-Saran. We need to reach them in the center of the Darkstorm."},
		["Reach the Center of the Darkstorm"] =
			{appendText="."},
		[10] = 
			{appendStepText="I used the portal in the Arkthzand Orrery chamber of the Library in Arkthzand Cavern in Blackreach to reach the Oblivion realm of Grayhaven. Lyris and I arrived at the end of the trail. ", stepTextKey="Verandis defied Rada al-Saran and was nearly killed. I need to protect Verandis and end Rada al-Saran's existence once and for all."},
		["Kill Rada al-Saran"] =
			{appendText="."},
		[11] = 
			{appendStepText="I used the portal in the Arkthzand Orrery chamber of the Library in Arkthzand Cavern in Blackreach to reach the Oblivion realm of Grayhaven. At the end of the trail, Verandis helped protect me. Finally, ", stepTextKey="Rada al-Saran is dead. Verandis is attempting to take control of the Darkstorm. I should wait for him."},
		["Wait for Count Verandis Ravenwatch"] =
			{appendText="."},
		[12] = 
			{appendStepText="I used the portal in the Arkthzand Orrery chamber of the Library in Arkthzand Cavern in Blackreach to reach the Oblivion realm of Grayhaven. The Ashen Lord, Rada al-Saran is dead. Now, ", stepTextKey="Verandis is wrestling with the Darkstorm, but he hasn't dispelled it. I should speak with him."},
		["Talk to Count Verandis Ravenwatch 3"] =
			{appendText=".", stepTextKey="Verandis is wrestling with the Darkstorm, but he hasn't dispelled it. I should speak with him."},
		[13] = 
			{appendStepText="In the Oblivion realm of Grayhaven, ", stepTextKey="Verandis opened a gateway to the orrery with the power of the Dark Heart. Lyris and I should return there while we still have the chance."},
		["Go to the Orrery Chamber"] =
			{appendText=" in the Library in Arkthzand Cavern in Blackreach."},
		[14] = 
			{appendStepText="", stepTextKey="Lyris and I made it back to the orrery chamber. Gwendis and Fennorian are waiting to welcome us back."},
		["Listen to Your Companions"] =
			{appendText=" in the orrery chamber of the Library in Arkthzand Cavern in Blackreach."},
		[15] = 
			{appendStepText="Lyris and I returned to the Arkthzand Orrery in the Library in Arkthzand Cavern in Blackreach. ", stepTextKey="The Dark Heart released its energy as we returned and we suddenly found Arana among us, alive and well. I should speak to her."},
		["Talk to Arana"] =
			{appendText="."},
		[16] = 
			{appendStepText="In the Arkthzand Orrery chamber of the Library in Arkthzand Cavern in Blackreach, I spoke with Arana. Now, ", stepTextKey="Lyris wants to talk to me. I should speak to her."},
		["Talk to Lyris Titanborn 1"] =
			{appendText=".", stepTextKey="Lyris wants to talk to me. I should speak to her."},
		[17] = 
			{appendStepText="", stepTextKey="Lyris suggested I head back to Markarth to confirm our suspicion that the lives lost to the Dark Heart have been restored. She'll meet me there."},
		["Meet Lyris Titanborn in Markarth"] =
			{appendText=", near the Guild Traders and the city's wayshrine."},
		[18] = 
			{appendStepText="I returned to Markarth. ", stepTextKey="Lyris and I have discovered that Verandis resurrected the lost souls of Markarth, returning the people killed by the Gray Host to life. I should talk to her about this development."},
		["Talk to Lyris Titanborn 2"] =
			{appendText=" by the bridge near the Guild Traders and the wayshrine.", stepTextKey="Lyris and I have discovered that Verandis resurrected the lost souls of Markarth, returning the people killed by the Gray Host to life. I should talk to her about this development."},
	},


	[GetQuestName(6570)] = { --"Second Chances" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="I should go to Understone Keep in Markarth to inform Ard Caddach of Rada al-Saran's death."},
		["Go to Understone Keep"] =
			{appendText=" at the west end of the city."},
		[2] = 
			{appendStepText="As soon as I entered Understone Keep in Markarth, ", stepTextKey="Braden told me Ard Caddach is holding an audience in his war room. I should find him there to tell him about Rada al-Saran's death."},
		["Go to Ard Caddach's War Room"] =
			{appendText=" up behind his throne, at the end of the keep's northwestern hallway."},
		[3] = 
			{appendStepText="In Markarth's Understone Keep, I entered the war room at the end of the keep's northwestern hallway. ", stepTextKey="Ard Caddach appears to be hosting a moot with the rulers of Eastern and Western Skyrim and they reached some kind of agreement. Ard Caddach wants to speak with me."},
		["Talk to Ard Caddach 1"] =
			{appendText=". I could speak with Jarl Svana, Prince Irnskar, and the Skald-King, too.", stepTextKey="Ard Caddach appears to be hosting a moot with the rulers of Eastern and Western Skyrim and they reached some kind of agreement. Ard Caddach wants to speak with me."},
		[4] = 
			{appendStepText="In his war room at Understone Keep in Markarth, I spoke with the Ard and his guests. ", stepTextKey="Ard Caddach asked me to find Arana and see if she's willing to serve as his counselor. She's somewhere in Understone Keep."},
		["Find Arana"] =
			{appendText=". She is probably somewhere near the throne in the keep."},
		[5] = 
			{appendStepText="In his war room at Understone Keep in Markarth, I spoke with the Ard and his guests. I found Arana in the hall near the throne. ", stepTextKey="I found Arana. I should see if she's willing to become Ard Caddach's counselor."},
		["Talk to Arana 1"] =
			{appendText=".", stepTextKey="I found Arana. I should see if she's willing to become Ard Caddach's counselor."},
		[6] = 
			{appendStepText="In Understone Keep at Markarth, ", stepTextKey="Arana agreed to act as Ard Caddach's counselor and will give him her answer herself. She informed me that a friend has travel a very long way to personally thank me for my deeds. I can meet them in a room to the rear of Understone Keep."},
		["Find Arana's Associate"] =
			{appendText=" in a southwestern room at the end of the hallway south of the throne."},
		[7] = 
			{appendStepText="In Understone Keep at Markarth, in the southwestern room at the end of the hallway south of the throne, I found Arana's associate. ", stepTextKey="Despite leaving Verandis behind in Rada al-Saran's sanctuary realm, he's appeared to speak with me. I should find out how he was able to return."},
		["Talk to Count Verandis Ravenwatch"] =
			{appendText="."},
		[8] = 
			{appendStepText="In Understone Keep, ", stepTextKey="Ard Caddach wants me to attend an address that he and the other leaders of Skyrim will give to the people of Markarth. I should find him in his audience chambers."},
		["Go to the Announcement"] =
			{appendText=" Hall after speaking with Gwendis, Fennorian, and Adusa-daro of House Ravenwatch. The announcement will be held in the northeastern hall of the keep. I should watch for Lyris and anyone else I know. After I enter, I should probably go up to the front of the chamber."},
		[9] = 
			{appendStepText="In Markarth's Understone Keep, ", stepTextKey="I arrived in the Announcement Hall. Arana wants to speak with me before the rulers of Skyrim make their announcement."},
		["Talk to Arana 2"] =
			{appendText=".", stepTextKey="I arrived in the Announcement Hall. Arana wants to speak with me before the rulers of Skyrim make their announcement."},
		[10] = 
			{appendStepText="In the Announcement Hall, the northeastern chamber of Understone Keep in Markarth, I spoke briefly with Arana. Now, ", stepTextKey="Ard Caddach wants to speak with me before he and the leaders of Skyrim announce their intentions to cooperate."},
		["Talk to Ard Caddach 2"] =
			{appendText=".", stepTextKey="Ard Caddach wants to speak with me before he and the leaders of Skyrim announce their intentions to cooperate."},
	},


-- 		=========================================================================
--		  The Reach - Side Quest 
-- 		=========================================================================

    [GetQuestName(6597)] = { --"A Challenge of Worth" --Jordakai
        [1] = 
            {appendStepText="Standing near the fortress wall with his four-wheeled cart outside Markarth, ", stepTextKey="Angair told me to find his clan mate Caddgarn in Vateshran Hollows if I wish to perform the Rites. I should go there and speak to him."},
        ["Talk to Caddgarn 1"] =
            {appendText=" in Vateshran Hollow, in the far southern mountains. He is standing near a totem in the central area, north of the waterfall and river. \n\nI can take Angair's cart to Vateshran Hollow.", stepTextKey="Angair told me to find his clan mate Caddgarn in Vateshran Hollows if I wish to perform the Rites. I should go there and speak to him."},
        [2] = 
            {appendStepText="I traveled to the southern mountains, far from Markarth. ", stepTextKey="I should find Caddgarn in the Vateshran Hollows and speak to him about taking the Vateshran's Rites."},
        ["Talk to Caddgarn 2"] =
            {appendText=". He stands near a totem in the central area, north of the waterfall and river.", stepTextKey="I should find Caddgarn in the Vateshran Hollows and speak to him about taking the Vateshran's Rites."},
    },


	[GetQuestName(6563)] = { --"After the Storm" --Jordakai
		[1] = 
			{appendStepText="", stepTextKey="Apprentice Fialyn asked me to meet her in Karthwasten so she could present me to her master, Shaman Ulvoch."},
		["Meet Apprentice Fialyn in Karthwasten"] =
			{appendText=", a village in The Reach's northeast. The Shaman's house is a wooden structure in the village's southeast."},
		[2] = 
			{appendStepText="In the region's northeast, ", stepTextKey="I arrived in the village of Karthwasten. I should speak with Apprentice Fialyn."},
		["Talk to Apprentice Fialyn 1"] =
			{appendText=" on the porch of Shaman Ulvoch's house.", stepTextKey="I arrived in the village of Karthwasten. I should speak with Apprentice Fialyn."},
		[3] = 
			{appendStepText="", stepTextKey="Apprentice Fialyn asked me to speak with Shaman Ulvoch. She wants him to explain the ward restoration process, after he approves of my presence."},
		["Talk to Shaman Ulvoch 1"] =
			{appendText=" in his house in the southeastern part of the village.", stepTextKey="Apprentice Fialyn asked me to speak with Shaman Ulvoch. She wants him to explain the ward restoration process, after he approves of my presence."},
		[4] = 
			{appendStepText="In his house in the village, ", stepTextKey="Shaman Ulvoch asked me to help Apprentice Fialyn gather materials to present as offerings at the wards. I need to gather willow branches, moon-touched stones, and cicada husks."},
		["Gather Willow Branches"] =
			{appendText=" on the slope with willow trees near the trail leading up to the old stone tower.\n"},
		["Gather Moon-Touched Stones"] =
			{appendText=" from the ground at the stone arch ruins near the old tower.\n"},
		["Gather Cicada Husks"] =
			{appendText=" on a rock overlooking the village, southwest of the old stone tower.\n\nI should search the mountaintop area with the old tower, northwest of the village."},
		[5] = 
			{appendStepText="Northwest of the village, ", stepTextKey="I gathered the various materials for the offerings. Now to take them to the wards and place them while Apprentice Fialyn says the prescribed words."},
		["Place the Offerings at the Wards"] =
			{appendText=" \n\nNarmira's Ward is north of the village on the trail, a little below the old tower.\nNocturnal's Ward is on the trail going up from the sharp curve in the trail leading from the village to the old tower.\nHircine's Ward is on the trail, southeast of Nocturnal's Ward and southwest of the village.\nMolag Bal's Ward is down  the trail, south of the village.\n"},
		[6] = 
			{appendStepText="", stepTextKey="The offerings have been placed at the wards. I should return to Karthwasten and inform Shaman Ulvoch that everything is ready for him to perform the restoration ritual."},
		["Return to Shaman Ulvoch"] =
			{appendText=" near the tall ritual pyre in the village."},
		[7] = 
			{appendStepText="In the village, ", stepTextKey="I should talk to Shaman Ulvoch now that the offerings have been placed at the wards."},
		["Talk to Shaman Ulvoch 2"] =
			{appendText=" at the tall ritual pyre.", stepTextKey="I should talk to Shaman Ulvoch now that the offerings have been placed at the wards."},
		[8] = 
			{appendStepText="", stepTextKey="Shaman Ulvoch requested that I present myself at the ritual pyre to complete the negotiations with the spirits."},
		["Present Yourself at the Ritual Pyre 1"] =
			{appendText=" in the village.", stepTextKey="Shaman Ulvoch requested that I present myself at the ritual pyre to complete the negotiations with the spirits."},
		[9] = 
			{appendStepText="", stepTextKey="Something went wrong during the ritual. I should speak to Shaman Ulvoch and find out what we need to do next."},
		["Talk to Shaman Ulvoch 3"] =
			{appendText=" at the tall ritual pyre in the village.", stepTextKey="Something went wrong during the ritual. I should speak to Shaman Ulvoch and find out what we need to do next."},
		[10] = 
			{appendStepText="In the village, the Shaman performed the ritual, but it failed. ", stepTextKey="Shaman Ulvoch doesn't know why the ritual failed, but suspects it might have something to do with the ritual pyre itself. I need to try and find a clue as to what went wrong."},
		["Search the Ritual Pyre"] =
			{appendText="."},
		[11] = 
			{appendStepText="In the village, ", stepTextKey="I found the components of a plant at the ritual site. I should report my findings to Apprentice Fialyn."},
		["Talk to Apprentice Fialyn 2"] =
			{appendText=" near the pyre about the horrid vine, the malformed root, and the misshapen tendril I found.", stepTextKey="I found the components of a plant at the ritual site. I should report my findings to Apprentice Fialyn."},
		[12] = 
			{appendStepText="", stepTextKey="Apprentice Fialyn thinks the source of the corrupted plant may lie in the Sanuarach Mine beneath Karthwasten. We need to go into the mine and investigate."},
		["Investigate the Sanuarach Mine"] =
			{appendText=". Its entrance is up the trail northwest of the village's ritual pyre. Inside, I should look up in the mine's southeastern tunnel."},
		[13] = 
			{appendStepText="Northwest of the village's ritual pyre, ", stepTextKey="Apprentice Fialyn and I made it inside the mine and found the corrupted plant. I should speak with her about what we should do next."},
		["Talk to Apprentice Fialyn 3"] =
			{appendText=" up in the southeastern tunnel of the mine.", stepTextKey="Apprentice Fialyn and I made it inside the mine and found the corrupted plant. I should speak with her about what we should do next."},
		[14] = 
			{appendStepText="", stepTextKey="Fialyn wants to burn all traces of the plant. We also need to destroy support pillars to secure the mine and make sure the Gray Host can no longer use it to farm the plant."},
		["Burn Netherroot Vines"] =
			{appendText=" \n\nOne is in the southeastern tunnel's corner and a second is close by in the corner to the west, in a cart. A third vine is in the mine's central cavern, and the fourth is in the northern cavern.\n"},
		["Destroy Support Pillars"] =
			{appendText=" \n\nThe westernmost cavern is a good place to damage pillars -- one on a platform in the southeast, one up in the southwest corner, and one up on the ritual platform between the braziers."},
		[15] = 
			{appendStepText="", stepTextKey="The plants are destroyed and the mine has been damaged enough to make it unusable by the Gray Host. I should return to Karthwasten so the shaman can complete the ritual of restoration for the wards."},
		["Return to Karthwasten"] =
			{appendText=". There is an exit from the mine's westernmost cavern in its northwest corner."},
		[16] = 
			{appendStepText="", stepTextKey="I should speak with Shaman Ulvoch and tell him that it should be safe to perform the restoration ritual now."},
		["Talk to Shaman Ulvoch 4"] =
			{appendText=" near the village's ritual pyre.", stepTextKey="I should speak with Shaman Ulvoch and tell him that it should be safe to perform the restoration ritual now."},
		[17] = 
			{appendStepText="", stepTextKey="As before, Shaman Ulvoch asked me to present myself at a pyre during the ritual. Hopefully now that Apprentice Fialyn and I destroyed the corrupted plants, the ritual will be successful."},
		["Present Yourself at the Ritual Pyre 2"] =
			{appendText=" in the village.", stepTextKey="As before, Shaman Ulvoch asked me to present myself at a pyre during the ritual. Hopefully now that Apprentice Fialyn and I destroyed the corrupted plants, the ritual will be successful."},
		[18] = 
			{appendStepText="", stepTextKey="It seems the restoration ritual was a success. I should talk to Apprentice Fialyn."},
		["Talk to Apprentice Fialyn 4"] =
			{appendText=" near the ritual pyre in the village.", stepTextKey="It seems the restoration ritual was a success. I should talk to Apprentice Fialyn."},
		[19] = 
			{appendStepText="", stepTextKey="The wards around Karthwasten have been restored. I should speak with Apprentice Fialyn."},
		["Talk to Apprentice Fialyn 5"] =
			{appendText=" at the ritual pyre in the village.", stepTextKey="The wards around Karthwasten have been restored. I should speak with Apprentice Fialyn."},
	},

    [GetQuestName(6586)] = { --"Betrayal at Briar Rock" --Jordakai
        [1] = 
            {appendStepText="In the southwestern mountains, southeast of Markarth and northwest of Briar Rock Wayshrine, I met three Reachfolk of the Hillhunter clan. ", stepTextKey="I agreed to help Medone by rescuing her people from the Thornroot clan. The survivors of Medone's clan are held in cages in the Briar Rock Ruins. I should free all the captives I can find."},
        ["Rescue Captives"] =
            {appendText=" \n\nI should look for cages in the areas up in the north, the south, and far west of the fortress."},
        [2] = 
            {appendStepText="In the southwestern mountain fortress of Briar Rock Ruins, ", stepTextKey="I have rescued all the members of Medone's clan I could find outside. They told me that their chieftain Faorin is imprisoned within the tower, I should find him."},
        ["Find Faorin"] =
            {appendText=" of the Hillhunter clan. He should be in the Dead Crone Tower up in the southwestern area of the old Nord ruins."},
        [3] = 
            {appendStepText="In the southwestern mountain fortress of Briar Rock Ruins, I searched the Dead Crone Tower up in the southwestern area of the old Nord ruins. ", stepTextKey="I located Chieftain Faorin in the tower at Briar Rock. I should talk to him."},
        ["Talk to Faorin"] =
            {appendText=" near his cage on an upper floor of the tower."},
        [4] = 
            {appendStepText="In the southwestern mountain fortress of Briar Rock Ruins, ", stepTextKey="I freed all the captured members of Medone's clan. All that remains for me is to burn down the briarheart tree the Thornroot clan uses for their rituals."},
        ["Burn the Briarheart Tree"] =
            {appendText=" at Dead Crone Overlook. I can reach the overlook through a western door up in Dead Crone Tower, the old Nord structure in the southwestern area of the fortress.\n\nFaorin, the Hillhunter clan chieftain, mentioned a hagraven matron may be near the tree."},
        [5] = 
            {appendStepText="In the southwest mountain fortress of Briar Rock Ruins, ", stepTextKey="I rescued Medone's people and burned the Thornroot clan's briarheart tree, preventing them from turning more Reachfolk into enslaved briarhearts. I should talk to Medone before I leave the area."},
        ["Talk to Medone 1"] =
            {appendText=". She is with her clan near the bridge outside Briar Rock Ruins.", stepTextKey="I rescued Medone's people and burned the Thornroot clan's briarheart tree, preventing them from turning more Reachfolk into enslaved briarhearts. I should talk to Medone before I leave the area."},
        [6] = 
            {appendStepText="At the southwestern mountain fortress of Briar Rock Ruins, ", stepTextKey="I rescued Medone's clan and punished the Thornroots by burning their briarheart tree. The Hillhunter clan is safe now. I should speak with Medone to learn the fate of her clan before leaving Briar Rock."},
        ["Talk to Medone 2"] =
            {appendText=" near the bridge outside the fortress.", stepTextKey="I rescued Medone's clan and punished the Thornroots by burning their briarheart tree. The Hillhunter clan is safe now. I should speak with Medone to learn the fate of her clan before leaving Briar Rock."},
    },


	[GetQuestName(6565)] = { --"By Love Betrayed" --Jordakai
		[1] = 
			{appendStepText="I spoke with a mercenary, Quintor, about a job he decided was too dangerous. ", stepTextKey="I should find Adusa-daro near the old Dwarven lift and find out more about what she needs help with."},
		["Find Adusa-daro 1"] =
			{appendText=" at a Dwarven arch near Reachwind Depths in the region's southeastern area, on the mountaintop east of Nalzthdbar Great Lift and south of the Rebel's Retreat Wayshrine.", stepTextKey="I should find Adusa-daro near the old Dwarven lift and find out more about what she needs help with."},
		[2] = 
			{appendStepText="On a southeastern mountaintop east of Nalzthdbar Great Lift and south across the Karth River from Rebel's Retreat, ", stepTextKey="I located Adusa-daro. Now I should talk to her and ask her about Kathad and the Lothid clan."},
		["Talk to Adusa-daro 1"] =
			{appendText=" at the Dwarven arch near Reachwind Depths.", stepTextKey="I located Adusa-daro. Now I should talk to her and ask her about Kathad and the Lothid clan."},
		[3] = 
			{appendStepText="On the southeastern mountaintop of Reachwind Depths, I spoke with the Khajiiti vampire from House Ravenwatch. ", stepTextKey="Adusa-daro wants me to meet her down below in the Dwarven ruins so we can find Kathad. The lift should descend into the cavern that houses the ruins of Reachwind Depths."},
		["Use the Dwarven Lift"] =
			{appendText=" in the nearby tower."},
		[4] = 
			{appendStepText="I entered the tower and found myself in a small cavern. ", stepTextKey="I should talk to Adusa-daro and ask about her plan for entering the Reachwind Depths Ruins."},
		["Talk to Adusa-daro 2"] =
			{appendText=".", stepTextKey="I should talk to Adusa-daro and ask about her plan for entering the Reachwind Depths Ruins."},
		[5] = 
			{appendStepText="After taking the lift from the southeastern mountaintop at the Dwarven tower of Reachwind Depths, ", stepTextKey="Adusa wants me to find an old sluice gate and use that to get inside the ruins the locals call the Reachwind Depths."},
		["Enter the Reachwind Depths Ruins"] =
			{appendText=". The sluice entry is to the west, on my right."},
		[6] = 
			{appendStepText="Through a sluice in the entry cavern of Reachwind Depths, ", stepTextKey="I entered the Dwarven ruins. Now I need to find a place where I can observe Adusa-daro's confrontation with the leader of the Lothid clan, Boss Trenlor."},
		["Find Boss Trenlor's Court"] =
			{appendText=" in the large southeastern chamber."},
		[7] = 
			{appendStepText="I entered Reachwind Depths ruins through a sluice and made my way to the southeastern chamber. ", stepTextKey="I found a place that overlooks Boss Trenlor's court. I should observe as Adusa talks to him."},
		["Observe the Confrontation"] =
			{appendText="."},
		[8] = 
			{appendStepText="I entered Reachwind Depths ruins through a sluice and made my way to the southeastern chamber. ", stepTextKey="Boss Trenlor had Adusa-daro tossed into the Deep Tombs. Adusa said that if that happened, it would be up to me to find her and rescue her."},
		["Find Adusa-daro 2"] =
			{appendText=". I should use the southern lift to reach the tombs and then search each chamber until I find her.", stepTextKey="Boss Trenlor had Adusa-daro tossed into the Deep Tombs. Adusa said that if that happened, it would be up to me to find her and rescue her."},
		[9] = 
			{appendStepText="I entered Reachwind Depths ruins through a sluice and made my way to the southeast, and then used the southern lift down to the tombs to reach the long, northern chamber. ", stepTextKey="I found Adusa-daro in the Deep Tombs. I should talk to her."},
		["Talk to Adusa-daro 3"] =
			{appendText=" in the southwestern alcove.", stepTextKey="I found Adusa-daro in the Deep Tombs. I should talk to her."},
		[10] = 
			{appendStepText="I entered Reachwind Depths ruins through a sluice and made my way to the southern lift to reach the Deep Tombs. I saw another vampire ahead of me. When I spoke with Adusa, she confirmed it was her friend. ", stepTextKey="Adusa-daro wants to search the Deep Tombs and locate Kathad. I should help her find him."},
		["Search for Kathad"] =
			{appendText=". He is likely heading for the small, far eastern chamber."},
		[11] = 
			{appendStepText="I entered Reachwind Depths ruins through a sluice and made my way to the southern lift to reach the Deep Tombs. Adusa-daro and I traveled to the far eastern chamber of the tombs. ", stepTextKey="We found Kathad in a storage chamber with another vampire. Adusa wants me to talk to him."},
		["Talk to Kathad 1"] =
			{appendText=".", stepTextKey="We found Kathad in a storage chamber with another vampire. Adusa wants me to talk to him."},
		[12] = 
			{appendStepText="I entered Reachwind Depths ruins through a sluice and made my way to the southern lift to reach the Deep Tombs. Adusa-daro and I traveled to the far eastern chamber of the tombs, the Storage Chamber. ", stepTextKey="Kathad refuses to leave until he helps Freyleth accomplish her plan to overthrow Boss Trenlor and provide a new direction for the Lothid clan. I should talk to Freyleth and learn about this plan."},
		["Talk to Freyleth 1"] =
			{appendText=", leaning against a crate on the floor. She appears injured.", stepTextKey="Kathad refuses to leave until he helps Freyleth accomplish her plan to overthrow Boss Trenlor and provide a new direction for the Lothid clan. I should talk to Freyleth and learn about this plan."},
		[13] = 
			{appendStepText="I entered Reachwind Depths ruins through a sluice and made my way to the southern lift to reach the Deep Tombs. Adusa-daro and I traveled to the far eastern storage chamber. ", stepTextKey="Kathad won't leave until he's sure the clan has a new leader. I agreed to help Freyleth accomplish her plan by acquiring a mushroom that grows in the Blinds, the caverns beneath the Deep Tombs. She can use the mushroom to weaken Boss Trenlor."},
		["Enter the Blinds"] =
			{appendText=" using the lift in the southernmost cavern of the tombs."},
		[14] = 
			{appendStepText="I entered Reachwind Depths ruins and made my way to the southern lift to reach the Deep Tombs. Adusa-daro and I entered The Blinds using a lift in the southernmost chamber of the tombs. ", stepTextKey="I need to search the Blinds, the caves beneath the Deep Tombs, to find the darkcap mushroom that Freyleth needs to weaken Boss Trenlor and accomplish her plan."},
		["Find the Darkcap Mushroom"] =
			{appendText=" in the large, southern cavern."},
		[15] = 
			{appendStepText="I entered Reachwind Depths ruins and made my way to the southern lift to reach the Deep Tombs. Adusa-daro and I entered The Blinds using a lift in the southernmost chamber of the tombs. ", stepTextKey="This huge section of the Blinds seems the likely place to find a darkcap mushroom. I should look around."},
		["Gather the Darkcap Mushroom"] =
			{appendText="."},
		[16] = 
			{appendStepText="I entered Reachwind Depths ruins and made my way to the southern lift to reach the Deep Tombs. Adusa-daro and I entered The Blinds using a lift in the southernmost chamber of the tombs. In the southern cavern, ", stepTextKey="I gathered the darkcap mushroom for Freyleth. Now I need to find the lift that leads to the servant's quarters so I can meet Kathad and Freyleth."},
		["Find the Lift"] =
			{appendText=" in the northwestern cavern of The Blinds."},
		[17] = 
			{appendStepText="I entered Reachwind Depths ruins and made my way to the southern lift to reach the Deep Tombs. Adusa-daro and I entered The Blinds using a lift in the southernmost chamber of the tombs. At the north end of the northwestern cavern, ", stepTextKey="I found the lift that Freyleth mentioned. I should use it so I can meet her and Kathad in the servant's quarters."},
		["Use the Lift"] =
			{appendText=" built by the Dwarves."},
		[18] = 
			{appendStepText="I entered Reachwind Depths ruins, made my way to the southern lift to reach the Deep Tombs. Then I entered The Blinds using a lift in the southernmost chamber of the tombs, found the mushrooms, and used a lift in the northwestern cavern to enter the Servant's Quarters. ", stepTextKey="Adusa wants to talk before we meet with Kathad and Freyleth."},
		["Talk to Adusa-daro 4"] =
			{appendText=".", stepTextKey="Adusa wants to talk before we meet with Kathad and Freyleth."},
		[19] = 
			{appendStepText="I entered Reachwind Depths ruins, made my way to the southern lift to reach the Deep Tombs. Then I entered The Blinds using a lift in the southernmost chamber of the tombs, found the mushrooms, and used a lift in the northwestern cavern to enter the Servant's Quarters. ", stepTextKey="We found Kathad and Freyleth in the servant's quarters. I should talk to him."},
		["Talk to Kathad 2"] =
			{appendText=".", stepTextKey="We found Kathad and Freyleth in the servant's quarters. I should talk to him."},
		[20] = 
			{appendStepText="I entered Reachwind Depths ruins and made my way to the southern lift to reach the Deep Tombs. Then I entered The Blinds using a lift in the southernmost chamber of the tombs, found the mushrooms, and used a lift in the northwestern cavern to enter the Servant's Quarters. ", stepTextKey="Kathad gave me a disguise so I can blend in as one of Boss Trenlor's servants. I should put it on before I leave this chamber."},
		["Put on the Servant Disguise"] =
			{appendText=". I have it in my pack."},
		[21] = 
			{appendStepText="In Reachwind Depths ruins, I traveled to the southern lift to enter the Deep Tombs, used another southern lift to reach the Blinds, and then used a northwestern lift to the Servant's Quarters. ", stepTextKey="Now that I'm wearing the disguise, I need to sneak past the clan vampires and reach Boss Trenlor's court so I can drop the darkcap mushroom into his chalice of blood."},
		["Go to Boss Trenlor's Court"] =
			{appendText=", using the eastern lift in the Servant's Quarters. In the westernmost room of the upper halls, I can find the entrance to Boss Trenlor's Court. I should avoid clan vampires to maintain my disguise. The table with Trenlor's chalice is near his throne."},
		[22] = 
			{appendStepText="In Reachwind Depths ruins, I traveled to the southern lift to enter the Deep Tombs, used another southern lift to reach the Blinds, and then took a northwestern lift to the Servant's Quarters. Then I made my way to the western chamber of the upper halls. ", stepTextKey="Now that I reached Boss Trenlor's court, I should place the darkcap mushroom in his chalice of blood."},
		["Place the Darkcap Mushroom in the Chalice"] =
			{appendText=" on the Dwarven table near his throne."},
		[23] = 
			{appendStepText="In Reachwind Depths, I traveled to the southern lift to enter the Deep Tombs, used another southern lift to reach the Blinds, and then took a northernwest lift to the servant's quarters. I made my way through the upper halls. In his Court, ", stepTextKey="I placed the darkcap mushroom in Boss Trenlor's chalice of blood. Now I should take the chalice and present it to him."},
		["Take Boss Trenlor's Chalice"] =
			{appendText=" from the Dwarven table near the throne."},
		[24] = 
			{appendStepText="In Reachwind Depths, I traveled to the southern lift to enter the Deep Tombs, used another southern lift to reach the Blinds, and then took a northernwest lift to the servant's quarters. I made my way through the upper halls. In his Court, ", stepTextKey="I should give the chalice of blood tainted with the darkcap mushroom to Boss Trenlor."},
		["Give Boss Trenlor the Chalice"] =
			{appendText="."},
		[25] = 
			{appendStepText="In Reachwind Depths ruins, I traveled to the southern lift to enter the Deep Tombs, used another southern lift to reach the Blinds, and then took a northwestern lift to the Servant's Quarters. Then I made my way to the western chamber of the upper halls. In his Court, ", stepTextKey="I should wait and see what the blood tainted with darkcap mushroom does to Boss Trenlor."},
		["Wait for Boss Trenlor"] =
			{appendText="."},
		[26] = 
			{appendStepText="In Reachwind Depths ruins, I traveled to the southern lift to enter the Deep Tombs, used another southern lift to reach the Blinds, and then took a northwestern lift to the Servant's Quarters. Then I made my way to the western chamber of the upper halls and into the Court. ", stepTextKey="Freyleth lied to us. The darkcap mushroom didn't weaken Boss Trenlor. It killed him! I should talk to her and get an explanation."},
		["Talk to Freyleth 2"] =
			{appendText=" by the throne.", stepTextKey="Freyleth lied to us. The darkcap mushroom didn't weaken Boss Trenlor. It killed him! I should talk to her and get an explanation."},
		[27] = 
			{appendStepText="", stepTextKey="After Freyleth tricked us into poisoning Boss Trenlor and took over the Lothid clan, Adusa left in disgust. I should meet her outside."},
		["Meet Adusa-daro Outside"] =
			{appendText=" of Reachwind Depths ruins. She took the lift at the north end of the throne room. I should use the entry cavern's northern lift to reach the surface. Adusa is probably by the Dwarven arch again."},
		[28] = 
			{appendStepText="", stepTextKey="I helped Adusa-daro convince Kathad to leave the Lothid clan. I should talk to her."},
		["Talk to Adusa-daro 5"] =
			{appendText=", standing with Kathad by the Dwarven arch near the Reachwind Depth's entrance tower.", stepTextKey="I helped Adusa-daro convince Kathad to leave the Lothid clan. I should talk to her."},
	},

	[GetQuestName(6575)] = { --"Endeavor in the Gloom" --Jordakai
		[1] = 
			{appendStepText="At Gloomreach, southeast of Markarth and across the Karth River south of the Lost Valley Wayshrine, ", stepTextKey="Psijic Calis asked me to accompany him to investigate the strange plant life inside the cave."},
		["Examine Strange Vegetation"] =
			{appendText=" near the waterfall in the small northeastern cavern."},
		[2] = 
			{appendStepText="In Gloomreach, southeast of Markarth and across the Karth River south of the Lost Valley Wayshrine, I went to the small northeastern cavern with a waterfall. ", stepTextKey="I examined the strange vegetation. I should speak to Psijic Calis and find out what he thinks is going on here."},
		["Talk to Psijic Calis 1"] =
			{appendText=".", stepTextKey="I examined the strange vegetation. I should speak to Psijic Calis and find out what he thinks is going on here."},
		[3] = 
			{appendStepText="At Gloomreach, southeast of Markarth and across the Karth River south of the Lost Valley Wayshrine, ", stepTextKey="Psijic Calis identified pockets of tonal disturbance inside the cave. We need to contain these disturbances before they get any worse."},
		["Contain Western Tonal Disturbance"] =
			{appendText=" by deactivating the Dwarven Amplifier in the small cavern south of the large western cavern. \n"},
		["Contain Southern Tonal Disturbance"] =
			{appendText=" by deactivating the Dwarven Amplifier in the large central southern cavern. \n"},
		["Contain Eastern Tonal Disturbance"] =
			{appendText=" by deactivating the Dwarven Amplifier in the large southeastern cavern."},
		[4] = 
			{appendStepText="At Gloomreach, southeast of Markarth and across the Karth River south of the Lost Valley Wayshrine, ", stepTextKey="Psijic Calis believes he can sense Master Pythis's magic here. I should look around to see if I can find any clues he might have left behind."},
		["Search for Master Pythis"] =
			{appendText="'s journal. I should begin looking in this small, southwestern cavern with a waterfall."},
		[5] = 
			{appendStepText="At Gloomreach, southeast of Markarth and across the Karth River south of the Lost Valley Wayshrine, ", stepTextKey="I located Master Pythis's journal. I should speak to Psijic Calis about what it contains."},
		["Talk to Psijic Calis 2"] =
			{appendText=" in the small, southwestern cavern with a waterfall.", stepTextKey="I located Master Pythis's journal. I should speak to Psijic Calis about what it contains."},
		[6] = 
			{appendStepText="At Gloomreach, southeast of Markarth and across the Karth River south of the Lost Valley Wayshrine, Psijic Calis devised a plan to stop Master Pythis. ", stepTextKey="We need to transport the relic back to Artaeum before it causes more damage. I should deactivate any of the Dwemer Amplifiers I see."},
		["Help Transport the Relic"] =
			{appendText=" after finding it. Psijic Calis senses the relic is nearby. I should go to the large, western cavern and look for a secure enclosure, likely down in the lowest, southeastern area of the cavern."},
		[7] = 
			{appendStepText="At Gloomreach, southeast of Markarth and across the Karth River south of the Lost Valley Wayshrine, we found the relic in a southeastern enclosure on the lowest level of the large, western cavern. ", stepTextKey="Another member of the Order came to Psijic Calis's aid. The two of them safely secured the relic. I should speak to Psijic Calis now that the danger has past."},
		["Talk to Psijic Calis 3"] =
			{appendText=". I should speak with Master Larama, too.", stepTextKey="Another member of the Order came to Psijic Calis's aid. The two of them safely secured the relic. I should speak to Psijic Calis now that the danger has past."},
		[8] = 
			{appendStepText="From the large, western cavern at Gloomreach, southeast of Markarth and across the Karth River south of the Lost Valley Wayshrine, the relic was returned to Artaeum. ", stepTextKey="Now that we solved the problem here in Gloomreach, I should speak to Psijic Calis about what happens next."},
		["Talk to Psijic Calis 4"] =
			{appendText=".", stepTextKey="Now that we solved the problem here in Gloomreach, I should speak to Psijic Calis about what happens next."},
	},

    [GetQuestName(6553)] = { --"Help Wanted in Markarth" --Jordakai
        [1] = 
            {appendStepText="", stepTextKey="The notice directed me to talk to Consul Cardea in the Reach city of Markarth for more details."},
        ["Talk to Consul Cardea 1"] =
            {appendText=", an Imperial, author, and administrator. She stands near Markarth's job brokers. They are northwest of the Guild Traders, upstairs on a terrace by the Dwarven pumping mechanism above a waterfall, in the city's southwest.", stepTextKey="The notice directed me to talk to Consul Cardea in the Reach city of Markarth for more details."},
        [2] = 
            {appendStepText="In southwest Markarth, ", stepTextKey="I should ask Consul Cardea how I go about picking up one of these daily jobs."},
        ["Talk to Consul Cardea 2"] =
            {appendText=", an Imperial, author, and administrator. She stands near Markarth's job brokers. They are northwest of the Guild Traders, upstairs on a terrace by the Dwarven pumping mechanism above a waterfall.", stepTextKey="I should ask Consul Cardea how I go about picking up one of these daily jobs."},
    },


    [GetQuestName(6562)] = { --"Lost in the Reach" --Jordakai
        [1] = 
            {appendStepText="In the northern mountains, near the side of the trail south of Druadach Redoubt, I met a female Nord. She told me how she and her husband have been prospecting for gold in The Reach. ", stepTextKey="Hiretta gave me a whistle and told me to use it to summon Snowy. She said if I find Snowy, I might find Bolfalgar, too."},
        ["Use Snowy's Whistle"] =
            {appendText=". Hiretta said Snowy and her husband went northeast. The rocky overhang above the blacksmith's anvil at Druadach Redoubt might be a good place to start. The view of the area should be better and I can blow the whistle there."},
        [2] = 
            {appendStepText="On the rocky overhang above the blacksmith's anvil at Druadach Redoubt, ", stepTextKey="Snowy came running as soon as I blew the whistle. I should praise Snowy and tell her she's a good girl so she'll trust me."},
        ["Praise Snowy"] =
            {appendText=", Hiretta's white bunny."},
        [3] = 
            {appendStepText="On the rocky overhang at Druadach Redoubt, praising the bunny worked. ", stepTextKey="Snowy wants me to follow her. Maybe she'll lead me to Bolfalgar."},
        ["Follow Snowy"] =
            {appendText=". She raced off to the east towards a small box canyon north of the Witchborne Ritual Site."},
        [4] = 
            {appendStepText="I followed the white bunny east of Druadach Redoubt and down to a small box canyon north of the Witchborne Ritual Site. ", stepTextKey="Snowy led me to Bolfalgar. I should talk to him and make sure he's all right."},
        ["Talk to Bolfalgar 1"] =
            {appendText=", standing in the brush near a lone tree.", stepTextKey="Snowy led me to Bolfalgar. I should talk to him and make sure he's all right."},
        [5] = 
            {appendStepText="I followed the white bunny east of Druadach Redoubt and down to a small box canyon north of the Witchborne Ritual Site. Now that Hiretta's pet and her husband are safe, ", stepTextKey="I should make sure Bolfalgar and Snowy can get back to Hiretta on their own before I take my leave."},
        ["Talk to Bolfalgar 2"] =
            {appendText=", standing in the brush near a lone tree.", stepTextKey="I should make sure Bolfalgar and Snowy can get back to Hiretta on their own before I take my leave."},
    },

	[GetQuestName(6591)] = { --"The Lost Scout's Report" --Jordakai
		[1] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach, I found a page from a scout. ", stepTextKey="After waiting for a rescue that didn't come, Falkfyr headed west from the Dwarven door to search for high ground. I should start by searching for any prominent overlooks west of the northern door into Blackreach."},
		["Find the High Ground"] =
			{appendText=" southeast of the Arkthzand Wayshrine near the edge of an illuminated, broken bridge."},
		[2] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach, southeast of the Arkthzand Wayshrine at the edge of the broken bridge, I found another page. ", stepTextKey="Falkfyr made it safely to a good vantage point, where he left another parchment note. I should read it and see where he went next."},
		["Read Falkfyr's Notes, Page 2"] =
			{appendText=".", stepTextKey="Falkfyr made it safely to a good vantage point, where he left another parchment note. I should read it and see where he went next."},
		[3] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach, southeast of the Arkthzand Wayshrine, I read another note. ", stepTextKey="Low on provisions, Falkfyr was forced to venture into the chaurus-infested wilds and made for the river to the north. He needed to find a safe place to refill his canteen. I should search the riverbank for another note."},
		["Find the Note by the Stream"] =
			{appendText=" on the west riverbank, below another broken bridge south of Arkthzand Wayshrine and northwest of a grotto."},
		[4] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach, on the western riverbank below the broken bridge, northwest of Ghostlight Grotto and south of Arkthzand Wayshrine, ", stepTextKey="I found another note from Falkfyr in the shadow of a dwarven platform. I should read it to see where he went next."},
		["Read Falkfyr's Notes, Page 3"] =
			{appendText=".", stepTextKey="I found another note from Falkfyr in the shadow of a dwarven platform. I should read it to see where he went next."},
		[5] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach, on the western riverbank below the broken bridge, northwest of Ghostlight Grotto and south of Arkthzand Wayshrine, ", stepTextKey="Falkfyr found water. He also learned that the chaurus would leave him alone if he was smeared in chaurus ichor. However, he still lacked food, so he headed to the nearby ruins to forage. I should look there next."},
		["Search the Dwarven Ruins"] =
			{appendText=" up by the curved wall of the large western Dwemer library ruin. I should look south of the broken bridge's northeastern gateway, west of Ghostlight Grotto."},
		[6] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach, by the curved wall of the western Dwemer library ruins, just south of its northeastern gateway, ", stepTextKey="I found another of Falkfyr's notes outside the Dwarven ruins. He made it this far, at least. I should read the note and learn what happened next."},
		["Read Falkfyr's Notes, Page 4"] =
			{appendText=".", stepTextKey="I found another of Falkfyr's notes outside the Dwarven ruins. He made it this far, at least. I should read the note and learn what happened next."},
		[7] = 
			{appendStepText="", stepTextKey="Falkfyr failed to find food in the Dwarven ruins, and he was forced to eat Blackreach mushrooms to survive. Luckily, they didn't poison him. Refreshed, he set off for a grove of fungal trees to the south. I should look there for his next note."},
		["Search the Fungal Grove"] =
			{appendText=", south and east across the river into a narrow area. I should look along the south side not far from the eastern riverbank."},
		[8] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach, across the river, south of Ghostlight Grotto and east of the large western ruin, I looked along the south side of a narrow area, not far from the eastern riverbank. ", stepTextKey="Falkfyr left another note in an odd grove of fungal trees. I should see what it says."},
		["Read Falkfyr's Notes, Page 5"] =
			{appendText=".", stepTextKey="Falkfyr left another note in an odd grove of fungal trees. I should see what it says."},
		[9] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach, southeast of the large western ruin, I found another note in the narrow cavern east of the river. ", stepTextKey="Falkfyr's latest note was a jumble of strange words and phrases. Perhaps eating mushrooms affected his mind. The note mentioned something he called the Great Oom off to the south. I may find out more if I head in that direction."},
		["Find the Great Oom"] =
			{appendText=". I should search further to the southeast in this narrow cavern, at least to where the cavern turns to the north."},
		[10] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach, at the curve in the narrow, southeastern cavern, ", stepTextKey="I found yet another note left by Falkfyr. This one lies at the base of one of Blackreach's giant mushrooms. I should read it and see if it offers a clue as to where Falkfyr went next."},
		["Read Falkfyr's Notes, Page 6"] =
			{appendText=".", stepTextKey="I found yet another note left by Falkfyr. This one lies at the base of one of Blackreach's giant mushrooms. I should read it and see if it offers a clue as to where Falkfyr went next."},
		[11] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach, I read another note at the foot of a giant mushroom in the curve of the narrow, southeastern cavern. ", stepTextKey="Falkfyr's latest note was odd and disturbing. A steady diet of Blackreach mushrooms clearly affected him, but he mentioned a new home to the north … and treasure. I should see if he left something behind."},
		["Find Falkfyr's Home"] =
			{appendText=". I should go north from the southeastern giant mushroom, going up in the left cavern, northwest of a wayshrine. His new home should be in a grove or thicket of mushrooms."},
		[12] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach at the Mistgloom Thicket, beneath a vibrant, glowing fungus, ", stepTextKey="I found one last note, an abandoned backpack, and a skeleton, likely Falkfyr's. Hopefully, this last note will offer some insight into the state of his mind at the end."},
		["Read Falkfyr's Notes, Page 7"] =
			{appendText=".", stepTextKey="I found one last note, an abandoned backpack, and a skeleton, likely Falkfyr's. Hopefully, this last note will offer some insight into the state of his mind at the end."},
		[13] = 
			{appendStepText="In the Arkthzand Cavern of Blackreach at the Mistgloom Thicket, beneath a vibrant, glowing fungus, ", stepTextKey="Falkfyr's last notes were the ravings of a madman. He seemed to believe that he was a spore and that he would grow into an oom. Despite his grim fate, there may be treasure and other spoils left in his pack. I should see what I can find."},
		["Search the Scout's Pack"] =
			{appendText="."},
	},

	[GetQuestName(6589)] = { --"Red Eagle's Song"		--Jordakai
		[1] = 
			{appendStepText="I spoke with a Nord scout in Markarth. ", stepTextKey="I need to go to the Reachwind Ritual Site and meet Lyris Titanborn."},
		["Go to the Reachwind Ritual Site"] =
			{appendText=" in the region's south. It is up in the rocky ledges, northeast of the southern road that leads to Valthume, northeast of Vateshran Hollows and south of Reachwind Depths."},
		[2] = 
			{appendStepText="I traveled to the rocky ledges along the southern road that leads to Valthume, northeast of Vateshran Hollows and south of Reachwind Depths. ", stepTextKey="Near the Reachwind Ritual Site, I spotted an Orc rifling through the pockets of a dead Gray Host vampire. I should talk to him and see what he knows about Lyris Titanborn."},
		["Talk to Gorgrath"] =
			{appendText=" up on a ledge on the north side of the road."},
		[3] = 
			{appendStepText="", stepTextKey="An Orc that Lyris saved from a band of Gray Host vampires said she found a letter that directed her to Valthume. I should head there and see if I can catch up with her."},
		["Go to Valthume"] =
			{appendText=". According to Gorgrath, I suspect I am far behind Lyris and Sai Sahan in their journey. I should go northeast and check along the road west of the Shadefeather Clan Camp in case Lyris and Sai left Valthume and are heading northwest."},
		[4] = 
			{appendStepText="I was winding my way east up the road, west of the Shadefeather Clan Camp. ", stepTextKey="On the way to Valthume, I spotted a Reachfolk taking her frustrations out on another dead Gray Host vampire. I should talk to her and find out if she saw Lyris Titanborn."},
		["Talk to Tisfira"] =
			{appendText=" up on the rocks on the south side of the road."},
		[5] = 
			{appendStepText="West of Shadefeather Clan Camp on the south side of the road, some distance northwest of Valthume, I met Tisfira. ", stepTextKey="A Reachfolk at Valthume said she sent the \"blond giant\" and the \"handsome Redguard\" to Hroldan Ring to talk to a vateshran. I should look for Lyris there."},
		["Go to Hroldan Ring"] =
			{appendText=". The stone arches of the Ring are on a footpath north of the river. It is west and a little north of Lost Valley Wayshrine."},
		[6] = 
			{appendStepText="North of the river in the region's central area, ", stepTextKey="I found Lyris Titanborn at Hroldan Ring. I should talk to her."},
		["Talk to Lyris Titanborn 1"] =
			{appendText=".", stepTextKey="I found Lyris Titanborn at Hroldan Ring. I should talk to her."},
		[7] = 
			{appendStepText="At Hroldan Ring, ", stepTextKey="Lyris asked me to go to Gloomreach and help Sai Sahan look for the third letter between the vampire leaders of the Gray Host. He thinks it contains clues to a connection between Rada al-Saran, a Reach hero, and Sai's martial tradition."},
		["Search Gloomreach"] =
			{appendText=" caverns, across the river south of Lost Valley Wayshrine. Its wooden entrance door is east of the Shadefeather Clan Camp and west of the stone bridge spanning the river. \n\nSai is likely in the narrow, northwest passage of the large northeastern cavern with a skyshard high above."},
		[8] = 
			{appendStepText="Through a crevice in the large northeastern cavern, ", stepTextKey="I found a concealed chamber hidden in the depths of Gloomreach Cavern. I should see what's inside."},
		["Search the Concealed Chamber"] =
			{appendText=" behind the wooden door."},
		[9] = 
			{appendStepText="Through a crevice in the large northeastern cavern, I found and entered a small chamber. ", stepTextKey="Sai Sahan entered the concealed chamber after I recovered the third letter he and Lyris were looking for. I should talk to him."},
		["Talk to Sai Sahan"] =
			{appendText="."},
		[10] = 
			{appendStepText="I met Sai in a concealed chamber in Gloomreach. ", stepTextKey="We found the third letter, but it didn't provide the details Sai Sahan needs to understand how Faolan Red Eagle helped Rada al-Saran regain his Shehai. I need to go to Red Eagle Redoubt and find a vateshran who may know more of the tale."},
		["Find a Vateshran at Red Eagle Redoubt"] =
			{appendText=". I should follow the footpath northeast, up the mountainside from the river bridge at Rebel's Retreat, the old Nord ruin in the eastern mountains."},
		[11] = 
			{appendStepText="I traveled up the mountain, northeast of Rebel's Retreat in the eastern mountains. ", stepTextKey="At Red Eagle Redoubt, a vateshran noticed me and asked what I seek. I should talk to her."},
		["Talk to Vateshran Ovra"] =
			{appendText=" near the cooking fire."},
		[12] = 
			{appendStepText="In the eastern mountains, ", stepTextKey="Lyris and Sai arrived at the redoubt. I should let them know what the vateshran told me."},
		["Talk to Lyris Titanborn 2"] =
			{appendText=" about the cave beneath Red Eagle's Redoubt.", stepTextKey="Lyris and Sai arrived at the redoubt. I should let them know what the vateshran told me."},
		[13] = 
			{appendStepText="At Red Eagle's Redoubt in the eastern mountains, I spoke with Vateshran Ovra. ", stepTextKey="I need to find the cave beneath the redoubt. Lyris and Sai will meet me after she talks to the vateshran."},
		["Go to the Cave Beneath the Redoubt"] =
			{appendText=". The Sacred Cave's entrance is in the redoubt, east of the cooking fire."},
		[14] = 
			{appendStepText="At Red Eagle's Redoubt in the eastern mountains, I entered the Sacred Cave. ", stepTextKey="Lyris and Sai arrived at the cave. I should talk to Lyris."},
		["Talk to Lyris Titanborn 3"] =
			{appendText=".", stepTextKey="Lyris and Sai arrived at the cave. I should talk to Lyris."},
		[15] = 
			{appendStepText="At Red Eagle's Redoubt in the eastern mountains, we entered the Sacred Cave. ", stepTextKey="Lyris thinks the dense foliage may be hiding the secret we came to this cave to learn. I should burn it away."},
		["Burn the Dense Foliage"] =
			{appendText=" covering the inscribed, standing stones along the path."},
		[16] = 
			{appendStepText="At Red Eagle's Redoubt in the eastern mountains, we entered the Sacred Cave and are following its path. ", stepTextKey="Words are carved into stone pillars in the cave. I need to clear more of the foliage so Sai and Lyris can read the next verse of the song."},
		["Find the Next Verse"] =
			{appendText=" inscribed on a standing stone."},
		[17] = 
			{appendStepText="At Red Eagle's Redoubt in the eastern mountains, we entered the Sacred Cave. We have found verses of a song inscribed on standing stones. ", stepTextKey="There should be one final verse to the song in the cave. I should burn the dense foliage to reveal it."},
		["Find the Final Verse"] =
			{appendText="."},
		[18] = 
			{appendStepText="At Red Eagle's Redoubt in the eastern mountains, we entered the Sacred Cave and discovered the verses to a song. ", stepTextKey="Lyris thinks she understands what the ancient song is trying to tell us. I should talk to her."},
		["Talk to Lyris Titanborn 4"] =
			{appendText=".", stepTextKey="Lyris thinks she understands what the ancient song is trying to tell us. I should talk to her."},
		[19] = 
			{appendStepText="At Red Eagle's Redoubt in the eastern mountains, we discovered the ancient song of Red Eagle. ", stepTextKey="Lyris asked me to meet them outside the cave. She wants to discuss what we learned with Sai in private."},
		["Wait Outside the Cave"] =
			{appendText=" in the redoubt."},
		[20] = 
			{appendStepText="In a sacred cave at Red Eagle's Redoubt in the eastern mountains, Sai Sahan, Lyris, and I discovered Red Eagle's song. ", stepTextKey="Lyris thinks she knows what the song is trying to tell us. I should ask her if Sai Sahan knows what he needs to do next to claim his spirit sword."},
		["Talk to Lyris Titanborn 5"] =
			{appendText=" outside the cave, near the cooking fire.", stepTextKey="Lyris thinks she knows what the song is trying to tell us. I should ask her if Sai Sahan knows what he needs to do next to claim his spirit sword."},
	},

    [GetQuestName(6598)] = { --"The Symbol of Gulibeg" --Jordakai
        [1] = 
            {appendStepText="Near Druadach Redoubt in the northern mountains, I found a body with a pack and a letter. ", stepTextKey="According to the note I found, Ansdurran stole a sacred relic that was supposed to be delivered to High Shaman Glynroch in Markarth. I should pick up the relic and take it to him."},
        ["Retrieve the Symbol of Gulibeg"] =
            {appendText=" from Ansdurran's pack by his body."},
        [2] = 
            {appendStepText="Near Druadach Redoubt in the northern mountains, I found a body with a pack and letter. ", stepTextKey="I retrieved the sacred relic. I should take it to the shrine in Markarth and let High Shaman Glynroch know what happened to his apprentice."},
        ["Find High Shaman Glynroch"] =
            {appendText=" in the Shrine of the Hunt-Father. The shrine's entry is high up at the western end of the large central structure of the city, south of the Stonevault Repository and west of The Hunter's Repose. From its front porch, the twin falls of Understone Keep provide a beautiful view."},
        [3] = 
            {appendStepText="High up at the western end of the large central structure of the city, south of the Stonevault Repository and west of The Hunter's Repose, ", stepTextKey="I found High Shaman Glynroch in Markarth. I should deliver the sacred relic to him and tell him that Apprentice Layren is dead."},
        ["Talk to High Shaman Glynroch 1"] =
            {appendText=" in the Shrine of the Hunt-Father. I should give him the relic I found, the Symbol of Gulibeg.", stepTextKey="I found High Shaman Glynroch in Markarth. I should deliver the sacred relic to him and tell him that Apprentice Layren is dead."},
        [4] = 
            {appendStepText="High up at the western end of the large central structure of the city, south of the Stonevault Repository and west of The Hunter's Repose, I gave the High Shaman the Symbol of Gulibeg. It is a relic that represents the Quick Fox aspect of Hircine. ", stepTextKey="I should talk to High Shaman Glynroch and see if there's a reward for returning the sacred relic."},
        ["Talk to High Shaman Glynroch 2"] =
            {appendText=" at the Shrine of the Hunt-Father.", stepTextKey="I should talk to High Shaman Glynroch and see if there's a reward for returning the sacred relic."},
    },

    [GetQuestName(6596)] = { --"The Symbol of Hrokkibeg" --Jordakai
        [1] = 
            {appendStepText="On the riverbank down in the gorge between two bridges, northeast of Briar Rock Ruins and northwest of the Nalzthdbar Great Lift, I found a body. ", stepTextKey="According to the note I found, Apprentice Gwerina was trying to bring a sacred relic to High Shaman Glynroch in Markath. I should pick up the relic so I can deliver it there."},
        ["Retrieve the Symbol of Hrokkibeg"] =
            {appendText=" from Gwerina's pack."},
        [2] = 
            {appendStepText="On the riverbank down in the gorge between two bridges, northeast of Briar Rock Ruins and northwest of the Nalzthdbar Great Lift, I found a pack near the body of Apprentice Gwerina. ", stepTextKey="I retrieved the sacred relic. I should take it to the shrine in Markarth and let High Shaman Glynroch know what happened to his apprentice."},
        ["Find High Shaman Glynroch"] =
            {appendText=" in the Shrine of the Hunt-Father. The shrine's entry is high up at the western end of the large central structure of the city, south of the Stonevault Repository and west of The Hunter's Repose. From its front porch, the twin falls of Understone Keep provide a beautiful view."},
        [3] = 
            {appendStepText="High up on the western end of the large central structure of the city, south of the Stonevault Repository and west of The Hunter's Repose, ", stepTextKey="I found High Shaman Glynroch in Markarth. I should deliver the sacred relic and tell him Apprentice Gwerina is dead."},
        ["Talk to High Shaman Glynroch 1"] =
            {appendText=" in the Shrine of the Hunt-Father. I should give him the relic I found, the Symbol of Hrokkibeg.", stepTextKey="I found High Shaman Glynroch in Markarth. I should deliver the sacred relic and tell him Apprentice Gwerina is dead."},
        [4] = 
            {appendStepText="High up at the western end of the large central structure of the city, south of the Stonevault Repository and west of The Hunter's Repose, I gave the High Shaman the Symbol of Gulibeg. It is a relic that represents the Mighty Bear aspect of Hircine. ", stepTextKey="I should talk to High Shaman Glynroch and see if there's a reward for returning the sacred relic."},
        ["Talk to High Shaman Glynroch 2"] =
            {appendText=" at the Shrine of the Hunt-Father.", stepTextKey="I should talk to High Shaman Glynroch and see if there's a reward for returning the sacred relic."},
    },

    [GetQuestName(6599)] = { --"The Symbol of Storihbeg" --Jordakai
        [1] = 
            {appendStepText="Under a pine tree near the eastern end of the blocked road southeast of the Lost Valley Wayshrine, I found a body with a pack and a letter. ", stepTextKey="According to the note I found, Kitza-Enoo stole a relic sacred to the Reachmen from Apprentice Egvarn before he could deliver it to High Shaman Glynroch in Markarth. I should search his pack for the relic."},
        ["Retrieve the Symbol of Storihbeg"] =
            {appendText=" from Kitza-Enoo's pack by his body."},
        [2] = 
            {appendStepText="At a pine tree near the eastern end of the blocked road southeast of the Lost Valley Wayshrine, ", stepTextKey="I recovered the stolen relic. I should take it to the shrine in Markarth and let High Shaman Glynroch know what happened to Apprentice Egvarn."},
        ["Find High Shaman Glynroch"] =
            {appendText=" in the Shrine of the Hunt-Father. The shrine's entry is high up at the western end of the large central structure of the city, south of the Stonevault Repository and west of The Hunter's Repose. From its front porch, the twin falls of Understone Keep provide a beautiful view."},
        [3] = 
            {appendStepText="High up at the western end of the large central structure of the city, south of the Stonevault Repository and west of The Hunter's Repose, ", stepTextKey="I found High Shaman Glynroch in Markarth. I should deliver the stolen relic and tell him know Apprentice Egvarn is dead."},
        ["Talk to High Shaman Glynroch 1"] =
            {appendText=" in the Shrine of the Hunt-Father. I should give him the relic I found, the Symbol of Storihbeg.", stepTextKey="I found High Shaman Glynroch in Markarth. I should deliver the stolen relic and tell him know Apprentice Egvarn is dead."},
        [4] = 
            {appendStepText="High up at the western end of the large central structure of the city, south of the Stonevault Repository and west of The Hunter's Repose, I gave the High Shaman the Symbol of Gulibeg. It is a relic that represents the King of the Wolf aspect of Hircine. ", stepTextKey="I should talk to High Shaman Glynroch and see if there's a reward for returning the stolen relic."},
        ["Talk to High Shaman Glynroch 2"] =
            {appendText=" at the Shrine of the Hunt-Father.", stepTextKey="I should talk to High Shaman Glynroch and see if there's a reward for returning the stolen relic."},
    },

    [GetQuestName(6609)] = { --"The Symbol of Uricanbeg" --Jordakai
        [1] = 
            {appendStepText="I have retrieved the other relics for the Shrine of the Hunt-Father in Markarth. Now, ", stepTextKey="I need to go to Lost Valley Redoubt and find Apprentice Orla and the remaining symbol of Hircine."},
        ["Find Apprentice Orla"] =
            {appendText=" and Keeva, her white wolf. They should be at the southeastern end of the Karth River, at Lost Valley Redoubt in the region's far southeast. Once I get there, I should search the high southwestern area of the redoubt."},
        [2] = 
            {appendStepText="In the region's far southeast, up in the high mountains at Lost Valley Redoubt, I spotted Keeva, the white wolf. Then, ", stepTextKey="I found Appentrice Orla, but it looks like she's been wounded. I should talk to her and see if she found the Symbol of Uricanbeg."},
        ["Talk to Apprentice Orla"] =
            {appendText=" near the river in the redoubt's high southwest."},
        [3] = 
            {appendStepText="Up in the high southwest of Lost Valley Redoubt, I spoke with Orla. ", stepTextKey="Apprentice Orla was injured trying to reclaim the Symbol of Uricanbeg. She asked my help to retrieve it, but warned me that a powerful minotaur guards it at the tower on the rise. I should fight or sneak my way past to find the sacred relic."},
        ["Retrieve the Symbol of Uricanbeg"] =
            {appendText=", a drum that represents the Great Stag aspect of Hircine."},
        [4] = 
            {appendStepText="At Lost Valley Redoubt in the far southeastern mountains, ", stepTextKey="I retrieved the Symbol of Uricanbeg from the minotaur's lair. I should deliver it to High Shaman Glynroch at the Shrine of the Hunt-Father in Markarth."},
        ["Talk to High Shaman Glynroch"] =
            {appendText=" in the Shrine of the Hunt-Father. I should give him the sacred relic, the drum known as the Symbol of Uricanbeg, the Great Stag.\n\nThe shrine's entry is high up at the western end of the large central structure of the city, south of the Stonevault Repository and west of The Hunter's Repose. From its front porch, the twin falls of Understone Keep provide a beautiful view."},
    },

	[GetQuestName(6590)] = { --"Vows and Oaths"--Jordakai
		[1] = 
			{appendStepText="Near Hroldan Ring, ", stepTextKey="Chief-of-Chiefs Cannear asked me offer my blessing to Eslyn and Madearn. I should find them in the handfasting cave to the north of Hroldan Ring."},
		["Go to the Handfasting Cave"] =
			{appendText=" with its torchlit, tusk-arch entry.\nBefore I go I should speak with the four Reachmen standing with the Chief-of-Chiefs."},
		[2] = 
			{appendStepText="Near Hroldan Ring's northern stone arch, ", stepTextKey="I went to the handfasting cave to offer the couple a blessing, but Eslyn and Madearn weren't there. I should see if I can locate any clues as to where they may have gone."},
		["Find Eslyn and Madearn 1"] =
			{appendText=" after searching the cave.", stepTextKey="I went to the handfasting cave to offer the couple a blessing, but Eslyn and Madearn weren't there. I should see if I can locate any clues as to where they may have gone."},
		[3] = 
			{appendStepText="In the Handfasting Cave near Hroldan Ring's northern stone arch, ", stepTextKey="Eslyn and Madearn left a note for the chief-of-chiefs that suggests they abandoned the handfasting and ran away. I should let Chief-of-Chiefs Cannear know."},
		["Talk to Chief-of-Chiefs Cannear 1"] =
			{appendText=". She remains with the others at the small clearing southwest of the cave and west of Hroldan Ring.", stepTextKey="Eslyn and Madearn left a note for the chief-of-chiefs that suggests they abandoned the handfasting and ran away. I should let Chief-of-Chiefs Cannear know."},
		[4] = 
			{appendStepText="West of Hroldan Ring, in a small clearing, ", stepTextKey="Chief-of-Chiefs Cannear asked me to find Eslyn and Madearn and convince them to return to Hroldan Ring. She suggested I search north of Hroldan Ring for them."},
		["Find Eslyn and Madearn 2"] =
			{appendText=". I should start by following the trail north, through the Reachmen's stone arch. As Reachfolk, they would leave natural trail markers. I should find a pile of sticks north of the arch, a feather east of a stone cairn, and then look northeast on a footpath for a small pouch to show a change of direction. From there, I should go southeast up a hill to a tree with a cloth fragment nearby and then east a short distance, down the hill to an old campsite.", stepTextKey="Chief-of-Chiefs Cannear asked me to find Eslyn and Madearn and convince them to return to Hroldan Ring. She suggested I search north of Hroldan Ring for them."},
		[5] = 
			{appendStepText="At an old campsite northeast of Hroldan Ring and south of a harrowed ritual site, ", stepTextKey="I found Eslyn and Madearn. I should speak with them."},
		["Talk to Eslyn 1"] =
			{appendText=" of the Eagleseer Clan.\n", stepTextKey="I found Eslyn and Madearn. I should speak with them."},
		["Talk to Madearn 1"] =
			{appendText=" of the Six-Fords Clan.", stepTextKey="I found Eslyn and Madearn. I should speak with them."},
		[6] = 
			{appendStepText="At an old campsite northeast of Hroldan Ring and south of a harrowed ritual site, ", stepTextKey="I asked Eslyn and Madearn what more they know about the feud between their clans. I should listen to what they have to say."},
		["Listen to Eslyn and Madearn"] =
			{appendText="."},
		[7] = 
			{appendStepText="I spoke with the clan chiefs' children at an old campsite northeast of Hroldan Ring. ", stepTextKey="Eslyn and Madearn think if they find a way to end the feud between their clans, they won't need to go through with the handfasting. We need to find a vateshran to learn more about the feud's origin."},
		["Find Vateshran Barth"] =
			{appendText=" at his campsite, southeast of a wayshrine up in the far southwestern mountains. If he is not there, I should search for clues by walking from the campfire back toward the wayshrine. Perhaps I'll find his fighting stick, a shillelagh, or a dagger.\n\nI should speak with Eslyn and Madearn again before I leave."},
		[8] = 
			{appendStepText="Southeast of the southwestern Briar Rock Wayshrine, ", stepTextKey="I found the camp, but the Vateshran is nowhere to be seen. The intended couple thinks he's been captured by the Thornroot clan and taken into the nearby ruins. I need to search the ruins to find him."},
		["Search for Vateshran Barth"] =
			{appendText=" at the Briar Rock Ruins, northwest of its wayshrine. If he is being held captive, it may be up in the ruin's western Briar Rock Crypts."},
		[9] = 
			{appendStepText="In the northern chamber of the Briar Rock Crypts in the western area of Briar Rock Ruins, ", stepTextKey="I found the vateshran tied up in Briar Rock Ruins. I should free him."},
		["Free Vateshran Barth"] =
			{appendText="."},
		[10] = 
			{appendStepText="From the northern chamber of the Briar Rock Crypts in the western area of the ruins, ", stepTextKey="Vateshran Barth wants me to guide him out of the Briar Rock Ruins to safety."},
		["Escort Vateshran Barth to Safety"] =
			{appendText="."},
		[11] = 
			{appendStepText="", stepTextKey="Now that I safely escorted the vateshran out of the ruins, I should speak with him."},
		["Talk to Vateshran Barth 1"] =
			{appendText=", just inside the main gates of Briar Rock Ruins in the region's mountainous southwest.", stepTextKey="Now that I safely escorted the vateshran out of the ruins, I should speak with him."},
		[12] = 
			{appendStepText="", stepTextKey="Vateshran Barth agreed to tell me more about the origin of the Six-Ford and Eagleseer feud. I should meet him back at his camp to speak with him further."},
		["Go to Vateshran Barth's Camp"] =
			{appendText=" in the southwestern mountains, just southeast of the Briar Rock Wayshrine."},
		[13] = 
			{appendStepText="Just southeast of the Briar Rock Wayshrine in the southwestern mountains, ", stepTextKey="I made it back to the vateshran's camp. I should speak with him about the feud now."},
		["Talk to Vateshran Barth 2"] =
			{appendText=".", stepTextKey="I made it back to the vateshran's camp. I should speak with him about the feud now."},
		[14] = 
			{appendStepText="At his camp near the Briar Rock Wayshrine, Vateshran Barth shared the story of how the Eagleseer Clan and the Six-Fords Clan began to feud with each other. ", stepTextKey="Eslyn and Madearn think they can resolve their clans' feud by repairing an ancient heirloom, the Lover's Coil. I should search the Karthspire Lea for a fragment of it."},
		["Travel to Karthspire Lea"] =
			{appendText=", the site of an early battle between the Eagleseer and Six-Fords Clans. It is between the river and the road west of the Rebel's Retreat Wayshrine, east of the city of Markath, and far northwest of Hroldan Ring. A stone memorial stands near swords, posts, and dirt mounds in the small area near a cold-flame brazier on the road."},
		[15] = 
			{appendStepText="Near a cold-flame brazier, north of a bridge on the river-side of the road west of Rebel's Retreat Wayshrine, ", stepTextKey="I made it to Karthspire Lea. I should look around for a fragment of the Lover's Coil."},
		["Find the Lover's Coil Fragment"] =
			{appendText=" by digging through the dirt piles."},
		[16] = 
			{appendStepText="West of Rebel's Retreat Wayshrine, at the memorial site between the river and the road, ", stepTextKey="I found the fragment of the Lover's Coil just as Madearn appeared at Karthspire Lea. I should speak with him."},
		["Talk to Madearn 2"] =
			{appendText=".", stepTextKey="I found the fragment of the Lover's Coil just as Madearn appeared at Karthspire Lea. I should speak with him."},
		[17] = 
			{appendStepText="", stepTextKey="Madearn wants me to find Eslyn. I should head to Faolan's Ire where she went to search for the other fragment of the Lover's Coil."},
		["Find Eslyn"] =
			{appendText=". Faolin Ire is southeast of Hroldan Ring and just southeast of a wayshrine above the road that follows the river's north bank to the region's far east. Eslyn may be up on a ridge southeast of the wayshrine."},
		[18] = 
			{appendStepText="Southeast of the Lost Valley Wayshrine, on a ridge north of the road, ", stepTextKey="I found Eslyn, but she needs help recovering the Lover's Coil fragment at Faolan's Ire. It's currently inside a Giant's camp. I should see if I can retrieve it."},
		["Gather the Lover's Coil Fragment at Faolan's Ire"] =
			{appendText=". The giants have made their camp around an ancient Reachfolk cairn, beneath their usual mammoth's skull."},
		[19] = 
			{appendStepText="Southeast of the Lost Valley Wayshrine, ", stepTextKey="I retreived the Lover's Coil fragment from the Giant camp. I should let Eslyn know."},
		["Talk to Eslyn 2"] =
			{appendText=", crouching up on the ridge west of the giant's camp.", stepTextKey="I retreived the Lover's Coil fragment from the Giant camp. I should let Eslyn know."},
		[20] = 
			{appendStepText=" ", stepTextKey="I should meet Eslyn, Madearn, and Vateshran Barth near Hroldan Ring."},
		["Go to Hroldan Ring"] =
			{appendText="'s clearing on the west side. It's where I first met the clan leaders."},
		[21] = 
			{appendStepText="", stepTextKey="Now that Chief-of-Chiefs Cannear knows the story of the Lover's Coil, I should speak with her and inform her of Eslyn and Madearn's plan to end the feud in lieu of the handfasting."},
		["Talk to Chief-of-Chiefs Cannear 2"] =
			{appendText=" in the small clearing on the west side of Hroldan Ring.", stepTextKey="Now that Chief-of-Chiefs Cannear knows the story of the Lover's Coil, I should speak with her and inform her of Eslyn and Madearn's plan to end the feud in lieu of the handfasting."},
		[22] = 
			{appendStepText="In the small clearing west of Hroldan Ring, ", stepTextKey="I decided to support Eslyn and Madearn and not force them to go along with the handfasting, despite objections from Chief-of-Chiefs Cannear. I should speak to Eslyn and Madearn about my decision."},
		["Talk to Eslyn 3"] =
			{appendText=".\n", stepTextKey="I decided to support Eslyn and Madearn and not force them to go along with the handfasting, despite objections from Chief-of-Chiefs Cannear. I should speak to Eslyn and Madearn about my decision."},
		["Talk to Madearn 3"] =
			{appendText=".\n\nThey are both in the Handfasting Cave, near Hroldan Ring's northern stone arch. Its tusk-arch entrance is illuminated by torches.", stepTextKey="I decided to support Eslyn and Madearn and not force them to go along with the handfasting, despite objections from Chief-of-Chiefs Cannear. I should speak to Eslyn and Madearn about my decision."},
		[23] = 
			{appendStepText="In the small clearing west of Hloran Ring, ", stepTextKey="I should watch Eslyn and Madearn present the restored Lover's Coil to their clans at Hroldan Ring."},
		["Watch Eslyn and Madearn Confront Their Clans"] =
			{appendText="."},
		[24] = 
			{appendStepText="", stepTextKey="The clan chiefs weren't convinced by Eslyn and Madearn's appeal. I should speak with Vateshran Barth about the future of the Six-Ford and Eagleseer clans."},
		["Talk to Vateshran Barth 3"] =
			{appendText=" in the small clearing west of Hroldan Ring. ", stepTextKey="The clan chiefs weren't convinced by Eslyn and Madearn's appeal. I should speak with Vateshran Barth about the future of the Six-Ford and Eagleseer clans."},
		[25] = 
			{appendStepText="At the small clearing on Hroldan Ring's west side, ", stepTextKey="I decided to convince Eslyn and Madearn to go through with the handfasting. I should speak with them about my decision."},
		["Talk to Eslyn 4"] =
			{appendText=".\n", stepTextKey="I decided to convince Eslyn and Madearn to go through with the handfasting. I should speak with them about my decision."},
		["Talk to Madearn 4"] =
			{appendText=".\n\nThey are both in the Handfasting Cave, near Hroldan Ring's northern stone arch. Its tusk-arch entrance is illuminated by torches.", stepTextKey="I decided to convince Eslyn and Madearn to go through with the handfasting. I should speak with them about my decision."},
		[26] = 
			{appendStepText="", stepTextKey="I should watch Eslyn and Madearn complete the handfasting rite at Hroldan Ring."},
		["Watch the Handfasting Rite"] =
			{appendText="."},
		[27] = 
			{appendStepText="On Hroldan Ring's west side, ", stepTextKey="Eslyn and Madearn nearly completed their handfasting, but Madearn decided he could not break his vow to Drisene and both clans have resumed their feud. I should speak with Vateshran Barth about the future of the clans."},
		["Talk to Vateshran Barth 4"] =
			{appendText=" in the small clearing.", stepTextKey="Eslyn and Madearn nearly completed their handfasting, but Madearn decided he could not break his vow to Drisene and both clans have resumed their feud. I should speak with Vateshran Barth about the future of the clans."},
		[28] = 
			{appendStepText="In the small clearing west of Hroldan Ring, ", stepTextKey="Eslyn and Madearn completed the handfasting rite, ensuring an end to their clans' feud. I should speak with Vateshran Barth about the future of the Six-Fords and Eagleseers."},
		["Talk to Vateshran Barth 5"] =
			{appendText=".", stepTextKey="Eslyn and Madearn completed the handfasting rite, ensuring an end to their clans' feud. I should speak with Vateshran Barth about the future of the Six-Fords and Eagleseers."},
	},
-- 		=========================================================================
--		  The Reach - Daily Quest 
-- 		=========================================================================

    [GetQuestName(6559)] = { --"Halt the Harrowstorms" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion near the waterfall, northwest of the Guild Traders, I spoke with the Reachfolk warrior, Nelldena. ", stepTextKey="When I locate a harrowstorm ritual site, I need to destroy the witch pikes and gray reliquary in order to disrupt the harrowstorm ritual."},
        ["Disrupt a Harrowstorm"] =
            {appendText=". A swirling tornado of void-black and blood-red, it often fills the land and sky of The Reach. \n\n- The Ragnvald Ritual Site is north of Markarth and southwest of the Bthardamz Dwarven ruin. \n- The Witchborne Ritual Site is in the northern mountains, northwest of Karthwasten, northeast of Arkthzand Great Lift, and southeast of Druabach Redoubt. \n- The Reachwind Ritual Site is in the south, southwest of the Dwarven tower of Reachwind Depths, and north of Vateshran Hollows. \n- The Harrowed Haunt Ritual Site is in the eastern mountains, northwest of the Lost Valley Wayshrine, and northeast of Hroldan Ring."},
        [2] = 
            {appendStepText="In the Reach, ", stepTextKey="I disrupted a harrowstorm ritual. I should return to Nelldena to report my success."},
        ["Talk to Nelldena"] =
            {appendText=", a Reachfolk warrior. She is at the small pavilion near the waterfall, northwest of the Guild Traders in Markarth."},
    },

    [GetQuestName(6585)] = { --"Discarded Treasures" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion northwest of the Guild Traders, I spoke with Gwenyfe, an archer with the Stonehands. I agreed to help protect The Reach. Now, ", stepTextKey="I need to find the Dwrarven construct and destroy it. I should also retrieve any scrap it leaves behind."},
        ["Destroy the Dwarven Construct"] =
            {appendText=" at Sentinal Point.\n"},
        ["Retrieve Dwarven Scrap"] =
            {appendText=" \n\nSentinel Point is up on a ridge in the southernmost curve of a cavern in the south-central area of Arkthzand Cavern in Blackreach. It is not far from the Nalzthdbar Great Lift, southwest of the Nighthollow Wayshrine. The Lift can be accessed in the southern mountains of The Reach, southeast of Markarth."},
        [2] = 
            {appendStepText="Near the Nalzthdbar Great Lift in the south of Arkthzand Cavern in Blackreach, ", stepTextKey="I destroyed the odd Dwarven construct and collected the scrap it distributed. I should return to Markarth and claim my reward."},
        ["Talk to Gwenyfe"] =
            {appendText=", the Stonehands archer at the small pavilion near the waterfall, northwest of the Guild Traders."},
    },


    [GetQuestName(6556)] = { --"Namira's Perversions" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion northwest of the Guild Traders, I spoke with Gwenyfe, an archer with the Stonehands, and agreed to help protect The Reach. Now, ", stepTextKey="I should find the witch matron and disrupt her ritual. I also need to rescue any Reachfolk she plans to sacrifice."},
        ["Disrupt the Ritual"] =
            {appendText=" at Four Skull Lookout in the eastern mountains.\n"},
        ["Rescue Captives"] =
            {appendText=" \n\nFour Skull Lookout is just northwest of Red Eagle's Redoubt and north of Rebel's Retreat."},
        [2] = 
            {appendStepText="At Four Skull Lookout near Red Eagle's Redoubt in the eastern mountains, ", stepTextKey="I disrupted the witch matron's ritual and freed her captives. Now I should claim my reward."},
        ["Talk to Gwenyfe"] =
            {appendText=", the Stonehands archer at the small pavilion near the waterfall, northwest of the Guild Traders in Markarth."},
    },

    [GetQuestName(6582)] = { --"Ruptures in the Reach" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion northwest of the Guild Traders, I spoke with Gwenyfe, an archer with the Stonehands. I agreed to help protect The Reach. Now, ", stepTextKey="I need to locate the witch matron and put a stop to her activities. I should also close any tears in the area with the charm the Stonehands gave me."},
        ["Kill the Witch Matron"] =
            {appendText=" at Four Skull Lookout in the eastern mountains.\n"},
        ["Close Magical Tears"] =
            {appendText=" \n\nThe magical tears appear as lavender wisps. Four Skull Lookout is just northwest of Red Eagle's Redoubt and north of Rebel's Retreat."},
        [2] = 
            {appendStepText="At Four Skull Lookout near Red Eagle's Redoubt in the eastern mountains, ", stepTextKey="I disrupted the witch matron's ritual and closed the void tears.I should return to Markarth for my reward."},
        ["Talk to Gwenyfe"] =
            {appendText=", the Stonehands archer at the small pavilion near the waterfall, northwest of the Guild Traders."},
    },

    [GetQuestName(6583)] = { --"The Scholar's Request" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion northwest of the Guild Traders, I spoke with Gwenyfe, an archer with the Stonehands. I agreed to protect The Reach. ", stepTextKey="I need to find the cave where the Dwarven construct is and destroy it. I should also use the Dwarven rod on any Dwarven spiders I see to render them docile."},
        ["Destroy the Dwarven Construct"] =
            {appendText=", the Dynastor Supreme.\n"},
        ["Use Rod on Spiders"] =
            {appendText=" \n\nThe rod works best on inactive Dwarven spiders. \n\nSentinel Point is up on a ridge in the southernmost curve of a cavern in the south-central area of Arkthzand Cavern in Blackreach. It is not far from the Nalzthdbar Great Lift and is southwest of the Nighthollow Wayshrine. The Lift can be accessed in the southern mountains of The Reach, southeast of Markarth."},
        [2] = 
            {appendStepText="Near the Nalzthdbar Great Lift in the south of Arkthzand Cavern in Blackreach, ", stepTextKey="I destroyed the unusual Dwarven construct and verified the rod makes Dwarven spiders docile. I should return to Markarth and claim my reward."},
        ["Talk to Gwenyfe"] =
            {appendText=", the Stonehands archer at the small pavilion near the waterfall, northwest of the Guild Traders."},
    },

    [GetQuestName(6584)] = { --"Guides to the Deep" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion northwest of the Guild Traders, I spoke with Gwenyfe, an archer with the Stonehands. I agreed to protect The Reach. ", stepTextKey="I need to find this odd Dwarven construct and destroy it. I also need to locate any beacons it put down and destroy them as well."},
        ["Destroy the Dwarven Construct"] =
            {appendText=", the Dynastor Supreme.\n"},
        ["Destroy Dwarven Beacons"] =
            {appendText=" \n\nThe beacons look similar to tall lanterns and should be near the monstrous construct. \n\nSentinel Point is up on a ridge in the southernmost curve of the cavern in the south-central area of Arkthzand Cavern in Blackreach. It is not far from the Nalzthdbar Great Lift and is southwest of the Nighthollow Wayshrine. The Lift can be accessed in the southern mountains of The Reach, southeast of Markarth."},
        [2] = 
            {appendStepText="Near the Nalzthdbar Great Lift in southern Arkthzand Cavern in Blackreach, ", stepTextKey="I destroyed the unusual Dwarven construct and the odd beacons it put down. I should return to Markarth and claim my reward."},
        ["Talk to Gwenyfe"] =
            {appendText=", the Stonehands archer at the small pavilion near the waterfall, northwest of the Guild Traders."},
    },

    [GetQuestName(6581)] = { --"Notes of the Void" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion northwest of the Guild Traders, I spoke with Gwenyfe, an archer with the Stonehands. I agreed to help protect The Reach. Now, ", stepTextKey="I need to stop the Reach clan's witch matron from performing the dangerous ritual. I should also recover any notes of hers I can find so that the Stonehands can destroy them."},
        ["Disrupt the Ritual"] =
            {appendText=" at Four Skull Lookout in the eastern mountains.\n"},
        ["Gather Ritual Notes"] =
            {appendText=" \n\nThe Witch Matron's Ritual Notes are scrolls, usually sitting on tables. Four Skull Lookout is just northwest of Red Eagle's Redoubt and north of Rebel's Retreat."},
        [2] = 
            {appendStepText="At Four Skull Lookout near Red Eagle's Redoubt in the eastern mountains, ", stepTextKey="I stopped the ritual and retrieved the remaining notes. I should claim my reward."},
        ["Talk to Gwenyfe"] =
            {appendText=", the Stonehands archer at the small pavilion near the waterfall, northwest of the Guild Traders in Markarth."},
    },

    [GetQuestName(6573)] = { --"Unhatched Menace" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion near the waterfall northwest of the Guild Traders, I spoke with the Bosmer job broker, Bralthahawn. He had some work available. Now, ", stepTextKey="I need to find and destroy the mage's strange egg."},
        ["Destroy the Strange Egg"] =
            {appendText=". It is likely being kept in a secluded place. I should search for a wooden storage area up on a ledge in the southern cavern of Gloomreach."},
        [2] = 
            {appendStepText="In Gloomreach caverns, ", stepTextKey="I destroyed the egg the crazed mage posessed. I should return to Bralthahawn and claim my reward."},
        ["Talk to Bralthahawn"] =
            {appendText=". The Bosmer job broker is at the small pavilion near the waterfall, northwest of the Guild Traders in Markarth."},
    },

    [GetQuestName(6557)] = { --"Wild Talismans" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion near the waterfall northwest of the Guild Traders, I spoke with the Bosmer job broker, Bralthahawn. I will be going to the ruins south of Markarth in the southwestern mountains. ", stepTextKey="I need to find and retrieve the talismans worn by the Wildblood warriors."},
        ["Gather Wildblood Warrior Talismans"] =
            {appendText=" \n\nI should look for tattered Wildblood sacks near the upper, northern cages and then in the Briar Rock Crypts, near an altar in a lower Draugr chamber."},
        [2] = 
            {appendStepText="At the ruins, ", stepTextKey="I gathered the Wildblood talismans that Bralthahawn requested. I should deliver them to him and claim my reward."},
        ["Talk to Bralthahawn"] =
            {appendText=". The Bosmer job broker is at the small pavilion near the waterfall, northwest of the Guild Traders in Markarth."},
    },


    [GetQuestName(6569)] = { --"What's Hers is Ours" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion near the waterfall northwest of the Guild Traders, I spoke with the Bosmer job broker, Bralthahawn. Now, ", stepTextKey="I should find the lair of the Thornroot clan's hagraven matron and take her totem."},
        ["Gather the Hagraven Totem"] =
            {appendText=" by a brazier at the base of an arch in Dead Crone Overlook. The matron may be at the overlook at the top of the Dead Crone Tower in the upper, southwestern area of Briar Rock Ruins. The ruins are in the southwestern mountains, far south of Markarth."},
        [2] = 
            {appendStepText="On the Dead Crone Overlook atop the tower in the Briar Rock Ruins, ", stepTextKey="I retrieved the hagraven matron's totem. I should return this to Bralthahawn."},
        ["Talk to Bralthahawn"] =
            {appendText=". The Bosmer job broker is at the small pavilion near the waterfall, northwest of the Guild Traders in Markarth."},
    },

    [GetQuestName(6571)] = { --"Magic Mycology" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion near the waterfall northwest of the Guild Traders, I spoke with the Bosmer job broker, Bralthahawn. Now, ", stepTextKey="I must enter Gloomreach and gather the mushrooms."},
        ["Gather the Mushrooms"] =
            {appendText=" \n\nThe entrance to Gloomreach is south across the Karth River from the Lost Valley Wayshrine in the southeast. I should look for the white mushrooms in the small northern cavern, as well as the eastern passages and caverns."},
        [2] = 
            {appendStepText="In the caverns of Gloomreach, ", stepTextKey="I gathered the mushroom samples that Bralthahawn asked for. I should return to Markarth."},
        ["Talk to Bralthahawn"] =
            {appendText=". The Bosmer job broker is at the small pavilion near the waterfall, northwest of the Guild Traders."},
    },


    [GetQuestName(6567)] = { --"The Tainted Briarheart" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion near the waterfall northwest of the Guild Traders, I spoke with the Bosmer job broker, Bralthahawn. I will be going to the Briar Rock Ruins in the mountains south of Markarth. ", stepTextKey="I need to find the tools the Thornroot shamans use to turn their captives into briarhearts and destroy them."},
        ["Destroy Ritual Tools"] =
            {appendText=" \n\nThe glowing, blood-red tool boxes may be at campsites and cages in the courtyards, or in the western Briar Rock Crypts, or, more often, up in the southwestern Dead Crone's Tower at Briar Rock Ruins."},
        [2] = 
            {appendStepText="At Briar Rock Ruins in the southwestern mountains, ", stepTextKey="I destroyed the Thornroot shamans tools. I should return to Bralthahawn and claim my reward."},
        ["Talk to Bralthahawn"] =
            {appendText=". The Bosmer job broker is at the small pavilion near the waterfall, northwest of the Guild Traders in Markarth."},
    },

    [GetQuestName(6572)] = { --"Strange Contamination" --Jordakai
        [1] = 
            {appendStepText="In Markarth, at the small pavilion near the waterfall northwest of the Guild Traders, I spoke with the Bosmer job broker, Bralthahawn. Now, ", stepTextKey="I should enter Gloomreach and gather samples of the fungal mold that the Gloomspore animals produce."},
        ["Gather Fungal Mold Samples"] =
            {appendText=" \n\nThe entrance to Gloomreach is south across the Karth River from the Lost Valley Wayshrine in the southeast. \n\nI should look for the Gloomspore Fungal Mold, a dark-capped mushroom, in the northeastern and southeastern tunnels and caverns, and also in the large, western cavern."},
        [2] = 
            {appendStepText="In the caverns of Gloomreach, ", stepTextKey="I gathered the fungal mold samples in Gloomreach. I should return it to Bralthahawn and claim my reward."},
        ["Talk to Bralthahawn"] =
            {appendText=". The Bosmer job broker is at the small pavilion near the waterfall, northwest of the Guild Traders in Markarth."},
    },

    [GetQuestName(6603)] = { --"Alone in the Dark" --Jordakai
        [1] = 
            {appendStepText="The Wayward Guardians, Arana's witch-rebels, are seen as the defenders of The Reach. I met Ardanir, a Wayward Guardian, by the south wall of The Hunter's Repose in Markarth. ", stepTextKey="Ardanir asked me to descend into the Arkthzand Cavern and rescue Reach exiles that have been captured by the blind creatures that live down there. According to a scout, the camp is near an underground river."},
        ["Rescue Missing Exiles"] =
            {appendText=" \n\nI should begin my search in Ghostlight Grotto, by the fork in the western river of Arkthzand Cavern of Blackreach."},
        [2] = 
            {appendStepText="At the Falmer camp in Ghostlight Grotto in Arkthzand Cavern of Blackreach, ", stepTextKey="I rescued two of the missing exiles, and retrieved a necklace from a third exile who was already dead. I should return to Markarth and let Ardanir know."},
        ["Talk to Ardanir"] =
            {appendText=". He should be outside by the south wall of The Hunter's Repose."},
    },

    [GetQuestName(6604)] = { --"Defenders of the Reach" --Jordakai
        [1] = 
            {appendStepText="The Wayward Guardians, Arana's witch-rebels, are seen as the defenders of The Reach. I met Ardanir, a Wayward Guardian, by the south wall of The Hunter's Repose in Markarth. ", stepTextKey="I need to descend into Nchuand-Zel and gather Gray Host sigils by defeating Gray Host forces."},
        ["Gather Gray Host Sigils"] =
            {appendText=" \n\nThe entrance to Nchuand-Zel is through the southern chamber of Understone Keep in the city."},
        [2] = 
            {appendStepText="In Nchuand-Zel, ", stepTextKey="I gathered the Gray Host sigils. I should return to Markarth and deliver them to Ardanir to show him I was successful."},
        ["Talk to Ardanir"] =
            {appendText=". He should be outside by the south wall of The Hunter's Repose."},
    },

    [GetQuestName(6600)] = { --"Remnants of the Deep Folk" --Jordakai
        [1] = 
            {appendStepText="The Wayward Guardians, Arana's witch-rebels, are seen as the defenders of The Reach. I met Ardanir, a Wayward Guardian, by the south wall of The Hunter's Repose in Markarth. ", stepTextKey="I should travel to Bthardamz and gather Dwarven scrap for the Wayward Guardians."},
        ["Gather Dwarven Scrap"] =
            {appendText=" \n\nPiles of scrap can be found on the stone platforms of Bthardamz, up in the northwestern mountains. The Dwarven ruin is north of the North Markarth Wayshrine and south of the Druadach Mountain Wayshrine."},
        [2] = 
            {appendStepText="At Bthardamz in the Druadach Mountains, ", stepTextKey="I gathered the Dwarven scrap. I should return to Markarth and deliver it to Ardanir."},
        ["Talk to Ardanir"] =
            {appendText=". He should be outside by the south wall of The Hunter's Repose."},
    },

    [GetQuestName(6605)] = { --"The Language of the Night" --Jordakai
        [1] = 
            {appendStepText="The Wayward Guardians, Arana's witch-rebels, are seen as the defenders of The Reach. I met Ardanir, a Wayward Guardian, by the south wall of The Hunter's Repose in Markarth. ", stepTextKey="Ardanir asked me to travel to Nighthollow Keep and find scrolls dealing with Nighthollow magic, along with the tome that will help translate their ancient language."},
        ["Gather Nighthollow Scrolls"] =
            {appendText=" \n\nThe scrolls will be in the chambers and hallways of the keep. Each releases latent magicka like small firelies rising in the air.\n"},
        ["Gather Tome of Void Runes"] =
            {appendText=" from the keep's northeastern study.\n\nNighthollow Keep is in the eastern area of Arkthzand Cavern of Blackreach. Travel via wayshrine to the Nighthollow Wayshrine in Arkthzand Cavern is convenient. Or the Nalzthdbar Great Lift in the southern mountains can be used."},
        [2] = 
            {appendStepText="In eastern Arkthzand Cavern of Blackreach, ", stepTextKey="I gathered the Nighthollow scrolls and a tome from Nighthollow Keep. I should return to Markarth and deliver them to Ardanir."},
        ["Talk to Ardanir"] =
            {appendText=". He should be outside by the south wall of The Hunter's Repose."},
    },

    [GetQuestName(6602)] = { --"The Light of Arkthzand" --Jordakai
        [1] = 
            {appendStepText="The Wayward Guardians, Arana's witch-rebels, are seen as the defenders of The Reach. I met Ardanir, a Wayward Guardian, by the south wall of The Hunter's Repose in Markarth. ", stepTextKey="I need travel to the Library of Arkthzand in Blackreach and gather gemstones from the Dwarven constructs that patrol the grounds."},
        ["Gather Arkthzand Gemstones"] =
            {appendText=" \n\nThe Library of Arkthzand is in the western area of Arkthzand Cavern of Blackreach."},
        [2] = 
            {appendStepText="In the courtyard of the Library of Arkthzand in Blackreach's Arkthzand Cavern, ", stepTextKey="I gathered the gemstones for Ardanir and the Wayward Guardians. I should return to Markarth and deliver them."},
        ["Talk to Ardanir"] =
            {appendText=". He should be outside by the south wall of The Hunter's Repose."},
    },

    [GetQuestName(6606)] = { --"The Lost Shrine"--Jordakai
        [1] = 
            {appendStepText="The Wayward Guardians, Arana's witch-rebels, are seen as the defenders of The Reach. I met Ardanir, a Wayward Guardian, by the south wall of The Hunter's Repose in Markarth. He said the Shrine of Lorkh reminds the Reachfolk of their will to live despite the certainty of death. ", stepTextKey="I need to travel to the Shrine of Lorkh at the Lost Valley Redoubt and use the water from the Karth to cleanse the site."},
        ["Cleanse the Shrine of Lorkh"] =
            {appendText=" using the Vial of Karth Water from Ardanir. The ancient, inscribed stone shrine is in the redoubt's southeast, east of the river and its bridge in the high mountains.\n\nThe Lost Valley Redoubt is far to the southeast of Markarth, high in the mountains, and south across the Karth River from the Lost Valley Wayshrine."},
        [2] = 
            {appendStepText="", stepTextKey="I cleansed the Shrine of Lorkh in the Lost Valley Redoubt with the pure water of the Karth. I should return to Markarth and let Ardanir know it's done."},
        ["Talk to Ardanir"] =
            {appendText=". He should be outside by the south wall of The Hunter's Repose."},
    },

    [GetQuestName(6601)] = { --"To Burn Away Evil" --Jordakai
        [1] = 
            {appendStepText="The Wayward Guardians, Arana's witch-rebels, are seen as the defenders of The Reach. I met Ardanir, a Wayward Guardian, by the south wall of The Hunter's Repose in Markarth. ", stepTextKey="I need to travel to Bthar-Zel to gather enchanted silver ore for the Wayward Guardians."},
        ["Gather Enchanted Silver Ore"] =
            {appendText=" \n\nThe silver ore is probably in the central chamber of the ruins.\n\nBthar-Zel lies in the far northern Druadach Mountains, across the Dwarven bridge known as Deep Folk Crossing. The Druadach Mountain Wayshrine is a short distance away. Its entrance, once warded by ancient Star Tales, is now open."},
        [2] = 
            {appendStepText="From the ancient Dwarven ruins in the northern Druadach Mountains, ", stepTextKey="I gathered enchanted silver ore from Brhar-Zel. I should return to Markarth and deliver it to Ardanir and the Wayward Guardians."},
        ["Talk to Ardanir"] =
            {appendText=". He should be outside by the south wall of The Hunter's Repose."},
    },

-- ==================================================================================================================================================
--	SOLSTICE																															Undaunted
-- ==================================================================================================================================================

-- 		=========================================================================
--		  MAIN QUEST SOLSTICE
-- 		=========================================================================

[GetQuestName(7314)] = { --"The Stirk Fellowship" --aashiana
		[1] = 
			{appendStepText="Outside Sunport in Solstice, ", stepTextKey="Midconjuror Mirmal of Sunport told me to report to Prince Azah, leader of the Fighters Guild. He's working with the Mages Guild to bring more allies to Solstice."},
		["Talk to Prince Azah 1"] =
			{appendText=", standing just past a small fenced enclosure south of the Sunport Docks Wayshrine.", stepTextKey="Midconjuror Mirmal of Sunport told me to report to Prince Azah, leader of the Fighters Guild. He's working with the Mages Guild to bring more allies to Solstice."},
		[2] = 
			{appendStepText="I found Prince Azah just past a small fenced enclosure south of the Sunport Docks Wayshrine. ", stepTextKey="The mages Farinor and Mirmal are opening a portal to bring representatives of the Three Alliances to Solstice. Prince Azah asked me to help by setting up portal anchors."},
		["Place Portal Anchors"] =
			{appendText=" \n\nPlace the first anchor at the east end of the tiles in front of Farinor.\nPlace the second anchor southeast of the first anchor, in a patch of dirt near the bottom of a hill.\nPlace the third anchor southwest of the second anchor, toward a low stone wall.\nPlace the fourth anchor back toward Farinor, making a rectangle around the tiles on the ground. Perhaps the tiles will be a landing area for the heroes porting in."},
		[3] = 
			{appendStepText="Just past a small fenced enclosure south of the Sunport Docks Wayshrine, ", stepTextKey="I placed the portal anchors. I should tell Mage Farinor everything is ready."},
		["Talk to Mage Farinor"] =
			{appendText=", standing near a tree with Prince Azah and Midconjurer Mirmal."},
		[4] = 
			{appendStepText="Just past a small fenced enclosure south of the Sunport Docks Wayshrine, ", stepTextKey="I placed the portal anchors for Farinor and Mirmal. Time to welcome the alliance representatives to Solstice."},
		["Welcome the Alliance Representatives"] =
			{appendText=" as they arrive through a portal into Solstice."},
		[5] = 
			{appendStepText="Just past a small fenced enclosure south of the Sunport Docks Wayshrine, I was watching the mages summon a portal. ", stepTextKey="Something went wrong! The alliance representatives never reached Sunport, and Farinor disappeared. I should ask Midconjuror Mirmal what happened."},
		["Talk to Midconjuror Mirmal"] =
			{appendText=", kneeling by the tiles in dismay about what to do next."},
		[6] = 
			{appendStepText="Just past a small fenced enclosure south of the Sunport Docks Wayshrine, ", stepTextKey="Midconjurer Mirmal of Sunport explained that Farinor sabotaged the portal. He was able to salvage enough of the spell to save the representatives, but he had to divert them to someplace else. I should inform Prince Azah."},
		["Talk to Prince Azah 2"] =
			{appendText=", standing nearby. apparently injured by the effects of the portal mishap.", stepTextKey="Midconjurer Mirmal of Sunport explained that Farinor sabotaged the portal. He was able to salvage enough of the spell to save the representatives, but he had to divert them to someplace else. I should inform Prince Azah."},
		[7] = 
			{appendStepText="Just past a small fenced enclosure south of the Sunport Docks Wayshrine, standing near the failed portal, ", stepTextKey="Mirmal thinks he knows where two of the alliance representatives were diverted when Mirmal tried to salvage the spell. Prince Azah wants me to find them and Gabrielle Benele, who he believes may be in danger as well."},
		["Find the Alliance Representatives and Gabrielle"] =
			{appendText=" \n\nFind Skordo the Knife. Head directly south of Sunport past the Central Siege Camp and Rampart Camp Wayshrine, then follow a trail south along the hills, taking the left fork to the southeast. Stone steps on the east side of the trail lead up to the abandoned Warm-Stone Village. Skordo is in a hut at the south end of the village up against the Writhing Wall, reached by elevated walkways. He may want me to help him investigate the Wall and any other clues. Before leaving, I should talk to Skordo about what I find in the hut. \n\nFind Walks-in-Ash, who was teleported to a camp on a small island off the central west coast, situated at the north end of a large inlet. Someone there may know where she is. \n\nFind Gabrielle Benele, exploring the courtyard of the Broken Light Temple at the northern end of the peninsula west of Sunport. She had sensed the presence of Darien and Meridia, and may want me to help her look around before returning to Sunport. I should check near the walls and under the arches for anything interesting. \n\nSomehow, Mirmal could sense where the Skordo, Walks-in-Ash, and Gabrielle were teleported to, and has marked them on my map."},
		[8] = 
			{appendStepText="In far-flung corners of Solstice, ", stepTextKey="I found two of the diverted alliance representatives and delivered Prince Azah's message to Gabrielle Benele. Now I should return to Sunport."},
		["Return to Sunport"] =
			{appendText=" and enter the city."},
		[9] = 
			{appendStepText="In far-flung corners of Solstice, ", stepTextKey="I located two of the diverted alliance representatives and directed them to Sunport. I also found Gabrielle. Now I should return to Sunport myself and report in to Prince Azah."},
		["Meet Prince Azah"] =
			{appendText=" inside the city, up the stone stairs in the southwest courtyard by The Sleepy Sloth Inn and Pub."},
		[10] = 
			{appendStepText="In far-flung corners of Solstice, ", stepTextKey="I located two of the diverted alliance representatives and directed them to Sunport. I also found Gabrielle. Now I should return to Sunport myself and report in to Prince Azah."},
		["Talk to Prince Azah 3"] =
			{appendText=" in the city's southwest courtyard by The Sleepy Sloth Inn and Pub."},
		[11] = 
			{appendStepText="", stepTextKey="With the acting leaders of the Fighters Guild and Mages Guild, and the representatives of the Pact and Covenant, assembled, Prince Azah is ready to begin the next stage of their operation. I should find out what that is."},
		["Talk to Prince Azah 4"] =
			{appendText=" in the city's southwest courtyard by The Sleepy Sloth Inn and Pub.", stepTextKey="With the acting leaders of the Fighters Guild and Mages Guild, and the representatives of the Pact and Covenant, assembled, Prince Azah is ready to begin the next stage of their operation. I should find out what that is."},
	},

[GetQuestName(7294)] = { --"The Regent of Sunport" --aashiana
		[1] = 
			{appendStepText="In Solstice, ", stepTextKey="Prince Azah suggests heading to Sunport's palace to confer with Regent Karinwe. I should go to Vinutilmo Palace."},
		["Go to Vinutilmo Palace 1"] =
			{appendText=" in the Palace District of Sunport, built into the center of the back wall of the city.", stepTextKey="Prince Azah suggests heading to the regent of Sunport's palace to confer with Regent Karinwe. I should go to Vinutilmo Palace."},
		[2] = 
			{appendStepText="I arrived at the palace in Sunport. ", stepTextKey="Something is wrong at the palace! Midconjuror Mirmal reports that the palace was empty when he arrived and there's no sign of Regent Karinwe. I need to look around the area for clues about what's going on here."},
		["Look for Clues"] =
			{appendText=" \n\nPrince Azah seems to have noticed something on the carpet under the balcony. \n\nWalks-in-Ash has found something odd at the door near the main entrance. \n\nSomething seems to have been discarded behind the throne..."},
		[3] = 
			{appendStepText="In the Palace at Sunport, ", stepTextKey="Skordo the Knife found someone on the balcony. Maybe they know something about what happened here. I should talk to them."},
		["Talk to the Palace Servant"] =
			{appendText=", sitting by a table on the balcony."},
		[4] = 
			{appendStepText="On the balcony in the palace at Sunport, I spoke with the servant, Viniama. ", stepTextKey="The witness believes Regent Karinwe was kidnapped from the palace! The kidnappers are likely headed to Swencoast Cottage, an isolated retreat to the west."},
		["Go to Swencoast Cottage"] =
			{appendText=". The witness thinks it may be along the inlet, southwest of the city and south of the Western Bay Wayshrine."},
		[5] = 
			{appendStepText="South of the West Bay Wayshrine, ", stepTextKey="I found Razum-dar near Swencoast Cottage. He's the representative sent by the Aldmeri Dominion. I should talk to him."},
		["Talk to Razum-dar"] =
			{appendText=", hiding by the stone wall outside the main entrance to the cottage."},
		[6] = 
			{appendStepText="South of the West Bay Wayshrine, ", stepTextKey="The Worm Cult is holding Regent Karinwe captive inside Swencoast Cottage. Razum-dar and I came up with a plan to free her. Now to rescue her!"},
		["Rescue Regent Karinwe"] =
			{appendText=". There are several ways into the cottage if the first approach doesn't work out. Razum-dar suspects she may be hidden on an upper floor."},
		[7] = 
			{appendStepText="In the upstairs study in Swencoast Cottage, south of the West Bay Wayshrine, ", stepTextKey="I found Regent Karinwe and freed her. She wants to talk to me."},
		["Talk to Regent Karinwe"] =
			{appendText=" about what she fears may be happening in Sunport."},
		[8] = 
			{appendStepText="In the upstairs study in Swencoast Cottage, south of the West Bay Wayshrine, ", stepTextKey="Regent Karinwe warned me the Worm Cult plans to unleash a terrible weapon upon the Palace District. While Razum-dar escorts her to safety, I should return to Sunport and warn Prince Azah."},
		["Return to Sunport"] =
			{appendText=" and find Prince Azah. Rather than rushing to the Palace District, it may be better to rendezvous with Prince Azah in the city's southwest courtyard by The Sleepy Sloth Inn and Pub."},
		[9] = 
			{appendStepText="Before returning to Sunport, ", stepTextKey="Regent Karinwe warned me about an impending Worm Cult attack on the Palace District. I should talk to Prince Azah about our next move."},
		["Talk to Prince Azah 1"] =
			{appendText=" in the city's southwest courtyard by The Sleepy Sloth Inn and Pub.", stepTextKey="Regent Karinwe warned me about an impending Worm Cult attack on the Palace District. I should talk to Prince Azah about our next move."},
		[10] = 
			{appendStepText="While we were returning to Sunport, ", stepTextKey="The Worm Cult seized control of Sunport's Palace District. Prince Azah asked me to slip in through a hidden entrance in the luxury goods shop and take the fight to the enemy."},
		["Enter the Palace District"] =
			{appendText=", after conferring with Regent Karinwe. \n\nBy the entrance to the Palace District near the Sunport Wayshrine, Adrard's Luxury Goods shop is marked by blue and white banners with a chair on them. Look for Regent Karinwe and other guides inside the shop to help find the way."},
		[11] = 
			{appendStepText="In Sunport, ", stepTextKey="I need to destroy the Worm Cult's necromantic devices in the Palace District and stop them from carrying out a massacre."},
		["Destroy Soul Reapers"] =
			{appendText=" \n\nSoul reapers can be found on the upper levels near the palace, guarded by Daedra."},
		[12] = 
			{appendStepText="In the Sunport Palace District, ", stepTextKey="I spotted Mage Farinor at the regent's palace. I need to get inside and confront the Worm Cult leaders."},
		["Go to Vinutilmo Palace 2"] =
			{appendText=" and get inside.", stepTextKey="I spotted Mage Farinor at the regent's palace. I need to get inside and confront the Worm Cult leaders."},
		[13] = 
			{appendStepText="Inside Vinultilmo Palace in Sunport, ", stepTextKey="Mage Farinor raised an undead monstrosity to delay me. I need to defeat it if I hope to catch her."},
		["Defeat Tidemuck"] =
			{appendText="."},
		[14] = 
			{appendStepText="In Sunport, ", stepTextKey="I cleared the Palace District and Vinutilmo Palace, but Mage Farinor escaped. I should search the area for clues as to what the Worm Cult plans next."},
		["Search the Regent's Study"] =
			{appendText=" through the door in the throne room of the palace."},

		[15] = 
			{appendStepText="In the Regent's Study inside Vinutilmo Palace in Sunport, ", stepTextKey="I discovered orders from a High Necromancer Wormblood to Mage Farinor. I should find Prince Azah and share what I learned."},
		["Find Prince Azah"] =
			{appendText=", in the plaza outside the palace."},
		[16] = 
			{appendStepText="In Sunport, ", stepTextKey="The Stirk Fellowship champions gathered outside Vinutilmo Palace. I should talk to Prince Azah about our next steps."},
		["Talk to Prince Azah 2"] =
			{appendText=", in the plaza outside the palace, about what I have learned.", stepTextKey="The Stirk Fellowship champions gathered outside Vinutilmo Palace. I should talk to Prince Azah about our next steps."},
		[17] = 
			{appendStepText="", stepTextKey="I liberated Sunport's Palace District and Vinutilmo Palace from the Worm Cult. I should talk to Prince Azah and determine our next move against the necromancers."},
		["Talk to Prince Azah 3"] =
			{appendText=", in the plaza outside the palace.", stepTextKey="I liberated Sunport's Palace District and Vinutilmo Palace from the Worm Cult. I should talk to Prince Azah and determine our next move against the necromancers."},
	},

[GetQuestName(7318)] = { --"The Passages Beneath" --aashiana
		[1] = 
			{appendStepText="At Sunport in Solstice, ", stepTextKey="Prince Azah asked me to find the Passages Beneath and intercept the Worm Cult's important shipment there. He told me to start by enlisting the help of Walks-in-Ash."},
		["Talk to Walks-in-Ash 1"] =
			{appendText=", at the plaza in front of the Vinutilmo Palace.", stepTextKey="Prince Azah asked me to find the Passages Beneath and intercept the Worm Cult's important shipment there. He told me to start by enlisting the help of Walks-in-Ash."},
		[2] = 
			{appendStepText="At the plaza in front of the palace in Sunport, ", stepTextKey="Walks-in-Ash suggested questioning a Worm Cult officer captured during the Palace District battle. I should go to the Sunport guard house near the western gate to see what the prisoner knows."},
		["Go to the Sunport Guard House"] =
			{appendText=", in an unobtrusive building across from a blue hanging banner. It is up the stone stairs northwest of the Port Produce and Provisions shop."},
		[3] = 
			{appendStepText="In the Sunport Guard House north of the western gate into the city, the Captain of the Guard, Noth Drenim, has given us permission to interrogate the prisoner. ", stepTextKey="This prisoner must know something about the Worm Cult's movements and strategy. I need to find a way to get him to tell us what we need to know."},
		["Talk to Bonelord Kagazal"] =
			{appendText=", the defiant khajiit in the open cell."},
		[4] = 
			{appendStepText="", stepTextKey="The prisoner revealed that the Passages Beneath are located within the abandoned Tarnur Mine to the south. I should meet Walks-in-Ash there."},
		["Go to Tarnur Mine"] =
			{appendText=", located along the southernmost road between Western and Eastern Solstice. The mine entrance is just north of the South Siege Camp along the Writhing Wall."},
		[5] = 
			{appendStepText="Near the South Siege Camp in southeastern Solstice, ", stepTextKey="Dark Adept Farinor is protecting an important shipment for Wormblood that are being transported through the Passages Beneath. I should search the tunnels of Tarnur Mine for any Worm Cult activity."},
		["Meet Walks-in-Ash in the Mine"] =
			{appendText=". The entrance is up a small hill northwest of the South Siege Camp."},
		[6] = 
			{appendStepText="I entered the Tarnur Mine in southeast Solstice. ", stepTextKey="The mining tunnels branched, so Walks-in-Ash and I decided to split up. I should explore the mine and search for Worm Cult activity while Walks does the same."},
		["Explore the Mine"] =
			{appendText="'s abandoned tunnel through the double doors to the left, while Walks-in-Ash explores the area to the right. Follow the old mining cart tracks through the twisting tunnels, then continue to an area near the water. Whatever they're transporting in here, they may be making use of the mine's infrastructure to move it."},
		[7] = 
			{appendStepText="Northwest of the South Siege Camp, on a platform near the Writhing Wall deep within Tarnur Mine, I met up with Walks-in-Ash. ", stepTextKey="I found a barge in an underground river. If there's an important Worm Cult shipment in these tunnels, this would seem to be the place. I should search the barge."},
		["Search the Barge"] =
			{appendText=" on the water. There's a creepy sarcophagus here, with an effigy of... is that Mannimarco??"},
		[8] = 
			{appendStepText="Deep in Tarnur Mine in southeast Solstice, Mage Farinor caught us investigating a suspicous sarcophagus. ", stepTextKey="Farinor's flesh atronach Gutter knocked Walks-in-Ash and I off the barge into the river, which swept us downstream. We need to find a way out of the rushing current."},
		["Escape the River"] =
			{appendText=" by climbing onto a small dirt ledge in the caves."},
		[9] = 
			{appendStepText="We are in a river cavern somewhere in southeast Solstice. ", stepTextKey="The underground river carried us out of Tarnur Mine. I should talk to Walks-in-Ash about what we found here."},
		["Talk to Walks-in-Ash 2"] =
			{appendText=" about what we saw, and what it suggests about the Worm Cult's plans.", stepTextKey="The underground river carried us out of Tarnur Mine. I should talk to Walks-in-Ash about what we found here."},
		[10] = 
			{appendStepText="", stepTextKey="Walks-in-Ash and I survived the Farinor's monster and the raging river, but Farinor escaped with Mannimarco's sarcophagus. I should return to Sunport to report what happened to Prince Azah."},
		["Return to Prince Azah"] =
			{appendText=", by diving into the whirlpool to escape the cavern, and then return to Sunport. He is waiting with the rest of the Fellowship in the throne room of Vinutilmo Palace to hear what was found."},
		[11] = 
			{appendStepText="Back in Sunport, ", stepTextKey="I found Prince Azah in Vinutilmo Palace. I should talk to him about what we found in the Passages Beneath."},
		["Talk to Prince Azah"] =
			{appendText=" in an alcove on the northwest side of the throne room."},
		[12] = 
			{appendStepText="In the throne room of Vinutilmo Palace in Sunport, Gabrielle was reporting on what she learned. ", stepTextKey="A projection of Vanus Galerion appeared, channeled through the staff Gabrielle Benele carries. I should listen to the message."},
		["Listen to Gabrielle Benele"] =
			{appendText=" and Vanus Galerion's projection."},
		[13] = 
			{appendStepText="In the throne room of Vinutilmo Palace in Sunport, we learned that ", stepTextKey="Vanus Galerion is a prisoner of the Worm Cult, but he found a way to reach out to Gabrielle Benele. I should talk to her about what we heard before he faded away."},
		["Talk to Gabrielle Benele 1"] =
			{appendText=" about what she thinks is going on.", stepTextKey="Vanus Galerion is a prisoner of the Worm Cult, but he found a way to reach out to Gabrielle Benele. I should talk to her about what we heard before he faded away."},
		[14] = 
			{appendStepText="At the palace in Sunport, ", stepTextKey="I learned that the Worm Cult has the remains of Mannimarco, the King of Worms. They are also holding the archmage Vanus Galerion prisoner. I should talk to Gabrielle Benele about our next steps."},
		["Talk to Gabrielle Benele 2"] =
			{appendText=" in the throne room.", stepTextKey="I learned that the Worm Cult has the remains of Mannimarco, the King of Worms. They are also holding the archmage Vanus Galerion prisoner. I should talk to Gabrielle Benele about our next steps."},
	},

[GetQuestName(7295)] = { --"The Writhing Wall" --aashiana
		[1] = 
			{appendStepText="Through a projection, ", stepTextKey="Vanus Galerion told us that the Writhing Wall is thinner at a place called Li-Xal Pass. Gabrielle wants to take his staff there and re-establish contact. I should meet her at the pass, north of Sunport."},
		["Go to Li-Xal Pass"] =
			{appendText=", at the far end of the road north of Sunport, past the North Siege Camp along the water. Then up stone stairs to a cave entrance."},
		[2] = 
			{appendStepText="Beyond the North Siege Camp and through a cave entrance, ", stepTextKey="I should ascend Li-Xal Pass and search for a thin spot in the Writhing Wall."},
		["Climb Li-Xal Pass 1"] =
			{appendText=". I should talk with Gabrielle before setting out, as some special equipment may be needed to ascend the path. She can provide guidance along the way while I fend off the Daedra and wildlife. I should look for grapple points whenever the path seems to end.", stepTextKey="I should ascend Li-Xal Pass and search for a thin spot in the Writhing Wall."},
		[3] = 
			{appendStepText="In a cave within Li-Xal Pass, ", stepTextKey="Gabrielle and I found our way to a weak point in the Writhing Wall, and a projection of Vanus Galerion appeared. He wants to speak with us."},
		["Talk to Vanus Galerion 1"] =
			{appendText=".", stepTextKey="Gabrielle and I found our way to a weak point in the Writhing Wall, and a projection of Vanus Galerion appeared. He wants to speak with us."},
		[4] = 
			{appendStepText="Within Li-Xal Pass, north of Sunport, we found a place. ", stepTextKey="The image of Vanus Galerion only managed a few moments of conversation before the Writhing Wall closed again. I need to look for another weak point farther up the pass."},
		["Climb Li-Xal Pass 2"] =
			{appendText=" to try to find a better connection with Vanus, using grappling points to reach higher passageways where the wall may be thinner.", stepTextKey="The image of Vanus Galerion only managed a few moments of conversation before the Writhing Wall closed again. I need to look for another weak point farther up the pass."},
		[5] = 
			{appendStepText="We traveled farther up Li-Xal Pass, north of Sunport. ", stepTextKey="We found another weak point in the Writhing Wall, and Vanus Galerion reappeared. I should talk to him while I can."},
		["Talk to Vanus Galerion 2"] =
			{appendText=".", stepTextKey="We found another weak point in the Writhing Wall, and Vanus Galerion reappeared. I should talk to him while I can."},
		[6] = 
			{appendStepText="Within Li-Xall Pass, north of Sunport, we found another place. ", stepTextKey="Once again the Writhing Wall sealed itself before I finished my conversation with Vanus Galerion. We should continue up the pass and locate another place where he can reach us."},
		["Climb Li-Xal Pass 3"] =
			{appendText=", heading north through the caves, using grappling points where needed, to an outdoor area far above Li-Xal Cove.", stepTextKey="Once again the Writhing Wall sealed itself before I finished my conversation with Vanus Galerion. We should continue up the pass and locate another place where he can reach us."},
		[7] = 
			{appendStepText="Far above Li-Xal Cove, we reached the top of Li-Xal Pass. ", stepTextKey="We located a third weak point in the Writhing Wall. I should talk to Vanus Galerion while I can."},
		["Talk to Vanus Galerion 3"] =
			{appendText=" on the stone platform at the top of Li-Xal Pass. ", stepTextKey="We located a third weak point in the Writhing Wall. I should talk to Vanus Galerion while I can."},
		[8] = 
			{appendStepText="Far above Li-Xal Cove, at the top of Li-Xal Pass, ", stepTextKey="Vanus Galerion's communications have finally stopped, but not before he passed along some vital intelligence about Wormblood's plans. Gabrielle wants to discuss what we learned."},
		["Talk to Gabrielle Benele"] =
			{appendText=" on the stone platform at the top of Li-Xal Pass."},
		[9] = 
			{appendStepText="Far above Li-Xal Cove, at the top of Li-Xal Pass, ", stepTextKey="Vanus Galerion told us the Gift of Death is hidden in Vosgah Shrine, a sacred teeba-hatsei court. Gabrielle wants me to go there and retrieve the relic before Wormblood can get it."},
		["Go to Vosgah Shrine"] =
			{appendText=", using the grapple points to reach the beach below, where a boat is waiting to take you back to a pier near the North Siege Camp. Travel to southwestern Solstice where the road curves to the south. Vosgah Shrine is built into the south side of a large mountain looming over the southern beaches. A flame at the top of a stone staircase can be seen from afar and marks the stone doorway into the Vosgah Shrine."},
		[10] = 
			{appendStepText="Northwest of the Vale of Revelry Wayshrine, within a stone doorway in the mountainside, ", stepTextKey="I found Razum-dar at Vosgah Shrine. I should talk to him about what he discovered."},
		["Talk to Razum-dar"] =
			{appendText=", waiting for me near the door."},
		[11] = 
			{appendStepText="Within the Vosgah Shrine in southwestern Solstice, ", stepTextKey="Razum-dar told me that Wormblood is already here. Raz and I need to find the teeba-hatsei court's ritual altar and get the Gift of Death before Phoom claims it."},
		["Reach the Ritual Altar"] =
			{appendText=" through a stone door at the northern end of the shrine."},
		[12] = 
			{appendStepText="We reached the Teeba-Hatsei ritual altar deep within the Vosgah Shrine in southwestern Solstice. ", stepTextKey="We interrupted Wormblood's attempt to claim the Gift of Death. Now we must defeat him."},
		["Defeat Wormblood 1"] =
			{appendText=", and by hiding behind the pillars for safety when Wormblood fills the floor with a deadly spell.", stepTextKey="We interrupted Wormblood's attempt to claim the Gift of Death. Now we must defeat him."},
		[13] = 
			{appendStepText="The battle at the ritual altar deep within the Vosgah Shrine is over. ", stepTextKey="We defeated Wormblood! I should take the Gift of Death to make sure it doesn't fall into the Worm Cult's hands."},
		["Take the Gift of Death"] =
			{appendText=" from the altar, glowing green."},
		[14] = 
			{appendStepText="Deep within the Vosgah Shrine in southwestern Solstice, ", stepTextKey="Wormblood brought himself back from the dead! Razum-dar and I need to find a way to defeat him and escape."},
		["Defeat Wormblood 2"] =
			{appendText=", again.", stepTextKey="Wormblood brought himself back from the dead! Razum-dar and I need to find a way to defeat him and escape."},
		[15] = 
			{appendStepText="We are still in the ritual chamber of Vosgah Shrine in southwestern Solstice. ", stepTextKey="If we can't kill Wormblood, maybe we can immobilize him, Raz wants me to collapse the shrine on top of him."},
		["Collapse the Shrine"] =
			{appendText=" by destroying the weakened columns and burying Wormblood under the debris."},
		[16] = 
			{appendStepText="Within the Vosgah Shrine in southwestern Solstice, ", stepTextKey="I trapped Wormblood under the collapsed shrine at the ancient teeba-hatsei court. I need to return to Sunport and report to Prince Azah."},
		["Return to Vinutilmo Palace"] =
			{appendText=" in Sunport to tell Prince Azah what happened."},
		[17] = 
			{appendStepText="In the Palace in Sunport, ", stepTextKey="Prince Azah wants to know what happened at Vosgah Shrine."},
		["Talk to Prince Azah 1"] =
			{appendText=" and answer his many questions about what happened in the Vosgah Shrine.", stepTextKey="Prince Azah wants to know what happened at Vosgah Shrine."},
		[18] = 
			{appendStepText="", stepTextKey="Razum-dar and I recovered the Gift of Death and escaped, keeping it out of Wormblood's hands. I should talk to Prince Azah about what we learned."},
		["Talk to Prince Azah 2"] =
			{appendText=" at the palace in Sunport about what our next steps should be.", stepTextKey="Razum-dar and I recovered the Gift of Death and escaped, keeping it out of Wormblood's hands. I should talk to Prince Azah about what we learned."},
	},

[GetQuestName(7296)] = { --"The Gift of Death" --aashiana
		[1] = 
			{appendStepText="", stepTextKey="Mirmal told me that Prince Azah wants to speak with me. He's waiting for me at Vinutilmo Palace with the champions of the Stirk Fellowship."},
		["Talk to Prince Azah 1"] =
			{appendText=" at the palace in Sunport.", stepTextKey="Mirmal told me that Prince Azah wants to speak with me. He's waiting for me at Vinutilmo Palace with the champions of the Stirk Fellowship."},
		[2] = 
			{appendStepText="In the throne room of the Vinutilmo Palace in Sunport, ", stepTextKey="Prince Azah asked the champions of the Stirk Fellowship for ideas about how to proceed. I should listen to the conversation."},
		["Listen to the Champions"] =
			{appendText=".", stepTextKey="Prince Azah asked the champions of the Stirk Fellowship for ideas about how to proceed. I should listen to the conversation."},
		[3] = 
			{appendStepText="In the throne room of the Vinutilmo Palace in Sunport, I learned ", stepTextKey="Razum-dar managed to filch a key with a strange crest from Wormblood. It appears to belong to an old Corelanya family crypt."},
		["Talk to Gabrielle Benele 1"] =
			{appendText=".", stepTextKey="Razum-dar managed to filch a key with a strange crest from Wormblood. It appears to belong to an old Corelanya family crypt."},
		[4] = 
			{appendStepText="In speaking with her at the palace in Sunport, I learned ", stepTextKey="Gabrielle believes we may learn something about Wormblood's plans if we can figure out why he was interested in Corelanya Crypt. I agreed to go check it out."},
		["Go to Corelanya Crypt"] =
			{appendText="Head south of Sunport on the main roads, staying on the east side of the water, until you reach an Argonian stone and wooden plank bridge. The Corelanya Manor can be seen on a hill behind it. After crossing the bridge, continue up the hill to the left, past the graveyard to the Corelanya Crypt. Skordo is waiting there."},
		[5] = 
			{appendStepText="Near the graveyard outside of Corelanya Manor in central Solstice, ", stepTextKey="I found the crypt Gabrielle Benele told me about. I should look around to figure out what Wormblood was doing in this place."},
		["Search Corelanya Crypt"] =
			{appendText=" after talking to Skordo about what he's noticed. The most important relics are likely stored in the hardest to reach chamber, warded by powerful magic."},
		[6] = 
			{appendStepText="We reached the innermost chamber of the Corelanya Crypt near the graveyard of Corelanya Manor. ", stepTextKey="We found the tomb of an ancient Corelanya lord, but it's protected by a magical barrier. I need to remove the barrier and see what the Worm Cult is hiding here."},
		["Destroy the Tomb's Barrier"] =
			{appendText=". It looks like destroying the pillars on either side of the tomb might do it."},
		[7] = 
			{appendStepText="Deep within the Corelanya Crypt near the Corelanya Manor, I destroyed the barrier protecting the Gift of Death. But then, ", stepTextKey="I found a High Elf spirit bound inside the Worm Cult's barrier. I should talk to the spirit and find out what Wormblood wanted from him."},
		["Talk to Arvoril"] =
			{appendText=" to learn more about the Gift of Death and the source of Wormblood's power. The Ghost may want a favor in return to free him from this place."},
		[8] = 
			{appendStepText="Deep within the Corelanya Crypt near the Corelanya Manor, I was told ", stepTextKey="Wormblood interrogated the spirit of Arvoril to learn where the Gift of Death was hidden. Arvoril asked me to remove the crystal Wormblood used to question him."},
		["Take the Ghostweld Crystal"] =
			{appendText=" from the crypt to free the Avoril's spirit and prevent Wormblood from returning here."},
		[9] = 
			{appendStepText="Within the Corelanya Crypt near Corelanya Manor, ", stepTextKey="Arvoril the spirit told me about the Gift of Death. I should return to Sunport and tell my comrades what I learned."},
		["Meet Gabrielle Benele at Vinutilmo Palace"] =
			{appendText=" in Sunport. She is studying the Gift of Death within the Regent's Study, to the right of the entrance."},
		[10] = 
			{appendStepText="I returned to the palace in Sunport. ", stepTextKey="I should tell Gabrielle Benele what I learned about the Gift of Death."},
		["Talk to Gabrielle Benele 2"] =
			{appendText=". She is with the others of the Fellowship in the Regent's Study", stepTextKey="I should tell Gabrielle Benele what I learned about the Gift of Death."},
		[11] = 
			{appendStepText="Within the Regent's Study in the Vinutilmo Palace at Sunport, ", stepTextKey="Gabrielle and I decided to use the Gift of Death to lure Wormblood to the ancient Broken Light Temple. We can use the projection crystal he left in the crypt to contact him."},
		["Place the Ghostweld Crystal"] =
			{appendText=" on the floor in the center of the room."},
		[12] = 
			{appendStepText="I placed the crystal on the floor of the Regent's Study in the palace at Sunport. ", stepTextKey="We summoned a projection of Wormblood. I need to offer him the Gift of Death to lure him into a face-to-face meeting."},
		["Talk to Wormblood"] =
			{appendText=" about the bargain Gabriel wants to make to return Vanus Galerion to the Fellowship."},
		[13] = 
			{appendStepText="In the Regent's Study in the palace in Sunport, ", stepTextKey="Wormblood agreed to bring Vanus Galerion to Broken Light Temple. I should talk to Gabrielle about how we proceed now."},
		["Talk to Gabrielle Benele 3"] =
			{appendText=" about our plans to lure Wormblood to the Broken Light Temple.", stepTextKey="Wormblood agreed to bring Vanus Galerion to Broken Light Temple. I should talk to Gabrielle about how we proceed now."},
		[14] = 
			{appendStepText="", stepTextKey="The exchange is on! We need to bring the Gift of Death to the courtyard of Broken Light Temple."},
		["Go to Broken Light Courtyard"] =
			{appendText=" on the west side of Broken Light Temple. The temple is at the northern tip of the peninsula, across the inlet, northwest of Sunport."},
		[15] = 
			{appendStepText="Northwest of Sunport, I joined the others. ", stepTextKey="The champions of the Stirk Fellowship are assembled in the courtyard of Broken Light Temple. I should talk to Prince Azah about what comes next."},
		["Talk to Prince Azah 2"] =
			{appendText=" to learn more about the plan to trap Wormblood in the Colored Rooms and what I need to do to help. The Bell of Meridia is ready for when Gabrielle begins to cast her spell.", stepTextKey="The champions of the Stirk Fellowship are assembled in the courtyard of Broken Light Temple. I should talk to Prince Azah about what comes next."},
		[16] = 
			{appendStepText="In the courtyard of the Broken Light Temple in northwestern Solstice, ", stepTextKey="Prince Azah told me to choose a champion to stand with me in the upcoming fight. I should speak with Razum-dar, Skordo the Knife, and Walks-in-Ash."},
		["Choose a Champion"] =
			{appendText=" after talking with each one."},
		[17] = 
			{appendStepText="In the courtyard of the Broken Light Temple in northwestern Solstice, ", stepTextKey="Prince Azah asked me to make sure our trap for Wormblood is ready. I need to get the mallet for the temple bell and get into position."},
		["Take the Mallet"] =
			{appendText=", lying on a ledge near the bell."},
		[18] = 
			{appendStepText="In the courtyard of the Broken Light Temple in northwestern Solstice, ", stepTextKey="I better get in position by the bell above the gate. I need to be ready to strike the bell on Gabrielle's signal"},
		["Get into Position at the Bell"] =
			{appendText="."},
		[19] = 
			{appendStepText="In the courtyard of the Broken Light Temple in northwestern Solstice, ", stepTextKey="Wormblood showed up, just as he said he would. It's time to put our plan into motion."},
		["Wait for the Signal"] =
			{appendText=" to strike the bell."},
		[20] = 
			{appendStepText="In the courtyard of the Broken Light Temple in northwestern Solstice, ", stepTextKey="Gabrielle Benele gave the signal! I need to trigger the trap and send the courtyard to Meridia's realm."},
		["Strike the Temple Bell"] =
			{appendText=" with the mallet."},
		[21] = 
			{appendStepText="In the courtyard of the Broken Light Temple in northwestern Solstice, ", stepTextKey="Gabrielle's ritual worked—everyone in the courtyard has been thrown into the Colored Rooms. I need to follow my allies."},
		["Enter the Colored Rooms"] =
			{appendText=" through the portal in the center of the courtyard."},
		[22] = 
			{appendStepText="After the ritual in the courtyard of the Broken Light Temple, ", stepTextKey="I arrived in the Colored Rooms, but the planar transition scattered both friend and foe alike. Wormblood is nowhere to be seen. I need to locate my allies and find my enemies."},
		["Explore the Colored Rooms"] =
			{appendText="."},
		[23] = 
			{appendStepText="After the ritual in the courtyard of the Broken Light Temple, I entered the Colored Rooms. ", stepTextKey="The planar transition left the temple courtyard strewn across the Colored Rooms. Wormblood is somewhere in here. This is our chance to kill him—if we can find him."},
		["Search for Wormblood"] =
			{appendText=", following the broken stone path."},
		[24] = 
			{appendStepText="After the ritual in the courtyard of the Broken Light Temple, I entered the Colored Rooms. ", stepTextKey="We heard Vanus Galerion calling for aid. He's tied up on a nearby ledge. We should try to get to him."},
		["Find Vanus Galerion"] =
			{appendText=" on a stone ledge above a courtyard."},
		[25] = 
			{appendStepText="Vanus Galerion's projection was a trick! In a stone courtyard in the Colored Rooms, ", stepTextKey="Gabrielle Benele is gravely wounded, but she has a plan to defeat the Worm Cult. She wants to speak with me."},
		["Talk to Gabrielle Benele 4"] =
			{appendText=". She wants me to use the Gift of Death to exchange her soul for another...", stepTextKey="Gabrielle Benele is gravely wounded, but she has a plan to defeat the Worm Cult. She wants to speak with me."},
		[26] = 
			{appendStepText="At a stone courtyard within the Colored Rooms, ", stepTextKey="Gabrielle is fading fast. She asked me to use the Gift of Death on her so that can bring the Stirk Fellowship the ally we need to defeat Wormblood."},
		["Use the Gift of Death"] =
			{appendText=" to exchange Gabrielle's soul for another."},
		[27] = 
			{appendStepText="Within a stone courtyard in the Colored Rooms, ", stepTextKey="I used the Gift of Death on Gabrielle, as she asked. I should see what her willing sacrifice brings next."},
		["Wait for the Gift's Sacrifice"] =
			{appendText=". She has exchanged her soul to return Darien to the Fellowship!"},
		[28] = 
			{appendStepText="Within a stone courtyard in the Colored Rooms, ", stepTextKey="Gabrielle's sacrifice purified the corrupt relic, returning it to a Light of Meridia. I should take it, as we may be able to use it."},
		["Take the Light of Meridia"] =
			{appendText=" and follow Darien."},
		[29] = 
			{appendStepText="Within the Colored Rooms, Gabrielle's sacrifice purified a powerful relic. ", stepTextKey="The Light of Meridia might be able to remove the barrier blocking our access to Wormblood's ritual."},
		["Remove the Barrier"] =
			{appendText=" using the Light of Meridia."},
		[30] = 
			{appendStepText="Within the Colored Rooms, ", stepTextKey="Gabrielle Benele chose to bring back Darien Gautier, a champion of Meridia. But Wormblood has already begun the ritual to resurrect Mannimarco. We must stop him."},
		["Stop Wormblood's Ritual"] =
			{appendText=" across the courtyard, beyond the barrier."},
		[31] = 
			{appendStepText="Within the Colored Rooms, ", stepTextKey="Mannimarco's spirit possessed Wormblood! He ordered Farinor to keep us from interfering as he seeks to regain his strength from the nearby soul reapers. I need to go through Farinor to stop him."},
		["Kill Farinor"] =
			{appendText=" by defeating her minions, with Darien's help."},
		[32] = 
			{appendStepText="Within the Colored Rooms, ", stepTextKey="Gabrielle Benele's sacrifice restored the Gift of Death to its true form—a powerful Light of Meridia. Darien told me to use the Light on a Worm Cult soul reaper."},
		["Use the Light of Meridia"] =
			{appendText=" to disrupt the Worm Cult ritual by destroying the Worm Cult devices."},
		[33] = 
			{appendStepText="We battled in the Colored Rooms. ", stepTextKey="We destroyed the Worm Cult soul reapers and ruined Wormblood's ritual. However, Mannimarco's spirit possessed Wormblood and escaped from the Colored Rooms. Darien Gaultier wants to speak with me before we return to Tamriel."},
		["Talk to Darien Gaultier"] =
			{appendText=" to explain how he came to be here, and the sacrifice Gabrielle made to bring him back."},
		[34] = 
			{appendStepText="", stepTextKey="We defeated the Worm Cult in the Colored Rooms, at a terrible cost. I should return to Sunport and regroup with my allies."},
		["Return to Vinutilmo Palace"] =
			{appendText=" in Sunport through the portal Walks-in Ash created."},
		[35] = 
			{appendStepText="In Sunport, ", stepTextKey="I found Prince Azah and the rest of my allies waiting for me in Vinutilmo Palace. I should speak with him."},
		["Talk to Prince Azah 3"] =
			{appendText=".", stepTextKey="I found Prince Azah and the rest of my allies waiting for me in Vinutilmo Palace. I should speak with him."},
		[36] = 
			{appendStepText="I joined the champions of the Stirk Fellowship in the palace at Sunport. ", stepTextKey="Although we lost Gabrielle Benele, I returned from the Colored Rooms with Darien Gaultier and a Light of Meridia. I should talk to Prince Azah about our next steps."},
		["Talk to Prince Azah 4"] =
			{appendText=".", stepTextKey="Although we lost Gabrielle Benele, I returned from the Colored Rooms with Darien Gaultier and a Light of Meridia. I should talk to Prince Azah about our next steps."},
	},

[GetQuestName(7322)] = { --"Crossing the Wall" --aashiana
		[1] = {appendStepText="", stepTextKey="Prince Azah has a special mission for me to help advance our attack against the Writhing Wall. I should go to Sunport Rampart Camp and speak to him."},
		["Find Prince Azah"] = 
			{appendText=", at the west entrance to the Rampart Camp, directly south of Sunport."},
		[2] = {appendStepText="", stepTextKey="Prince Azah has a special mission for me to help advance our attack against the Writhing Wall. I should go to Sunport Rampart Camp and speak to him."},
		["Talk to Prince Azah 1"] = 
			{appendText=", at the west entrance to the Rampart Camp."},
		[3] = {appendStepText="At the Rampart Camp in central Solstice, ", stepTextKey="Prince Azah asked me to hasten the attack on the Writhing Wall. I should visit the Meridian Lens and speak to Midconjuror Mirmal."},
		["Find Midconjuror Mirmal at the Meridian Lens"] = 
			{appendText=", up the ramp from the camp's main platform.", stepTextKey="Prince Azah asked me to hasten the attack on the Writhing Wall. I should visit the Meridian Lens and speak to Midconjuror Mirmal."},
		[4] = {appendStepText="At the Rampart Camp in central Solstice, ", stepTextKey="Prince Azah asked me to hasten the attack on the Writhing Wall. I should visit the Meridian Lens and speak to Midconjuror Mirmal."},
		["Talk to Midconjuror Mirmal"] = 
			{appendText=", standing by the light, up the ramp from the camp's main platform.", stepTextKey="Prince Azah asked me to hasten the attack on the Writhing Wall. I should visit the Meridian Lens and speak to Midconjuror Mirmal."},
		[5] = 
			{appendStepText="At the Rampart Camp in central Solstice, ", stepTextKey="Midconjuror Mirmal thinks Gabrielle's research on the Writhing Wall may help us find a way to disable whatever is healing it. I should meet Darien in Vinutilmo Palace and see what we find."},
		["Meet Darien Gautier in the Regent's Study"] =
			{appendText=" within the Palace in Sunport."},
		[6] = 
			{appendStepText="In the Palace in Sunport, ", stepTextKey="I found Darien Gautier in the regent's study, looking over Gabrielle's notes. I should speak with him."},
		["Talk to Darien Gautier 1"] =
			{appendText=" about what information Gabrielle may have left behind that could help us defeat the Worm Cult's plans. ", stepTextKey="I found Darien Gautier in the regent's study, looking over Gabrielle's notes. I should speak with him."},
		[7] = 
			{appendStepText="In the Regent's Study in the Palace in Sunport, ", stepTextKey="I should take a look at the journal and notes Gabrielle left behind."},
		["Read Gabrielle's Journal"] =
			{appendText=", on the table near Darien."},
		["Read Gabrielle's Research"] =
			{appendText=", on the table on the other side of the room."},
		[8] = 
			{appendStepText="Based on her notes in the Regent's Study in the Palace in Sunport, ", stepTextKey="Gabrielle had some theories about binding points or shrines supporting the Writhing Wall. I should see what Darien makes of her ideas."},
		["Talk to Darien Gautier 2"] =
			{appendText=".", stepTextKey="Gabrielle had some theories about binding points or shrines supporting the Writhing Wall. I should see what Darien makes of her ideas."},
		[9] = 
			{appendStepText="", stepTextKey="Gabrielle noted places where the Writhing Wall's bindings create local distortions. Disrupting this necromantic energy could lead us to the binding points. I should investigate with Darien."},
		["Investigate the North and South Wall"] =
			{appendText="s. Roads leading to mountain passes are blocked by the Writhing Wall. One is north of the North Siege Camp, and another is east of the South Siege Camp."},
		[10] = 
			{appendStepText="On the road north of the North Seige Camp, ", stepTextKey="I investigated the mountain pass at Li-Xal and discovered a distortion near the Writhing Wall. I should get a closer look."},
		["Examine Writhing Distortion 1"] =
			{appendText=" in the center of the Writhing Wall along the road north of the North Siege Camp.", stepTextKey="I investigated the mountain pass at Li-Xal and discovered a distortion near the Writhing Wall. I should get a closer look."},
		[11] = 
			{appendStepText="", stepTextKey="Darien wants to examine the distortion at the Writhing Wall. His connection to Meridia makes him more sensitive to necromantic energies."},
		["Observe Darien Gautier 1"] =
			{appendText=" as he examines the Writhing Distortion at the wall.", stepTextKey="Darien wants to examine the distortion at the Writhing Wall. His connection to Meridia makes him more sensitive to necromantic energies."},
		[12] = 
			{appendStepText="", stepTextKey="The Writhing Wall distortion reacted to Darien's presence. We found a spectral chain of energy anchored to the wall. I should follow this energy to locate its source."},
		["Enter Portal"] =
			{appendText=" on the road near the Writhing Wall."},
		[13] = 
			{appendStepText="We entered the portal on the road north of the North Siege Camp. ", stepTextKey="The necromantic energy sustaining the Writhing Wall led to a cavern on Solstice's western coast. I should investigate with Darien."},
		["Investigate Carapace Caverns"] =
			{appendText="."},
		[14] = 
			{appendStepText="Within Carapace Cavern on the west coast of Solstice, ", stepTextKey="Gabrielle Benele's notes suggested some sort of shrine or anchor point binding the Writhing Wall to Solstice. I should search Carapace Caverns and find it."},
		["Find the Anchor Shrine 1"] =
			{appendText=". The distortion leads to a location near the skyshard at the south end of the cavern. Enter a chamber through a small stone entrance to find a hidden temple containing an Anchor Shrine.", stepTextKey="Gabrielle Benele's notes suggested some sort of shrine or anchor point binding the Writhing Wall to Solstice. I should search Carapace Caverns and find it."},
		[15] = 
			{appendStepText="On the west coast of Solstice, ", stepTextKey="I located the Writhing Wall's binding shrine inside Carapace Caverns. I need to destroy this shrine to weaken the wall."},
		["Destroy the Anchor Shrine 1"] =
			{appendText=" by defeating its guardians and breaking the anchor shrine.", stepTextKey="I located the Writhing Wall's binding shrine inside Carapace Caverns. I need to destroy this shrine to weaken the wall."},
		[16] = 
			{appendStepText="", stepTextKey="Gabrielle noted places where the Writhing Wall's bindings create local distortions. Disrupting this necromantic energy could lead us to the binding points. I should investigate with Darien."},
		["Investigate Wall by Shell-Tide Village"] =
			{appendText=", taking the southernmost road that leads east to the Writhing Wall."},
		[17] = 
			{appendStepText="Along the southernmost road that leads east to the Writhing Wall, ", stepTextKey="I investigated the mountain pass east of Shell-Tide Village and discovered a distortion near the Writhing Wall. I should get a closer look."},
		["Examine Writhing Distortion 2"] =
			{appendText=". A chain of energy leads to another portal in a rock on the side of the road.", stepTextKey="I investigated the mountain pass east of Shell-Tide Village and discovered a distortion near the Writhing Wall. I should get a closer look."},
		[18] = 
			{appendStepText="After traveling through a portal on the southernmost road leading to the Writhing Wall, ", stepTextKey="The necromantic energy sustaining the Writhing Wall led to an old mine near Solstice's southern mountains. I should investigate with Darien."},
		["Investigate Tarnur Mine"] =
			{appendText=", following the anchor chains. The mine is near the South Siege Camp."},
		[19] = 
			{appendStepText="Near the South Siege Camp, we followed the chains to the mine. ", stepTextKey="Gabrielle Benele's notes suggested some sort of shrine or anchor point binding the Writhing Wall to Solstice. I should search Tarnur Mine and find it."},
		["Find the Anchor Shrine 2"] =
			{appendText=". The anchor chains led us to some abandoned tunnels, then through the tunnels to a root-covered entrance in the stone wall. Within this hidden area, the anchor chains will likely lead to an Anchor Shrine.", stepTextKey="Gabrielle Benele's notes suggested some sort of shrine or anchor point binding the Writhing Wall to Solstice. I should search Tarnur Mine and find it."},
		[20] = 
			{appendStepText="Within the portal created by the Writhing Distortion in the southern Writhing Wall, ", stepTextKey="I located the Writhing Wall's binding shrine inside Tarnur Mine. I need to destroy this shrine to weaken the wall."},
		["Destroy the Anchor Shrine 2"] =
			{appendText=".", stepTextKey="I located the Writhing Wall's binding shrine inside Tarnur Mine. I need to destroy this shrine to weaken the wall."},
		[21] = 
			{appendStepText="At the north and south ends of the wall, ", stepTextKey="I destroyed the anchor shrines reinforcing the Writhing Wall. I should return to the Fellowship camp at Sunport Rampart and tell Prince Azah what we found."},
		["Return to the Sunport Rampart Camp"] =
			{appendText=" in central Solstice."},
		[22] = 
			{appendStepText="", stepTextKey="I destroyed the anchor shrines reinforcing the Writhing Wall. I should return to the Fellowship camp at Sunport Rampart and tell Prince Azah what we found."},
		["Talk to Prince Azah 2"] =
			{appendText=", standing in front of a large, white command tent.", stepTextKey="I destroyed the anchor shrines reinforcing the Writhing Wall. I should return to the Fellowship camp at Sunport Rampart and tell Prince Azah what we found."},
		[23] = 
			{appendStepText="At the Rampart Camp in central Solstice, ", stepTextKey="Prince Azah told me that instability of the Writhing Wall damaged the nearby mountainside, revealing a large fissure. He asked me to see if it leads through the wall into Eastern Solstice."},
		["Find Fissure Near Writhing Wall"] =
			{appendText=". I should talk to Midconjuror Mirmal about it before I leave. \n\nFrom the Central Siege Camp east of the Rampart Camp Wayshrine, follow the eastern hillside south until you reach a small cave with a lantern and mining tools in front of it."},
		[24] = 
			{appendStepText="Southeast of the Rampart Camp, ", stepTextKey="Darien and I found the fissure Prince Azah told us about. I need to find out how far it goes."},
		["Enter the Fissure"] =
			{appendText="."},
		[25] = 
			{appendStepText="Through a cave entrance along the road southeast of the Rampart Camp, ", stepTextKey="I went through the fissure and discovered ancient ruins in a cavern near the Writhing Wall. I should investigate and see where they lead."},
		["Explore the Ruins"] =
			{appendText=" and find the Daedric temple, where a ritual is about to start."},
		[26] = 
			{appendStepText="Within the fissure ruins cave in the mountainside southeast of the Rampart Camp, ", stepTextKey="I found Mannimarco overseeing a ritual to prevent the Writhing Wall's collapse. I need to interrupt the ritual so we can destroy the Writhing Wall."},
		["Stop the Ritual"] =
			{appendText=" by traveling through the caves to the Daedric temple and defeating the guardians along the way. Then destroy the ritual altar."},
		[27] = 
			{appendStepText="In the Daedric temple within the fissure ruins cave southeast of the Rampart Camp, ", stepTextKey="Mannimarco summoned a Daedric guardian to protect the final binding point. I must defeat the maldrith so I can destroy the shrine."},
		["Defeat the Maldrith"] =
			{appendText=" guardian with Darien's help."},
		[28] = 
			{appendStepText="In the Daedric temple within the fissure ruins cave southeast of the Rampart Camp, ", stepTextKey="The ritual altar is protected by a shield, but Darien thinks he can disable it. I should observe what happens."},
		["Observe Darien Gautier 2"] =
			{appendText=" as he brings down the shield, but at what cost?", stepTextKey="The ritual altar is protected by a shield, but Darien thinks he can disable it. I should observe what happens."},
		[29] = 
			{appendStepText="In the Daedric temple within the fissure ruins cave southeast of the Rampart Camp, ", stepTextKey="I defeated the maldrith guarding the ritual. I need to destroy the altar to disrupt the Worm Cult's effort to repair the Writhing Wall here."},
		["Destroy the Ritual Altar"] =
			{appendText=" on the platform. "},
		[30] = 
			{appendStepText="In the Daedric temple within the fissure ruins cave southeast of the Rampart Camp, ", stepTextKey="Disrupting the Worm Cult's ritual caused the Writhing Wall to unravel. Mannimarco was forced to retreat."},
		["Observe the Writhing Wall"] =
			{appendText=", weakened from the destruction of the ritual altars. But Darien appears to be weakened also."},
		[31] = 
			{appendStepText="In the Daedric temple within the fissure ruins cave southeast of the Rampart Camp, ", stepTextKey="Darien appears weakened from Mannimarco's attack. I should check on him."},
		["Talk to Darien Gautier 3"] =
			{appendText=", sitting next to the broken altar, injured.", stepTextKey="Darien appears weakened from Mannimarco's attack. I should check on him."},
		[32] = 
			{appendStepText="We disrupted Mannimarco's ritual. ", stepTextKey="The Writhing Wall appears unstable. I should return to the Fellowship camp at Sunport Rampart and inform Prince Azah about our success in the ruins."},
		["Return to Sunport Rampart Camp"] =
			{appendText=" in central Solstice."},
		[33] = 
			{appendStepText="", stepTextKey="I found Prince Azah at the Sunport Rampart Camp. I should tell him what happened in the ruins."},
		["Talk to Prince Azah 3"] =
			{appendText=" about what Darian and I found in the cave southeast of the Rampart Camp.", stepTextKey="I found Prince Azah at the Sunport Rampart Camp. I should tell him what happened in the ruins."},
		[34] = 
			{appendStepText="At the Rampart Camp, ", stepTextKey="Prince Azah asked me to personally fire the final blast against the Writhing Wall. I should activate the Meridian Lens."},
		["Activate the Meridian Lens"] =
			{appendText=" in the center of the upper platform."},
		[35] = 
			{appendStepText="At the Rampart Camp, ", stepTextKey="The Light of Meridia destroyed the Writhing Wall! I should talk to Prince Azah about what comes next."},
		["Talk to Prince Azah 4"] =
			{appendText=", standing near the Meridian Lens. Our efforts have broken through the Writhing Wall, and we can now send our forces into Eastern Solstice.", stepTextKey="The Light of Meridia destroyed the Writhing Wall! I should talk to Prince Azah about what comes next."},
	},

[GetQuestName(7284)] = { --"The Worm Turns" --aashiana
		[1] = 
			{appendStepText="", stepTextKey="Prince Azah is sending me and the other champions to scout the path through the mountain pass. I should rendezvous with Skordo before heading too far into the eastern side of the island."},
		["Investigate the Pass"] =
			{appendText=" leading to eastern Solstice in the central mountains, east of the Rampart camp.", stepTextKey="Prince Azah is sending me and the other champions to scout the path through the mountain pass. I should rendezvous with Skordo before heading too far into the eastern side of the island."},
		[2] = 
			{appendStepText="", stepTextKey="Prince Azah is sending me and the other champions to scout the path through the mountain pass. I should rendezvous with Skordo before heading too far into the eastern side of the island."},
		["Talk to Skordo the Knife 1"] =
			{appendText=" near the central mountain pass leading into eastern Solstice.", stepTextKey="Prince Azah is sending me and the other champions to scout the path through the mountain pass. I should rendezvous with Skordo before heading too far into the eastern side of the island."},
		[3] = 
			{appendStepText="East of Rampart Camp in central Solstice, I spoke with Skordo the Knife on the mountain pass road. ", stepTextKey="Skordo said that the dying Stone-Nest villager described how the Worm Cult is testing a new device on Argonian prisoners. The villager escaped thanks to someone on the inside. While Skordo informs Prince Azah, I should meet up with Darien and Raz."},
		["Rendezvous with Razum-dar and Darien"] =
			{appendText=" on the eastern side of the central pass overlooking a Worm Cult camp, near the Grand Juncture Wayshrine."},
		[4] = 
			{appendStepText="After crossing the pass on the central road and reaching the Grand Juncture Pass Wayshrine, ", stepTextKey="I met up with Razum-dar and Darien on a vantage point overlooking the land below. I should talk to him."},
		["Talk to Razum-dar"] =
			{appendText=" about what he has learned from scouting the area near the wayshrine. He has a few ideas for some sneaky sabotage..."},
		[5] = 
			{appendStepText="", stepTextKey="To stop the flow of Daedric reinforcements from Coldharbour, Raz suggests that Darien and I destroy the portal anchors in the camp in front of Gristmung Hold. We should also search the camp for information about the Worm Cult's plans."},
		["Destroy the Portal Anchors"] =
			{appendText=" \n\nFrom the top of the hill at the Grand Juncture Pass Wayshrine, four portal anchors on tile platforms are clearly visible. I need to head down into the camp and destroy them. First, I should check in with Darien and see how he's doing.\n"},
		["Search the Worm Cult Camp"] =
			{appendText=" \n\nWhile destroying the anchors, keep an eye out for important papers or plans in the camp, probably somewhere in or near the tents. Killing a few Daedra along the way wouldn't go amiss."},
		[6] = 
			{appendStepText="In the Worm Cult camp just below the Grand Juncture Pass Wayshrine, Darien and I had a little fun sabotaging the camp. ", stepTextKey="Now that we destroyed the portal anchors and recovered some Worm Cult documents, Darien suggests we head to the eastern overlook to discuss our next steps."},
		["Go to the Eastern Overlook"] =
			{appendText=" to get a better view of Gristmung Hold and see what the Worm Cult are up to. A large rock jutting out from the hillside looks perfect."},
		[7] = 
			{appendStepText="Below the Grand Juncture Pass Wayshrine, Darien and I have found a rocky overlook where we can consider our next move. ", stepTextKey="Now that we found a safe place to talk, I should see what Darien thinks of the documents we uncovered in the Worm Cult camp."},
		["Talk to Darien Gautier 1"] =
			{appendText=" about what we have learned and what we could do next to foil their plans.", stepTextKey="Now that we found a safe place to talk, I should see what Darien thinks of the documents we uncovered in the Worm Cult camp."},
		[8] = 
			{appendStepText="At our overlook below the Grand Juncture Pass Wayshrine, ", stepTextKey="Darien suggested I secure the ballistas atop the two guard platforms so we can turn them on Gristmung Hold. I just need to take out the Sentinels guarding them first."},
		["Capture the Enemy Ballistas"] =
			{appendText=" \n\nThe ballistas are at the top of platforms to the north and south of the camp below. I must take out the Sentinals protecting the ballistas by destroying their clawed platforms before they can see me."},
		[9] = 
			{appendStepText="In the Worm Cult camp below the Grand Juncture Pass Wayshrine, ", stepTextKey="I silenced the Sentinels and captured the ballistas. Now to let Prince Azah know we're ready to assault Gristmung Hold."},
		["Meet with Prince Azah"] =
			{appendText=" at the iron bridge leading to Gristmung Hold."},
		[10] = 
			{appendStepText="In the Worm Cult camp below the Grand Juncture Pass Wayshrine, ", stepTextKey="I silenced the Sentinels and captured the ballistas. Now to let Prince Azah know we're ready to assault Gristmung Hold."},
		["Talk to Prince Azah 1"] =
			{appendText=" and let him know we are ready to go.", stepTextKey="I silenced the Sentinels and captured the ballistas. Now to let Prince Azah know we're ready to assault Gristmung Hold."},
		[11] = 
			{appendStepText="After sabotaging the Worm Cult camp below the Grand Juncture Pass Wayshrine, ", stepTextKey="Walks-in-Ash and Darien went north to establish flanking positions before the attack, but they have yet to light their signal fires. Prince Azha wants me to go check on them."},
		["Find Walks-in-Ash and Darien"] =
			{appendText=". Just outside the north gates of the Worm Cult camp, a small trail heads down into the ravine. The unlit signal pyre can be seen in some ruins at the top of a rocky outcropping. Walks-in-Ash and Darien are in the ravine below the pyre, negotiating with the local Stone-Nest Argonians near a large totem."},
		[12] = 
			{appendStepText="Northeast of the Grand Juncture Pass Wayshrine, on a road leading north from the Worm Cult camp, ", stepTextKey="I arrived to find Darien and Walk-in-Ash surrounded by Stone-Nest Argonians. I should talk to their leader, Jeetra, and try to deescalate the situation."},
		["Talk to Jeetra 1"] =
			{appendText=". She seems wary of our plans, but believes that stealth is the better approach. She is willing to guide us to a secret way into the Hold, after lighting the signal pyre.", stepTextKey="I arrived to find Darien and Walk-in-Ash surrounded by Stone-Nest Argonians. I should talk to their leader, Jeetra, and try to deescalate the situation."},
		[13] = 
			{appendStepText="On the road north of the Worm Cult camp below the Grand Juncture Pass Wayshrine, ", stepTextKey="I agreed to help Jeetra rescue her people if she helps us get into Gristmung Hold. But first, I need to light the signal fire so Prince Azah begins the assault and provides us with a distraction."},
		["Light the Signal Flare"] =
			{appendText=" at the pyre amidst rocky fortifications at the top of the hill to the east."},
		[14] = 
			{appendStepText="Northeast of the Grand Juncture Pass Wayshrine, at the top of a hill near Gristmung Hold, ", stepTextKey="I lit the fire to signal the Fellowship advance force to begin their assault on Gristmung Hold. Now I should join Jeetra in the caverns beneath the hold so I can get inside."},
		["Go to the Cave Entrance Beneath the Hold"] =
			{appendText=", lit by a torch in the valley below the iron bridge. Jeetra is waiting by a pool of water under the Hold. Talk to her about the secret way into the Hold."},
		[15] = 
			{appendStepText="In the cavern underneath Gristmung Hold, east of the Grand Juncture Pass Wayshrine, ", stepTextKey="Jeetra wants us to use the ladder to reach the pipe that leads up into Gristmung Hold. They have another way to get inside and will meet us later."},
		["Enter Gristmung Hold"] =
			{appendText=" by climbing up the ladder."},
		[16] = 
			{appendStepText="At Gristmung Hold, east of the Grand Juncture Pass Wayshrine, ", stepTextKey="The Stirk Fellowship's assault hasn't broken through the main gate yet. Jeetra suggested we may be able to open the gate from the inside. We just need to reach the gate winches."},
		["Reach the Main Gate"] =
			{appendText=". Head up the stairs to the platform around the edge of the Hold. To the south, you can see the stairs you need to reach to open the gate. Follow the upper platform around to some stairs on the far side, then cross the central area to the stairs leading up to the winches - ideally without being seen - or at least without leaving anyone to tell the tale."},
		[17] = 
			{appendStepText="Within Gristmung Hold, ", stepTextKey="We reached the main gate and located the gate winches to open it. We should use the winches to open the gate and let the Stirk Fellowship advance force into the hold."},
		["Activate the Gate Winches"] =
			{appendText=" - there is one on each side of the gate."},
		[18] = 
			{appendStepText="In Gristmung Hold, ", stepTextKey="We got the gate open, but only long enough for Skordo, Walks, and a few Stirk soldiers to get inside. I should consult with Skordo about what to do next."},
		["Talk to Skordo the Knife 2"] =
			{appendText=". He wants us to free the Stone-Nest Argonian prisoners and find the traitor on the inside.", stepTextKey="We got the gate open, but only long enough for Skordo, Walks, and a few Stirk soldiers to get inside. I should consult with Skordo about what to do next."},
		[19] = 
			{appendStepText="In Gristmung Hold, ", stepTextKey="While Skordo and Walks defend the entryway and get the gate open for the rest of the advance force, Darien and I need to reach the hold's central keep so we can rescue the prisoners."},
		["Reach the Central Keep"] =
			{appendText=" by continuing along the outer ledge to the east. Look for a large metal door with lanterns on either side."},
		[20] = 
			{appendStepText="Within Gristmung Hold, east of the Grand Juncture Pass Wayshrine, ", stepTextKey="We entered the hold's central keep. Now to search around and find the prisoners before they are sacrificed."},
		["Search the Central Keep"] =
			{appendText=", down the stairs and through the rooms and passageways. A small room off of the library appears to hold some clues."},
		[21] = 
			{appendStepText="Within Gristmung Hold, we headed north of the library in the central keep. ", stepTextKey="While looking for the prisoners, Darien and I discovered a chamber full of soul reapers. I should look around and see what I can find."},
		["Search the Chamber"] =
			{appendText=" for any useful information."},
		[22] = 
			{appendStepText="In Gristmung Hold, a small chamber north of the library in the central keep held some clues. ", stepTextKey="We learned more about the new device the Worm Cult constructed, an improved soul reaper called a soul flayer. I should talk to Darien about what this all means."},
		["Talk to Darien Gautier 2"] =
			{appendText=" about what we found here.", stepTextKey="We learned more about the new device the Worm Cult constructed, an improved soul reaper called a soul flayer. I should talk to Darien about what this all means."},
		[23] = 
			{appendStepText="Within Gristmung Hold we are in its central keep. ", stepTextKey="We still need to find and rescue the prisoners before the Worm Cult sacrifices them. We should search deeper inside the keep."},
		["Find the Prisoners"] =
			{appendText=" by continuing through the passageways to the east and north."},
		[24] = 
			{appendStepText="Within Gristmung Hold's central keep, ", stepTextKey="I found Jeetra, but she's caught on the other side of a closed gate. I should talk to her and find out what the situation is."},
		["Talk to Jeetra 2"] =
			{appendText=". She has seen the prisoners, who were taken up the stairs nearby. We should follow and try to find them.", stepTextKey="I found Jeetra, but she's caught on the other side of a closed gate. I should talk to her and find out what the situation is."},
		[25] = 
			{appendStepText="Within Gristmung Hold's central keep, ", stepTextKey="Jeetra spotted a Daedra leading away the prisoners, including her egg-sister Baar-Jasa—who's also the Worm Cult defector we were hoping to find. Walks-in-Ash followed after them. We need to catch up and help her."},
		["Find Walks-in-Ash"] =
			{appendText=" and the prisoners by continuing up the staircase and exploring further into the keep."},
		[26] = 
			{appendStepText="Within the central keep of Gristmung Hold, ", stepTextKey="I found Walks-in-Ash observing the cultists from hiding. They appear to be starting a ritual using the shackle. I should talk to Walks-in-Ash and figure out how we save the prisoners."},
		["Talk to Walks-in-Ash"] =
			{appendText=" about how to stop the ritual and free the prisoners. I need to go through the far door and reach the ritual chamber."},
		[27] = 
			{appendStepText="The ritual has begun in the central keep of Gristmung Hold. ", stepTextKey="While Walks-in-Ash deals with the shackle and Darien sets out to free the prisoners, I need to defeat the dark adept and stop the ritual from being completed."},
		["Defeat the Dark Adept"] =
			{appendText=" and her minions in the ritual chamber."},
		[28] = 
			{appendStepText="In the ritual chamber within the central keep of Gristmung Hold, ", stepTextKey="I defeated the dark adept, but Walks-in-Ash and Darien aren't able to destroy the shackle. Darien has given up and asked me to take the Light of Meridia."},
		["Take the Light of Meridia"] =
			{appendText=" from the platform by the stairs, in front of Darien."},
		[29] = 
			{appendStepText="In the ritual chamber within the central keep of Gristmung Hold, ", stepTextKey="Darien wasn't able to destroy the shackle. I need to try to use the Light of Meridia to add its strength to Vanus's staff to help Walks finally destroy the shackle."},
		["Use the Light of Meridia"] =
			{appendText=" on the shackle in the center of the platform."},
		[30] = 
			{appendStepText="In the ritual chamber within the central keep of Gristmung Hold, ", stepTextKey="Darien looks exhausted and defeated after failing  to destroy the shackle with the Light of Meridia. I should check on him."},
		["Talk to Darien Gautier 3"] =
			{appendText=", standing dejected on the platform.", stepTextKey="Darien looks exhausted and defeated after failing  to destroy the shackle with the Light of Meridia. I should check on him."},
		[31] = 
			{appendStepText="", stepTextKey="Now that we destroyed the shackle in Gristmung Hold and rescued the Stone-Nest prisoners, I should head outside and rejoin the others."},
		["Rejoin Your Allies"] =
			{appendText=" through a passageway at the far end of the ritual chamber to the right of the altar lit by candles. I need to jump down from this place to the ground below and cross the river to the camp."},
		[32] = 
			{appendStepText="Across the river from Gristmung Hold, after escaping from the ritual chamber, ", stepTextKey="I found my allies in a small camp outside Gristmung Hold, talking with Jeetra and the rescued prisoners. I should report in to Prince Azah and find out how the battle turned out."},
		["Talk to Prince Azah 2"] =
			{appendText=" and compare notes about what happened, inside and outside the keep in Gristmung Hold.", stepTextKey="I found my allies in a small camp outside Gristmung Hold, talking with Jeetra and the rescued prisoners. I should report in to Prince Azah and find out how the battle turned out."},
		[33] = 
			{appendStepText="We assaulted Gristmung Hold. ", stepTextKey="We destroyed a shackle and weakened the Planemeld, cut off the Worm Cult's Daedric reinforcements, and broke the power of Gristmung Hold. I should see if Prince Azah has further orders."},
		["Talk to Prince Azah 3"] =
			{appendText=" to receive my reward and a well-deserved rest.", stepTextKey="We destroyed a shackle and weakened the Planemeld, cut off the Worm Cult's Daedric reinforcements, and broke the power of Gristmung Hold. I should see if Prince Azah has further orders."},
	},

[GetQuestName(7329)] = { --"Hunt for the Great Mage" --aashiana
		[1] = 
			{appendStepText="At our small camp just north of the Gristmung Hold Camp Wayshrine, ", stepTextKey="Prince Azah asked me to talk to Baar-Jasa, the Worm Cult defector, and see if she knows anything that can help us find Vanus Galerion."},
		["Talk to Baar-Jasa"] =
			{appendText=", the Argonian we rescued, standing near the campfire in prisoner's clothes. She has left a note from Vanus in a secret cache in an abandoned village nearby. I should try to find it."},
		[2] = 
			{appendStepText="At our small camp just north of the Gristmung Hold Camp Wayshrine, Baar-Jasa told me that ", stepTextKey="Before being captured by the Worm Cult, Baar-Jasa hid a note from Vanus Galerion in an abandoned Stone-Nest village. Jeetra and I need to go there and retrieve it."},
		["Go to the Abandoned Village"] =
			{appendText=" situated at the westernmost point of a large bay in the eastern coastline of Solstice."},
		[3] = 
			{appendStepText="In a small abandoned village on the westernmost point of a bay in Solstice's eastern coastline, ", stepTextKey="Baar-Jasa hid Vanus Galerion's note in a hidden cache in a stone totem. I should find the cache and recover the note."},
		["Find the Hidden Cache"] =
			{appendText=" inside a large stone house with a broken wheelbarrow in front of it. \n\nThe stone totem inside with red, white, and green carvings is where Baar-Jassa hid the cache. She couldn't come herself, but gave me a drawing showing the correct sequence of the carvings. I should use the buttons on the wall to turn the carvings on the totem until they match the drawing. Then I can open the cache and retrieve the note. "},
		[4] = 
			{appendStepText="In a small village on the west side of a bay along the eastern coastline of Solstice, I found the hidden cache with Vanus' note. ", stepTextKey="Vanus Galerion's note reveals a number of details about the Worm Cult and their plans. I should talk to Jeetra about this."},
		["Talk to Jeetra 1"] =
			{appendText=" about the note. She knows how to reach several of the locations mentioned by Vanus.", stepTextKey="Vanus Galerion's note reveals a number of details about the Worm Cult and their plans. I should talk to Jeetra about this."},
		[5] = 
			{appendStepText="In his note, ", stepTextKey="Vanus Galerion told us that the power source for the new soul flayers makes use of prefect bismuth crystals drawn from the Kaz-Neesak Mine. Jeetra says the mine is north of Xor-Hist and wants to accompany me there to investigate."},
		["Go to the Kaz-Neesak Mine"] =
			{appendText=", high in the cliffs of the central east coast of Solstice. A paved path south of the abandoned village leads east to the mine. Follow the path until it crosses a stone bridge, then just before the second stone bridge, turn left up the hill to the mine. This village also appears to have been occupied by Worm Cult forces."},
		[6] = 
			{appendStepText="In the cliffs high above the Xir-Hist Wayshrine, ", stepTextKey="I reached the Kaz-Neesak Mine. I should investigate the area."},
		["Investigate the Kaz-Neesak Mine"] =
			{appendText="\n\nThe entrance is in the cliffs at the far end of the mining encampment. Look for any information you can find that describes what they're doing here, most likely in the deepest recesses of the mine to keep it away from the prying eyes of outsiders."},
		[7] = 
			{appendStepText="Deep in the Kaz-Neesak Mine along the central east coast of Solstice, ", stepTextKey="We found orders to build more soul flayers and a map indicating where the Worm Cult plans to test them. I should confer with Jeetra about this."},
		["Talk to Jeetra 2"] =
			{appendText=" about what to do with this information.", stepTextKey="We found orders to build more soul flayers and a map indicating where the Worm Cult plans to test them. I should confer with Jeetra about this."},
		[8] = 
			{appendStepText="Jeetra suggests you divide up the most urgent tasks. She will continue the search for Vanus, while ", stepTextKey="I need to go to the harvest sites indicated on the map and destroy any soul flayers and recover any other clues I may find there. On the way out of the mine, find the Xor-Hist wayshrine across the road, by the stone bridge."},
		["Find the Soul Flayer Harvest Sites"] =
			{appendText=". From the Kaz-Neesak Mine and the Xor-Hist wayshrine, travel south along the paved trail, go past the town of Xor-Hist, then follow the road around to the southwest to a ruined village just before the Fellowship Forge crafting area. Worm Cult banners have been raised at the village."},
		[9] = 
			{appendStepText="At the southern end of the paved road that traverses the east coast of Solstice, ", stepTextKey="I reached one of the harvest sites indicated on the map. I need to destroy any soul flayers and recover any other clues I can find here."},
		["Investigate the Harvest Site"] =
			{appendText=". After I destroy the soul flayers and neutralize the threat, I should read the note on the desk near the entrance, which may help us understand what they're doing here.\n"},
		["Destroy Soul Flayers"] =
			{appendText="\n\nOne of the soul flayers can be found just to the left of the entrance between two abandoned buildings, while the other is visible at the top of the stairs on the other side of the courtyard. Thankfully, they're not active yet."},
		[10] = 
			{appendStepText="Where the eastern coastal road meets the southern end of the central north-south road, near the Stone Cove Wayshrine, ", stepTextKey="I need to locate the second harvest site."},
		["Find the Other Soul Flayer Harvest Site"] =
			{appendText=", up on the hill beside a large rock outcropping just north of the crossroads. Destroy the soul flayer next to the outcropping, then cross a stone bridge to the west, where the other soul flayer is located. Once the soul flayers have been neutralized, there is some information on a nearby cart at a stone pavilion that may prove useful."},
		[11] = 
			{appendStepText="In southeastern Solstice, ", stepTextKey="I explored both harvest sites and destroyed the unactivated soul flayers. I should return to the Fellowship camp and speak with Darien before I report to Prince Azah. My companions are worried about him."},
		["Return to the Gristmung Fellowship Camp"] =
			{appendText=" near the wayshrine of the same name, across the river from Gristmung Hold."},
		[12] = 
			{appendStepText="In southeastern Solstice, ", stepTextKey="I explored both harvest sites and destroyed the unactivated soul flayers. I should return to the Fellowship camp and speak with Darien before I report to Prince Azah. My companions are worried about him."},
		["Talk to Darien"] =
			{appendText=" near the Gristmung Hold Camp."},
		[13] = 
			{appendStepText="At the Gristmung Hold Camp, ", stepTextKey="I should speak to Prince Azah and let him know the result of my mission."},
		["Talk to Prince Azah 1"] =
			{appendText=".", stepTextKey="I should speak to Prince Azah and let him know the result of my mission."},
		[14] = 
			{appendStepText="", stepTextKey="I found Vanus Galerion's notes, destroyed some soul flayers, learned they are more dangerous than we thought, and found a clue as to where Vanus is being held. I should talk to Prince Azah."},
		["Talk to Prince Azah 2"] =
			{appendText=" about what we have learned and what to do next.", stepTextKey="I found Vanus Galerion's notes, destroyed some soul flayers, learned they are more dangerous than we thought, and found a clue as to where Vanus is being held. I should talk to Prince Azah."},
	},



[GetQuestName(7285)] = { --"The Deep Tombs of Xul-Haj" --aashiana
		[1] = 
			{appendStepText="At the Gristmung Hold Camp, we learned that ", stepTextKey="Vanus has been taken to a ritual site in an Argonian xanmeer. I should speak with Jeetra and see if she can point us at the correct location."},
		["Talk to Jeetra 1"] =
			{appendText=". She reluctantly agreed to help me investigate Xul-Haj, where Vanus may be held captive, after we check on the safety of her village near the site.", stepTextKey="Vanus has been taken to a ritual site in an Argonian xanmeer. I should speak with Jeetra and see if she can point us at the correct location."},
		[2] = 
			{appendStepText="", stepTextKey="Jeetra believes the tomb the Worm Cult seeks is the ancient necropolis of Xul-Haj. I should meet her at her village, which is near the xanmeer tomb."},
		["Go to Jeetra's Village"] =
			{appendText=" far to the north, nestled into the southeast corner of the large bay of northern Solstice."},
		[3] = 
			{appendStepText="On the northern coast of Solstice, northeast of the Salt-Air Station, ", stepTextKey="Darien met me at the village, but something has happened here. We should look around."},
		["Investigate Village"] =
			{appendText=". It looks like the Worm Cult has already invaded! A soul flayer stands at the center of the village, which is deathly quiet... Only the note from the dead cultist has left any clues as to what happened here."},
		[4] = 
			{appendStepText="At her village on the southeast coastline of the great northern bay of Solstice, ", stepTextKey="We don't see Jeetra's body among the dead. I should look around and see if I can find her."},
		["Find Jeetra"] =
			{appendText=". She arrived after the destruction wrought by the soul flayer, and has taken refuge in her home in the northeast of the village to mourn the dead and plan her revenge."},
		[5] = 
			{appendStepText="Jeetra explained that Xul-Haj was a necropolis for the Argonian people. ", stepTextKey="Jeetra agreed to join us at Xul-Haj and help us stop the Worm Cult from raising an undead army and rescue Vanus Galerion. I should meet her there."},
		["Go to Xul-Haj"] =
			{appendText=", in the center of the northeastern peninsula of Solstice, on the west bank of the river. We must travel either north or south around the rocky hills to the east to reach the xanmeer. It is northwest of the Mor Naril Camp Wayshrine."},
		[6] = 
			{appendStepText="In the central area of the northeastern peninsula of Solstice, ", stepTextKey="I met Jeetra and Darien at the entrance to Xul-Haj. We need to enter the ruins to stop the Worm Cult and rescue Vanus Galerion."},
		["Enter Xul-Haj"] =
			{appendText=" through the imposing stone door up the stairs. Jeetra warned us to stay close, as there are many dangers ahead, and not just from the Worm Cult."},
		[7] = 
			{appendStepText="We found the deep tombs in the central area on the northeastern peninsula of Solstice. ", stepTextKey="We entered the Xul-Haj ruins. Now to look around and try to find the Worm Cult and Vanus."},
		["Explore Xul-Haj 1"] =
			{appendText=". The main door into the ruins is warded; we will need to find another way in.", stepTextKey="We entered the Xul-Haj ruins. Now to look around and try to find the Worm Cult and Vanus."},
		[8] = 
			{appendStepText="In northeastern Solstice, we entered Xul-Haj. ", stepTextKey="A ward blocks the door leading to the deep tombs. I should talk to Jeetra and see if she knows another way to get there."},
		["Talk to Jeetra 2"] =
			{appendText=". She has an idea of another way in; unfortunately, it involves a lot of swimming. Meanwhile, Darien fell through the floor...", stepTextKey="A ward blocks the door leading to the deep tombs. I should talk to Jeetra and see if she knows another way to get there."},
		[9] = 
			{appendStepText="In northeastern Solstice, within the entryway to Xul-Haj, ", stepTextKey="Gabrielle's voice led Darien into a trap. Now we need to search Xul-Haj not just for a way to reach the deep tombs, but in order to find Darien."},
		["Explore Xul-Haj 2"] =
			{appendText=". I'll follow Jeetra into the lower halls; she seems to know where she's going. After dispatching some Worm Cult soul-stealers, we found an Argonian ghost that seems to be trying to get our attention.", stepTextKey="Gabrielle's voice led Darien into a trap. Now we need to search Xul-Haj not just for a way to reach the deep tombs, but in order to find Darien."},
		[10] = 
			{appendStepText="We entered the lower halls of Xul-Haj in northeastern Solstice. ", stepTextKey="As we made our way toward the deep tombs, a spirit materialized before us and pointed out Darien across the way. Now it seems like it wants to speak to us. I should talk to it."},
		["Talk to the Xul-Haj Spirit"] =
			{appendText=". We reassured him that we are neither looters nor soul-stealers. He has offered to give us such help as he can. It appears to involve... more swimming."},
		[11] = 
			{appendStepText="Within the lower halls of Xul-Haj in northeastern Solstice, ", stepTextKey="The Worm Cult tampered with the water levels in the xanmeer, cutting off our access to the deep tombs. We need to head to the sacred wellsprings and find a way to raise the water levels again."},
		["Reach the Wellspring 1"] =
			{appendText=" through the eastern door and into the depths of the xanmeer to the Cistern Chamber, then to the north to the Wellspring.", stepTextKey="The Worm Cult tampered with the water levels in the xanmeer, cutting off our access to the deep tombs. We need to head to the sacred wellsprings and find a way to raise the water levels again."},
		[12] = 
			{appendStepText="Within the Wellspring Chamber of Xul-Haj in northeast Solstice, ", stepTextKey="The Worm Cult moved the sacred wellspring stones and stopped the flow of water from the wellspring. I need to put the stones back into their proper position to restore the flow of water."},
		["Talk to Jeetra 3"] =
			{appendText=" about this puzzle we must solve to raise the water level.", stepTextKey="The Worm Cult moved the sacred wellspring stones and stopped the flow of water from the wellspring. I need to put the stones back into their proper position to restore the flow of water."},
		[13] = 
			{appendStepText="In the Wellspring Chamber deep in Xul-Haj in northeastern Solstice, ", stepTextKey="The Worm Cult moved the sacred wellspring stones and stopped the flow of water from the wellspring. I need to put the stones back into their proper position to restore the flow of water."},
		["Move the Sacred Stones 1"] =
			{appendText=" across the grated floor, until each one is resting on a plate that triggers the water to rise. The plate in the first chamber is just behind the stone, near the central pillars. The second stone on the other side of the pillars must be moved to a grate opposite the first one. The stones may be moved by light or heavy attacks.", stepTextKey="The Worm Cult moved the sacred wellspring stones and stopped the flow of water from the wellspring. I need to put the stones back into their proper position to restore the flow of water."},
		[14] = 
			{appendStepText="In the Wellspring Chamber within Xul-Haj, the deep tombs of northeastern Solstice, ", stepTextKey="I restored the flow of water to flood the chambers. I should return to the cistern chamber and see if we can move forward now."},
		["Return to the Cistern Chamber"] =
			{appendText=" through a doorway to the south."},
		[15] = 
			{appendStepText="Within the Cistern Chamber in Xul-Haj, of northeastern Solstice, the water has risen partway. ", stepTextKey="Apparently, we need to locate another wellspring to get the water level to the right depth for us to reach Darien and the deep tombs. I need to explore the way ahead to find the next wellspring."},
		["Explore Xul-Haj 3"] =
			{appendText=" by entering the flooded cistern and swimming to the far side, where another door may give us entry to new areas.", stepTextKey="Apparently, we need to locate another wellspring to get the water level to the right depth for us to reach Darien and the deep tombs. I need to explore the way ahead to find the next wellspring."},
		[16] = 
			{appendStepText="We continue to work in the depths of Xul-Haj of northeastern Solstice. ", stepTextKey="We need to find a second wellspring to release more water into the chambers."},
		["Reach the Wellspring 2"] =
			{appendText=" through the passages beyond the northwest door in the flooded Cistern.", stepTextKey="We need to find a second wellspring to release more water into the chambers."},
		[17] = 
			{appendStepText="In the depths of Xul-Haj in northeastern Solstice, once again ", stepTextKey="I need to move the sacred stones to release the waters of this wellspring and fully flood the chambers."},
		["Move the Sacred Stones 2"] =
			{appendText=" to the pressure plates using light or heavy attacks. The stone near the entrance needs to be moved around the platform in front of us to a grate on the far side. \n\nA gate will open to the south, which allows us to move the second stone across the walkway. It must be moved through the arch and then to the left, to a spot in front of a closed gate.\n\nThe first stone must then be moved off of its plate, all the way across the floor, to the right, and to the right again to another pressure plate, which will raise the second gate.\n\nCross the walkway to the other stone and move it through the now open gate, then to the pressure plate in front of the pillar.", stepTextKey="I need to move the sacred stones to release the waters of this wellspring and fully flood the chambers."},
		[18] = 
			{appendStepText="In the depths of Xul-Haj in northeastern Solstice, ", stepTextKey="I released water from the second wellspring. Now to return to the cistern chamber and see if we can reach Darien."},
		["Search for Darien"] =
			{appendText=", heading up the steps to the north and east and back through the passageways to the cistern chamber. The water is higher now, and I can swim to the western platform. We can hear Darien through the door..."},
		[19] = 
			{appendStepText="In the depths of Xul-Haj in northeastern Solstice, ", stepTextKey="Darien, mad with grief, fled deeper into the xanmeer to follow the false spirit. Now that we have restored the water from the wellsprings, I need to follow him."},
		["Rescue Darien"] =
			{appendText=" from the clutches of a false spirit and Worm Cultists."},
		[20] = 
			{appendStepText="In the depths of Xul-Haj in northeastern Solstice, ", stepTextKey="I rescued Darien from a false spirit that turned out to be a Harvester. Now I should talk to him."},
		["Talk to Darien"] =
			{appendText=" about his feelings of despair."},
		[21] = 
			{appendStepText="In the depths of Xul-Haj in northeastern Solstice, I spoke with Darien. ", stepTextKey="Now that Darien is back with us, we need to find Vanus and stop the Worm Cult ritual."},
		["Find Vanus Galerion"] =
			{appendText=". The only passages we haven't explored yet are to the west, behind the altar. On the way, perhaps the ghost will appear to guide us. From the western chamber, we should go south to the Funerary Temple."},
		[22] = 
			{appendStepText="In the depths of Xul-Haj in northeastern Solstice, ", stepTextKey="I reached the funerary temple. Mannimarco is drawing energy from Vanus to power his ritual and perform a mass resurrection of the bodies in this tomb. I need to interrupt the ritual and set Vanus free."},
		["Stop the Ritual"] =
			{appendText=" by defeating the minions and allowing Vanus to get free."},
		[23] = 
			{appendStepText="In the Funerary Chamber of Xul-Haj in northeastern Solstice, we succeeded. ", stepTextKey="We freed Vanus and stopped the ritual. Now, while Vanus keeps Mannimarco distracted, I need to destroy the shackle set up here."},
		["Destroy the Shackle"] =
			{appendText=" with the Light of Meridia."},
		[24] = 
			{appendStepText="In the Funerary Chamber of Xul-Haj in northeast Solstice, another success. ", stepTextKey="We stopped the ritual, rescued Vanus, and destroyed another Planemeld shackle. Mannimarco managed to escape, but we did good work here. I should leave the tomb to regroup with my allies outside."},
		["Exit Xul-Haj"] =
			{appendText=" using the portal Vanus created."},
		[25] = 
			{appendStepText="", stepTextKey="We stopped the ritual, rescued Vanus, and destroyed another Planemeld shackle. Mannimarco managed to escape, but we did good work here. I should leave the tomb to regroup with my allies outside."},
		["Meet Your Allies Outside Xul-Haj"] =
			{appendText=" in northeastern Solstice."},
		[26] = 
			{appendStepText="Outside Xul-Haj In northeastern Solstice, southwest of the Mor Naril Camp Wayshrine, ", stepTextKey="I rejoined Vanus and the others outside Xul-Haj, but we have been joined by the ancient Argonian spirit. I should talk with him."},
		["Talk to Ukka-Naza"] =
			{appendText=" to receive his thanks ... and a warning."},
		[27] = 
			{appendStepText="Outside Xul-Haj in northeastern Solstice, southwest of the Mor Naril Camp Wayshrine, I spoke with Ukka-Raza. ", stepTextKey="The spirit warned of Mor Naril, the Final Dark, and the wraithforge that Mannimarco is pulling out of Coldharbour. It seems that Vanus may know something about all this. I should ask him about it."},
		["Talk to Vanus Galerion"] =
			{appendText=" to compare notes and catch up on everything that has happened."},
		[28] = 
			{appendStepText="", stepTextKey="We saved Vanus, stopped the Worm Cult from raising an army of undead, and broke another Planemeld shackle, but Mannimarco escaped. Now I should join my allies at the Mor Naril Fellowship Camp."},
		["Go to the Mor Naril Fellowship Camp"] =
			{appendText=", east of Xul-Haj. It is up the mountain, southeast of the Mor Naril Camp Wayshrine in the northeastern peninsula of Solstice."},
		[29] = 
			{appendStepText="", stepTextKey="We saved Vanus, stopped the Worm Cult from raising an army of undead, and broke another Planemeld shackle, but Mannimarco escaped. Now I should give my report to Prince Azah."},
		["Talk to Prince Azah"] =
			{appendText=" in the Mor Naril Fellowship Camp in northeastern Solstice. He is standing before a large white tent on the lower level."},
	},


[GetQuestName(7317)] = { --"The Gates of Mor Naril" --aashiana
		[1] = 
			{appendStepText="From the Fellowship Camp near the Mor Naril Camp Wayshrine in northeast Solstice, ", stepTextKey="Razum-dar went ahead to study the soul flayer emplacements the Worm Cult set up to defend Mor Naril. I should find him and see what he learned."},
		["Find Razum-dar"] =
			{appendText=". He is scouting down a hill from the gates of Mor Naril, at the south end of the peninsula in northeast Solstice."},
		[2] = 
			{appendStepText="", stepTextKey="Razum-dar went ahead to study the soul flayer emplacements the Worm Cult set up to defend Mor Naril. I should find him and see what he learned."},
		["Talk to Razum-dar 1"] =
			{appendText=".", stepTextKey="Razum-dar went ahead to study the soul flayer emplacements the Worm Cult set up to defend Mor Naril. I should find him and see what he learned."},
		[3] = 
			{appendStepText="West of the gates of Mor Naril in northeast Solstice, ", stepTextKey="Razum-dar said he noticed smoke rising from a different part of the ruins. He suspects there's a Worm Cult camp outside the walls. I should investigate."},
		["Find the Source of the Smoke"] =
			{appendText=" to the west, carefully sneaking past Worm Cult minions with torches."},
		[4] = 
			{appendStepText="West of the gates of Mor Naril in northeast Solstice, ", stepTextKey="Razum-dar said he noticed smoke rising from a different part of the ruins. He suspects there's a Worm Cult camp outside the walls. I should investigate."},
		["Investigate the Worm Cult Camp"] =
			{appendText=" down the hill and west from the gates of Mor Naril. There's just a few supplies and a small campfire here. Maybe the note on the bench will provide some answers."},
		[5] = 
			{appendStepText="We investigated the small camp west of the gates to Mor Naril in northeast Solstice. ", stepTextKey="A letter from Mannimarco we found in the camp suggests that a deer was somehow able to bypass the death fields of the soul flayers. I need to take a closer look at the defenses set west of the camp."},
		["Investigate the Soul Flayer"] =
			{appendText=" southwest of the small camp, near the end of the ramparts of Mor Naril. Somehow, a deer got past the defenses and is standing near a large Stone-Nest statue sitting on the ground. A Worm Cult minion is lying dead on the rampart nearby."},
		[6] = 
			{appendStepText="On the ramparts west of the gates of Mor Naril in northeast Solstice, ", stepTextKey="Raz and I found a dead Worm Cultist who seems to have been killed while tinkering with a soul flayer. I should discuss our discoveries with him."},
		["Talk to Razum-dar 2"] =
			{appendText=". This situation has left us with more questions than answers. We need more information than we can safely find here.", stepTextKey="Raz and I found a dead Worm Cultist who seems to have been killed while tinkering with a soul flayer. I should discuss our discoveries with him."},
		[7] = 
			{appendStepText="On the ramparts west of the gates of Mor Naril in northeast Solstice, ", stepTextKey="Razum-dar thinks we should consult with our Stone-Nest allies about what we found on the dead Worm Cultist. I should return to camp and speak with Jeetra."},
		["Return to Mor Naril Fellowship Camp"] =
			{appendText=", southeast of the Mor Naril Camp Wayshrine."},
		[8] = 
			{appendStepText="", stepTextKey="Razum-dar suggested that we ask our Stone-Nest allies about the statue we found near Mor Naril. I need to speak with Jeetra."},
		["Find Jeetra"] =
			{appendText=" in the lower part of the Mor Naril Fellowship Camp, near the central watchtower."},
		[9] = 
			{appendStepText="", stepTextKey="Razum-dar suggested that we ask our Stone-Nest allies about the statue we found near Mor Naril. I need to speak with Jeetra."},
		["Talk to Jeetra 1"] =
			{appendText=" about what we found on the Mor Naril ramparts.", stepTextKey="Razum-dar suggested that we ask our Stone-Nest allies about the statue we found near Mor Naril. I need to speak with Jeetra."},
		[10] = 
			{appendStepText="At the Mor Naril Fellowship Camp in northeast Solstice, ", stepTextKey="Jeetra revealed that her people fought against Mor Naril in the distant past. She offered to introduce me to an elder who may know more about the voskrona colossals. I need to meet her in the caves of Basking-Stone."},
		["Go to Basking-Stone Refuge"] =
			{appendText=", southwest of Mor Naril. Follow the road outside the camp southwest, past Mor Naril. Just before the road passes through a large cavern, turn right and go around the cavern and down a small ravine. Continue on that path to a cave entrance covered with vines to the left, lit by a torch. The Elder Jeetra spoke of should be inside."},
		[11] = 
			{appendStepText="Southwest of Mor Naril, ", stepTextKey="I reached the Basking-Stone Refuge and Elder Tso-Nassa has agreed to speak with me. I should talk to him."},
		["Talk to Elder Tso-Nassa 1"] =
			{appendText=", at the bottom of the path through the cave and across a rope bridge. He can tell me of the legends regarding the Voskrona Colossals."},
		[12] = 
			{appendStepText="Southwest of Mor Naril, within the Basking-Stone Caves, ", stepTextKey="Elder Tso-Nassa told me that knowledge of how to awaken the voskrona colossals has been lost. He suggested I check the Corelanyan library at the Sea and Sword Lodge for any records preserved there."},
		["Enter the Sea and Sword Lodge"] =
			{appendText=". This Corelanya training ground lies north of the Grand Juncture Pass Wayshrine, against the east side of the central mountains. Enter through the large wooden double doors."},
		[13] = 
			{appendStepText="North of the Grand Juncture Pass Wayshrine along the mountains, ", stepTextKey="I need to find the library in the Sea and Sword Lodge. Jeetra says it's in the southern section of the complex."},
		["Find the Library"] =
			{appendText=" in the southern part of the Lodge. I found an unexpected tunnel through the building, heading south from the central fountain. It leads to a large room circled by pillars and bookcases."},
		[14] = 
			{appendStepText="North of the Grand Junction Wayshrine, through a tunnel in the Sea and Sword Lodge,  ", stepTextKey="I located the library, but the door is locked. Jeetra suggested there may be a key in the nearby study hall, or I can try to pick the lock."},
		["Find a Key"] =
			{appendText=" in the study hall, which can be reached through the large cavern, just north and to the left. Worm Cult sentinels are guarding something in the antechamber, where a safe and other valuables are stored. Perhaps the key is here? If not, I can always pick the lock."},
		["Pick the Lock"] =
			{appendText=", if I can."},
		[15] = 
			{appendStepText="In the main library at the south end of the Sea and Sword Lodge, north of the Grand Junction Wayshrine, ", stepTextKey="I unlocked the door. Time to see if anything in the library can help us overcome the soul flayer death fields."},
		["Enter the Library"] =
			{appendText=", across a stone bridge and down the stairs to the lower level."},
		[16] = 
			{appendStepText="In the lower section of the library at the south end of the Sea and Sword Lodge, ", stepTextKey="The librarian is still here. She should know where I can find the old Corelanya manuscripts. I should talk to her."},
		["Talk to Librarian Tindensea"] =
			{appendText=", who cautiously agreed to let us see the manuscripts referring to the Voskrona Colossals."},
		[17] = 
			{appendStepText="In the lower section of the library at the south end of the Sea and Sword Lodge, ", stepTextKey="Librarian Tindensea retrieved two ancient Corelanya texts that could be relevant to my task. I should examine them."},
		["Examine the Guardians of Mor Naril"] =
			{appendText=" on the lectern to the right, glowing blue."},
		["Examine the Chronicles of Kinlord Orlemar"] =
			{appendText=" on the lectern to the left, glowing blue."},
		[18] = 
			{appendStepText="In the lower section of the library at the south end of the Sea and Sword Lodge, ", stepTextKey="The Corelanya texts described the stone colossals keeping watch over Mor NariI. I should discuss my findings with Jeetra."},
		["Talk to Jeetra 2"] =
			{appendText=", standing by the doorway, about what I gathered from the old records.", stepTextKey="The Corelanya texts described the stone colossals keeping watch over Mor NariI. I should discuss my findings with Jeetra."},
		[19] = 
			{appendStepText="From what we learned in the library of the Sea and Sword Lodge, ", stepTextKey="Jeetra thinks she knows the location of the old manor where Kinlord Orlemar took the Eyes of the Colossal and marked it on my map. We should see if they are still there."},
		["Go to Vaedinhill Manor"] =
			{appendText=", farther north along the main road, through an area that looks like Coldharbour. The old manor is across the road from where a skyshard glows on top of a ledge."},
		[20] = 
			{appendStepText="North of the Sea and Sword Lodge, and southeast of the Caterwaul Cove Wayshrine,  ", stepTextKey="I found the ruins of Vaedinhill Manor. The kinlord's vault is supposed to lie in the caverns below the old manor. I should look for a way down."},
		["Locate the Cavern Entrance"] =
			{appendText=" within the ruins to the west below, where spiders and ghosts dwell. The cavern entrance is near the center of the ruins. Lanterns still light the stairs leading down."},
		[21] = 
			{appendStepText="North of the Sea and Sword Lodge and southeast of the Caterwaul Cove Wayshrine, I located Vaedinhill Manor. In the center of the ruins, ", stepTextKey="I found the entrance to the caverns beneath Vaedinhill Manor. I should explore the caverns and find the kinlord's vault."},
		["Locate Vaedinhill Vault"] =
			{appendText=", through the trapdoor and the caverns below. After passing through the caves, I have found some ruins, where a ghost appears to be reminiscing while gazing at some paintings on the wall."},
		[22] = 
			{appendStepText="I entered the cavern beneath the ruins of Vaedinhill Manor, southeast of the Caterwaul Cove Wayshrine. At the end of a stone passageway, ", stepTextKey="I found the vault. Now I just need to figure out how to get inside."},
		["Open the Vault"] =
			{appendText=". It is warded by some kind of puzzle. The four braziers in front of the door may provide clues that will help me remove the ward. Each has a symbol on it that probably relates to one of the paintings."},
		[23] = 
			{appendStepText="In the caves below the ruins of Vaedinhill Manor, ", stepTextKey="I successfully removed the ward on the vault door. I should explore inside."},
		["Enter Vaedinhill Vault"] =
			{appendText="."},
		[24] = 
			{appendStepText="Underneath the ruins of Vaedinhill Manor, north of the Sea and Sword Lodge, ", stepTextKey="I should search the vault for the Eyes of the Colossal."},
		["Search the Vault"] =
			{appendText=". A note on the desk suggests that the Eyes of the Colossal must still be here. There is a small open trunk by a bookcase in the southern part of the vault."},
		[25] = 
			{appendStepText="Underneath the ruins of Vaedinhill Manor, north of the Sea and Sword Lodge, ", stepTextKey="I found the crystals that once served as a voskrona colossal's eyes. I should take them."},
		["Take the Eyes of the Colossal"] =
			{appendText=" from the small trunk."},
		[26] = 
			{appendStepText="Underneath the ruins of Vaedinhill Manor, north of the Sea and Sword Lodge, ", stepTextKey="I found the Eyes of the Colossal. I should show them to Jeetra."},
		["Talk to Jeetra 3"] =
			{appendText=" about where to take the eyes so they can be used in the battle to come.", stepTextKey="I found the Eyes of the Colossal. I should show them to Jeetra."},
		[27] = 
			{appendStepText="", stepTextKey="Jeetra suggested I take the Eyes of the Colossal and the Corelanya texts to Elder Tso-Nassa. She will bring him to the Stirk Fellowship camp outside Mor Naril."},
		["Return to the Mor Naril Fellowship Camp"] =
			{appendText=" in northeast Solstice, southeast of the Mor Naril Camp Wayshrine."},
		[28] = 
			{appendStepText="", stepTextKey="Jeetra suggested I take the Eyes of the Colossal and the Corelanya texts to Elder Tso-Nassa. She will bring him to the Stirk Fellowship camp outside Mor Naril."},
		["Talk to Elder Tso-Nassa 2"] =
			{appendText=". He waits by the command tent in the central part of the camp that is southeast of the Mor Naril Camp Wayshrine in northeast Solstice.", stepTextKey="Jeetra suggested I take the Eyes of the Colossal and the Corelanya texts to Elder Tso-Nassa. She will bring him to the Stirk Fellowship camp outside Mor Naril."},
		[29] = 
			{appendStepText="At the central command tent in the Mor Naril Fellowship Camp in northeast Solstice, ", stepTextKey="I should speak to Prince Azah about the crystalline eyes we discovered."},
		["Talk to Prince Azah"] =
			{appendText=" about how we can use the Voskrona Colossals to aid us in battle."},
	},


[GetQuestName(7286)] = { --"The Final Dark" --aashiana
		[1] = 
			{appendStepText="Southeast of the Mor Naril Camp Wayshrine in northeast Solstice, we prepare for battle. At the command tent in the center of the Fellowship Camp southeast of the Mor Naril Camp Wayshrine, all of my companions have gathered in preparation for the final assault on Mor Naril. I should speak to them all before departing.\n\nThe fortress and the impending Planemeld are clearly visible from the command tent - a dark vision of what we are about to walk into, come what may. ", stepTextKey="Prince Azah's advance force located a dormant voskrona colossal just inside Mor Naril's walls. I'm supposed to meet Elder Tso-Nassa there."},
		["Enter Mor Naril"] =
			{appendText=" at its gates south of the camp. Near the fortress, our company is waiting. I've been directed to scale the wall using a ladder to reach a platform inside."},
		[2] = 
			{appendStepText="In northeast Solstice, ", stepTextKey="I entered Mor Naril and found Darien waiting for me. I should speak to him."},
		["Talk to Darien Gautier 1"] =
			{appendText=" to prepare for the start of the battle.", stepTextKey="I entered Mor Naril and found Darien waiting for me. I should speak to him."},
		[3] = 
			{appendStepText="Inside the walls of Mor Naril in northeast Solstice, ", stepTextKey="Elder Tso-Nassa is waiting near the voskrona colossal selected for the attack. I need to find him so we can begin our assault."},
		["Reach the Colossal"] =
			{appendText=" down the stairs to the west, then up the other side and to the left along the platform, where the Elder and the Colossal are waiting."},
		[4] = 
			{appendStepText="On the northwest platform within Mor Naril, in northeast Solstice, ", stepTextKey="Elder Tso-Nassa is waiting for me beside an ancient voskrona statue. I should speak with him."},
		["Talk to Elder Tso-Nassa"] =
			{appendText=" about how to wake the Colossal and transfer my spirit into it."},
		[5] = 
			{appendStepText="On the northwest platform within Mor Naril, in northeast Solstice, ", stepTextKey="Elder Tso-Nassa asked me to place the Eyes of the Colossal on the statue to bring it to life."},
		["Place the Eyes of the Colossal 1"] =
			{appendText=" onto the statue.", stepTextKey="Elder Tso-Nassa asked me to place the Eyes of the Colossal on the statue to bring it to life."},
		[6] = 
			{appendStepText="Within Mor Naril, Vanus provided the energy to bring the Colossal to life. Now it's my turn. ", stepTextKey="Elder Tso-Nassa needs me to control the voskrona colossal and guide it where it needs to go."},
		["Take Control of the Voskrona Colossal 1"] =
			{appendText=" by attuning my spirit with it. ", stepTextKey="Elder Tso-Nassa needs me to control the voskrona colossal and guide it where it needs to go."},
		[7] = 
			{appendStepText="In Mor Naril, Vanus is able to give me battle advice telepathically. ", stepTextKey="My will now controls the voskrona colossal. I should use this form to smash through the soul flayers and breach the inner defenses of Mor Naril."},
		["Destroy the Soul Flayers 1"] =
			{appendText=" with my new, or rather, ancient skills. I should continue down this central path and destroy everything in the Fellowship's way.", stepTextKey="My will now controls the voskrona colossal. I should use this form to smash through the soul flayers and breach the inner defenses of Mor Naril."},
		[8] = 
			{appendStepText="In the northern area of Mor Naril, ", stepTextKey="I broke through the soul flayers and smashed Mor Naril's inner gate. I should clear out the Worm Cultists defending the courtyard."},
		["Clear the Courtyard"] =
			{appendText=" in the southeast area of Mor Naril. A large titan bars our way. This, I can handle with Darien's help.\n\nOnce we clear the courtyard, Darien and I should head up the stairs to the northwest to eliminate any other Daedra we find there."},
		[9] = 
			{appendStepText="In northeast Solstice, our battle has begun. ", stepTextKey="My allies and I secured the courtyard of Mor Naril. I should talk to Prince Azah about our next steps."},
		["Talk to Prince Azah 1"] =
			{appendText=" about our next steps - how to destroy the Wraithforge. We need to divert Mannimarco's attention. Prince Azah will take care of that, while I choose an ally to go with me to the Wraithforge. He gave me the Eyes of the Colossal in case I can use them again.", stepTextKey="My allies and I secured the courtyard of Mor Naril. I should talk to Prince Azah about our next steps."},
		[10] = 
			{appendStepText="In northeast Solstice, in the center of Mor Naril, ", stepTextKey="Prince Azah wants me to find the way to the wraithforge. I should choose an ally to join me."},
		["Choose an Ally"] =
			{appendText=" to go with me."},
		[11] = 
			{appendStepText="In the fortress, we destroyed the soul flayers in the Fellowship's path. ", stepTextKey="My ally and I need to search Mor Naril. We must find a way to reach the wraithforge."},
		["Search Mor Naril"] =
			{appendText=", entering through the large double doors in front of us."},
		[12] = 
			{appendStepText="In northeast Solstice, we reached Mor Naril's central \"gardens.\" ", stepTextKey="We found some allies blocked by a soul flayer, but there's another voskrona colossal nearby. I should use the Eyes of the Colossal to activate it."},
		["Place the Eyes of the Colossal 2"] =
			{appendText=" into the Voskrona.", stepTextKey="We found some allies blocked by a soul flayer, but there's another voskrona colossal nearby. I should use the Eyes of the Colossal to activate it."},
		[13] = 
			{appendStepText="In northeast Solstice, in the center of Mor Naril, I used the Eyes again. ", stepTextKey="The colossal has been activated. I should use the activation rune to take control."},
		["Take Control of the Voskrona Colossal 2"] =
			{appendText=" and move through the gate ahead.", stepTextKey="The colossal has been activated. I should use the activation rune to take control."},
		[14] = 
			{appendStepText="In northeast Solstice, ", stepTextKey="I found more soul flayers in a sinister garden within Mor Naril's walls. I should disable them so the Fellowship can advance."},
		["Destroy the Soul Flayers 2"] =
			{appendText=" blocking our path to the Wraithforge.", stepTextKey="I found more soul flayers in a sinister garden within Mor Naril's walls. I should disable them so the Fellowship can advance."},
		[15] = 
			{appendStepText="In northeast Solstice, in the center of Mor Naril, ", stepTextKey="I cleared a path through the soul flayers in Mor Naril's gardens. Now Prince Azah wants to speak with me."},
		["Talk to Prince Azah 2"] =
			{appendText=", further into the gardens. He wants me to follow Vanus and help him, through the double doors into the Mor Naril Priory nearby.", stepTextKey="I cleared a path through the soul flayers in Mor Naril's gardens. Now Prince Azah wants to speak with me."},
		[16] = 
			{appendStepText="In northeast Solstice, in the Gardens of Mor Naril, ", stepTextKey="Prince Azah told me that Vanus Galerion went off in search of some new threat. He wants me to find Vanus and regroup with the Fellowship as I continue to look for the wraithforge."},
		["Find Vanus Galerion"] =
			{appendText=". He must have gone through the Mor Naril Priory and the passages beyond. There is some kind of temple here, where a light is contained."},
		[17] = 
			{appendStepText="In the Temple within the Mor Naril Priory, ", stepTextKey="I found Vanus Galerion examining a strange device. I should speak with him."},
		["Talk to Vanus Galerion"] =
			{appendText=". He seems to have found Darien's Light, being held here for some dark purpose."},
		[18] = 
			{appendStepText="Within the Mor Naril Priory Temple, ", stepTextKey="Vanus believes Mannimarco is using this device to corrupt Darien's stolen Light of Meridia. He's attempting to create another Gift of Death. As Vanus attempts to extract it, I need to defend him."},
		["Defend Vanus Galerion"] =
			{appendText=" while he attempts to free the Light of Meridia from its dark container."},
		[19] = 
			{appendStepText="Within the Mor Naril Priory Temple, ", stepTextKey="Vanus breached the vessel containing Darien's stolen Light of Meridia. I should take it so we can return it to him."},
		["Take the Light of Meridia"] =
			{appendText=" from its dark container."},
		[20] = 
			{appendStepText="Within the Mor Naril Priory Temple, we have disrupted Mannimarco's attempts to interfere. ", stepTextKey="We have Darien's Light of Meridia. We should find to our allies so we can return it to him."},
		["Find Your Allies"] =
			{appendText=", out in the courtyard of Mor Naril where the Great Shackle awaits."},
		[21] = 
			{appendStepText="In the southeastern courtyard of Mor Naril in northeast Solstice, our enemy prepares. ", stepTextKey="A Daedric Titan is marshaling Worm Cult forces to defend the shackle from attack. We must defeat it and clear a path for our allies."},
		["Defeat the Titan"] =
			{appendText=" and all its minions with the help of my allies."},
		[22] = 
			{appendStepText="In the southeastern courtyard of Mor Naril in northeast Solstice, ", stepTextKey="I need to explain our plan to Darien and convince him to take back his powers."},
		["Talk to Darien Gautier 2"] =
			{appendText=", near the shackle.", stepTextKey="I need to explain our plan to Darien and convince him to take back his powers."},
		[23] = 
			{appendStepText="In the southeastern courtyard of Mor Naril in northeast Solstice, ", stepTextKey="Darien accepted his powers again. I need to join him in using the Light of Meridia to destroy the Worm Cult's last shackle and stop their Reverse Planemeld."},
		["Use the Light of Meridia"] =
			{appendText=" to create a portal to the Great Shackle above."},
		[24] = 
			{appendStepText="In the southeastern courtyard of Mor Naril in northeast Solstice, we succeeded. ", stepTextKey="Destroying the shackle revealed a portal to the wraithforge. Darien and I need to enter and confront Mannimarco."},
		["Reach the Wraithforge"] =
			{appendText=" through the portal in the center of the courtyard."},
		[25] = 
			{appendStepText="In the southeastern courtyard of Mor Naril in northeast Solstice, we entered the portal. ", stepTextKey="We found the wraithforge. I must stop Mannimarco from using it to complete his bodily resurrection."},
		["Stop Mannimarco"] =
			{appendText=", by any means necessary. Follow the path to the south to reach him."},
		[26] = 
			{appendStepText="At the Wraithforge, ", stepTextKey="Darien thinks that destroying the altar will weaken Mannimarco. I need to find and awaken a voskrona colossal while Darien distracts Mannimarco."},
		["Place the Eyes of the Colossal 3"] =
			{appendText=" in the Voskrona Colossal, where we entered the arena.", stepTextKey="Darien thinks that destroying the altar will weaken Mannimarco. I need to find and awaken a voskrona colossal while Darien distracts Mannimarco."},
		[27] = 
			{appendStepText="At the Wraithforge, ", stepTextKey="I awakened a voskrona colossal. I need to attune myself to it so I can destroy the altar and weaken Mannimarco."},
		["Take Control of the Voskrona Colossal 3"] =
			{appendText=".", stepTextKey="I awakened a voskrona colossal. I need to attune myself to it so I can destroy the altar and weaken Mannimarco."},
		[28] = 
			{appendStepText="At the Wraithforge, ", stepTextKey="I'm in control of a voskrona colossal but Mannimarco summoned a bone dragon to defend the altar. I need to defeat it while Darien keeps Mannimarco busy."},
		["Defeat Krahnoviir"] =
			{appendText=" using all of the Voskrona's ancient powers."},
		[29] = 
			{appendStepText="", stepTextKey="With the dragon defeated I need to destroy the altar."},
		["Destroy the Altar"] =
			{appendText=" at the Wraithforge, using the Voskrona Colossus' ancient powers."},
		[30] = 
			{appendStepText="", stepTextKey="With the altar destroyed Mannimarco appears to be drawing energy directly from the wraithforge! Darien and I need to put a stop to him once and for all."},
		["Defeat Mannimarco"] =
			{appendText=", again."},
		[31] = 
			{appendStepText="At the Wraithforge, ", stepTextKey="Darien has a plan! He's channeling all of his power into one final effort to defeat Mannimarco. I should take up his power and use it to end this once and for all."},
		["Use Darien's Power on Mannimarco"] =
			{appendText=", sending him to a final, horrifying, well-deserved death. At last."},
		[32] = 
			{appendStepText="", stepTextKey="Mannimarco is gone, trapped within the destroyed wraithforge. The Planemeld is ending, but Vanus Galerion came to retrieve me and Darien before we're lost in Coldharbour."},
		["Escape the Wraithforge"] =
			{appendText=" through Vanus' portal."},
		[33] = 
			{appendStepText="", stepTextKey="We made it back to Sunport! Midconjurer Mirmal told us that Regent Karinwe is waiting to speak to us in the palace. But first we may want to catch up with our allies outside."},
		["Return to the Palace"] =
			{appendText=" in Sunport and enjoy a welcome reunion with allies."},
		[34] = 
			{appendStepText="In the Sunport Palace of Solstice, ", stepTextKey="I found Regent Karinwe and Prince Azah waiting for me inside the palace. I should speak with her and tell her about our victory over the Worm Cult."},
		["Talk to Regent Karinwe"] =
			{appendText=" about her plans for the future of Solstice."},
		[35] = 
			{appendStepText="In the Sunport Palace of Solstice, ", stepTextKey="Prince Azah intends to speak for heroes and the fallen of the recent battle. I should listen to him."},
		["Listen to Prince Azah"] =
			{appendText=" as he addresses the entire fellowship and mourns the fallen."},
		[36] = 
			{appendStepText="In the Sunport Palace of Solstice, ", stepTextKey="I should speak to Prince Azah about our battle in Mor Naril."},
		["Talk to Prince Azah 3"] =
			{appendText=" to receive your reward, now that the war is over and the Stirk Fellowship is disbanding.", stepTextKey="I should speak to Prince Azah about our battle in Mor Naril."},
	},


-- 		=========================================================================
--		  SIDE QUESTS SOLSTICE
-- 		=========================================================================



[GetQuestName(7229)] = { --"An Ambition Fulfilled"--aashiana 
		[1] = 
			{appendStepText="I found a golden Daedra standing north of a small pond at some ruins near the mountains to the west of Eastern Solstice, northwest of the Stone Cove Wayshrine. They want to get back something a monkey stole so they can wreak some havoc in Coldharbour. ", stepTextKey="I should talk to Ezhkel and find out what their plan is to infiltrate Coldharbour."},
		["Talk to Ezhkel 1"] =
			{appendText=" about their plan to get it back.", stepTextKey="I should talk to Ezhkel and find out what their plan is to infiltrate Coldharbour."},
		[2] = 
			{appendStepText="At some ruins by a lake near the southwestern mountains in Eastern Solstice, ", stepTextKey="Ezhkel needs to retrieve a keystone from a monkey trapped in a nearby vault. It's locked by three levers. I need to help direct Daedra to the correct levers to unlock the vault."},
		["Unlock the Vault"] =
			{appendText=" \n\nPoint the rod at the helper you choose, then at the lever you want them to help with.\n\nBecause it can fly, direct the Seeker to the highest lever, on top of the pillar of stone.\n\nBecause it is small, direct the Daedrat to the lever buried in rubble.\n\nBecause it is strong, direct the Ogrim to the lever that is rusted in place."},
		[3] = 
			{appendStepText="At some ruins by a lake near the southwestern mountains in Eastern Solstice, I have successfully helped pull the levers that opened the door to the underground vault. ", stepTextKey="With the vault now unlocked, I should head inside and find Ezhkel's missing keystone."},
		["Enter the Vault"] =
			{appendText=", through the underground stone door."},
		[4] = 
			{appendStepText="At some ruins by a lake near the southwestern mountains in Eastern Solstice, ", stepTextKey="I found the monkey that stole the keystone inside the vault. I should retrieve the keystone from it."},
		["Retrieve the Keystone"] =
			{appendText=" from the monkey's body."},
		[5] = 
			{appendStepText="Within an underground vault by a lake near the southwestern mountains in Eastern Solstice, ", stepTextKey="I recovered the ritual chamber keystone. Now Ezhkel wants to discuss next steps."},
		["Talk to Ezhkel 2"] =
			{appendText=", standing just inside the vault. They have some roleplaying in mind...", stepTextKey="I recovered the ritual chamber keystone. Now Ezhkel wants to discuss next steps."},
		[6] = 
			{appendStepText="", stepTextKey="With the keystone secured, we can now enter a ritual chamber within the Lair of the Black Worm. I should head there and find a Worm Cult disguise for myself."},
		["Enter the Lair of the Black Worm"] =
			{appendText=", in a cave near the central shoreline of the large bay in northern solstice."},
		[7] = 
			{appendStepText="In a cave along the north-central coastline of Eastern Solstice, ", stepTextKey="I entered the Lair of the Black Worm. I should steal some necromancer garb from somewhere within the Worm Cult's nest to use as a disguise."},
		["Acquire a Worm Cult Disguise"] =
			{appendText=", heading down the stairs from the entrance, then left along the ledge. Jump down into the water and go up the stairs on the other side. Worm Cult clothing can be found in a small crate of supplies at the top of the stairs."},
		[8] = 
			{appendStepText="Within the Lair of the Black Worm, a cavern near the north-central coast of Eastern Solstice, I found some Worm Cult clothing. ", stepTextKey="With a disguise secured, I should meet Ezhkel outside the ritual chamber. They said it was through a tunnel in the southeast corner of the Lair of the Black Worm."},
		["Meet Ezhkel Outside the Ritual Chamber"] =
			{appendText=". Just past the supply crate and carts, descend the ramp to the canal and follow it straight ahead to a tunnel in the rock. Ezhkel is waiting in front of a warded stone door."},
		[9] = 
			{appendStepText="Through a tunnel to the southeast in the Lair of the Black Worm, near the north-central coast of Eastern Solstice, ", stepTextKey="I found Ezhkel outside the ritual chamber. I should use the keystone to dispel the protective ward on the door."},
		["Dispel the Ward"] =
			{appendText="."},
		[10] = 
			{appendStepText="Through a tunnel to the southeast in the Lair of the Black Worm, near the north-central coast of Eastern Solstice, ", stepTextKey="Ezhkel wants to go over the plan before we enter the ritual chamber. I should talk to them."},
		["Talk to Ezhkel 3"] =
			{appendText=".", stepTextKey="Ezhkel wants to go over the plan before we enter the ritual chamber. I should talk to them."},
		[11] = 
			{appendStepText="Through a tunnel to the southeast in the Lair of the Black Worm, near the north-central coast of Eastern Solstice, ", stepTextKey="I should disguise myself and put on the Worm Cult garb before we enter the ritual chamber."},
		["Put on Worm Cult Garb"] =
			{appendText=". I put it in my backpack."},
		[12] = 
			{appendStepText="Our path lead us through a tunnel to the southeast in the Lair of the Black Worm, near the north-central coast of Eastern Solstice. ", stepTextKey="Now that we're both disguised, I can lead Ezhkel into the Worm Cult's ritual chamber to be sacrificed."},
		["Enter the Worm Cult Ritual"] =
			{appendText=" through the unwarded door."},
		[13] = 
			{appendStepText="Within the Ritual Chamber in the Worm Cult Lair, ", stepTextKey="I should take part in the ritual and offer up Ezhkel for sacrifice at the appropriate moment."},
		["Participate in the Ritual"] =
			{appendText=", moving forward as if I know the way."},
		[14] = 
			{appendStepText="The Ritual Chamber is within the Worm Cult Lair. ", stepTextKey="It's my turn in the Worm Cult ritual circle. Time to sacrifice Ezhkel."},
		["Sacrifice Ezhkel"] =
			{appendText=", with a bit of dramatic play-acting."},
		[15] = 
			{appendStepText="Within the Ritual Chamber in the Worm Cult Lair, ", stepTextKey="The Worm Cultists realize something went wrong. I need to fight my way free of them so I can escape the chamber."},
		["Kill the Worm Cultists"] =
			{appendText="; they're in my way, like so many before them."},
		[16] = 
			{appendStepText="The Ritual Chamber is within the Worm Cult Lair. ", stepTextKey="With the Worm Cultists dealt with, I should head outside the lair and find the summoning circle Ezhkel prepared on the coastline."},
		["Find Ezhkel's Summoning Circle"] =
			{appendText=". I should return to Eastern Solstice by finding my way out of the Worm Cult Lair through the cave entrance, or using a convenient coastal Wayshrine. Ezhkel's summoning circle is just north of the cave entrance on the north-central coastline of Eastern Solstice, near the large island."},
		[17] = 
			{appendStepText="", stepTextKey="With the Worm Cultists dealt with, I should head outside the lair and find the summoning circle Ezhkel prepared on the coastline."},
		["Use the Velothi Conjuring Rod"] =
			{appendText="."},
		[18] = 
			{appendStepText="On the north-central coast of Eastern Solstice, on a sand spit near the large island to the north, ", stepTextKey="Ezhkel emerged from the summoning circle as a Xivilai formed by Coldharbour's creatia. I should talk to them."},
		["Talk to Ezhkel 4"] =
			{appendText=".", stepTextKey="Ezhkel emerged from the summoning circle as a Xivilai formed by Coldharbour's creatia. I should talk to them."},
		[19] = 
			{appendStepText="", stepTextKey="I helped Ezhkel reform as a Coldharbour Daedra and grew close to them in the process. I should talk to them about concluding our business."},
		["Talk to Ezhkel 5"] =
			{appendText=".", stepTextKey="I helped Ezhkel reform as a Coldharbour Daedra and grew close to them in the process. I should talk to them about concluding our business."},
	},

[GetQuestName(7333)] = { --"Blood on the Water"	--aashiana 
		[1] = 
			{appendStepText="Northwest of the Caterwaul Cove Wayshrine along the northwest coast of Eastern Solstice, I found some ships that apparently fell out of Coldharbour onto these shores as part of the attempted planemeld.\n\nOn a large rock near a shipwreck, I found an Alfiq looking for his shipmates. ", stepTextKey="Suraj said if Captain One-Eye survived, she'd rally the crew at the cliffs to the north. I should search for her there."},
		["Talk to Captain One-Eye 1"] =
			{appendText=", the Argonian skeleton by a campfire with some of her crew, further west along the road from the Caterwaul Cove Wayshrine.", stepTextKey="Suraj said if Captain One-Eye survived, she'd rally the crew at the cliffs to the north. I should search for her there."},
		[2] = 
			{appendStepText="Near the cliffs along the road west of the Caterwaul Cove Wayshrine in Eastern Solstice, ", stepTextKey="Captain One-Eye gave me a rune to place on the deck of the Caterwaul, Captain Sain's ship. She suggested I sneak through the caves on the way to avoid being spotted. If Captain Sain captured her crew, I don't want to give him an excuse to harm them."},
		["Place Rune on the Caterwaul"] =
			{appendText=".\n\nFurther west on the road, sneak through the Seaside Caves by the stone bridge. Avoid being noticed by Captain Sain's crew inside the caves or by the spying eyes of the Watchlings. Leave the caves just near the Caterwaul.\n\nThere is a grapple point on the shore, left of the steps to the dock. From there, it looks like I can grapple up to the deck of the ship. I'll need to sneak up to the front of the ship and place the rune near the supply crates."},
		[3] = 
			{appendStepText="In Caterwaul Cove, on the northwest shoreline of Eastern Solstice, ", stepTextKey="I placed Captain One-Eye's rune on the Caterwaul. I should disembark the Caterwaul and report back to Captain One-Eye."},
		["Disembark the Caterwaul"] =
			{appendText=", going back through the ship and jumping or grappling off the back deck."},
		[4] = 
			{appendStepText="", stepTextKey="Suraj found me as I disembarked the Caterwaul. I should speak with him and see what he wants."},
		["Talk to Suraj"] =
			{appendText=", up the trail from the grapple point by the cave entrance."},
		[5] = 
			{appendStepText="On the northwest shoreline of Eastern Solstice, where the Caterwaul is moored, ", stepTextKey="Captain One-Eye sent Suraj to ask if I'd gather the bones from her Lost Fleet crew where they fell along the beach. Suraj suggested my time might be better spent killing Quartermaster Xynark. I should decide which task I want to do, or do both."},
		["Gather Bones of the Lost Fleet Crew"] =
			{appendText=" \n\n\n\nFrom the path where Suraj is waiting, enter the cave and follow the elevated path to the ledge. To the left is a grapple point that leads to a cavern. Past the exit from the cavern, the bones can be found in piles of flotsam to the southeast along the shoreline."},
		["Kill Quartermaster Xynark"] =
			{appendText=". From the path where I left Suraj, enter the cave and follow the elevated path to the ledge. To the left is a grapple point, where I can reach a cavern and ring the bell to summon the Quartermaster."},
		[6] = 
			{appendStepText="", stepTextKey="Captain One-Eye sent Suraj to ask if I'd gather the bones from her Lost Fleet crew where they fell along the beach. Suraj suggested my time might be better spent killing Quartermaster Xynark. I should report back to Captain One-Eye."},
		["Talk to Captain One-Eye 2"] =
			{appendText=", at the ramp to her ship, north along the shoreline.", stepTextKey="Captain One-Eye sent Suraj to ask if I'd gather the bones from her Lost Fleet crew where they fell along the beach. Suraj suggested my time might be better spent killing Quartermaster Xynark. I should report back to Captain One-Eye."},
		[7] = 
			{appendStepText="At her ship, north along the shoreline from the Caterwaul Cove Wayshrine, ", stepTextKey="Captain One-Eye has more tasks for me to help her crew get ready to sail. I should talk to Suraj and Argenta to get more information on the specific tasks."},
		["Talk to Argenta"] =
			{appendText=", securing some barrels by the cliffs. She suggests I also talk with Suraj, on a little island by the ship, hidden in the reeds."},
		[8] = 
			{appendStepText="Near Captain One-Eye's ship, moored along the coastline, northeast of the Caterwaul Cove Wayshrine, ", stepTextKey="Suraj suggested I steal pieces of the siege weapon Coldharbour's Teeth from Velehk Sain's crew to set up on the Bonnie Spriggan. Argenta told me about some of the Caterwaul's crew wanting to defect. I can investigate one or both of these leads."},
		["Gather Coldharbour's Teeth"] =
			{appendText=" \n\n\n\nThe seige weapon pieces are inside the cave to the west. I should avoid being seen by Watchlings. Use the grappling points to travel up and out of sight. Baskets are also available to hide in. The siege weapon parts are through the cave entrance to the north, in crates around the edges."},
		["Find the Mutineers"] =
			{appendText=" among Captain Sain's crew in the cave to the west."},
		[9] = 
			{appendStepText="", stepTextKey="Suraj suggested I steal pieces of the siege weapon Coldharbour's Teeth from Velehk Sain's crew to set up on the Bonnie Spriggan. Argenta told me about some of the Caterwaul's crew wanting to mutiny. I can investigate one or both of these leads."},
		["Talk to Captain One-Eye 3"] =
			{appendText=" outside the cave through the south exit, using the grappling hook to return to the cliff above her ship. She's up on the deck, getting ready to sail.", stepTextKey="Suraj suggested I steal pieces of the siege weapon Coldharbour's Teeth from Velehk Sain's crew to set up on the Bonnie Spriggan. Argenta told me about some of the Caterwaul's crew wanting to mutiny. I can investigate one or both of these leads."},
		["Recruit the Mutineers"] =
			{appendText=". Head to the west of the room with small boats stored in the center, then either cross the wooden bridge or use a grappling hook to reach the passageway beyond to the left. Watchlings patrol the area.\n\nIn the next room, I need to destroy the anchor gem to get rid of the observer - the giant eye in the center of the room. I can use the crates for cover and try to get over there without being seen."},
		[10] = 
			{appendStepText="", stepTextKey="Suraj suggested I steal pieces of the siege weapon Coldharbour's Teeth from Velehk Sain's crew to set up on the Bonnie Spriggan. Argenta told me about some of the Caterwaul's crew wanting to defect. I should report back to Captain One-Eye."},
		["Talk to Captain One-Eye 4"] =
			{appendText=" about what I can expect in the battle to come and what I can do to help.", stepTextKey="Suraj suggested I steal pieces of the siege weapon Coldharbour's Teeth from Velehk Sain's crew to set up on the Bonnie Spriggan. Argenta told me about some of the Caterwaul's crew wanting to defect. I should report back to Captain One-Eye."},
		[11] = 
			{appendStepText="On the deck of the Bonnie Spriggan, moored northwest of the Caterwaul Cove Wayshrine in Eastern Solstice, ", stepTextKey="Captain One-Eye says my efforts to help the crew haven't gone unnoticed. She wants me to give a rallying speech to the crew before we set sail."},
		["Deliver Speech to the Crew"] =
			{appendText=", standing on a soapbox before the where they've gathered."},
		[12] = 
			{appendStepText="On the deck of the Bonnie Spriggan, ", stepTextKey="I gave my speech to the crew. We're ready to set sail and stop the Caterwaul. I should enter the cabin and stay out of the way of the deck crew."},
		["Sit Below Deck"] =
			{appendText=", through the door where Suraj is waiting to talk with me."},
		[13] = 
			{appendStepText="", stepTextKey="The Bonnie Spriggan caught the Caterwaul and engaged her in combat. I should join the fight and help Captain One-Eye defeat Captain Velehk Sain."},
		["Join the Fray"] =
			{appendText=" back on the deck."},
		[14] = 
			{appendStepText="", stepTextKey="The Bonnie Spriggan caught the Caterwaul and engaged the ship in combat. I should help Captain One-Eye defeat Captain Velehk Sain."},
		["Kill Captain Velehk Sain"] =
			{appendText=" along with his minions and crew."},
		[15] = 
			{appendStepText="Once Captain Velekh was destroyed, ", stepTextKey="Captain One-Eye bestowed me the honor of setting the Caterwaul ablaze. I should go light the sails and send the ship to her grave."},
		["Light the Sails"] =
			{appendText=" on fire."},
		[16] = 
			{appendStepText="", stepTextKey="We defeated Velehk Sain and destroyed his ship. I should return to the cabin so the crew can bring us back to Solstice."},
		["Return to Solstice"] =
			{appendText="."},
		[17] = 
			{appendStepText="", stepTextKey="I made it back to Solstice with the crew of the Bonnie Spriggan. I should talk to Captain One-Eye about what we accomplished."},
		["Return to Captain One-Eye"] =
			{appendText=", at the back of the ship, celebrating with the crew. I should talk to her."},
		[18] = 
			{appendStepText="", stepTextKey="I should talk to Captain One-Eye about what we accomplished."},
		["Talk to Captain One-Eye 5"] =
			{appendText=".", stepTextKey="I should talk to Captain One-Eye about what we accomplished."},
	},


[GetQuestName(7374)] = { --"Choice and Consequence"	--aashiana 
		[1] = 
			{appendStepText="Just north of the Mor Naril Wayshrine in northeast Solstice, apparently ", stepTextKey="I have to prove to Cariel that I can infiltrate the Worm Cult base without being seen. She gave me some small stones and said that throwing them at empty barrels will make a sound and distract nearby guards."},
		["Use the Distraction Stones"] =
			{appendText=" on the other side of the lake, inside the Worm Cult camp palisades. In front of the tent furthest back on lower ground, there are several barrels I can practice on, while crouching."},
		[2] = 
			{appendStepText="In the Worm Cult camp across from Aldwilne Citadel, on the northeastern peninsula of Solstice, ", stepTextKey="I tried the stones on some barrels outside the Worm Cult base. I should go back and talk to Cariel to hear what the next step of her plan is."},
		["Talk to Cariel 1"] =
			{appendText=", waiting at the northwestern entrance to the camp.", stepTextKey="I tried the stones on some barrels outside the Worm Cult base. I should go back and talk to Cariel to hear what the next step of her plan is."},
		[3] = 
			{appendStepText="In the Worm Cult camp across from Aldwilne Citadel, on the northeastern peninsula of Solstice, ", stepTextKey="Cariel wasn't able to figure out why Prince Naemon is helping these Worm Cultists or what their goals were in this citadel. She wants me to sneak through the Worm Cult nest and find the answers to her questions."},
		["Gather Information in the Worm Cult Camp"] =
			{appendText=" \n\nGather information from tents and tables, and by listening in on conversations throughout the Worm Cult camp. Mounds of straw provide convenient hiding places if you're sneaking. Worm cultists with lanterns patrol the camp and the dogs are quite alert.\n\n- Hide in a straw container on some planks by the water to listen in on a demonstration.\n- Find a letter inside one of the tents in the back of the upper camp. \n- Find another letter inside the other tent in back of the upper camp.\n- Hide in another straw container on some planks in the water toward the coast to hear an interesting conversation."},
		[4] = 
			{appendStepText="After sneaking around the camp across from Aldwilne Citadel in northeast Solstice, ", stepTextKey="I heard a bit more of what the Worm Cult and Prince Naemon's plan is. I should return to Cariel and let her know."},
		["Talk to Cariel 2"] =
			{appendText=", hiding nearby along the shoreline of the canal, across from the Citadel.", stepTextKey="I heard a bit more of what the Worm Cult and Prince Naemon's plan is. I should return to Cariel and let her know."},
		[5] = 
			{appendStepText="Near Aldwilne Citadel in northeastern Solstice, Cariel reminded me that ", stepTextKey="I can't walk into the Worm Cult fortress looking the way I do. I need to steal a disguise to help me move around unquestioned."},
		["Steal a Worm Cult Apprentice Disguise"] =
			{appendText=" from a chest in the tent to the right of the bridge to Aldwilne Citadel."},
		["Steal a Worm Cult Bonelord Disguise"] =
			{appendText=" from a chest in the tent to the left of the bridge to Aldwilne Citadel."},
		[6] = 
			{appendStepText="The task ahead takes place in the Worm Cult Camp across from Aldwilne Citadel, in northeastern Solstice. ", stepTextKey="The disguise I stole isn't going to do me much good until I put it on. Then I can walk right into the citadel."},
		["Wear Disguise"] =
			{appendText=" to walk freely around the camp."},
		[7] = 
			{appendStepText="In the Worm Cult Camp across from Aldwilne Citadel in northeastern Solstice, ", stepTextKey="I acquired a Worm Cult Disguise. Once I put that on, I should be able to enter the citadel."},
		["Enter the Citadel"] =
			{appendText=" across the stone bridge."},
		[8] = 
			{appendStepText="I am inside the Aldwilne Citadel. ", stepTextKey="A Worm Cultist called me over to talk to him. He might be able to tell me how I can gain access to wherever Dark Adept Vairisse is."},
		["Find Your Way to Dark Adept Vairisse"] =
			{appendText=". Inside a tent to the right of the entrance, there's a chest sitting out in plain sight. I should see what's in it."},
		[9] = 
			{appendStepText="Just inside Aldwilne Citadel, in northeast Solstice, ", stepTextKey="I obtained the key I need to reach Dark Adept Vairisse's study. I should use it and find her."},
		["Find Dark Adept Vairisse 1"] =
			{appendText=". Her office is along the path to the left of the stairs. I still need to watch out for the dogs. They may see through this disguise. \n\nShe is inside the first large chamber, behind the table.", stepTextKey="I obtained the key I need to reach Dark Adept Vairisse's study. I should use it and find her."},
		[10] = 
			{appendStepText="In her office north of the entrance to Aldwilne Citadel, in northeast Solstice, ", stepTextKey="I found Dark Adept Vairisse. I should speak to her and figure out a way to gain her trust."},
		["Talk to Dark Adept Vairisse"] =
			{appendText=" and convince her to give you a task in the fortress."},
		[11] = 
			{appendStepText="In her office north of the entrance to Aldwilne Citadel, ", stepTextKey="Dark Adept Vairisse gave me a vitrified soul crystal and told me to fill it with souls from the captives in the prisons."},
		["Go to the Prisons"] =
			{appendText=", through the passageway to the east."},
		[12] = 
			{appendStepText="In the Prison in Aldwilne Citadel southeast of Vairisse's office, ", stepTextKey="I found the captives in the prisons, but they're actively being interrogated by Worm Slayers. I should talk to the slayers while I figure out my next step"},
		["Talk to the Torturers"] =
			{appendText=" in front of the prisoners. The one in the center seems to be in charge."},
		[13] = 
			{appendStepText="My search lead me inside the prison in Aldwilne Citadel southeast of Vairisse's office in the north wall. ", stepTextKey="The Worm Slayer thought I was an officer and left me in the room with the captives. I should talk to them before I do anything too final."},
		["Talk to the Captives"] =
			{appendText=" and decide what to do about the prisoners."},
		[14] = 
			{appendStepText="My search lead me inside the prison in Aldwilne Citadel southeast of Vairisse's office in the north wall. ", stepTextKey="The vitrified soul crystal needs to be filled with souls from the captives. That's what Dark Adept Vairisse said."},
		["Use the Soul Gem on the Captives"] =
			{appendText=". I have no choice, if we're going to prevent the Planemeld."},
		[15] = 
			{appendStepText="My search lead me inside the prison in Aldwilne Citadel southeast of Vairisse's office in the north wall. ", stepTextKey="The captives said they should be able to escape the citadel without being seen. But they can't do that when they're tied up."},
		["Release the Captives"] =
			{appendText=" \n"},
		[16] = 
			{appendStepText="My search lead me inside the prison in Aldwilne Citadel southeast of Vairisse's office in the north wall. ", stepTextKey="After releasing the captives, I'm not sure who I can use to fill this vitrified soul crystal for Dark Anchor Vairisse. But then I remembered the slayers. Their souls would work."},
		["Capture the Souls of the Worm Slayers"] =
			{appendText=" \n\nAlive or dead, their souls are mine now."},
		[17] = 
			{appendStepText="My search lead me inside the prison in the north wall of Aldwilne Citadel, in northeast Solstice. ", stepTextKey="With the vitrified soul crystal filled, it's time to find Dark Adept Vairisse and show her that I'm trustworthy. She said she would be on the other side of the prisons when I finished my task."},
		["Meet Dark Adept Vairisse"] =
			{appendText=" through the south door."},
		[18] = 
			{appendStepText="In Aldwilne Citadel, in northeast Solstice, ", stepTextKey="I gained Dark Adept Vairisse's trust. I should leave her study like she asked."},
		["Leave Dark Adept Vairisse's Study"] =
			{appendText=" into the courtyard to the south, where Cariel is waiting."},
		[19] = 
			{appendStepText="Near the north wall of the courtyard in Aldwilne Citadel, in northeast Solstice, ", stepTextKey="Cairel says its time to convince Prince Naemon to trust me. First step is finding him and talking to him."},
		["Find Prince Naemon 1"] =
			{appendText=", through the doorway to the southeast, avoiding the dogs.", stepTextKey="Cairel says its time to convince Prince Naemon to trust me. First step is finding him and talking to him."},
		[20] = 
			{appendStepText="In Aldwilne Citadel in northeast Solstice, ", stepTextKey="Cairel says its time to convince Prince Naemon to trust me. First step is finding him and talking to him."},
		["Talk to Prince Naemon 1"] =
			{appendText=" in his quarters, standing by a table in the center of the room.", stepTextKey="Cairel says its time to convince Prince Naemon to trust me. First step is finding him and talking to him."},
		[21] = 
			{appendStepText="In his quarters in Aldwilne Citadel, ", stepTextKey="Prince Naemon is convinced there's a spy in the citadel. He wants me to track the spy down and bring it to him. Cariel is the spy. I should start with her and see what she wants to do."},
		["Talk to Cariel 3"] =
			{appendText=", waiting outside in the courtyard, through the door and up the stairs, the way I came in. She has found a disguise of her own and is waiting between the blue tents on the upper platform.", stepTextKey="Prince Naemon is convinced there's a spy in the citadel. He wants me to track the spy down and bring it to him. Cariel is the spy. I should start with her and see what she wants to do."},
		[22] = 
			{appendStepText="In Aldwilne Citadel, ", stepTextKey="Cariel's plan to give Prince Naemon what he wants—a spy— without exposing her involvement starts with me finding a cultist. Preferably one who fits into Cariel's clothing."},
		["Find a Suitable Cultist"] =
			{appendText=", somewhere among the tents on the platform above the entrance to Mor Naril. They need to be about her size. The woman in the tent at the top of the stairs from the entrance seems to be about the right size. I need to convince her to come with me."},
		[23] = 
			{appendStepText="In a tent at the top of the steps from the entrance to Aldwilne Citadel, ", stepTextKey="I found a cultist who looks like she would fit into Cariel's clothes. I should lead her to where Cariel's waiting."},
		["Lead the Cultist to Cariel"] =
			{appendText=". She's hiding within broken stone walls behind a pillar to the right of the door blocked by rubble."},
		[24] = 
			{appendStepText="At Cariel's hiding place, behind a pillar to the right at the top of the stairs from the entrance to Aldwilne Citadel, ", stepTextKey="I need to incapacitate the cultist so Cariel to get on with the next step of her plan."},
		["Knock Out the Cultist"] =
			{appendText="."},
		[25] = 
			{appendStepText="I am at Cariel's hiding place, behind a pillar to the right at the top of the stairs from the entrance to Aldwilne Citadel. ", stepTextKey="Now that I incapacitated the cultist, its time to do the next part of Cariel's plan. I should talk to her to see what it is."},
		["Talk to Cariel 4"] =
			{appendText=".", stepTextKey="Now that I incapacitated the cultist, its time to do the next part of Cariel's plan. I should talk to her to see what it is."},
		[26] = 
			{appendStepText="At Cariel's hiding place, behind a pillar to the right at the top of the stairs from the entrance to Aldwilne Citadel, ", stepTextKey="Cariel handed me the letter she wrote and her amulet. She asked me to plant them on the cultist."},
		["Plant Evidence on Captive"] =
			{appendText="."},
		[27] = 
			{appendStepText="I am at Cariel's hiding place, behind a pillar to the right at the top of the stairs from the entrance to Aldwilne Citadel. ", stepTextKey="We need the cultist awake and alert to bring her in front of Prince Naemon. Which means the next step is to wait for her to wake up."},
		["Wait for the Cultist to Wake Up"] =
			{appendText="."},
		[28] = 
			{appendStepText="At Cariel's hiding place, behind a pillar to the right at the top of the stairs from the entrance to Aldwilne Citadel, ", stepTextKey="Cariel gave the cultist a potion that would temporarily render her unable to talk. I should speak to the cultist so I can know when the potion starts taking effect."},
		["Talk to Cultist"] =
			{appendText="."},
		[29] = 
			{appendStepText="I am at Cariel's hiding place, behind a pillar to the right at the top of the stairs from the entrance to Aldwilne Citadel. ", stepTextKey="The evidence is planted and the cultist can't discredit my story. Time to take her to Prince Naemon and present him with the spy he was looking for."},
		["Lead the Cultist to Prince Naemon"] =
			{appendText=" in his quarters, through a door along the wall to the north."},
		[30] = 
			{appendStepText="In his quarters above the entrance to Aldwilne Citadel, in the eastern wall, ", stepTextKey="I brought Prince Naemon the \"spy\" he was looking for. Time to tell him the good news."},
		["Talk to Prince Naemon 2"] =
			{appendText=", waiting near his bedchamber to the right.", stepTextKey="I brought Prince Naemon the \"spy\" he was looking for. Time to tell him the good news."},
		[31] = 
			{appendStepText="In his quarters above the entrance to Aldwilne Citadel, in the eastern wall, ", stepTextKey="Prince Naemon wants to ask the \"spy\" some questions. I could tell him that she won't answer, but I don't think this interrogation will last long."},
		["Listen to the Interrogation"] =
			{appendText="."},
		[32] = 
			{appendStepText="In his quarters above the entrance to Aldwilne Citadel, in the eastern wall, ", stepTextKey="Prince Naemon told me to search the \"spy\". Imagine his surprise when I find the letter and the amulet Cariel planted."},
		["Take the Amulet"] =
			{appendText="."},
		["Take the Letter"] =
			{appendText="."},
		[33] = 
			{appendStepText="Currently I am at his quarters above the entrance to Aldwilne Citadel, in the eastern wall. ", stepTextKey="It doesn't look like Prince Naemon is pleased with what I gave him. I should make sure he doesn't want anything else."},
		["Talk to Prince Naemon 3"] =
			{appendText=".", stepTextKey="It doesn't look like Prince Naemon is pleased with what I gave him. I should make sure he doesn't want anything else."},
		[34] = 
			{appendStepText="In his quarters above the entrance to Aldwilne Citadel, in the eastern wall, ", stepTextKey="Prince Naemon told me to take the cultist out of this room."},
		["Take the Cultist Outside"] =
			{appendText=" the chamber, up the stairs and through the door at the east end of the room."},
		[35] = 
			{appendStepText="In Prince Naemon's Statuary room, ", stepTextKey="Prine Naemon wants me to kill the \"spy\". I'm not sure if I want to kill the cultist, but I have to do something or the Prince won't trust me."},
		["Talk to the Captive"] =
			{appendText=" and choose her fate."},
		[36] = 
			{appendStepText="", stepTextKey="The cultist is a member of the Worm Cult. She was working to bring Coldharbour to Nirn which would kill so many. My course is clear. She has to die."},
		["Kill Cultist and Collect Proof of the Kill"] =
			{appendText=" from her body."},
		[37] = 
			{appendStepText="", stepTextKey="I have the proof Prince Naemon wants. I should talk to him and show him that I can be trusted."},
		["Talk to Prince Naemon 4"] =
			{appendText=" in his quarters down the stairs from the Statuary.", stepTextKey="I have the proof Prince Naemon wants. I should talk to him and show him that I can be trusted."},
		[38] = 
			{appendStepText="In his quarters above the entrance to Aldwilne Citadel, in the eastern wall, ", stepTextKey="Prince Naemon seemed grateful that I found the \"spy\". I should look for Cariel to see what we need to do next."},
		["Talk to Cariel 5"] =
			{appendText=", along the path by the wall to the south.", stepTextKey="Prince Naemon seemed grateful that I found the \"spy\". I should look for Cariel to see what we need to do next."},
		[39] = 
			{appendStepText="In Aldwilne Citadel, ", stepTextKey="Cariel needs me to take a dagger from Prince Naemon's Loyalists. She said the dagger will be important in the next phase of her plan."},
		["Steal a Dagger from Prince Naemon's Loyalists"] =
			{appendText=", in a cluster of tents nearby. The tent on the far side has a chest with the dagger inside."},
		[40] = 
			{appendStepText="", stepTextKey="Cariel gave me her Imprinting Crystal and told me to record her talking to Dark Adept Vairisse. This recording will convince Prince Naemon that the dark adept is working with the Eyes of the Queen. I should make sure I get a good recording."},
		["Record Cariel Talking to the Dark Adept"] =
			{appendText=", up the stairs to the south towards Vairesse's tent, around the corner to the southeast, where a tower is visible. I could still be caught if the dogs see me.\n\nI can hide behind a crate once I get there, then use the imprinting crystal."},
		[41] = 
			{appendStepText="", stepTextKey="I stole a dagger and recorded Cariel's conversation with the dark adept. I should talk to Cariel to see what she wants me to do with them."},
		["Talk to Cariel 6"] =
			{appendText=", standing behind a tent nearby, with a stack of barrels in front.", stepTextKey="I stole a dagger and recorded Cariel's conversation with the dark adept. I should talk to Cariel to see what she wants me to do with them."},
		[42] = 
			{appendStepText="", stepTextKey="It's important that Prince Naemon sees the recording of Cariel and Dark Adept Vairisse. I should toss the Imprinting Crystal somewhere the prince's Loyalists will find it."},
		["Toss the Crystal Near the Prince's Loyalists"] =
			{appendText=". Sneak around the edge of the platform to the east and toss it into the corner."},
		[43] = 
			{appendStepText="On the uppermost platform in Aldwilne Citadel, to the southwest, ", stepTextKey="Cariel asked me to sabotage the shackle site. I should look for places where I can break the equipment and then plant the dagger I took from the prince's loyalists."},
		["Sabotage the Shackle Site"] =
			{appendText=" \n\nOn the upper platform to the east, the shackle machinery is stored, waiting for the demonstration.\n\nBreak the chains on the ground by the shackle equipment closest to the wall. This might be a good place to leave the dagger.\n\nOn the shackle equipment next to the first one, break another piece of chain.\n\nJump down to the area to the north and break the shackle equipment on the far side, near the wheelbarrow and crystals."},
		["Plant Evidence Near the Shackle Site"] =
			{appendText=". Place the dagger under the shackle equipment nearest the wall on the upper platform."},
		[44] = 
			{appendStepText="I am in the easternmost courtyard of Aldwilne Citadel. ", stepTextKey="The shackle equipment is sabotaged and I planted the dagger I stole from Prince Naemon's loyalists. If someone finds me near all this evidence, our ruse won't work."},
		["Go Somewhere Less Suspicious"] =
			{appendText=". Maybe I should join the cluster of people waiting for the demonstration, since I am still in disguise."},
		[45] = 
			{appendStepText="I am in the easternmost courtyard of Aldwilne Citadel. ", stepTextKey="Dark Adept Vairisse's demonstration is going to start soon. I should find somewhere to watch it."},
		["Watch the Demonstration 1"] =
			{appendText=" with the others, on the circular patio with broken pillars.", stepTextKey="Dark Adept Vairisse's demonstration is going to start soon. I should find somewhere to watch it."},
		[46] = 
			{appendStepText="I am in the easternmost courtyard of Aldwilne Citadel. ", stepTextKey="Dark Adept Vairisse asked me to start the demonstration of all her work. I know it's sabotaged, but she doesn't."},
		["Start the Equipment"] =
			{appendText=" on the circular dais glowing blue. It feels very strange to be operating the shackle."},
		[47] = 
			{appendStepText="In the easternmost courtyard of Aldwilne Citadel, ", stepTextKey="I started the demonstration. Now all that's left to do is see how well my sabotage efforts worked."},
		["Watch the Demonstration 2"] =
			{appendText=", and talk with Dark Adept Vairisse afterward.", stepTextKey="I started the demonstration. Now all that's left to do is see how well my sabotage efforts worked."},
		[48] = 
			{appendStepText="In the easternmost courtyard of Aldwilne Citadel, ", stepTextKey="Dark Adept Vairisse is planning to attack Prince Naemon and his loyalists, I think she's angry enough. The prince's state is still unknown. I should talk to him to see where his anger is."},
		["Find Prince Naemon 2"] =
			{appendText=" through the doors to the west nearby. He is reviewing the contents of the recording we made. I should talk to him.", stepTextKey="Dark Adept Vairisse is planning to attack Prince Naemon and his loyalists, I think she's angry enough. The prince's state is still unknown. I should talk to him to see where his anger is."},
		[49] = 
			{appendStepText="", stepTextKey="Everything's gone according to plan. Prince Naemon and Dark Adept Vairisse are at each others throats and the Planemeld equipment is broken. I should talk to Cariel to see what's left in her plan."},
		["Talk to Cariel 7"] =
			{appendText=". She's been listening behind the bookshelves on the other side of the room.", stepTextKey="Everything's gone according to plan. Prince Naemon and Dark Adept Vairisse are at each others throats and the Planemeld equipment is broken. I should talk to Cariel to see what's left in her plan."},
		[50] = 
			{appendStepText="", stepTextKey="Cariel's plan is to attack Prince Naemon while he's distracted and take the Staff of Magnus away from him. The prince vowed to use his power to help defeat the Worm Cult. I don't think I can follow both plans. I have to choose a side."},
		["Talk to Cariel 8"] =
			{appendText=" in the central area of the cellars in Aldwilne Citadel.", stepTextKey="Cariel's plan is to attack Prince Naemon while he's distracted and take the Staff of Magnus away from him. The prince vowed to use his power to help defeat the Worm Cult. I don't think I can follow both plans. I have to choose a side."},
		["Talk to Prince Naemon 5"] =
			{appendText=" in the central area of the cellars in Aldwilne Citadel.", stepTextKey="Cariel's plan is to attack Prince Naemon while he's distracted and take the Staff of Magnus away from him. The prince vowed to use his power to help defeat the Worm Cult. I don't think I can follow both plans. I have to choose a side."},
		[51] = 
			{appendStepText="Within Aldwilne Citadel's ruins, ", stepTextKey="Cariel said Prince Naemon's loyalists are gathering in the southern wing of the cellar. We should look for the prince there."},
		["Find Prince Naemon 3"] =
			{appendText=". He fled into the southern cellar through the door near where I was speaking with him.", stepTextKey="Cariel said Prince Naemon's loyalists are gathering in the southern wing of the cellar. We should look for the prince there."},
		[52] = 
			{appendStepText="", stepTextKey="Prince Naemon must be stopped before he can do any more damage."},
		["Defeat Prince Naemon"] =
			{appendText="."},
		[53] = 
			{appendStepText="", stepTextKey="The Staff of Magnus is what's fueling Prince Naemon's great power. I need to take it from him so we can stop him."},
		["Take the Staff of Magnus"] =
			{appendText="."},
		[54] = 
			{appendStepText="", stepTextKey="Prince Naemon no longer has his staff. Cariel and I have a better chance at defeating him now. We have to make the most of it."},
		["Help Cariel Defeat Prince Naemon"] =
			{appendText="."},
		[55] = 
			{appendStepText="", stepTextKey="Prince Naemon said that anyone could get the staff to cast a petrification spell. Time to put that theory to use."},
		["Use the Staff of Magnus"] =
			{appendText="."},
		[56] = 
			{appendStepText="In the southern cellars of Aldwilne Citadel, I petrified Naemon with his own staff. ", stepTextKey="Prince Naemon's no longer a threat to Solstice. Cariel's waiting to talk to me."},
		["Talk to Cariel 9"] =
			{appendText=".", stepTextKey="Prince Naemon's no longer a threat to Solstice. Cariel's waiting to talk to me."},
		[57] = 
			{appendStepText="I am in Aldwilne Citadel. ", stepTextKey="We defeated Prince Naemon and saw Dark Adept Vairisse turn to stone. Both threats in the fortress have been dealt with. I should talk to Cariel to see if our work here is done."},
		["Talk to Cariel 10"] =
			{appendText=", to receive your reward.", stepTextKey="We defeated Prince Naemon and saw Dark Adept Vairisse turn to stone. Both threats in the fortress have been dealt with. I should talk to Cariel to see if our work here is done."},
		[58] = 
			{appendStepText="In the center of the Cellar in Aldwilne Citadel, ", stepTextKey="Prince Naemon said Dark Adept Vairisse was hiding away in the northern wing of the cellar."},
		["Find Dark Adept Vairisse 2"] =
			{appendText=" in the north wing of the cellar.", stepTextKey="Prince Naemon said Dark Adept Vairisse was hiding away in the northern wing of the cellar."},
		[59] = 
			{appendStepText="In the north wing of the cellar, ", stepTextKey="Dark Adept Vairisse is a threat to all of Nirn. I should take her down."},
		["Defeat Dark Adept Vairisse"] =
			{appendText="."},
		[60] = 
			{appendStepText="In the north wing of the cellar of Aldwilne Citadel, ", stepTextKey="Cariel appeared after the battle. She said she wants to talk."},
		["Talk to Cariel 11"] =
			{appendText=".", stepTextKey="Cariel appeared after the battle. She said she wants to talk."},
		[61] = 
			{appendStepText="Outside the cellar, ", stepTextKey="I should find Prince Naemon now that the fight is over and Cariel's gone."},
		["Talk to Prince Naemon 6"] =
			{appendText=".", stepTextKey="I should find Prince Naemon now that the fight is over and Cariel's gone."},
		[62] = 
			{appendStepText="Outside of Aldwilne Citadel, on the northeast coast of Eastern Solstice, ", stepTextKey="Dark Adept Vairisse is no longer a threat to Solstice. Cariel wasn't happy with my decision to help Prince Naemon, but I did what I thought was right. I should talk to the prince to see if there's anything I missed."},
		["Talk to Prince Naemon 7"] =
			{appendText=".", stepTextKey="Dark Adept Vairisse is no longer a threat to Solstice. Cariel wasn't happy with my decision to help Prince Naemon, but I did what I thought was right. I should talk to the prince to see if there's anything I missed."},
[63] = 
			{appendStepText="In Prince Naemon's Statuary room, ", stepTextKey="Prince Naemon wants me to kill the \"spy\". I'm not sure if I want to kill the cultist, but I have to do something or the Prince won't trust me."},
		["Talk to the Captive"] =
			{appendText=" and choose her fate."},
},

[GetQuestName(7391)] = { --"A Cold Grave"	--aashiana 
        [1] = 
            {appendStepText="On the eastern shoreline of a small lake west of Ashbound Hall, near a tall circular building with a skyshard on top, a ghost is standing at the shoreline gazing at his frozen body. ", stepTextKey="Tesamoril told me Healer Namreras can be found in the Central Siege Camp. I can either lie and say Tesamoril died heroically, like he asked me to, or I can tell Namreras the truth that Tesamoril's death was an accident."},
        ["Find Healer Namreras"] =
            {appendText=" at the Stirk Fellowship Rampart Camp on the main crafting level, standing next to a bonfire."},
        [2] = 
            {appendStepText="At the Stirk Fellowship Rampart Camp on the main crafting level, standing next to a bonfire, ", stepTextKey="Against Tesamoril's request, I told Healer Namreras the truth about her husband's death. I should talk to her about a reward."},
        ["Talk to Healer Namreras 1"] =
            {appendText=".", stepTextKey="Against Tesamoril's request, I told Healer Namreras the truth about her husband's death. I should talk to her about a reward."},
        [3] = 
            {appendStepText="At the Stirk Fellowship Rampart Camp on the main crafting level, standing next to a bonfire, ", stepTextKey="I honored Tesamoril's request and lied to Healer Namreras about the manner of her husband's death. I should talk to her about a reward."},
        ["Talk to Healer Namreras 2"] =
            {appendText=".", stepTextKey="I honored Tesamoril's request and lied to Healer Namreras about the manner of her husband's death. I should talk to her about a reward."},
    },


[GetQuestName(7299)] = { --"The Daedric Scourge"	--aashiana 
		[1] = 
			{appendStepText="On the road north of Sunport, ", stepTextKey="A smuggler from Deetra Grotto suffering from the Daedric scourge said I could find the healer named Keeshka near the entrance to the grotto. I should go and talk to him."},
		["Talk to Healer Keeshka 1"] =
			{appendText=", an Argonian down a small path to the northeast, near the entrance to the grotto. He also appears ill.", stepTextKey="A smuggler from Deetra Grotto suffering from the Daedric scourge said I could find the healer named Keeshka near the entrance to the grotto. I should go and talk to him."},
		[2] = 
			{appendStepText="At the western entrance to Deetra Grotto, just off the main path heading north of Sunport, ", stepTextKey="I need to enter Deetra Grotto with Healer Keeshka to help him gather the remaining ingredients for his curative and to find his friend, Razug."},
		["Enter Deetra Grotto"] =
			{appendText=" through the cave entrance behind Keeshka, then follow either passage to the main grotto."},
		[3] = 
			{appendStepText="", stepTextKey="Now that I'm inside Deetra Grotto, I should help Healer Keeshka gather the remaining ingredients for his curative and locate his missing friend, Razug."},
		["Find Razug"] =
			{appendText=", in the southeast part of the large south-central peninsula, in an area with Argonian ruins. From the center of the ruins, Razug is up a short flight of stairs to the northwest. She is very ill."},
		["Gather Ingredients"] =
			{appendText=" \n\nTravel to the southwesternmost area by crossing the bridges or by swimming. Powerful Daedra reside here, but the ingredient Keeshka needs can be found on the dead Scourged Banekin, glowing blue to the southeast of the central arena.\n\nTravel to the southwestern side of the large southern peninsula and look for a Scourged Leaf glowing blue at the end of a row of palm trees.\n\nTravel to an area northeast of the large ship moored in the center of Deetra Grotto. On a hexagonal platform on stilts, Keeshka's Remedy Book lies on a wooden table. Below, on the cavern's floor to the west, Scourge Salt can be found on the beach at the corner of the docks.\n\nTravel to an area of ruined and burned buildings in the northwestern grotto, where two Daedric Titans often fight. A Scourged Branch can be found just outside the western pagoda, which appears relatively intact."},
		[4] = 
			{appendStepText="In areas throughout Deetra Grotto, ", stepTextKey="We gathered the remaining ingredients for the curative and found Razug. Now to head for the grotto docks so Keeshka can prepare the curative."},
		["Go to the Grotto Docks"] =
			{appendText=", just west of where the large ship is moored in the center of the Grotto."},
		[5] = 
			{appendStepText="", stepTextKey="We gathered the remaining ingredients for the curative and found Razug. Now to head for the grotto docks so Keeshka can prepare the curative."},
		["Enter the Grotto Docks"] =
			{appendText=", through the wooden doors."},
		[6] = 
			{appendStepText="Just west of where the large ship is moored in the center of the Grotto, ", stepTextKey="I entered the grotto docks. Now Healer Keeshka wants to speak to me."},
		["Talk to Healer Keeshka 2"] =
			{appendText=", standing near Razug and a Deckhand at the center of the docks.", stepTextKey="I entered the grotto docks. Now Healer Keeshka wants to speak to me."},
		[7] = 
			{appendStepText="At the central docks where a large ship is moored, ", stepTextKey="Keeshka instructed me on how to finish preparing the curative. I need to add the remaining ingredients to the cauldron in the nearby hut."},
		["Place the Ingredients in Keeshka's Cauldron"] =
			{appendText=" on the elevated platform to the south."},
		[8] = 
			{appendStepText="After preparing the curative, ", stepTextKey="Razug intercepted me. She wants to be the one to test the curative. I should talk to her."},
		["Take the Curative to Healer Keeshka"] =
			{appendText=", after Razug has tested it."},
		[9] = 
			{appendStepText="It appears ", stepTextKey="The curative worked and Razug no longer suffers from the Daedric scourge. I should talk to Healer Keeshka and see if he agrees with the diagnosis."},
		["Talk to Keeshka"] =
			{appendText=" on the central dock."},
	},


[GetQuestName(7326)] = { --"A Death-Dancer's Duty"	--aashiana 
        [1] = 
            {appendStepText="East of the Vale of Revelry Wayshrine and northwest of Shell-Tide Village, I met Death-Dancer Teerad in a field with Argonian ruins nearby. He asked me for help. ", stepTextKey="I need to go to the locations Teerad specified, use the sacred scallop he gave me, and talk to the spirits of the three dead warriors so they can tell me where to find their missing tidal votives. I should then join Teerad at the grave-stakes."},
        ["Recover the Tidal Votives"] =
            {appendText=" \n\nThe death-site of Drunee was in a bay to the southwest, out past a small house on stilts, near the snout of a large creature's skeleton in the water. After using the scallop shell, the ghost of Drunee appeared nearby. He said his votive was near the hatching pools, east of Shell-Tide Village on the shoreline. I found it in a small wooden box near a large, spiny, pink shell.\n\nThe death-site of Laral-Eil was on the south shore of the large central bay, north of the Corelanya Wayshrine. She died on a peaceful grassy hillside near a large flat rock and two trees, with a view of the Ruins of Tuniria across the bay. After using the scallop shell, she appeared nearby. She said she left her votive near the north entrance to Shell-Tide Village, where sweet-smelling flowers bloom. I found it in a small wooden box on a bench inside the wall, near some blue flowers and a coral formation.\n\nThe death-site of Vutraka was in a field of white and purple flowers, south of the entrance to Black Gem Foundry and north of a small campsite. After using the scallop shell, he appeared nearby. Vutraka said he left his votive on the front deck of his hut in Shell-Tide village. I found it to the right of the front door of a large house on stilts at the south end of the village."},
        [2] = 
            {appendStepText="Northeast of the village, beyond the whalebone arch and on the path to the large stone altar, ", stepTextKey="I should meet Teerad at the grave-stakes and speak with him."},
        ["Meet Teerad"] =
            {appendText=" in the burial grounds, near where three mounds of earth and burial stakes have been prepared for the three spirits."},
        [3] = 
            {appendStepText="Northeast of the village, beyond the whalebone arch and on the path to the large stone altar, ", stepTextKey="I should meet Teerad at the grave-stakes and speak with him."},
        ["Talk to Teerad 1"] =
            {appendText=" in the burial grounds, near where three mounds of earth and burial stakes have been prepared for the three spirits.", stepTextKey="I should meet Teerad at the grave-stakes and speak with him."},
        [4] = 
            {appendStepText="In the burial grounds, where three mounds of earth and burial stakes have been prepared for the three spirits, ", stepTextKey="I should place the tidal votives near each grave-stake."},
        ["Place Laras-Eil's Votive"] =
            {appendText=" at the mound next to the Death-Dancer.\n"},
        ["Place Drunee's Votive"] =
            {appendText=" at the central mound.\n"},
        ["Place Vutraka's Votive"] =
            {appendText=" at the third mound."},
        [5] = 
            {appendStepText="In the burial grounds, where three mounds of earth and burial stakes were prepared for the three spirits, ", stepTextKey="I helped Teerad perform the funerary rites. The spirits have moved on. Now I should claim my reward."},
        ["Talk to Teerad 2"] =
            {appendText=", under the tree by the lantern.", stepTextKey="I helped Teerad perform the funerary rites. The spirits have moved on. Now I should claim my reward."},
    },


[GetQuestName(7246)] = { --"Dismantling the Worm"	--aashiana 
		[1] = 
			{appendStepText="", stepTextKey="I should meet Ojouna inside the Lair of the Black Worm."},
		["Enter the Lair of the Black Worm"] =
			{appendText=", a large cavern near the north-central coastline of Eastern Solstice. North of the main road is a sunken clearing with vines hanging over the entrance. Dead Worm Cultists strewn about are evidence of Ojouna's change of heart."},
		[2] = 
			{appendStepText="Inside a massive cavern filled with old Argonian Ruins, the Worm Cult has made this an important base of operations. ", stepTextKey="The rituals are scattered throughout what remains of the Stone-Nest village. I need to locate the ritual sites and help Ojouna stop them to free the prisoners."},
		["Stop the Rituals"] =
			{appendText=" \n\nTravel directly ahead and east from the cave exit, then north at the corner with a huge stone wall. Go down the stairs and across the bridge, and continue along the eastern side of the ruins, up the hill toward some large crystals. Beyond these is one of the ritual altars to the left. Deactivate the ritual focus that powers the altar.\n\nAround the corner ahead, take the stairs down and go across the wooden platform, then up the stone stairs on the other side, then up the stairs to the left with scaffolding. Continue inside the building, where another ritual is taking place.\n\nGo back to the northern passageway and head east out of the building, down the stairs and up the other side, where green trees still thrive in the shadow of soul magic. Continue south along the upper passageway, through an area with buildings that appear recently inhabited. Continue all the way down to the far wall. Across a rope bridge, another ritual is taking place.\n\nTurn to the east and continue along the outer wall. After you pass an icy waterfall, near the skyshard, head down the stairs to another icy area with a large cart. Look for a way down to the right of the cart, then up the bridge on the other side. Turn right and go across the stone bridge, to the last ritual area, with a fearsome guardian."},
		[3] = 
			{appendStepText="After stopping the rituals and defeating the guardian, ", stepTextKey="Ojouna asked me to meet her outside the Lair of the Black Worm so she could ask me something."},
		["Meet Ojouna Outside the Lair of the Black Worm"] =
			{appendText=". Jump down to the walkway below, toward the southern cave entrance. Ahead and to the left, find the stone stairs down and up the other side, then continue up several flights of stairs to the cave entrance. Look for trees with brilliant blue blossoms to guide you to the cave entrance. Once through, Ojouna wants to talk once more."},
		[4] = 
			{appendStepText="Outside the Worm Cult Lair near the north-central coastline of Eastern Solstice, ", stepTextKey="Ojouna can't decide if she should surrender to the Stirk Fellowship or go free. She asked me to help her make a decision."},
		["Talk to Ojouna 1"] =
			{appendText=" about her choices.", stepTextKey="Ojouna can't decide if she should surrender to the Stirk Fellowship or go free. She asked me to help her make a decision."},
		[5] = 
			{appendStepText="Outside the Worm Cult Lair near the north-central coastline of Eastern Solstice, ", stepTextKey="I convinced Ojouna to surrender herself to the Stirk Fellowship to face justice for her actions as a Worm Cultist. I should speak with her one last time."},
		["Talk to Ojouna 2"] =
			{appendText=".", stepTextKey="I convinced Ojouna to surrender herself to the Stirk Fellowship to face justice for her actions as a Worm Cultist. I should speak with her one last time."},
		[6] = 
			{appendStepText="Outside the Worm Cult Lair near the north-central coastline of Eastern Solstice, ", stepTextKey="I convinced Ojouna to start a new life and find a new path of magic. I should talk to her one last time."},
		["Talk to Ojouna 3"] =
			{appendText=".", stepTextKey="I convinced Ojouna to start a new life and find a new path of magic. I should talk to her one last time."},
    },


[GetQuestName(7300)] = { --"The Everlasting Fair"	--aashiana 
		[1] = 
			{appendStepText="On a small trail along the northern beach of southwest Solstice, west of a stone platform with elevated huts, ", stepTextKey="Aderus Juven asked me to check on Sergeant Alydine near the entrance to the Everlasting Fair."},
		["Talk to Sergeant Alydine"] =
			{appendText=", west along the trail. She is near a small campfire within full view of the blue and red tent."},
		[2] = 
			{appendStepText="At the southwest tip of Solstice, ", stepTextKey="I should enter the fairgrounds and see if I can find Sashii or the other missing members of Sergeant Alydine's squad."},
		["Go to the Everlasting Fair"] =
			{appendText=", continuing along the trail toward the tent. I should speak to Araval when I get there to find out what delights are on offer."},
		[3] = 
			{appendStepText="At the southwest tip of Solstice, ", stepTextKey="I should enter the fairgrounds and see if I can find Sashii or the other missing members of Sergeant Alydine's squad."},
		["Explore the Fair"] =
			{appendText=". A muffled voice is coming from a wardrobe ahead... \n\nAfter speaking to it, continue up the hill toward the large, circular blue and red tent. A purple glow around some fairgoers suggests ensorcellment at work."},
		[4] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, on a platform to the west of the central tent,  ", stepTextKey="A strange talking goat called out to me. I should see what it wants."},
		["Talk to the Goat 1"] =
			{appendText=" with the glowing red eyes. He knows where Sashii is, and he gave me a protective talisman that works against some of the magic here.", stepTextKey="A strange talking goat called out to me. I should see what it wants."},
		[5] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, on a platform to the west of the central tent,  ", stepTextKey="I made a deal with the goat to help it restore the fair if it leads me to Sashii. It told me I should look for her in the Bristleback Extravaganza."},
		["Search the Bristleback Extravaganza"] =
			{appendText=", past the tent to the south, to a stone arch with a wooden door. Talk with the Argonian gatekeeper, with a princely pig at her side, to learn more about the arena before entering.\n\nThere are others in the arena you may want to talk to for information and strategies."},
		[6] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, ", stepTextKey="I found an Orc in the Bristleback Extravaganza. She referred to herself as Sashii. I should talk to her."},
		["Talk to Sashii 1"] =
			{appendText=", in the southwest corner of the enclosure, up a hill out of the way of the bristlebacks. She seems to have been transformed into an orc...", stepTextKey="I found an Orc in the Bristleback Extravaganza. She referred to herself as Sashii. I should talk to her."},
		[7] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, within the Bristleback Enclosure, ", stepTextKey="It turns out Sashii has been turned into an Orc by someone called the Lady of Riot. I should help her escape the bristlebacks so we can speak more."},
		["Get Sashii to Safety"] =
			{appendText=", by sneaking through the enclosure around to the exit ... or killing the bristlebacks."},
		[8] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, ", stepTextKey="I got Sashii away from the bristlebacks. I should go find the goat."},
		["Talk to the Goat 2"] =
			{appendText=", waiting nearby. He wants me to find the two halves of the Rod of Revels before helping me find the rest of my companions.", stepTextKey="I got Sashii away from the bristlebacks. I should go find the goat."},
		[9] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, ", stepTextKey="Since the goat helped me find Sashii, I need to fulfill my end of the deal. I agreed to help it find the halves of the Rod of Revels. I should search the Ogrim Parade and Misfortune Teller for the pieces."},
		["Go to the Ogrim Parade"] =
			{appendText=". I should talk to Sashii before beginning my search. The Ogrim Parade is down the hill, to the left of the large bonfire. I should talk to the Orc standing by the gate before entering."},
		["Go to the Misfortune Teller 1"] =
			{appendText=", just across from where we are standing, at a circular tent with Madame Mysterra, the Khajiit fortune-teller in a blue and gold dress standing in front. I should talk to her.", stepTextKey="Since the goat helped me find Sashii, I need to fulfill my end of the deal. I agreed to help it find the halves of the Rod of Revels. I should search the Ogrim Parade and Misfortune Teller for the pieces."},
		[10] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, ", stepTextKey="I need to search the Ogrim Parade and the Misfortune Teller for the pieces of the Rod of Revels. I need to win a prize ticket to claim the rod."},
		["Earn a Prize Ticket at the Ogrim Parade"] =
			{appendText="."},
		[11] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, ", stepTextKey="I need to defeat the ogrims in the parade to earn a prize ticket. There should be a prize chest nearby. Then I can check if there's a piece of the Rod of Revels inside."},
		["Claim a Prize Chest"] =
			{appendText=" at the center of the platform beyond the exit from the Ogrim Parade."},
		[12] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, ", stepTextKey="I defeated the ogrims. Instead of the rod, I found a note from Sashii's friend, Brunnduhl. It appears he's been turned into a monkey. I should check the Misfortune Teller next."},
		["Go to the Misfortune Teller 2"] =
			{appendText=", back up the hill, past where the goat was waiting, to a circular tent with Madame Mysterra, the Khajiit fortune-teller in a blue and gold dress standing in front. I should talk to her.", stepTextKey="I defeated the ogrims. Instead of the rod, I found a note from Sashii's friend, Brunnduhl. It appears he's been turned into a monkey. I should check the Misfortune Teller next."},
		[13] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, ", stepTextKey="I need to see if I can find a prize ticket in the Misfortune Teller's tent. I should try out the orbs in the tent to see what happens."},
		["Search the Misfortune Teller's Garden"] =
			{appendText=". Like many such tents, it is larger than it appears from the outside. One of the floating blue orbs is talking to me. Should I touch it? One after another, they call to me..."},
		[14] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, ", stepTextKey="One of the orbs transported me to the Misfortune Teller. I should see if there's a prize chest nearby. I need to open it to check for a piece of the rod."},
		["Find the Prize Chest"] =
			{appendText=". Follow the cave tunnel to the central room, where the Misfortune Teller waits in the form of a beholder. Defeat her to remove the barrier from the stairs beyond, leading to her prize chest in a side chamber."},
		[15] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, in the Misfortune Teller's lair, ", stepTextKey="I found the prize chest. I need to open it to check for a piece of the rod."},
		["Claim a Prize"] =
			{appendText=" from the chest."},
		[16] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, in the Misfortune Teller's lair, ", stepTextKey="I found a piece of the Rod of Revels in the prize chest. I should find the goat."},
		["Leave the Misfortune Teller"] =
			{appendText=" through the portal."},
		[17] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, ", stepTextKey="The goat was waiting for me. I should speak to it."},
		["Talk to the Goat 3"] =
			{appendText=", near the entrance to the Misfortune Teller's tent.", stepTextKey="The goat was waiting for me. I should speak to it."},
		[18] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, ", stepTextKey="The goat told me Sashii might be in trouble. I should look for her by the beach."},
		["Find Sashii"] =
			{appendText=" at the beach, further down the hill to the west. She is standing on top of a stone platform with a view in all directions."},
		[19] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, on a platform overlooking the western beach, ", stepTextKey="Sashii wants to talk to me. I should speak to her."},
		["Talk to Sashii 2"] =
			{appendText=". She wants to help track down the monkey, er, Brunnduhl.", stepTextKey="Sashii wants to talk to me. I should speak to her."},
		[20] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, ", stepTextKey="I need to find Brunnduhl near the dock. There's a suspicious trail of bananas nearby. I should follow it to see where it leads."},
		["Find Brunnduhl"] =
			{appendText=". At the base of the stone stairs, follow the glowing bananas along the shoreline, past a boat full of bananas, to a wooden dock, where a monkey comes to greet us."},
		[21] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, at the northern docks, ", stepTextKey="Sashii and I followed a trail of bananas to Brunnduhl. I should talk to him and see if he has the other half of the rod."},
		["Talk to the Monkey"] =
			{appendText=" by the dock."},
		[22] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, at the northern docks, ", stepTextKey="The Lady of Riot stole the rod from Brunnduhl and hid it. She also says she knows the goat is hiding near the shipwreck. I should go find it."},
		["Find the Goat Near a Shipwreck"] =
			{appendText=", further to the north, past a blue and red tent, on the dock near a small sailboat. I should talk to him."},
		[23] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, at the northern docks, ", stepTextKey="The goat and I figured out where the other half of the Rod of Revels is. I should visit Blood 'n' Baubles to find it."},
		["Enter Blood 'N' Baubles"] =
			{appendText=", the red and blue circular tent just east of the goat on the dock."},
		[24] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, within the Blood 'N' Baubles tent, ", stepTextKey="I need to win Blood 'n' Baubles game to find the rod. I should try to find the rod among the jellies."},
		["Find the Rod in Blood 'N' Baubles"] =
			{appendText=". Talk to Lervent Penoit, in Dwemer form, for more information on the horrors below. I need to find a small jelly with the other half of the rod inside."},
		[25] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, within the Blood 'N' Baubles tent, ", stepTextKey="The goat told me to meet it by the Fountain of Roses. It needs to repair the Rod of Revels so we can use it to dispel the Lady's magic."},
		["Go to the Fountain of Roses"] =
			{appendText=", through the portal in the tent. The Fountain of Roses is up the hill, on a stone platform to the southeast. I should talk to the goat and give him the pieces of the rod."},
		[26] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, at the Fountain of Roses, ", stepTextKey="The goat needs to repair the Rod of Revels so we can use it to find the Lady's Tent of Dark Joy."},
		["Wait for the Goat"] =
			{appendText=" to repair the Rod and bring it back to us."},
		[27] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, at the Fountain of Roses, ", stepTextKey="The goat repaired the Rod of Revels. I should take it."},
		["Take the Rod of Revels"] =
			{appendText=" from the floor in front of the goat."},
		[28] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, along the north beach, ", stepTextKey="The goat asked me to use the rod to dispel the Lady's magic around the fair. Her spells are hiding the entrance to her lair in the Tent of Dark Joy."},
		["Dispel Magic with the Rod of Revels"] =
			{appendText=". We may have to try various distinctive locations to the north and east before we find it, such as a giant shell, a statue of The Lady, and a coral tree.\n\n- The giant shell is on a stone dock to the north.\n- The Lady statue made of black rock is within an enclosure of cloth and banners just to the right of the stone steps from the fountain down to the beach.\n- The coral tree is being displayed further east along the beach."},
		[29] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, next to a stone wall within an enclosure of cloth and banners, at the base of the stairs from the Fountain of Roses,  ", stepTextKey="I found the entrance to the Tent of Dark Joy. I should enter it and face the Lady of Riot."},
		["Enter the Tent of Dark Joy"] =
			{appendText="."},
		[30] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, within the Tent of Dark Joy, ", stepTextKey="I need to defeat the Lady of Riot to break her spell and free everyone at the Everlasting Fair."},
		["Defeat the Lady of Riot"] =
			{appendText=", beyond a stone door at the end of the winding passageways in the Tent of Dark Joy."},
		[31] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, within the Tent of Dark Joy, ", stepTextKey="The goat asked me to place the rod on its pedestal. This will return the fair to its rightful owner, the Daedric Prince Sanguine."},
		["Restore the Everlasting Fair"] =
			{appendText=", by placing the rod on the circular pedestal at the front of the stone structure in the cave."},
		[32] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, within the Tent of Dark Joy, ", stepTextKey="I placed the Rod of Revels on its pedestal and restored the fair. I should speak with the goat."},
		["Talk to the Goat 4"] =
			{appendText=", waiting behind me.", stepTextKey="I placed the Rod of Revels on its pedestal and restored the fair. I should speak with the goat."},
		[33] = 
			{appendStepText="At the Everlasting Fair in southwest Solstice, through a glowing red portal in the corner of the stone structure, ", stepTextKey="The goat sent me out of the Tent of Dark Joy. I should find Sashii and the others."},
		["Find Sashii and Her Friends"] =
			{appendText=", around a crate near the path leading to the exit from the fair, where I came in."},
		[34] = 
			{appendStepText="After some complaining, ", stepTextKey="The goat returned Sashii and her friends to their original forms. I should speak with Sashii about what happened."},
		["Talk to Sashii 3"] =
			{appendText=", sitting on the crate, back in her Alfiq form.", stepTextKey="The goat returned Sashii and her friends to their original forms. I should speak with Sashii about what happened."},
		[35] = 
			{appendStepText="In southwest Solstice, ", stepTextKey="The Everlasting Fair is once more under Sanguine's control. It's not perfectly safe, but visitors can come and go as they please again, without any unwanted transformations."},
		["Talk to Sashii 4"] =
			{appendText=" to find out her future plans and receive your reward.", stepTextKey="The Everlasting Fair is once more under Sanguine's control. It's not perfectly safe, but visitors can come and go as they please again, without any unwanted transformations."},
	},

[GetQuestName(7309)] = { --"Fleeing the Shadows"	--aashiana 
		[1] = 
			{appendStepText="In Calindvale Gardens in south-central Eastern Solstice, ", stepTextKey="I need to destroy the accursed loci and free the imprisoned Shadow Walkers."},
		["Destroy the Loci"] =
			{appendText=" \n\nAfter rescuing the Shadow Walkers in the west-central part of the gardens and in the northwest circular cavern, continue northeast through the dark and winding tunnels. One of the locus is just past the exit along the northern wall and looks something like a soul reaper.\n\nAfter rescuing another group of Shadow Walkers at the northeast end of the central area, make your way to the southeast end of the central open area, through the large brown archway and up several sets of stairs. \n\nAt the southern end, go through the small plaza and up the stairs to the east and more stairs to the north. Before going under the trellis, jump up on the ledge and down into the small circular area beyond. Destroy the locus in the center of this area."},
		["Save the Shadow Walkers"] =
			{appendText=" \n\nThe lost Shadow Walkers can be found in three areas of the northern half of the Gardens. One group is straight ahead from the entrance, then through a marble arch and down the stairs. Take the steps down from the circular dais and follow the path along the water to the north. Between two large green trees, several Shadow Walkers are being held by green bindings. Destroy the crystalline binding device to set them free, then talk with Adwis.\n\nJust past the trees to the north, by the pool with a flaming brazier, a path heads west and then turns to the north. In a large circular cavern with a Daedric camp, several Shadow Walkers are being held among the crystalline daedric spikes on the northwest side.\n\nAfter destroying the northernmost focus, go up the stairs to the south past the Daedric champion in his arena. Continue through a small tunnel to the northeastern corner of the large central area of the gardens. The remaining Shadow Walkers are in a cage on the eastern ledge. Pull the lever to release the prisoners.\n\nOne of the prisoners, Glonorn, warned me that even after destroying the second locus, we'll still need to disrupt some kind of ritual in the northeast area of the Gardens."},
		[2] = 
			{appendStepText="In Calindvale Gardens in south-central Eastern Solstice, ", stepTextKey="I saved the Shadow Walkers and destroyed the loci. One of the freed captives suggested I go to the undergrowth chamber in the northeast to stop the Worm Cult's plan here."},
		["Go to the Undergrowth Chamber"] =
			{appendText=", heading north through the chambers on the east side of the Gardens. Continue north through a tunnel that opens into a large cavern, where the Worm Cult has set up a base of operations.\n\nContinue down several sets of stairs to reach the lower level where the ritual is being conducted."},
		[3] = 
			{appendStepText="In the northeasternmost area of Calindvale Gardens, ", stepTextKey="I reached the undergrowth chamber and found Nalgorfin and some of the Shadow Walkers I rescued. I should speak to him."},
		["Talk to Nalgorfin 1"] =
			{appendText=", standing in front of the altar.", stepTextKey="I reached the undergrowth chamber and found Nalgorfin and some of the Shadow Walkers I rescued. I should speak to him."},
		[4] = 
			{appendStepText="In the northeasternmost area of Calindvale Gardens, ", stepTextKey="I need to destroy the final locus to collapse the nexus, close the portal, and cut off the flow of energy from Coldharbour."},
		["Destroy the Infernal Locus"] =
			{appendText=", the pillar with the purple gem in front of the altar."},
		[5] = 
			{appendStepText="In the northeasternmost area of Calindvale Gardens, ", stepTextKey="I helped the Shadow Walkers destroy the nexus. I should meet Nalgorfin outside and see what he has to say."},
		["Meet Nalgorfin Outside"] =
			{appendText=" the gardens through the exit to the southwest. The fastest way from the altar is southwest through the caverns, then southwest along the central pools to the circular dais where I first entered the central gardens, then up the stairs through the cavern to the western exit. The Shadow Walkers are waiting for me just outside the exit."},
		[6] = 
			{appendStepText="Within Calindvale Gardens in south-central Eastern Solstice, ", stepTextKey="I rescued the Shadow Walkers, destroyed the accursed and infernal loci, and closed the nexus to Coldharbour. I should talk to Nalgorfin and see if he needs anything else."},
		["Talk to Nalgorfin 2"] =
			{appendText=", under the trees of Nirn.", stepTextKey="I rescued the Shadow Walkers, destroyed the accursed and infernal loci, and closed the nexus to Coldharbour. I should talk to Nalgorfin and see if he needs anything else."},
	},

[GetQuestName(7301)] = { --"Ghosthunters"	--aashiana 
		[1] = 	
			{appendStepText="Just south of Corelanya Manor in central Solstice, east of a Wayshrine of the same name,  ", stepTextKey="Oorbesh suggested Gahz, the rival ghost hunter, will be waiting outside the doors to Corelanya Manor. She said I should speak to her so we might know her plans and how best to avoid her once we go inside."},
		["Talk to Gahz 1"] =
			{appendText=" on the north side of Corelanya Manor, waiting outside the front door.", stepTextKey="Oorbesh suggested Gahz, the rival ghost hunter, will be waiting outside the doors to Corelanya Manor. She said I should speak to her so we might know her plans and how best to avoid her once we go inside."},
		[2] = 
			{appendStepText="The northern entrance to Corelanya Manor, can be found in central Solstice. ", stepTextKey="It turns out that Oorbesh's rival ghost hunter, Gahz, is actually her sister. I should head inside the manor to help Oorbesh discover what ghosts or treasures await within."},
		["Enter Corelanya Manor"] =
			{appendText=" through the front door, just up the steps."},
		[3] = 
			{appendStepText="Just inside Corelanya Manor in central Solstice, ", stepTextKey="Gahz plans to search the manor foyer. I should help Oorbesh do the same."},
		["Explore the Foyer"] =
			{appendText=". Among the many books, scrolls, and cabinets, a bowl of gems on a table to the right seems unusual.\n\nIn a square sitting area between the staircases, ritual candles in the far corner near a pile of books look intriguing.\n\nA bright blue soul cage by a nearby pillar may be related to the history of necromancy in this house."},
		[4] = 
			{appendStepText="In the foyer of Corelanya Manor, at a pillar past the staircases, ", stepTextKey="I opened a strange box and a wisp flew out and disappeared farther in the manor. Gahz seems to have some questions about what just happened."},
		["Talk to Gahz 2"] =
			{appendText=", standing behind me, wondering what I just did...", stepTextKey="I opened a strange box and a wisp flew out and disappeared farther in the manor. Gahz seems to have some questions about what just happened."},
		[5] = 
			{appendStepText="In the foyer of Corelanya Manor, past the staircases, I somehow let a wisp escape from a blue container. ", stepTextKey="Oorbesh saw the wisp leave some sort of residue as it fled the foyer. I can crouch down to see the trail myself, or just head through the door I saw it fly into."},
		["Follow Wisp"] =
			{appendText=" through a door to the east, into the dining hall."},
		[6] = 
			{appendStepText="Inside central Solstice within the walls of Corelanya Manor, lays the dining hall. ", stepTextKey="The wisp's trail ends in the dining hall. I should look around with Oorbesh and Gahz to find where it's hiding."},
		["Search the Dining Hall"] =
			{appendText=". Check around the room in all the containers where it could be hiding."},
		[7] = 
			{appendStepText="There may be something hidden in the basket on the dining table. ", stepTextKey="We found a talking skeever hiding in the manor kitchens. I should speak to it and learn more."},
		["Talk to Skeever"] =
			{appendText=" by the overturned basket on the dining table. He claims to be the master of the manor - and a necromancer. Strange form to choose for one so powerful."},
		[8] = 
			{appendStepText="The wisp’s trail lead to the dining room of Corelanya Manor, in central Solstice. ", stepTextKey="The wisp turned out to be the soul of Valendir, former high necromancer of Clan Corelanya. He asked for our help in seeking revenge against those who killed him and trapped his soul all these years. We agreed to help in exchange for treasure."},
		["Reclaim Valendir's Wisp"] =
			{appendText=" and put him back in the soul cage."},
		[9] = 
			{appendStepText="In the dining room of Corelanya Manor in Central Solstice, ", stepTextKey="Valendir gave us a choice to search either the Wailing Gardens or the Reanimatorium to find more information on who killed him. Gahz and Oorbesh both want to search different areas. I should speak to them and make a decision on where to go first."},
		["Enter Reanimatorium"] =
			{appendText=", through the trap door in the corner of the room, just past the dining room. "},
		["Enter the Wailing Gardens 1"] =
			{appendText=", through the door at the end of the room to the west.", stepTextKey="Valendir gave us a choice to search either the Wailing Gardens or the Reanimatorium to find more information on who killed him. Gahz and Oorbesh both want to search different areas. I should speak to them and make a decision on where to go first."},
		[10] = 
			{appendStepText="Through the trapdoor in the floor, just past the dining room in Corelanya Manor, there’s more to explore. ", stepTextKey="We made it to the Reanimatorium. I should venture farther in to see what awaits us down here."},
		["Search the Reanimatorium 1"] =
			{appendText=", full of iron cages, bones, and candles. Gods only know what they did in here. \n\nAnother wisp has formed up ahead. It's Valendir, out of his cage! He wants to tell me more about his work here.", stepTextKey="We made it to the Reanimatorium. I should venture farther in to see what awaits us down here."},
		[11] = 
			{appendStepText="There’s an obstacle up ahead. ", stepTextKey="A wall of toxic miasma blocks our path. I should speak to Valendir about what we can do to proceed with our search of the Reanimatorium."},
		["Talk to Valendir 1"] =
			{appendText=", in wisp form.", stepTextKey="A wall of toxic miasma blocks our path. I should speak to Valendir about what we can do to proceed with our search of the Reanimatorium."},
		[12] = 
			{appendStepText="In the Reanimatorium below Corelanya Manor, reached through a trapdoor just beyond the dining room, ", stepTextKey="Valendir thinks he can pilot the suits of armor and activate valves that will clear the toxic miasma blocking our path. I should activate the soul cage to put Valendir inside the suit of armor."},
		["Put Valendir Inside the Armor 1"] =
			{appendText=", by using the soul cage near the bronzed armor on a pedestal just before the toxic pool.", stepTextKey="Valendir thinks he can pilot the suits of armor and activate valves that will clear the toxic miasma blocking our path. I should activate the soul cage to put Valendir inside the suit of armor."},
		[13] = 
			{appendStepText="In the Reanimatorium below Corelanya Manor in central Solstice, reached through a trapdoor just beyond the dining room, ", stepTextKey="Valendir is piloting the suit of armor and needs my help pointing him the right direction. I should direct him to the switch that will clear the miasma while being mindful of hazards in his path."},
		["Direct Valendir to the Valve"] =
			{appendText=" at the wheel on the right-hand wall, using your magic from the safety of the steps."},
		[14] = 
			{appendStepText="In the Reanimatorium below Corelanya Manor in central Solstice, reached through a trapdoor in the dining room, there are more clues to be found. ", stepTextKey="With Valendir's help, we cleared a wall of toxic miasma. I should search the area for any clues relating to who might have killed Valendir."},
		["Search the Reanimatorium 2"] =
			{appendText=" \n\nKill any zombies in your way. Clearing the heaps of flesh on the floor should prevent them from continually reforming. Some fleshcrafting tools on an altar across the first room look... interesting.\n\nThrough the passage to the north, I found a small library with another suit of armor. I should activate it with the soul cage. The suit of armor needs to avoid the traps in the center of the room. By standing on the crates, I can first mark the candlestick to the left of the room, then direct him to the wheel to avoid the traps. \n\nAfterwards, Valendir mentioned I should read a letter on a barrel to the left of the exit from this room. A suit of armor waits before the next room as well. I should activate it. Start by marking a cart by a stone wall on the left side of the room. Wait for the trap in the center of the room to clear, then mark a bone pile to the right, just before a brazier. Wait for the trap by the valve to clear, then mark the wheel across the room to shut off the valve.\n\nA golden ghost stands by the brazier to the right. I should speak with him.", stepTextKey="With Valendir's help, we cleared a wall of toxic miasma. I should search the area for any clues relating to who might have killed Valendir."},
		[15] = 
			{appendStepText="Underneath the Corelanya Manor in central Solstice, we have cleared the Reanimatorium of its undead and miasma. ", stepTextKey="I should talk to Valendir."},
		["Talk to Valendir 2"] =
			{appendText=", in a storage room at the southeast end of the Reanimatorium.", stepTextKey="I should talk to Valendir."},
		[16] = 
			{appendStepText="In the Corelanya Manor in central Solstice, we continue to search for more clues. ", stepTextKey="We decided to search the Wailing Gardens for more information on who killed Valendir. I should enter the the Wailing Gardens at the center of Corelanya Manor."},
		["Enter the Wailing Gardens 2"] =
			{appendText=" by returning up the ladder, heading south through the dining room and through a door to the west.", stepTextKey="We decided to search the Wailing Gardens for more information on who killed Valendir. I should enter the the Wailing Gardens at the center of Corelanya Manor."},
		[17] = 
			{appendStepText="In central Solstice, there’s more to explore on the grounds south of the Corelanya Manor. ", stepTextKey="We made it to the Wailing Gardens. I should see if there's a way inside the hedge maze."},
		["Search the Wailing Gardens"] =
			{appendText=" for the ghost of Lirianwe, following the garden paths. Talk to Valendir to find a way through the maze."},
		[18] = 
			{appendStepText="Outside Corelanya Manor, the grounds of the Wailing Gardens are expansive. ", stepTextKey="The maze in the Wailing Gardens is overgrown. I should speak to Valendir about how to proceed."},
		["Talk to Valendir 3"] =
			{appendText=", just ahead, in wisp form.", stepTextKey="The maze in the Wailing Gardens is overgrown. I should speak to Valendir about how to proceed."},
		[19] = 
			{appendStepText="In the Wailing Gardens outside Corelanya Manor, ", stepTextKey="Valendir thinks he hears the voice of his sister singing on the other side of the maze. He can control the statues and smash the overgrown hedges blocking our path. I should activate the soul cage to put Valendir inside the statue."},
		["Put Valendir in the Statue"] =
			{appendText=" in the corner by the stone wall, using the soul cage."},
		[20] = 
			{appendStepText="In the Wailing Gardens outside Corelanya Manor, ", stepTextKey="Valendir is controlling the statue, but he needs my help pointing him the right direction. I should direct him to the overgrown hedge that blocks our path."},
		["Direct Valendir to the Overgrown Hedge"] =
			{appendText=", a thin area of the hedge to the left of the statue."},
		[21] = 
			{appendStepText="After breaking through the hedge, we can still hear singing. ", stepTextKey="We're getting closer to the singing coming from the far side of the hedge maze. I should find the source of the singing."},
		["Find the Source of the Music"] =
			{appendText=", heading toward the southern area of the central maze. Behind a stone statue in the south-central part of the maze, another suit of armor awaits. Mark an area of thin vines in the southeast corner of the room with the statue.\n\nContinue along the southernmost passage to the east. Go through a stone arch and up some stone steps to find another suit of armor on a pedestal. Direct it through the area of thin vines to the left of the statue.\n\nContinue up the eastern passages to the north. Lirianwe can be heard singing in the northwestern area of the maze, where ghosts are dancing to the music."},
		[22] = 
			{appendStepText="There’s a gathering of sorts in the northwest corner of the maze. ", stepTextKey="We came across a garden party full of dancing spirits, but none of them seem to be the person singing. Gahz suggested mingling with the party guests to find out more information."},
		["Talk to the Party Guests"] =
			{appendText=" \n\nA dancing woman with a bun and a pink flower in her hair is willing to talk with you.\n\nA bald man dancing with another man has information about Lirianwe.\n\nLiranwe has appeared, sitting on the side of the fountain in a black dress."},
		[23] = 
			{appendStepText="Sitting on the side of the fountain, in the northwest corner of the Wailing Gardens outside Corelanya Manor, ", stepTextKey="I spoke to Lirianwe, but she seems unaware that she's at a party full of spirits of the dead. I should talk to Valendir to relay what happened and find out what to do next."},
		["Talk to Valendir 4"] =
			{appendText=", the wisp in the corner by a broken iron fence.", stepTextKey="I spoke to Lirianwe, but she seems unaware that she's at a party full of spirits of the dead. I should talk to Valendir to relay what happened and find out what to do next."},
		[24] = 
			{appendStepText="There’s still more to explore underneath and outside Corelanya Manor, in central Solstice. ", stepTextKey="We searched the Reanimatorium and the Wailing Gardens for clues as to who murdered Valendir and trapped him in the soul cage. Now, Valendir wants to search his own quarters. I should head up the staircase in the foyer to find his room."},
		["Go to Valendir's Quarters"] =
			{appendText=". Jump down through the broken area of the fence to reach the door into the foyer of Corelanya Manor. Head up the stairs and through the archway at the back, then turn right to reach Valendir's quarters."},
		[25] = 
			{appendStepText="In Corelanya Manor in central Solstice, up the stairs at the end of the hallway to the right, there’s a room. ", stepTextKey="We found Valendir's quarters. I should search the room for any information on who killed him."},
		["Search Valendir's Quarters"] =
			{appendText=" \n\nA journal lying on the floor by the northern wall explains much.\n\nA small cup on the floor by the bed may be the one spoken of in the journal.\n\nA harp stands to the left of the wardrobe by the bed. Was it Lirianwe's?"},
		[26] = 
			{appendStepText="In Corelanya Manor, in Valendir's quarters upstairs, ", stepTextKey="I found the cup that held the poison that killed Valendir, a harp belonging to Lirianwe, and a journal belonging to Siluran. Then, another fracture of Lirianwe appeared, weeping. I should speak to her."},
		["Talk to Lirianwe"] =
			{appendText=" in Corelanya Manor, in Valendir's quarters upstairs, on a throne-like chair glowing blue."},
		[27] = 
			{appendStepText="In Corelanya Manor, in Valendir's quarters upstairs, ", stepTextKey="Lirianwe confirmed that Siluran was the one who plotted the death of his twin brother Valendir. He siphoned Valendir's soul to empower his attempts to learn necromancy and bring Lirianwe back to life. I should talk to Valendir about what we learned."},
		["Talk to Valendir 5"] =
			{appendText=", floating nearby, still in wisp form.", stepTextKey="Lirianwe confirmed that Siluran was the one who plotted the death of his twin brother Valendir. He siphoned Valendir's soul to empower his attempts to learn necromancy and bring Lirianwe back to life. I should talk to Valendir about what we learned."},
		[28] = 
			{appendStepText="Gahz and Oorbesh are upstairs in Corelanya Manor, in Valendir's quarters. ", stepTextKey="While talking to Valendir, Oorbesh disappeared. Gahz says she was standing near the bookcase when it happened. I should investigate the bookcase to learn more."},
		["Investigate the Bookcase"] =
			{appendText="."},
		[29] = 
			{appendStepText="Upstairs, in Corelanya Manor, there may be something hidden underneath the bookcase in Valendir’s quarters. ", stepTextKey="The bookcase revealed a secret passage underneath the manor. Oorbesh can't have gone far. I should enter the passage and find her."},
		["Enter the Bookcase"] =
			{appendText=" to reach the Manor Grotto."},
		[30] = 
			{appendStepText="In Corelanya Manor, upstairs, in Valendir's quarters, there’s more beyond the bookcase. ", stepTextKey="The bookcase revealed a secret passage underneath the manor. Oorbesh can't have gone far. I should search the manor grotto and find her."},
		["Find Oorbesh 1"] =
			{appendText=". Head down the stairs to the right to reach the main grotto.", stepTextKey="The bookcase revealed a secret passage underneath the manor. Oorbesh can't have gone far. I should search the manor grotto and find her."},
		[31] = 
			{appendStepText="The grotto beneath Corelanya Manor holds more to explore. ", stepTextKey="Another wall of deadly miasma lies ahead of us. Oorbesh couldn't have gone through it and survived. I should search the area for any clues as to what happened to her."},
		["Search the Manor Grotto"] =
			{appendText=" \n\nI can't go into the poison. The only place left is behind the stairs. There's a small clothing scrap by the staircase, near another one of those suits of armor.\n\nBy some trees across from the armor is a fog lantern. I wonder if that will help?"},
		[32] = 
			{appendStepText="In the grotto beneath Corelanya Manor, ", stepTextKey="I searched the area and found a lantern and a scrap of cloth, but no Oorbesh. Gahz is getting impatient about finding her sister. I should speak to Valendir about how to proceed."},
		["Talk to Valendir 6"] =
			{appendText=", floating by the stairs in wisp form, about what to do next.", stepTextKey="I searched the area and found a lantern and a scrap of cloth, but no Oorbesh. Gahz is getting impatient about finding her sister. I should speak to Valendir about how to proceed."},
		[33] = 
			{appendStepText="In the grotto beneath Corelanya Manor, ", stepTextKey="Valendir recognized the lantern as a means by which Siluran got through the miasma. He has a plan to affix the lantern to a suit of armor and guide me through the miasma. I'll still need to direct him and stay close as he moves."},
		["Put Valendir Inside the Armor 2"] =
			{appendText=", using the soul cage.", stepTextKey="Valendir recognized the lantern as a means by which Siluran got through the miasma. He has a plan to affix the lantern to a suit of armor and guide me through the miasma. I'll still need to direct him and stay close as he moves."},
		[34] = 
			{appendStepText="In the grotto beneath Corelanya Manor, ", stepTextKey="I should direct Valendir to engage the valve to clear the miasma so Gahz can join us in finding Oorbesh."},
		["Follow Valendir"] =
			{appendText=", staying within his protective light and killing any undead that come near."},
		[35] = 
			{appendStepText="We proceed on our path in the grotto beneath Corelanya Manor. ", stepTextKey="We made it to the other side of the miasma with Valendir's help. I should continue our search for Oorbesh."},
		["Find Oorbesh 2"] =
			{appendText=", beyond the door at the east end of the chamber.", stepTextKey="We made it to the other side of the miasma with Valendir's help. I should continue our search for Oorbesh."},
		[36] = 
			{appendStepText="In the grotto beneath Corelanya Manor, Oorbesh must be close by. ", stepTextKey="We found Oorbesh at the mercy of Siluran, Valendir's twin brother. Siluran has made an appeal to me against the choice of allying with Valendir. I should speak to him."},
		["Talk to Siluran"] =
			{appendText=", standing at the edge of an arena across a chasm."},
		[37] = 
			{appendStepText="In a grotto beneath Corelanya Manor, ", stepTextKey="I tried reasoning with Siluran, but could come to no agreement. He is intent on using Oorbesh's body to resurrect Lirianwe. I should find a way to Siluran to stop him from carrying out this ritual."},
		["Find a Way to Siluran"] =
			{appendText=". The only way out seems to be the door we came through, at the south end of the cavern. Perhaps there is another way to him beyond the door."},
		[38] = 
			{appendStepText="", stepTextKey="I found the way to Siluran. I should confront him so we can save Oorbesh and Valendir, and then find the treasure we were promised."},
		["Confront Siluran"] =
			{appendText="."},
		[39] = 
			{appendStepText="At the arena in the cavern below Corelanya Manor, ", stepTextKey="Siluran seems to have learned some skills in necromancy in his time trapped in Corelanya Manor. I should defeat him so we can save Oorbesh and Valendir."},
		["Defeat Siluran"] =
			{appendText=" in the arena, in the form of a Colossus."},
		[40] = 
			{appendStepText="At the arena in the cavern below Corelanya Manor, we challenged Siluran. ", stepTextKey="We defeated Siluran. Valendir, having taken over Siluran's body, wants me to use the soul cage to capture Siluran's essence before he dissipates."},
		["Capture Siluran in the Soul Cage"] =
			{appendText=", at the center of the arena."},
		[41] = 
			{appendStepText="At the arena in the cavern below Corelanya Manor, ", stepTextKey="Valendir has taken over the body of his twin brother, Siluran. I should speak to him about what comes next."},
		["Talk To Valendir"] =
			{appendText=", inhabiting his brother's body."},
		[42] = 
			{appendStepText="We found Oorbesh at the arena, in the cavern below Corelanya Manor. ", stepTextKey="We stopped Siluran from using Oorbesh's body to resurrect his sister, Lirianwe. I should join Gahz in seeing if her sister Oorbesh is all right."},
		["Check on Oorbesh"] =
			{appendText=", lying on an altar near a statue of Meridia."},
		[43] = 
			{appendStepText="At the arena in the cavern below Corelanya Manor, ", stepTextKey="Valendir found closure with Lirianwe and has agreed to lead us to the treasure he promised. I should follow him."},
		["Meet Oorbesh and Gahz in the Treasury"] =
			{appendText=", through the wooden door past Lirianwe's altar."},
		[44] = 
			{appendStepText="In the Treasury beneath Corelanya Manor, ", stepTextKey="Oorbesh seems preoccupied with the vast amount of treasure in this room. Since she and Gahz seemed to have reconciled their rivalry, I should speak to Gahz about my reward."},
		["Talk to Gahz 3"] =
			{appendText=", gazing at a painting.", stepTextKey="Oorbesh seems preoccupied with the vast amount of treasure in this room. Since she and Gahz seemed to have reconciled their rivalry, I should speak to Gahz about my reward."},
		[45] = 
			{appendStepText="Gahz is in the Treasury beneath Corelanya Manor. ", stepTextKey="We helped Valendir resolve his unfinished business and even found him a new body to live in. Oorbesh seems occupied with the treasure, so I should speak to Gahz about my reward."},
		["Talk to Gahz 4"] =
			{appendText=".", stepTextKey="We helped Valendir resolve his unfinished business and even found him a new body to live in. Oorbesh seems occupied with the treasure, so I should speak to Gahz about my reward."},
	},


[GetQuestName(7385)] = { --"The Hermit in the Hills"	--aashiana 
        [1] = 
            {appendStepText="", stepTextKey="I should deliver the stone-nest soup to Hecicla's home near Calindvale Gardens."},
        ["Travel to Hecicla's House"] =
            {appendText=". Head up to the main road and travel west past the abandoned stone village. Just before the landscape turns into Daedric spikes, take the smaller path to the south. Continue a fair distance along this path, past the entrance to Calindvale Gardens and down into a ruined stone village by the water below.\n\nHecicla's house is at the south end of the stone village, with tattered brown banners hanging from the roof."},
        [2] = 
            {appendStepText="In south-central Eastern Solstice, ", stepTextKey="I should deliver the stone-nest soup to Hecicla's home near Calindvale Gardens."},
        ["Talk to Hecicla 1"] =
            {appendText=", in her home at the south end of the village.", stepTextKey="I should deliver the stone-nest soup to Hecicla's home near Calindvale Gardens."},
        [3] = 
            {appendStepText="In her home in south-central Solstice, south of Calindvale Gardens, ", stepTextKey="Hecicla asked me to prepare the stone-soup for her."},
        ["Prepare Stone-Soup"] =
            {appendText=" by placing the soup-pot in the fireplace, then taking it out again when I decide it is ready."},
        [4] = 
            {appendStepText="In her home in south-central Solstice, south of Calindvale Gardens, ", stepTextKey="I prepared some stone-soup. I should give it to Hecicla."},
        ["Give Prepared Stone-Soup to Hecicla"] =
            {appendText="."},
        [5] = 
            {appendStepText="In her home in south-central Solstice, south of Calindvale Gardens, ", stepTextKey="I delivered and prepared the stone-soup for Hecicla. I should see if she needs anything else before I collect my payment."},
        ["Talk to Hecicla 2"] =
            {appendText=".", stepTextKey="I delivered and prepared the stone-soup for Hecicla. I should see if she needs anything else before I collect my payment."},
        [6] = 
            {appendStepText="In her home in south-central Solstice, south of Calindvale Gardens, ", stepTextKey="I delivered the stone-soup to Hecicla but decided she could prepare it for herself. Now I should talk to her about my payment."},
        ["Talk to Hecicla 3"] =
            {appendText=".", stepTextKey="I delivered the stone-soup to Hecicla but decided she could prepare it for herself. Now I should talk to her about my payment."},
    },


[GetQuestName(7158)] = { --"Honor Bound"	--aashiana 
		[1] = 
			{appendStepText="On the southeast shoreline across from Sunport, near the entrance to Naj-Caldeesh, I found a note pinned to a tree asking for help in finding a missing horse. ", stepTextKey="I should find Squire Albec and ask him about Honor."},
		["Talk to Squire Albec 1"] =
			{appendText=", on the path just north of the tree where I found the note.", stepTextKey="I should find Squire Albec and ask him about Honor."},
		[2] = 
			{appendStepText="North of Naj-Caldeesh, ", stepTextKey="Squire Albec wants to search for Honor's tracks and follow them. He suggests I crouch to the ground to see them more easily. I should find the tracks and see where they lead."},
		["Follow Honor's Tracks 1"] =
			{appendText=" by crouching along the trail. Honor seems to like tufts of tall grass along the trail heading north. He also likes rabbits. And berries.", stepTextKey="Squire Albec wants to search for Honor's tracks and follow them. He suggests I crouch to the ground to see them more easily. I should find the tracks and see where they lead."},
		[3] = 
			{appendStepText="Along the trail north of Naj-Caldeesh, ", stepTextKey="We found a sword on the ground. Squire Albec believes it belongs to a Dremora from the Deathbringer clan. I should ask him about it."},
		["Talk to Squire Albec 2"] =
			{appendText=" about the sword.", stepTextKey="We found a sword on the ground. Squire Albec believes it belongs to a Dremora from the Deathbringer clan. I should ask him about it."},
		[4] = 
			{appendStepText="On the trail north of Naj-Caldeesh, ", stepTextKey="Squire Albec told me that Honor despises the Deathbringer clan. If he caught their scent, he'd chase after them. I should continue following Honor's tracks before he gets in trouble."},
		["Follow Honor's Tracks 2"] =
			{appendText=" by crouching and looking for disturbed grass and guar footprints.", stepTextKey="Squire Albec told me that Honor despises the Deathbringer clan. If he caught their scent, he'd chase after them. I should continue following Honor's tracks before he gets in trouble."},
		[5] = 
			{appendStepText="On a large flat rock at the end of Honor's trail, ", stepTextKey="We overheard a Dremora talking about capturing Honor. I should talk to Squire Albec about this."},
		["Talk to Squire Albec 3"] =
			{appendText=" about how to find Honor, who may be hiding from the Dremora.", stepTextKey="We overheard a Dremora talking about capturing Honor. I should talk to Squire Albec about this."},
		[6] = 
			{appendStepText="At the end of Honor's trail, along the coast across the bay from Sunport, ", stepTextKey="Squire Albec believes Honor may be nearby. I should put a snack on the ground to draw out the trusty mount."},
		["Place Snack"] =
			{appendText=" on the ground near the large rock."},
		[7] = 
			{appendStepText="At the end of Honor's trail, along the coast across the bay from Sunport, ", stepTextKey="I set out Honor's favorite snack. I should wait to see how he responds to it."},
		["Wait for Honor"] =
			{appendText="... well, that didn't take long! He must love this snack."},
		[8] = 
			{appendStepText="When Honor came running to get his snack, ", stepTextKey="Deathbringer Zara-Vyln captured Squire Albec instead of Honor. They fled before I could stop them. I should see if Honor can help find him."},
		["Talk to Honor 1"] =
			{appendText=", in the clearing where I placed his snack.", stepTextKey="Deathbringer Zara-Vyln captured Squire Albec instead of Honor. They fled before I could stop them. I should see if Honor can help find him."},
		[9] = 
			{appendStepText="", stepTextKey="Honor didn't say anything to me since he's just a bantam guar. I got the impression that he wants to show me something. I should follow Honor."},
		["Follow Honor"] =
			{appendText=" to a stone door in a hillside northwest of Naj-Caldeesh and east of Shor's Stand Wayshrine."},
		[10] = 
			{appendStepText="Northwest of Naj-Caldeesh and east of Shor's Stand Wayshrine, ", stepTextKey="Honor led me to a stone door. He hasn't moved from it. Perhaps I should knock on the door to see who's behind it."},
		["Knock on the Stone Door"] =
			{appendText="."},
		[11] = 
			{appendStepText="", stepTextKey="When I knocked on the stone door, I heard Deathbringer Zara-Vyln's voice behind it. I should check if Honor can help open the door."},
		["Talk to Honor 2"] =
			{appendText=", the bantam guar, and see if he understands what to do.", stepTextKey="When I knocked on the stone door, I heard Deathbringer Zara-Vyln's voice behind it. I should check if Honor can help open the door."},
		[12] = 
			{appendStepText="", stepTextKey="Honor keeps gesturing to the hole in a wall as if he wants to enter. I should watch Honor go through."},
		["Enter the Hole in the Wall"] =
			{appendText="."},
		[13] = 
			{appendStepText="Just to the left of the stone door, ", stepTextKey="Honor entered a narrow passage through a hole in the wall. I should watch as he explores the passage. He might have a plan."},
		["Explore the Narrow Passage"] =
			{appendText="."},
		[14] = 
			{appendStepText="By the stone door leading to the Dremora's lair, ", stepTextKey="I watched through a hole in the wall as Honor explored a narrow passage. He discovered a lever that might unlock the door. I should watch as Honor pulls the lever."},
		["Unlock the Door"] =
			{appendText=", using the lever."},
		[15] = 
			{appendStepText="Inside the Dremora's lair, ", stepTextKey="Honor managed to unlock the door into the cave system. I should go inside."},
		["Enter Cave"] =
			{appendText=" through the stone door."},
		[16] = 
			{appendStepText="Inside the Dremora's hillside refuge, behind a stone door east of Shor's Stand Wayshrine, ", stepTextKey="I should find Squire Albec and rescue him from Deathbringer Zara-Vyln"},
		["Rescue Squire Albec"] =
			{appendText=", by defeating the Dremora in her inner shrine and untying him."},
		[17] = 
			{appendStepText="In the Dremora's inner lair, behind a stone door east of Shor's Stand Wayshrine, ", stepTextKey="I untied Squire Albec's bindings and set him free. He left the cave system with Honor. I should follow them and meet him outside."},
		["Meet Squire Albec Outside"] =
			{appendText=" the Dremora's refuge, west of Shor's Stand Wayshrine, below a rocky cliff."},
		[18] = 
			{appendStepText="West of Shor's Stand Wayshrine, below a rocky cliff, ", stepTextKey="I found Squire Albec and Honor outside of the cave system where Deathbringer Zara-Vyln held him prisoner. I should talk to Squire Albec and find out about what he plans to do next."},
		["Talk to Squire Albec 4"] =
			{appendText=" about his plans to return Honor to Sir Cadwell.", stepTextKey="I found Squire Albec and Honor outside of the cave system where Deathbringer Zara-Vyln held him prisoner. I should talk to Squire Albec and find out about what he plans to do next."},
	},


[GetQuestName(7376)] = { --"Lost Among the Ashes"	--aashiana 
		[1] = 
			{appendStepText="Along the north-central road in Eastern Solstice, Scout Mihnassi told me that ", stepTextKey="A High Elf mage named Sirilonwe is concerned about her missing partner, Terinvel. They came to Solstice to explore the Hall of Vampires, but he has gone missing."},
		["Talk to Sirilonwe 1"] =
			{appendText=", standing by a tree near some wrecked and burning wagons, further along the road."},
		[2] = 
			{appendStepText="South along a path from the burning wagons, then east around the large rocky outcropping, ", stepTextKey="We found Ormard's camping area easily enough. Sirilonwe wants to search his campsite, in the hopes we find some information about why the two of them went ahead into the Hall of Vampires without her."},
		["Search the Camp"] =
			{appendText=". Terinvel's notebook has been left behind. It should hold some clues. Another note nearby seems to have been written by one of the vampires, perhaps a prisoner. The campfire is still warm."},
		[3] = 
			{appendStepText="North of Ashbound Hall in Eastern Solstice, Sirilonwe is looking for her companions. ", stepTextKey="Though neither Terinvel nor Ormard were near the campsite, we did find a few things, when searching. I should talk to Sirilonwe."},
		["Talk to Sirilonwe 2"] =
			{appendText=", standing by the campfire.", stepTextKey="Though neither Terinvel nor Ormard were near the campsite, we did find a few things, when searching. I should talk to Sirilonwe."},
		[4] = 
			{appendStepText="At a campfire north of Ashbound Hall in north-central Eastern Solstice, his journal suggests that ", stepTextKey="Ormard had found a way into the Hall of Vampires. Sirilonwe assumes that he and Terinvel headed inside. We need to locate Ormard's secret entry into the place. It should be relatively close by."},
		["Find the Cave Entrance to Ashbound Hall"] =
			{appendText=". By a lake to the southeast, a campfire is burning. Not far away, a cave entrance is lit by a lantern."},
		[5] = 
			{appendStepText="At the eastern end of a lake in north-central Eastern Solstice, a campfire burns near a cave entrance. ", stepTextKey="Ormard had found a way in to the Hall of Vampires, a break in the foundation, probably caused when the place crashed into Tamriel."},
		["Enter Ashbound Hall"] =
			{appendText=" through the cave."},
		[6] = 
			{appendStepText="In the north-central area of Eastern Solstice, near the east end of a lake, ", stepTextKey="We have made it into the Hall of Vampires. I should speak to Sirilonwe before we go further in."},
		["Talk to Sirilonwe 3"] =
			{appendText=".", stepTextKey="We have made it into the Hall of Vampires. I should speak to Sirilonwe before we go further in."},
		[7] = 
			{appendStepText="At the southern entrance to Ashbound Hall, ", stepTextKey="As Sirilonwe noted, nothing else to do, but go forward. I should keep an eye out for anything useful, like a map, or more of Terinvel's papers."},
		["Search for Terinvel 1"] =
			{appendText=", beginning with the hall just ahead. A discarded journal in the middle of the hallway isn't his, but mentions a way to pass through a door ahead.", stepTextKey="As Sirilonwe noted, nothing else to do, but go forward. I should keep an eye out for anything useful, like a map, or more of Terinvel's papers."},
		[8] = 
			{appendStepText="Not far into the corridors of Ashbound Hall, ", stepTextKey="We came to a sealed door. There is a room next to it we should investigate, perhaps it will provide information on how to unseal the door so we can continue our search."},
		["Search the Safe Room"] =
			{appendText=". A crumpled note by the bookshelf to the east and another note penned by an inmate on the table nearby are helpful. Someone in here really wants out of this place. The Aspect of Brutality mentioned in the note is here, glowing blue on some overturned furniture by the brazier."},
		[9] = 
			{appendStepText="Near the entrance to Ashbound Hall, in a safe room near a sealed door, ", stepTextKey="I've found some notes about the sealed doors in this place and an engraved medallion, that may be one of the aspects, or keys, that the note referred to. I should talk to Sirilonwe."},
		["Talk to Sirilonwe 4"] =
			{appendText=" about what I found.", stepTextKey="I've found some notes about the sealed doors in this place and an engraved medallion, that may be one of the aspects, or keys, that the note referred to. I should talk to Sirilonwe."},
		[10] = 
			{appendStepText="In Ashbound Hall, in north-central Eastern Solstice, ", stepTextKey="Sirilonwe agreed that the Aspect of Brutality we found is a key to opening some of the sealed doors within this place. We're going to give it a try."},
		["Place the Aspect"] =
			{appendText=" of Brutality in the center slot of the circular apparatus by the door."},
		[11] = 
			{appendStepText="Inside the main entrance to Ashbound Hall, ", stepTextKey="We unsealed the door that was blocking our way and can now explore this darker, misty area."},
		["Search for Terinvel 2"] =
			{appendText=" amongst the vampires imprisoned here.", stepTextKey="We unsealed the door that was blocking our way and can now explore this darker, misty area."},
		[12] = 
			{appendStepText="As we entered the main halls, ", stepTextKey="We've heard a voice, wary, but not mad. I think we should look for the source. Maybe we can get more information on how to get through this place."},
		["Find the Source of the Whispers"] =
			{appendText=", following the glowing red sigils on the floor. They have led us to a prison cell on the right."},
		[13] = 
			{appendStepText="Within Ashbound Hall, ", stepTextKey="We found a young woman, hiding herself within a cell. She appears to be a vampire, but was not immediately hostile. I want to speak to her."},
		["Talk to Azatha"] =
			{appendText=". She has seen the ones we're searching for, and can tell us much about the situation here. All she wants is to get out of this place. Maybe we can help each other."},
		[14] = 
			{appendStepText="In Ashbound Hall in north-central Solstice, ", stepTextKey="The vampire, Azatha, called this area the Misty Halls. She may have seen Terinvel and Ormard, but was not entirely sure, as she was intent on making her way out of this place. She gave us the Aspect of Domination and I let her go on her way."},
		["Find the Map of Ashbound Hall"] =
			{appendText=". In a circular room with a statue of a gargoyle in the center, the antechamber to the west has what we seek."},
		[15] = 
			{appendStepText="In Ashbound Hall, off of a room to the south with a Gargoyle statue, ", stepTextKey="We found a room brightly lit and out of the way. Sirilonwe suggested Terinvel may have stopped there. I should investigate the room."},
		["Investigate the Brightly Lit Room"] =
			{appendText=". In the opposite corner of the room from the map, another sigil glows in the corner of the floor."},
		[16] = 
			{appendStepText="", stepTextKey="I should talk to Sirilonwe."},
		["Talk to Sirilonwe 5"] =
			{appendText=" about where to go next and her many questions about this place.", stepTextKey="I should talk to Sirilonwe."},
		[17] = 
			{appendStepText="South of the central room in Ashbound Hall, ", stepTextKey="We found a rough map of this place, which is helpful and the next sealed door should not be too far ahead of us."},
		["Continue the Search for Terinvel 1"] =
			{appendText=" in the room to the north.", stepTextKey="We found a rough map of this place, which is helpful and the next sealed door should not be too far ahead of us."},
		[18] = 
			{appendStepText="In the central chamber, on a walkway above the cavern below, ", stepTextKey="We need to cross a bridge to get to the next sealed door. Unfortunately there are some big piles of fallen stones blocking our way."},
		["Talk to Sirilonwe 6"] =
			{appendText=" and see if she has any ideas about how to get across.", stepTextKey="We need to cross a bridge to get to the next sealed door. Unfortunately there are some big piles of fallen stones blocking our way."},
		[19] = 
			{appendStepText="In the central chamber on the walkway above the cavern floor, ", stepTextKey="To get rid of the rubble on the bridge, so we can cross safely, Sirilonwe is trying some sort of alteration spell, momentarily weakening the structure of the rocks so they can be easily smashed."},
		["Clear the Bridge"] =
			{appendText=" by smashing the altered rock."},
		[20] = 
			{appendStepText="North of the central chamber of Ashbound Hall, ", stepTextKey="Azatha said there was a sealed door further into this place. We need to find it and unseal it."},
		["Continue the Search for Terinvel 2"] =
			{appendText=". Another shielded door lies to the north. ", stepTextKey="Azatha said there was a sealed door further into this place. We need to find it and unseal it."},
		[21] = 
			{appendStepText="To the north, ", stepTextKey="We found a door that requires three aspects. We should unseal it."},
		["Unseal the Door"] =
			{appendText=". I should put the Brutality sigil in the center of the apparatus as before, then put the Domination sigil just to the left and the Conquest sigil just to the right of the center plate."},
		[22] = 
			{appendStepText="Continue through the unwarded door, into the Broken Halls. ", stepTextKey="This area has borne the brunt of the fall from Coldharbour into Tamriel. We're pressing forward and looking for any more clues about why Terinvel wanted to get into this place ahead of everyone, even his partner."},
		["Search the Broken Halls"] =
			{appendText=". The red sigils seem to be leading us somewhere..."},
		[23] = 
			{appendStepText="", stepTextKey="This area has borne the brunt of the fall from Coldharbour into Tamriel. We're pressing forward and looking for any more clues about why Terinvel wanted to get into this place ahead of everyone, even his partner."},
		["Investigate the Campsite"] =
			{appendText=" in a corner of the sunken area in the center of the room. There's a hat on the stone in front of the campfire, and a note on the ground to the right."},
		[24] = 
			{appendStepText="", stepTextKey="Sirilonwe wants to cast some sort of spell to see if she can produce an echo of Terinvel and Ormard, since they may recently have been in this spot."},
		["Wait for Sirilonwe"] =
			{appendText="."},
		[25] = 
			{appendStepText="", stepTextKey="I should talk to Sirilonwe"},
		["Talk to Sirilonwe 7"] =
			{appendText=". She still wants to continue. We should move on.", stepTextKey="I should talk to Sirilonwe"},
		[26] = 
			{appendStepText="", stepTextKey="This part of Ashbound Hall is a broken mess. We need to navigate through it."},
		["Find the Crater"] =
			{appendText=" through the door to the east."},
		[27] = 
			{appendStepText="", stepTextKey="This part of Ashbound Hall is a broken mess. We need to navigate through it."},
		["Cross the Crater"] =
			{appendText=", defeating any vampires or other foes along the way, and continue through the door on the far side."},
		[28] = 
			{appendStepText="", stepTextKey="This part of Ashbound Hall is a broken mess. We need to navigate through it."},
		["Continue Pursuing Terinvel"] =
			{appendText=" through a large room with square pillars and falling debris. Another door lies ahead."},
		[29] = 
			{appendStepText="", stepTextKey="This part of Ashbound Hall is a broken mess. We need to navigate through it."},
		["Talk to Livanio Deltorius"] =
			{appendText=", he has asked for our help and promised not to harm us. He would like some healing in return to strengthen him for the journey out."},
		[30] = 
			{appendStepText="In the depths of Ashbound Hall, ", stepTextKey="Sirilonwe healed Liviano with a spell and he decided to attack us. She turned him into ashes. I should search his remains to see if he did have the Aspect he claimed to."},
		["Search Livanio's Remains"] =
			{appendText=", an ashpile in the center of the floor."},
		[31] = 
			{appendStepText="I found the Aspect of Corruption on the vampire's remains. ", stepTextKey="I should talk to Sirilonwe about what we learned and what just happened."},
		["Talk to Sirilonwe 8"] =
			{appendText=".", stepTextKey="I should talk to Sirilonwe about what we learned and what just happened."},
		[32] = 
			{appendStepText="Deep in Ashbound Hall, ", stepTextKey="We aren't far from the big courtyard we saw on a map. We believe that Terinvel, and Ormard are near there, behind another sealed door."},
		["Reach the Central Courtyard"] =
			{appendText=", through the door ahead. A small room to the left contains another note. Diagonally across from that room, a book lies open on the floor. \n\nI should continue following red sigils through the hall; they seem to be guiding us... but for good or ill?"},
		[33] = 
			{appendStepText="We defeated the guardian, but Ormard lies injured on the floor. A discarded note is by the rubble near the wall. ", stepTextKey="I should talk to Sirilonwe about what we learned and what just happened."},
		["Talk to Ormard"] =
			{appendText=", apparently dying of some sort of blood curse on the floor."},
		[34] = 
			{appendStepText="", stepTextKey="We made it to the courtyard we had seen on a map earlier. I should look around."},
		["Look for the Aspect of Dread"] =
			{appendText=". If it's like the others, it should be a small oval, glowing blue. I should check around the rubble, in case he tried to hide it."},
		[35] = 
			{appendStepText="Deep within Ashmund Hall, ", stepTextKey="We found more information and the last Aspect we need to get to Terinvel. I should talk to Sirilonwe."},
		["Talk to Sirilonwe 9"] =
			{appendText=", standing across the room by Ormard's body.", stepTextKey="We found more information and the last Aspect we need to get to Terinvel. I should talk to Sirilonwe."},
		[36] = 
			{appendStepText="Finally, ", stepTextKey="We have enough aspects to unseal the Den of Gargoyles."},
		["Unseal the Den of Gargoyles"] =
			{appendText=". There is a final apparatus waiting up the nearby stairs. Place the sigils to the center, left, right, far left, and far right."},
		[37] = 
			{appendStepText="In Ashmund Hall, at the final door, ", stepTextKey="We've unsealed the Den of Gargoyles. Time to face the Elder and find Terinvel."},
		["Enter the Den of Gargoyles"] =
			{appendText=", through the door ahead."},
		[38] = 
			{appendStepText="In the final arena, ", stepTextKey="Ormard, the vampire who lured Terinvel into Ashbound Hall, and his master, the Elder, have Terinvel. We'll need to kill them to free Sirilonwe's friend."},
		["Kill The Elder"] =
			{appendText=" and all her minions."},
		[39] = 
			{appendStepText="In the final arena in Ashmund Hall, ", stepTextKey="Although the Elder tossed Terinvel aside, it appears he is all right. He probably wants to thank us."},
		["Wait for Terinvel"] =
			{appendText=" to recover. He is apparently unhappy that we killed the Elder Vampire, along with all its knowledge."},
		[40] = 
			{appendStepText="In the final arena in Ashmund Hall, ", stepTextKey="We rescued Terinvel, but he wasn't happy to see us or get rescued. We can talk back at Sirilonwe's camp."},
		["Use Sirilonwe's Portal"] =
			{appendText=" to reach the camp north of Ashmund Hall near the main road along the north-central coast of Eastern Solstice."},
		[41] = 
			{appendStepText="At the camp north of Ashmund Hall, near the road along the northern coast of east-central Solstice, ", stepTextKey="Terinvel is not happy with being rescued and he is arguing with Sirilonwe. Maybe I can talk to him, to give her time to cool off and to calm him down."},
		["Talk to Terinvel"] =
			{appendText=" near the campfire."},
		[42] = 
			{appendStepText="At their camp along the north-central coast of Eastern Solstice, ", stepTextKey="Terinvel is determined to become a vampire, to pursue the piece of the relic he wants so badly. I should talk to Sirilonwe about this, she may know what to do about her friend."},
		["Talk to Sirilonwe 10"] =
			{appendText=" about how to handle Terinvel's ... condition.", stepTextKey="Terinvel is determined to become a vampire, to pursue the piece of the relic he wants so badly. I should talk to Sirilonwe about this, she may know what to do about her friend."},
		[43] = 
			{appendStepText="At their camp on the north-central coast of Eastern Solstice, ", stepTextKey="Terinvel is determined to become a vampire and it is already taking hold, according to him. I think Sirilonwe may try to get him help, before he becomes too dangerous."},
		["Talk to Sirilonwe 11"] =
			{appendText=", after doing what had to be done.", stepTextKey="Terinvel is determined to become a vampire, and it is already taking hold, according to him. I think Sirilonwe may try to get him help, before he becomes too dangerous."},
	},



[GetQuestName(7244)] = { --"Mystery of the Broken Temple"	--aashiana 
		[1] = 
			{appendStepText="Outside the Temple, on a small Island northwest of Sunport, ", stepTextKey="Eraamine needs a lucent shard to empower her translocation rod. I should search the nearby rubble to find one."},
		["Search Rubble for Lucent Shard"] =
			{appendText=". The temple is in disrepair, and there are piles of rubble all around the outside walls of the building."},
		[2] = 
			{appendStepText="On a small island northwest of Sunport, ", stepTextKey="I found a lucent shard outside Broken Light Temple. I should give it to Eraamine."},
		["Talk to High Priest Eraamine 1"] =
			{appendText=", searching rubble south of the main temple for... something.", stepTextKey="I found a lucent shard outside Broken Light Temple. I should give it to Eraamine."},
		[3] = 
			{appendStepText="Southeast of the Broken Light Temple, on a small island northwest of Sunport, ", stepTextKey="Eraamine gave me the translocation rod so that I can try it out. She asked me to use it and pick up a large pile of rubble nearby. I should use the rod as she instructed."},
		["Use the Rod to Collect Rubble"] =
			{appendText=" in the center of the circular plaza at the top of the stairs."},
		[4] = 
			{appendStepText="On a circular plaza southeast of the Golden Light Temple, on an island northwest of Sunport, ", stepTextKey="I used the translocation rod on the large pile of rubble and it disappeared. High Priest Eraamine pointed out where she'd like me to place the stone. I should use the rod and release the rubble."},
		["Use the Rod to Place Rubble"] =
			{appendText=" at the gap in the stone walkway leading to the temple entrance."},
		[5] = 
			{appendStepText="On a circular plaza southeast of the Golden Light Temple, on an island northwest of Sunport, ", stepTextKey="I filled a gap in the path to the temple entrance with stone from the rod. High Priest Eraamine ran ahead and entered Broken Light Temple. I should follow her and go inside."},
		["Enter Broken Light Temple"] =
			{appendText=" by crossing the path I created and entering through the doors ahead."},
		[6] = 
			{appendStepText="On an island northwest of Sunport, ", stepTextKey="I entered Broken Light Temple but I don't see High Priest Eraamine. I should explore deeper inside to find her."},
		["Find High Priest Eraamine"] =
			{appendText=" following her along the sandy path into the temple."},
		[7] = 
			{appendStepText="On an island northwest of Sunport, we entered the Broken Light Temple through an upper door on the south side. Inside, ", stepTextKey="High Priest Eraamine found a set of doors that she referred to as cynosure. She tried to open them, but without success. I should search the room for information about these doors and what lies beyond them."},
		["Search For Clues to the Cynosure Doors"] =
			{appendText=". Scattered around the room are an old Meridian blade, a broken statue, and a note relating some of the events surrounding the fall of the temple. The note also describes how a true believer may access and purify the temple."},
		[8] = 
			{appendStepText="Within the first chamber we entered on the south side of the temple, ", stepTextKey="I found a letter that described how priests locked the doors to the cynosure after a catastrophe. I should discuss what I found with High Priest Eraamine."},
		["Talk to Eraamine"] =
			{appendText=", standing near the door sealed with glowing sigils. It appears there may be rituals we can perform in other parts of the temple to unlock the doors. She wants me to help her choose where to start."},
		[9] = 
			{appendStepText="In the southern chamber we entered, the door to the main temple is sealed by glowing sigils of dawn and dusk. ", stepTextKey="The note I found said that we need to perform a ritual of light in both the eastern Dawn Wing and western Purity Wing of the temple. I should enter the Dawn Wing and find the ritual site."},
		["Enter the Dawn Wing"] =
			{appendText=" through an archway and a door to the east."},
		[10] = 
			{appendStepText="", stepTextKey="High Priest Eraamine and I entered the eastern Dawn Wing of Broken Light Temple. She wants to search for anything that can help guide us to the ritual site. I should look around for information."},
		["Search for Information on the Dawn Wing"] =
			{appendText=". There is a box lit by candles on the floor to the left, a small red gem on the floor near some candles by the stairs to the right, and an amulet on a cloth on top of a table ahead. And urns... so many urns."},
		[11] = 
			{appendStepText="Among other items in the eastern Dawn Wing, ", stepTextKey="I found an old amulet and High Priest Eraamine said it called to her. When she held it, something seemed to possess her. I should talk to whatever has a hold on Eraamine."},
		["Talk to Carisea"] =
			{appendText=", by the central arch inside the east wing."},
		[12] = 
			{appendStepText="Inside the eastern Dawn Wing of the temple, ", stepTextKey="Someone named Carisea possessed High Priest Eraamine and spoke through her. She gave me instructions on how to find the Dawn Wing ritual site. I should make a path along the eastern bridge to begin my search."},
		["Use a Rod to Make a Path Across the Bridge"] =
			{appendText=". Below the broken bridge, I can see some rubble that I could pick up with the wand High Priest Araamine gave me. Maybe I can use that to fill the gap in the stone bridge!\n\nWhile gathering the rubble below, I found a book in an alcove written in Carisea's time. Maybe there will be others scattered around the temple that can explain more of what happened here. We should cross the bridge and see what lies on the other side."},
		[13] = 
			{appendStepText="", stepTextKey="As we progress through the Dawn Wing, we encountered more collapsed walkways. I should use the rod to fix the gaps and continue my search for the ritual site."},
		["Search For the Ritual Site"] =
			{appendText=". Guardians protect the way, and more broken paths must be repaired to complete the crossing. There is plenty of rubble, but not all of it is suitable to create the paths.\n\nA large glowing statue of Meridia lies beyond the first bridge we repaired. Behind the statue is another broken path to be repaired by picking up rubble below. I will probably have to fight my way further through the watery depths, then backtrack a bit to the first bridge to make my way back to the second broken bridge with the rubble."},
		[14] = 
			{appendStepText="After repairing two broken stone bridges in the eastern Dawn Wing, ", stepTextKey="I reached the door to the Dawn Wing ritual site. Before I could go, Sentinel Carisea possessed High Priest Eraamine and stopped me. I should talk to her and find out what she wants."},
		["Talk To Sentinel Carisea"] =
			{appendText=". She wants to warn us and explain the choices and battles that lie ahead."},
		[15] = 
			{appendStepText="Within the Dawn wing, after repairing the broken bridges to the ritual site, ", stepTextKey="Sentinel Carisea warned me that, as the temple's sentinel, she will attack us when we enter the ritual site room. Regardless, I should go in so we can complete the ritual."},
		["Enter the Ritual Site"] =
			{appendText=" through the door to the north, beyond the repaired stone bridges."},
		[16] = 
			{appendStepText="Within the ritual site at the north end of the eastern Dawn Wing, ", stepTextKey="I discovered Sentinel Carisea's true form as a giant glowing monster. This must be the sentinel that defends the temple. I should defeat Carisea so we can complete the ritual of light."},
		["Defeat Sentinel Carisea"] =
			{appendText=". Use the golden shield for protection if you need to."},
		[17] = 
			{appendStepText="Within the ritual site at the north end of the eastern Dawn Wing, ", stepTextKey="I fought alongside High Priest Eraamine to defeat Sentinel Carisea. Now we must perform this wing's ritual. I should talk to Eraamine and find out how to proceed."},
		["Talk to High Priest Eraamine 2"] =
			{appendText=" to learn about my part in the ritual.", stepTextKey="I fought alongside High Priest Eraamine to defeat Sentinel Carisea. Now we must perform this wing's ritual. I should talk to Eraamine and find out how to proceed."},
		[18] = 
			{appendStepText="Within the ritual site at the north end of the eastern Dawn Wing, ", stepTextKey="High Priest Eraamine explained to me how the ritual works. I should follow her instructions and complete the ritual to unlock a cynosure door."},
		["Complete the Ritual 1"] =
			{appendText=", beginning in the center of the room. Then walk to the tiles she directs me to during the ritual, drawing glowing lines between the cardinal directions.", stepTextKey="High Priest Eraamine explained to me how the ritual works. I should follow her instructions and complete the ritual to unlock a cynosure door."},
		[19] = 
			{appendStepText="Within the ritual site at the north end of the Dawn Wing, ", stepTextKey="The east wing ritual is complete. Now I should return to the temple's great hall."},
		["Return to the Great Hall 1"] =
			{appendText=", through a portal on the glowing dais at the north end of the room.", stepTextKey="The east wing ritual is complete. Now I should return to the temple's great hall."},
		[20] = 
			{appendStepText="Here at the southern entrance to the temple, ", stepTextKey="The note I found said that we need to perform a ritual of light in both the Purity and Dawn Wings of the temple. I should enter the western Purity Wing to complete the ritual on that side."},
		["Enter the Purity Wing"] =
			{appendText=" to the west, through an archway and another door. I should talk to Eraamine first to find out what lies ahead."},
		[21] = 
			{appendStepText="", stepTextKey="Eraamine and I entered the temple's western Purity Wing. Somewhere in here is part of the ritual to unlock the cynosure doors. I should search the wing for the ritual site."},
		["Search for the Ritual Site 1"] =
			{appendText=". A note on the table to the left of the doorway may shed some light on what happened here. Another damaged journal is in the room beyond on a table to the left. There is a lot of rubble down here. Maybe I can use it to repair something in the upper part of this wing?", stepTextKey="Eraamine and I entered the temple's western Purity Wing. Somewhere in here is part of the ritual to unlock the cynosure doors. I should search the wing for the ritual site."},
		[22] = 
			{appendStepText="It worked! I've repaired a walkway to the east on the upper level. ", stepTextKey="While we searched for the ritual site, a strange man with glowing eyes spoke to us. I should talk to him and find out what he wants."},
		["Talk to Tomarion 1"] =
			{appendText=", behind a metal grate. Is that a prison cell? He seems to want to help us and gave us directions to the ritual site in this wing. There's something very odd about him though. I should talk with Eraamine before continuing.", stepTextKey="While we searched for the ritual site, a strange man with glowing eyes spoke to us. I should talk to him and find out what he wants."},
		[23] = 
			{appendStepText="In the western Dusk Wing, in a cell to the east, ", stepTextKey="We met Tomarion who was once the High Priest of this temple. He wants to help us access the cynosure. He told us to head north to find the ritual site. I should head in the direction he pointed."},
		["Search for the Ritual Site 2"] =
			{appendText=". Continue to the north, then west down into the lower level, then to the north again through another door. Looks like I will need to collect some more rubble to repair this path. Tomarion can tell me where to find some, in the center of a circular room up the stairs. \n\nMore rubble from up here will be needed to fix a second gap in the bridge once the first one is repaired. To find a large enough pile of rubble, I must go all the way around to the east side of the upper area, past a giant spider and her brood, and around the corner. After collecting the rubble, I can continue along that path and jump down through a hole to return to the path that needs repairing.\n\nOnce the path is complete, cross the path and enter the ritual site past the door.", stepTextKey="We met Tomarion who was once the High Priest of this temple. He wants to help us access the cynosure. He told us to head north to find the ritual site. I should head in the direction he pointed."},
		[24] = 
			{appendStepText="I found the ritual Chamber at the northern end of the western Dusk Wing. ", stepTextKey="True to his word, Tomarion led me to the site for the ritual to unlock a cynosure door. He appeared again and asked to speak. I should talk to Tomarion again."},
		["Talk to Tomarion 2"] =
			{appendText=", behind the bars to the left of the glowing sigil.", stepTextKey="True to his word, Tomarion led me to the site for the ritual to unlock a cynosure door. He appeared again and asked to speak. I should talk to Tomarion again."},
		[25] = 
			{appendStepText="In the ritual Chamber at the northern end of the western Dusk Wing, ", stepTextKey="Tomarion encouraged me to allow him access the cynosure. He wants it to turn him into a sentinel. After he left, High Priest Eraamine asked to the discuss the ritual. I should speak with her."},
		["Talk to High Priest Eraamine 3"] =
			{appendText=" in the Ritual Chamber by the east wall. ", stepTextKey="Tomarion encouraged me to allow him access the cynosure. He wants it to turn him into a sentinel. After he left, High Priest Eraamine asked to the discuss the ritual. I should speak with her."},
		[26] = 
			{appendStepText="In the ritual Chamber at the northern end of the western Dusk Wing, ", stepTextKey="High Priest Eraamine recognized the ritual required to unlock the cynosure door. I should listen to her instructions and do what she says."},
		["Complete the Ritual 2"] =
			{appendText=", starting in the center of the room and following her directions from there.", stepTextKey="High Priest Eraamine recognized the ritual required to unlock the cynosure door. I should listen to her instructions and do what she says."},
		[27] = 
			{appendStepText="In the ritual Chamber at the northern end of the western Dusk Wing, ", stepTextKey="I told High Priest Eraamine that Tomarion asked that we let him inside the cynosure. She seemed skeptical about the idea. I should head back to the great hall and meet her there."},
		["Return to the Great Hall 2"] =
			{appendText=", through the portal on the glowing dais at the north end of the ritual chamber.", stepTextKey="I told High Priest Eraamine that Tomarion asked that we let him inside the cynosure. She seemed skeptical about the idea. I should head back to the great hall and meet her there."},
		[28] = 
			{appendStepText="We are back at the southern entrance to the temple, having completed the rituals in both wings to allow entrance to the cynosure. ", stepTextKey="As I approached the door to the cynosure, Tomarion appeared and entered first. High Priest Eraamine tried to stop him, but failed. I should talk to her and prepare for what's next."},
		["Talk to High Priest Eraamine 4"] =
			{appendText=".", stepTextKey="As I approached the door to the cynosure, Tomarion appeared and entered first. High Priest Eraamine tried to stop him, but failed. I should talk to her and prepare for what's next."},
		[29] = 
			{appendStepText="", stepTextKey="Tomarion entered the cynosure before we could stop him. I should join High Priest Eraamine and follow him inside."},
		["Enter the Cynosure"] =
			{appendText="."},
		[30] = 
			{appendStepText="After repairing the Dawn and Dusk Wings of the temple, ", stepTextKey="Tomarion entered the cynosure before we could stop him. I should join High Priest Eraamine and follow him inside."},
		["Find a Way to Cross the Bridge"] =
			{appendText=". Through the door, there is a broken bridge with a large pile of rubble to the right. I should use it to repair the bridge."},
		[31] = 
			{appendStepText="After repairing the Dawn and Dusk Wings of the temple, ", stepTextKey="Tomarion entered the cynosure before we could stop him. I should join High Priest Eraamine and follow him inside."},
		["Watch Tomarion"] =
			{appendText=", as he uses the cynosure font's power to become her new sentinel."},
		[32] = 
			{appendStepText="Within the cynosure chamber, ", stepTextKey="I tried to stop Tomarion from absorbing the cynosure's power, but was too late. He transformed into the temple's new sentinel. I should destroy him before he kills us."},
		["Defeat Sentinel Tomarion"] =
			{appendText=", using the golden bubbles to protect yourself from his wrath."},
		[33] = 
			{appendStepText="Within the cynosure chamber, ", stepTextKey="We defeated Sentinel Tomarion, but his transformation convinced High Priest Eraamine to destroy the cynosure. She suggested I use the translocation rod on the pillars around the room. I should break the pillars with the rod."},
		["Use the Rod to Destroy the Cynosure Orbs"] =
			{appendText=" "},
		[34] = 
			{appendStepText="Within the cynosure chamber, ", stepTextKey="I broke the pillars holding up the cynosure and now the room is crumbling. I should escape Broken Light Temple and speak to High Priest Eraamine."},
		["Meet Eraamine in the Great Hall"] =
			{appendText=", across the bridge and through the door to the south. She is standing by a broken pillar near the pool."},
		[35] = 
			{appendStepText="Within the cynosure chamber, ", stepTextKey="High Priest Eraamine and I destroyed the cynosure so that no one can access its enormous power. I should talk to her about what comes next."},
		["Talk to High Priest Eraamine 5"] =
			{appendText=", standing by a broken pillar near the pool.", stepTextKey="High Priest Eraamine and I destroyed the cynosure so that no one can access its enormous power. I should talk to her about what comes next."},
	},




 [GetQuestName(7248)] = { --"Party Pains" 	--aashiana               
        [1] = 
            {appendStepText="In Western Solstice, centrally located near the southern coast in a spot away from any roads or prying eyes, ", stepTextKey="High Priest Caroril showed me the entrance to the Vale of Revelry. I should make my way inside."},
        ["Enter the Vale of Revelry"] =
            {appendText=". It seems many have discarded empty bottles and worldly possessions here, as if they will not need them again."},
        [2] = 
            {appendStepText="This tent is truly much larger than it appears! ", stepTextKey="The missing acolytes are somewhere inside this party. It shouldn't be too hard tracking down acolytes of the God of Love here."},
        ["Find the Missing Acolytes"] =
            {appendText=" \n\nThey will be somewhere along this paved winding path, doing Sanguine knows what... \nI found one acolyte who has stayed true to her faith, in the easternmost clearing at a home on top of the hill. She is attempting to convert the followers of Sanguine to worship Dibella, probably a lost cause.\nReturning to the main paved path, I wound my way up to a large circular arena, strangely empty for a party. In a dark red tent to the east, I found Rakamin, quite inebriated. He plans to tell Cororil all about it... when he is able to find his way back.\nContinuing on the paved path to the northeast corner, I found another worshipper dancing near a tent where a Master of Cups provides music. She loves the freedom and feeling of the dance and plans to leave the worship of Dibella. At least she agreed to tell Cororil herself."},
        [3] = 
            {appendStepText="Within the Vale of Revelry, in a blue and red tent in the south-central area of Western Solstice, ", stepTextKey="I convinced the missing acolytes to leave the revelers party. I should return to High Priest Caroril and see what becomes of their sect."},
        ["Talk to High Priest Caroril"] =
            {appendText=", outside the entrance to the tent, chiding her acolytes for their behavior."},
    },


[GetQuestName(7311)] = { --"A Pirate's Debt"	--aashiana
		[1] = 
			{appendStepText="Just southeast of the Corelanya Wayshrine below the Great Bay in Western Solstice, there is a small shop built into a rocky hideaway. Outside the shop, an angry Sea Elf is looking for help. ", stepTextKey="I should talk to Cirwynia."},
		["Talk to Cirwynia 1"] =
			{appendText=" and see what you can do to help her.", stepTextKey="I should talk to Cirwynia."},
		[2] = 
			{appendStepText="Outside Wankeen's shop in Western Solstice, southeast of the Corelanya Manor Wayshrine, ", stepTextKey="Cirwynia says there's a valuable stolen heirloom at the Worm Cult camp. I should go there and see if I can find it."},
		["Go to Worm Cult Camp"] =
			{appendText=" she has marked on my map and steal the item. Follow the road south and then east through the sands to a clearing with three large shells. Cirwynia is waiting there."},
		[3] = 
			{appendStepText="As I promised, ", stepTextKey="I should steal the heirloom from the Worm Cult camp."},
		["Rob the Worm Cult Camp"] =
			{appendText=" down below the clearing. There's only one tent, so it must be there somewhere. There are a few boxes and coffers on the tables inside that could contain something valuable."},
		[4] = 
			{appendStepText="On the southeast sands of Western Solstice, ", stepTextKey="I acquired the stolen family heirloom from the Worm Cult camp. Now, I should meet Cirwynia back at Wankeen's shop, southeast of Shor's Stand."},
		["Meet Cirwynia at Wankeen's Shop 1"] =
			{appendText=", within a rock formation just southeast of the Corelanya Manor Wayshrine.", stepTextKey="I acquired the stolen family heirloom from the Worm Cult camp. Now, I should meet Cirwynia back at Wankeen's shop, southeast of Shor's Stand."},
		[5] = 
			{appendStepText="Within a rock formation just southeast of the Corelanya Manor Wayshrine, ", stepTextKey="I arrived at Wankeen's shop from the Worm Cult camp. I should talk to Cirwynia."},
		["Talk to Cirwynia 2"] =
			{appendText=", waiting inside by the fire.", stepTextKey="I arrived at Wankeen's shop from the Worm Cult camp. I should talk to Cirwynia."},
		[6] = 
			{appendStepText="Outside Wankeen's shop in Western Solstice, southeast of the Corelanya Manor Wayshrine, ", stepTextKey="Cirwynia says there's a valuable Argonian idol at the antiquarian's hut. I should go there and see if I can find it."},
		["Go to Antiquarian's Hut"] =
			{appendText=" she has marked on my map and then steal the item. The Antiquarian's Hut is west of the shop, next to a xanmeer along the southern shore of the Great Bay. The ramp to the front door is to the left on the first level of the xanmeer."},
		[7] = 
			{appendStepText="From the first level of the xanmeer, up the wooden ramp to the left, ", stepTextKey="I should collect the idol from the antiquarian's hut."},
		["Rob the Antiquarian's Hut"] =
			{appendText=". The item is on the table in the back, opposite the front door."},
		[8] = 
			{appendStepText="I avoided undue attention and ", stepTextKey="I acquired the idol from the antiquarian's hut. Now, I should meet Cirwynia back at Wankeen's shop, southeast of Shor's Stand."},
		["Meet Cirwynia at Wankeen's Shop 2"] =
			{appendText=", within a rock formation just southeast of the Corelanya Manor Wayshrine.", stepTextKey="I acquired the idol from the antiquarian's hut. Now, I should meet Cirwynia back at Wankeen's shop, southeast of Shor's Stand."},
		[9] = 
			{appendStepText="I returned to Wankeen's shop after ", stepTextKey="I collected the idol from the antiquarian's hut. I should talk to Cirwynia."},
		["Talk to Cyrwinia 3"] =
			{appendText=", waiting inside by the fire.", stepTextKey="I collected the idol from the antiquarian's hut. I should talk to Cirwynia."},
		[10] = 
			{appendStepText="Wankeen has gone back on his deal, no doubt under pressure from Captain Artellas. ", stepTextKey="I should go with Cirwynia to meet Captain Artellas in the back room."},
		["Meet Captain Artellas in the Back Room"] =
			{appendText="."},
		[11] = 
			{appendStepText="In the back room of Wakeen's shop, just southeast of the Corelanya Manor Wayshrine in Western Solstice, ", stepTextKey="I should defend Cirwynia from Artellas and his crew."},
		["Defend Cirwynia 1"] =
			{appendText=", whatever it takes. These are pirates, after all.", stepTextKey="I should defend Cirwynia from Artellas and his crew."},	
		[12] = 
			{appendStepText="In the back room of Wakeen's shop, just southeast of the Corelanya Manor Wayshrine in Western Solstice, ", stepTextKey="I should defend Cirwynia from Captain Artellas and his crew."},
		["Defend Cirwynia 2"] =
			{appendText=", whatever it takes. These are pirates, after all.", stepTextKey="I should defend Cirwynia from Captain Artellas and his crew."},
		[13] = 
			{appendStepText="In the back room of Wakeen's shop, just southeast of the Corelanya Manor Wayshrine in Western Solstice, ", stepTextKey="Now that we defeated Captain Artellas, I should talk to Cirwynia."},
		["Talk to Cirwynia 4"] =
			{appendText=".", stepTextKey="Now that we defeated Captain Artellas, I should talk to Cirwynia."},
			},



[GetQuestName(7313)] = { --"Roots in Stone"	--aashiana
		[1] = 
			{appendStepText="As I approached the Argonian settlement of Xor-Hist, built into the rocky cliffs along the central east coast of Solstice, ", stepTextKey="An injured torchbearer explained to Mani-Kai that there are three signal pyres surrounding the village. We need to light each of them so that villagers outside of Xor-Hist know to seek shelter before the Worm Cult attacks."},
		["Light the Signal Pyres"] =
			{appendText=" \n\nThe northern pyre is up on the cliffs north of Xor-Hist Village, east up a path from the road and wayshrine of the same name to a rocky clearing. The pyre is at the top of the stone steps north of the clearing, where it can be easily seen from the village.\n\nThe western pyre is across the road from the center of the Village, up on a ledge near the mountains to the west, lit by a torch just below.\n\nThe southern pyre is south of the southern entrance to the Village on a ledge by the rocky shore, with pink-flowered vines growing on the stones below.\n\nEach of the pyres is guarded by Daedra, no doubt to prevent the village from being alerted to their presence."},
		[2] = 
			{appendStepText="North, west, and south of Xor-Hist Village, on the central east coast of Solstice, ", stepTextKey="All three signal pyres are lit. We should head toward the village and see how they fare."},
		["Go to Xor-Hist"] =
			{appendText=". There are entrances across from each of the pyres."},
		[3] = 
			{appendStepText="After lighting the signal pyres near Xor-Hist, along the east-central coast of Solstice, ", stepTextKey="A Naga warrior appeared as we made our way toward Xor-Hist and demanded we talk to him. I should speak with him."},
		["Talk to Xica-Ilan 1"] =
			{appendText=" to gain entrance to the village.", stepTextKey="A Naga warrior appeared as we made our way toward Xor-Hist and demanded we talk to him. I should speak with him."},
		[4] = 
			{appendStepText="After lighting the signal pyres near Xor-Hist, along the east-central coast of Solstice, ", stepTextKey="The warrior named Xica-Ilan, a death-dancer currently protecting Xor-Hist, gave us permission to enter the village to speak with the elder, Stone-Shaper Tozka."},
		["Enter Xor-Hist"] =
			{appendText=". Xica-Ilan said we could find the Stone-Shaper at the center of the village, along the west side."},
		[5] = 
			{appendStepText="Within Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="I should speak with Stone-Shaper Tozka. I can find him near the center of the village."},
		["Find Stone-Speaker Tozka"] =
			{appendText=", on the stone plaza near a wooden doorway lit by braziers."},
		[6] = 
			{appendStepText="Within Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="I should speak with Stone-Shaper Tozka. I can find him near the center of the village."},
		["Talk to Stone-Speaker Tozka"] =
			{appendText="."},
		[7] = 
			{appendStepText="Within Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="Stone-Shaper Tozka agreed to allow Mani-Kai to commune with the village's Hist tree. It is in a courtyard in the center of the village. I should enter the courtyard now."},
		["Enter the Hist Courtyard"] =
			{appendText=" through the wooden door, framed with stone and lit by braziers."},
		[8] = 
			{appendStepText="Within the central courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="Mani-Kai wants to speak with me before she communes with the Hist. I should see what she needs."},
		["Talk to Mani-Kai 1"] =
			{appendText=".", stepTextKey="Mani-Kai wants to speak with me before she communes with the Hist. I should see what she needs."},
		[9] = 
			{appendStepText="Within the central courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="Mani-Kai explained that her ritual uses a set of wind chimes. She asked me to hang them from the Hist tree."},
		["Hang Mani-Kai's Wind Chimes"] =
			{appendText=" from a branch of the Hist Tree growing over the path."},
		[10] = 
			{appendStepText="Within the central courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="The wind chimes reacted wildly after I hung them on the Hist tree. I should ask Mani-Kai what this means."},
		["Talk to Mani-Kai 2"] =
			{appendText=".", stepTextKey="The wind chimes reacted wildly after I hung them on the Hist tree. I should ask Mani-Kai what this means."},
		[11] = 
			{appendStepText="Within the central courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="Mani-Kai believes the Hist tree wants us to enter a temple hidden beneath the village. She says it is important that Stone-Shaper Tozka gives us permission to enter the temple. I should speak with him."},
		["Talk to Stone-Shaper Tozka 1"] =
			{appendText=" in the center of the path, barring the way to whatever lies below.", stepTextKey="Mani-Kai believes the Hist tree wants us to enter a temple hidden beneath the village. She says it is important that Stone-Shaper Tozka gives us permission to enter the temple. I should speak with him."},
		[12] = 
			{appendStepText="Within the central courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="Stone-Shaper Tozka granted us permission to enter the temple, Atak's First Root, under the supervision of Xica-Ilan. I should enter the temple and search for whatever it is Mani-Kai believes we will find."},
		["Enter Atak's First Root"] =
			{appendText=" along the path, down the stone stairs, and through the door that lies below."},
		[13] = 
			{appendStepText="Within Xor-Hist Village, on the west-central coast of Solstice, we have entered the Temple below the Hist Tree. ", stepTextKey="The temple is badly damaged by the roots of the Hist tree and the centuries that have passed. I should tread carefully."},
		["Explore Atak's First Root 1"] =
			{appendText=" \n\nA short distance in, near a large hist root, vine-covered bookcases line the walls behind a stone table holding a Builder's journal. ", stepTextKey="The temple is badly damaged by the roots of the Hist tree and the centuries that have passed. I should tread carefully."},
		[14] = 
			{appendStepText="Within Xor-Hist Village, on the west-central coast of Solstice, we have entered the Temple below the Hist Tree. ", stepTextKey="The temple still contains writings belonging to the Builders, the first Argonians to settle on Solstice. I should look around for anything that might reveal the temple's secrets and why the Hist wants us here."},
		["Explore Atak's First Root 2"] =
			{appendText=" \n\nAreas to the north and south hold additional books, tools, and relics from an ancient time.", stepTextKey="The temple still contains writings belonging to the Builders, the first Argonians to settle on Solstice. I should look around for anything that might reveal the temple's secrets and why the Hist wants us here."},
		[15] = 
			{appendStepText="Within Xor-Hist Village, on the west-central coast of Solstice, we have entered the Temple below the Hist Tree. ", stepTextKey="We found journals belonging to an ancient Builder that revealed the existence of a vault deeper in the temple, supposedly filled with voskrona stone guardians. We should head farther in to find it."},
		["Explore the Temple"] =
			{appendText=" through the eastern passageway."},
		[16] = 
			{appendStepText="Beneath Xor-Hist Village, on the west-central coast of Solstice,  ", stepTextKey="There is a large, cavernous space deep in the temple that contains what appears to be an upside-down xanmeer. I should speak with Mani-Kai and Xica-Ilan about how to proceed."},
		["Talk to Mani-Kai 3"] =
			{appendText=".\n", stepTextKey="There is a large, cavernous space deep in the temple that contains what appears to be an upside-down xanmeer. I should speak with Mani-Kai and Xica-Ilan about how to proceed."},
		["Talk to Xica-Ilan 2"] =
			{appendText=".", stepTextKey="There is a large, cavernous space deep in the temple that contains what appears to be an upside-down xanmeer. I should speak with Mani-Kai and Xica-Ilan about how to proceed."},
		[17] = 
			{appendStepText="In the vast cavern beneath Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="The writings revealed three counterweights controlling the pendulums that are blocking us from reaching the xanmeer. Xica-Ilan also gave me a grappling hook to help find the counterweights hidden throughout the cavern. I should search for them."},
		["Release the Counterweights"] =
			{appendText=" \n\nFrom where we stand at the top of the stairs leading down to the pendulums, all three counterweights can be seen - two to the left and one to the right. \n\nWe will likely need our grappling hooks to reach at least some of them, as surely the builders did not intend for the central xanmeer to be easily reached by outsiders. Caves and corridors along the sides may also provide passage."},
		[18] = 
			{appendStepText="In the vast cavern beneath Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="Releasing the counterweights activated the pendulums, which are now swinging along the path toward the vault. We need to get past them to reach it."},
		["Reach the Vault"] =
			{appendText=", by returning to the entrance and heading down the stairs to the pendulums. I should watch them carefully to time my crossing of the bridge. I may still need my grappling hook beyond that point. The doorway to the central vault lies directly ahead."},
		[19] = 
			{appendStepText="In the vast cavern beneath Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="The vault is filled with dormant voskrona guardians. I should speak with Xica-Ilan and see if he has any ideas about how to activate them."},
		["Talk to Xica-Ilan 3"] =
			{appendText=".", stepTextKey="The vault is filled with dormant voskrona guardians. I should speak with Xica-Ilan and see if he has any ideas about how to activate them."},
		[20] = 
			{appendStepText="Within the central vault in the vast cavern beneath Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="One of the dormant guardians appears to be holding the control stone mentioned in the Builder's writings. It is used to activate the voskrona. Xica-Ilan believes there is a way to release the control stone. I should follow his lead."},
		["Release the Builder's Control Stone"] =
			{appendText=", by activating the stone-nest idol on the lower floor, while your companions stand on pressure plates above."},
		[21] = 
			{appendStepText="Within the central vault in the vast cavern beneath Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="Xica-Ilan was right and we were able to release the control stone through a puzzle hidden in the room. I should pick up the control stone."},
		["Take the Builder's Control Stone"] =
			{appendText=" from the central dais."},
		[22] = 
			{appendStepText="Within the central vault in the vast cavern beneath Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="We need to see if the control stone works. I should activate it and see if it awakens the dormant guardians."},
		["Awaken the Guardians"] =
			{appendText=" using the control stone at the totem above the stairs, with glowing red eyes."},
		[23] = 
			{appendStepText="Within the central vault in the vast cavern beneath Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="The control stone worked and the voskrona guardians have begun exiting the temple. Xica-Ilan has gone ahead to warn the village of their arrival. Before we return to Xor-Hist, Mani-Kai wishes to speak with me."},
		["Talk to Mani-Kai 4"] =
			{appendText=", waiting behind me.", stepTextKey="The control stone worked and the voskrona guardians have begun exiting the temple. Xica-Ilan has gone ahead  to warn the village of their arrival. Before we return to Xor-Hist, Mani-Kai wishes to speak with me."},
		[24] = 
			{appendStepText="Within the central vault in the vast cavern beneath Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="Mani-Kai hopes that these stone guardians will be enough to protect the village from the Worm Cult's attack. We should return to Xor-Hist and catch up with Xica-Ilan."},
		["Return to the Surface"] =
			{appendText=", up the stone stairs to the east and out the door to a breathtaking view of the eastern seas. A platform and stairs to the right lead to the southern entrance to the Village. I should go see what's happening there."},
		[25] = 
			{appendStepText="In Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="It seems the Worm Cult launched their attack while we were in the temple. Xica-Ilan is heading into the inner courtyard to protect Stone-Shaper Tozka. I should follow him."},
		["Enter the Courtyard"] =
			{appendText=" through the wooden door."},
		[26] = 
			{appendStepText="In the central courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="I should use the control stone to summon voskrona guardians to our side so we can face down the Worm Cult threat."},
		["Use the Builder's Control Stone"] =
			{appendText=" anywhere in the courtyard."},
		[27] = 
			{appendStepText="In the central courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="I should defeat the Worm Cult threat with the aid of the voskrona guardians."},
		["Defeat the Soul-Shriven Behemoth"] =
			{appendText=" and all its minions, with the help of the Voskrona."},
		[28] = 
			{appendStepText="In the central courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="With the aid of the voskrona guardians, we successfully defeated the Worm Cult's forces. While Xica-Ilan helps Stone-Shaper Tozka get somewhere safe, Mani-Kai wishes to commune once more with the Hist tree. I should speak with her."},
		["Talk to Mani-Kai 5"] =
			{appendText=", standing near the Hist-Tree root.", stepTextKey="With the aid of the voskrona guardians, we successfully defeated the Worm Cult's forces. While Xica-Ilan helps Stone-Shaper Tozka get somewhere safe, Mani-Kai wishes to commune once more with the Hist tree. I should speak with her."},
		[29] = 
			{appendStepText="In the central courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="Mani-Kai believes that the Hist tree has calmed down now that the threat has been ended. I should find Stone-Shaper Tozka and tell him about the voskrona guardians we discovered below the village."},
		["Find Stone-Shaper Tozka"] =
			{appendText=", in the southwest courtyard of Xor-Hist Village, marked by a pink-flowering tree."},
		[30] = 
			{appendStepText="In the southwestern courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="I should speak with Stone-Shaper Tozka about what we discovered in the temple below Xor-Hist."},
		["Talk to Stone-Shaper Tozka 2"] =
			{appendText=".", stepTextKey="I should speak with Stone-Shaper Tozka about what we discovered in the temple below Xor-Hist."},
		[31] = 
			{appendStepText="In the southwestern courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="In thanks for our help facing the Worm Cult threat, and for discovering these ancient stone guardians, Stone-Shaper Tozka has pledged his village's aid to the Stirk Fellowship. Xica-Ilan will now fight beside the Fellowship. I should tell Mani-Kai."},
		["Talk to Mani-Kai 6"] =
			{appendText=", standing nearby.", stepTextKey="In thanks for our help facing the Worm Cult threat, and for discovering these ancient stone guardians, Stone-Shaper Tozka has pledged his village's aid to the Stirk Fellowship. Xica-Ilan will now fight beside the Fellowship. I should tell Mani-Kai."},
		[32] = 
			{appendStepText="In the southwestern courtyard of Xor-Hist Village, on the west-central coast of Solstice, ", stepTextKey="We successfully saved the village of Xor-Hist and gained their aid in the coming fight against the Worm Cult. I should talk with Mani-Kai."},
		["Talk to Mani-Kai 7"] =
			{appendText=".", stepTextKey="We successfully saved the village of Xor-Hist and gained their aid in the coming fight against the Worm Cult. I should talk with Mani-Kai."},
	},



[GetQuestName(7304)] = { --"The Roughest Pearl"		--aashiana
        [1] = 
            {appendStepText="On the southern shore of Sanguine Island, in the center of the Great Bay in southwest Solstice and north of the Everlasting Fair, ", stepTextKey="I should gather the volcanic pearls and bring them to Captain Genevé Delitian."},
        ["Gather the Volcanic Pearls"] =
            {appendText=", glowing black and red on the sand."},
        [2] = 
            {appendStepText="On the southern shore of Sanguine Island, ", stepTextKey="I gathered the pearls and should bring them to Captain Genevé Delitian."},
        ["Find Captain Genevé Delitian"] =
            {appendText=" in Shor's Stand, in the center of the western peninsula of Solstice. She will be sitting at her usual table with ropes and floats on it, left of the entrance to the Whale Splash Inn in the town square."},
        [3] = 
            {appendStepText="On the southern shore of Sanguine Island, ", stepTextKey="I gathered the pearls and should bring them to Captain Genevé Delitian."},
        ["Talk to Captain Genevé Delitian"] =
            {appendText=" about her cargo."},
    },



[GetQuestName(7245)] = { --"Secrets in the Sand"		--aashiana
		[1] = 
			{appendStepText="On the southwest coast of the western peninsula of Solstice, near the mouth of the great central inlet, I found a note pinned to a palm tree warning of dangers ahead. ", stepTextKey="The leaflet said the wandering spirit roams the western beach. I should search the area."},
		["Talk to the Wandering Spirit"] =
			{appendText=", near a small boat just northwest along the coastline."},
		[2] = 
			{appendStepText="Along the southwest coast of the western peninsula of Solstice there is a small boat. ", stepTextKey="The wandering spirit said to meet him in Tainted Leel. I should take the boat and travel there."},
		["Enter Tainted Leel"] =
			{appendText=", using the boat nearby."},
		[3] = 
			{appendStepText="", stepTextKey="I met the wandering spirit in Tainted Leel. I should look around and see if I can determine what's going on here."},
		["Investigate Tainted Leel"] =
			{appendText=". The pool nearby looks interesting."},
		[4] = 
			{appendStepText="Inside an Argonian xanmeer, reached by taking a small boat along the southwest coast of the western peninsula of Solstice, ", stepTextKey="I met the wandering spirit in Tainted Leel. I should look around and see if I can determine what's going on here."},
		["Retrieve the Dagger"] =
			{appendText=" from the skeleton in the pool."},
		[5] = 
			{appendStepText="At the underground entrance to Tainted Leel, offshore of the western coast of Solstice, ", stepTextKey="I retrieved the dagger and helped the wandering spirit recall his name, Akech-Chun. I should speak with him and see what else he remembers."},
		["Talk to Akech-Chun 1"] =
			{appendText=", standing by the pool.", stepTextKey="I retrieved the dagger and helped the wandering spirit recall his name, Akech-Chun. I should speak with him and see what else he remembers."},
		[6] = 
			{appendStepText="At the underground entrance to Tainted Leel, offshore of the western coast of Solstice, ", stepTextKey="Akech-Chun said he senses fragments of his memory in different parts of the village. If I find them, he should be able to recall what happened to him."},
		["Search Tainted Leel for Missing Memories"] =
			{appendText=" \n\nContinue west through the passageways to the central outdoor area of Tainted Leel. Head south to the xanmeer along the southern beach. Go up the stone stairs, to a shrine overlooking the water, with a pink-flowering tree. Akech-Chun seems to recognize the ceremonial bowl on the altar. I should take a closer look.\n\nContinue up the nearby stone stairs and travel along the elevated paths and bridges north, then west, and north again to an area by the mountain. On a ledge to the west is a book the records some history from Akech-Chun's time. Go around the stone building to the east, where windchimes hang over the entrance to a small courtyard. Akech-Chun may recognize any Argonian wind chimes on the floor by the building. I may examine them. \n\nBack toward the mountain, take the wooden bridge to the next platform to the east, and enter the passageways under the mountain through the stone pillars. Follow the lower passages to the southeast, watching out for traps. In a large chamber just north of the entrance, an old foe awaits. Something familiar lies on the altar beyond."},
		[7] = 
			{appendStepText="In Tainted Leel, reached by a small boat from the southeast coast of Solstice, ", stepTextKey="I found three items from Akech-Chun's past that held pieces of his memory. He seems to have recalled what happened to him and wants to reconvene by his corpse. I should meet him there."},
		["Return To Akech-Chun's Corpse"] =
			{appendText=" at the eastern entrance to Tainted Leel, and talk to Akech-Chun about what he remembers now."},
		[8] = 
			{appendStepText="At the underground entrance to Tainted Leel, near his corpse, ", stepTextKey="Akech-Chun believes he was the cause of his village's destruction since he invited the necromancers here. He asked me to tell him what he should do: remain here as a spirit to help his people or release him to face his fate in the Void."},
		["Tell Akech-Chun to Move On"] =
			{appendText=" and find peace in the Void."},
		["Tell Akech-Chun to Help His People"] =
			{appendText=" by remaining here."},
		[9] = 
			{appendStepText="At the underground entrance to Tainted Leel, ", stepTextKey="I decided that Akech-Chun should move on to face his fate in the Void. I should burn his corpse to release his spirit."},
		["Burn Akech-Chun's Corpse"] =
			{appendText=" on the stone platform in the pool."},
		[10] = 
			{appendStepText="", stepTextKey="I decided that Akech-Chun should remain a lingering spirit to provide whatever help he can to his cursed people. I need to place the items we found by his corpse so we can bind his spirit here."},
		["Place Akech-Chun's Items"] =
			{appendText=" near his skeleton on the stone in the pool."},
		[11] = 
			{appendStepText="", stepTextKey="Akech-Chun is now permanently bound to Tainted Leel. It seems he still has something to discuss with me. I should talk to him."},
		["Talk to Akech-Chun 2"] =
			{appendText=" by the pool at the western entrance to Tainted Leel.", stepTextKey="Akech-Chun is now permanently bound to Tainted Leel. It seems he still has something to discuss with me. I should talk to him."},
	},



[GetQuestName(7247)] = { --"The Skull of Gandelec"		--aashiana
        [1] = 
            {appendStepText="Near a cave on the beach at the far northwest tip of Solstice, located northwest of Shor's Stand, the Sea Elf ", stepTextKey="Loraviel gave me a dampening orb that needs to be attuned to the necrotic energy in the cavern before I swap it with the skull. I should head into the caverns so Loraviel can perform the ritual."},
        ["Enter Carapace Cavern"] =
            {appendText=" through the entrance on the beach, covered with vines."},
        [2] = 
            {appendStepText="In Carapace Cavern on a northwestern beach in Solstice, ", stepTextKey="Loraviel plans to meet me in astral form at altars in the caverns. When I'm at an altar, I should hold out the dampening orb while she performs the attuning ritual."},
        ["Attune the Dampening Orb at Altars"] =
            {appendText=" \n\nEach one is protected by guardians in a blue ritual circle. The small stone altars are nearby.\n- The first altar is in the center of the northernmost tunnel.\n- The second altar is halfway down the easternmost tunnel in a flooded room, on a platform reached by a wooden ramp.\n- The final altar is up wooden ramps and stone steps along the easternmost tunnel to a small room in the southwest corner of the caves."},
        [3] = 
            {appendStepText="", stepTextKey="Now that the dampening orb is fully attuned to the necrotic energy of the caverns, I can remove the Skull of Gandelec and replace it with the attuned orb."},
        ["Find the Skull of Gandelec"] =
            {appendText=" by continuing around the cave complex to the west, back toward the entrance."},
        [4] = 
            {appendStepText="", stepTextKey="Now that the dampening orb is fully attuned to the necrotic energy of the caverns, I can remove the Skull of Gandelec and replace it with the attuned orb."},
        ["Take the Skull of Gandelec"] =
            {appendText=", in a small tiled passageway to the east, before you return to the cavern's entrance below. The skull is sitting on an altar similar to the others, glowing with necromantic energy."},
        [5] = 
            {appendStepText="", stepTextKey="I took the Skull of Gandelec. Now I should quickly put the attuned dampening orb in its place."},
        ["Place the Attuned Dampening Orb"] =
            {appendText=" on the altar."},
        [6] = 
            {appendStepText="In a small tiled passageway east and above the entrance to the cavern, ", stepTextKey="I successfully swapped the attuned dampening orb for the Skull of Gandelec. I should give it to Loraviel."},
        ["Return to Loraviel"] =
            {appendText=", outside on the beach."},
    },



[GetQuestName(7303)] = { --"Slime Pickings" 		--aashiana
        [1] = 
            {appendStepText="Along the beach on the far northwest coastline of Solstice, I found a note and a small jar of ... Sload Slime?? Apparently, someone actually wants this. ", stepTextKey="I should take the jar of Sload slime and bring it to Captain Genevé Delitian."},
        ["Gather Sload Slime"] =
            {appendText=", wiping your hands carefully. Now where to put it?"},
        [2] = 
            {appendStepText="To get rid of it as soon as possible, ", stepTextKey="I should take the jar of Sload slime to Captain Genevé Delitian."},
        ["Find Captain Genevé Delitian"] =
            {appendText=" in the nearest settlement, Shor's Stand, near the center of the western peninsula. She's having a drink to recover from the shipwreck, outside the Whale Splash Inn at a table with rope and floats."},
        [3] = 
            {appendStepText="Outside of the Whale Splash Inn in Shor's Stand, ", stepTextKey="I should take the jar of Sload slime to Captain Genevé Delitian."},
        ["Talk to Captain Genevé Delitian"] =
            {appendText=". It seems this is one of several ... valuables that they lost in the storm. She's very happy to see it!"},
    },


[GetQuestName(7305)] = { --"Striking the Deal"  		--aashiana
        [1] = 
            {appendStepText="In Shore's Stone, after returning her lost cargo, the Captain said ", stepTextKey="I should meet Captain Genevé Delitian and her client near the cathedral in Sunport."},
        ["Meet Captain Genevé Delitian"] =
            {appendText=", down the stairs from the Sunport Wayshrine, near a wooden caravan and some barrels. Her parents' client turned out to be a Daedra!"},
        [2] = 
            {appendStepText="Just down the stairs from the Sunport Wayshrine, near a wooden caravan and some barrels, ", stepTextKey="I should talk to Captain Genevé Delitian and help her resolve the deal."},
        ["Help Genevé Finish the Deal"] =
            {appendText=". I may want to talk with Xiamut first to understand his intentions."},
        [3] = 
            {appendStepText="Just down the steps from the Sunport Wayshrine, ", stepTextKey="Captain Genevé Delitian is going to renegotiate with the Skaafin for a better deal. I should talk to her one more time before she lets the Skaafin know."},
        ["Talk to Captain Genevé Delitian 1"] =
            {appendText=".", stepTextKey="Captain Genevé Delitian is going to renegotiate with the Skaafin for a better deal. I should talk to her one more time before she lets the Skaafin know."},
        [4] = 
            {appendStepText="Just down the stairs from the Sunport Wayshrine, ", stepTextKey="Genevé Delitian is going to reject the Skaafin's bargain. I should talk to her one more time before she tells him."},
        ["Talk to Captain Genevé Delitian 2"] =
            {appendText=".", stepTextKey="Genevé Delitian is going to reject the Skaafin's bargain. I should talk to her one more time before she tells him."},
        [5] = 
            {appendStepText="Just down the stairs from the Sunport Wayshrine, ", stepTextKey="Genevé Delitian is going to take the Skaafin's bargain. I should talk to her before she lets him know."},
        ["Talk to Captain Genevé Delitian 3"] =
            {appendText=".", stepTextKey="Genevé Delitian is going to take the Skaafin's bargain. I should talk to her before she lets him know."},
    },

[GetQuestName(7297)] = { --"The Stubbornness of Nords"   		--aashiana
		[1] = 
			{appendStepText="On the road outside Shor's Stand, in the central hills of the western peninsula in Solstice, ", stepTextKey="Ysmair asked me to find Britt the Bold in Shor's Stand main square."},
		["Go to Shor's Stand"] =
			{appendText=", where several villagers are having a heated discussion with Britt the Bold."},
		[2] = 
			{appendStepText="In Shor's Stand, in the central hills of the western peninsula of Solstice, ", stepTextKey="I found Britt being berated by some important-looking villagers. Something happened before I got here. I should talk to Britt to let her know that I'm here to help."},
		["Talk to Britt the Bold 1"] =
			{appendText=", standing dejected with her pack and some books by the central square.", stepTextKey="I found Britt being berated by some important-looking villagers. Something happened before I got here. I should talk to Britt to let her know that I'm here to help."},
		[3] = 
			{appendStepText="In Shor's Stand, on the western Peninsula in Solstice, ", stepTextKey="Speaker Hialf mentioned that we should talk to him if we really want to help the village. Britt thinks that this is the best way to get the village speakers to listen. She wants me to talk to Speaker Hialf."},
		["Talk to Speaker Hialf"] =
			{appendText=". Since Bear Hall is responsible for protecting the village, he is probably inside. Bear Hall is a large building at the north end of the square, decorated with giant fossil bones.\n\nSpeaker Hialf is sitting in a dining area to the left of the entrance. He is concerned about a large beast that has been terrorizing the villagers and wants our help dealing with that before he is willing to consider lending aid to defeat the Worm Cult."},
		[4] = 
			{appendStepText="In Shor's Stand, on the western peninsula of Solstice, ", stepTextKey="Britt said she would meet me to the east of the village to start hunting the beast. But Speaker Hialf mentioned that there were villagers who could tell me more about the beast if I wanted to get more information about what we're after."},
		["Meet Britt the Bold Outside the Village"] =
			{appendText=", after gathering more information. Two of the villagers, standing near a meat rack in front of Bear Hall, are talking about it.\n\nOn the eastern road, in a camp below the village, a Khajiit merchant has lost his magic cap. It's hard to imagine how, but could this be related?\n\nContinue down the hill and take a smaller path to the east, lit by burning torches. Britt is waiting by a burned area along the path."},
		[5] = 
			{appendStepText="The path lead me along a trail in the forest southeast of Shor's Stand, on the western peninsula of Solstice. ", stepTextKey="The beast's trail leads deeper into the woods. I should talk to Britt before we head in."},
		["Talk to Britt the Bold 2"] =
			{appendText=", standing by a burned area on the path.", stepTextKey="The beast's trail leads deeper into the woods. I should talk to Britt before we head in."},
		[6] = 
			{appendStepText="The path lead me along a trail in the forest southeast of Shor's Stand, on the western peninsula of Solstice. ", stepTextKey="The beast plaguing Shor's Stand is somewhere in these woods. There's a big path of destruction I can follow to get closer to the beast."},
		["Follow the Path of Destruction"] =
			{appendText=". I don't see any other patches of fire on this side of the rocks, so maybe I should check to see if the beast continued along this path. There may be more burned patches ahead. I should examine them."},
		[7] = 
			{appendStepText="The trail is to the east of Shor's Stand on the western peninsula of Solstice. ", stepTextKey="While on the beast's trail, Britt and I ran across an injured Nord. Talking to her might give us some more information about the beast or about what happened to her."},
		["Talk to the Injured Warrior"] =
			{appendText=", sitting by a tree along the trail. She seems all right for now, and does not want to go back to Shor's Stand without finding the beast. We should continue up the trail."},
		[8] = 
			{appendStepText="On the trail east of Shor's Stand, first we saw a monkey, then a sloth, in patches of fire with purple flames. Curiouser and curiouser. ", stepTextKey="The beast is somewhere up ahead. This is a great opportunity to catch the beast, but if we don't hurry we could lose it."},
		["Catch the Beast"] =
			{appendText=". It went into a cave up ahead. The trail of fire and purple flame leads right into a cave filled with geometric blue crystals. What other wonders lie within?"},
		[9] = 
			{appendStepText="I am deep in the cave at the end of a trail of fire through a forest east of Shor's Stand, in Western Solstice. ", stepTextKey="The beast turned out to be a sloth wearing a wizard's hat. Britt's distracting the sloth and keeping it calm, but she asked me to take the hat off of it."},
		["Take the Hat"] =
			{appendText=" from the sloth."},
		[10] = 
			{appendStepText="I am deep in the cave at the end of a trail of fire through a forest east of Shor's Stand, in Western Solstice. ", stepTextKey="We retrieved a magical hat from a sloth. It appears the hat's magic lost control when the creature found it. With the hat secured now, I should speak to Britt about our next steps."},
		["Talk to Britt the Bold 3"] =
			{appendText=".", stepTextKey="We retrieved a magical hat from a sloth. It appears the hat's magic lost control when the creature found it. With the hat secured now, I should speak to Britt about our next steps."},
		[11] = 
			{appendStepText="Our path lead us to the western peninsula of Solstice east of Shor's Stand. ", stepTextKey="The beast's reign of terror is over. I should go back to Speaker Hialf in the Bear Hall to let him know that the village is no longer in danger."},
		["Go to Shor's Stand Bear Hall"] =
			{appendText=", north of the town square, to give them the good news. Speaker Hialf is arguing with this daughter by the fire. I should talk to him."},
		[12] = 
			{appendStepText="Shor's Stand is on the western peninsula of Solstice. ", stepTextKey="The Bear Hall agreed to consider joining the Stirk Fellowship. Speaker Hialf mentioned that we should talk with Speaker Frogirde next. I should let Britt the Bold know that her plan worked."},
		["Talk to Britt the Bold 4"] =
			{appendText=", who has arrived in Bear Hall with the Khajiit merchant and the sloth.", stepTextKey="The Bear Hall agreed to consider joining the Stirk Fellowship. Speaker Hialf mentioned that we should talk with Speaker Frogirde next. I should let Britt the Bold know that her plan worked."},
		[13] = 
			{appendStepText="In Shor's Stand, on the western peninsula of Solstice, ", stepTextKey="I should go find Speaker Frogirde and talk to her to see why she doesn't want to join the Stirk Fellowship."},
		["Talk to Speaker Frogirde 1"] =
			{appendText=" within the Hall of Feathers, directly east of the Town Square, with a rooster out front and rugs airing out on the roof. She is standing by the fire, sharpening a knife.", stepTextKey="I should go find Speaker Frogirde and talk to her to see why she doesn't want to join the Stirk Fellowship."},
		[14] = 
			{appendStepText="In Shor's Stand's Hall of Feathers, ", stepTextKey="Speaker Frogirde doubts that the Stirk Fellowship will respect her village's culture. She wants Britt to prove that they're willing to learn about Shor's Stand's culture and suggested that I look around to find inspiration on how to do that."},
		["Learn about Shor's Stand's Culture"] =
			{appendText=". Speaker Frogirde suggested that I should read some books. There are several scattered around the hall, including a book near a rug by the fire, one on a table under the stairs, and a recipe on the dining table."},
		[15] = 
			{appendStepText="In the Hall of Feathers in Shor's Stand, on the western peninsula of Solstice, ", stepTextKey="I discovered some books about Shor's Stand. One of these will help Britt and I come up with a way to prove to Speaker Frogirde that we respect her culture. But which one? I should show them to Britt the Bold."},
		["Talk to Britt the Bold 5"] =
			{appendText=", waiting outside the Hall of Feathers.", stepTextKey="I discovered some books about Shor's Stand. One of these will help Britt and I come up with a way to prove to Speaker Frogirde that we respect her culture. But which one? I should show them to Britt the Bold."},
		[16] = 
			{appendStepText="In Shor's Stand on the western peninsula of Solstice, ", stepTextKey="I found a recipe for Together Stew in the Hall of Feathers. Britt's going to find some of the ingredients, but she wants me to find buzzer's treasure, spuds from the deep, and swimmer's scales around the village."},
		["Gather the Ingredients"] =
			{appendText=".\n\nBehind Wolf Hall on the south side of the village, there are some mead casks. Maybe the brewer can help me find some honey.\n\nTo the northwest, there is a farm that seems to have a ... coral crab infestation? Maybe I can help. Crouching can often help with following a trail. I should search carefully when I reach the end of it.\n\nTo the west of Shor's Stand, a fisherman on a dock near the lake can give you advice on how to obtain what you seek. He's already sitting by the best fishing hole."},
		[17] = 
			{appendStepText="In Shor's Stand, on the western peninsula of Solstice, ", stepTextKey="Britt said to meet her behind the Bear Hall after I found all the ingredients. I should go there to see what she has in mind."},
		["Meet Britt the Bold Behind the Bear Hall"] =
			{appendText=", where an outdoor cooking area awaits your culinary creation."},
		[18] = 
			{appendStepText="Behind Bear Hall in Shor's Stand, on the western peninsula of Solstice, ", stepTextKey="I found where Britt set up a cooking station. I should talk to her to see how her hunt for ingredients went."},
		["Talk to Britt the Bold 6"] =
			{appendText=", in a cook's apron, waiting to hear if I have all the ingredients for the Together Stew.", stepTextKey="I found where Britt set up a cooking station. I should talk to her to see how her hunt for ingredients went."},
		[19] = 
			{appendStepText="Behind Bear Hall in Shor's Stone, we need to make the Together Stew. ", stepTextKey="The recipe I found outlines what order to add the ingredients to create the feast. Britt wants to be the one to cook, but she needs me to tell her the order in which to cook everything. She trusts me to decipher the recipe."},
		["Cook the Feast"] =
			{appendText=". The recipe is lying on a box near the lamppost. Remember to add the ingredients in reverse order, according to the recipe."},
		[20] = 
			{appendStepText="", stepTextKey="Britt ran off to get ready for the feast. She asked me to take the stew we made to the village square."},
		["Take Stew"] =
			{appendText=" from the fire."},
		[21] = 
			{appendStepText="The cooking area is behind Bear Hall. ", stepTextKey="The feast is prepared. I should serve it to the speakers of Shor's Stand."},
		["Serve the Feast"] =
			{appendText=" to the speakers. They are assembled in front of the Whale Splash Inn, decorated with colored flags and giant bones of sea creatures. Place a bowl of the stew on each of the three tables nearest to the entrance to the Inn."},
		[22] = 
			{appendStepText="The meals are in front of the Whale Splash Inn in Shor's Stand. ", stepTextKey="The feast is served. The only way to find out if our efforts worked is to talk to Speaker Frogirde."},
		["Talk to Speaker Frogirde 2"] =
			{appendText=", seated just to the right of the entrance to the Whale Splash Inn. Be sure to read the book she gave you, on the seat across from her at the table.", stepTextKey="The feast is served. The only way to find out if our efforts worked is to talk to Speaker Frogirde."},
		[23] = 
			{appendStepText="Shor's Stand is on the western peninsula of Solstice. ", stepTextKey="There's one last speaker that Britt and I haven't spoken to yet. I should see if he'll talk to me and let me know why he doesn't like the idea of joining the Stirk Fellowship."},
		["Talk to Speaker Sogrard 1"] =
			{appendText=", sitting closest to the inn, just to the left of the door.", stepTextKey="There's one last speaker that Britt and I haven't spoken to yet. I should see if he'll talk to me and let me know why he doesn't like the idea of joining the Stirk Fellowship."},
		[24] = 
			{appendStepText="Standing near the stage at the center of the town square in Shor's Stand, on the western peninsula of Solstice, ", stepTextKey="Britt will want to know what Speaker Sogrard said about convincing the whole village to join the Fellowship."},
		["Talk to Britt the Bold 7"] =
			{appendText=" about the speech Speaker Sogrard wants her to give.", stepTextKey="Britt will want to know what Speaker Sogrard said about convincing the whole village to join the Fellowship."},
		[25] = 
			{appendStepText="At the gathering in front of the Whale Splash Inn in Shor's Stand, ", stepTextKey="Speaker Sogrard wants Britt to make a speech to convince the village to join the Stirk Fellowship. Britt asked for my help in learning more about the village's founding. I should talk to her when I know the whole story."},
		["Help Britt the Bold Prepare Her Speech"] =
			{appendText=" by reviewing the book Speaker Frogirde gave me and being prepared to silently prompt her if she forgets what to say."},
		[26] = 
			{appendStepText="The gathering is in front of the Whale Splash Inn in Shor's Stand. ", stepTextKey="It's time for Britt to give her speech. I should listen to it and help point out pieces of the story that she forgets."},
		["Aid Britt the Bold's Speech"] =
			{appendText=", whenever she falters."},
		[27] = 
			{appendStepText="The gathering is in front of the Whale Splash Inn in Shor's Stand. ", stepTextKey="The speech worked! Britt wants to talk to me again now that Speaker Sogrard said he needed some time to think. I should see what she wants."},
		["Talk to Britt the Bold 8"] =
			{appendText=", standing in front of the door to the Whale Splash Inn in Shor's Stand. She has a new plan to further convince Speaker Sogrard to join with the Fellowship.", stepTextKey="The speech worked! Britt wants to talk to me again now that Speaker Sogrard said he needed some time to think. I should see what she wants."},
		[28] = 
			{appendStepText="In Shor's Stand on the western peninsula of Solstice, ", stepTextKey="Britt plans to start a brawl in the Whale Splash Inn to let Speaker Sogrard express his frustration so he can admit that her speech was convincing. If I don't go into the inn after Britt, who knows how rowdy things will get."},
		["Go to the Whale Splash Inn"] =
			{appendText=" to see how this turns out. Britt may need your help to pull this off."},
		[29] = 
			{appendStepText="In the Whale Splash Inn, ", stepTextKey="Shor's Stand really knows how to throw a good tavern brawl. I can't leave Britt to face these villagers alone."},
		["Join the Brawl"] =
			{appendText=" and take on all comers - don't hold back!"},
		[30] = 
			{appendStepText="Outside the Whale Splash Inn in Shor's Stand, ", stepTextKey="Speaker Sogrard wants to talk to me now that the brawl has ended. He doesn't look like someone who likes to be kept waiting."},
		["Talk to Speaker Sogrard 2"] =
			{appendText=".", stepTextKey="Speaker Sogrard wants to talk to me now that the brawl has ended. He doesn't look like someone who likes to be kept waiting."},
		[31] = 
			{appendStepText="In Shor's Stand in front of the Whale Splash Inn, ", stepTextKey="Speaker Sogrard agreed. Britt and I managed to convince all the speakers to lend their support to the Stirk Fellowship. Britt will want to hear the good news herself."},
		["Talk to Britt the Bold 9"] =
			{appendText=", across from Speaker Sogrard.", stepTextKey="Speaker Sogrard agreed. Britt and I managed to convince all the speakers to lend their support to the Stirk Fellowship. Britt will want to hear the good news herself."},
		[32] = 
			{appendStepText="In the town square in Shor's Stand, ", stepTextKey="Britt's really excited by the news. Her assignment for the Nord Cultural Exchange was a success. I should talk to her again to see if she needs anything else."},
		["Talk to Britt the Bold 10"] =
			{appendText=" to receive your reward for helping convince the Nords of Shor's Stand to aid the Fellowship and make her mission a success.", stepTextKey="Britt's really excited by the news. Her assignment for the Nord Cultural Exchange was a success. I should talk to her again to see if she needs anything else."},
	},

[GetQuestName(7260)] = { --"Sunport Seeks Adventurers!"   --aashiana
        [1] = 
            {appendStepText="In Sunport, the capital city of Solstice, I found a poster requesting adventurers to sign up for \"dangerous undertakings.\" ", stepTextKey="I should speak with Korasephina in the city of Sunport for more details about these jobs."},
        ["Talk to Korasephina 1"] =
            {appendText=". She can be found near the southern entrance to Sunport, down the stairs and to the right from the central Sunport Wayshrine, in purple and white garb. She awaits near a table and board with job postings for new adventurers to answer her call.", stepTextKey="I should speak with Korasephina in the city of Sunport for more details about these jobs."},
        [2] = 
            {appendStepText="Near the south gates of Sunport, at a table with job postings on the board behind, ", stepTextKey="I should ask Korasephina how I can sign up for one of these daily jobs."},
        ["Talk to Korasephina 2"] =
            {appendText=" about the work available.", stepTextKey="I should ask Korasephina how I can sign up for one of these daily jobs."},
    },

[GetQuestName(7292)] = { --"Tides of the Heart"   --aashiana
		[1] = 
			{appendStepText="Keshu the Black Fin is trying to recruit Argonian warriors for the Stirk Fellowship at Shell-Tide Village, on the south coast of western Solstice near the central mountains. She has asked for my help. ", stepTextKey="I need to go to the hut in the center of the village and talk to Tide-Reader Suhath."},
		["Go to the Tide-Reader's Hut"] =
			{appendText=", a large, thatched structure on the southwest side of the village."},
		[2] = 
			{appendStepText="On the south coast of Western Solstice, ", stepTextKey="I need to go to the hut in the center of the village and talk to Tide-Reader Suhath."},
		["Talk to Tide-Reader Suhath 1"] =
			{appendText=" within the well-appointed hut. He and Keshu seem to be acquainted.", stepTextKey="I need to go to the hut in the center of the village and talk to Tide-Reader Suhath."},
		[3] = 
			{appendStepText="In the Tide-Reader's hut in Shell-Tide Village, on the south coast of Western Solstice are more clues. ", stepTextKey="The tide-reader instructed me to find two young villagers, Senik-Haas and Tlali-Haas. Keshu and I will help the egg-brothers complete their chukka-sei and cleanse the local waters of the necrotic taint."},
		["Talk to Senik-Haas 1"] =
			{appendText=", a young male Argonian with green skin, northeast of the village at the training grounds. He is enthusiastic about the Tide-Reader's plan.", stepTextKey="The tide-reader instructed me to find two young villagers, Senik-Haas and Tlali-Haas. Keshu and I will help the egg-brothers complete their chukka-sei and cleanse the local waters of the necrotic taint."},
		["Talk to Tlali-Haas 1"] =
			{appendText=", a young orange-skinned Argonian on the far shore east of the village, tending to the tainted egg hatchery.", stepTextKey="The tide-reader instructed me to find two young villagers, Senik-Haas and Tlali-Haas. Keshu and I will help the egg-brothers complete their chukka-sei and cleanse the local waters of the necrotic taint."},
		[4] = 
			{appendStepText="At the tainted egg hatchery east of the Shell-Tide Village, on the south coast of Western Solstice, ", stepTextKey="Tlali-Haas marked a location on my map for an archway just outside the village that indicates the entrance to their burial grounds. I was asked to meet them there to begin the first trial of their chukka-sei."},
		["Meet Senik and Tlali-Haas at the Burial Grounds"] =
			{appendText=", north of the village and east of the path leading north to the Shell-Tide Village Wayshrine. The group is gathered near an archway made of whale bones."},
		[5] = 
			{appendStepText="North of the Shell-Tide Village, near an archway made of whale bones, ", stepTextKey="I arrived at the entrance to Shell-Tide's burial grounds. I should speak with Keshu to learn about the first trial before we begin."},
		["Talk to Keshu the Black Fin 1"] =
			{appendText=", standing with the brothers.", stepTextKey="I arrived at the entrance to Shell-Tide's burial grounds. I should speak with Keshu to learn about the first trial before we begin."},
		[6] = 
			{appendStepText="Northeast of Shelltide Village my search continues. ", stepTextKey="The brothers must visit burial sites as part of their first trial. I must clear a safe path for the brothers so that they can pray at each site. I should also search for anything that might tell us what the cultists are doing here."},
		["Clear the Burial Sites"] =
			{appendText=" \n\nI must kill any Worm Cultists or other adversaries so that the brothers can complete their ritual safely. The burial grounds have low rock walls around burial stakes planted in the soil. The first burial ground is to the east, just beyond the whalebones. Look for additional sites to the northeast of the village. At the final burial site, at a large stone altar lit with blue flame, risen Argonians may attack us as we clear the site.\n"},
		["Investigate the Worm Cult's Presence"] =
			{appendText=" \n\nI should find any evidence I can that explains what the Worm Cultists are doing here. A small camp with iron gates, just past a second whalebone arch, contains a scroll near a blue glowing lamp. At a nearby burial ground, it looks like the Worm Cult was excavating skeletons. Further to the east, blue Worm Cult lanterns are lit near freshly dug graves. A camp just past the graves has what appear to be Argonian bodies on some kind of ritual altar."},
		[7] = 
			{appendStepText="Northeast of the Shell-Tide Village, near the wayshrine of the same name, ", stepTextKey="I helped the brothers successfully pray at each burial site. I should meet Keshu near the cliffs and speak with her about the next trial in the ritual."},
		["Find Keshu Near the Beach"] =
			{appendText="."},
		[8] = 
			{appendStepText="Northeast of the Shell-Tide Village, near the wayshrine of the same name, ", stepTextKey="I helped the brothers successfully pray at each burial site. I should meet Keshu near the cliffs and speak with her about the next trial in the ritual."},
		["Talk to Keshu"] =
			{appendText=", to the east of the final burial ground, on a rocky ledge overlooking the inlet below."},
		[9] = 
			{appendStepText="On a ledge east of the burial grounds, overlooking an inlet and island to the south, ", stepTextKey="Keshu asked that I find a fanik goc root for the next trial, a dream-wallow. And she also wants me to search a nearby Worm Cult camp for more clues as to their purpose here."},
		["Gather Fanik Goc Root"] =
			{appendText=", below the ledge and to the east, where a Worm Cult camp has been set up. The purple fanik goc roots can be found near palm trees surrounding the camp.\n"},
		["Search the Worm Cult Camp"] =
			{appendText=". In one of the tents by the water, there is a strange alchemical apparatus, with some papers or notes. I should read what it says and bring it back to Keshu."},
		[10] = 
			{appendStepText="After ransacking the Worm Cult camp northeast of an island along the south coast of Solstice, ", stepTextKey="I should meet the egg-brothers at the ritual site on the nearby islet now that I have the fanik goc root."},
		["Meet at the Ritual Site"] =
			{appendText=". Follow the inlet to the north of the island around to the west side, where the tainted hatcheries lie, then climb the path up to the center of the island. On a rocky ledge to the right of the path, Tlali-Haas is waiting for the fanik goc root to begin the Dream-Wallow."},
		[11] = 
			{appendStepText="In the center of the island east of Shell-Tide village, ", stepTextKey="I arrived at the dream-wallow ritual site. I should speak with Tlali-Haas and hand over the fanik goc root."},
		["Talk to Tlali-Haas 2"] =
			{appendText=" and give him the fanik goc root.", stepTextKey="I arrived at the dream-wallow ritual site. I should speak with Tlali-Haas and hand over the fanik goc root."},
		[12] = 
			{appendStepText="Keshu is at the center of the island east of Shell-Tide Village. ", stepTextKey="While Tlali-Haas prepares the dream-wallow ritual, I should check in with Keshu."},
		["Talk to Keshu the Black Fin 2"] =
			{appendText=", standing behind the brothers by the rock wall.", stepTextKey="While Tlali-Haas prepares the dream-wallow ritual, I should check in with Keshu."},
		[13] = 
			{appendStepText="At the center of the island east of Shell-Tide Village, ", stepTextKey="Keshu is going to remain at the ritual site to keep an eye on our unconscious bodies while I enter the dream-wallow to assist the brothers. I need to enter Senik-Haas' dream-wallow first."},
		["Enter the Dream with Senik-Haas"] =
			{appendText=" at the blue-flamed brazier in front of the brothers."},
		[14] = 
			{appendStepText="", stepTextKey="Inside this dream-wallow we encountered a dark version of Senik-Haas that joined the Worm Cult. I need to defeat this shadow version of Senik-Haas before continuing to the next dream."},
		["Explore the Dream 1"] =
			{appendText=" along the sandy spit with grave markers and ruined buildings. At the far end, I found a doorway leading to the center of the dream. I should see what lies beyond.", stepTextKey="Inside this dream-wallow we encountered a dark version of Senik-Haas that joined the Worm Cult. I need to defeat this shadow version of Senik-Haas before continuing to the next dream."},
		[15] = 
			{appendStepText="", stepTextKey="Inside this dream-wallow we encountered a dark version of Senik-Haas that joined the Worm Cult. I need to defeat this shadow version of Senik-Haas before continuing to the next dream."},
		["Defeat Dark Adept Senik-Haas"] =
			{appendText=", in a pool that appears to hold a tainted hatchery."},
		[16] = 
			{appendStepText="Within the Dream-Wallow the fight took place. ", stepTextKey="Now that the shadow version of Senik-Haas has been defeated, I can move on to the next dream."},
		["Enter the Dream with Tlali-Haas"] =
			{appendText=", through a portal on the far side of the pool."},
		[17] = 
			{appendStepText="I should go further into the Dream-Wallow. ", stepTextKey="Much like Senik-Haas, a dark version of Tlali-Haas has joined the Worm Cult. I must defeat this shadow version of Tlali-Haas so I can exit the dream-wallow."},
		["Explore the Dream 2"] =
			{appendText=", continuing down the stone stairs and walkways to the greenish tainted pools below, while listening to the inner struggles of Tlali-Hass. A stone doorway, north of the pools, leads to an area with more stone steps and pools below.", stepTextKey="Much like Senik-Haas, a dark version of Tlali-Haas has joined the Worm Cult. I must defeat this shadow version of Tlali-Haas so I can exit the dream-wallow."},
		[18] = 
			{appendStepText="", stepTextKey="Much like Senik-Haas, a dark version of Tlali-Haas has joined the Worm Cult. I must defeat this shadow version of Tlali-Haas so I can exit the dream-wallow."},
		["Defeat Dark Adept Tlali-Haas"] =
			{appendText=" in the murky brown pool below."},
		[19] = 
			{appendStepText="", stepTextKey="I helped the brothers complete the dream-wallow ritual. I should exit the dream and check on how they're doing."},
		["Exit the Dream-Wallow"] =
			{appendText=" through the portal beyond the final pool."},
		[20] = 
			{appendStepText="Back at the ritual site in the center of the island east of Shell-Tide Village, ", stepTextKey="Keshu mentioned Senik-Haas and Tlali-Haas look distressed following the dream-wallow. I should check on them and see how they're doing."},
		["Talk to Senik-Haas 2"] =
			{appendText=", standing at the corner of the structure with the stone pillars.\n", stepTextKey="Keshu mentioned Senik-Haas and Tlali-Haas look distressed following the dream-wallow. I should check on them and see how they're doing."},
		["Talk to Tlali-Haas 3"] =
			{appendText=", sitting nearby.", stepTextKey="Keshu mentioned Senik-Haas and Tlali-Haas look distressed following the dream-wallow. I should check on them and see how they're doing."},
		[21] = 
			{appendStepText="On the island east of the Shell-Tide Village, the brothers have completed the first ritual. ", stepTextKey="The final trial of the chukka-sei will take start on the southern shoreline below. I should meet Keshu and the egg-brothers there."},
		["Meet at the Southern Shores of Solstice"] =
			{appendText=", below the ritual site."},
		[22] = 
			{appendStepText="At the base of the island east of Shell-Tide Village, in the glowing water, ", stepTextKey="Keshu, the egg-brothers, and I gathered along the southern shore of Solstice. I should speak with Keshu and find out how we proceed to the final trial in the ritual."},
		["Talk to Keshu the Black Fin 3"] =
			{appendText=", standing in front of the brothers.", stepTextKey="Keshu, the egg-brothers, and I gathered along the southern shore of Solstice. I should speak with Keshu and find out how we proceed to the final trial in the ritual."},
		[23] = 
			{appendStepText="At the central southern shoreline of the island east of Shell-Tide Village, ", stepTextKey="Senik-Haas and Tlali-Haas dove into a whirlpool to reach a hidden tidal cavern, the location of the final trial. I should dive in and follow them."},
		["Dive into the Whirlpool"] =
			{appendText=" under the island, to the Shrine of Sithis."},
		[24] = 
			{appendStepText="At the Shrine of Sithis, below the island east of the Shell-Tide Village, ", stepTextKey="The Worm Cult is performing some sort of ritual in the tidal cave! I need to deal with the cultists and their leader so that the egg-brothers can complete the chukka-sei."},
		["Defeat the Worm Cult"] =
			{appendText=" and end the ritual."},
		[25] = 
			{appendStepText="Under the island east of the Shell-Tide Village, ", stepTextKey="I dealt with the Worm Cult and put an end to the ritual they were performing. Now I should enter the opening beyond the waterfall and reach the sacred shrine."},
		["Reach the Shrine"] =
			{appendText=", through the vine-covered passage under the waterfall. The Shrine of Sithis dominates the far side of the cavern beyond."},
		[26] = 
			{appendStepText="I have arrived at the cavern under the island east of the Shell-Tide Village. ", stepTextKey="Now that we reached the shrine, I should talk to Keshu and find out what I need to do here."},
		["Talk to Keshu the Black Fin 4"] =
			{appendText=", gazing up at the Shrine to Sithis, about the next step in the ritual.", stepTextKey="Now that we reached the shrine, I should talk to Keshu and find out what I need to do here."},
		[27] = 
			{appendStepText="In the cavern under the island east of Shell-Tide Village, ", stepTextKey="I should approach the shrine so we can all be acknowledged for having walked the path of the chukka-sei."},
		["Approach the Shrine to Sithis"] =
			{appendText="."},
		[28] = 
			{appendStepText="At the Shrine of Sithis, in the cavern under the island east of Shell-Tide Village, ", stepTextKey="Senik-Haas and Tlali-Haas have completed their chukka-sei, and the Worm Cult ritual responsible for the necrotic taint has been stopped. I should return to Shell-Tide Village and meet everyone at the hatchery."},
		["Return to the Hatchery"] =
			{appendText=" through a passage behind the Shrine of Sithis. I emerged on the beach southeast of the hatching grounds, which are visible to the southwest. I should head toward the red flaming altar in the hatching grounds and continue past it to the shoreline of the village, where everyone has gathered."},
		[29] = 
			{appendStepText="On the eastern shore of the village, ", stepTextKey="I arrived at the Shell-Tide hatchery. The tide-reader wants to speak with me. I should talk to him."},
		["Talk to Tide-Reader Suhath 2"] =
			{appendText=", at the center of the gathering.", stepTextKey="I arrived at the Shell-Tide hatchery. The tide-reader wants to speak with me. I should talk to him."},
		[30] = 
			{appendStepText="Our path lead us among the central shores of Solstice. ", stepTextKey="We stopped a Worm Cult ritual that was causing problems for Shell-Tide Village and helped two young warriors complete a rite of their own. Now I should talk to Keshu and make sure she's satisfied with the outcome."},
		["Talk to Keshu the Black Fin 5"] =
			{appendText=", standing to the other side of Tide-Reader Suhath.", stepTextKey="We stopped a Worm Cult ritual that was causing problems for Shell-Tide Village and helped two young warriors complete a rite of their own. Now I should talk to Keshu and make sure she's satisfied with the outcome."},
	},

[GetQuestName(7289)] = { --"To Know the Void"   --aashiana
        [1] = 
            {appendStepText="At his camp near Xul-Katama, Sahmazim said ", stepTextKey="I should enter the ruins of Xul-Katama to seek out the Vos-Toh stone tablets for Sahmazim."},
        ["Enter Xul-Katama, Monastery of the Death-Dancers"] =
            {appendText=", across two rope bridges, high above an inlet from the sea, and into the ancient Argonian ruins through the stone door.\n\nTake the broad path to the right of the entrance, lit by stone braziers. Follow the path along the outer wall north, then up some stone stairs and ahead through a hole in the stone wall, killing any Worm Cultists you see. Continue up some stone stairs, then turn right to enter the northwesternmost room. On the upper level of this room, past a triangular paved platform, one of the stone tablets leans against the stone by the brazier.\n\nContinue through the southern passageway to the next large room. On the south side of the central large structure, another tablet rests on a stone altar.\n\nLeave this room through the eastern passageway, go to the left and down the stairs to the large rectangular room. A stone tablet rests on an altar just past the central grove of palm trees."},
        [2] = 
            {appendStepText="On an island along the southwest coast of Eastern Solstice, in Xul-Katama, ", stepTextKey="I recovered the stone tablets. I should speak to Sahmazim and pass along the Vos-Toh stone tablets."},
        ["Talk to Sahmazim 1"] =
            {appendText=". Cross the two rope bridges and return to Sahmazim's camp to the left. He is waiting by the desk.", stepTextKey="I recovered the stone tablets. I should speak to Sahmazim and pass along the Vos-Toh stone tablets."},
        [3] = 
            {appendStepText="At his camp near Xul-Katama, ", stepTextKey="Sahmazim seems pleased I managed to save the Vos-Toh stone tablets from the Worm Cult. All that remains is to claim my reward. I should speak with him to claim it."},
        ["Talk to Sahmazim 2"] =
            {appendText=" to receive your reward... and learn more about the tablets' teachings regarding Sithis and the Void, if you are so inclined.", stepTextKey="Sahmazim seems pleased I managed to save the Vos-Toh stone tablets from the Worm Cult. All that remains is to claim my reward. I should speak with him to claim it."},
    },


[GetQuestName(7293)] = { --"A Traitor's Tyranny"    --aashiana
        [1] = 
            {appendStepText="", stepTextKey="Master Tanertor gave me a keystone to activate the lodge's portal gates, where he suspects the apprentices would gather. I can find them in the northeast, northwest, and southwest lodge. He also asks that I recover the relic from Lector Fenworine."},
        ["Activate Portal Gates"] =
            {appendText=" \n\nFrom the courtyard, head inside the large double doors. Once inside, head into the caverns south of the large central fountain. Continue all the way through this large cavern, into and through the southern library, and out into the caverns to the southwest. In the very back of this cavern, activate the portal gate between two pillars guarded by apprentices.\n\nContinue to the north through the cavern, up the stairs in front of you, jog to the right and then left up more stairs, to a lit brazier. The room to the east of the brazier contains the Staff of the Darkbinders.\n\nAfter retrieving the Staff, return up the stairs to the brazier and continue north down two sets of stairs to a hallway with a red rug and banner. Go up the stairs to the right, past an area with maps on the wall, to a circular room. Another portal is being guarded by apprentices to the east.\n\nReturn to the room with the maps and travel through the caverns to the east and then north. Just outside the cavern, take the corridor to the east. The final portal is at the south end of the balcony.\n"},
        ["Retrieve the Staff of the Darkbinders"] =
            {appendText=". It can be found on the east end of the central oval room, which can only be reached from the west side near a fiery brazier."},
        [2] = 
            {appendStepText="Within the College of Sea and Swords along the northern central mountains in Eastern Solstice, ", stepTextKey="I helped the apprentices escape through the portals and recovered the relic. Now to head outside and return it to Master Tanertor."},
        ["Talk to Master Tanertor"] =
            {appendText=". From the northeastern portal, the exit to the courtyard is across the balcony and down the stairs, south through the room below, further south to the central fountain, and out the central doors to the east. Master Tanertor is just past the fountain in the courtyard, talking with some of the apprentices."},
    },


[GetQuestName(7302)] = { --"Wealth from the Sea"    --aashiana
        [1] = 
            {appendStepText="About halfway down the eastern coastline of the large inlet outside Sunport, I found a crate that was lost at sea. ", stepTextKey="I should take the crate of dried snow truffles and bring them to Captain Genevé Delitian."},
        ["Gather the Crate of Truffles"] =
            {appendText="."},
        [2] = 
            {appendStepText="Along the eastern shoreline of the large inlet near Sunport, ", stepTextKey="I gathered the crate of snow truffles and should bring it to Captain Genevé Delitian. Her note said she would be staying at the inn of a Nord Village."},
        ["Find Captain Genevé Delitian"] =
            {appendText=" in Shor's Stand, in the center of the western peninsula of Solstice. Its wayshrine of the same name is just northeast of the village, at a crossroads. She's likely sitting at her usual spot outside the Whale Splash Inn in the town square, at a wooden table with ropes and buoys."},
        [3] = 
            {appendStepText="Along the eastern shoreline of the large inlet near Sunport, ", stepTextKey="I gathered the crate of snow truffles and should bring it to Captain Genevé Delitian. Her note said she would be staying at the inn of a Nord Village."},
        ["Talk to Captain Genevé Delitian"] =
            {appendText=" about the crate you found."},
    },



[GetQuestName(7393)] = { --"The Golden Knight"     --aashiana
		[1] = 
			{appendStepText="Outside Sunport Palace in Solstice, ", stepTextKey="Darien wants to search Gristmung Hold for information Mannimarco was collecting on the light he stole from Darien. I should head there with him to investigate."},
		["Investigate Gristmung Hold"] =
			{appendText=", east of the Grand Juncture Pass Wayshrine in Eastern Solstice. Since there are still Daedra there, we should enter the Hold from the cave in the ravine north of the iron bridge, as we did before.\n\nOnce in, we can head up the stairs to the platform above, go down the north stairs to the central courtyard, and cross it to the south stairs, killing any Daedra we find along the way.\n\nBack on the upper platform, we should make our way to the east, across the metal bridge and around to the doorway to the Central Keep we found before. This was the area in which they were doing research earlier, so it may have something useful."},
		[2] = 
			{appendStepText="The hold lies to the east of the Grand Juncture Pass Wayshrine in Eastern Solstice. ", stepTextKey="We located the library within Gristmung Hold. Now we need to search through it and see if we can uncover anything Mannimarco wrote about Darien or his stolen light."},
		["Search the Library"] =
			{appendText=" \n\nA note discarded hastily during the battle may provide a clue.\n\nSome Worm Cult still seem to be trying to perform a ritual in the small room off the library, using a strange gem within a skeleton. Should I touch it?\n"},
		[3] = 
			{appendStepText="There is a small room off the library in Gristmung Hold. ", stepTextKey="We discovered an echo stone with Mannimarco's memories on it. We should listen and see what we can learn."},
		["Observe Mannimarco's Vision"] =
			{appendText="."},
		[4] = 
			{appendStepText="In a small room off the library in Gristmung Hold, touching the gem caused a vision of Mannimarco to appear. Apparently, ", stepTextKey="Mannimarco knew more about Darien's light than we thought. Darien seems shaken up by some of the revelations. I should speak to him."},
		["Talk to Darien Gautier"] =
			{appendText="."},
		[5] = 
			{appendStepText="", stepTextKey="Our next stop is Broken Light Temple. Mannimarco mentioned Meridia's knight and Darien thinks they may have the answers he seeks. If we can find them anywhere, it would be at this temple to Meridia."},
		["Meet Darien at Broken Light Temple"] =
			{appendText=", on a small island northwest of Sunport in Solstice, on the path south of the Temple."},
		[6] = 
			{appendStepText="On a small island northwest of Sunport in Solstice, ", stepTextKey="I arrived at Broken Light Temple. I should find Darien and speak to him about our next move."},
		["Talk to Darien 1"] =
			{appendText=". He doesn't seem keen on going in there until I scout it first. I've agreed to go in and make sure there aren't any traps or obstacles lying in wait. Maybe he's just not sure Meridia's done with him yet.", stepTextKey="I arrived at Broken Light Temple. I should find Darien and speak to him about our next move."},
		[7] = 
			{appendStepText="On a small island northwest of Sunport in Solstice, I've reached Meridia's Temple. ", stepTextKey="Before we can continue into Broken Light, I need to figure out what's going on in there. I should look for anyone nearby that I might be able to assist."},
		["Resolve the Mysteries of the Broken Light Temple"] =
			{appendText=". I helped High Priest Eraamine restore the Broken Light Temple. Now, Darien and I can continue inside."},
		[8] = 
			{appendStepText="On a small island northwest of Sunport in Solstice, ", stepTextKey="I should meet Darien inside the Broken Light Temple and help him find the answers he seeks."},
		["Meet Darien Inside Broken Light Temple"] =
			{appendText=". From the top of a circular plaza to the south, I should cross the bridge that I repaired earlier to the entrance, then continue along the sandy path to the entrance hall. I can meet Darien by the doors to the Cynosure at the far end of the pool."},
		[9] = 
			{appendStepText="There is a small island northwest of Sunport in Solstice. ", stepTextKey="We entered the cynosure of Broken Light Temple. Aurorans appear to be waiting for us. We should approach cautiously to see what they want."},
		["Investigate the Temple Cynosure"] =
			{appendText="."},
		[10] = 
			{appendStepText="There is a small island northwest of Sunport, within the Cynosure Chamber of the Temple of Broken Light. ", stepTextKey="One of the leaders of the Aurorans wishes to speak to me, but Darien appears to be in pain. I need to figure out what the Auroran wants."},
		["Talk to Lortharil the Radiant"] =
			{appendText=", standing in the center of the beams of light."},
		[11] = 
			{appendStepText="", stepTextKey="Lortharil wants to take Darien's light back—a light we thought was gone. The Aurorans won't stop until they get what they were sent for, so I need to find a way to stop them."},
		["Stop Lortharil the Radiant"] =
			{appendText=", but how?"},
		[12] = 
			{appendStepText="There is a small island northwest of Sunport, within the Cynosure Chamber of the Temple of Broken Light. ", stepTextKey="The light inside Darien is overpowering him. Memories that aren't his are threatening to take him over. If I can't find a way to remind him of who he is, who knows what will happen."},
		["Save Darien Gautier"] =
			{appendText=" by helping him remember what matters and who he really is."},
		[13] = 
			{appendStepText="Within the Cynosure Chamber of the Temple of Broken Light, ", stepTextKey="I managed to pull Darien back through the memories of our adventures and he was able to push whatever it was inside him back. For now. I need to find Vanus in Sunport and speak to him about this."},
		["Find Vanus in Sunport 1"] =
			{appendText=". Darien thinks Vanus may be able to help sort out the conflicting memories inhabiting his soul."}, 
		["Talk to Vanus"] =
			{appendText=", waiting in a peaceful garden terrace to the right of the Palace entrance.", stepTextKey="I managed to pull Darien back through the memories of our adventures and he was able to push whatever it was inside him back. For now. I need to find Vanus in Sunport and speak to him about this."},
		[14] = 
			{appendStepText="Within the Cynosure Chamber of the Temple of Broken Light, ", stepTextKey="I couldn't snap Darien out of his trance, but Vanus and Skordo showed up and helped. I need to find Vanus in Sunport and figure out what's going on."},
		["Find Vanus in Sunport 2"]=
			{appendText=". Darien thinks Vanus may be able to help sort out the conflicting memories inhabiting his soul.", stepTextKey="I couldn't snap Darien out of his trance, but Vanus and Skordo showed up and helped. I need to find Vanus in Sunport and figure out what's going on."}, 
		["Return to Sunport"]=
			{appendText=". Talk to Vanus, waiting in a peaceful garden terrace to the right of the Palace entrance."}, 
		[15] = 
			{appendStepText="In Sunport, ", stepTextKey="Darien's waiting for me in the tavern. I should find him and finally have that drink he's been promising me."},
		["Find Darien in the Tavern"] =
			{appendText=" called the Sleepy Sloth Inn and Pub, just inside the western entrance to Sunport, up the stairs to the south. He is reminiscing with Skordo at a table by the fire in a ground floor room to the right of the entrance."},
		["Talk to Darien 2"] =
			{appendText="", stepTextKey="Darien's waiting for me in the tavern. I should find him and finally have that drink he's been promising me."},
		[16] = 
			{appendStepText="In Sunport, in the Sleepy Sloth Inn and Pub, ", stepTextKey="I confessed how I felt to Darien and woke up in a strange house with him. I should see what he's doing and speak to him about all of … this."},
		["Talk to Darien 3"] =
			{appendText=", sitting by the fire.", stepTextKey="I confessed how I felt to Darien and woke up in a strange house with him. I should see what he's doing and speak to him about all of … this."},
		[17] =
			{appendStepText="", stepTextKey="Vanus has given me a warning about Darien's potential power. I need to find him down near the docks and speak to him before he leaves."},
		["Talk to Darien 4"]=
			{appendText=" standing by a large ship at the end of the Sunport Docks.", stepTextKey="Vanus has given me a warning about Darien's potential power. I need to find him down near the docks and speak to him before he leaves."},
	},



[GetQuestName(7390)] = { --"Death Hound's Devotion"     --aashiana
        [1] = 
            {appendStepText="On a point of land southeast of the large island in the north-central bay of Eastern Solstice, a vampire hunter told me her death hound has gone missing. ", stepTextKey="Carminia gave me vial of her blood that will lead Bloodmite back to her once he sniffs it. She last saw him heading north toward the Ashbound Halls. I should head there."},
        ["Find Bloodmite"] =
            {appendText=", southwest along the northern road, near the Worm Cult Lair."},
        [2] = 
            {appendStepText="On the north-central road in Eastern Solstice, near the Worm Cult Lair, ", stepTextKey="Bloodmite is surrounded by death hounds and looks like he's in trouble. I may need to fight them off before I can pour the blood vial for him to sniff."},
        ["Pour Blood Vial for Bloodmite"] =
            {appendText=" on the ground."},
        [3] = 
            {appendStepText="On the north-central road in Eastern Solstice, near the Worm Cult Lair, ", stepTextKey="I poured the blood vial for Bloodmite to sniff and he ran off. I should check to see if he returned to Carminia and ask her about my reward."},
        ["Talk to Carminia"] =
            {appendText=", on the point of land to the northeast along the coast, in a grove of palm trees."},
    },

-- 		=========================================================================
--		  DAILY QUESTS SOLSTICE
-- 		=========================================================================

[GetQuestName(7263)] = { --"Candleflies for the Dead"      --aashiana
        [1] = 
            {appendStepText="I need to release candleflies to honor the Argonian dead. ", stepTextKey="I should go to Tainted Leel."},
        ["Go To Tainted Leel"] =
            {appendText=". This offshore island can only be reached by boat. A small boat has been moored along the shoreline for infrequent visitors to use, on the southwestern beaches of the western peninsula, near the mouth of the the large central bay."},
        [2] = 
            {appendStepText="To honor the fallen, ", stepTextKey="I should release candleflies within Tainted Leel."},
        ["Release Candleflies"] =
            {appendText=" \n\nTravel from the subterranean cavern up to the outdoor ruins. Head south along the ruins until you find an area with wheat crops. Release candleflies between the two rows of wheat furthest back.\n\nContinue around the ruins to the westernmost point near the water. Wheat crops grow near a stone fountain set into the side of the ruins. Release candleflies within the wheat on either side of the fountain.\n\nGo up the stone stairs to the north, and then another flight of stairs to an upper platform. At the north end of the platform, look for an entrance into the xanmeer lit by two braziers with blue flames. Down the stairs is another area with wheat crops. From the entrance to this room, release the candleflies by the crops just to your right, in the far back right, or to the center left."},
        [3] = 
            {appendStepText="Off the southwest coast of Solstice, in and around the xanmeer, ", stepTextKey="I released the candleflies in Tainted Leel to honor the traditions of the fallen Argonians. I should return to Lector Volonaro for my reward."},
        ["Talk to Lector Volonaro"] =
            {appendText=" in Cathedral Square in Sunport. He is standing by a pillar near a billboard with daily jobs for hire, near the southern gate to the city."},
    },



[GetQuestName(7264)] = { --"Gaulm's Lair"             --aashiana
        [1] = 
            {appendStepText="On the road leading west from Sunport, ruins with tall pillars can be seen to the south, on a large peninsula along the Great Bay, east of the Western Bay Wayshrine. ", stepTextKey="I need to burn the caustic voriplasms infesting the ruins of Tuniria and defeat Gaulm the vahath behemoth."},
        ["Defeat Gaulm"] =
            {appendText=", defending against all comers in the center of the ruins."},
        ["Burn Caustic Voriplasms"] =
            {appendText=" \n\nThe voriplasms glow a sickly bright green.\n- One is inside the arena, near a totem on the west side.\n- One is outside, on a stone pillar on the northeast side.\n- One is on the outside of a stone wall, at the eastern entrance to the arena."},
        [2] = 
            {appendStepText="At the Ruins of Tuniria, west of Sunport on a peninsula on the north side of the Great Bay, ", stepTextKey="I defeated Gaulm the vahath behemoth and cleansed the ruins of voriplasms. I should return to Morlia to claim my reward."},
        ["Talk to Morlia"] =
            {appendText=" in Cathedral Square in Sunport. She is standing by a desk in front of a billboard with daily jobs for hire, near the southern gate to the city."},
    },


[GetQuestName(7265)] = { --"Guardians Gone Bad"               --aashiana
        [1] = 
            {appendStepText="In the north-central peninsula of Western Solstice, ", stepTextKey="I need to find the altars in the ruins of Vakkan Cape, return the stolen relics, and defeat any voskrona guardians I meet."},
        ["Defeat the Voskrona Guardians"] =
            {appendText=", hostile to all who enter, even when we bring the relics that have been stolen back to their care."},
        ["Return Argonian Relics"] =
            {appendText=" \n\nPlace the relics on the rectangular Argonian altars in the four corners of the ruin, and perhaps the Guardians will know peace, however temporary."},
        [2] = 
            {appendStepText="In the north-central peninsula of Western Solstice, ", stepTextKey="I returned the stolen relics and defeated the voskrona guardians. I should return to Morlia and claim my reward."},
        ["Talk to Morlia"] =
            {appendText=" in Cathedral Square in Sunport. She is standing by a desk in front of a billboard with daily jobs for hire, near the southern gate to the city."},
    },



[GetQuestName(7262)] = { --"Sanguine's Solace"    --aashiana
        [1] = 
            {appendStepText="In south-central Solstice, southwest of the Shell-Tide Village Wayshrine, a strange circular tent has been erected, showing signs of devotion to debauchery. To discover what unknown pleasures it may hold, ", stepTextKey="I should enter the Vale of Revelry."},
        ["Enter Vale of Revelry"] =
            {appendText=" inside the tent, which is much larger than it appears."},
        [2] = 
            {appendStepText="To add to Lector Volonaro's unusual botanical collection, ", stepTextKey="I should gather specimens of Sanguine's solace."},
        ["Gather Sanguine's Solace"] =
            {appendText=" \n\nThe plants are located only in certain areas of Sanguine's Solace, although their reasons for choosing these particular places to grow are unknown. \n\nOne of these deep pink flowers, emitting an unusual dark red mist, grows by a tree on a hill east of the entrance. Continuing along the circular path, more of these flowers grow near a clearing to the southeast, where a camp has been set up for the revelers. Follow the path all the way around to a bridge crossing a stream, where more specimens grow."},
        [3] = 
            {appendStepText="This seems like a place one could spend a lot of time in... But, ", stepTextKey="I gathered enough specimens of Sanguine's solace from the Vale of Revelry. I should return to Lector Volonaro for my reward."},
        ["Talk to Lector Volonaro"] =
            {appendText=" in Cathedral Square in Sunport. He is standing by a pillar near a billboard with daily jobs for hire, near the southern gate to the city."},
    },


[GetQuestName(7261)] = { --"Save the Ruins!"                  --aashiana
        [1] = 
            {appendStepText="Northwest and across the bay from Sunport, remnants of ancient ruins watch over the bay from high atop a rocky cliff. A dock and circular pavilion are to the north below the ruins if traveling by water. By land, there is a main road that goes up to the northeast tip of the western peninsula. \n\nOnce there, ", stepTextKey="I should place the alchemical deterrents in the area around Bay Forest's ruins."},
        ["Place Alchemical Deterrents"] =
            {appendText=" \n\nThere are many possible places to put them to keep the wildlife away, but just choose what looks best to you.\n\n- One could go in the southern building that the researchers use as a base camp. Maybe near the book filled with notes to keep it safe.\n\n- One could be left on the flat stone table with a large pot.\n\n- There are some shallow steps leading to the top of the cliff to the east. This might work.\n\n- An old pillar at the northwest corner of the camp looks important. There is a gray rock with a flat top near it that might work.\n\n- Along the west side, a corner of a wall is preserved with scaffolding. A deterrent could be placed in the corner."},
        [2] = 
            {appendStepText="In the ruins across the bay from Sunport in Western Solstice, ", stepTextKey="I placed the alchemical deterrents around the ruins in Sunport's Bay Forest. I should return to Lector Volonaro to claim my payment."},
        ["Talk to Lector Volonaro"] =
            {appendText=" in Cathedral Square in Sunport. He is standing by a pillar near a billboard with daily jobs for hire, near the southern gate to the city."},
    },

[GetQuestName(7266)] = { --"Tidewash Stranded"                --aashiana
        [1] = 
            {appendStepText="In a large cove with many small pools on the southwest coast of Western Solstice, with a huge skeleton on one side and a shipwreck on the other, ", stepTextKey="I need to find Tidespite on Tidewash Strand and rescue the stranded salvage crew."},
        ["Defeat Tidespite"] =
            {appendText=" and his many minions. "},
        ["Rescue Salvage Crew"] =
            {appendText=" \n\nThey are being menaced by dangerous coral crabs! \n- One is cowering by a large shell just west of the cove.\n- Another is on a sandy beach just before the shipwrecks.\n- The third is on the other side of the cove, near the head of the huge skeleton."},
        [2] = 
            {appendStepText="In Tidewash Strand, a cove in southwest Solstice, ", stepTextKey="I defeated Tidespite and rescued the remaining salvage crew from Tidewash Strand. I should report back to Morlia and collect my reward."},
        ["Talk to Morlia"] =
            {appendText=" in Cathedral Square in Sunport. She is standing by a desk in front of a billboard with daily jobs for hire, near the southern gate to the city."},
    },


[GetQuestName(7270)] = { --"Ghishzor's Ritual"  --aashiana
        [1] = 
            {appendStepText="", stepTextKey="I can find Ghishzor at the ritual site of Zyv-Elehk in eastern Solstice. I need to reach the site, defeat the Daedra, and extinguish the ritual fires."},
        ["Defeat Ghishzor"] =
            {appendText=", in the far northeastern reaches of Eastern Solstice. Follow the road heading north from the Mor Naril Camp Wayshrine. Turn left at the fork in the road near the Stirk Fellowship camp, then head into the daedric lands to the northwest. The main entrance to the ritual site is on the west side of the huge circular daedric arena."},
        ["Extinguish Ritual Fires"] =
            {appendText=", burning with occult blue flames at three corners of the arena."},
        [2] = 
            {appendStepText="", stepTextKey="I extinguished the ritual fires and defeated Ghishzor. I should return to Morlia and collect my reward."},
        ["Talk to Morlia"] =
            {appendText=" in Cathedral Square in Sunport. She is standing by a desk in front of a billboard with daily jobs for hire, near the southern gate to the city."},
    },

[GetQuestName(7271)] = { --"Soulcaller's Curse"   --aashiana

        [1] = 
            {appendStepText="In southeast Solstice, just northeast of the Stone Cove Wayshrine, ", stepTextKey="I should find the ancient Argonian site, defeat Soulcaller, and retrieve the stone tablets."},
        ["Defeat Soulcaller"] =
            {appendText=", a powerful voidmother, who has chosen this site of ritual power as her home."},
        ["Retrieve Ancient Tablets"] =
            {appendText=" \n\nThe tablets are buried in rubble near stone walls surrounding the ritual site."},
        [2] = 
            {appendStepText="In southeast Solstice, at her ritual site in the Daedric hills, ", stepTextKey="I defeated Soulcaller and retrieved the ancient tablets from the site she haunted. I should return to Morlia and turn them in."},
        ["Talk to Morlia"] =
            {appendText=" in Cathedral Square in Sunport. She is standing by a desk in front of a billboard with daily jobs for hire, near the southern gate to the city."},
    },

[GetQuestName(7272)] = { --"Wo-Xeeth's Wrath"      --aashiana

        [1] = 
            {appendStepText="Near the central northern coast of Solstice, just southeast of the Caterwaul Cove Wayshrine, ", stepTextKey="I need to find the lair of Wo-Xeeth, defeat the behemoth, and retrieve the Corelanya relics left there."},
        ["Defeat Wo-Xeeth"] =
            {appendText=" and his minions of fire and ice."},
        ["Recover Corelanya Relics"] =
            {appendText=" \n\nLook for the relics in ancient ruins and rubble around the muddy arena, where torches light the ancient bones of Corelanya skeletons."},
        [2] = 
            {appendStepText="", stepTextKey="I defeated Wo-Xeeth and recovered the Corelanya relics. I should report back to Morlia and collect my reward."},
        ["Talk to Morlia"] =
            {appendText=" in Cathedral Square in Sunport. She is standing by a desk in front of a billboard with daily jobs for hire, near the southern gate to the city."},
    },

[GetQuestName(7268)] = { --"Black Worm Relics"      --aashiana
        [1] = 
            {appendStepText="Along the north-central coast of Eastern Solstice, south of a small island in the center of the bay, ", stepTextKey="I should enter the Lair of the Black Worm."},
        ["Enter Lair of the Black Worm"] =
            {appendText=", by traveling across the pass north of Sunport to Eastern Solstice, or use the Caterwaul Cove Wayshrine to reach the northern shoreline. Along the north-central road, look for a trail off to the north between two large Daedric rock formations. The trail leads down the cave entrance."},
        [2] = 
            {appendStepText="Inside the cave is an old stone-nest village, lost to time, and recently invaded by the Worm Cult. ", stepTextKey="I should explore the cave and gather Worm Cult relics."},
        ["Gather Worm Cult Relics"] =
            {appendText=" \n\n- Follow the path ahead, down one set of stairs and up another. At the top of the stairs, a strange plaque rests on the left-hand pillar.\n\n- Follow the path along the edge of the ruins to the north-central building, then turn south past a Daedric altar and workshop. At the bottom of the first flight of stairs, in a corner to the right covered with leaves, a glowing skull sits on a ledge.\n\n- Go back up the stairs and continue along the outer path up and down stone staircases and wooden ramps, until you reach an area that appears inhabited along the western side, with purple trees. Near the last tree, a dark orb sits in a spiked stand."},
        [3] = 
            {appendStepText="Continue exploring around the outer edge of the ruins to the cave entrance, or return to the Sunport wayshrine. ", stepTextKey="I braved the Lair of the Black Worm and gathered Worm Cult relics. I should return to Lector Volonaro."},
        ["Talk to Lector Volanaro"] =
            {appendText=" in Cathedral Square in Sunport. He is standing by a pillar near a billboard with daily jobs for hire, near the southern gate to the city."},
    },

[GetQuestName(7269)] = { --"Fragments of Fear"                  --aashiana
        [1] = 
            {appendStepText="North along the mountains from the Grand Juncture Pass Wayshrine in Eastern Solstice lies the training facility of the College of Sea and Sword, with architecture reminiscent of Sunport.\n\n", stepTextKey="I should enter the Sea and Sword Lodge."},
        ["Enter the Sea and Sword Lodge"] =
            {appendText=", recently invaded by Worm Cultists."},
        [2] = 
            {appendStepText="To protect those who train here and the irreplacable artifacts and books stored within, ", stepTextKey="I should destroy the anchor fragments."},
        ["Destroy Anchor Fragments"] =
            {appendText=" \n\nThe fragments, giving off a blue flame, can be found to the south in the great library, to the east where marble pathways are shattered and have fallen into the flooded corridors below, and to the north, where a Daedric portal and chains lie in a cavern in the heart of the Lodge."},
        [3] = 
            {appendStepText="In Eastern Solstice, north of the Grand Juncture Pass Wayshrine, ", stepTextKey="I dealt with the anchor fragments inside the Sea and Sword Lodge. I should return to Lector Volonaro for my payment."},
        ["Talk to Lector Volanaro"] =
            {appendText=" in Cathedral Square in Sunport. He is standing by a pillar near a billboard with daily jobs for hire, near the southern gate to the city."},
    },

[GetQuestName(7267)] = { --"Samples Needed"                 --aashiana
        [1] = 
            {appendStepText="Southeast of the Caterwaul Cove Wayshrine in Eastern Solstice, ", stepTextKey="I should gather samples of letifer orca using Lector Volonaro's sample kit. He marked an area along the eastern crags of Solstice where I can find this planta growing."},
        ["Gather Samples of Letifer Orca"] =
            {appendText=" \n\nI can find them in the daedric lands, at a low point in the road with lakes on both sides. This purplish-red orchid-like plant grows on the hillsides near these lakes. Its flat, star-shaped leaves may provide stability for its large, bulbous head."},
        [2] = 
            {appendStepText="In central Solstice, ", stepTextKey="I gathered samples of the letifer orca growing along the eastern crags. I should return to Lector Volonaro for my reward."},
        ["Talk to Lector Volonaro"] =
            {appendText=" in Cathedral Square in Sunport. He is standing by a pillar near a billboard with daily jobs for hire, near the southern gate to the city."},
    },

[GetQuestName(7275)] = { --"Protecting the Besieged" --aashiana
        [1] = 
            {appendStepText="At the Rampart Camp, near the Rampart Camp Wayshrine south of Sunport in Solstice, the Stirk Fellowship continues its battle against the invading Worm Cult forces. Near a large white tent next to the woodworking station, General Zasimba is coordinating the defense. Look for a Khajiit with green and gold armor to receive her orders. ", stepTextKey="I should help patrol and defend a Stirk Fellowship siege camp along the Writhing Wall."},
        ["Defend a Siege Camp"] =
            {appendText=" along the Writhing Wall. There are two camps north of Sunport, one camp immediately east of this platform, and two more camps to the southeast. Once I explore each camp and make note of where they are on my map, I will be able to see where the Worm Cult is attacking by checking my map.\n\nDaedric forces will attempt to set up Soul Reapers at various points along the perimeter of the camp. Kill the Daedra and destroy the Soul Reapers before they can invade the camp. Powerful bosses are likely to arrive toward the end of the fight in the center of the camp itself, so be sure to join up with companions for these fights. Siege camp commanders offer rewards after each fight for your help, in a golden chest within the camp."},
        [2] = 
            {appendStepText="In Solstice, ", stepTextKey="I helped defend a Stirk Fellowship siege camp as requested. I should talk to General Zasimba to claim my reward."},
        ["Talk to General Zasimba"] =
            {appendText=", at the Rampart Camp south of Sunport, standing by some barrels at the white tent near the woodworking station."},
    },

