		[GetQuestName(4107)] = { -- "Banishing the Banished"		-- OneSkyGod
			["Find the First Keeper"] =
				{appendText=". Keeper Cirion may hold the secret to their whereabouts."},
			["Find Keeper Areldur"] =
				{appendText=" in the eastern reaches of the dungeon."},
			["Find the Second Keeper"] =
				{appendText=". Keeper Cirion may possess knowledge on them in the the eastern reaches of the dungeon."},
			["Find Keeper Voranil"] =
				{appendText=" in a chamber that can be found by always keeping to the left, from the dungeon’s entrance onwards."},
			["Find the Third Keeper"] =
				{appendText=". Keeper Cirion may possess knowledge about them in a chamber that can be found by always keeping to the left, from the dungeon’s entrance onwards."},
			["Find Keeper Imiril"] =
				{appendText=" in the fathom depths of the abyssal dungeon."},
			["Speak with Keeper Cirion"] =
				{appendText=" in the northmost depths of the abyssal dungeon."},
			["Search for Rilis' Binding Stone Prison"] =
				{appendText=" by delving deep into the abyssal dungeon's farthest reaches."},
			["Kill the Daedra around Rilis' Binding Stone Prison"] =
				{appendText=" deep within the abyssal dungeon's farthest reaches."},
			["Kill High Kinlord Rilis"] =
				{appendText=" in farthest reaches of the abyssal dungeon."},
			["Wait for the Keepers to Bind High Kinlord Rilis"] =
				{appendText=" in the last chamber where Oblivion begins to reveal itself."},
			["Talk to Keeper Cirion"] =
				{appendText=" in the last chamber where Oblivion begins to reveal itself."},
		},
		[GetQuestName(4597)] = { -- "The Plan"						-- OneSkyGod
			["Deactivate the First Binding Stone"] =
				{appendText=""},
			["Deactivate the Second Binding Stone"] =
				{appendText=""},
			["Deactivate the Third Binding Stone"] =
				{appendText=""},
			["Talk to Keeper Cirion"] =
				{appendText=" in the last chamber where Oblivion begins to reveal itself."},
			["Use the Final Binding Stone"] =
				{appendText=" in the last chamber where Oblivion begins to reveal itself."},
			["Kill High Kinlord Rilis"] =
				{appendText=""},
			["Check Cirion for Signs of Life"] =
				{appendText=" in the last chamber where Oblivion begins to reveal itself."},
		},
		[GetQuestName(4054)] = { -- "Deadly Whispers"				-- OneSkyGod	-- Spindleclutch
			["Clear the First Cave"] =
				{appendText=" by venturing into the dark depths of the cavern and face the dreadful arachnid that dwells there. You have heard fearful whispers from the trembling entourage that it is this beast that spins the silken threads that cover all you see."},
			["Clear the Second Cave"] =
				{appendText=".\nOne of the companions whispered in your ear:\nThere's something you need to know. Down this cave, there's a gate that no one can open, and a spider watches from the darkness. It came out of nowhere and took one of us last time."},
			["Clear the Third Cave"] =
				{appendText=" by venturing deeper into the arachnid-infested grotto."},
			["Silence the Whispers"] =
				{appendText=".\n\nAs I continue to descend deeper into the arachnid-infested grotto, the sound of the scurrying arachnids grows louder and louder, gradually overwhelming my senses. \nThe sound slowly begins to fade away, replaced by a soft whispering voice that gradually becomes more prominent the deeper I go into the cavern."},
			["Talk to Guardian Sud-Hareem"] =
				{appendText=" at the furthest end of the cave."},
		},
		[GetQuestName(3993)] = { -- "Kings of the Grotto"			-- OneSkyGod	-- Fungal Grotto
			["Kill the Goblin War Chief"] =
				{appendText=", in the depths of the underground grotto. It's a goblin brute with bulging muscles and a fierce scowl who surveys the largest cavern from atop with a predatory glare. The air is thick with the stench of his power, and his minions cower in fear at his very presence. With a voice like gravel, he rallies his horde, goading them into a frenzied battle rage with promises of glory and plunder."},
			["Mount the Head on a Spike"] =
				{appendText=".\nThis will make the onlooking goblins, who gather in the largest cavern, fear you."},
			["Lead the Goblins against the Dreugh"] =
				{appendText=" deeper into the grotto."},
			["Defeat the Dreugh King"] =
				{appendText=" at the endmost cavern of the grotto."},
			["Talk to Vila Theran by the Shrine Entrance"] =
				{appendText=", at the top of the hill in the endmost cavern in the grotto."},
		},
		

-- ==================================================================================================================================================
--	Scribing																															Scribing
-- ==================================================================================================================================================
	[GetQuestName(7104)] = { -- "The Second Era of Scribing"		-- Cyberjanet
		["Talk to Adept Irnard"] =
			{appendText=" near a Mages Guild at Skingrad in West Weald, Mournhold in Deshaan, Stormhaven in Wayrest, or Elden Root in Grahtwood. He is wearing a teal suit, and waves to catch your attention."},
		["Find Votary Nahlia"] =
			{appendText=". Adept Irnard's portal is near the Mages Guild at Skingrad in West Weald, Mournhold in Deshaan, Stormhaven in Wayrest, or Elden Root in Grahtwood. It seems opening one opens them all, isn't that magic?"},
		["Enter the Sunnamere Study"] =
			{appendText=" through the door at the bottom of the stairs. The portal entrance between Sunnamere and the Mages Guilds at Skingrad in West Weald, Mournhold in Deshaan, Stormhaven in Wayrest, or Elden Root in Grahtwood will remain open while you investigate here."},
		["Talk to Votary Nahlia 1"] =
			{appendText=" waiting by the door of the Sunnamere study. The portal in the corridor outside the study will take you back to the Mages Guild at Skingrad in West Weald, Mournhold in Deshaan, Stormhaven in Wayrest, or Elden Root in Grahtwood, should you have second thoughts or need something you forgot.", stepTextKey="The unstable magic is a portal at the far end of the study. I need to speak to Votary Nahlia to find out what this is all about."},
		["Investigate the Anomalies"] =
			{appendText=" inside the Sunnamere study. Look for notes... and what is that shimmering figure? The portal in the outside corridor, leading back to the Mages Guilds at Skingrad in West Weald, Mournhold in Deshaan, Elden Root in Grahtwood, or Wayrest in Stormhaven will stay open while you look around."},
		["Enter the Portal"] =
			{appendText=" at the far end of the study, the one that leads to an unknown distant place. Not the one in the corridor outside that takes you back to the Mages Guild at Skingrad in West Weald, Mournhold in Deshaan, Stormhaven in Wayrest, or Elden Root in Grahtwood."},
		["Find the Source of Unstable Magic"] =
			{appendText=" in this unknown distant place with its long corridor, glowing blue orbs, and various daedra.\n\nThe glowing blue orbs don't seem dangerous, but it will be a fight to get to the end, where there's a wide double staircase leading to another door. Through that door is a working wayshrine! And yet another door.\n\nWhile it's tempting to explore where the wayshrine goes, you may lose sight of Votary Nahlia if you leave now. Though you can always use the portals near the Mages Guilds at Skingrad in West Weald, Mournhold in Deshaan, Stormhaven in Wayrest, or Elden Root in Grahtwood to get back to her."},
		["Talk to Votary Nahlia 2"] =
			{appendText=" at the culmination of your journey starting at a portal near a Mages Guild. Linking the portals at Skingrad in West Weald, Mournhold in Deshaan, Stormhaven in Wayrest, and Elden Root in Grahtwood must have taken some powerful magic!\n\nThis is some kind of balcony, overlooking a large room below.\n\nThere is a strange altar pulsing with unstable magic at the edge of the balcony, just beyond Votary Nahlia.", stepTextKey="We seem to have found the source of the magical disturbance. I should speak to Votary Nahlia about what to do next."},
		["Close the Doors"] =
			{appendText="\nThere are five mysterious doors in the room below the altar leaking a blackish magical disturbance. There are stairs leading down on either side of the balcony. There's a lot to explore, but look for a door into the large lower room of the Scholarium Main Hall.\n\nThe wayshrine just outside this room is named Scholarium. A study of the world map puts it in...Eyevea? That wayshrine may be a handy way to get back here."},
		["Go to Votary Nahlia at the Altar"] =
			{appendText=" on the balcony above the large lower room. There are two exits, which both lead to stairs that take you below."},
		["Talk to the Crow 1"] =
			{appendText=" perched next to the unstable altar on the balcony of the Scholarium. Surely Eyevea has more to do with the magical disturbances here than Votary Nahlia.", stepTextKey="A talking crow accused Votary Nahlia of causing this magical disturbance. I should speak to the Crow."},
		["Find a Replacement Crystal for the Altar"] =
			{appendText=" on the balcony of the Scholarium, somewhere in Eyevea. There's a ladder near the exit to the west wing. Use the other exit and go down the stairs.\n\nTurn right at the bottom, then left and onwards to a large room. There's a crate of forgotten crystals next to some empty shelves in the corner, alongside various other crates and barrels."},
		["Return to the Altar with the Crystal"] =
			{appendText=" you found in the east wing of the Scholarium, underneath Eyevea. There are stairs leading up to the balcony with the altar. The exit from the wayshrine also leads directly into the balcony area.\n\nJust place the crystal on the altar and hope nothing goes bang."},
		["Follow the Crow's Instructions"] =
			{appendText=". Using the altar brings up some kind of magic, and a grimoire. Sliding the grimoire into the grimoire slot brings up more options. Match the scripts to the slots."},
		["Talk to the Crow 2"] =
			{appendText=" perching next to the altar, observing your efforts keenly.", stepTextKey="I repaired the altar and scribed something called a Grimoire. I should speak to the Crow to understand what just happened."},
		["Talk to Votary Nahlia 3"] =
			{appendText=" who is standing in front of the Scholarium altar. She may have some views on how to manage this discovery in Eyevea.", stepTextKey="The Crow wants me to continue on a journey to learn more about Scribing, but encouraged me to speak to Votary Nahlia first."},
		["Talk to Votary Nahlia 4"] =
			{appendText=", who is still at the altar in the Eyevea Scholarium. She has much to tell the Mages Guild and is possibly composing herself.", stepTextKey="Nahlia is going to return to the Mages Guild and get their advice on what to do next. I should speak to her about her plans."},
	},
	-- The Wing of the Indrik
	-- The Wing of the Netch
	-- The Wing of the Gryphon
	-- The Wing of the Crow
	

-- ==================================================================================================================================================
--	Subclassing																															Subclassing
-- ==================================================================================================================================================
	[GetQuestName(7325)] = { -- "A Study in Discipline"				-- Cyberjanet
        [1] = 
            {appendStepText="She has Adventure Camps in major cities all over Tamriel, with a signature red flag and a white, black, and gold sigil.\n\nIn Reaper's March, her camp is in the northeast, just under the bridge at the Dune wayshrine. In the Rift, it's in the central city of Riften, next to the wayshrine. In northwest Bangkorai, look for The Stalls, a small market area to the west of the Evermore Wayshrine.\n\n", stepTextKey="I should speak to Bahtra at-Hunding and learn what she wishes to teach me."},
        ["Talk to Bahtra at-Hunding 1"] =
            {appendText=", a female Redguard in brown and argent armor. She has a lot to discuss, with insights into the various adventuring professions. Once you have explored some options, you will be ready to choose.", stepTextKey="I should speak to Bahtra at-Hunding and learn what she wishes to teach me."},
        [2] = 
            {appendStepText="She has Adventure Camps in major cities all over Tamriel, with a signature red flag and a white, black, and gold sigil.\n\nIn Reaper's March, her camp is in the northeast, just under the bridge at the Dune wayshrine. In the Rift, it's in the central city of Riften, next to the wayshrine. In northwest Bangkorai, look for The Stalls, a small market area to the west of the Evermore Wayshrine.\n\n", stepTextKey="I should speak again to Bahtra at-Hunding, focusing my mind on the discipline I wish to master. I should choose a new discipline to explore and commit to using it before I move on."},
        ["Equip a New Skill Line"] =
            {appendText=". Choosing a new discipline is free. She lists all the classes and you can see their skill lines by opening the drop-down box. Just click the + symbol to choose one, then decide which of your current skill lines you no longer need. Click Subclassing again if you wish to examine the options for a second new skill line."},
        ["Subclass a New Skill Line"] =
            {appendText=". Once you have chosen your new skill lines, look for the Confirm Option at the bottom of the screen."},
        [3] = 
            {appendStepText="She has Adventure Camps in major cities all over Tamriel, with a signature red flag and a white, black, and gold sigil.\n\nIn Reaper's March, her camp is in the northeast, just under the bridge at the Dune wayshrine. In the Rift, it's in the central city of Riften, next to the wayshrine. In northwest Bangkorai, look for The Stalls, a small market area to the west of the Evermore Wayshrine.\n\n", stepTextKey="With Bahtra's assistance, I've chosen new disciplines to pursue. I should speak with her again."},
        ["Talk to Bahtra at-Hunding 2"] =
            {appendText=" once you have chosen your new disciplines.", stepTextKey="With Bahtra's assistance, I've chosen new disciplines to pursue. I should speak with her again."},
    },


