--		 HEART'S WEEK
-- 		=========================================================================



    [GetQuestName(7372)] = { --"Heartsick Follies" --Jordakai
        [1] = 
            {appendStepText="Near the guild traders northwest of the city, ", stepTextKey="I should go to the festival grounds in Belkarth, Craglorn and speak to Kuzam-jo."},
        ["Talk to Kuzam-jo 1"] =
            {appendText=", a tiger-striped Pahmer-raht in a blue-accented white robe. He stands near the performance platform at his tent with red and white banners. \n\nTravel to Craglorn is via wayshrine, by cart from major cities such as the Alliance capitals, or by road from southeastern Bangkorai and northern West Weald.", stepTextKey="I should go to the festival grounds in Belkarth, Craglorn and speak to Kuzam-jo."},
        [2] = 
            {appendStepText="In Craglorn at the festival grounds in the southern city of Belkarth, I spoke with a Priest of Mara. He is concerned about a preformance for the festivities. ", stepTextKey="I should go to the inn and seek out the troupe's director. She will be able to tell me more about their situation."},
        ["Enter the Inn"] =
            {appendText=" in Belkarth, the Crossroads Tavern."},
        [3] = 
            {appendStepText="I entered the Crossroads Tavern in Belkarth in Craglorn. ", stepTextKey="I should talk to the troupe's director and find out what the problem is."},
        ["Talk to Director"] =
            {appendText=" Dreams-in-Scenes."},
        [4] = 
            {appendStepText="At the Crossroads Tavern in Belkarth in Craglorn, I spoke with Dreams-in-Scenes. ", stepTextKey="The director asked that I talk to the troupe's writer, lead actor, and choreographer."},
        ["Help the Struggling Troupe Members"] =
            {appendText=" \n\nThe director mentioned Ghadaz, Essynia, and Tilelme. All are here with her at the tavern. If the choreographer needs to watch a fight for inspiration, the bandits at Haddock's Market, east of Belkarth, may be a good place to find a formidable foe, likely far from the cavern's entrance. "},
        [5] = 
            {appendStepText="At Belkarth in Cragforn, I did as director Dreams-in-Scenes asked. ", stepTextKey="I did my best to help the troupe members. I should watch the play and see if my advice helped."},
        ["Watch the Play"] =
            {appendText=" at the Belkarth Festival Grounds."},
        [6] = 
            {appendStepText="At the Belkarth Festival Grounds near Craglorn's southern city, I attended the performance. ", stepTextKey="The play seems to be in much better shape. I should talk to the Essynia and see how she feels."},
        ["Talk to the Writer"] =
            {appendText=". Essynia is near the stage."},
        [7] = 
            {appendStepText="", stepTextKey="After watching the play and speaking with the writer, Essynia, I should check in with the director, Dreams-in-Scenes."},
        ["Talk to the Director"] =
            {appendText=" near the stage at the Belkarth Festival Grounds in Craglorn's southern city."},
        [8] = 
            {appendStepText="In the southern city of Belkarth in Craglorn, I was able to do as the Priest of Mara asked. ", stepTextKey="I helped the troupe members get their act together. I should talk to Kuzam-jo and let him know."},
        ["Talk to Kuzam-jo 2"] =
            {appendText=". The tiger-striped Pahmer-raht is clad in blue and white, standing at his tent near the stage at the festival grounds.", stepTextKey="I helped the troupe members get their act together. I should talk to Kuzam-jo and let him know."},
    },

	[GetQuestName(7375)] = { --"A Toast to Malcontents" --Jordakai
		[1] = 
			{appendStepText="On the road between Craglorn's southern city and the Belkarth Festival Grounds, ", stepTextKey="I should talk to Samara Gautier and see what plans she has in store for us."},
		["Talk to Samara Gautier 1"] =
			{appendText=", a Breton dressed in black and red, standing by a roadside wall.", stepTextKey="I should talk to Samara Gautier and see what plans she has in store for us."},
		[2] = 
			{appendStepText="Between the southern city of Belkarth in Craglorn and the city's festival grounds, I found the Breton whom the Priest of Mata mentioned. ", stepTextKey="Samara Gautier wants me to learn about old Sanguine traditions related to Hearts Day. She asked me to meet her in a number of locations around Belkarth."},
		["Participate in Sanguine Traditions"] =
			{appendText="\n• At the city's Crossroads Tavern, Samara has something in mind to do there.\n• She has planned another activity at the Gem & Flask, like finding treats around town.\n • And a \"quaint\" picnic, south of the city on the river bridge near the lake.\n • Checking in with Kuzam-jo, the Priest of Mara, may be a good idea, too."},
		[3] = 
			{appendStepText="Three activities around Belkarth in Craglorn, ", stepTextKey="I should talk to Samara now that I participated in all of her Sanguine traditions."},
		["Talk to Samara Gautier 2"] =
			{appendText=".", stepTextKey="I should talk to Samara now that I participated in all of her Sanguine traditions."},
		[4] = 
			{appendStepText="Around Belkarth in Craglorn, ", stepTextKey="I participated in all of Samara Gautier's traditions. I should return to Kuzam-jo and let him know how it went."},
		["Talk to Kuzam-jo 1"] =
			{appendText=" at his tent in the Belkarth Festival Grounds northwest of town.", stepTextKey="I participated in all of Samara Gautier's traditions. I should return to Kuzam-jo and let him know how it went."},
	},

	[GetQuestName(7380)] = { --"Discord Among Friends" --Jordakai
		[1] = 
			{appendStepText="I spoke with the Priest of Mara at the Belkarth Festival Grounds in southern Craglorn. Now, ", stepTextKey="I should go to Waste Walker's Forge in Belkarth and find the Blue Sash Guild."},
		["Head to Waste Walker's Forge"] =
			{appendText=" and find Estelle."},
		[2] = 
			{appendStepText="In Craglorn's southern city of Belkarth, ", stepTextKey="I walked into the middle of an argument between the members of the Blue Sash Guild. I should speak with Estelle, their guild leader."},
		["Talk to Estelle Larconne"] =
			{appendText=" at the pool between the Bell and Bridle stables and the Waste Walker's Forge."},
		[3] = 
			{appendStepText="", stepTextKey="The guild members are fighting over the disappearance of a rare piece of loot. They seem to be blaming Almanora. I should talk to her myself."},
		["Talk to Almanora"] =
			{appendText=", an Altmer mage. She is standing in the sitting area of Waste Walker's Forge in Belkarth."},
		[4] = 
			{appendStepText="In Craglorn's southern city of Belkarth, I spoke with the Altmer mage. ", stepTextKey="Almanora thinks the bow may still be in Zalgaz's Den. I should head there and meet her by the entrance to the cave."},
		["Go to the Entrance of Zalgaz's Den"] =
			{appendText=". The cavern is west of Belkarth and south of the Seeker's Archive Wayshrine."},
		[5] = 
			{appendStepText="In southern Craglorn, west of Belkarth and south of the Seeker's Archive Wayshrine, I found the cavern. ", stepTextKey="I met with Almanora outside of Zalgaz's Den. We should head inside and look for the bow."},
		["Enter Zalgaz's Den"] =
			{appendText=" with the mage."},
		[6] = 
			{appendStepText="West of Belkarth and south of the Seeker's Archive Wayshrine in southern Craglorn, I entered the caverns where the Blue Sash guildmates had been. ", stepTextKey="If Almanora is right, the bow should still be inside the chest she found it in. We should search Zalgaz's Den to find it."},
		["Search for the Bow"] =
			{appendText=". It should be in the northeastern area of the large, watery cavern."},
		[7] = 
			{appendStepText="At Zalgaz's Den in southern Craglorn, Almanora and I were successful. ", stepTextKey="We found the bow in a partially looted chest. Almanora is taking the bow and heading back to Belkarth. I should meet the guild members at the forge."},
		["Return to the Waste Walker's Forge"] =
			{appendText="."},
		[8] = 
			{appendStepText="After helping Almanora retrieve the bow from the chest at Zalgaz's Den in southern Craglorn, I headed back to Belkarth. ", stepTextKey="When I returned to the forge, I overheard another argument between the guild members. Jeshi seems to still be mad. I should talk with Estelle to find out what is happening."},
		["Talk to Estelle 1"] =
			{appendText=" near the Clothier's counter.", stepTextKey="When I returned to the forge, I overheard another argument between the guild members. Jeshi seems to still be mad. I should talk with Estelle to find out what is happening."},
		[9] = 
			{appendStepText="At the Waste Walker's Forge in the southern city of Belkarth in Craglorn, I spoke with the Blue Sash leader. ", stepTextKey="Estelle thinks there's something bothering Jeshi, but he won't talk to any of his friends about it. I should try to talk to him."},
		["Talk to Jeshi"] =
			{appendText=". The Argonian is upstairs, near the blacksmith."},
		[10] = 
			{appendStepText="I spoke with the Argonian at the Waste Walker's Forge. ", stepTextKey="Jeshi had intended to craft gear for his friends, but his shipment of materials was attacked on its way to Belkarth. He marked areas where I might find those materials. I should try and retrieve them."},
		["Retrieve Jeshi's Lost Shipment"] =
			{appendText="\nThe caravan was attacked near the crossroads east of Belkarth. The bandits likely divided up the stolen goods.\n• There is a small camp at a ruin south of the road, east of Haddock's Market and north of Bloodroot Forge.\n• There are broken crates and a damaged cart, just east of the split in the main roads, north of Conflagrant Anomaly.\n• There is a lone crate under the large, stone arch at Lake of Teeth in east of Lower Craglorn."},
		[11] = 
			{appendStepText="After searching areas in eastern Lower Craglorn, ", stepTextKey="I found the remains of Jeshi's shipment and recovered the materials he needs. I should return to him at the forge."},
		["Return to Jeshi"] =
			{appendText=" at the Waste Walker's Forge in Belkarth. The Argonian is probably upstairs near the blacksmith."},
		[12] = 
			{appendStepText="With the materials I recovered in Craglorn, Jeshi is crafting gifts for his friends at the blacksmith station of Belkarth's Waste Walker's Forge. ", stepTextKey="Jeshi wants to present his gifts to his friends. I should stand by and watch."},
		["Wait for Jeshi to Present His Gifts"] =
			{appendText=" to his guildmates."},
		[13] = 
			{appendStepText="With the materials I recovered in Craglorn, Jeshi crafted gifts for his friends. ", stepTextKey="After receiving his new set of armor, Bigrok activated some sort of Dwemer explosive. Now there's no sign of him. I should talk with Estelle."},
		["Talk to Estelle 2"] =
			{appendText=" in the blacksmith area of Waste Walker's Forge in Belkarth.", stepTextKey="After receiving his new set of armor, Bigrok activated some sort of Dwemer explosive. Now there's no sign of him. I should talk with Estelle."},
		[14] = 
			{appendStepText="At the forge in Craglorn's southern city of Belkarth, Bigrok decided to test out the armor Jeshi made for him.  ", stepTextKey="Estelle says the device Bigrok used should have teleported him somewhere nearby. I should search the area outside of Belkarth for Bigrok."},
		["Find Bigrok"] =
			{appendText=". Perhaps the area near the winery northeast of town is a good place to start."},
		[15] = 
			{appendStepText="I found the warrior on the rooftop balcony of Ogondar's Winery in Lower Craglorn. ", stepTextKey="With Bigrok safe and sound, I should return to the forge and reunite him with his guild mates."},
		["Return to Waste Walker's Forge"] =
			{appendText=" in Belkarth."},
		[16] = 
			{appendStepText="Back at the Waste Walker's Forge at Belkarth in southern Craglorn, I found the guildmates. ", stepTextKey="Bigrok apologized for the mess he caused and it seems like this may be the end of the guild's troubles. I should speak with Estelle."},
		["Talk to Estelle 3"] =
			{appendText=".", stepTextKey="Bigrok apologized for the mess he caused and it seems like this may be the end of the guild's troubles. I should speak with Estelle."},
		[17] = 
			{appendStepText="The guildmates had me chasing around southern Craglorn. In the end, ", stepTextKey="I helped repair the friendships at the heart of the Blue Sash Guild. I should return to Kuzam-jo and let him know."},
		["Talk to Kuzam-jo"] =
			{appendText=", the Priest of Mara. The tiger-striped Pahmer-raht should be by his tent, near the stage at the Belkarth Festival Grounds."},
	},

    [GetQuestName(7392)] = { --"Matters of the Heart" --Jordakai
        [1] = 
            {appendStepText="In southern Craglorn at the Belkarth Festival Grounds, I met with the Priest of Mara again. ", stepTextKey="Kuzam-jo would like to hug me, but only if I'm comfortable with it. I should decide whether or not I want to hug him."},
        ["Hug Kuzam-jo 1"] =
            {appendText=". \n", stepTextKey="Kuzam-jo would like to hug me, but only if I'm comfortable with it. I should decide whether or not I want to hug him."},
        ["Do Not Hug Kuzam-jo"] =
            {appendText="."},
        [2] = 
            {appendStepText="At his tent near the stage of the Belkarth Festival Grounds in southern Craglorn, ", stepTextKey="I decided to hug Kuzam-jo. I should approach him for a hug."},
        ["Hug Kuzam-jo 2"] =
            {appendText=".", stepTextKey="I decided to hug Kuzam-jo. I should approach him for a hug."},
        [3] = 
            {appendStepText="In southern Craglorn at the Belkarth Festival Grounds, ", stepTextKey="Kuzam-jo would like to speak with me now that we're through this matter of hugs."},
        ["Talk to Kuzam-jo 1"] =
            {appendText=", the Priest of Mara.", stepTextKey="Kuzam-jo would like to speak with me now that we're through this matter of hugs."},
        [4] = 
            {appendStepText="While speaking with the Priest of Mara at the Belkarth Festival Grounds, he expressed his gratitude. ", stepTextKey="Kuzam-jo gifted me an Amulet of the Heart in honor of what I accomplished during Hearts Week. He said that I should hold it in my hands and feel its light."},
        ["Use the Amulet of the Heart"] =
            {appendText="."},
        [5] = 
            {appendStepText="The Priest of Mara gave me a gift. Holding it in my hands, ", stepTextKey="I used the Amulet of the Heart and it shined with light. I should talk with Kuzam-jo."},
        ["Talk to Kuzam-jo 2"] =
            {appendText=" by his tent at the Belkarth Festival Grounds in southern Craglorn.", stepTextKey="I used the Amulet of the Heart and it shined with light. I should talk with Kuzam-jo."},
    },
-- 		=========================================================================
--		 Zeal of Zenithar
-- 		=========================================================================


		[GetQuestName(6750)] = { -- "Honest Toil"--octavare			-- OneSkyGod
			["Pray to Zenithar"] =
				{appendText=". The altar to Zenithar is located in Craglorn at the Belkarth Festival Grounds, among the tents situated just down the road from the guild traders. It is a small, star-shaped sigil. Behind it is a statue of the Imperial Pantheon's depiction of the divine Zenithar, god of work, commerce and trade. He holds an anvil up in one hand, and has his other hand over his chest.\n"},
			["Ask Fasaria to Say the Prayer"] =
				{appendText=". She is beside the tents next to the statue of Zenithar, located at the Belkarth Festival Grounds in Craglorn."},
			["Gain a Level or Earn a Champion Point"] =
				{appendText="."},
			["Unearth an Antiquity or Treasure Chest"] =
				{appendText="."},
			["Trade with Guild Traders"] =
				{appendText=", spending at least 10,000 gold.\n\n\n\n\nSecret Quest for 100K: Show your devotion to Zenithar by using an emote that represents working or helping at the festival. Take a screenshot in front of the Statue of Zenithar at the Belkarth Events Festival Grounds in Craglorn. Then, open the Immersive Quests addon settings, click -Join Discord Team-, and be the first to post your picture in the Secret Quest Chat & contact @OneSkyGod to claim your prize!"},
			["Talk to Fasaria"] =
				{appendText=". She is beside the tents next to the statue of Zenithar, located at the Belkarth Festival Grounds in Craglorn."},
		},
		[GetQuestName(6749)] = { -- "The Unrefusable Offer"			-- OneSkyGod
			["Talk to Amminus Varo 1"] =
				{appendText=", currently praying on the right-hand side of the Statue of Zenithar at the Belkarth Events Festival Grounds, located at the northwestern edge of the city in Craglorn.\n", stepTextKey="There is a festival for Zenithar, the God of Commerce and Toil, happening in Belkarth. I should talk to Amminus Varo about it."},
			["Craft Baked Apples"] =
				{appendText=" at a cooking station. \n\nOdhilda is a master chef renowned for her culinary skills never seen too far from a cooking fire. She may share her Baked Apples Recipe for the right price. As a follower of Zenithar, she is currently doing her part brining in favor at one of the stalls, behind the Statue of Zenithar at the Belkarth Events Festival Grounds in Craglorn."},
			["Talk to Amminus Varo 2"] =
				{appendText=" paying homage under the canopy stall near the Statue of Zenithar at the Belkarth Events Festival Grounds in Craglorn.", stepTextKey="I made the baked apples Amminus Varo requested for his offering to prove my worth to Zenthar. I should return to him and see what else is required for the offering."},
			["Gather Bundle of Maple Wood"] =
				{appendText=". Some branches from the tallest, eldest trees may have fallen between the festival grounds and the bridge leading into town of Belkarth in Craglorn."},
			["Talk to Amminus Varo 3"] =
				{appendText=" bowing beneath the canopy stall near the Statue of Zenithar at the Belkarth Events Festival Grounds in Craglorn.", stepTextKey="I gathered the wood that Amminus Varo requested. I should deliver it to his hands."},
			["Retrieve Blessed Awl"] =
				{appendText=" from the belongings guarded by their leader. To reach their camp I may take the road leading east out of Belkarth in Craglorn and pass underneath the massive stone arch. The Greycloacks gather just past there."},
			["Talk to Amminus Varo 4"] =
				{appendText=" deep in prayer next to the Statue of Zenithar at the Belkarth Events Festival Grounds in Craglorn.", stepTextKey="I found the blessed awl on the body of the Greycloak's leader. I should return it to Amminus Varo so he can finish assembling the offering for Zenithar."},
			["Follow Amminus Varo"] =
				{appendText="."},
			["Burn the Offering"] =
				{appendText=" into the bed of coals in front of the Statue of Zenithar, at the Belkarth Events Festival Grounds in Craglorn."},
			["Talk To Amminus Varo"] =
				{appendText=" near to the Statue of Zenithar at the Belkarth Events Festival Grounds in Craglorn."},
		},

-- 		=========================================================================
--		 New Life
-- 		=========================================================================

  [GetQuestName(5879)] = { --"The New Life Festival"		--Morgan Miles 
        [1] = 
            {appendStepText="", stepTextKey="I should speak with Breda about celebrating the New Life Festival."},
        ["Talk to Breda"] =
            {appendText=". You can find her in the New Life Festival Tent, just south of Windhelm, the northernmost city in Eastmarch."},
    },

    [GetQuestName(5845)] = { --"Castle Charm Challenge"		--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="To complete the Castle Charm Challenge, I must entertain the people of Alcaire Keep. I should travel there."},
        ["Travel to Alcaire Keep"] =
            {appendText=" in northwestern Stormhaven. I have my performance kit in my backpack."},
        [2] = 
            {appendStepText="I arrived at Castle Alcaire in northwestern Stormhaven. ", stepTextKey="To complete the Castle Charm Challenge, I must entertain the people of Alcaire Keep. I should perform in the Old Goat Inn."},
        ["Perform in the Old Goat Inn"] =
            {appendText=" near the castle's southern gate. I should find some revelers not watching some other performer."},
        [3] = 
            {appendStepText="I am at Castle Alcaire in northwestern Stormhaven. ", stepTextKey="To complete the Castle Charm Challenge, I must entertain the people of Alcaire Keep. I should perform in the castle square."},
        ["Perform in Alcaire Castle's Square"] =
            {appendText=", east of the castle. I should perform for revelers not watching another performer."},
        [4] = 
            {appendStepText="I am at Castle Alcaire in northwestern Stormhaven. ", stepTextKey="To complete the Castle Charm Challenge, I must entertain the people of Alcaire Keep. I should perform in the castle throne room."},
        ["Perform in Alcaire Castle's Throne Room"] =
            {appendText=". I should entertain those not watching others perform."},
        [5] = 
            {appendStepText="I finished entertaining the revelers at Castle Alcaire in Stormhaven. Now, ", stepTextKey="I should return to Eastmarch and speak with Breda."},
        ["Return to Breda"] =
            {appendText=" at the New Life Festival tent near the Kynesgrove Wayshrine, south of the northern city of Windhelm."},
        [6] = 
            {appendStepText="I returned to the New Life Festival tent near the Kynesgrove Wayshrine, south of the northern city of Windhelm. ", stepTextKey="I should speak with Breda about celebrating the New Life Festival."},
        ["Talk to Breda"] =
            {appendText="."},
    },

    [GetQuestName(5855)] = { --"Fish Boon Feast"	--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="To assist the Fish Boon Feast, I should fish for Histmuck Blobfin, Shadowfen Creeping Leech, and Black Marsh Cucumber at a New Life Fishing Hole in Shadowfen. I could also trade for fish with friends, or buy them from guild traders."},
        ["Collect Histmuck Blobfin"] =
            {appendText=".\n"},
        ["Collect Shadowfen Creeping Leech"] =
            {appendText=".\n"},
        ["Collect Black Marsh Cucumber"] =
            {appendText=".\n\nThe Argonians of southern Shadowfen say the best New Life Fishing Holes are along the southeastern river banks, south and east of the Percolating Mire Wayshrine.\nIf needed, I can buy bait from Charalee, a merchant at The Wayward Pilgrim in the southern city of Hissmir."},
        [2] = 
            {appendStepText="Now that I have a Histmuck Blobfin, a Shadowfin Creeping Leech, and a Black Marsh Cucumber in my backpack, ", stepTextKey="I should speak with Gentle-Heart in Hissmir."},
        ["Talk to Gentle-Heart"] =
            {appendText=". She is at her cooking fire on the northeastern first level of the xanmeer in the southern city of Hissmir in Shadowfen."},
        [3] = 
            {appendStepText="I delivered the fish to Gentle-Heart in Hissmir. Now, ", stepTextKey="I should return to Eastmarch and speak with Breda."},
        ["Return to Breda"] =
            {appendText=" at the New Life Festival tent near the Kynesgrove Wayshrine, south of the northern city of Windhelm."},
        [4] = 
            {appendStepText="I returned to the New Life Festival tent near the Kynesgrove Wayshrine, south of the northern city of Windhelm. ", stepTextKey="I should speak with Breda about celebrating the New Life Festival."},
        ["Talk to Breda"] =
            {appendText="."},
    },

	[GetQuestName(5837)] = { --"Lava Foot Stomp"		--Kid-Atlantic
		[1] = 
			{appendStepText="One New Life tradition in Stonefalls is the Lava Foot Stomp, a dance born during a brief and ill-advised attempt by Ebonheart to ban dancing. Locals adapted by creating a routine that looked like stamping out lava splashes on one's boots, giving everyone just enough plausible deniability to claim they were being very safety-conscious.\nThe dance spread quickly despite the ban, because — as the locals like to say — when the music starts, feet have a way of cutting loose. The dancers wore a dazzling pin as a sign of camaraderie, and Breda has provided me with a replica.\n\n", stepTextKey="To complete the Lava Foot Stomp, I should dance at the Watch House Inn, located in Davon's Watch."},
		["Dance at the Watch House Inn in Davon's Watch"] =
			{appendText=", the northeastern town in Stonefalls. I should head inside, use the Dazzling Pin, kick off my Sundas shoes, and prove that even molten rock can’t keep a good beat down."},
		[2] = 
			{appendStepText="One New Life tradition in Stonefalls is the Lava Foot Stomp, a dance born during a brief and ill-advised attempt by Ebonheart to ban dancing. Locals adapted by creating a routine that looked like stamping out lava splashes on one's boots, giving everyone just enough plausible deniability to claim they were being very safety-conscious.\nThe dance spread quickly despite the ban because — as the locals like to say — when the music starts, feet have a way of cutting loose. The dancers wore a dazzling pin as a sign of camaraderie, and Breda has provided me with a replica.\n\n", stepTextKey="To complete the Lava Foot Stomp, I should dance at the Fish Stink, located in Davon's Watch."},
		["Dance at the Fish Stink in Davon's Watch"] =
			{appendText=". Once again, I should use the Dazzling Pin, take the floor, and pull the patrons off of their knees."},
		[3] = 
			{appendStepText="One New Life tradition in Stonefalls is the Lava Foot Stomp, a dance born during a brief and ill-advised attempt by Ebonheart to ban dancing. Locals adapted by creating a routine that looked like stamping out lava splashes on one's boots, giving everyone just enough plausible deniability to claim they were being very safety-conscious.\nThe dance spread quickly despite the ban because — as the locals like to say — when the music starts, feet have a way of cutting loose. The dancers wore a dazzling pin as a sign of camaraderie, and Breda has provided me with a replica.\n\n", stepTextKey="To complete the Lava Foot Stomp, I should dance at the Ebony Flask, located in Ebonheart."},
		["Dance at the Ebony Flask in Ebonheart"] =
			{appendText=", the central city in Stonefalls. Ebonheart may have tried to ban dancing once, but the urge to let loose still lingers. Once again, I should use the Dazzling Pin and get it back before the moment passes."},
		[4] = 
			{appendStepText="One New Life tradition in Stonefalls is the Lava Foot Stomp, a dance born during a brief and ill-advised attempt by Ebonheart to ban dancing. Locals adapted by creating a routine that looked like stamping out lava splashes on one's boots, giving everyone just enough plausible deniability to claim they were being very safety-conscious.\nThe dance spread quickly despite the ban because — as the locals like to say — when the music starts, feet have a way of cutting loose. The dancers wore a dazzling pin as a sign of camaraderie, and Breda has provided me with a replica.\n\n", stepTextKey="To complete the Lava Foot Stomp, I should dance at the Hlaalu House, located in Ebonheart."},
		["Dance At Hlaalu House in Ebonheart"] =
			{appendText=". I should join the celebrations downstairs, use the Dazzling Pin again, and get everyone to lose their blues."},
		[5] = 
			{appendStepText="I've cut my feet loose across Stonefalls and completed the Lava Foot Stomp. ", stepTextKey="I should return to Eastmarch and speak with Breda."},
		["Return to Breda"] =
			{appendText=". She’s waiting at the New Life Festival tent south of Windhelm — no doubt ready to hear how far the dance has spread."},
	},

    [GetQuestName(5838)] = { --"Mud Ball Merriment"		--Morgan Miles 
        [1] = 
            {appendStepText="", stepTextKey="To participate in Mud Ball Merriment, I should first head to Skywatch and throw mud balls at anyone who looks too stuffy to enjoy themselves."},
        ["Share the Joy of Mud Balls in Skywatch"] =
            {appendText=" \n\nAnywhere in Auridon's central city, you can throw mud balls at city dwellers or fellow players to participate in the festivities. You might want to leave the guards out of it...\n\n\n\nSecret Quest for 100K: Show us how you ruined the attaire of a fellow player with a mudball: Take a screenhot and share it, open the Immersive Quests addon settings, click -Join Discord Team-, and be the first to post your picture in the Secret Quest Chat & contact @OneSkyGod to claim your prize!"},
        [2] = 
            {appendStepText="", stepTextKey="To participate in Mud Ball Merriment, I should throw mud balls at the Alliance ambassadors. They can be found in Skywatch."},
        ["Pelt Dominion Ambassador Camore"] =
            {appendText="\n"},
        ["Pelt Daggerfall Ambassador Arnand Relippe"] =
            {appendText="\n"},
        ["Pelt Ebonheart Ambassador Tolendos Dreloth"] =
            {appendText="\n\nThey can be heard bickering with each other inside Skywatch Manor's dining room."},
        [3] = 
            {appendStepText="It involved throwing mudballs at anyone and everyone - except the guards, who apparently weren't in a festive mood. I even pelted some dignitaries with mudballs.\n\n", stepTextKey="I should return to Eastmarch and speak with Breda."},
        ["Return to Breda"] =
            {appendText=". She waits in the New Life Festival Tent, just south of Windhelm, the northernmost city in Eastmarch."},
        [4] = 
            {appendStepText="", stepTextKey="I should speak with Breda about celebrating the New Life Festival."},
        ["Talk to Breda"] =
            {appendText=". She waits in the New Life Festival Tent, just south of Windhelm, the northernmost city in Eastmarch."},
    },

    [GetQuestName(5839)] = { --"Signal Fire Sprint"		--Wex
        [1] = 
            {appendStepText="", stepTextKey="I should travel to Bergama and speak with Aubatha about the Signal Fire Sprint."},
        ["Travel to Bergama"] =
            {appendText=". Aubatha, the Bergama Festival Chief, is located at the western entrance to the city."},
        [2] = 
            {appendStepText="", stepTextKey="I should speak with Aubatha in Bergama about the Signal Fire Sprint."},
        ["Talk to Aubatha 1"] =
            {appendText=" at the western entrance to the city.", stepTextKey="I should speak with Aubatha in Bergama about the Signal Fire Sprint."},
        [3] = 
            {appendStepText="", stepTextKey="To complete the Signal Fire Sprint, I should light the warning fires around Bergama in the correct order before Aubatha finishes the count."},
        ["Light West Signal Fire"] =
            {appendText=" on the bridge overlooking the western gate.\n"},
        ["Light South Signal Fire"] =
            {appendText=" on the roof of Magistrate Sulma's house. I can head east on the bridge where the West Signal Fire is located to get there quickly.\n"},
        ["Light East Signal Fire"] =
            {appendText=". Backtracking from the South Signal Fire, I can head north at the first turn to reach it.\n"},
        ["Light North Signal Fire"] =
            {appendText=". From the East Signal Fire, I can head directly west to the end of the bridge. The signal fire should be by the stairs leading back down."},
        [4] = 
            {appendStepText="", stepTextKey="I should speak with Aubatha about the Signal Fire Sprint."},
        ["Talk to Aubatha 2"] =
            {appendText=" at the western entrance to the city.", stepTextKey="I should speak with Aubatha about the Signal Fire Sprint."},
        [5] = 
            {appendStepText="", stepTextKey="I should return to Eastmarch and speak with Breda."},
        ["Return to Breda"] =
            {appendText="."},
        [6] = 
            {appendStepText="", stepTextKey="I should speak with Breda about celebrating the New Life Festival."},
        ["Talk to Breda"] =
            {appendText=" at the New Life Festival Tent, which can be found on the road from the Kynesgrove Wayshrine to Windhelm."},
    },

	[GetQuestName(5811)] = { --"Snow Bear Plunge"		--Cyberjanet
		[1] = 
			{appendStepText="The Nords celebrate by traveling to remote places, stripping down to their smallclothes, and leaping into the freezing water. It's apparently...invigorating.\n\n", stepTextKey="To complete the Snow Bear Plunge, I must leap into the freezing water from three places in Eastmarch. First, I should head to Cub's Tumble."},
		["Travel to Cub's Tumble"] =
			{appendText=" on the docks of Windhelm, the capital city in the north. You will be able to see a great, warming bonfire close by on the banks. Look for the perfect place to jump from."},
		[2] = 
			{appendStepText="The Nords celebrate by traveling to remote places, stripping down to their smallclothes, and leaping into the freezing water. It's apparently...invigorating.\n\nI found the first location she marked on my map. ", stepTextKey="To complete the Snow Bear Plunge, I must leap from Cub's Tumble into the freezing water below."},
		["Leap From Cub's Tumble Into the Water"] =
			{appendText=" and then make your way to the bonfire on the nearby riverbank to warm up. You can see it from the pier, before you jump."},
		[3] = 
			{appendStepText="The Nords celebrate by traveling to remote places, stripping down to their smallclothes, and leaping into the freezing water. It's apparently...invigorating.\n\nI've done the jump at Cub's Tumble. ", stepTextKey="To complete the Snow Bear Plunge, I must leap into the freezing water from three places in Eastmarch. Next, I should head to Horker's Drop."},
		["Travel to Horker's Drop"] =
			{appendText=" in the middle of the bridge leading into Windhelm. There is no warming bonfire visible. Look for the perfect place to jump from."},
		[4] = 
			{appendStepText="TThe Nords celebrate by traveling to remote places, stripping down to their smallclothes, and leaping into the freezing water. It's apparently...invigorating.\n\nShe marked three locations on my map. I've done the jump at Cub's Tumble. ", stepTextKey="To complete the Snow Bear Plunge, I must leap from Horker's Drop into the freezing water below."},
		["Leap From Horker's Drop Into the Water"] =
			{appendText=" and look around for a bonfire when you surface. It's under the bridge you jump from."},
		[5] = 
			{appendStepText="The Nords celebrate by traveling to remote places, stripping down to their smallclothes, and leaping into the freezing water. It's apparently...invigorating.\n\nI've done the jump at Cub's Tumble and at Horker's Drop. ", stepTextKey="To complete the Snow Bear Plunge, I must leap into the freezing water from three places in Eastmarch. Finally, I should head to Dead Man's Fall."},
		["Travel to Dead Man's Fall"] =
			{appendText=". Follow the road west, along the river flowing past Windhelm. You'll reach the Voljar Meadery wayshrine, and nearby you'll see the bonfire. Dead Man's Fall is at the top of the waterfall just beyond it."},
		[6] = 
			{appendStepText="The Nords celebrate by traveling to remote places, stripping down to their smallclothes, and leaping into the freezing water. It's apparently...invigorating.\n\nI've done the jump at Cub's Tumble and Horker's Drop. ", stepTextKey="To complete the Snow Bear Plunge, I must leap from Dead Man's Fall into the freezing water below."},
		["Leap From Dead Man's Fall Into the Water"] =
			{appendText=" and make your way to the warming bonfire on the bank when you surface."},
		[7] = 
			{appendStepText="The Nords celebrate by traveling to remote places, stripping down to their smallclothes, and leaping into the freezing water. It's apparently...invigorating.\n\nI traveled to three places and jumped. Bonfires warmed me up afterwards. Would I do this again? Either way, ", stepTextKey="I should return to Breda and let her know I completed the Snow Bear Plunge."},
		["Return to Breda"] =
			{appendText=" at the New Life Festival Tent in Eastmarch, just south of Windhelm."},
		[8] = 
			{appendStepText="The Nords celebrate by traveling to remote places, stripping down to their smallclothes, and leaping into the freezing water. It's apparently...invigorating.\n\nI tried it. Now, ", stepTextKey="I should speak with Breda about celebrating the New Life Festival."},
		["Talk to Breda"] =
			{appendText=" at the New Life Festival Tent south of Windhelm in Eastmarch."},
	},

    [GetQuestName(5856)] = { --"Stonetooth Bash"	--Jordakai
        [1] = 
            {appendStepText="", stepTextKey="To celebrate the Stonetooth Bash, I should travel to Stonetooth Fortress and speak with Matron Borbuga."},
        ["Travel to Stonetooth Fortress on Betnikh"] =
            {appendText="."},
        [2] = 
            {appendStepText="I arrived at Betnikh. ", stepTextKey="To celebrate the Stonetooth Bash, I should speak with Matron Borbuga at Stonetooth Fortress."},
        ["Talk to Matron Borbuga"] =
            {appendText=" as she sharpens her cutlery. She is by a table in the cooking area of the fortress."},
        [3] = 
            {appendStepText="", stepTextKey="To celebrate the Stonetooth Bash, I must collect food for Matron Borbuga. I should seek out creatures such as wolves and rabbits for Stonetooth Mystery Meat and wasps for Betnikh Honeycomb."},
        ["Collect Stonetooth Mystery Meat"] =
            {appendText=" \n\nI can hunt wolves, rabbits, mudcrabs, and rats south of the fortress.\n"},
        ["Collect Betnikh Honeycomb"] =
            {appendText="\nI should hunt wasps or find their nests southwest of the fortress."},
        [4] = 
            {appendStepText="", stepTextKey="To celebrate the Stonetooth Bash, I should deliver the food I collected to Matron Borbuga in Stonetooth Fortress."},
        ["Deliver Food to Matron Borbuga"] =
            {appendText=" at her table in the cooking area of the fortress on Betnikh."},
        [5] = 
            {appendStepText="On Betnikh, in the cooking area of the market in Stonetooth Fortress, the mystery meat and honeycomb have been used to create Orcish delicacies. ", stepTextKey="To celebrate the Stonetooth Bash, I should feast with Matron Borbuga's clan! I should sample everything."},
        ["Drink Some Betnikh Spiked Ale"] =
            {appendText=" drawn from the keg. A good belch would be appreciated after I drink this Orcish brew.\n"},
        ["Eat Slice of Honeyed Wolf Pie"] =
            {appendText=". It is cooling on the corner of a table.\n"},
        ["Nibble Bitter Goat Cheese"] =
            {appendText=". A slice is sitting near a loaf of hearty bread on a table."},
        [6] = 
            {appendStepText="In the cooking area of Stonetooth Fortress on Betnikh, I shared in the feast. ", stepTextKey="To celebrate the Stonetooth Bash, I should belch as loud as I can."},
        ["Show Your Appreciation"] =
            {appendText="."},
        [7] = 
            {appendStepText="I feasted with the Orcs of Stonetooth Fortress on Betnikh. Now, ", stepTextKey="I should return to Eastmarch and speak with Breda."},
        ["Return to Breda"] =
            {appendText=" at the New Life Festival tent near the Kynesgrove Wayshrine, south of the northern city of Windhelm."},
        [8] = 
            {appendStepText="I returned to the New Life Festival tent near the Kynesgrove Wayshrine, south of the northern city of Windhelm. ", stepTextKey="I should speak with Breda about celebrating the New Life Festival."},
        ["Talk to Breda"] =
            {appendText="."},
    },

    [GetQuestName(5834)] = { --"The Trial of Five-Clawed Guile"			--Jordakai
        [1] = 
            {appendStepText="To complete the Trial of Five-Clawed Guile, ", stepTextKey="She said I should travel to Rawl'kha and speak with Tumira."},
        ["Travel to Rawl'kha in Reaper's March"] =
            {appendText=", the central city of this Khajiiti region."},
        [2] = 
            {appendStepText="I arrived in the central city of Reaper's March. ", stepTextKey="I should speak with Tumira, the Festival Chief of Rawl'kha."},
        ["Talk to Tumira"] =
            {appendText=". She is standing by the four-wheeled cart between the bridges west of the city."},
        [3] = 
            {appendStepText="Between the bridges, west of the central city of Rawl'kha in Reaper's March, ", stepTextKey="I must retrieve the contents of three locked chests within a short amount of time. I will need lockpicks to open the chests."},
        ["Collect Footpad's Coin"] =
            {appendText=" from its chest.\n"},
        ["Collect Prowler's Coin"] =
            {appendText=" from its chest.\n"},
        ["Collect Rajhin's Coin"] =
            {appendText=" from its chest."},
        [4] = 
            {appendStepText="Between the bridges, west of the central city of Rawl'kha in Reaper's March, ", stepTextKey="I retrieved a unique coin from each of the locked chests. I should present them to Tumira."},
        ["Present Coins to Tumira"] =
            {appendText=". She is waiting by the four-wheeled cart."},
        [5] = 
            {appendStepText="I completed the trial at Rawl'kha. Now, ", stepTextKey="I should return to Eastmarch and speak with Breda."},
        ["Return to Breda"] =
            {appendText=" at the New Life Festival tent near the Kynesgrove Wayshrine, south of the northern city of Windhelm."},
        [6] = 
            {appendStepText="I returned to the New Life Festival tent near the Kynesgrove Wayshrine, south of the northern city of Windhelm. ", stepTextKey="I should speak with Breda about celebrating the New Life Festival."},
        ["Talk to Breda"] =
            {appendText="."},
    },

    [GetQuestName(5852)] = { --"War Orphan's Sojourn"		--Kid-Atlantic
        [1] = 
            {appendStepText="A New Life tradition in Grahtwood is to offer donations and aid to war orphans in need — a reminder that not all wounds left by conflict are borne by soldiers. ", stepTextKey="To complete the War Orphan's Sojourn, I must first travel to the Temple of the Eight in Grahtwood and speak with Ormurrel."},
        ["Talk to Ormurrel at the Temple of the Eight in Grahtwood"] =
            {appendText=", northwest of Elden Root in the central region. \n\nI can follow the road north of Elden Root, turn west at the first crossroads, and continue until I reach the Temple. It is a hollow graht-oak on a stone ridge, its branches shaped into intricate arches and set with amber windows."},
        [2] = 
            {appendStepText="I’ve spoken with Ormurrel, a priest of the Temple, about how I might help the war orphans who rely on its aid. ", stepTextKey="To complete the War Orphan's Sojourn, I must either donate gold to the Temple of the Eight in Grahtwood or kill encroaching wildlife that threatens the temple."},
        ["Donate to the Temple of the Eight in Grahtwood"] =
            {appendText=". I can speak with Ormurrel to offer a modest donation in support of the orphans.\n"},
        ["Kill Encroaching Wildlife"] =
            {appendText=" \n\nSeveral stray hoarvors have wandered too close to the temple grounds. Clearing them out would help keep the area safe."},
        [3] = 
            {appendStepText="", stepTextKey="I should return to Eastmarch and speak with Breda."},
        ["Return to Breda"] =
            {appendText=". She’s waiting at the New Life Festival tent south of Windhelm."},
    },

    [GetQuestName(7334)] = { --"Cold War"		--Cyberjanet
        [1] = 
            {appendStepText="There's certainly enough snow in northern Eastmarch! ", stepTextKey="I should head to Windhelm and speak to Bruni."},
        ["Talk to Bruni 1"] =
            {appendText=", gathering snow near the stairs of Windhelm's entrance. She will explain how to take part in her challenge.", stepTextKey="I should head to Windhelm and speak to Bruni."},
        [2] = 
            {appendStepText="She's very near the New Life tent in Eastmarch, at Windhelm's entrance, planning a festival celebration from her childhood. ", stepTextKey="I need to hurl snowballs at all five of Bruni's targets scattered around Windhelm to complete my part in the festivity. I can use her snow mound to get the snowballs I need."},
        ["Hurl Snowballs at Targets"] =
            {appendText=" \n\nYou heard Bruni, don't forget your snowballs! Any Nordic celebration includes mead, song, and bashing each other senseless, no matter who takes part. Does that mean our targets are near the pubs, or around the Fighters Guild? Or are they huddling in shadows to avoid being seen? Aim well!"},
        [3] = 
            {appendStepText="She's organised a snowball ambush! ", stepTextKey="I hurled five snowballs at my targets in Windhelm. I should return to Bruni and tell her I did my part for New Life."},
        ["Return to Bruni"] =
            {appendText=" and her mound of snow just outside Windhelm in Eastmarch."},
        [4] = 
            {appendStepText="Her snowball ambush was taken in true festive spirit. ", stepTextKey="I returned to Bruni after completing my part of the New Life festivity. I should speak to her and ask about my reward."},
        ["Talk to Bruni 2"] =
            {appendText=", gathering snow near the stairs at the entrance to Windhelm in Eastmarch.", stepTextKey="I returned to Bruni after completing my part of the New Life festivity. I should speak to her and ask about my reward."},
    },

	[GetQuestName(7346)] = { --"Food for New Life"		--Morgan Miles 
		[1] = 
			{appendStepText="", stepTextKey="Lanullin is preparing her offerings to the elders in Auridon. I should speak to her and learn what I can do to help."},
		["Talk to Lanullin 1"] =
			{appendText=". She's at the Vulkhel Guard docks, next to the Harbor Skiff boat that frequents the Gold Coast.", stepTextKey="Lanullin is preparing her offerings to the elders in Auridon. I should speak to her and learn what I can do to help."},
		[2] = 
			{appendStepText="", stepTextKey="I need to prepare a carrot soup offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."},
		["Craft Carrot Soup"] =
			{appendText=". Speak with Lanullin at the docks of Vulkhel Guard in Auridon for advice on where to find what you need. She's next to the Harbor Skiff boat that frequents the Gold Coast."},
		[3] = 
			{appendStepText="", stepTextKey="Time to deliver the offering. The list Lanullin gave me should say whom to offer this to and where."},
		["Deliver Carrot Soup to Teliwe"] =
			{appendText=". She's crouched in a small patch of pink flowers, atop a rock formation just south-southeast of the College Wayshrine in Auridon.\n\nThe wayshrine lies almost centered between the cities of Firsthold and Skywatch, just to the southwest of the College of Aldmeri Propriety."},
		[4] = 
			{appendStepText="", stepTextKey="I delivered the New Life offering to Lanullin's elder. I should let her know I completed my task."},
		["Return to Lanullin"] =
			{appendText=". She awaits news of your delivery at the docks of Vulkhel Guard in Auridon, next to the Harbor Skiff boat that frequents the Gold Coast."},
		[5] = 
			{appendStepText="", stepTextKey="Today's New Life offering is complete. I should speak to Lanullin and ask about my reward."},
		["Talk to Lanullin 2"] =
			{appendText=" at the Vulkhel Guard docks in Auridon, next to the Harbor Skiff boat that frequents the Gold Coast.", stepTextKey="Today's New Life offering is complete. I should speak to Lanullin and ask about my reward."},
		[6] = 
			{appendStepText="", stepTextKey="I need to prepare a baked potato offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."},
		["Craft Baked Potato"] =
			{appendText=". Speak with Lanullin at the docks of Vulkhel Guard in Auridon for advice on where to find what you need. She's next to the Harbor Skiff boat that frequents the Gold Coast."},
		[7] = 
			{appendStepText="", stepTextKey="Time to deliver the offering. The list Lanullin gave me should say whom to offer this to and where."},
		["Deliver Baked Potato to Nenilon"] =
			{appendText=", who's fishing on the western coast of Auridon, near the entrance to Toothmaul Gully.\n\nThe dungeon of Toothmaul Gully lies northwest of Vulkhel Guard, the southernmost city of Auridon."},
		[8] = 
			{appendStepText="", stepTextKey="I need to prepare a banana surprise offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."},
		["Craft Banana Surprise"] =
			{appendText=". Speak with Lanullin at the docks of Vulkhel Guard in Auridon for advice on where to find what you need. She's next to the Harbor Skiff boat that frequents the Gold Coast."},
		[9] = 
			{appendStepText="", stepTextKey="Time to deliver the offering. The list Lanullin gave me should say whom to offer this to and where."},
		["Deliver Banana Surprise to Geraldrim"] =
			{appendText=". He is sharpening his dagger, sat on a rock just off the path found west-northwest of The Lover mundus stone.\n\nThe Lover mundus stone can be found due northwest from the wayshrine of Skywatch, the eastern-central city of Auridon."},


	},

    [GetQuestName(7355)] = { --"The Dragon's Hoard"		--Wex
        [1] = 
            {appendStepText="I've been asked to travel to Reaper's March. ", stepTextKey="I should travel to Rawl'kha and find Tibarr to learn more about his New Life festivity."},
        ["Talk to Tibarr 1"] =
            {appendText=" along the northern road into the city, behind the Fighter's Guild Hall.", stepTextKey="I should travel to Rawl'kha and find Tibarr to learn more about his New Life festivity."},
        [2] = 
            {appendStepText="In Reaper's March, ", stepTextKey="Tibarr wants me to steal a coin from the lair of Rawl'kha's Dragon. He mentioned the lair was in a cavern nearby."},
        ["Steal a Coin from the Dragon's Hoard"] =
            {appendText=". The entrance is located along the cliff wall behind The Waxing Crescent.\n\nThere are coins in the back of the cave, I need to grab one while evading the traps covering the floor."},
        [3] = 
            {appendStepText="While in Reaper's March, ", stepTextKey="I swiped the Dragon's coin. Tibarr wants me to give it to the Orc beggar, Yarg. I should talk to him and give him the coin."},
        ["Give the Coin to the Beggar"] =
            {appendText=" in Rawl'kha's Dragon's Lair, at the entrance.\n\nRawl'kha's Dragon's Lair is located along the cliff wall behind The Waxing Crescent."},
        [4] = 
            {appendStepText="", stepTextKey="I swiped the Dragon's coin and donated it to the Orc beggar. Now I should report back to Tibarr."},
        ["Return to Tibarr"] =
            {appendText=" behind the Rawl'kha Fighter's Guild Hall in Reaper's March."},
        [5] = 
            {appendStepText="", stepTextKey="I completed Tibarr's New Life festivity and gave the Dragon's coin to the Orc beggar. Now to claim my own reward from Tibarr."},
        ["Talk to Tibarr 2"] =
            {appendText=" behind the Rawl'kha Fighter's Guild Hall in Reaper's March.", stepTextKey="I completed Tibarr's New Life festivity and gave the Dragon's coin to the Orc beggar. Now to claim my own reward from Tibarr."},
    },

[GetQuestName(7364)] = { --"Betnihk's Boon"		--Kid-Atlantic
        [1] = 
            {appendStepText="", stepTextKey="Mahagog is hosting the festivity with a group of Orcs at Stonetooth Fortress. I should speak to him to learn more about this contest of strength."},
        ["Talk to Mahagog 1"] =
            {appendText=". I doubt the Orcs would bother hauling boulders up wooden staircases, and giving sledgehammers to drunken revelers is asking for trouble. \nThe test of strength is likely in one of the ground-level courtyards, easily accessible from the services and drinks, but far enough to avoid disaster.", stepTextKey="Mahagog is hosting the festivity with a group of Orcs at Stonetooth Fortress. I should speak to him to learn more about this contest of strength."},
        [2] = 
            {appendStepText="", stepTextKey="Mahagog mentioned he fought a group of Daedra west of Stonetooth Fortress, who left behind an Oblivion boulder for us to smash. I should search the area, find the boulder, and mark its location on my map."},
        ["Find the Oblivion Boulder"] =
            {appendText=" according to Mahagog's directions. If his tale is true, then I'm looking for a big rock surrounded by Daedra corpses. The ridge west of the fortress might be a good vantage point."},
        [3] = 
            {appendStepText="Mahagog recalled fighting some daedra who left behind a boulder perfectly suited for the contest, and ", stepTextKey="I found the strange Oblivion boulder. I should return to Mahagog and let him know exactly where it is."},
        ["Return to Mahagog"] =
            {appendText=" in the northwest courtyard of Stonetooth Fortress."},
        [4] = 
            {appendStepText="I've marked the location of an Oblivion boulder perfect for the test, and now ", stepTextKey="Mahagog is waiting for me. I should tell him about the boulder I found for our challenge."},
        ["Talk to Mahagog 2"] =
            {appendText=" in the northwest courtyard of Stonetooth Fortress.", stepTextKey="Mahagog is waiting for me. I should tell him about the boulder I found for our challenge."},
        [5] = 
            {appendStepText="The challenge is in the northwest courtyard of Stonetooth Fortress. ", stepTextKey="Mahagog said I could find an Orsimer hammer to use for the challenge at a blacksmith's station in the fortress. I should get it and try to smash the Oblivion boulder."},
        ["Prove Your Strength"] =
            {appendText=". The Orcs love their hammers — a good one should be proudly on display in the Stonetooth Smithy. \nAfter I borrow it, I should bring it back to the test of strength while Mahagog fetches the Oblivion boulder for me to smash."},
        [6] = 
            {appendStepText="", stepTextKey="I proved my strength and destroyed the Oblivion boulder. Time to speak to Mahagog about my reward."},
        ["Talk to Mahagog 3"] =
            {appendText=" in the northwest courtyard of Stonetooth Fortress.\n", stepTextKey="I proved my strength and destroyed the Oblivion boulder. Time to speak to Mahagog about my reward."},
    },

    [GetQuestName(7366)] = { --"The Desert and the Sea"		--Jordakai
        [1] = 
            {appendStepText="I spoke with Anicus Novius at the New Life Festival tent in Eastmarch, south of Windhelm. ", stepTextKey="The traveler was said to be seen out in Sentinel asking for help. I should start there and speak to them."},
        ["Talk to the Lone Traveler"] =
            {appendText=" with his lantern and backpack. He was last seen southeast of the wayshrine, south of Sentinel in the northwestern Alik'r Desert."},
        [2] = 
            {appendStepText="In the Alik'r Desert, I spoke with a Redguard traveler who taught me a ritual to provide peace to the spirits of deceased Yokudan mages. ", stepTextKey="I need to fill the waterskin with Yokuda's waters in the west. Once done, I can perform the ritual of Anseilak at Motalion Necropolis."},
        ["Perform the Ritual of Anseilak"] =
            {appendText=" by pouring the seawater in a ritual circle, north of a wall with three archways in the northeastern area of the necropolis.\nFirst, I must travel to the shore far west of Sentinel, just northeast of Na-Tatumba's Landing. Another lone traveler, with lantern and backpack, stands on the shore, south of the fresh seawater mists rising up into the air.\nThen, I must travel to Motalion Necropolis. Its entrance is on the west side of the northeastern city of Satakalaam."},
        [3] = 
            {appendStepText="I traveled to Motalion Necropolis at the northeastern city of Satakalaam in Alik'r Desert. In a ritual circle, north of a wall with three archways in the northeastern area of the necropolis, I poured the seawater. ", stepTextKey="I helped Hassavir complete his pilgrimage and performed Anseilak for the fallen Yokudan mages. I should speak to him and ask about my reward."},
        ["Talk to Hassavir"] =
            {appendText=" at the ritual circle."},
    },

    [GetQuestName(7361)] = { --"The Hunt for Dakoi"		--Wex
        [1] = 
            {appendStepText="Upon arriving in Shadowfen, ", stepTextKey="I should look for Yesei in Stormhold and see if he needs help catching the Dakoi fish."},
        ["Talk to Yesei 1"] =
            {appendText=" along the river northeast of Stormhold.", stepTextKey="I should look for Yesei in Stormhold and see if he needs help catching the Dakoi fish."},
        [2] = 
            {appendStepText="", stepTextKey="I need bait to catch the Dakoi fish. Yesei mentioned the Shadowscale camp west from Stormhold might have a bottle of bloodwine that could work."},
        ["Gather Bait"] =
            {appendText=" in Shadowfen. The camp lies on the road just outside Hei-Halai. If I follow the road out of Stormhold to the northwest, the second left turn should lead me right to it.\n\nThe supply carts around the camp should be a good place to look for the bloodwine."},
        [3] = 
            {appendStepText="", stepTextKey="Yesei last saw the Dakoi in the streams near Stormhold's outskirts. I should start fishing there."},
        ["Hunt Down the Dakoi"] =
            {appendText=" in Shadowfen. A good place to start tracking it would be the river fork on the east side of Stormhold, south of the entrance with the Ayleid bridge.\n\nI should contain my search within the confines of Stormhold, and not travel too far into deep water."},
        [4] = 
            {appendStepText="In Shadowfen, ", stepTextKey="I caught the Dakoi, revealed to be an Argonian acting like a fish. He gave me one to hand to Yesei. I should return to him."},
        ["Return to Yesei"] =
            {appendText=" at his fishing spot along the river northeast of Stormhold."},
        [5] = 
            {appendStepText="", stepTextKey="I returned to Yesei with fish from the Dakoi. I should speak to him and ask about my reward."},
        ["Talk to Yesei 2"] =
            {appendText=" at his fishing spot along the river northeast of Stormhold.", stepTextKey="I returned to Yesei with fish from the Dakoi. I should speak to him and ask about my reward."},
    },

    [GetQuestName(7365)] = { --"The Judgment of Garth"		--Jordakai
        [1] = 
            {appendStepText="I spoke with Anicus Novius at the New Life Festival tent in Eastmarch, south of Windhelm. ", stepTextKey="Anicus mentioned the hermit was spotted in the Rift. I should speak to him and learn more about his pet bear's needs."},
        ["Talk to the Hermit"] =
            {appendText=" with his large bear. He was last seen near the water, southwest of Skald's Retreat and west of the eastern city of Riften."},
        [2] = 
            {appendStepText="I spoke with Baldan in The Rift. He is entertaining his bear near the water, southwest of Skald's Retreat and west of the eastern city of Riften. ", stepTextKey="I need to find some honeycomb to put Garth in a good mood for New Life. The hermit said the forests near Hunter's Glade should have some."},
        ["Gather Honeycomb for Garth"] =
            {appendText=" near a cheese sack at the Giant's camp, northeast of Riften and southeast of Fort Greenwall. \n\nOnce I have the honeycomb, I should return to Garth, the bear. Baldan and his pet are waiting near the water southwest of Skald's Retreat. I can place the honeycomb in Garth's feeding stone, and then I should play a musical instrument for the bear."},
        [3] = 
            {appendStepText="I am with Baldan and his bear in the Rift, southwest of Skald's Retreat and west of the eastern city of Riften. ", stepTextKey="I fed Garth the honeycomb and saved all of Tamriel, according to the hermit. I should speak to him and ask about my reward."},
        ["Talk to Baldan"] =
            {appendText="."},
    },

    [GetQuestName(7362)] = { --"The Mudman"		--Jordakai
        [1] = 
            {appendStepText="I spoke with Anicus Novius at the New Life Festival tent in Eastmarch, south of Windhelm. ", stepTextKey="I should speak to Dailonda in Elden Root to find out more about what she needs help with."},
        ["Talk to Dailonda 1"] =
            {appendText=" by the north road out of Elden Root, the central city of Grahtwood. She is on a small hill, southwest of the Elden Root Temple Wayshrine.", stepTextKey="I should speak to Dailonda in Elden Root to find out more about what she needs help with."},
        [2] = 
            {appendStepText="On the small hill by the city's northern road, southwest of the Elden Root Temple Wayshrine, I spoke with the Bosmer. ", stepTextKey="Dailonda said she needs fresh mud to spring the Mudman to life. Time to dig."},
        ["Assist in Sculpting the Mudman"] =
            {appendText=".\nI should gather mud from a Mud Hole by a grassy patch in the water between Elden Root's northern roots, south of the road.\nWith the mud, I can return to Dailonda on the hill by the northern road of Elden Root. There I should dance in the mud before helping to build the Mudman effigy."},
        [3] = 
            {appendStepText="On a small hill by the northern road out of Elden Root in central Grahtwood, ", stepTextKey="I smeared the mud and helped Dailonda complete the Mudman effigy. I should speak to her and ask about my reward."},
        ["Talk to Dailonda 2"] =
            {appendText=" standing in the muddy water near the Mudman.", stepTextKey="I smeared the mud and helped Dailonda complete the Mudman effigy. I should speak to her and ask about my reward."},
    },

[GetQuestName(6588)] = { --"Old Life Observance" --Kid-Atlantic

	[1] = 
		{appendStepText="", stepTextKey="I'm interested in this Old Life ceremony, I should talk to Petronius Galenus for more information. I can perform the ceremony for myself and if I wish, carry messages from refugees as well."},
	["Talk to Petronius Galenus"] =
		{appendText=" at the New Life Festival Tent in Eastmarch, on the road from the Kynesgrove Wayshrine to Windhelm."},

--Auridon
	[2] = 
		{appendStepText="", stepTextKey="I need to perform the Old Life remembrance ceremony at an Old Life shrine. Petronius Galenus marked one on my map of Auridon."},
	["Find the Old Life Shrine in Auridon"] =
		{appendText=". From Vulkhel Guard, follow the island's coastline to the west. The shrine lies further north beyond Seaside Scarp Camp. It should be emitting a beam of golden light."},
	[3] = 
		{appendStepText="", stepTextKey="I can perform the Remembrance ceremony at the shrine by writing a message to someone deceased, lighting a candle, and then burning the message in the candle's flame. If I have a bundle of Old Life messages Petronius gave me, I can also burn those in the same flame."},
	["Perform the Old Life Ceremony"] =
		{appendText=" at the shrine."},
--ReapersMarch
	[4] = 
		{appendStepText="", stepTextKey="I need to perform the Old Life remembrance ceremony at an Old Life shrine. Petronius Galenus marked one on my map of Reaper's March."},
	["Find the Old Life Shrine in Reaper's March"] =
		{appendText=". It is located along the road north of Dune. It should be emitting a beam of golden light."},
	[5] = 
		{appendStepText="", stepTextKey="I can perform the Remembrance ceremony at the shrine by writing a message to someone deceased, lighting a candle, and then burning the message in the candle's flame. If I have a bundle of Old Life messages Petronius gave me, I can also burn those in the same flame."},
	["Perform the Old Life Ceremony"] =
		{appendText=" at the shrine."},
--Glenumbra
	[6] = 
		{appendStepText="", stepTextKey="I need to perform the Old Life remembrance ceremony at an Old Life shrine. Petronius Galenus marked one on my map of Glenumbra."},
	["Find an Old Life Shrine in Glenumbra"] =
		{appendText=". Take the northern road from Aldcroft and cross the bridge. Take the first right and then continue to the northeast. Following the road, the shrine is located behind the eastern ruined wall at Cambray Pass. It should be emitting a beam of golden light."},
	[7] = 
		{appendStepText="", stepTextKey="I can perform the Remembrance ceremony at the shrine by writing a message to someone deceased, lighting a candle, and then burning the message in the candle's flame. If I have a bundle of Old Life messages Petronius gave me, I can also burn those in the same flame."},
	["Perform the Old Life Ceremony"] =
		{appendText=" at the shrine."},
--Bangkorai
	[8] = 
		{appendStepText="", stepTextKey="I need to perform the Old Life remembrance ceremony at an Old Life shrine. Petronius Galenus marked one on my map of Bangkorai."},
	["Find the Old Life Shrine in Bangkorai"] =
		{appendText=". Following the road south from Fang Lair, the shrine is by the river just before the bridge going southwest. It should be emitting a beam of golden light."},
	[9] = 
		{appendStepText="", stepTextKey="I can perform the Remembrance ceremony at the shrine by writing a message to someone deceased, lighting a candle, and then burning the message in the candle's flame. If I have a bundle of Old Life messages Petronius gave me, I can also burn those in the same flame."},
	["Perform the Old Life Ceremony"] =
		{appendText=" at the shrine."},
--Stonefalls
	[10] = 
		{appendStepText="", stepTextKey="I need to perform the Old Life remembrance ceremony at an Old Life shrine. Petronius Galenus marked one on my map of Stonefalls."},
	["Find the Old Life Shrine in Stonefalls"] =
		{appendText=" in the far northwestern corner of the region, along the road passing into The Rift. The shrine is located along the cliff on the far side of the large bridge from Fort Virak. It should be emitting a beam of golden light."},
	[11] = 
		{appendStepText="", stepTextKey="I can perform the Remembrance ceremony at the shrine by writing a message to someone deceased, lighting a candle, and then burning the message in the candle's flame. If I have a bundle of Old Life messages Petronius gave me, I can also burn those in the same flame."},
	["Perform the Old Life Ceremony"] =
		{appendText=" at the shrine."},
--TheRift
	[12] = 
		{appendStepText="", stepTextKey="I need to perform the Old Life remembrance ceremony at an Old Life shrine. Petronius Galenus marked one on my map of The Rift."},
	["Find an Old Life Shrine in The Rift"] =
		{appendText=". The shrine can be found by taking the eastern road out of Riften and following it all the way to the end. The shrine is hidden in the crags behind the first watchtower on the road beyond Fullhelm Fort. It should be emitting a beam of golden light."},
	[13] = 
		{appendStepText="", stepTextKey="I can perform the Remembrance ceremony at the shrine by writing a message to someone deceased, lighting a candle, and then burning the message in the candle's flame. If I have a bundle of Old Life messages Petronius gave me, I can also burn those in the same flame."},
	["Perform the Old Life Ceremony"] =
		{appendText=" at the shrine."},

--ReturnEastmarch
	[14] = 
		{appendStepText="", stepTextKey="I participated in the Old Life ceremony. I should return to Petronius Galenus."},
	["Talk to Petronius Galenus"] =
		{appendText=" at the New Life Festival Tent, which can be found in Eastmarch on the road from the Kynesgrove Wayshrine to Windhelm."},
},

[GetQuestName(6327)] = { --"A Charitable Contribution"-- Imperial Charity --Deep Winter Charity Writ --OneSkyGod
		[1] = 
			{appendStepText="I can purchase a suitable crafting recipe from a blacksmith, carpenter, clothier, chef, or brewer found within one of the city’s trading districts. I can also purchase the required materials from a guild trader, or acquire them through my travels.\n\n", stepTextKey="I need to craft the supplies described in my contract. Once crafted, I should deliver them to Selvari Abello at the New Life Festival camp."},
		["Craft a Rough Bedroll, Basic\nProgress"] =
			{appendText=""},
		["Deliver the Supplies 1"] =
			{appendText=" to Selvari Abello, the Charity Writ Coordinator, found in prayer at the New Life Festival tent south of Windhelm, the northernmost city.", stepTextKey="I need to craft the supplies described in my contract. Once crafted, I should deliver them to Selvari Abello at the New Life Festival camp."},
		[2] = 
			{appendStepText="", stepTextKey="I gave the crafted supplies to Selvari Abello. All that remains is to complete our transaction."},
		["Talk to Selvari Abello"] =
			{appendText=", the Charity Writ Coordinator, located at the New Life Festival tent south of Windhelm, the northernmost city, where she is often found in prayer."},
		[3] = 
			{appendStepText="I can purchase a suitable crafting recipe from a blacksmith, carpenter or clothier found within one of the city’s trading districts. I can also purchase the required materials from a guild trader, or acquire them through my travels.\n\n", stepTextKey="I need to craft the supplies specified by my contract.\n\nOnce I've crafted them, I need to deliver them to any writ turn-in site."},
		["Craft a Rough Hatchet, Practical"] =
			{appendText=""},
		["Deliver the Supplies 2"] =
			{appendText=" to any major city, the writ turn-in site is identified by seven cargo crates, each marked with a distinct crafting symbol.", stepTextKey="I need to craft the supplies specified by my contract.\n\nOnce I've crafted them, I need to deliver them to any writ turn-in site."},
		[4] = 
			{appendStepText="", stepTextKey="I've placed the requested supplies into the crate. All that remains is to sign the manifest."},
		["Sign the Manifest"] =
			{appendText=" at the writ turn-in site in any major city. The site is identified by seven cargo crates, each marked with a distinct crafting symbol."},
	},
-- 		=========================================================================
--		 JESTER'S FESTIVAL
-- 		=========================================================================

    [GetQuestName(5941)] = { --"The Jester's Festival" --Jordakai
        [1] = 
            {appendStepText="To join in the fun, ", stepTextKey="I should speak with Jester King Jorunn, Queen Ayrenn, or King Emeric about celebrating the Jester's Festival."},
        ["Talk to Jester King Jorunn 1"] =
            {appendText=" by the Jester's Festival tent south of the coastal city of Ebonheart in central Stonefalls.", stepTextKey="I should speak with Jester King Jorunn, Queen Ayrenn, or King Emeric about celebrating the Jester's Festival."},
        ["Talk to Jester Queen Ayrenn 1"] =
            {appendText=" by the Jester's Festival tent north of Vulkhel Guard in southern Auridon.", stepTextKey="I should speak with Jester King Jorunn, Queen Ayrenn, or King Emeric about celebrating the Jester's Festival."},
        ["Talk to Jester King Emeric 1"] =
            {appendText=" at the back of the Jester's Festival tent east of Daggerfall in southwestern Glenumbra.", stepTextKey="I should speak with Jester King Jorunn, Queen Ayrenn, or King Emeric about celebrating the Jester's Festival."},
        [2] = 
            {appendStepText="To begin the celebration, ", stepTextKey="I should speak to Jester Queen Ayrenn about joining in the festivities."},
        ["Talk to Jester Queen Ayrenn 2"] =
            {appendText=" by the Jester's Festival tent north of Vulkhel Guard in southern Auridon.", stepTextKey="I should speak to Jester Queen Ayrenn about joining in the festivities."},
        [3] = 
            {appendStepText="To begin the celebration, ", stepTextKey="I should speak to Jester King Emeric about joining in the festivities."},
        ["Talk to Jester King Emeric 2"] =
            {appendText=" at the back of the Jester's Festival tent east of Daggerfall in southwestern Glenumbra.", stepTextKey="I should speak to Jester King Emeric about joining in the festivities."},
        [4] = 
            {appendStepText="To begin the celebration, ", stepTextKey="I should speak to Jester King Jorunn about joining in the festivities."},
        ["Talk to Jester King Jorunn 2"] =
            {appendText=" by the Jester's Festival tent south of the coastal city of Ebonheart in central Stonefalls.", stepTextKey="I should speak to Jester King Jorunn about joining in the festivities."},
        [5] = 
            {appendStepText="At the Jester's Festival north of Vulkhel Guard in southern Auridon, ", stepTextKey="I should speak to Jester Queen Ayrenn about joining in the festivities."},
        ["Talk to Jester Queen Ayrenn 3"] =
            {appendText=".", stepTextKey="I should speak to Jester Queen Ayrenn about joining in the festivities."},
        [6] = 
            {appendStepText="At the Jester's Festival east of Daggerfall in southern Glenumbra, ", stepTextKey="I should speak to Jester King Emeric about joining in the festivities."},
        ["Talk to Jester King Emeric 3"] =
            {appendText=".", stepTextKey="I should speak to Jester King Emeric about joining in the festivities."},
        [7] = 
            {appendStepText="At the Jester's Festival south of Ebonheart in central Stonefalls, ", stepTextKey="I should speak to Jester King Jorunn about joining in the festivities."},
        ["Talk to Jester King Jorunn 3"] =
            {appendText=".", stepTextKey="I should speak to Jester King Jorunn about joining in the festivities."},
    },

    [GetQuestName(5931)] = { --"A Noble Guest" --Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should find Jester King Jorunn in Ebonheart."},
        ["Travel to the Festival in Stonefalls"] =
            {appendText=", south of the central, coastal city of Ebonheart."},
        [2] = 
            {appendStepText="I went to the Jester's Festival south of the central, coastal city of Ebonheart in Stonefalls. Now, ", stepTextKey="I should speak to Jester King Jorunn and see how I can join in the festivities in Ebonheart."},
        ["Speak to Jester King Jorunn"] =
            {appendText="."},
        [3] = 
            {appendStepText="I met the jester royal at the Jester's Festival in central Stonefalls, south of the coastal city of Ebonheart. ", stepTextKey="Jester King Jorunn said I should bring a gift of mudcrab apples to his betrothed. I should acquire some before finding her."},
        ["Steal Mudcrab Apples"] =
            {appendText=". There should be a full basket in the large building of Ashfall Stables, just south of the city wall."},
        [4] = 
            {appendStepText="I visited the Ashfall Stables at the central, coastal city of Ebonheart. ", stepTextKey="I have the mudcrab apples, now to find Jorunn's betrothed and show her he sent me to steal her away."},
        ["Find Jorunn's Betrothed"] =
            {appendText=". She is probably with her keeper in the coastal Argonian village on the north side of Ebonheart in Stonefalls."},
        [5] = 
            {appendStepText="With the mudcrab apples from Ashfall Stables, ", stepTextKey="I convinced Princess to follow me, now I need to lead her back to Jester King Jorunn and avoid the butcher."},
        ["Lead Princess to Jester King Jorunn"] =
            {appendText=" at the Jester's Festival in central Stonefalls, south of the coastal city of Ebonheart."},
        [6] = 
            {appendStepText="At the Jester's Festival in central Stonefalls, south of Ebonheart, ", stepTextKey="I have delivered Princess safely into the arms of Jester King Jorunn. I should speak with him about my success."},
        ["Talk to Jester King Jorunn"] =
            {appendText="."},
    },

    [GetQuestName(5921)] = { --"Springtime Flair" --Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should find Jester Queen Ayrenn in Auridon."},
        ["Travel to the Festival in Auridon"] =
            {appendText=", just north of the southern city of Vulkhel Guard."},
        [2] = 
            {appendStepText="I went to the Jester's Festival north of Vulkhel Guard. Now, ", stepTextKey="I should travel to the festival in Auridon and help prank people there"},
        ["Speak to Jester Queen Ayrenn"] =
            {appendText="."},
        [3] = 
            {appendStepText="", stepTextKey="First, I need to locate grumps in Vulkhel Guard and toss these Petal Pelters at them."},
        ["Prank Grumpy Temple Stoics in Vulkhel Guard"] =
            {appendText="\n\nThe grumps are likely in the commons, near the Mages Guild and Fighters Guild in this southern port city of Auridon."},
        [4] = 
            {appendStepText="", stepTextKey="With Vulkhel Guard cheered, I now need to locate grumps in Skywatch and toss my Petal Pelters at them."},
        ["Prank Grumpy Residents in Skywatch"] =
            {appendText="\n\nA good place to look is in the lower merchant area near the main gate of this city on the east-central coast of Auridon."},
        [5] = 
            {appendStepText="", stepTextKey="With Skywatch cheered, I only need to locate grumps in the College of Aldmeri Propriety and toss these Petal Pelters at them to fulfill my duty to Jester Queen Ayrenn."},
        ["Prank Grumpy Professors at the College"] =
            {appendText="\n\nThese professors are likely in the main school building of the College of Aldmeri Propriety in northeastern Auridon."},
        [6] = 
            {appendStepText="", stepTextKey="I have not left a single frown to be found in Auridon. I should speak to Jester Queen Ayrenn about my success."},
        ["Return to Jester Queen Ayrenn"] =
            {appendText=" at the Jester's Festival north of the southern city of Vulkhel Guard."},
    },

    [GetQuestName(5937)] = { --"Royal Revelry" --Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I should find Jester King Emeric at the festivities in Daggerfall."},
        ["Travel to the Festival in Glenumbra"] =
            {appendText=", near the eastern gate of the southwestern port city of Daggerfall."},
        [2] = 
            {appendStepText="I went to the Jester's Festival near the eastern gate of Daggerfall in southern Glenumbra. Now, ", stepTextKey="I should speak to Jester King Emeric and find out how I might join in the festivities."},
        ["Speak to Jester King Emeric 1"] =
            {appendText=" in the back of the festival tent.", stepTextKey="I should speak to Jester King Emeric and find out how I might join in the festivities."},
        [3] = 
            {appendStepText="I met the jester royal at the Jester's Festival near the eastern gate of Daggerfall in southern Glenumbra. ", stepTextKey="Jester King Emeric needs hard to acquire materials to create replacement illusion dazzlers. I need to collect these ingredients in Glenumbra from Silumm and Ilessan Tower."},
        ["Collect Glowing Ayleid Bone Dust"] =
            {appendText=" \n\nSilumm is an underground Ayleid ruin with its entrance on the shoreline just north of the city walls, not far from its docks. The dust may be in small piles or carried by hostiles in the ruin.\n"},
        ["Collect Dragonfire Dust"] =
            {appendText=" \n\nIlessan Tower lies in ruins across the river east of the Daggerfall festival. Underground through a trapdoor, crystals can provide dust or the bandits may be carrying it."},
        [4] = 
            {appendStepText="From the two sites in southern Glenumbra, ", stepTextKey="I collected all of the ingredients Jester King Emeric needs to craft his dazzlers, now I need to deliver them."},
        ["Talk to Jester King Emeric"] =
            {appendText=" at the Daggerfall Jester's Festival."},
        [5] = 
            {appendStepText="", stepTextKey="Jester King Emeric has granted me the honor of awing the crowds around Daggerfall with his illusion dazzlers. He's crafting some for me right now."},
        ["Wait for Jester Emeric to Craft His Dazzlers"] =
            {appendText="."},
        [6] = 
            {appendStepText="", stepTextKey="Jester King Emeric has granted me the honor of awing the crowds around Daggerfall with his illusion dazzlers. He's left me a sack full for that purpose. I should take them."},
        ["Take Illusion Dazzlers"] =
            {appendText="' bag on the stage."},
        [7] = 
            {appendStepText="At the festival in southern Glenumbra, the jester royal provided me with dazzlers. ", stepTextKey="Jester King Emeric has granted me the honor of awing the crowds around Daggerfall with his illusion dazzlers. I should find some celebrants to impress and start setting off dazzlers."},
        ["Use Illusion Dazzlers at the Docks"] =
            {appendText="\n"},
        ["Use Illusion Dazzlers at the Castle"] =
            {appendText="\n"},
        ["Use Illusion Dazzlers at the Hillside"] =
            {appendText="\n\nDressed in gold and purple, celebrants have gathered to enjoy the festivities."},
        [8] = 
            {appendStepText="", stepTextKey="I set off all of Jester King Emeric's illusion dazzlers to the amusement of crowds all around Daggerfall. I should inform him of my success."},
        ["Speak to Jester King Emeric 2"] =
            {appendText=" in the back tent at the Jester's Festival near Daggerfall's eastern gate in southern Glenumbra.", stepTextKey="I set off all of Jester King Emeric's illusion dazzlers to the amusement of crowds all around Daggerfall. I should inform him of my success."},
    },

    [GetQuestName(6622)] = { --"A Foe Most Porcine" --Jordakai
        [1] = 
            {appendStepText="", stepTextKey="Rozette the Rapscallion has more information about this competition I've been invited to participate in."},
        ["Talk to Rozette the Rapscallion 1"] =
            {appendText=". Dressed in her jester finery, she is at the Hammerdeath Arena in western Stormhaven, northwest of Wayrest.", stepTextKey="Rozette the Rapscallion has more information about this competition I've been invited to participate in."},
        [2] = 
            {appendStepText="At Hammerdeath Arena in western Stormhaven, I spoke with the Breton jester. ", stepTextKey="Rozette the Rapscallion informed me that I'm officially entered to participate in bouts with King Boar. Now I need to defeat him to claim my prize."},
        ["Defeat King Boar"] =
            {appendText=" inside the nearby arena."},
        [3] = 
            {appendStepText="At Hammerdeath Arena in western Stormhaven, ", stepTextKey="I defeated King Boar in the arena. I should see Rozette the Rapscallion for my reward."},
        ["Talk to Rozette the Rapscallion 2"] =
            {appendText=" on the platform.", stepTextKey="I defeated King Boar in the arena. I should see Rozette the Rapscallion for my reward."},
    },

    [GetQuestName(6632)] = { --"The King's Spoils" --Jordakai
        [1] = 
            {appendStepText="", stepTextKey="Enter the Festival Arena by obtaining a King Boar Invitational ticket."},
        ["Enter the Festival Arena"] =
            {appendText=" at Hammerdeath Arena in western Stormhaven."},
        [2] = 
            {appendStepText="", stepTextKey="Collect fermented mudcrab apples by gathering them during the King Boar challenge in the Festival Arena. Gaining access to the Arena requires an Invitation."},
        ["Gather Fermented Mudcrab Apples"] =
            {appendText=" from filled baskets in the arena."},
        [3] = 
            {appendStepText="At Hammerdeath Arena in western Stormhaven, I battled King Boar in the festival arena. ", stepTextKey="I gathered some fermented mudcrab apples, I can gather more or return to Jad'zirri to see if she can use them."},
        ["Bring the Fermented Mudcrab Apples to Jad'zirri"] =
            {appendText=" by the platform."},
        [4] = 
            {appendStepText="As part of celebrating the Jester's Festival, ", stepTextKey="I have fermented mudcrab apples for Jad'zirri. I should speak to her about getting my cider."},
        ["Talk to Jad'zirri"] =
            {appendText=" at Hammerdeath Arena in western Stormhaven, northwest of Wayrest."},
    },

    [GetQuestName(6640)] = { --"Prankster's Carnival" --Jordakai
    [1] = 
        {appendStepText="", stepTextKey="I should get more information from Soars-in-Laughter about how to go about setting up a prank."},
    ["Talk to Soars-in-Laughter 1"] =
        {appendText=". She is by the cart at the Jester's Festival, south of Ebonheart in Stonefalls.", stepTextKey="I should get more information from Soars-in-Laughter about how to go about setting up a prank."},
    [2] = 
        {appendStepText="At the Jester's Festival south of Ebonheart in Stonefalls, I agreed to prank a friend of Soars-in-Laughter. ", stepTextKey="I need to pick up a Prank Kit at Soars-in-Laughter's workshop."},
    ["Gather the Prank Kit"] =
        {appendText=" from her workshop cart."},
    [3] = 
        {appendStepText="With the prank kit in my pack, ", stepTextKey="I should look for Lejikeh in Dhalmora and carry out the prank."},
    ["Find Lejikeh"] =
        {appendText=" near the southwestern gate behind the large Fit-For-Kings hut of the eastern village in Bal Foyen."},
    [4] = 
        {appendStepText="I found the Redguard at Target Trades, her merchant shack by the southwestern gate of Dhalmora in eastern Bal Foyen. Now, ", stepTextKey="I need to set up the prank without Lejikeh noticing."},
    ["Place the Slime Prank"] =
        {appendText=" bucket on the roof at the storage spot of the shack."},
    [5] = 
        {appendStepText="With the prank kit in my pack, ", stepTextKey="I should look for Klumbert in Skywatch and carry out the prank."},
    ["Find Klumbert"] =
        {appendText=" at his covered wagon by the bridge down in the Mercantile of this eastern port city of Auridon."},
    [6] = 
        {appendStepText="I found Klumbert, a Bosmer, at his covered wagon by the bridge down in the Mercantile of Skywatch in Auridon. Now, ", stepTextKey="I need to place the prank book without Klumbert noticing."},
    ["Place the Trick Book"] =
        {appendText=" on his workbench in the wagon."},
    [7] = 
        {appendStepText="With the prank kit in my pack, ", stepTextKey="I should look for Skurnd in Mistral to carry out the prank."},
    ["Find Skurnd"] =
        {appendText=", a Nord. He enjoys dancing on the deck of The Boatman's Tail tavern in the port city of Khenarthi's Roost."},
    [8] = 
        {appendStepText="I found the Nord up on the side deck of The Boatman's Tail tavern in Mistral on the island of Khenarthi's Roost. ", stepTextKey="I need to place the stinkpot prank under Skurnd's seat without him noticing."},
    ["Place the Stinkpot"] =
        {appendText=" on the small stool he uses to rest between dances."},
    [9] = 
        {appendStepText="", stepTextKey="I should hide nearby to see if my prank is successful."},
    ["Wait for the Prank to Be Triggered"] =
        {appendText="."},
    [10] = 
        {appendStepText="", stepTextKey="I carried out the prank. I should return to Soars-in-Laughter to share my success."},
    ["Talk to Soars-in-Laughter 2"] =
        {appendText=" by her workshop cart at the Jester's Festival, south of Ebonheart in Stonefalls.", stepTextKey="I carried out the prank. I should return to Soars-in-Laughter to share my success."},
    [11] = 
        {appendStepText="", stepTextKey="My prank was successful. I should talk to Soars-in-Laughter."},
    ["Talk to Soars-in-Laughter 3"] =
        {appendText=" by her workshop cart at the Jester's Festival, south of Ebonheart in Stonefalls.", stepTextKey="My prank was successful. I should talk to Soars-in-Laughter."},
    },

    [GetQuestName(6722)] = { --"Getting the Band Together" --Jordakai
        [1] = 
            {appendStepText="", stepTextKey="I need to find the fine wine Samuel said would entice the minstrels and recruit them for the festival."},
        ["Recruit Performers for the Festival"] =
            {appendText="\n\nWine bottles can be found inside each location, either in plain sight or carried by the denizens. After finding the wine, a summoning circle will appear. Three sites must be visited:\n • Ondil, an Ayleid ruin near the Tanzelwil Wayshrine, northwest of Vulkhel Guard in Auridon. A bottle of Fioraellian Muskwine may be found within. The summoning circle appears at an altar where the entry hallway meets the first large chamber.\n • Dresan Keep, a ruined tower in central Glenumbra, northeast of Daggerfall and west of Aldcroft. A bottle of Bloodroot Rosé is within, but the summoning circle will appear outside the tower.\n • Mephala's Nest is underneath a Daedric ruin on a hilltop east of the Jester's Festival site, south of Ebonheart in Stonefalls. After entering through the trapdoor, find a bottle of Spider-Venom Wine. The summoning circle will be in the first large chamber."},
        [2] = 
            {appendStepText="", stepTextKey="All of the minstrels have been gathered for the Jester's Festival. I should return to Samuel."},
        ["Return to Any Jester's Festival Tent"] =
            {appendText=" and speak with Samuel Gourone, the Breton with a tonsure.\n\nJester's Festivals can be found north of Vulkhel Guard in southern Auridon, east of Daggerfall in southern Glenumbra, and south of Ebonheart in central Stonefalls."},
        [3] = 
            {appendStepText="", stepTextKey="The minstrels made it to the Jester's Festival. I should talk to Samuel to see if there's anything else he needs."},
        ["Talk to Samuel Gourone 1"] =
            {appendText=" at the festival's stage.", stepTextKey="The minstrels made it to the Jester's Festival. I should talk to Samuel to see if there's anything else he needs."},
        [4] = 
            {appendStepText="At the Jester's Festival, ", stepTextKey="Samuel decided to let me do the honors and ring the nearby bell to tell the minstrels to start their performance."},
        ["Ring the Bell"] =
            {appendText="."},
        [5] = 
            {appendStepText="", stepTextKey="I helped Samuel liven up the Jesters Festival with music performed by captive Daedra. I should speak with him now that the performance is over."},
        ["Talk to Samuel Gourone 2"] =
            {appendText=".", stepTextKey="I helped Samuel liven up the Jesters Festival with music performed by captive Daedra. I should speak with him now that the performance is over."},
    },

}